import ctypes
if os.name == 'nt':
    from ctypes import wintypes
    
    # [V163.3] 64비트 Windows API 정밀 ctypes 선언 (힙 손상 0xc0000374 방지) 🛡️✨
    # 1. user32
    ctypes.windll.user32.GetForegroundWindow.argtypes = []
    ctypes.windll.user32.GetForegroundWindow.restype = wintypes.HWND

    ctypes.windll.user32.GetParent.argtypes = [wintypes.HWND]
    ctypes.windll.user32.GetParent.restype = wintypes.HWND

    ctypes.windll.user32.GetAncestor.argtypes = [wintypes.HWND, wintypes.DWORD]
    ctypes.windll.user32.GetAncestor.restype = wintypes.HWND

    ctypes.windll.user32.GetWindowThreadProcessId.argtypes = [wintypes.HWND, ctypes.POINTER(wintypes.DWORD)]
    ctypes.windll.user32.GetWindowThreadProcessId.restype = wintypes.DWORD

    ctypes.windll.user32.GetWindowTextLengthW.argtypes = [wintypes.HWND]
    ctypes.windll.user32.GetWindowTextLengthW.restype = ctypes.c_int

    ctypes.windll.user32.GetWindowTextW.argtypes = [wintypes.HWND, wintypes.LPWSTR, ctypes.c_int]
    ctypes.windll.user32.GetWindowTextW.restype = ctypes.c_int

    ctypes.windll.user32.FindWindowW.argtypes = [wintypes.LPCWSTR, wintypes.LPCWSTR]
    ctypes.windll.user32.FindWindowW.restype = wintypes.HWND

    ctypes.windll.user32.GetClassNameW.argtypes = [wintypes.HWND, wintypes.LPWSTR, ctypes.c_int]
    ctypes.windll.user32.GetClassNameW.restype = ctypes.c_int

