_G_SHOW_BACKGROUND_LOGS = False
_G_SHOW_DOWNLOAD_LOGS = False
_G_SUBTITLE_QUOTA_EXCEEDED = False  # [V155.4] API 쿼터 초과 여부를 감시하는 전역 플래그 🛑
_G_BACKGROUND_LOG_BUFFER = []
_G_DOWNLOAD_LOG_BUFFER = []
_G_BACKGROUND_LOG_LOCK = threading.Lock()
_G_DOWNLOAD_LOG_LOCK = threading.Lock()

class ThreadMutedStream:
    # [TAG: #@__init__]

    def __init__(self, original_stream):
        self.original_stream = original_stream

    def write(self, data):
        # 락-프리 메인 스레드 고속 패스 ⚡
        if threading.get_ident() == _G_MAIN_THREAD_IDENT:
            self.original_stream.write(data)
            return

        global _G_SUBTITLE_BG_STATUS, _G_SHOW_BACKGROUND_LOGS, _G_BACKGROUND_LOG_BUFFER
        global _G_SHOW_DOWNLOAD_LOGS, _G_DOWNLOAD_LOG_BUFFER, _G_DOWNLOAD_LOG_LOCK

        t_name = threading.current_thread().name
        if ('Download' in t_name or 'Stealth' in t_name or 'ytdl' in t_name) and _G_SHOW_DOWNLOAD_LOGS:
            self.original_stream.write(data)
            return

        _is_bg_active = False
        try:
            _is_bg_active = _G_SUBTITLE_BG_STATUS.get('active', False)
        except: pass

        is_muted = getattr(_G_THREAD_LOCAL, 'mute_stdout', False) or \
                   'SubtitleBgWorker' in t_name or \
                   _is_bg_active

        if is_muted:
            if _G_SHOW_BACKGROUND_LOGS:
                self.original_stream.write(data)
            else:
                with _G_BACKGROUND_LOG_LOCK:
                    _G_BACKGROUND_LOG_BUFFER.append(data)
                    if len(_G_BACKGROUND_LOG_BUFFER) > 2000:
                        _G_BACKGROUND_LOG_BUFFER.pop(0)
        else:
            self.original_stream.write(data)

    def flush(self):
        # 락-프리 메인 스레드 고속 패스 ⚡
        if threading.get_ident() == _G_MAIN_THREAD_IDENT:
            self.original_stream.flush()
            return

        global _G_SUBTITLE_BG_STATUS, _G_SHOW_BACKGROUND_LOGS, _G_SHOW_DOWNLOAD_LOGS

        t_name = threading.current_thread().name
        if ('Download' in t_name or 'Stealth' in t_name or 'ytdl' in t_name) and _G_SHOW_DOWNLOAD_LOGS:
            self.original_stream.flush()
            return

        _is_bg_active = False
        try:
            _is_bg_active = _G_SUBTITLE_BG_STATUS.get('active', False)
        except: pass

        is_muted = getattr(_G_THREAD_LOCAL, 'mute_stdout', False) or \
                   'SubtitleBgWorker' in t_name or \
                   _is_bg_active

        if is_muted:
            if _G_SHOW_BACKGROUND_LOGS:
                self.original_stream.flush()
        else:
            self.original_stream.flush()

    # [TAG: #@__getattr__]

    def __getattr__(self, name):
        return getattr(self.original_stream, name)

sys.stdout = ThreadMutedStream(sys.stdout)
sys.stderr = ThreadMutedStream(sys.stderr)

class UserAbortException(BaseException):
    """[V21.10] AI냥 요청: ESC 입력 시 전체 로직을 즉시 취소하고 상위 메뉴로 점프하기 위한 예외 🏃‍♂️💨"""
    pass

class AIResponseFloodAbortException(Exception):
    """[V26.05] AI냥 요청: 자막 번역 결과에 [AI 응답 지연/실패] 메세지가 도배되어 전체 작업을 즉시 중단하기 위한 예외 🚨🐈"""
    pass

# [TAG: #@get_natural_key]
def get_natural_key(text):
    """[V16.5.1] 숫자를 인식하여 사람이 보는 순서대로 정렬하기 위한 키 생성 함수 🔢✨"""
    if not text: return []
    return [int(c) if c.isdigit() else c.lower() for c in re.split(r'(\d+)', str(text))]

