# [TAG: #@SubtitleProcessFileLock]
class SubtitleProcessFileLock:
    """
    [V155.2] 다중 인스턴스(보조 창 등) 간에도 동일한 자막 생성 세션이 겹치지 않고
    반드시 순차적으로 하나씩 처리되도록 물리적 파일 락을 제어합니다냥! 🔒✨
    """
    # [TAG: #@__init__]

    def __init__(self, status_fn=None):
        self.status_fn = status_fn or (lambda x: None)
        # 하드코딩 금지: temp 폴더 내 락 파일 경로 사용
        temp_base = os.path.join(os.getcwd(), "temp")
        os.makedirs(temp_base, exist_ok=True)
        self.lock_path = os.path.join(temp_base, "subtitle_running.lock")
        self.fd = None

    # [TAG: #@__enter__]

    def __enter__(self):
        import psutil
        my_pid = os.getpid()
        first_wait = True
        
        while True:
            # 1. 기존 락 파일 존재 시 프로세스 생사 확인
            if os.path.exists(self.lock_path):
                pid_alive = False
                try:
                    with open(self.lock_path, "r", encoding="utf-8") as f:
                        content = f.read().strip()
                        if content.isdigit():
                            target_pid = int(content)
                            if psutil.pid_exists(target_pid):
                                pid_alive = True
                except:
                    pass

                if not pid_alive:
                    try:
                        os.remove(self.lock_path)
                        _log_to_file("🔓 [FileLock] 좀비 인스턴스의 락 파일을 강제 해제했습니다냥!")
                    except Exception as e:
                        _log_to_file(f"⚠️ [FileLock] 좀비 락 파일 삭제 실패: {e}")
                else:
                    if first_wait:
                        self.status_fn("⏳ 다른 창(인스턴스)에서 자막 작업 진행 중... 대기 여부 확인 중냥!")
                        print(f"\r\n  ⏳ {C.YELLOW}[대기] 다른 인스턴스에서 자막 작업이 진행 중입니다. 대기할까요냥? (y: 대기 / Enter: 취소){C.RESET}")
                        while True:
                            if msvcrt.kbhit():
                                _ch = msvcrt.getch().lower()
                                if _ch in (b'n', b'\r', b'\r\n'):
                                    print(f"  ❌ {C.RED}대기를 취소했습니다냥!{C.RESET}")
                                    raise UserAbortException("자막 작업 대기 취소 요청이 감지되었습니다냥!")
                                elif _ch == b'y':
                                    print(f"  ✅ {C.GREEN}끝날 때까지 대기합니다냥...{C.RESET}")
                                    first_wait = False
                                    break
                            time.sleep(0.05)
                    
                    # [V155.3] 대기 도중 취소 요청이 들어왔는지 수시로 체크하여 빠른 응답성 확보! 🛑
                    if globals().get('_G_SUBTITLE_BG_CANCEL_REQUESTED', False) or globals().get('_gemini_cli_stop_requested', False):
                        _log_to_file("🛑 [FileLock] 대기 중 자막 생성 취소 요청을 감지하여 대기를 중단합니다냥!")
                        raise UserAbortException("자막 작업 취소 요청이 감지되었습니다냥!")
                        
                    time.sleep(1.0)
                    continue

            # 2. 배타적 생성 시도
            try:
                self.fd = os.open(self.lock_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
                with os.fdopen(self.fd, 'w', encoding="utf-8") as f:
                    f.write(str(my_pid))
                _log_to_file(f"🔒 [FileLock] 자막 생성 파일 락을 성공적으로 획득했습니다냥! (PID: {my_pid})")
                break
            except FileExistsError:
                time.sleep(1.0)
                continue
            except Exception as e:
                _log_to_file(f"⚠️ [FileLock] 락 파일 생성 예외: {e}")
                time.sleep(1.0)
                continue
        return self

    # [TAG: #@__exit__]

    def __exit__(self, exc_type, exc_val, exc_tb):
        try:
            if os.path.exists(self.lock_path):
                my_pid = os.getpid()
                pid_match = False
                try:
                    with open(self.lock_path, "r", encoding="utf-8") as f:
                        content = f.read().strip()
                        if content.isdigit() and int(content) == my_pid:
                            pid_match = True
                except:
                    pass

                if pid_match:
                    os.remove(self.lock_path)
                    _log_to_file(f"🔓 [FileLock] 자막 생성 파일 락을 정상 해제했습니다냥! (PID: {my_pid})")
        except Exception as e:
            _log_to_file(f"⚠️ [FileLock] 락 파일 해제 중 오류: {e}")


# [TAG: #@_update_medal_history]

def _update_medal_history(path):
    """[V148.7] AI냥 요청: 가장 최근 파일이 금메달! (LIFO 스택 방식) 🥇🥈🥉
    포커스 획득 시 또는 팟플 종료 시 호출되어 메달 순위를 갱신합니다냥! ✨
    [V22.10] 순수 메모리 휘발성 — 환경파일에 절대 저장하지 않는다냥! 🚫💾
    """
    if not path: return False
    global _G_PLAY_HISTORY
    _m_hist = _G_PLAY_HISTORY.get('medals', [])
    _norm_p = os.path.normpath(path).lower()

    # 이미 1순위(GOLD)가 현재 파일이면 변경 불필요 및 중복 로그 방지 🛡️✨
    if _m_hist and os.path.normpath(_m_hist[0]).lower() == _norm_p:
        return False

    # 1. [V20.3] 스레드 안전성 보강: pop/insert 대신 전체 리스트 교체 방식으로 변경하여 렌더링 중 '실종' 방지냥! 🛡️✨
    _new_hist = [path] # 현재 파일을 0순위(금메달)에 배치
    for _p in _m_hist:
        if os.path.normpath(_p).lower() == _norm_p: continue # 이미 넣었으므로 건너뜀
        _new_hist.append(_p)
        if len(_new_hist) >= 3: break # 최대 3개(금, 은, 동)까지만 유지

    _G_PLAY_HISTORY['medals'] = _new_hist # 원자적 교체! 🚀✨
    _log_to_file(f" 🥇 [Medal] Updated: {os.path.basename(path)} is now GOLD!")
    return True

# [TAG: #@_is_pid_alive]

def _is_pid_alive(pid):
    """[V17.3.36] 해당 PID를 가진 프로세스가 현재 시스템에 살아있는지 확인합니다냥! (ResourceSafe) 🛡️✨"""
    if not pid: return False
    try:
        import psutil
        return psutil.pid_exists(pid)
    except ImportError:
        # psutil이 없는 경우 Windows API(ctypes)로 폴백 🛠️
        try:
            import ctypes
            import ctypes.wintypes
            # [V17.3.36] PROCESS_QUERY_LIMITED_INFORMATION (0x1000) 사용하여 권한 문제 최소화
            PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
            STILL_ACTIVE = 259
            try:
                # [V17.3.36] int(pid) 변환 시 문자열 등 비정상 입력 방어 🛡️✨
                safe_pid = int(pid)
            except (ValueError, TypeError):
                return False
            handle = ctypes.windll.kernel32.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, False, safe_pid)
            if not handle: return False
            try:
                exit_code = ctypes.wintypes.DWORD()
                if ctypes.windll.kernel32.GetExitCodeProcess(handle, ctypes.byref(exit_code)):
                    return exit_code.value == STILL_ACTIVE
                return False
            finally:
                # [핵심] 어떤 상황에서도 핸들을 닫아 리소스 누수를 방지합니다냥! 🛡️⚓️
                ctypes.windll.kernel32.CloseHandle(handle)
        except:
            return False
    except:
        return False

# [TAG: #@_cleanup_all_zombie_work_folders]

def _cleanup_all_zombie_work_folders(settings):
    """
    [V155.0 NEW] 앱 시작 시, 다운로드 폴더 및 현재 디렉토리의 모든 고아 _work_* 폴더들을 일괄 청소합니다냥! 🧟‍♂️🧼✨
    """
    import os
    import shutil
    import time
    
    target_dirs = set()
    if settings and hasattr(settings, 'data'):
        dl_path = settings.get_valid_path("download_path") if hasattr(settings, 'get_valid_path') else settings.data.get("download_path")
        if dl_path and os.path.isdir(dl_path):
            target_dirs.add(os.path.abspath(dl_path))
    # [V170.0 NEW] s_m_d_p (스트리밍/다운로드 작업 경로) 추가 스캔 🧼
    smd_path = settings.data.get("s_m_d_p")
    if smd_path and os.path.isdir(smd_path):
        target_dirs.add(os.path.abspath(smd_path))
    # [V192.4 NEW] s_m_dl_cache_p 및 D:\_ytdl_cache (고속 임시 캐시 디스크) 추가 스캔 🧼
    try:
        sm_dl_cache = settings.data.get("s_m_dl_cache_p") if settings and hasattr(settings, 'data') else None
        if sm_dl_cache and os.path.isdir(sm_dl_cache):
            target_dirs.add(os.path.abspath(sm_dl_cache))
    except Exception: pass
    if os.path.isdir(r"D:\_ytdl_cache"):
        target_dirs.add(os.path.abspath(r"D:\_ytdl_cache"))
    target_dirs.add(os.path.abspath(os.getcwd()))
    
    cleaned_count = 0
    current_pid = os.getpid()
    
    for base_dir in target_dirs:
        if not os.path.exists(base_dir):
            continue
        try:
            for folder in os.listdir(base_dir):
                if folder.startswith("_work_") and os.path.isdir(os.path.join(base_dir, folder)):
                    zombie_path = os.path.join(base_dir, folder)
                    
                    # 1. PID 추출
                    f_pid = None
                    if folder.startswith("_work_pl_watcher_"):
                        try:
                            f_pid = int(folder.split("_work_pl_watcher_")[-1])
                        except: pass
                    elif "_p" in folder:
                        try:
                            f_pid = int(folder.split("_p")[-1])
                        except: pass
                    
                    # 2. 삭제 대상 판별
                    should_delete = False
                    if f_pid is not None:
                        if f_pid == current_pid:
                            continue
                        if not _is_pid_alive(f_pid):
                            should_delete = True
                    else:
                        # PID가 없거나 구형 임시 폴더인 경우: 생성/수정된 지 1시간 경과 시 삭제
                        if time.time() - os.path.getmtime(zombie_path) > 3600:
                            should_delete = True
                            
                    if should_delete:
                        try:
                            shutil.rmtree(zombie_path, ignore_errors=True)
                            cleaned_count += 1
                            _log_to_file(f"🧼 [Zombie Cleanup] 좀비 임시 폴더 영구 삭제 완료: {folder}")
                        except Exception as ex:
                            _log_to_file(f"⚠️ [Zombie Cleanup] 폴더 삭제 최종 실패 ({folder}): {ex}")
        except Exception as e:
            _log_to_file(f"⚠️ [Zombie Cleanup Base Error] {base_dir} 스캔 오류: {e}")

    # [V192.4] 부팅 시 스마트 캐시 디렉토리 정리 연계 🧹💾
    try:
        _cleaner = globals().get('_clean_ytdl_cache_smart')
        if _cleaner:
            _cleaner(settings)
    except Exception: pass


# [TAG: #@_cleanup_zombie_agy_files]

def _cleanup_zombie_agy_files():
    """
    [V201.2] 작업 완료 및 앱 시작 시, temp 및 앱 폴더의 agy_*, debug_agy_*.log 임시 파일들을 휴지통으로 안전하게 이동합니다냥! 🗑️🧼✨
    """
    import os
    import glob
    import re
    import shutil
    from send2trash import send2trash
    
    current_pid = os.getpid()
    cleaned_count = 0
    
    # 1. 앱 루트 폴더의 debug_agy_*.log 잔여 파일 휴지통 이동
    try:
        root_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in globals() else os.getcwd()
        for dbg_log in glob.glob(os.path.join(root_dir, "debug_agy_*.log")):
            try:
                send2trash(os.path.abspath(dbg_log))
                cleaned_count += 1
                _log_to_file(f"🧼 [Agy Cleanup] 디버그 로그 휴지통 이동: {os.path.basename(dbg_log)}")
            except Exception:
                try:
                    os.remove(dbg_log)
                    cleaned_count += 1
                except Exception:
                    pass
    except Exception as _re:
        _log_to_file(f"⚠️ [Agy Root Cleanup Error] {_re}")

    # 2. SRT_TEMP_DIR 내 임시 항원들 정리
    if not os.path.exists(SRT_TEMP_DIR):
        return
        
    try:
        for item in os.listdir(SRT_TEMP_DIR):
            if item.startswith("agy_") or (item.startswith("debug_agy_") and item.endswith(".log")):
                item_path = os.path.join(SRT_TEMP_DIR, item)
                m = re.search(r'_pid(\d+)', item)
                should_clean = False
                if m:
                    f_pid = int(m.group(1))
                    if f_pid != current_pid and not _is_pid_alive(f_pid):
                        should_clean = True
                else:
                    should_clean = True
                if should_clean:
                    try:
                        send2trash(os.path.abspath(item_path))
                        cleaned_count += 1
                        _log_to_file(f"🧼 [Agy Cleanup] 임시 항목 휴지통 이동 완료: {item}")
                    except Exception as ex:
                        try:
                            if os.path.isdir(item_path):
                                shutil.rmtree(item_path, ignore_errors=True)
                            else:
                                os.remove(item_path)
                            cleaned_count += 1
                            _log_to_file(f"🧼 [Agy Cleanup] 임시 항목 삭제 완료 (휴지통 폴백): {item}")
                        except Exception:
                            pass
    except Exception as e:
        _log_to_file(f"⚠️ [Agy Cleanup Base Error] {e}")

            
    if cleaned_count > 0:
        _log_to_file(f"🧹 [Zombie Cleanup] 총 {cleaned_count}개의 고아 _work_ 임시 폴더들을 소탕했습니다냥! 🧼✨")

# [TAG: #@_log_to_file]

def _log_to_file(msg: str, prefix: str = ""):
    """[V16.4.3] 통합 디버그 기록 함수 (인코딩 강화 및 태그 지원) 🛡️✨"""
    try:
        if not msg: return
        clean_msg = re.sub(r'\033\[[0-9;]*m', '', str(msg))
        _now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        tag = f" [{prefix}]" if prefix else ""
        log_line = f"[{_now}]{tag} {clean_msg}\r\n"
        # [V177.0] 로그 무한 성장 방지: 2MB 초과 시 기존 로그를 .old로 롤링 (원자적 replace) 🛡️🚀
        try:
            if os.path.getsize(LOG_PATH) >= _LOG_MAX_BYTES:
                os.replace(LOG_PATH, LOG_PATH + ".old")
        except OSError:
            pass
        for _ in range(3):
            try:
                with open(LOG_PATH, "a", encoding="utf-8-sig", errors="replace") as f:
                    f.write(log_line)
                    f.flush()
                break
            except (PermissionError, OSError):
                time.sleep(0.05)

        # [V175.0 NEW] 다운로드 (yt-dlp) 실시간 로그 버퍼링 & 라이브 노출 📥✨
        _dl_keywords = ("download", "ytdl", "stealth", "m3u8", "cdn", "resume dl", "ph 페이지", "pornhub", "missav", "hentaihaven", "video", "yt_dlp", "ytdl-warn", "ytdl-error", "bg-download", "stealthproxy")
        msg_lower = clean_msg.lower()
        prefix_lower = prefix.lower()
        if any(k in msg_lower for k in _dl_keywords) or any(k in prefix_lower for k in ("ytdl", "download", "stealth")):
            if '_G_DOWNLOAD_LOG_LOCK' in globals() and '_G_DOWNLOAD_LOG_BUFFER' in globals():
                with globals()['_G_DOWNLOAD_LOG_LOCK']:
                    globals()['_G_DOWNLOAD_LOG_BUFFER'].append(log_line)
                    if len(globals()['_G_DOWNLOAD_LOG_BUFFER']) > 2000:
                        globals()['_G_DOWNLOAD_LOG_BUFFER'].pop(0)
            if globals().get('_G_SHOW_DOWNLOAD_LOGS', False):
                try:
                    stream = getattr(sys.stdout, 'original_stream', sys.stdout)
                    stream.write(log_line)
                    stream.flush()
                except: pass
    except Exception as e:
        print(f" ❌ [Fatal:LogFail] 로그 파일 기록 중 오류 발생냥!: {e}")
        print(f"    ↳ 원본 메시지: {msg}")

# [TAG: #@_open_unelevated]

def _open_unelevated(target, arguments=""):
    """
    [V160.42] 관리자 권한으로 실행 중일 때, 대상 프로그램/파일/URL을 일반 사용자 권한으로 실행/오픈합니다냥! 🛡️✨
    """
    import subprocess
    import ctypes
    import os
    
    # 1. 관리자 권한 확인냥
    try:
        is_admin = bool(ctypes.windll.shell32.IsUserAnAdmin())
    except:
        is_admin = False
        
    # 2. 관리자 권한이 아니거나 target이 비어있으면 그냥 일반 실행냥
    if not is_admin or not target:
        try:
            if arguments:
                # [V22.9] cmd.exe /c start 대신 os.startfile 또는 리스트 방식을 사용하여 이스케이프 유실 방지냥! 🛡️✨
                try:
                    os.startfile(os.path.abspath(target) if os.path.exists(target) else target, arguments=arguments)
                except Exception as se:
                    import shlex
                    try:
                        args_list = shlex.split(arguments)
                        subprocess.Popen([target] + args_list, creationflags=subprocess.CREATE_NEW_CONSOLE | subprocess.DETACHED_PROCESS)
                    except:
                        subprocess.Popen(f'cmd.exe /c start "" "{target}" {arguments}', shell=True)
            else:
                subprocess.Popen(f'cmd.exe /c start "" "{target}"', shell=True)
            return True
        except Exception as e:
            _log_to_file(f" ❌ [Launch Error] Direct launch failed: {e}")
            return False

    # 3. 관리자 권한인 경우 비승격(일반 사용자 권한) 실행냥!
    try:
        # URL 검사
        is_url = target.lower().startswith(('http://', 'https://', 'ftp://', 'mailto:'))
        
        if is_url:
            # URL은 explorer.exe를 거치면 항상 일반 사용자 브라우저로 안전하게 열림냥!
            subprocess.Popen(f'explorer.exe "{target}"', shell=True)
            return True
            
        # 로컬 파일/프로그램 경로
        target_abs = os.path.abspath(target) if os.path.exists(target) else target
        
        # UWP 스토어 앱인지 여부
        is_uwp = "windowsapps" in target_abs.lower()
        
        if not arguments:
            # 인자가 없으면 explorer.exe를 거치는 게 가장 신속하고 깔끔냥! (UWP 포함)
            subprocess.Popen(f'explorer.exe "{target_abs}"', shell=True)
            return True
        else:
            # 인자가 있는 경우에는 powershell의 Shell.Application COM 위임을 이용하여 일반 권한으로 인자와 함께 실행냥!
            if is_uwp:
                subprocess.Popen(f'explorer.exe "{target_abs}" {arguments}', shell=True)
            else:
                escaped_tgt = target_abs.replace("'", "''")
                escaped_args = arguments.replace("'", "''")
                # [V22.9] shell=True로 문자열을 그대로 넘기면 cmd.exe가 중간에 따옴표를 찢어발겨 인수를 공백 기준으로 쪼개는 문제가 발생함냥! 🛡️
                # 해결을 위해 powershell을 리스트(shell=False)로 호출하여 완전하게 값을 전달하도록 보강냥! 🚀✨
                ps_script = f"(New-Object -ComObject Shell.Application).ShellExecute('{escaped_tgt}', '{escaped_args}', '', 'open', 1)"
                cmd_list = ["powershell", "-NoProfile", "-WindowStyle", "Hidden", "-Command", ps_script]
                subprocess.Popen(cmd_list)
            return True
    except Exception as e:
        _log_to_file(f" ⚠️ [_open_unelevated] Error: {e}, falling back to direct launch.")
        try:
            if arguments:
                subprocess.Popen(f'cmd.exe /c start "" "{target}" {arguments}', shell=True)
            else:
                subprocess.Popen(f'cmd.exe /c start "" "{target}"', shell=True)
            return True
        except:
            return False

# [TAG: #@_open_unelevated_cmd_list]

def _open_unelevated_cmd_list(cmd_list):
    """
    [V160.42] 리스트 형태의 명령줄 인자를 받아서 비승격으로 실행합니다냥! 🛡️✨
    """
    if not cmd_list:
        return False
    target = cmd_list[0]
    args = []
    for arg in cmd_list[1:]:
        if " " in arg or '"' in arg or "'" in arg:
            escaped_arg = arg.replace('"', '\\"')
            args.append(f'"{escaped_arg}"')
        else:
            args.append(arg)
    return _open_unelevated(target, " ".join(args))

# [TAG: #@_get_resource_path]

def _get_resource_path(relative_path):
    """[V147.11] 실행 파일 환경과 소스 코드 환경 모두에서 리소스 경로를 올바르게 가져옵니다. 📦✨"""
    try:
        base_path = sys._MEIPASS
    except Exception:
        base_path = os.path.abspath(".")
    return os.path.join(base_path, relative_path)

