_VIRTUAL_KEY_QUEUE = deque()
_VIRTUAL_KEY_LOCK = threading.Lock()
_web_prompt_future = None

def _push_virtual_key(k):
    """웹 터미널에서 들어온 가상 키를 큐에 주입냥! ⌨️"""
    with _VIRTUAL_KEY_LOCK:
        _VIRTUAL_KEY_QUEUE.append(k)

def _has_virtual_key():
    """현재 소비되지 않은 가상 키가 버퍼에 있는지 확인 🔍"""
    with _VIRTUAL_KEY_LOCK:
        return len(_VIRTUAL_KEY_QUEUE) > 0

def _pop_virtual_key():
    """가상 키 버퍼에서 1개 추출 📥"""
    with _VIRTUAL_KEY_LOCK:
        if _VIRTUAL_KEY_QUEUE:
            return _VIRTUAL_KEY_QUEUE.popleft()
        return None

def _clear_virtual_keys():
    """가상 키 버퍼 초기화 🧹"""
    with _VIRTUAL_KEY_LOCK:
        _VIRTUAL_KEY_QUEUE.clear()

def _parse_xterm_keys(data: str):
    """xterm.js에서 전달된 ANSI 이스케이프 시퀀스를 윈도우 msvcrt 가상키로 변환! 🔄"""
    keys = []
    i = 0
    n = len(data)
    ansi_map = {
        '\x1b[A': ('\xe0', 'H'), '\x1bOA': ('\xe0', 'H'), # Up
        '\x1b[B': ('\xe0', 'P'), '\x1bOB': ('\xe0', 'P'), # Down
        '\x1b[C': ('\xe0', 'M'), '\x1bOC': ('\xe0', 'M'), # Right
        '\x1b[D': ('\xe0', 'K'), '\x1bOD': ('\xe0', 'K'), # Left
        '\x1b[H': ('\xe0', 'G'), '\x1b[1~': ('\xe0', 'G'), # Home
        '\x1b[F': ('\xe0', 'O'), '\x1b[4~': ('\xe0', 'O'), # End
        '\x1b[5~': ('\xe0', 'I'), # PgUp
        '\x1b[6~': ('\xe0', 'Q'), # PgDn
        '\x1b[2~': ('\xe0', 'R'), # Insert
        '\x1b[3~': ('\xe0', 'S'), # Delete
        '\x1b[1;2A': ('\xe0', '\x98'), # Shift+Up (따봉 토글)
        '\x1b[1;2B': ('\xe0', '\xa0'), # Shift+Down (카트 토글)
        '\x1b[1;5A': ('\xe0', '\x8d'), # Ctrl+Up
        '\x1b[1;5B': ('\xe0', '\x91'), # Ctrl+Down
        '\x1bOP': ('\x00', ';'), '\x1b[11~': ('\x00', ';'), # F1
        '\x1bOQ': ('\x00', '<'), '\x1b[12~': ('\x00', '<'), # F2
        '\x1bOR': ('\x00', '='), '\x1b[13~': ('\x00', '='), # F3
        '\x1bOS': ('\x00', '>'), '\x1b[14~': ('\x00', '>'), # F4
    }
    while i < n:
        if data[i] == '\x1b' and i + 1 < n:
            matched = False
            for seq, pair in sorted(ansi_map.items(), key=lambda x: -len(x[0])):
                if data.startswith(seq, i):
                    keys.extend(pair)
                    i += len(seq)
                    matched = True
                    break
            if matched:
                continue
            if data[i:i+2] == '\x1b[':
                end_idx = i + 2
                while end_idx < n and not ('@' <= data[end_idx] <= '~'):
                    end_idx += 1
                if end_idx < n:
                    i = end_idx + 1
                    continue
            keys.append('\x1b')
            i += 1
        elif data[i] in ('\x7f', '\x08'):
            keys.append('\x08')
            i += 1
        else:
            keys.append(data[i])
            i += 1
    return keys

class _ConsoleMirrorTee:
    """stdout/stderr를 가로채서 PC 콘솔에도 찍고, 웹 SSE 클라이언트들에게 실시간 복제 전송하는 Tee 스트림 📡📺"""
    def __init__(self, original_stream):
        self._orig = original_stream
        self._lock = threading.Lock()
        self._history = deque(maxlen=4000)
        self._clients = set()

    def write(self, data):
        if not data:
            return
        if self._orig:
            try:
                self._orig.write(data)
                self._orig.flush()
            except Exception:
                pass
        with self._lock:
            self._history.append(data)
            dead = []
            for q in self._clients:
                try:
                    q.put_nowait(data)
                except Exception:
                    dead.append(q)
            for d in dead:
                self._clients.discard(d)

    def flush(self):
        if self._orig:
            try:
                self._orig.flush()
            except Exception:
                pass

    def add_client(self):
        q = queue.Queue(maxsize=2000)
        with self._lock:
            snapshot = "".join(self._history)
            if snapshot:
                if len(snapshot) > 65536:
                    snapshot = snapshot[-65536:]
                try:
                    q.put_nowait(snapshot)
                except Exception:
                    pass
            self._clients.add(q)
        return q

    def remove_client(self, q):
        with self._lock:
            self._clients.discard(q)

    def __getattr__(self, name):
        return getattr(self._orig, name)

_G_CONSOLE_MIRROR = None
def _init_console_mirror():
    global _G_CONSOLE_MIRROR
    if _G_CONSOLE_MIRROR is None and sys.stdout is not None:
        _G_CONSOLE_MIRROR = _ConsoleMirrorTee(sys.stdout)
        sys.stdout = _G_CONSOLE_MIRROR
        sys.stderr = _ConsoleMirrorTee(sys.stderr)

_init_console_mirror()


# [V147.210] AI냥 요청: 필요한 라이브러리를 자동으로 설치(Lazy Install)해주는 엔진냥! 📦✨
def import_or_install(import_name, pkg_name=None):
    """라이브러리가 없으면 즉시 설치하고 임포트한다냥! 🚀💨"""
    if pkg_name is None: pkg_name = import_name
    try:
        return __import__(import_name)
    except ImportError:
        print(f"\r\n 📦 {C.SKY}필요한 모듈 '{pkg_name}'이 없어서 자동으로 설치 중이야냥...{C.RESET}")
        try:
            subprocess.check_call([sys.executable, "-m", "pip", "install", pkg_name])
            print(f" ✅ {C.GREEN}'{pkg_name}' 설치 완료!✨{C.RESET}")
            return __import__(import_name)
        except Exception as e:
            # [#@import_or_install_user_fallback] WinError 32 등 권한 에러 시 --user 모드로 재시도냥! 🔄
            print(f" ⚠️ {C.YELLOW}일반 설치 실패, --user 모드로 재시도 중...{C.RESET}")
            try:
                subprocess.check_call([sys.executable, "-m", "pip", "install", "--user", pkg_name])
                print(f" ✅ {C.GREEN}'{pkg_name}' --user 모드로 설치 완료!✨{C.RESET}")
                import importlib, site
                importlib.invalidate_caches()
                # user site-packages 경로를 sys.path에 추가 (즉시 import 가능하게)
                user_site = site.getusersitepackages()
                if user_site not in sys.path:
                    sys.path.insert(0, user_site)
                return __import__(import_name)
            except Exception as e2:
                print(f" ❌ {C.RED}'{pkg_name}' 설치 실패냥!: {e2}{C.RESET}")
                return None

# [V21.3] yt-dlp 정기 업데이트 엔진 (스로틀링 방지 핵심!) 🛡️📺✨
def _update_ytdlp_if_needed():
    """실행 시 yt-dlp가 너무 오래되었거나 유튜브 정책이 변했을 때를 대비해 자동 업데이트냥! 🚀"""
    try:
        # 1. 마지막 업데이트 체크 시간 확인 (하루 1회 제한으로 부팅 속도 보호)
        _flag_p = os.path.join(SRT_TEMP_DIR, ".ytdlp_last_upd")
        if os.path.exists(_flag_p):
            with open(_flag_p, 'r') as f:
                _last = float(f.read().strip())
                if time.time() - _last < 86400: # 24시간 이내면 스킵냥! 🛌
                    return
        
        print(f" 📡 {C.SKY}유튜브 엔진(yt-dlp) 최신 상태 유지 중... (속도 저하 방지){C.RESET}")
        # [V21.3] 무음 모드로 업데이트 시도 (실패해도 진행은 되게!) 🛡️
        flags = 0x08000000 if os.name == 'nt' else 0
        subprocess.run([sys.executable, "-m", "pip", "install", "-U", "yt-dlp"], 
                       capture_output=True, creationflags=flags, timeout=30)
        
        with open(_flag_p, 'w') as f: f.write(str(time.time()))
    except: pass

