# [TAG: #@_clean_series_title]
def _clean_series_title(title: str) -> str:
    """[V22.31] AI냥 요청: 시리즈 제목 정규화 및 에피소드/코덱 등 노이즈 제거 단일 엔진 🧹✨
    [V21.2] 및 [V21.0] 의 중복 정의를 병합하고 최신 로직을 반영하여 덮어쓰기 논리 오류를 완벽 박멸했습니다냥! 🛡️✨
    """
    if not title: return ""
    import html
    
    # 0. HTML 엔티티 해제
    t = html.unescape(title)
    
    # 1. 소괄호, 대괄호, 중괄호 및 그 내용물 제거 (예: [720p], (Uncensored))
    t = re.sub(r'\[[^\]]*\]|\([^\)]*\)|\{[^\}]*\}', '', t)
    
    # 2. 에피소드 관련 패턴 제거 (Case Insensitive)
    # Episode, Ep, Part, Pt, Vol, Volume, Chapter, Ch, # 및 대시-숫자 패턴 등 통합 제거냥!
    patterns = [
        r'\s*(Episode|Ep|Part|Pt|Vol|Volume|Chapter|Ch|#)\.?\s?\d+.*',
        r'\s*V\d+.*',
        r'\s+-\s+\d+.*',     # "Title - 01"
        r'\s+#\d+.*',        # "Title #01"
    ]
    for p in patterns:
        t = re.sub(p, '', t, flags=re.IGNORECASE)
        
    # 3. 화질 및 코덱 정보 제거
    t = re.sub(r'(?i)\b(1080p|720p|480p|360p|HD|FHD|x264|x265|h264|h265|hevc)\b', '', t)
    
    # 4. 문장 끝의 숫자 제거 (보통 에피소드 번호가 맨 뒤에 붙는 경우)
    t = re.sub(r'\s\d+$', '', t)
    
    # 5. 불필요한 특수문자 및 공백 정리
    t = re.sub(r'[-_./\\:|]', ' ', t)
    t = ' '.join(t.split())
    
    return t.strip().rstrip('-').strip()


# [V2.16] yt-dlp/ffmpeg 잡음을 완전히 차단하기 위한 전역 Logger 🧼✨
class SilentLogger:
    # [TAG: #@debug]
    def debug(self, msg): pass
    # [TAG: #@warning]
    def warning(self, msg):
        try:
            # [V142.15] 무해하지만 시끄러운 유튜브 전용 경고 필터링 🧼
            filter_keywords = [
                'Preferring "ko" translated fields',
                '재생되는 동안 사용할 수 없는 동영상',
                'unavailable videos are hidden',
                'fragments are not available',
                '사용할 수 없는 동영상은 숨겨졌습니다',
                'Passing cookies as a header', # [V19.6.1] yt-dlp 쿠키 헤더 경고 무시냥! 🤫
                'No supported JavaScript runtime', # [V178.5] JS 런타임 미설치 경고 차단 🛡️
                'JavaScript runtime could be found',
                'YouTube extraction without a JS runtime',
                '--js-runtimes',
                'yt-dlp/wiki/EJS',
                'deprecated'
            ]
            if any(k.lower() in str(msg).lower() for k in filter_keywords): return
            _log_to_file(f"[ytdl-warn] {msg}")
        except Exception as e:
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")
    # [TAG: #@error]
    def error(self, msg):
        try:
            # [V142.15] 에러 메시지 중에서도 무시 가능한 것들 필터링
            filter_keywords = [
                'fragments are not available',
                'Passing cookies as a header',
                'No supported JavaScript runtime',
                'JavaScript runtime could be found',
                'YouTube extraction without a JS runtime'
            ]
            if any(k.lower() in str(msg).lower() for k in filter_keywords): return
            _log_to_file(f"[ytdl-error] {msg}")
        except Exception as e:
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

# [V178.5] yt-dlp 전역 경고 차단 및 SilentLogger 자동 장착 인터셉터 🧼🛡️✨
# [V193.1] 부팅 속도 최적화: 예전엔 여기서 `import yt_dlp` 를 메인 스레드로 동기 수행했다.
#   yt_dlp 는 cryptography/urllib3/websockets/extractor 를 끌어와 실측 751ms 를 잡아먹고,
#   L1323 의 `yt_dlp = None` lazy 설계까지 무력화했다. (/media 재생과는 무관한 지불)
#   → 이제 (1) load_heavy_modules() 가 실제로 import 하는 순간에 패치를 걸고,
#     (2) 부팅 초기에 백그라운드 예열 스레드로 미리 데워둔다. 🐾
_ydl_silence_patched = False
# [V193.2] 🔒 check-then-act(플래그 확인 → orig_init 캡처 → __init__ 교체)을 두 스레드가
#   동시에 하면 _safe_ydl_init 가 이중으로 감싸일 수 있다. GIL 은 이를 막지 않는다.
#   (import 가 스레드 전환 지점이라 창이 실제로 존재) → 전용 락으로 직렬화.
_ydl_patch_lock = threading.Lock()

def _apply_ydl_silence_patch(ydl_module=None):
    """[V178.5] yt_dlp.YoutubeDL.__init__ 에 SilentLogger 를 자동 장착한다 (멱등). 🧼
    이미 패치되었으면 즉시 반환하므로 어디서 몇 번 불러도 안전하오."""
    global _ydl_silence_patched, yt_dlp
    if _ydl_silence_patched:
        return yt_dlp
    with _ydl_patch_lock:          # [V193.2] 원자적 check-then-act
        if _ydl_silence_patched:   # 대기 중 다른 스레드가 끝냈을 수 있음 → 재확인
            return yt_dlp
        try:
            if ydl_module is None:
                import yt_dlp as ydl_module
            orig_init = ydl_module.YoutubeDL.__init__
            def _safe_ydl_init(self, params=None, *args, **kwargs):
                if params is None:
                    params = {}
                if isinstance(params, dict):
                    params.setdefault('no_warnings', True)
                    params.setdefault('quiet', True)
                    if 'logger' not in params:
                        params['logger'] = SilentLogger()
                orig_init(self, params, *args, **kwargs)
            ydl_module.YoutubeDL.__init__ = _safe_ydl_init
            yt_dlp = ydl_module
            _ydl_silence_patched = True
        except Exception:
            pass
    return yt_dlp

def _bg_warm_yt_dlp():
    """[V193.1] yt_dlp 예열 스레드 본체 (데몬) — 메인 스레드는 절대 기다리지 않는다. 🐾"""
    _apply_ydl_silence_patch()

try:
    threading.Thread(target=_bg_warm_yt_dlp, name="YtDlpWarm", daemon=True).start()
except Exception:
    pass

# [V108.6] 전역 코랩 풀 객체 조기 선언 (브릿지 서버 통신용 스코프 확보) 🚽✨🛡️
# [V121.0] 🚽 ColabPool 클래스 최상단 배치 (부팅 레이스 컨디션 원천 봉쇄!) ✨🛡️
class ColabPool:
    """[V102.0] IP 기반 화장실 한줄서기(Queue) 시스템 🚽✨
    여러 코랩 서버를 IP별로 독립적으로 관리하며, 대기열을 통해 실시간으로 작업을 배분합니다.
    """

    # [TAG: #@__init__]
    def __init__(self, urls: list = None):
        self._servers = {}  # {ip_or_id: url}
        self._dead = set()  # 죽은 서버 IP
        self._queue = deque() # [V120.0] Priority-In 가변 대기열 (deque로 교체) 🚽🚀
        self._in_queue = set() # 대기열에 들어있는 IP 추적
        self._working_ips = set() # [V120.0] 현재 작업 현장에 투입된 IP 추적 👷‍♂️🏗️
        self._lock = threading.Lock()
        self._condition = threading.Condition(self._lock) # [V120.0] 큐 대기용 컨디션 변수 ✨

        self._url_locks = {}
        self._pool_init_lock = threading.Lock()

        if urls:
            self.set_urls(urls)

    # [TAG: #@_get_ip_from_url]
    def _get_ip_from_url(self, url: str) -> str:
        """URL에서 IP를 추출하거나 식별자를 생성합니다. (쿼리 파라미터 고려 ✨)"""
        from urllib.parse import urlparse, parse_qs

        # 1. 쿼리 파라미터(ip 또는 id) 또는 경로(/bridge_ip/...)가 명시되어 있다면 최우선적으로 식별자로 사용 ✨
        try:
            # [V109.5] 경로 기반 식별자 추출 우선 시도 🕵️‍♂️🔍
            path_match = re.search(r'/bridge_ip/([^/\s?&]+)', url)
            if path_match: return path_match.group(1)

            parsed = urlparse(url)
            qs = parse_qs(parsed.query)
            if 'ip' in qs and qs['ip']: return qs['ip'][0]
            if 'id' in qs and qs['id']: return qs['id'][0]
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

        # 2. 호스트명(IP) 추출 (기존 방식)
        # http://1.2.3.4:5000 -> 1.2.3.4
        match = re.search(r'//([^:/]+)', url)
        if match:
            return match.group(1)

        # 3. 최후의 보루: 해시
        return f"anon_{hash(url) % 10000}"

    # [TAG: #@get_lock]
    def get_lock(self, url: str) -> threading.Lock:
        """[V108.7] 아이피/ID 기반으로 변환하여 정밀한 전역 락 반환! 🔐✨
        localhost:5000?ip=A와 ip=B가 서로 다른 화장실(Lock)로 인식되도록 합니다냥!
        """
        # URL에서 유일한 식별자(IP 또는 ID) 추출
        lock_key = self._get_ip_from_url(url)
        with self._pool_init_lock:
            if lock_key not in self._url_locks:
                self._url_locks[lock_key] = threading.Lock()
            return self._url_locks[lock_key]

    @property
    # [TAG: #@urls]
    def urls(self) -> list:
        with self._lock:
            return list(self._servers.values())

    @property
    def primary_url(self) -> Optional[str]:
        """현재 대기열의 맨 앞에 있는 서버(또는 첫 번째 등록 서버)"""
        with self._lock:
            if not self._servers: return None
            return list(self._servers.values())[0]

    @property
    # [TAG: #@active_count]
    def active_count(self) -> int:
        with self._lock:
            return len(self._servers) - len(self._dead)

    @property
    # [TAG: #@idle_count]
    def idle_count(self) -> int:
        """대기 중인(여유 있는) 서버 개수"""
        with self._lock:
            return len(self._queue)

    # [TAG: #@update_server]
    def update_server(self, url: str, ip: str = None):
        """[V102.0] IP를 기준으로 서버 주소를 업데이트하거나 신규 등록합니다냥! 🚀"""
        if not url: return
        url = url.rstrip('/')
        if not ip: ip = self._get_ip_from_url(url)

        # [V108.9] 🔍 디버그 로깅 강화 (성능 저하 방지를 위해 상세 로그는 주석 처리 가능)
        _log_to_file(f" 🔍 [Pool] update_server - IP: {ip}, URL: {url}")

        with self._lock:
            # [V110.0] bridge_ip 전용 URL 등록 시 제네릭 127.0.0.1 항목 자동 제거 🧹✨
            # 예: http://127.0.0.1:5000/bridge_ip/8.x.x.x 가 추가되면
            # 기존에 남아있던 http://127.0.0.1:5000 (제네릭) 항목을 풀에서 청소합니다냥!
            if '/bridge_ip/' in url and ip != '127.0.0.1':
                generic_ip = '127.0.0.1'
                generic_url_base = url.split('/bridge_ip/')[0]  # http://127.0.0.1:5000
                if generic_ip in self._servers and '/bridge_ip/' not in self._servers.get(generic_ip, ''):
                    _log_to_file(f" 🧹 [Pool] 제네릭 {generic_ip} 항목 제거 (bridge_ip 전용으로 대체)")
                    del self._servers[generic_ip]
                    self._dead.discard(generic_ip)
                    self._in_queue.discard(generic_ip)
                    # 큐에서도 제거 (새 큐로 재구성)
                    old_items = []
                    while len(self._queue) > 0:
                        try: old_items.append(self._queue.popleft())
                        except: break
                    for item in old_items:
                        if item != generic_ip:
                            self._queue.append(item)

            # [V108.9] 서버 정보 업데이트
            is_new = ip not in self._servers
            self._servers[ip] = url

            # [V108.9] 🧟 서버 부활 로직 (핵심!)
            # 죽어있던 서버였다면 사망 명부에서 지우고 '무조건' 다시 줄 세우기 대상으로 설정
            was_dead = ip in self._dead
            if was_dead:
                now_str = datetime.now().strftime('%H:%M:%S')
                print(f" 🧟 [{now_str}] [Colab: {ip}] 서버 부활! 사망 명부에서 제거하고 대기열로 즉시 복귀시킵니다냥! ✨")
                self._dead.discard(ip)
                # 부활한 서버는 기존 대기열 상태(꼬임 방지)를 무시하고 합류시켜야 함
                if ip in self._in_queue:
                    self._in_queue.remove(ip)

            # [V120.5] 재연결/노크 시 대기열 즉시 복구 로직 (사용자님 전용 우선순위 정책) 🚀✨
            # 1. 아예 신규 서버이거나
            # 2. 사망 명부에 있던 서버가 부활했거나
            # 3. 등록은 되어있지만 현재 대기열에 없는 경우
            should_requeue = is_new or was_dead or (ip not in self._in_queue)

            if should_requeue:
                if ip not in self._in_queue:
                    # [V120.0] 신규/부활 서버 최우선 순위 부여 (줄 맨 앞으로 새치기!) 🚽🚀
                    if is_new or was_dead:
                        self._queue.appendleft(ip) # 신입은 맨 앞으로! 🏎️
                        now_str = datetime.now().strftime('%H:%M:%S')
                        _write_bridge_log(f" 🚽 [{now_str}] [Colab: {ip}] 신입/부활 일꾼이 최우선 순위로 합류했습니다! 🔥", console=False)
                    else:
                        self._queue.append(ip) # 기존 일꾼은 차례대로 줄서기
                        now_str = datetime.now().strftime('%H:%M:%S')
                        _write_bridge_log(f" 🧱 [{now_str}] [Colab: {ip}] 일꾼이 대기열에 합류했습니다! (대기:{len(self._queue)}대) 🛡️", console=False)

                    self._in_queue.add(ip)
                    self._condition.notify_all() # 대기 중인 acquire_server 깨우기 ✨
                else:
                    _log_to_file(f" 🔍 [Pool] {ip} 서버는 이미 대기열에 하나 서 있음 (중복 방지 🛡️)")

    # [TAG: #@add_url]
    def add_url(self, url: str):
        """기존 방식 호환용 (IP 자동 추출)"""
        self.update_server(url)

    # [TAG: #@set_urls]
    def set_urls(self, urls: list):
        """서버 목록 전체 교체 및 대기열 초기화"""
        with self._lock:
            self._servers = {}
            self._dead.clear()
            self._queue = deque()
            self._in_queue.clear()
            self._working_ips.clear()

            for u in urls:
                if u and u.strip():
                    ip = self._get_ip_from_url(u)
                    self._servers[ip] = u.rstrip('/')
                    self._queue.append(ip)
                    self._in_queue.add(ip)
            self._condition.notify_all()

    # [TAG: #@acquire_server]
    def acquire_server(self, timeout: float = None) -> Tuple[str, str]:
        """[V120.0] 사용 가능한 서버를 대기열에서 가져옵니다. (Thread-Safe Blocking) 🚽🌀"""
        start_time = time.time()
        with self._condition:
            while not self._queue:
                # [V120.0] 줄이 비어있으면 서버가 올 때까지 대기냥! ⏳
                remaining = None
                if timeout is not None:
                    remaining = timeout - (time.time() - start_time)
                    if remaining <= 0: return None, None

                if not self._condition.wait(timeout=remaining):
                    # 타임아웃 발생 시
                    if not self._queue: return None, None

            # [V120.0] 줄의 맨 앞에서 탈취! (FIFO)
            ip = self._queue.popleft()
            if ip in self._in_queue:
                self._in_queue.remove(ip)

            # [V120.0] 작업 투입 목록에 등록 👷‍♂️🏗️
            self._working_ips.add(ip)

            url = self._servers.get(ip)
            if not url or ip in self._dead:
                # 죽은 서버인 경우 버리고 다음 차례 시도 (재귀호출 시 락 주의하여 루프 권장이나 안전빵 재귀)
                return self.acquire_server(timeout=timeout - (time.time() - start_time) if timeout else None)

            return ip, url

    # [TAG: #@release_server]
    def release_server(self, ip: str):
        """[반납] 작업이 끝난 서버(IP)를 다시 대기열 맨 뒤로 보냅니다. 🔄"""
        with self._lock:
            # 작업 현장 명단에서 제거 🏁
            if ip in self._working_ips:
                self._working_ips.remove(ip)

            if ip in self._servers and ip not in self._dead:
                # [V121.0] 중복 방지: 이미 줄 서 있으면 또 넣지 않음 🛡️
                if ip not in self._in_queue:
                    self._queue.append(ip)
                    self._in_queue.add(ip)
                    self._condition.notify_all()

    # [TAG: #@mark_dead]
    def mark_dead(self, url: str):
        """서버 사망 판정 - 대기열에 다시 넣지 않습니다. (아이피 기반 정밀 매칭)"""
        if not url: return
        url = url.rstrip('/')
        target_ip = self._get_ip_from_url(url)

        with self._lock:
            # [V108.9] 사망 명부 등록 및 관리
            is_newly_dead = False

            # 1. IP가 식별된 경우 (우선)
            if target_ip in self._servers:
                if target_ip not in self._dead:
                    self._dead.add(target_ip)
                    is_newly_dead = True
                    now_str = datetime.now().strftime('%H:%M:%S')
                    # [V109.0] 메인 터미널 청소: 관제 센터로만 전송 💀
                    _write_bridge_log(f" 💀 [{now_str}] {C.RED}[서버 이탈]{C.RESET} {C.BOLD}{target_ip}{C.RESET} 서버가 사망 명부에 등록되었습니다냥.. (URL: {url})", console=False)

            # 2. IP 식별 실패 또는 등록되지 않은 URL인 경우 전체 순회 (호환성)
            if not is_newly_dead:
                for ip, f_url in list(self._servers.items()):
                    if f_url.rstrip('/') == url:
                        if ip not in self._dead:
                            self._dead.add(ip)
                            target_ip = ip # 이후 처리를 위해 매칭된 IP 저장
                            is_newly_dead = True
                            now_str = datetime.now().strftime('%H:%M:%S')
                            print(f" 💀 [{now_str}] {C.RED}[서버 이탈]{C.RESET} {ip} 서버를 사망 명부에 성공적으로 등록했습니다냥!")
                            break

            # [V122.0] 사망 처리된 서버는 대기열 및 작업 중 목록에서 즉시 제거 (상태창 정확도 향상 ✨🛡️)
            if is_newly_dead and target_ip:
                if target_ip in self._in_queue: self._in_queue.remove(target_ip)
                if target_ip in self._working_ips: self._working_ips.remove(target_ip)
            elif not is_newly_dead:
                _log_to_file(f" 🔍 [Pool] mark_dead 실패: {url} 에 해당하는 활성 서버를 못 찾음")

    # [TAG: #@get_url]
    def get_url(self, skip_locked: bool = False) -> Optional[str]:
        """기존 로직 호환용 (단일 URL 반환)"""
        # 호환성을 위해 대기열에서 잠깐 빌려왔다 바로 반납하는 식으로 동작
        ip, url = self.acquire_server(timeout=1.0)
        if ip:
            self.release_server(ip)
            return url

        p_url = self.primary_url
        return p_url if p_url else None

    # [TAG: #@request_with_failover]
    def request_with_failover(self, method: str, endpoint: str, **kwargs) -> 'requests.Response':
        """기존 로직 호환 (대기열 기반으로 1회 시도)"""
        ip, url = self.acquire_server(timeout=5.0)
        if not ip: raise RuntimeError("사용 가능한 코랩 서버가 없습니다.")

        try:
            import requests as _req
            full_url = url.rstrip('/') + endpoint
            if method.lower() == 'get': resp = _req.get(full_url, **kwargs)
            else: resp = _req.post(full_url, **kwargs)
            return resp
        finally:
            self.release_server(ip)

    # [TAG: #@to_list]
    def to_list(self) -> list:
        return list(self._servers.values())

    # [TAG: #@__str__]
    def __str__(self):
        with self._lock:
            # [V120.0] 직관적인 상태 대시보드 출력 (Working/Ready/Dead 구분) 🎬✨
            active_info = []
            for ip in self._servers:
                if ip in self._dead: status = "💀Dead"
                elif ip in self._working_ips: status = "🏗️Busy"
                elif ip in self._in_queue: status = "🍵Idle"
                else: status = "❓Wait" # 등록은 되었으나 큐/작업 양쪽 다 없는 상태
                active_info.append(f"{ip}({status})")

            return f"ColabPool [{' | '.join(active_info)}]"

# [V121.0] G_COLAB_POOL 조기 초기화 (원천 봉쇄) ✨🛡️
G_COLAB_POOL = ColabPool([])

# ==============================================================================
# [V141.0] 스텔스 우회 엔진 (StealthProxyServer) - SNI 파편화 SOCKS5 프록시 🕵️‍♂️📡✨
# ==============================================================================
class StealthProxyServer:
    """[V141.0] 초경량 SNI 파편화 SOCKS5 프록시 엔진 📡🛠️
    사용자님의 'Miss19 매니저' 전용 타겟 우회를 위해 설계되었습니다.
    """
    # [TAG: #@__init___2]
    def __init__(self, host='127.0.0.1', port=18181):
        self.host = host
        self.port = port
        self.running = False
        self.server_sock = None
        self._thread = None
        self._lock = threading.Lock() # [V141.2] 🛡️ 스레드 세이프 락 추가
        # [V141.12] DNS cache (도메인: IP) 🧠
        # [V154.20] AI냥 요청: Nyaa/Sukebei 접속 불가 차단 해결을 위한 Static IP 선제 등록 🏁✨
        self._dns_cache = {
            'nyaa.si': '186.2.163.20',
            'sukebei.nyaa.si': '198.251.89.38',
            'www.nyaa.si': '186.2.163.20',
            'www.sukebei.nyaa.si': '198.251.89.38'
        }

    # [TAG: #@start]
    def start(self):
        with self._lock:
            if self.running: return
            self.running = True
            self.server_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.server_sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            try:
                self.server_sock.bind((self.host, self.port))
                self.server_sock.listen(128)
                self._thread = threading.Thread(target=self._run, daemon=True)
                self._thread.start()
                _log_to_file(f"📡 [Stealth] 프록시 엔진 가동 시작! (127.0.0.1:{self.port})")
            except Exception as e:
                _log_to_file(f"⚠️ [Stealth] 엔진 바인딩 실패: {e}")
                self.running = False

    # [TAG: #@stop]
    def stop(self):
        with self._lock:
            self.running = False
            if self.server_sock:
                try: self.server_sock.close()
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")
            _log_to_file("📡 [Stealth] 프록시 엔진 정지.")

    # [TAG: #@_run]
    def _run(self):
        while self.running:
            try:
                client_sock, addr = self.server_sock.accept()
                threading.Thread(target=self._handle_client, args=(client_sock,), daemon=True).start()
            except: break

    # [TAG: #@_recvall]
    def _recvall(self, sock, n):
        """[V141.3] TCP 분할 수신 안전 버퍼 - n바이트를 반드시 모두 읽어야 리턴 🛡️"""
        buf = b''
        while len(buf) < n:
            chunk = sock.recv(n - len(buf))
            if not chunk:
                return None
            buf += chunk
        return buf

    # [TAG: #@_handle_client]
    def _handle_client(self, client_sock):
        remote_sock = None # [V141.3] 🛡️ 소켓 누수 방지: 항상 None으로 초기화
        try:
            client_sock.settimeout(10.0)
            # 1. SOCKS5 Handshake - [V141.3] 완전수신 보장 (TCP partial recv 버그 픽스)
            greet = self._recvall(client_sock, 2)
            if not greet or greet[0] != 0x05: client_sock.close(); return
            n_methods = greet[1]
            self._recvall(client_sock, n_methods) # 메서드 목록 완전 소비
            client_sock.sendall(b"\x05\x00")

            # 2. SOCKS5 Request - [V141.3] 4바이트 완전수신 보장
            data = self._recvall(client_sock, 4)
            if not data or data[1] != 1: # CONNECT 전용
                client_sock.close(); return

            atyp = data[3]
            if atyp == 1: # IPv4
                raw = self._recvall(client_sock, 4)
                if not raw: client_sock.close(); return
                addr = socket.inet_ntoa(raw)
            elif atyp == 3: # Domain
                lenb = self._recvall(client_sock, 1)
                if not lenb: client_sock.close(); return
                addr_len = lenb[0]
                raw_addr = self._recvall(client_sock, addr_len)
                if not raw_addr: client_sock.close(); return
                addr = raw_addr.decode()

                # [V141.2] Stealth DoH (DNS over HTTPS) 엔진 내장! 📡🛡️
                if not addr.replace('.', '').isdigit():
                    # [V141.12] DNS 캐시 체크 🧠
                    if addr in self._dns_cache:
                        addr = self._dns_cache[addr]
                    else:
                        try:
                            import urllib.request
                            # 1차 시도: Cloudflare DoH
                            try:
                                req = urllib.request.Request(
                                    f"https://cloudflare-dns.com/dns-query?name={addr}&type=A",
                                    headers={"accept": "application/dns-json"}
                                )
                                with urllib.request.urlopen(req, timeout=3) as resp:
                                    doh_data = json.loads(resp.read().decode())
                                    if "Answer" in doh_data:
                                        for ans in doh_data["Answer"]:
                                            if ans["type"] == 1: # A record
                                                addr = ans["data"]
                                                self._dns_cache[raw_addr.decode()] = addr # 캐시 저장
                                                break
                            except:
                                # 2차 시도: Google DoH (Cloudflare 차단 대비 백업)
                                req = urllib.request.Request(
                                    f"https://dns.google/resolve?name={addr}&type=A",
                                    headers={"accept": "application/json"}
                                )
                                with urllib.request.urlopen(req, timeout=3) as resp:
                                    doh_data = json.loads(resp.read().decode())
                                    if "Answer" in doh_data:
                                        for ans in doh_data["Answer"]:
                                            if ans["type"] == 1: # A record
                                                addr = ans["data"]
                                                self._dns_cache[raw_addr.decode()] = addr # 캐시 저장
                                                break
                        except Exception as e:
                            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                            if "6" not in str(e):
                                _log_to_file(f"⚠️ [Silent Exception] {e}")

            else: # IPv6 등 미지원 타입
                client_sock.close(); return

            port_raw = self._recvall(client_sock, 2)
            if not port_raw: client_sock.close(); return
            port = int.from_bytes(port_raw, 'big')

            # 3. Connect to Target
            try:
                remote_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                remote_sock.settimeout(10)
                remote_sock.connect((addr, port))
                client_sock.sendall(b"\x05\x00\x00\x01" + b"\x00\x00\x00\x00\x00\x00")
            except Exception:
                # [V141.3] 연결 실패 시 remote_sock도 반드시 정리 (소켓 핸들 누수 방지)
                client_sock.sendall(b"\x05\x01\x00\x01" + b"\x00\x00\x00\x00\x00\x00")
                try: client_sock.close()
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")
                try:
                    if remote_sock: remote_sock.close()
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")
                return

            # 4. Data Transfer (Targeting Fragmentation for Port 80, 443) ✂️✨
            if port in [80, 443]:
                self._transfer_with_fragment(client_sock, remote_sock)
            else:
                self._pipe(client_sock, remote_sock)

        except:
            try: client_sock.close()
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")
            try:
                if remote_sock: remote_sock.close() # [V141.3] 예외 경로 remote_sock 누수 방지
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

    # [TAG: #@_transfer_with_fragment]
    def _transfer_with_fragment(self, client, remote):
        """[V141.9] 통합 파편화 로직 - 첫 패킷(SNI or HTTP Host) 조각내서 전송 🕵️‍♂️✂️"""
        try:
            # 첫 요청 패킷 대기
            first_chunk = client.recv(8192)
            if not first_chunk: return

            # 📡 [DPI Bypass] TCP_NODELAY로 버퍼링 끄고 강제로 쪼개서 보냄냥!
            remote.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)

            # [V141.13] SecretDNS 스타일의 '랜덤 다단계 파편화' (Random Multi-Stage) 🎲✂️
            # 검열 장비의 패턴 인식을 방지하기 위해 분할 위치를 가변적으로 설정하며,
            # 초정밀 지연(0.005s)을 통해 Python SSL 모듈과의 타이밍 호환성을 확보합니다냥!
            # 1단계: 선제 1~3바이트 전송
            # [V141.15] TLS 핸드셰이크 안정성을 위해 첫 조각 크기 상향 (3~5바이트) ✂️🛡️
            idx1 = random.randint(3, 5)
            remote.sendall(first_chunk[:idx1])
            time.sleep(0.005)

            # 2단계: 중간 패킷(5~20바이트 범위) 랜덤 전송
            idx2 = random.randint(idx1 + 1, 20)
            remote.sendall(first_chunk[idx1:idx2])
            time.sleep(0.005)

            # 3단계: 나머지 전체 전송
            remote.sendall(first_chunk[idx2:])

            # 이후는 고속 파이핑 모드로 전환
            self._pipe(client, remote)
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")
        finally:
            try: client.close()
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")
            try: remote.close()
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

    # [TAG: #@_pipe]
    def _pipe(self, s1, s2):
        """양방향 단순 데이터 파이핑 🚰"""
        import select
        try:
            while True:
                # [V141.3] select 타임아웃 60초 설정 - half-close 좀비 스레드 방지! ⏱️🧟
                r, w, e = select.select([s1, s2], [], [], 60)
                if not r: break  # 60초간 데이터 없으면 연결 종료 판단
                if s1 in r:
                    data = s1.recv(8192)
                    if not data: break
                    s2.sendall(data)
                if s2 in r:
                    data = s2.recv(8192)
                    if not data: break
                    s1.sendall(data)
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")
        finally:
            try: s1.close()
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")
            try: s2.close()
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

