def _find_warp_cli():
    """Cloudflare WARP CLI 실행 파일 경로를 탐색합니다냥! ⚡"""
    import shutil
    p = shutil.which("warp-cli")
    if p and os.path.exists(p):
        return p
    candidate_paths = [
        os.path.expandvars(r"%ProgramFiles%\Cloudflare\Cloudflare WARP\warp-cli.exe"),
        os.path.expandvars(r"%ProgramFiles(x86)%\Cloudflare\Cloudflare WARP\warp-cli.exe"),
        os.path.expandvars(r"%LocalAppData%\Cloudflare\warp-cli.exe"),
    ]
    for cp in candidate_paths:
        if os.path.exists(cp):
            return cp
    return None

def _is_warp_connected():
    """WARP 터널 연결 여부를 확인합니다."""
    cli = _find_warp_cli()
    if not cli:
        return False
    try:
        res = subprocess.run([cli, "status"], capture_output=True, text=True, timeout=3)
        return "Connected" in res.stdout
    except Exception:
        return False

