def _set_windows_system_proxy(enable=True, server=""):
    """[V193.0] 윈도우 시스템 프록시를 켜거나 끕니다. (WinINet 동기화) 🌐"""
    if os.name != 'nt':
        return False
    try:
        import winreg, ctypes
        INTERNET_SETTINGS = r"Software\Microsoft\Windows\CurrentVersion\Internet Settings"
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, INTERNET_SETTINGS, 0, winreg.KEY_WRITE) as key:
            if enable and server:
                winreg.SetValueEx(key, "ProxyEnable", 0, winreg.REG_DWORD, 1)
                winreg.SetValueEx(key, "ProxyServer", 0, winreg.REG_SZ, server)
            else:
                winreg.SetValueEx(key, "ProxyEnable", 0, winreg.REG_DWORD, 0)

        # WinINet 인터넷 옵션 실시간 갱신 통보 (브라우저 즉시 반영)
        try:
            INTERNET_OPTION_SETTINGS_CHANGED = 39
            INTERNET_OPTION_REFRESH = 37
            internet_set_option = ctypes.windll.Wininet.InternetSetOptionW
            internet_set_option(0, INTERNET_OPTION_SETTINGS_CHANGED, 0, 0)
            internet_set_option(0, INTERNET_OPTION_REFRESH, 0, 0)
        except Exception:
            pass
        return True
    except Exception as e:
        _log_to_file(f"⚠️ [SystemProxy] 설정 실패: {e}")
        return False

def _test_node_ping(server_str, timeout=1.5):
    """프록시 노드의 연결 핑(ms)을 측정합니다."""
    try:
        parts = server_str.split(":")
        host = parts[0]
        port = int(parts[1]) if len(parts) > 1 else 8080
        t0 = time.time()
        s = socket.create_connection((host, port), timeout=timeout)
        s.close()
        return round((time.time() - t0) * 1000)
    except Exception:
        return -1

