# [TAG: #@_migrate_ff_binaries]
def _migrate_ff_binaries():
    """[V16.3.0] 루트의 ff* 파일들을 temp/ 폴더로 자동 이동 (정리 및 이슈 방지) 🚚✨"""
    try:
        script_dir = os.path.dirname(os.path.abspath(__file__))
        temp_dir = os.path.join(script_dir, "temp")
        if not os.path.exists(temp_dir):
            os.makedirs(temp_dir, exist_ok=True)

        migrated = False
        for fn in ["ffmpeg.exe", "ffprobe.exe", "ffplay.exe"]:
            src = os.path.join(script_dir, fn)
            dst = os.path.join(temp_dir, fn)
            if os.path.exists(src):
                try:
                    # 대상이 이미 있으면 제거 후 이동 (최신성 유지)
                    if os.path.exists(dst):
                        try: os.remove(dst)
                        except Exception as e:
                            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                            if "6" not in str(e):
                                _log_to_file(f"⚠️ [Silent Exception] {e}")
                    shutil.move(src, dst)
                    _log_to_file(f"🚚 {fn} 파일을 temp/ 폴더로 이동 완료! (호환성 유지)")
                    migrated = True
                except Exception as e:
                    _log_to_file(f"⚠️ {fn} 이동 중 오류: {e}")

        if migrated:
            print(f"\r\n 🚚 {C.SKY}[시스템 정리]{C.RESET} 루트에 있던 FFmpeg 바이너리들을 {C.BOLD}temp/{C.RESET} 폴더로 옮겼어냥! ✨")
            time.sleep(0.5)
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")

# [TAG: #@_get_ffmpeg_bin]

def _get_ffmpeg_bin():
    """[V176.8] ffmpeg.exe 경로를 찾습니다 (temp/ 및 시스템 절대경로 보장) 🎬"""
    try:
        script_dir = os.path.dirname(os.path.abspath(__file__))
        temp_ff = os.path.join(script_dir, "temp", "ffmpeg.exe")
        if os.path.exists(temp_ff): return os.path.normpath(temp_ff)
        root_ff = os.path.join(script_dir, "ffmpeg.exe")
        if os.path.exists(root_ff): return os.path.normpath(root_ff)
        sys32_ff = r"C:\Windows\System32\ffmpeg.exe"
        if os.path.exists(sys32_ff): return os.path.normpath(sys32_ff)
        found = shutil.which("ffmpeg.exe") or shutil.which("ffmpeg")
        if found and os.path.exists(found): return os.path.normpath(found)
        return "ffmpeg"
    except: return "ffmpeg"


# [TAG: #@_get_ffprobe_bin]
def _get_ffprobe_bin():
    """[V176.8] ffprobe.exe 경로를 찾습니다 (temp/ 및 시스템 절대경로 보장) 🎬"""
    try:
        script_dir = os.path.dirname(os.path.abspath(__file__))
        temp_ff = os.path.join(script_dir, "temp", "ffprobe.exe")
        if os.path.exists(temp_ff): return os.path.normpath(temp_ff)
        root_ff = os.path.join(script_dir, "ffprobe.exe")
        if os.path.exists(root_ff): return os.path.normpath(root_ff)
        sys32_ff = r"C:\Windows\System32\ffprobe.exe"
        if os.path.exists(sys32_ff): return os.path.normpath(sys32_ff)
        found = shutil.which("ffprobe.exe") or shutil.which("ffprobe")
        if found and os.path.exists(found): return os.path.normpath(found)
        return "ffprobe"
    except: return "ffprobe"

# [TAG: #@_get_ytdl_js_runtimes]
def _get_ytdl_js_runtimes():
    """[V175.0] yt-dlp JS 챌린지 및 n-challenge 해결을 위한 Node.js / Deno 등 JS 런타임 탐색 🚀⚡"""
    runtimes = {}
    try:
        node_path = shutil.which("node")
        if not node_path:
            for p in [
                r"C:\Program Files\nodejs\node.exe",
                r"C:\Program Files (x86)\nodejs\node.exe",
                os.path.expandvars(r"%LOCALAPPDATA%\Programs\nodejs\node.exe"),
                os.path.expandvars(r"%APPDATA%\npm\node.exe"),
            ]:
                if os.path.isfile(p):
                    node_path = p
                    break
        if node_path and os.path.isfile(node_path):
            runtimes['node'] = {'path': os.path.normpath(node_path)}

        deno_path = shutil.which("deno")
        if not deno_path:
            for p in [
                os.path.expandvars(r"%USERPROFILE%\.deno\bin\deno.exe"),
                os.path.expandvars(r"%LOCALAPPDATA%\Programs\deno\deno.exe"),
            ]:
                if os.path.isfile(p):
                    deno_path = p
                    break
        if deno_path and os.path.isfile(deno_path):
            runtimes['deno'] = {'path': os.path.normpath(deno_path)}
    except Exception:
        pass
    return runtimes

# [TAG: #@_get_ytdl_cookiefile]
def _get_ytdl_cookiefile():
    """[V176.5] 유튜브 로그인/연령제한/봇우회를 위한 cookies.txt 자동 탐색 🍪✨"""
    try:
        base_dir = os.path.dirname(os.path.abspath(__file__))
        candidate_paths = [
            os.path.join(base_dir, "cookies.txt"),
            os.path.join(base_dir, "youtube_cookies.txt"),
            os.path.join(base_dir, "temp", "cookies.txt"),
            os.path.join(base_dir, "temp", "youtube_cookies.txt"),
        ]
        for cp in candidate_paths:
            if os.path.isfile(cp) and os.path.getsize(cp) > 10:
                return cp
    except Exception:
        pass
    return None

# [TAG: #@_is_valid_media_file]
def _is_valid_media_file(path: str, require_video: bool = False, timeout: int = 10) -> bool:
    """[V178.11] 잔재 '쓰레기' 판별 — ffprobe로 실제 파싱되는 파일만 '다운로드 성공'으로 인정한다. 🧪🛡️
    [배경] 2026-10-08 실측 사고: 디스크 용량 부족(Errno 28)으로 yt-dlp 결합이 꼬여
            `.temp.mp4`(moov 없음=완전 복구 불가) 와 `.f234-1.mp4`(29초 결손)가 남았는데,
            '크기 > 1MB' 만 보므로 "다운로드 성공"으로 오인되어 장부에 영구 기록되고
            재다운로드가 원천 차단돼 버렸음. → 반드시 ffprobe 로 실제 무결성을 확인할 것.
    - require_video=False : 영상 OR (정상 확장자의) 오디오만 있으면 True (MP3/M4A 전용 다운로드 보호)
    - require_video=True  : 영상 스트림이 반드시 있어야 True (영상 다운로드 검증용)
    """
    if not path or not os.path.isfile(path):
        return False
    try:
        if os.path.getsize(path) < 1024:
            return False
    except OSError:
        return False
    try:
        flags = 0x08000000 if os.name == 'nt' else 0
        probe_cmd = [_get_ffprobe_bin(), "-v", "error", "-show_entries", "stream=codec_type", "-of", "csv=p=0", path]
        p_res = subprocess.run(probe_cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, creationflags=flags, timeout=timeout)
        st_types = p_res.stdout.decode('utf-8', errors='replace').split()
        if 'video' in st_types:
            return True
        if require_video:
            return False
        # 오디오 전용은 '정상 확장자'까지 확인해 잘린 잔재(.f234-1.mp4 같은 mp4-named 오디오)를 걸러낸다!
        if 'audio' in st_types:
            return os.path.splitext(path)[1].lower() in ('.mp3', '.m4a', '.aac', '.opus', '.wav', '.flac', '.mp4.aac')
        return False
    except Exception:
        return False

# [TAG: #@_ensure_download_disk_space]
def _ensure_download_disk_space(path: str, need_bytes: int = 2 * 1024 ** 3) -> bool:
    """[V178.11] 다운로드 착수 '전' 저장 드라이브 여유 공간 사전 검사 (Errno 28 원천 차단) 💾🛡️
    [배경] 2026-10-08 실측: G: 용량 부족 상태에서 3회나 futile 재시도 후 포기 → 시간·대역폭 낭비.
    """
    try:
        target = path if os.path.isdir(path) else (os.path.dirname(path) or path)
        free_b = shutil.disk_usage(target).free
        if free_b < need_bytes:
            _log_to_file(f"🛑 [Disk-Guard] '{target}' 여유 공간 {free_b / 1024**3:.2f}GB < 필요 {need_bytes / 1024**3:.2f}GB "
                         f"→ 다운로드를 시작하지 않고 즉시 중단한다 (Errno 28 futile 재시도 원천 차단)! 🚀")
            return False
        return True
    except Exception:
        return True  # 검사 실패 시엔 기존 동작 유지 (강제 중단 금지)

# [TAG: #@_repair_and_merge_unmerged_streams]
def _repair_and_merge_unmerged_streams(target_dir: str, save_to_dir: str = None) -> list:
    """[V177.4] .f248.webm, .f137.mp4 등 미결합 스트림 파일을 감지하여 짝 오디오와 함께 무손실(Lossless) 초고속 결합 🎬🔊✨"""
    if not target_dir or not os.path.exists(target_dir):
        return []
    
    import re, subprocess, shutil
    ff = _get_ffmpeg_bin()
    fp = _get_ffprobe_bin()
    flags = 0x08000000 if os.name == 'nt' else 0
    merged_files = []
    
    out_dir = save_to_dir if (save_to_dir and os.path.exists(save_to_dir)) else target_dir
    
    try:
        files = os.listdir(target_dir)
    except Exception:
        return []
        
    # [V178.11] yt-dlp가 이름 충돌 회피용으로 붙이는 '-N' 접미사(.f234-1.mp4)와
    #            결합 실패 잔재(.temp.mp4)까지 인식한다! (기존엔 둘 다 놓쳐 짝을 못 찾았음) 🛡️
    pattern = re.compile(r'^(?P<base>.+?)\.(?:f(?P<fmt>\d+)(?:-\d+)?|temp(?:-\d+)?)\.(?P<ext>webm|mp4|mkv|m4a)$', re.IGNORECASE)
    
    groups = {}
    for f in files:
        if f.endswith(('.part', '.ytdl', '.temp', '.tmp', '.lock')): continue
        m = pattern.match(f)
        if m:
            base = m.group('base')
            fmt = m.group('fmt')
            ext = m.group('ext').lower()
            full_p = os.path.join(target_dir, f)
            if os.path.isfile(full_p) and os.path.getsize(full_p) > 1024:
                groups.setdefault(base, []).append({'file': f, 'fmt': fmt, 'ext': ext, 'path': full_p})
                
    for base, stream_list in groups.items():
        try:
            video_item = None
            audio_item = None
            
            for item in stream_list:
                try:
                    probe_cmd = [fp, "-v", "error", "-show_entries", "stream=codec_type", "-of", "csv=p=0", item['path']]
                    p_res = subprocess.run(probe_cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, creationflags=flags, timeout=5)
                    st_types = p_res.stdout.decode('utf-8', errors='replace').strip().split()
                    if 'video' in st_types and not video_item:
                        video_item = item
                    elif 'audio' in st_types and not audio_item:
                        audio_item = item
                except Exception:
                    pass

            # [V178.11] probe가 '(video도 audio도 아님)' 으로 떨어진 .temp.* 는 yt-dlp 결합 실패 잔재다.
            #            moov 박스(샘플 인덱스+SPS/PPS)가 없어 복구가 불가능하므로 휴지통으로 폐기한다! 🗑️🛡️
            for item in stream_list:
                if item.get('fmt') is None and not _is_valid_media_file(item['path']):
                    _log_to_file(f"🗑️ [Stream Merger] 결합 실패 잔재 폐기(복구 불가): {item['file']}")
                    try: safe_remove_file(item['path'], use_trash=True)
                    except Exception: pass
            
            if video_item:
                clean_base = base.replace(' ', '_')
                final_out = os.path.join(out_dir, f"{clean_base}.mp4")

                # [V178.9] 챕터 주입 및 오디오 보충을 위한 v_id 사전 탐색 🕵️‍♂️🔍
                v_id = None
                v_id_match = re.search(r'\[([0-9A-Za-z_-]{11})\]', base)
                if not v_id_match:
                    v_id_match = re.search(r'([0-9A-Za-z_-]{11})$', base)
                if v_id_match:
                    v_id = v_id_match.group(1)
                else:
                    _clean_query = re.sub(r'^\[.*?\]\s*', '', base).strip()
                    if _clean_query:
                        try:
                            import yt_dlp
                            _s_opts = _apply_ytdl_stealth_opts({'extract_flat': True, 'quiet': True, 'no_warnings': True, 'logger': SilentLogger()})
                            with yt_dlp.YoutubeDL(_s_opts) as ydl_s:
                                s_res = ydl_s.extract_info(f"ytsearch1:{_clean_query}", download=False)
                                if s_res and 'entries' in s_res and s_res['entries']:
                                    v_id = s_res['entries'][0].get('id')
                        except Exception: pass
                
                # Case A: 짝이 되는 오디오 스트림이 있는 경우 -> 즉시 무손실 합체!
                if audio_item:
                    _log_to_file(f"🍳 [Stream Merger] Merging video ({video_item['file']}) + audio ({audio_item['file']}) -> {final_out}")
                    cmd = [
                        ff, "-y",
                        "-i", video_item['path'],
                        "-i", audio_item['path'],
                        "-c", "copy",
                        "-map", "0:v:0",
                        "-map", "1:a:0",
                        "-movflags", "+faststart",
                        final_out
                    ]
                    m_res = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, creationflags=flags, timeout=60)
                    if m_res.returncode == 0 and os.path.exists(final_out) and os.path.getsize(final_out) > 1024 * 1024:
                        _log_to_file(f"✅ [Stream Merger Success] Created merged file: {final_out}")
                        # [V178.9] 미결합 스트림 결합 후 챕터 정보 즉시 주입 보장! 📖✨
                        if '_inject_youtube_chapters_if_needed' in globals():
                            try:
                                _v_url = f"https://www.youtube.com/watch?v={v_id}" if v_id else None
                                globals()['_inject_youtube_chapters_if_needed'](final_out, video_url=_v_url)
                            except Exception as _che:
                                _log_to_file(f"⚠️ [Stream Merger Case A Chapter Error] {_che}")
                        merged_files.append(final_out)
                        try: os.remove(video_item['path'])
                        except Exception: pass
                        try: os.remove(audio_item['path'])
                        except Exception: pass
                        continue
                
                # Case B: 비디오 스트림만 있고 짝 오디오가 누락된 경우 -> yt-dlp로 오디오 단독 보충 다운로드 후 결합!
                if v_id:
                    _log_to_file(f"🛰️ [Stream Merger] Video ID {v_id} detected. Fetching missing audio for {base}...")
                    temp_audio_out = os.path.join(target_dir, f"{base}.temp_audio.m4a")
                    y_audio_opts = {
                        'ffmpeg_location': ff,
                        'format': 'bestaudio[ext=m4a]/bestaudio/best',
                        'outtmpl': temp_audio_out,
                        'quiet': True,
                        'no_warnings': True,
                        'logger': SilentLogger(),
                    }
                    y_audio_opts = _apply_ytdl_stealth_opts(y_audio_opts)
                    try:
                        import yt_dlp
                        with yt_dlp.YoutubeDL(y_audio_opts) as ydl_a:
                            ydl_a.download([f"https://www.youtube.com/watch?v={v_id}"])
                            
                        actual_audio = temp_audio_out if os.path.exists(temp_audio_out) else None
                        if not actual_audio:
                            for cf in os.listdir(target_dir):
                                if f"{base}.temp_audio" in cf:
                                    actual_audio = os.path.join(target_dir, cf); break
                                    
                        if actual_audio and os.path.exists(actual_audio):
                            cmd = [
                                ff, "-y",
                                "-i", video_item['path'],
                                "-i", actual_audio,
                                "-c", "copy",
                                "-map", "0:v:0",
                                "-map", "1:a:0",
                                "-movflags", "+faststart",
                                final_out
                            ]
                            m_res = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, creationflags=flags, timeout=60)
                            if m_res.returncode == 0 and os.path.exists(final_out) and os.path.getsize(final_out) > 1024 * 1024:
                                _log_to_file(f"✅ [Stream Merger Success with fetched audio] {final_out}")
                                # [V178.9] 오디오 보충 결합 후 챕터 정보 즉시 주입 보장! 📖✨
                                if '_inject_youtube_chapters_if_needed' in globals():
                                    try:
                                        _v_url = f"https://www.youtube.com/watch?v={v_id}" if v_id else None
                                        globals()['_inject_youtube_chapters_if_needed'](final_out, video_url=_v_url)
                                    except Exception as _che:
                                        _log_to_file(f"⚠️ [Stream Merger Case B Chapter Error] {_che}")
                                merged_files.append(final_out)
                                try: os.remove(video_item['path'])
                                except Exception: pass
                                try: os.remove(actual_audio)
                                except Exception: pass
                                continue
                    except Exception as _fe:
                        _log_to_file(f"⚠️ [Stream Merger Fetch Audio Error] {_fe}")
                        
        except Exception as _ge:
            _log_to_file(f"⚠️ [Stream Merger Group Error] {base}: {_ge}")
            
    return merged_files

# [TAG: #@_apply_ytdl_stealth_opts]
def _apply_ytdl_stealth_opts(opts: dict):
    """[V177.4] yt-dlp 최신 우회 옵션 및 ffmpeg 위치를 자동 주입냥! 🛡️✨"""
    if not isinstance(opts, dict):
        return opts
    js_rt = _get_ytdl_js_runtimes()
    if js_rt:
        opts['js_runtimes'] = js_rt
    opts.setdefault('remote_components', ['ejs:github'])
    opts.setdefault('no_warnings', True)
    opts.setdefault('quiet', True)
    if 'logger' not in opts:
        opts['logger'] = SilentLogger()
    
    # 🍳 FFmpeg 위치 전역 100% 필수 주입 (비디오+오디오 결합 및 자막/메타데이터 주입 보장)
    ff_bin = _get_ffmpeg_bin()
    if ff_bin:
        opts.setdefault('ffmpeg_location', ff_bin)

    ext_args = opts.setdefault('extractor_args', {})
    if isinstance(ext_args, dict):
        yt_sub = ext_args.setdefault('youtube', {})
        if isinstance(yt_sub, dict):
            yt_sub.setdefault('lang', ['ko'])
            yt_sub.setdefault('country', ['KR'])
            
    opts['referer'] = 'https://www.youtube.com/'
            
    cookie_file = _get_ytdl_cookiefile()
    if cookie_file:
        opts['cookiefile'] = cookie_file
    return opts

# [TAG: #@verify_ffmpeg_diagnostics]
def verify_ffmpeg_diagnostics():
    """FFmpeg와 FFprobe가 실제로 실행 가능한지 최종 테스트하고 정보를 출력합니다냥! 🕵️‍♂️🛡️✨"""
    ff = _get_ffmpeg_bin()
    fp = _get_ffprobe_bin()

    _log_to_file(f"🔍 [FFmpeg:Diag] Testing binaries: FF={ff}, FP={fp}")

    results = {"ffmpeg": False, "ffprobe": False, "version": "Unknown"}

    flags = 0x08000000 if os.name == 'nt' else 0

    # 1. FFmpeg 테스트
    try:
        res = subprocess.run([ff, "-version"], capture_output=True, text=True, encoding="utf-8", errors="replace", creationflags=flags, timeout=5)
        if res.returncode == 0:
            results["ffmpeg"] = True
            v_match = re.search(r'ffmpeg version ([\w\.\-]+)', res.stdout)
            if v_match: results["version"] = v_match.group(1)
    except Exception as e:
        _log_to_file(f" ❌ [FFmpeg:Diag] FFmpeg test failed: {e}")

    # 2. FFprobe 테스트
    try:
        res = subprocess.run([fp, "-version"], capture_output=True, text=True, encoding="utf-8", errors="replace", creationflags=flags, timeout=5)
        if res.returncode == 0:
            results["ffprobe"] = True
    except Exception as e:
        _log_to_file(f" ❌ [FFmpeg:Diag] FFprobe test failed: {e}")

    # 결과 출력
    if results["ffmpeg"] and results["ffprobe"]:
        print(f"   ✅ {C.GREEN}[엔진 정상]{C.RESET} FFmpeg {results['version']} 버전이 준비되었습니다. 🚀")
        return True
    else:
        print(f"   ❌ {C.RED}[엔진 오류]{C.RESET} FFmpeg가 정상적으로 설치되지 않았거나 실행할 수 없어냥!")
        print(f"      - 경로1: {ff}")
        print(f"      - 경로2: {fp}")
        print("      - 해결: 'temp' 폴더에 ffmpeg.exe, ffprobe.exe를 직접 넣어주면 해결돼냥! 🐣")
        return False


# [TAG: #@_clear_console_buffer]
def _clear_console_buffer(lines=10, push_history=True):
    """[사용자 전용] 화면을 지우기 전 기존 내용을 밀어올려(push_history) 스크롤을 보존하고 여백을 둡니다. 🧹✨"""
    if push_history:
        # [V17.3.19] AI 가이드: 기존 내용을 스크롤 히스토리로 밀어올리기냥! 🚀
        sys.stdout.write('\r\n' * 40)
        sys.stdout.flush()

    # 1. 화면 초기화 (Home & Clear Below 방식 - 스크롤 보존) ✨
    clear_console(history_preserve=True, push_history=False) # 위에서 이미 밀었으므로 중복 방지

    # 2. 요청하신 여백 추가
    if lines > 0:
        sys.stdout.write('\r\n' * lines)
    sys.stdout.flush()

# [V82.6] 콘솔 UI 겹침 방지를 위한 전역 자물쇠 (RLock으로 교체 - 데드락 방지) 🔐🔄
# 배경 스레드(Ollama 설치 등)와 메인 메뉴 루프가 동시에 콘솔을 쓰는 걸 막아줍니다.
G_CONSOLE_UI_LOCK = threading.RLock()
