# [TAG: #@_encrypt_json_data]
def _encrypt_json_data(data_dict: dict) -> str:
    """[V150.1] JSON 데이터를 암호화 문자열로 변환합니다냥! 🔐✨"""
    import json as _json
    import base64 as _base64
    try:
        raw_str = _json.dumps(data_dict, ensure_ascii=False)
        key = "BINU_SECRET_KEY_OTT_🦦".encode('utf-8') # [수정] 이모지 호환성 확보 ✨
        raw_bytes = raw_str.encode('utf-8')
        xored = bytes([b ^ key[i % len(key)] for i, b in enumerate(raw_bytes)])
        return _base64.b64encode(xored).decode('utf-8')
    except Exception as e:
        _log_to_file(f"⚠️ [Encrypt] 암호화 실패: {e}")
        return _json.dumps(data_dict, ensure_ascii=False)

# [TAG: #@_decrypt_json_data]
def _decrypt_json_data(enc_data: str) -> dict:
    """[V150.1] 암호화된 데이터를 JSON으로 복원합니다냥! (하위호환 지원) 🔓✨"""
    import json as _json
    import base64 as _base64
    if not enc_data: return {}
    try:
        # 1. 암호화된 데이터(Base64)인 경우 복호화 시도
        key = "BINU_SECRET_KEY_OTT_🦦".encode('utf-8') # [수정] 이모지 호환성 확보 ✨
        raw_bytes = _base64.b64decode(enc_data)
        xored = bytes([b ^ key[i % len(key)] for i, b in enumerate(raw_bytes)])
        return _json.loads(xored.decode('utf-8'))
    except Exception:
        # 2. 복호화 실패 시 기존 평문 JSON일 가능성이 99% → 그대로 로드
        try:
            return _json.loads(enc_data)
        except Exception as e:
            _log_to_file(f"⚠️ [Decrypt] 최종 로드 실패: {e}")
            return {}

# [TAG: #@_download_queue_persist]
_DL_QUEUE_PERSIST_LOCK = threading.Lock()
_DL_QUEUE_PERSIST_FILE = os.path.join(SRT_TEMP_DIR, 'download_queue.pid')

# [TAG: #@_save_download_queue_persist]

def _save_download_queue_persist(queue_list: list):
    """[V171.0] 다운로드 미완료 큐 목록을 암호화하여 download_queue.pid 파일에 원자적(Atomic)으로 저장합니다냥! 🔐💾✨"""
    try:
        with _DL_QUEUE_PERSIST_LOCK:
            if not queue_list:
                if os.path.exists(_DL_QUEUE_PERSIST_FILE):
                    try: os.remove(_DL_QUEUE_PERSIST_FILE)
                    except Exception: pass
                return
            
            enc_str = _encrypt_json_data({"queue": queue_list, "updated_at": time.time()})
            tmp_file = f"{_DL_QUEUE_PERSIST_FILE}.tmp"
            os.makedirs(os.path.dirname(_DL_QUEUE_PERSIST_FILE), exist_ok=True)
            with open(tmp_file, 'w', encoding='utf-8') as f:
                f.write(enc_str)
            os.replace(tmp_file, _DL_QUEUE_PERSIST_FILE)
    except Exception as e:
        _log_to_file(f"⚠️ [DL Queue Persist Save Error] {e}")

# [TAG: #@_load_download_queue_persist]

def _load_download_queue_persist() -> list:
    """[V171.0] 암호화된 download_queue.pid 파일에서 미완료 다운로드 큐를 복호화하여 로드합니다냥! 🔓📥✨"""
    try:
        with _DL_QUEUE_PERSIST_LOCK:
            if not os.path.exists(_DL_QUEUE_PERSIST_FILE):
                return []
            with open(_DL_QUEUE_PERSIST_FILE, 'r', encoding='utf-8') as f:
                enc_str = f.read()
            data = _decrypt_json_data(enc_str)
            if isinstance(data, dict) and 'queue' in data and isinstance(data['queue'], list):
                return data['queue']
            elif isinstance(data, list):
                return data
            return []
    except Exception as e:
        _log_to_file(f"⚠️ [DL Queue Persist Load Error] {e}")
        return []

# [TAG: #@_add_to_download_queue_persist]

def _add_to_download_queue_persist(items: list):
    """[V171.0] 다운로드 항목들을 큐 파일에 등록/추가합니다냥! ➕📥"""
    try:
        curr_queue = _load_download_queue_persist()
        existing_urls = {x.get('url') for x in curr_queue if isinstance(x, dict) and x.get('url')}
        existing_ids = {x.get('id') for x in curr_queue if isinstance(x, dict) and x.get('id')}
        added = False
        for item in items:
            if isinstance(item, dict):
                u = item.get('url')
                v_id = item.get('id')
                if not u and not v_id:
                    continue
                if (u and u in existing_urls) or (v_id and v_id in existing_ids):
                    continue
                curr_queue.append(item)
                if u:
                    existing_urls.add(u)
                if v_id:
                    existing_ids.add(v_id)
                added = True
        if added:
            _save_download_queue_persist(curr_queue)
    except Exception as e:
        _log_to_file(f"⚠️ [DL Queue Add Error] {e}")

# [TAG: #@_remove_from_download_queue_persist]

def _remove_from_download_queue_persist(url: str):
    """[V171.0] 완료되거나 스킵된 다운로드 URL/ID 항목을 큐 파일에서 제거하고 갱신합니다냥! ➖🧹"""
    try:
        if not url:
            return
        curr_queue = _load_download_queue_persist()
        new_queue = [
            x for x in curr_queue
            if isinstance(x, dict) and x.get('url') != url and x.get('id') != url
        ]
        if len(new_queue) != len(curr_queue):
            _save_download_queue_persist(new_queue)
    except Exception as e:
        _log_to_file(f"⚠️ [DL Queue Remove Error] {e}")

# [TAG: #@_check_and_resume_download_queue]

def _check_and_resume_download_queue(s_ref):
    """[V171.0] 앱 재시작 시, 남은 암호화 큐가 있고 메인 앱(서브 앱 제외)이며 토글이 ON이면 자동으로 백그라운드 다운로드를 마저 진행합니다냥! 🔄📥🚀"""
    try:
        # [V171.1] 보조 인스턴스(--secondary) 실행 시 다운로드 이어서 받기 스킵 (중복 다운로드 및 오작동 차단 🛡️✨)
        if '--secondary' in sys.argv or globals().get('IS_SECONDARY_INSTANCE', False):
            _log_to_file("🛡️ [Resume DL] 보조 인스턴스(--secondary) 실행이 감지되어 다운로드 이어서 받기를 스킵합니다냥!")
            return
        resume_enabled = s_ref.data.get('s_m_b_d_resume', True)
        if not resume_enabled:
            return

        pending_items = _load_download_queue_persist()
        if not pending_items:
            return

        globals()['_G_STEALTH_BG_CANCEL_REQUESTED'] = False # [V176.7] 부팅 시 취소 플래그 안전 초기화 🛡️✨
        _log_to_file(f"🔄 [Resume DL] 앱 재시작 감지! 남은 미완료 다운로드 {len(pending_items)}개를 마저 백그라운드에서 다운로드합니다냥! 🚀")

        # [TAG: #@_boot_resume_worker]

        def _boot_resume_worker():
            global _G_STEALTH_BG_TASKS, _G_STEALTH_BG_LOCK
            if '_G_STEALTH_BG_TASKS' not in globals():
                globals()['_G_STEALTH_BG_TASKS'] = []
                globals()['_G_STEALTH_BG_LOCK'] = threading.Lock()

            t_cnt = len(pending_items)
            import queue
            task_q = queue.Queue()
            for idx, target in enumerate(pending_items, 1):
                task_q.put((idx, target))

            def _resume_sub():
                while not task_q.empty():
                    if globals().get('_G_STEALTH_BG_CANCEL_REQUESTED', False):
                        with task_q.mutex:
                            task_q.queue.clear()
                        break
                    try:
                        idx, target = task_q.get_nowait()
                    except queue.Empty:
                        break

                    url = target.get('url')
                    slug = target.get('id')
                    title = target.get('title', 'Unknown Title')
                    if not url and slug:
                        url = f"https://deovr.com/{slug}"
                        target['url'] = url
                    if not url:
                        task_q.task_done()
                        continue

                    _task_status = {
                        'cancel': False,
                        'v_url': url,
                        'id': slug,
                        'title': title,
                        'index': idx,
                        'total': t_cnt,
                        'is_deovr': (target.get('type') == 'deovr')
                    }
                    with globals()['_G_STEALTH_BG_LOCK']:
                        globals()['_G_STEALTH_BG_TASKS'].append(_task_status)

                    try:
                        if target.get('type') == 'deovr':
                            if '_execute_deovr_download_process' in globals():
                                target_res = target.get('preferred_res') or '3840p'
                                target_path = target.get('saved_path') or (s_ref.data.get('deovr_download_path') if (s_ref and hasattr(s_ref, 'data')) else None) or (s_ref.get_valid_path("download_path") if (s_ref and hasattr(s_ref, 'get_valid_path')) else None)
                                globals()['_execute_deovr_download_process']([target], target_res, target_path or os.getcwd(), s_ref, is_bg_mode=True, task_status_ref=_task_status)
                            else:
                                _log_to_file(f"⚠️ [Resume DL DeoVR] _execute_deovr_download_process 함수 미발견: {title}")
                        else:
                            res = _s_m_download_video(url, title, s_ref, _task_status=_task_status, index=idx, total=t_cnt)
                    except Exception as _e:
                        _log_to_file(f"❌ [Resume DL Boot Error] {title}: {_e}")
                    finally:
                        with globals()['_G_STEALTH_BG_LOCK']:
                            if _task_status in globals()['_G_STEALTH_BG_TASKS']:
                                globals()['_G_STEALTH_BG_TASKS'].remove(_task_status)
                        _remove_from_download_queue_persist(url)
                        if slug:
                            _remove_from_download_queue_persist(slug)
                        task_q.task_done()
                        try: _schedule_ytdl_cache_cleanup(s_ref)
                        except Exception: pass

                    # [V176.7] 개별 작업 타임아웃/실패는 해당 영상만 큐에서 지워지고 계속 진행되어야 함!
                    # 전체 대기 큐 비우기 및 작업 중단은 오직 사용자가 7번으로 명시적 전체 취소를 요청했을 때만 가동 🛡️✨
                    if globals().get('_G_STEALTH_BG_CANCEL_REQUESTED', False):
                        with task_q.mutex:
                            task_q.queue.clear()
                        try:
                            _save_download_queue_persist([])
                        except Exception: pass
                        _log_to_file("🛑 [Resume DL Boot] 사용자에 의해 백그라운드 다운로드가 전체 취소되어 대기 큐를 모두 비웠습니다냥!")
                        break

            # [V192.2] 설정된 동시 다운로드 영상 수(s_m_dl_concurrency) 동적 반영 🚀
            _concurrency = 4
            try:
                target_s = s_ref if s_ref is not None else globals().get('settings')
                if target_s:
                    if hasattr(target_s, 'data') and isinstance(target_s.data, dict):
                        _concurrency = int(target_s.data.get('s_m_dl_concurrency', 4))
                    elif hasattr(target_s, 'get'):
                        _concurrency = int(target_s.get('s_m_dl_concurrency', 4))
                    elif isinstance(target_s, dict):
                        _concurrency = int(target_s.get('s_m_dl_concurrency', 4))
            except Exception:
                _concurrency = 4
            _concurrency = max(1, min(16, _concurrency))
            worker_count = max(1, min(_concurrency, t_cnt))
            threads = []
            for _ in range(worker_count):
                th = threading.Thread(target=_resume_sub, daemon=True)
                th.start()
                threads.append(th)
            for th in threads:
                th.join()


        t = threading.Thread(target=_boot_resume_worker, daemon=True)
        t.start()
    except Exception as e:
        _log_to_file(f"⚠️ [Resume DL Boot Hook Error] {e}")

# [TAG: #@_save_gdrive_cache]
def _save_gdrive_cache():
    """[V131.9] 현재 메모리에 있는 GDrive 캐시를 디스크(JSON)에 굽습니다냥! 💾✨"""
    try:
        _serializable = {}
        for (acc, rp), data in _GDRIVE_CACHE.items():
            _key = f"{acc}|{rp}" # 튜플은 JSON 키가 될 수 없으므로 구분자 결합 🧠
            _serializable[_key] = {
                "data": data,
                "time": _GDRIVE_CACHE_TIME.get((acc, rp), time.time())
            }

        _dir = os.path.dirname(_GDRIVE_CACHE_FILE)
        if not os.path.exists(_dir): os.makedirs(_dir, exist_ok=True)

        # [V150.1] 암호화 적용 및 원자적 교체 🛡️
        enc_content = _encrypt_json_data(_serializable)
        tmp_path = _GDRIVE_CACHE_FILE + f".tmp_{os.getpid()}"
        try:
            with open(tmp_path, 'w', encoding='utf-8') as f:
                f.write(enc_content)
            os.replace(tmp_path, _GDRIVE_CACHE_FILE) # 안전하게 교체! ✨
        except Exception as e:
            if os.path.exists(tmp_path): os.remove(tmp_path)
            raise e
    except Exception as e:
        _log_to_file(f" [GDrive] Cache Save Fail: {e}")

# [TAG: #@_load_gdrive_cache]
def _load_gdrive_cache():
    """[V131.9] 디스크에 저장된 GDrive 캐시를 메모리로 불러옵니다냥! 📖💡"""
    global _GDRIVE_CACHE, _GDRIVE_CACHE_TIME, _GDRIVE_CACHE_PERSISTED
    if _GDRIVE_CACHE_PERSISTED: return
    try:
        if os.path.exists(_GDRIVE_CACHE_FILE):
            with open(_GDRIVE_CACHE_FILE, 'r', encoding='utf-8') as f:
                _content = f.read()
            # [V150.1] 복호화 적용 🔓
            _raw = _decrypt_json_data(_content)

            for _key, _val in _raw.items():
                if "|" in _key:
                    acc, rp = _key.split("|", 1)
                    _GDRIVE_CACHE[(acc, rp)] = _val["data"]
                    _GDRIVE_CACHE_TIME[(acc, rp)] = _val["time"]
            _log_to_file(f" [GDrive] Persistent Cache Loaded: {len(_GDRIVE_CACHE)} items")
    except Exception as e:
        _log_to_file(f" [GDrive] Cache Load Fail: {e}")
    finally:
        _GDRIVE_CACHE_PERSISTED = True

# [TAG: #@_optimistic_remove_gdrive_cache]
def _optimistic_remove_gdrive_cache(targets):
    """[V154.99] 백그라운드 삭제 전 UI 즉시 반영을 위해 메모리/디스크 캐시에서 타겟을 선제적 제거 ⚡✨"""
    global _GDRIVE_CACHE, _GDRIVE_CACHE_PERSISTED
    if not _GDRIVE_CACHE_PERSISTED:
        _load_gdrive_cache()
    changed = False
    for src in targets:
        if not _is_gdrive_path(src): continue
        _a, _rp = _gdrive_parse_path(src)
        if not _a or _rp is None: continue
        _clean = _rp.strip('/')
        _parts = _clean.split('/')
        _parent = '/'.join(_parts[:-1])
        _nm = _parts[-1]
        is_dir = src.endswith('/') or src.endswith('\\')
        
        keys_to_check = [
            (_a, _parent),
            (_a, _parent.strip('/')),
            (_a, _parent + '/' if _parent else '')
        ]
        for k in keys_to_check:
            if k in _GDRIVE_CACHE:
                dirs, files = _GDRIVE_CACHE[k]
                if is_dir:
                    new_dirs = [d for d in dirs if d.get('Name', d.get('name', '')).strip() != _nm.strip()]
                    if len(new_dirs) != len(dirs):
                        _GDRIVE_CACHE[k] = (new_dirs, files)
                        changed = True
                else:
                    new_files = [f for f in files if f.get('Name', f.get('name', '')).strip() != _nm.strip()]
                    if len(new_files) != len(files):
                        _GDRIVE_CACHE[k] = (dirs, new_files)
                        changed = True
    if changed:
        _save_gdrive_cache()

# [TAG: #@_filter_deleting_items]
def _filter_deleting_items(account, rpath, item_tuple):
    """[V154.99] 백그라운드 삭제 중인 항목이 원격 새로고침 등으로 화면에 다시 나타나는 유령 현상 방지 👻🛡️"""
    global _GDRIVE_DELETING_PATHS
    if not _GDRIVE_DELETING_PATHS or not item_tuple:
        return item_tuple
    dirs, files = item_tuple
    _clean_rpath = (rpath or '').strip('/')
    def _is_del(name, is_dir):
        vpath = f"gdrive://{account}/{(_clean_rpath + '/' + name).lstrip('/')}"
        if is_dir:
            return vpath in _GDRIVE_DELETING_PATHS or (vpath + '/') in _GDRIVE_DELETING_PATHS
        return vpath in _GDRIVE_DELETING_PATHS
    filtered_dirs = [d for d in dirs if not _is_del(d.get('Name', d.get('name', '')), True)]
    filtered_files = [f for f in files if not _is_del(f.get('Name', f.get('name', '')), False)]
    return filtered_dirs, filtered_files


class NeonTranscription:
    """[V89.11] 로컬 Whisper 추출 중 실시간 전사 내용을 5줄 네온사인 효과로 출력하는 클래스 🌈✨
    (사용자님 요청: 3줄 -> 5줄 확장 및 부드러운 스크롤 애니메이션 적용)
    """
    # [TAG: #@__init___4]
    def __init__(self, capacity=5, offset_lines=2):
        self.queue = []
        self.capacity = capacity
        self.offset_lines = offset_lines # status 라인과의 간격
        self.colors = [
            "\033[96m",       # Neon Cyan
            "\033[38;5;201m", # Neon Pink
            "\033[95m",       # Neon Magenta
            "\033[93m",       # Neon Yellow
            "\033[94m",       # Neon Blue
            "\033[92m",       # Neon Green
            "\033[38;5;214m", # Neon Orange
            "\033[38;5;86m"   # Neon Mint
        ]
        self.color_idx = 0
        self._lock = threading.Lock()

    # [TAG: #@update]
    def update(self, text):
        if not text or not text.strip(): return
        with self._lock:
            import time as _time
            term_cols = shutil.get_terminal_size().columns
            # UI 깨짐 방지를 위해 최대 길이를 터미널 너비의 80% 정도로 제한
            max_len = max(20, term_cols - 15)

            clean_text = text.strip().replace("\r\n", " ")
            if len(clean_text) > max_len:
                clean_text = clean_text[:max_len-3] + "..."

            # [애니메이션 Step 1] 기존 내용 위로 밀어올리기 (Scroll Up Effect) 🎢
            # 한 줄이 추가될 때, 큐가 꽉 찼다면 기존 정보를 한 칸씩 미리 올려서 그림
            target_queue = list(self.queue)
            target_queue.append(clean_text)
            if len(target_queue) > self.capacity:
                target_queue.pop(0)

            # 현재 위치 저장 및 네온 영역 시작점으로 이동
            sys.stdout.write(f"\033[{self.offset_lines}B")

            # 중간 단계 출력 (부드러운 전환을 위해 빈 자리나 이동된 자리 표시)
            for i in range(self.capacity):
                # 마지막 줄(새로 나타날 줄)은 일단 비워두고 나머지만 한 줄씩 위로 그림
                curr_content = target_queue[i] if i < len(target_queue) - 1 else ""
                color = self.colors[(self.color_idx + i) % len(self.colors)]
                sys.stdout.write(f"\r\033[K   {color}⌁ {curr_content}\033[0m\r\n")

            # 잠시 대기 (스크롤되는 느낌을 주기 위한 미세 딜레이)
            sys.stdout.flush()
            _time.sleep(0.03)

            # [애니메이션 Step 2] 실제 큐 업데이트 및 새로운 문장 타이핑 출력 ⌨️
            self.queue = target_queue

            # 다시 네온 시작점으로 이동 (5줄 위 + offset 2줄만큼 위로)
            sys.stdout.write(f"\033[{self.capacity + self.offset_lines}A\033[{self.offset_lines}B")

            for i in range(self.capacity):
                content = self.queue[i] if i < len(self.queue) else ""
                color = self.colors[(self.color_idx + i) % len(self.colors)]

                # 마지막 새로 추가된 줄만 타이핑 효과 적용
                if i == len(self.queue) - 1 and content:
                    # 타이핑 효과 (문자가 네온사인처럼 생성되는 느낌)
                    sys.stdout.write(f"\r\033[K   {color}⌁ ")
                    for char in content:
                        sys.stdout.write(char)
                        sys.stdout.flush()
                        _time.sleep(0.005) # 매우 빠른 타이핑
                    sys.stdout.write("\033[0m\r\n")
                else:
                    sys.stdout.write(f"\r\033[K   {color}⌁ {content}\033[0m\r\n")

            # 색상 인덱스 순환
            self.color_idx = (self.color_idx + 1) % len(self.colors)

            # 커서 원위치 (기존 status 위치 복구)
            sys.stdout.write(f"\033[{self.capacity + self.offset_lines}A")
            sys.stdout.flush()

    # [TAG: #@clear]
    def clear(self):
        """작업 종료 시 출력했던 네온 라인들을 지웁니다. 🧹"""
        with self._lock:
            sys.stdout.write(f"\033[{self.capacity + self.offset_lines}A")
            sys.stdout.flush()


