# [V82.9] Ollama 글로벌 라이프사이클 관리 함수 (통합 및 재사용) 🛠️🔄
# [TAG: #@_ensure_ollama_server]
def _ensure_ollama_server() -> bool:
    """Ollama 서버가 켜져 있는지 확인하고, 꺼져 있으면 자동으로 깨웁니다."""
    # [TAG: #@__is_port_in_use]
    def __is_port_in_use(port):
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                return s.connect_ex(('127.0.0.1', port)) == 0
        except: return False

    if __is_port_in_use(11434): return True

    # 윈도우 표준 경로들 탐색
    appdata = os.environ.get("LOCALAPPDATA", "")
    paths = [
        os.path.join(appdata, "Ollama", "ollama.exe"),
        os.path.join(os.environ.get('PROGRAMFILES', r"C:\Program Files"), r"Ollama\ollama.exe"),
        os.path.join(os.environ.get('PROGRAMFILES(X86)', r"C:\Program Files (x86)"), r"Ollama\ollama.exe")
    ]
    for p in paths:
        if os.path.exists(p):
            print(f"\r\n 🚀 {C.SKY}[Ollama 기동]{C.RESET} 서버를 깨우는 중이야냥! 잠시만 기다려줘... ✨")
            try:
                subprocess.Popen("start /B ollama serve", shell=True)
            except:
                return False

            for _ in range(10): # 최대 10초 대기
                time.sleep(1)
                if __is_port_in_use(11434): return True
            return False # 10초 지나도 안 켜지면 실패 반환
    return False # 설치 경로에 없으면 즉시 종료 (10초 대기 방지) 🚀

# [TAG: #@_find_ollama_model_tag]
def _find_ollama_model_tag(base_name: str) -> str:
    """모델 이름(예: gemma4)이 주어지면, 리스트나 파일시스템에서 실제 태그(gemma4:local 등)를 찾아냅니다."""
    base_name = base_name.replace("local_ollama_", "")
    if ":" in base_name: return base_name # 이미 태그가 있으면 그대로 사용

    # 1. 'ollama list' 우선 검색
    try:
        output = subprocess.check_output("ollama list", shell=True).decode()
        for line in output.splitlines()[1:]:
            parts = line.split()
            if not parts: continue
            full_name = parts[0]
            if full_name.startswith(base_name + ":") or full_name == base_name:
                return full_name
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")

    # 2. 파일 시스템 직접 탐색 (Registry Fallback) 🔍📁
    try:
        ollama_path = os.path.expanduser("~/.ollama/models/manifests/registry.ollama.ai/library")
        model_dir = os.path.join(ollama_path, base_name)
        if os.path.exists(model_dir):
            tags = [f for f in os.listdir(model_dir) if os.path.isfile(os.path.join(model_dir, f))]
            if "local" in tags: return f"{base_name}:local"
            if "latest" in tags: return f"{base_name}:latest"
            if tags: return f"{base_name}:{tags[0]}" # 첫 번째 태그라도 사용
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")

    return base_name # 못 찾으면 일단 원래 이름 반환

