def get_srt_temp_path(v_path: str, suffix: str) -> str:
    """[V147.167] 동영상 경로에 기반한 고유한 임시 파일 경로 생성 (srt/temp 폴더 내) 🧬📌
    v_path가 없으면 suffix만 붙여서 반환냥!
    """
    if not v_path: return os.path.join(SRT_TEMP_DIR, f"unknown_{int(time.time())}{suffix}")

    # [V147.168] 사용자님 요청: 확장자 유무와 상관없이 동일한 비디오면 동일한 해시를 생성 🛡️🧬
    # (video.mp4 와 video 가 같은 해시를 가지도록 splitext 처리 후 abspath 취함)
    clean_path = os.path.splitext(os.path.abspath(v_path))[0]
    path_hash = hashlib.md5(clean_path.encode()).hexdigest()[:8]
    fn_no_ext = os.path.basename(clean_path)
    # 결과 예: video_a1b2c3d4.processing.lock
    return os.path.join(SRT_TEMP_DIR, f"{fn_no_ext}_{path_hash}{suffix}")


