# [V192.2] 스텔스 다운로드 동적 세마포어 클래스 & 동기화 헬퍼 (miss.py 이식 & 동적 확장) 📥🔐
class _DynamicDownloadSemaphore:
    def __init__(self, initial=4):
        self._cond = threading.Condition(threading.Lock())
        self._capacity = max(1, min(16, int(initial)))
        self._active = 0

    def set_capacity(self, new_cap):
        with self._cond:
            self._capacity = max(1, min(16, int(new_cap)))
            self._cond.notify_all()

    def get_capacity(self):
        with self._cond:
            return self._capacity

    def acquire(self, blocking=True, timeout=None):
        with self._cond:
            if not blocking:
                if self._active < self._capacity:
                    self._active += 1
                    return True
                return False
            end_time = None if timeout is None else (time.time() + timeout)
            while self._active >= self._capacity:
                if timeout is not None:
                    remaining = end_time - time.time()
                    if remaining <= 0:
                        return False
                    self._cond.wait(remaining)
                else:
                    self._cond.wait()
            self._active += 1
            return True

    def release(self):
        with self._cond:
            if self._active > 0:
                self._active -= 1
            self._cond.notify_all()

    def __enter__(self):
        self.acquire()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.release()

_s_m_dl_semaphore = _DynamicDownloadSemaphore(4)

def _sync_s_m_dl_semaphore(new_limit=None):
    """설정된 동시 다운로드 수(s_m_dl_concurrency)에 맞춰 세마포어 크기 동기화 🔄"""
    global _s_m_dl_semaphore, settings
    if new_limit is None:
        try:
            if 'settings' in globals() and settings:
                if hasattr(settings, 'data') and isinstance(settings.data, dict):
                    new_limit = settings.data.get('s_m_dl_concurrency', 4)
                elif hasattr(settings, 'get'):
                    new_limit = settings.get('s_m_dl_concurrency', 4)
                elif isinstance(settings, dict):
                    new_limit = settings.get('s_m_dl_concurrency', 4)
                else:
                    new_limit = 4
            else:
                new_limit = 4
        except Exception:
            new_limit = 4
    try:
        new_limit = max(1, min(16, int(new_limit)))
        _s_m_dl_semaphore.set_capacity(new_limit)
    except Exception:
        pass
    return _s_m_dl_semaphore


# [V8.10] 최근 선택 및 히스토리 관리 (전역화) ✨
# [TAG: #@_save_recent_selection]
def _save_recent_selection(selection, s_param=None, is_last=True):
    """[V8.10] 선택된 파일 리스트를 히스토리에 최상단(index 0)으로 저장 💾
    is_last=True인 경우 앱의 '가장 최근 선택된 그룹(last_selection)'을 업데이트합니다.
    """
    global settings
    s = s_param if s_param else settings
    if not s or not selection: return

    recent_history = s.data.get('recent_files_history', [])
    for path in selection:
        if not path: continue
        try:
            path_abs = os.path.abspath(path)
            # [V128.8] AI냥 요청: 플레이리스트 파일(.dpl, .m3u, .m3u8)은 히스토리에서 제외 🚫📄
            if path_abs.lower().endswith(('.dpl', '.m3u', '.m3u8')): continue

            # [V8.11] 폴더(디렉토리)는 최근 파일 목록에 등록하지 않도록 차단 🕵️‍♂️🛑📁
            if not os.path.isfile(path_abs): continue
        except: continue

        if path_abs in recent_history: recent_history.remove(path_abs)
        recent_history.insert(0, path_abs) # 0번 인덱스(최상단)에 삽입!

    if is_last:
        s.data['last_selection'] = selection
    s.data['recent_files_history'] = recent_history[:25] # 최대 25개 유지
    s.save()

# [V22.12] 경로 정규화 및 히스토리 PK 산출 공통 헬퍼 함수 🧼🔑✨
def _norm_p_safe(p):
    """경로 정규화 전역 안전 헬퍼 🧼✨"""
    if not p or not isinstance(p, str): return ""
    if p.startswith(('http://', 'https://', 'gdrive://')): return p
    try: return os.path.normpath(os.path.abspath(p)).lower()
    except: return p.lower()

def _get_history_pk(view_mode, current_dir_path, settings_obj=None):
    """현재 컨텍스트의 히스토리 PK(Primary Key)를 물리 폴더/가상 폴더 기준에 맞추어 산출냥! 🔑✨
    유튜브동영상(YOUTUBE_FOLDER)은 가상폴더이면서 동시에 물리폴더이므로,
    물리폴더(download_path)가 존재할 경우 항상 물리폴더 경로를 기준으로 통일하여 짬뽕/오작동 방지냥! 🛡️
    """
    s = settings_obj if settings_obj else globals().get('settings')
    _yt_path = s.get_valid_path("download_path") if (s and hasattr(s, 'get_valid_path')) else (s.data.get("download_path") if (s and hasattr(s, 'data')) else None)
    _yt_norm = _norm_p_safe(_yt_path) if _yt_path else None
    _cur_norm = _norm_p_safe(current_dir_path) if current_dir_path else None

    # [V22.12] 유튜브동영상(YOUTUBE_FOLDER)은 가상폴더이자 물리폴더(download_path)이므로 물리폴더 기준 통합냥! 🎬📁
    if view_mode == 'YOUTUBE_FOLDER' or (_yt_norm and _cur_norm == _yt_norm):
        return _yt_norm if _yt_norm else 'YOUTUBE_FOLDER'
    if view_mode:
        return view_mode
    return _cur_norm

# [V147.170] AI냥 요청: 하이라이팅(GOLD/ORANGE) 저장 로직 전역화 및 시점 변경 ✨🎨
def _save_last_played_ctx(target_path, settings_obj=None, pk=None, is_starting=False, quiet=False):
    """메뉴별/폴더별 마지막 작업 파일을 기록냥! (금색/동색 2단계 강조 지원) 💾✨
    is_starting=True 면 현재 재생 중으로만 표시하고 실제 금색 변경은 지연시킵니다. ✨
    """
    if not target_path: return
    # [V147.170] AI냥 요청: 폴더가 히스토리에 박히는 현상 원천 차단! 🛡️🛑
    # [V147.173] 유튜브 URL, 구글 드라이브 등 파일이 아닌 경우도 히스토리 기록 허용냥! 🌍✨
    is_url = target_path.startswith(('http://', 'https://', 'gdrive://'))
    if not is_url and not os.path.isfile(target_path): return

    global settings, _g_potplayer_current_path, _g_potplayer_current_pk
    s = settings_obj if settings_obj else settings
    if not s: return
    try:
        # [V147.173] URL인 경우 abspath/normpath 생략하여 원본 유지
        ta = target_path if is_url else os.path.normpath(os.path.abspath(target_path))

        # [V148.0] AI냥 요청: 재생 시작 시 '최근 파일' 히스토리에도 자동 등록하여 정렬 유지! 🕒🚀✨
        if not is_url: _save_recent_selection([ta], s_param=s, is_last=False)

        # pk가 없으면 파일의 절대 경로 폴더를 키로 사용
        if not pk:
            if is_url: pk = "URL_HISTORY" # [신규] URL 전용 히스토리 키
            else: pk = os.path.normpath(os.path.abspath(os.path.dirname(target_path))).lower()
        # [V147.175] AI냥 요청: 재생을 시작할 때는 '현재 재생 중'으로만 표시하고, 실제 황금색 변경은 종료 시까지 지연! 🕰️🎬✨
        if is_starting:
            # [V22.10] AI냥 요청: DPL 모두재생 시 최초 시작 파일에만 트로피 장착! 🏆✨
            # (일반 단일 재생은 트로피 대상이 아님 — DPL 전용 명예! 🎖️)
            # 순수 메모리 휘발성 — 환경파일에 절대 저장하지 않는다냥! 🚫💾
            global _G_PLAY_HISTORY
            if globals().get('_g_potplayer_is_dpl_mode', False):
                _pk_key = os.path.normpath(pk).lower() if pk else ""
                if _pk_key and _pk_key not in _G_PLAY_HISTORY.get('trophies', {}):
                    # 최초 시작 파일에만 부여 (이미 트로피가 있으면 덮어쓰지 않음!)
                    _G_PLAY_HISTORY.setdefault('trophies', {})[_pk_key] = ta
                    _log_to_file(f" 🏆 [Trophy Set] DPL start file for {_pk_key}: {os.path.basename(ta)}")

            # [지능형 전환] 만약 이미 다른 파일이 재생 중이었다면, 그 파일은 이제 '끝난 것'으로 간주하여 기록냥!
            if _g_potplayer_current_path and _g_potplayer_current_path != ta:
                # [V21.1] 재귀 호출 시에는 중복 저장을 방지하기 위해 quiet=True로 처리냥! (병목 감소)
                _save_last_played_ctx(_g_potplayer_current_path, settings_obj=s, pk=_g_potplayer_current_pk, is_starting=False, quiet=True)

            _g_potplayer_current_path = ta
            _g_potplayer_current_pk = pk
            _log_to_file(f" 🎬 [Playback Start] Current set to {ta} (Gold update deferred)")
            return # 시작 시점에는 여기서 종료!

        # [실제 기록 업데이트 로직] (재생 종료 또는 다른 파일 시작 시 호출됨)
        if 'last_played_per_menu' not in s.data: s.data['last_played_per_menu'] = {}
        lh = s.data['last_played_per_menu'].get(pk, [])

        # [V147.170] 기존 기록에서 제거 후 최상단 삽입 (Gold -> Orange -> Brown 밀어내기! 🔄✨)
        if ta in lh: lh.remove(ta)
        lh.insert(0, ta)
        s.data['last_played_per_menu'][pk] = lh[:3] # 금색(0), 주황(1), 갈색(2) 세 개 유지냥! ✨

        # [V147.172] AI냥 요청: 모든 메뉴에서 일률적으로 강조를 위해 '전역 마지막 재생 파일' 리스트(3단계) 기록냥! 🏆🌍
        _gg_raw = s.data.get('last_played_global', [])
        if _gg_raw is None: _gg = []
        elif isinstance(_gg_raw, str): _gg = [_gg_raw]
        elif isinstance(_gg_raw, list): _gg = _gg_raw
        else: _gg = [] # 예외 케이스 방어 🛡️

        if ta in _gg: _gg.remove(ta)
        _gg.insert(0, ta)
        s.data['last_played_global'] = _gg[:3]

        # 만약 저장하려는 파일이 현재 재생 중인 파일이었다면, 이제 감시가 끝난 것이므로 초기화냥!
        if _g_potplayer_current_path == ta:
            _g_potplayer_current_path = None
            _g_potplayer_current_pk = None

        s.save(quiet=quiet)
        if not quiet:
            _log_to_file(f" 🏆 [Gold Updated] {ta} is now the Last Played file.")
        
        # [V19.8.3] AI냥 요청: 금은동 메달이 갱신될 때 ✨ 아이콘 장부도 함께 최신화냥! 🛡️✨
        globals()['_G_EXPLORER_NEW_ITEMS_DIRTY'] = True 
    except Exception as e:
        _log_to_file(f" ❌ [_save_last_played_ctx] Error: {e}")
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")

# [TAG: #@_save_last_dir]
def _save_last_dir(path, s_param=None):
    """[V121.7] 마지막 폴더 위치를 전역 설정(settings.json)에 안전하게 저장한다냥! 📁💾"""
    global settings
    s = s_param if s_param else settings
    if not s: return
    try:
        d = path if os.path.isdir(path) else os.path.dirname(path)
        if os.path.isdir(d):
            s.data['last_dir'] = d
            s.save()
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")

# [TAG: #@_read_dpl]
def _read_dpl(dpl_path):
    """[V164.1] DPL 플레이리스트 인코딩(utf-16, utf-8, cp949) 공통 리더 헬퍼 📖✨"""
    if not dpl_path or not os.path.exists(dpl_path): return ""
    for enc in ["utf-16", "utf-8", "cp949"]:
        try:
            with open(dpl_path, "r", encoding=enc, errors="ignore") as f:
                content = f.read()
            if "DAUMPLAYLIST" in content or "playname" in content or "*file*" in content:
                return content
        except Exception:
            continue
    return ""

# [TAG: #@_add_potplayer_recent]
def _add_potplayer_recent(s_param=None, find_title=None, dpl_paths=None, skip_save=True):
    """[V8.10] AI냥의 팟플 스캔 알고리즘 🕵️‍♂️✨
    [V8.12] 120초(2분) 이내의 최신 기록인 경우 경로를 반환하여 자동 선택 가능하도록 확장! 🕒🎯
    [V121.7] find_title 이 있으면 DPL 본문을 스캔하여 창 제목과 일치하는 전체 경로를 역추적한다냥! 🛸🛰️
    [V121.8] dpl_paths(메모리 리스트)가 제공되면 파일 시스템보다 먼저 대조한다냥! 📂✨
    """
    global settings, _G_LAST_POTPLAYER_RESOLVED_PATH
    s = s_param if s_param else settings
    if not s: return None, 0

    try:
        now = time.time()

        # [비누님 요청 ⚡ STEP 1] CPU 2차 최적화: 동일 제목 & DPL mtime 미변동 시 0.0001초 초고속 반환!
        appdata_tmp = os.environ.get("APPDATA", "")
        dpl_main = os.path.join(appdata_tmp, r"PotPlayer64\Playlist\PotPlayer64.dpl")
        curr_dpl_mtime = os.path.getmtime(dpl_main) if os.path.exists(dpl_main) else 0

        _last_title = globals().get('_g_last_scan_title')
        _last_path = globals().get('_g_last_scan_path')
        _last_mtime = globals().get('_g_last_scan_mtime', 0)

        if find_title and find_title == _last_title and curr_dpl_mtime == _last_mtime and _last_path and os.path.exists(_last_path):
            return _last_path, curr_dpl_mtime

        # [V134.5] 제목 정규화 유틸 함수 고도화 🛠️🚀 (특수 제목 형식 완벽 대응)
        # [TAG: #@_pure_norm]
        def _pure_norm(text):
            if not text: return ""
            t = text
            # 1. 접미어 제거 (" - 팟플...", " - PotPlayer...", " - 팟플레이어", " - BINU_KOREA_SRT_")
            t = re.sub(r'\s*-\s*(?:팟플[^\s]*|PotPlayer[^\s]*|BINU[^\s]*)\s*$', '', t, flags=re.IGNORECASE)
            for suffix in [" - PotPlayer", " - 팟플레이어", " - BINU_KOREA_SRT_"]:
                if suffix in t:
                    t = t.split(suffix)[0]

            # 2. 접두어 제거 (🎨 [Playlist], 🔍[✅SYNC], [1/10] 등)
            t = re.sub(r'^🔍\[.*?\]\s*', '', t) # [✅SYNC] 등 상태 아이콘 제거
            t = re.sub(r'^\[.*?\]\s*', '', t)  # [PlaylistName] 또는 [1/10] 등 대괄호 접두어 제거

            # [V142.72] AI냥 요청: 팟플 제목창의 '56. ' 같은 순번 인덱스 제거 로직 추가 🚀✨
            t = re.sub(r'^\d+\.\s*', '', t) # "56. " 등의 인덱스 제거

            # 3. 비알파뉴메릭 특수기호 소각 및 소문자화
            # [V142.72] 일본어, 중국어 등 다국어 지원을 위해 [^a-zA-Z0-9ㄱ-ㅣ가-힣] 대신 \w 사용! 🌏✨
            return re.sub(r'[^\w]', '', t).strip().lower()

        # [V121.8] 메모리 리스트(dpl_paths)가 있고 검색 제목이 있다면 최우선 검색! 🚀💎
        if find_title and dpl_paths:
            norm_target = _pure_norm(find_title)
            if norm_target:
                for p in dpl_paths:
                    if not p: continue
                    fn = os.path.basename(p)
                    # [V134.6] 정확도 향상을 위해 substring 매칭 대신 포함 관계를 더 엄격하게 체크
                    norm_fn = _pure_norm(fn)
                    if norm_target and norm_fn and (norm_target in norm_fn or norm_fn in norm_target):
                        if os.path.exists(p):
                            if not skip_save:
                                if _G_LAST_POTPLAYER_RESOLVED_PATH != p:
                                    _log_to_file(f" 💎 [Memory Sync] Resolved via internal list: {p}")
                                    _G_LAST_POTPLAYER_RESOLVED_PATH = p
                                _save_recent_selection([p], s, is_last=True)
                            globals()['_g_last_scan_title'] = find_title
                            globals()['_g_last_scan_path'] = p
                            globals()['_g_last_scan_mtime'] = time.time()
                            return p, time.time()
        # [V8.10] AppData\Roaming 내 팟플레이어 플레이리스트 경로 후보들 📁
        appdata = os.environ.get("APPDATA", "")
        dpl_candidates = [
            os.path.join(appdata, r"PotPlayer64\Playlist\PotPlayer64.dpl"),
            os.path.join(appdata, r"PotPlayerMini64\Playlist\PotPlayerMini64.dpl"),
            os.path.join(appdata, r"PotPlayer\Playlist\PotPlayer.dpl")
        ]

        for dpl in dpl_candidates:
            if not os.path.exists(dpl): continue

            mtime = os.path.getmtime(dpl)
            # [V121.4] 60분 룰 -> 24시간 룰로 상향하여 장시간 영상 시청 후에도 동기화 보장 ⌚✨
            if now - mtime > 86400: continue

            # [V130.8] 최근파일 기록 초기화 시점 이전에 생성된 팟플 기록은 무시하여 좀비 부활 방지! 🧟‍♂️🚫
            if s and mtime <= s.data.get('history_cleared_at', 0): continue

            # [신규] 초기화 이후 첫 재생 여부 판단을 위한 엄격한 시점 체크 🕒
            _clear_time = s.data.get('history_cleared_at', 0) if s else 0


            cached = globals().get('_g_dpl_content_cache', {}).get(dpl)
            if cached and cached[0] == mtime:
                content, file_lines = cached[1], cached[2]
            else:
                content = _read_dpl(dpl)
                file_lines = re.findall(r"\d+\*file\*([^\r\n]*)", content)
                if '_g_dpl_content_cache' not in globals():
                    globals()['_g_dpl_content_cache'] = {}
                globals()['_g_dpl_content_cache'][dpl] = (mtime, content, file_lines)

            found_path = None

            # [V121.7] 제목 기반 역추적 로직 최우선 가동! 🕵️‍♂️🔭🎯
            if find_title:
                norm_target = _pure_norm(find_title)
                if norm_target:
                    # DPL 파일 라인 역추적
                    for line_path in file_lines:
                        p = line_path.strip().strip('"').strip("'")
                        if not p: continue

                        # 경로 내 파일명과 제목 대조 (매칭 확률 극대화)
                        fn = os.path.basename(p)
                        if norm_target in _pure_norm(fn): # [V128.9] pure_fn 대조 생략 및 최적화
                            if os.path.exists(p):
                                found_path = p
                                if _G_LAST_POTPLAYER_RESOLVED_PATH != found_path:
                                    _log_to_file(f" 🛸 [Super Jump] Title resolved to path: {found_path}")
                                    _G_LAST_POTPLAYER_RESOLVED_PATH = found_path
                                break

                    # [BugFix V1] find_title 역추적 성공 시 즉시 반환 (return 경로 누락 수정) 🛡️✨
                    # 기존 코드는 found_path를 찾고도 if not find_title 블록이 스킵되어 return 없이 루프 탈출 후 None 반환이었음!
                    if found_path:
                        if not skip_save:
                            _save_recent_selection([found_path], s, is_last=True)
                        globals()['_g_last_scan_title'] = find_title
                        globals()['_g_last_scan_path'] = found_path
                        globals()['_g_last_scan_mtime'] = mtime
                        return found_path, mtime

            # [V142.9] AI냥 요청: 역추적 실패 시 DPL 파일 본문에서 강제로 경로를 추출하는 폴백 로직 주석 처리 🚫🛑
            # 이제 실시간 제목 동기화 기반으로만 작동하도록 통일합니다냥!
                if found_path:
                    try:
                        # 팟플레이어 클래스 중 하나라도 윈도우가 있다면 (실행 중이라면)
                        is_running = False
                        for cn in ["PotPlayer64", "PotPlayerMini64", "PotPlayer"]:
                            if ctypes.windll.user32.FindWindowW(cn, None):
                                is_running = True; break

                        if is_running:
                            curr_title = _get_potplayer_title()
                            if curr_title:
                                # [V128.4] 제목이 단순히 'PotPlayer' 뿐이라면 아무것도 재생 안 함 -> 싱크 거부 🧼✨
                                # (Suffix 제거 후에도 PotPlayer라면 재생 중이 아닌 것으로 간주)
                                norm_t = _pure_norm(curr_title)
                                if norm_t in ["potplayer", "potplayermini64", "potplayer64", ""]:
                                    _log_to_file(f" 🧼 [Sync Guard] PotPlayer is idle (Title: {curr_title}). Skipping sync.")
                                    found_path = None
                                else:
                                    # 파일명과 제목 대조
                                    norm_f = _pure_norm(os.path.basename(found_path))
                                    if norm_f not in norm_t and norm_t not in norm_f:
                                        _log_to_file(f" 🛡️ [Sync Guard] Title mismatch! File: {norm_f}, Title: {norm_t}. Sync cancelled.")
                                        found_path = None
                    except Exception as ex:
                        _log_to_file(f" ⚠️ [Sync Guard Error] {ex}")

                # [V61.16] 팟플레이어 기종 학습 (PotPlayer64 vs Mini) 🧠✨
                if found_path:
                    pot_type = "PotPlayer64"
                    if "PotPlayerMini64" in dpl: pot_type = "PotPlayerMini64"
                    elif "PotPlayer" in dpl and "Mini" not in dpl: pot_type = "PotPlayer64"

                    if s:
                        s.data['last_potplayer_type'] = pot_type

                    # [V128.7] AI냥 요청: 감지된 파일을 '가장 위'로 히스토리에 영구 저장 (Value화) 🚀✨
                    if not skip_save and os.path.exists(found_path):
                        _save_recent_selection([found_path], s, is_last=False)

                    # [V8.13] 120초(2분) 이내의 최근 기록인지 판별 (글로벌 덮어쓰기용) 🕒🛡️
                    is_fresh = (now - mtime <= 120)
                    if not skip_save:
                        _save_recent_selection([found_path], s, is_last=is_fresh)

                    # [V128.8] 가상 플리 파일 방지 🛡️📄
                    if found_path.lower().endswith(('.dpl', '.m3u', '.m3u8')):
                        found_path = None

                # [V61.22] 최종 결과 반환
                return found_path, mtime
    except Exception as e:
        print(f"⚠️ [_add_potplayer_recent] {e}")
    return None, 0

# ==============================================================================
# 🏰 [V129.0] 동기화 로직 전용 캡슐화 엔진 (Isolation Zone) 🛡️📡🎯
# (AI냥 요청: 직접 재생과 DPL 재생 로직이 절대 섞이지 않게 가둬버림!)
# ==============================================================================

# [TAG: #@_get_sync_path_dpl]
def _get_sync_path_dpl(s, find_title=None):
    """📡 [DPL 전용] 창 제목과 메모리 플리 리스트 기반 경로 추출"""
    dpl_list = globals().get('_g_potplayer_dpl_paths')
    if not find_title: return None, 0
    # [V142.10] AI냥 요청: dpl_list(메모리)가 없더라도 DPL 파일(디스크)에서 제목 기반 역추적을 수행하도록 조건 완화! 🚀✨
    return _add_potplayer_recent(s, find_title=find_title, dpl_paths=dpl_list)

# [TAG: #@_get_sync_path_direct]
def _get_sync_path_direct(s):
    """🕒 [직접 재생 전용] .dpl 파일 mtime 및 playname 기반 경로 추출"""
    return _add_potplayer_recent(s) # 기본 인자로 호출 (mtime 감지 모드)

# [TAG: #@_find_idx_in_options]
def _find_idx_in_options(options, target_path, exact_path_map=None):
    """🎯 [Navigator] 추출된 경로가 현재 목록(options)의 몇 번째 인덱스인지 탐색"""
    if not target_path or not options: return -1

    # [V134.5] 내비게이터용 정규화 엔진 최신화 🕵️‍♂️✨ (DPL 접두어 및 사용자 커스텀 접미어 완벽 제거)
    ptrn_suffix = re.compile(r'\s*-\s*(PotPlayer|팟플레이어|BINU_KOREA_SRT_.*)', re.I)
    # [V142.72] AI냥 요청: "56. " 같은 인덱스 숫자까지 접두어 패턴에 포함! 🚀✨
    ptrn_prefix = re.compile(r'^(🔍\[.*?\]\s*|\[.*?\]\s*|\d+\.\s*)')

    # [TAG: #@_fuzzy_norm]
    def _fuzzy_norm(text):
        if not text: return ""
        # 1. 접미어 정리 (PotPlayer, BINU_KOREA_SRT_)
        t = ptrn_suffix.split(text)[0]
        # 2. 접두어 정리 (🔍[✅SYNC], [Playlist], 인덱스 숫자)
        t = ptrn_prefix.sub('', t)
        # 3. 특수문자 제거 및 다국어 지원 (\w)
        return re.sub(r'[^\w]', '', t).lower()

    is_title_res = target_path.startswith("[TITLE]")
    target_clean = target_path.replace("[TITLE]", "").lower() if is_title_res else os.path.normpath(target_path).lower()
    
    norm_target_fuzzy = _fuzzy_norm(target_clean) if is_title_res else None

    for idx, opt in enumerate(options):
        opt_p = None
        if isinstance(opt, dict): opt_p = opt.get('path')
        elif exact_path_map: opt_p = exact_path_map.get(_get_ui_text(opt))

        if not opt_p: continue

        # 정규화 매칭 시도 🕵️‍♂️
        curr_norm = os.path.normpath(opt_p).lower()
        if is_title_res:
             # [V134.6] 제목 매칭 시도 (Fuzzy Matching 정밀화: Substring 포함 관계 체크) 🕵️‍♂️✨
             base_name = os.path.basename(curr_norm)
             pure_name = os.path.splitext(base_name)[0]
             norm_base = _fuzzy_norm(base_name)
             norm_pure = _fuzzy_norm(pure_name)

             # [V134.6] 정확도 향상: 어느 한 쪽이 다른 쪽에 완전히 포함될 때만 매칭으로 인정
             if norm_target_fuzzy and norm_base and (norm_target_fuzzy in norm_base or norm_base in norm_target_fuzzy):
                 # 추가 검증: 너무 짧은 문자열(3자 미만)끼리의 부분 일치는 무시하여 오작동 방지
                 if len(norm_target_fuzzy) >= 3 and len(norm_base) >= 3:
                     return idx, opt_p
             if norm_target_fuzzy and norm_pure and (norm_target_fuzzy in norm_pure or norm_pure in norm_target_fuzzy):
                 if len(norm_target_fuzzy) >= 3 and len(norm_pure) >= 3:
                     return idx, opt_p
        else:
             # 경로 매치 시: 1:1 절대 경로 대조
             if curr_norm == target_clean: return idx, opt_p

    return -1, None

