_g_select_toggle_states = {'sub': 0, 'hit': 0, 'size': 0} # [V165.0] 자막/따봉/용량 일괄 선택 토글 상태 저장소 🔄✨

def _get_potplayer_played_files(s=None):
    """[V164.0] 팟플 DPL 파일 및 세션 기록에서 실제로 '재생(시청)한 항목'만 정밀 추출한다냥! 🎬🎯✨"""
    collected = []
    seen = set()

    def _add_valid_p(p):
        if not p or not isinstance(p, str): return
        p_clean = p.strip().strip('"').strip("'")
        if not p_clean: return
        norm = os.path.normpath(p_clean).lower()
        if norm not in seen and os.path.exists(p_clean) and not os.path.isdir(p_clean):
            seen.add(norm)
            collected.append(os.path.normpath(p_clean))

    # 1. 세션 히스토리 누적 스캔
    sess_hist = globals().get('_g_potplayer_session_history', set())
    for p in sess_hist: _add_valid_p(p)

    # 2. DPL 파일 스캔 (%APPDATA%\PotPlayer64 등)
    appdata = os.environ.get("APPDATA", "")
    dpl_candidates = [
        os.path.join(appdata, r"PotPlayer64\Playlist\PotPlayer64.dpl"),
        os.path.join(appdata, r"PotPlayerMini64\Playlist\PotPlayerMini64.dpl"),
        os.path.join(appdata, r"PotPlayer\Playlist\PotPlayer.dpl")
    ]
    for dpl in dpl_candidates:
        if not os.path.exists(dpl): continue
        content_dpl = _read_dpl(dpl)

        if content_dpl:
            # playname= 헤더 파일
            m_play = re.search(r"playname=([^\r\n]*)", content_dpl)
            if m_play and m_play.group(1).strip():
                _add_valid_p(m_play.group(1).strip())

            # 재생 위치/시청 흔적이 있는 인덱스 N 추출
            played_indices = set()
            for idx_str in re.findall(r"(\d+)\*start", content_dpl): played_indices.add(idx_str)
            for idx_str in re.findall(r"(\d+)\*played", content_dpl): played_indices.add(idx_str)
            for idx_str in re.findall(r"(\d+)\*pos", content_dpl): played_indices.add(idx_str)

            for idx_str in played_indices:
                m_file = re.search(fr"{idx_str}\*file\*([^\r\n]*)", content_dpl)
                if m_file and m_file.group(1).strip():
                    _add_valid_p(m_file.group(1).strip())

            if not collected:
                file_lines = re.findall(r"\d+\*file\*([^\r\n]*)", content_dpl)
                for line_path in file_lines:
                    _add_valid_p(line_path)

    # 3. 현재 재생 중인 파일 및 최근 감지 파일 추가
    cur_p = globals().get('_g_potplayer_current_path')
    if cur_p: _add_valid_p(cur_p)

    last_res = globals().get('_G_LAST_POTPLAYER_RESOLVED_PATH')
    if last_res: _add_valid_p(last_res)

    last_title = globals().get('_g_last_seen_pot_title')
    if last_title and s:
        try:
            p_found, _ = _get_sync_path_dpl(s, find_title=last_title)
            if p_found: _add_valid_p(p_found)
        except: pass

    return collected

def _match_potplayer_files(options, pot_files, max_len, exact_path_map):
    """[V164.0] 수집된 팟플 파일들과 현재 options 항목들 간의 매칭 인덱스/경로 리스트를 반환한다냥! 🎯✨"""
    if not pot_files or not options: return []
    pot_norm_paths = {os.path.normpath(pf).lower() for pf in pot_files if os.path.exists(pf)}
    pot_pure_names = {re.sub(r'[^\w]', '', os.path.splitext(os.path.basename(pf))[0]).lower() for pf in pot_files if os.path.exists(pf)}

    target_file_data = []
    for _idx, _opt in enumerate(options):
        if _idx < max_len: continue # 좌측 사이드바 메뉴 제외
        _p = None
        if isinstance(_opt, dict): _p = _opt.get('path')
        elif exact_path_map: _p = exact_path_map.get(_get_ui_text(_opt))
        if not _p: continue

        is_match = False
        if os.path.exists(_p) and not os.path.isdir(_p):
            norm_curr = os.path.normpath(_p).lower()
            if norm_curr in pot_norm_paths:
                is_match = True
            else:
                pure_curr = re.sub(r'[^\w]', '', os.path.splitext(os.path.basename(_p))[0]).lower()
                if pure_curr and len(pure_curr) >= 2 and pure_curr in pot_pure_names:
                    is_match = True

        if is_match:
            target_file_data.append((_idx, _p))

    return target_file_data

# [TAG: #@_trigger_webdav_play_event]
def _trigger_webdav_play_event(file_path: str, source_label: str = "WebDAV"):
    """[V180.7] WebDAV / 미디어 서버 스트리밍 요청 시 실시간 파일 추적 및 삭제 대기열 즉시 해소 🎯✨"""
    global _g_skybox_sync_result, _global_menu_redraw_flag
    try:
        if not file_path or not isinstance(file_path, str) or not os.path.isfile(file_path):
            return
        video_exts = (
            '.mp4', '.mkv', '.avi', '.wmv', '.mov', '.flv', '.ts', '.webm', '.m4v', '.mp3', 
            '.flac', '.m2ts', '.tp', '.wav', '.m4a', '.aac', '.ogg', '.mpg', '.mpeg', '.wma'
        )
        if not file_path.lower().endswith(video_exts):
            return

        norm_file = os.path.normpath(file_path)

        # 🚮 [핵심] 원격/미디어 스트리밍으로 새 파일이 재생되는 순간, 이전 파일들의 잠금이 풀렸으므로 삭제 대기열 즉시 처리!
        try:
            flush_pending_delete_queue({norm_file})
        except Exception: pass

        # ⚠️ TUI 탐색기 모드가 아닐 때는 화면 깜빡임 방지를 위해 포커싱만 중단 (백그라운드 삭제는 정상 수행)
        if not globals().get('_g_in_tui_explorer', False):
            return

        # ⚠️ [V180.7] 원격 파일 추적 기능 전역 토글(s_m_remote_file_tracker) 활성화 여부 확인
        s = globals().get('settings')
        if not (s and hasattr(s, 'data') and s.data.get('s_m_remote_file_tracker', False)):
            return

        # 중복 알림 방지 (동일 파일이 계속 스트리밍될 때는 중복 감지/화면 리프레시 방지 - 10분 이내 스킵)
        now = time.time()
        last_trig = getattr(_trigger_webdav_play_event, '_last_triggered', {})
        if last_trig.get('file') == norm_file and (now - last_trig.get('time', 0) < 600.0):
            return
        _trigger_webdav_play_event._last_triggered = {'file': norm_file, 'time': now}

        _log_to_file(f"🎯 [{source_label} Tracker] 재생 파일 감지: {norm_file}")
        try:
            label_display = "미디어서버" if source_label in ("MediaServer", "미디어서버") else source_label
            msg = f"{label_display} 재생 감지: {os.path.basename(norm_file)}"
            globals()['_g_bottom_msg'] = f"🚀 {msg}"
            _show_windows_toast(msg, "Binu Assistant")
        except: pass

        # TUI 탐색기가 열려있을 때만 즉시 해당 파일로 포커싱 이동 & 선택
        _g_skybox_sync_result = norm_file
        globals()['_global_menu_redraw_flag'] = True
        globals()['_global_force_explorer_refresh'] = True
    except Exception as e:
        _log_to_file(f"⚠️ [_trigger_webdav_play_event] Error: {e}")

_trigger_media_server_play_event = _trigger_webdav_play_event

# [TAG: #@_skybox_monitor_thread_fn]
def _skybox_monitor_thread_fn():
    global _g_skybox_monitor_running, _g_skybox_sync_result, _skybox_sync_active, _global_menu_redraw_flag
    import psutil, time, subprocess, re
    _g_skybox_monitor_running = True
    video_extensions = ('.mp4', '.mkv', '.avi', '.wmv', '.mov', '.flv', '.ts', '.webm', '.m4v', '.mp3', '.flac')
    last_seen_file = None
    
    handle_exe_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'temp', 'handle.exe')
    if not os.path.exists(handle_exe_path):
        try:
            os.makedirs(os.path.dirname(handle_exe_path), exist_ok=True)
            import urllib.request
            urllib.request.urlretrieve("https://live.sysinternals.com/handle.exe", handle_exe_path)
        except:
            pass
            
    while _skybox_sync_active:
        playing_files = set()
        
        # [V22.2.4 PID Fix] PID 기반 초정밀 탐색 (프로세스명이 무엇이든 PID로 100% 파일 핸들 획득! 🎯✨)
        target_pids = []
        try:
            for p in psutil.process_iter(['pid', 'name']):
                p_name = (p.info.get('name') or '').lower()
                if any(k in p_name for k in ['skybox', 'airscreen', 'vrplayer', 'deovr', 'heresphere', 'moonplayer', 'moonvr', 'pigasus']):
                    target_pids.append(p.info['pid'])
        except Exception:
            pass
            
        if target_pids and os.path.exists(handle_exe_path):
            ext_pattern = '|'.join(ext.replace('.', r'\.') for ext in video_extensions)
            for pid in target_pids:
                try:
                    proc = subprocess.Popen([handle_exe_path, '-accepteula', '-p', str(pid)], stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, creationflags=subprocess.CREATE_NO_WINDOW)
                    out, _ = proc.communicate(timeout=1.5)
                    
                    out_str = ""
                    for enc in ('cp949', 'euc-kr', 'utf-8', sys.getfilesystemencoding()):
                        try:
                            out_str = out.decode(enc)
                            break
                        except Exception:
                            pass
                    if not out_str:
                        out_str = out.decode('utf-8', errors='ignore')

                    matches = set(re.findall(r'([A-Za-z]:\\[^\r\n]+(?:' + ext_pattern + r'))', out_str, flags=re.IGNORECASE))
                    for m in matches:
                        raw_path = m.strip()
                        if '?' in raw_path:
                            try:
                                d = os.path.dirname(raw_path)
                                b = os.path.basename(raw_path)
                                if os.path.exists(d):
                                    b_pat = re.sub(r'\?+', '.*', re.escape(b))
                                    matcher = re.compile('^' + b_pat + '$', re.IGNORECASE)
                                    for f in os.listdir(d):
                                        if matcher.match(f):
                                            candidate = os.path.join(d, f)
                                            if os.path.isfile(candidate):
                                                raw_path = candidate
                                                break
                            except Exception:
                                pass
                        
                        if '?' not in raw_path and os.path.exists(raw_path) and os.path.isfile(raw_path):
                            playing_files.add(os.path.abspath(raw_path))
                except Exception as e:
                    _log_to_file(f"⚠️ [Skybox Tracker PID={pid}] handle.exe error: {e}")

        # psutil open_files 백업 플랜
        if not playing_files and target_pids:
            for pid in target_pids:
                try:
                    p = psutil.Process(pid)
                    for file in p.open_files():
                        if file.path.lower().endswith(video_extensions) and os.path.isfile(file.path):
                            playing_files.add(os.path.abspath(file.path))
                except Exception:
                    pass
        
        current_file = list(playing_files)[0] if playing_files else None
        
        if current_file and current_file != last_seen_file:
            _log_to_file(f"✅ [Skybox Tracker] 새 재생 파일 감지됨: {current_file}")
            try:
                msg = f"Skybox 재생 감지: {os.path.basename(current_file)}"
                globals()['_g_bottom_msg'] = f"🚀 {msg}"
                _show_windows_toast(msg, "Binu Assistant")
            except: pass
            
            last_seen_file = current_file
            if globals().get('_g_in_tui_explorer', False):
                _g_skybox_sync_result = current_file
                _global_menu_redraw_flag = True

        flush_pending_delete_queue(playing_files)
        time.sleep(3)
        
    _g_skybox_monitor_running = False

# [TAG: #@_potplayer_monitor_thread_fn]
def _potplayer_monitor_thread_fn(s):
    """[V121.3] 백그라운드에서 팟플레이어 종료를 감시하는 스레드 전용 함수냥! 🕵️‍♂️🛰️"""
    global _g_potplayer_monitor_running, _g_potplayer_sync_result, _potplayer_sync_active, _global_menu_redraw_flag
    try:
        _g_potplayer_monitor_running = True
        _log_to_file("📡 [Monitor Thread] 팟플레이어 백그라운드 감시 시작냥! 🕵️‍♂️")

        # [V142.17] 감시 스레드가 시작될 때만 단축키(Shift+Up/Down) 감시를 켭니다! 🚀
        try: globals().get('_register_potplayer_hotkeys', lambda: None)()
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

        # 실제 감시 로직 실행 (이미 최적화된 블로킹 모드 사용)
        # [V142.22] 다중 팟플 대응: 전역 PID 변수 전달 🎯
        res_path, res_mtime = _wait_for_potplayer_exit(s, blocking=True, is_dpl_mode=_g_potplayer_is_dpl_mode, target_pid=_g_last_potplayer_pid)

        # 결과 저장 및 신호 발송 🚀
        if res_path:
            _g_potplayer_sync_result = res_path
            globals()['_g_last_sync_source'] = 'POTPLAYER'
            _log_to_file(f"🎯 [Monitor Thread] 감지 성공! 결과: {res_path} (PID: {_g_last_potplayer_pid})")
            # [V121.6] AI냥 요청: 하단 알림 문구 포맷팅 최적화 📢✨
            _disp_name = os.path.basename(res_path.replace("[TITLE]", ""))
            # [수정] 비누님 요청으로 "팟플 제목창 마지막 파일" 알림 제거 🤫
            globals()['_last_bg_notification'] = ""
            globals()['_last_bg_notification_time'] = time.time()
            # [V22.36] 팟플레이어 종료 감지 성공 시 즉시 TUI 탐색기 화면 새로고침 및 마지막 위치 이동 트리거! 🚀✨🎯
            globals()['_global_force_explorer_refresh'] = True
            globals()['_global_menu_redraw_flag'] = True
        elif res_mtime == -1:
            # [V21.6] AI냥 요청: 팟플이 애초에 안 떴다면(AIMP 등) 조용히 퇴근냥! 🤫🛡️
            _log_to_file(" 🤫 [Monitor Thread] PotPlayer not detected. Quiet exit.")
        else:
            # [V142.10] 제목 감지 실패 시 안내 추가 (DPL/단독 재생 모두 작동냥!) 🧼✨
            _log_to_file("⚠️ [Monitor Thread] 제목 감지 실패... 🛑")
            globals()['_last_bg_notification'] = "📢 팟플 제목 감지 실패.."
            globals()['_last_bg_notification_time'] = time.time()
            
            # [V21.3] AI냥 요청: 감지 실패 시에도 파일 삭제 등으로 인한 불일치 해결을 위해 '조용한 리프레시' 트리거냥! 🛰️🔄✨
            # [V21.6] 단, 이때는 '화면을 새로고침했어냥!' 메시지가 덮어쓰지 않도록 조용히 진행냥! 🤫
            globals()['_global_force_explorer_refresh'] = True
            globals()['_global_menu_redraw_flag'] = True

    except Exception as e:
        _log_to_file(f"❌ [Monitor Thread] 오류 발생: {e}")
    finally:
        # [V147.175] AI냥 요청: 재생이 완전히 끝났으므로, 현재 재생 중이던 파일을 비로소 황금색으로 등극! 🏆✨
        global _g_potplayer_current_path, _g_potplayer_current_pk, _G_LAST_POTPLAYER_RESOLVED_PATH
        # [V151.8] 팟플 종료 시 로그 캐시 초기화냥! (다음번 재생 시 로그가 다시 보일 수 있게) 🛸✨
        _G_LAST_POTPLAYER_RESOLVED_PATH = None

        # [V22.37] 팟플레이어 종료 시 감지된 최종 재생 파일에 대해 낙엽(Gold) 및 메달 저장 🍂🥇
        _final_played = res_path or _g_potplayer_current_path
        if _final_played and not str(_final_played).startswith("[TITLE]"):
            _log_to_file(f"🏁 [Monitor Thread] Playback finished. Updating medal & leaf for {_final_played}")
            _update_medal_history(_final_played)
            try:
                time.sleep(0.02)
                _save_last_played_ctx(_final_played, settings_obj=s, pk=_g_potplayer_current_pk, is_starting=False, quiet=True)
            except Exception as _se:
                _log_to_file(f"⚠️ [Monitor Thread] Leaf save error: {_se}")

        globals()['_g_is_switching_media'] = False
        _g_potplayer_current_path = None
        _g_potplayer_current_pk = None

        # 화면 새로고침 신호 발송
        if res_path:
            globals()['_global_force_explorer_refresh'] = True
            globals()['_global_menu_redraw_flag'] = True
        else:
            _global_menu_redraw_flag = True

        # 팟플레이어가 정상 종료되었을 때만 최신 재생 상태 동기화 및 이전 시청 복원
        try: _sync_auto_playlist_dpl_on_exit(res_path)
        except Exception as _syne: _log_to_file(f"⚠️ [DPL Sync On Exit Error] {_syne}")
        # 🎬 [V179.0] 팟플 종료 시 DPL 1/2 및 레지스트리에서 최종 시청 위치(초)를 추출하여 썸.db에 영구 동기화 💾✨
        try: _sync_potplayer_exit_position_to_db(_final_played)
        except Exception as _pos_e: _log_to_file(f"⚠️ [PotPlayer Exit Pos Sync Error] {_pos_e}")
        _restore_music_if_needed(s)

        _g_potplayer_monitor_running = False
        _potplayer_sync_active = False # 플래그 초기화

        # [V142.17] 팟플 감시가 끝나면 단축키 감시도 칼같이 해제! 🛑
        try: globals().get('_unregister_potplayer_hotkeys', lambda: None)()
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

        _log_to_file("🏁 [Monitor Thread] 감시 자취를 감춤냥! 💨")
_last_dpl_mtime = 0      # 플레이리스트 최종 수정 시간 메모리 🕒
_last_jumped_mtime = 0   # 마지막으로 자동 점프를 수행한 플레이리스트 시간 🛑
_last_playback_trigger_time = 0 # [V61.28] 재생 시작 시각 (2초 쿨타임용) 🕒🚀

# [TAG: #@_sync_auto_playlist_dpl_on_exit]
def _sync_auto_playlist_dpl_on_exit(last_played_path=None):
    """[V164.30] 팟플레이어 정상 종료 시점에 활성 슬롯 DPL의 최신 재생 상태를 temp/Binu_Auto_Playlist.dpl 에 완벽 동기화합니다. 🔄📋✨"""
    try:
        if globals().get('_g_is_switching_media'):
            return

        t_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "temp")
        if not os.path.exists(t_dir):
            return
        
        main_dpl = os.path.join(t_dir, "Binu_Auto_Playlist.dpl")
        active_slot = globals().get('_g_active_dpl_slot', '1')
        slot_dpl = os.path.join(t_dir, f"Binu_Auto_Playlist_{active_slot}.dpl")

        # 활성 슬롯의 최신 DPL이 존재하면 main_dpl로 복사 동기화
        if os.path.exists(slot_dpl) and os.path.getsize(slot_dpl) > 0:
            try:
                import shutil
                shutil.copy2(slot_dpl, main_dpl)
            except Exception: pass

        target_f = last_played_path or globals().get('_g_potplayer_current_path') or globals().get('_G_LAST_POTPLAYER_RESOLVED_PATH')
        abs_target = os.path.abspath(target_f) if target_f else None
        
        # [V177.1] 팟플레이어 자체 DPL(AppData)에서 최신 playindex 또는 playname 폴백 확인 🕵️‍♂️
        appdata_dir = os.environ.get('APPDATA', '')
        pot_dpls = [
            os.path.join(appdata_dir, r"PotPlayer64\Playlist\PotPlayer64.dpl"),
            os.path.join(appdata_dir, r"PotPlayerMini64\Playlist\PotPlayerMini64.dpl"),
            os.path.join(appdata_dir, r"PotPlayer\Playlist\PotPlayer.dpl")
        ]
        pot_playindex = -1
        pot_playname = None
        for pd in pot_dpls:
            if os.path.exists(pd):
                ptxt = _read_dpl(pd)
                if ptxt:
                    for pline in ptxt.splitlines():
                        if pline.startswith("playindex="):
                            try: pot_playindex = int(pline.split("=", 1)[1].strip())
                            except: pass
                        elif pline.startswith("playname="):
                            pot_playname = pline.split("=", 1)[1].strip()
                if pot_playindex >= 0 or pot_playname:
                    break

        if not abs_target and pot_playname and os.path.exists(pot_playname):
            abs_target = os.path.abspath(pot_playname)

        if os.path.exists(main_dpl):
            matched_idx = -1
            lines = []
            for dpl_target_path in [main_dpl, slot_dpl]:
                if not os.path.exists(dpl_target_path): continue
                dpl_txt = _read_dpl(dpl_target_path)
                if not dpl_txt: continue
                lines = dpl_txt.splitlines()
                
                # 1차: abs_target 경로로 인덱스 매칭
                if abs_target:
                    for line in lines:
                        if "*file*" in line:
                            parts = line.split("*file*", 1)
                            if len(parts) == 2 and (parts[1].strip().lower() == abs_target.lower() or os.path.basename(parts[1].strip()).lower() == os.path.basename(abs_target).lower()):
                                try:
                                    matched_idx = int(parts[0].strip()) - 1
                                    break
                                except: pass
                                
                # 2차: 팟플 DPL에서 직접 추출한 playindex 폴백
                if matched_idx < 0 and pot_playindex >= 0:
                    matched_idx = pot_playindex

                if matched_idx >= 0:
                    new_lines = []
                    for line in lines:
                        if abs_target and line.startswith("playname="):
                            new_lines.append(f"playname={abs_target}")
                        elif line.startswith("playindex=") or line.startswith("topindex="):
                            continue
                        else:
                            new_lines.append(line)
                    
                    if new_lines and new_lines[0].strip() == "DAUMPLAYLIST":
                        new_lines.insert(1, f"topindex={matched_idx}")
                        new_lines.insert(1, f"playindex={matched_idx}")
                        if abs_target and not any(l.startswith("playname=") for l in new_lines):
                            new_lines.insert(1, f"playname={abs_target}")
                            
                        with open(dpl_target_path, "w", encoding="utf-8", errors="replace") as f:
                            f.write("\r\n".join(new_lines) + "\r\n")

            if matched_idx >= 0:
                _t_name = os.path.basename(abs_target) if abs_target else f"인덱스 {matched_idx}"
                _log_to_file(f"🎯 [DPL Sync On Exit] Binu_Auto_Playlist.dpl 및 슬롯 {active_slot} 마지막 시청 위치(인덱스 {matched_idx}: {_t_name}) 완벽 갱신 완료!")
            
            # [V177.1] DPL 재생 이력(0번부터 matched_idx번까지 소비된 파일들) 통계 일괄 DB 기록 📊🎬
            played_files = []
            if matched_idx >= 0 and lines:
                for line in lines:
                    if "*file*" in line:
                        parts = line.split("*file*", 1)
                        if len(parts) == 2:
                            try:
                                item_idx = int(parts[0].strip()) - 1
                                if 0 <= item_idx <= matched_idx:
                                    f_p = parts[1].strip()
                                    if f_p and os.path.exists(f_p):
                                        played_files.append(f_p)
                            except: pass
            elif abs_target and os.path.exists(abs_target):
                played_files = [abs_target]
                
            if played_files:
                try: _record_batch_playbacks(played_files)
                except Exception as _rbe: _log_to_file(f"⚠️ [DPL Playback Stats Record Error] {_rbe}")
    except Exception as e:
        _log_to_file(f"⚠️ [_sync_auto_playlist_dpl_on_exit Error] {e}")

_g_is_switching_media = False

# [TAG: #@_kill_potplayer]
def _kill_potplayer(graceful=True):
    """[V164.10] 팟플레이어가 재생 위치(이어보기 시간)를 정상 저장하고 닫히도록 WM_CLOSE를 먼저 전송합니다. 🛑🎬✨"""
    try:
        import ctypes, time, subprocess
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        globals()['_g_is_switching_media'] = True

        if graceful:
            hwnds = []
            def _enum_proc(hwnd, lparam):
                class_buf = ctypes.create_unicode_buffer(256)
                user32.GetClassNameW(hwnd, class_buf, 256)
                if class_buf.value in ["PotPlayer64", "PotPlayerMini64", "PotPlayer"]:
                    hwnds.append(hwnd)
                return True
            ENUM_PROC = ctypes.WINFUNCTYPE(ctypes.c_bool, wintypes.HWND, wintypes.LPARAM)
            user32.EnumWindows(ENUM_PROC(_enum_proc), 0)

            WM_CLOSE = 0x0010
            for h in hwnds:
                user32.PostMessageW(h, WM_CLOSE, 0, 0)

            # [V164.14] 초고속 20ms 폴링으로 팟플이 닫히는 즉시 루프 탈출 (평균 30~50ms) ⚡
            for _ in range(12):
                time.sleep(0.02)
                if not is_potplayer_running():
                    break

        # 아직 덜 닫힌 프로세스가 있다면 부드러운 taskkill 후 최종 정리
        if is_potplayer_running():
            for proc_name in ["PotPlayer64.exe", "PotPlayerMini64.exe", "PotPlayer.exe"]:
                subprocess.run(["taskkill", "/IM", proc_name],
                               stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            time.sleep(0.05)
            if is_potplayer_running():
                for proc_name in ["PotPlayer64.exe", "PotPlayerMini64.exe", "PotPlayer.exe"]:
                    subprocess.run(["taskkill", "/F", "/IM", proc_name],
                                   stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception as e:
        _log_to_file(f"⚠️ [_kill_potplayer Error] {e}")

# [TAG: #@_get_potplayer_exe_path]
def _get_potplayer_exe_path():
    """시스템에 설치된 팟플레이어 실행 파일(PotPlayer64.exe) 경로를 반환합니다. 🎬🎯"""
    candidates = [
        r"C:\Program Files\DAUM\PotPlayer\PotPlayer64.exe",
        r"C:\Program Files (x86)\DAUM\PotPlayer\PotPlayer.exe",
        r"C:\Program Files\DAUM\PotPlayer\PotPlayerMini64.exe",
        r"C:\Program Files (x86)\DAUM\PotPlayer\PotPlayerMini.exe",
        os.path.join(os.environ.get('PROGRAMFILES', r"C:\Program Files"), r"DAUM\PotPlayer\PotPlayer64.exe"),
        os.path.join(os.environ.get('PROGRAMFILES(X86)', r"C:\Program Files (x86)"), r"DAUM\PotPlayer\PotPlayer.exe"),
    ]
    for p in candidates:
        if p and os.path.isfile(p):
            return p
    try:
        import winreg
        for subkey in [r"Software\DAUM\PotPlayer64", r"Software\DAUM\PotPlayerMini64", r"Software\DAUM\PotPlayer"]:
            try:
                k = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, subkey)
                val, _ = winreg.QueryValueEx(k, "ProgramPath")
                winreg.CloseKey(k)
                if val and os.path.isfile(val): return val
            except: pass
    except: pass
    return None

# [TAG: #@_get_potplayer_title]
def _get_potplayer_title__REMOVE_TARGET(target_pid=None):
    """[V110.10] 현재 실행 중인 팟플레이어의 창 제목을 가져온다냥! (PID 지정 시 정밀 타격 가능) 🕵️‍♂️🔭"""
    try:
        from ctypes import wintypes
        import ctypes
        user32 = ctypes.windll.user32

        if target_pid:
            found_title = [None]
            def _enum_proc(hwnd, lparam):
                class_buf = ctypes.create_unicode_buffer(256)
                user32.GetClassNameW(hwnd, class_buf, 256)
                if class_buf.value in ["PotPlayer64", "PotPlayerMini64", "PotPlayer"]:
                    lp_pid = wintypes.DWORD()
                    user32.GetWindowThreadProcessId(hwnd, ctypes.byref(lp_pid))
                    if lp_pid.value == target_pid:
                        buf = ctypes.create_unicode_buffer(512)
                        user32.GetWindowTextW(hwnd, buf, 512)
                        found_title[0] = buf.value
                        return False
                return True

            ENUM_WINDOWS_PROC = ctypes.WINFUNCTYPE(ctypes.c_bool, wintypes.HWND, wintypes.LPARAM)
            user32.EnumWindows(ENUM_WINDOWS_PROC(_enum_proc), 0)
            if found_title[0]: return found_title[0]
            return None

        for class_name in ["PotPlayer64", "PotPlayerMini64", "PotPlayer"]:
            hwnd = user32.FindWindowW(class_name, None)
            if hwnd:
                buf = ctypes.create_unicode_buffer(512)
                user32.GetWindowTextW(hwnd, buf, 512)
                return buf.value
    except Exception as e:
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")
    return None

_g_current_active_dpl_name = "Binu_Auto_Playlist.dpl"
_g_last_toggle_prev_dpl_time = 0

def _check_dpl_locked_files(files_list):
    """[V164.35] 파일 락 전수 검사 비활성화 (대조 오버헤드 제거) 🚀✨"""
    return None

def _detect_current_potplayer_playing_slot(dpl1_path, dpl2_path):
    """[V164.37] 팟플레이어 창 제목에서 현재 재생 중인 파일명을 추출하여 1번 vs 2번 DPL 중 어디에 속해 있는지 0.001초 감지 🕵️‍♂️⚡"""
    try:
        import os, re
        get_title_func = globals().get('_get_potplayer_title')
        cur_title = get_title_func() if get_title_func else None
        cur_path = globals().get('_g_potplayer_current_path') or globals().get('_G_LAST_POTPLAYER_RESOLVED_PATH')

        read_func = globals().get('_read_dpl') or (lambda p: "")
        dpl1_txt = read_func(dpl1_path).lower() if os.path.exists(dpl1_path) else ""
        dpl2_txt = read_func(dpl2_path).lower() if os.path.exists(dpl2_path) else ""

        check_keys = []
        if cur_path:
            norm_cp = os.path.normpath(cur_path).lower()
            check_keys.extend([norm_cp, os.path.basename(norm_cp)])

        if cur_title:
            ct_clean = cur_title.strip()
            ct_clean_file = re.sub(r'\s*-\s*(?:팟플[^\s]*|PotPlayer[^\s]*|BINU[^\s]*)\s*$', '', ct_clean, flags=re.IGNORECASE).strip()
            generic_names = ["PotPlayer", "PotPlayer64", "PotPlayerMini64", "팟플레이어", "PotPlayer Mini"]
            if not any(g == ct_clean for g in generic_names) and len(ct_clean) >= 3:
                ext_match = re.search(r'([^\r\n\\/:*?"<>|]+\.(?:mp4|mkv|avi|ts|wmv|mov|flv|webm|m4v|tp|mp3|flac|wav|aac|m4a|ogg))', ct_clean_file, re.IGNORECASE)
                extracted_fn = ext_match.group(1).strip().lower() if ext_match else ct_clean_file.lower()
                check_keys.extend([extracted_fn, ct_clean_file.lower()])

        in_dpl1 = False
        in_dpl2 = False

        for k in check_keys:
            if not k: continue
            if dpl1_txt and k in dpl1_txt:
                in_dpl1 = True
            if dpl2_txt and k in dpl2_txt:
                in_dpl2 = True

        if in_dpl1 and not in_dpl2:
            return "1"
        if in_dpl2 and not in_dpl1:
            return "2"
        return None
    except Exception:
        return None

def _get_smart_dpl_slot(temp_dir=None):
    """[V164.37 스마트 DPL 슬롯 결정] 팟플 창 제목 기반 현재 슬롯 감지 및 고속 슬롯 선택 ⏱️🎬🔀✨"""
    try:
        import os, time
        if not temp_dir:
            temp_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "temp")
        dpl1 = os.path.join(temp_dir, "Binu_Auto_Playlist_1.dpl")
        dpl2 = os.path.join(temp_dir, "Binu_Auto_Playlist_2.dpl")

        # 1. 팟플레이어가 실행 중인 경우: 창 제목으로 현재 열린 플리 감지 후 반대 슬롯 선택! 🎯
        is_running_func = globals().get('is_potplayer_running')
        pot_running = bool(is_running_func() if is_running_func else False)
        if pot_running:
            detected_current_slot = _detect_current_potplayer_playing_slot(dpl1, dpl2)
            if detected_current_slot == "1":
                _log_to_file("🎯 [Smart DPL Slot] 팟플 창 제목 감지: 1번 플리 재생 중 확인! ➔ 2번 슬롯 선택!")
                return "2"
            elif detected_current_slot == "2":
                _log_to_file("🎯 [Smart DPL Slot] 팟플 창 제목 감지: 2번 플리 재생 중 확인! ➔ 1번 슬롯 선택!")
                return "1"
            
            # 특정되지 않을 때: 활성 슬롯의 반대 선택
            active_slot = str(globals().get('_g_active_dpl_slot', '1'))
            target_slot = "2" if active_slot == "1" else "1"
            _log_to_file(f"🎯 [Smart DPL Slot] 팟플 실행 중 (활성 슬롯 {active_slot}) ➔ 슬롯 {target_slot} 전환!")
            return target_slot

        # 2. 팟플레이어가 닫혀 있거나 비재생 상태인 경우: 파일 수정 시간(mtime) 비교 ⏱️
        t1 = os.path.getmtime(dpl1) if (os.path.exists(dpl1) and os.path.getsize(dpl1) > 0) else -1
        t2 = os.path.getmtime(dpl2) if (os.path.exists(dpl2) and os.path.getsize(dpl2) > 0) else -1
        
        if t1 > 0 and t2 > 0:
            return "1" if t1 <= t2 else "2"
        if t1 > 0:
            return "1"
        if t2 > 0:
            return "2"
        return "1"
    except Exception as e:
        _log_to_file(f"⚠️ [_get_smart_dpl_slot] 에러 발생 (기본 슬롯 1 사용): {e}")
        return "1"

_get_oldest_dpl_slot = _get_smart_dpl_slot

def _apply_target_volume_on_media_switch(target_vol, target_play_file=None, max_wait_sec=1.5):
    """[V164.39] 팟플레이어가 실제로 새 영상을 로드하여 창 제목이 바뀐 정확한 순간(0.01초 오차 없이)에 볼륨을 동기화 적용합니다. 🔊🎬✨"""
    if target_vol is None:
        return
    def _worker():
        try:
            import time, os
            start_t = time.time()
            check_key = os.path.basename(target_play_file).lower() if target_play_file else None
            get_title_func = globals().get('_get_potplayer_title')
            applied = False

            # 새 영상이 실제로 팟플레이어 창에 로드될 때까지 0.04초 간격으로 초고속 감지
            while time.time() - start_t < max_wait_sec:
                if get_title_func and check_key:
                    title = get_title_func()
                    if title and check_key in title.lower():
                        _set_system_volume(target_vol)
                        applied = True
                        elapsed = time.time() - start_t
                        _log_to_file(f"🔊 [Toggle Prev DPL] 새 영상 로드 감지 ➔ 목표 볼륨: {target_vol}% 실시간 적용 완료! (지연: {elapsed:.2f}s)")
                        break
                time.sleep(0.04)

            # 타임아웃 도달 시 안전 적용
            if not applied:
                _set_system_volume(target_vol)
                elapsed = time.time() - start_t
                _log_to_file(f"🔊 [Toggle Prev DPL] 타임아웃 안전 적용 ➔ 목표 볼륨: {target_vol}% 적용 완료! (경과: {elapsed:.2f}s)")
        except Exception as e:
            _log_to_file(f"⚠️ [_apply_target_volume_on_media_switch Error] {e}")

    import threading
    threading.Thread(target=_worker, daemon=True).start()

def _init_active_dpl_slot():
    """[V164.38] 앱 시작/재시작 시점에 팟플 창 제목 및 DPL 수정시간(mtime)을 기반으로 현재 활성 슬롯(1 or 2)을 자동 판정하여 초기화합니다. 🎯⏱️✨"""
    try:
        import os
        t_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "temp")
        dpl1 = os.path.join(t_dir, "Binu_Auto_Playlist_1.dpl")
        dpl2 = os.path.join(t_dir, "Binu_Auto_Playlist_2.dpl")

        # 1. 팟플레이어가 이미 실행 중이면 창 제목으로 감지
        is_running_func = globals().get('is_potplayer_running')
        pot_running = bool(is_running_func() if is_running_func else False)
        if pot_running:
            slot = _detect_current_potplayer_playing_slot(dpl1, dpl2)
            if slot in ("1", "2"):
                _log_to_file(f"🎯 [Active DPL Slot Init] 팟플 실행 중 감지 ➔ 활성 슬롯 {slot} 초기화 완료!")
                return slot

        # 2. 팟플이 꺼져 있으면 mtime 비교: 가장 최근에 사용/수정된 슬롯을 현재 활성 슬롯으로 설정
        t1 = os.path.getmtime(dpl1) if (os.path.exists(dpl1) and os.path.getsize(dpl1) > 0) else -1
        t2 = os.path.getmtime(dpl2) if (os.path.exists(dpl2) and os.path.getsize(dpl2) > 0) else -1
        if t1 > 0 and t2 > 0:
            slot = "1" if t1 >= t2 else "2"
        elif t1 > 0:
            slot = "1"
        elif t2 > 0:
            slot = "2"
        else:
            slot = "1"
        _log_to_file(f"⏱️ [Active DPL Slot Init] mtime 기반 (t1={t1:.1f}, t2={t2:.1f}) ➔ 활성 슬롯 {slot} 초기화 완료!")
        return slot
    except Exception as e:
        _log_to_file(f"⚠️ [_init_active_dpl_slot Error] {e}")
        return "1"

# [TAG: #@_execute_toggle_auto_playlist_prev]
_g_active_dpl_slot = _init_active_dpl_slot()

def _execute_toggle_auto_playlist_prev(s=None):
    """ [V164.37 핑퐁 DPL 슬롯 상호전환] 팟플 창 제목 기반 열린 플리 정밀 감지 후 즉시 상호전환! 🔀🎬✨ """
    global _g_active_dpl_slot, _g_last_toggle_prev_dpl_time, _g_potplayer_is_dpl_mode, _g_potplayer_dpl_paths
    try:
        import time, shutil, os, re
        now = time.time()
        # [1. 중복 연타/더블 트리거 방어 0.3초 디바운스 가드] 🛡️
        if now - globals().get('_g_last_toggle_prev_dpl_time', 0) < 0.3:
            _log_to_file("⏱️ [Toggle Prev DPL] 0.3초 이내 중복 트리거 차단 (Debounce Guard)")
            return False
        globals()['_g_last_toggle_prev_dpl_time'] = now

        if os.name == 'nt':
            try:
                import ctypes as _ct
                _ct.windll.kernel32.FlushConsoleInputBuffer(_ct.windll.kernel32.GetStdHandle(-10))
            except Exception: pass

        _gl_s = s or globals().get('_gl_settings') or globals().get('settings')
        t_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "temp")
        if not os.path.exists(t_dir):
            os.makedirs(t_dir, exist_ok=True)

        dpl1 = os.path.join(t_dir, "Binu_Auto_Playlist_1.dpl")
        dpl2 = os.path.join(t_dir, "Binu_Auto_Playlist_2.dpl")
        prev_fixed_dpl = os.path.join(t_dir, "Binu_Auto_Playlist_Prev.dpl")
        main_temp_dpl = os.path.join(t_dir, "Binu_Auto_Playlist.dpl")

        # [슬롯 복원 선행 체크] 1번이나 2번 슬롯이 비어있으면 Prev 백업 파일에서 복원
        if (not os.path.exists(dpl1) or os.path.getsize(dpl1) == 0) and os.path.exists(prev_fixed_dpl) and os.path.getsize(prev_fixed_dpl) > 0:
            try: shutil.copy2(prev_fixed_dpl, dpl1)
            except Exception: pass

        if (not os.path.exists(dpl2) or os.path.getsize(dpl2) == 0) and os.path.exists(prev_fixed_dpl) and os.path.getsize(prev_fixed_dpl) > 0:
            try: shutil.copy2(prev_fixed_dpl, dpl2)
            except Exception: pass

        cur_slot = str(globals().get('_g_active_dpl_slot', '1'))

        # 1. 팟플 실행 중 여부 확인 및 창 제목 기반 현재 재생 슬롯 정밀 감지 🕵️‍♂️✨
        is_running_func = globals().get('is_potplayer_running')
        pot_running = bool(is_running_func() if is_running_func else False)

        target_slot = None
        if pot_running:
            detected_current_slot = _detect_current_potplayer_playing_slot(dpl1, dpl2)
            if detected_current_slot == "1":
                target_slot = "2"
                cur_slot = "1"
                _log_to_file("🎯 [Smart Toggle DPL] 팟플 창 제목 감지: 1번 플리 재생 중 확인! ➔ 2번 슬롯으로 전환!")
            elif detected_current_slot == "2":
                target_slot = "1"
                cur_slot = "2"
                _log_to_file("🎯 [Smart Toggle DPL] 팟플 창 제목 감지: 2번 플리 재생 중 확인! ➔ 1번 슬롯으로 전환!")
            else:
                target_slot = "2" if cur_slot == "1" else "1"
                _log_to_file(f"🎯 [Smart Toggle DPL] 팟플 실행 중 (활성 슬롯 {cur_slot}) ➔ {target_slot}번 슬롯으로 전환!")
        else:
            # 비재생 / 팟플 종료 상태: 파일 수정시간(mtime) 비교 ⏱️
            t1 = os.path.getmtime(dpl1) if (os.path.exists(dpl1) and os.path.getsize(dpl1) > 0) else -1
            t2 = os.path.getmtime(dpl2) if (os.path.exists(dpl2) and os.path.getsize(dpl2) > 0) else -1
            if t1 > 0 and t2 > 0:
                target_slot = "2" if t1 >= t2 else "1"
                cur_slot = "1" if target_slot == "2" else "2"
                _log_to_file(f"⏱️ [Smart Toggle DPL] 비재생 상태: 시간차 비교(t1={t1:.1f}, t2={t2:.1f}) ➔ 슬롯 {target_slot} 선택!")
            elif t1 > 0:
                target_slot = "2"
            elif t2 > 0:
                target_slot = "1"
            else:
                target_slot = "2" if cur_slot == "1" else "1"

        target_dpl = os.path.join(t_dir, f"Binu_Auto_Playlist_{target_slot}.dpl")

        # 대상 슬롯 DPL이 여전히 없으면 Prev 백업 파일에서 복원
        if (not os.path.exists(target_dpl) or os.path.getsize(target_dpl) == 0) and os.path.exists(prev_fixed_dpl) and os.path.getsize(prev_fixed_dpl) > 0:
            try: shutil.copy2(prev_fixed_dpl, target_dpl)
            except: pass

        if not os.path.exists(target_dpl) or os.path.getsize(target_dpl) == 0:
            status_msg = "⚠️ 전환할 이전 플레이리스트(Prev)가 아직 없습니다냥!"
            globals()['_last_bg_notification'] = status_msg
            globals()['_last_bg_notification_time'] = time.time()
            globals()['_global_menu_redraw_flag'] = True
            _log_to_file(f"⚠️ [Toggle Prev DPL] {status_msg}")
            return False

        # [V164.17] 플리 전환 수행 시 팟플 종료 자동 새치기 복원 트리거 완전 해제 🛑
        _clear_media_restore_state()
        _log_to_file(f" 🔓 [Toggle Prev DPL] 슬롯 {cur_slot} ➔ 슬롯 {target_slot} 상호 전환 시작! 🔀✨")

        globals()['_g_is_switching_media'] = True
        _g_active_dpl_slot = target_slot

        # 전환된 대상 DPL에서 재생 대상 파일 및 파일 목록 추출
        read_func = globals().get('_read_dpl') or (lambda p: "")
        txt = read_func(target_dpl)
        swapped_files = []
        target_play_file = None
        if txt:
            for l in txt.splitlines():
                if l.startswith("playname="):
                    target_play_file = l.split("playname=", 1)[1].strip()
                elif "*file*" in l:
                    fp = l.split("*file*", 1)[1].strip()
                    if fp: swapped_files.append(os.path.abspath(fp))

        if not target_play_file and swapped_files:
            target_play_file = swapped_files[0]

        _g_potplayer_is_dpl_mode = True
        _g_potplayer_dpl_paths = swapped_files

        # 전환 대상 플리의 목표 볼륨 사전 판정 🎛️
        target_vol = _get_playlist_target_volume(target_dpl, target_play_file, s=_gl_s)

        # 메인 대표 파일(Binu_Auto_Playlist.dpl) 동기화
        try:
            shutil.copy2(target_dpl, main_temp_dpl)
        except Exception: pass

        # 메인 플리 재생 시작 (새로운 파일명으로 팟플에 직접 전달되어 즉시 재생!) 🚀
        globals()['_g_last_launch_time'] = 0
        open_path_resilient(target_dpl)
        _trigger_potplayer_monitor(_gl_s)

        # [V164.39] 실제 새 영상이 팟플에 로드되는 정확한 순간에 볼륨 전환 동기화! 🔊🎬✨
        if target_vol is not None:
            _apply_target_volume_on_media_switch(target_vol, target_play_file)

        disp_name = os.path.basename(target_play_file) if target_play_file else "이전 플레이리스트"
        vol_info = f" (🔊 {target_vol}%)" if target_vol is not None else ""
        status_msg = f"🔀 [플리 상호 전환] 슬롯 {target_slot}: {disp_name}{vol_info}"
        globals()['_last_bg_notification'] = status_msg
        globals()['_last_bg_notification_time'] = time.time()
        globals()['_global_menu_redraw_flag'] = True
        _log_to_file(f"🔀 [Shortcut Action] toggle_prev_auto_playlist triggered: {status_msg}")
        return True
    except Exception as e:
        _log_to_file(f"❌ [_execute_toggle_auto_playlist_prev Error] {e}")
        return False

# [TAG: #@is_potplayer_running]
def is_potplayer_running(target_pid=None):
    """[V61.18] 팟플레이어(64/Mini64)가 실행 중인지 확인한다냥! (PID 지정 시 해당 프로세스 정밀 체크) 🕵️‍♂️⚡✨"""
    try:
        from ctypes import wintypes
        user32 = ctypes.windll.user32

        if target_pid:
            # [V142.22] 특정 PID를 가진 팟플 윈도우가 있는지 전수 조사
            found = [False]
            # [TAG: #@_enum_proc]

            def _enum_proc(hwnd, lparam):
                class_buf = ctypes.create_unicode_buffer(256)
                user32.GetClassNameW(hwnd, class_buf, 256)
                if class_buf.value in ["PotPlayer64", "PotPlayerMini64", "PotPlayer"]:
                    lp_pid = wintypes.DWORD()
                    user32.GetWindowThreadProcessId(hwnd, ctypes.byref(lp_pid))
                    if lp_pid.value == target_pid:
                        found[0] = True
                        return False # 찾았으니 중단
                return True

            ENUM_WINDOWS_PROC = ctypes.WINFUNCTYPE(ctypes.c_bool, wintypes.HWND, wintypes.LPARAM)
            user32.EnumWindows(ENUM_WINDOWS_PROC(_enum_proc), 0)
            return found[0]

        # 기본 로직: 아무 팟플이나 떠 있으면 True
        for class_name in ["PotPlayer64", "PotPlayerMini64", "PotPlayer"]:
            if user32.FindWindowW(class_name, None):
                return True
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")
    return False

# [TAG: #@_trigger_potplayer_monitor]
def _trigger_potplayer_monitor(s):
    """[V121.3] 팟플레이어 감시 스레드를 안전하게 시작한다냥! (중복 방지) 🚀🔐✨"""
    global _g_potplayer_monitor_running
    if not _g_potplayer_monitor_running:
        t = threading.Thread(target=_potplayer_monitor_thread_fn, args=(s,), daemon=True)
        t.start()
        return True
    return False

# [TAG: #@_get_potplayer_title]
def _get_potplayer_title(target_pid=None):
    """[V110.10] 현재 실행 중인 팟플레이어의 창 제목을 가져온다냥! (PID 지정 시 정밀 타격 가능) 🕵️‍♂️🔭"""
    try:
        from ctypes import wintypes
        user32 = ctypes.windll.user32

        if target_pid:
            # [V142.22] 다중 실행 대응: 지정된 PID의 윈도우 제목만 추출냥!
            found_title = [None]
            # [TAG: #@_enum_proc]

            def _enum_proc(hwnd, lparam):
                class_buf = ctypes.create_unicode_buffer(256)
                user32.GetClassNameW(hwnd, class_buf, 256)
                if class_buf.value in ["PotPlayer64", "PotPlayerMini64", "PotPlayer"]:
                    lp_pid = wintypes.DWORD()
                    user32.GetWindowThreadProcessId(hwnd, ctypes.byref(lp_pid))
                    if lp_pid.value == target_pid:
                        buf = ctypes.create_unicode_buffer(512)
                        user32.GetWindowTextW(hwnd, buf, 512)
                        found_title[0] = buf.value
                        return False
                return True

            ENUM_WINDOWS_PROC = ctypes.WINFUNCTYPE(ctypes.c_bool, wintypes.HWND, wintypes.LPARAM)
            user32.EnumWindows(ENUM_WINDOWS_PROC(_enum_proc), 0)
            if found_title[0]: return found_title[0]
            return None

        for class_name in ["PotPlayer64", "PotPlayerMini64", "PotPlayer"]:
            hwnd = user32.FindWindowW(class_name, None)
            if hwnd:
                buf = ctypes.create_unicode_buffer(512)
                user32.GetWindowTextW(hwnd, buf, 512)
                return buf.value
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")
    return None

# [TAG: #@_wait_for_potplayer_exit]
def _wait_for_potplayer_exit(s=None, last_mtime=None, blocking=True, is_dpl_mode=False, target_pid=None):
    """[V61.19] 팟플레이어 플레이리스트(.dpl) 및 창 제목을 감시하여 최신 파일 정보를 반환한다냥! 🕵️‍♂️📡🛸✨
    [V142.22] target_pid 파라미터 추가: 다중 실행 시 특정 인스턴스만 정밀 감시! 🎯🛡️
    """
    global _potplayer_sync_active, _g_potplayer_is_dpl_mode
    # _potplayer_sync_active = True # [V96.4] 오지랖(!) 방지: 함수 호출만으로 플래그를 세우지 않음 ✨🎯
    if not s: return None, None

    # 1. 감시할 플레이리스트 파일 경로 특정 🎯
    appdata = os.environ.get('APPDATA', '')
    pot_type = s.data.get('last_potplayer_type', 'PotPlayer64')
    dpl_path = os.path.join(appdata, f"{pot_type}\\Playlist\\{pot_type}.dpl")

    if not os.path.exists(dpl_path):
        legacy_paths = [
            os.path.join(appdata, r"PotPlayer64\Playlist\PotPlayer64.dpl"),
            os.path.join(appdata, r"PotPlayerMini64\Playlist\PotPlayerMini64.dpl")
        ]
        for p in legacy_paths:
            if os.path.exists(p):
                dpl_path = p
                break

    if not os.path.exists(dpl_path):
        return None, None

    # 2. 기준 시간 설정 🕒
    if last_mtime is None:
        try: last_mtime = os.path.getmtime(dpl_path)
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

    # 3. 수정 시점 감시 🕵️‍♂️📡
    global _g_last_seen_pot_title
    try:
        # [V61.17.1] 비차단 모드: 현재 상태만 체크하고 즉시 반환 🏎️
        if not blocking:
            _t = _get_potplayer_title(target_pid=target_pid)
            if _t:
                # [V142.10] AI냥 요청: 단독 재생 시에도 창 제목 기반 즉시 추출 🛰️
                return _get_sync_path_dpl(s, find_title=_t)
            else:
                # [직접 모드 폴백] 제목이 없을 경우 mtime 변화 시에만 추출 🕒
                cur_mtime = os.path.getmtime(dpl_path)
                if cur_mtime != last_mtime:
                    return _get_sync_path_direct(s)
                return None, last_mtime

        # [V21.6] AI냥 요청: 팟플이 아닐 때(음악 등)는 5초 후 조용히 포기냥! 🤫
        _start_wait = time.time()
        while not is_potplayer_running(target_pid=target_pid):
            # [V164.20] target_pid로 못 찾더라도 팟플레이어가 전체적으로 실행 중이면 target_pid를 None으로 전환하여 계속 감시! 🎯
            if is_potplayer_running():
                target_pid = None
                break
            if time.time() - _start_wait > 5.0: 
                _log_to_file(" 🛡️ [Monitor] PotPlayer start wait timeout. Player is likely not PotPlayer.")
                return None, -1
            time.sleep(0.1)

        # [V128.9] AI냥 요청: 재생 중에는 창 제목만 가볍게 캐싱냥! 🕵️‍♂️🔭
        # [V134.5] 제너릭 제목 방어막 강화 🛡️⚓ (더 깐깐하게 무시하여 실제 파일명을 사수한다냥!)
        generic_names = ["PotPlayer", "PotPlayer64", "PotPlayerMini64", "팟플레이어", "PotPlayer Mini"]
        _last_dpl_guard_check_t = 0
        while is_potplayer_running(target_pid=target_pid):
            curr_t = _get_potplayer_title(target_pid=target_pid)
            if curr_t:
                ct_clean = curr_t.strip()
                # 1. 완전 일치 목록 제외
                if any(g == ct_clean for g in generic_names): pass
                # 2. '팟플레이어'라는 글자만 있거나 너무 짧은 제목 방어
                elif ct_clean in ["팟플레이어", "PotPlayer"] or len(ct_clean) < 5: pass
                else:
                    _g_last_seen_pot_title = curr_t

            # 🛡️ [비누님 요청] 플리 재생 중 모든 자료가 삭제/고갈되었을 때 안전 처리 가드! 🛑
            # [V171.5] 🚫 "팟플레이어 강제 종료"를 이 가드에서 완전 제거했습니다! (비누님 실제 사고: 팟플이 자꾸 꺼짐) 💥
            #   이전엔 아래 두 경우에 _kill_potplayer()로 팟플을 죽였는데,
            #     ① 플리 파일이 모두 삭제됨         → 사용자가 일부러 틀어놓은 영상이 끌려감 (과잉 개입)
            #     ② 슬롯1/2 중 '다른 슬롯' 영상을 재생 → 앱의 정상 기능(🔀 슬롯 전환)과 정면 충돌! (자기모순)
            #        실제 로그: '🚨 [Playlist Guard] 다른 플리 침범 감지: Curly-Haired Babe...' → 팟플레이어 종료 💥
            #   🐾 원칙: "자동 신호는 최소 단위로, 사용자 명시 행동은 범위 전체로"
            #      → 자동 가드는 **추적만 해제**하고 팟플레이어는 절대 건드리지 않는다! (사용자 재생 존중)
            now_t = time.time()
            if is_dpl_mode and (now_t - _last_dpl_guard_check_t >= 0.4):
                _last_dpl_guard_check_t = now_t
                dpl_paths = globals().get('_g_potplayer_dpl_paths') or []
                if dpl_paths:
                    alive_files = [p for p in dpl_paths if os.path.exists(p)]
                    _guard_break = False
                    # 1) 현재 플리의 모든 파일이 디스크에서 삭제되어 남은 파일이 0개인 경우
                    if not alive_files:
                        _log_to_file("🛑 [Playlist Guard] 현재 플리의 모든 파일이 삭제되어 비어있습니다. 플리 추적만 해제합니다! (팟플레이어는 그대로 재생 유지) 🛡️")
                        globals()['_last_bg_notification'] = "🛑 플리 자료가 모두 삭제되어 플리 추적을 해제했어요! (재생은 계속됩니다) 🛡️"
                        globals()['_g_potplayer_dpl_paths'] = []
                        _guard_break = True
                    # [V171.5] 2) 파일이 남아있지만 팟플레이어가 현재 플리 밖의 다른 파일을 재생하는 경우
                    #   🚫 이전: "다른 슬롯이면 침범"으로 보고 _kill_potplayer() → 팟플레이어 강제 종료 (자기모순 버그!)
                    #   ✅ 이제: 플리 추적만 해제. 팟플레이어는 절대 건드리지 않는다!
                    #      (다른 슬롯 영상 재생은 앱의 정상 기능, 유튜브 등은 애초에 추적 대상이 아님)
                    elif _g_last_seen_pot_title:
                        norm_curr_title = re.sub(r'[^\w]', '', _g_last_seen_pot_title).lower()
                        in_current_dpl = any(
                            re.sub(r'[^\w]', '', os.path.splitext(os.path.basename(p))[0]).lower() in norm_curr_title
                            for p in alive_files
                        )
                        if not in_current_dpl:
                            _log_to_file(f"🛡️ [Playlist Guard] 현재 플리 밖 영상 재생 감지: '{os.path.basename(_g_last_seen_pot_title)}' → 플리 추적만 해제합니다! (팟플레이어 유지) 🎬")
                            globals()['_g_potplayer_dpl_paths'] = []
                            globals()['_last_bg_notification'] = f"🛡️ 플리 추적 해제됨 (재생은 계속): {os.path.basename(_g_last_seen_pot_title)}"
                            _guard_break = True
                    if _guard_break:
                        globals()['_g_potplayer_is_dpl_mode'] = False
                        globals()['_last_bg_notification_time'] = time.time()
                        globals()['_global_menu_redraw_flag'] = True
                        # [V171.5] ⚠️ 여기서 break/continue 하지 않는다! (두 가지 이유) 🛡️
                        #   1) continue 하면 하단 time.sleep(0.1)을 건너뛰어 **바지락(busy) 루프**가 된다.
                        #   2) break 하면 감시 스레드가 죽어 '팟플 따봉/카트' 전역 단축키와 팟플 종료 감시가 함께 사라진다.
                        #   → 그냥 다음 반복으로 넘어가면 된다. _g_potplayer_dpl_paths가 []가 되었으므로
                        #     다음 iteration부터 `if dpl_paths:`가 False가 되어 가드는 자연히 조용해진다. 🧘
                        #     (아래 time.sleep(0.1)도 정상 실행되어 CPU 점유도 없음)

            # [V20.6] 종료 감지 반응 속도 상향 (1.0s -> 0.1s) ⚡
            time.sleep(0.1)

        # [V128.9] 팟플 종료 확인! 이제 딱 한 번만 역추적 실행냥! 🕒🎯🛸
        if _g_last_seen_pot_title:
            _log_to_file(f"🏁 [Exit Sync] PotPlayer exited. Resolving title: {_g_last_seen_pot_title}")
            _f_path, _ = _get_sync_path_dpl(s, find_title=_g_last_seen_pot_title)
            _g_last_seen_pot_title = None # 사용 후 초기화
            if _f_path: return _f_path, time.time()

        # [V142.9] AI냥 요청: 종료 후 DPL 파일에서 정보를 가져오는 로직 주석 처리 🚫🛑
        # 이제 실시간 창 제목 감시(_g_last_seen_pot_title) 방식으로만 최종 파일을 확정합니다냥!
        # _p, _ = _get_sync_path_direct(s)
        # _log_to_file(f"🏁 [_wait_for_potplayer_exit] PotPlayer exited. Final DPL path: {_p}")
        # return _p, time.time()

        _log_to_file("🏁 [_wait_for_potplayer_exit] PotPlayer exited. (DPL Direct Sync Disabled)")
        if not globals().get('_g_is_switching_media'):
            try: _sync_auto_playlist_dpl_on_exit()
            except Exception: pass
        return None, time.time()
    except Exception as e:
        _log_to_file(f"❌ [_wait_for_potplayer_exit] Error: {e}")
        return None, last_mtime


# [TAG: #@_resilient_startfile]
def _resilient_startfile(path, ptype='v'):
    """[V8.12] os.startfile이 실패(연결 앱 깨짐)할 경우를 대비하여 타입별 플레이어를 직접 찾아 실행하는 폴백 유틸리티 🛡️✨
    ptype: 'v' (Video), 'm' (Music)
    """
    try:
        # [선행 백업] DPL 백업은 선행 루틴에서 전담하므로 일반 파일 실행 시에만 복원 상태 해제 🛑
        try:
            if not str(path).lower().endswith(('.dpl', '.m3u', '.m3u8')):
                _clear_media_restore_state()
        except Exception: pass

        # [신규] 폴더 재생 시 볼륨 자동 조절 적용 🔊✨
        _apply_folder_auto_volume(path)
        # 1차 시도: 시스템 기본 앱 실행
        os.startfile(path)
        return True
    except Exception as e:
        _log_to_file(f"⚠️ [Resilient Startfile] os.startfile failed: {e}")

        # 2차 시도: 주요 플레이어 폴백 (사용자님 요청: 음악/영상 앱 구분)
        pot_path = r"C:\Program Files\DAUM\PotPlayer\PotPlayer64.exe"
        vlc_path = r"C:\Program Files\VideoLAN\VLC\vlc.exe"
        aimp_path = r"C:\Program Files (x86)\AIMP\AIMP.exe" # AIMP 표준 경로 후보

        # [V8.12] 음악일 때 AIMP 우선 순위, 영상일 때 팟플 우선 순위 🏹
        candidates = []
        if ptype == 'm':
            candidates = [aimp_path, pot_path, vlc_path]
        else:
            candidates = [pot_path, vlc_path]

        for player in candidates:
            if player and os.path.exists(player):
                try:
                    subprocess.Popen([player, path])
                    _log_to_file(f"🚀 [Resilient Startfile] Fallback to player: {player}")
                    return True
                except: continue

        # 모든 시도 실패 시 에러 재발생 (상단 핸들러에서 텔레그램 알림용)
        raise e


# [TAG: #@_set_clipboard_text]
def _set_clipboard_text__REMOVE_TARGET(text: str) -> bool:
    """[V161.0] 다단계 폴백(ctypes -> clip.exe -> tkinter)을 지원하는 범용 클립보드 복사 유틸리티 📋✨"""
    if not text:
        return False
        
    success = False
    
    # 1단계: ctypes 기반 윈도우 네이티브 API (가장 강력)
    try:
        import ctypes
        CF_UNICODETEXT = 13
        GMEM_MOVEABLE = 0x0002
        user32 = ctypes.windll.user32
        kernel32 = ctypes.windll.kernel32

        # 클립보드 원시기 정화
        try:
            user32.OpenClipboard(None)
            user32.EmptyClipboard()
            user32.CloseClipboard()
        except: pass

        text_utf16 = text.encode('utf-16le') + b'\x00\x00'
        if user32.OpenClipboard(None):
            try:
                user32.EmptyClipboard()
                h_global = kernel32.GlobalAlloc(GMEM_MOVEABLE, len(text_utf16))
                if h_global:
                    lp_global = kernel32.GlobalLock(h_global)
                    if lp_global:
                        ctypes.memmove(lp_global, text_utf16, len(text_utf16))
                        kernel32.GlobalUnlock(h_global)
                        if user32.SetClipboardData(CF_UNICODETEXT, h_global):
                            success = True
            finally:
                user32.CloseClipboard()
    except Exception as e:
        _log_to_file(f"⚠️ [Native Clipboard Error] {e}")

    # 2단계: Windows clip.exe (백업)
    if not success:
        try:
            subprocess.run(['clip'], input=text.encode('utf-16le'), check=True, creationflags=0x08000000)
            success = True
        except Exception as e:
            _log_to_file(f"⚠️ [clip.exe Clipboard Error] {e}")

    # 3단계: tkinter 방식 (호환성)
    if not success:
        try:
            import tkinter as tk
            root = tk.Tk()
            root.withdraw()
            root.clipboard_clear()
            root.clipboard_append(text)
            root.update()
            root.destroy()
            success = True
        except Exception as e:
            _log_to_file(f"⚠️ [tkinter Clipboard Error] {e}")

    return success


# [TAG: #@_get_tailscale_path]
def _get_tailscale_path__REMOVE_TARGET() -> Optional[str]:
    """Tailscale 실행 파일 경로 감지 윈도우 전용 🛡️"""
    import shutil
    ts_path = shutil.which("tailscale")
    if ts_path:
        return ts_path
    default_path = r"C:\Program Files\Tailscale\tailscale.exe"
    if os.path.exists(default_path):
        return default_path
    return None


# [TAG: #@_run_tailscale_cmd]
def _run_tailscale_cmd__REMOVE_TARGET(args: list) -> Tuple[int, str]:
    """Tailscale 명령어를 백그라운드로 실행하고 (리턴코드, 출력문자열) 반환 (충돌 시 자동 복구 재시도 탑재 🛡️)"""
    ts_path = _get_tailscale_path()
    if not ts_path:
        return -1, "Tailscale이 설치되어 있지 않거나 경로를 찾을 수 없습니다. ❌"
    
    # [TAG: #@_exec]

    def _exec(cmd_args):
        try:
            res = subprocess.run(
                [ts_path] + cmd_args,
                capture_output=True,
                text=True,
                creationflags=0x08000000,
                timeout=10,
                encoding='utf-8',
                errors='ignore'
            )
            return res.returncode, res.stdout.strip() + "\n" + res.stderr.strip()
        except subprocess.TimeoutExpired:
            return -9, "명령어 실행 시간 초과(Timeout) ❌"
        except Exception as e:
            return -9, f"오류 발생: {e} ❌"

    code, output = _exec(args)
    
    # [V161.5] Tailscale 'up' 시 기존 non-default flags 누락으로 인한 에러 발생 시 자동 구제냥! 🛡️✨
    if code != 0 and "requires mentioning all non-default flags" in output:
        suggested_flags = None
        # 개행으로 쪼개서 한줄씩 정밀 탐색냥!
        for line in output.split('\n'):
            line_clean = line.strip()
            if line_clean.startswith("tailscale up --"):
                suggested_flags = line_clean[len("tailscale up "):].strip()
                break
                
        if suggested_flags:
            import shlex
            try:
                retry_args = shlex.split(suggested_flags)
                _log_to_file(f"🔄 [Tailscale Auto Recovery] Detected conflict flags. Retrying with: {retry_args}")
                
                # 에러 메시지에서 제안받은 옵션들로 다시 실행
                retry_code, retry_output = _exec(retry_args)
                if retry_code == 0:
                    return 0, f"⚠️ 이전에 설정된 추가 옵션들이 자동 병합되어 실행되었습니다냥! (자동 복구 완료) 👍\n\n{retry_output}"
                else:
                    return retry_code, retry_output
            except Exception as ex:
                _log_to_file(f"⚠️ [Tailscale Auto Recovery Fail] {ex}")
                
    return code, output


# [TAG: #@_is_tailscale_running]
def _is_tailscale_running() -> bool:
    """Tailscale 클라이언트/데몬 프로세스 실행 여부 확인 🔌"""
    try:
        import psutil
        for proc in psutil.process_iter(['name']):
            pname = (proc.info.get('name') or '').lower()
            if pname in ('tailscaled.exe', 'tailscale.exe', 'tailscale-ipn.exe'):
                return True
    except Exception:
        try:
            out = subprocess.check_output('tasklist /FI "IMAGENAME eq tailscale*" /NH', shell=True, text=True, errors='ignore', creationflags=0x08000000)
            if "tailscale" in out.lower():
                return True
        except Exception:
            pass
    return False


# [TAG: #@_get_tailscale_ip]

def _get_tailscale_ip__REMOVE_TARGET() -> str:
    """현재 기기의 Tailscale IPv4 주소를 반환"""
    code, output = _run_tailscale_cmd(["ip", "-4"])
    if code == 0:
        lines = [line.strip() for line in output.strip().split("\n") if line.strip()]
        if lines:
            ip = lines[0]
            if ip and not ip.startswith("Tailscale") and not ip.startswith("Error"):
                return ip
    return "조회 실패"


# [TAG: #@_get_tailscale_status_dict]
def _get_tailscale_status_dict__REMOVE_TARGET() -> dict:
    """tailscale status --json 결과를 파싱하여 주요 상태 딕셔너리 반환"""
    status_dict = {
        "online": False,
        "ip": "조회 실패",
        "ssh": False,
        "exit_node_advertised": False,
        "exit_node_used": "미사용",
        "routes_advertised": []
    }
    
    code, output = _run_tailscale_cmd(["status", "--json"])
    if code != 0:
        return status_dict
        
    try:
        import json
        output_clean = output.strip()
        if not output_clean.startswith("{"):
            start_idx = output_clean.find("{")
            if start_idx != -1:
                output_clean = output_clean[start_idx:]
        
        if output_clean.startswith("{"):
            data = json.loads(output_clean)
            self_info = data.get("Self", {})
            status_dict["online"] = self_info.get("Online", False) or self_info.get("Active", False)
            
            ips = self_info.get("TailscaleIPs", [])
            ipv4s = [ip for ip in ips if ":" not in ip]
            if ipv4s:
                status_dict["ip"] = ipv4s[0]
                
            cap_map = self_info.get("CapMap", {})
            status_dict["ssh"] = "https://tailscale.com/cap/ssh" in cap_map
    except Exception as e:
        _log_to_file(f"⚠️ [Tailscale Status Parse Error] {e}")
        
    return status_dict


# [TAG: #@_get_local_subnets]
def _get_local_subnets__REMOVE_TARGET() -> list:
    """현재 기기의 모든 활성 네트워크 어댑터의 사설 IPv4 대역(예: 192.168.100.0/24) 목록 반환"""
    import socket
    subnets = []
    try:
        hostname = socket.gethostname()
        for ip in socket.gethostbyname_ex(hostname)[2]:
            parts = ip.split('.')
            if len(parts) == 4:
                if ip.startswith("127."):
                    continue
                if ip.startswith("100."):
                    try:
                        second_octet = int(parts[1])
                        if 64 <= second_octet <= 127:
                            continue
                    except: pass
                
                is_private = False
                if ip.startswith("10."):
                    is_private = True
                elif ip.startswith("192.168."):
                    is_private = True
                elif ip.startswith("172."):
                    try:
                        second_octet = int(parts[1])
                        if 16 <= second_octet <= 31:
                            is_private = True
                    except: pass
                
                if is_private:
                    subnet = f"{parts[0]}.{parts[1]}.{parts[2]}.0/24"
                    if subnet not in subnets:
                        subnets.append(subnet)
    except Exception as e:
        _log_to_file(f"⚠️ [Get Local Subnets Error] {e}")
    return subnets


# [TAG: #@_get_tailscale_peers]
def _get_tailscale_peers__REMOVE_TARGET() -> list:
    """현재 Tailscale 네트워크에 연결된 기기(Peer)들의 정보 리스트 반환"""
    peers = []
    code, output = _run_tailscale_cmd(["status", "--json"])
    if code != 0:
        return peers
    try:
        import json
        output_clean = output.strip()
        if not output_clean.startswith("{"):
            start_idx = output_clean.find("{")
            if start_idx != -1:
                output_clean = output_clean[start_idx:]
        if output_clean.startswith("{"):
            data = json.loads(output_clean)
            peer_data = data.get("Peer", {})
            for key, info in peer_data.items():
                hostname = info.get("HostName", "이름 없음")
                ips = info.get("TailscaleIPs", [])
                ipv4s = [ip for ip in ips if ":" not in ip]
                ip = ipv4s[0] if ipv4s else "IP 없음"
                os_type = info.get("OS", "unknown")
                online = info.get("Online", False) or info.get("Active", False)
                exit_node_opt = info.get("ExitNodeOption", False)
                
                peers.append({
                    "hostname": hostname,
                    "ip": ip,
                    "os": os_type,
                    "online": online,
                    "exit_node_opt": exit_node_opt
                })
    except Exception as e:
        _log_to_file(f"⚠️ [Get Tailscale Peers Error] {e}")
    return peers

# [TAG: #@_set_clipboard_text]
def _set_clipboard_text__REMOVE_TARGET(text: str) -> bool:
    """[V161.0] 다단계 폴백(ctypes -> clip.exe -> tkinter)을 지원하는 범용 클립보드 복사 유틸리티 📋✨"""
    if not text:
        return False
        
    success = False
    
    # 1단계: ctypes 기반 윈도우 네이티브 API (가장 강력)
    try:
        import ctypes
        CF_UNICODETEXT = 13
        GMEM_MOVEABLE = 0x0002
        user32 = ctypes.windll.user32
        kernel32 = ctypes.windll.kernel32

        # 클립보드 원시기 정화
        try:
            user32.OpenClipboard(None)
            user32.EmptyClipboard()
            user32.CloseClipboard()
        except: pass

        text_utf16 = text.encode('utf-16le') + b'\x00\x00'
        if user32.OpenClipboard(None):
            try:
                user32.EmptyClipboard()
                h_global = kernel32.GlobalAlloc(GMEM_MOVEABLE, len(text_utf16))
                if h_global:
                    lp_global = kernel32.GlobalLock(h_global)
                    if lp_global:
                        ctypes.memmove(lp_global, text_utf16, len(text_utf16))
                        kernel32.GlobalUnlock(h_global)
                        if user32.SetClipboardData(CF_UNICODETEXT, h_global):
                            success = True
            finally:
                user32.CloseClipboard()
    except Exception as e:
        _log_to_file(f"⚠️ [Native Clipboard Error] {e}")

    # 2단계: Windows clip.exe (백업)
    if not success:
        try:
            subprocess.run(['clip'], input=text.encode('utf-16le'), check=True, creationflags=0x08000000)
            success = True
        except Exception as e:
            _log_to_file(f"⚠️ [clip.exe Clipboard Error] {e}")

    # 3단계: tkinter 방식 (호환성)
    if not success:
        try:
            import tkinter as tk
            root = tk.Tk()
            root.withdraw()
            root.clipboard_clear()
            root.clipboard_append(text)
            root.update()
            root.destroy()
            success = True
        except Exception as e:
            _log_to_file(f"⚠️ [tkinter Clipboard Error] {e}")

    return success


# [TAG: #@_get_tailscale_path]
def _get_tailscale_path__REMOVE_TARGET() -> Optional[str]:
    """Tailscale 실행 파일 경로 감지 윈도우 전용 🛡️"""
    import shutil
    ts_path = shutil.which("tailscale")
    if ts_path:
        return ts_path
    default_path = r"C:\Program Files\Tailscale\tailscale.exe"
    if os.path.exists(default_path):
        return default_path
    return None


# [TAG: #@_run_tailscale_cmd]
def _run_tailscale_cmd__REMOVE_TARGET(args: list) -> Tuple[int, str]:
    """Tailscale 명령어를 백그라운드로 실행하고 (리턴코드, 출력문자열) 반환 (충돌 시 자동 복구 재시도 탑재 🛡️)"""
    ts_path = _get_tailscale_path()
    if not ts_path:
        return -1, "Tailscale이 설치되어 있지 않거나 경로를 찾을 수 없습니다. ❌"
    
    # [TAG: #@_exec]

    def _exec(cmd_args):
        try:
            res = subprocess.run(
                [ts_path] + cmd_args,
                capture_output=True,
                text=True,
                creationflags=0x08000000,
                timeout=10,
                encoding='utf-8',
                errors='ignore'
            )
            return res.returncode, res.stdout.strip() + "\n" + res.stderr.strip()
        except subprocess.TimeoutExpired:
            return -9, "명령어 실행 시간 초과(Timeout) ❌"
        except Exception as e:
            return -9, f"오류 발생: {e} ❌"

    code, output = _exec(args)
    
    # [V161.5] Tailscale 'up' 시 기존 non-default flags 누락으로 인한 에러 발생 시 자동 구제냥! 🛡️✨
    if code != 0 and "requires mentioning all non-default flags" in output:
        import re
        output_clean = output.replace('\r', '')
        match = re.search(r'tailscale up\s+(--\S+.*)$', output_clean, re.MULTILINE)
        if match:
            suggested_flags = match.group(1).strip()
            import shlex
            try:
                retry_args = shlex.split(suggested_flags)
                _log_to_file(f"🔄 [Tailscale Auto Recovery] Detected conflict flags. Retrying with: {retry_args}")
                
                # 에러 메시지에서 제안받은 옵션들로 다시 실행
                retry_code, retry_output = _exec(retry_args)
                if retry_code == 0:
                    return 0, f"⚠️ 이전에 설정된 추가 옵션들이 자동 병합되어 실행되었습니다냥! (자동 복구 완료) 👍\n\n{retry_output}"
                else:
                    return retry_code, retry_output
            except Exception as ex:
                _log_to_file(f"⚠️ [Tailscale Auto Recovery Fail] {ex}")
                
    return code, output


# [TAG: #@_get_tailscale_ip]
def _get_tailscale_ip__REMOVE_TARGET() -> str:
    """현재 기기의 Tailscale IPv4 주소를 반환"""
    code, output = _run_tailscale_cmd(["ip", "-4"])
    if code == 0:
        lines = [line.strip() for line in output.strip().split("\n") if line.strip()]
        if lines:
            ip = lines[0]
            if ip and not ip.startswith("Tailscale") and not ip.startswith("Error"):
                return ip
    return "조회 실패"


# [TAG: #@_get_tailscale_status_dict]
def _get_tailscale_status_dict__REMOVE_TARGET() -> dict:
    """tailscale status --json 결과를 파싱하여 주요 상태 딕셔너리 반환"""
    status_dict = {
        "online": False,
        "ip": "조회 실패",
        "ssh": False,
        "exit_node_advertised": False,
        "exit_node_used": "미사용",
        "routes_advertised": []
    }
    
    code, output = _run_tailscale_cmd(["status", "--json"])
    if code != 0:
        return status_dict
        
    try:
        import json
        output_clean = output.strip()
        if not output_clean.startswith("{"):
            start_idx = output_clean.find("{")
            if start_idx != -1:
                output_clean = output_clean[start_idx:]
        
        if output_clean.startswith("{"):
            data = json.loads(output_clean)
            self_info = data.get("Self", {})
            status_dict["online"] = self_info.get("Online", False) or self_info.get("Active", False)
            
            ips = self_info.get("TailscaleIPs", [])
            ipv4s = [ip for ip in ips if ":" not in ip]
            if ipv4s:
                status_dict["ip"] = ipv4s[0]
                
            cap_map = self_info.get("CapMap", {})
            status_dict["ssh"] = "https://tailscale.com/cap/ssh" in cap_map
    except Exception as e:
        _log_to_file(f"⚠️ [Tailscale Status Parse Error] {e}")
        
    return status_dict


# [TAG: #@_get_local_subnets]
def _get_local_subnets__REMOVE_TARGET() -> list:
    """현재 기기의 모든 활성 네트워크 어댑터의 사설 IPv4 대역(예: 192.168.100.0/24) 목록 반환"""
    import socket
    subnets = []
    try:
        hostname = socket.gethostname()
        for ip in socket.gethostbyname_ex(hostname)[2]:
            parts = ip.split('.')
            if len(parts) == 4:
                if ip.startswith("127."):
                    continue
                if ip.startswith("100."):
                    try:
                        second_octet = int(parts[1])
                        if 64 <= second_octet <= 127:
                            continue
                    except: pass
                
                is_private = False
                if ip.startswith("10."):
                    is_private = True
                elif ip.startswith("192.168."):
                    is_private = True
                elif ip.startswith("172."):
                    try:
                        second_octet = int(parts[1])
                        if 16 <= second_octet <= 31:
                            is_private = True
                    except: pass
                
                if is_private:
                    subnet = f"{parts[0]}.{parts[1]}.{parts[2]}.0/24"
                    if subnet not in subnets:
                        subnets.append(subnet)
    except Exception as e:
        _log_to_file(f"⚠️ [Get Local Subnets Error] {e}")
    return subnets


# [TAG: #@_get_tailscale_peers]
def _get_tailscale_peers__REMOVE_TARGET() -> list:
    """현재 Tailscale 네트워크에 연결된 기기(Peer)들의 정보 리스트 반환"""
    peers = []
    code, output = _run_tailscale_cmd(["status", "--json"])
    if code != 0:
        return peers
    try:
        import json
        output_clean = output.strip()
        if not output_clean.startswith("{"):
            start_idx = output_clean.find("{")
            if start_idx != -1:
                output_clean = output_clean[start_idx:]
        if output_clean.startswith("{"):
            data = json.loads(output_clean)
            peer_data = data.get("Peer", {})
            for key, info in peer_data.items():
                hostname = info.get("HostName", "이름 없음")
                ips = info.get("TailscaleIPs", [])
                ipv4s = [ip for ip in ips if ":" not in ip]
                ip = ipv4s[0] if ipv4s else "IP 없음"
                os_type = info.get("OS", "unknown")
                online = info.get("Online", False) or info.get("Active", False)
                exit_node_opt = info.get("ExitNodeOption", False)
                
                peers.append({
                    "hostname": hostname,
                    "ip": ip,
                    "os": os_type,
                    "online": online,
                    "exit_node_opt": exit_node_opt
                })
    except Exception as e:
        _log_to_file(f"⚠️ [Get Tailscale Peers Error] {e}")
    return peers


# [TAG: #@_is_private_ip]

def _is_private_ip(ip_str: str) -> bool:
    """주어진 IP 주소가 사설 IP, 루프백, CGNAT 또는 링크 로컬 주소인지 검사"""
    if not ip_str or not isinstance(ip_str, str):
        return True
    ip_str = ip_str.strip()
    try:
        parts = [int(p) for p in ip_str.split('.')]
        if len(parts) != 4:
            return True
        # 127.0.0.0/8 (Loopback)
        if parts[0] == 127:
            return True
        # 10.0.0.0/8 (Private)
        if parts[0] == 10:
            return True
        # 172.16.0.0 ~ 172.31.255.255 (Private)
        if parts[0] == 172 and 16 <= parts[1] <= 31:
            return True
        # 192.168.0.0/16 (Private)
        if parts[0] == 192 and parts[1] == 168:
            return True
        # 100.64.0.0/10 (CGNAT / Tailscale)
        if parts[0] == 100 and 64 <= parts[1] <= 127:
            return True
        # 169.254.0.0/16 (Link-Local)
        if parts[0] == 169 and parts[1] == 254:
            return True
        return False
    except Exception:
        return True


# [TAG: #@_is_gateway_ip]
def _is_gateway_ip(ip_str) -> bool:
    """공유기 게이트웨이 IP(사설 대역 끝자리 .1 — 예: 192.168.100.1, 192.168.0.1, 10.0.0.1, 172.16.0.1)인지 판별한다 🌐🛡️
    · 공유기 포트포워딩 / NAT 헤어핀(루프백)으로 외부 도메인(예: forsys01.iptime.org)이나 공인 IP를 타고 들어오면
      서버 입장에서는 송신자 IP(remote_addr)가 공유기 게이트웨이(.1)로 찍힌다.
    · 따라서 사설 대역이라도 끝자리가 `.1` 인 게이트웨이 IP(단, 127.0.0.1 루프백 제외)는
      **외부 접근 IP** 로 간주하여 평문 `?k=` 사용을 차단하고 `?t=` 토큰만 허용해야 한다!"""
    try:
        ip = str(ip_str or '').strip()
        parts = [int(p) for p in ip.split('.')]
        if len(parts) != 4:
            return False
        if parts[0] == 127:
            return False  # 127.0.0.1 루프백은 로컬 자기 자신
        if parts[3] != 1:
            return False
        if parts[0] == 10:
            return True
        if parts[0] == 172 and 16 <= parts[1] <= 31:
            return True
        if parts[0] == 192 and parts[1] == 168:
            return True
        return False
    except Exception:
        return False


# [TAG: #@_is_internal_client_ip]
def _is_internal_client_ip(ip_str) -> bool:
    """요청이 '내부망(사설/루프백/Tailscale)' 에서 오는지 판별한다 🛡️
    · 내부망 → 예전처럼 `?k=<비밀번호>` 사용 허용 (LAN 안이라 6자리 노출 위험이 낮다)
    · 외부망 / 공유기 게이트웨이(.1) → `?t=<서명토큰>` 만 허용. 평문 k 는 '주소창·기록·로그' 에 남으므로 차단한다.
    · ⚠️ 공유기 게이트웨이 IP(사설 끝자리 `.1`, 예: `192.168.100.1`)는 포트포워딩/NAT 헤어핀(외부 도메인·공인 IP 경유)
       진입점이므로 **외부망(False)** 으로 판정한다! (127.0.0.1 루프백은 제외)
    · ⚠️ IPv6 을 _is_private_ip 에 넘기면 '4자리가 아니므로 사설로 간주' 되어
       외부 IPv6 접근이 k 를 쓸 수 있는 구멍이 된다. 그래서 여기서 IPv6 을 직접 처리한다.
    · 알 수 없는 IP('unknown'/빈값)는 **외부망(fail-closed)** 으로 본다. 🛡️"""
    ip = str(ip_str or '').strip()
    if not ip or ip.lower() == 'unknown':
        _log_to_file("🟡 [Security] 클라이언트 IP 확인 불가 → 외부망(보수적)으로 판정. ?t= 토큰 링크를 쓰세요.")
        return False
    if ip.lower() in ('localhost', 'localhost.localdomain'):
        return True
    if ':' in ip:   # ── IPv6 ──
        low = ip.lower()
        if low in ('::1', '::'):
            return True                             # 루프백
        if low.startswith(('fc', 'fd')):
            return True                             # ULA (fc00::/7)
        if low.startswith('fe8') or low.startswith('fe9') \
           or low.startswith('fea') or low.startswith('feb'):
            return True                             # 링크로컬 (fe80::/10)
        return False                                # 그 외 = 전역 주소 = 외부망
    # ⚠️ '숫자 4자리가 아닌' 것 = 호스트명(예: forsys01.iptime.org)이다. 반드시 외부망으로 봐야 한다.
    if ip.count('.') != 3:
        return False
    # 🚫 공유기 게이트웨이(.1) 타고 들어온 요청은 외부 접근(포트포워딩/NAT 루프백)이므로 내부망에서 제외!
    if _is_gateway_ip(ip):
        return False
    return _is_private_ip(ip)


# [TAG: #@_get_real_client_ip_global]
def _get_real_client_ip(req=None) -> str:
    """🌐 요청 헤더(X-Forwarded-For, X-Real-IP, CF-Connecting-IP) 및 remote_addr 분석을 통한
    실제 클라이언트 IP 추출 헬퍼 (전역 함수 — _page_server_key 등 어디서나 호출 가능) 🛡️✨"""
    try:
        r = req
        if r is None:
            from flask import request as r
        fwd = r.headers.get('X-Forwarded-For') if hasattr(r, 'headers') else None
        if fwd:
            ips = [p.strip() for p in str(fwd).split(',') if p.strip()]
            for ip_item in ips:
                if ip_item and ip_item not in ('127.0.0.1', '::1', 'localhost'):
                    return ip_item
            if ips:
                return ips[0]
        real = (r.headers.get('X-Real-IP') if hasattr(r, 'headers') else None)
        if real and str(real).strip():
            return str(real).strip()
        cf = (r.headers.get('CF-Connecting-IP') if hasattr(r, 'headers') else None)
        if cf and str(cf).strip():
            return str(cf).strip()
        addr = getattr(r, 'remote_addr', '')
        if addr and str(addr).strip():
            return str(addr).strip()
        return 'unknown'
    except Exception:
        return 'unknown'


# [TAG: #@_is_internal_http_request]
def _is_internal_http_request(req=None, client_ip=None) -> bool:
    """현재 HTTP 요청이 순수 내부망 접근인지 판별한다 🛡️
    1) 클라이언트 IP가 내부망이어야 함 (공유기 게이트웨이 `.1` 제외)
    2) 브라우저가 접속한 Host 헤더(예: `forsys01.iptime.org:5000`, `175.253.249.106:5000`)가
       외부 도메인/공인 IP/게이트웨이(`.1`)이면, 설령 LAN 내부에서 호출했더라도 **외부 접근(False)** 으로 간주하여
       `?k=` 평문 키 사용을 차단하고 `?t=` 토큰만 허용한다!"""
    try:
        r = req
        if r is None:
            from flask import request as r
        ip = client_ip if client_ip is not None else _get_real_client_ip(r)
        if not _is_internal_client_ip(ip):
            return False
        host_hdr = ''
        if hasattr(r, 'headers'):
            host_hdr = (r.headers.get('X-Forwarded-Host') or r.headers.get('Host') or getattr(r, 'host', '') or '').strip()
        elif hasattr(r, 'host'):
            host_hdr = str(getattr(r, 'host', '') or '').strip()
        if host_hdr:
            h = host_hdr.split(',')[0].strip()
            if h.startswith('['):
                h = h.split(']')[0].lstrip('[')
            else:
                h = h.split(':')[0].strip()
            if h and not _is_internal_client_ip(h):
                return False
        return True
    except Exception:
        return False


# [TAG: #@_is_using_public_ip_directly]
def _is_using_public_ip_directly__REMOVE_TARGET() -> bool:
    """현재 PC의 1순위 대표 어댑터가 공유기 내부망(사설 IP)을 거치지 않고 공인 IP를 직접 사용 중인지 판별냥! 🌐"""
    import socket
    # 1단계: 실제 인터넷 통신(아웃바운드 라우팅 메트릭 1순위) 소켓 local IP 확인
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.settimeout(2.0)
        s.connect(("1.1.1.1", 80))
        primary_local_ip = s.getsockname()[0]
        s.close()
        if primary_local_ip and not _is_private_ip(primary_local_ip):
            return True
    except Exception:
        pass

    # 2단계: 메트릭 최우선 순위 물리 어댑터 IP 확인
    try:
        adapters = _get_physical_adapters()
        valid = [a for a in adapters if a.get("Status") == "Up" and a.get("IPv4Address")]
        if valid:
            sorted_adj = sorted(
                valid,
                key=lambda x: x.get("InterfaceMetric") if x.get("InterfaceMetric") is not None else 9999
            )
            main_ip = sorted_adj[0].get("IPv4Address")
            if main_ip and not _is_private_ip(main_ip):
                return True
    except Exception:
        pass

    return False


# [TAG: #@_set_clipboard_text]
def _set_clipboard_text__REMOVE_TARGET(text: str) -> bool:
    """[V161.0] 다단계 폴백(ctypes -> clip.exe -> tkinter)을 지원하는 범용 클립보드 복사 유틸리티 📋✨"""
    if not text:
        return False
        
    success = False
    
    # 1단계: ctypes 기반 윈도우 네이티브 API (가장 강력)
    try:
        import ctypes
        CF_UNICODETEXT = 13
        GMEM_MOVEABLE = 0x0002
        user32 = ctypes.windll.user32
        kernel32 = ctypes.windll.kernel32

        # 클립보드 원시기 정화
        try:
            user32.OpenClipboard(None)
            user32.EmptyClipboard()
            user32.CloseClipboard()
        except: pass

        text_utf16 = text.encode('utf-16le') + b'\x00\x00'
        if user32.OpenClipboard(None):
            try:
                user32.EmptyClipboard()
                h_global = kernel32.GlobalAlloc(GMEM_MOVEABLE, len(text_utf16))
                if h_global:
                    lp_global = kernel32.GlobalLock(h_global)
                    if lp_global:
                        ctypes.memmove(lp_global, text_utf16, len(text_utf16))
                        kernel32.GlobalUnlock(h_global)
                        if user32.SetClipboardData(CF_UNICODETEXT, h_global):
                            success = True
            finally:
                user32.CloseClipboard()
    except Exception as e:
        _log_to_file(f"⚠️ [Native Clipboard Error] {e}")

    # 2단계: Windows clip.exe (백업)
    if not success:
        try:
            subprocess.run(['clip'], input=text.encode('utf-16le'), check=True, creationflags=0x08000000)
            success = True
        except Exception as e:
            _log_to_file(f"⚠️ [clip.exe Clipboard Error] {e}")

    # 3단계: tkinter 방식 (호환성)
    if not success:
        try:
            import tkinter as tk
            root = tk.Tk()
            root.withdraw()
            root.clipboard_clear()
            root.clipboard_append(text)
            root.update()
            root.destroy()
            success = True
        except Exception as e:
            _log_to_file(f"⚠️ [tkinter Clipboard Error] {e}")

    return success


# [TAG: #@_get_tailscale_path]
def _get_tailscale_path__REMOVE_TARGET() -> Optional[str]:
    """Tailscale 실행 파일 경로 감지 윈도우 전용 🛡️"""
    import shutil
    ts_path = shutil.which("tailscale")
    if ts_path:
        return ts_path
