# [TAG: #@_is_using_public_ip_directly]
def _is_using_public_ip_directly__REMOVE_TARGET() -> bool:
    """현재 PC의 1순위 대표 어댑터가 공유기 내부망(사설 IP)을 거치지 않고 공인 IP를 직접 사용 중인지 판별냥! 🌐"""
    import socket
    # 1단계: 실제 인터넷 통신(아웃바운드 라우팅 메트릭 1순위) 소켓 local IP 확인
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.settimeout(2.0)
        s.connect(("1.1.1.1", 80))
        primary_local_ip = s.getsockname()[0]
        s.close()
        if primary_local_ip and not _is_private_ip(primary_local_ip):
            return True
    except Exception:
        pass

    # 2단계: 메트릭 최우선 순위 물리 어댑터 IP 확인
    try:
        adapters = _get_physical_adapters()
        valid = [a for a in adapters if a.get("Status") == "Up" and a.get("IPv4Address")]
        if valid:
            sorted_adj = sorted(
                valid,
                key=lambda x: x.get("InterfaceMetric") if x.get("InterfaceMetric") is not None else 9999
            )
            main_ip = sorted_adj[0].get("IPv4Address")
            if main_ip and not _is_private_ip(main_ip):
                return True
    except Exception:
        pass

    return False


# [TAG: #@_set_clipboard_text]
def _set_clipboard_text(text: str) -> bool:
    """[V161.0] 다단계 폴백(ctypes -> clip.exe -> tkinter)을 지원하는 범용 클립보드 복사 유틸리티 📋✨"""
    if not text:
        return False
        
    success = False
    
    # 1단계: ctypes 기반 윈도우 네이티브 API (가장 강력)
    try:
        import ctypes
        CF_UNICODETEXT = 13
        GMEM_MOVEABLE = 0x0002
        user32 = ctypes.windll.user32
        kernel32 = ctypes.windll.kernel32

        # 클립보드 원시기 정화
        try:
            user32.OpenClipboard(None)
            user32.EmptyClipboard()
            user32.CloseClipboard()
        except: pass

        text_utf16 = text.encode('utf-16le') + b'\x00\x00'
        if user32.OpenClipboard(None):
            try:
                user32.EmptyClipboard()
                h_global = kernel32.GlobalAlloc(GMEM_MOVEABLE, len(text_utf16))
                if h_global:
                    lp_global = kernel32.GlobalLock(h_global)
                    if lp_global:
                        ctypes.memmove(lp_global, text_utf16, len(text_utf16))
                        kernel32.GlobalUnlock(h_global)
                        if user32.SetClipboardData(CF_UNICODETEXT, h_global):
                            success = True
            finally:
                user32.CloseClipboard()
    except Exception as e:
        _log_to_file(f"⚠️ [Native Clipboard Error] {e}")

    # 2단계: Windows clip.exe (백업)
    if not success:
        try:
            subprocess.run(['clip'], input=text.encode('utf-16le'), check=True, creationflags=0x08000000)
            success = True
        except Exception as e:
            _log_to_file(f"⚠️ [clip.exe Clipboard Error] {e}")

    # 3단계: tkinter 방식 (호환성)
    if not success:
        try:
            import tkinter as tk
            root = tk.Tk()
            root.withdraw()
            root.clipboard_clear()
            root.clipboard_append(text)
            root.update()
            root.destroy()
            success = True
        except Exception as e:
            _log_to_file(f"⚠️ [tkinter Clipboard Error] {e}")

    return success


