def _get_tailscale_fqdn() -> Optional[str]:
    """현재 기기의 Tailscale 정식 FQDN 도메인(예: binu-pc.tailnet-xyz.ts.net)을 반환 🌐"""
    code, output = _run_tailscale_cmd(["status", "--json"])
    if code != 0:
        return None
    try:
        import json
        output_clean = output.strip()
        if not output_clean.startswith("{"):
            start_idx = output_clean.find("{")
            if start_idx != -1:
                output_clean = output_clean[start_idx:]
        if output_clean.startswith("{"):
            data = json.loads(output_clean)
            self_info = data.get("Self", {})
            dns_name = self_info.get("DNSName", "").strip().rstrip(".")
            if dns_name:
                return dns_name
    except Exception as e:
        _log_to_file(f"⚠️ [Get Tailscale FQDN Error] {e}")
    return None


def _get_cert_dir() -> str:
    """SSL 보안 인증서 보관 디렉토리 (C:\\srt\\certs) 반환 및 폴더 자동 생성 📁"""
    cert_dir = os.path.join(BASE_DIR, "certs")
    os.makedirs(cert_dir, exist_ok=True)
    return cert_dir


_CERT_INSPECT_CACHE: dict = {}


def _inspect_cert_file(cert_path: str) -> Optional[dict]:
    """SSL 인증서 파일(.crt / .pem)의 유효기간, 만료일(D-Day), 도메인(SAN), 발급기관 등 정밀 검사 🔍 (mtime 캐시 지원)"""
    if not cert_path or not os.path.exists(cert_path):
        return None
    try:
        mtime = os.path.getmtime(cert_path)
        cached = _CERT_INSPECT_CACHE.get(cert_path)
        if cached and cached[0] == mtime:
            return cached[1]
    except Exception:
        mtime = 0

    try:
        _auto_install("cryptography", "cryptography", "SSL 인증서 분석용")
        from cryptography import x509
        from cryptography.x509.oid import NameOID, ExtensionOID
        import datetime
        
        with open(cert_path, "rb") as f:
            cert_data = f.read()
        cert = x509.load_pem_x509_certificate(cert_data)
        
        # 주체(Subject) & 발급자(Issuer)
        cn_attrs = cert.subject.get_attributes_for_oid(NameOID.COMMON_NAME)
        subject_cn = cn_attrs[0].value if cn_attrs else "알 수 없음"
        
        issuer_attrs = cert.issuer.get_attributes_for_oid(NameOID.ORGANIZATION_NAME) or cert.issuer.get_attributes_for_oid(NameOID.COMMON_NAME)
        issuer_str = issuer_attrs[0].value if issuer_attrs else "자체 서명"
        
        # 유효기간 계산 (신규 cryptography / 구버전 호환)
        now_utc = datetime.datetime.now(datetime.timezone.utc)
        
        not_after = getattr(cert, "not_valid_after_utc", None)
        if not_after is None:
            not_after = cert.not_valid_after
            if not_after.tzinfo is None:
                not_after = not_after.replace(tzinfo=datetime.timezone.utc)
        
        not_before = getattr(cert, "not_valid_before_utc", None)
        if not_before is None:
            not_before = cert.not_valid_before
            if not_before.tzinfo is None:
                not_before = not_before.replace(tzinfo=datetime.timezone.utc)
        
        days_left = (not_after.date() - now_utc.date()).days
        
        # SAN (Subject Alternative Names) 추출 → DNS / IP 분리 수집 🧩
        sans = []
        dns_names = []
        ip_addresses = []
        try:
            from cryptography import x509 as _x509
            san_ext = cert.extensions.get_extension_for_oid(ExtensionOID.SUBJECT_ALTERNATIVE_NAME)
            for name in san_ext.value:
                sans.append(str(name.value))
                if isinstance(name, _x509.IPAddress):
                    ip_addresses.append(str(name.value))
                else:
                    dns_names.append(str(name.value))
        except Exception:
            pass
        
        res = {
            "exists": True,
            "path": cert_path,
            "subject": subject_cn,
            "issuer": issuer_str,
            "not_before": not_before.strftime("%Y-%m-%d %H:%M:%S UTC"),
            "not_after": not_after.strftime("%Y-%m-%d %H:%M:%S UTC"),
            # [수정] 소비부(_menu_ssl_cert_manager)가 요구하는 *_str 키를 반드시 제공한다 🔑
            "not_before_str": not_before.strftime("%Y-%m-%d"),
            "not_after_str": not_after.strftime("%Y-%m-%d %H:%M:%S UTC"),
            "expire_date": not_after.strftime("%Y-%m-%d"),
            "days_left": days_left,
            "is_expired": days_left < 0,
            "sans": sans,
            "dns_names": dns_names,
            "ip_addresses": ip_addresses
        }
        if mtime > 0:
            _CERT_INSPECT_CACHE[cert_path] = (mtime, res)
        return res
    except Exception as e:
        _log_to_file(f"⚠️ [Cert Inspect Error] {e}")
        return None


def _issue_tailscale_cert(target_domain: Optional[str] = None) -> Tuple[bool, str, str, str]:
    """Tailscale 공식 Let's Encrypt 무료 공인 SSL 인증서를 원클릭으로 자동 발급/갱신 🔐"""
    if not target_domain:
        target_domain = _get_tailscale_fqdn()
    if not target_domain:
        return False, "Tailscale이 켜져 있지 않거나 MagicDNS/도메인을 조회할 수 없어냥. ❌", "", ""
    
    cert_dir = _get_cert_dir()
    cert_file = os.path.join(cert_dir, "tailscale.crt")
    key_file = os.path.join(cert_dir, "tailscale.key")
    
    # tailscale cert --cert-file ... --key-file ... <domain>
    args = ["cert", "--cert-file", cert_file, "--key-file", key_file, target_domain]
    code, out = _run_tailscale_cmd(args)
    if code == 0 and os.path.exists(cert_file):
        return True, f"Tailscale Let's Encrypt 공인 인증서 발급 성공! 🎉\n- 도메인: {target_domain}\n- 인증서: {cert_file}\n- 개인키: {key_file}", cert_file, key_file
    else:
        return False, f"인증서 발급 실패냥: {out}", "", ""


def _generate_universal_ssl_cert(cert_path: Optional[str] = None, key_path: Optional[str] = None, extra_domains: Optional[list] = None, extra_ips: Optional[list] = None) -> Tuple[bool, str, str, str]:
    """로컬 사설망, Tailscale, localhost 등을 포괄하는 10년 유효 멀티 SAN 자체 서명 SSL 인증서 원클릭 생성 🔑"""
    try:
        _auto_install("cryptography", "cryptography", "SSL 인증서 생성용")
        from cryptography import x509
        from cryptography.x509.oid import NameOID
        from cryptography.hazmat.primitives import hashes
        from cryptography.hazmat.primitives.asymmetric import rsa
        from cryptography.hazmat.primitives import serialization
        import datetime
        import ipaddress
        import socket

        cert_dir = _get_cert_dir()
        if not cert_path:
            cert_path = os.path.join(cert_dir, "self_signed.crt")
        if not key_path:
            key_path = os.path.join(cert_dir, "self_signed.key")

        private_key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
        hostname = socket.gethostname()
        
        subject = issuer = x509.Name([
            x509.NameAttribute(NameOID.COUNTRY_NAME, "KR"),
            x509.NameAttribute(NameOID.STATE_OR_PROVINCE_NAME, "Seoul"),
            x509.NameAttribute(NameOID.ORGANIZATION_NAME, "Binu AI Studio"),
            x509.NameAttribute(NameOID.COMMON_NAME, hostname or "127.0.0.1"),
        ])
        
        # SAN 리스트 자동 구성 (모든 로컬 IP + Tailscale IP + localhost + DuckDNS + 커스텀)
        san_items = []
        
        # 기본 IP
        ip_set = {"127.0.0.1"}
        # 로컬 어댑터 IP들
        try:
            for ip in socket.gethostbyname_ex(hostname)[2]:
                if ip and ":" not in ip:
                    ip_set.add(ip)
        except Exception:
            pass
        # Tailscale IP
        ts_ip = _get_tailscale_ip()
        if ts_ip and ts_ip != "조회 실패":
            ip_set.add(ts_ip)
        if extra_ips:
            for ip in extra_ips:
                if ip: ip_set.add(ip)
                
        for ip in ip_set:
            try:
                san_items.append(x509.IPAddress(ipaddress.ip_address(ip)))
            except Exception:
                pass
                
        # 기본 DNS 도메인
        dns_set = {"localhost"}
        if hostname:
            dns_set.add(hostname)
        ts_fqdn = _get_tailscale_fqdn()
        if ts_fqdn:
            dns_set.add(ts_fqdn)
        if extra_domains:
            for d in extra_domains:
                if d: dns_set.add(d)
                
        for d in dns_set:
            try:
                san_items.append(x509.DNSName(d))
            except Exception:
                pass

        cert = x509.CertificateBuilder().subject_name(
            subject
        ).issuer_name(
            issuer
        ).public_key(
            private_key.public_key()
        ).serial_number(
            x509.random_serial_number()
        ).not_valid_before(
            datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(days=1)
        ).not_valid_after(
            datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(days=3650)  # 10년 유효
        ).add_extension(
            x509.SubjectAlternativeName(san_items),
            critical=False,
        ).sign(private_key, hashes.SHA256())

        os.makedirs(os.path.dirname(cert_path), exist_ok=True)
        os.makedirs(os.path.dirname(key_path), exist_ok=True)

        with open(key_path, "wb") as f:
            f.write(private_key.private_bytes(
                encoding=serialization.Encoding.PEM,
                format=serialization.PrivateFormat.TraditionalOpenSSL,
                encryption_algorithm=serialization.NoEncryption()
            ))
            
        with open(cert_path, "wb") as f:
            f.write(cert.public_bytes(serialization.Encoding.PEM))
            
        return True, f"멀티 SAN 자체 서명 인증서 생성 완료! 🔑 (유효기간: 10년)\n- 포함된 IP: {', '.join(sorted(list(ip_set)))}\n- 포함된 도메인: {', '.join(sorted(list(dns_set)))}", cert_path, key_path
    except Exception as e:
        _log_to_file(f"❌ [SSL Gen Error] {e}")
        return False, f"인증서 생성 실패: {e}", "", ""


def _get_ssl_cert_summary_badge() -> str:
    """메인 메뉴 표시용 SSL 인증서 보유 상태 요약 배지 반환 🛡️"""
    cert_dir = os.path.join(BASE_DIR, "certs")
    ts_cert = os.path.join(cert_dir, "tailscale.crt")
    self_cert = os.path.join(cert_dir, "self_signed.crt")
    
    ts_info = _inspect_cert_file(ts_cert)
    self_info = _inspect_cert_file(self_cert)
    
    if ts_info and not ts_info["is_expired"]:
        return f"🟢 Tailscale 인증서 D-{ts_info['days_left']}"
    elif self_info and not self_info["is_expired"]:
        return "🟢 자체 서명 인증서 보유"
    else:
        return "⚪ 미발급"


def _tailscale_ping_peer(settings=None):
    """Tailscale 피어(타 기기) 선택 핑 진단 헬퍼 📶⚡"""
    peers = _get_tailscale_peers()
    if not peers:
        print(f"\n❌ {ctext('현재 등록되거나 온라인인 Tailscale 피어 기기를 찾지 못했습니다냥! Tailscale 연결을 확인해주세요.', C.RED)}")
        input(f"\n🐾 {ctext('계속하려면 엔터(Enter) 키를 누르세요냥...', C.GREEN)} ")
        return

    peer_opts = []
    for i, p in enumerate(peers, 1):
        status_lbl = "🟢 온라인" if p.get("online") else "🔴 오프라인"
        os_lbl = f"[{p.get('os', '기기')}]" if p.get("os") else ""
        peer_opts.append(f" 💻 {p.get('hostname', '이름없음')} ({p.get('ip', '-')}) {os_lbl} [{status_lbl}]")
    peer_opts.append(" ❌ 취소하고 돌아가기")

    sel, _, *_ = _interactive_menu("📶 Tailscale 피어 기기 핑 진단 (기기 선택)", peer_opts, timeout=0)
    if sel is None or sel < 0 or sel >= len(peers):
        return

    target_peer = peers[sel]
    target_ip = target_peer.get("ip", "")
    target_name = target_peer.get("hostname", target_ip)

    if not target_ip:
        print(f"\n❌ {ctext('선택한 피어의 IP 주소가 올바르지 않습니다냥.', C.RED)}")
        time.sleep(1.2)
        return

    print(f"\n🔄 {ctext(f'[{target_name}] ({target_ip}) Tailscale 핑 진단을 시작합니다냥! [중단: Ctrl+C]', C.SKY)}")
    print("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
    
    # 1. tailscale ping CLI 시도 (가능한 경우 직접 터널 레이턴시 측정)
    ts_path = _get_tailscale_path()
    if ts_path and os.path.isfile(ts_path):
        try:
            subprocess.run([ts_path, "ping", target_ip])
        except KeyboardInterrupt:
            pass
        except Exception:
            try:
                subprocess.run(["ping", "-n", "4", target_ip])
            except KeyboardInterrupt:
                pass
    else:
        try:
            subprocess.run(["ping", "-n", "4", target_ip])
        except KeyboardInterrupt:
            pass
            
    input(f"\n✅ {ctext('핑 진단이 완료되었습니다! 엔터를 누르면 돌아갑니다냥.', C.GREEN)} ")


# ==============================================================================
# [V185.2] 독립도메인 Let's Encrypt 발급 엔진 (win-acme + DNS-01) 🔐🌐
# ==============================================================================
# 목표: *.byus.net 같은 "자체 보유 도메인"에 공인 인증서를 원클릭 발급/갱신한다.
#   ① win-acme(wacs.exe) 엔진 자동 다운로드 · 설치 (C:\srt\temp\win-acme)
#   ② DNS-01 챌린지 TXT 레코드를 byus.net 마스터 서버에 SSH로 자동 추가/삭제
#      (byus.net 자체가 ns.byus.net 이고 DNS zone 파일을 직접 보유 → 완전 자동화 가능)
#   ③ 발급된 인증서는 C:\srt\certs\acme\ 에 PEM/PFX 로 보관
# ==============================================================================

_ACME_WACS_VERSION = "2.2.9.1701"                                     # win-acme 엔진 버전
_ACME_WACS_DIRNAME = "win-acme"

# ── [V185.3] 하드코딩 제거 / 자동 감지 설정 ────────────────────────────────
# ❌ 도메인·zone 파일 경로·NS 서버를 코드에 박지 않는다.
#    아래 후보 배열은 "탐색 시작점"일 뿐이고, 실제 값은 원격 서버를 조회해서 결정한다.
_ACME_NAMED_CONF_CANDIDATES = [          # BIND 설정 파일 후보 (구형 → 신형 순)
    "/etc/named.conf",                    # RedHat 7.x / 구형 (실측: byus.net)
    "/etc/bind/named.conf",               # Debian/Ubuntu (bind9)
    "/etc/bind/named.conf.local",         # Debian/Ubuntu 하위 zone conf
    "/etc/named.conf.local",
    "/etc/named/named.conf",
]
_ACME_ZONE_DIR_CANDIDATES = [            # zone 파일이 놓일 디렉터리 후보
    "/var/named",                         # RedHat (실측: byus.net)
    "/var/lib/named",                     # Fedora
    "/var/lib/bind",                      # Debian/Ubuntu
    "/etc/bind",
    "/etc/named",
]
_ACME_PIDFILE_CANDIDATES = [             # named pid 파일 후보
    "/var/run/named.pid",
    "/run/named/named.pid",
    "/var/run/named/named.pid",
]
# 🔎 자동 탐색 실패 시 사용자가 직접 지정하게 되는 기본값 (하드코딩 아님 — 저장소 초기값)
_ACME_DEFAULT_SSH_HOST = ""              # 빈 값 = "설정에서 지정"
_ACME_ZONE_NAME = ""                     # 빈 값 = "원격 zone 목록에서 자동 선택"
_ACME_STATE_FILE_SUFFIX = ".acme_txt_state"

# ── 발급 모드 정의 ─────────────────────────────────────────────────────────
#   와일드카드(*.예도메인)는 DNS-01 필수, 단일 호스트는 HTTP-01 도 가능하나
#   여기서는 DNS-01 로 통일 (80/443 포트 불필요 · 서버 설정 불필요)
_ACME_ISSUE_MODES = {
    "wildcard": {"label": "와일드카드 (*.도메인)",       "desc": "DNS-01 필수 · 모든 1단계 하위 도메인 커버"},
    "apex":     {"label": "메인 도메인만 (예: example.com)", "desc": "루트 도메인 1개만"},
    "sub":      {"label": "특정 서브도메인 (예: srt.example.com)", "desc": "지정한 서브도메인만"},
    "multi":    {"label": "직접 입력 (여러 개)",        "desc": "공백/쉼표로 여러 도메인 입력"},
    "san_add":  {"label": "기존 목록에 추가",           "desc": "현재 SAN 목록 + 새 도메인"},
}


def _get_acme_dir() -> str:  # [TAG: #@_get_acme_dir]
    """ACME 엔진·스크립트·인증서 보관 루트 폴더 (C:\\srt\\certs\\acme) 반환 및 생성 📁"""
    d = os.path.join(_get_cert_dir(), "acme")
