# [TAG: #@YOUTUBE_CAPTURE_ENGINE]
# [V177.0] 비누 요청: 유튜브 다운로드 파일 전용 정밀 갈무리 & 스크립트/자막 뷰어 엔진 🎬📜✨
# ==============================================================================

def _is_valid_youtube_id(vid_id: str, check_online: bool = True) -> bool:
    """
    [V177.1] 유튜브 비디오 ID(11자리) 형식 및 온라인 유효성(oEmbed) 검증 🎬🛡️
    """
    import re, urllib.request
    if not vid_id or not isinstance(vid_id, str):
        return False
    vid_id = vid_id.strip()
    if not re.match(r'^[a-zA-Z0-9_-]{11}$', vid_id):
        return False
    if not check_online:
        return True
    try:
        url = f"https://www.youtube.com/oembed?url=https://www.youtube.com/watch?v={vid_id}&format=json"
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        with urllib.request.urlopen(req, timeout=2.0) as res:
            if res.status == 200:
                return True
    except urllib.error.HTTPError as e:
        if e.code in [400, 404]:
            return False
    except Exception:
        return True
    return False

def _detect_youtube_id_from_file(path: str) -> str:
    """
    [V177.1] 파일로부터 유튜브 ID(11자리) 및 로컬 메타데이터 정밀 감지 🎬🔍
    """
    import os, re, json, urllib.request, urllib.parse
    if not path or not os.path.exists(path):
        return None
    
    # 1. 동명 .info.json 파일 확인
    base_noext = os.path.splitext(path)[0]
    for info_ext in [".info.json", ".json"]:
        info_json_path = base_noext + info_ext
        if os.path.exists(info_json_path):
            try:
                with open(info_json_path, 'r', encoding='utf-8', errors='ignore') as f:
                    info_data = json.load(f)
                    if isinstance(info_data, dict):
                        if 'id' in info_data and _is_valid_youtube_id(str(info_data['id'])):
                            return str(info_data['id'])
                        if 'webpage_url' in info_data:
                            m_url = re.search(r'(?:v=|youtu\.be/)([a-zA-Z0-9_-]{11})', str(info_data['webpage_url']))
                            if m_url and _is_valid_youtube_id(m_url.group(1)):
                                return m_url.group(1)
            except: pass
    
    # 2. 파일 헤더/테일 (1MB) 바이너리 스캔
    if os.path.isfile(path):
        try:
            with open(path, 'rb') as f:
                head_data = f.read(1024 * 1024)
                f.seek(0, 2)
                f_size = f.tell()
                tail_size = min(1024 * 1024, f_size)
                f.seek(max(0, f_size - tail_size))
                tail_data = f.read(tail_size)
                match = re.search(rb'(?:youtube\.com/watch\?v=|youtu\.be/)([a-zA-Z0-9_-]{11})', head_data + tail_data)
                if match:
                    extracted_id = match.group(1).decode('utf-8', errors='ignore')
                    if _is_valid_youtube_id(extracted_id):
                        return extracted_id
        except: pass
        
    # 3. 파일명 자체에서 유튜브 ID 패턴 찾기 (앞/뒤/대괄호 등 전방위 탐색 및 oEmbed 검증)
    fname = os.path.basename(path)
    base_name = os.path.splitext(fname)[0]
    m_lead = re.match(r'^([a-zA-Z0-9_-]{11})_', base_name)
    if m_lead and _is_valid_youtube_id(m_lead.group(1)):
        return m_lead.group(1)
    m = re.search(r'\[([a-zA-Z0-9_-]{11})\]', base_name)
    if m and _is_valid_youtube_id(m.group(1)):
        return m.group(1)
    m2 = re.search(r'[-_]([a-zA-Z0-9_-]{11})$', base_name)
    if m2 and _is_valid_youtube_id(m2.group(1)):
        return m2.group(1)
        
    # 4. 파일명 검색을 통한 videoId 획득 ([업로더] 제목 등)
    try:
        clean_name = base_name.replace('_', ' ')
        q_no_uploader = re.sub(r'\[.*?\]', '', clean_name).strip()[:80]
        q_with_uploader = re.sub(r'[\[\]\(\)]', ' ', clean_name).strip()[:80]
        
        candidates_q = []
        if q_no_uploader and len(q_no_uploader) >= 2:
            candidates_q.append(q_no_uploader)
        if q_with_uploader and q_with_uploader not in candidates_q:
            candidates_q.append(q_with_uploader)
            
        for search_query in candidates_q:
            encoded_query = urllib.parse.quote(search_query)
            search_url = f"https://www.youtube.com/results?search_query={encoded_query}"
            req = urllib.request.Request(search_url, headers={'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'})
            with urllib.request.urlopen(req, timeout=4.0) as response:
                html = response.read().decode('utf-8', errors='ignore')
            matches = re.findall(r'"videoId":"([a-zA-Z0-9_-]{11})"', html)
            for vid in matches:
                if _is_valid_youtube_id(vid):
                    return vid
    except Exception as e:
        _log_to_file(f"⚠️ [_detect_youtube_id_from_file Search Error] {e}")
    
    return None

def _is_youtube_video_or_path(path: str):
    """
    [V177.0] 해당 파일이 유튜브 영상인지 판별하고 (is_yt, yt_id) 반환 🎬✨
    """
    import os, re
    if not path or not os.path.exists(path) or os.path.isdir(path):
        return False, ""
    
    # 동영상/오디오 확장자 체크
    ext = os.path.splitext(path)[1].lower()
    if ext not in ['.mp4', '.mkv', '.webm', '.m4a', '.mp3', '.ts', '.avi', '.flv', '.mov']:
        return False, ""
        
    # 1. 유튜브 ID 감지 시도
    yt_id = _detect_youtube_id_from_file(path)
    if yt_id:
        return True, yt_id
        
    # 2. 파일명에 [업로더] 패턴이 있거나 유튜브 보관함 내 파일인 경우
    fname = os.path.basename(path)
    if re.match(r'^\[.*?\]', fname) or re.match(r'^\(.*?\)', fname):
        return True, ""
    if '유튜브' in path or 'youtube' in path.lower() or 'YouTube' in path:
        return True, ""
        
    return False, ""

def fetch_youtube_summary_and_script(path: str, yt_id: str = None):
    """
    [V177.0] 유튜브 영상의 메타데이터, 설명란(Description), 자막/대본 스크립트(Transcript) 추출 🎬📜✨
    """
    import json, urllib.request, urllib.parse, re, os
    import yt_dlp
    
    if not yt_id:
        yt_id = _detect_youtube_id_from_file(path)
        
    # 로컬 자막 확인
    local_srt_lines = []
    base_noext = os.path.splitext(path)[0] if path else ""
    local_srt_path = ""
    for s_ext in ['.ko.srt', '.srt', '.ko.vtt', '.vtt']:
        s_path = base_noext + s_ext
        if os.path.exists(s_path):
            try:
                with open(s_path, 'r', encoding='utf-8', errors='ignore') as sf:
                    content = sf.read()
                    blocks = content.strip().split('\n\n')
                    for blk in blocks:
                        lines = [l.strip() for l in blk.split('\n') if l.strip()]
                        if len(lines) >= 3 and '-->' in lines[1]:
                            time_part = lines[1].split('-->')[0].strip().split(',')[0].split('.')[0]
                            t_parts = time_part.split(':')
                            if len(t_parts) == 3 and t_parts[0] == '00':
                                time_str = f"{t_parts[1]}:{t_parts[2]}"
                            else:
                                time_str = time_part
                            txt_part = " ".join(lines[2:])
                            local_srt_lines.append({'time': time_str, 'text': txt_part})
                if local_srt_lines:
                    local_srt_path = s_path
                    break
            except: pass
            
    yt_data = {
        'yt_id': yt_id or "",
        'title': os.path.splitext(os.path.basename(path))[0] if path else "유튜브 동영상",
        'uploader': "알 수 없음",
        'upload_date': "",
        'duration_str': "",
        'view_count': 0,
        'description': "",
        'url': f"https://www.youtube.com/watch?v={yt_id}" if yt_id else "",
        'transcript_lines': local_srt_lines,
        'local_srt_path': local_srt_path,
        'source': 'local_srt' if local_srt_lines else 'none'
    }
    
    # 동명 .info.json 파일 확인
    if base_noext:
        for info_ext in [".info.json", ".json"]:
            info_json_path = base_noext + info_ext
            if os.path.exists(info_json_path):
                try:
                    with open(info_json_path, 'r', encoding='utf-8') as f:
                        info_data = json.load(f)
                        if isinstance(info_data, dict):
                            if 'title' in info_data: yt_data['title'] = info_data.get('title')
                            if 'uploader' in info_data or 'channel' in info_data: yt_data['uploader'] = info_data.get('uploader') or info_data.get('channel')
                            if 'description' in info_data: yt_data['description'] = info_data.get('description')
                            if 'upload_date' in info_data:
                                ud = str(info_data.get('upload_date'))
                                yt_data['upload_date'] = f"{ud[:4]}-{ud[4:6]}-{ud[6:]}" if len(ud) == 8 else ud
                            if 'duration_string' in info_data: yt_data['duration_str'] = info_data.get('duration_string')
                            if 'id' in info_data and not yt_data['yt_id']:
                                yt_data['yt_id'] = str(info_data['id'])
                                yt_data['url'] = f"https://www.youtube.com/watch?v={yt_data['yt_id']}"
                except: pass
    
    # 온라인 메타데이터 및 스크립트 가져오기 (yt-dlp)
    target_query = f"https://www.youtube.com/watch?v={yt_data['yt_id']}" if yt_data.get('yt_id') else ""
    if not target_query and path:
        # ID가 없으면 파일명 기반 ytsearch1 폴백 사용! 🎯✨
        clean_q = os.path.splitext(os.path.basename(path))[0].replace('_', ' ')
        clean_q = re.sub(r'\[.*?\]', '', clean_q).strip()[:80]
        if clean_q:
            target_query = f"ytsearch1:{clean_q}"
            
    if target_query:
        ydl_opts = {
            'quiet': True,
            'no_warnings': True,
            'skip_download': True,
            'extract_flat': False,
        }
        try:
            with yt_dlp.YoutubeDL(ydl_opts) as ydl:
                res = ydl.extract_info(target_query, download=False)
                info = res['entries'][0] if (res and 'entries' in res and res['entries']) else res
                if info:
                    if 'id' in info:
                        yt_data['yt_id'] = str(info['id'])
                        yt_data['url'] = f"https://www.youtube.com/watch?v={info['id']}"
                    yt_data['title'] = info.get('title') or yt_data['title']
                    yt_data['uploader'] = info.get('uploader') or info.get('channel') or yt_data['uploader']
                    up_date = str(info.get('upload_date') or '')
                    if len(up_date) == 8:
                        yt_data['upload_date'] = f"{up_date[:4]}-{up_date[4:6]}-{up_date[6:]}"
                    elif up_date:
                        yt_data['upload_date'] = up_date
                    dur = info.get('duration_string')
                    if not dur and info.get('duration'):
                        d_sec = info.get('duration')
                        yt_data['duration_str'] = f"{d_sec//60:02d}:{d_sec%60:02d}"
                    elif dur:
                        yt_data['duration_str'] = dur
                    yt_data['view_count'] = info.get('view_count') or 0
                    if not yt_data['description'] or len(info.get('description', '')) > len(yt_data['description']):
                        yt_data['description'] = (info.get('description') or "").strip()
                    
                    # 온라인 자막/스크립트 파싱 (로컬 자막이 없을 때)
                    if not yt_data['transcript_lines']:
                        subs = info.get('subtitles', {})
                        auto_subs = info.get('automatic_captions', {})
                        
                        target_subs = None
                        for lang_code in ['ko', 'ko-KR', 'ko-kr', 'en', 'en-US', 'ja']:
                            if lang_code in subs and subs[lang_code]:
                                target_subs = subs[lang_code]; break
                            if lang_code in auto_subs and auto_subs[lang_code]:
                                target_subs = auto_subs[lang_code]; break
                                
                        if target_subs:
                            json3_url = None
                            vtt_url = None
                            for fmt in target_subs:
                                if fmt.get('ext') == 'json3': json3_url = fmt.get('url')
                                elif fmt.get('ext') == 'vtt': vtt_url = fmt.get('url')
                                
                            if json3_url:
                                req = urllib.request.Request(json3_url, headers={'User-Agent': 'Mozilla/5.0'})
                                with urllib.request.urlopen(req, timeout=10) as resp:
                                    sub_data = json.loads(resp.read().decode('utf-8'))
                                events = sub_data.get('events', [])
                                parsed_lines = []
                                cur_time = ""
                                cur_text_parts = []
                                for ev in events:
                                    t_ms = ev.get('tStartMs', 0)
                                    mins = int(t_ms // 60000)
                                    secs = int((t_ms % 60000) // 1000)
                                    time_label = f"{mins:02d}:{secs:02d}"
                                    segs = ev.get('segs', [])
                                    seg_text = "".join(s.get('utf8', '') for s in segs).strip()
                                    if not seg_text or seg_text == '\n': continue
                                    
                                    cur_text_parts.append(seg_text)
                                    full_chunk = " ".join(cur_text_parts)
                                    if len(full_chunk) >= 45 or seg_text.endswith(('.', '?', '!', '다.', '요.', '죠.')):
                                        parsed_lines.append({'time': cur_time or time_label, 'text': full_chunk})
                                        cur_text_parts = []
                                        cur_time = ""
                                    elif not cur_time:
                                        cur_time = time_label
                                        
                                if cur_text_parts:
                                    parsed_lines.append({'time': cur_time or "00:00", 'text': " ".join(cur_text_parts)})
                                    
                                if parsed_lines:
                                    yt_data['transcript_lines'] = parsed_lines
                                    yt_data['source'] = 'youtube_online'
        except Exception as e:
            _log_to_file(f"⚠️ [fetch_youtube_summary_and_script Error] {e}")
            
    return yt_data

def show_youtube_capture_viewer(file_path: str, yt_id: str = None, settings_ref=None):
    """
    [V177.0] 유튜브 전용 갈무리 TUI 뷰어 (대본/자막 스크립트, 영상 설명, AI 요약, 저장/복사) 🎬📜✨
    """
    import msvcrt, webbrowser
    
    print(f"\r\n 🔍 {C.SKY}'{os.path.basename(file_path)}'{C.RESET} 유튜브 스크립트 및 설명 정보 갈무리 중... 🕵️‍♂️✨")
    yt_data = fetch_youtube_summary_and_script(file_path, yt_id)
    
    page = 0
    lines_per_page = 15
    ai_summary = ""
    status_msg = ""
    
    all_trans = yt_data.get('transcript_lines', [])
    total_trans = len(all_trans)
    max_pages = max(1, (total_trans + lines_per_page - 1) // lines_per_page) if total_trans > 0 else 1
    
    while True:
        clear_console()
        
        # 1. 헤더 영역 🎬
        print(f" {C.BOLD}{C.YELLOW}🎬 [유튜브 상세 갈무리 (YouTube Capture)]{C.RESET}")
        print(f" {C.DIM}{'='*78}{C.RESET}")
        print(f" 📌 {C.BOLD}{C.SKY}제목:{C.RESET} {yt_data['title']}")
        
        meta_items = []
        if yt_data['uploader'] and yt_data['uploader'] != "알 수 없음":
            meta_items.append(f"👤 {C.BOLD}{yt_data['uploader']}{C.RESET}")
        if yt_data['upload_date']:
            meta_items.append(f"📅 {yt_data['upload_date']}")
        if yt_data['duration_str']:
            meta_items.append(f"⏱️ {yt_data['duration_str']}")
        if yt_data['view_count']:
            meta_items.append(f"👁️ {yt_data['view_count']:,}회")
        if meta_items:
            print(f" {' | '.join(meta_items)}")
            
        if yt_data['url']:
            print(f" 🔗 {C.DIM}원본 링크:{C.RESET} {C.UNDERLINE}{C.SKY}{yt_data['url']}{C.RESET}")
        print(f" 📂 {C.DIM}로컬 파일:{C.RESET} {file_path}")
        print(f" {C.DIM}{'-'*78}{C.RESET}")
        
        # 2. AI 요약 영역 (생성된 경우) 🤖
        if ai_summary:
            print(f" 🤖 {C.BOLD}{C.GREEN}[Gemini AI 브리핑 & 핵심 3줄 요약]{C.RESET}")
            for a_line in ai_summary.strip().split('\n'):
                print(f"   {a_line}")
            print(f" {C.DIM}{'-'*78}{C.RESET}")
            
        # 3. 영상 설명란 영역 (Description) 📝
        desc = yt_data.get('description', '').strip()
        if desc:
            print(f" 📝 {C.BOLD}{C.YELLOW}[영상 설명란 (Description)]{C.RESET}")
            desc_lines = [d.strip() for d in desc.split('\n') if d.strip()]
            show_desc = desc_lines[:5]
            for dl in show_desc:
                disp_dl = dl if len(dl) <= 75 else dl[:72] + "..."
                print(f"   {C.GRAY}{disp_dl}{C.RESET}")
            if len(desc_lines) > 5:
                print(f"   {C.DIM}... (설명란 총 {len(desc_lines)}줄 / [S] 저장 또는 [C] 복사로 전체 확인 가능냥!){C.RESET}")
            print(f" {C.DIM}{'-'*78}{C.RESET}")
            
        # 4. 영상 스크립트 / 자막 (Transcript) 📜
        if total_trans > 0:
            start_idx = page * lines_per_page
            end_idx = min(start_idx + lines_per_page, total_trans)
            sub_badge = f"{C.GREEN}(온라인 자막){C.RESET}" if yt_data.get('source') == 'youtube_online' else f"{C.SKY}(로컬 자막){C.RESET}"
            print(f" 📜 {C.BOLD}{C.CYAN}[영상 대본 / 자막 스크립트]{C.RESET} {sub_badge} {C.DIM}(페이지 {page+1}/{max_pages}, 총 {total_trans}구절){C.RESET}")
            for item in all_trans[start_idx:end_idx]:
                t_str = f"{C.YELLOW}[{item['time']}]{C.RESET}"
                print(f"   {t_str} {item['text']}")
        else:
            print(f" 📜 {C.BOLD}{C.CYAN}[영상 대본 / 자막 스크립트]{C.RESET}")
            print(f"   ⚠️ {C.YELLOW}이 영상에는 추출 가능한 자막/대본 정보가 없습니다냥! 😿{C.RESET}")
            print(f"   💡 {C.DIM}(영상 자막을 만들고 싶다면 메인 탐색기에서 [A] 키(음성인식/자막생성)를 실행해줘냥!){C.RESET}")
            
        print(f" {C.DIM}{'='*78}{C.RESET}")
        
        # 상태 메시지
        if status_msg:
            print(f" {status_msg}")
            status_msg = ""
            
        # 5. 하단 단축키 바 ⌨️
        print(f" {C.GREEN}[S]{C.RESET} 스크립트 저장 | {C.GREEN}[C]{C.RESET} 클립보드 복사 | {C.GREEN}[A]{C.RESET} AI 3줄 요약 | {C.GREEN}[B]{C.RESET} 유튜브 열기 | {C.GREEN}[◀/▶]{C.RESET} 페이지 | {C.YELLOW}[Enter/Space/ESC/q]{C.RESET} 나가기 : ", end="", flush=True)
        
        try:
            k = msvcrt.getch()
        except:
            break
            
        # 특수키 (방향키, PgUp, PgDn) 처리
        if k in [b'\x00', b'\xe0']:
            try:
                k2 = msvcrt.getch()
                if k2 in [b'K', b'H', b'I']: # Left, Up, PgUp
                    page = max(0, page - 1)
                    continue
                elif k2 in [b'M', b'P', b'Q']: # Right, Down, PgDn
                    page = min(max_pages - 1, page + 1)
                    continue
            except: pass
            continue
            
        k_char = k.decode('latin-1', errors='ignore').lower()
        
        if k_char in ['q', '\r', '\n', '\x1b']: # ESC, Enter, q
            break
        elif k_char == ' ':
            if page < max_pages - 1:
                page += 1
            else:
                break
        elif k_char in ['p', 'h', 'k']:
            page = max(0, page - 1)
        elif k_char in ['n', 'l', 'j']:
            page = min(max_pages - 1, page + 1)
        elif k_char == 'b':
            if yt_data.get('url'):
                print(f"\r\n 🌐 {C.SKY}유튜브 원본 웹페이지를 브라우저로 엽니다냥... ({yt_data['url']}){C.RESET}")
                webbrowser.open(yt_data['url'])
                time.sleep(1)
            else:
                status_msg = f" ❌ {C.RED}유튜브 주소를 찾을 수 없어 브라우저를 열 수 없습니다냥!{C.RESET}"
        elif k_char == 's':
            out_txt_name = f"{os.path.splitext(file_path)[0]}_youtube_script.txt"
            try:
                with open(out_txt_name, 'w', encoding='utf-8') as tf:
                    tf.write(f"🎬 제목: {yt_data['title']}\n")
                    tf.write(f"👤 채널: {yt_data['uploader']} | 📅 업로드일: {yt_data['upload_date']} | ⏱️ 재생시간: {yt_data['duration_str']}\n")
                    tf.write(f"🔗 원본 링크: {yt_data['url']}\n")
                    tf.write(f"📂 로컬 경로: {file_path}\n")
                    tf.write("="*75 + "\n\n")
                    if ai_summary:
                        tf.write("[Gemini AI 핵심 요약]\n")
                        tf.write(ai_summary + "\n\n" + "="*75 + "\n\n")
                    if desc:
                        tf.write("[영상 설명란 (Description)]\n")
                        tf.write(desc + "\n\n" + "="*75 + "\n\n")
                    tf.write("[영상 대본 / 자막 스크립트 (Transcript)]\n")
                    if total_trans > 0:
                        for item in all_trans:
                            tf.write(f"[{item['time']}] {item['text']}\n")
                    else:
                        tf.write("(추출된 자막/대본이 없습니다)\n")
                status_msg = f" ✅ {C.GREEN}스크립트 전문이 파일로 안전하게 저장되었어냥! 💾✨\r\n    👉 {out_txt_name}{C.RESET}"
            except Exception as e:
                status_msg = f" ❌ {C.RED}스크립트 파일 저장 실패: {e}{C.RESET}"
        elif k_char == 'c':
            clip_buf = []
            clip_buf.append(f"🎬 {yt_data['title']}")
            clip_buf.append(f"👤 채널: {yt_data['uploader']} | 📅 날짜: {yt_data['upload_date']} | ⏱️ 길이: {yt_data['duration_str']}")
            if yt_data['url']: clip_buf.append(f"🔗 {yt_data['url']}")
            clip_buf.append("\n" + "="*50 + "\n")
            if ai_summary:
                clip_buf.append("[AI 핵심 요약]")
                clip_buf.append(ai_summary + "\n\n" + "="*50 + "\n")
            if desc:
                clip_buf.append("[영상 설명]")
                clip_buf.append(desc + "\n\n" + "="*50 + "\n")
            clip_buf.append("[영상 대본 / 스크립트]")
            if total_trans > 0:
                for item in all_trans:
                    clip_buf.append(f"[{item['time']}] {item['text']}")
            full_clip_text = "\n".join(clip_buf)
            
            _set_clipboard_text(full_clip_text)
            status_msg = f" 📋 {C.GREEN}전체 스크립트 및 영상 설명이 클립보드에 복사되었어냥! 🐾✨ (Ctrl+V로 붙여넣기 가능){C.RESET}"
        elif k_char == 'a':
            print(f"\r\n 🤖 {C.SKY}Gemini AI가 영상 스크립트 및 설명을 정밀 분석하여 핵심 요약을 작성 중입니다냥... 🧠✨{C.RESET}", end="", flush=True)
            try:
                trans_sample = " ".join([it['text'] for it in all_trans[:100]]) if total_trans > 0 else ""
                ai_prompt = f"""다음 유튜브 영상의 제목, 설명란, 스크립트(자막)를 분석하여 핵심 내용을 한국어로 명확하고 흥미롭게 브리핑 요약해줘.

[영상 제목]: {yt_data['title']}
[채널명]: {yt_data['uploader']}
[영상 설명란]:
{desc[:1000]}

[대본/스크립트 내용]:
{trans_sample[:3000]}

[작성 요구사항]:
1. 💡 **3줄 핵심 요약**: 영상의 핵심 메시지를 글머리기호(•) 3줄로 알기 쉽게 요약
2. 📌 **주요 포인트 & 키워드**: 영상에서 다루는 핵심 주제나 중요 포인트를 2~3줄로 정리
불필요한 서두나 잡담 없이 깔끔하게 요약 본문만 작성해줘."""
                
                ai_res = ask_ai(ai_prompt, timeout=25)
                if ai_res and not ai_res.startswith("❌"):
                    ai_summary = ai_res.strip()
                    status_msg = f" 🤖 {C.GREEN}AI 요약이 성공적으로 완료되었어냥! 🧠✨{C.RESET}"
                else:
                    status_msg = f" ⚠️ {C.YELLOW}AI 요약 생성에 실패했어냥: {ai_res}{C.RESET}"
            except Exception as e:
                status_msg = f" ❌ {C.RED}AI 요약 생성 중 오류: {e}{C.RESET}"


