# [TAG: #@get_file_identity]
def get_file_identity(path: str):
    """[V147.162] 파일명이나 위치가 바뀌어도 파일을 끝까지 추적할 수 있는 고유 지문을 생성합니다냥! 🧬✨
    Returns: (fingerprint_str, file_index_int, volume_serial_int) or (None, 0, 0) on failure

    핵심 원리:
      - 파일 크기 + 데이터 샘플 해시(SHA256) = 복사본도 추적 가능한 '내용 지문'
      - WindowsFileIndex = 같은 드라이브 내 이름변경/이동을 메타데이터만으로 즉시 추적
      - mtime은 지문에서 제외! (복사 시 바뀌므로 복사본 추적이 깨짐)
    """
    if not path or not os.path.exists(path) or os.path.isdir(path):
        return None, 0, 0

    try:
        stat = os.stat(path)
        size = stat.st_size

        # 1. 윈도우 고유 번호 (FileIndex) - 같은 드라이브 내 이동/이름변경 즉시 추적! 🆔🛡️
        file_index = 0
        volume_serial = 0
        if os.name == 'nt':
            try:
                from ctypes import windll, wintypes, Structure, byref
                class _BY_HANDLE_FILE_INFORMATION(Structure):
                    _fields_ = [
                        ("dwFileAttributes", wintypes.DWORD), ("ftCreationTime", wintypes.FILETIME),
                        ("ftLastAccessTime", wintypes.FILETIME), ("ftLastWriteTime", wintypes.FILETIME),
                        ("dwVolumeSerialNumber", wintypes.DWORD), ("nFileSizeHigh", wintypes.DWORD),
                        ("nFileSizeLow", wintypes.DWORD), ("nNumberOfLinks", wintypes.DWORD),
                        ("nFileIndexHigh", wintypes.DWORD), ("nFileIndexLow", wintypes.DWORD),
                    ]
                INVALID_HANDLE_VALUE = wintypes.HANDLE(-1).value
                GENERIC_READ = 0x80000000
                FILE_SHARE_READ = 1
                OPEN_EXISTING = 3
                h = windll.kernel32.CreateFileW(path, GENERIC_READ, FILE_SHARE_READ, None, OPEN_EXISTING, 0, None)
                if h and h != INVALID_HANDLE_VALUE:
                    info = _BY_HANDLE_FILE_INFORMATION()
                    if windll.kernel32.GetFileInformationByHandle(h, byref(info)):
                        file_index = (info.nFileIndexHigh << 32) + info.nFileIndexLow
                        volume_serial = info.dwVolumeSerialNumber
                    windll.kernel32.CloseHandle(h)
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

        # 2. 데이터 샘플링 (앞/중간/끝 1MB씩) - 복사본도 추적 가능한 핵심 지문! 🧬✨
        samples = b""
        with open(path, "rb") as f:
            samples += f.read(1024 * 1024)           # 앞 1MB
            if size > 3 * 1024 * 1024:               # 중간 1MB (3MB 이상일 때)
                f.seek(size // 2)
                samples += f.read(1024 * 1024)
            if size > 2 * 1024 * 1024:               # 끝 1MB (2MB 이상일 때)
                f.seek(max(0, size - 1024 * 1024))
                samples += f.read(1024 * 1024)

        # 핵심 지문 = 크기 + 데이터 내용 해시 (mtime 제외!)
        data_hash = hashlib.sha256(samples).hexdigest()
        core_fp = f"{size}_{data_hash}"
        return hashlib.md5(core_fp.encode()).hexdigest(), file_index, volume_serial
    except Exception as e:
        _log_to_file(f"⚠️ [Identity] 지문 추출 실패 ({os.path.basename(path)}): {e}")
        return None, 0, 0

# [TAG: #@_get_filename_similarity]

def _get_filename_similarity(s1, s2):
    """[V147.178] 두 파일명의 유사도 측정 (0.0 ~ 1.0) 📏"""
    import difflib
    return difflib.SequenceMatcher(None, s1, s2).ratio()

# [TAG: #@safe_splitext]
def safe_splitext(name):
    """[V17.3.37] AI냥 요청: 온점(.)이 버전이나 날짜(29.05)에 사용된 경우를 방어하는 안전한 확장자 추출기 🛡️✨
    - 진짜 확장자(예: .mp4, .mkv, .srt, .zip 등 2~5글자 영숫자 조합)인 경우만 잘라내냥!
    """
    basename = os.path.basename(name)
    base, ext = os.path.splitext(basename)
    if ext and re.match(r'^\.[a-zA-Z0-9]{2,5}$', ext):
        return base, ext
    return basename, ""

# [TAG: #@get_series_signature]
def get_series_signature(name):
    """[V147.182] AI냥 요청: 프로그램 전체 공용 시리즈 시그니처 엔진 🧬💎
    - 메타데이터([])를 제거하고, 에피소드 번호(1~3자리 숫자)만 지워서 '뼈대'를 추출해냥!
    - [품번 방어]: 4자리 이상의 긴 숫자나 숫자 뒤에 붙은 숫자는 품번으로 간주하여 보존해냥! 🛡️🔢
    """
    if not name: return ""
    base, _ = safe_splitext(name)
    # 1. 메타데이터 제거 ([...], (...))
    base_clean = re.sub(r'\[.*?\]|\(.*?\)', '', base).strip()

    # [V17.3.36] 품번(Product ID) 방어: '대문자-숫자' 패턴은 그 자체로 고유 아이덴티티이므로 시그니처로 보존냥! 🛡️⚓
    _m = re.match(r'^([A-Z]{2,8}-\d{2,6})', base_clean.upper())
    if _m:
        return _m.group(1).lower()

    # [신규] 단일 영문자 에피소드 표기(A-Z) 제거 (예: _A, -A, A 등) 🔤🛡️
    # 뒤에 붙는 단일 영문자를 지움으로써 시그니처 뼈대를 통일시켜줍니다.
    base_clean = re.sub(r'(?i)(?:[_\s-][a-z]|(?<=\d)[a-z])$', '', base_clean).strip()

    # [V147.183] AI냥 요청: 만약 메타데이터를 제거하고 남은 뼈대가 너무 부실("episode" 등)하면 원래 이름을 사용한다냥! 🛡️✨
    _test_sig = re.sub(r'(?<!\d)\d{1,3}(?!\d)', '', base_clean).strip().lower()
    if not _test_sig or _test_sig in ("episode", "ep", "ova", "vol", "part", "-", "_", "series"):
        base_clean = base

    # 2. 에피소드 숫자만 제거 (앞뒤에 숫자가 없는 1~3자리 숫자)
    sig = re.sub(r'(?<!\d)\d{1,3}(?!\d)', '', base_clean)
    return sig.strip().lower()

# [TAG: #@is_series_sibling]
def is_series_sibling(name1, name2):
    """[V147.180] AI냥 요청: 숫자 1~2자리 차이만 허용하는 초정밀 시리즈 판별 🧬🛡️
    - MOVIE-123 vs MOVIE-456: 차이가 너무 커서 기각! 🚫
    - abcd vs abcd2: 숫자 1개 차이이므로 승인! ✅
    - FC2-123_1 vs FC2-123_2: 숫자 1개 교체이므로 승인! ✅
    """
    if not name1 or not name2 or name1 == name2: return False
    b1, _ = safe_splitext(name1)
    b2, _ = safe_splitext(name2)

    # [V202.2] 순수 숫자 파일명(01 vs 02, 1 vs 2 등) 직관적 시리즈 판정 🔢🛡️
    if b1.isdigit() and b2.isdigit() and len(b1) <= 3 and len(b2) <= 3:
        return True

    # 1. 기초 유사도 검증 (최소 85% 이상은 되어야 함) 📏
    if _get_filename_similarity(b1, b2) < 0.85: return False

    # [V17.3.36] 시그니처 대조 방식은 보조 수단으로만 사용하고, 정밀 분석(difflib)을 우선합니다냥! 🛡️⚓
    # (단순 시그니처 일치는 품번 오탐지가 많아 숏컷 제거)

    # 2. 차이점 분석 (difflib.SequenceMatcher 이용) 🕵️‍♂️
    import difflib
    s = difflib.SequenceMatcher(None, b1, b2)
    diff_chars = []
    for tag, i1, i2, j1, j2 in s.get_opcodes():
        if tag != 'equal':
            # [V147.181] AI냥 요청: 품번(긴 숫자)의 끝자리만 바뀌는 경우 방어! 🛡️
            # 차이가 시작되는 지점 바로 앞 문자가 '숫자'라면, 이건 시리즈가 아니라 품번 차이로 간주냥!
            if i1 > 0 and b1[i1-1].isdigit(): return False
            if j1 > 0 and b2[j1-1].isdigit(): return False

            diff_chars.append(b1[i1:i2] + b2[j1:j2])

    # 3. 차이가 오직 '숫자'나 '단일 영문자' 이내인지 검증 🔍
    all_diff = "".join(diff_chars)
    # [V147.180] 공백이나 하이픈 등 미세한 차이는 허용하되 핵심은 숫자/알파벳이 1~2개여야 함
    # 그 외 쓰레기 문자가 포함되어 있다면 기각!
    clean_diff_num = re.sub(r'[^0-9]', '', all_diff)
    clean_diff_alpha = re.sub(r'[^a-zA-Z]', '', all_diff)
    other_diff = re.sub(r'[0-9a-zA-Z\s\-_\[\]\(\)]', '', all_diff) # 숫자/알파벳/기호 제외한 글자들

    if (0 < len(clean_diff_num) <= 2 or 0 < len(clean_diff_alpha) <= 2) and len(other_diff) == 0:
        return True
    return False

# [TAG: #@_get_video_track_file]

def _get_video_track_file() -> str:
    """[V147.162] 동영상 추적 장부 경로를 settings.json에서 읽어옵니다냥! 📂
    settings에 'video_track_file' 키가 없으면 기본값(temp/video_track.json)을 사용해요.
    """
    # 전역 settings 객체가 준비된 경우에만 읽기 (부팅 초기에는 None일 수 있음)
    try:
        if settings is not None:
            return settings.data.get("video_track_file", os.path.join("temp", "video_track.json"))
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")
    return os.path.join("temp", "video_track.json")

# [TAG: #@_load_video_tracks]

def _load_video_tracks() -> dict:
    """[V147.162] 추적 장부 로드냥! 📚
    - 파일이 없으면 → temp 폴더 포함 자동 생성 후 빈 dict 반환
    - 파일이 깨져 있으면 → 백업 후 빈 dict 반환
    """
    track_file = _get_video_track_file()
    track_dir  = os.path.dirname(track_file)

    # temp 폴더가 없으면 자동 생성 🏗️
    if track_dir and not os.path.exists(track_dir):
        try:
            os.makedirs(track_dir, exist_ok=True)
            _log_to_file(f"📂 [VideoTrack] temp 폴더 자동 생성: {track_dir}")
        except Exception as e:
            _log_to_file(f"⚠️ [VideoTrack] 폴더 생성 실패: {e}")

    # 파일 없으면 → 빈 장부로 시작 (최초 실행 시 정상)
    if not os.path.exists(track_file):
        _log_to_file(f"📋 [VideoTrack] 지문 파일 없음 → 새로 시작: {track_file}")
        return {}

    try:
        with open(track_file, "r", encoding="utf-8") as f:
            content = f.read()
        # [V150.1] 복호화 적용 🔓
        return _decrypt_json_data(content)
    except Exception as e:
        # JSON 손상 → 백업 후 빈 dict 반환
        _log_to_file(f"⚠️ [VideoTrack] 장부 손상 → 백업 후 초기화: {e}")
        try:
            bak = track_file + ".bak"
            os.replace(track_file, bak)
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")
        return {}

# [TAG: #@_save_video_tracks]

def _save_video_tracks(tracks: dict):
    """[V147.162] 추적 장부 저장냥! 💾
    저장 경로는 settings.json의 'video_track_file' 키를 따릅니다.
    """
    track_file = _get_video_track_file()
    try:
        ensure_dir(os.path.dirname(track_file))
        tmp_path = track_file + f".tmp_{os.getpid()}"

        # [V150.1] 암호화 적용 🔐
        enc_content = _encrypt_json_data(tracks)
        with open(tmp_path, "w", encoding="utf-8") as f:
            f.write(enc_content)
        os.replace(tmp_path, track_file)  # 원자적 교체 🛡️
    except Exception as e:
        _log_to_file(f"⚠️ [VideoTrack] 장부 저장 실패: {e}")
        try:
            if os.path.exists(tmp_path):
                os.remove(tmp_path)
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

# [TAG: #@update_video_track]
def update_video_track(v_path: str):
    """[V147.162] 동영상의 DNA와 현재 위치를 장부에 기록합니다냥! 📝✨
    호출 시점: process_video_file 진입 직후 (파일을 처음 만나는 순간 DNA 등록!)
    """
    if not v_path or not os.path.exists(v_path):
        return
    fp, file_index, volume_serial = get_file_identity(v_path)
    if not fp:
        return

    tracks = _load_video_tracks()

    # 경로 -> 지문 매핑 (경로로 지문을 찾기 위해)
    tracks[v_path] = fp

    # 지문 -> 상세정보 매핑 (지문으로 파일을 찾기 위해)
    entry = tracks.get(fp, {})
    entry.update({
        "last_path":    v_path,
        "last_seen":    time.time(),
        "filename":     os.path.basename(v_path),
        "size":         os.path.getsize(v_path),
        "file_index":   file_index,
        "volume_serial": volume_serial,
    })
    tracks[fp] = entry
    _save_video_tracks(tracks)

# [TAG: #@add_to_translated_history]
def add_to_translated_history(v_path: str, settings):
    """[V147.165] 번역 완료된 파일을 명예의 전당(translated_history)에 훈장과 함께 등록합니다냥! 🎖️✨
    DNA 정보를 포함하여 나중에 파일이 이사 가도 찾을 수 있게 해요.
    """
    if not v_path or not settings:
        return

    # 1. 최신 장부 로드 📚
    t_history = settings.data.get('translated_history', [])
    if not isinstance(t_history, list): t_history = []

    # 2. 7일 지난 구닥다리 기록 먼저 청소냥! (실제 파일에서도 삭제하여 DB 비대화 방지 🧹✨)
    _now = time.time()
    t_history = [h for h in t_history if isinstance(h, dict) and (_now - h.get('done_at', 0)) < 604800]
    settings.data['translated_history'] = t_history

    # 3. 기존 항목 제거 (중복 방지 및 최신화: AI냥 요청 🚀) 🕵️‍♂️
    t_history = [h for h in t_history if isinstance(h, dict) and h.get('path') != v_path]


    # 4. DNA 지문 확보 🧬
    dna, _, _ = get_file_identity(v_path)
    # 장부에도 실시간 위치 등록 (지능형 추적용)
    update_video_track(v_path)

    # 5. 명예의 전당 입성! 🎖️
    t_history.append({
        "path": v_path,
        "dna": dna,
        "done_at": _now
    })

    # 6. 저장 💾
    settings.data['translated_history'] = t_history
    settings.save()
    _log_to_file(f"🎖️ [History] 번역 완료 리스트 등록: {os.path.basename(v_path)}")

# [TAG: #@find_moved_video]
def find_moved_video(original_path: str, search_dirs: Optional[list] = None, status_fn=None, target_fp: Optional[str] = None) -> Optional[str]:
    """[V155.0] 이름이 바뀌거나 이사 간 동영상을 파일명 대조로 빛의 속도로 찾아냅니다냥! 🕵️‍♂️🧭✨
    (AI냥 가이드: 무거운 DNA 해시 대조를 전면 배제하고, 파일명 및 존재 여부 검사로 초가속화!)
    """
    if not original_path:
        return None

    # 전략 1: 아직 거기 있음!
    if os.path.exists(original_path) and os.path.isfile(original_path):
        return original_path

    # 대상 파일명 추출
    target_name = os.path.basename(original_path)
    if not target_name:
        return None

    # 스캔할 디렉토리 풀 구성
    s_dirs = []

    # 1. 원래 파일이 있던 부모 폴더
    orig_dir = os.path.dirname(original_path)
    if orig_dir and os.path.isdir(orig_dir):
        s_dirs.append(orig_dir)

    # 2. 인자로 들어온 검색 폴더들
    if search_dirs:
        for sd in search_dirs:
            if sd and os.path.isdir(sd):
                s_dirs.append(sd)

    # 3. 현재 작업 폴더
    cwd = os.getcwd()
    if cwd and os.path.isdir(cwd):
        s_dirs.append(cwd)

    # 4. 설정(Settings)에 등록된 모든 미디어 폴더 그룹 추가
    _gl_settings = globals().get('settings') or globals().get('settings_ref')
    if _gl_settings and hasattr(_gl_settings, 'data'):
        # playlist_groups, playlist_music_groups 등 모든 즐겨찾기 폴더 스캔
        for key in ('playlist_groups', 'playlist_music_groups'):
            groups = _gl_settings.data.get(key, [])
            for grp in groups:
                if isinstance(grp, str) and grp and os.path.isdir(grp):
                    s_dirs.append(grp)
                elif isinstance(grp, dict) and grp.get('path') and os.path.isdir(grp['path']):
                    s_dirs.append(grp['path'])

    # 중복 제거 및 경로 정규화 (순서 유지)
    unique_dirs = []
    seen = set()
    for d in s_dirs:
        norm = os.path.normcase(os.path.abspath(d))
        if norm not in seen:
            seen.add(norm)
            unique_dirs.append(d)

    # 전략 2: 단순 파일명 매칭 (DNA/용량 검사 없이 즉시 통과!)
    # 파일명만 같으면 용량이 살짝 바뀌더라도 대체하여 인정냥! 👍
    for sdir in unique_dirs:
        candidate = os.path.join(sdir, target_name)
        if os.path.exists(candidate) and os.path.isfile(candidate):
            # 찾았냥! 장부 갱신 시도 후 즉시 경로 반환냥!
            _log_to_file(f"🎯 [Tracking] 파일명 매칭으로 대체 성공냥!: {candidate}")
            try:
                update_video_track(candidate)
            except Exception:
                pass
            return candidate

    # 전략 3: 장부의 last_path 가볍게 체크 (DNA 검사 없이 존재 여부만!)
    try:
        tracks = _load_video_tracks()
        fp = target_fp or (tracks.get(original_path) if original_path else None)
        if fp:
            entry = tracks.get(fp, {}) if fp in tracks else {}
            last_path = entry.get("last_path", "")
            if last_path and last_path != original_path and os.path.exists(last_path) and os.path.isfile(last_path):
                # 파일명도 같은지 확인하여 신뢰성 보장
                if os.path.basename(last_path) == target_name:
                    _log_to_file(f"🎯 [Tracking] 장부 기록 매칭으로 대체 성공냥!: {last_path}")
                    try:
                        update_video_track(last_path)
                    except Exception:
                        pass
                    return last_path
    except Exception as e:
        _log_to_file(f"⚠️ [Tracking Warning] 장부 매칭 중 예외 발생: {e}")

    # AI냥 지침에 따라 무거운 디렉토리 전수 DNA 해싱 대조(전략 3, 4)는 완전 생략하고 신속히 None 반환냥! 🤫
    _log_to_file(f"🔍 [Tracking] 파일 매칭 실패 (파일명 탐색 범위 초과): {target_name}")
    return None

# [TAG: #@_clean_file_icons]
def _clean_file_icons(s):
    """[V8.16] 파일 목록의 표시 문자열에서 아이콘(🎬, 🎵, 📄, 📎)을 확실하게 제거합니다. ✨"""
    if not s: return ""
    # 알려진 아이콘들 및 공백 제거
    res = s.replace("🎬", "").replace("🎵", "").replace("📄", "").replace("📎", "").strip()
    return res

