# [TAG: #@get_affection_band]
def get_affection_band(score: int) -> tuple:
    """[Nostalgia] 호감도 점수(0~100)로부터 단계 번호와 밴드명을 반환합니다. 💖"""
    try:
        score = max(0, min(100, int(score)))
    except Exception:
        score = 15
    if score < 20: return 1, "무관심"
    elif score < 40: return 2, "의식"
    elif score < 60: return 3, "호감"
    elif score < 80: return 4, "애정"
    else: return 5, "사랑"

