# [TAG: #@_get_drive_usage_fancy]
def _get_drive_usage_fancy(path):
    """[V122.8] AI냥 요청: 사용률에 따라 색상(🟢🟡🔴)과 달 위상(🌑~🌕)이 변하는 킹갓 트윈 이모지 헤더 🟢🌓🎨💎✨"""
    try:
        total, used, free = shutil.disk_usage(path)
        percent = (used / total) * 100

        # 1. 색상 결정 (텍스트 및 이모지 서클용) 🎨
        if percent < 60:
            color = C.LIGHT_GREEN
            circle = "🟢"
        elif percent < 90:
            color = C.YELLOW
            circle = "🟡"
        else:
            color = C.RED
            circle = "🔴"

        # 2. 채워지는 달 위상 결정 (5단계) - [V122.9] AI냥 요청: 남은 공간 기준으로 반대로 해석 🌕
        # 꽉 찬 경우(사용률 100%) 흑색달(🌑), 텅 빈 경우(사용률 0%) 보름달(🌕)
        free_percent = 100 - percent
        phases = ['🌑', '🌒', '🌓', '🌔', '🌕']
        phase_idx = min(4, int(free_percent // 20))
        moon = phases[phase_idx]

        # 3. 데이터 포맷팅
        t_gb = total / (1024**3)
        u_gb = used / (1024**3)
        f_gb = free / (1024**3)

        # 4. 상태 요정 얼굴 결정 (용량 넉넉할 땐 웃고, 부족할 땐 헐!) 😊😱
        face = "😊" if percent < 90 else "😱"

        # 결과 결합: 🟢 55.4% · 480/500G · 🌓 😊 20G Free
        # [V122.12] AI냥 요청: 달 옆에 사람 모양 이모지 추가! (넉넉할 땐 웃고 부족할 땐 헐) ✨
        # [V18.10] AI냥 요청: 여기도 사용량(u_gb) 대신 남은용량(f_gb)이 우선 보이게냥! 💾✨
        res = f"{circle} {color}{percent:.1f}%{C.RESET} · {C.SKY}{f_gb:.0f}{C.RESET}/{t_gb:.0f}G · {moon} {face} {C.SKY}{f_gb:.1f}G Free{C.RESET}"
        return res
    except:
        return ""

# [TAG: #@_get_playlists_dir]
def _get_playlists_dir(is_music=False):
    """[V61.15] 플레이리스트 저장 폴더를 지능적으로 탐색합니다. (설정/실행파일 경로 하위 playlists, playlists.music 순) 🛰️✨"""
    script_dir = os.path.dirname(os.path.abspath(__file__))
    if is_music:
        # [V78.0] 폴더명 통일: playlists.music ✨
        search_dirs = ["playlists.music", "playlists", "playlist"]
    else:
        search_dirs = ["playlists", "playlist"]
    for d in search_dirs:
        target = os.path.join(script_dir, d)
        if os.path.exists(target):
            return target
    return os.path.join(script_dir, "playlists.music" if is_music else "playlists")

# [TAG: #@safe_html]
def safe_html(text: str) -> str:
    """[V36.4] 텔레그램 허용 태그(blockquote 포함)는 보존하되, 따옴표 이스케이프 및 a 태그 프로토콜을 안전하게 정제함 🛡️"""
    if not text: return ""

    # 1. 모든 문자를 안전하게 이스케이프 (따옴표 포함)
    escaped = html.escape(str(text), quote=True)

    # 2. 텔레그램 지원 단일 태그 복구 (blockquote 포함 📜✨)
    allowed_tags = ['b', 'strong', 'i', 'em', 'u', 'ins', 's', 'strike', 'del', 'code', 'pre', 'tg-spoiler', 'blockquote']
    for tag in allowed_tags:
        escaped = escaped.replace(f"&lt;{tag}&gt;", f"<{tag}>")
        escaped = escaped.replace(f"&lt;/{tag}&gt;", f"</{tag}>")
        escaped = escaped.replace(f"&lt;{tag.upper()}&gt;", f"<{tag.upper()}>")
        escaped = escaped.replace(f"&lt;/{tag.upper()}&gt;", f"</{tag.upper()}>")

    # [신규] expandable blockquote 태그 복구
    escaped = re.sub(r'&lt;blockquote\s+expandable&gt;', '<blockquote expandable>', escaped, flags=re.IGNORECASE)

    # 3. <a> 태그 복구 (http, https, tg 프로토콜만 허용하여 텔레그램 정책 준수)
    # [TAG: #@restore_link]
    def restore_link(match):
        attrs = match.group(1) # href=&quot;URL&quot; 등
        inner = match.group(2) # 링크 텍스트
        # href="URL" 또는 href='URL' (이스케이프된 따옴표 대응) 추출
        href_match = re.search(r'href=(?:&quot;|&#x27;)(.*?)(?:&quot;|&#x27;)', attrs)
        if href_match:
            url = href_match.group(1).replace("&amp;", "&")
            if url.lower().startswith(('http://', 'https://', 'tg://')):
                return f'<a href="{url}">{inner}</a>'
        # 허용되지 않는 프로토콜이나 형식이면 이스케이프된 채로 유지
        return f"&lt;a {attrs}&gt;{inner}&lt;/a&gt;"

    # [V36.3] <a>...</a> 쌍을 한꺼번에 처리하여 밸런스 붕괴 방지
    escaped = re.sub(r'&lt;a\s+(.*?)&gt;(.*?)&lt;/a&gt;', restore_link, escaped, flags=re.IGNORECASE | re.DOTALL)

    return escaped

# [TAG: #@_get_actual_console_hwnd]
_G_CONSOLE_HWND_CACHE = (None, 0.0)
# [TAG: #@_get_actual_console_hwnd]

def _get_actual_console_hwnd():
    """[V142.44] 최적화: 콘솔 핸들을 캐싱하여 시스템 호출 부하 감소 (CPU 다이어트 🧼✨)"""
    global _G_CONSOLE_HWND_CACHE
    if os.name != 'nt': return None

    now = time.time()
    if _G_CONSOLE_HWND_CACHE[0] and (now - _G_CONSOLE_HWND_CACHE[1] < 3.0): # 3초 동안 캐시 유지
        try:
            if ctypes.windll.user32.IsWindow(_G_CONSOLE_HWND_CACHE[0]):
                return _G_CONSOLE_HWND_CACHE[0]
        except Exception:
            pass

    try:
        hwnd = ctypes.windll.kernel32.GetConsoleWindow()
        if not hwnd:
            _G_CONSOLE_HWND_CACHE = (None, now)
            return None
        last_hwnd = hwnd
        while True:
            parent = ctypes.windll.user32.GetParent(last_hwnd)
            if not parent: break
            last_hwnd = parent
        root_hwnd = ctypes.windll.user32.GetAncestor(hwnd, 2)
        res = last_hwnd if last_hwnd else (root_hwnd if root_hwnd else hwnd)
        _G_CONSOLE_HWND_CACHE = (res, now)
        return res
    except:
        return None

# [V29.2] 안시 컬러 속성 부재 시 에러를 방지하기 위한 안전 장치 메타클래스 🛡️
class SafeColor(type):
    # [TAG: #@__getattr__]
    def __getattr__(cls, name):
        # [V29.2] 속성 호출 시 존재하지 않으면 에러 대신 RESET 반환 및 로그 기록 📝
        if name not in ['__wrapped__', '__fallback__']: # 린트/특수 속성 제외
            _log_to_file(f"🎨 [SafeColor Warning] 정의되지 않은 컬러 속성 호출됨: C.{name} (RESET으로 대체됨)")
        return getattr(cls, 'RESET', '')

