# [TAG: #@_set_title_throttled]

def _set_title_throttled(title: str):
    global _G_LAST_CONSOLE_TITLE
    if globals().get("_G_SLEEP_MODE", False) and not title.startswith("[💤 SLEEP]"):
        title = f"[💤 SLEEP] {title}"
    if title != _G_LAST_CONSOLE_TITLE:
        try:
            ctypes.windll.kernel32.SetConsoleTitleW(title)
            _G_LAST_CONSOLE_TITLE = title
        except Exception as e:
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")
