# [TAG: #@_len_ansi]
def _len_ansi(text: str) -> int:
    """ANSI 탈출 코드를 제외한 실제 출력되는 문자열의 시각적 길이를 계산합니다."""
    # ANSI escape sequences 제거용 정규표현식
    ansi_escape = re.compile(r'\033\[[0-9;]*m')
    clean_text = ansi_escape.sub('', text)

    # [V35.0] 한글 등 와이드 문자는 2칸으로 계산하는 로직 (정확도 향상 📏)
    import unicodedata
    visual_len = 0
    for char in clean_text:
        if unicodedata.east_asian_width(char) in ('F', 'W'):
            visual_len += 2
        else:
            visual_len += 1
    return visual_len

# [TAG: #@_center_ansi]
def _center_ansi(text: str, width: int) -> str:
    """ANSI 코드가 포함된 문자열을 지정된 폭의 중앙에 정렬합니다."""
    vlen = _len_ansi(text)
    if vlen >= width: return text
    left_pad = (width - vlen) // 2
    right_pad = width - vlen - left_pad
    return f"{' ' * left_pad}{text}{' ' * (right_pad if right_pad > 0 else 0)}"

_LAST_AIMP_TITLE = None
_LAST_AIMP_CHECK_TIME = 0

def get_aimp_song_title():
    """[V163.3] AIMP로 재생 중인 곡 제목을 가져옵니다. (64비트 SendMessageTimeoutW 안전화) 🎵"""
    global _LAST_AIMP_TITLE, _LAST_AIMP_CHECK_TIME
    if os.name != 'nt':
        return None
    now = time.time()
    if now - _LAST_AIMP_CHECK_TIME < 1.5:
        return _LAST_AIMP_TITLE
    _LAST_AIMP_CHECK_TIME = now
    
    ret_title = None
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        
        # 1. AIMP 재생 상태 체크 (Remote API - AIMP5 호환형 + 락 방지 타임아웃 📻✨)
        hwnd_remote = user32.FindWindowW("AIMP2_RemoteInfo", None)
        if hwnd_remote:
            result = ctypes.c_size_t(0)
            ret = user32.SendMessageTimeoutW(
                hwnd_remote,
                0x0477, # WM_AIMP_PROPERTY
                64,     # AIMP_RA_PROPERTY_PLAYER_STATE
                0,
                2,      # SMTO_ABORTIFHUNG (응답 없음 시 즉시 에러 리턴)
                100,    # 100ms 타임아웃
                ctypes.byref(result)
            )
            state = result.value if ret else 0
            
            # state == 2 인 경우에만 현재 재생 중(Playing)입니다냥!
            if state == 2:
                # 2. 재생 중일 때만 TAIMPMainForm 창 타이틀에서 곡명 획득냥!
                hwnd_main = user32.FindWindowW("TAIMPMainForm", None)
                if hwnd_main:
                    buf = ctypes.create_unicode_buffer(512)
                    user32.GetWindowTextW(hwnd_main, buf, 512)
                    title = buf.value.strip()
                    if title and not any(title == x for x in ["AIMP", "AIMP3", "AIMP4", "AIMP5"]):
                        ret_title = title
    except Exception as e:
        _log_to_file(f"⚠️ [get_aimp_song_title Error] {e}")
    _LAST_AIMP_TITLE = ret_title
    return ret_title


