# [TAG: #@_pure_norm_global]
def _pure_norm(text):
    """팟플레이어 창 제목 및 파일명 비교를 위한 순수 정규화 헬퍼 (전역 공용) 🧼💎"""
    if not text: return ""
    import re
    t = str(text)
    # 1. 접미어 제거 (" - 팟플...", " - PotPlayer...", " - 팟플레이어", " - BINU_KOREA_SRT_")
    t = re.sub(r'\s*-\s*(?:팟플[^\s]*|PotPlayer[^\s]*|BINU[^\s]*)\s*$', '', t, flags=re.IGNORECASE)
    for suffix in [" - PotPlayer", " - 팟플레이어", " - BINU_KOREA_SRT_"]:
        if suffix in t:
            t = t.split(suffix)[0]

    # 2. 접두어 제거 (🎨 [Playlist], 🔍[✅SYNC], [1/10] 등)
    t = re.sub(r'^🔍\[.*?\]\s*', '', t)
    t = re.sub(r'^\[.*?\]\s*', '', t)
    t = re.sub(r'^\d+\.\s*', '', t)

    # 3. 비알파뉴메릭 특수기호 소각 및 소문자화
    return re.sub(r'[^\w]', '', t).strip().lower()

def is_potplayer_playing(target_pid=None):
    """ [V164.5] 팟플레이어가 단순히 켜져 있는 것뿐만 아니라 '실제로 재생 중(Playing)'이거나 미디어가 로드되어 있는지 EnumWindows 전수조사로 정밀 감지한다냥! 🎬⚡ """
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32

        # 1. EnumWindows로 실행 중인 모든 팟플레이어 윈도우 전수 조사 🕵️‍♂️
        hwnds = []
        def _enum_pot_proc(hwnd, lparam):
            class_buf = ctypes.create_unicode_buffer(256)
            user32.GetClassNameW(hwnd, class_buf, 256)
            if class_buf.value in ["PotPlayer64", "PotPlayerMini64", "PotPlayer"]:
                if target_pid:
                    lp_pid = wintypes.DWORD()
                    user32.GetWindowThreadProcessId(hwnd, ctypes.byref(lp_pid))
                    if lp_pid.value == target_pid:
                        hwnds.append((hwnd, class_buf.value))
                else:
                    hwnds.append((hwnd, class_buf.value))
            return True

        ENUM_PROC = ctypes.WINFUNCTYPE(ctypes.c_bool, wintypes.HWND, wintypes.LPARAM)
        user32.EnumWindows(ENUM_PROC(_enum_pot_proc), 0)

        # EnumWindows 실패 시 FindWindowW 폴백
        if not hwnds:
            for class_name in ["PotPlayer64", "PotPlayerMini64", "PotPlayer"]:
                h = user32.FindWindowW(class_name, None)
                if h: hwnds.append((h, class_name))

        if not hwnds:
            # 팟플 프로세스 자체가 없으면 False
            return False

        for hwnd, class_name in hwnds:
            # 2. 팟플레이어 Win32 API로 재생 상태 직접 조회 📡
            # WM_USER = 0x0400, POT_GET_PLAY_STATUS = 0x5004
            status_res = ctypes.c_size_t(0)
            ret = user32.SendMessageTimeoutW(hwnd, 0x0400, 0x5004, 0, 0x0002, 500, ctypes.byref(status_res))
            if ret != 0:
                play_status = status_res.value
                if play_status == 2:  # 2: 재생 중 (Playing)
                    _log_to_file(f"🎬 [PotPlayer State] Win32 API 재생 중 감지됨 (Status=2, HWND={hwnd})")
                    return True
                elif play_status == 1:  # 1: 일시정지 (미디어 로드됨)
                    _log_to_file(f"🎬 [PotPlayer State] Win32 API 일시정지(미디어 로드) 감지됨 (Status=1, HWND={hwnd})")
                    return True

            # 3. 보조 검사: 창 제목에 실제 미디어 파일명이 포함되어 있는지 검사 🕵️‍♂️
            buf = ctypes.create_unicode_buffer(512)
            user32.GetWindowTextW(hwnd, buf, 512)
            title = buf.value.strip()
            generic_names = ["PotPlayer", "PotPlayer64", "PotPlayerMini64", "팟플레이어", "PotPlayer Mini"]
            if title and not any(g == title for g in generic_names) and len(title) >= 3:
                _log_to_file(f"🎬 [PotPlayer State] 창 제목 기반 미디어 로드 감지: {title}")
                return True

        # 4. 최후 보조: 우리 앱의 팟플 모니터링 스레드가 돌고 있는 경우도 재생 중으로 인정
        if globals().get('_g_potplayer_monitor_running') or globals().get('_g_potplayer_current_path'):
            _log_to_file("🎬 [PotPlayer State] 모니터링 스레드 활성 상태 기반 감지 완료")
            return True

    except Exception as e:
        _log_to_file(f"⚠️ [is_potplayer_playing Error] {e}")
    return False

def _get_active_potplayer_dpl_path():
    """ 현재 시스템의 활성 팟플레이어 .dpl 파일 경로를 반환한다냥! 📁 """
    appdata = os.environ.get("APPDATA", "")
    candidates = [
        os.path.join(appdata, r"PotPlayer64\Playlist\PotPlayer64.dpl"),
        os.path.join(appdata, r"PotPlayerMini64\Playlist\PotPlayerMini64.dpl"),
        os.path.join(appdata, r"PotPlayer\Playlist\PotPlayer.dpl")
    ]
    for p in candidates:
        if os.path.exists(p):
            return p
    return None

def _backup_current_potplayer_state(s=None):
    """ [V164.21] DPL 재생 직전 기존 팟플 재생 상태(우리앱 DPL / 외부 DPL / 단일 파일)를 정밀 구분하여 temp에 완벽 백업한다냥! 💾🎬 """
    global _g_was_video_backup_dpl_path, _g_was_video_backup_single_path
    _g_was_video_backup_dpl_path = None
    _g_was_video_backup_single_path = None
    
    try:
        temp_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "temp")
        existing_temp_dpl = os.path.join(temp_dir, "Binu_Auto_Playlist.dpl")
        has_existing_dpl = os.path.exists(existing_temp_dpl) and os.path.getsize(existing_temp_dpl) > 0
        old_mem_paths = globals().get('_g_potplayer_dpl_paths', [])

        # [V164.21] 팟플이 실행 중이거나, 기존 DPL 파일/메모리 목록이 존재하면 무조건 플리 상호전환(Prev DPL) 백업 수행! 🎬⚡
        if not (is_potplayer_playing() or is_potplayer_running() or has_existing_dpl or old_mem_paths):
            return False

        _gl_s = s or globals().get('_gl_settings') or globals().get('settings')
        curr_title = _get_potplayer_title()
        single_path = None

        # 1. 창 제목 기반 현재 재생 중인 실제 파일 경로 정밀 역추적 🕵️‍♂️
        if curr_title:
            ct_clean = curr_title.strip()
            # 접미어 잘림 방어 (" - 팟플레", " - PotPlayer..." 등 제거)
            ct_clean_file = re.sub(r'\s*-\s*(?:팟플[^\s]*|PotPlayer[^\s]*|BINU[^\s]*)\s*$', '', ct_clean, flags=re.IGNORECASE).strip()
            generic_names = ["PotPlayer", "PotPlayer64", "PotPlayerMini64", "팟플레이어", "PotPlayer Mini"]
            if not any(g == ct_clean for g in generic_names) and len(ct_clean) >= 3:
                # 1-1. 제목에서 확장자 포함된 순수 파일명 직접 추출
                ext_match = re.search(r'([^\r\n\\/:*?"<>|]+\.(?:mp4|mkv|avi|ts|wmv|mov|flv|webm|m4v|tp|mp3|flac|wav|aac|m4a|ogg))', ct_clean_file, re.IGNORECASE)
                extracted_fn = ext_match.group(1).strip() if ext_match else ct_clean_file

                # 1-2. 기존 메모리 리스트(_g_potplayer_dpl_paths)에서 최우선 탐색!
                if old_mem_paths:
                    for p in old_mem_paths:
                        if not p or not os.path.isfile(p): continue
                        fn = os.path.basename(p)
                        if fn.lower() == extracted_fn.lower() or _pure_norm(fn) == _pure_norm(ct_clean_file) or (_pure_norm(fn) and _pure_norm(fn) in _pure_norm(ct_clean_file)):
                            single_path = os.path.abspath(p)
                            break
                    if not single_path:
                        fpath_mem, _ = _add_potplayer_recent(_gl_s, find_title=ct_clean_file, dpl_paths=old_mem_paths, skip_save=True)
                        if fpath_mem and os.path.isfile(fpath_mem):
                            single_path = os.path.abspath(fpath_mem)

                # 1-3. 현재 작업 폴더 및 최근 폴더에서 추출된 파일명 직접 탐색
                if not single_path and extracted_fn:
                    cur_d = globals().get('current_dir') or globals().get('_last_known_dir')
                    candidate_dirs = [cur_d] if cur_d and os.path.isdir(cur_d) else []
                    if _gl_s and hasattr(_gl_s, 'data'):
                        hist_dirs = _gl_s.data.get('recent_folders', [])
                        candidate_dirs.extend([hd for hd in hist_dirs if hd and os.path.isdir(hd)])
                    for cd in candidate_dirs:
                        cp = os.path.join(cd, extracted_fn)
                        if os.path.isfile(cp):
                            single_path = os.path.abspath(cp)
                            break
                        try:
                            for real_f in os.listdir(cd):
                                if _pure_norm(real_f) == _pure_norm(extracted_fn) and os.path.isfile(os.path.join(cd, real_f)):
                                    single_path = os.path.abspath(os.path.join(cd, real_f))
                                    break
                        except: pass
                        if single_path: break

                # 1-4. DPL 파일 역추적
                if not single_path:
                    fpath, _ = _get_sync_path_dpl(_gl_s, find_title=ct_clean_file)
                    if fpath and os.path.isfile(fpath) and not fpath.lower().endswith(('.dpl', '.m3u', '.m3u8')):
                        single_path = os.path.abspath(fpath)
                
                # 1-5. 최근 재생 기록 역추적
                if not single_path:
                    fpath2, _ = _add_potplayer_recent(_gl_s, find_title=ct_clean_file, skip_save=True)
                    if fpath2 and os.path.isfile(fpath2) and not fpath2.lower().endswith(('.dpl', '.m3u', '.m3u8')):
                        single_path = os.path.abspath(fpath2)
                
                # 1-6. 전역 경로 캐시 대조
                if not single_path:
                    for cp in [globals().get('_g_potplayer_current_path'), globals().get('_G_LAST_POTPLAYER_RESOLVED_PATH')]:
                        if cp and os.path.isfile(cp) and not cp.lower().endswith(('.dpl', '.m3u', '.m3u8')):
                            fn = os.path.splitext(os.path.basename(cp))[0].lower()
                            if fn and (fn in ct_clean_file.lower() or _pure_norm(fn) in _pure_norm(ct_clean_file)):
                                single_path = os.path.abspath(cp)
                                break

        # 1-7. [안전망 Fallback] 제목 역추적이 실패했더라도 마지막 재생 파일이 존재하면 fallback 채택! 🛡️💎
        if not single_path:
            for cp in [globals().get('_g_potplayer_current_path'), globals().get('_G_LAST_POTPLAYER_RESOLVED_PATH')]:
                if cp and os.path.isfile(cp) and not cp.lower().endswith(('.dpl', '.m3u', '.m3u8')):
                    single_path = os.path.abspath(cp)
                    _log_to_file(f"💾 [DPL Backup] 제목 역추적 미스 → 전역 마지막 재생 파일로 Fallback 성공: {os.path.basename(single_path)}")
                    break
        if not single_path and old_mem_paths:
            for p in old_mem_paths:
                if p and os.path.isfile(p):
                    single_path = os.path.abspath(p)
                    _log_to_file(f"💾 [DPL Backup] 메모리 플레이리스트 첫 번째 파일로 Fallback 성공: {os.path.basename(single_path)}")
                    break

        temp_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "temp")
        os.makedirs(temp_dir, exist_ok=True)
        backup_dpl = os.path.join(temp_dir, "Binu_Auto_Playlist_Prev.dpl")
        backup_dpl_created = False
        existing_temp_dpl = os.path.join(temp_dir, "Binu_Auto_Playlist.dpl")

        if single_path and os.path.isfile(single_path):
            _g_was_video_backup_single_path = single_path

            # [구분 1] 우리 앱이 이전에 생성했던 DPL 플레이리스트(메모리/temp 파일)에서 재생 중이었던 경우! 🎯
            old_mem_paths = globals().get('_g_potplayer_dpl_paths', [])
            
            # 1-A. 메모리 리스트에 single_path가 존재하는 경우 (우리 앱 DPL 재생 중)
            if old_mem_paths and any(os.path.abspath(p).lower() == single_path.lower() for p in old_mem_paths if p):
                try:
                    matched_idx = 0
                    for idx, p in enumerate(old_mem_paths):
                        if p and os.path.abspath(p).lower() == single_path.lower():
                            matched_idx = idx
                            break
                    
                    _saved_ctx_header = ""
                    if os.path.exists(existing_temp_dpl):
                        try:
                            with open(existing_temp_dpl, "r", encoding="utf-8", errors="replace") as _ef:
                                for _el in _ef:
                                    if _el.startswith("#context_key="):
                                        _saved_ctx_header = _el.strip() + "\r\n"
                                        break
                        except Exception: pass

                    with open(backup_dpl, "w", encoding="utf-8", errors="replace") as f:
                        f.write("DAUMPLAYLIST\r\n")
                        if _saved_ctx_header:
                            f.write(_saved_ctx_header)
                        f.write(f"playname={single_path}\r\n")
                        f.write(f"playindex={matched_idx}\r\n")
                        f.write(f"topindex={matched_idx}\r\n")
                        f.write(f"itemcount={len(old_mem_paths)}\r\n")
                        for i, p in enumerate(old_mem_paths):
                            abs_p = os.path.abspath(p)
                            title = os.path.basename(p)
                            f.write(f"{i+1}*file*{abs_p}\r\n")
                            f.write(f"{i+1}*title*{title}\r\n")
                    
                    _g_was_video_backup_dpl_path = backup_dpl
                    backup_dpl_created = True
                    _log_to_file(f"💾 [DPL Backup] 우리앱 기존 DPL 플레이리스트 격리 백업 성공! (총 {len(old_mem_paths)}개 파일, 현재시청: {os.path.basename(single_path)}, 인덱스: {matched_idx}) 🎬✨")
                except Exception as ex_mem:
                    _log_to_file(f"⚠️ [Mem DPL Backup Error] {ex_mem}")

            # 1-B. temp/Binu_Auto_Playlist.dpl 파일에 single_path가 존재하는 경우
            if not backup_dpl_created and os.path.exists(existing_temp_dpl):
                try:
                    dpl_content = _read_dpl(existing_temp_dpl)
                    if single_path.lower() in dpl_content.lower() or os.path.basename(single_path).lower() in dpl_content.lower():
                        dpl_lines = dpl_content.splitlines()
                        found_idx = 0
                        file_count = 0
                        for l in dpl_lines:
                            if "*file*" in l:
                                file_count += 1
                                f_part = l.split("*file*", 1)[1].strip()
                                if f_part.lower() == single_path.lower() or os.path.basename(f_part).lower() == os.path.basename(single_path).lower():
                                    found_idx = file_count - 1
                        
                        new_lines = []
                        for l in dpl_lines:
                            if l.startswith("playname="):
                                new_lines.append(f"playname={single_path}")
                            elif l.startswith("playindex="):
                                new_lines.append(f"playindex={found_idx}")
                            elif l.startswith("topindex="):
                                new_lines.append(f"topindex={found_idx}")
                            else:
                                new_lines.append(l)
                        
                        with open(backup_dpl, "w", encoding="utf-8", errors="replace") as f:
                            f.write("\r\n".join(new_lines) + "\r\n")
                            
                        _g_was_video_backup_dpl_path = backup_dpl
                        backup_dpl_created = True
                        _log_to_file(f"💾 [DPL Backup] temp DPL 파일 재생 인덱스 보정 백업 성공! ({os.path.basename(single_path)}, 인덱스: {found_idx})")
                except Exception as ex_temp:
                    _log_to_file(f"⚠️ [Temp DPL Backup Error] {ex_temp}")

            # [구분 2] 팟플레이어 기본 AppData DPL에 single_path가 존재하는 경우 (외부 플리 재생 중) 📂
            if not backup_dpl_created:
                active_dpl = _get_active_potplayer_dpl_path()
                if active_dpl and os.path.exists(active_dpl):
                    try:
                        dpl_content = _read_dpl(active_dpl)
                        if single_path.lower() in dpl_content.lower() or os.path.basename(single_path).lower() in dpl_content.lower():
                            lines = dpl_content.splitlines()
                            new_lines = []
                            play_idx = 0
                            for line in lines:
                                if line.startswith("playname="):
                                    new_lines.append(f"playname={single_path}")
                                elif line.startswith("playindex=") or line.startswith("topindex="):
                                    continue
                                else:
                                    if "*file*" in line and (single_path.lower() in line.lower() or os.path.basename(single_path).lower() in line.lower()):
                                        try: play_idx = int(line.split("*file*")[0]) - 1
                                        except: pass
                                    new_lines.append(line)
                            
                            if new_lines and new_lines[0].strip() == "DAUMPLAYLIST":
                                new_lines.insert(1, f"topindex={play_idx}")
                                new_lines.insert(1, f"playindex={play_idx}")
                                if not any(l.startswith("playname=") for l in new_lines):
                                    new_lines.insert(1, f"playname={single_path}")
                            
                            with open(backup_dpl, "w", encoding="utf-8", errors="replace") as f:
                                f.write("\r\n".join(new_lines) + "\r\n")
                            
                            _g_was_video_backup_dpl_path = backup_dpl
                            backup_dpl_created = True
                            _log_to_file(f"💾 [DPL Backup] 팟플 기본 플레이리스트 동기화 백업 성공 (인덱스: {play_idx})")
                    except Exception as ex_dpl:
                        _log_to_file(f"⚠️ [DPL Sync Backup Error] {ex_dpl}")

            # [구분 3] 어디에도 플리가 없으면 single_path 단일 파일 전용 클린 DPL 생성! 🎬
            if not backup_dpl_created:
                try:
                    with open(backup_dpl, "w", encoding="utf-8", errors="replace") as f:
                        f.write("DAUMPLAYLIST\r\n")
                        f.write(f"playname={single_path}\r\n")
                        f.write("playindex=0\r\n")
                        f.write("topindex=0\r\n")
                        f.write("itemcount=1\r\n")
                        f.write(f"1*file*{single_path}\r\n")
                        f.write(f"1*title*{os.path.basename(single_path)}\r\n")
                    _g_was_video_backup_dpl_path = backup_dpl
                    backup_dpl_created = True
                    _log_to_file(f"💾 [DPL Backup] 단일 파일 전용 클린 DPL 백업 생성 완료: {os.path.basename(single_path)}")
                except Exception as ex_single:
                    _log_to_file(f"⚠️ [Clean DPL Backup Error] {ex_single}")

        # [구분 4] single_path 특정 실패 시에도 기존 temp DPL 또는 메모리 리스트가 존재하면 무조건 백업 보존! 🛡️💎
        if not backup_dpl_created:
            if os.path.exists(existing_temp_dpl) and os.path.getsize(existing_temp_dpl) > 0:
                try:
                    import shutil
                    shutil.copy2(existing_temp_dpl, backup_dpl)
                    _g_was_video_backup_dpl_path = backup_dpl
                    backup_dpl_created = True
                    _log_to_file(f"💾 [DPL Backup] 기존 Binu_Auto_Playlist.dpl 직접 복제 백업 성공! 📋✨")
                except Exception as ex_cp:
                    _log_to_file(f"⚠️ [Direct DPL Copy Backup Error] {ex_cp}")
            elif old_mem_paths:
                try:
                    with open(backup_dpl, "w", encoding="utf-8", errors="replace") as f:
                        f.write("DAUMPLAYLIST\r\n")
                        f.write(f"playname={old_mem_paths[0]}\r\n")
                        f.write("playindex=0\r\n")
                        f.write("topindex=0\r\n")
                        f.write(f"itemcount={len(old_mem_paths)}\r\n")
                        for i, p in enumerate(old_mem_paths):
                            abs_p = os.path.abspath(p)
                            title = os.path.basename(p)
                            f.write(f"{i+1}*file*{abs_p}\r\n")
                            f.write(f"{i+1}*title*{title}\r\n")
                    _g_was_video_backup_dpl_path = backup_dpl
                    backup_dpl_created = True
                    _log_to_file(f"💾 [DPL Backup] 메모리 리스트 기반 DPL 백업 생성 완료! (총 {len(old_mem_paths)}개 파일) 🎬✨")
                except Exception as ex_memp:
                    _log_to_file(f"⚠️ [Mem List DPL Backup Error] {ex_memp}")

        return bool(backup_dpl_created or single_path)
    except Exception as e:
        _log_to_file(f"⚠️ [_backup_current_potplayer_state Error] {e}")
        return False

def _is_music_playing_now():
    """ [V163.0] DPL 시작 전 노래(AIMP 등)가 재생 중이었는지 정밀 감지한다냥! 🎵 """
    try:
        title = get_aimp_song_title()
        if title and len(str(title).strip()) > 0:
            return True
        if globals().get('_last_aimp_menu_title'):
            return True
    except Exception as e:
        _log_to_file(f"⚠️ [_is_music_playing_now Error] {e}")
    return False

_g_was_media_backup_volume = None
_g_last_dpl_backup_time = 0

def _check_and_mark_media_playing_before_dpl(s=None):
    """ [V164.21] 새치기 미디어 재생 시작 직전에(볼륨 조절 전!) 영상, 노래 및 원본 볼륨 상태를 정확히 1회만 기록한다냥! 🎬🎵🔊 """
    global _g_was_music_playing_before_dpl, _g_was_video_backup_dpl_path, _g_was_video_backup_single_path, _g_was_media_backup_volume, _g_last_dpl_backup_time
    try:
        _now = time.time()
        _gl_s = s or globals().get('_gl_settings') or globals().get('settings')
        
        # 1. [V164.21] 영상(기존 팟플) 백업 - 자동복원 옵션과 무관하게 플리 상호전환(Prev DPL)을 위해 항상 백업 수행! 🎬⚡
        temp_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "temp")
        existing_temp_dpl = os.path.join(temp_dir, "Binu_Auto_Playlist.dpl")
        has_existing_dpl = os.path.exists(existing_temp_dpl) and os.path.getsize(existing_temp_dpl) > 0
        old_mem_paths = globals().get('_g_potplayer_dpl_paths', [])

        if is_potplayer_playing() or is_potplayer_running() or has_existing_dpl or old_mem_paths or globals().get('_g_potplayer_current_path'):
            # 팟플 실행/재생 중일 때의 현재 볼륨을 정확히 백업 🔊
            try:
                _cur_v = _get_system_volume()
                if _cur_v is not None and _cur_v >= 0:
                    _g_was_media_backup_volume = _cur_v
            except Exception: pass
            
            backed_up = _backup_current_potplayer_state(_gl_s)
            if backed_up:
                _g_last_dpl_backup_time = _now
                _g_was_music_playing_before_dpl = False
                prev_info = os.path.basename(_g_was_video_backup_single_path) if _g_was_video_backup_single_path else (_g_was_video_backup_dpl_path and os.path.basename(_g_was_video_backup_dpl_path)) or "기존 플레이리스트"
                _log_to_file(f"🎬 [DPL 새치기 감지] 이전에 재생 중이던 영상({prev_info}) 감지됨 → 이전 볼륨: {_g_was_media_backup_volume}% 백업 완료! 🎬🔄✨")
                return
                
        _g_was_video_backup_dpl_path = None
        _g_was_video_backup_single_path = None

        # 2. 노래 복원 옵션 체크
        music_enabled = _gl_s.data.get("audio_dpl_auto_restore_music", True) if _gl_s else True
        if music_enabled and _is_music_playing_now():
            try:
                _cur_v = _get_system_volume()
                if _cur_v is not None and _cur_v >= 0:
                    _g_was_media_backup_volume = _cur_v
            except Exception: pass
            _g_was_music_playing_before_dpl = True
            _g_last_dpl_backup_time = _now
            _log_to_file(f"🎵 [DPL 새치기 감지] 이전에 재생 중이던 노래 감지됨 → 이전 볼륨: {_g_was_media_backup_volume}% 백업 완료! 🎵🔄✨")
        else:
            _g_was_music_playing_before_dpl = False
            _g_was_media_backup_volume = None
    except Exception as e:
        _log_to_file(f"⚠️ [_check_and_mark_media_playing_before_dpl Error] {e}")

_check_and_mark_music_playing_before_dpl = _check_and_mark_media_playing_before_dpl

def _restore_media_if_needed(s=None):
    """ [V164.2] 팟플레이어(DPL) 종료 시 끊겼던 영상(플레이리스트) 또는 노래를 다시 재생하고 볼륨도 복구한다냥! 🎬🎵🔊▶️ """
    global _g_was_music_playing_before_dpl, _g_was_video_backup_dpl_path, _g_was_video_backup_single_path, _g_was_media_backup_volume
    try:
        _gl_s = s or globals().get('_gl_settings') or globals().get('settings')

        # 1. 영상 / 이전 플레이리스트 복원 🎬
        video_enabled = _gl_s.data.get("audio_dpl_auto_restore_video", True) if _gl_s else True
        backup_dpl = _g_was_video_backup_dpl_path
        backup_single = _g_was_video_backup_single_path
        restore_vol = _g_was_media_backup_volume
        
        # 중복 실행 방지를 위해 전역 변수 초기화
        _g_was_video_backup_dpl_path = None
        _g_was_video_backup_single_path = None
        _g_was_media_backup_volume = None

        if video_enabled and (backup_dpl or backup_single):
            _g_was_music_playing_before_dpl = False  # 영상 복원 시 노래 복원은 생략
            target_to_play = None
            if backup_dpl and os.path.exists(backup_dpl) and os.path.getsize(backup_dpl) > 0:
                target_to_play = backup_dpl
            elif backup_single and os.path.isfile(backup_single):
                target_to_play = backup_single

            if target_to_play:
                _log_to_file(f"🎬 [DPL Restore] 팟플 종료 감지됨 → 이전 팟플(플리/영상) 복원 실행! 🎬▶️: {target_to_play} (복구 볼륨: {restore_vol}%)")

                def _async_restore_video(target_path, settings_obj, target_vol):
                    try:
                        import ctypes
                        ctypes.windll.ole32.CoInitialize(None)
                        time.sleep(0.5)  # 이전 팟플 프로세스 완전 종료 대기
                        open_path_resilient(target_path)
                        time.sleep(0.5)
                        # [신규] 이전 시청 재개 시 백업 볼륨 복구 작동 🔊✨
                        if target_vol is None or target_vol < 0:
                            target_vol = _get_playlist_target_volume(target_path, s=settings_obj)
                        if target_vol is not None and target_vol >= 0:
                            _set_system_volume(target_vol)
                            _log_to_file(f"🔊 [DPL Restore] 이전 시청 재개에 따라 시스템 볼륨을 {target_vol}%로 복구 완료!")
                        _trigger_potplayer_monitor(settings_obj)
                    except Exception as ex:
                        _log_to_file(f"⚠️ [_async_restore_video Error] {ex}")
                    finally:
                        try:
                            import ctypes
                            ctypes.windll.ole32.CoUninitialize()
                        except: pass

                threading.Thread(target=_async_restore_video, args=(target_to_play, _gl_s, restore_vol), daemon=True).start()

                disp_name = "이전 플레이리스트" if target_to_play.lower().endswith(".dpl") else os.path.basename(target_to_play)
                vol_info = f" {C.YELLOW}(🔊 {restore_vol}% 복구){C.RESET}" if (restore_vol is not None and restore_vol >= 0) else ""
                globals()['_last_bg_notification'] = f"🎬 {C.BOLD}{C.GREEN}[이전 시청 재개]{C.RESET} {disp_name}{vol_info}"
                globals()['_last_bg_notification_time'] = time.time()
                globals()['_global_menu_redraw_flag'] = True
                return

        # 2. 노래 복원 🎵
        if _g_was_music_playing_before_dpl:
            _g_was_music_playing_before_dpl = False  # 중복 실행 방지
            music_enabled = _gl_s.data.get("audio_dpl_auto_restore_music", True) if _gl_s else True
            if music_enabled:
                _log_to_file(f"🎵 [DPL Restore] 팟플 종료 감지됨 → 끊겼던 노래 재생 다시 시작! 🎧▶️ (복구 볼륨: {restore_vol}%)")
                # [신규] 노래 재개 시 백업 볼륨 복구 작동 🔊✨
                if restore_vol is not None and restore_vol >= 0:
                    _set_system_volume(restore_vol)
                    _log_to_file(f"🔊 [DPL Restore] 노래 재생 재개에 따라 시스템 볼륨을 {restore_vol}%로 복구 완료!")
                _pc_control_key('playpause')
                vol_info = f" {C.YELLOW}(🔊 {restore_vol}% 복구){C.RESET}" if (restore_vol is not None and restore_vol >= 0) else ""
                globals()['_last_bg_notification'] = f"🎵 {C.BOLD}{C.GREEN}[노래 재생 재개]{C.RESET}{vol_info}"
                globals()['_last_bg_notification_time'] = time.time()
                globals()['_global_menu_redraw_flag'] = True
    except Exception as e:
        _log_to_file(f"⚠️ [_restore_media_if_needed Error] {e}")

_restore_music_if_needed = _restore_media_if_needed


def _is_app_focused():
    """ [V163.1] 현재 콘솔 창이 윈도우 포커스(활성화) 상태인지 확인한다냥! 🎯 """
    if os.name != 'nt':
        return True
    try:
        import ctypes
        hwnd_console = ctypes.windll.kernel32.GetConsoleWindow()
        if not hwnd_console:
            return True
        hwnd_fg = ctypes.windll.user32.GetForegroundWindow()
        return hwnd_console == hwnd_fg
    except Exception:
        return True


def _get_system_global_idle_time():
    """ [V163.3] 윈도우 시스템 전체(다른 앱 포함) 마우스/키보드 유휴 시간(초)을 반환한다냥! 🖱️⌨️ """
    if os.name != 'nt':
        return 9999.0
    try:
        import ctypes
        from ctypes import wintypes
        class LASTINPUTINFO(ctypes.Structure):
            _fields_ = [("cbSize", wintypes.UINT), ("dwTime", wintypes.DWORD)]
        
        lii = LASTINPUTINFO()
        lii.cbSize = ctypes.sizeof(LASTINPUTINFO)
        if ctypes.windll.user32.GetLastInputInfo(ctypes.byref(lii)):
            millis = (ctypes.windll.kernel32.GetTickCount() & 0xFFFFFFFF) - lii.dwTime
            if millis < 0:
                millis += 0x100000000
            return max(0.0, millis / 1000.0)
    except Exception as e:
        _log_to_file(f"⚠️ [_get_system_global_idle_time Error] {e}")
    return 9999.0

def _is_any_media_playing():
    """ [V163.2] 현재 소리/미디어(AIMP 노래, 팟플레이어 등)가 재생 중인지 확인한다냥! 🎵🎬 """
    try:
        # 1. AIMP 노래 재생 중
        if get_aimp_song_title() or globals().get('_last_aimp_menu_title'):
            return True
            
        # 2. 팟플레이어 실행 중
        if is_potplayer_running():
            return True
            
        # 3. 백그라운드 오디오/미디어 모니터링 플래그 체크
        if globals().get('_is_music_playing', False):
            return True
    except Exception as e:
        _log_to_file(f"⚠️ [_is_any_media_playing Error] {e}")
    return False


_G_PING_ONLINE = True
_G_SHOW_ONLINE_BADGE = False
_G_ONLINE_BADGE_EXPIRY = 0.0

# [TAG: #@_async_ping_check]

def _async_ping_check():
    global _G_PING_ONLINE, _G_SHOW_ONLINE_BADGE, _G_ONLINE_BADGE_EXPIRY
    import subprocess
    try:
        # -n 1: 1번만 핑 전송, -w 1000: 타임아웃 1000ms
        # [수정] Windows 환경 한글 출력에 따른 UnicodeDecodeError 방지를 위해 stdout/stderr를 DEVNULL로 리다이렉트냥! 🚀
        res = subprocess.run(["ping", "-n", "1", "-w", "1000", "168.126.63.1"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        # returncode 0이면 핑 응답 수신 성공냥!
        is_online = (res.returncode == 0)
        
        # [신규] 오프라인 -> 온라인 상태 전환 감지 시 ONLINE 배지 5초 노출 설정 🚀✨
        if is_online and not _G_PING_ONLINE:
            _G_SHOW_ONLINE_BADGE = True
            import time
            _G_ONLINE_BADGE_EXPIRY = time.time() + 5.0
            
        _G_PING_ONLINE = is_online
    except Exception:
        _G_PING_ONLINE = False

# [신규] 카페인 모드 현재 상태 문자열 반환 헬퍼 (앱 리셋 후에도 1시간/2시간 등 예약 시 녹색 🟢 유지) ☕✨
def _get_caffeine_status_display(settings_obj=None, caf_mgr=None):
    if caf_mgr is None:
        caf_mgr = globals().get('caffeine')
    if settings_obj is None:
        settings_obj = globals().get('settings') or globals().get('settings_ref')

    if not caf_mgr or not getattr(caf_mgr, 'is_active', False):
        return "⚫ OFF"

    # [최우선] 항상 켜짐 모드일 경우 무조건 '🟢 ON (항상)' 노출 (타이머 잔여값 무시) ☕♾️
    if settings_obj and hasattr(settings_obj, 'data') and settings_obj.data.get('caffeine_always_on', False):
        return "🟢 ON (항상)"

    now_ts = time.time()
    c_until = settings_obj.data.get('caffeine_until', 0) if settings_obj and hasattr(settings_obj, 'data') else 0
    if c_until and c_until > now_ts:
        rem_sec = int(c_until - now_ts)
        rem_h = rem_sec // 3600
        rem_m = (rem_sec % 3600) // 60
        if rem_h > 0 and rem_m > 0:
            rem_txt = f"{rem_h}시간 {rem_m}분"
        elif rem_h > 0:
            rem_txt = f"{rem_h}시간"
        else:
            rem_txt = f"{max(1, rem_m)}분"
        return f"🟢 ON ({rem_txt})"

    return "🟡 ON"

# ==============================================================================
class TimerAlarmManager:
    # [TAG: #@__init___5]
    def __init__(self):
        self.alarms = [] # 비휘발성 저장 정각 알람 {'time': '1200', 'desc': '저장된 정각 알람', 'active': True}
        self.timers = [] # 휘발성 n분 타이머
        self.running = False
        self.alerting = False
        self.last_alert_time = 0
        self.last_caffeine_off_time = 0  # [중복 도배 방지] 카페인 자동 해제 알림 쿨다운 🛡️☕
        self.ping_counter = 4  # 시작 즉시 실행되도록 4로 설정냥! (5가 되면 실행)

    # [TAG: #@start_3]
    def start(self):
        if self.running: return
        self.running = True
        threading.Thread(target=self._loop, daemon=True).start()

    # [TAG: #@sync_alarms]
    def sync_alarms(self, settings_obj):
        """환경설정(settings)에서 알람을 불러옵니다."""
        self.alarms = settings_obj.data.get('user_alarms', [])
        
        # [자가 치유] 00분이 아닌 알람인데 "정각 알람" 명칭이 들어가 있는 경우 교정 🩹✨
        changed = False
        for a in self.alarms:
            t_str = a.get('time', '')
            desc = a.get('desc', '')
            if len(t_str) == 4 and t_str.isdigit() and not t_str.endswith('00'):
                if "정각 알람" in desc:
                    a['desc'] = desc.replace("정각 알람", "알람")
                    changed = True
        if changed:
            self.save_alarms(settings_obj)

    # [TAG: #@save_alarms]
    def save_alarms(self, settings_obj):
        settings_obj.data['user_alarms'] = self.alarms
        settings_obj.save()

    # [TAG: #@add_timer]
    def add_timer(self, minutes, b_type=None, title=None):
        default_desc = f'{minutes}분 타이머'
        if b_type == 'caffeine_off': default_desc = f'카페인 {minutes}분 타이머'
        
        if title:
            desc = f"[{title}] {default_desc}"
        else:
            desc = default_desc
            
        end_time = time.time() + minutes * 60
        
        # [V22.29] 사용자 요청: 10분 이상 일반 타이머는 비휘발성 정각 알람으로 우회 저장 💾⏳
        if minutes >= 10 and b_type is None:
            import datetime
            target_dt = datetime.datetime.fromtimestamp(end_time)
            time_str = target_dt.strftime("%H%M")
            target_date_str = target_dt.strftime("%Y%m%d")
            
            alarm_dict = {
                'time': time_str,
                'desc': desc,
                'active': True,
                'target_date': target_date_str,
                'end_time': end_time
            }
            self.alarms.append(alarm_dict)
            if 'settings' in globals():
                self.save_alarms(settings)
        else:
            t_dict = {'end_time': end_time, 'desc': desc}
            if b_type: t_dict['type'] = b_type
            self.timers.append(t_dict)

    # [TAG: #@add_alarm]
    def add_alarm(self, time_str, settings_obj, day_offset=None, title=None, is_recurring=False):
        # 형식검증 (HHMM)
        if len(time_str) != 4 or not time_str.isdigit(): return False
        try:
            hour = int(time_str[:2])
            minute = int(time_str[2:])
            import datetime
            now_dt = datetime.datetime.now()
            if day_offset is not None:
                target_dt = now_dt + datetime.timedelta(days=day_offset)
                target_dt = target_dt.replace(hour=hour, minute=minute, second=0, microsecond=0)
            else:
                target_dt = now_dt.replace(hour=hour, minute=minute, second=0, microsecond=0)
                if target_dt <= now_dt:
                    target_dt += datetime.timedelta(days=1)
            target_date_str = target_dt.strftime("%Y%m%d")
            
            day_desc = ""
            if day_offset == 1:
                day_desc = "내일 "
            elif day_offset == 2:
                day_desc = "모레 "
            elif day_offset is not None and day_offset > 2:
                day_desc = f"{day_offset}일 뒤 "
                
            if minute == 0:
                base_desc = f"{day_desc}{hour}시 정각 알람"
            else:
                base_desc = f"{day_desc}{hour}시 {minute}분 알람"
                
            if title:
                desc = f"[{title}] {base_desc}"
            else:
                desc = base_desc
                
            self.alarms.append({
                'time': time_str, 
                'desc': desc, 
                'active': True,
                'target_date': target_date_str,
                'is_recurring': is_recurring
            })
            self.save_alarms(settings_obj)
            return True
        except Exception as e:
            _log_to_file(f"⚠️ [add_alarm Exception] {e}")
            return False

    # [TAG: #@set_timer]
    def set_timer(self, minutes, title=None):
        self.add_timer(minutes, title=title)

    # [TAG: #@cancel]
    def cancel(self, settings_obj=None):
        self.timers.clear()
        self.alarms.clear()
        if settings_obj: self.save_alarms(settings_obj)

    # [TAG: #@cancel_timers_only]
    def cancel_timers_only(self, settings_obj=None):
        """[V22.32] 알람은 유지하고 기존 '타이머'들만 모두 제거합니다냥! 🧹⏳"""
        self.timers.clear()
        self.alarms = [a for a in self.alarms if "타이머" not in a.get('desc', '')]
        _s = settings_obj or globals().get('settings')
        if _s: self.save_alarms(_s)

    # [TAG: #@cancel_alarms_only]
    def cancel_alarms_only(self, settings_obj=None):
        """[V22.33] 기존 등록된 알람들만 모두 제거합니다냥! 🧹⏰"""
        self.alarms.clear()
        _s = settings_obj or globals().get('settings')
        if _s: self.save_alarms(_s)

    # [TAG: #@is_active]
    def is_active(self):
        if getattr(self, 'hide_status', False):
            return False
        return bool(self.timers or any(a.get('active', True) for a in self.alarms))

    # [TAG: #@is_hourly_alarm]
    def is_hourly_alarm(self, a):
        """[공통 판정] '정각 알람(매시/매일 반복)' 인지 판별한다냥! 🕐🚦
        [규칙] SSOT: get_status_message()(상단 상태줄)와 draw_timer_alarm_status()(우하단 상태줄)가
        **반드시 이 한 곳의 판정만** 써야, 한쪽에만 노출되는 규칙 분산(어긋남)이 생기지 않는다. 🛡️
        """
        if not isinstance(a, dict):
            return False
        t_str = str(a.get('time', '') or '')
        desc = str(a.get('desc', '') or '')
        if a.get('is_recurring', False):
            return True
        # 구버전 데이터('is_recurring' 키 없음) 호환: 'HHMM' + 00분 + '정각' 포함이면 정각 알람으로 간주
        return ('is_recurring' not in a and len(t_str) == 4 and t_str.endswith('00')
                and ("정각 알람" in desc or "정각" in desc))

    # [TAG: #@get_status_message]
    def get_status_message(self):
        import datetime
        now = time.time()
        candidates = [] # (epoch_time, desc, type_label)

        # 1. 휘발성 타이머 수집
        for t in self.timers:
            end_t = t.get('end_time')
            if end_t:
                try: candidates.append((float(end_t), t.get('desc', '타이머'), 'timer'))
                except: pass

        # 2. 비휘발성 알람 수집 (1회성 알람만 수집, 정각 알림 제외)
        for a in self.alarms:
            if not a.get('active', True): continue
            if self.is_hourly_alarm(a): continue # [공통 판정] 정각/반복 알람 제외 🕐

            if 'end_time' in a:
                try: candidates.append((float(a['end_time']), a.get('desc', '알람'), 'alarm'))
                except: pass
            else:
                t_str = a.get('time', '')
                t_date = a.get('target_date', '')
                if len(t_str) == 4 and t_str.isdigit():
                    try:
                        hour = int(t_str[:2])
                        minute = int(t_str[2:])
                        if t_date:
                            dt = datetime.datetime.strptime(t_date, "%Y%m%d").replace(hour=hour, minute=minute, second=0, microsecond=0)
                        else:
                            now_dt = datetime.datetime.now()
                            dt = now_dt.replace(hour=hour, minute=minute, second=0, microsecond=0)
                            if dt <= now_dt:
                                dt += datetime.timedelta(days=1)
                        candidates.append((dt.timestamp(), a.get('desc', '알람'), 'alarm'))
                    except: pass

        # [V16.3.6] 사용자 요청: 고정 알람은 정각 알람처럼 메인 노티 메시지에서 제외 (1회성 알람 & 타이머만 표출) 🎯✨
        # _s = globals().get('settings') or globals().get('settings_ref')
        # if _s and hasattr(_s, 'data'):
        #     if '_get_next_recurring_app_alarm_datetime' in globals():
        #         next_dt, next_info = _get_next_recurring_app_alarm_datetime(_s)
        #         if next_dt:
        #             candidates.append((next_dt.timestamp(), f"[고정] {next_info}", 'alarm'))

        if not candidates:
            return ""

        # 가장 임박한 알람 정렬 및 추출 🎯
        candidates.sort(key=lambda x: x[0])
        shortest_epoch, shortest_desc, _type = candidates[0]
        
        now_str = datetime.datetime.now().strftime("%H:%M")
        
        display_desc = shortest_desc
        if len(display_desc) > 30:
            display_desc = display_desc[:27] + "..."

        # 남은 시간(분) 계산 ⏳
        left_min = max(0, int((shortest_epoch - now) / 60))

        # [중복 방지 & 몇분 남음 표시] 타이머만 예정 시각을 노출하고, 알람은 현재 시각과 남은 시간만 노출!
        if _type == 'timer':
            try:
                shortest_dt = datetime.datetime.fromtimestamp(shortest_epoch)
                scheduled_str = shortest_dt.strftime("%H시 %M분")
            except:
                scheduled_str = "미정"
            time_info = f"({scheduled_str} 예정 // 현재시간 : {now_str} // {left_min}분 남음)"
        else:
            time_info = f"(현재시간 : {now_str} // {left_min}분 남음)"
            
        total_count = len(candidates)
        extra_str = f" [외 {total_count - 1}개]" if total_count > 1 else ""
        
        return f"{display_desc} {time_info}{extra_str} "
    

    def trigger_alert(self, desc):
        if self.alerting: return
        self.alerting = True
        print(f"\r\n\r\n 🚨 {C.REVERSE}{C.YELLOW} [알람 / 타이머] {desc} 시간이 되었습니다! {C.RESET}\r\n")
        try:
            # 텔레그램 발송 시도
            if 'settings' in globals() and settings.data.get('telegram_token'):
                tk = settings.data.get('telegram_token')
                cid = settings.data.get('telegram_chat_id')
                if tk and cid:
                    import requests
                    requests.post(f"https://api.telegram.org/bot{tk}/sendMessage", json={
                        "chat_id": cid, "text": f"🚨 <b>[알람 삐오삐오!]</b>\r\n\r\n지정하신 알람이 울렸어멍!\r\n👉 {desc}", "parse_mode": "HTML",
                        "reply_markup": {
                            "inline_keyboard": [[{"text": "🔕 알람 끄기", "callback_data": "stop_alarm"}]]
                        }
                    }, timeout=5)
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")
        threading.Thread(target=self._beep_loop, args=(desc,), daemon=True).start()

    # [TAG: #@_beep_loop]
    def _beep_loop(self, desc=None):
        # [TAG: #@_emit_beep]

        def _emit_beep(freq, duration_sec):
            try:
                spk_enabled = False
                spk_dev = ""
                spk_mode = "dual"
                _s = globals().get('settings') or globals().get('settings_ref')
                if _s and hasattr(_s, 'data'):
                    spk_enabled = _s.data.get("alarm_speaker_output_enabled", False)
                    spk_dev = _s.data.get("alarm_speaker_device_id", "")
                    spk_mode = _s.data.get("alarm_speaker_output_mode", "dual")
                
                if spk_enabled and spk_dev:
                    play_alarm_custom_beep(spk_dev, mode=spk_mode, freq=freq, duration_sec=duration_sec)
                else:
                    import winsound
                    winsound.Beep(int(freq), int(duration_sec * 1000))
            except Exception as e:
                try:
                    import winsound
                    winsound.MessageBeep(-1)
                except: pass
                _log_to_file(f"⚠️ [Alarm Beep Safe Fallback] {e}")

        is_hourly = False
        if desc and "정각 알람" in str(desc):
            is_hourly = True

        if is_hourly:
            # [V수정] 정각 알람 전용 선택된 알람음 재생 ⏰✨
            if self.alerting:
                stype = "gentle_single"
                _s = globals().get('settings') or globals().get('settings_ref')
                if _s and hasattr(_s, 'data'):
                    stype = _s.data.get("hourly_alarm_sound_type", "gentle_single")
                play_hourly_alarm_sound(_emit_beep, stype, _s)
            self.alerting = False
            return

        class LASTINPUTINFO(ctypes.Structure):
            _fields_ = [("cbSize", ctypes.c_uint), ("dwTime", ctypes.c_uint)]
        class POINT(ctypes.Structure):
            _fields_ = [("x", ctypes.c_long), ("y", ctypes.c_long)]

        lii = LASTINPUTINFO()
        lii.cbSize = ctypes.sizeof(LASTINPUTINFO)
        ctypes.windll.user32.GetLastInputInfo(ctypes.byref(lii))
        start_input_time = lii.dwTime

        pt = POINT()
        ctypes.windll.user32.GetCursorPos(ctypes.byref(pt))
        start_mouse_x, start_mouse_y = pt.x, pt.y

        _s = globals().get('settings') or globals().get('settings_ref')
        # [V164.5] 블루투스 이어폰 연결 감지 및 전용 알람 시간 적용 🎧⏰
        is_bt_connected = False
        if '_is_bluetooth_audio_connected' in globals():
            try:
                is_bt_connected = globals()['_is_bluetooth_audio_connected'](_s)
            except Exception:
                pass

        if '_get_alarm_ring_duration_sec' in globals():
            try:
                ring_duration_sec = globals()['_get_alarm_ring_duration_sec'](_s, for_bluetooth=is_bt_connected)
            except Exception:
                ring_duration_sec = 10 if is_bt_connected else 30
        else:
            try:
                ring_duration_sec = int(float(_s.data.get("alarm_no_response_ring_duration_min", 1.0)) * 60)
            except Exception:
                ring_duration_sec = 30

        if '_format_alarm_duration_str' in globals():
            try:
                dur_disp = globals()['_format_alarm_duration_str'](ring_duration_sec)
            except Exception:
                dur_disp = f"{ring_duration_sec}초"
        else:
            dur_disp = f"{ring_duration_sec}초"

        mode_tag = "🎧 블루투스 이어폰" if is_bt_connected else "🔊 기본 스피커"
        max_beeps = max(1, int(ring_duration_sec))

        beep_count = 0
        while self.alerting:
            _emit_beep(1000, 0.5)
            beep_count += 1
            time.sleep(0.5)
            # 사용자 요청: 반응 없을 때 설정된 시간(6초~5분) 동안 울린 후 자동 종료 ⏰⏳
            if beep_count >= max_beeps:
                print(f"\r\n ⏰ {C.DIM}알람이 [{mode_tag}: {dur_disp}]간 울려 자동 종료되었습니다.{C.RESET}")
                self.alerting = False
                break

            # 짧은 시간(6초 등) 설정도 배려하여 시작 2~3초 후부터 입력 감지
            min_input_check = min(3, max(1, max_beeps - 1))
            if beep_count >= min_input_check:
                ctypes.windll.user32.GetLastInputInfo(ctypes.byref(lii))
                ctypes.windll.user32.GetCursorPos(ctypes.byref(pt))

                input_changed = lii.dwTime != start_input_time
                mouse_moved = abs(pt.x - start_mouse_x) > 10 or abs(pt.y - start_mouse_y) > 10

                if input_changed or mouse_moved:
                    self.alerting = False
                    break
        self.alerting = False

    # [TAG: #@_loop]
    def _loop(self):
        while self.running:
            now = time.time()
            now_str = time.strftime("%H%M")
            # [최적화] Sleep 모드 시 핑 주기를 60초로 완화하여 CPU 절약 💤🏓
            self.ping_counter += 1
            _ping_interval = 60 if _G_SLEEP_MODE else 5  # Sleep 모드: 60초, 활성: 5초
            if self.ping_counter >= _ping_interval:
                self.ping_counter = 0
                threading.Thread(target=_async_ping_check, daemon=True).start()

            if not self.alerting:
                # 요일별 / 매월 고정 앱 알람 검사 ⏰
                _s = globals().get('settings') or globals().get('settings_ref')
                if _s and hasattr(_s, 'data'):
                    rec_app_alarms = _s.data.get('recurring_app_alarms', [])
                    import datetime as _dt_mod
                    now_dt = _dt_mod.datetime.now()
                    cur_weekday = now_dt.weekday()
                    cur_day = now_dt.day
                    for ra in rec_app_alarms:
                        if ra.get('enabled', True):
                            t_str = ra.get('time', '').replace(':', '')
                            if t_str != now_str:
                                continue

                            is_match = False
                            rep_type = ra.get('repeat_type', 'monthly' if ra.get('month_days') else 'weekly')
                            if rep_type == 'monthly' or ra.get('month_days'):
                                m_days = ra.get('month_days', [])
                                if '_get_actual_days_in_month' in globals():
                                    act_days = _get_actual_days_in_month(now_dt.year, now_dt.month, m_days)
                                else:
                                    import calendar as _cal_mod
                                    try: _, _max_d = _cal_mod.monthrange(now_dt.year, now_dt.month)
                                    except: _max_d = 31
                                    act_days = []
                                    for md in m_days:
                                        try:
                                            md_int = int(md)
                                            if 1 <= md_int <= _max_d: act_days.append(md_int)
                                            elif md_int <= 0:
                                                rmd = _max_d + md_int
                                                if 1 <= rmd <= _max_d: act_days.append(rmd)
                                        except: pass
                                if cur_day in act_days:
                                    is_match = True
                            else:
                                days = ra.get('days', [])
                                if cur_weekday in days:
                                    is_match = True

                            if is_match:
                                if now - self.last_alert_time >= 60:
                                    self.last_alert_time = now
                                    label = ra.get('label', '고정 알람')
                                    self.trigger_alert(f"[고정 알람] {label} ({ra.get('time')})")
                                    break

                # [신규] 영구 보존형 카페인 타이머 (caffeine_until) 만료 검사 (앱 리셋/재시작 후에도 유지되다 만료 시 자동 OFF ☕🟢)
                try:
                    _s_obj = globals().get('settings') or globals().get('settings_ref')
                    if _s_obj and hasattr(_s_obj, 'data'):
                        _c_until = _s_obj.data.get('caffeine_until', 0)
                        if _c_until and now >= _c_until:
                            _caf = globals().get('caffeine')
                            if _caf: _caf.disable()
                            # [버그 픽스] pop() 사용 시 디스크 동기화로 값이 계속 되살아나던 문제 완벽 차단! 🛡️✨
                            _s_obj.data['caffeine_until'] = 0
                            _s_obj.data['caffeine_duration_hours'] = 0
                            _s_obj.data['caffeine_always_on'] = False
                            if hasattr(_s_obj, 'dirty_keys'):
                                _s_obj.dirty_keys.update({'caffeine_until', 'caffeine_duration_hours', 'caffeine_always_on'})
                            _s_obj.save()
                            globals()['_last_bg_notification'] = "⚫ 카페인 모드 타이머 만료 — 모니터 보호를 위해 절전 방지가 자동 해제되었습니다냥! ☕🐾"
                            globals()['_last_bg_notification_time'] = now
                            globals()['_global_menu_redraw_flag'] = True
                            # [도배 방지] 최소 60초 내 중복 발송 차단 가드 🛡️✨
                            if now - getattr(self, 'last_caffeine_off_time', 0) >= 60:
                                self.last_caffeine_off_time = now
                                try:
                                    tk = _s_obj.data.get('telegram_token')
                                    cid = _s_obj.data.get('telegram_chat_id')
                                    if tk and cid:
                                        import requests
                                        requests.post(f"https://api.telegram.org/bot{tk}/sendMessage", json={
                                            "chat_id": cid, "text": "☕ <b>[카페인 조용히 OFF]</b>\r\n\r\n설정된 카페인 시간이 만료되어 모니터 보호를 위해 카페인 모드를 조용히 해제했습니다냥! 🐾", "parse_mode": "HTML"
                                        }, timeout=5)
                                except Exception as e:
                                    if "6" not in str(e):
                                        _log_to_file(f"⚠️ [Silent Exception] {e}")
                except Exception:
                    pass

                # 휘발성 타이머 검사
                for t in self.timers[:]:
                    if now >= t['end_time']:
                        if t.get('type') == 'caffeine_off':
                            # [사용자 요청] 알람 울리지 않고 조용히 카페인 모드 해제 🟠
                            _caf = globals().get('caffeine')
                            if _caf: _caf.disable()
                            if 'settings' in globals():
                                settings.data['caffeine_always_on'] = False
                                settings.data['caffeine_until'] = 0
                                settings.data['caffeine_duration_hours'] = 0
                                if hasattr(settings, 'dirty_keys'):
                                    settings.dirty_keys.update({'caffeine_until', 'caffeine_duration_hours', 'caffeine_always_on'})
                                settings.save()
                            globals()['_last_bg_notification'] = "⚫ 카페인 모드 타이머 만료 — 절전 방지가 조용히 해제되었습니다냥! ☕"
                            globals()['_last_bg_notification_time'] = now
                            globals()['_global_menu_redraw_flag'] = True
                            # [도배 방지] 영구 타이머와 알림 중복 방지 (60초 쿨다운 공유) 🛡️✨
                            if now - getattr(self, 'last_caffeine_off_time', 0) >= 60:
                                self.last_caffeine_off_time = now
                                try:
                                    if 'settings' in globals() and settings.data.get('telegram_token'):
                                        tk = settings.data.get('telegram_token')
                                        cid = settings.data.get('telegram_chat_id')
                                        if tk and cid:
                                            import requests
                                            requests.post(f"https://api.telegram.org/bot{tk}/sendMessage", json={
                                                "chat_id": cid, "text": f"☕ <b>[카페인 조용히 OFF]</b>\r\n\r\n타이머({t['desc']})가 만료되어 모니터 보호를 위해 카페인 모드를 조용히 해제했습니다냥! 🐾", "parse_mode": "HTML"
                                            }, timeout=5)
                                except Exception as e:
                                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                                    if "6" not in str(e):
                                        _log_to_file(f"⚠️ [Silent Exception] {e}")
                            self.timers.remove(t)
                            break
                        else:
                            self.trigger_alert(t['desc'])
                            self.timers.remove(t)
                            break # 한 번에 하나씩
                # 알람 검사 (순회 중 삭제 안전을 위해 복사본 이용 및 1회성 발동 후 삭제 🧹✨)
                for a in self.alarms[:]:
                    if a.get('active', True):
                        t_date = a.get('target_date')
                        t_time = a.get('time')
                        is_date_match = True
                        if t_date:
                            is_date_match = (time.strftime("%Y%m%d") == t_date)
                        if is_date_match and t_time == now_str:
                            if now - self.last_alert_time >= 60: # 1분 내 중복 방지
                                self.last_alert_time = now
                                
                                # [V22.29] 사용자 요청: 타이머 대체 알람인 경우 미세 오차(초 단위)를 sleep으로 정밀 대기 ⏳⏰
                                if 'end_time' in a:
                                    try:
                                        target_epoch = float(a['end_time'])
                                        wait_time = target_epoch - time.time()
                                        if 0 < wait_time <= 65: # 60초 내외 오차 대기
                                            time.sleep(wait_time)
                                    except Exception as e:
                                        _log_to_file(f"⚠️ [alarm timer sleep error] {e}")
                                        
                                self.trigger_alert(a['desc'])
                                # [V신규] 정각 알람은 매일 반복하도록 내일 날짜로 갱신, 그 외는 즉시 삭제 🧹✨
                                is_hourly = False
                                t_str = a.get('time', '')
                                if a.get('is_recurring', False):
                                    is_hourly = True
                                elif 'is_recurring' not in a and len(t_str) == 4 and t_str.endswith('00') and "정각 알람" in a.get('desc', ''):
                                    is_hourly = True
                                
                                if is_hourly:
                                    import datetime as _dt
                                    next_day = _dt.datetime.now() + _dt.timedelta(days=1)
                                    a['target_date'] = next_day.strftime("%Y%m%d")
                                    a['is_recurring'] = True
                                else:
                                    self.alarms.remove(a)
                                
                                if 'settings' in globals():
                                    self.save_alarms(settings)


            time.sleep(3 if _G_SLEEP_MODE and not self.timers and not any(a.get("active") for a in self.alarms) else 1)


_timer_mgr = TimerAlarmManager()


# [TAG: #@draw_timer_alarm_status]
def draw_timer_alarm_status():
    """타이머와 알람의 상태를 콘솔의 우하단에 실시간으로 렌더링하고, desc가 25자 초과 시 슬라이싱합니다냥! 🐾
    [주의] 정각 알람(예: '10시 정각 알람')은 is_hourly_alarm() 판정으로 **노출하지 않습니다** 🧹
    (ESC 연타 시 화면 최하단에 순간 나타났다 사라지는 문제 제거)
    """
    if '_timer_mgr' not in globals() or not _timer_mgr.is_active():
        return
        
    try:
        import shutil
        term_cols, term_lines = shutil.get_terminal_size()
        
        status_parts = []
        for t in _timer_mgr.timers:
            desc = t.get('desc', '')
            if len(desc) > 25:
                desc = desc[:22] + "..."
            try:
                end_time = safe_float(t.get('end_time', 0))
            except:
                end_time = time.time()
            left_min = max(0, int((end_time - time.time()) / 60))
            status_parts.append(f"⏳ {desc} ({left_min}분 남음)")
            
        for a in _timer_mgr.alarms:
            if a.get('active', True):
                # [V-rules] 정각 알람(예: '10시 정각 알람')은 하단에 노출하지 않는다냥! 🧹
                #   ESC 연타 시 깜빡이던 원인 + 불필요한 중복 표시 제거가 목적.
                #   판정은 get_status_message() 와 동일 함수(is_hourly_alarm)를 써야 어긋남이 없다. 🚦
                if _timer_mgr.is_hourly_alarm(a):
                    continue
                desc = a.get('desc', '')
                if len(desc) > 25:
                    desc = desc[:22] + "..."
                if 'end_time' in a:
                    try:
                        end_time = float(a['end_time'])
                        left_min = max(0, int((end_time - time.time()) / 60))
                        status_parts.append(f"⏳ {desc} ({left_min}분 남음)")
                    except:
                        status_parts.append(f"⏰ {desc}")
                else:
                    status_parts.append(f"⏰ {desc}")
                
        if not status_parts:
            return
            
        status_line = " | ".join(status_parts)
        
        from unicodedata import east_asian_width
        # [TAG: #@_v_width]

        def _v_width(s):
            plain = re.sub(r'\033\[[0-9;]*m', '', s)
            return sum(2 if east_asian_width(ch) in ('F', 'W') else 1 for ch in plain)
            
        w = _v_width(status_line)
        x = max(1, term_cols - w - 2)
        y = term_lines
        
        sys.stdout.write(f"\033[s\033[{y};{x}H{C.DIM}{status_line}{C.RESET}\033[u")
        sys.stdout.flush()
    except Exception as e:
        _log_to_file(f"⚠️ [draw_timer_alarm_status Exception] {e}")


# [V78.x] CORE UTILITIES (MOVED UP FOR GLOBAL EXECUTION ORDER) ✨
# ==============================================================================
class TelegramBot:
    """텔레그램 봇 API를 활용하여 메시지를 전송하고 Chat ID를 가져오는 헬퍼 클래스"""
    @staticmethod
    # [TAG: #@set_my_commands]
    def set_my_commands(token: str) -> bool:
        """[V76.0] 텔레그램 봇의 메뉴(Bot Command) 버튼을 설정합니다. 🕹️"""
        if not token: return False
        try:
            import requests
            url = f"https://api.telegram.org/bot{token}/setMyCommands"
            commands = [
                {"command": "start", "description": "기능 키보드 및 메인 메뉴 호출 🧼"},
                {"command": "mypc", "description": "내 PC 리모컨 제어 💻"},
                {"command": "server", "description": "미디어 서버 정보 및 제어 🌐"},
                {"command": "debate", "description": "인공지능들 간의 끝장 토론 시작 ⚖️"},
                {"command": "setname", "description": "내 이름 설정 (예: /setname 사용자) 🏷️"}
            ]
            res = requests.post(url, json={"commands": commands}, timeout=10)
            return res.json().get("ok", False)
        except Exception as e:
            _log_to_file(f"⚠️ [Set Commands Error] {e}")
            return False


    @staticmethod
    # [TAG: #@get_updates]
    def get_updates(token: str) -> dict:
        """새로운 메시지 내역을 조회합니다. (Chat ID 추출용)"""
        try:
            import requests # Local import to avoid lazy loading issues
        except ImportError:
            return {"ok": False, "description": "Requests 모듈이 설치되어 있지 않습니다."}

        url = f"https://api.telegram.org/bot{token}/getUpdates"
        try:
            res = requests.get(url, timeout=10)
            return res.json()
        except Exception as e:
            return {"ok": False, "description": str(e)}

    @staticmethod
    # [TAG: #@_markdown_to_telegram_html]
    def _markdown_to_telegram_html(text: str) -> str:
        """마크다운 형식을 텔레그램 지원 HTML로 변환합니다."""
        if not text:
            return text
        # **bold** -> <b>bold</b>
        text = re.sub(r'(?<!\*)\*\*([^\*]+)\*\*(?!\*)', r'<b>\1</b>', text)
        return text

    @staticmethod
    # [TAG: #@send_message]
    def send_message(token: str, chat_id: str, text: str, reply_markup: dict = None) -> bool:
        """[V15.5.3] 레거시 호환용 포워딩: 모든 메시지 전송은 telegram_send로 통합됨."""
        text = TelegramBot._markdown_to_telegram_html(text)
        buttons = None
        passed_reply_markup = reply_markup
        if reply_markup and "inline_keyboard" in reply_markup:
            buttons = reply_markup["inline_keyboard"]
            passed_reply_markup = None

        parse_mode = None
        if "<" in text and ">" in text:
            parse_mode = "HTML"

        return telegram_send(text, buttons=buttons, parse_mode=parse_mode, chat_id=chat_id, reply_markup=passed_reply_markup)

    @staticmethod
    # [TAG: #@send_message_with_buttons]
    def send_message_with_buttons(token: str, chat_id: str, text: str, inline_keyboard: list) -> bool:
        """[Deprecated] Use send_message instead."""
        return TelegramBot.send_message(token, chat_id, text, {"inline_keyboard": inline_keyboard})

    @staticmethod
    # [TAG: #@edit_message_text_with_buttons]
    def edit_message_text_with_buttons(token: str, chat_id: str, message_id: int, text: str, inline_keyboard: list) -> bool:
        """[Deprecated] Use edit_message_text instead."""
        return TelegramBot.edit_message_text(token, chat_id, message_id, text, inline_keyboard)

    @staticmethod
    # [TAG: #@answer_callback_query]
    def answer_callback_query(token: str, callback_query_id: str, text: str = "", show_alert: bool = False) -> bool:
        """콜백 쿼리에 응답합니다 (버튼 클릭 시 피드백)."""
        if not token: return False
        try:
            import requests
            url = f"https://api.telegram.org/bot{token}/answerCallbackQuery"
            payload = {"callback_query_id": callback_query_id, "text": text, "show_alert": show_alert}
            res = requests.post(url, json=payload, timeout=10)
            return res.json().get("ok", False)
        except Exception as e:
            _log_to_file(f"⚠️ [Answer Callback Error] {e}")
            return False

    @staticmethod
    # [TAG: #@send_chat_action]
    def send_chat_action(token: str, chat_id: Union[str, int], action: str = "typing") -> bool:
        """[V24.4] 텔레그램 상단에 '입력 중...' 등의 상태를 표시합니다."""
        if not token or not chat_id: return False
        try:
            import requests
            url = f"https://api.telegram.org/bot{token}/sendChatAction"
            payload = {"chat_id": str(chat_id), "action": action}
            res = requests.post(url, json=payload, timeout=10)
            return res.json().get("ok", False)
        except Exception as e:
            _log_to_file(f"⚠️ [Send Chat Action Error] {e}")
            return False

    @staticmethod
    # [TAG: #@edit_message_text]
    def edit_message_text(token: str, chat_id: str, message_id: int, text: str, inline_keyboard: list = None) -> bool:
        """[V15.5.3] 기존 메시지의 텍스트(및 선택적으로 버튼)를 수정합니다. (안정화 적용)"""
        if not token or not chat_id or not message_id: return False

        text = TelegramBot._markdown_to_telegram_html(text)
        try:
            import requests
            url = f"https://api.telegram.org/bot{token}/editMessageText"
            payload = {
                "chat_id": str(chat_id),
                "message_id": message_id,
                "text": text,
                "disable_web_page_preview": True
            }
            if "<" in text and ">" in text:
                payload["parse_mode"] = "HTML"

            if inline_keyboard is not None:
                payload["reply_markup"] = {"inline_keyboard": inline_keyboard}

            for i in range(3):
                try:
                    res = requests.post(url, json=payload, timeout=10)
                    if res.status_code == 400:
                        err_desc = res.json().get("description", "")
                        # HTML 파싱 에러는 모드 해제 후 재시도 가치가 있음
                        if "can't parse entities" in err_desc and payload.get("parse_mode") == "HTML":
                             payload.pop("parse_mode", None)
                             _log_to_file("⚠️ [Telegram Edit] HTML 파싱 에러 감지. 순수 텍스트로 재시도.")
                             continue

                        # URL 오류 등은 재시도해도 실패하므로 즉시 종료 (지연 방지)
                        _log_to_file(f"🛑 [Telegram Edit] 치명적 파라미터 에러 감지. 재시도 중단: {err_desc}")
                        return False

                    res_json = res.json()
                    ok = res_json.get("ok", False)
                    if not ok:
                         _log_to_file(f"⚠️ [Telegram Edit] API 오류: {res_json} (시도 {i+1}/3)")
                         time.sleep(1)
                         continue
                    return True
                except Exception as req_e:
                    _log_to_file(f"⚠️ [Telegram Edit] 요청 오류: {req_e} (시도 {i+1}/3)")
                    time.sleep(1)
            return False

        except Exception as e:
            _log_to_file(f"⚠️ [Telegram Edit] 치명적 예외: {e}")
            return False

    @staticmethod
    # [TAG: #@get_updates_with_offset]
    def get_updates_with_offset(token: str, offset: int = 0, timeout: int = 30) -> dict:
        """Long polling으로 봇 업데이트를 수신합니다."""
        if not token: return {"ok": False}
        try:
            import requests
        except ImportError:
            return {"ok": False}
        url = f"https://api.telegram.org/bot{token}/getUpdates"
        params = {"offset": offset, "timeout": timeout, "allowed_updates": '["message", "callback_query"]'}
        try:
            res = requests.get(url, params=params, timeout=timeout + 10)
            return res.json()
        except:
            return {"ok": False}

    @staticmethod
    # [TAG: #@send_photo]
    def send_photo(token: str, chat_id: str, photo_path: str, caption: str = "", reply_markup: dict = None) -> bool:
        """지정된 채팅방으로 사진 파일을 전송합니다."""
        if not token or not chat_id or not os.path.exists(photo_path): return False
        try:
            import requests
            import json as _json
        except ImportError:
            return False

        url = f"https://api.telegram.org/bot{token}/sendPhoto"
        try:
            with open(photo_path, "rb") as f:
                files = {"photo": f}
                data = {"chat_id": chat_id, "caption": caption, "parse_mode": "HTML"}
                if reply_markup:
                    data["reply_markup"] = _json.dumps(reply_markup)
                res = requests.post(url, data=data, files=files, timeout=30)
                return res.json().get("ok", False)
        except:
            return False

    @staticmethod
    # [TAG: #@delete_message]
    def delete_message(token: str, chat_id: str, message_id: int) -> bool:
        """[V24.3] 지정된 메시지를 삭제합니다. (생각 중... 메시지 정리용)"""
        if not token or not chat_id or not message_id: return False
        try:
            import requests
            url = f"https://api.telegram.org/bot{token}/deleteMessage"
            payload = {"chat_id": str(chat_id), "message_id": message_id}
            res = requests.post(url, json=payload, timeout=10)
            return res.json().get("ok", False)
        except Exception as e:
            _log_to_file(f"⚠️ [Telegram Delete Error] {e}")
            return False


