def _read_spark_progress():
    """temp/spark_progress.json 을 읽는다. 없으면 빈 dict."""
    try:
        p = os.path.join(BASE_DIR, "temp", "spark_progress.json")
        if not os.path.exists(p):
            return {}
        with open(p, "r", encoding="utf-8") as f:
            return json.load(f) or {}
    except Exception:
        return {}


def _spark_progress_is_running(d):
    """진행 기록이 '아직 살아있는지' 판정 (5분 이상 갱신 없으면 정지로 본다)"""
    try:
        ts = float(d.get("updated_at") or 0)
        if not ts:
            return False
        if (time.time() - ts) > 300:   # 5분 이상 갱신 없으면 정지로 간주
            return False
        # 🐱 pid 가 있으면 '그 프로세스가 살아있는지' 로 최종 판정한다.
        #    (psutil 이 없으면 OS 별 명령어로 확인)
        pid = d.get("pid")
        if pid:
            try:
                pid = int(pid)
            except (TypeError, ValueError):
                return True
            if pid <= 0:
                return True
            try:
                import psutil
                return psutil.pid_exists(pid)
            except ImportError:
                pass
            except Exception:
                return True
            try:
                if os.name == 'nt':
                    out = subprocess.run(
                        ['tasklist', '/FI', f'PID eq {pid}', '/NH'],
                        capture_output=True, text=True, timeout=8).stdout
                else:
                    out = subprocess.run(['ps', '-p', str(pid)],
                                         capture_output=True, text=True, timeout=8).stdout
                return str(pid) in out
            except Exception:
                return True
        return True
    except Exception:
        return False


def _read_spark_progress_brief():
    """메뉴 라벨용 한 줄 요약 (예: '🎵 MP3 변환 중 1/6')"""
    try:
        d = _read_spark_progress()
        if not d:
            return "대기"
        st = d.get("stage") or ""
        icon, lbl = _SPARK_STAGE_LABEL.get(st, ("•", st or "대기"))
        cur, tot = d.get("current", 0), d.get("total", 0)
        if tot:
            return f"{icon} {lbl} {cur}/{tot}"
        return f"{icon} {lbl}"
    except Exception:
        return "대기"


# ══════════════════════════════════════════════════════════════════════
# [TAG: #@_LiveOverlay]
# 🛡️[V193.6] 비번쩍임 '제자리 갱신' 오버레이 렌더러 (화면 번쩍임 근본 제거) ✨
#
#   🔴 왜 번쩍였나?
#     예전 대시보드는 매 갱신마다 `\x1b[H`(화면 홈) + `\x1b[J`(커서~화면끝 삭제)로
#     '화면 한 화면을 통째로 지우고 다시 칠했다.'
#     → 터미널은 1프레임(0.4초)마다 '화면 전체 셀'을 전부 재페인트해야 하고,
#        Windows Terminal 은 그것을 백색 번쩍임으로 보여준다. (2.5회/초 = 사용자가 본 번쩍임)
#     · 갱신마다 스피너가 돌아가므로 '내용이 안 바뀌었는데도' 매번 지우고 다시 그렸다.
#
#   🟢 해결 (탐색기 화면과 같은 방식)
#     ① 전체 화면 지움(ESC[J / ESC[2J)을 '절대' 쓰지 않는다.
#     ② 직전 프레임의 줄 수를 기억해 커서를 '블록 첫 줄'로 되돌린 뒤
#        `\r` + 내용 + `\033[K`(그 줄 끝까지만 지우기)로 덮어쓴다.
#     ③ 내용이 '실제로 바뀐 줄만' 다시 그린다. (커서 이동만 하는 건 재페인트가 없다)
#     → 터미널이 다시 칠하는 셀이 '바뀐 그 줄'뿐이므로 번쩍임이 사라진다.
#
#   ④ [V193.7] ★ '내용이 하나라도 안 바뀌었으면 아예 아무 것도 출력하지 않는다' (0 바이트)
#     → 폴링 루프(0.4초 / 1초 주기)는 계속 돌더라도 화면은 완전히 정지해 깜빡임이 0 이 된다.
#     → draw() 의 반환값(True=고침 / False=아무것도 안 함)으로 '유휴' 여부도 알 수 있다.
#
#   📐 커서 정합 규약 (self._lines = 확보한 블록 높이)
#     draw() 가 끝나면 커서는 '블록 마지막 줄 바로 아래 빈 줄'의 0열에 있다(=top+_lines).
#     다음 draw() 는 그 자리에서 `_lines` 만큼 위로 올라가 'top' 으로 복귀한다.
#     블록 높이는 '터미널 높이 - reserve' 로 제한해 마지막 줄에서 스크롤이 뜨지 않게 한다.
#     (reserve=1 이면 '커서 대기행'을 위해 1줄을 남겨둔다. 화면 꽉 채우는 화면은 0 지정)
# ══════════════════════════════════════════════════════════════════════
class _LiveOverlay:
    """화면을 한 칸도 지우지 않고 '제자리에서' 갱신하는 오버레이 🛡️✨"""

    def __init__(self, tag="overlay", reserve=1):
        self.tag = tag
        self.reserve = max(0, int(reserve))   # 블록 아래 남겨둘 줄 수 (기본 1 = 커서 대기행)
        self._prev = []        # 직전 프레임의 줄(ANSI 포함)
        self._lines = 0        # 확보해둔 블록 높이(줄)
        self._started = False  # 블록이 그려지기 시작했는가
        self._term_lines = 0   # 블록을 잡을 때의 터미널 높이 (창 리사이즈 감지용)
        self._parked_y = None  # 마지막에 커서를 둔 실제 Y (자기치유 검사용)
        self._safe = False     # 안전 모드(홈에서 전체 재인쇄) 여부 — 줄바꿈 발생 시 자동 진입

    def _has_overflow(self, lines, cols):
        """[V193.7] 어떤 줄이 터미널 너비를 넘어 '자동 줄바꿈' 되는가? 🛡️
        줄바꿈이 생기면 '논리 줄 수 ≠ 실제 행 수' 가 되어 제자리 갱신 커서 계산이 깨진다.
        → 이 경우에만 '안전 모드(홈에서 전체 재인쇄)' 로 자동 폴백한다."""
        try:
            if not cols or cols < 8:
                return False
            import unicodedata          # 표준 라이브러리 (lazy import)
            for ln in lines:
                w = 0
                for ch in re.sub(r'\033\[[0-9;]*[A-Za-z]', '', str(ln)):
                    cp = ord(ch)
                    # 'A'(Ambiguous: ─ ━ ⚠ 등)은 Windows Terminal 에서 '1칸' 으로 그려진다.
                    #   → 2칸으로 세면 '실제로는 안 넘치는 줄'을 오탐해 안전모드로落入시킨다. 🛡️
                    if (unicodedata.east_asian_width(ch) in ('F', 'W')
                            or (0x1F300 <= cp <= 0x1F9FF) or (0x2600 <= cp <= 0x26FF)
                            or (0x2700 <= cp <= 0x27BF) or (0xFE00 <= cp <= 0xFE0F)):
                        w += 2
                    else:
                        w += 1
                    if w > cols:
                        return True
        except Exception:
            # [V193.7 · 99감사 P3] 측정 실패 시 '안전 모드(전체 재인쇄)' 로 간다.
            #   (False 를 주면 '오버플로우인데 빠른 경로'로 진행해 커서 계산이 깨질 수 있다) 🛡️
            return True
        return False

    def _draw_safe(self, lines):
        """안전 모드: 홈으로 이동 → 전체 재인쇄 → 아래 잔여 지움 (예전 방식 그대로) 🛡️
        ⚠️ 줄바꿈으로 '논리줄수 ≠ 실제행수' 가 되는 상황에서만 쓰는 모드이므로
           커서 수업을 전혀 쓰지 않는다. 대신 '화면 높이'를 넘지 않게 잘라서
           아래로 밀려나는 것을 막는다. (예전에는 무제한으로 밀려났다) ⚓"""
        try:
            try:
                _maxh = max(3, shutil.get_terminal_size().lines)
            except Exception:
                _maxh = 40
            if len(lines) > _maxh:
                lines = lines[:_maxh]
            sys.stdout.write("\x1b[H")
            for i, line in enumerate(lines):
                sys.stdout.write("\r" + line + "\033[K")
                if i < len(lines) - 1:
                    sys.stdout.write("\n")
            sys.stdout.write("\x1b[J")
            sys.stdout.flush()
        except Exception as e:
            _log_to_file(f"⚠️ [LiveOverlay/{self.tag}] 안전모드 그리기 실패: {e}")

    def reanchor(self, full_clear=True):
        """블록을 버리고 '화면 홈'에서 다시 잡는다. (커서 정합 복구) 🛡️"""
        try:
            if full_clear:
                sys.stdout.write("\x1b[2J\x1b[H")
            else:
                sys.stdout.write("\r\x1b[H")
            sys.stdout.flush()
        except Exception:
            pass
        self._prev = []
        self._lines = 0
        self._parked_y = None
        self._started = True

    # ── 블록 첫 줄로 커서를 되돌린다 ──
    def _goto_top(self):
        if self._started and self._lines > 0:
            # reserve>0 : 대기행(top+_lines) 에 커서가 있음 → _lines 만큼 위로
            # reserve=0 : 마지막 줄 끝에 커서가 있음   → _lines-1 만큼 위로
            up = self._lines if self.reserve > 0 else (self._lines - 1)
            if up > 0:
                sys.stdout.write(f"\033[{up}A")
        sys.stdout.write("\r")

    def start(self, full_clear=True):
        """오버레이 시작. 기본은 화면을 확실히 비우고 홈(1행1열)에서 시작한다."""
        self.reanchor(full_clear=full_clear)

    def draw(self, lines, force=False):
        """lines(list[str]) 를 제자리에서 갱신한다.
        ★ 내용이 '하나도 안 바뀌었으면' 아무 것도 출력하지 않는다 (0 바이트).
        @return True=화면을 고쳤다 / False=아무것도 안 했다(내용 동일)"""
        try:
            lines = [str(x) for x in (lines or [])]
        except Exception:
            return False
        try:
            _tsize = shutil.get_terminal_size()
            tlines, tcols = _tsize.lines, _tsize.columns
        except Exception:
            tlines, tcols = 40, 80
        if not tlines or tlines < 6:
            tlines = 40

        # 🛡️ [V193.7 안전모드] 어떤 줄이 너비를 넘어 '자동 줄바꿈' 되면 논리줄수≠실제행수가 되어
        #    커서 계산이 깨진다 → 이 경우에만 '홈에서 전체 재인쇄'(예전 방식)로 자동 폴백한다.
        #    (안전모드에서는 커서 수업을 전혀 쓰지 않으니 줄바꿈이 있어도 100% 안전)
        _overflow = self._has_overflow(lines, tcols)
        if _overflow or self._safe:
            if not _overflow and self._safe:
                # 더 이상 줄바꿈이 없으면 '제자리 갱신' 으로 복귀 (홈에서 다시 잡고 시작)
                self._safe = False
                self.reanchor(full_clear=False)
            else:
                self._safe = True
                self._draw_safe(lines)
                self._prev = []
                self._lines = 0
                self._parked_y = None
                self._started = True
                return True

        # 🛡️ 사용자가 창 크기를 바꾸면 이전 커서 계산이 무효 → 1회만 정비용 후 재시작
        if self._started and self._lines > 0 and tlines != self._term_lines:
            self.reanchor(full_clear=True)
        # 🛡️ [V193.7 자기치유] 백그라운드 스레드가 화면에 print 해서 커서가 옮겨졌으면
        #    제자리 갱신이 깨진다 → 실제 커서 위치를 확인하고 자동 재앵커한다.
        # ⚠️ 단, 출력이 'StringIO 캡처' 중이면(_console_cursor_y 가 보는 콘솔은 아직 안 움직였다)
        #    값이 어긋나 매 프레임마다 2J 가 발생한다 → 이 경우 검사를 건너뛴다.
        #    (render_menu 가 stdout 을 StringIO 로 가로채 때 해당. 앵커 유효성은
        #     _LOG_LIVE_WAS_OPEN / clear_-console 신호로 보장된다) 🛡️
        elif (self._started and self._lines > 0 and self._parked_y is not None
                and _stdout_is_real_console()):
            _cur_y = _console_cursor_y()
            if _cur_y is not None and _cur_y != self._parked_y:
                self.reanchor(full_clear=True)
        self._term_lines = tlines

        max_h = max(3, tlines - self.reserve)   # 스크롤이 뜨지 않게 높이를 제한
        if len(lines) > max_h:
            lines = lines[:max_h]
        need = min(max(self._lines, len(lines)), max_h)
        if len(lines) < need:                # 줄수가 줄면 '빈 줄'을 그려 남은 글자를 지운다
            lines = lines + [""] * (need - len(lines))

        # ★★ '바뀐 내용이 하나도 없다' → 아예 아무 것도 출력하지 않는다 (유휴) 🛡️
        #    (폴링 루프는 계속 돌지만 화면은 0 바이트 = 완전 정지 = 번쩍임 0)
        if (not force and self._started and self._lines > 0
                and lines == self._prev):
            return False

        try:
            self._goto_top()
            for i, line in enumerate(lines):
                old = self._prev[i] if i < len(self._prev) else None
                if old is None or old != line:      # ★ 바뀐 줄만 다시 칠한다
                    sys.stdout.write("\r" + line + "\033[K")
                if i < len(lines) - 1:
                    sys.stdout.write("\n")
            if self.reserve > 0:
                sys.stdout.write("\n\033[K")        # 블록 아래 '커서 대기 행' 비우기
            sys.stdout.flush()
        except Exception as e:
            _log_to_file(f"⚠️ [LiveOverlay/{self.tag}] 그리기 실패: {e}")
            return False
        self._prev = lines
        self._lines = need
        self._started = True   # start() 를 못 부르고 draw() 만 온 경우에도 정합 보장 🛡️
        # 다음 갱신 때 '커서가 그대로인지' 비교 (캡처 버퍼면 기록하지 않는다)
        self._parked_y = _console_cursor_y() if _stdout_is_real_console() else None
        return True

    def clear(self):
        """오버레이가 차지한 줄만 지우고 커서를 그 자리로 되돌린다 (원상 복구)."""
        if self._started and self._lines > 0:
            try:
                self._goto_top()          # 커서를 블록 첫 줄(top)로
                n = self._lines           # 지울 줄 수 = 블록 줄 + 아래 대기행
                for i in range(n):
                    if i:
                        sys.stdout.write("\r\n")
                    sys.stdout.write("\033[K")   # 이 줄 끝까지만 지우기
                sys.stdout.write("\r")
                sys.stdout.flush()
            except Exception:
                pass
        self._prev = []
        self._lines = 0
        self._parked_y = None


# ══════════════════════════════════════════════════════════════════════
# [TAG: #@_ui_live]
# 🌐 [V193.7] 앱 전역 공용 "비번쩍임 실시간 갱신" 헬퍼 (자주 쓰는 화면 공통) ✨
#
#   예전에는 화면마다 'ESC[H + ESC[J 로 전체 지우고 다시 그리기' 를 각자 손으로 썼고,
#   그 탓에 어디서 갱신하든 다 '번쩍' 않았다. 이 블록이 그걸 '공통 모듈'로 뺐다. 🛡️
#
#   ┌────────────────────────────────────────────────────────────────┐
#   │ ❶ 순수 '바뀜 감지' (아무것도 안 그리는 초경량 헬퍼)                  │
#   │    if _ui_is_changed(새값, "내키"):   # True = 바뀜(최초 포함)     │
#   │        무거운_렌더링()                                            │
#   └────────────────────────────────────────────────────────────────┘
#   ┌────────────────────────────────────────────────────────────────┐
#   │ ❷ 실시간 갱신 화면 3줄 패턴 (폴링 루프에 그대로 쓰인다)             │
#   │    _ui_live_begin()                    # 화면 시작 (1회만)        │
#   │    while True:                                                     │
#   │        _ui_live_update(줄_목록)          # ★ 안 바뀌었으면 0 바이트 │
#   │        time.sleep(0.5)                                             │
#   │    _ui_live_end()                      # 치우고 복귀               │
#   └────────────────────────────────────────────────────────────────┘
#
#   규약: begin/update/end 는 '항상' 짝을 이뤄야 한다. (안 그러면 커서 정합이 깨진다) 🛡️
# ══════════════════════════════════════════════════════════════════════
_UI_LIVE_SINGLETON = None     # 전역 단일 인스턴스 (한 화면에서 동시에 1개만)


# [TAG: #@_console_cursor_y]
def _stdout_is_real_console():
    """[V193.7] 지금 sys.stdout 가 '진짜 콘솔'인지 (StringIO 캡처가 아닌지) 판별 🛡️
    · 캡처 버퍼로 나가는 화면(render_menu 의 StringIO 등)에서는 커서 위치 조회가
      '아직 쓰이지 않은 미래 위치' 를 가리켜 자기치유가 매 프레임 오작동한다.
    → 이 경우 커서 검사를 통째로 건너뛴다."""
    try:
        return hasattr(sys.stdout, "fileno")
    except Exception:
        return False


def _console_cursor_y():
    """[V193.7] 실제 콘솔 커서의 Y 좌표를 읽는다. (읽을 수 없으면 None = 검사 생략)
    🛡️ 용도: '누군가(백그라운드 스레드 등) 화면에 print 해서 커서를 옮겼는지' 확인하고
       제자리 갱신이 깨졌을 때 자동 재앵커(자기치유)하기 위함."""
    if os.name != 'nt':
        return None
    try:
        import ctypes

        class _COORD(ctypes.Structure):
            _fields_ = [("X", ctypes.c_short), ("Y", ctypes.c_short)]

        class _SMALL_RECT(ctypes.Structure):
            _fields_ = [("Left", ctypes.c_short), ("Top", ctypes.c_short),
                        ("Right", ctypes.c_short), ("Bottom", ctypes.c_short)]

        class _INFO(ctypes.Structure):
            _fields_ = [("dwSize", _COORD), ("dwCursorPosition", _COORD),
                        ("wAttributes", ctypes.c_ushort), ("srWindow", _SMALL_RECT),
                        ("dwMaximumWindowSize", _COORD)]

        _h = ctypes.windll.kernel32.GetStdHandle(-11)   # STD_OUTPUT_HANDLE
        _info = _INFO()
        if ctypes.windll.kernel32.GetConsoleScreenBufferInfo(_h, ctypes.byref(_info)):
            return int(_info.dwCursorPosition.Y)
    except Exception:
        return None
    return None


# [TAG: #@_ui_is_changed]
def _ui_is_changed(new_value, key="default", force=False):
    """[V193.7] '바뀐 내용이 있는지'만 확인하는 초경량 공용 헬퍼 🛡️
    @param new_value 비교할 새 값 (문자열 / 튜플 / dict / 뭐든)
    @param key      판별 키 (화면 이름 등. 서로 다른 판별 기준을 한 함수에서 섞어 쓸 때)
    @param force    True 면 무조건 '바뀜' (=강제 리프레시)
    @return True = '바뀜'(최초 호출 포함) / False = '안 바뀜'
    예) if _ui_is_changed(상태문자열, "mybar"):  무거운_작업()"""
    try:
        cache = _ui_is_changed._cache
    except AttributeError:
        cache = _ui_is_changed._cache = {}
    if force:
        cache[key] = new_value
        return True
    if key in cache and cache[key] == new_value:
        return False
    cache[key] = new_value
    return True


# [TAG: #@_ui_live_begin]
def _ui_live_begin(full_clear=True, tag="ui", reserve=1):
    """[V193.7] 비번쩍임 실시간 갱신 화면 시작. (반드시 _ui_live_end 와 짝을 이룰 것) 🛡️"""
    global _UI_LIVE_SINGLETON
    try:
        if full_clear:
            # 진입 1회만 전체 지움 (갱신 중에는 절대 쓰지 않는다)
            try:
                clear_console(history_preserve=False)
            except Exception:
                sys.stdout.write("\x1b[2J\x1b[H")
                sys.stdout.flush()
        _UI_LIVE_SINGLETON = _LiveOverlay(tag, reserve=reserve)
        _UI_LIVE_SINGLETON.start(full_clear=False)
    except Exception as e:
        _log_to_file(f"⚠️ [_ui_live] 시작 실패: {e}")
    return _UI_LIVE_SINGLETON


# [TAG: #@_ui_live_update]
def _ui_live_update(lines, force=False):
    """[V193.7] ★ '바뀔 때만' 제자리 갱신.
    @return True = 화면을 고쳤다 / False = 안 바뀌어 아무 것도 안 했다(0 바이트)"""
    ov = _UI_LIVE_SINGLETON
    if ov is None:
        # 아직 begin 안 했으면 '한 번만' 자동으로 준비한다 (호출 실수 방어)
        ov = _ui_live_begin()
        if ov is None:
            try:
                sys.stdout.write("".join(str(x) + "\r\n" for x in (lines or [])))
                sys.stdout.flush()
            except Exception:
                pass
            return True
    return bool(ov.draw(lines, force=force))


# [TAG: #@_ui_live_end]
def _ui_live_end(keep=False):
    """[V193.7] 실시간 갱신 화면 종료. (기본: 우리가 칠한 줄만 지우고 커서 원위치로)"""
    global _UI_LIVE_SINGLETON
    ov = _UI_LIVE_SINGLETON
    _UI_LIVE_SINGLETON = None
    if ov is None:
        return False
    if not keep:
        try:
            ov.clear()
        except Exception:
            pass
    return True


# ══════════════════════════════════════════════════════════════════════
# [TAG: #@_spark_progress_lines]
# 📊 [V193.6] 진행 상황 화면 '본문'을 '줄 목록'으로 반환 (비번쩍임 오버레이용)
#   순수 함수 — 갱신 루프가 매 프레임 호출한다. (문자열 반환이 필요하면 _spark_progress_body 사용)
# ══════════════════════════════════════════════════════════════════════
def _spark_progress_lines(d, running, spin_idx=0):
    """진행 상황 텍스트를 줄 단위 리스트로 만든다. (ANSI 포함)"""
    L = []
    st = d.get("stage") or "idle"
    icon, lbl = _SPARK_STAGE_LABEL.get(st, ("•", st))
    col = getattr(C, _SPARK_STAGE_COLOR.get(st, "WHITE"), C.WHITE)

    # 1) 현재 단계
    badge = f" {C.GREEN}● 진행 중{C.RESET}" if running else f" {C.GRAY}⏸ 종료됨{C.RESET}"
    # 진행 중일 때만 '깜빡이는' 스피너로 '살아있다'는 느낌을 준다
    spin = "⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏"[spin_idx % 10] if running else "  "
    L.append(f"   {col}{icon} {C.BOLD}{lbl}{C.RESET}{badge}  {C.SKY}{spin}{C.RESET}")
    msg = str(d.get("msg") or "").strip()
    if msg:
        L.append(f"     {C.GRAY}{msg[:100]}{C.RESET}")

    # 2) 진행률 바
    cur, tot = int(d.get("current") or 0), int(d.get("total") or 0)
    if tot > 0:
        pct = max(0, min(100, int(cur * 100 / tot)))
        filled = int(pct / 5)
        bar = "█" * filled + "░" * (20 - filled)
        L.append("")
        L.append(f"   {C.WHITE}진행률{C.RESET}  {C.LIGHT_CYAN}{bar}{C.RESET} {C.BOLD}{pct}%{C.RESET}  ({cur}/{tot})")
    else:
        L.append("")
        L.append(f"   {C.GRAY}진행률  (총 파일 수 집계 전){C.RESET}")

    # 3) 사용 계정
    acct = d.get("account") or {}
    if acct.get("email") or acct.get("profile_dir"):
        L.append(f"   {C.WHITE}계정{C.RESET}    {C.LIGHT_PURPLE}{acct.get('email') or '?'}{C.RESET} {C.GRAY}(프로필: {acct.get('profile_dir') or '-'}){C.RESET}")

    # 4) 마지막 갱신
    try:
        ago = max(0, int(time.time() - float(d.get("updated_at") or 0)))
        L.append(f"   {C.WHITE}마지막{C.RESET}  {C.GRAY}{ago}초 전{C.RESET}")
    except Exception:
        pass

    # 5) 파일별 상태
    files = d.get("files") or []
    if files:
        L.append("")
        L.append(f"   {C.WHITE}── 파일별 상태 ──{C.RESET}")
        _fcol = {"extract": "YELLOW", "upload": "LIGHT_CYAN", "sent": "GREEN",
                 "error": "RED", "verify": "LIGHT_CYAN", "retry": "YELLOW"}
        for f in files[:15]:
            fst = f.get("state") or "idle"
            fi, fl = _SPARK_STAGE_LABEL.get(fst, ("•", fst))
            fc = getattr(C, _fcol.get(fst, "GRAY"), C.GRAY)
            L.append(f"     {fc}{fi} {fl:<14}{C.RESET} {C.WHITE}{str(f.get('name') or '')[:42]}{C.RESET}")
        if len(files) > 15:
            L.append(f"     {C.GRAY}… 외 {len(files) - 15}개{C.RESET}")
    else:
        L.append("")
        L.append(f"   {C.GRAY}파일별 상태는 수집 중이에요.{C.RESET}")

    L.append("")
    L.append(f"   {C.GRAY}· 자동 번역(69번) 을 켜두면 새 파일이 담길 때 자동으로 전송됩니다.{C.RESET}")
    L.append(f"   {C.GRAY}· 전송이 끝나면 '장바구니 스파크 자막 즉시 수신(72번)' 으로 자막을 가져옵니다.{C.RESET}")
    return L


# [TAG: #@_spark_progress_body]
# 📊 [V193.5] 진행 상황 화면 '본문' 생성 (문자열 반환 — 하위 호환용)
#   [V193.6] 실제 렌더는 _spark_progress_lines(줄 목록) + _LiveOverlay(제자리 갱신)를 쓴다.
#   [V193.7 · 99감사] 현재 내부 호출부는 0건(=dead wrapper). '문자열 반환 계약'은
#            V193.5 이전 호출부가 문자열을 기대하므로 제거하지 않고 명시적으로 남긴다.
#            (스킬/외부 스크립트가 문자열을 요구할 수 있음 · 제거 시 회귀 위험) 🛡️
def _spark_progress_body(d, running, spin_idx=0):
    """진행 상황 텍스트 블록을 만든다. (ANSI 포함) — 문자열 계약 유지용 래퍼"""
    return "\n".join(_spark_progress_lines(d, running, spin_idx))


# ══════════════════════════════════════════════════════════════════════
# [TAG: #@_show_spark_progress_menu]
# 📊 [V193.5] '스파크 번역 진행 상황' 실시간 대시보드
#   · 5초마다 자동 갱신 (스피너로 '살아있음' 표시)
#   · Enter / Esc / q / Space 아무 키나 누르면 즉시 '장바구니' 로 복귀
#
# 🐛[V193.5 감사 수정] ANSI 커서 정합 붕괴 근본 제거
#   이전 구현은 'ESC[F 1회 + ESC[B(nlines+4)' 로 원위치 복귀를 시도했으나,
#   ① 대시보드 진입 전 clear_console() 를 안 불러서 '이전 TUI 화면(수백 줄)' 위에서 시작했고
#   ② 되돌리기 계산(nlines+4)이 '실제 소비 줄 수'와 어긋나
#   → 갱신 1회마다 커서가 +33줄씩 밀려 화면이 무한 스크롤됐다. (가상 터미널로 실측)
#
# 🛡️[V193.6 번쩍임 제거] 갱신 방식을 '제자리 덮어쓰기'로 바꾼다
#   V193.5 해법(ESC[H 홈 + ESC[J 로 커서~화면끝 삭제)은 커서 정합은 잡혔지만,
#   '한 화면 전체를 0.4초마다 지우고 다시 칠한다' → Windows Terminal 백색 깜빡임이
#   초당 2.5회 = 사용자가 본 "번쩍번쩍" 의 정체였다. 🐛
#   지금은 [_LiveOverlay] 로 '바뀐 줄만' 덮어쓰고(전체 지움 0회) 번쩍임이 없다.
#   커서 정합 규약은 _LiveOverlay 문서 참고. (top+_lines 자리에 커서를 되돌린다)
# ══════════════════════════════════════════════════════════════════════
def _show_spark_progress_menu(s=None, interval=5.0, max_seconds=3600.0,
                              auto_return_on_finish=False, auto_return_wait=6.0):
    """스파크 번역 진행 상황 실시간 대시보드 (Enter 로 언제든 돌아간다)."""
    try:
        d0 = _read_spark_progress()
        if not d0:
            print(f"\r\n {C.SKY}── [ 📊 스파크 번역 진행 상황 ] ──{C.RESET}\r\n")
            print(f"   {C.GRAY}아직 스파크 번역을 실행한 적이 없어요.{C.RESET}")
            print(f"   {C.GRAY}장바구니에서 '스파크 번역'을 요청하면 여기에 진행 상황이 표시됩니다.{C.RESET}\r\n")
            time.sleep(2.0)
            return False

        try:
            import msvcrt as _msvcrt
        except ImportError:
            _msvcrt = None

        # 🛡️ 진입 전 화면을 확실히 비운다. (이전 TUI 화면 위에 그려 '위로 튐/잔상' 방지)
        #    ↳ 여기서 한 번만 전체 지움(2J)한다. '갱신 중'에는 절대 전체 지우기를 쓰지 않는다!
        # [V193.7] 앱 공용 헬퍼로 통일 (다른 실시간 화면들도 같은 3줄 패턴을 쓴다)
        _ui_live_begin(full_clear=True, tag="SparkProgress", reserve=1)

        started = time.time()
        spin = 0
        finished_at = None   # 완료/실패 감지 시각 (자동 복귀용)

        while True:
            d = _read_spark_progress()
            running = _spark_progress_is_running(d)

            # ---- 그리기: ★ '내용이 바뀐 줄만' 그리고, 하나도 안 바뀌면 0 바이트 ----
            _lines = [f" {C.SKY}── [ 📊 스파크 번역 진행 상황 ] ──{C.RESET}", ""]
            _lines += _spark_progress_lines(d, running, spin)
            _lines.append("")
            if auto_return_on_finish and not running and d.get("stage") in ("finished", "error"):
                _lines.append(f"   {C.GRAY}(완료 감지 — 잠시 후 장바구니로 돌아갑니다){C.RESET}")
            else:
                _lines.append(
                    f"   {C.LIGHT_GREEN}⏎{C.RESET} {C.GRAY}Enter(또는 아무 키)로 돌아가기  ·  {interval:.0f}초 자동 갱신{C.RESET}")
            # 전체 화면 지움(ESC[J/ESC[2J) 0회 · 안 바뀌었으면 아예 아무 것도 안 쓴다 🛡️
            _ui_live_update(_lines)
            spin += 1

            # ---- 완료/실패 감지 → 지정 시 자동 복귀 ----
            if auto_return_on_finish and not running and d.get("stage") in ("finished", "error"):
                if finished_at is None:
                    finished_at = time.time()
                elif time.time() - finished_at >= auto_return_wait:
                    break
            else:
                finished_at = None

            # ---- 키 입력 폴링 (Enter 등) → 즉시 복귀 ----
            if _msvcrt is not None:
                try:
                    # 🐛 IME 팬텀 키 이벤트(0xE5 등) 제거 — 한국어 IME 에서 '실수로 즉시 종료' 방지
                    if _clean_console_input_buffer():
                        _k = _msvcrt.getch()
                        if isinstance(_k, bytes) and _k:
                            # 방향키/기능키 = 선두 바이트(0x00/0xE0) + 뒤 바이트
                            #   → 복귀하지 않고 '뒤 바이트만 소비' 후 계속 관찰한다
                            if _k in (b"\x00", b"\xe0"):
                                try:
                                    _msvcrt.getch()
                                except Exception:
                                    pass
                            elif _k in (b"\r", b"\n", b" ", b"\x1b"):
                                break              # Enter / Space / Esc → 복귀
                            elif _k.isdigit() or (0x61 <= _k[0] <= 0x7a):
                                break              # 숫자 / 영문 소문자 → 복귀
                            # 그 외(Shift, Ctrl 등)는 무시하고 계속 갱신
                except Exception:
                    pass
            else:
                time.sleep(0.25)

            # ---- 종료 조건 ----
            if time.time() - started > max_seconds:
                break
            time.sleep(0.4)

        # 🐛[감사 수정] 마지막 프레임을 '완전 삭제'로 끝낸다.
        #   예전 ESC[F+ESC[J 는 커서를 1줄만 올려서 지우므로 대시보드 전체가
        #   스크롤 히스토리에 남아 맨 화면에 진행내용이 그대로 노출됐다.
        #   → 마지막 요약 1줄만 남기고 나머지는 확실히 날린다.
        # [V193.6] 종료 시에도 '전체 화면 지움(2J)' 대신 '우리가 칠했던 줄만' 지운다.
        #   (전체 지움은 백색 번쩍임 1회를 더 만든다. 🛡️)
        #   TUI 전역 상태 리셋은 clear_console 과 '똑같이' 직접 수행한다
        #   (호출부도 clear_console() 를 호출하므로 화면 정리가 겹쳐도 무해하다)
        _fin = _read_spark_progress()
        _fin_run = _spark_progress_is_running(_fin)
        _fin_stage = _fin.get("stage")
        try:
            _ui_live_end()    # 대시보드가 차지했던 줄만 제자리에서 지운다 (공용 헬퍼)
        except Exception:
            try:
                clear_console(history_preserve=False)
            except Exception:
                sys.stdout.write("\x1b[2J\x1b[H")
        try:
            globals()['G_LAST_TUI_MENU_HEIGHT'] = 0
            globals()['_g_console_has_dirty_logs'] = False
        except Exception:
            pass
        _res_icon, _res_lbl = _SPARK_STAGE_LABEL.get(_fin_stage, ("•", _fin_stage or "대기"))
        if _fin_stage == "finished":
            print(f"\r\n   {C.GREEN}{_res_icon} 스파크 번역 {_res_lbl}{C.RESET} {C.GRAY}({_fin.get('msg') or ''}){C.RESET}")
            print(f"   {C.GRAY}· '장바구니 스파크 자막 즉시 수신(72번)' 으로 완성된 자막을 받아오세요.{C.RESET}\r\n")
        elif _fin_stage == "error":
            print(f"\r\n   {C.RED}{_res_icon} 스파크 번역 실패{C.RESET} {C.GRAY}({_fin.get('msg') or ''}){C.RESET}")
            print(f"   {C.GRAY}· 장바구니에 그대로 남아 다음 실행 때 자동 재시도됩니다.{C.RESET}\r\n")
        else:
            _msg = str(_fin.get("msg") or "")[:70]
            print(f"\r\n   {C.GRAY}← 장바구니로 돌아갑니다. {_msg}{C.RESET}\r\n")
        if callable(globals().get('_invalidate_view_caches')):
            globals()['_invalidate_view_caches']()
        time.sleep(1.2)
        return True
    except Exception as e:
        _log_to_file(f"⚠️ [SparkProgress] 진행 화면 오류: {e}")
        try:
            print(f"\r\n ❌ {C.RED}진행 상황 표시 중 오류: {e}{C.RESET}\r\n")
        except Exception:
            pass
        time.sleep(2.0)
        return False
    finally:
        # [V193.7 · 99감사 P3] 예외로 튀어나가도 '제자리 갱신' 전역 상태를 남기지 않는다
        #   (정상 종료 경로에서는 이미 _ui_live_end() 가 싱글턴을 비우므로 여기는 no-op)
        if globals().get('_UI_LIVE_SINGLETON') is not None:
            try:
                _ui_live_end()
            except Exception:
                pass


# ══════════════════════════════════════════════════════════════════════
# ══════════════════════════════════════════════════════════════════════
# [TAG: #@_spark_profiles_dir]
def _spark_profiles_dir():
    r"""스파크 전용 Chrome 의 프로필 루트 (..\Chrome\SparkData)"""
    local = os.environ.get('LOCALAPPDATA') or os.path.expanduser('~\\AppData\\Local')
    return os.path.join(local, 'Google', 'Chrome', 'SparkData')


# [TAG: #@_spark_local_state_path]
def _spark_local_state_path():
    return os.path.join(_spark_profiles_dir(), 'Local State')


# [TAG: #@_spark_list_profiles]
def _spark_list_profiles():
    """등록된 Chrome 프로필 → [{dir, email, name, exists, logged_in}]"""
    out = []
    try:
        p = _spark_local_state_path()
        if not os.path.exists(p):
            return out
        with open(p, 'r', encoding='utf-8') as f:
            d = json.load(f) or {}
        prof = d.get('profile') or {}
        order = prof.get('profiles_order') or list((prof.get('info_cache') or {}).keys())
        cache = prof.get('info_cache') or {}
        for pdir in order:
            info = cache.get(pdir) or {}
            em = str(info.get('user_name') or '').strip()
            out.append({
                'dir': pdir,
                'email': em,
                'name': info.get('name') or pdir,
                'exists': os.path.isdir(os.path.join(_spark_profiles_dir(), pdir)),
                'logged_in': bool(em and '@' in em),
            })
    except Exception as e:
        _log_to_file(f"⚠️ [SparkProfile] 프로필 목록 조회 실패: {e}")
    return out


# ══════════════════════════════════════════════════════════════════════
# [TAG: #@_spark_logout_profile]
# 🔓 [V193.5] 스파크 프로필 '로그아웃' (쿠키·토큰만 삭제, 폴더는 보존)
#   왜 필요한가: 계정 세션이 꼬였거나 다른 계정으로 바꾸고 싶을 때
#   '프로필 전체 삭제' 는 历史(북마크/로그인정보)까지 날리므로 부담스럽다.
#   → 로그인 정보만 지워 '깨끗한 재로그인' 상태를 만든다.
# ══════════════════════════════════════════════════════════════════════
def _spark_logout_profile(profile_dir):
    """프로필에서 로그인 흔적(쿠키/자격증명/세션)만 제거한다. 반환: (ok, 메시지)"""
    root = _spark_profiles_dir()
    pdir_path = os.path.join(root, profile_dir)
    if not os.path.isdir(pdir_path):
        return False, f"'{profile_dir}' 프로필이 없어."
    _close_spark_chrome_safely()      # 파일 잠금 해제
    time.sleep(1.0)
    removed = []
    # 1) 쿠키 DB (구글 로그인 세션의 핵심)
    for rel in (os.path.join("Network", "Cookies"), "Cookies"):
        fp = os.path.join(pdir_path, rel)
        if os.path.exists(fp):
            try:
                os.remove(fp); removed.append("쿠키")
            except Exception:
                try:
                    os.makedirs(os.path.join(pdir_path, "Network"), exist_ok=True)
                    open(fp, "w").close(); removed.append("쿠키(초기화)")
                except Exception:
                    pass
    # 2) 로그인 정보 저장소
    for rel in ("Login Data", "Login Data For Account", "Web Data", "Affiliation Database"):
        fp = os.path.join(pdir_path, rel)
        if os.path.exists(fp):
            try:
                os.remove(fp); removed.append(rel)
            except Exception:
                pass
    # 3) 세션/스토리지 (앱 로그인 흔적)
    for rel in ("Sessions", "Sessions_Encrypted", "Local Storage", "Session Storage",
                "WebStorage", "Sync Data", "Current Session", "Current Tabs"):
        fp = os.path.join(pdir_path, rel)
        if os.path.exists(fp):
            try:
                if os.path.isdir(fp):
                    import shutil
                    shutil.rmtree(fp, ignore_errors=True)
                else:
                    os.remove(fp)
                removed.append(rel)
            except Exception:
                pass
    # 4) 'Account Web Data' (계정 연동 정보)
    for rel in ("Account Web Data",):
        fp = os.path.join(pdir_path, rel)
        if os.path.exists(fp):
            try:
                os.remove(fp); removed.append(rel)
            except Exception:
                pass
    return True, (f"로그인 정보 제거: {', '.join(removed)}" if removed else "제거할 항목 없음(이미 로그아웃됨)")


# ══════════════════════════════════════════════════════════════════════
# [TAG: #@_spark_reset_profile]
# ♻️ [V193.5] 스파크 프로필 '완전 초기화' (프로필 폴더 통째 삭제)
#   주의: 이 프로필 안의 북마크/기록/확장 등 '모든' 데이터가 사라진다.
#        스파크 번역 전용 프로필이므로 대체로 무해하지만, 되돌릴 수 없으니 확인을 받는다.
# ══════════════════════════════════════════════════════════════════════
def _spark_reset_profile(profile_dir, keep_local_state=True):
    """프로필 폴더를 통째로 삭제하고 Local State 에서 등록을 해제한다."""
    root = _spark_profiles_dir()
    target = os.path.join(root, profile_dir)
    if not os.path.isdir(target):
        return False, f"'{profile_dir}' 프로필이 없어."
    _close_spark_chrome_safely()
    time.sleep(1.0)
    try:
        import shutil
        shutil.rmtree(target, ignore_errors=True)
    except Exception as e:
        return False, f"삭제 실패: {e}"
    if os.path.isdir(target):
        return False, "삭제 실패 (파일이 사용 중일 수 있음)"
    # Local State 에서 등록 해제 + last_used 를 남은 프로필로 되돌린다
    try:
        p = _spark_local_state_path()
        with open(p, 'r', encoding='utf-8') as f:
            d = json.load(f) or {}
        prof = d.setdefault('profile', {})
        prof['profiles_order'] = [x for x in (prof.get('profiles_order') or []) if x != profile_dir]
        (prof.get('info_cache') or {}).pop(profile_dir, None)
        if prof.get('last_used') == profile_dir:
            nxt = (prof.get('profiles_order') or ['Default'])[0]
            prof['last_used'] = nxt
            prof['last_active_profiles'] = [nxt]
        with open(p, 'w', encoding='utf-8') as f:
            json.dump(d, f, ensure_ascii=False, indent=3)
    except Exception as e:
        _log_to_file(f"⚠️ [SparkProfile] Local State 정리 실패: {e}")
    return True, f"'{profile_dir}' 프로필을 완전히 삭제했어냥."


# ══════════════════════════════════════════════════════════════════════
# [TAG: #@_spark_menu_maintenance]
# 🧹 [V193.5] 스파크 프로필 '로그아웃 / 완전 초기화' 서브메뉴
# ══════════════════════════════════════════════════════════════════════
def _spark_menu_maintenance(s=None):
    """스파크 프로필 관리(로그아웃 / 완전 초기화 / 빈 프로필 정리) 서브메뉴"""
    while True:
        profs = _spark_list_profiles()
        if not profs:
            print(f"\r\n {C.SKY}── [ 🧹 스파크 프로필 관리 ] ──{C.RESET}\r\n")
            print(f"   {C.YELLOW}등록된 스파크 Chrome 프로필이 없어. (스파크 크롬을 한 번 실행하면 생겨요){C.RESET}\r\n")
            time.sleep(2.2)
            return
        _cur_act = s.data.get('spark_active_account', '') if s else ''
        _opts = []
        for p in profs:
            _tag = " (사용중)" if p['logged_in'] else f" {C.YELLOW}(미로그인){C.RESET}"
            _b = " ✅" if p['dir'] in str(s.data.get('spark_active_account', '')) else ""
            _email = p['email'] or "(로그인 안 됨)"
            _opts.append((f"🔓 로그아웃: {_email}  [프로필: {p['dir']}]{_tag}{_b}", p['dir']))
        _opts.append(("♻️ 완전 초기화(프로필 폴더 삭제): 선택 → 다음 단계", "__reset__"))
        _opts.append((f"{C.GRAY}🔙 취소{C.RESET}", "__back__"))

        print(f"\r\n {C.SKY}── [ 🧹 스파크 프로필 관리 (로그아웃 / 초기화) ] ──{C.RESET}\r\n")
        print(f"   {C.GRAY}세션이 꼬였거나 다른 계정으로 갈아타고 싶을 때 여기서 초기화해요.{C.RESET}")
        print(f"   {C.GRAY}· '로그아웃'  = 로그인 정보만 지우고 폴더는 보존 (북마크/기록 유지){C.RESET}")
        print(f"   {C.GRAY}· '완전 초기화' = 프로필 전체 삭제 (모든 데이터 사라짐, 되돌릴 수 없음){C.RESET}\r\n")

        labels = [o[0] for o in _opts]
        _sel_data = _interactive_menu("🧹 스파크 프로필 관리", labels)
        _sel = _sel_data[0] if isinstance(_sel_data, tuple) else _sel_data
        if isinstance(_sel, list):
            _sel = _sel[0] if _sel else -1
        if not (0 <= _sel < len(_opts)):
            return

        _label, _target = _opts[_sel]
        if _target == "__back__":
            return
        if _target == "__reset__":
            # 완전 초기화 대상 프로필 선택
            _r_opts = [f"♻️ {p['email'] or '(미로그인)'}  [프로필: {p['dir']}]" for p in profs]
            _r_opts.append(f"{C.GRAY}🔙 취소{C.RESET}")
            print(f"\r\n {C.RED}⚠️ 완전 초기화하면 해당 프로필의 모든 데이터가 삭제됩니다!{C.RESET}")
            print(f"   {C.GRAY}되돌릴 수 없으니 신중히 선택하세요.{C.RESET}\r\n")
            _rs = _interactive_menu("♻️ 완전 초기화할 프로필 선택", _r_opts)
            _rs = _rs[0] if isinstance(_rs, tuple) else _rs
            if isinstance(_rs, list):
                _rs = _rs[0] if _rs else -1
            if not (0 <= _rs < len(profs)):
                return
            _rp = profs[_rs]
            _ans = prompt_input(f"   입력해 '{_rp['dir']}' 을(를) 완전 삭제할까요? (yes 입력): ").strip().lower()
            if _ans != "yes":
                print(f"\r\n {C.GRAY}취소했어냥. 아무것도 삭제하지 않았어요.{C.RESET}")
                time.sleep(1.4)
                continue
            _ok, _msg = _spark_reset_profile(_rp['dir'])
            _col = C.GREEN if _ok else C.RED
            print(f"\r\n {'✅' if _ok else '❌'} {_col}{_msg}{C.RESET}")
            if _ok:
                # 계정 목록에서도 제거
                if s:
                    _lst = [a for a in (s.data.get('spark_login_accounts') or [])
                            if a.get('profile_dir') != _rp['dir']]
                    s.data['spark_login_accounts'] = _lst
                    if s.data.get('spark_active_account') and \
                       _rp['dir'] == (s.data.get('spark_login_accounts') or [{}])[0].get('profile_dir'):
                        s.data['spark_active_account'] = _lst[0]['name'] if _lst else ''
                    s.save()
                print(f"   {C.GRAY}다음 '스파크 번역' 실행 시 새 프로필로 로그인 화면이 열립니다.{C.RESET}")
            time.sleep(2.0)
            continue

        # 로그아웃
        _tp = next((p for p in profs if p['dir'] == _target), None)
        if not _tp:
            continue
        _ans = prompt_input(f"   입력해 '{_target}' 프로필 로그아웃할까요? (yes 입력): ").strip().lower()
        if _ans != "yes":
            print(f"\r\n {C.GRAY}취소했어냥.{C.RESET}")
            time.sleep(1.2)
            continue
        _ok, _msg = _spark_logout_profile(_target)
        _col = C.GREEN if _ok else C.RED
        print(f"\r\n {'✅' if _ok else '❌'} {_col}{_msg}{C.RESET}")
        if _ok:
            print(f"   {C.GRAY}다음 '스파크 번역' 실행 시 로그인 화면이 열립니다. 그때 로그인해주세요!{C.RESET}")
        time.sleep(2.0)


# [TAG: #@_add_spark_account_with_login]
# 🐱[V193.5] 새 스파크 계정 추가 = '새 프로필 → 로그인' 방식 (로그아웃 후 재로그인)
#   Chrome 은 한 프로필에 여러 계정을 동시에 로그인시키면 슬롯(/u/N/)으로 늘어나지만,
#   실측하니 '한 프로필 = 한 계정' 이 기본 구조라 계정마다 '프로필' 을 따로 쓰는 게 확실하다.
#   → 새 프로필 이름을 정하고 그 프로필로 크롬을 '화면 VISIBLE' 로 띄워
#     사용자가 직접 로그인하게 안내한다. (구글 로그인은 브라우저 창에서 해야 하므로 자동화 불가)
# ══════════════════════════════════════════════════════════════════════
def _add_spark_account_with_login(s, existing):
    """새 스파크 계정을 '새 프로필 로그인' 방식으로 등록/활성화한다."""
    try:
        _n = len(existing) + 1
        default_dir = f"Profile Spark{_n}"
        base = _spark_user_data_dir()

        print(f"\r\n 🐱 {C.BOLD}{C.LIGHT_BLUE}[새 스파크 계정 추가]{C.RESET}")
        print(f"   {C.GRAY}Chrome 은 '프로필' 단위로 계정을 기억해요. 새 프로필을 만들고 그곳에{C.RESET}")
        print(f"   {C.GRAY}로그인하면, 앞으로 그 계정으로 스파크 번역을 보낼 수 있어요.{C.RESET}\r\n")

        _dir = prompt_input(f"   📁 새 Chrome 프로필 이름 (기본: {default_dir}): ").strip() or default_dir
        try:
            _dir = re.sub(r'[\\/:*?"<>|]', '', _dir).strip() or default_dir
        except Exception:
            _dir = default_dir
        if _dir == 'Default':
            print(f"\r\n ⚠️ {C.YELLOW}'Default' 는 기존 계정이 있는 프로필이라 덮어씁니다. 다른 이름 쓰세요!{C.RESET}")
            time.sleep(2.0)
            return False

        if os.path.isdir(os.path.join(base, _dir)):
            _ans = prompt_input(f"   ⚠️ '{_dir}' 이(가) 이미 있어요. 그래도 이 프로필을 쓸까요? (y/N): ").strip().lower()
            if not _ans.startswith('y'):
                print(f"\r\n {C.GRAY}취소했어냥.{C.RESET}")
                time.sleep(1.2)
                return False

        # 1) 스파크 크롬 '완전 종료' → 새 프로필로 다시 뜨게 (기존 로그인 잔존 방지)
        _close_spark_chrome_safely()
        time.sleep(1.2)

        # 🐛[P1 순서 버그] 원래 쓰던 프로필은 '크롬을 띄우기 전에' 기억해야 한다.
        #    크롬은 시작과 동시에 last_used 를 새 프로필로 옮겨 버리므로,
        #    Popen 이후에 읽으면 '되돌릴 원본'을 이미 잃어 복구가 무의미해진다. (경합 제거)
        _prev_last_used = ""
        try:
            _pp = _spark_local_state_path()
            if os.path.exists(_pp):
                with open(_pp, 'r', encoding='utf-8') as _f:
                    _prev_last_used = str((json.load(_f) or {}).get('profile', {}).get('last_used') or '')
        except Exception:
            _prev_last_used = ""

        # 2) 새 프로필로 크롬을 '화면 VISIBLE' 로 실행 (사용자가 직접 로그인)
        chrome = None
        for _c in (r"C:\Program Files\Google\Chrome\Application\chrome.exe",
                   r"C:\Program Files (x86)\Google\Chrome\Application\chrome.exe"):
            if os.path.exists(_c):
                chrome = _c
                break
        if not chrome:
            print(f"\r\n ❌ {C.RED}Chrome 실행 파일을 못 찾았어!{C.RESET}")
            time.sleep(2.0)
            return False

        try:
            import subprocess as _sp
            _sp.Popen([chrome, f"--user-data-dir={base}",
                       f"--profile-directory={_dir}",
                       "--no-first-run", "--no-default-browser-check",
                       "https://gemini.google.com/"])
        except Exception as e:
            print(f"\r\n ❌ {C.RED}스파크 로그인 창 실행 실패: {e}{C.RESET}")
            time.sleep(2.0)
            return False

        # 🐛[P0 순서 버그] '로그인 안 됐다' 판정은 반드시 "로그인 후 Enter" 대기 '뒤' 에 한다.
        #    (여기 — 즉 Popen 직후 — 에서 검사하면 크롬이 뜨기기도 전에 판정해
        #     '로그인 실패 → 버릴까요?' 가 100% 무조건 나오는 오탐이 된다. 2026-09-30 실증)
        #    → 아래 "✅ 로그인 후 Enter" 대기 직후로 이동했다.

        print(f"\r\n 🔐 {C.YELLOW}브라우저가 열렸어요. 거기서 그냥 {C.BOLD}{C.WHITE}로그인{C.RESET}{C.YELLOW}만 하면 끝!{C.RESET}")
        print(f"   {C.GRAY}· 새 프로필이라 비어 있으므로, 기존 계정 로그인도 그대로 됩니다.{C.RESET}")
        print(f"   {C.GRAY}· 로그인 후 스파크(Gemini) 화면이 열리는지 확인해 주세요.{C.RESET}\r\n")

        try:
            prompt_input("   ✅ 로그인 후 이 화면에서 Enter 를 누르세요... ").strip()
        except (KeyboardInterrupt, EOFError):
            pass

        # 🐛[P0 순서 버그 고정] 여기서야 '로그인 안 된 빈 프로필' 을 판정한다.
        #    (Popen 직후가 아니라 '사용자가 로그인할 기회를 준 뒤' 에 검사해야 한다)
        #    · 로그인 성공 → info_cache 에 이메일이 있으므로 조용히 통과
        #    · 진짜 실패 → 그때만 되돌릴지 물어보고, 'yes' 면 정리 + last_used 복구
        #      예전엔 이 판정이 로그인 대기 '앞' 에 있어서 매번 오탐이 났다. (2026-09-30 실증)
        try:
            if not _read_spark_logged_in_email(base, _dir):
                print(f"\r\n ⚠️ {C.YELLOW}'{_dir}' 프로필에 로그인된 계정을 못 찾겠어요.{C.RESET}")
                print(f"   {C.GRAY}· 창에서 로그인을 마치지 않았거나, 다른 창에 로그인했을 수 있어요.{C.RESET}")
                _a2 = prompt_input(
                    f"   {C.YELLOW}'yes' 입력 시 이 프로필 폴더가 영구 삭제돼요.{C.RESET}\n"
                    f"   그래도 로그인 안 한 '{_dir}' 프로필을 버릴까요? (yes 입력): "
                ).strip().lower()
                if _a2 == "yes":
                    _ok, _msg = _spark_reset_profile(_dir)
                    print(f"   {'✅' if _ok else '❌'} {_msg}")
                    if _ok:
                        if _prev_last_used and _prev_last_used != _dir:
                            print(f"   {C.GREEN}✅ 원래 프로필('{_prev_last_used}')로 되돌려 놓았어. 이제 정상 전송돼요!{C.RESET}")
                        else:
                            print(f"   {C.YELLOW}⚠️ 되돌릴 이전 프로필을 몰라서 last_used 를 '{_prev_last_used or 'Default'}' 로 설정했어.{C.RESET}")
                            print(f"   {C.GRAY}  스파크를 쓰려면 '스파크 프로필 관리' 에서 로그인된 프로필 하나를 남겨주세요.{C.RESET}")
                        if s:
                            _lst = [a for a in (s.data.get('spark_login_accounts') or [])
                                    if a.get('profile_dir') != _dir]
                            s.data['spark_login_accounts'] = _lst
                            s.save()
                    time.sleep(2.0)
                    return _ok
        except Exception:
            pass

        # 3) 로그인된 이메일을 '실측'해서 등록 (사용자 오입력 없이 자동 인식) 🐱
        _email = _read_spark_logged_in_email(base, _dir)
        if not _email:
            _email = prompt_input(f"   📧 로그인한 계정 이메일 (확인용): ").strip() or _dir
        _name = _email.split('@')[0] if '@' in _email else _dir

        _lst = [a for a in existing if a.get('email') != _email]
        _lst.append({'name': _name, 'email': _email, 'profile_dir': _dir})
        if s:
            s.data['spark_login_accounts'] = _lst
            s.data['spark_active_account'] = _name
            s.save()
        print(f"\r\n ✨ {C.GREEN}'{_email}' (프로필: {_dir}) 을 새 스파크 전송 계정으로 등록했어냥! 🐱🎉{C.RESET}")
        print(f"   {C.GRAY}다음 '스파크 번역'부터 이 계정으로 전송됩니다.{C.RESET}")
        if callable(globals().get('_invalidate_view_caches')):
            globals()['_invalidate_view_caches']()
        time.sleep(2.0)
        return True
    except Exception as e:
        _log_to_file(f"⚠️ [SparkProfile] 새 계정 등록 실패: {e}")
        try:
            print(f"\r\n ❌ {C.RED}계정 추가 중 오류: {e}{C.RESET}")
        except Exception:
            pass
        time.sleep(2.0)
        return False

# [TAG: #@_gdrive_settings_menu]
def _gdrive_settings_menu(s):
    """구글 드라이브 계정 관리 및 설정 메뉴 (V126.0) ☁️⚙️"""
    # [V129.6] UnboundLocalError 방지를 위해 필수 임포트를 함수 최상단으로 이동 🚚🛡️
    import uuid
    # [V129.6-누락분] webbrowser 도 반드시 여기에 있어야 한다! 아래쪽(12913행)에서만
    #   임포트되면 앞선 rclone 인증 흐름(12751행 webbrowser.open)이 UnboundLocalError 로
    #   조용히 삼켜져 브라우저 자동 오픈이 실패한다. 🛡️
    import webbrowser
    try: import requests
    except: requests = None

    while True:
        accounts = _gdrive_accounts(s)
        # [V128.7] AI냥 요청: API 등록 여부 시각화 🛰️✨
        api_status = f" {C.GREEN}(등록됨){C.RESET}" if (s and s.data.get('gdrive_api_client_id')) else ""
        # [신규] 현재 연동된 스파크 자막 수신(추수) 구글 계정 조회 🌾☁️
        cur_spark_acct = s.data.get('spark_gdrive_account', '') if s else ''
        if not cur_spark_acct:
            _gf = s.data.get('audio_extract_gdrive_folder', '') if s else ''
            if _gf and _gf.startswith('gdrive://'):
                _part = _gf[len('gdrive://'):].strip('/')
                cur_spark_acct = _part.split('/')[0] if '/' in _part else _part
        if not cur_spark_acct:
            cur_spark_acct = 'gd_masterbyus'

        cur_spark_disp = cur_spark_acct
        for _a in accounts:
            if _a.get('name') == cur_spark_acct:
                _em = _a.get('email', cur_spark_acct)
                cur_spark_disp = _em.split('@')[0] + '@' if '@' in _em else f"{_em}@"
                break

        # [신규 2026-09-30] 스파크 '전송(로그인)' 계정 — 수신용 Drive 계정과는 별개 🐱🔐
        #   받는 쪽(spark_gdrive_account)과 보내는 쪽(여기)은 서로 다른 계정이다.
        #   ⚠️ 계정의 진짜 단위는 'Chrome 프로필' 이다 (/u/N/ 아님 — 실측 결론)
        cur_login_acct = s.data.get('spark_active_account', '') if s else ''
        _login_accts = (s.data.get('spark_login_accounts') or []) if s else []
        if cur_login_acct:
            cur_login_disp = next(
                (a.get('email') or a.get('name') for a in _login_accts
                 if isinstance(a, dict) and a.get('name') == cur_login_acct), cur_login_acct)
        else:
            cur_login_disp = "자동감지 (마지막사용 프로필)"

        options = [
            f"{C.LIGHT_CYAN}➕ 구글 드라이브 계정 추가 (New Account){C.RESET}",
            f"{C.SKY}🔄 구글 계정 토큰 재인증 (Reconnect){C.RESET}",
            f"{C.YELLOW}🚀 [초강력] 속도 최적화: 전용 API(Client ID) 설정{C.RESET}{api_status}",
            f"{C.LIGHT_RED}🗑️ 구글 드라이브 계정 제거 (Delete Account){C.RESET}",
            f"{C.LIGHT_GREEN}✅ 모든 연결 테스트 (Test All){C.RESET}",
            f"{C.LIGHT_PURPLE}🌾 스파크 자막 수신(추수) 연동 계정 설정{C.RESET} {C.GREEN}[ 현재: {cur_spark_disp} ({cur_spark_acct}) ]{C.RESET}",
            f"{C.LIGHT_BLUE}🐱 스파크 번역 '전송' 로그인 계정 설정{C.RESET} {C.GREEN}[ 현재: {cur_login_disp} ]{C.RESET}",
            f"{C.GRAY}🔙 이전으로{C.RESET}"
        ]

        # 현재 등록된 계정 표시
        header = f"\r\n {C.SKY}── [ ☁️ 구글 드라이브 계정 관리 ] ──{C.RESET}\r\n"
        if not accounts:
            header += " (등록된 계정이 없습니다냥!) \r\n"
        else:
            for i, acct in enumerate(accounts):
                _spark_badge = f" {C.LIGHT_PURPLE}[🌾 스파크 추수 연동]{C.RESET}" if acct['name'] == cur_spark_acct else ""
                header += f" {C.WHITE}[{i+1}]{C.RESET} {C.YELLOW}{acct['name']}{C.RESET} ({acct['email']}){_spark_badge} \r\n"

        print(header)
        sel_data = _interactive_menu("구글 드라이브 관리", options)
        # [V127.2] 반환값이 튜플(int, str, ...)일 경우 인덱스만 추출냥! 🕵️‍♂️✨
        sel = sel_data[0] if isinstance(sel_data, tuple) else sel_data

        if sel == 0:  # 계정 추가
            print(f"\r\n {C.SKY}☁️ 신규 구글 드라이브 계정 등록 프로세스 시작...{C.RESET}")
            sys.stdout.flush()

            # [V128.6] AI냥 요청: 지능형 모드 선택 (일반 vs 전문가) 🚀✨
            _mode_opts = ["⚡ 일반 모드 (rclone 기본값 사용)", "🚀 전문가 모드 (전용 API 키 사용 - 초고속!)"]
            _m_data = _interactive_menu("구글 드라이브 등록 모드 선택", _mode_opts)
            _mode = _m_data[0] if isinstance(_m_data, tuple) else _m_data

            _cid, _ccs = "", ""
            if _mode == 1:
                # [V128.7] AI냥 요청: 저장된 정보가 있으면 자동 로드 🚀
                saved_cid = s.data.get('gdrive_api_client_id')
                saved_ccs = s.data.get('gdrive_api_client_secret')

                if saved_cid and saved_ccs:
                    print(f"\r\n 🛰️ {C.SKY}저장된 API 정보를 발견했습니다냥!{C.RESET}")
                    print(f" {C.GRAY}ID: {saved_cid[:10]}... / Secret: {saved_ccs[:5]}...{C.RESET}")
                    if prompt_input(" 이 정보를 그대로 사용하시겠습니까? (Y/n): ").lower() != 'n':
                        _cid, _ccs = saved_cid, saved_ccs

                if not _cid:
                    # [V128.6] AI냥 요청: 친절한 가이드 및 브라우저 자동 호출 🚀💎
                    _show_gdrive_api_setup_guide()

                    print(f"\r\n 🔑 {C.YELLOW}브라우저 창에서 발급받은 정보를 차례로 입력해줘냥!{C.RESET}")
                    _cid = prompt_input(" 🆔 Client ID를 여기에 붙여넣어줘냥:").strip().strip('"\'')
                    _ccs = prompt_input(" 🔐 Client Secret도 마저 붙여넣어줘냥:").strip().strip('"\'')

                if not _cid or not _ccs:
                    print(f" ⚠️ {C.RED}ID나 Secret이 입력되지 않아 일반 모드로 전환합니다냥!{C.RESET}")
                    _mode = 0
                else:
                    # 입력받은 정보 저장 (영구 보관)
                    s.data['gdrive_api_client_id'] = _cid
                    s.data['gdrive_api_client_secret'] = _ccs
                    s.save()

            name_input = f"gd_{uuid.uuid4().hex[:6]}"
            rclone_exe = _ensure_rclone()
            conf_path = os.path.join('temp', 'rclone.conf')

            try:
                subprocess.run([rclone_exe, 'config', 'delete', name_input, '--config', conf_path],
                               capture_output=True, creationflags=0x08000000)
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

            print(f"\r\n {C.YELLOW}브라우저가 열리면 구글 로그인을 완료하고 권한을 승인해주세요냥!{C.RESET}")
            time.sleep(1.0)

            # [V129.4] 포트 충돌 방지를 위해 기존 rclone 프로세스 정리 🧹✨
            os.system("taskkill /F /IM rclone.exe /T 2>nul")

            # 전문가 모드일 경우 명령어에 파라미터 주입 🧪🛡️
            _base_cmd = f'"{rclone_exe}" config create "{name_input}" drive --config "{conf_path}"'
            if _mode == 1:
                _base_cmd += f' client_id "{_cid}" client_secret "{_ccs}"'

            # [V129.2] rclone이 인증 주소를 출력하면 이를 가로채서 직접 열어주기 위해 Popen 사용냥! 🕵️‍♂️🔍
            print(f"\r\n 📡 {C.SKY}구글 인증 서비스를 준비 중입니다냥...{C.RESET}")
            print(f" {C.GRAY}(브라우저가 자동으로 열리지 않으면 아래 출력되는 주소를 클릭해주세요냥!){C.RESET}\r\n")

            proc = None
            try:
                # 윈도우에서 새로운 콘솔 창을 띄우되, rclone의 출력을 현재 터미널에도 어느 정도 투영냥!
                # rclone config create는 상당히 인터랙티브하므로 shell=True로 실행
                proc = subprocess.Popen(_base_cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, bufsize=1)

                auth_url_found = False
                for line in proc.stdout:
                    # rclone의 출력 내용을 정제해서 현재 터미널에 표시냥! 📝
                    clean_line = line.strip()
                    if not clean_line: continue
                    print(f"  {C.GRAY}[rclone]{C.RESET} {clean_line}")

                    # [V129.5] 인증 URL 패턴 매칭: 단순 안내 주소는 무시하고 토큰이 포함된 진짜 주소만 낚아채기! 🎣✨
                    if not auth_url_found and ("http://127.0.0.1" in clean_line or "accounts.google.com" in clean_line):
                        # 설정 안내 문구에 포함된 주소는 건너뛰기 🧼
                        if "Redirect URL is set to" in clean_line: continue

                        url_match = re.search(r'(https?://[^\s]+)', clean_line)
                        if url_match:
                            # URL 끝에 붙은 불필요한 부착물 제거 🧼
                            target_url = url_match.group(0).rstrip('"\'()[].,')

                            # 진짜 토큰 정보가 있거나 구글 도메인일 때만 오픈!
                            if "/auth?state=" in target_url or "accounts.google.com" in target_url:
                                print(f"\r\n 🌐 {C.GREEN}인증 주소를 발견했습니다냥! 브라우저를 강제로 열어볼게요냥! 🚀{C.RESET}")
                                print(f" 🔗 {C.SKY}{target_url}{C.RESET}")
                                webbrowser.open(target_url)
                                auth_url_found = True

                    # rclone이 "Use auto config? (y/n)" 이라고 물어보는 단계에서 멈추면 안 되므로 루프 탈출 조건 설정
                    if "브라우저 인증을 완료하셨나요?" in clean_line or "완료 후 [엔터]" in clean_line:
                         break

                # 사용자가 인증을 마칠 때까지 대기
                print(f"\r\n {C.YELLOW}브라우저에서 로그인을 완료하고 권한을 승인해주세요냥!{C.RESET}")
                prompt_input(" 완료 후 [엔터]를 누르면 연결을 테스트합니다... ")

            except Exception as e:
                print(f" ❌ {C.RED}인증 과정에서 오류가 발생했습니다냥: {e}{C.RESET}")
            finally:
                if proc:
                    try:
                        # shell=True이므로 프로세스 트리 전체를 죽여야 함 (Windows)
                        os.system(f"taskkill /F /T /PID {proc.pid} 2>nul")
                        proc.terminate()
                    except Exception as e:
                        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                        if "6" not in str(e):
                            _log_to_file(f"⚠️ [Silent Exception] {e}")

            # [V128.6] 최적화 플래그 주입 테스트 🧪
            test_cmd = [rclone_exe, 'lsjson', '--config', conf_path, f"{name_input}:", "--max-depth", "0", "--drive-pacer-min-sleep", "10ms"]
            test_res = subprocess.run(test_cmd, capture_output=True, text=True, creationflags=0x08000000)

            if test_res.returncode == 0:
                print(f"\r\n ✅ {C.GREEN}구글 드라이브 연결 테스트에 성공했습니다!{C.RESET}")

                email_display = "내_드라이브"
                try:
                    dump_res = subprocess.run([rclone_exe, 'config', 'dump', '--config', conf_path], capture_output=True, text=True, creationflags=0x08000000)
                    if dump_res.returncode == 0:
                        dump_data = json.loads(dump_res.stdout)
                        if name_input in dump_data:
                            token_str = dump_data[name_input].get('token', '')
                            if token_str:
                                token_data = json.loads(token_str)

                                access_token = token_data.get('access_token')
                                if access_token:
                                    import requests
                                    api_url = "https://www.googleapis.com/drive/v3/about?fields=user"
                                    headers = {"Authorization": f"Bearer {access_token}"}
                                    drv_res = requests.get(api_url, headers=headers, timeout=5)
                                    if drv_res.status_code == 200:
                                        user_info = drv_res.json().get('user', {})
                                        fetched_email = user_info.get('emailAddress', '')
                                        if fetched_email and "@" in fetched_email:
                                            email_display = fetched_email.split("@")[0]
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")

                email_input = prompt_input(f" 화면에 표시할 이름 입력 (기본: {email_display}): ").strip()
                if not email_input: email_input = email_display

                # [V129.6] AI냥 요청: 임시 ID(name_input)를 이메일 기반 정식 ID로 자동 갱신 🤖✨
                # (예: gd_0f6a20 -> gd_masterbyus)
                final_name = f"gd_{email_input}"
                conf_path = os.path.join('temp', 'rclone.conf')

                # 중복 체크 및 순차 번호 부여 (예: gd_poodle_2) 🛡️
                try:
                    dump_res = subprocess.run([rclone_exe, 'config', 'dump', '--config', conf_path], capture_output=True, text=True, creationflags=0x08000000)
                    if dump_res.returncode == 0:
                        import json as _json
                        all_remotes = _json.loads(dump_res.stdout).keys()
                        if final_name in all_remotes:
                            _cnt = 2
                            while f"{final_name}_{_cnt}" in all_remotes: _cnt += 1
                            final_name = f"{final_name}_{_cnt}"
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")

                # rclone 리모트 이름 실제 변경 실행 🚀
                try:
                    res = subprocess.run([rclone_exe, 'config', 'rename', name_input, final_name, '--config', conf_path], capture_output=True, creationflags=0x08000000)
                    if res.returncode == 0:
                        name_input = final_name  # 확정된 이름으로 갱신
                    else:
                        raise Exception(res.stderr.strip() or "rclone command failed")
                except Exception as e:
                    # 💡 rclone 명령어 실패 시 직접 rclone.conf 파일을 읽어 텍스트 치환으로 섹션 이름 변경냥! (로컬 폴백) 🛠️✨
                    try:
                        if os.path.exists(conf_path):
                            with open(conf_path, 'r', encoding='utf-8') as _cf:
                                _conf_txt = _cf.read()
                            _old_sec = f"[{name_input}]"
                            _new_sec = f"[{final_name}]"
                            if _old_sec in _conf_txt:
                                _conf_txt = _conf_txt.replace(_old_sec, _new_sec)
                                with open(conf_path, 'w', encoding='utf-8') as _cf:
                                    _cf.write(_conf_txt)
                                name_input = final_name
                            else:
                                print(f" ⚠️ 리모트 이름 자동 갱신 실패 (임명 유지): {e}")
                        else:
                            print(f" ⚠️ 리모트 이름 자동 갱신 실패 (임명 유지): {e}")
                    except Exception as _ex:
                        print(f" ⚠️ 리모트 이름 자동 갱신 실패 (임명 유지): {_ex}")

                accounts.append({"name": name_input, "email": email_input})
                s.data['gdrive_accounts'] = accounts
                s.save()
                print(f" 🌟 {C.YELLOW}'{email_input}'{C.GREEN} ({name_input}) 이름으로 등록 완료!{C.RESET}")
            else:
                # [V127.9] AI냥 요청: 연결 실패 시 상세 사유 출력 로직 보강 🕵️‍♂️🛡️
                err_msg = test_res.stderr.strip() or "알 수 없는 연결 오류"
                print(f"\r\n {C.LIGHT_RED}❌ 연결 테스트 실패! {C.RESET}")

                if "invalid_grant" in err_msg.lower():
                    print(f" 💡 {C.YELLOW}원인: 구글 로그인 승인이 취소되었거나 세션이 만료되었습니다냥!{C.RESET}")
                elif "token" in err_msg.lower():
                    print(f" 💡 {C.YELLOW}원인: 인증 토큰이 생성되지 않았습니다. 브라우저에서 '허용'을 꼭 눌러주세요냥!{C.RESET}")
                elif "timeout" in err_msg.lower() or not err_msg:
                    print(f" 💡 {C.YELLOW}원인: 네트워크 응답 속도가 너무 느려 테스트를 완료하지 못했습니다냥!{C.RESET}")
                else:
                    print(f" 🚩 상세 사유: {C.GRAY}{err_msg[:200]}{C.RESET}")

                print(f" {C.SKY}Tip: 인터넷 상태를 확인하고, 브라우저에서 '허용'을 꼭 눌러주세요냥!{C.RESET}")

                # 실패했다면 불완전한 설정 잔재를 다시 지워주는 센스냥! 🧼
                try: subprocess.run([rclone_exe, 'config', 'delete', name_input, '--config', conf_path], creationflags=0x08000000)
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")

                prompt_input("\r\n 엔터를 누르면 메뉴로 돌아갑니다...") # [V127.9] NameError 박멸! 🩹
