    # [V99.5] 기간 포맷터 헬퍼 ⏱️
    # [TAG: #@_format_dur]
    def _format_dur(sec):
        if not sec: return ""
        h, m, s = int(sec // 3600), int((sec % 3600) // 60), int(sec % 60)
        return (f"[{h:02}:{m:02}:{s:02}] " if h > 0 else f"[{m:02}:{s:02}] ")

    # [V99.5] 암호화된 외부 캐시 로드 및 마이그레이션 🛡️🔐
    _d_cache = _manage_explorer_cache()
    if s and 'explorer_duration_cache' in s.data:
        # 기존 저장소 데이터 흡수 후 삭제 (settings.json 다이어트) ✨🧹
        old_cache = s.data.pop('explorer_duration_cache', {})
        if isinstance(old_cache, dict): _d_cache.update(old_cache)
        s.save()

    # [V99.5] 탐색기 전용 영상 길이 캐싱 (뮤비/노뮤비 필터용) 🚀🎬✨
    # [TAG: #@_get_video_duration_with_cache]
    def _get_video_duration_with_cache(path):
        if not path or not os.path.exists(path): return 0
        try:
            mtime = os.path.getmtime(path)
            if path in _d_cache:
                c_data = _d_cache[path]
                if isinstance(c_data, list) and len(c_data) == 2:
                    c_mtime, c_dur = c_data
                    if c_mtime == mtime: return c_dur

            # 캐시 미스: [V5.8] 영상 시간 체크 봉인 🐢🛑
            # dur = get_video_duration(path)
            dur = 0
            _d_cache[path] = [mtime, dur]
            if len(_d_cache) > 5000: _d_cache.pop(next(iter(_d_cache)))
            return dur
        except: return 0

