    def _sync_cursor_from_potplayer(current_sel, last_path=None):
        """🏰 [V129.0] 독립된 동기화 엔진들을 활용하여 커서를 이동합니다 (캡슐화 버전) 🛡️🎯"""
        global _potplayer_sync_active

        # 1. 경로 미지정 시 모드에 따른 전용 함수 호출로 경로 획득
        if last_path is None:
            _t = _get_potplayer_title()
            if _t:
                # [V142.10] AI냥 요청: 단독 재생 시에도 동일한 제목 동기화 로직(find_title) 사용! 🚀✨
                last_path, _ = _get_sync_path_dpl(s, find_title=_t)
            else:
                last_path, _ = _get_sync_path_direct(s)

        if not last_path: return current_sel

        # 2. 통합 내비게이터 _find_idx_in_options를 통해 인덱스 추출
        found_idx, found_path = _find_idx_in_options(options, last_path, _exact_path_map)

        if found_idx != -1:
            # 동기화 성공 알림 및 인덱스 반환 ✨
            _msg_type = "통합" if _t else "직접"
            print(f"\r\n  {ctext(f'🎯 [{_msg_type} 싱크]', C.SKY)} {ctext('커서 자동 이동 완료!', C.WHITE)}", flush=True)
            # 화면 잔상 방지를 위한 ANSI 초기화
            clear_console()
            _potplayer_sync_active = False
            return found_idx, found_path

        return current_sel, None
    # [TAG: #@_resolve_sel_idx]
    def _resolve_sel_idx(sel_input):
        """[V96.4] int, list, set 어떤 형태의 선택 결과든 현재 포커스 인덱스(int)로 변환 🧼✨🎯"""
        if isinstance(sel_input, int): return sel_input
        if isinstance(sel_input, (list, set)) and sel_input:
            # 리스트면 첫 번째 항목(보통 마지막으로 조작한 항목) 반환
            return list(sel_input)[0]
        return next_sel # 기존 값 유지

    # [V130.2] 액션 해독 정합성 강화: 키보드 vs 버튼 충돌 방지 및 전수 매핑 🕵️‍♂️🎯
    # [V130.2] 액션 해독 우선순위 강화: 다중 선택 중에도 클릭된 버튼을 잃어버리지 않게 개선냥! 🛡️🕹️👑
    # [TAG: #@_resolve_action_from_selection]
    def _resolve_action_from_selection(sel, options, _check_indices, rows=0, cols=1, is_explorer=False, filter_text=""):
        action = None

        # [TAG: #@_get_v_num]
        def _get_v_num(target_idx):
            """시각적 번호 환산 (디버깅용) 🕵️‍♂️🔢"""
            if target_idx < 0: return 0
            _v_num = 0
            for i in range(len(options)):
                if _is_tui_item_skipped(i, True, options, rows, cols, is_explorer, True, [], filter_text): continue
                if not _is_tui_item_skipped(i, False, options, rows, cols, is_explorer, True, [], filter_text):
                    _v_num += 1
                if i == target_idx: return _v_num
            return target_idx + 1 if not is_explorer else 0

        try:
            for _idx in _check_indices:
                if 0 <= _idx < len(options):
                    _opt = options[_idx]
                    _v_num = _get_v_num(_idx)
                    _u_txt_raw = str(_get_ui_text(_opt))
                    _u_txt = re.sub(r'\033\[[0-9;]*m', '', _u_txt_raw).strip()

                    if isinstance(_opt, dict):
                        _found_key = _opt.get('key') or _opt.get('action')
                        if _found_key:
                            if _found_key.startswith("action_"): _found_key = _found_key.replace("action_", "", 1)
                            action = _found_key
                            if action:
                                # _log_to_file(f" [Explorer] Action Found: {action} ([{_u_txt}]) at index {_idx} (Visual: {_v_num})")
                                return action
                        else:
                            _keys = list(_opt.keys())
                            # _log_to_file(f" [Explorer] Key Missing at Index {_idx} (Visual: {_v_num}): label=[{_u_txt}], keys={_keys}")
                    else:
                        # _log_to_file(f" [Explorer] Not a Dict at Index {_idx} (Visual: {_v_num})")
                        pass
        except Exception as _e:
            _log_to_file(f" [Explorer] Mapping Error: {_e}")
        return action

