    _sort_prefs = s.data.get('folder_sort_prefs', {}) if s else {}
    _init_sort_key = current_dir if (_is_gdrive_path(current_dir) or _is_virtual_path(current_dir)) else os.path.abspath(current_dir)
    _current_prefs = _sort_prefs.get(_init_sort_key, {})
    _sort_mode = _current_prefs.get('mode', 'name')      # 기본값 'name'
    _sort_reverse = _current_prefs.get('reverse', False)   # 기본값 False
