    _virtual_sort_reverse = False

    # [V61.9] 브라우저/파일 선택 모드 판별 ✨ (UnboundLocalError 방지를 위해 미리 정의)
    is_general_explorer = (title == "TUI 탐색기")

    # [V61.4] 처음 진입 시 커서 위치 초기화 (기본값 0: 좌측 상단 PC 탐색기) 📍
    # [V147.169] 메뉴별 마지막 재생 파일 강조/저장 헬퍼 전진 배치 ✨🛰️
    # [V142.25] AI냥 요청: 로직 이원화 방지를 위한 통합 경로 정규화 함수 ✨🛰️🗺️
    def _norm_p(p):
        """URL은 보존하고 로컬 경로는 절대경로+소문자로 정규화합니다. 🧼✨"""
        if not p or not isinstance(p, str): return ""
        if p.startswith(('http://', 'https://', 'gdrive://', 'virtual://')): return p
        try: return os.path.normpath(os.path.abspath(p)).lower()
        except: return p.lower()

    _last_hists_abs = []
    # [TAG: #@_get_item_disp]

    def _get_item_disp(item, full_path, current_color=""):
        """마지막 재생 파일 강조 색상 적용기 ✨🎨"""
        # [신규] 밑줄→공백 치환 표시 모드 적용 🔤✨
        _us_to_sp = s.data.get('s_m_underscore_to_space', False) if s else False
        if _us_to_sp:
            item = item.replace('_', ' ')
        if current_color: return f"{current_color}{item}{C.RESET}"
        if not full_path: return item
        try:
            # [V142.25] 통합 정규화 함수 사용 🧼✨
            p_abs = _norm_p(full_path)

            # [V147.176] AI냥 요청: "낙엽은 썩으면 안 돼!" (로컬 히스토리 최우선 보호 로직) 🛡️🍂✨
            # [V147.191] ⚠️ 중요: 낙엽(히스토리)은 재생이 완전히 '끝났을 때' 기록되는 것을 원칙으로 함냥! 🏁📜
            # (재생 시작 시 즉시 동기화하던 로직은 AI냥 요청으로 롤백됨 ⏪)
            if len(_last_hists_abs) > 0 and p_abs == _last_hists_abs[0]:
                return f"{C.GOLD}{item}{C.RESET}"
            if len(_last_hists_abs) > 1 and p_abs == _last_hists_abs[1]:
                return f"{C.ORANGE}{item}{C.RESET}"
            if len(_last_hists_abs) > 2 and p_abs == _last_hists_abs[2]:
                return f"{C.BROWN}{item}{C.RESET}"

            # [V147.172] 전역 마지막 재생 파일 기록 (보조 강조! ✨🏆🌍)
            # [BugFix] 폴더별 히스토리가 있으면 전역 보조 강조는 사용하지 않음 → 노/주/갈 중복 방지! 🛡️
            if _last_hists_abs:
                return item  # 이 폴더엔 이미 자체 히스토리가 있으므로 전역은 스킵냥! 🚫
            _gg_data = s.data.get('last_played_global', [])
            if _gg_data is None: _gg_list = []
            elif isinstance(_gg_data, str): _gg_list = [_gg_data]
            elif isinstance(_gg_data, list): _gg_list = _gg_data
            else: _gg_list = []

            for idx, gg_path in enumerate(_gg_list):
                if idx >= 3: break
                if p_abs == _norm_p(gg_path):
                    if idx == 0: return f"{C.GOLD}{item}{C.RESET}"
                    if idx == 1: return f"{C.ORANGE}{item}{C.RESET}"
                    if idx == 2: return f"{C.BROWN}{item}{C.RESET}"
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")
        return item

    # [TAG: #@_save_last_played_ctx_local]

    def _save_last_played_ctx_local(target_path, is_starting=False):
        """현재 컨텍스트에 마지막 재생 파일 기록냥! (전역 함수 호출) 💾✨
        [V147.191] 기록 정책: 재생 시작이 아닌, 완전히 '끝난 파일'만 기록하는 것이 원칙냥! 🏁📜
        (재생 시작 시 즉시 기록하여 색상을 바꾸던 로직은 혼동 방지를 위해 제거됨 🚫)
        """
        pk = _get_history_pk(_view_mode, current_dir, s)
        _save_last_played_ctx(target_path, settings_obj=s, pk=pk, is_starting=is_starting)

    # [신규] 파일 목록 5개 단위 구분선(구분선(width=79)) 삽입 헬퍼 📏✨
    def _apply_file_sep5(file_items):
        """[V155.5] 파일 목록이 길 때 메인 메뉴처럼 5개 단위로 구분선을 삽입합니다."""
        if not (s and s.data.get('s_m_file_sep_5', False)):
            return file_items
        if not file_items or len(file_items) <= 5:
            return file_items
        sep_files = []
        for i, itm in enumerate(file_items):
            if i > 0 and i % 5 == 0:
                sep_files.append(구분선(width=79))
            sep_files.append(itm)
        return sep_files

    # [V21.4.3] AI냥 요청: 플레이리스트 파일(dpl/m3u) 중 최신 시점을 기준으로 신규 파일 ✨ 표시냥! ⚖️⏳
    def _apply_new_sparkles(files_list, time_map=None):
        """플레이리스트(dpl/m3u) 수정 시각보다 최근에 추가된 파일에 ✨를 붙입니다."""
        try:
            if not files_list or _gdrive_mode: return
            
            # [V21.4.3] temp 폴더 내의 .dpl과 .m3u 중 더 최신 시점을 찾습니다냥! 🕵️‍♂️✨
            _t_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "temp")
            import glob
            _pl_files = glob.glob(os.path.join(_t_dir, "Binu_Auto_Playlist*.*"))
            
            _times = []
            for _f in _pl_files:
                if _f.endswith(('.dpl', '.m3u', '.m3u8')):
                    _times.append(os.path.getmtime(_f))
            
            if not _times: return
            dpl_ref_time = max(_times)
            for f_obj in files_list:
                if not isinstance(f_obj, dict): continue
                fp = f_obj.get('path', '')
                if not fp: continue
                try:
                    # [V20.1] 전달받은 시간 맵이 있으면 우선 사용, 없으면 직접 조회 🕒
                    f_mtime = time_map.get(fp) if (time_map and fp in time_map) else None
                    if f_mtime is None and os.path.exists(fp):
                        f_mtime = os.path.getmtime(fp)
                    
                    if f_mtime and f_mtime > dpl_ref_time:
                        f_obj['new_tag'] = f"{C.CYAN}✨{C.RESET}"
                except Exception: pass
        except Exception as _e:
            _log_to_file(f"⚠️ [_apply_new_sparkles] {_e}")

