        if is_pc_root_active and (not _view_mode): active_idx_set.add(len(left_items))
        left_items.append({"key": "action_PC_EXPLORER", "label": f"{C.BOLD}{C.SKY}💻 PC 탐색기{C.RESET}"})


        # left_items.append(" ") # 1: 공백 (AI냥 요청: 번호 정렬을 위해 일단 주석 처리냥! 📏)

        # 2-6: 특수 뷰 모드
        special_views = [
            ("RECENT", "🕒 최근 파일"),
            ("HITS", "👍 따봉동영상"),
            ("YOUTUBE_FOLDER", "📺 유튜브동영상"),
            ("CART", "🛒 카트")
        ]

        for v_code, v_label in special_views:
            if _view_mode == v_code:
                active_idx_set.add(len(left_items))

            lbl = v_label
            if v_code == "CART": lbl = f"🛒 카트 ({len(cart)}개)"
            left_items.append({"key": f"action_{v_code}", "label": lbl})

        left_items.append(" ") # 6: 공백

        # 7-10: 필터/재생 액션 (활성 표시 안 함)
        left_items.extend([
            {"key": "action_PLAY_FILTERED", "label": f"{Cd}🎬 {_get_filter_label(_file_type_filter)}재생{R}"},
            {"key": "action_PLAY_WITH_SUB", "label": f"{Cd}📄 {G}자막있모{R} 재생"},
            {"key": "action_PLAY_WITHOUT_SUB", "label": f"{Cd}🚫 {C.RED}자막없모{R} 재생"},
            {"key": "action_SELECT_FILTERED", "label": f"{Cd}📥 {_get_filter_label(_file_type_filter)}선택{R}"},
        ])
        left_items.append(" ") # 11: 공백

        # [V96.0] 드라이브 및 숏컷 키 적용 📦✨
        # [Fix] 현재 열린 폴더와 가장 구체적으로 매칭되는 항목 하나만 하늘색 강조 🩵
        _cur_drive = os.path.splitdrive(os.path.normpath(current_dir))[0].upper() if (not _is_gdrive_path(current_dir) and not _is_virtual_path(current_dir)) else ""
        _cur_abs = _norm_p(current_dir) if not _is_gdrive_path(current_dir) else ""

        # 숏컷 중 가장 긴(가장 구체적인) 매칭 경로 먼저 계산 🔍
        _best_sc_abs = ""
        if not _is_gdrive_path(current_dir):
            for d in ds_disp:
                if isinstance(d, dict) and 'path' in d:
                    _sc_abs = _norm_p(d['path'])
                    if _is_virtual_path(current_dir) and _is_virtual_path(d['path']):
                        if _cur_abs.startswith(_sc_abs) and len(_sc_abs) > len(_best_sc_abs):
                            _best_sc_abs = _sc_abs
                    elif not _is_virtual_path(current_dir) and not _is_virtual_path(d['path']):
                        if _cur_abs.startswith(_sc_abs) and len(_sc_abs) > len(_best_sc_abs):
                            _best_sc_abs = _sc_abs

        _shortcut_matched = bool(_best_sc_abs)  # 숏컷 매칭되면 드라이브는 강조 안 함냥! 🛡️

        # 1. 드라이브 색칠 🎨
        for d in available_drives:
            if isinstance(d, dict) and 'path' in d:
                _d_drive = os.path.splitdrive(os.path.normpath(d['path']))[0].upper()
                _letter = _d_drive.rstrip(':')
                # [신규] 숨김 처리된 드라이브는 좌측 메뉴에서 제외 💽🚫
                if _letter in _hidden_drives or d['path'].upper() in _hidden_drives or f"{_letter}:\\" in _hidden_drives:
                    continue
                # [수정] is_explorer_mode 환경에서 드라이브 일치 여부만 체크냥!
                # [V141.25] AI냥 요청: 특수 뷰 모드(_view_mode) 중에는 드라이브/숏컷 자동 강조 비활성화 🛡️✨
                _is_active_drive = is_explorer_mode and (not _view_mode) and (not _shortcut_matched) and (not _is_gdrive_path(current_dir)) and (_d_drive == _cur_drive)
                if _is_active_drive: active_idx_set.add(len(left_items))
                _raw_label = d.get('text', d['path'])
                left_items.append({"key": f"DRIVE:{d['path']}", "label": _raw_label, "path": d['path']})

        # 2. 숏컷 색칠 🎨
        for d in ds_disp:
            if isinstance(d, dict) and 'path' in d:
                _sc_abs = _norm_p(d['path'])
                # [V141.25] 숏컷 역시 특수 뷰 모드 중에는 중복 강조 방지냥! 🛡️✨
                _is_active_sc = is_explorer_mode and (not _view_mode) and (_sc_abs == _best_sc_abs)
                if _is_active_sc: active_idx_set.add(len(left_items))
                _raw_label = d.get('text', d['path'])
                left_items.append({"key": f"SHORTCUT:{d['path']}", "label": _raw_label, "path": d['path']})

        # [V127.5] 구글 드라이브 통합 관리 (사용자 요청: 설정 메뉴를 위로, 계정은 아래로! ☁️🔄✨)
        left_items.append(" ")
        left_items.append({"key": "action_GDRIVE_SETTINGS", "label": f"{C.GRAY}☁️ 구글 드라이브{C.RESET}"})

        _gdrive_acct_list = _gdrive_accounts(s) if s else []
        if _gdrive_acct_list:
            for _ga in _gdrive_acct_list:
                _ga_nm  = _ga.get('name', '?')
                _ga_email = _ga.get('email', _ga_nm)
                # [V127.5] AI냥 요청: 계정명을 @까지만 깔끔하게 표시냥! 🧼✨
                _clean_mail = _ga_email.split('@')[0] + "@" if '@' in _ga_email else _ga_email

                # [V127.5] 시각적 계층 구조를 위해 계정명 앞에 약간의 공백 추가 📏✨
                _ga_label = f"  ☁️ {_clean_mail}"
                # [V141.18] 구글 드라이브 활성 체크 로직 복구냥! ☁️▶
                # [V141.25] 구글 드라이브 계정도 예외는 없다냥! 🛡️☁️
                _is_act_gd = is_explorer_mode and (not _view_mode) and _is_gdrive_path(current_dir) and _gdrive_parse_path(current_dir)[0] == _ga_nm
                if _is_act_gd: active_idx_set.add(len(left_items))
                left_items.append({"key": f"action_GDRIVE:{_ga_nm}", "label": f"{_ga_label}"})

        # [V127.1] 정렬 메뉴 토글화 레이블 최적화 (사용자 요청: 상태에 따라 레이블명 자동 전환 🔄✨)
        if _view_mode == 'TRASH' and _virtual_sort_mode == 'default':
            _t_rev = False
            _n_rev = False
        else:
            _t_rev = (_sort_mode == 'time' and _sort_reverse)
            _n_rev = (_sort_mode == 'name' and _sort_reverse)

        left_items.append(" ")
        # [V142.52→통합] 영상/음악 플리 메뉴 제거 → 즐겨찾기(30번)에서 구분선으로 분리 표시 📌✨
        if _view_mode in ('FAVORITES', 'PLAYLIST_VIDEO', 'PLAYLIST_MUSIC'): active_idx_set.add(len(left_items))
        left_items.append({"key": "action_FAVORITES", "label": "📌 즐겨찾기"})

        # [V19.5.3] AI냥 요청: 휴지통 메뉴를 즐겨찾기 아래로 이동냥! ♻️📍✨
        if _view_mode == 'TRASH': active_idx_set.add(len(left_items))
        left_items.append({"key": "action_TRASH", "label": "♻️ 휴지통 (T)"})

        if _view_mode == 'ALL_VIDEO': active_idx_set.add(len(left_items))
        left_items.append({"key": "action_ALL_VIDEO", "label": "🎬 모든동영상"})
        if _view_mode == 'ALL_MUSIC': active_idx_set.add(len(left_items))
        left_items.append({"key": "action_ALL_MUSIC", "label": "🎵 모든음악"})
        left_items.append(" ")
        left_items.extend([
            # [V98.9.6] 정렬 및 필터류를 더 간결하고 고급스럽게 압축 📏💎
            {"key": "action_SORT_TIME_TOGGLE", "label": f"{_sc('time', _t_rev)} {('⏳ 시간역순' if _t_rev else '🕒 시간순')}"},
            {"key": "action_SORT_NAME_TOGGLE", "label": f"{_sc('name', _n_rev)} {('🔡 이름역순' if _n_rev else '🔤 이름순')}"},
            {"key": "action_SORT_SUBTITLE_DESC", "label": f"{_sc('subtitle_time', True)} ⌛ 최신자막순"},
            {"key": "action_SORT_SHUFFLE_TOGGLE", "label": f"{'✅' if _shuffle_mode else '  '} 🔀 셔플 재생 [X]"}, # [V152.2] 셔플 재생 추가
            " ",
            {"key": "action_REFRESH", "label": "🔄 새로고침 [F8]"},
            (lambda item: (active_idx_set.add(len(left_items)) if _view_mode == 'SEARCH' else None, item)[1])({"key": "action_SEARCH_FILE", "label": "🔍 파일찾기 [F9]"}),
            " ",
            {"key": "action_SUBTITLE_FILTER", "label": f"{C.WHITE if _subtitle_filter==0 else (C.LIGHT_GREEN if _subtitle_filter==1 else C.RED)}{('⚪' if _subtitle_filter==0 else ('🟢' if _subtitle_filter==1 else '🔴'))} 자막: {['모두', '있음', '없음'][_subtitle_filter]}{R}"},
            {"key": "action_FILE_TYPE_FILTER", "label": f"{Cd}{['🎬', '🎵', '📄', '📦'][_file_type_filter]} 유형: {['영상', '음악', '자막', '모두'][_file_type_filter]}{R}"},
            {"key": "action_GUIDE", "label": "❓ 조작 가이드"},
            {"key": "action_CANCEL", "label": f"{C.RED}❌ 취소{R}"},
            " ",
            " "
        ])

        # [신규] 드라이브 용량 목록 생성 헬퍼 🖥️💾✨
        # [신규] 드라이브 용량 목록 생성 헬퍼 (토글 버튼화 & 좌측 메뉴 연동) 🖥️💾✨
        def _build_disk_items():
            _items = []
            try:
                import string
                _hidden_drives_local = set()
                if s:
                    for _hd in s.data.get('hidden_drives', []):
                        _hd_u = str(_hd).upper().rstrip(':\\')
                        _hidden_drives_local.add(_hd_u)
                        _hidden_drives_local.add(f"{_hd_u}:\\")
                for letter in string.ascii_uppercase:
                    drive = f"{letter}:\\"
                    if os.path.exists(drive):
                        try:
                            usage = shutil.disk_usage(drive)
                            vol_name = ""
                            try:
                                vn_buf = ctypes.create_unicode_buffer(1024)
                                if ctypes.windll.kernel32.GetVolumeInformationW(ctypes.c_wchar_p(drive), vn_buf, 1024, None, None, None, None, 0):
                                    vol_name = vn_buf.value
                            except: pass
                            percent = (usage.used / usage.total) * 100 if usage.total > 0 else 0
                            filled = int(percent / 10)
                            bar = "■" * filled + "□" * (10 - filled)
                            bar_color = C.GREEN if percent < 70 else (C.YELLOW if percent < 90 else C.RED)
                            f_percent = 100 - percent
                            _is_hidden = (letter.upper() in _hidden_drives_local) or (drive.upper() in _hidden_drives_local)
                            _t_icon = f"{C.GRAY}⬜{C.RESET}" if _is_hidden else f"{C.GREEN}✅{C.RESET}"
                            label = f"{_t_icon} {letter}:\\ {bar_color}[{bar}]{R} {C.SKY}{_format_size_hr(usage.free)}{R} / {_format_size_hr(usage.total)} ({f_percent:.1f}%)"
                            if vol_name: label += f" {C.DIM}[{vol_name}]{R}"
                            # [토글 버튼] 하드 안으로 이동하지 않고 좌측 사이드바 표시 여부 토글 액션 키 부여 🎛️💾✨
                            _items.append({"key": f"action_TOGGLE_DRIVE_VISIBILITY:{letter.upper()}", "label": label})
                        except: pass
            except: pass
            return _items

        # [신규] 가상 폴더 / 물리 폴더 컨텍스트 식별 헬퍼 🧭✨
        _VIEW_NAMES_MAP = {
            'RECENT': '최근 파일',
            'HITS': '따봉동영상',
            'CART': '카트',
            'TRASH': '휴지통',
            'ALL_VIDEO': '모든동영상',
            'ALL_MUSIC': '모든음악',
            'FAVORITES': '즐겨찾기',
            'PLAYLIST_VIDEO': '영상 플레이리스트',
            'PLAYLIST_MUSIC': '음악 플레이리스트',
            'YOUTUBE_FOLDER': '유튜브 보관함',
            'SEARCH': '검색 결과',
            'MISSAV_FOLDER': 'MissAV 보관함',
            'TORRENT_FOLDER': '토렌트 보관함',
            '141PPV_FOLDER': '141PPV 보관함',
        }

        def _get_current_ctx_info(v_mode, c_dir):
            if v_mode and v_mode in _VIEW_NAMES_MAP:
                return f"VIEW:{v_mode}", f"가상폴더({_VIEW_NAMES_MAP[v_mode]})"
            elif v_mode:
                return f"VIEW:{v_mode}", f"가상폴더({v_mode})"
            if c_dir:
                if _is_virtual_path(c_dir):
                    _vn, _ = _virtual_parse_path(c_dir)
                    return f"VIRTUAL:{_vn}", f"가상폴더({_vn})"
                return os.path.normpath(c_dir).lower(), os.path.basename(c_dir) or c_dir
            return "UNKNOWN", "알 수 없는 폴더"

        def _get_common_ui_cache_str(v_mode, c_dir):
            if not s: return ""
            _ck, _ = _get_current_ctx_info(v_mode, c_dir)
            _f_vols = s.data.get('folder_auto_volumes', {})
            _cur_v = _lookup_folder_volume_entry(_ck, _f_vols, s)
            if _cur_v is None and c_dir:
                _cur_v = _lookup_folder_volume_entry(c_dir, _f_vols, s)
            _trks = s.data.get('skybox_tracker_folders', [])
            if _ck.startswith("VIEW:"):
                _sky = (_ck in _trks)
            else:
                _sky = any(not f.startswith("VIEW:") and os.path.normpath(f).lower() == _ck for f in _trks)
            _rem = s.data.get('s_m_remote_file_tracker', False)
            _ht = s.data.get('s_m_hide_temp', False)
            _us = s.data.get('s_m_underscore_to_space', False)
            _s5 = s.data.get('s_m_file_sep_5', False)
            _ctoe = s.data.get('clear_translated_on_exit', False)
            _croe = s.data.get('clear_recent_on_exit', False)
            _hd = ",".join(sorted(s.data.get('hidden_drives', [])))
            return f"{_cur_v}_{_sky}_{_rem}_{_ht}_{_us}_{_s5}_{_ctoe}_{_croe}_{_hd}"

        # [V97.6] AI냥 요청: '__DIVIDER__' 대신 '키 형식(Dict)' 사용 및 정렬 최적화 🧼✨💎
        # [TAG: #@_get_explorer_items]
        def _get_explorer_items(title, icon, content_list, e_opts=None, is_header=True, mid_content=None):
            if e_opts is None: e_opts = []

            # [신규] 모든 가상/물리 뷰 공통 토글 및 볼륨 메뉴 (녹색 체크상자 5종) 🟢✨
            _common_toggle_opts = []
            if mode == 'file':
                _ctx_k, _ctx_n = _get_current_ctx_info(_view_mode, current_dir)
                
                # 1. 임시/시스템/숨김 파일 숨기기 토글
                _hide_temp = s.data.get('s_m_hide_temp', False) if s else False
                _t_icon = f"{C.GREEN}✅{C.RESET}" if _hide_temp else f"{C.GRAY}⬜{C.RESET}"
                _common_toggle_opts.append({"key": "action_TOGGLE_TEMP_FILES", "label": f"🟢 {_t_icon} 임시/시스템/숨김 파일 숨기기 (토글)"})

                # 2. 밑줄(_) 공백 치환 토글
                _us_to_sp = s.data.get('s_m_underscore_to_space', False) if s else False
                _us_icon = f"{C.GREEN}✅{C.RESET}" if _us_to_sp else f"{C.GRAY}⬜{C.RESET}"
                _common_toggle_opts.append({"key": "action_TOGGLE_UNDERSCORE_SPACE", "label": f"🔤 {_us_icon} 밑줄(_)을 공백으로 치환해서 보기 (토글)"})

                # 3. 5개 단위 구분선 토글
                _sep5 = s.data.get('s_m_file_sep_5', False) if s else False
                _sep5_icon = f"{C.GREEN}✅{C.RESET}" if _sep5 else f"{C.GRAY}⬜{C.RESET}"
                _common_toggle_opts.append({"key": "action_TOGGLE_FILE_SEP_5", "label": f"📏 {_sep5_icon} 파일 리스트 구분선 (5개) 추가 (토글)"})

                # 4. Skybox Tracker 토글 (가상/물리 개별 판정)
                _tracker_folders = s.data.get('skybox_tracker_folders', []) if s else []
                if _ctx_k.startswith("VIEW:"):
                    _this_sky_on = (_ctx_k in _tracker_folders)
                else:
                    _this_sky_on = any(not f.startswith("VIEW:") and os.path.normpath(f).lower() == _ctx_k for f in _tracker_folders)
                _s_icon = f"{C.GREEN}✅{C.RESET}" if _this_sky_on else f"{C.GRAY}⬜{C.RESET}"
                _sky_lbl = f"이 {_ctx_n} Skybox 자동 추적 (저장/제거)" if _ctx_k.startswith("VIEW:") else "이 폴더 Skybox 자동 추적 (저장/제거)"
                _common_toggle_opts.append({"key": "action_TOGGLE_SKYBOX_TRACKER", "label": f"📡 {_s_icon} {_sky_lbl}"})

                # 4-2. [V180.7] 원격(WebDAV/미디어서버) 재생 파일 실시간 자동 추적 전역 토글 🌐🎯
                _rem_on = s.data.get('s_m_remote_file_tracker', False) if s else False
                _r_icon = f"{C.GREEN}✅{C.RESET}" if _rem_on else f"{C.GRAY}⬜{C.RESET}"
                _rem_lbl = "원격지 요청 파일(webdav/ftp/web) 자동 추적 하이라이트 (토글)"
                _common_toggle_opts.append({"key": "action_TOGGLE_REMOTE_TRACKER", "label": f"🌐 {_r_icon} {_rem_lbl}"})

                # 5. 볼륨 자동 조절 (가상/물리 개별 판정)
                _f_auto_vols = s.data.get('folder_auto_volumes', {}) if s else {}
                _cur_f_vol = _lookup_folder_volume_entry(_ctx_k, _f_auto_vols, s)
                if _cur_f_vol is None and current_dir:
                    _cur_f_vol = _lookup_folder_volume_entry(current_dir, _f_auto_vols, s)
                if _cur_f_vol is not None:
                    _v_icon = f"{C.GREEN}✅{C.RESET}"
                    _v_text = f"{C.YELLOW}{_cur_f_vol}%{C.RESET}"
                else:
                    _v_icon = f"{C.GRAY}⬜{C.RESET}"
                    _v_text = f"{C.GRAY}OFF{C.RESET}"
                _vol_lbl = f"이 {_ctx_n} 재생시 볼륨 자동 조절" if _ctx_k.startswith("VIEW:") else "이 폴더 재생시 볼륨 자동 조절"
                _common_toggle_opts.append({"key": "action_SET_FOLDER_AUTO_VOLUME", "label": f"🔊 {_v_icon} {_vol_lbl} ({_v_text})"})

            # [V130.5] ☁️ 구글 드라이브 액션 버튼 정밀 구성 🚀
            _gd_opts = []
            if mode == 'file':
                if not _is_gdrive_path(current_dir):
                    if _gdrive_manager('accounts', s=s):
                        _gd_opts.append({"key": "action_COPY_GDRIVE", "label": "🚀 구글로 복사하기 (U)"})
                        _gd_opts.append({"key": "action_SYNC_GDRIVE", "label": "🔄 현재리스트 구글드라이브와 싱크하기"})
                else:
                    # 구글 드라이브 내부에서는 내 컴퓨터로 가져오기(다운로드) 활성화 📥 (단축키: V)
                    _gd_opts.append({"key": "action_DOWNLOAD_GDRIVE", "label": "🚀 로컬로 가져오기 (V)"})

            # [v7.6] AI냥 요청: 가로선 아래 고정 메뉴 영역에 페이지 이동 버튼 추가 🌐🔄✨
            # [V141.2] AI냥 통합 요청: 페이지네이션 로직을 공통 _get_pagination_opts 함수로 위임냥! 🐾✨
            pagination_opts = []
            # [v8.1] YOUTUBE_FOLDER는 로컬 폴더라 cat_url 없음 → 웹 모드만 페이지네이션 적용냥! 🌐📄✨
            if _view_mode in ['SEARCH', 'MISSAV_FOLDER', 'TORRENT_FOLDER', '141PPV_FOLDER']:
                pagination_opts = _get_pagination_opts(view_mode=_view_mode)

            # [신규] 물리 탐색기일 때 즐겨찾기 추가/해제 버튼 연동 📌
            _cur_fav_opts = _fav_btn_opts if ('_fav_btn_opts' in locals() and not _view_mode) else []

            # [V165.3] 동적 토글 상태별 라벨/색상/이모지 제어 (1: 녹색, 2: 빨간색, 0: 기본값) 🎨✨
            _t_st = globals().setdefault('_g_select_toggle_states', {'sub': 0, 'hit': 0, 'size': 0})
            _sub_st = _t_st.get('sub', 0)
            _hit_st = _t_st.get('hit', 0)
            _sz_st = _t_st.get('size', 0)

            # 1. 자막 토글 라벨 (자막 없는 영상 우선 선택) 📄🚫✨
            if _sub_st == 1:
                _sub_lbl = f"🔴 {C.RED}자막 없는 동영상 선택됨 (토글){C.RESET}"
            elif _sub_st == 2:
                _sub_lbl = f"🟢 {C.GREEN}자막 있는 동영상 선택됨 (토글){C.RESET}"
            else:
                _sub_lbl = "📄 자막 없는/있는 동영상 선택 (토글)"

            # 2. 따봉 토글 라벨
            if _hit_st == 1:
                _hit_lbl = f"🟢 {C.GREEN}따봉 마크 있는 파일 선택됨 (토글){C.RESET}"
            elif _hit_st == 2:
                _hit_lbl = f"🔴 {C.RED}따봉 마크 없는 파일 선택됨 (토글){C.RESET}"
            else:
                _hit_lbl = "👍 따봉 마크가 있는/없는 파일 선택 (토글)"

            # 3. 용량 토글 라벨
            if _sz_st == 1:
                _sz_lbl = f"🟢 {C.GREEN}100메가 미만 파일 선택됨 (토글){C.RESET}"
            elif _sz_st == 2:
                _sz_lbl = f"🔴 {C.RED}100메가 이상 파일 선택됨 (토글){C.RESET}"
            else:
                _sz_lbl = "💾 100메가 미만/이상 파일 선택 (토글)"

            # [V132.8] ⚓ AI냥의 명품 메뉴 가이드 (🚨 신규 메뉴 추가 시 필수 3대 체크리스트!) ⚓
            # 📖 정식 규칙 → AGENTS.md § "TUI 메뉴 액션 = 화이트리스트 3곳 필수 등록"
            # 1. 메뉴 정의: {"key": "action_액션이름", "label": "표시문구"}
            # 2. 🚨 화이트리스트 등록 (절대 누락 금지! 누락 시 클릭해도 액션 차단되어 먹통 됨):
            #    - _bypass_targets_check_actions : 타겟 파일 없어도 액션 허용
            #    - _master_actions (★여기 빠지면 죽은 코드★) : 마스터 디스패치 진입 허용
            #    - _initial_indices 예외 : 다중선택 작업 시 선택 해제 방지
            # 3. 핸들러 구현: if action == "액션이름": ... (아래 원격 디스패치 체인) 🛡️✨💎
            # 4. 검증: 새 액션 추가 후 반드시 화이트리스트 등장 횟수(>=3) + 핸들러 연결을 확인할 것!
            return [
                구분선(title, icon=icon, width=79), # 엔진 수정으로 79 너비가 안전하게 출력됨!
            ] + content_list + [
                구분선(width=79)
            ] + (mid_content if mid_content else []) + ([구분선(width=79)] if mid_content else []) + pagination_opts + e_opts + _common_toggle_opts + _gd_opts + [
                {"key": "action_CLEAR_FOLDER_HISTORY", "label": "🍂 이 폴더 히스토리 초기화 하기 (낙엽 치우기)"},
                {"key": "action_DIRECT_PATH", "label": "⌨️ 직접 텍스트로 경로 입력"},
                {"key": "action_TRASH_CLEAR", "label": "🗑️ 휴지통 비우기 (t)"}, #@trash_menu_shortcut_t_T_split_fix
                {"key": "action_TRASH_RESTORE", "label": "♻️ 휴지통에서 복구하기"},
                {"key": "action_SELECT_POTPLAYER_PLAYED", "label": "🎬 팟플 재생(시청)한 파일 모조리 선택 (1회성) (y, .)"},
                {"key": "action_SELECT_SUB_TOGGLE", "label": _sub_lbl},
                {"key": "action_SELECT_HIT_TOGGLE", "label": _hit_lbl},
                {"key": "action_SELECT_SIZE_TOGGLE", "label": _sz_lbl},
                {"key": "action_SUB_MUX", "label": "📥 선택한 파일의 자막을 동영상에 합체 (ffmpeg soft)"},
                {"key": "action_FIX_VIDEO_JITTER", "label": "🪄 선택한 파일 떨림/프레임 보정 (디인터레이스 & CFR 고속 복구)"},
                {"key": "action_AUDIO_EXTRACT", "label": "🎵 선택한 파일의 음원 추출 (원음/MP3/전사용)"},
                {"key": "action_EMBED_ALBUM_ART", "label": "🎨 선택한 음악 파일에 앨범 커버(아트) 주입/임베드"},
                {"key": "action_SUB_EXTRACT", "label": "📤 선택한 파일의 내장 자막 분리 & 제거"},
                {"key": "action_SUB_OPEN_NOTEPAD", "label": "📝 선택한 파일의 자막 파일 메모장으로 열기"},
                {"key": "action_SUB_DELETE_TRASH", "label": "🗑️ 선택한 파일의 자막 파일 삭제 (휴지통)"},
                {"key": "action_SUB_TRANS_GEMINI", "label": "🧠 선택한 파일의 외국어 자막 한글로 번역 (gemini api)"},
                {"key": "action_SERIES_TIME_REORDER", "label": "⏱️ 선택한 파일의 시리즈 시간 재정렬 & 영상-자막 시간 일치 (동기화)"},
                {"key": "action_REORDER_SHORTCUTS", "label": "⚙️ 숏컷 위치 조정 (선호번호 지정)"},
            ] + ([{"key": "action_SEARCH_UPLOADER_DOWNLOAD", "label": f"{C.GOLD}🔎 파일명 괄호 [업로더] 로 유튜브 검색 다운로드 (L){C.RESET}"}] if _view_mode == 'YOUTUBE_FOLDER' else []) + [
                {"key": "action_OPEN_EXPLORER", "label": "📂 이 폴더 탐색기로 열기"}
            ] + _cur_fav_opts


        if _view_mode in ('FAVORITES', 'PLAYLIST_VIDEO', 'PLAYLIST_MUSIC'):
            # [V19.6] AI냥 요청: 즐겨찾기(FAVORITES) 뷰 가속화 (캐시 연동 🚀✨)
            # [통합] 가상 병합 폴더, 수동 즐겨찾기, 영상/음악 플리를 구분선으로 분리 표시 📌🔮🎬🎵
            _fav_ck = f"{len(s.data.get('virtual_folders', {}))}_{len(s.data.get('playlist_groups', {}))}_{len(s.data.get('playlist_music_groups', {}))}_{show_music_fav}_{_get_common_ui_cache_str(_view_mode, current_dir)}"
            if action and action not in ("REFRESH") and _last_fav_cache_key == _fav_ck and _last_fav_right_items is not None:
                right_items = _last_fav_right_items
            else:
                # [통합] 가상 병합 폴더, 수동 즐겨찾기, 영상 플리, 음악 플리를 구분선으로 분리해서 하나의 목록으로 표시 📌🔮🎬🎵
                vid_folders = set()
                mus_folders = set()
                custom_fav_folders = s.data.get('custom_favorites', []) if s else []
                virt_folders_map = s.data.get('virtual_folders', {}) if s else {}
                if s:
                    for paths in s.data.get('playlist_groups', {}).values(): vid_folders.update(paths)
                    for paths in s.data.get('playlist_music_groups', {}).values(): mus_folders.update(paths)

                # 1) 수동 추가 즐겨찾기 목록 구성 📌✨
                custom_fav_list = []
                for d in sorted(custom_fav_folders):
                    if os.path.exists(d):
                        disp_str = f"📁 {d}"
                        custom_fav_list.append({"text": disp_str, "path": d})
                        _exact_path_map[disp_str] = d
                if not custom_fav_list: custom_fav_list = [{"text": " (수동으로 추가된 즐겨찾기 폴더가 없습니다)", "path": None}]

                # 2) 영상 플리 목록 구성
                vid_list = []
                for d in sorted(vid_folders):
                    if os.path.exists(d):
                        disp_str = f"📁 {d}"
                        vid_list.append({"text": disp_str, "path": d})
                        _exact_path_map[disp_str] = d
                if not vid_list: vid_list = [{"text": "(등록된 영상 플리가 없습니다)", "path": None}]

                # 3) 음악 플리 목록 구성
                mus_list = []
                for d in sorted(mus_folders):
                    if os.path.exists(d):
                        disp_str = f"📁 {d}"
                        mus_list.append({"text": disp_str, "path": d})
                        _exact_path_map[disp_str] = d
                if not mus_list: mus_list = [{"text": "(등록된 음악 플리가 없습니다)", "path": None}]

                # 0) 가상 병합 폴더(Union) 목록 구성 🔮✨
                virt_list = []
                for _vnm, _vpaths in sorted(virt_folders_map.items()):
                    _valid_ps = [p for p in _vpaths if os.path.exists(p)]
                    _p_sum = ", ".join([os.path.basename(p.rstrip('\\/')) or p for p in _valid_ps[:3]])
                    if len(_valid_ps) > 3: _p_sum += f" 외 {len(_valid_ps)-3}개"
                    _disp_str = f"🔮 {_vnm}  →  [{len(_valid_ps)}개 병합] ({_p_sum})"
                    _v_path = f"virtual://{_vnm}"
                    virt_list.append({"text": _disp_str, "path": _v_path})
                    _exact_path_map[_disp_str] = _v_path
