                if _exists:
                    ext = os.path.splitext(rp)[1].lower()
                    has_s = (any(os.path.exists(os.path.splitext(rp)[0] + s_ext) for s_ext in ('.ko.srt', '.srt', '.smi')) and rp.lower().endswith(v_exts))

                    # [신규] 자막 및 유형 필터 연동 ✨
                    if _subtitle_filter == 1 and not has_s: continue
                    if _subtitle_filter == 2 and has_s: continue

                    if _file_type_filter == 0 and ext not in v_exts: continue
                    if _file_type_filter == 1 and ext not in m_exts: continue
                    if _file_type_filter == 2 and ext not in t_exts: continue
                    if _file_type_filter == 3 and ext in ('.srt', '.smi'): continue

                    # [V128.7] AI냥 요청: 현재 팟플에서 재생 중인 파일에 재생 아이콘(📀) 시각화 🚀✨
                    is_playing = (fresh_pot_path and os.path.normcase(os.path.abspath(rp)) == os.path.normcase(os.path.abspath(fresh_pot_path)))
                    icon = '📀' if is_playing else ('🎥' if ext.endswith(v_exts) else '🎵' if ext.endswith(m_exts) else '📄' if ext.endswith(t_exts) else '📎')
                    srt_icon = "📄" if has_s else "  "
                    hit_icon = "👍" if os.path.basename(rp) in hits else "  "
