                    _s_exts_t = ('.srt', '.smi', '.ass', '.vtt', '.ssa', '.sub', '.sbv')
                    
                    v_bases = {os.path.splitext(f)[0] for f in all_files if f.lower().endswith(_v_exts_t)}
                    clean_v_bases = set()
                    for vb in v_bases:
                        cvb = re.sub(r"[‛'‘`’“”′″‚„‹›]", "", vb).strip().lower()
