                            s_base_clean = raw_s_base
                            for lang_tag in ('.ko', '.kr', '.en', '.ja', '.jp', '.zh', '.cn', '_ko', '_kr', '_en'):
                                if s_base_clean.lower().endswith(lang_tag):
                                    s_base_clean = s_base_clean[:-len(lang_tag)]
