                            # 음원 확장자 제거 (.mp3.srt 등)
                            for a_ext in ('.mp3', '.wav', '.m4a', '.aac', '.flac', '.ogg', '.wma'):
                                if s_base_clean.lower().endswith(a_ext):
                                    s_base_clean = s_base_clean[:-len(a_ext)]
