# [TAG: #@_search_web_duckduckgo]
def _search_web_duckduckgo(query: str) -> str:
    """[V54.1] AI 챗봇의 외부 지식 보완을 위한 쌩 내장 모듈 기반 덕덕고 웹 파싱 모듈 🔍"""
    try:
        import urllib.request
        import urllib.parse
        import ssl
        import re # [수정] urllib.parse 명시적 임포트 🌐
        url = "https://html.duckduckgo.com/html/?q=" + urllib.parse.quote(query)
        req = urllib.request.Request(
            url,
            data=b"",
            headers={
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)',
                'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,*/*;q=0.8',
                'Accept-Language': 'en-US,en;q=0.5'
            }
        )
        context = ssl._create_unverified_context()
        html_content = ""
        try:
            with urllib.request.urlopen(req, data=urllib.parse.urlencode({'q': query}).encode('utf-8'), context=context, timeout=5) as res:
                html_content = res.read().decode('utf-8')
        except Exception:
            try:
                req = urllib.request.Request(url, headers=req.headers)
                with urllib.request.urlopen(req, context=context, timeout=5) as res:
                    html_content = res.read().decode('utf-8')
            except Exception as e:
                _log_to_file(f"⚠️ [DuckDuckGo Error] {e}")
                return []

        snippets = re.findall(r'<a class="result__snippet[^>]*>(.*?)</a>', html_content, flags=re.DOTALL | re.IGNORECASE)
        results = []
        for s in snippets:
            text = re.sub(r'<[^>]+>', '', s)
            text = html.unescape(text) # [V2.0] html.escape 대신 unescape 사용
            text = text.strip()
            if len(text) > 10:
                results.append(text)
            if len(results) >= 3:
                break
        return "\r\n".join(results)
    except Exception as e:
        _log_to_file(f"🔍 [Web Search Error] {e}")
        return f"검색 중 오류가 발생했습니다: {e}"

# [TAG: #@_search_youtube_advanced]
def _search_youtube_advanced(query: str, limit: int = 20, offset: int = 0) -> List[dict]:
    """[V1.0] yt-dlp를 사용하여 유튜브 검색 결과 리스트를 가져옵니다. (제목, ID, URL 포함) 🔍✨"""
    import yt_dlp

    # [V1.2] 한국어 제목 및 날짜 정보 수집 강화 🛠️
    ydl_opts = {
        'extract_flat': True,
        'quiet': True,
        'no_warnings': True,
        'logger': SilentLogger(),
        'playlist_items': f"{offset + 1}-{offset + limit}",
        'language': 'ko',
        'geo_bypass': True, # [V142.14] 지역 제한 우회 및 현지화 유도 🌍
        'extractor_args': {'youtube': {'lang': ['ko']}}, # [V17.5.3] AI냥 요청: 한국어 제목 강제 (1순위) 🇰🇷✨
        'headers': {
            'Accept-Language': 'ko-KR,ko;q=0.9',
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/119.0.0.0 Safari/537.36'
        }
    }

    results = []
    try:
        with yt_dlp.YoutubeDL(ydl_opts) as ydl:
            # ytsearch 기법을 사용하여 검색어 조회
            search_query = f"ytsearch{offset + limit}:{query}"
            info = ydl.extract_info(search_query, download=False)

            if 'entries' in info:
                # ytsearch{N}은 항상 1번부터 N번까지 가져오므로, 요청한 offset 이후 항목만 취함
                all_entries = info['entries']
                target_entries = all_entries[offset:offset + limit]

                for entry in target_entries:
                    if entry:
                        v_id = entry.get('id')
                        v_url = f"https://www.youtube.com/watch?v={v_id}" if v_id else (entry.get('url') or entry.get('webpage_url'))
                        results.append({
                            'id': v_id,
                            'title': entry.get('title', '제목 없음'),
                            'url': v_url,
                            'uploader': entry.get('uploader', '알 수 없음'),
                            'duration': entry.get('duration'),
                            'upload_date': entry.get('upload_date') # [V142.14] 업로드 날짜 정보 추가 📅
                        })
    except Exception as e:
        _log_to_file(f"🔍 [YouTube Advanced Search Error] {e}")

    return results

# [TAG: #@_search_youtube_playlists]

def _search_youtube_playlists(query: str, limit: int = 50, offset: int = 0) -> List[dict]:
    """yt-dlp를 사용하여 재생목록 필터링된 유튜브 검색 결과 리스트를 가져옵니다. 🔍📁✨"""
    import yt_dlp
    import urllib.parse

    encoded_query = urllib.parse.quote_plus(query)
    search_url = f"https://www.youtube.com/results?search_query={encoded_query}&sp=EgIQAw%253D%253D"

    ydl_opts = {
        'extract_flat': True,
        'quiet': True,
        'no_warnings': True,
        'logger': SilentLogger(),
        'playlist_items': f"{offset + 1}-{offset + limit}",
        'language': 'ko',
        'geo_bypass': True,
        'extractor_args': {'youtube': {'lang': ['ko']}},
        'headers': {
            'Accept-Language': 'ko-KR,ko;q=0.9,en-US;q=0.8,en;q=0.7',
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/119.0.0.0 Safari/537.36'
        }
    }

    results = []
    try:
        with yt_dlp.YoutubeDL(ydl_opts) as ydl:
            info = ydl.extract_info(search_url, download=False)
            if info and 'entries' in info:
                all_entries = info['entries']
                target_entries = all_entries[offset:offset + limit]

                for entry in target_entries:
                    if entry:
                        v_id = entry.get('id')
                        v_url = f"https://www.youtube.com/playlist?list={v_id}" if v_id else (entry.get('url') or entry.get('webpage_url'))
                        results.append({
                            'id': v_id,
                            'title': entry.get('title', '제목 없음'),
                            'url': v_url,
                            'uploader': entry.get('uploader') or entry.get('channel') or '알 수 없음',
                            'video_count': entry.get('video_count'),
                        })
    except Exception as e:
        _log_to_file(f"🔍 [YouTube Playlist Search Error] {e}")

    return results


# [TAG: #@_search_youtube]
def _search_youtube(query: str) -> str:
    """[사양 유지용 래퍼] 기존 코드와의 호환성을 위해 유지합니다냥! 🐾"""
    results = _search_youtube_advanced(query, limit=1)
    if results:
        return f"유튜브 추천 링크: {results[0]['url']}"
    return "유튜브 검색에 실패했다냥 😿"


# [TAG: #@_cat_proactive_talk]
def _cat_proactive_talk(settings_ref, chat_id, token, force_trend=False, custom_system_prompt=None):
    # [V47.2] AI냥 활성화 체크 및 듀엣 모드 가드 [V60.0]
    if not settings_ref.data.get('cat_enabled', False): return
    if settings_ref.data.get('cat_persona_id_2'):
        # 듀엣 모드일 때는 선톡(Proactive Talk) 안 함 (침묵 시 팝콘 🍿 기능만 활성화)
        return

    try:
        # [V60.1] Snapshotting Persona & Context (isolated proxy)
        current_id = settings_ref.data.get('cat_persona_id', "")
        if not current_id: return

        # [V78.0] 퀴즈맨은 자동 선톡(노가리)을 하지 않습니다. 🧩🛡️
        if current_id == "quizman": return

        # Snapshotted isolated settings
        p_settings = CatSettingsProxy(settings_ref, {
            'cat_persona_id': current_id,
            'cat_history': settings_ref.data.get('cat_history', [])
        })
        agent = CatAgent(p_settings)

        # [NEW] 실시간 검색어 결합
        trends = _get_realtime_keywords()
        trend_str = f" (참고 트렌드: {', '.join(trends)})" if trends else ""

        if custom_system_prompt:
            # [V81.2] 외부에서 지정한 커스텀 프롬프트(예: 복귀 인사) 사용
            topic = custom_system_prompt
        elif current_id == "writer":
            topic = f"방금 나온 따끈따끈한 주식/경제/테마주 찌라시나 뉴스 요약 브리핑. 반드시 호탕한 과장님 톤으로 아재 개그를 섞어서 선톡!{trend_str}"
        elif current_id == "boss":
            topic = f"지금 막 들어온 국내외 최신/인기 뉴스 요약 및 깊이 있는 뉴스 인사이트(생각해볼 이슈) 브리핑. 신뢰감 있는 뉴스 앵커 톤으로 이전에 했던 말과 중복되지 않게 지적으로 선톡!{trend_str}"
        elif current_id == "newsbot":
            topic = "지금 가장 중요하고 핵심적인 정치/경제/IT 국내외 종합 뉴스 요약 브리핑. 반드시 치우치지 않고 객관적이고 신뢰감 있는 뉴스 앵커(로봇) 톤으로 정중하게 선톡!"
        elif current_id == "realtimebot":
            t_str = f"현재 대한민국 실시간 인기 검색어: {', '.join(trends)}" if trends else "현재 특별한 실시간 검색어가 없습니다."
            topic = f"[{t_str}] 이 검색어들을 바탕으로 현재 가장 이슈가 되고 있는 관련 뉴스들을 흥미롭고 발빠르게 요약 브리핑. 실시간 소식을 전하는 날쌘돌이 톤으로 선톡!"
        elif current_id == "kurzweil":
            topic = f"요즘 가장 핵심적인 AI/기술/경제 이슈 하나를 골라 '만약 이것이 이렇게 흘러간다면 1년 뒤·10년 뒤 우리 삶은 어떻게 바뀔까?'로 이어지는 레이 커즈와일식 지수적 예측을 선톡으로 건네줘. 그리고 가볍게 '원하면 이 시나리오를 턴제 미래 시뮬레이션으로 돌려볼 수 있다'는 안내도 한 줄 섞어줘.{trend_str}"
        else:
            # [V77.0] 대화 맥락(History)과 캐릭터 성격을 최우선으로 선톡 주제 선정 🧠💖
            history = settings_ref.data.get('cat_history', [])
            context_summary = ""
            if history:
                last_conv = [f"{'유저' if h['role']=='user' else '나'}: {h['content']}" for h in history[-3:]]
                context_summary = f"(최근 나눈 대화: {', '.join(last_conv)})"

            topic = (f"기존에 사용자와 나누었던 대화 내용{context_summary}의 흐름을 자연스럽게 이어가거나, "
                     f"너의 페르소나({current_id})의 개성과 취향이 듬뿍 담긴 창의적이고 감성적인 주제 하나를 네가 직접 정해봐. "
                     f"외부 검색어에 의존하기보다 너와 사용자 사이의 친밀함을 높이는 방향으로!")

            if trends and (force_trend or random.random() < 0.3): # 검색어 비중 축소 (0.5 -> 0.3)
                trend_kw = random.choice(trends)
                topic = f"{topic} (만약 대화가 막힌다면 요즘 이슈인 '{trend_kw}'를 너만의 방식으로 살짝 언급해봐.)"

        # 엔진별 선톡 프롬프트 (패널 규격이 엔진마다 다름) 🎭🔮
        engine = get_persona_engine(current_id)
        if engine == "future":
            prompt = (f"지침: [{topic}]\r\n\r\n"
                      f"위 지침을 바탕으로 사용자가 반가워할 '선톡'을 미래학자 톤으로 보내줘. "
                      f"캐릭터 설정(말투, 태도)을 100% 유지하고, 하단에 [FUTURE] 상태 패널까지 포함하여 아주 매력적으로 말을 걸어줘! 🐾")
        elif engine == "avt":
            prompt = (f"지침: [{topic}]\r\n\r\n"
                      f"위 지침을 바탕으로 사용자가 놀라거나 반가워할 '선톡'을 보내줘. "
                      f"캐릭터 설정을 100% 유지하며 1인칭 인과 지문과 대사를 섞어 서사하고, 하단에 [PANEL](AVT 규격)까지 포함해서 아주 매력적으로 말을 걸어줘! 🐾")
        elif engine == "nostalgia":
            prompt = (f"지침: [{topic}]\r\n\r\n"
                      f"위 지침을 바탕으로 사용자가 깜짝 놀라거나 반가워할 '선톡'을 보내줘. "
                      f"캐릭터 설정(말투, 태도)을 100% 유지하면서, 생생한 지문과 대사, 그리고 하단 [PANEL]까지 포함하여 아주 매력적으로 말을 걸어줘! 🐾")
        else:
            prompt = (f"지침: [{topic}]\r\n\r\n"
                      f"위 지침을 바탕으로 사용자가 깜짝 놀라거나 반가워할 '선톡'을 보내줘. "
                      f"캐릭터 설정(말투, 태도)을 100% 유지하면서 재미있고 매력적으로 말을 걸어줘! 🐾")

        # [Nostalgia/AVT/Future] 선톡 시에도 엔진별 패널 및 인터랙티브 버튼 생성 🎮✨
        raw_reply, parsed_data, turn_cnt = agent.get_response_by_engine(prompt, persona_id=current_id)
        if raw_reply:
            if not settings_ref.data.get('cat_enabled', False): return # [V76.5] 대기 중 OFF 되었으면 발송 취소 🛑

            p_name = PERSONA_DICT.get(current_id, current_id).split('(')[0].strip()
            tts_enabled = settings_ref.data.get('cat_tts_enabled', False)
            send_ai_persona_reply(p_name, raw_reply, chat_id=str(chat_id), tts=tts_enabled, parsed=parsed_data, persona_id=current_id, turn=turn_cnt)

            # 발송된 '선톡' 내용만 히스토리에 수동 기록
            append_persona_history(current_id, "assistant", raw_reply)

            # Proxy의 결과를 원본에 반영
            history = p_settings.data.get('cat_history', [])
            now_str = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            history.append({'role': 'assistant', 'content': raw_reply, 'time': now_str})
            if len(history) > 20: history = history[-20: ]

            settings_ref.data['cat_history'] = history
            settings_ref.save()

    except Exception as e:
        _log_to_file(f"[Proactive Error] {e}")


# [TAG: #@reset_cat_duel_timer]
def reset_cat_duel_timer(settings_ref, chat_id, token, is_first=True):
    """[V59.0] 유저 입력이 없을 때 60초(최초 30초) 뒤 봇들끼리 대화하도록 스케줄링 🍿"""
    global _cat_duel_timer
    if _cat_duel_timer is not None:
        _cat_duel_timer.cancel()

    # 듀엣 모드 + 자율 대화 모드가 켜져 있을 때만 작동
    if not settings_ref.data.get('cat_enabled', False) or not settings_ref.data.get('cat_persona_id_2'):
        return
    if not settings_ref.data.get('cat_duel_enabled', False):
        return

    delay = 30.0 if is_first else 60.0 # 최초 30초, 이후 60초 [V60.1]
    _cat_duel_timer = threading.Timer(delay, _execute_cat_duel_task, args=(settings_ref, chat_id, token))
    _cat_duel_timer.daemon = True
    _cat_duel_timer.start()

# [TAG: #@_execute_cat_duel_task]
def _execute_cat_duel_task(settings_ref, chat_id, token, is_intro=False):
    """[V63.0] 60초 침묵 시 봇들끼리 체계적인 주제로 티키타카 실행! 🍿✨"""
    try:
        if not settings_ref.data.get('cat_enabled', False): return
        cancel_cat_proactive_talk()

        p1_id = settings_ref.data.get('cat_persona_id', 'cat')
        p2_id = settings_ref.data.get('cat_persona_id_2')
        if not p2_id: return

        p1_name = PERSONA_DICT.get(p1_id, p1_id).split('(')[0].strip()
        p2_name = PERSONA_DICT.get(p2_id, p2_id).split('(')[0].strip()
        un = settings_ref.data.get('user_name', '주인님')

        # [V63.0] 대화 상태 관리 (Phase: 0=발현, 1=응답, 2=재응답, 3=마무리)
        phase = settings_ref.data.get('cat_duel_phase', 0)
        topics = settings_ref.data.get('cat_duel_topics', [])
        topic_idx = settings_ref.data.get('cat_duel_topic_idx', 0)

        # 0. 주제 생성 📝
        if not topics or topic_idx >= len(topics):
            print("  └─ [Duel] 🤖 주제 분석 및 생성 시작")
            p1_persona = settings_ref.data.get('cat_persona', '')
            p2_persona = settings_ref.data.get('cat_persona_2', '')
            temp_agent = CatAgent(settings_ref)
            topic_prompt = (f"당신은 {p1_name}이고 상대방은 {p2_name}입니다.\r\n"
                          f"당신의 페르소나: {p1_persona}\r\n"
                          f"상대방의 페르소나: {p2_persona}\r\n\r\n"
                          f"위 두 캐릭터의 성격과 관계를 분석해서, 둘이서 단둘이 있을 때 나눌법한 구체적이고 흥미로운 대화 주제 10가지를 리스트 형식으로 작성해줘. "
                          f"반드시 주제만 한 줄씩 10개 나열하고 다른 설명은 하지 마.")
            raw_topics = temp_agent.get_response(topic_prompt, skip_history=True)
            topics = [re.sub(r'^\d+[\.\)]\s*', '', t).strip() for t in str(raw_topics).splitlines() if t.strip() and any(c.isalpha() for c in t)]
            topics = topics[:10]
            if not topics: topics = ["요즘 날씨와 기분", "좋아하는 간식", "최근에 본 영상"]
            settings_ref.data['cat_duel_topics'] = topics
            settings_ref.data['cat_duel_topic_idx'] = 0
            settings_ref.data['cat_duel_phase'] = 0
            topic_idx, phase = 0, 0
            _log_to_file("🍿 [Duel] 신규 주제 10개 생성!")

        current_topic = topics[topic_idx] if topic_idx < len(topics) else "우리들의 이야기"

        # 1. 페이즈별 설정
        if phase == 0: # 화제발현 (AI1)
            speaker_id, speaker_name, other_name = p1_id, p1_name, p2_name
            prompt = f"상황: {un}님이 자리를 비운 사이, 당신({speaker_name})은 {other_name}와 단둘이 있습니다. 주제 '{current_topic}'에 대해 {other_name}에게 먼저 자연스럽게 말을 걸어주세요. 페르소나 몰입!"
            next_phase = 1
        elif phase == 1: # 응답 (AI2)
            speaker_id, speaker_name, other_name = p2_id, p2_name, p1_name
            prompt = f"상황: {other_name}가 방금 '{current_topic}'에 대해 말을 걸었습니다. 당신({speaker_name})은 상대방의 스타일에 맞춰 재치 있게 응답해주세요. 페르소나 유지!"
            next_phase = 2
        elif phase == 2: # 재응답 (AI1)
            speaker_id, speaker_name, other_name = p1_id, p1_name, p2_name
            prompt = f"상황: {other_name}와의 대화가 이어지고 있습니다. 주제 '{current_topic}'에 대해 당신({speaker_name})의 생각을 덧붙이거나 질문을 하며 대화를 깊게 이어가주세요."
            next_phase = 3
        else: # 마무리 (AI2)
            speaker_id, speaker_name, other_name = p2_id, p2_name, p1_name
            prompt = f"상황: 주제 '{current_topic}'에 대한 대화를 훈훈하게 마무리 짓는 멘트를 해주세요. 다음에는 다른 이야기를 하자는 암시를 줘도 좋습니다. 아주 짧게!"
            next_phase = 0

        is_p1 = (speaker_id == p1_id)
        s_proxy = CatSettingsProxy(settings_ref, {
            'cat_persona': settings_ref.data.get('cat_persona' if is_p1 else 'cat_persona_2', ''),
            'cat_persona_id': speaker_id,
            'cat_history': settings_ref.data.get('cat_history' if is_p1 else 'cat_history_2', [])
        })
        agent = CatAgent(s_proxy)

        try:
            TelegramBot.send_chat_action(token, chat_id, "typing")
            reply = agent.get_response(prompt)
            if not settings_ref.data.get('cat_duel_enabled', False): return

            settings_ref.data['cat_history' if is_p1 else 'cat_history_2'] = s_proxy.data.get('cat_history', [])

            # [V63.2] 통일된 응답 포맷팅 적용 🧼
            final_reply = format_cat_reply(speaker_name, reply)
            TelegramBot.send_message(token, chat_id, final_reply, reply_markup=standard_kb)

            # [V63.1] TTS 기능이 켜져있으면 음성 메시지 추가 전송 (본문만 읽어줌) 🎙️
            if settings_ref.data.get('cat_tts_enabled', False):
                voice = "ko-KR-SunHiNeural" if is_p1 else "ko-KR-InJoonNeural"
                telegram_send_voice(reply, voice_name=voice, chat_id=chat_id)

            settings_ref.data['cat_duel_phase'] = next_phase
            if next_phase == 0:
                settings_ref.data['cat_duel_topic_idx'] = topic_idx + 1
            settings_ref.save()

            # 대화 끝났으니 다시 예약 (사용자가 올 때까지 계속!)
            reset_cat_duel_timer(settings_ref, chat_id, token, is_first=False)

        except Exception as e:
            _log_to_file(f"⚠️ [Duel Cycle Error] {e}")

    except Exception as e_top:
        _log_to_file(f"⚠️ [Duel Top Error] {e_top}")

# ─────────────────────────────────────────────────────────────
# [V62.0] 정치 토론방 (Debate Mode) 핵심 로직 ⚖️🎙️
# ─────────────────────────────────────────────────────────────

# [TAG: #@reset_cat_debate_timer]
def reset_cat_debate_timer(settings_ref, chat_id, token, delay=20.0):
    """[V62.0] 토론 다음 턴 예약 (침묵 20초 후 실행) ⏱️"""
    global _cat_debate_timer, _debate_active
    if _cat_debate_timer is not None:
        try: _cat_debate_timer.cancel()
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

    if not _debate_active: return

    _cat_debate_timer = threading.Timer(delay, _execute_cat_debate_task, args=(settings_ref, chat_id, token))
    _cat_debate_timer.daemon = True
    _cat_debate_timer.start()

# [TAG: #@_execute_cat_debate_task]
def _execute_cat_debate_task(settings_ref, chat_id, token):
    """[V62.0] 토론 단계별 발언 실행 루틴 (기승전결 관리) 🎙️"""
    global _debate_active, _debate_topic, _debate_turn_count, _debate_phase, _debate_last_speaker, _debate_user_interjection

    try:
        if not _debate_active: return

        # 0. 주제 자동 생성 60초 체크 (최초 턴 한정)
        if not _debate_topic and _debate_turn_count == 0:
             _log_to_file("🔍 토론 주제 없음 -> 자동 선정 시도...")
             _debate_topic = _get_hot_debate_topic(settings_ref)
             telegram_send(f"<b>[⚖️ 시스템 알림]</b>\r\n60초간 주제가 입력되지 않아 오늘 가장 핫한 이슈로 토론을 시작합니다!\r\n\r\n📌 <b>주제: {_debate_topic}</b>", chat_id=chat_id)
             time.sleep(2)

        # 1. 종료 조건 체크
        if _debate_turn_count >= 12:
            _finish_debate(settings_ref, chat_id, token, reason="limit")
            return

        # 2. 페르소나 및 단계 결정 (기:1-3, 승:4-6, 전:7-9, 결:10-12)
        _debate_turn_count += 1
        if _debate_turn_count <= 3: _debate_phase = "기"
        elif _debate_turn_count <= 6: _debate_phase = "승"
        elif _debate_turn_count <= 9: _debate_phase = "전"
        else: _debate_phase = "결"

        # 화자 결정: 사회자 -> 진보 -> 보수 순환 (기승전결 각 1턴씩 총 12턴)
        rem = _debate_turn_count % 3
        if rem == 1:
            current_role = "moderator"
        elif rem == 2:
            current_role = "progressive"
        else:
            current_role = "conservative"

        _debate_last_speaker = current_role
        persona_emoji = "⚖️"
        if current_role == "progressive": persona_emoji = "💙"
        elif current_role == "conservative": persona_emoji = "❤️"

        # [V62.1] 토론자 명찰 가독성 개선 및 턴 정보 추가
        p_info = PERSONA_DICT.get(current_role, "사회자")
        persona_name = p_info.split(' ')[-1].replace('(','').replace(')','')

        own_turn = (_debate_turn_count - 1) // 3 + 1
        display_name = f"{persona_emoji} {persona_name} (🗣️본인 {own_turn}/4 | 전체 {_debate_turn_count}/12)"

        # 3. 응답 생성
        agent = CatAgent(settings_ref)

        reply = agent.get_debate_response(current_role, _debate_topic, _debate_turn_count, _debate_phase, _debate_user_interjection)
        _debate_user_interjection = "" # 한 번 반영 후 초기화

        if not _debate_active: return

        # [V63.2] 통일된 응답 포맷팅 적용 (토론용 상세 명찰 유지) 🧼
        final_msg = format_cat_reply(display_name, reply)
        telegram_send(final_msg, chat_id=chat_id)

        # [V63.1] TTS 기능이 켜져있으면 음성 메시지 추가 전송 🎙️
        if settings_ref.data.get('cat_tts_enabled', False):
            voice = "ko-KR-SunHiNeural"
            if current_role == "progressive": voice = "ko-KR-SunHiNeural"
            elif current_role == "conservative": voice = "ko-KR-InJoonNeural"
            else: voice = "ko-KR-InJoonNeural" # Moderator
            telegram_send_voice(reply, voice_name=voice, chat_id=chat_id)

        # 4. 다음 턴 예약 (30초 텀 유지)
        reset_cat_debate_timer(settings_ref, chat_id, token, delay=30.0)

    except Exception as e:
        _log_to_file(f"⚠️ [Debate Task Error] {e}")
        _debate_active = False

# [TAG: #@_finish_debate]
def _finish_debate(settings_ref, chat_id, token, reason="limit"):
    """[V62.0] 토론 공식 종료 및 사회자의 최종 요약 보고서 발송 📄⚖️"""
    global _debate_active, _debate_topic, _debate_turn_count, _cat_debate_timer

    _debate_active = False
    if _cat_debate_timer:
        try: _cat_debate_timer.cancel()
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

    try:
        # 종료 메시지 발송
        end_notice = "🏁 <b>토론이 최대 턴 수(12턴)에 도달하여 자동 종료됩니다.</b>" if reason == "limit" else "🏁 <b>유저 요청으로 토론을 종료합니다.</b>"
        telegram_send(end_notice, chat_id=chat_id)
        time.sleep(1)

        agent = CatAgent(settings_ref)
        # 최종 리포트 생성
        report = agent.get_debate_response("moderator", _debate_topic, _debate_turn_count, "결", user_interjection="토론이 종료되었습니다. 공정한 요약 리포트를 작성해주세요.")

        final_msg = f"<b>[⚖️ 사회자 요약 리포트]</b>\r\n\r\n{report}\r\n\r\n<i>토론이 모두 종료되었습니다. 참여해주신 모든 분들 감사합니다.</i>"
        telegram_send(final_msg, chat_id=chat_id, reply_markup=standard_kb)

        # [V63.3] 사회자 요약 리포트 TTS 추가 (사용자 요청) 🎙️⚖️
        if settings_ref.data.get('cat_tts_enabled', False):
            telegram_send_voice(report, voice_name="ko-KR-InJoonNeural", chat_id=chat_id)

        # 사용된 주제 저장
        used = settings_ref.data.get("cat_debate_used_topics", [])
        if _debate_topic and _debate_topic not in used:
            used.append(_debate_topic)
            settings_ref.data["cat_debate_used_topics"] = used
            settings_ref.save()

        # 상태 리셋
        _debate_topic = ""
        _debate_turn_count = 0

    except Exception as e:
        _log_to_file(f"⚠️ [Debate Finish Error] {e}")
        telegram_send("토론을 마무리하는 중 오류가 났다냥! 😿", chat_id=chat_id)

# [TAG: #@start_debate]
def start_debate(settings_ref, chat_id, token, topic=None):
    """[V62.0] 토론방 개설!! 🚀⚖️"""
    global _debate_active, _debate_topic, _debate_turn_count, _debate_phase, _debate_last_speaker, _cat_debate_timer

    # [V62.1] 기존 토론 타이머가 있다면 취소 (중복 실행 방지)
    if _cat_debate_timer:
        try: _cat_debate_timer.cancel()
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

    _debate_active = True
    _debate_topic = topic
    _debate_turn_count = 0
    _debate_phase = "기"
    _debate_last_speaker = ""

    # 기존 히스토리 초기화 (토론 집중을 위해)
    settings_ref.data['cat_history'] = []
    settings_ref.save()

    # [V62.4] 주제가 있으면 즉시 시작, 없으면 60초간 대기 (유저 입력 유도)
    if topic:
        _execute_cat_debate_task(settings_ref, chat_id, token)
    else:
        # [V76.1] 토론 시작 안내 및 주제 입력 유도 (즉각 반응 주도록 개선) ⚖️✨
        reply = "⚖️ <b>토론 인큐베이팅 모드 가동!</b>\r\n\r\n지금부터 <b>60초간</b> 토론하고 싶은 주제를 자유롭게 입력해줘! 👍\r\n\r\n💡 <b>아래 버튼에서 주제를 고르면 즉시 시작할 수 있어!</b> (선택이 없으면 60초 후 자동 매칭됨 🎬)"

        # [V76.3] 추천 주제 버튼 생성 및 전송 🎙️🔘
        # [TAG: #@_send_topic_buttons]
        def _send_topic_buttons():
            topics = _get_recommended_topics(settings_ref)
            buttons = []
            for i, t in enumerate(topics):
                # 글자수 제한 (버튼 가독성을 위해)
                btn_text = (t[:17] + "...") if len(t) > 20 else t
                buttons.append([{"text": f"📍 {btn_text}", "callback_data": f"cat_debate_set:{t[:40]}"}])

            TelegramBot.send_message(token, chat_id, reply, reply_markup={"inline_keyboard": buttons})

        threading.Thread(target=_send_topic_buttons, daemon=True).start()

        # 사회자 등판 전, 유저의 주제 입력을 60초간 기다림 ⏱️
        reset_cat_debate_timer(settings_ref, chat_id, token, delay=60.0)


