# [V34.0] 시각적 로딩 애니메이션 (사용자님 요청 실적 🚀)
class LoadingSpinner:
    # [TAG: #@__init___7]
    def __init__(self, message="🚀 로딩 중..."):
        self.message = message
        self.loading = False
        self.frames = ['⠋','⠙','⠹','⠸','⠼','⠴','⠦','⠧','⠇','⠏']

    # [TAG: #@_spin]
    def _spin(self):
        i = 0
        while self.loading:
            sys.stdout.write(f'\r   {self.message} {self.frames[i % len(self.frames)]}')
            sys.stdout.flush()
            time.sleep(0.08)
            i += 1

    # [TAG: #@__enter__]
    def __enter__(self):
        self.loading = True
        self.thread = threading.Thread(target=self._spin, daemon=True)
        self.thread.start()
        return self

    # [TAG: #@__exit__]
    def __exit__(self, exc_type, exc_val, exc_tb):
        self.loading = False
        time.sleep(0.12) # 루프의 time.sleep 보다 약간 길게 주어 정지 확인
        # 줄 청소 (ANSI 길이 고려)
        sys.stdout.write('\r' + ' ' * (_len_ansi(self.message) + 15) + '\r')
        sys.stdout.flush()

# [V34.0] 자막 지능형 분할 (긴 문장 가독성 개선 ✂️)
# [TAG: #@smart_split_text]
def smart_split_text(text: str, max_chars: int = 40) -> str:
    """한 줄이 너무 길 경우 문맥을 고려하여 줄바꿈(\r\n)을 삽입합니다."""
    if not text: return ""
    lines = text.split('\r\n')
    new_lines = []

    for line in lines:
        if _len_ansi(line) <= max_chars:
            new_lines.append(line)
            continue

        # 40자 이상이면 분할 시도
        current_line = ""
        words = line.split(' ')
        for word in words:
            if _len_ansi(current_line + " " + word) > max_chars:
                if current_line:
                    new_lines.append(current_line.strip())
                    current_line = word
                else:
                    new_lines.append(word)
                    current_line = ""
            else:
                current_line += (" " if current_line else "") + word
        if current_line:
            new_lines.append(current_line.strip())

    return '\r\n'.join(new_lines)

