# [TAG: #@_global_exception_handler]
def _global_exception_handler(exctype, value, tb):
    try:
        with open(_DEBUG_LOG_PATH, "a", encoding="utf-8", errors="replace") as f:
            f.write(f"\r\n[{datetime.now()}] [ERROR] Uncaught Exception:\r\n")
            traceback.print_exception(exctype, value, tb, file=f)
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")
    sys.__excepthook__(exctype, value, tb)

sys.excepthook = _global_exception_handler

