# [TAG: #@check_self_upgrade]
def check_self_upgrade():
    """[V16.0.2] 스스로 소스 코드를 읽어 버전이 변경되었는지 확인하고 재시작합니다."""
    try:
        current_file = os.path.abspath(__file__)
        if not os.path.exists(current_file): return
        with open(current_file, 'r', encoding='utf-8') as f:
            for line in f:
                if "WATCHDOG_VERSION =" in line:
                    disk_version = line.split("=")[1].strip().strip('"').strip("'")
                    if disk_version != WATCHDOG_VERSION:
                        _wd_log(f"🔄 워치독 새 버전 감지 ({disk_version})! 자가 재시작합니다.")
                        send_msg("🐕 <b>[워치독 업데이트]</b>\r\n\r\n어! 내꺼 워치독 소스 업데이트 됐다멍. 업데이트 했다멍. 🚀")
                        time.sleep(1.5)
                        global _watchdog_mutex_handle, _watchdog_lock_handle
                        if _watchdog_mutex_handle:
                            ctypes.windll.kernel32.CloseHandle(_watchdog_mutex_handle)
                            _watchdog_mutex_handle = None
                        if _watchdog_lock_handle:
                            _watchdog_lock_handle.close()
                            _watchdog_lock_handle = None
                        os.execv(sys.executable, [sys.executable] + sys.argv)
                    break 
    except Exception as e:
        _wd_log(f"❌ 자가 업데이트 체크 중 오류: {e}")

# [TAG: #@check_singleton]
def check_singleton():
    global _watchdog_mutex_handle, _watchdog_lock_handle
    try:
        mutex_name = "BinuWatchdog_Mutex"
        _watchdog_mutex_handle = ctypes.windll.kernel32.CreateMutexW(None, False, mutex_name)
        if ctypes.windll.kernel32.GetLastError() == 183:
            # [수정] 자가 잠금 방지를 위해 일단 핸들을 닫음
            ctypes.windll.kernel32.CloseHandle(_watchdog_mutex_handle)
            _watchdog_mutex_handle = None

            # [V19.1] 좀비 정리 후 깨끗하게 다시 시도 (지능형 재시도 루프 추가) 🔄✨
            # 윈도우 커널이 이전 프로세스의 뮤텍스 핸들을 정리할 시간을 벌어줍니다.
            for retry in range(10): 
                _watchdog_mutex_handle = ctypes.windll.kernel32.CreateMutexW(None, False, mutex_name)
                if ctypes.windll.kernel32.GetLastError() != 183:
                    break 
                ctypes.windll.kernel32.CloseHandle(_watchdog_mutex_handle)
                time.sleep(0.5)

            if ctypes.windll.kernel32.GetLastError() == 183:
                _wd_log("⚠️ 이미 실행 중 (Mutex Conflict)"); return False
        try:
            _watchdog_lock_handle = open(lock_file, 'a+')
            if os.name == 'nt':
                import msvcrt
                msvcrt.locking(_watchdog_lock_handle.fileno(), msvcrt.LK_NBLCK, 1)
        except Exception:
            _wd_log("⚠️ 이미 실행 중 (File Lock Conflict)")
            return False
        _wd_log("🐕 싱글톤 락 획득 성공"); return True
    except Exception as e: _wd_log(f"❌ 싱글톤 체크 실패: {e}"); return False

# [TAG: #@_wd_decrypt_setting]
def _wd_decrypt_setting(enc_value):
    if not enc_value: return ""
    try:
        import hashlib, base64
        from cryptography.fernet import Fernet
        user_seed = os.getlogin() if hasattr(os, 'getlogin') else os.environ.get('USERNAME', 'binu_master')
        key_seed = hashlib.sha256(user_seed.encode()).digest()
        fernet_key = base64.urlsafe_b64encode(key_seed)
        f = Fernet(fernet_key)
        return f.decrypt(enc_value.encode()).decode()
    except:
        return enc_value

# [TAG: #@load_config]
def load_config():
    try:
        data = _wd_get_settings()
        if data:
            token = _wd_decrypt_setting(data.get("telegram_token", ""))
            chat_id = _wd_decrypt_setting(data.get("telegram_chat_id", ""))
            user_name = data.get("user_name", "주인님")
            persona = data.get("cat_persona", "cat")
            update_watchdog_keyboard(persona)
            return token, chat_id, user_name
    except Exception as e:
        _wd_log(f"⚠️ [Silent Exception] {e}")
    return "", "", "주인님"


# [V16.2.7] 절전/깨우기 로직은 메인 앱(korea.srt.py)으로 통합되었습니다.
# 워치독에서는 더 이상 직접 시스템 전원을 제어하지 않습니다. 🐕🛡️

# [V16.2.4] dual_wake_and_sleep은 제거되고 _pc_sleep_wake로 통합되었습니다.
# ------------------------------------------

# [TAG: #@send_msg]
def send_msg(text, reply_markup=None):
    token, chat_id, _ = load_config()
    if not token or not chat_id: return
    try:
        url = f"https://api.telegram.org/bot{token}/sendMessage"
        safe_text = text
        if "<b>" in text or "<code>" in text or "<i>" in text:
            tags = ["b", "i", "code", "pre", "u", "s", "a"]
            tm = {}
            # [TAG: #@_h]
            def _h(m):
                mk = f"__TAG_{len(tm)}__"
                tm[mk] = m.group(0); return mk
            pat = r'</?(?:' + '|'.join(tags) + r')(?:\s+[^>]*?)?>'
            safe_text = re.sub(pat, _h, text, flags=re.IGNORECASE)
            safe_text = html.escape(safe_text)
            for mk, tg in tm.items(): safe_text = safe_text.replace(html.escape(mk), tg)
        else:
            safe_text = html.escape(text)
        payload = {"chat_id": chat_id, "text": safe_text, "parse_mode": "HTML", "reply_markup": reply_markup or standard_kb}
        for attempt in range(5):
            try:
                resp = requests.post(url, json=payload, timeout=10)
                if resp.status_code == 200: break
            except Exception as e:
                if attempt == 4:
                    _wd_log(f"⚠️ [Silent Exception] {e}")
            time.sleep(2.0)
    except Exception as e: _wd_log(f"❌ 메시지 전송 실패: {e}")

# [TAG: #@edit_msg_with_buttons]
def edit_msg_with_buttons(msg_id, text, buttons):
    token, chat_id, _ = load_config()
    if not token or not chat_id: return
    try:
        url = f"https://api.telegram.org/bot{token}/editMessageText"
        safe_text = text
        if "<b>" in text or "<code>" in text or "<i>" in text:
            tags = ["b", "i", "code", "pre", "u", "s", "a"]
            tm = {}
            # [TAG: #@_h_2]
            def _h(m):
                mk = f"__TAG_{len(tm)}__"
                tm[mk] = m.group(0); return mk
            pat = r'</?(?:' + '|'.join(tags) + r')(?:\s+[^>]*?)?>'
            safe_text = re.sub(pat, _h, text, flags=re.IGNORECASE)
            safe_text = html.escape(safe_text)
            for mk, tg in tm.items(): safe_text = safe_text.replace(html.escape(mk), tg)
        else:
            safe_text = html.escape(text)
        payload = {"chat_id": chat_id, "message_id": msg_id, "text": safe_text, "parse_mode": "HTML", "reply_markup": {"inline_keyboard": buttons}}
        for attempt in range(3):
            try:
                if requests.post(url, json=payload, timeout=10).status_code == 200: break
            except Exception as e:
                _wd_log(f"⚠️ [Silent Exception] {e}")
            time.sleep(1)
    except Exception as e: _wd_log(f"❌ 메시지 수정 실패: {e}")

# [TAG: #@answer_cb]
def answer_cb(cb_id, text, show_alert=False):
    token, _, _ = load_config()
    if not token: return
    try:
        url = f"https://api.telegram.org/bot{token}/answerCallbackQuery"
        requests.post(url, json={"callback_query_id": cb_id, "text": text, "show_alert": show_alert}, timeout=10)
    except Exception as e:
        _wd_log(f"⚠️ [Silent Exception] {e}")

# [TAG: #@is_main_running]
def is_main_running():
    try:
        # 1. 재시작 중 유예 시간 확인 (타임스탬프 기반: 최대 15초)
        bridge = _wd_load_bridge()
        restart_until = bridge.get('restarting_until', 0)
        if restart_until and time.time() < restart_until:
            return True
            
        # 2. 윈도우 OS 전역 뮤텍스 확인 (메인 프로세스 생존 여부 커널 레벨 확인)
        mutex_name = "Global\\BinuSubtitleGenerator_Mutex"
        h_mutex = ctypes.windll.kernel32.OpenMutexW(0x00100000, False, mutex_name)
        if h_mutex:
            ctypes.windll.kernel32.CloseHandle(h_mutex)
            return True
    except Exception as e:
        _wd_log(f"⚠️ [Silent Exception] {e}")
    return False

# [TAG: #@run_main]
def run_main(tray_mode=False, skip_check=False):
    if is_main_running(): return "🐕 🤔 <b>이미 앱이 실행 중이야!</b>"
    try:
        # 실행 전 브릿지 정리
        bridge = _wd_load_bridge()
        bridge['handoff_active'] = False
        bridge['restarting_until'] = 0
        _wd_save_bridge(bridge)
        py_exe = re.sub(r"pythonw\.exe$", "python.exe", sys.executable, flags=re.IGNORECASE)
        
        # [V16.4.1] Windows Terminal(wt.exe) 감지하여 일관된 터미널 환경 제공 🚀✨
        wt_path = shutil.which("wt.exe") or shutil.which("wt")
        if not wt_path:
            _local_wt = os.path.expandvars(r"%LOCALAPPDATA%\Microsoft\WindowsApps\wt.exe")
            if os.path.exists(_local_wt):
                wt_path = _local_wt
        
        extra_args = []
        if tray_mode: extra_args.append("--tray")
        if skip_check: extra_args.append("--skip-check")

        if wt_path and not tray_mode:
            # Windows Terminal로 최대화 및 --_wt_relaunched 플래그를 붙여서 직행! 🚀
            cmd = [wt_path, "--maximized", "--", py_exe, MAIN_SCRIPT, "--_wt_relaunched"] + extra_args
            subprocess.Popen(cmd, cwd=os.path.dirname(MAIN_SCRIPT))
            _wd_log(f"🚀 메인 앱 명령 실행 (Windows Terminal 직행: {wt_path})")
        else:
            args = [py_exe, MAIN_SCRIPT] + extra_args
            si = subprocess.STARTUPINFO()
            si.dwFlags |= subprocess.STARTF_USESHOWWINDOW
            si.wShowWindow = 3 if not tray_mode else 0 # SW_SHOWMAXIMIZED / SW_HIDE
            subprocess.Popen(args, creationflags=0, cwd=os.path.dirname(MAIN_SCRIPT), startupinfo=si)
            _wd_log("🚀 메인 앱 명령 실행 (표준 프로세스)")

        return "🐕 🚀 <b>메인 앱 가동 요청!</b>\r\n" + ("(트레이 모드 🟢)" if tray_mode else "")
    except Exception as e: return f"❌ 가동 실패: {e}"

# [TAG: #@stop_main]
def stop_main():
    if not is_main_running(): return "💤 <b>이미 앱이 꺼져 있어!</b>"
    try:
        script_name = os.path.basename(MAIN_SCRIPT)
        ps_cmd = f'$scriptName = "{script_name}"; $procs = Get-CimInstance Win32_Process | Where-Object {{ $_.CommandLine -like "*$scriptName*" }}; foreach ($p in $procs) {{ if ($p.Name -match "python|wt") {{ taskkill /F /T /PID $p.ProcessId /ErrorCode 0 > $null 2>&1; }} }}'
        subprocess.run(['powershell', '-Command', ps_cmd], capture_output=True, creationflags=0x08000000)
        _wd_log("🛑 메인 앱 및 터미널 강제 종료 시퀀스 완료")
        return "🐕 🛑 <b>메인 앱 및 터미널 종료 완료!</b>"
    except Exception as e: return f"❌ 종료 실패: {e}"

# [TAG: #@pc_reboot]
def pc_reboot():
    send_msg("🔄 <b>PC 시스템 재부팅을 시작합니다!</b>\r\n잠시 후 다시 만나요! 👋")
    time.sleep(1)
    os.system("shutdown /r /f /t 0")

