# [TAG: #@manage_watchdog_startup_shortcut]
def manage_watchdog_startup_shortcut(enable=True):
    """와치독을 윈도우 시작 프로그램(Startup) 폴더에 등록/해제"""
    try:
        if os.name != 'nt': return False, "Windows 전용 기능이야."

        # 1. 시작 프로그램 폴더 경로 확인 (PowerShell 이용)
        ps_get_startup = "[Console]::OutputEncoding = [System.Text.Encoding]::UTF8; (New-Object -ComObject Shell.Application).NameSpace(0x7).Self.Path"
        res = subprocess.run(['powershell', '-Command', ps_get_startup], capture_output=True)
        startup_dir = res.stdout.decode('utf-8', errors='replace').strip()
        if not startup_dir:
            startup_dir = os.path.join(os.environ.get('APPDATA', ''), r"Microsoft\Windows\Start Menu\Programs\Startup")

        shortcut_path = os.path.join(startup_dir, "Binu_Watchdog.lnk")

        if enable:
            watchdog_script = os.path.join(os.path.dirname(os.path.abspath(__file__)), "watchdog.py")
            if not os.path.exists(watchdog_script): return False, "와치독 스크립트가 없어."

            pyw_exe = sys.executable.replace("python.exe", "pythonw.exe")
            # PowerShell로 바로가기 생성 (WScript.Shell 이용)
            ps_create_lnk = f"$s = (New-Object -ComObject WScript.Shell).CreateShortcut('{shortcut_path}'); $s.TargetPath = '{pyw_exe}'; $s.Arguments = '\"{watchdog_script}\"'; $s.WorkingDirectory = '{os.path.dirname(watchdog_script)}'; $s.Description = 'Binu Watchdog Agent'; $s.Save()"
            subprocess.run(['powershell', '-Command', ps_create_lnk], capture_output=True)
            return True, shortcut_path
        else:
            if os.path.exists(shortcut_path):
                os.remove(shortcut_path)
            return True, None
    except Exception as e:
        return False, str(e)

# [TAG: #@manage_watchdog_interactive]
def manage_watchdog_interactive(settings):
    """와치독 스크립트 관리 인터랙티브 메뉴"""
    try:
        while True:
            clear_console()

            watchdog_script = os.path.join(os.path.dirname(os.path.abspath(__file__)), "watchdog.py")
            is_installed = os.path.exists(watchdog_script)
            is_running = _is_watchdog_running()
            is_always_on = settings.data.get("watchdog_always_on", False)

            status_str = f"{C.GREEN}🟢 실행 중{C.RESET}" if is_running else f"{C.DIM}⚫ 정지됨{C.RESET}"
            install_str = f"{C.GREEN}✅ 설치됨{C.RESET}" if is_installed else f"{C.DIM}❌ 미설치{C.RESET}"
            always_on_str = f"{C.GREEN}ON (자동 시작){C.RESET}" if is_always_on else f"{C.DIM}OFF (수동 시작){C.RESET}"

            _print_standard_menu_header("watchdog", settings, install=install_str, status=status_str, always_on=always_on_str)

            menu_items = [
                ("install", " 🐕 와치독 설치 / 갱신 (watchdog.py 생성)"),
                ("toggle_always", f" 🔄 와치독 상시 실행 (현재: {'🟢 ON' if is_always_on else '⚫ OFF'})"),
                ("_sep", 구분선()),
                ("start", " 🐕 와치독 실행 (백그라운드)"),
                ("stop", " 🐕 와치독 종료 (관리 중단)"),
                ("open_startup", " 📂 시작프로그램 폴더 열기"),
                ("uninstall", " 🐕 와치독 제거 (파일 삭제)"),
                ("back", " ❌ 이전 메뉴로 돌아가기")
            ]

            options = [item[1] for item in menu_items]
            choice_idx, _, *_ = _interactive_menu("🐕 Watchdog 관리", options, timeout=0, prefix="[ 1/1 ] ")
            if choice_idx < 0: # [수정] ESC 키 입력 시 메인 메뉴로 복구 ✨
                break

            choice = menu_items[choice_idx][0]

            if choice == "back": return True
            if choice == "_sep": continue

            if choice == "toggle_always":
                new_val = not is_always_on
                settings.data["watchdog_always_on"] = new_val
                settings.data.get("watchdog_always_on", False)
                settings.save()
                success, _ = manage_watchdog_startup_shortcut(new_val)
                if new_val:
                    if success: print(f" 📂 {C.DIM}시작 프로그램에 바로가기 추가 완료!{C.RESET}")
                    if not is_running: _start_watchdog_background(watchdog_script)
                else:
                    if success: print(f" 🗑️ {C.DIM}시작 프로그램에서 바로가기 제거 완료.{C.RESET}")
                time.sleep(1)
                continue

            if choice == "install":
                was_running = is_running
                if was_running: _stop_watchdog()

                if _update_watchdog_script(settings, silent=False):
                    if was_running:
                        print(f"\r\n ✨ {ctext('watchdog.py 업데이트 완료! 다시 실행할게. 👍', C.GREEN)}")
                        if _start_watchdog_background(watchdog_script):
                            print(f" 🚀 {ctext('와치독 재실행 성공! 🐕', C.GREEN)}")
                    else:
                        print(f"\r\n ✨ {ctext('watchdog.py 성공적으로 생성/갱신 완료! 👍', C.GREEN)}")

                    # [신규] 상시 실행 중이면 바로가기 경로 최신화
                    if settings.data.get("watchdog_always_on", False):
                        manage_watchdog_startup_shortcut(True)

                time.sleep(1.5)

            elif choice == "start":
                if not is_installed:
                    print(f"\r\n ⚠️ {ctext('먼저 와치독을 설치해줘!', C.YELLOW)}")
                else:
                    # [개선] 이미 실행 중이더라도 일단 다 끄고 새롭게 실행 (꼬임 방지)
                    if is_running:
                        print(f"\r\n 🔄 {ctext('현재 실행 중인 와치독을 재시작할게...', C.CYAN)}")

                    if _start_watchdog_background(watchdog_script):
                        print(f"\r\n 🚀 {ctext('와치독을 새롭게 실행했어! 이제 텔레그램 감시를 시작할게. 🐕', C.GREEN)}")
                    else:
                        print("\r\n ❌ 실행 실패!")
                time.sleep(2)

            elif choice == "stop":
                if not is_running:
                    print(f"\r\n ⚠️ {ctext('와치독이 실행 중이지 않아.', C.YELLOW)}")
                else:
                    if _stop_watchdog():
                        print(f"\r\n 🛑 {ctext('와치독을 안전하게 종료했어! 👋 이제 원격 가동이 안 돼! 💤', C.CYAN)}")
                    else:
                        print("\r\n ❌ 종료 실패!")
                time.sleep(2)

            elif choice == "uninstall":
                if is_installed:
                    if is_running:
                        print(f"\r\n ⚠️ {ctext('먼저 실행 중인 와치독을 종료해줘!', C.YELLOW)}")
                    else:
                        os.remove(watchdog_script)
                        # [신규] 제거 시 시작 프로그램 바로가기도 함께 삭제
                        manage_watchdog_startup_shortcut(False)
                        print(f"\r\n 🗑️ {ctext('와치독 스크립트를 삭제했어. 🗑️', C.GOLD)}")
                else:
                    print(f"\r\n ⚠️ {ctext('이미 삭제되었거나 파일이 없어.', C.YELLOW)}")
                time.sleep(1.5)

            elif choice == "open_startup":
                startup_dir = os.path.join(os.getenv('APPDATA', ''), 'Microsoft\\Windows\\Start Menu\\Programs\\Startup')
                if os.path.exists(startup_dir):
                    os.startfile(startup_dir)
                    ok(f"시작프로그램 폴더를 열었어! 📁\r\n{C.DIM}({startup_dir}){C.RESET}")
                else:
                    err("시작프로그램 폴더를 찾을 수 없어! ❌")
                pause()
    except UserAbortException:
        print(f"\r\n {C.YELLOW}⚠️ 작업을 중단하고 메인 메뉴로 돌아왔어냥!{C.RESET}")
        time.sleep(1)

