# [TAG: #@reg_get]
def reg_get(root, path, name, default=None):
    try:
        with winreg.OpenKey(root, path) as k:
            val, _ = winreg.QueryValueEx(k, name)
            return val
    except Exception:
        return default

# [TAG: #@reg_set]
def reg_set(root, path, name, value, reg_type):
    try:
        with winreg.CreateKeyEx(root, path, 0, winreg.KEY_ALL_ACCESS) as k:
            winreg.SetValueEx(k, name, 0, reg_type, value)
        return True
    except Exception as e:
        return str(e)

