# 자막 및 AI 처리 공통 유틸리티
# ==============================================================================
# [TAG: #@find_subtitle]
def find_subtitle(v_path):
    """비디오 파일명과 일치하는 핵심 3종(.ko.srt, .srt, .smi) 자막 파일 경로를 반환 🎯✨"""
    if not v_path: return None
    base = os.path.splitext(v_path)[0]
    for ext in ('.ko.srt', '.srt', '.smi'):
        p = base + ext
        if os.path.exists(p):
            return p
    return None

# [TAG: #@get_subtitle_mtime]
def get_subtitle_mtime(v_path, dir_entries=None):
    """[최신자막순 ⌛] 짝이 있는 자막 3종(.ko.srt/.srt/.smi) 중 가장 최근 mtime 반환 (자막 없으면 0.0) 🎬
    - find_subtitle()는 '우선순위 첫 매치'만 반환하므로, 구 버전 백업본(.ko.srt)이 남아있으면
      오래된 자막을 잡아버리는 문제가 있다. '최근에 번역한' 기준이 목적이므로 3종을 전부 max()로 집계한다.
      (콘솔 '⌛ 최신자막순'(_sort_mode='subtitle_time')과 100% 동일한 규격 🛡️)
    - dir_entries(.scandir 캐시)를 넘기면 추가 스캔 없이 dict 조회 + stat 1회로 끝난다. ⚡
    - 네트워크/가상 경로(gdrive://, url_group://)는 조회 실패 → 0 반환 = 정렬 시 최하단으로 내려간다. ✅
    """
    if not v_path:
        return 0.0
    try:
        base, _v_ext = os.path.splitext(v_path)
    except Exception:
        return 0.0
    if not base or base.endswith((':', '/', '\\')) or not os.path.isabs(base):
        # 가상/URL 경로는 로컬 자막과 짝지을 수 없다 → 최하단 처리
        return 0.0
    stem = os.path.basename(base)
    if not stem:
        return 0.0

    best = 0.0
    for s_ext in ('.ko.srt', '.srt', '.smi'):
        if dir_entries is not None and isinstance(dir_entries, dict):
            ent = dir_entries.get((stem + s_ext).lower())
            if ent is None:
                continue
            try:
                if not ent.is_file():
                    continue
                mt = float(ent.stat().st_mtime)
            except Exception:
                continue
        else:
            try:
                sub_p = base + s_ext
                if not os.path.exists(sub_p):
                    continue
                mt = float(os.path.getmtime(sub_p))
            except Exception:
                continue
        if mt > best:
            best = mt
    return best

# [TAG: #@find_audio]
def find_audio(v_path, dir_entries=None):
    """비디오 파일명과 일치하는 동일 이름의 오디오 파일(.mp3, .m4a, .wav 등) 경로를 반환 🎙️✨"""
    if not v_path: return None
    try:
        v_norm = os.path.normcase(os.path.abspath(v_path))
        base, v_ext = os.path.splitext(v_path)
        audio_exts = ('.mp3', '.m4a', '.wav', '.aac', '.flac', '.ogg')
        target_stem = os.path.splitext(os.path.basename(v_path))[0].strip().lower()

        # 1. 사전 전달된 dir_entries(캐시된 디렉토리 맵)가 있으면 0초 즉시 조회 ⚡
        if dir_entries is not None and isinstance(dir_entries, dict):
            for ext in audio_exts:
                cand_name = (target_stem + ext).lower()
                entry = dir_entries.get(cand_name)
                if entry and entry.is_file():
                    full_p = entry.path if hasattr(entry, 'path') else os.path.join(os.path.dirname(v_path), entry.name)
                    if os.path.normcase(os.path.abspath(full_p)) != v_norm:
                        return full_p
            return None

        # 2. 동일 디렉토리 직접 매칭 (가장 빠름)
        for ext in audio_exts:
            p = base + ext
            if os.path.exists(p) and os.path.normcase(os.path.abspath(p)) != v_norm:
                return p

        # 3. 특수문자/유니코드 정규화 대비 디렉토리 파일 스캔 폴백
        parent_dir = os.path.dirname(v_path)
        if os.path.isdir(parent_dir):
            with os.scandir(parent_dir) as it:
                for entry in it:
                    if entry.is_file():
                        e_stem, e_ext = os.path.splitext(entry.name)
                        if e_ext.lower() in audio_exts and e_stem.strip().lower() == target_stem:
                            full_p = entry.path
                            if os.path.normcase(os.path.abspath(full_p)) != v_norm:
                                return full_p
    except Exception:
        pass
    return None

# [TAG: #@get_api_keys] (#@sec_api)
def get_api_keys() -> List[str]:
    """[V146.0] API 키 및 상태 정보를 통합 관리하고 마이그레이션합니다. 🚀🛡️✨"""
    global API_KEYS, genai

    # [V16.3.3] 인스턴스별 격리된 설정 파일 경로 결정 🕵️‍♂️✨
    _target_settings = SETTINGS_FILE
    if '--secondary' in sys.argv:
        # [V142.5.4] 보조 인스턴스라면 settings_{PID}.json 경로를 우선 사용냥!
        _target_settings = SETTINGS_FILE.replace(".json", f"_{os.getpid()}.json")

    try: import google.generativeai as genai
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")

    # 1. 레거시 파일(api_keys.txt) 마이그레이션
    legacy_file = "api_keys.txt"
    if os.path.exists(legacy_file):
        try:
            with open(legacy_file, "r", encoding="utf-8") as f:
                legacy_lines = f.readlines()

            migrated_keys_raw = []
            for line in legacy_lines:
                k = line.strip()
                if k.startswith("AQ.AQ."): k = k[3:]
                if k.startswith("AIzaSyAIzaSy"): k = k[6:]
                if k.startswith("AIzaSy") or k.startswith("AQ."):
                    migrated_keys_raw.append(k)

            if migrated_keys_raw:
                current_settings = {}
                if os.path.exists(_target_settings):
                    try:
                        with open(_target_settings, "r", encoding="utf-8") as f:
                            current_settings = json.load(f)
                    except Exception as e:
                        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                        if "6" not in str(e):
                            _log_to_file(f"⚠️ [Silent Exception] {e}")

                if "api_keys" not in current_settings: current_settings["api_keys"] = []

                added_count = 0
                dt = current_settings.get("gemini_api_type")
                default_tier = "paid" if dt in ("paid", 1) else "free"

                for k_raw in migrated_keys_raw:
                    exists = False
                    for existing in current_settings["api_keys"]:
                        if (isinstance(existing, dict) and existing.get("key") == k_raw) or (isinstance(existing, str) and existing == k_raw):
                            exists = True; break
                    if not exists:
                        current_settings["api_keys"].append({"key": k_raw, "tier": default_tier, "status": "active", "blocked_until": 0})
                        added_count += 1

                if added_count > 0:
                    with open(_target_settings, "w", encoding="utf-8") as f:
                        json.dump(current_settings, f, ensure_ascii=False, indent=4)
                    _log_to_file(f"Migrated {added_count} keys from legacy file.")

                # [V16.3.3] 레거시 파일 삭제는 메인 인스턴스에서만 안전하게 수행냥! 🧹
                if '--secondary' not in sys.argv:
                    try:
                        from send2trash import send2trash
                        send2trash(legacy_file)
                    except:
                        if os.path.exists(legacy_file): os.remove(legacy_file)
        except Exception as e: _log_to_file(f"Legacy migration error: {e}")

    # 2. 환경 변수 확인 (우선순위 🛡️)
    env_keys = os.environ.get("GEMINI_API_KEYS")
    if env_keys:
        keys = [k.strip() for k in re.split(r'[,\s]+', env_keys) if k.strip()]
        if keys: return keys

    # 3. 데이터 구조 동기화 및 로드 (settings.json + binu_state.json 통합 로드) 🕵️‍♂️✨
    try:
        d = {}
        # [V147.235] AI냥 요청: 전역 settings 객체가 이미 활성화되어 있다면 해당 데이터를 즉시 참조냥! 🤝
        if 'settings' in globals() and globals()['settings'] and hasattr(globals()['settings'], 'data'):
            d = globals()['settings'].data # [V150.7] dict() 복사 제거냥! 참조를 그대로 써야 실시간 동기화가 돼냥! 🛡️✨

        else:
            # 직접 파일 로드 (fallback)
            if os.path.exists(SETTINGS_FILE):
                try:
                    with open(SETTINGS_FILE, "r", encoding="utf-8") as f: d.update(json.load(f))
                except: pass

            # [V147.236] AI냥 요청: api_keys는 규정된 성격에 따라 settings.json(Core)으로 복구됨. 🛡️
            # 다만, 기존에 temp/binu_state.json(State)에 잘못 저장된 키들을 유실 없이 마이그레이션하기 위해 체크함냥! 📦🔄
            state_file = os.path.join(os.getcwd(), "temp", "binu_state.json")
            if os.path.exists(state_file):
                try:
                    with open(state_file, "r", encoding="utf-8") as f:
                        s_data = json.load(f)
                        if "api_keys" in s_data:
                            d.update({"api_keys": s_data["api_keys"]})
                            _log_to_file("📦 [Migration] Found API keys in temp/binu_state.json. Moving back to settings.json logic...")
                except: pass

        # [V147.238] 런타임 타입 검증 강화 (사각지대 1, 2, 4 방어) 🛡️
        if not isinstance(d, dict): d = {}
        keys_data = d.get("api_keys", [])
        if not isinstance(keys_data, list): keys_data = []

        # [규칙] AGENTS.md §암호화 — ⚠️ 구멍 ⑤ : 위의 fallback 은 settings.json 을 **raw 로 읽어** 온다.
        #   settings 전역이 아직 없거나 죽었을 때 이 분기가 타는데, 복호화를 안 하면 암호문이 그대로 내려와
        #   · startswith("AIzaSy"/"AQ.") 검사(레거시 마이그레이션 L34902 등) 전부 실패
        #   · genai.configure(api_key=<암호문>) → Gemini 영구 마비
        # ☠️ 단, 이 함수는 **앱 시작 초기에 모듈 로드 완료 전에도 호출**된다.
        #   그래서 다른 모듈 함수(_wd_decrypt_setting 등)를 참조하면 NameError 로 죽고,
        #   조용히 암호문 키를 반환하는 최악의 경로로 빠진다.
        #   (실측 로그: "API key loading error: name '_wd_decrypt_setting' is not defined")
        #   → 따라서 아래는 **자기 완결적 중첩 함수**로 정의한다. (모듈 레벨 함수 참조 금지) 🛡️
        def _api_key_decrypt(v):
            if not v or not isinstance(v, str): return v
            try:
                import hashlib as _h, base64 as _b
                from cryptography.fernet import Fernet as _F2
                _us = os.getlogin() if hasattr(os, 'getlogin') else os.environ.get('USERNAME', 'binu_master')
                return _F2(_b.urlsafe_b64encode(_h.sha256(_us.encode()).digest())).decrypt(v.encode()).decode()
            except Exception:
                return v   # fail-safe: 평문/미암호문은 원문 반환

        _dec_keys_data = []
        for _ki in keys_data:
            if isinstance(_ki, dict):
                _ni = dict(_ki)
                _kv = _ni.get("key")
                if isinstance(_kv, str) and _kv:
                    _ni["key"] = _api_key_decrypt(_kv)
                _dec_keys_data.append(_ni)
            elif isinstance(_ki, str) and _ki:
                _dec_keys_data.append(_api_key_decrypt(_ki))
            else:
                _dec_keys_data.append(_ki)
        keys_data = _dec_keys_data


        cooldowns = d.get("api_key_cooldowns", {})
        if not isinstance(cooldowns, dict): cooldowns = {}

        dt = d.get("gemini_api_type")
        default_tier = "paid" if dt in ("paid", 1) else "free"

        needs_save = False
        final_list = []
        for key_item in keys_data:
            if isinstance(key_item, str):
                final_list.append({"key": key_item, "tier": default_tier, "status": "active", "blocked_until": cooldowns.get(key_item, 0), "usage_count": 0})
                needs_save = True
            elif isinstance(key_item, dict) and "key" in key_item:
                if "tier" not in key_item: key_item["tier"] = default_tier; needs_save = True
                if "status" not in key_item: key_item["status"] = "active"; needs_save = True
                if "blocked_until" not in key_item: key_item["blocked_until"] = 0; needs_save = True
                if "usage_count" not in key_item: key_item["usage_count"] = 0; needs_save = True
                final_list.append(key_item)

        # [V147.235] 로드된 키가 하나도 없으면 로그에 기록냥! (디버깅용) 🕵️‍♂️
        if not final_list:
            _log_to_file("⚠️ [get_api_keys] No keys found in either settings.json or binu_state.json.")
        else:
            _log_to_file(f"✅ [get_api_keys] Loaded {len(final_list)} API keys successfully.")

        if needs_save:
            # 주의: 여기서 직접 저장하면 락 충돌 위험이 있으므로, 가급적 전역 settings.save()를 유도하거나 최소한의 저장만 수행
            if 'settings' in globals() and globals()['settings'] and hasattr(globals()['settings'], 'save'):
                globals()['settings'].data["api_keys"] = final_list
                globals()['settings'].save()
            else:
                d["api_keys"] = final_list
                if "api_key_cooldowns" in d: del d["api_key_cooldowns"]
                with open(SETTINGS_FILE, "w", encoding="utf-8") as f:
                    json.dump(d, f, ensure_ascii=False, indent=4)

        ret = [k["key"] for k in final_list]

        # [V150.6] AI냥 요청: 인메모리 카운트 보존 및 지능적 동기화 (유실 방지) 🛡️📊
        global API_KEY_USAGE_COUNT
        file_counts = [k.get("usage_count", 0) for k in final_list]

        if not API_KEY_USAGE_COUNT or len(API_KEY_USAGE_COUNT) != len(file_counts):
            # 초기화 혹은 키 개수 변경 시 파일 데이터 우선
            API_KEY_USAGE_COUNT = file_counts
        else:
            # 인메모리와 파일 데이터 중 더 큰 값을 선택하여 갱신 (누적치 보존)
            for i in range(len(API_KEY_USAGE_COUNT)):
                if i < len(file_counts):
                    API_KEY_USAGE_COUNT[i] = max(API_KEY_USAGE_COUNT[i], file_counts[i])


        return ret
    except Exception as e:
        _log_to_file(f"API key loading error: {e}")
        try: return [k["key"] if isinstance(k, dict) else k for k in d.get("api_keys", [])]
        except: return []

# [TAG: #@rotate_api_key_global]
def rotate_api_key_global(current_idx: Optional[int] = None) -> bool:
    """[V146.0] 초통합 전역 API 키 로테이션 및 쿨다운 관리 🔐✨"""
    global API_KEY_IDX, API_KEYS
    with API_KEY_LOCK:
        if current_idx is not None and API_KEY_IDX != current_idx:
            return True

        # [V151.3] 전역 settings 객체를 직접 사용하여 파일 입출력 레이스 컨디션 방지 🛡️✨
        if 'settings' in globals() and globals()['settings']:
            settings_obj = globals()['settings']
            settings_data = settings_obj.data
        else:
            # Fallback (거의 발생 안 함)
            settings_data = {}
            if os.path.exists(SETTINGS_FILE):
                try:
                    with open(SETTINGS_FILE, "r", encoding="utf-8") as f: settings_data = json.load(f)
                except: pass

        settings_obj = globals().get('settings')


        API_KEYS = get_api_keys()
        if not API_KEYS: return False

        keys_list = settings_data.get("api_keys", [])
        cooldowns = settings_data.get("api_key_cooldowns", {})
        now = time.time()

        best_idx = (API_KEY_IDX + 1) % len(API_KEYS)
        found_available = False

        # [V146.6] 모든 키를 전수 조사해서 시간이 지난 건 미리 복구 🔓✨
        for item in keys_list:
            if isinstance(item, dict):
                b_until = item.get("blocked_until", 0)
                if b_until > 0 and now >= b_until:
                    item["status"] = "active"
                    item["blocked_until"] = 0

        # 실제 사용할 키 선택 (Least Loaded Balancing 적용) ⚖️
        sequential_429_count = 0
        available_indices = []
        for i in range(len(API_KEYS)):
            k_str = API_KEYS[i]
            blocked_until = 0
            for item in keys_list:
                if isinstance(item, dict) and item.get("key") == k_str:
                    blocked_until = item.get("blocked_until", 0); break
            if blocked_until == 0: blocked_until = cooldowns.get(k_str, 0)
            if now >= blocked_until: available_indices.append(i)

        if available_indices:
            sorted_candidates = sorted(available_indices, key=lambda idx: API_KEY_USAGE_COUNT[idx])
            for test_idx in sorted_candidates:
                k_str = API_KEYS[test_idx]
                try:
                    import google.generativeai as genai
                    genai.configure(api_key=k_str)
                    _v_model = genai.GenerativeModel('gemini-3.5-flash')
                    _v_model.generate_content("hi", generation_config={"max_output_tokens": 1})
                    best_idx = test_idx
                    found_available = True
                    API_KEY_USAGE_COUNT[best_idx] += 1
                    break
                except Exception as ve:
                    ve_str = str(ve).lower()
                    if any(x in ve_str for x in ["429", "quota", "exhausted", "capacity"]):
                        sequential_429_count += 1
                        if sequential_429_count >= 3:
                            _log_to_file("⚠️ [API 경보] 3회 연속 429 에러! 로테이션 중단.")
                            break
                        _set_api_key_cooldown_internal(k_str, minutes=60, settings_data=settings_data)
                        time.sleep(1.0)
                        continue
                    else: continue

        API_KEY_IDX = best_idx
        # 최종 선택된 키로 재설정
        try:
            import google.generativeai as genai
            genai.configure(api_key=API_KEYS[API_KEY_IDX])
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

        try:
            settings_data["api_key_idx"] = API_KEY_IDX
            # [V147.180] 사용량 데이터 동기화 📊✨
            if "api_keys" in settings_data:
                for i, item in enumerate(settings_data["api_keys"]):
                    if i < len(API_KEY_USAGE_COUNT):
                        item["usage_count"] = API_KEY_USAGE_COUNT[i]

            # [V151.3] 직접 파일 쓰기 대신 전역 settings.save() 호출하여 안전성 확보 🛡️✨
            if settings_obj and hasattr(settings_obj, 'save'):
                settings_obj.save()
            else:
                with open(SETTINGS_FILE, "w", encoding="utf-8") as f:
                    json.dump(settings_data, f, ensure_ascii=False, indent=4)
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")


        # [V146.2] 성공적으로 사용 가능한 키를 찾았는지 여부를 반환합니다냥! 🕵️‍♂️✨
        if not found_available:
            return False

        print(f"\r\n🔄 [API 로테이션] 성공 (Index: {API_KEY_IDX + 1}) ✨ 검증완료!")
        if os.name == 'nt':
            try:
                import winsound
                winsound.Beep(1000, 150)
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")
        return True

# [TAG: #@_set_api_key_cooldown_internal]
def _set_api_key_cooldown_internal(api_key_target: str, minutes: int = 60, settings_data: dict = None):
    """[V147.155] 락(Lock) 없이 쿨다운 데이터를 업데이트하는 내부 유틸리티 🛠️"""
    keys_list = settings_data.get("api_keys", [])
    found = False
    blocked_until_val = time.time() + (minutes * 60)

    for item in keys_list:
        if isinstance(item, dict) and item.get("key") == api_key_target:
            item["blocked_until"] = blocked_until_val
            if minutes >= 1440: item["status"] = "Daily Limit"
            elif minutes <= 5: item["status"] = "RPM Limit"
            else: item["status"] = "exhausted"
            found = True
            break

    if not found:
        # 레거시 호환
        cooldowns = settings_data.get("api_key_cooldowns", {})
        cooldowns[api_key_target] = blocked_until_val
        settings_data["api_key_cooldowns"] = cooldowns

API_EXHAUSTION_WAIT_LOCK = threading.Lock()

# [TAG: #@wait_for_api_exhaustion_recovery]
def wait_for_api_exhaustion_recovery(status_fn=None):
    """[V146.5] 모든 API 키 소진 시 사용자 입력을 기다립니다. (스레드 안전) 🛑⌨️"""
    with API_EXHAUSTION_WAIT_LOCK:
        # 먼저 현재 키 상태를 재확인 (다른 스레드가 이미 해결했을 수 있음)
        if rotate_api_key_global():
            return

        _msg = f"🚨 [차단] 모든 API 키 소진! ({_get_ai_key_label()})"
        if status_fn: status_fn(f"{_msg} 엔터:재시도 / q:중단")

        try:
            print(f"\r\n{_msg}")
            user_cmd = input(">> [엔터]를 누르면 재시도, [q]를 입력하면 중단을 시작합니다냥! : ").strip().lower()
            if user_cmd == 'q':
                _log_to_file("🛑 사용자가 중단을 요청했습니다냥! 작업을 종료합니다.")
                raise KeyboardInterrupt("User requested stop")
        except KeyboardInterrupt:
            raise # 메인 루프로 중단 신호 전달
        except Exception as ie:
            _log_to_file(f"⚠️ 입력 대기 중 오류 발생: {ie}")
            time.sleep(30)

# [TAG: #@select_next_gemini_key]
def select_next_gemini_key():
    """[V146.0] 라운드 로빈 로테이션을 전역 통합 로직으로 위임합니다. 🔄"""
    rotate_api_key_global()
    return API_KEYS[API_KEY_IDX] if API_KEYS else None

# [TAG: #@_get_ai_key_label]
def _get_ai_key_label():
    """[V146.1] 현재 사용 중인 API 키의 레이블을 반환합니다냥! (예: gemini.api.key-1) 🔑✨"""
    try:
        # 전역 변수 API_KEY_IDX 참조
        _idx = globals().get('API_KEY_IDX', 0)
        return f"gemini.api.key-{_idx + 1}"
    except:
        return "gemini.api.key-?"

# [TAG: #@ask_ai]
def ask_ai(prompt, system_prompt=None, model=None, return_raw=False, temp=0.2, max_tokens=8192, stream=False, status_fn=None, timeout=30):
    """
    [V146.0] 초통합 AI 호출 인터페이스 (Global Rotation 통합) ✨🤖
    - prompt: 텍스트 혹은 Gemini 멀티모달 리스트([file_obj, "prompt"])
    - model: GenerativeModel 객체 혹은 모델 이름(str)
    - return_raw: True일 경우 SDK Response 객체 반환 (AIAgent 호환용)
    - stream: True일 경우 Generator(Chunk 반복자) 반환
    - timeout: CLI 호출 시 응답 대기 제한 시간 ⏳
    """
    # 1. 모델 및 인자 정규화
    model_name_resolved = model or globals().get('_flask_shared_model')
    if not model_name_resolved or (isinstance(model_name_resolved, str) and model_name_resolved.lower() == 'auto'):
        model_name_resolved = 'gemini-3.5-flash' # [V19.98] 'auto' 모델인 경우 SDK API를 위해 기본 모델로 자동 전향냥! 🤖✨

    _model = model_name_resolved
    if isinstance(_model, str):
        try: _model = genai.GenerativeModel(model_name=_model)
        except: _model = None

    # 2. 시스템 프롬프트 결합
    full_contents = prompt
    if system_prompt:
        if isinstance(full_contents, list):
            full_contents.append(f"\r\n\r\n[SYSTEM]\r\n{system_prompt}")
        else:
            full_contents = f"[SYSTEM]\r\n{system_prompt}\r\n\r\n[PROMPT]\r\n{prompt}"

    # 3. [V205.0] agy CLI(SQLite WAL) 엔진 최우선 호출 🚀✨
    if not globals().get('_cli_failed', False) and not return_raw and not stream and not isinstance(prompt, list):
        try:
            prompt_for_cli = ""
            if system_prompt:
                prompt_for_cli = f"[SYSTEM]\r\n{system_prompt}\r\n\r\n"

            if isinstance(prompt, str):
                prompt_for_cli += prompt
            else:
                prompt_for_cli += str(prompt)

            if status_fn: status_fn("🚀 [agy CLI] 모드로 AI 작업 중... ✨")
            _cli_res = call_agy_cli_sqlite(prompt_for_cli, timeout=timeout)
            if _cli_res and not str(_cli_res).startswith("⚠️ [agy SQLite Error]") and not str(_cli_res).startswith("❌"):
                globals()['_cli_empty_count'] = 0
                return _cli_res
            else:
                _empty_cnt = globals().get('_cli_empty_count', 0) + 1
                globals()['_cli_empty_count'] = _empty_cnt
                _log_to_file(f"⚠️ [ask_ai] agy CLI 응답 이상 ({_empty_cnt}/3회) API(SDK)로 폴백합니다냥!")
                if _empty_cnt >= 3:
                    globals()['_cli_failed'] = True
                    _log_to_file("🚨 [agy CLI 이상 3회 연속] CLI 모드를 스킵하고 API 채널로 전환합니다냥! 🚀")
        except Exception as e:
            _log_to_file(f"⚠️ [ask_ai agy CLI 우선호출 실패] {e}")

    # [V19.99] AI냥 요청: CLI 실패 시 API(SDK) 전환 여부를 1회 한정 동의 구하기냥! 🛡️🌏
    if not return_raw and not stream and not isinstance(prompt, list):
        fallback_choice = globals().get('_api_fallback_choice')
        if fallback_choice == 'no':
            _log_to_file("🚫 [API 전환 차단] 사용자가 API 모드 전환을 거부하여 번역을 즉시 중단합니다냥!")
            return ""

        if fallback_choice is None:
            # [V90.3] 백그라운드(텔레그램 등) 스레드에서는 TUI 메뉴를 띄울 수 없으므로 자동 거부 🛡️
            if threading.get_ident() != _G_MAIN_THREAD_IDENT:
                _log_to_file("🚫 [API 전환 차단] 백그라운드 스레드에서는 API 전환 확인 메뉴를 띄울 수 없어 자동 거부합니다냥!")
                globals()['_api_fallback_choice'] = 'no'
                return ""

            # TUI 인터랙티브 메뉴를 통해 의사 타진냥!
            _log_to_file("🤔 CLI 실패 감지 -> 사용자에게 API(SDK) 전환 여부 확인창 팝업!")
            title = "⚠️ [CLI 번역 지연/실패] API(SDK) 모드로 전환하여 계속할까요냥? (최대한 API 사용 방지)"
            opts = [
                "1. 🚀 Yes! API 모드로 전환해서 번역을 끝까지 계속하기냥!",
                "2. ⏭️ No! API 키 사용을 원치 않으니 여기서 작업을 즉시 중단하기냥!"
            ]
            try:
                # _interactive_menu 호출 (TUI 메인 스레드 안전 가드)
                sel, _, *_ = _interactive_menu(title, opts, default_idx=0, timeout=0)
                if sel == 0:
                    globals()['_api_fallback_choice'] = 'yes'
                    _log_to_file("✅ [API 전환 동의] 사용자가 API(SDK) 사용을 승인하여 전환합니다냥! 🚀")
                else:
                    globals()['_api_fallback_choice'] = 'no'
                    _log_to_file("🚫 [API 전환 거부] 사용자가 API(SDK) 사용을 거절하여 작업을 중단합니다냥! 👋")
                    return ""
            except Exception as pe:
                _log_to_file(f"⚠️ [인터랙티브 메뉴 오류] {pe} -> 기본적으로 API 사용 차단냥!")
                globals()['_api_fallback_choice'] = 'no'
                return ""

    # 4. 재시도 및 키 로테이션 로직 (위험/대체 경로 - SDK)
    max_retries = 10
    for attempt in range(max_retries):
        try:
            if _model:
                with LLM_SEMAPHORE:
                    config = genai.types.GenerationConfig(temperature=temp, max_output_tokens=max_tokens)
                    response = _model.generate_content(full_contents, generation_config=config, stream=stream)

                if stream or return_raw:
                    # [V19.4] API 모드 사용 안내 📡
                    if status_fn: status_fn("📡 [Gemini API] 모드로 번역 중... ⏳")
                    try:
                        API_KEY_USAGE_COUNT[API_KEY_IDX] += 1
                        # [V150.6] 실시간 동기화: settings 객체에도 즉시 반영냥! 🛰️
                        if 'settings' in globals() and globals()['settings']:
                            _sk = globals()['settings'].data.get("api_keys", [])
                            if API_KEY_IDX < len(_sk):
                                _sk[API_KEY_IDX]["usage_count"] = API_KEY_USAGE_COUNT[API_KEY_IDX]
                    except Exception as e:
                        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                        if "6" not in str(e):
                            _log_to_file(f"⚠️ [Silent Exception] {e}")
                    return response


                # [V16.6.4] AI냥 요청: 고도화된 할루시네이션 정제 로직 적용 🛡️✨
                res_text = AIAgent.fix_ai_hallucination(response.text)
                if res_text:
                    # [V19.4] API 모드 사용 안내 📡
                    if status_fn: status_fn("📡 [Gemini API] 모드로 번역 중... ⏳")
                    try:
                        API_KEY_USAGE_COUNT[API_KEY_IDX] += 1
                        # [V150.6] 실시간 동기화: settings 객체에도 즉시 반영냥! 🛰️
                        if 'settings' in globals() and globals()['settings']:
                            _sk = globals()['settings'].data.get("api_keys", [])
                            if API_KEY_IDX < len(_sk):
                                _sk[API_KEY_IDX]["usage_count"] = API_KEY_USAGE_COUNT[API_KEY_IDX]
                    except Exception as e:
                        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                        if "6" not in str(e):
                            _log_to_file(f"⚠️ [Silent Exception] {e}")
                return res_text

            else:
                raise ValueError("No active AI model.")

        except Exception as e:
            _log_to_file(f"⚠️ [ask_ai SDK 오류 (시도 {attempt+1}/{max_retries})] {e}")
            err_str = str(e).lower()

            if "certificate_verify_failed" in err_str or "certificate verify failed" in err_str:
                _log_to_file("⚠️ [SSL/인증서 보안 우회] 순수 HTTP REST API로 번역 우회를 시도합니다냥! 🛡️")
                try:
                    import urllib.request, json
                    _cur_k = API_KEYS[API_KEY_IDX] if API_KEYS and API_KEY_IDX < len(API_KEYS) else None
                    if _cur_k and isinstance(full_contents, str) and not stream and not return_raw:
                        m_name = model_name_resolved.replace("models/", "")
                        url = f"https://generativelanguage.googleapis.com/v1beta/models/{m_name}:generateContent?key={_cur_k}"
                        payload = {"contents": [{"parts": [{"text": full_contents}]}]}
                        req = urllib.request.Request(url, method='POST')
                        req.add_header('Content-Type', 'application/json')
                        with urllib.request.urlopen(req, data=json.dumps(payload).encode('utf-8')) as res:
                            d = json.loads(res.read().decode('utf-8'))
                            res_text = d['candidates'][0]['content']['parts'][0]['text'].strip()
                            res_text = AIAgent.fix_ai_hallucination(res_text)
                            if status_fn: status_fn("📡 [Gemini API] (HTTP 우회) 모드로 번역 완료! ✨")
                            return res_text
                except Exception as ue:
                    _log_to_file(f"⚠️ [HTTP 우회 실패] {ue}")

            if any(x in err_str for x in ["api key not valid", "unauthenticated", "suspended", "permission denied"]):
                _log_to_file(f"🛑 [FATAL] AI 호출 중단 (인증 오류): {e}")
                break

            if any(x in err_str for x in ["403", "429", "quota", "exhausted"]):
                # [V146.7] 에러 메시지에 따라 스마트 쿨다운 설정 🧠
                cooldown_min = 60 # 기본 1시간

                if "minute" in err_str or "per minute" in err_str:
                    cooldown_min = 2  # RPM 제한은 금방 풀림 (2분)
                    _log_to_file(f"⏳ [RPM 제한] {_get_ai_key_label()} - 잠시 휴식 (2분)")
                elif "day" in err_str or "per day" in err_str or "daily" in err_str:
                    cooldown_min = 1440 # RPD 제한은 하루 (24시간)
                    _log_to_file(f"🛑 [일일 할당량 소진] {_get_ai_key_label()} - 24시간 휴식")
                else:
                    _log_to_file(f"⚠️ [할당량 초과] {_get_ai_key_label()} - 60분 휴식")

                _cur_key = API_KEYS[API_KEY_IDX] if API_KEYS and API_KEY_IDX < len(API_KEYS) else None
                if _cur_key: set_api_key_cooldown(_cur_key, minutes=cooldown_min)

                if not rotate_api_key_global(API_KEY_IDX):
                    # 모든 키가 막혔을 때의 예외 처리 🛑
                    wait_for_api_exhaustion_recovery(status_fn)
                else:
                    # 키가 성공적으로 바뀌었으면 상태 메시지 업데이트 ✨
                    if status_fn: status_fn(f"🔄 3. AI 키 교체 완료! ({_get_ai_key_label()})...")
                continue

            if attempt == max_retries - 1: break
            time.sleep(2)

    # 폴백은 이미 최상단에서 우선 처리했으므로 실패 시 빈 문자열 반환
    return "" if not return_raw else None

# [TAG: #@ask_gemini]
def ask_gemini(model, prompt):
    """[하위 호환용] 기존 코드가 ask_gemini를 호출할 경우 ask_ai로 브릿지 🌉"""
    return ask_ai(prompt, model=model)

# [TAG: #@parse_srt_block]
def parse_srt_block(block):
    """SRT 블록 문자열을 파싱하여 딕셔너리로 반환"""
    lines = block.strip().split('\r\n')
    if len(lines) < 2 or '-->' not in lines[1]:
        return None
    start_end = lines[1].split('-->')
    start_str = start_end[0].strip()
    end_str = start_end[1].strip()
    return {
        "index": lines[0].strip(),
        "start": start_str,
        "end": end_str,
        "start_sec": parse_srt_time(start_str),
        "end_sec": parse_srt_time(end_str),
        "text_lines": lines[2:]
    }

