# [TAG: #@_file_dav_stop_server]
def _file_dav_stop_server(settings=None):
    """독립 WebDAV 파일서버를 중지합니다."""
    global _file_dav_server_running, _file_dav_cheroot_server
    if _file_dav_cheroot_server:
        try:
            _file_dav_cheroot_server.stop()
        except Exception as e:
            _log_to_file(f"⚠️ [FileDav] 서버 종료 오류: {e}")
        _file_dav_cheroot_server = None
    
    # UPnP 포트 포워딩 해제 시도
    if settings:
        use_upnp = settings.data.get('file_webdav_use_upnp', False)
        port = int(settings.data.get('file_webdav_port', 8765))
        if use_upnp:
            print(f"  🔓 {C.BOLD}UPnP 포트 포워딩 해제 시도 중 (포트: {port})...{C.RESET}")
            try:
                global _upnp_mapped_ports, _upnp_instance, _upnp_mode
                if port in _upnp_mapped_ports:
                    _upnp_mapped_ports.remove(port)
                if _upnp_mode == "library" and _upnp_instance:
                    _upnp_instance.deleteportmapping(port, 'TCP')
                else:
                    _upnp_soap_request('DeletePortMapping', port)
                print(f"    - 포트 {port} 해제됨")
            except Exception as e:
                _log_to_file(f"⚠️ [FileDav] UPnP 해제 오류: {e}")

    # 정지 시 상태 저장
    if settings:
        settings.data['file_webdav_last_running_state'] = False
        settings.save()

    _file_dav_server_running = False
    print(f"\r\n ⚫ {ctext('WebDAV 파일서버를 종료했어!', C.GOLD)}")

# [TAG: #@_file_dav_generate_self_signed_cert]
def _file_dav_generate_self_signed_cert(cert_path, key_path):
    """자체 서명 SSL 인증서(Self-Signed Certificate)를 자동으로 생성합니다."""
    try:
        _auto_install("cryptography", "cryptography", "SSL 인증서 생성용")
        from cryptography import x509
        from cryptography.x509.oid import NameOID
        from cryptography.hazmat.primitives import hashes
        from cryptography.hazmat.primitives.asymmetric import rsa
        from cryptography.hazmat.primitives import serialization
        import datetime
        import ipaddress

        print("  🔑 자체 서명 SSL 보안 인증서를 자동 생성하는 중이야... (안전 접속용)")
        private_key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
        
        subject = issuer = x509.Name([
            x509.NameAttribute(NameOID.COUNTRY_NAME, "KR"),
            x509.NameAttribute(NameOID.STATE_OR_PROVINCE_NAME, "Seoul"),
            x509.NameAttribute(NameOID.ORGANIZATION_NAME, "Binu WebDAV File Server"),
            x509.NameAttribute(NameOID.COMMON_NAME, "127.0.0.1"),
        ])
        
        cert = x509.CertificateBuilder().subject_name(
            subject
        ).issuer_name(
            issuer
        ).public_key(
            private_key.public_key()
        ).serial_number(
            x509.random_serial_number()
        ).not_valid_before(
            datetime.datetime.utcnow() - datetime.timedelta(days=1)
        ).not_valid_after(
            datetime.datetime.utcnow() + datetime.timedelta(days=3650)  # 10년 유효
        ).add_extension(
            x509.SubjectAlternativeName([
                x509.IPAddress(ipaddress.IPv4Address("127.0.0.1")),
                x509.DNSName("localhost")
            ]),
            critical=False,
        ).sign(private_key, hashes.SHA256())

        # temp 디렉토리 유무 체크 및 자동 생성
        temp_dir = os.path.dirname(cert_path)
        os.makedirs(temp_dir, exist_ok=True)

        with open(key_path, "wb") as f:
            f.write(private_key.private_bytes(
                encoding=serialization.Encoding.PEM,
                format=serialization.PrivateFormat.TraditionalOpenSSL,
                encryption_algorithm=serialization.NoEncryption()
            ))
            
        with open(cert_path, "wb") as f:
            f.write(cert.public_bytes(serialization.Encoding.PEM))
            
        print("  ✅ SSL 보안 인증서 생성 완료!")
        return True
    except Exception as e:
        _log_to_file(f"❌ [FileDav] SSL 인증서 자동 생성 실패: {e}")
        return False

# [TAG: #@_file_dav_get_users]
def _file_dav_get_users(settings):
    """WebDAV 사용자 계정 목록을 가져오며 구버전 단일 계정 설정을 자동 마이그레이션합니다."""
    users = settings.data.get('file_webdav_users')
    if users is None:
        # 구버전 단일 계정 데이터 자동 마이그레이션
        old_id = str(settings.data.get('file_webdav_id', 'admin')).strip() or 'admin'
        old_pw = str(settings.data.get('file_webdav_pw', ''))
        users = [{
            "id": old_id,
            "pw": old_pw,
            "folders": ["*"],  # 기본 전체 공유 허용
            "readonly": None   # None: 각 폴더의 기본 읽기/쓰기 설정 따름
        }]
        settings.data['file_webdav_users'] = users
        settings.save()
    elif not users:
        # 빈 리스트인 경우 기본 admin 생성
        users = [{
            "id": "admin",
            "pw": "",
            "folders": ["*"],
            "readonly": None
        }]
        settings.data['file_webdav_users'] = users
        settings.save()
    return users

# [TAG: #@_file_dav_save_users]
def _file_dav_save_users(settings, users):
    """WebDAV 사용자 계정 목록을 저장하고 첫 번째 계정을 기본 ID/PW로 동기화합니다."""
    settings.data['file_webdav_users'] = users
    if users:
        settings.data['file_webdav_id'] = users[0].get('id', 'admin')
        settings.data['file_webdav_pw'] = users[0].get('pw', '')
    settings.save()

# [TAG: #@_file_dav_user_folder_toggle]
def _file_dav_user_folder_toggle(settings, user):
    """계정별 공유 폴더 접근 권한(선택/해제) 토글 메뉴."""
    R = C.RESET
    while True:
        folders = settings.data.get('file_webdav_folders', [])
        if not folders:
            err("등록된 공유 폴더가 없어냥! 먼저 공유 폴더를 추가해줘.")
            pause(sec=1.5)
            return

        u_folders = user.get('folders', ['*'])
        is_all = '*' in u_folders

        print(f"\r\n {C.PURPLE}╔{'═'*60}{R}")
        print(f" {C.PURPLE}║{R}  👤 계정: {C.BOLD}{C.CYAN}{user.get('id')}{R} 의 {C.GOLD}공유 폴더 접근 범위 설정{R}")
        print(f" {C.PURPLE}╟{'─'*60}{R}")
        print(f" {C.PURPLE}║{R}  💡 번호를 눌러 폴더별 접근 권한을 {C.GREEN}[허용]{R} ↔ {C.RED}[차단]{R} 토글할 수 있어냥!")
        print(f" {C.PURPLE}╚{'═'*60}{R}\r\n")

        options = []
        for f in folders:
            fname = f.get('name', '').strip('/')
            is_virt = f.get('is_virtual', False) or ('paths' in f)
            ro = f.get('readonly', True)
            ro_label = "🔒읽기전용" if ro else "✏️읽기쓰기"
            
            # 현재 사용자가 이 폴더에 접근 가능한지 체크
            has_access = is_all or (fname in u_folders)
            status_icon = f"{C.BOLD}{C.GREEN}[✅ 접근허용]{R}" if has_access else f"{C.DIM}{C.RED}[❌ 접근차단]{R}"
            
            if is_virt:
                v_paths = [p for p in f.get('paths', []) if isinstance(p, str) and os.path.isdir(p)]
                valid_icon = "🔮" if v_paths else "⚠️(경로없음)"
                desc = f"가상 병합 ({len(v_paths)}개 폴더)"
                options.append(f" {status_icon} {valid_icon} /{fname}  →  [{desc}] [{ro_label}]")
            else:
                fpath = f.get('path', '')
                valid_icon = "📁" if os.path.isdir(fpath) else "⚠️(경로없음)"
                options.append(f" {status_icon} {valid_icon} /{fname}  →  {fpath} [{ro_label}]")

        div_idx = len(options)
        options += [
            구분선(),
            " 🟢 모든 폴더 전체 허용 (ALL)",
            " 🔴 모든 폴더 전체 차단 (NONE)",
            " 💾 설정 완료 (돌아가기)"
        ]

        all_idx = div_idx + 1
        none_idx = div_idx + 2
        done_idx = div_idx + 3

        sel = menu(f"📁 [{user.get('id')}] 공유 폴더 접근 권한 토글", options)

        if sel is None or sel == done_idx or (sel is not None and sel > done_idx):
            break
        elif sel == all_idx:
            user['folders'] = ['*']
            users = _file_dav_get_users(settings)
            _file_dav_save_users(settings, users)
            ok(f"[{user.get('id')}] 계정: 모든 폴더 전체 접근 허용 완료!")
            _notify_restart_if_running()
            pause(sec=0.8)
        elif sel == none_idx:
            user['folders'] = []
            users = _file_dav_get_users(settings)
            _file_dav_save_users(settings, users)
            ok(f"[{user.get('id')}] 계정: 모든 폴더 접근 차단 완료!")
            _notify_restart_if_running()
            pause(sec=0.8)
        elif sel < len(folders):
            target_folder = folders[sel]
            target_name = target_folder.get('name', '').strip('/')
            
            if is_all:
                # 기존에 전체 허용(*)이었으면 target_name만 끈 나머지 목록으로 구체화
                current_set = set(f.get('name', '').strip('/') for f in folders)
                current_set.discard(target_name)
                user['folders'] = list(current_set)
                toggled_state = False
            else:
                current_set = set(u_folders)
                if target_name in current_set:
                    current_set.remove(target_name)
                    toggled_state = False
                else:
                    current_set.add(target_name)
                    toggled_state = True
                user['folders'] = list(current_set)

            users = _file_dav_get_users(settings)
            _file_dav_save_users(settings, users)

            state_msg = f"{C.GREEN}접근 허용{R}" if toggled_state else f"{C.RED}접근 차단{R}"
            ok(f"[{user.get('id')}] 계정의 /{target_name} 권한을 {state_msg} (으)로 변경했어냥!")
            _notify_restart_if_running()
            pause(sec=0.6)

# [TAG: #@_file_dav_manage_users]
def _file_dav_manage_users(settings):
    """WebDAV 멀티 계정 관리 서브메뉴."""
    R = C.RESET
    while True:
        users = _file_dav_get_users(settings)
        folders = settings.data.get('file_webdav_folders', [])

        options = []
        for i, u in enumerate(users):
            uid = u.get('id', 'admin')
            upw = u.get('pw', '')
            pw_info = "🔑비번있음" if upw else "🔓비번없음"
            
            u_folders = u.get('folders', ['*'])
            if '*' in u_folders:
                folder_info = f"📁 전체 접근 ({len(folders)}개 폴더)"
            elif not u_folders:
                folder_info = "📁 접근 폴더 없음 (0개) ⚠️"
            else:
                valid_cnt = sum(1 for f in folders if f.get('name', '').strip('/') in u_folders)
                folder_info = f"📁 {valid_cnt}개 폴더 접근 허용"
            
            ro_policy = u.get('readonly')
            ro_str = " [🔒읽기전용]" if ro_policy is True else (" [✏️읽기쓰기]" if ro_policy is False else "")
            
            options.append(f" 👤 {uid:<12} [{pw_info}]  {folder_info}{ro_str}")

        div_idx = len(options)
        options += [구분선(), " ➕ 새 계정 추가", " ❌ 이전 메뉴로 돌아가기"]

        add_idx = div_idx + 1
        back_idx = div_idx + 2

        sel = menu("👥 WebDAV 멀티 계정 및 폴더 권한 관리", options)

        if sel is None or sel == back_idx or (sel is not None and sel > back_idx):
            break
        elif sel == add_idx:
            # 새 계정 추가
            print(f"\r\n 👤 {C.CYAN}새로 생성할 계정 아이디(ID)를 입력해줘:{R}")
            new_id = input("   아이디> ").strip()
            if not new_id:
                err("아이디를 입력하지 않았어냥!")
                pause()
                continue

            # 중복 체크
            if any(u.get('id', '').lower() == new_id.lower() for u in users):
                err(f"'{new_id}' 아이디는 이미 등록되어 있어냥!")
                pause()
                continue

            print(f"\r\n 🔑 {C.CYAN}비밀번호를 입력해줘 (엔터만 치면 비밀번호 없음):{R}")
            new_pw = input("   비밀번호> ").strip()

            # 접근 범위 초기 선택
            scope_sel = menu(f"📁 [{new_id}] 계정의 초기 공유 폴더 접근 범위", [
                " 🟢 모든 공유 폴더 전체 허용 (기본)",
                " 🔍 폴더별로 직접 선택/지정하기",
                " ❌ 취소"
            ])
            if scope_sel is None or scope_sel == 2:
                continue

            new_user = {
                "id": new_id,
                "pw": new_pw,
                "folders": ["*"] if scope_sel == 0 else [],
                "readonly": None
            }
            users.append(new_user)
            _file_dav_save_users(settings, users)
            ok(f"새 계정 '{new_id}' 추가 완료!")

            if scope_sel == 1:
                _file_dav_user_folder_toggle(settings, new_user)
            else:
                _notify_restart_if_running()
                pause(sec=0.8)

        elif sel < len(users):
            # 특정 계정 선택 -> 상세 설정 메뉴
            u = users[sel]
            while True:
                uid = u.get('id', 'admin')
                upw = u.get('pw', '')
                pw_display = ('*' * len(upw)) if upw else '(없음 - 비번 미사용)'
                u_folders = u.get('folders', ['*'])
                if '*' in u_folders:
                    folder_summary = f"전체 접근 허용 ({len(folders)}개)"
                elif not u_folders:
                    folder_summary = "접근 허용 폴더 없음 (0개) ⚠️"
                else:
                    folder_summary = f"{', '.join(u_folders[:3])}{' 외 ' + str(len(u_folders)-3) + '개' if len(u_folders) > 3 else ''} (총 {len(u_folders)}개)"

                ro_val = u.get('readonly')
                ro_mode_str = "🔒 강제 읽기 전용" if ro_val is True else ("✏️ 강제 읽기+쓰기" if ro_val is False else "⚙️ 폴더 자체 권한 따름 (기본)")

                user_options = [
                    f" 📁 공유 폴더 접근 범위 설정 (선택/해제)  [현재: {folder_summary}]",
                    f" 🔑 비밀번호 변경  [현재: {pw_display}]",
                    f" 👤 아이디 변경  [현재: {uid}]",
                    f" 🔒 계정 쓰기 정책 변경  [현재: {ro_mode_str}]",
                    " 🗑️ 이 계정 삭제",
                    " ❌ 이전 메뉴로 돌아가기"
                ]

                user_sel = menu(f"⚙️ [{uid}] 계정 상세 설정", user_options)

                if user_sel is None or user_sel == 5:
                    break
                elif user_sel == 0:
                    # 공유 폴더 접근 범위 설정 토글
                    _file_dav_user_folder_toggle(settings, u)
                elif user_sel == 1:
                    # 비밀번호 변경
                    print(f"\r\n 🔑 {C.CYAN}[{uid}] 새 비밀번호를 입력해줘 (엔터만 치면 비밀번호 없음):{R}")
                    val = input("   비밀번호> ").strip()
                    u['pw'] = val
                    _file_dav_save_users(settings, users)
                    ok("비밀번호를 변경했어냥!" if val else "비밀번호를 제거했어냥!")
                    _notify_restart_if_running()
                    pause(sec=0.8)
                elif user_sel == 2:
                    # 아이디 변경
                    print(f"\r\n 👤 {C.CYAN}[{uid}] 새 아이디를 입력해줘:{R}")
                    val = input("   아이디> ").strip()
                    if not val:
                        err("아이디를 비워둘 수 없어냥!")
                        pause()
                        continue
                    if any(other is not u and other.get('id', '').lower() == val.lower() for other in users):
                        err(f"'{val}' 아이디는 이미 다른 계정에서 사용 중이야냥!")
                        pause()
                        continue
                    old_id = uid
                    u['id'] = val
                    _file_dav_save_users(settings, users)
                    ok(f"아이디를 '{old_id}' 에서 '{val}' (으)로 변경했어냥!")
                    _notify_restart_if_running()
                    pause(sec=0.8)
                elif user_sel == 3:
                    # 읽기/쓰기 정책 변경
                    p_sel = menu(f"🔒 [{uid}] 계정 쓰기 권한 정책", [
                        " ⚙️ 폴더 자체 권한 따름 (기본값)",
                        " 🔒 강제 읽기 전용 (이 계정은 모든 폴더 다운로드만 가능)",
                        " ✏️ 강제 읽기+쓰기 (이 계정은 접근 폴더에 업로드/삭제 가능)",
                        " ❌ 취소"
                    ])
                    if p_sel == 0:
                        u['readonly'] = None
                    elif p_sel == 1:
                        u['readonly'] = True
                    elif p_sel == 2:
                        u['readonly'] = False
                    else:
                        continue
                    _file_dav_save_users(settings, users)
                    ok(f"[{uid}] 쓰기 권한 정책을 저장했어냥!")
                    _notify_restart_if_running()
                    pause(sec=0.8)
                elif user_sel == 4:
                    # 계정 삭제
                    if len(users) <= 1:
                        err("계정이 1개뿐이라 삭제할 수 없어! 최소 1개의 계정은 필요해냥.")
                        pause(sec=1.5)
                        continue
                    confirm = menu(f"🗑️ 정말 '{uid}' 계정을 삭제할까냥?", [
                        " 🗑️ 예, 삭제합니다",
                        " ❌ 취소"
                    ])
                    if confirm == 0:
                        users.remove(u)
                        _file_dav_save_users(settings, users)
                        ok(f"'{uid}' 계정을 삭제했어냥!")
                        _notify_restart_if_running()
                        pause(sec=0.8)
                        break

# [TAG: #@_file_dav_start_server]
def _file_dav_start_server(settings, is_bg: bool = False):
    """독립 WebDAV 파일서버를 시작합니다 (멀티 계정 및 계정별 폴더 격리 지원)."""
    global _file_dav_server_running, _file_dav_server_thread, _file_dav_cheroot_server
    R = C.RESET

    if _file_dav_server_running:
        print(f"\r\n ⚠️ {ctext('이미 실행 중이야!', C.YELLOW)}")
        return False

    port = int(settings.data.get('file_webdav_port', 8765))
    folders = settings.data.get('file_webdav_folders', [])
    users = _file_dav_get_users(settings)

    # HTTPS(SSL) 및 프로토콜 변수를 상단에서 일괄 초기화
    use_ssl = settings.data.get('file_webdav_use_ssl', False)
    proto = "https" if use_ssl else "http"
    cert_path = os.path.join(BASE_DIR, "temp", "file_dav_cert.pem")
    key_path = os.path.join(BASE_DIR, "temp", "file_dav_key.pem")

    # 소켓 바인딩 오류 방지
    if _is_port_in_use(port):
        print(f"\r\n ❌ {ctext('WebDAV 포트(' + str(port) + ')가 이미 사용 중(점유)인 상태야! 이전 서버가 아직 완전히 꺼지지 않았거나 다른 프로그램이 쓰고 있어.', C.RED)}")
        return False

    if not folders:
        print(f"\r\n ❌ {ctext('공유 폴더가 하나도 등록되지 않았어! 폴더를 먼저 추가해줘.', C.RED)}")
        return False

    _auto_install("wsgidav", "wsgidav", "WebDAV 파일서버")
    _auto_install("cheroot", "cheroot", "WebDAV 구동용 웹서버")

    try:
        import stat
        from wsgidav import util
        from wsgidav.wsgidav_app import WsgiDAVApp
        from wsgidav.fs_dav_provider import FilesystemProvider, FileResource, BUFFER_SIZE
        from wsgidav.dav_provider import DAVProvider, DAVCollection, DAVNonCollection
        from wsgidav.dc.base_dc import BaseDomainController

        # [V180.1] 물리 파일 리소스 스트리밍 추적 안전 래핑 🛡️
        if not hasattr(FileResource, '_trackable_patched'):
            _orig_file_resource_get_content = FileResource.get_content
            def _trackable_file_resource_get_content(self):
                try:
                    fp = getattr(self, '_file_path', None)
                    if fp:
                        _trigger_webdav_play_event(fp, "WebDAV")
                except: pass
                return _orig_file_resource_get_content(self)
            FileResource.get_content = _trackable_file_resource_get_content
            FileResource._trackable_patched = True

        import re as _dav_re
        import unicodedata as _dav_unicodedata

        def _dav_natural_key(text):
            """[V180.7] 자연수 정렬 키 (Ep1 -> Ep2 -> Ep10 순서 보장 🔢✨)"""
            return [int(c) if c.isdigit() else c.lower() for c in _dav_re.split(r'(\d+)', str(text))]

        _DAV_MIME_EXTS = {
            '.mp4': 'video/mp4', '.mkv': 'video/x-matroska', '.avi': 'video/x-msvideo',
            '.mov': 'video/quicktime', '.wmv': 'video/x-ms-wmv', '.flv': 'video/x-flv',
            '.ts': 'video/mp2t', '.webm': 'video/webm', '.m4v': 'video/x-m4v',
            '.mp3': 'audio/mpeg', '.flac': 'audio/flac', '.wav': 'audio/wav',
            '.m4a': 'audio/mp4', '.aac': 'audio/aac', '.ogg': 'audio/ogg',
            '.srt': 'text/plain; charset=utf-8', '.smi': 'text/plain; charset=utf-8',
            '.vtt': 'text/vtt; charset=utf-8', '.txt': 'text/plain; charset=utf-8'
        }

        # ━━━ 가상 병합 파일시스템 프로바이더 (실시간 Union FS) ━━━
        class MergedFileResource(DAVNonCollection):
            """가상 병합 폴더 내의 단일 파일 리소스 (실시간 Range 스트리밍 및 ETag 완벽 지원)"""
            def __init__(self, path: str, environ, real_path: str, readonly: bool = True):
                super().__init__(path, environ)
                self._file_path = real_path
                self._readonly = readonly
                try:
                    self.file_stat = os.stat(self._file_path)
                except:
                    self.file_stat = None
                self.name = os.path.basename(self._file_path)
                self.name = util.to_str(self.name)

            def get_content_length(self):
                if self.file_stat:
                    return self.file_stat[stat.ST_SIZE]
                try: return os.path.getsize(self._file_path)
                except: return 0

            def get_content_type(self):
                ext = os.path.splitext(self._file_path)[1].lower()
                if ext in _DAV_MIME_EXTS:
                    return _DAV_MIME_EXTS[ext]
                return util.guess_mime_type(self._file_path) or 'application/octet-stream'

            def get_content(self):
                _trigger_webdav_play_event(self._file_path, "WebDAV")
                return open(self._file_path, 'rb', BUFFER_SIZE)

            def get_last_modified(self):
                if self.file_stat:
                    return self.file_stat[stat.ST_MTIME]
                try: return os.path.getmtime(self._file_path)
                except: return time.time()

            def get_creation_date(self):
                if self.file_stat:
                    return self.file_stat[stat.ST_CTIME]
                try: return os.path.getctime(self._file_path)
                except: return time.time()

            def support_ranges(self):
                return True

            def get_display_name(self):
                return self.name

            def support_etag(self):
                return True

            def get_etag(self):
                return util.get_file_etag(self._file_path)

        class MergedFolderResource(DAVCollection):
            """여러 물리 디렉토리를 실시간 병합하여 노출하는 가상 컬렉션 (서브폴더 및 빈 폴더 완벽 지원)"""
            def __init__(self, path: str, environ, provider, matched_dirs: list, is_root: bool = False):
                super().__init__(path, environ)
                self._provider = provider
                self._matched_dirs = [os.path.normpath(d) for d in matched_dirs if os.path.isdir(d)]
                self._is_root = is_root
                base_name = os.path.basename(self.path.rstrip('/'))
                self.name = util.to_str(base_name) if base_name else "root"

            def get_display_name(self):
                base_name = os.path.basename(self.path.rstrip('/'))
                return base_name if base_name else "MergedFolder"

            def get_member_names(self):
                """[V180.7] 자연 정렬을 적용하여 클라이언트(Skybox/nPlayer)에서 다음 파일이 올바른 순서로 재생되도록 지원 🎬⏭️"""
                names = set()
                for pdir in self._matched_dirs:
                    try:
                        if os.path.isdir(pdir):
                            for entry in os.listdir(pdir):
                                if not util.is_str(entry):
                                    entry = entry.decode(sys.getfilesystemencoding(), errors='replace')
                                cand = os.path.join(pdir, entry)
                                if os.path.isdir(cand) or os.path.isfile(cand):
                                    names.add(util.to_str(entry))
                    except Exception:
                        pass
                return sorted(list(names), key=_dav_natural_key)

            def get_member(self, name: str):
                """[V180.7] 유니코드/대소문자 차이도 안전하게 탐색하여 다음 파일 호출 실패 원천 차단! 🛡️✨"""
                if not name:
                    return None
                name = util.to_str(name)
                sub_path = util.join_uri(self.path, name)
                matched_sub_dirs = []
                matched_file = None

                # 1차 직접 매칭
                for d in self._matched_dirs:
                    cand = os.path.join(d, name)
                    if os.path.isdir(cand):
                        matched_sub_dirs.append(cand)
                    elif os.path.isfile(cand) and matched_file is None:
                        matched_file = cand

                # 2차 유니코드 정규화(NFC/NFD) 및 대소문자 무시 매칭 (클라이언트 요청 오차 보정)
                if not matched_sub_dirs and matched_file is None:
                    norm_target = _dav_unicodedata.normalize('NFC', name).lower()
                    for d in self._matched_dirs:
                        if os.path.isdir(d):
                            try:
                                for entry in os.listdir(d):
                                    entry_norm = _dav_unicodedata.normalize('NFC', entry).lower()
                                    if entry_norm == norm_target:
                                        cand = os.path.join(d, entry)
                                        if os.path.isdir(cand):
                                            matched_sub_dirs.append(cand)
                                        elif os.path.isfile(cand) and matched_file is None:
                                            matched_file = cand
                            except Exception: pass

                if matched_sub_dirs:
                    return MergedFolderResource(sub_path, self.environ, self._provider, matched_sub_dirs, is_root=False)
                if matched_file:
                    return MergedFileResource(sub_path, self.environ, matched_file, readonly=self._provider._readonly)
                return None

            def get_last_modified(self):
                mtimes = []
                for pdir in self._matched_dirs:
                    try: mtimes.append(os.path.getmtime(pdir))
                    except: pass
                return max(mtimes) if mtimes else time.time()

            def get_creation_date(self):
                ctimes = []
                for pdir in self._matched_dirs:
                    try: ctimes.append(os.path.getctime(pdir))
                    except: pass
                return max(ctimes) if ctimes else time.time()

            def get_directory_info(self):
                return None

            def get_etag(self):
                return None

            def support_etag(self):
                return False

            def is_link(self):
                return False

            def get_used_bytes(self):
                for pdir in self._matched_dirs:
                    try: return shutil.disk_usage(pdir).used
                    except: pass
                return 0

            def get_available_bytes(self):
                for pdir in self._matched_dirs:
                    try: return shutil.disk_usage(pdir).free
                    except: pass
                return 0

        class HitsFolderResource(DAVCollection):
            """[V180.9] 따봉(좋아요) 동영상들을 실시간 모아서 서빙하는 가상 컬렉션 👍✨"""
            def __init__(self, path: str, environ, provider):
                super().__init__(path, environ)
                self._provider = provider
                base_name = os.path.basename(self.path.rstrip('/'))
                self.name = util.to_str(base_name) if base_name else "HitsFolder"

            def get_display_name(self):
                return self.name

            def _get_hit_files(self):
                now = time.time()
                cache = getattr(self._provider, '_cached_files', None)
                cache_time = getattr(self._provider, '_cached_time', 0)
                if cache is not None and (now - cache_time < 4.0):
                    return cache

                hits_dict = settings.data.get('hits', {}) if settings else {}
                res = {}
                for h_name, h_val in hits_dict.items():
                    p = h_val if isinstance(h_val, str) else (h_val.get("path", "") if isinstance(h_val, dict) else "")
                    if p and os.path.isfile(p):
                        fname = os.path.basename(p)
                        res[fname] = p
                        base_no_ext = os.path.splitext(p)[0]
                        for s_ext in ('.srt', '.smi', '.ko.srt', '.en.srt', '.vtt', '.txt'):
                            s_path = base_no_ext + s_ext
                            if os.path.isfile(s_path):
                                res[os.path.basename(s_path)] = s_path
                self._provider._cached_files = res
                self._provider._cached_time = now
                return res

            def get_member_names(self):
                hit_files = self._get_hit_files()
                return sorted(list(hit_files.keys()), key=_dav_natural_key)

            def get_member(self, name: str):
                if not name: return None
                hit_files = self._get_hit_files()
                name_str = util.to_str(name)
                real_p = hit_files.get(name_str)
                if not real_p:
                    norm_n = _dav_unicodedata.normalize('NFC', name_str).lower()
                    for k, v in hit_files.items():
                        if _dav_unicodedata.normalize('NFC', k).lower() == norm_n:
                            real_p = v; break
                if real_p and os.path.isfile(real_p):
                    sub_path = util.join_uri(self.path, name_str)
                    return MergedFileResource(sub_path, self.environ, real_p, readonly=self._provider._readonly)
                return None

            def get_last_modified(self): return time.time()
            def get_creation_date(self): return time.time()
            def get_directory_info(self): return None
            def get_etag(self): return None
            def support_etag(self): return False
            def is_link(self): return False
            def get_used_bytes(self): return 0
            def get_available_bytes(self): return 0

        class HitsDAVProvider(DAVProvider):
            """[V180.9] 따봉(좋아요) 동영상 전용 WebDAV 가상 프로바이더 👍✨"""
            def __init__(self, readonly: bool = True):
                super().__init__()
                self._readonly = readonly
                self._cached_files = None
                self._cached_time = 0

            def get_resource_inst(self, path: str, environ):
                rel_path = path
                if self.share_path and rel_path.lower().startswith(self.share_path.lower()):
                    rel_path = rel_path[len(self.share_path):]
                if not rel_path or rel_path == '/':
                    rel_path = '/'
                clean_path = rel_path.strip('/')
                rel_parts = [p for p in clean_path.split('/') if p]

                if not rel_parts:
                    return HitsFolderResource('/', environ, self)

                if len(rel_parts) == 1:
                    fname = rel_parts[0]
                    norm_fname = _dav_unicodedata.normalize('NFC', fname).lower()
                    files_map = HitsFolderResource('/', environ, self)._get_hit_files()
                    for k, real_p in files_map.items():
                        if _dav_unicodedata.normalize('NFC', k).lower() == norm_fname:
                            return MergedFileResource(f"/{k}", environ, real_p, readonly=self._readonly)
                return None

        class AllMediaFolderResource(DAVCollection):
            """[V180.9] 즐겨찾기에 등록된 모든 하위 폴더의 낱개 미디어 파일들을 재귀적으로 모아서 평면 서빙하는 가상 컬렉션 (모든동영상 / 모든음악) 🎬🎵✨"""
            def __init__(self, path: str, environ, provider):
                super().__init__(path, environ)
                self._provider = provider
                base_name = os.path.basename(self.path.rstrip('/'))
                self.name = util.to_str(base_name) if base_name else ("AllVideos" if provider.media_type == "video" else "AllMusic")

            def get_display_name(self):
                return self.name

            def _get_media_files(self):
                now = time.time()
                cache = getattr(self._provider, '_cached_files', None)
                cache_time = getattr(self._provider, '_cached_time', 0)
                if cache is not None and (now - cache_time < 5.0):
                    return cache

                key = 'playlist_groups' if self._provider.media_type == 'video' else 'playlist_music_groups'
                target_exts = ('.mp4', '.mkv', '.avi', '.mov', '.wmv', '.flv', '.m4v', '.webm', '.ts', '.m2ts', '.mpg', '.mpeg', '.tp') if self._provider.media_type == 'video' else ('.mp3', '.flac', '.wav', '.m4a', '.aac', '.ogg', '.wma')
                
                folders = set()
                if settings:
                    for p_list in settings.data.get(key, {}).values():
                        if isinstance(p_list, list):
                            for p in p_list:
                                if isinstance(p, str) and os.path.isdir(p):
                                    folders.add(os.path.normpath(p))
                    for p in settings.data.get('custom_favorites', []):
                        if isinstance(p, str) and os.path.isdir(p):
                            folders.add(os.path.normpath(p))

                res = {}
                for root_fld in sorted(folders):
                    try:
                        for root, dirs, files in os.walk(root_fld):
                            for fn in files:
                                if fn.lower().endswith(target_exts):
                                    full_p = os.path.join(root, fn)
                                    if fn in res and res[fn] != full_p:
                                        parent_nm = os.path.basename(root)
                                        f_base, f_ext = os.path.splitext(fn)
                                        disp_fn = f"{f_base} ({parent_nm}){f_ext}"
                                        res[disp_fn] = full_p
                                    else:
                                        res[fn] = full_p
                                    
                                    if self._provider.media_type == 'video':
                                        base_no_ext = os.path.splitext(full_p)[0]
                                        for s_ext in ('.srt', '.smi', '.ko.srt', '.en.srt', '.vtt', '.txt'):
                                            s_path = base_no_ext + s_ext
                                            if os.path.isfile(s_path):
                                                s_fn = os.path.basename(s_path)
                                                if fn in res and '(' in fn and ')' in fn:
                                                    s_base, s_e = os.path.splitext(s_fn)
                                                    parent_nm = os.path.basename(root)
                                                    res[f"{s_base} ({parent_nm}){s_e}"] = s_path
                                                else:
                                                    res[s_fn] = s_path
                    except Exception:
                        pass
                self._provider._cached_files = res
                self._provider._cached_time = now
                return res

            def get_member_names(self):
                files_map = self._get_media_files()
                return sorted(list(files_map.keys()), key=_dav_natural_key)

            def get_member(self, name: str):
                if not name: return None
                files_map = self._get_media_files()
                name_str = util.to_str(name)
                real_p = files_map.get(name_str)
                if not real_p:
                    norm_n = _dav_unicodedata.normalize('NFC', name_str).lower()
                    for k, v in files_map.items():
                        if _dav_unicodedata.normalize('NFC', k).lower() == norm_n:
                            real_p = v; break
                if real_p and os.path.isfile(real_p):
                    sub_path = util.join_uri(self.path, name_str)
                    return MergedFileResource(sub_path, self.environ, real_p, readonly=self._provider._readonly)
                return None

            def get_last_modified(self): return time.time()
            def get_creation_date(self): return time.time()
            def get_directory_info(self): return None
            def get_etag(self): return None
            def support_etag(self): return False
            def is_link(self): return False
            def get_used_bytes(self): return 0
            def get_available_bytes(self): return 0

        class AllMediaDAVProvider(DAVProvider):
            """[V180.9] 모든동영상/모든음악 낱개 파일 평면 노출 WebDAV 가상 프로바이더 🎬🎵✨"""
            def __init__(self, media_type: str = 'video', readonly: bool = True):
                super().__init__()
                self.media_type = media_type  # 'video' or 'music'
                self._readonly = readonly
                self._cached_files = None
                self._cached_time = 0

            def get_resource_inst(self, path: str, environ):
                rel_path = path
                if self.share_path and rel_path.lower().startswith(self.share_path.lower()):
                    rel_path = rel_path[len(self.share_path):]
                if not rel_path or rel_path == '/':
                    rel_path = '/'
                clean_path = rel_path.strip('/')
                rel_parts = [p for p in clean_path.split('/') if p]

                if not rel_parts:
                    return AllMediaFolderResource('/', environ, self)

                if len(rel_parts) == 1:
                    fname = rel_parts[0]
                    norm_fname = _dav_unicodedata.normalize('NFC', fname).lower()
                    files_map = AllMediaFolderResource('/', environ, self)._get_media_files()
                    for k, real_p in files_map.items():
                        if _dav_unicodedata.normalize('NFC', k).lower() == norm_fname:
                            return MergedFileResource(f"/{k}", environ, real_p, readonly=self._readonly)
                return None

        class MergedFilesystemProvider(DAVProvider):
            """여러 물리 디렉토리를 하나의 가상 디렉토리 트리로 실시간 병합(Union)하는 프로바이더"""
            def __init__(self, root_paths: list, readonly: bool = True):
                super().__init__()
                self._root_paths = [os.path.normpath(p) for p in root_paths if isinstance(p, str)]
                self._readonly = readonly

            def get_resource_inst(self, path: str, environ):
                # [V180.6] share_path 접두사를 대소문자 무시로 제거하여 상대경로만 추출
                rel_path = path
                if self.share_path and rel_path.lower().startswith(self.share_path.lower()):
                    rel_path = rel_path[len(self.share_path):]
                if not rel_path or rel_path == '/':
                    rel_path = '/'
                clean_path = rel_path.strip('/')
                rel_parts = [p for p in clean_path.split('/') if p]

                # 1. 루트 경로 ('/') 요청 시: 빈 폴더여도 안전한 빈 가상 컬렉션 반환
                if not rel_parts:
                    valid_roots = [p for p in self._root_paths if os.path.isdir(p)]
                    return MergedFolderResource(path, environ, self, valid_roots, is_root=True)

                # 2. 하위 경로 요청 시: 모든 root_path에서 해당 상대경로를 실시간 탐색
                matched_dirs = []
                matched_file = None

                # 1차 직접 매칭
                for root in self._root_paths:
                    if not os.path.isdir(root):
                        continue
                    cand = os.path.join(root, *rel_parts)
                    if os.path.isdir(cand):
                        matched_dirs.append(cand)
                    elif os.path.isfile(cand) and matched_file is None:
                        matched_file = cand

                # 2차 유니코드/대소문자 무시 매칭 (클라이언트 URL 인코딩 오차 보정)
                if not matched_dirs and matched_file is None:
                    target_name = rel_parts[-1]
                    norm_target = _dav_unicodedata.normalize('NFC', target_name).lower()
                    parent_parts = rel_parts[:-1]
                    for root in self._root_paths:
                        if not os.path.isdir(root): continue
                        pdir = os.path.join(root, *parent_parts) if parent_parts else root
                        if os.path.isdir(pdir):
                            try:
                                for entry in os.listdir(pdir):
                                    if _dav_unicodedata.normalize('NFC', entry).lower() == norm_target:
                                        cand = os.path.join(pdir, entry)
                                        if os.path.isdir(cand): matched_dirs.append(cand)
                                        elif os.path.isfile(cand) and matched_file is None: matched_file = cand
                            except Exception: pass

                full_path = util.join_uri(self.share_path or '/', *rel_parts)
                if matched_dirs:
                    return MergedFolderResource(full_path, environ, self, matched_dirs, is_root=False)

                if matched_file:
                    return MergedFileResource(full_path, environ, matched_file, readonly=self._readonly)

                return None

        # 1. 개별 공유폴더 파일시스템 프로바이더들을 매핑 테이블에 사전 등록
        provider_mapping = {}
        for folder in folders:
            name = folder.get('name', '').strip().strip('/')
            readonly = folder.get('readonly', True)
            if not name:
                continue

            v_type = folder.get('virtual_type', '')
            is_virtual = folder.get('is_virtual', False) or ('paths' in folder) or bool(v_type)

            if v_type == 'hits' or (name.lower() in ('hits', '따봉동영상') and not folder.get('path') and not folder.get('paths')):
                mount_point = f"/{name.lower()}"
                provider_mapping[mount_point] = HitsDAVProvider(readonly=readonly)
            elif v_type == 'all_video' or (name.lower() in ('all_video', '모든동영상') and not folder.get('path') and not folder.get('paths')):
                mount_point = f"/{name.lower()}"
                provider_mapping[mount_point] = AllMediaDAVProvider(media_type='video', readonly=readonly)
            elif v_type == 'all_music' or (name.lower() in ('all_music', '모든음악') and not folder.get('path') and not folder.get('paths')):
                mount_point = f"/{name.lower()}"
                provider_mapping[mount_point] = AllMediaDAVProvider(media_type='music', readonly=readonly)
            elif is_virtual:
                paths = folder.get('paths', [])
                valid_paths = []
                for p in paths:
                    if isinstance(p, str):
                        if not os.path.isdir(p):
                            try: os.makedirs(p, exist_ok=True)
                            except: continue
                        valid_paths.append(p)
                mount_point = f"/{name.lower()}"
                provider_mapping[mount_point] = MergedFilesystemProvider(valid_paths, readonly=readonly)
            else:
                path = folder.get('path', '').strip()
                if not path:
                    continue
                if not os.path.isdir(path):
                    try: os.makedirs(path, exist_ok=True)
                    except: continue
                mount_point = f"/{name.lower()}"
                provider_mapping[mount_point] = FilesystemProvider(path, readonly=readonly, fs_opts={})

        # 2. 멀티 계정 & 폴더별 접근 제어 커스텀 DomainController
        class FileDavDomainController(BaseDomainController):
            """독립 WebDAV 파일서버 전용 멀티 계정 & 폴더별 접근 제어 도메인 컨트롤러"""
            def __init__(self, wsgidav_app, config):
                super().__init__(wsgidav_app, config)
                self.users_list = config.get('file_dav_users', [])

            def __str__(self):
                return f"{self.__class__.__name__}()"

            def _find_user(self, user_name):
                for u in self.users_list:
                    if u.get('id') == user_name:
                        return u
                return None

            def _check_folder_access(self, user, folder_name):
                if not folder_name or folder_name in ('', '/', 'favicon.ico', '_dav_res'):
                    return True
                u_folders = user.get('folders', ['*'])
                if '*' in u_folders:
                    return True
                # 대소문자 무시 비교
                folder_lower = folder_name.lower()
                return any(f.lower() == folder_lower for f in u_folders)

            def get_domain_realm(self, path_info, environ):
                # 단일 통합 Realm 사용으로 브라우저의 중복 로그인 팝업 완전 방지!
                return "Binu WebDAV"

            def require_authentication(self, realm, environ):
                if not self.users_list:
                    return False
                # 비밀번호가 설정된 계정이 1개라도 있으면 인증 활성화
                return any(bool(u.get('pw')) for u in self.users_list)

            def basic_auth_user(self, realm, user_name, password, environ):
                user = self._find_user(user_name)
                if user is None:
                    return False
                expected_pw = user.get('pw', '')
                if password != expected_pw:
                    return False
                
                environ["wsgidav.auth.roles"] = user.get("roles", [])
                environ["wsgidav.auth.user_name"] = user_name
                environ["file_dav.user_obj"] = user

                # 폴더 접근 권한 확인
                dav_provider = environ.get('wsgidav.provider')
                share_path = getattr(dav_provider, 'share_path', '') if dav_provider else ''
                path = environ.get('PATH_INFO', '')
                target = (share_path or path).strip('/').split('/')[0]

                if target and target not in ('', 'favicon.ico', '_dav_res') and share_path != '/':
                    if not self._check_folder_access(user, target):
                        from wsgidav.dav_error import DAVError, HTTP_FORBIDDEN
                        raise DAVError(HTTP_FORBIDDEN, f"[{user_name}] 계정은 /{target} 폴더에 접근 권한이 없습니다.")

                return True

            def supports_http_digest_auth(self):
                return True

            def digest_auth_user(self, realm, user_name, environ):
                user = self._find_user(user_name)
                if user is None:
                    return False
                
                dav_provider = environ.get('wsgidav.provider')
                share_path = getattr(dav_provider, 'share_path', '') if dav_provider else ''
                path = environ.get('PATH_INFO', '')
                target = (share_path or path).strip('/').split('/')[0]

                if target and target not in ('', 'favicon.ico', '_dav_res') and share_path != '/':
                    if not self._check_folder_access(user, target):
                        from wsgidav.dav_error import DAVError, HTTP_FORBIDDEN
                        raise DAVError(HTTP_FORBIDDEN, f"[{user_name}] 계정은 /{target} 폴더에 접근 권한이 없습니다.")

                expected_pw = user.get('pw', '')
                environ["wsgidav.auth.roles"] = user.get("roles", [])
                environ["wsgidav.auth.user_name"] = user_name
                environ["file_dav.user_obj"] = user
                return self._compute_http_digest_a1(realm, user_name, expected_pw)

        # 3. WsgiDAV 루트(/) 가상 컬렉션 (로그인한 사용자별 허용 폴더만 노출)
        class FileDavRootCollection(DAVCollection):
            """독립 WebDAV 루트 컬렉션: 로그인한 사용자별 허용된 공유 폴더만 노출"""
            def __init__(self, path: str, environ, folders_list, users_list):
                super().__init__(path, environ)
                self._folders = folders_list
                self._users = users_list

            def _get_current_user_allowed_folders(self):
                user_name = self.environ.get("wsgidav.auth.user_name")
                if not user_name:
                    return None
                for u in self._users:
                    if u.get('id') == user_name:
                        return u.get('folders', ['*'])
                return None

            def get_member_names(self):
                allowed = self._get_current_user_allowed_folders()
                names = []
                for f in self._folders:
                    name = f.get('name', '').strip().strip('/')
                    if not name:
                        continue
                    v_type = f.get('virtual_type', '')
                    is_virtual = f.get('is_virtual', False) or ('paths' in f) or bool(v_type)
                    mount_key = name.lower()
                    if is_virtual:
                        if allowed is None or '*' in allowed or any(a.lower() == mount_key for a in allowed):
                            names.append(mount_key)
                    else:
                        path = f.get('path', '').strip()
                        if os.path.isdir(path):
                            if allowed is None or '*' in allowed or any(a.lower() == mount_key for a in allowed):
                                names.append(mount_key)
                return names

            def get_member(self, name):
                allowed = self._get_current_user_allowed_folders()
                # 폴더 접근 제어는 대소문자 무시 비교
                if allowed is not None and ('*' not in allowed):
                    if not any(a.lower() == name.lower() for a in allowed):
                        return None  # 허용되지 않은 폴더 차단
                mount_point = f"/{name.lower()}"
                if mount_point in provider_mapping:
                    res = provider_mapping[mount_point].get_resource_inst("/", self.environ)
                    if res:
                        res.path = mount_point
                        # [V180.6] 물리 폴더명이 아닌 설정된 공유 폴더명으로 표시 (youtube→G:\mv 에서 mv가 아닌 youtube 표시)
                        display_name = name
                        for f in self._folders:
                            cfg_name = f.get('name', '').strip().strip('/')
                            if cfg_name.lower() == name.lower():
                                display_name = cfg_name
                                break
                        res.name = display_name
                    return res
                return None

        class FileDavRootProvider(DAVProvider):
            """루트(/) 요청만 전담 처리하는 가상 프로바이더"""
            def __init__(self, folders_list, users_list):
                super().__init__()
                self._folders = folders_list
                self._users = users_list

            def get_resource_inst(self, path: str, environ):
                path = path.rstrip('/')
                if not path or path == '/':
                    return FileDavRootCollection('/', environ, self._folders, self._users)
                return None

        # 4. 루트 매핑 등록 추가
        provider_mapping["/"] = FileDavRootProvider(folders, users)

        config = {
            "provider_mapping": provider_mapping,
            "verbose": 0,
            "logging": {"enable_loggers": []},
            "dir_browser": {"enable": True, "response_trailer": ""},
            "file_dav_users": users,
            "file_dav_folders": folders,
            "http_authenticator": {
                "domain_controller": FileDavDomainController,
                "accept_basic": True,
                "accept_digest": True,
                "default_to_digest": False,
            }
        }

        if use_ssl:
            if not os.path.exists(cert_path) or not os.path.exists(key_path):
                _file_dav_generate_self_signed_cert(cert_path, key_path)
            
            if os.path.exists(cert_path) and os.path.exists(key_path):
                config["ssl_certificate"] = cert_path
                config["ssl_private_key"] = key_path

        dav_app = WsgiDAVApp(config)

        # [TAG: #@_run_file_dav]
        def _run_file_dav():
            global _file_dav_server_running, _file_dav_cheroot_server
            _file_dav_server_running = True
            
            import sys
            orig_stderr = sys.stderr
            class SSLEOFErrorFilter:
                def __init__(self, orig):
                    self.orig = orig
                def write(self, msg):
                    if any(x in msg for x in ["ssl.SSLEOFError", "violation of protocol", "socket.error", "SSLEOFError", "Traceback"]):
                        return
                    self.orig.write(msg)
                def flush(self):
                    self.orig.flush()
            sys.stderr = SSLEOFErrorFilter(orig_stderr)

            try:
                from cheroot.wsgi import Server as CherootServer
                srv = CherootServer(('0.0.0.0', port), dav_app)
                
                if use_ssl and os.path.exists(cert_path) and os.path.exists(key_path):
                    from cheroot.ssl.builtin import BuiltinSSLAdapter
                    srv.ssl_adapter = BuiltinSSLAdapter(certificate=cert_path, private_key=key_path)

                _file_dav_cheroot_server = srv
                srv.start()
            except Exception as e:
                print(f"❌ [FileDav] 서버 오류: {e}")
            finally:
                sys.stderr = orig_stderr
                _file_dav_server_running = False
                _file_dav_cheroot_server = None

        _file_dav_server_thread = threading.Thread(target=_run_file_dav, daemon=True)
        _file_dav_server_thread.start()

        # UPnP 자동 포트 포워딩 점검 및 시도
        use_upnp = settings.data.get('file_webdav_use_upnp', False)
        local_ip = _get_local_ip()
        if use_upnp:
            try:
                global _miniupnpc_install_checked
                if not _miniupnpc_install_checked:
                    _auto_install("miniupnpc", "miniupnpc", "공유기 UPnP 포트 포워딩", is_optional=True)
                    _miniupnpc_install_checked = True

                success = _setup_upnp_port_forwarding(port)
                if success:
                    ext_ip = _get_external_ip()
                    if ext_ip:
                        local_ip = ext_ip
            except Exception as upnp_err:
                print(f" ❌ {C.RED}UPnP 자동 설정 중 오류 발생: {upnp_err}{R}")

        settings.data['file_webdav_last_running_state'] = True
        settings.save()

        if not is_bg:
            time.sleep(0.8)
            print(f"\r\n {'='*55}")
            print(f" 📂 {C.BOLD}{C.GREEN}독립 WebDAV 파일서버 가동 중!{R}")
            print(f" 🌐 {C.BOLD}주소:{R}  {proto}://{local_ip}:{port}/")
            print(f" {'='*55}\r\n")
        else:
            _log_to_file(f"📂 [Standalone WebDAV Running] {proto}://{local_ip}:{port}/")
        return True

    except Exception as e:
        print(f"\r\n ❌ {ctext(f'WebDAV 파일서버 시작 실패: {e}', C.RED)}")
        _file_dav_server_running = False
        return False

# [TAG: #@_file_dav_manage_folders]
def _notify_restart_if_running():
    """WebDAV 서버가 구동 중이면 재시작 필요성을 안내해 줍니다."""
    global _file_dav_server_running
    if _file_dav_server_running:
        print(f"\r\n 💡 {ctext('WebDAV 파일서버가 이미 가동 중이야냥! 변경 사항을 적용하려면 서버를 재시작해줘!', C.YELLOW)}")

# [TAG: #@_file_dav_manage_folders]
def _file_dav_manage_folders(settings):
    """공유 폴더 등록/삭제/수정 서브메뉴 (가상 병합 폴더 지원)."""
    global _file_dav_server_running
    R = C.RESET
    while True:
        folders = settings.data.get('file_webdav_folders', [])

        options = []
        if folders:
            for i, f in enumerate(folders):
                name = f.get('name', '').strip('/')
                v_type = f.get('virtual_type', '')
                is_virtual = f.get('is_virtual', False) or ('paths' in f) or bool(v_type)
                ro = f.get('readonly', True)
                ro_label = "🔒읽기전용" if ro else "✏️읽기쓰기"
                if v_type == 'hits' or (name.lower() in ('hits', '따봉동영상') and not f.get('path') and not f.get('paths')):
                    hit_cnt = len(settings.data.get('hits', {})) if settings else 0
                    options.append(f" 👍 /{name}  →  [👍 따봉 동영상 낱개 모음 ({hit_cnt}개)]  [{ro_label}]")
                elif v_type == 'all_video' or (name.lower() in ('all_video', '모든동영상') and not f.get('path') and not f.get('paths')):
                    options.append(f" 🎬 /{name}  →  [🎬 모든 동영상 낱개 파일 모음]  [{ro_label}]")
                elif v_type == 'all_music' or (name.lower() in ('all_music', '모든음악') and not f.get('path') and not f.get('paths')):
                    options.append(f" 🎵 /{name}  →  [🎵 모든 음악 낱개 파일 모음]  [{ro_label}]")
                elif is_virtual:
                    paths = f.get('paths', [])
                    valid_paths = [p for p in paths if isinstance(p, str) and os.path.isdir(p)]
                    valid = "🔮" if valid_paths else "❌"
                    path_preview = f"[{len(valid_paths)}개 병합] ({', '.join(os.path.basename(p.rstrip('\\/')) or p for p in valid_paths[:2])}{' 외 ' + str(len(valid_paths)-2) + '개' if len(valid_paths) > 2 else ''})"
                    options.append(f" {valid} /{name}  →  {path_preview}  [{ro_label}]")
                else:
                    path = f.get('path', '')
                    valid = "✅" if os.path.isdir(path) else "❌"
                    options.append(f" {valid} /{name}  →  {path}  [{ro_label}]")
        else:
            options.append(" (등록된 폴더 없음)")

        options += [
            구분선(),
            " ➕ 폴더 추가",
            " 📌 즐겨찾기에서 일괄 추가",
            " 🔮 가상 병합 폴더 생성 (여러 물리 폴더 묶기)",
            " ⭐ 특수 가상폴더 추가 (따봉동영상/모든동영상/모든음악)",
            " 🗑️ 폴더 삭제",
            " ❌ 이전 메뉴로 돌아가기"
        ]
        sel = menu("📁 공유 폴더 관리", options)

        if sel is None:
            break

        item_count = len(folders) if folders else 1
        div_offset = item_count
        add_idx = div_offset + 1
        fav_add_idx = div_offset + 2
        merge_add_idx = div_offset + 3
        special_add_idx = div_offset + 4
        del_idx = div_offset + 5
        back_idx = div_offset + 6

        if sel == add_idx:
            # 폴더 추가
            import tkinter as tk
            root = tk.Tk(); root.withdraw(); root.attributes('-topmost', True)
            path_input = remote_explorer(mode='dir', title="WebDAV 파일서버에 공유할 폴더 선택")
            root.destroy()
            
            if not path_input:
                continue
            if isinstance(path_input, list):
                path_input = path_input[0] if path_input else None
            
            if not path_input or not os.path.isdir(path_input):
                err("유효하지 않은 폴더 경로가 선택되었어냥!")
                pause()
                continue
            path_input = os.path.normpath(path_input)

            print(f"\r\n 🏷️  {C.CYAN}탑재 이름을 입력해줘 (URL에 표시될 이름, 영문/숫자 권장):{R}")
            name_input = input("   이름> ").strip().strip('/')
            if not name_input:
                name_input = os.path.basename(path_input.rstrip('\\/')) or "shared"

            # 읽기전용/읽기쓰기 선택
            ro_sel = menu("🔐 접근 권한 선택", [
                " 🔒 읽기 전용 (다운로드만 가능)",
                " ✏️ 읽기+쓰기 (업로드/삭제 가능)",
                " ❌ 취소"
            ])
            if ro_sel is None or ro_sel == 2:
                continue
            readonly = (ro_sel == 0)

            folders.append({"name": name_input, "path": path_input, "readonly": readonly})
            settings.data['file_webdav_folders'] = folders
            settings.save()
            ro_label = "읽기전용" if readonly else "읽기+쓰기"
            ok(f"/{name_input} ({path_input}) [{ro_label}] 추가 완료!")
            _notify_restart_if_running()
            pause(sec=1)

        elif sel == fav_add_idx:
            # [신규] 즐겨찾기에서 일괄 추가 (토글 메뉴) 📌✨
            fav_folders_set = set()
            for grp_paths in settings.data.get('playlist_groups', {}).values():
                if isinstance(grp_paths, list):
                    for p in grp_paths:
                        if isinstance(p, str) and os.path.isdir(p):
                            fav_folders_set.add(os.path.normpath(p))
            for grp_paths in settings.data.get('playlist_music_groups', {}).values():
                if isinstance(grp_paths, list):
                    for p in grp_paths:
                        if isinstance(p, str) and os.path.isdir(p):
                            fav_folders_set.add(os.path.normpath(p))
            for p in settings.data.get('custom_favorites', []):
                if isinstance(p, str) and os.path.isdir(p):
                    fav_folders_set.add(os.path.normpath(p))

            if not fav_folders_set:
                err("등록된 즐겨찾기 폴더가 없어냥!")
                pause()
                continue

            sorted_fav_folders = sorted(list(fav_folders_set), key=lambda x: (x.lower(), x))
            existing_norm_paths = {os.path.normcase(os.path.normpath(f.get('path', ''))) for f in folders if f.get('path')}
            existing_names = {f.get('name', '').strip('/') for f in folders if f.get('name')}

            fav_options = []
            init_indices = set()
            for idx, p in enumerate(sorted_fav_folders):
                norm_p = os.path.normcase(p)
                base_nm = os.path.basename(p.rstrip('\\/')) or p
                if norm_p in existing_norm_paths:
                    status_tag = f" {C.GREEN}[이미 등록됨]{R}"
                    init_indices.add(idx)
                else:
                    status_tag = ""
                fav_options.append(f"📁 {base_nm}  →  {p}{status_tag}")

            try:
                sel_res, _, *_ = _interactive_menu(
                    "📌 즐겨찾기 폴더 일괄 선택 (Space: 선택/해제 토글, Enter: 완료)",
                    fav_options,
                    allow_multi=True,
                    initial_indices=init_indices,
                    allow_empty=True
                )
            except UserAbortException:
                continue

            if sel_res is None or (isinstance(sel_res, int) and sel_res < 0):
                continue

            if isinstance(sel_res, int):
                selected_idxs = [sel_res]
            else:
                selected_idxs = list(sel_res)

            selected_paths = [sorted_fav_folders[i] for i in selected_idxs if 0 <= i < len(sorted_fav_folders)]
            new_paths = [p for p in selected_paths if os.path.normcase(p) not in existing_norm_paths]

            if not new_paths:
                if not selected_paths:
                    print(f"\r\n ℹ️ {C.YELLOW}선택된 폴더가 없어냥!{R}")
                else:
                    print(f"\r\n ℹ️ {C.YELLOW}선택한 폴더는 이미 모두 WebDAV에 등록되어 있어냥!{R}")
                pause(sec=1)
                continue

            # 일괄 접근 권한 선택
            ro_sel = menu(f"🔐 일괄 추가할 {len(new_paths)}개 폴더의 접근 권한 선택", [
                " 🔒 읽기 전용 (다운로드만 가능)",
                " ✏️ 읽기+쓰기 (업로드/삭제 가능)",
                " ❌ 취소"
            ])
            if ro_sel is None or ro_sel == 2:
                continue
            readonly = (ro_sel == 0)
            ro_label = "🔒읽기전용" if readonly else "✏️읽기쓰기"

            added_count = 0
            for p in new_paths:
                base_name = os.path.basename(p.rstrip('\\/')) or "shared"
                candidate_name = base_name
                cnt = 2
                while candidate_name in existing_names:
                    candidate_name = f"{base_name}_{cnt}"
                    cnt += 1
                existing_names.add(candidate_name)
                folders.append({"name": candidate_name, "path": p, "readonly": readonly})
                added_count += 1

            settings.data['file_webdav_folders'] = folders
            settings.save()
            ok(f"즐겨찾기에서 {added_count}개 폴더 [{ro_label}] 일괄 추가 완료!")
            _notify_restart_if_running()
            pause(sec=1)

        elif sel == merge_add_idx:
            # [신규] 🔮 가상 병합 폴더 생성 (여러 물리 폴더 묶기) ✨
            seen_paths = set()
            candidate_list = []

            # 1) 현재 등록된 단일 물리 폴더들
            for f in folders:
                if not f.get('is_virtual') and f.get('path'):
                    p = os.path.normpath(f.get('path'))
                    if os.path.isdir(p) and os.path.normcase(p) not in seen_paths:
                        seen_paths.add(os.path.normcase(p))
                        candidate_list.append((f.get('name', ''), p))

            # 2) 즐겨찾기 폴더들
            for grp_paths in list(settings.data.get('playlist_groups', {}).values()) + list(settings.data.get('playlist_music_groups', {}).values()):
                if isinstance(grp_paths, list):
                    for p in grp_paths:
                        if isinstance(p, str) and os.path.isdir(p):
                            norm_p = os.path.normpath(p)
                            if os.path.normcase(norm_p) not in seen_paths:
                                seen_paths.add(os.path.normcase(norm_p))
                                candidate_list.append(('', norm_p))

            for p in settings.data.get('custom_favorites', []):
                if isinstance(p, str) and os.path.isdir(p):
                    norm_p = os.path.normpath(p)
                    if os.path.normcase(norm_p) not in seen_paths:
                        seen_paths.add(os.path.normcase(norm_p))
                        candidate_list.append(('', norm_p))

            if not candidate_list:
                err("가상 병합에 사용할 수 있는 물리 폴더가 없어냥! 먼저 물리 폴더를 추가해줘.")
                pause()
                continue

            merge_menu_opts = []
            for reg_nm, p in candidate_list:
                base_nm = os.path.basename(p.rstrip('\\/')) or p
                reg_tag = f" {C.SKY}[/{reg_nm}]{R}" if reg_nm else ""
                merge_menu_opts.append(f"📁 {base_nm}{reg_tag}  →  {p}")

            print(f"\r\n {C.PURPLE}╔{'═'*65}{R}")
            print(f" {C.PURPLE}║{R}  🔮 {C.BOLD}{C.GOLD}가상 병합 폴더 생성 (Union Folder){R}")
            print(f" {C.PURPLE}╟{'─'*65}{R}")
            print(f" {C.PURPLE}║{R}  💡 여러 드라이브/물리 폴더를 하나의 가상 폴더로 합쳐서 서빙합니다.")
            print(f" {C.PURPLE}║{R}  💡 {C.GREEN}Space키{R}로 묶을 물리 폴더들을 2개 이상 선택 후 {C.GREEN}Enter{R}를 눌러줘냥!")
            print(f" {C.PURPLE}╚{'═'*65}{R}\r\n")

            try:
                sel_res, _, *_ = _interactive_menu(
                    "🔮 가상 폴더로 묶을 물리 폴더 선택 (Space: 다중선택, Enter: 완료)",
                    merge_menu_opts,
                    allow_multi=True,
                    allow_empty=True
                )
            except UserAbortException:
                continue

            if sel_res is None or (isinstance(sel_res, int) and sel_res < 0):
                continue

            if isinstance(sel_res, int):
                selected_idxs = [sel_res]
            else:
                selected_idxs = list(sel_res)

            selected_paths = [candidate_list[i][1] for i in selected_idxs if 0 <= i < len(candidate_list)]

            if len(selected_paths) < 2:
                err("가상 병합 폴더는 최소 2개 이상의 물리 폴더를 선택해야 해냥!")
                pause(sec=1.5)
                continue

            print(f"\r\n 🏷️  {C.CYAN}가상 병합 폴더의 탑재 이름을 입력해줘 (예: movies, all_data):{R}")
            name_input = input("   가상 이름> ").strip().strip('/')
            if not name_input:
                name_input = "merged_" + os.path.basename(selected_paths[0].rstrip('\\/'))

            existing_names = {f.get('name', '').strip('/') for f in folders if f.get('name')}
            if name_input in existing_names:
                err(f"'{name_input}' 이름은 이미 사용 중이야냥!")
                pause()
                continue

            # 권한 선택 (가상 병합은 읽기 전용 권장)
            ro_sel = menu(f"🔐 /{name_input} 가상 병합 폴더 권한 선택", [
                " 🔒 읽기 전용 (강력 권장 - 여러 폴더의 파일을 안전하게 통합 열람/스트리밍)",
                " ✏️ 읽기+쓰기 (업로드 시 첫 번째 물리 폴더에 저장)",
                " ❌ 취소"
            ])
            if ro_sel is None or ro_sel == 2:
                continue
            readonly = (ro_sel == 0)
            ro_label = "🔒읽기전용" if readonly else "✏️읽기쓰기"

            folders.append({
                "name": name_input,
                "paths": selected_paths,
                "is_virtual": True,
                "readonly": readonly
            })
            settings.data['file_webdav_folders'] = folders
            settings.save()
            ok(f"🔮 /{name_input} (물리 폴더 {len(selected_paths)}개 병합) [{ro_label}] 생성 완료!")
            _notify_restart_if_running()
            pause(sec=1.2)

        elif sel == special_add_idx:
            # [신규] ⭐ 특수 가상폴더 추가 (따봉동영상 / 모든동영상 / 모든음악) - 이름 및 권한 맞춤 설정 지원 ✨
            sp_opts = [
                " 👍 따봉동영상 (hits) 가상폴더 등록",
                " 🎬 모든동영상 (all_video) 가상폴더 등록",
                " 🎵 모든음악 (all_music) 가상폴더 등록",
                " 🌟 3종 전체 일괄 등록 (따봉/모든영상/모든음악)",
                " ❌ 취소"
            ]
            sp_sel = menu("⭐ 특수 가상 폴더 선택", sp_opts)
            if sp_sel is None or sp_sel == 4:
                continue

            existing_names = {f.get('name', '').strip('/').lower() for f in folders if f.get('name')}

            if sp_sel in (0, 1, 2):
                v_type_map = {0: ("hits", "따봉동영상", "👍 따봉동영상"), 1: ("all_video", "모든동영상", "🎬 모든동영상"), 2: ("all_music", "모든음악", "🎵 모든음악")}
                v_type, def_name, type_label = v_type_map[sp_sel]

                print(f"\r\n 🏷️  {C.CYAN}{type_label} 가상 탑재 이름을 입력해줘 (예: {def_name}, {v_type}):{R}")
                name_input = input(f"   가상 이름 [기본: {def_name}]> ").strip().strip('/')
                if not name_input:
                    name_input = def_name

                if name_input.lower() in existing_names:
                    err(f"'{name_input}' 이름은 이미 사용 중이야냥!")
                    pause(sec=1.5)
                    continue

                # 권한 선택 (읽기전용 vs 읽기쓰기)
                ro_sel = menu(f"🔐 /{name_input} 접근 권한 선택", [
                    " 🔒 읽기 전용 (권장 - 안전한 스트리밍)",
                    " ✏️ 읽기+쓰기 (업로드/수정 허용)",
                    " ❌ 취소"
                ])
                if ro_sel is None or ro_sel == 2:
                    continue
                readonly = (ro_sel == 0)
                ro_label = "🔒읽기전용" if readonly else "✏️읽기쓰기"

                folders.append({
                    "name": name_input,
                    "virtual_type": v_type,
                    "is_virtual": True,
                    "readonly": readonly
                })
                settings.data['file_webdav_folders'] = folders
                settings.save()
                ok(f"/{name_input} ({type_label}) [{ro_label}] 가상폴더 추가 완료!")
                _notify_restart_if_running()
                pause(sec=1.2)

            elif sp_sel == 3:
                # 3종 전체 일괄 등록
                ro_sel = menu("🔐 3종 특수 가상폴더 일괄 접근 권한 선택", [
                    " 🔒 읽기 전용 (권장 - 안전한 스트리밍)",
                    " ✏️ 읽기+쓰기 (업로드/수정 허용)",
                    " ❌ 취소"
                ])
                if ro_sel is None or ro_sel == 2:
                    continue
                readonly = (ro_sel == 0)
                ro_label = "🔒읽기전용" if readonly else "✏️읽기쓰기"

                to_add_list = []
                if '따봉동영상' not in existing_names and 'hits' not in existing_names:
                    to_add_list.append({"name": "따봉동영상", "virtual_type": "hits", "is_virtual": True, "readonly": readonly})
                if '모든동영상' not in existing_names and 'all_video' not in existing_names:
                    to_add_list.append({"name": "모든동영상", "virtual_type": "all_video", "is_virtual": True, "readonly": readonly})
                if '모든음악' not in existing_names and 'all_music' not in existing_names:
                    to_add_list.append({"name": "모든음악", "virtual_type": "all_music", "is_virtual": True, "readonly": readonly})

                if not to_add_list:
                    print(f"\r\n ℹ️ {C.YELLOW}3종 특수 가상폴더가 이미 모두 등록되어 있어냥!{R}")
                    pause(sec=1.5)
                    continue

                folders.extend(to_add_list)
                settings.data['file_webdav_folders'] = folders
                settings.save()
                ok(f"특수 가상폴더 {len(to_add_list)}개 [{ro_label}] 일괄 추가 완료! (WebDAV 자동 반영)")
