            del_options = []
            for f in folders:
                name = f.get('name', '')
                is_virt = f.get('is_virtual', False) or ('paths' in f)
                if is_virt:
                    paths = f.get('paths', [])
                    del_options.append(f" 🗑️ 🔮 /{name}  →  [가상 병합 {len(paths)}개 폴더]")
                else:
                    del_options.append(f" 🗑️ /{name}  →  {f.get('path', '')}")
            del_options.append(" ❌ 취소")
            del_sel = menu("🗑️ 삭제할 폴더 선택", del_options)
            if del_sel is None or del_sel >= len(folders):
                continue
            removed = folders.pop(del_sel)
