            # 사용자별 권한 목록에서도 삭제된 폴더명 정리
            users = _file_dav_get_users(settings)
            for u in users:
                u_f = u.get('folders', [])
                if '*' not in u_f and removed_name in u_f:
                    u_f.remove(removed_name)
            _file_dav_save_users(settings, users)
            
