# [TAG: #@_file_dav_settings_menu]
def _file_dav_settings_menu(settings):
    """포트 / 보안(SSL) / UPnP 및 계정 관리 서브메뉴."""
    R = C.RESET
    while True:
        port = settings.data.get('file_webdav_port', 8765)
        users = _file_dav_get_users(settings)
        user_cnt = len(users)
        rep_user = users[0].get('id', 'admin') if users else 'admin'

        use_upnp = settings.data.get('file_webdav_use_upnp', False)
        use_ssl = settings.data.get('file_webdav_use_ssl', False)
        upnp_status = "🟢 ON" if use_upnp else "⚫ OFF"
        ssl_status = "🟢 ON (HTTPS)" if use_ssl else "⚫ OFF (HTTP)"
        options = [
            f" 🔌 포트 변경  [현재: {port}]",
            f" 👥 WebDAV 계정 및 권한 관리  [등록: {user_cnt}개 (대표: {rep_user})]",
            f" 📡 UPnP 외부 포트 포워딩 사용  [현재: {upnp_status}]",
            f" 🔒 HTTPS 보안 연결 사용  [현재: {ssl_status}]",
            " ❌ 이전 메뉴로 돌아가기"
        ]
        sel = menu("⚙️ WebDAV 파일서버 설정", options)

        if sel is None or sel == 4:
            break
        elif sel == 0:
            print(f"\r\n 🔌 {C.CYAN}포트 번호를 입력해줘 (1024~65535, 기본: 8765):{R}")
            val = input("   포트> ").strip()
            try:
                p = int(val)
                if 1024 <= p <= 65535:
                    if p in [5000, 18080]:
                        err(f"포트 {p}는 미디어서버에서 사용 중이야! 다른 포트를 입력해줘.")
                        pause()
                        continue
                    settings.data['file_webdav_port'] = p
                    settings.save()
                    ok(f"포트를 {p}번으로 변경했어!")
                else:
                    err("1024~65535 범위로 입력해줘!")
            except ValueError:
                err("숫자만 입력해줘!")
            pause(sec=1)
        elif sel == 1:
            _file_dav_manage_users(settings)
        elif sel == 2:
            new_val = not settings.data.get('file_webdav_use_upnp', False)
            settings.data['file_webdav_use_upnp'] = new_val
            settings.save()
            status_text = "사용함(ON)" if new_val else "사용안함(OFF)"
            ok(f"UPnP 외부 포트포워딩을 {status_text} 상태로 설정했어!")
            pause(sec=1.2)
        elif sel == 3:
            new_val = not settings.data.get('file_webdav_use_ssl', False)
            settings.data['file_webdav_use_ssl'] = new_val
            settings.save()
            status_text = "보안연결(HTTPS)" if new_val else "일반연결(HTTP)"
            ok(f"연결 프로토콜을 {status_text} 상태로 설정했어!")
            pause(sec=1.2)


