# [TAG: #@_ssh_server_status]

def _ssh_server_status():
    """Windows OpenSSH sshd 서비스 상태를 확인합니다."""
    try:
        import subprocess
        result = subprocess.run(
            ['sc', 'query', 'sshd'],
            capture_output=True, text=True, timeout=5
        )
        return 'RUNNING' in result.stdout
    except Exception:
        return False

# [TAG: #@_ssh_server_is_installed]

def _ssh_server_is_installed():
    """OpenSSH 서버 기능이 설치되어 있는지 확인합니다."""
    try:
        import subprocess
        result = subprocess.run(
            ['sc', 'query', 'sshd'],
            capture_output=True, text=True, timeout=5
        )
        # 서비스 자체가 존재하면 설치된 것
        return 'FAILED 1060' not in result.stdout and result.returncode != 1060
    except Exception:
        return False

# [TAG: #@_ssh_server_enable]

def _ssh_server_enable(port=22):
    """OpenSSH 서버를 설치 및 시작합니다."""
    import subprocess
    R = C.RESET

    print(f"\r\n  🔧 {C.CYAN}OpenSSH 서버 활성화 중...{R}")

    # 1. 설치 여부 확인 후 없으면 설치
    if not _ssh_server_is_installed():
        print(f"  📦 {C.YELLOW}OpenSSH 서버 기능 설치 중 (잠시 대기해줘냥!)...{R}")
        result = subprocess.run(
            ['powershell', '-Command',
             'Add-WindowsCapability -Online -Name OpenSSH.Server~~~~0.0.1.0'],
            capture_output=True, text=True, timeout=150
        )
        if result.returncode != 0:
            print(f"  ❌ {C.RED}설치 실패: {result.stderr[:200]}{R}")
            return False
        print(f"  ✅ {C.GREEN}OpenSSH 서버 설치 완료!{R}")

    # 2. 포트 및 비밀번호 인증 설정 보정 (sshd_config 수정)
    sshd_config = r'C:\ProgramData\ssh\sshd_config'
    try:
        if os.path.exists(sshd_config):
            with open(sshd_config, 'r', encoding='utf-8', errors='ignore') as f:
                cfg = f.read()
            import re
            
            # 포트 보정 (포트가 22가 아니면 변경)
            if port != 22:
                if re.search(r'^#?Port\s+\d+', cfg, re.MULTILINE):
                    cfg = re.sub(r'^#?Port\s+\d+', f'Port {port}', cfg, flags=re.MULTILINE)
                else:
                    cfg = f'Port {port}\n' + cfg
            
            # 비밀번호 로그인 강제 활성화 (PasswordAuthentication yes)
            if re.search(r'#?\s*PasswordAuthentication\s+no', cfg, re.IGNORECASE):
                cfg = re.sub(r'#?\s*PasswordAuthentication\s+no', 'PasswordAuthentication yes', cfg, flags=re.IGNORECASE)
            elif re.search(r'#?\s*PasswordAuthentication\s+yes', cfg, re.IGNORECASE):
                cfg = re.sub(r'#?\s*PasswordAuthentication\s+yes', 'PasswordAuthentication yes', cfg, flags=re.IGNORECASE)
            elif 'PasswordAuthentication' not in cfg:
                cfg += '\nPasswordAuthentication yes\n'
                
            # 관리자(administrators) 전용 공개키 의무화 규칙 무력화 (주석 처리)
            cfg = re.sub(
                r'(Match\s+Group\s+administrators\s*\n\s*AuthorizedKeysFile\s+__PROGRAMDATA__/ssh/administrators_authorized_keys)',
                r'# \1',
                cfg,
                flags=re.IGNORECASE
            )
            
            with open(sshd_config, 'w', encoding='utf-8') as f:
                f.write(cfg)
            print(f"  🔌 {C.SKY}SSH 설정 파일 최적화 완료 (비밀번호 인증 활성화)!{R}")
            if port != 22:
                print(f"  🔌 {C.SKY}SSH 포트를 {port}번으로 설정 완료!{R}")
    except PermissionError:
        print(f"  ⚠️ {C.RED}SSH 설정 수정을 위해 관리자 권한이 일시적으로 필요해냥!{R}")
        # 임시 관리자 UAC 권한 상승 보정 시도
        try:
            # 파워쉘을 통해 관리자 권한으로 설정 파일 직접 보정 명령 실행
            cmd = f'Start-Process powershell -ArgumentList "-Command (Get-Content \'{sshd_config}\') -replace \'#?PasswordAuthentication no\',\'PasswordAuthentication yes\' -replace \'Match Group administrators\',\'# Match Group administrators\' | Out-File \'{sshd_config}\' -Encoding utf8" -Verb RunAs -WindowStyle Hidden -Wait'
            subprocess.run(["powershell", "-Command", cmd], capture_output=True)
            print(f"  ✅ {C.GREEN}관리자 승인을 통해 비밀번호 인증 설정 완료!{R}")
        except Exception as e:
            print(f"  ❌ {C.RED}설정 자동 수정 실패 (수동 설정 권장): {e}{R}")
    except Exception as e:
        print(f"  ⚠️ SSH 설정 최적화 중 오류 발생: {e}")

    # 3. 서비스 시작 + 자동시작 등록
    subprocess.run(['sc', 'config', 'sshd', 'start=auto'], capture_output=True)
    result = subprocess.run(['sc', 'start', 'sshd'], capture_output=True, text=True)

    # 4. 방화벽 규칙 자동 추가
    fw_name = f'Binu_SSH_{port}'
    subprocess.run([
        'netsh', 'advfirewall', 'firewall', 'add', 'rule',
        f'name={fw_name}', 'dir=in', 'action=allow',
        'protocol=TCP', f'localport={port}'
    ], capture_output=True)
    print(f"  🔥 {C.GREEN}방화벽 인바운드 규칙 등록 완료 (포트 {port})!{R}")

    import time; time.sleep(1.2)
    return _ssh_server_status()

# [TAG: #@_ssh_server_disable]

def _ssh_server_disable():
    """OpenSSH 서버를 중지합니다."""
    import subprocess
    subprocess.run(['sc', 'config', 'sshd', 'start=demand'], capture_output=True)
    result = subprocess.run(['sc', 'stop', 'sshd'], capture_output=True, text=True)
    import time; time.sleep(0.8)
    return not _ssh_server_status()

# [TAG: #@_ssh_server_get_current_port]

def _ssh_server_get_current_port():
    """sshd_config에서 현재 SSH 포트를 읽어옵니다."""
    sshd_config = r'C:\ProgramData\ssh\sshd_config'
    try:
        if os.path.exists(sshd_config):
            import re
            with open(sshd_config, 'r', encoding='utf-8', errors='ignore') as f:
                for line in f:
                    m = re.match(r'^Port\s+(\d+)', line.strip())
                    if m:
                        return int(m.group(1))
    except Exception:
        pass
    return 22

# [TAG: #@_ssh_server_send_telegram]

def _ssh_server_send_telegram(settings, port, local_ip, ext_ip):
    """SSH 접속 정보를 텔레그램으로 전송합니다."""
    import getpass
    # SSH 전용 ID/PW 우선, 없으면 현재 Windows 계정명 폴백
    ssh_id = settings.data.get('ssh_server_id', '') or _ssh_get_windows_username()
