def _tweak_office_menu():
    """🎓 오피스 2021 정품 인증 상태 확인 & 갱신 & 다운로드 메뉴"""
    import subprocess
    import os
    import time
    import webbrowser

    vbs_paths = [
        r"C:\Program Files\Microsoft Office\root\Office16\ospp.vbs",
        r"C:\Program Files (x86)\Microsoft Office\root\Office16\ospp.vbs",
        r"C:\Program Files\Microsoft Office\Office16\ospp.vbs",
        r"C:\Program Files (x86)\Microsoft Office\Office16\ospp.vbs"
    ]

    # [TAG: #@_find_vbs]

    def _find_vbs():
        return next((p for p in vbs_paths if os.path.exists(p)), None)

    # [TAG: #@_get_license_status]

    def _get_license_status(found_vbs):
        """ospp.vbs /dstatus 로 현재 라이선스 상태 조회"""
        vbs_dir = os.path.dirname(found_vbs)
        try:
            res = subprocess.run(
                ["cscript", "//nologo", "ospp.vbs", "/dstatus"],
                cwd=vbs_dir, capture_output=True, text=True,
                encoding='cp949', errors='ignore', creationflags=0x08000000
            )
            output = res.stdout.strip()
            product_name = "알 수 없음"
            license_status = "알 수 없음"
            remaining_days = -1
            kms_server = "미설정"

            for line in output.splitlines():
                line = line.strip()
                if "PRODUCT NAME:" in line.upper() or "제품 이름" in line:
                    product_name = line.split(":", 1)[-1].strip()
                elif "LICENSE STATUS" in line.upper() or "라이선스 상태" in line:
                    license_status = line.split(":", 1)[-1].strip()
                elif "REMAINING GRACE" in line.upper() or "유예 기간" in line:
                    part = line.split(":", 1)[-1].strip()
                    # "30 day(s)" 형태 파싱
                    for tok in part.split():
                        if tok.isdigit():
                            remaining_days = int(tok)
                            break
                elif "KMS MACHINE NAME FROM DNS" in line.upper() or "kms" in line.lower():
                    kms_server = line.split(":", 1)[-1].strip()

            return product_name, license_status, remaining_days, kms_server, output
        except Exception as ex:
            return "조회 실패", str(ex), -1, "알 수 없음", ""

    # [TAG: #@_wait_enter]

    def _wait_enter():
        prompt_input("\n 🐾 계속하려면 엔터(Enter) 키를 누르세요냥... ")

    while True:
        found_vbs = _find_vbs()
        installed = found_vbs is not None

        if installed:
            product_name, license_status, remaining_days, kms_server, _ = _get_license_status(found_vbs)
            vbs_dir_display = os.path.dirname(found_vbs)

