# [TAG: #@_tweak_restart_as_admin]
def _tweak_restart_as_admin():
    """[V1.0] 현재 프로그램을 관리자 권한으로 승격시켜 재실행합니다냥!"""
    import ctypes
    import sys
    import os
    import time
    
    # 이미 관리자 권한인지 체크
    try:
        if ctypes.windll.shell32.IsUserAnAdmin():
            print(f"\r\n ✅ {C.GREEN}이미 관리자 권한으로 실행 중입니다냥!{C.RESET}")
            time.sleep(1)
            return
    except Exception:
        pass

    print(f"\r\n 🛡️  {ctext('관리자 권한으로 재실행을 시도합니다냥...', C.SKY)}")
    print(f" ⚠️  {C.YELLOW}잠시 후 화면에 관리자 권한 UAC 창이 뜨면 [예]를 눌러줘냥!{C.RESET}")
    time.sleep(1.5)
    
    try:
        script = os.path.abspath(sys.argv[0])
        params = ' '.join([f'"{arg}"' for arg in sys.argv[1:]])
        
        if not params:
            params = '--admin-restart'
        else:
            params += ' --admin-restart'
            
        ret = ctypes.windll.shell32.ShellExecuteW(
            None, 
            "runas", 
            sys.executable, 
            f'"{script}" {params}', 
            os.getcwd(), 
            1
        )
        
        if int(ret) > 32:
            print(f" ✅ {C.GREEN}재실행 성공! 현재 일반 권한 창을 종료합니다냥...{C.RESET}")
            time.sleep(1)
            sys.exit(0)
        else:
            print(f" ❌ {ctext(f'재실행 실패! 에러 코드: {ret}', C.RED)}")
            time.sleep(2)
    except Exception as e:
        print(f" ❌ {ctext(f'재실행 중 오류 발생: {e}', C.RED)}")
        time.sleep(2)


# [TAG: #@_tweak_detect_hotkey_conflicts]
def _tweak_detect_hotkey_conflicts():
    """[V2.0] 단축키 충돌을 점유하고 있는 범인 프로세스(앱) 탐색 기능 (간이 스캐너 & OpenArk)"""
    import urllib.request
    import ssl
    import ctypes
    import webbrowser
    import subprocess

    dashboard("단축키 충돌 탐색 도구", "🟢 검사 방식 선택",
              "전역 단축키 충돌을 점유하고 있는 범인 프로세스(앱)를 찾는 도구입니다.")
    
    options = [
        " 🔍 1. 내 PC 단축키 도둑 용의자 검색 (초간단 진단)",
        " 🛠️ 2. OpenArk 다운로드 및 실행 (커널 정밀 분석)",
        " ❌ 3. 취소"
    ]
    sel = menu("🔎 분석 방법 선택", options)

    if sel == 0:
        # 간이 용의자 프로세스 스캔 기능
        dashboard("단축키 도둑 용의자 스캐너", "🔍 진단 중...", "윈도우 백그라운드 프로세스를 분석하여 단축키 충돌 용의자를 추적합니다.")
        print(f"\r\n ⚙️  {ctext('현재 실행 중인 윈도우 프로세스를 스캔하고 있어냥...', C.SKY, C.BOLD)}")
        
        suspects_db = {
            "igfxem.exe": "인텔 그래픽 제어 센터 (Intel Hotkey Service - 단축키 선점 악명 높음)",
            "igfkhk.exe": "인텔 그래픽 핫키 서비스 (Intel Graphics Hotkey)",
            "igfxhk.exe": "인텔 그래픽 핫키 서비스 (Intel Graphics Hotkey)",
            "radeonsoftware.exe": "AMD Radeon Software (AMD 그래픽 오버레이 단축키)",
            "amdrsserv.exe": "AMD Radeon 오버레이 서비스",
            "picpick.exe": "픽픽 (PicPick - 화면 캡처 단축키 선점 단골 앱)",
            "deepl.exe": "DeepL 번역기 데스크톱 앱 (Alt/Ctrl 단축키 점유)",
            "nvsphelper64.exe": "NVIDIA GeForce Experience 오버레이",
            "nvidia share.exe": "NVIDIA GeForce Experience 공유 기능",
            "kakaotalk.exe": "카카오톡 데스크톱 (단축키 충돌 유발 가능)",
            "discord.exe": "디스코드 (게임 오버레이 및 음소거 단축키)",
            "autohotkey.exe": "오토핫키 (AutoHotkey 매크로 스크립트)",
            "sharex.exe": "ShareX 캡처 도구",
            "xmousebuttoncontrol.exe": "X-Mouse Button Control (마우스 매핑 도구)",
            "wacomtablet.exe": "와콤 타블렛 드라이버 (단축키 매핑 관련)",
            "powertoys.exe": "Microsoft PowerToys (Keyboard Manager 단축키 재매핑)"
        }
        
        try:
            result = subprocess.run(["tasklist", "/NH", "/FO", "CSV"], capture_output=True, text=True, errors='ignore')
            lines = result.stdout.strip().split('\r\n')
            
            found_suspects = []
            for line in lines:
                if not line:
                    continue
                parts = line.split(',')
                if len(parts) > 0:
                    proc_name = parts[0].replace('"', '').lower().strip()
                    if proc_name in suspects_db:
                        found_suspects.append((proc_name, suspects_db[proc_name]))
            
            found_suspects = list(set(found_suspects))
            
            print("\r\n" + "─"*75)
            if found_suspects:
                print(f" 🚨 {ctext('단축키 강탈 의심 용의자 프로세스 감지 완료!', C.RED, C.BOLD)}")
                print("─"*75)
                print(" 현재 비누님 PC에서 작동 중인 다음 프로그램들이 단축키를 점유하고 있을 가능성이 매우 높아냥!\r\n")
                for idx, (proc, desc) in enumerate(found_suspects, 1):
                    print(f"  {idx}. {C.YELLOW}{proc}{C.RESET} ➔ {C.WHITE}{desc}{C.RESET}")
                print(f"\r\n 👉 {C.SKY}조치 방법{C.RESET}:")
                print("    1) 작업 표시줄 우측 트레이나 작업 관리자(Ctrl+Shift+Esc)에서 위 프로그램을 완전히 종료해봐냥.")
                print("    2) 또는, 해당 프로그램 내부 설정에서 '전역 단축키' 또는 '핫키' 옵션을 해제해줘냥.")
            else:
                print(f"  {C.GREEN}깨끗함! 악명 높은 단축키 도둑 용의자가 백그라운드에 감지되지 않았어냥!{C.RESET}")
                print("─"*75)
                print("  대중적인 단축키 점유 프로그램 외에 다른 독자적인 프로그램이 범인일 수 있어냥.")
                print("  더 정밀한 분석이 필요하다면 OpenArk를 사용해보거나 작업 관리자에서 수동으로 종료해보자냥!")
            print("─"*75 + "\r\n")
            
        except Exception as e:
            print(f" ❌ {ctext(f'프로세스 스캔 중 에러 발생: {e}', C.RED)}")
            
        prompt_input("\r\n 🔔 엔터를 누르면 메뉴로 돌아갑니다...")
        return

    elif sel == 1:
        # OpenArk 실행 방식
        # 1. 저장 디렉토리 설정 및 파일 경로 구성
        temp_dir = os.path.abspath("temp")
        if not os.path.exists(temp_dir):
            os.makedirs(temp_dir)
        exe_path = os.path.join(temp_dir, "OpenArk64.exe")

        # 2. 이미 파일이 존재하면 무조건 즉시 실행, 없으면 자동 다운로드
        if not (os.path.exists(exe_path) and os.path.getsize(exe_path) > 0):
            # 안전한 미러 저장소의 raw exe 다운로드 링크를 제공하여 404를 차단합니다.
            download_url = "https://github.com/c1earyy/OpenArk64/raw/main/OpenArk64.exe"
            print(f"\r\n 📥 {ctext('최신버전 OpenArk64.exe 다운로드 시작...', C.SKY, C.BOLD)}")
            print(f" 🔗 {C.DIM}{download_url}{C.RESET}\r\n")

            try:
                # SSL 경고 우회
                context = ssl._create_unverified_context()
                req = urllib.request.Request(download_url, headers={'User-Agent': 'Mozilla/5.0'})
                
                with urllib.request.urlopen(req, context=context) as response, open(exe_path, 'wb') as out_file:
                    total_size = int(response.info().get('Content-Length', 0))
                    downloaded = 0
                    block_size = 1024 * 64 # 64KB
                    
                    while True:
                        buffer = response.read(block_size)
                        if not buffer:
                            break
                        downloaded += len(buffer)
                        out_file.write(buffer)
                        if total_size > 0:
                            percent = int(downloaded * 100 / total_size)
                            print(f"\r 📥 다운로드 중: {percent}% ({downloaded}/{total_size} bytes)...", end="")
                        else:
                            print(f"\r 📥 다운로드 중: {downloaded} bytes...", end="")
                    print()
                
                print(f"\r\n ✅ {ctext('다운로드 완료!', C.GREEN)}")
            except Exception as e:
                print(f"\r\n ❌ {ctext(f'다운로드 중 오류 발생냥!: {e}', C.RED)}")
                print("    👉 깃허브 서버 상황이나 네트워크 상태를 확인해줘냥!")
                print("    👉 브라우저로 직접 다운로드받을 수 있게 공식 페이지를 열어줄게냥!")
                time.sleep(2)
                try:
                    webbrowser.open("https://github.com/c1earyy/OpenArk64")
                except:
                    pass
                prompt_input("\r\n 🔔 엔터를 누르면 메뉴로 돌아갑니다...")
                return

        # 4. 관리자 권한으로 실행
        print(f"\r\n ⚡ {ctext('관리자 권한(UAC)으로 OpenArk 실행 요청 중...', C.YELLOW)}")
        try:
            ret = ctypes.windll.shell32.ShellExecuteW(None, "runas", exe_path, None, None, 1)
            if ret > 32:
                print(f" ✅ {C.GREEN}성공적으로 OpenArk가 실행되었어!{C.RESET}")
                _log_to_file("OpenArk Execute: Success")
            else:
                print(f" ⚠️  {C.YELLOW}실행 요청이 반려되었거나 실패했을 수 있어냥! (코드: {ret}){C.RESET}")
        except Exception as e:
            print(f" ❌ {ctext(f'실행 실패: {e}', C.RED)}")
            _log_to_file(f"❌ [OpenArk Runas Error] {e}")
            prompt_input("\r\n 🔔 엔터를 누르면 메뉴로 돌아갑니다...")
            return

        # 5. 사용 방법 가이드 화면에 띄워주기
        print("\r\n" + "─"*75)
        print(f" 🕵️‍♂️ {ctext('단축키 충돌 범인(프로세스) 잡는 가이드', C.PURPLE, C.BOLD)}")
        print("─"*75)
        print(f" 1. 실행된 {C.SKY}OpenArk{C.RESET} 창의 상단 탭에서 {C.YELLOW}[Kernel]{C.RESET} 탭을 클릭합니다.")
        print(f" 2. 왼쪽 사이드 메뉴에서 {C.YELLOW}[System Hotkey]{C.RESET}를 선택합니다.")
        print(f" 3. {C.RED}[필수] 오른쪽 아래 빨간 글씨 옆의 [Enter KernelMode] 버튼{C.RESET}을 눌러 줍니다.")
        print("    (드라이버가 로드되어야 등록된 전역 단축키 목록이 표에 출력됩니다!)")
        print(f" 4. 표에서 먹통이었던 단축키(예: {C.WHITE}alt+f12{C.RESET} 등)를 검색하거나 찾습니다.")
        print(f" 5. 해당 단축키 행의 {C.GREEN}[Process]{C.RESET} 컬럼에 있는 프로그램이 범인 프로세스입니다! 🔍")
        print("─"*75)
        
        prompt_input("\r\n 🔔 엔터를 누르면 메뉴로 돌아갑니다...")
        return
    else:
        return


# [TAG: #@_tweak_file_extension_toggle]
def _tweak_file_extension_toggle():
    """파일 확장자 표시 켜기/끄기 토글"""
    while True:
        reg_path = r"Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced"
        current_val = reg_get(winreg.HKEY_CURRENT_USER, reg_path, "HideFileExt", -1)
        is_visible = (current_val == 0)

        cur_str = f"{C.GREEN}🟢 보이는 중{C.RESET}" if is_visible else f"{C.DIM}⚫ 숨겨진 상태{C.RESET}"
        dashboard("파일 확장자 표시 토글", cur_str,
                  "탐색기에서 파일 확장자(.txt, .mp4 등)를 보이게/숨기게 합니다.",
                  f"{C.CYAN}변경 후 탐색기가 자동으로 새로고침 돼!{C.RESET}")

        options = [
            f" 👁️ 확장자 보이기 🟢 {'← 현재' if is_visible else ''}",
            f" 🙈 확장자 숨기기 ⚫ {'← 현재' if not is_visible else ''}",
            " ❌ 이전 메뉴로 돌아가기"
        ]
        sel = menu("📄 파일 확장자 설정", options)
        if sel >= 2: # 뒤로 가기
            break

        res = reg_set(winreg.HKEY_CURRENT_USER, reg_path, "HideFileExt", sel, winreg.REG_DWORD) # 0=보이기, 1=숨기기
        if res is True:
            try:
                SHCNE_ASSOCCHANGED = 0x08000000
                ctypes.windll.shell32.SHChangeNotify(SHCNE_ASSOCCHANGED, 0, None, None)
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")
            state_str = "보이기" if sel == 0 else "숨기기"
            ok(f"파일 확장자를 [{state_str}]로 변경했어! ✨")
        else:
            err(f"레지스트리 변경 실패: {res}")
        pause()


# [TAG: #@_tweak_context_menu_restore]
def _tweak_context_menu_restore():
    """Win11 우클릭 메뉴 복구 (클래식) / 원복"""
    while True:
        reg_path = r"Software\Classes\CLSID\{86ca1aa0-34aa-4e8b-a509-50c905bae2a2}\InprocServer32"
        is_classic = reg_get(winreg.HKEY_CURRENT_USER, reg_path, "") is not None

        cur_str = f"{C.GREEN}🟢 클래식 메뉴 (Win10 스타일){C.RESET}" if is_classic else f"{C.DIM}⚫ 기본 메뉴 (Win11 스타일){C.RESET}"
        dashboard("우클릭 컨텍스트 메뉴 설정", cur_str,
                  "Win11의 축소된 우클릭 메뉴를 Win10 스타일로 복구/원복합니다.",
                  f"{C.GOLD}⚠️ 변경 후 탐색기가 재시작됩니다!{C.RESET}")

        options = [
            f" 🔧 클래식 메뉴로 복구 (Win10 스타일) {'← 현재' if is_classic else ''}",
            f" 🔄 기본 메뉴로 원복 (Win11 스타일) {'← 현재' if not is_classic else ''}",
            " ❌ 이전 메뉴로 돌아가기"
        ]
        sel = menu("🖱️ 우클릭 메뉴 설정", options)
        if sel >= 2: # 뒤로 가기
            break

        if sel == 0 and not is_classic:
            try:
                winreg.CreateKeyEx(winreg.HKEY_CURRENT_USER, reg_path)
                reg_set(winreg.HKEY_CURRENT_USER, reg_path, "", "", winreg.REG_SZ)
                ok("클래식 우클릭 메뉴로 변경했어! 탐색기 재시작 중...")
                restart_explorer()
                time.sleep(2)
            except Exception as e:
                err(f"변경 실패: {e}")
                pause()
        elif sel == 1 and is_classic:
            try:
                winreg.DeleteKey(winreg.HKEY_CURRENT_USER, reg_path)
                ok("Win11 기본 우클릭 메뉴로 원복했어! 탐색기 재시작 중...")
                restart_explorer()
                time.sleep(2)
            except Exception as e:
                err(f"변경 실패: {e}")
                pause()

        is_classic = reg_get(winreg.HKEY_CURRENT_USER, reg_path, "") is not None # 상태 갱신


# [TAG: #@open_terminal_action_fix]
def _tweak_open_terminal(admin=False, silent=False):
    """현재 작업 디렉토리에서 터미널(Windows Terminal 또는 cmd.exe)을 엽니다."""
    import shutil
    import ctypes
    import subprocess
    current_dir = os.getcwd()
    
    # wt.exe 존재 여부 탐색
    wt_path = shutil.which("wt.exe")
    if not wt_path:
        _local_wt = os.path.expandvars(r"%LOCALAPPDATA%\Microsoft\WindowsApps\wt.exe")
        if os.path.exists(_local_wt):
            wt_path = _local_wt
            
    success = False
    term_name = "Windows Terminal" if wt_path else "명령 프롬프트(cmd.exe)"
    admin_suffix = " (관리자)" if admin else ""
    
    # 현재 실행 권한 체크
    try:
        is_app_admin = bool(ctypes.windll.shell32.IsUserAnAdmin())
    except:
        is_app_admin = False
        
    try:
        if admin:
            # 관리자 권한으로 Windows Terminal 또는 cmd.exe 실행
            exe = wt_path if wt_path else "cmd.exe"
            args = f'-d "{current_dir}"' if wt_path else None
            ret = ctypes.windll.shell32.ShellExecuteW(None, "runas", exe, args, current_dir, 1)
            success = (ret > 32)
        else:
            # 일반 권한으로 실행
            if is_app_admin:
                # 현재 앱이 이미 관리자 권한이면, 탐색기(Shell.Application) COM 객체 경유 PowerShell 트릭을 사용하여 
                # 일반 권한으로 프로세스를 강제 실행합니다.
                exe = wt_path if wt_path else "cmd.exe"
                args = f'-d \"{current_dir}\"' if wt_path else ""
                
                ps_cmd = f'''powershell -NoProfile -Command "(New-Object -ComObject Shell.Application).ShellExecute('{exe}', '{args}', '{current_dir}', 'open', 1)"'''
                subprocess.Popen(ps_cmd, shell=True)
                success = True
            else:
                # 앱이 일반 권한 상태면 그냥 상속하여 팝업
                if wt_path:
                    subprocess.Popen([wt_path, "-d", current_dir])
                else:
                    ctypes.windll.shell32.ShellExecuteW(None, "open", "cmd.exe", None, current_dir, 1)
                success = True
    except Exception as e:
        if not silent:
            print(f"\r\n ❌ {ctext(f'터미널 열기 실패냥... {e}', C.RED)}")
            time.sleep(1.5)
        return False

    if success:
        if not silent:
            print(f"\r\n ✅ {ctext(f'현재 위치({current_dir})에서 {term_name}{admin_suffix} 창을 열었어냥! 💻✨', C.GREEN)}")
            time.sleep(1.5)
    else:
        if not silent:
            print(f"\r\n ⚠️ {ctext('터미널 실행이 취소되었거나 실패했어냥!', C.YELLOW)}")
            time.sleep(1.5)
    return success


# [TAG: #@_tweak_win_terminal_setup]
def _tweak_win_terminal_setup():
    """Windows Terminal 설치 및 기본 터미널 자동 설정 (One-Click)"""
    while True:
        wt_path = shutil.which("wt")
        is_installed = wt_path is not None
        
        # 1. 기본 터미널 위임 상태 체크 🔍
        reg_path = r"Console\%%Startup"
        is_default = False
        try:
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, reg_path) as k:
                val, _ = winreg.QueryValueEx(k, "DelegationTerminal")
                if val == "{E12CFF52-A866-4C77-9A90-F570A7AA2C6B}":
                    is_default = True
        except: pass

        # 2. .py 파일 연결 상태 체크 (강제 WT 모드 여부) 🔍
        py_reg_path = r"Software\Classes\Python.File\shell\open\command"
        is_py_wt = False
        try:
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, py_reg_path) as k:
                val, _ = winreg.QueryValueEx(k, "")
                if "wt.exe" in val.lower():
                    is_py_wt = True
        except: pass

        cur_status = f"{C.GREEN}🟢 설정됨{C.RESET}" if is_default else f"{C.YELLOW}🟡 호스트 선택{C.RESET}"
        py_status = f"{C.GREEN}🚀 WT 직행{C.RESET}" if is_py_wt else f"{C.YELLOW}🐌 일반(conhost){C.RESET}"
        inst_status = f"{C.GREEN}🟢 설치됨{C.RESET}" if is_installed else f"{C.RED}⚫ 미설치{C.RESET}"

        dashboard("Windows Terminal 완전 자동 설정", 
                  f"기본: {cur_status} / .py연결: {py_status} / 설치: {inst_status}",
                  "클릭 한 번으로 설치부터 기본 터미널 고정까지 완료합니다!",
                  ["앱 실행 시 '두 번 뜨는 현상'을 해결하는 가장 빠른 방법냥! ✨",
                   "🚀 .py 직행 모드: 더블클릭 시 conhost 없이 바로 WT가 뜹니다! 👍"])

        options = []
        if not is_installed:
            options.append(f" 🚀 {C.BOLD}{C.SKY}Windows Terminal 자동 설치 및 기본값 설정{C.RESET}")
        else:
            options.append(f" 🔧 {C.BOLD}{C.SKY}Windows Terminal을 '기본 터미널'로 즉시 설정{C.RESET}")
            
        options.append(f" 🚀 {C.BOLD}{C.GREEN}.py 파일 실행 시 Windows Terminal 강제 사용 (강력 추천){C.RESET}")
        options.append(" 🔄 모든 설정 초기화 (기본 파이썬 런처/호스트 복구)")
        options.append(" ❌ 이전 메뉴로 돌아가기")

        sel = menu("💻 Terminal Automation", options)
        if sel == len(options) - 1: break # 돌아가기

        if sel == 0: # 설치 및 설정 (또는 그냥 설정)
            if not is_installed:
                print(f"\r\n ⏳ {ctext('1단계: Windows Terminal 설치 중... (winget)', C.CYAN)}")
                res = subprocess.run(["winget", "install", "--id", "Microsoft.WindowsTerminal", "-e", "--accept-source-agreements", "--accept-package-agreements"], capture_output=True, text=True)
                if res.returncode != 0 and "already installed" not in res.stdout.lower():
                    err("설치 중에 문제가 발생했어냥... 직접 설치가 필요할 것 같아.")
                    pause(); continue
                ok("1단계: 설치 완료! ✨")
                time.sleep(1)

            print(f" ⏳ {ctext('2단계: 기본 터미널 레지스트리 설정 중...', C.CYAN)}")
            try:
                with winreg.CreateKeyEx(winreg.HKEY_CURRENT_USER, reg_path) as k:
                    winreg.SetValueEx(k, "DelegationConsole", 0, winreg.REG_SZ, "{2EACA947-7F5F-4CFA-BA87-8F7FBEEFBE69}")
                    winreg.SetValueEx(k, "DelegationTerminal", 0, winreg.REG_SZ, "{E12CFF52-A866-4C77-9A90-F570A7AA2C6B}")
                ok("모든 설정 완료! 🎉 이제 앱을 다시 켜면 윈도우 터미널로 바로 뜰 거야냥! 🐾✨")
            except Exception as e:
                err(f"2단계 실패냥... (권한 확인 필요): {e}")
            pause()
        
        elif sel == 1: # .py WT 강제 모드
            if not is_installed:
                err("먼저 Windows Terminal을 설치해야 해냥! ㅠㅠ"); pause(); continue
            
            print(f"\r\n ⏳ {ctext('.py 파일 연결을 Windows Terminal로 직행하도록 수정 중...', C.CYAN)}")
            try:
                # HKCU\Software\Classes\Python.File\shell\open\command 수정
                # 기존 py.exe 경로를 찾아서 앞에 wt.exe를 붙여줌냥!
                # [V141.50] --_wt_relaunched 플래그를 미리 넣어서 중복 재시작 방지! 🕵️‍♂️✨
                default_cmd = r'"C:\Windows\py.exe" "%L" %*'
                try:
                    with winreg.OpenKey(winreg.HKEY_CLASSES_ROOT, r"Python.File\shell\open\command") as k:
                        default_cmd, _ = winreg.QueryValueEx(k, "")
                except: pass
                
                # wt.exe가 이미 있으면 중복 방지, 없으면 추가
                if "wt.exe" not in default_cmd.lower():
                    # %* 앞에 플래그 삽입
                    if "%*" in default_cmd:
                        new_cmd = f'wt.exe {default_cmd.replace("%*", "--_wt_relaunched %*")}'
                    else:
                        new_cmd = f'wt.exe {default_cmd} --_wt_relaunched'
                else:
                    new_cmd = default_cmd
                    if "--_wt_relaunched" not in new_cmd:
                        new_cmd = new_cmd.replace("%*", "--_wt_relaunched %*")

                with winreg.CreateKeyEx(winreg.HKEY_CURRENT_USER, py_reg_path) as k:
                    winreg.SetValueEx(k, "", 0, winreg.REG_SZ, new_cmd)
                ok(".py 파일 직행 설정 완료! 🎉 이제 더블클릭하면 바로 WT가 열릴 거야냥! 🐾✨")
            except Exception as e:
                err(f"설정 실패: {e}"); pause()
            pause()

        elif sel == 2: # 모든 설정 초기화
            print(f"\r\n ⏳ {ctext('터미널 및 .py 연결 설정을 초기화 중...', C.CYAN)}")
            try:
                # 1. 기본 터미널 위임 삭제
                try:
                    with winreg.OpenKey(winreg.HKEY_CURRENT_USER, reg_path, 0, winreg.KEY_SET_VALUE | winreg.KEY_WRITE) as k:
                        try: winreg.DeleteValue(k, "DelegationConsole")
                        except: pass
                        try: winreg.DeleteValue(k, "DelegationTerminal")
                        except: pass
                except: pass
                
                # 2. .py HKCU 오버라이드 삭제 (HKCR 기본값으로 돌아감)
                try:
                    # 키 전체 삭제
                    winreg.DeleteKey(winreg.HKEY_CURRENT_USER, py_reg_path)
                    # 상위 폴더들도 비어있으면 정리 (Python.File 등)
                    parent = r"Software\Classes\Python.File\shell\open"
                    try: winreg.DeleteKey(winreg.HKEY_CURRENT_USER, parent)
                    except: pass
                except: pass
                
                ok("모든 설정을 기본값으로 복구했어냥! 🧼")
            except Exception as e:
                err(f"복구 중 일부 오류 (이미 초기화되었을 수 있음): {e}")
            pause()


# [TAG: #@_tweak_show_mypc_icon]
def _tweak_show_mypc_icon():
    """바탕화면에 '내 PC' 아이콘 표시/숨기기"""
    while True:
        reg_path = r"Software\Microsoft\Windows\CurrentVersion\Explorer\HideDesktopIcons\NewStartPanel"  # fix unicode issue
        mypc_guid = "{20D04FE0-3AEA-1069-A2D8-08002B30309D}"
        is_visible = (reg_get(winreg.HKEY_CURRENT_USER, reg_path, mypc_guid, -1) == 0)

        cur_str = f"{C.GREEN}🟢 보이는 중{C.RESET}" if is_visible else f"{C.DIM}⚫ 숨겨진 상태{C.RESET}"
        dashboard("내 PC 아이콘 설정", cur_str, "바탕화면에 '내 PC' 아이콘을 보이게/숨기게 합니다.")

        options = [
            f" 🖥️ 내 PC 아이콘 보이기 {'← 현재' if is_visible else ''}",
            f" 🙈 내 PC 아이콘 숨기기 {'← 현재' if not is_visible else ''}",
            " ❌ 이전 메뉴로 돌아가기"
        ]
        sel = menu("💻 내 PC 아이콘", options)
        if sel >= 2: # 뒤로 가기
            break

        new_val = 0 if sel == 0 else 1
        res = reg_set(winreg.HKEY_CURRENT_USER, reg_path, mypc_guid, new_val, winreg.REG_DWORD)
        if res is True:
            state_str = "보이기" if sel == 0 else "숨기기"
            ok(f"내 PC 아이콘을 [{state_str}]로 변경했어! ✨\r\n    {C.DIM}바탕화면을 새로고침(F5)하면 반영돼!{C.RESET}")
        else:
            err(f"레지스트리 변경 실패: {res}")
        pause()


# [TAG: #@_tweak_win_update_pause]
def _tweak_win_update_pause():
    """윈도우 업데이트 일시중단 / 재개"""
    while True:
        result = subprocess.run(["sc", "query", "wuauserv"], capture_output=True, text=True)
        is_running = "RUNNING" in result.stdout if result.returncode == 0 else True

        cur_str = f"{C.GREEN}🟢 업데이트 활성{C.RESET}" if is_running else f"{C.GOLD}⏸️ 업데이트 일시중단{C.RESET}"
        dashboard("윈도우 업데이트 제어", cur_str,
                  "Windows Update 서비스를 일시중단하거나 재개합니다.",
                  f"{C.RED}⚠️ 관리자 권한이 필요합니다!{C.RESET}")

        options = [
            f" ⏸️ 업데이트 일시중단 {'← 현재' if not is_running else ''}",
            f" ▶️ 업데이트 재개 {'← 현재' if is_running else ''}",
            " ❌ 이전 메뉴로 돌아가기"
        ]
        sel = menu("🔄 윈도우 업데이트", options)
        if sel >= 2: # 뒤로 가기
            break

        if sel == 0:
            subprocess.run(["net", "stop", "wuauserv"], capture_output=True)
            run_cmd(["sc", "config", "wuauserv", "start=", "disabled"],
                    ok_msg="윈도우 업데이트 서비스를 일시중단했어! ⏸️",
                    fail_msg="실패 (관리자 권한 필요)")
            pause()
        elif sel == 1:
            subprocess.run(["sc", "config", "wuauserv", "start=", "auto"], capture_output=True)
            run_cmd(["net", "start", "wuauserv"],
                    ok_msg="윈도우 업데이트 서비스를 재개했어! ▶️",
                    fail_msg="실패 (관리자 권한 필요)")
            pause()


# [TAG: #@_tweak_auto_login]
def _tweak_auto_login():
    """윈도우 자동 로그인 설정 / 해제"""
    while True:
        reg_path = r"SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon"
        auto_val = reg_get(winreg.HKEY_LOCAL_MACHINE, reg_path, "AutoAdminLogon", "0")
        is_auto = (auto_val == "1")
        username = reg_get(winreg.HKEY_LOCAL_MACHINE, reg_path, "DefaultUserName", "")

        cur_str = f"{C.GREEN}🟢 자동 로그인 ON ({username}){C.RESET}" if is_auto else f"{C.DIM}⚫ 수동 로그인{C.RESET}"
        dashboard("윈도우 자동 로그인 설정", cur_str,
                  "부팅 시 비밀번호 입력 없이 자동으로 로그인합니다.",
                  f"{C.RED}⚠️ 관리자 권한 필요! 비밀번호가 레지스트리에 평문 저장됩니다.{C.RESET}")

        options = [
            " 🔓 자동 로그인 설정",
            " 🔒 자동 로그인 해제",
            " ❌ 이전 메뉴로 돌아가기"
        ]
        sel = menu("🔑 자동 로그인", options)
        if sel >= 2: # 뒤로 가기
            break

        if sel == 0:  # 설정
            usr = prompt_input(f"\r\n 👤 사용자 이름 (기본: {os.getlogin()}): ").strip() or os.getlogin()
            pwd = prompt_input(" 🔑 비밀번호 (빈칸=비밀번호 없음): ").strip()

            try:
                with winreg.CreateKeyEx(winreg.HKEY_LOCAL_MACHINE, reg_path, 0, winreg.KEY_ALL_ACCESS) as k:
                    winreg.SetValueEx(k, "AutoAdminLogon", 0, winreg.REG_SZ, "1")
                    winreg.SetValueEx(k, "DefaultUserName", 0, winreg.REG_SZ, usr)
                    winreg.SetValueEx(k, "DefaultPassword", 0, winreg.REG_SZ, pwd)
                ok(f"자동 로그인 설정 완료! (사용자: {usr}) ✨")
            except Exception as e:
                err(f"설정 실패: {e} (관리자 권한 필요)")
            pause()
        elif sel == 1:  # 해제
            try:
                with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, reg_path, 0, winreg.KEY_ALL_ACCESS) as k:
                    winreg.SetValueEx(k, "AutoAdminLogon", 0, winreg.REG_SZ, "0")
                    try: winreg.DeleteValue(k, "DefaultPassword")
                    except FileNotFoundError: pass
                ok("자동 로그인을 해제했어! 🔒")
            except Exception as e:
                err(f"해제 실패: {e} (관리자 권한 필요)")
            pause()


# [TAG: #@_tweak_telegram_boot_notify]
def _tweak_telegram_boot_notify(settings):
    """부팅 시 텔레그램 메시지 발송 설정 [VBS 방식 (한글 보정)]"""
    token = settings.data.get('telegram_token', '')
    chat_id = settings.data.get('telegram_chat_id', '')
    has_config = token and chat_id

    task_name = "Binu_BootNotify_Telegram"
    vbs_path = os.path.join(tempfile.gettempdir(), "_boot_telegram_notify.vbs")
    ps1_path = vbs_path.replace(".vbs", ".ps1") # 구버전 청소용

    # [신규] 시작프로그램 폴더 경로 (일반 권한용)
    startup_dir = os.path.join(os.getenv('APPDATA', ''), r"Microsoft\Windows\Start Menu\Programs\Startup")
    vbs_startup_path = os.path.join(startup_dir, "Binu_BootNotify.vbs")

    while True:
        # 실시간 상태 체크 (시작프로그램 폴더 내 파일 존재 여부)
        is_reg = os.path.exists(vbs_startup_path)
        reg_str = f"{C.GREEN}등록됨 (ON 🟢){C.RESET}" if is_reg else f"{C.DIM}미등록 (OFF ⚫){C.RESET}"

        dashboard("부팅 시 텔레그램 알림 (VBS)", reg_str,
                  "컴퓨터가 켜질 때마다 텔레그램으로 부팅 성공 메시지를 보냅니다.",
                  ["시작프로그램(Startup) 폴더에 등록되어 일반 권한으로 작동합니다.",
                   "전용 VBS 스크립트가 백그라운드에서 실행됩니다."])

        options = [
            " 📨 부팅 알림 등록 (VBS 설정/갱신)",
            " 🧪 알람 테스트 (즉시 발송)",
            " 🗑️ 부팅 알림 해제",
            " 📂 시작프로그램 폴더 열기",
            " ❌ 이전 메뉴로 돌아가기"
        ]
        sel = menu("📱 부팅 텔레그램 알림", options)
        if sel >= 4: # 뒤로 가기
            break

        if sel == 0:
            if not has_config:
                print(f"\r\n ⚠️ {ctext('먼저 텔레그램 봇 설정에서 토큰과 Chat ID를 설정해줘!', C.YELLOW)}")
                pause(sec=2)
                continue

            hostname = os.environ.get("COMPUTERNAME", "Unknown-PC")
            # VBS 기반 알림 스크립트 (XMLHTTP 사용)
            # [중요] 한글 깨짐 방지를 위해 인코딩을 cp949로 저장해야 함
            vbs_content = f"""
' Binu Boot Notification (Matched to User's Working POST Snippet)
Dim botToken, chatId, hostname, msg, url, data, http, arg, skip_delay

' Check for /now argument
skip_delay = False
For Each arg In WScript.Arguments
    If LCase(arg) = "/now" Then skip_delay = True
Next

If Not skip_delay Then WScript.Sleep 15000

botToken = "{token}"
chatId = "{chat_id}"
hostname = "{hostname}"

msg = "PC Booted: [" & hostname & "] at " & Now

url = "https://api.telegram.org/bot" & botToken & "/sendMessage"
data = "chat_id=" & chatId & "&text=" & msg

On Error Resume Next
Set http = CreateObject("MSXML2.XMLHTTP")
http.open "POST", url, False
http.setRequestHeader "Content-Type", "application/x-www-form-urlencoded"
http.send data
""".strip()
            try:
                # [중요] 한글 깨짐 방지를 위해 cp949 (ANSI)로 저장
                with open(vbs_startup_path, "w", encoding="cp949", errors="replace") as f:
                    f.write(vbs_content)

                ok("부팅 시 텔레그램 알림 등록 완료! ✨\r\n(시작프로그램 폴더에 등록되었어)")

                # [청소] 혹시 기존에 스케줄러(관리자 권한 방식)로 등록된 게 있다면 삭제 시도
                subprocess.run(['schtasks', '/Delete', '/TN', task_name, '/F'], capture_output=True, shell=True)
                if os.path.exists(vbs_path):
                    try: os.remove(vbs_path)
                    except Exception as e:
                        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                        if "6" not in str(e):
                            _log_to_file(f"⚠️ [Silent Exception] {e}")
                if os.path.exists(ps1_path):
                    try: os.remove(ps1_path)
                    except Exception as e:
                        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                        if "6" not in str(e):
                            _log_to_file(f"⚠️ [Silent Exception] {e}")
            except PermissionError:
                err("\r\n ⚠️ 권한 오류가 발생했어! (Permission Denied)\r\n")
                print(f" 1. {C.YELLOW}백신(Avast 등)이 파일을 잠그고 있을 확률이 높아.{C.RESET}")
                print(" 2. 시작프로그램 폴더에서 'Binu_BootNotify.vbs'를 수동으로 지워보거나,")
                print(" 3. 백신에서 이 프로그램을 '예외'로 등록해줘! 🛡️")
            except Exception as e:
                err(f"오류: {e}")
            pause(sec=2)

        elif sel == 1: # 테스트 발송
            if not os.path.exists(vbs_startup_path):
                err("먼저 '알림 등록'을 해서 스크립트 파일을 생성해줘! ❌")
            else:
                ok("테스트 메시지를 발송합니다... 📤")
                # /now 인자를 주어 지연 없이 즉시 발송하게 함
                run_cmd(f'wscript.exe "{vbs_startup_path}" /now', shell=True, ok_msg="발송 명령 전송 완료! 텔레그램을 확인해봐! 📱")
            pause()

        elif sel == 2: # 해제
            if os.path.exists(vbs_startup_path):
                try:
                    os.remove(vbs_startup_path)
                    ok("부팅 알림을 해제했어! 🗑️")
                except Exception as e:
                    err(f"해제 실패: {e}")
            else:
                ok("이미 해제되어 있거나 등록된 파일이 없어.")

            # [청소] 기존 스케줄러 방식도 함께 삭제 시도
            subprocess.run(['schtasks', '/Delete', '/TN', task_name, '/F'], capture_output=True, shell=True)
            pause()

        elif sel == 3: # 시작프로그램 폴더 열기
            startup_dir = os.path.join(os.getenv('APPDATA', ''), 'Microsoft\\Windows\\Start Menu\\Programs\\Startup')
            if os.path.exists(startup_dir):
                os.startfile(startup_dir)
                ok(f"시작프로그램 폴더를 열었어! 📁\r\n{C.DIM}({startup_dir}){C.RESET}")
            else:
                err("시작프로그램 폴더를 찾을 수 없어! ❌")
            pause()


# [TAG: #@_tweak_ime_toggle]
def _tweak_ime_toggle():
    """한글 입력기 2벌식 ↔ 3벌식 토글"""
    reg_targets = [
        (r"Software\Microsoft\IME\15.0\IMEKR", "InputMethod"),
        (r"Software\Microsoft\InputMethod\Settings\kor", "InputType")
    ]

    while True:
        val = 0
        for path, value_name in reg_targets:
            res = reg_get(winreg.HKEY_CURRENT_USER, path, value_name)
            if res is not None:
                val = res
                break

        ime_names = {0: "2벌식 표준", 1: "3벌식 390", 2: "3벌식 최종"}
        cur_name = ime_names.get(val, f"알 수 없는 값({val})")
        cur_str = f"{C.CYAN}{cur_name}{C.RESET}"

        dashboard("한글 입력기 변환", cur_str, "한글 입력 방식을 2벌식/3벌식 간에 전환합니다.")

        options = [
            f" ⌨️ 2벌식 표준 {'← 현재' if val == 0 else ''}",
            f" ⌨️ 3벌식 390 {'← 현재' if val == 1 else ''}",
            f" ⌨️ 3벌식 최종 {'← 현재' if val == 2 else ''}",
            " 📝 타자 연습 (입력 테스트)",
            " ⚙️ 윈도우 한글 입력기 설정 열기",
            " ❌ 취소 / 뒤로가기"
        ]
        sel = menu("⌨️ 한글 입력기 변경", options)

        if sel < 3:
            success = False
            for path, value_name in reg_targets:
                if reg_set(winreg.HKEY_CURRENT_USER, path, value_name, sel, winreg.REG_DWORD) is True:
                    success = True

            if success:
                try: ctypes.windll.user32.SendMessageTimeoutW(0xFFFF, 0x001A, 0, "intl", 0x0002, 3000, ctypes.byref(ctypes.c_size_t()))
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")

                ok(f"한글 입력기를 [{ime_names[sel]}]로 변경했어! ⌨️\r\n    {C.DIM}시스템에 반영 신호를 보냈어! (메모장 등 다른 앱을 클릭해보면 확인 가능해){C.RESET}")
            else:
                err("변경 실패")
            pause()
        elif sel == 3:  # 타자 연습
            print(f"\r\n 💡 {C.CYAN}아무 글자나 자유롭게 입력해봐! (엔터 키만 누르면 이전 메뉴로 돌아가) {C.RESET}")
            print(f"    {C.DIM}※ 현재 검은 화면(콘솔) 안에서는 윈도우 특성상 즉시 안 바뀔 수도 있어! ※{C.RESET}")
            print(f"    {C.DIM}※ 그럴 땐 메모장이나 웹브라우저 창을 띄워서 쳐보면 바뀐 걸 알 수 있을 거야 💕 ※{C.RESET}")
            while True:
                if not prompt_input(f" {C.CYAN}▶{C.RESET} ").strip(): break
        elif sel == 4:
            ok("윈도우 한글 입력기 설정 창을 띄울게! 🚀\r\n    창이 뜨면 하단의 '하드웨어 키보드 레이아웃' 등에서 세벌식을 직접 확인할 수 있어!")
            open_settings("ms-settings:regionlanguage-korime")
            pause()
        else:
            break


# [TAG: #@_get_external_ip]

def _get_external_ip__REMOVE_TARGET():
    """[DuckDNS] 공인 IP를 안전하게 감지냥! 🌐"""
    urls = [
        "https://api.ipify.org",
        "https://ipinfo.io/ip",
        "https://icanhazip.com"
    ]
    import urllib.request
    import ssl
    ctx = ssl.create_default_context()
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE
    
    for url in urls:
        try:
            req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
            with urllib.request.urlopen(req, context=ctx, timeout=5) as resp:
                ip = resp.read().decode('utf-8').strip()
                if ip:
                    parts = ip.split('.')
                    if len(parts) == 4 and all(p.isdigit() and 0 <= int(p) <= 255 for p in parts):
                        return ip
        except Exception as e:
            _log_to_file(f"⚠️ [DuckDNS IP Check] Failed to get IP from {url}: {e}")
    return None

# [TAG: #@_update_duckdns]

def _update_duckdns(domain, token, ip=None):
    """[DuckDNS] API를 호출하여 도메인 정보를 갱신냥! 📤 (도메인 풀네임에서 서브도메인만 자동 추출)"""
    import urllib.request
    import ssl
    ctx = ssl.create_default_context()
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE
    
    # 전체 도메인 형태(example.duckdns.org)에서 API 호출용 서브도메인(example)만 파싱
    subdomain = domain.strip()
    if subdomain.endswith(".duckdns.org"):
        subdomain = subdomain[:-12]
        
    ip_param = ip if ip else ""
    url = f"https://www.duckdns.org/update?domains={subdomain}&token={token}&ip={ip_param}"
    try:
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        with urllib.request.urlopen(req, context=ctx, timeout=10) as resp:
            content = resp.read().decode('utf-8').strip()
            return content == "OK", content
    except Exception as e:
        return False, str(e)

# [TAG: #@_get_wifi_info]

def _get_wifi_info():
    """[DuckDNS] 현재 연결된 와이파이 상태와 SSID를 감지냥! 📶 (오감지 버그 픽스 완료)"""
    try:
        import subprocess
        res = subprocess.run(["netsh", "wlan", "show", "interfaces"], capture_output=True, text=True, errors="replace", shell=True)
        out = res.stdout
        state = None
        ssid = None
        
        for line in out.splitlines():
            line_str = line.strip()
            if ":" in line_str:
                parts = line_str.split(":", 1)
                key = parts[0].strip().lower()
                val = parts[1].strip()
                if key in ("state", "상태"):
                    state = val.lower()
                elif key in ("ssid", "프로필", "profile"):
                    if key == "ssid":
                        ssid = val
                    elif not ssid:
                        ssid = val
        
        is_connected = False
        if state:
            # '연결 안 됨' 이나 'disconnected' 와 같은 제외 조건 우선 필터링
            if "안" in state or "disconnect" in state:
                is_connected = False
            elif state in ("connected", "연결됨"):
                is_connected = True
            elif "connected" in state or "연결됨" in state:
                is_connected = True
                
        # 2중 안전장치: 연결되었다고 판단되더라도 SSID가 비어 있거나 없으면 실제론 연결 안 된 것임
        if is_connected and (not ssid or ssid.strip() == ""):
            is_connected = False
            
        return is_connected, ssid
    except Exception as e:
        _log_to_file(f"⚠️ [_get_wifi_info] Error: {e}")
        return False, None

# [TAG: #@_get_default_gateway]

def _get_default_gateway__REMOVE_TARGET():
    """[DuckDNS] 현재 PC의 기본 게이트웨이(Default Gateway) IP를 파싱냥! 🌐"""
    import subprocess
    try:
        res = subprocess.run(["ipconfig"], capture_output=True, text=True, errors="replace", shell=True)
        out = res.stdout
        for line in out.splitlines():
            if "Default Gateway" in line or "기본 게이트웨이" in line:
                parts = line.split(":")
                if len(parts) > 1:
                    gw = parts[1].strip()
                    if gw and not gw.startswith("fe80"):  # IPv6 링크 로컬 주소 제외냥
                        return gw
    except Exception:
        pass
    return None

# [TAG: #@_get_current_wlan_bssid]

def _get_current_wlan_bssid():
    """[DuckDNS] 현재 연결된 무선 AP의 BSSID(물리 MAC 주소)를 파싱냥! 📶"""
    import subprocess
    try:
        res = subprocess.run(["netsh", "wlan", "show", "interfaces"], capture_output=True, text=True, errors="replace", shell=True)
        out = res.stdout
        for line in out.splitlines():
            line_str = line.strip()
            if ":" in line_str:
                parts = line_str.split(":", 1)
                key = parts[0].strip().lower()
                val = parts[1].strip()
                if key in ("bssid", "bssid 주소"):
                    return val
    except Exception:
        pass
    return None

# [TAG: #@_is_physically_hotspot]

def _is_physically_hotspot():
    """[DuckDNS] 물리적 특성(LAA 가상 MAC + 모바일 게이트웨이 IP 대역)으로 핫스팟 여부를 판별냥! 📱 (SSID 키워드 매칭은 완전히 제외)"""
    # 1. 디폴트 게이트웨이 IP 대역 대조
    gw_ip = _get_default_gateway()
    if gw_ip:
        # iOS: 172.20.10.X | Android: 192.168.43.X, 192.168.225.X | Windows ICS: 192.168.137.X, 192.168.173.X
        for prefix in ("172.20.10.", "192.168.43.", "192.168.225.", "192.168.137.", "192.168.173."):
            if gw_ip.startswith(prefix):
                return True, f"핫스팟 고유 게이트웨이 IP 감지 ({gw_ip})"
                
    # 2. BSSID의 LAA(Locally Administered Address) 가상 MAC 주소 여부 검사 (x2:xx, x6:xx, xa:xx, xe:xx)
    bssid = _get_current_wlan_bssid()
    if bssid:
        bssid_clean = bssid.replace("-", ":").strip().lower()
        parts = bssid_clean.split(":")
        if parts:
            first_byte = parts[0]
            if len(first_byte) == 2:
                second_char = first_byte[1]
                if second_char in ("2", "6", "a", "e"):
                    return True, f"가상(LAA) MAC 주소 감지 ({bssid_clean})"
                    
    return False, None

# [TAG: #@_is_update_blocked_by_network]

def _is_update_blocked_by_network(settings):
    """[DuckDNS] 현재 네트워크 상황에 따라 업데이트가 차단(제외)되어야 하는지 판단냥! 📶 (물리 핫스팟 엔진 융합)"""
    exclude_wifi = settings.data.get("duckdns_exclude_wifi", False)
    exclude_hotspot = settings.data.get("duckdns_exclude_hotspot", False)
    exclude_public_ip = settings.data.get("duckdns_exclude_public_ip", False)
    allowed_ssids = settings.data.get("duckdns_allowed_ssids", [])
    
    # [V162.0] 공인 IP 직접 사용시 업데이트 제외 기능 🌐
    if exclude_public_ip:
        if _is_using_public_ip_directly():
            return True, "공인 IP 직접 사용 중 (사설 공유기 내부망이 아님) [공인 IP 제외 설정 켜짐]"
            
    is_connected, ssid = _get_wifi_info()
    if not is_connected:
        return False, None
        
    if exclude_wifi:
        return True, f"Wi-Fi 연결 사용 중 (SSID: {ssid}) [Wi-Fi 제외 설정 켜짐]"
        
    if exclude_hotspot:
        is_physical, reason = _is_physically_hotspot()
        if is_physical:
            return True, f"핫스팟/모바일 데이터 연결 사용 중 (SSID: {ssid}) [{reason}]"
            
    if allowed_ssids:
        if ssid not in allowed_ssids:
            return True, f"허용되지 않은 Wi-Fi 연결 사용 중 (SSID: {ssid}) [허용 목록에 없음]"
            
    return False, None

# [TAG: #@_check_and_update_duckdns_on_startup]

def _check_and_update_duckdns_on_startup(settings):
    """[DuckDNS] 앱 시작 시 1회 체크하여 IP가 바뀌었다면 Duck DNS 업데이트냥! 🔄"""
    import sys
    # 보조 인스턴스에서는 스킵
    if '--secondary' in sys.argv:
        return
        
    enabled = settings.data.get("duckdns_auto_update", False)
    if not enabled:
        return
        
    # 네트워크 제외 조건 검사
    is_blocked, reason = _is_update_blocked_by_network(settings)
    if is_blocked:
        _log_to_file(f"ℹ️ [DuckDNS Startup] Update skipped: {reason}")
        return

    domain = settings.data.get("duckdns_domain", "").strip()
    token = settings.data.get("duckdns_token", "").strip()
    
    if not domain or not token:
        _log_to_file("⚠️ [DuckDNS Startup] Auto update enabled but domain or token is missing.")
        return
        
    _log_to_file("🌐 [DuckDNS Startup] Checking external IP...")
    current_ip = _get_external_ip()
    if not current_ip:
        _log_to_file("⚠️ [DuckDNS Startup] Failed to retrieve current external IP.")
        return
        
    last_ip = settings.data.get("duckdns_last_ip", "").strip()
    if current_ip == last_ip:
        _log_to_file(f"ℹ️ [DuckDNS Startup] IP not changed ({current_ip}). Update skipped.")
        return
        
    _log_to_file(f"🔄 [DuckDNS Startup] IP changed ({last_ip} -> {current_ip}). Updating Duck DNS...")
    success, res_msg = _update_duckdns(domain, token, current_ip)
    if success:
        _log_to_file(f"✅ [DuckDNS Startup] Update success. IP registered: {current_ip}")
        settings.data["duckdns_last_ip"] = current_ip
        settings.save()
    else:
        _log_to_file(f"❌ [DuckDNS Startup] Update failed: {res_msg}")

# [TAG: #@_tweak_duckdns_setup]

def _tweak_duckdns_setup(settings):
    try:
        return _tweak_duckdns_setup_body(settings)
    except UserAbortException:
        return

def _tweak_duckdns_setup_body(settings):
    """[DuckDNS & Tailscale] TUI 기반 설정 입력 및 네트워크 제외 관리 메뉴냥! 🦆🔌"""
    try:
        return _tweak_duckdns_setup_inner(settings)
    except UserAbortException:
        return

def _tweak_duckdns_setup_inner(settings):
    cached_current_ip = None
    cached_dns_ip = None
    
    def refresh_ips(domain_str):
        nonlocal cached_current_ip, cached_dns_ip
        import socket
        cached_current_ip = _get_external_ip()
        
        if domain_str:
            full_domain = domain_str.strip()
            if not full_domain.endswith(".duckdns.org"):
                full_domain = full_domain + ".duckdns.org"
            try:
                cached_dns_ip = socket.gethostbyname(full_domain)
            except Exception:
                cached_dns_ip = None
        else:
            cached_dns_ip = None

    # 엔터 키를 입력받아 화면 대기를 유지해주는 TUI 헬퍼
    def _wait_enter():
        prompt_input("\n 🐾 계속하려면 엔터(Enter) 키를 누르세요냥... ")

    # 서브메뉴 최초 진입 시 IP 1회 자동 로딩
    initial_domain = settings.data.get("duckdns_domain", "")
    refresh_ips(initial_domain)

    # Tailscale 세부 옵션 기동(Up) 서브메뉴
    def _tailscale_up_submenu():
        while True:
            # 설정 상태 읽기
            ts_ssh = settings.data.get("tailscale_ssh_enabled", False)
            ts_exit_adv = settings.data.get("tailscale_exit_node_advertised", False)
            ts_exit_used = settings.data.get("tailscale_exit_node_used_ip", "")
            ts_routes_adv = settings.data.get("tailscale_routes_advertised", "")
            
            label_ssh = "🟢 활성" if ts_ssh else "🔴 비활성"
            label_exit_adv = "🟢 활성" if ts_exit_adv else "🔴 비활성"
            label_exit_used = f"🟢 사용 ({ts_exit_used})" if ts_exit_used else "🔴 미사용"
            label_routes = f"🟢 노출 ({ts_routes_adv})" if ts_routes_adv else "🔴 미노출"
            
            sub_menu = [
                구분선("연결 & 원격 접속"),
                " 1. ⚡ 기본 연결 실행 (추가 옵션 없이 Tailscale 연결)",
                f" 2. 🔑 SSH 서버 활성화 토글 [{label_ssh}] (타 기기 원격 쉘 접속 허용)",
                구분선("라우팅 & 관문 (Exit Node / Subnet)"),
                f" 3. 📢 Exit Node(출구 노드)로 광고 토글 [{label_exit_adv}] (이 PC를 타 기기 관문으로 등록)",
                f" 4. 🌐 다른 기기의 Exit Node 사용 설정 [{label_exit_used}] (해외/가정망 경유 우회)",
                f" 5. 🔀 로컬 서브넷(Routes) 노출 설정 [{label_routes}] (공유기 내부 대역 통째 공유)",
                구분선("인증 & 복구 도구"),
                " 6. 🔄 로그인 세션 강제 재인증 (--force-reauth) (계정 만료/인증 오류 해결)",
                " 7. 🧼 모든 설정 초기화 및 재시작 (--reset) (설정 오류 시 초기화)",
                구분선(),
                " 8. ❌ 이전 메뉴로 돌아가기"
            ]
            
            sel, _, *_ = _interactive_menu("🔌 Tailscale 서비스 연결(Up) 세부 옵션", sub_menu, timeout=0)
            if sel is None or sel < 0 or sel >= len(sub_menu):
                break

            _sel_item = sub_menu[sel]
            if isinstance(_sel_item, dict):
                continue
            _opt_str = str(_sel_item)

            if "돌아가기" in _opt_str or "이전" in _opt_str or "취소" in _opt_str:
                break
                
            if "기본 연결 실행" in _opt_str:  # 기본 연결
                ok("Tailscale 기본 연결 시도 중... 🔌")
                code, out = _run_tailscale_cmd(["up"])
                if code == 0:
                    ok("Tailscale 연결 성공! 👍")
                else:
                    err(f"Tailscale 연결 실패: {out}")
                _wait_enter()
                
            elif "SSH 서버 활성화" in _opt_str:  # SSH 토글
                new_val = not ts_ssh
                settings.data["tailscale_ssh_enabled"] = new_val
                settings.save()
                ok(f"SSH 서버 활성화 상태가 {'켜짐' if new_val else '꺼짐'}으로 변경되었어. 즉시 반영을 위해 재시작해냥!")
                
                args = ["up"]
                if new_val: args.append("--ssh")
                if ts_exit_adv: args.append("--advertise-exit-node")
                if ts_exit_used: args += ["--exit-node", ts_exit_used]
                if ts_routes_adv: args += ["--advertise-routes", ts_routes_adv]
                
                code, out = _run_tailscale_cmd(args)
                if code == 0:
                    ok("Tailscale 설정 적용 완료! 🎉")
                else:
                    err(f"설정 적용 실패: {out}")
                _wait_enter()
                
            elif "Exit Node(출구 노드)로 광고" in _opt_str or "출구 노드" in _opt_str:  # Exit Node 광고 토글
                new_val = not ts_exit_adv
                settings.data["tailscale_exit_node_advertised"] = new_val
                settings.save()
                ok(f"Exit Node 광고 기능이 {'켜짐' if new_val else '꺼짐'}으로 변경되었어. 즉시 반영을 위해 재시작해냥!")
                
                args = ["up"]
                if ts_ssh: args.append("--ssh")
                if new_val: args.append("--advertise-exit-node")
                if ts_exit_used: args += ["--exit-node", ts_exit_used]
                if ts_routes_adv: args += ["--advertise-routes", ts_routes_adv]
                
                code, out = _run_tailscale_cmd(args)
                if code == 0:
                    ok("Tailscale 설정 적용 완료! 🎉")
                else:
                    err(f"설정 적용 실패: {out}")
                _wait_enter()
                
            elif "다른 기기의 Exit Node 사용" in _opt_str:  # 다른 Exit Node 사용 설정
                if ts_exit_used:
                    # 이미 사용 중이면 끄기
                    settings.data["tailscale_exit_node_used_ip"] = ""
                    settings.save()
                    ok("다른 기기의 Exit Node 사용을 해제했어. 즉시 반영을 시도할게냥!")
                    
                    args = ["up"]
                    if ts_ssh: args.append("--ssh")
                    if ts_exit_adv: args.append("--advertise-exit-node")
                    if ts_routes_adv: args += ["--advertise-routes", ts_routes_adv]
                    args.append("--exit-node=")
                    
                    code, out = _run_tailscale_cmd(args)
                    if code == 0:
                        ok("Tailscale Exit Node 사용 해제 완료! 🎉")
                    else:
                        err(f"설정 적용 실패: {out}")
                else:
                    # 기기 목록 가져오기
                    peers = _get_tailscale_peers()
                    ip_input = ""
                    
                    if peers:
                        peer_menu = []
                        for i, p in enumerate(peers):
                            status_lbl = "온라인 🟢" if p["online"] else "오프라인 🔴"
                            exit_lbl = "Exit Node 지원 ✨" if p["exit_node_opt"] else "미지원"
                            peer_menu.append(f" {i+1}. {p['hostname']} ({p['ip']}) [{status_lbl} | {exit_lbl}]")
                        peer_menu.append(f" {len(peers)+1}. 📝 직접 IP 혹은 기기 이름 입력하기")
                        peer_menu.append(f" {len(peers)+2}. ❌ 취소")
                        
                        p_sel, _, *_ = _interactive_menu("🌐 인터넷 경유지로 지정할 Exit Node 선택냥", peer_menu, timeout=0)
                        if p_sel is None or p_sel == len(peers) + 1 or p_sel < 0:
                            ok("설정이 취소되었어냥.")
                            _wait_enter()
                            continue
                        elif p_sel == len(peers):
                            ip_input = prompt_input(" 🌐 인터넷 경유지로 지정할 Exit Node의 IP 혹은 기기이름을 입력냥: ").strip()
                        else:
                            ip_input = peers[p_sel]["ip"]
                    else:
                        ip_input = prompt_input(" 🌐 인터넷 경유지로 지정할 Exit Node의 IP 혹은 기기이름을 입력냥: ").strip()
                        
                    if ip_input:
                        settings.data["tailscale_exit_node_used_ip"] = ip_input
                        settings.save()
                        ok(f"Exit Node를 '{ip_input}'(으)로 설정하고 반영을 시도할게냥!")
                        
                        args = ["up"]
                        if ts_ssh: args.append("--ssh")
                        if ts_exit_adv: args.append("--advertise-exit-node")
                        args += ["--exit-node", ip_input]
                        if ts_routes_adv: args += ["--advertise-routes", ts_routes_adv]
                        
                        code, out = _run_tailscale_cmd(args)
                        if code == 0:
                            ok("Tailscale Exit Node 적용 완료! 🎉")
                        else:
                            err(f"설정 적용 실패: {out}")
                    else:
                        ok("입력이 취소되었어.")
                _wait_enter()
                
            elif "로컬 서브넷(Routes)" in _opt_str:  # 서브넷 라우팅 광고 설정
                if ts_routes_adv:
                    # 해제
                    settings.data["tailscale_routes_advertised"] = ""
                    settings.save()
                    ok("서브넷 라우팅(Routes) 광고를 해제했어. 즉시 반영을 시도할게냥!")
                    
                    args = ["up"]
                    if ts_ssh: args.append("--ssh")
                    if ts_exit_adv: args.append("--advertise-exit-node")
                    if ts_exit_used: args += ["--exit-node", ts_exit_used]
                    args.append("--advertise-routes=")
                    
                    code, out = _run_tailscale_cmd(args)
                    if code == 0:
                        ok("서브넷 라우팅 해제 완료! 🎉")
                    else:
                        err(f"설정 적용 실패: {out}")
                else:
                    # 현재 내부 IP 대역 감지
                    subnets = _get_local_subnets()
                    route_input = ""
                    
                    if subnets:
                        subnet_menu = []
                        for i, sub in enumerate(subnets):
                            subnet_menu.append(f" {i+1}. 🔀 감지된 내부 대역 선택: {sub}")
                        subnet_menu.append(f" {len(subnets)+1}. 📝 직접 입력하기")
                        subnet_menu.append(f" {len(subnets)+2}. ❌ 취소")
                        
                        s_sel, _, *_ = _interactive_menu("🔀 광고할 로컬 서브넷 대역 선택냥", subnet_menu, timeout=0)
                        if s_sel is None or s_sel == len(subnets) + 1 or s_sel < 0:
                            ok("설정이 취소되었어냥.")
                            _wait_enter()
                            continue
                        elif s_sel == len(subnets):
                            route_input = prompt_input(" 🔀 광고할 서브넷 대역을 입력냥 (예: 192.168.0.0/24): ").strip()
                        else:
                            route_input = subnets[s_sel]
                    else:
                        route_input = prompt_input(" 🔀 광고할 서브넷 대역을 입력냥 (예: 192.168.0.0/24): ").strip()
                        
                    if route_input:
                        settings.data["tailscale_routes_advertised"] = route_input
                        settings.save()
                        ok(f"서브넷 대역 '{route_input}'(으)로 설정하고 반영을 시도할게냥!")
                        
                        args = ["up"]
                        if ts_ssh: args.append("--ssh")
                        if ts_exit_adv: args.append("--advertise-exit-node")
                        if ts_exit_used: args += ["--exit-node", ts_exit_used]
                        args += ["--advertise-routes", route_input]
                        
                        code, out = _run_tailscale_cmd(args)
                        if code == 0:
                            ok("서브넷 라우팅 광고 적용 완료! 🎉")
                        else:
                            err(f"설정 적용 실패: {out}")
                    else:
                        ok("입력이 취소되었어.")
                _wait_enter()
                
            elif "강제 재인증" in _opt_str or "--force-reauth" in _opt_str:  # 강제 재인증
                ok("강제 재인증 웹링크를 생성 중입니다냥... 🔑")
                ts_path = _get_tailscale_path()
                if ts_path:
                    import subprocess
                    subprocess.Popen([ts_path, "up", "--force-reauth"], creationflags=subprocess.CREATE_NEW_CONSOLE)
                    ok("새로운 콘솔 창에서 로그인 인증을 요청했어! 웹 브라우저를 확인해줘냥. 👍")
                else:
                    err("Tailscale 실행 경로를 찾을 수 없어냥. ❌")
                _wait_enter()
                
            elif "모든 설정 초기화" in _opt_str or "--reset" in _opt_str:  # 설정 초기화
                confirm = prompt_input(" 정말 모든 설정을 초기화하고 재시작할까냥? (y/N): ").strip().lower()
                if confirm == 'y':
                    ok("설정 초기화 진행 중... 🧼")
