# [TAG: #@_mcp_server_mgr]
# [V22.40] AI 에이전트(Spark/Claude/Cursor/ChatGPT) 연동용 통합 MCP 서버 관리기 🤖✨
# ==============================================================================

_G_MCP_SERVER_PROC = None
_G_MCP_SERVER_INFO = {
    "port": 8766,
    "token": "",
    "started_at": 0,
    "url": "",
    "tunnel_url": ""
}
_G_MCP_SERVER_LOGS = []

def _get_mcp_server_script():
    """c:\\srt\\scripts\\mcp_server.py 스크립트 경로 확인 (구버전 temp/ 위치도 fallback 지원)"""
    for cand in (os.path.join(BASE_DIR, "scripts", "mcp_server.py"),
                 os.path.join(BASE_DIR, "temp", "mcp_server.py"),
                 os.path.join(BASE_DIR, "mcp_server.py")):
        if os.path.exists(cand):
            return cand
    return None

def _is_mcp_server_running():
    """MCP 서버 프로세스 실행 여부 확인 🟢"""
    global _G_MCP_SERVER_PROC
    if _G_MCP_SERVER_PROC is not None:
        if _G_MCP_SERVER_PROC.poll() is None:
            return True
        else:
            _G_MCP_SERVER_PROC = None
    # 프로세스 객체가 없어도 포트가 열려있는지 헬스체크
    try:
        import urllib.request
        port = _G_MCP_SERVER_INFO.get("port", 8766)
        req = urllib.request.Request(f"http://127.0.0.1:{port}/health", headers={'User-Agent': 'SRT-Health'})
        with urllib.request.urlopen(req, timeout=0.8) as resp:
            if resp.status == 200:
                return True
    except Exception:
        pass
    return False

def _is_mcp_server_active():
    """MCP 서버 활성 상태 (TUI 메뉴 상태 표시용)"""
    return _is_mcp_server_running()

def _stop_mcp_server():
    """MCP 서버 프로세스 안전 종료 및 잔여 포트 정리 🛑"""
    global _G_MCP_SERVER_PROC, _G_MCP_SERVER_INFO
    stopped = False
    if _G_MCP_SERVER_PROC is not None:
        try:
            _G_MCP_SERVER_PROC.terminate()
            _G_MCP_SERVER_PROC.wait(timeout=2)
            stopped = True
        except Exception:
            try:
                _G_MCP_SERVER_PROC.kill()
                stopped = True
            except Exception:
                pass
        _G_MCP_SERVER_PROC = None
        
    # 포트(기본 8766)를 잡고 있는 잔여 파이썬 프로세스 강제 정리 🧹
    try:
        port = int(_G_MCP_SERVER_INFO.get("port", 8766))
        raw = subprocess.run(["netstat", "-ano"], capture_output=True).stdout
        try: out = raw.decode("cp949", errors="ignore")
        except: out = raw.decode("utf-8", errors="ignore")
        
        for line in out.splitlines():
            if f":{port}" in line and "LISTENING" in line:
                parts = line.strip().split()
                if parts and parts[-1].isdigit():
                    pid = parts[-1]
                    if pid != str(os.getpid()):
                        subprocess.run(["taskkill", "/F", "/T", "/PID", pid], capture_output=True)
                        stopped = True
    except Exception:
        pass
        
    _G_MCP_SERVER_INFO["started_at"] = 0
    _G_MCP_SERVER_INFO["url"] = ""
    return stopped

def _start_mcp_server(port=8766, auth_token=None):
    """백그라운드에서 mcp_server.py 프로세스 기동 🚀"""
    global _G_MCP_SERVER_PROC, _G_MCP_SERVER_INFO, _G_MCP_SERVER_LOGS
    script_path = _get_mcp_server_script()
    if not script_path:
        print(f"\r\n❌ {ctext('mcp_server.py 스크립트 파일을 찾을 수 없어냥! 😢', C.RED)}")
        return False
        
    if _is_mcp_server_running():
        _stop_mcp_server()
        time.sleep(0.5)
        
    cmd = [sys.executable, script_path, "--port", str(port)]
    if auth_token and auth_token.strip():
        cmd.extend(["--token", auth_token.strip()])
        
    # UTF-8 환경 보장
    sub_env = os.environ.copy()
    sub_env["PYTHONUNBUFFERED"] = "1"
    sub_env["PYTHONIOENCODING"] = "utf-8"

    try:
        proc = subprocess.Popen(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            env=sub_env,
            creationflags=0x08000000  # CREATE_NO_WINDOW
        )
        _G_MCP_SERVER_PROC = proc
        _G_MCP_SERVER_LOGS = []
        
        def _mcp_log_reader(stream):
            for raw_line in iter(stream.readline, b''):
                try:
                    line_str = raw_line.decode('utf-8', errors='replace').strip()
                except Exception:
                    line_str = raw_line.decode('cp949', errors='replace').strip()
                if line_str:
                    _G_MCP_SERVER_LOGS.append(line_str)
                    if len(_G_MCP_SERVER_LOGS) > 300:
                        _G_MCP_SERVER_LOGS.pop(0)
            stream.close()
            
        threading.Thread(target=_mcp_log_reader, args=(proc.stdout,), daemon=True).start()
        threading.Thread(target=_mcp_log_reader, args=(proc.stderr,), daemon=True).start()
        
        # 헬스체크 대기
        start_t = time.time()
        ready = False
        while time.time() - start_t < 4:
            if _is_mcp_server_running():
                ready = True
                break
            time.sleep(0.2)
            
        if ready:
            _G_MCP_SERVER_INFO = {
                "port": port,
                "token": auth_token or "",
                "started_at": time.time(),
                "url": f"http://localhost:{port}/sse" + (f"?token={auth_token}" if auth_token else ""),
                "tunnel_url": ""
            }
            return True
        else:
            _stop_mcp_server()
            return False
    except Exception as e:
        print(f"\r\n❌ {ctext(f'MCP 서버 시작 중 오류 발생: {e}', C.RED)}")
        return False

def _get_mcp_status_dict(settings=None):
    """MCP 서버 및 Cloudflare Tunnel의 전체 상태 요약 딕셔너리 반환 🤖📊"""
    port = int(settings.data.get("mcp_server_port", 8766)) if settings else 8766
    auth_token = settings.data.get("mcp_auth_token", "").strip() if settings else ""
    
    server_running = _is_mcp_server_running()
    quick_running = _is_quick_tunnel_running()
    quick_url = _G_CLOUDFLARE_QUICK_TUNNEL_INFO.get("url", "") if quick_running else ""
    
    if quick_running and quick_url:
        public_mcp_url = f"{quick_url}/mcp" + (f"?token={auth_token}" if auth_token else "")
        public_sse_url = f"{quick_url}/sse" + (f"?token={auth_token}" if auth_token else "")
    else:
        public_mcp_url = f"http://localhost:{port}/mcp" + (f"?token={auth_token}" if auth_token else "")
        public_sse_url = f"http://localhost:{port}/sse" + (f"?token={auth_token}" if auth_token else "")
        
    return {
        "running": server_running,
        "port": port,
        "auth_token": auth_token,
        "auth_required": bool(auth_token),
        "tunnel_running": quick_running,
        "tunnel_url": quick_url,
        "spark_mcp_url": public_mcp_url if server_running else "",
        "claude_sse_url": public_sse_url if server_running else "",
        "local_mcp_url": f"http://localhost:{port}/mcp" + (f"?token={auth_token}" if auth_token else ""),
        "local_sse_url": f"http://localhost:{port}/sse" + (f"?token={auth_token}" if auth_token else ""),
        "workspace": BASE_DIR
    }

def _toggle_mcp_server(settings=None, start_tunnel=True):
    """MCP 서버 원클릭 ON/OFF 토글 헬퍼 🔄"""
    if _is_mcp_server_running():
        _stop_mcp_server()
        if _is_quick_tunnel_running():
            _stop_quick_tunnel()
        return False, "MCP 서버 및 터널이 종료되었습니다. 🛑"
    else:
        port = int(settings.data.get("mcp_server_port", 8766)) if settings else 8766
        auth_token = settings.data.get("mcp_auth_token", "").strip() if settings else ""
        ok_srv = _start_mcp_server(port=port, auth_token=auth_token)
        if not ok_srv:
            return False, "MCP 서버 시작에 실패했습니다. ❌"
        
        msg = f"MCP 서버가 포트 {port}에서 시작되었습니다. 🟢"
        if start_tunnel:
            ok_cf = _start_quick_tunnel(f"http://localhost:{port}", "AI 에이전트 MCP 서버", auth_token=auth_token)
            if ok_cf and _G_CLOUDFLARE_QUICK_TUNNEL_INFO.get("url"):
                q_url = _G_CLOUDFLARE_QUICK_TUNNEL_INFO["url"]
                msg += f" (Cloudflare Tunnel: {q_url})"
        return True, msg

def _build_mcp_config_json(url):
    """클라이언트에 붙여넣을 표준 MCP 설정 JSON 생성"""
    config = {
        "mcpServers": {
            "srt-workspace": {
                "url": url
            }
        }
    }
    return json.dumps(config, indent=2, ensure_ascii=False)

