# [TAG: #@_resolve_active_audio_device]

def _resolve_active_audio_device(device_id_or_name_str):
    """
    다중 장치 ID, 장치명, 닉네임/별칭 등 다양한 토큰 목록에서 
    현재 활성화(active)되어 있는 실시간 오디오 장치 ID를 유연하고 똑똑하게 찾아 반환합니다. 🎧✨
    """
    if not device_id_or_name_str: return ""
    tokens = [t.strip() for t in device_id_or_name_str.split(";") if t.strip()]
    if not tokens: return ""
    
    all_names = _get_all_device_names_from_reg()
    active_ids = _get_active_device_ids()
    if not active_ids: return tokens[0]

    aliases = {}
    try:
        if 'settings' in globals() and globals()['settings']:
            aliases = globals()['settings'].data.get("audio_aliases", {})
        elif 'settings_ref' in globals() and globals()['settings_ref']:
            aliases = globals()['settings_ref'].data.get("audio_aliases", {})
    except: pass

    active_dev_info = []
    for d_id in active_ids:
        raw_name = all_names.get(d_id, "")
        alias = aliases.get(raw_name) or aliases.get(d_id)
        disp_name = _format_audio_device_name(raw_name, alias) if raw_name else ""
        active_dev_info.append((d_id, raw_name, disp_name, alias or ""))

    # 1단계: 현재 활성화된 장치 GUID와 정확히 일치하는 경우
    for token in tokens:
        token_lower = token.lower()
        if token_lower.startswith("{0.0.0.00000000}."):
            if token_lower in active_ids:
                return token_lower

    # 2단계: 토큰 명칭과 활성 장치 명칭/닉네임/포맷명의 대소문자 무시 완전 일치
    for token in tokens:
        t_low = token.lower()
        if t_low.startswith("{0.0.0.00000000}."):
            t_raw = all_names.get(t_low, "")
            if t_raw: t_low = t_raw.lower()
            else: continue

        for d_id, raw_name, disp_name, alias in active_dev_info:
            if t_low in (raw_name.lower(), disp_name.lower(), alias.lower()):
                return d_id

    # 3단계: 부분 문자열(Sub-string) 유연한 상호 포함 및 정제 매칭
    import re
    # [TAG: #@_clean_str]

    def _clean_str(s):
        return re.sub(r'[\s\(\)\[\]\-_,\.]+', '', s).lower()

    for token in tokens:
        t_low = token.lower()
        if t_low.startswith("{0.0.0.00000000}."):
            t_raw = all_names.get(t_low, "")
            if t_raw: t_low = t_raw.lower()
            else: continue

        t_clean = _clean_str(t_low)

        for d_id, raw_name, disp_name, alias in active_dev_info:
            r_low = raw_name.lower()
            dp_low = disp_name.lower()
            al_low = alias.lower()

            if (t_low and (t_low in r_low or r_low in t_low or t_low in dp_low or dp_low in t_low)):
                return d_id
            if (al_low and (t_low in al_low or al_low in t_low)):
                return d_id

            if t_clean:
                r_clean = _clean_str(raw_name)
                dp_clean = _clean_str(disp_name)
                al_clean = _clean_str(alias)
                if (r_clean and (t_clean in r_clean or r_clean in t_clean)):
                    return d_id
                if (dp_clean and (t_clean in dp_clean or dp_clean in t_clean)):
                    return d_id
                if (al_clean and (t_clean in al_clean or al_clean in t_clean)):
                    return d_id

    # 4단계: 매칭 실패 시 첫 번째 토큰 리턴
    return tokens[0]

# [TAG: #@_get_all_device_names_from_reg]

def _get_all_device_names_from_reg():
    """레지스트리에서 모든 오디오 렌더 장치의 ID와 실제 이름 매핑을 반환합니다. 중복 이름은 인스턴스 ID 꼬리표를 붙여 구분합니다."""
    import winreg
    key_path = r'SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\Render'
    temp_list = []
    try:
        render_key = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, key_path)
        for i in range(winreg.QueryInfoKey(render_key)[0]):
            try:
                sub_key_name = winreg.EnumKey(render_key, i)
                sub_key = winreg.OpenKey(render_key, sub_key_name)
                prop_key = winreg.OpenKey(sub_key, 'Properties')
                try:
                    name = winreg.QueryValueEx(prop_key, '{a45c254e-df1c-4efd-8020-67d146a850e0},14')[0]
                except:
                    try:
                        name = winreg.QueryValueEx(prop_key, '{a45c254e-df1c-4efd-8020-67d146a850e0},2')[0]
                    except:
                        name = "알 수 없는 장치"
                try:
                    desc = winreg.QueryValueEx(prop_key, '{b3f8fa53-0004-438e-9003-51a46e139bfc},6')[0]
                except: desc = ''
                
                try:
                    instance_id = winreg.QueryValueEx(prop_key, '{b3f8fa53-0004-438e-9003-51a46e139bfc},2')[0]
                except:
                    instance_id = ""
                    
                base_name = f"{name} ({desc})" if desc else name
                device_id = f"{{0.0.0.00000000}}.{sub_key_name}"
                temp_list.append({
                    "device_id": device_id.lower(),
                    "base_name": base_name,
                    "instance_id": instance_id
                })
            except: pass
    except: pass
    
    name_counts = {}
    for item in temp_list:
        n = item["base_name"]
        name_counts[n] = name_counts.get(n, 0) + 1
        
    names_map = {}
    for item in temp_list:
        n = item["base_name"]
        d_id = item["device_id"]
        inst_id = item["instance_id"]
        if name_counts[n] > 1 and inst_id:
            inst_suffix = inst_id.split('\\')[-1]
            names_map[d_id] = f"{n} [{inst_suffix}]"
        else:
            names_map[d_id] = n
    return names_map

# [TAG: #@_format_audio_device_name]

def _format_audio_device_name(original_name, alias=None):
    """
    오디오 디바이스 이름을 깔끔하게 포맷팅합니다.
    사용자 화면 노출용이므로 내부 식별용 꼬리표(예: [8&2DE137D4&0&0000])는 제거합니다.
    """
    import re
    clean_name = re.sub(r"\s*\[[^\]]+\]$", "", original_name)
    match = re.match(r"^(.+?) \((.*)\)$", clean_name)
    if match:
        device_type = match.group(1).strip()
        controller_name = match.group(2).strip()
        if alias:
            return f"{alias} ({controller_name})"
        else:
            return f"{device_type} ({controller_name})"
    else:
        if alias:
            return f"{alias} ({clean_name})"
        else:
            return clean_name

# [TAG: #@_get_audio_device_display_name_by_id]

def _get_audio_device_display_name_by_id(dev_id_or_name, settings=None):
    """장치 ID 또는 이름으로부터 사용자 표시용 장치명을 반환합니다냥! 🎧"""
    if not dev_id_or_name:
        return ""
    all_names = _get_all_device_names_from_reg()
    aliases = {}
    if settings:
        try: aliases = settings.data.get("audio_aliases", {})
        except: pass
    elif 'settings' in globals() and globals()['settings']:
        try: aliases = globals()['settings'].data.get("audio_aliases", {})
        except: pass
    elif 'settings_ref' in globals() and globals()['settings_ref']:
        try: aliases = globals()['settings_ref'].data.get("audio_aliases", {})
        except: pass

    if dev_id_or_name.lower().startswith("{0.0.0.00000000}."):
        real_name = all_names.get(dev_id_or_name.lower(), "")
        if not real_name:
            real_name = dev_id_or_name
    else:
        real_name = dev_id_or_name

    return _format_audio_device_name(real_name, aliases.get(real_name) or aliases.get(dev_id_or_name))

# [TAG: #@_set_audio_device_by_id]

