# [TAG: #@_get_alarm_speaker_display_name]

def _get_alarm_speaker_display_name(settings_obj=None):
    """알람 전용 출력 스피커의 표시용 이름을 반환합니다냥! 🔊"""
    try:
        if settings_obj is None and 'settings' in globals():
            settings_obj = globals()['settings']
        if not settings_obj:
            return "설정 안 됨"
        dev_id = settings_obj.data.get("alarm_speaker_device_id", "")
        if not dev_id:
            return "미선택 (기본 스피커)"
        
        all_names = _get_all_device_names_from_reg()
        aliases = settings_obj.data.get("audio_aliases", {})
        
        if dev_id.lower().startswith("{0.0.0.00000000}."):
            real_name = all_names.get(dev_id.lower(), dev_id)
            return _format_audio_device_name(real_name, aliases.get(real_name))
        else:
            return _format_audio_device_name(dev_id, aliases.get(dev_id))
    except Exception:
        return "미선택 (기본 스피커)"


# [TAG: #@_get_device_keywords_from_id]

def _get_device_keywords_from_id(device_id):
    if not device_id: return [], []
    guid = device_id.split('.')[-1]
    key_path = r'SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\Render\\' + guid + r'\\Properties'
    keywords = []
    try:
        import winreg
        prop_key = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, key_path)
        for k in ['{b3f8fa53-0004-438e-9003-51a46e139bfc},6', 
                  '{a45c254e-df1c-4efd-8020-67d146a850e0},2', 
                  '{a45c254e-df1c-4efd-8020-67d146a850e0},14',
                  '{b3f8fa53-0004-438e-9003-51a46e139bfc},5']:
            try:
                val = winreg.QueryValueEx(prop_key, k)[0]
                if isinstance(val, str) and val.strip():
                    keywords.append(val.strip())
            except: pass
    except: pass

    import re
    tokens = set()
    for kw in keywords:
        sub_tokens = re.split(r'[\s\(\)\[\]\-_,]+', kw)
        for t in sub_tokens:
            if len(t) >= 2 and t.lower() not in ['audio', 'device', 'speakers', 'headphones', 'output', 'high', 'definition']:
                tokens.add(t.lower())
    return list(tokens), keywords


def _calculate_device_name_match_score(dev_name, tokens, raw_keywords):
    """오디오 장치명과 타겟 장치 키워드/토큰 간의 일치 점수를 계산합니다냥! 🎵🎯"""
    if not dev_name: return 0
    dev_name_lower = dev_name.lower()
    score = 0
    for kw in raw_keywords:
        if kw.lower() in dev_name_lower:
            score += 10
    for token in tokens:
        if token.lower() in dev_name_lower:
            score += len(token) * 2
    return score


def play_alarm_custom_beep(target_device_str, mode="dual", freq=1000, duration_sec=0.5, volume=None):
    """지정된 오디오 디바이스 및 모드(dual: 동시출력 / custom_only: 단독출력)에 맞춰 Beep 음을 정밀하게 재생합니다냥! 🔊✨"""
    if volume is None:
        try:
            if 'settings' in globals():
                volume = float(settings.data.get("alarm_speaker_volume", 80)) / 100.0
            else:
                volume = 0.8
        except: volume = 0.8
    try:
        import pyaudio
        p = pyaudio.PyAudio()
    except Exception:
        import winsound
        winsound.Beep(int(freq), int(duration_sec * 1000))
        return

    try:
        target_index = None
        default_index = None
        
        try:
            default_info = p.get_default_output_device_info()
            default_index = default_info['index']
        except: pass

        tokens, raw_keywords = _get_device_keywords_from_id(target_device_str)
        if target_device_str and (tokens or raw_keywords):
            best_score = 0
            for i in range(p.get_device_count()):
                try:
                    info = p.get_device_info_by_index(i)
                    if info.get('maxOutputChannels', 0) > 0:
                        dev_name = info.get('name', '')
                        score = _calculate_device_name_match_score(dev_name, tokens, raw_keywords)
                        if score > best_score:
                            best_score = score
                            target_index = i
                except: pass

        if target_index is None:
            target_index = default_index

        devices_to_play = []
        if mode == "dual":
            if default_index is not None:
                devices_to_play.append(default_index)
            if target_index is not None and target_index not in devices_to_play:
                devices_to_play.append(target_index)
        else: # custom_only
            if target_index is not None:
                devices_to_play.append(target_index)
            elif default_index is not None:
                devices_to_play.append(default_index)

        import math, struct, threading
        sample_rate = 44100
        num_samples = int(sample_rate * duration_sec)
        samples = bytearray()
        
        for i in range(num_samples):
            val = math.sin(2 * math.pi * freq * i / sample_rate) * volume
            int_val = int(val * 32767)
            samples.extend(struct.pack('<h', int_val))

        # [TAG: #@_play_single_stream]

        def _play_single_stream(dev_idx):
            try:
                stream = p.open(format=pyaudio.paInt16,
                                channels=1,
                                rate=sample_rate,
                                output=True,
                                output_device_index=dev_idx)
                stream.write(bytes(samples))
                stream.stop_stream()
                stream.close()
            except Exception: pass

        threads = []
        for dev_idx in devices_to_play:
            t = threading.Thread(target=_play_single_stream, args=(dev_idx,), daemon=True)
            threads.append(t)
            t.start()

        if mode == "dual":
            # [TAG: #@_winsound_beep]

            def _winsound_beep():
                try:
                    import winsound
                    winsound.Beep(int(freq), int(duration_sec * 1000))
                except: pass
            t_win = threading.Thread(target=_winsound_beep, daemon=True)
            threads.append(t_win)
            t_win.start()

        for t in threads:
            t.join(timeout=duration_sec + 0.5)

        try:
            # [V170.3] PortAudio DLL 메모리 해제 시 Access Violation(0xc0000005) 방지 보호막 🛡️
            time.sleep(0.05)
            p.terminate()
        except: pass
    except Exception as e:
        try:
            if 'p' in locals(): p.terminate()
        except: pass
        try:
            import winsound
            winsound.Beep(int(freq), int(duration_sec * 1000))
        except: pass


# [TAG: #@_select_alarm_speaker_volume_menu]

def _select_alarm_speaker_volume_menu(settings_obj):
    """타이머 및 알람 전용 출력 스피커의 볼륨 크기를 설정합니다냥! 🔊"""
    cur_vol = settings_obj.data.get("alarm_speaker_volume", 80)
    vol_values = [100, 90, 80, 70, 60, 50, 40, 30, 20, 10]
    vol_opts = [
        "🔊 알람 볼륨 100% (최대)",
        "🔊 알람 볼륨 90%",
        "🔊 알람 볼륨 80% (권장)",
        "🔉 알람 볼륨 70%",
        "🔉 알람 볼륨 60%",
        "🔉 알람 볼륨 50%",
        "🔈 알람 볼륨 40%",
        "🔈 알람 볼륨 30%",
        "🔈 알람 볼륨 20%",
        "🔈 알람 볼륨 10% (최소)",
        "✏️ 사용자 직접 입력 (%)",
        "❌ 취소 및 돌아가기"
    ]
    opts_disp = []
    for i, v in enumerate(vol_values):
        if v == cur_vol:
            opts_disp.append(ctext(f"{vol_opts[i]} (현재 설정됨)", C.GREEN))
        else:
            opts_disp.append(vol_opts[i])
    opts_disp.append(vol_opts[10])
    opts_disp.append(vol_opts[11])

    v_sel, action, *_ = _interactive_menu(f"🔊 알람/타이머 전용 출력 볼륨을 선택해줘냥! (현재: {cur_vol}%)", opts_disp, timeout=0)
    if v_sel >= 0 and v_sel < len(vol_values):
        chosen_vol = vol_values[v_sel]
        settings_obj.data["alarm_speaker_volume"] = chosen_vol
        settings_obj.save()
        print(f"\r\n ✅ {C.GREEN}알람 출력 볼륨이 [{chosen_vol}%] 로 변경되었어!{C.RESET}")
        time.sleep(1)
    elif v_sel == 10: # 사용자 직접 입력
        print(f"\r\n ✏️ {C.CYAN}원하는 알람 출력 볼륨(%)을 1~100 사이 숫자로 입력해줘:{C.RESET} ", end="")
        val_str = input().strip()
        try:
            val_int = int(val_str)
            val_int = max(1, min(100, val_int))
            settings_obj.data["alarm_speaker_volume"] = val_int
            settings_obj.save()
            print(f"\r\n ✅ {C.GREEN}알람 출력 볼륨이 [{val_int}%] 로 변경되었어!{C.RESET}")
            time.sleep(1)
        except Exception:
            print(f"\r\n ❌ {C.RED}올바른 숫자를 입력해주지 않았어냥!{C.RESET}")
            time.sleep(1)


# [TAG: #@_format_alarm_duration_str]
def _format_alarm_duration_str(seconds):
    """초 단위 시간을 6초, 10초, 30초, 1분, 1.5분 등으로 예쁘게 포맷팅합니다냥! ⏳"""
    try:
        sec_int = int(round(float(seconds)))
    except Exception:
        sec_int = 30
    if sec_int < 60:
        return f"{sec_int}초"
    mins = sec_int / 60.0
    if mins.is_integer():
        return f"{int(mins)}분"
    return f"{mins:g}분"


# [TAG: #@_get_alarm_ring_duration_sec]
def _get_alarm_ring_duration_sec(settings_obj, for_bluetooth=False):
    """기본 또는 블루투스 연결 시 반응 없을 때 알람 지속 시간(초)을 반환합니다냥! ⏳🎧"""
    if not settings_obj or not hasattr(settings_obj, 'data'):
        return 10 if for_bluetooth else 30
    try:
        if for_bluetooth:
            if "alarm_no_response_bt_ring_duration_sec" in settings_obj.data:
                return max(1, int(settings_obj.data["alarm_no_response_bt_ring_duration_sec"]))
            if "alarm_no_response_bt_ring_duration_min" in settings_obj.data:
                return max(1, int(float(settings_obj.data["alarm_no_response_bt_ring_duration_min"]) * 60))
            return 10
        else:
            if "alarm_no_response_ring_duration_sec" in settings_obj.data:
                return max(1, int(settings_obj.data["alarm_no_response_ring_duration_sec"]))
            if "alarm_no_response_ring_duration_min" in settings_obj.data:
                return max(1, int(float(settings_obj.data["alarm_no_response_ring_duration_min"]) * 60))
            return 30
    except Exception:
        return 10 if for_bluetooth else 30


# [TAG: #@_is_bluetooth_audio_connected]
def _is_bluetooth_audio_connected(settings_obj=None):
    """현재 블루투스 오디오 기기(이어폰/헤드폰/스피커)가 연결 및 활성화되어 있는지 초고속(0.001초) 판별합니다냥! 🎧"""
    try:
        if '_get_active_device_ids' in globals():
            active_ids = _get_active_device_ids()
        else:
            import winreg
            key_path = r'SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\Render'
            active_ids = set()
            try:
                render_key = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, key_path)
                for i in range(winreg.QueryInfoKey(render_key)[0]):
                    try:
                        sub_key_name = winreg.EnumKey(render_key, i)
                        sub_key = winreg.OpenKey(render_key, sub_key_name)
                        state = winreg.QueryValueEx(sub_key, 'DeviceState')[0]
                        if state == 1:
                            active_ids.add(f"{{0.0.0.00000000}}.{sub_key_name}".lower())
                    except: pass
            except: pass

        if not active_ids:
            return False

        # 1. 활성 장치 중 블루투스 장치가 있는지 확인
        if '_is_bluetooth_audio_device' in globals():
            for dev_id in active_ids:
                if _is_bluetooth_audio_device(dev_id):
                    return True

        # 2. settings에 지정된 블루투스 장치 ID가 활성 상태인지 확인
        if settings_obj and hasattr(settings_obj, 'data'):
            bt_dev_val = settings_obj.data.get("audio_bluetooth_device", "")
            if bt_dev_val:
                tokens = [t.strip().lower() for t in bt_dev_val.split(";") if t.strip()]
                for t in tokens:
                    if t in active_ids:
                        return True

        # 3. 현재 기본 오디오 장치가 블루투스인지 확인
        if '_get_current_default_audio_device_id' in globals():
            def_id = _get_current_default_audio_device_id()
            if def_id and '_is_bluetooth_audio_device' in globals() and _is_bluetooth_audio_device(def_id):
                return True
    except Exception:
        pass
    return False


# [TAG: #@_select_alarm_ring_duration_menu]

def _select_alarm_ring_duration_menu(settings_obj):
    """반응 없을 때 알람 울리는 시간 (기본 스피커 / 블루투스 이어폰)을 설정합니다냥! ⏳🎧"""
    dur_values = [6, 10, 15, 20, 30, 60, 120, 180, 300]
    dur_opts = [
        "⚡ 6초 (초단기 알림)",
        "⚡ 10초 (추천 - 블루투스 귀 보호)",
        "⏳ 15초",
        "⏳ 20초",
        "⏳ 30초 (기본값, 0.5분)",
        "⏳ 1분 (60초)",
        "⏳ 2분",
        "⏳ 3분",
        "⏳ 5분",
        "❌ 취소 및 돌아가기"
    ]

    while True:
        cur_normal_sec = _get_alarm_ring_duration_sec(settings_obj, for_bluetooth=False)
        cur_bt_sec = _get_alarm_ring_duration_sec(settings_obj, for_bluetooth=True)
        cur_normal_str = _format_alarm_duration_str(cur_normal_sec)
        cur_bt_str = _format_alarm_duration_str(cur_bt_sec)
        is_bt_now = _is_bluetooth_audio_connected(settings_obj)
        bt_status_tag = f" {ctext('[현재 연결됨]', C.GREEN)}" if is_bt_now else ""

        sub_opts = [
            f"🔊 1. 기본(스피커) 울리는 시간 설정 {ctext(f'(현재: {cur_normal_str})', C.SKY)}",
            f"🎧 2. 블루투스 이어폰 연결 시 울리는 시간 설정 {ctext(f'(현재: {cur_bt_str})', C.SKY)}{bt_status_tag}",
            "❌ 3. 취소 및 돌아가기"
        ]

        title = f"⏳ [반응 없을 때 알람 울리는 시간 관리] (기본: {cur_normal_str} / 🎧블투: {cur_bt_str})"
        sel, action, *_ = _interactive_menu(title, sub_opts, timeout=0)
        if action == "REFRESH" or sel < 0 or sel == 2 or sel >= len(sub_opts):
            break

        is_bt_target = (sel == 1)
        target_name = "블루투스 이어폰" if is_bt_target else "기본(스피커)"
        cur_target_sec = cur_bt_sec if is_bt_target else cur_normal_sec
        cur_target_str = cur_bt_str if is_bt_target else cur_normal_str

        opts_disp = []
        for i, v in enumerate(dur_values):
            if v == cur_target_sec:
                opts_disp.append(ctext(f"{dur_opts[i]} (현재 설정됨)", C.GREEN))
            else:
                opts_disp.append(dur_opts[i])
        opts_disp.append(dur_opts[-1])

        sub_title = f"⏳ [{target_name}] 반응 없을 때 알람 울리는 시간을 선택해줘냥! (현재: {cur_target_str})"
        d_sel, d_act, *_ = _interactive_menu(sub_title, opts_disp, timeout=0)
        if d_sel >= 0 and d_sel < len(dur_values):
            chosen_sec = dur_values[d_sel]
            chosen_str = _format_alarm_duration_str(chosen_sec)
            chosen_min = round(chosen_sec / 60.0, 3)

            if is_bt_target:
                settings_obj.data["alarm_no_response_bt_ring_duration_sec"] = chosen_sec
                settings_obj.data["alarm_no_response_bt_ring_duration_min"] = chosen_min
            else:
                settings_obj.data["alarm_no_response_ring_duration_sec"] = chosen_sec
                settings_obj.data["alarm_no_response_ring_duration_min"] = chosen_min
            settings_obj.save()

            print(f"\r\n ✅ {C.GREEN}[{target_name}] 반응 없을 때 알람 울리는 시간이 [{chosen_str}] 로 변경되었어!{C.RESET}")
            time.sleep(1)

def generate_sound_pcm_in_memory(sound_key):
    """디스크 파일 생성 0개! 메모리(RAM) 상에서 오디오 PCM 파형을 0.001초 만에 즉시 수학 연산합니다냥! 🧠🎶"""
    import math, struct
    sample_rate = 44100
    channels = 1
    sw = 2
    
    silent_padding = b'\x00' * int(sample_rate * channels * sw * 0.5)
    buf = bytearray()
    
    if sound_key == "clock_grandfather_ding":
        duration = 2.5
        num_samples = int(sample_rate * duration)
        f0 = 196.0
        for i in range(num_samples):
            t = i / sample_rate
            attack = min(1.0, t / 0.005)
            decay = math.exp(-t * 1.6)
            v1 = math.sin(2 * math.pi * f0 * t) * 0.45
            v2 = math.sin(2 * math.pi * (f0 * 1.004) * t) * 0.35
            v3 = math.sin(2 * math.pi * (f0 * 2.756) * t) * 0.20 * math.exp(-t * 3.0)
            v4 = math.sin(2 * math.pi * (f0 * 5.404) * t) * 0.12 * math.exp(-t * 5.0)
            v5 = math.sin(2 * math.pi * (f0 * 0.5) * t) * 0.15
            val = (v1 + v2 + v3 + v4 + v5) * attack * decay
            buf.extend(struct.pack('<h', int(max(-1.0, min(1.0, val * 0.85)) * 32767)))
            
    elif sound_key == "clock_wall_ding_dong":
        duration = 2.8
        num_samples = int(sample_rate * duration)
        for i in range(num_samples):
            t = i / sample_rate
            val = 0.0
            if 0.0 <= t < 1.4:
                t1 = t
                att = min(1.0, t1 / 0.005)
                dec = math.exp(-t1 * 1.8)
                f_ding = 220.0
                v = (math.sin(2 * math.pi * f_ding * t1) * 0.4 +
                     math.sin(2 * math.pi * f_ding * 1.003 * t1) * 0.3 +
                     math.sin(2 * math.pi * f_ding * 2.76 * t1) * 0.2 * math.exp(-t1 * 3.5))
                val += v * att * dec
            if 0.9 <= t:
                t2 = t - 0.9
                att = min(1.0, t2 / 0.005)
                dec = math.exp(-t2 * 1.5)
                f_dong = 164.81
                v = (math.sin(2 * math.pi * f_dong * t2) * 0.45 +
                     math.sin(2 * math.pi * f_dong * 1.004 * t2) * 0.35 +
                     math.sin(2 * math.pi * f_dong * 2.76 * t2) * 0.18 * math.exp(-t2 * 3.0))
                val += v * att * dec
            buf.extend(struct.pack('<h', int(max(-1.0, min(1.0, val * 0.8)) * 32767)))

    elif sound_key == "clock_tick_tock":
        num_samples = int(sample_rate * 0.35)
        for i in range(num_samples):
            t = i / sample_rate
            val = 0
            if 0 <= t < 0.08:
                env = math.exp(-t * 80)
                val += math.sin(2 * math.pi * 3200 * t) * 0.4 * env + math.sin(2 * math.pi * 1800 * t) * 0.3 * env
                val += (math.sin(t * 12345) % 1.0 - 0.5) * 0.2 * env
            elif 0.18 <= t < 0.26:
                t2 = t - 0.18
                env = math.exp(-t2 * 90)
                val += math.sin(2 * math.pi * 2400 * t2) * 0.4 * env + math.sin(2 * math.pi * 1400 * t2) * 0.3 * env
                val += (math.sin(t2 * 9876) % 1.0 - 0.5) * 0.2 * env
            buf.extend(struct.pack('<h', int(max(-1.0, min(1.0, val)) * 32767)))

    elif sound_key == "clock_sharp_tick":
        num_samples = int(sample_rate * 0.12)
        for i in range(num_samples):
            t = i / sample_rate
            env = math.exp(-t * 120)
            val = (math.sin(2 * math.pi * 4200 * t) * 0.3 + math.sin(2 * math.pi * 2200 * t) * 0.4 + math.sin(2 * math.pi * 850 * t) * 0.3) * env
            val += (math.sin(t * 54321) % 1.0 - 0.5) * 0.25 * env
            buf.extend(struct.pack('<h', int(max(-1.0, min(1.0, val)) * 32767)))

    elif sound_key == "clock_wooden_tock":
        num_samples = int(sample_rate * 0.2)
        for i in range(num_samples):
            t = i / sample_rate
            env = math.exp(-t * 45)
            val = (math.sin(2 * math.pi * 1200 * t) * 0.5 + math.sin(2 * math.pi * 600 * t) * 0.4) * env
            buf.extend(struct.pack('<h', int(max(-1.0, min(1.0, val)) * 32767)))

    elif sound_key == "clock_cuckoo_short":
        num_samples = int(sample_rate * 0.35)
        for i in range(num_samples):
            t = i / sample_rate
            val = 0
            if 0 <= t < 0.12:
                val = math.sin(2 * math.pi * 1046.5 * t) * 0.6 * math.exp(-t * 20)
            elif 0.14 <= t < 0.32:
                t2 = t - 0.14
                val = math.sin(2 * math.pi * 783.99 * t2) * 0.6 * math.exp(-t2 * 15)
            buf.extend(struct.pack('<h', int(max(-1.0, min(1.0, val)) * 32767)))

    if not buf:
        return None, sample_rate, channels, sw

    raw_frames = silent_padding + bytes(buf)
    return raw_frames, sample_rate, channels, sw

def play_in_memory_pcm_sound(sound_key, target_device_str=None, mode="dual", volume=None):
    """디스크 파일 0개! 메모리 상에서 PCM 파형을 즉시 연산하여 스피커로 바로 재생합니다냥! 🧠🔊"""
    raw_frames, sample_rate, channels, sw = generate_sound_pcm_in_memory(sound_key)
    if not raw_frames:
        return False
        
    if volume is None:
        try:
            if 'settings' in globals() and hasattr(globals()['settings'], 'data'):
                volume = float(globals()['settings'].data.get("alarm_speaker_volume", 80)) / 100.0
            elif 'settings_ref' in globals() and hasattr(globals()['settings_ref'], 'data'):
                volume = float(globals()['settings_ref'].data.get("alarm_speaker_volume", 80)) / 100.0
            else: volume = 0.8
        except: volume = 0.8

    try:
        import pyaudio, struct
        p = pyaudio.PyAudio()
        
        target_index = None
        default_index = None
        try:
            default_info = p.get_default_output_device_info()
            default_index = default_info['index']
        except: pass

        if target_device_str:
            tokens, raw_keywords = _get_device_keywords_from_id(target_device_str)
            if tokens or raw_keywords:
                best_score = 0
                for i in range(p.get_device_count()):
                    try:
                        info = p.get_device_info_by_index(i)
                        if info.get('maxOutputChannels', 0) > 0:
                            dev_name = info.get('name', '')
                            score = _calculate_device_name_match_score(dev_name, tokens, raw_keywords)
                            if score > best_score:
                                best_score = score
                                target_index = i
                    except: pass

        out_indices = []
        if mode == "dual":
            if default_index is not None: out_indices.append(default_index)
            if target_index is not None and target_index not in out_indices: out_indices.append(target_index)
        else:
            if target_index is not None: out_indices.append(target_index)
            elif default_index is not None: out_indices.append(default_index)

        if not out_indices and default_index is not None:
            out_indices.append(default_index)

        if sw == 2 and volume != 1.0:
            sample_count = len(raw_frames) // 2
            samples = struct.unpack(f'<{sample_count}h', raw_frames)
            scaled_samples = [max(-32768, min(32767, int(s * volume))) for s in samples]
            raw_frames = struct.pack(f'<{sample_count}h', *scaled_samples)

        streams = []
        for idx in out_indices:
            try:
                st = p.open(format=p.get_format_from_width(sw), channels=channels, rate=sample_rate, output=True, output_device_index=idx)
                streams.append(st)
            except: pass

        if streams:
            chunk_size = 1024 * channels * sw
            for pos in range(0, len(raw_frames), chunk_size):
                chunk = raw_frames[pos:pos+chunk_size]
                for st in streams:
                    try: st.write(chunk)
                    except: pass
            for st in streams:
                try:
                    st.stop_stream()
                    st.close()
                except: pass
            p.terminate()
            return True
        p.terminate()
    except Exception:
        pass
    return False

