            import urllib.parse
            import webbrowser
            import ctypes
            import ctypes.wintypes
            import psutil
            
            found_titles = []
            target_pids = set()
            for p in psutil.process_iter(['pid', 'name']):
                if p.info['name'] and p.info['name'].lower() in ['aimp.exe', 'potplayer64.exe', 'potplayer.exe']:
                    target_pids.add(p.info['pid'])

            if target_pids:
                ENUM_WINDOWS_PROC = ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.wintypes.HWND, ctypes.wintypes.LPARAM)
                def foreach_window(hwnd, lParam):
                    pid = ctypes.wintypes.DWORD()
                    ctypes.windll.user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
                    if pid.value in target_pids:
                        length = ctypes.windll.user32.GetWindowTextLengthW(hwnd)
                        if length > 0:
                            buff = ctypes.create_unicode_buffer(length + 1)
                            ctypes.windll.user32.GetWindowTextW(hwnd, buff, length + 1)
                            title = buff.value
                            if title in ["Default IME", "MSCTFIME UI"]: return True
                            
                            try:
                                name = psutil.Process(pid.value).name().lower()
                            except:
                                return True
                                
                            if name == 'aimp.exe':
                                if title.endswith(' - AIMP'): found_titles.append((title[:-7], True))
                                elif title != "AIMP": found_titles.append((title, True))
                            elif name in ['potplayer.exe', 'potplayer64.exe']:
                                if title.endswith(' - PotPlayer'): found_titles.append((title[:-12], False))
                                elif title.endswith(' - 팟플레이어'): found_titles.append((title[:-9], False))
                                elif title.endswith(' - PotPlayer64'): found_titles.append((title[:-14], False))
                                else: found_titles.append((title, False))
                    return True
                    
                ctypes.windll.user32.EnumWindows(ENUM_WINDOWS_PROC(foreach_window), 0)
            
            valid_titles = [t for t in found_titles if t[0] not in ["QFI", "AIMP", "GDI+ Window", "Media context", "OleMainThreadWndName", "Default IME", "MSCTFIME UI", "PotPlayer64", "PotPlayer", "팟플레이어"]]
            best_tuple = max(valid_titles, key=lambda x: len(x[0])) if valid_titles else None

            if best_tuple:
                best_title, is_aimp = best_tuple
                import re
                # 1. 숫자. (공백) 으로 시작하는 플레이리스트 인덱스 제거 (예: "1374. Mariah Carey" -> "Mariah Carey")
                best_title = re.sub(r'^\d+\.\s*', '', best_title)
                # 2. AIMP 호환성 등 이유로 끝에 붙는 " - Winamp" 꼬리표 제거
                best_title = re.sub(r'\s*-\s*Winamp$', '', best_title, flags=re.IGNORECASE)
                
                print(f"\r\n 🔍 {ctext(f'[{best_title}] 덕덕고 AI 검색 준비 중...', C.CYAN)}")
                
