# [TAG: #@windows_tweak_menu_interactive]
def _get_browser_exe_path(browser_name):
    """브라우저 실행 파일 경로 획득"""
    import os
    import winreg
    exe_names = {
        'chrome': 'chrome.exe',
        'whale': 'whale.exe',
        'edge': 'msedge.exe'
    }
    exe_name = exe_names.get(browser_name)
    if not exe_name:
        return None
        
    try:
        key_path = rf"SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths\{exe_name}"
        with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, key_path) as key:
            val, _ = winreg.QueryValueEx(key, "")
            return val
    except Exception:
        try:
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, key_path) as key:
                val, _ = winreg.QueryValueEx(key, "")
                return val
        except Exception:
            pass
            
    # 하드코딩 백업 경로
    program_files = os.environ.get('ProgramFiles', r'C:\Program Files')
    program_files_x86 = os.environ.get('ProgramFiles(x86)', r'C:\Program Files (x86)')
    local_appdata = os.environ.get('LOCALAPPDATA', '')
    
    fallbacks = {
        'chrome': [
            os.path.join(program_files, r'Google\Chrome\Application\chrome.exe'),
            os.path.join(program_files_x86, r'Google\Chrome\Application\chrome.exe'),
            os.path.join(local_appdata, r'Google\Chrome\Application\chrome.exe')
        ],
        'whale': [
            os.path.join(program_files, r'Naver\Naver Whale\Application\whale.exe'),
            os.path.join(program_files_x86, r'Naver\Naver Whale\Application\whale.exe'),
            os.path.join(local_appdata, r'Naver\Naver Whale\Application\whale.exe')
        ],
        'edge': [
            os.path.join(program_files_x86, r'Microsoft\Edge\Application\msedge.exe'),
            os.path.join(program_files, r'Microsoft\Edge\Application\msedge.exe')
        ]
    }
    
    for path in fallbacks.get(browser_name, []):
        if os.path.exists(path):
            return path
            
    return None


