# [TAG: #@_get_system_default_browser]

def _get_system_default_browser(browsers_def=None):
    """윈도우 레지스트리를 읽어 현재 기본 웹 브라우저의 실행 파일 경로 및 이름을 구합니다."""
    import winreg
    import os
    
    if browsers_def is None:
        browsers_def = _get_browser_definitions()
    
    b_path = None
    b_name = "chrome"
    
    try:
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\Shell\Associations\UrlAssociations\http\UserChoice") as key:
            prog_id, _ = winreg.QueryValueEx(key, "ProgId")
        
        with winreg.OpenKey(winreg.HKEY_CLASSES_ROOT, f"{prog_id}\\shell\\open\\command") as key:
            cmd, _ = winreg.QueryValueEx(key, "")
            
        cmd = cmd.strip()
        if cmd.startswith('"'):
            end = cmd.find('"', 1)
            if end != -1:
                b_path = cmd[1:end]
        else:
            b_path = cmd.split()[0]
            
        if b_path and os.path.exists(b_path):
            lower_path = b_path.lower()
            if "chrome" in lower_path:
                b_name = "chrome"
            elif "edge" in lower_path or "msedge" in lower_path:
                b_name = "edge"
            elif "whale" in lower_path:
                b_name = "whale"
            elif "brave" in lower_path:
                b_name = "brave"
            elif "firefox" in lower_path:
                b_name = "firefox"
    except Exception:
        pass
        
    if not b_path or not os.path.exists(b_path):
        b_path = None
        for name in ['chrome', 'whale', 'edge', 'brave', 'firefox']:
            for p in browsers_def[name]['paths']:
                if p and os.path.exists(p):
                    b_path = p
                    b_name = name
                    break
            if b_path:
                break
                
    return b_name, b_path


# [TAG: #@_create_multi_url_bat_shortcut]

def _create_multi_url_bat_shortcut(settings):
    """새창으로 여러탭 동시에 열기 바로가기 만들기 (bat)"""
    import os
    import shutil
    import subprocess
    import winreg
    
    # 1. multi_url 단축키 찾기
    custom_shortcuts = settings.data.get('custom_shortcuts', {})
    multi_url_shortcuts = {}
    for k, v in custom_shortcuts.items():
        if isinstance(v, dict) and v.get('type') == 'multi_url':
            multi_url_shortcuts[k] = v
            
    # 2. 독립형 여러 웹 그룹 가져오기
    independent_groups = settings.data.get('independent_bat_groups', {})
    if not isinstance(independent_groups, dict):
        independent_groups = {}
        settings.data['independent_bat_groups'] = independent_groups
        settings.save()
        
    # 3. 그룹 선택 메뉴 리스트 빌드
    sc_options = [" ➕ [신규 독립 그룹] 단축키 없는 독립 여러 웹 그룹 만들기 🚀"]
    group_map = []
    group_map.append(('new_independent', None, []))
    
    # 단축키 그룹 추가
    for k, v in multi_url_shortcuts.items():
        tgt = v.get('target', [])
        urls_str = ", ".join(tgt)
        if len(urls_str) > 40:
            urls_str = urls_str[:37] + "..."
        sc_options.append(f" 🔗 [단축키 그룹] {k} -> {urls_str} ({len(tgt)}개)")
        group_map.append(('shortcut', k, tgt))
        
    # 독립 그룹 추가
    for k, tgt in independent_groups.items():
        urls_str = ", ".join(tgt)
        if len(urls_str) > 40:
            urls_str = urls_str[:37] + "..."
        sc_options.append(f" 📄 [독립 그룹] {k} -> {urls_str} ({len(tgt)}개)")
        group_map.append(('independent', k, tgt))
        
    sc_options.append(" ❌ 취소")
    
    sc_sel = menu("🌐 바로가기(.bat)로 만들 여러 웹 그룹을 골라줘냥!", sc_options)
    if sc_sel < 0 or sc_sel >= len(group_map):
        return
        
    sel_type, sel_key, urls = group_map[sc_sel]
    
    # 3-1. 신규 독립 그룹 생성 처리
    if sel_type == 'new_independent':
        print("\r\n ➕ 새로 만들 독립 여러 웹 그룹의 이름을 정해줘냥:")
        print("    (예: 작업용, 공부방, 오전뉴스 등. 바탕화면 bat 파일명에 쓰입니다.)")
        new_name = input(" 👉 ").strip()
        if not new_name:
            print(" ⚠️ 이름이 입력되지 않아 취소되었어냥.")
            pause()
            return
            
        for char in ['\\', '/', ':', '*', '?', '"', '<', '>', '|']:
            new_name = new_name.replace(char, '_')
            
        if new_name in independent_groups:
            print(f" ⚠️ '{new_name}' 그룹이 이미 존재해냥!")
            pause()
            return
            
        independent_groups[new_name] = []
        settings.data['independent_bat_groups'] = independent_groups
        settings.save()
        
        sel_type = 'independent'
        sel_key = new_name
        urls = []
        
        updated_urls = _edit_shortcut_urls(settings, sel_key, urls, is_independent=True)
        if updated_urls is not None:
            urls = updated_urls
        else:
            del independent_groups[sel_key]
            settings.save()
            return
    
    # 3-2. 기존 그룹에 대한 작업 선택
    else:
        while True:
            action_options = [
                f" 🚀 이대로 바탕화면에 바로가기(.bat) 배포하기 ({len(urls)}개 URL)",
                " ✏️ 사이트 URL 목록 편집하기 (추가/수정/삭제)",
            ]
            if sel_type == 'independent':
                action_options.append(" 🗑️ 이 독립 그룹 전체 삭제하기")
            action_options.append(" ❌ 취소")
            
            action_sel = menu(f"⚙️ [{sel_key} 그룹] 다음 작업을 골라줘냥!", action_options)
            if action_sel < 0:
                return
                
            cancel_idx = 3 if sel_type == 'independent' else 2
            if action_sel == cancel_idx:
                return
                
            if action_sel == 1:
                is_ind = (sel_type == 'independent')
                updated_urls = _edit_shortcut_urls(settings, sel_key, urls, is_independent=is_ind)
                if updated_urls is not None:
                    urls = updated_urls
                    if is_ind:
                        independent_groups = settings.data.get('independent_bat_groups', {})
                continue
                
            elif sel_type == 'independent' and action_sel == 2:
                confirm = menu(f"⚠️ 정말로 '{sel_key}' 그룹을 완전히 삭제할 거야냥?", [" 🗑️ 삭제", " ❌ 취소"])
                if confirm == 0:
                    del independent_groups[sel_key]
                    settings.save()
                    ok(f" 🗑️ '{sel_key}' 그룹이 삭제되었어냥!")
                    time.sleep(1)
                    return
                continue
                
            elif action_sel == 0:
                break
                
    if not urls:
        print(f"\r\n {C.RED}❌ 등록된 URL 주소가 하나도 없어 배포할 수 없어냥!{C.RESET}")
        pause()
        return
        
    # 4. 설치된 브라우저 사전 검색 맵 빌드
    browsers_def = _get_browser_definitions()
    
    installed_browsers = []
    for b_key, b_info in browsers_def.items():
        found_path = None
        for p in b_info['paths']:
            if p and os.path.exists(p):
                found_path = p
                break
        if found_path:
            installed_browsers.append({
                'key': b_key,
                'name': b_info['name'],
                'path': found_path,
                'new_window_flag': b_info['new_window_flag'],
                'incognito_flag': b_info['incognito_flag']
            })
            
    # 5. 브라우저 선택 메뉴 구성 (시스템 기본 + 설치된 브라우저 목록)
    br_options = [" 💻 시스템 기본 브라우저 (자동 감지)"]
    for b in installed_browsers:
        br_options.append(f" 🌐 {b['name']}")
    br_options.append(" ❌ 취소")
    
    br_sel = menu("🌐 사용할 웹 브라우저를 골라줘냥!", br_options)
    if br_sel < 0 or br_sel >= len(br_options) - 1:
        return
        
    selected_browser = None
    if br_sel == 0:
        b_name, b_path = _get_system_default_browser(browsers_def)
        b_info = browsers_def.get(b_name, browsers_def['chrome'])
        selected_browser = {
            'key': b_name,
            'name': f"시스템 기본 브라우저 ({b_info['name']})",
            'path': b_path,
            'new_window_flag': b_info['new_window_flag'],
            'incognito_flag': b_info['incognito_flag']
        }
    else:
        selected_browser = installed_browsers[br_sel - 1]
        
    # 6. 실행 모드 선택 (시크릿 모드 여부)
    incognito_options = [
        " 🕶️ 시크릿 모드 (Incognito/Private)",
        " 🌐 일반 모드 (Normal)",
        " ❌ 취소"
    ]
    incognito_sel = menu("🕶️ 브라우저 실행 모드를 골라줘냥!", incognito_options)
    if incognito_sel < 0 or incognito_sel >= 2:
        return
    use_incognito = (incognito_sel == 0)
    
    # 7. 바탕화면 폴더 경로 가져오기
    desktop = _get_desktop_path()
        
    shortcut_name = f"여러웹동시열기_{sel_key.replace('+', '_')}"
    if use_incognito:
        shortcut_name += "_시크릿"
    shortcut_name += ".bat"
    shortcut_path = os.path.join(desktop, shortcut_name)
    
    # URL 목록을 배치파일용으로 인코딩
    urls_escaped = " ".join([f'"{u}"' for u in urls])
    
    bat_content = "@echo off\r\n"
    
    b_path_escaped = selected_browser['path']
    b_exe = os.path.basename(b_path_escaped)
    
    flags = [selected_browser['new_window_flag']]
    if use_incognito:
        flags.append(selected_browser['incognito_flag'])
    flags_str = " ".join(flags)
    
    bat_content += f'rem {selected_browser["name"]} 실행\r\n'
    bat_content += f'start "" "{b_path_escaped}" {flags_str} {urls_escaped}\r\n'

    try:
        with open(shortcut_path, "w", encoding="cp949") as f:
            f.write(bat_content)
        ok(f" 🎉 바탕화면에 '{shortcut_name}' 바로가기(.bat)를 성공적으로 만들었어냥! 🚀")
    except Exception as e:
        err(f" ❌ 바로가기 생성 중 오류 발생: {e}")
        
    pause()


# [TAG: #@_get_chromium_bookmarks]

def _get_chromium_bookmarks(browser_key):
    """지정된 크로미움 브라우저의 북마크 데이터를 로드하여 트리 구조로 반환합니다."""
    import os
    import json
    
    local_appdata = os.environ.get('LOCALAPPDATA', '')
    if not local_appdata:
        return None
        
    paths = {
        'chrome': os.path.join(local_appdata, r"Google\Chrome\User Data"),
        'whale': os.path.join(local_appdata, r"Naver\Naver Whale\User Data"),
        'edge': os.path.join(local_appdata, r"Microsoft\Edge\User Data")
    }
    
    base_dir = paths.get(browser_key)
    if not base_dir or not os.path.exists(base_dir):
        return None
        
    profiles = ['Default', 'Profile 1', 'Profile 2', 'Profile 3', 'Profile 4']
    try:
        for entry in os.listdir(base_dir):
            if entry.startswith('Profile ') and entry not in profiles:
                profiles.append(entry)
    except:
        pass
        
    bookmark_file = None
    for p_dir in profiles:
        f_path = os.path.join(base_dir, p_dir, "Bookmarks")
        if os.path.exists(f_path):
            bookmark_file = f_path
            break
            
    if not bookmark_file:
        return None
        
    try:
        with open(bookmark_file, "r", encoding="utf-8") as f:
            data = json.load(f)
        return data.get('roots', {})
    except:
        return None


# [TAG: #@_explore_bookmarks_tui]

def _explore_bookmarks_tui(roots):
    """북마크 루트에서 폴더를 탐색하며 URL을 선택해 리턴하는 TUI 루프"""
    if not roots:
        return None
        
    root_node = {
        'type': 'folder',
        'name': '북마크 루트',
        'children': []
    }
    for k, v in roots.items():
        if isinstance(v, dict) and 'name' in v:
            root_node['children'].append(v)
            
    node_history = []
    current_node = root_node
    
    while True:
        options = []
        item_map = []
        
        if node_history:
            options.append(" ⬅️ [상위 폴더로 이동]")
            item_map.append('up')
            
        children = current_node.get('children', [])
        for item in children:
            t = item.get('type')
            name = item.get('name', '이름 없음')
            if t == 'folder':
                options.append(f" 📂 [폴더] {name}")
                item_map.append(('folder', item))
            elif t == 'url':
                url = item.get('url', '')
                disp_url = url if len(url) <= 40 else url[:37] + "..."
                options.append(f" 🔗 {name} ({disp_url})")
                item_map.append(('url', name, url))
                
        options.append(" ❌ 취소 및 돌아가기")
        
        sel = menu(f"⭐ 북마크 탐색: {current_node.get('name')}", options)
        if sel < 0 or sel == len(options) - 1:
            return None
            
        action = item_map[sel]
        if action == 'up':
            current_node = node_history.pop()
        elif action[0] == 'folder':
            node_history.append(current_node)
            current_node = action[1]
        elif action[0] == 'url':
            return action[2]


# [TAG: #@_create_app_shortcut]

def _create_app_shortcut():
    """Gemini 자막 자동 생성기 바로가기 바탕화면에 만들기"""
    import os
    import sys
    import subprocess
    import winreg

    try:
        # 1. 바탕화면 폴더 경로 가져오기
        desktop = _get_desktop_path()

        # 2. 바로가기 생성 파일 경로
        script_path = os.path.abspath(sys.argv[0])
        working_dir = os.path.dirname(script_path)
        shortcut_name = "Gemini 자막 자동 생성기.lnk"
        shortcut_path = os.path.join(desktop, shortcut_name)

        # 3. 파이썬 실행 경로
        py_exe = sys.executable
        arguments = f'"{script_path}"'

        # 4. PowerShell WScript 바로가기 생성 커맨드
        ps_cmd = f"""
        $Shell = New-Object -ComObject WScript.Shell
        $Shortcut = $Shell.CreateShortcut("{shortcut_path}")
        $Shortcut.TargetPath = "{py_exe}"
        $Shortcut.Arguments = '{arguments}'
        $Shortcut.WorkingDirectory = "{working_dir}"
        $Shortcut.IconLocation = "{py_exe},0"
        $Shortcut.Description = "Gemini 고성능 동영상 자막 자동 생성기"
        $Shortcut.Save()
        """

        proc = subprocess.run(["powershell", "-Command", ps_cmd], capture_output=True, text=True)
        if proc.returncode == 0 and os.path.exists(shortcut_path):
            ok(f" 🎉 바탕화면에 '{shortcut_name}' 바로가기를 성공적으로 만들었어냥! 🚀")
            print(f"  👉 실행경로: {py_exe}")
            print(f"  👉 스크립트: {script_path}")
            print(f"  💡 이제 이 바로가기를 드래그해서 작업표시줄에 고정하면 돼냥! 👍")
        else:
            err(f" ❌ 바로가기 생성 실패: {proc.stderr}")
    except Exception as e:
        err(f" ❌ 바로가기 생성 중 오류 발생: {e}")

    pause()


# [TAG: #@_tweak_browser_gpu_toggle]

def _tweak_browser_gpu_toggle(target_browser=None, interactive=True):
    """브라우저 하드웨어 가속 토글 (Chrome/Whale/Edge)"""
    import os
    import json
    import psutil
    import time
    import subprocess
    
    appdata = os.environ.get('LOCALAPPDATA')
    if not appdata:
        print(f"\r\n ❌ {C.RED}LOCALAPPDATA 환경 변수를 찾을 수 없어냥!{C.RESET}")
        pause()
        return

    # 브라우저별 경로 설정
    browsers = {
        'chrome': {
            'name': 'Google Chrome',
            'path': os.path.join(appdata, r'Google\Chrome\User Data\Local State'),
            'process': 'chrome.exe'
        },
        'whale': {
            'name': '네이버 웨일 (Naver Whale)',
            'path': os.path.join(appdata, r'Naver\Naver Whale\User Data\Local State'),
            'process': 'whale.exe'
        },
        'edge': {
            'name': 'Microsoft Edge',
            'path': os.path.join(appdata, r'Microsoft\Edge\User Data\Local State'),
            'process': 'msedge.exe'
        }
    }

    # 단일 브라우저 즉시 토글 처리 루틴
    def do_toggle(bkey):
        binfo = browsers[bkey]
        path = binfo['path']
        if not os.path.exists(path):
            err(f"{binfo['name']}의 설정 파일(Local State)이 존재하지 않아냥! 먼저 브라우저를 한 번 실행해줘.")
            if interactive: pause()
            return False
            
        try:
            with open(path, 'r', encoding='utf-8') as f:
                data = json.load(f)
                is_enabled1 = data.get('hardware_acceleration_mode_enabled', True)
                is_enabled2 = True
                if 'hardware_acceleration_mode' in data and isinstance(data['hardware_acceleration_mode'], dict):
                    is_enabled2 = data['hardware_acceleration_mode'].get('enabled', True)
                is_enabled = is_enabled1 and is_enabled2
        except Exception as e:
            err(f"설정 파일 읽기 오류: {e}")
            if interactive: pause()
            return False
            
        target_val = not is_enabled
        target_val_str = "활성화(ON)" if target_val else "비활성화(OFF)"
        
        proc_name = binfo['process']
        is_running = False
        for proc in psutil.process_iter(['name']):
            if proc.info['name'] and proc.info['name'].lower() == proc_name.lower():
                is_running = True
                break
                
        if is_running:
            if interactive:
                print(f"\r\n ⚠️ {C.RED}경고: {binfo['name']}이 현재 실행 중이야!{C.RESET}")
                print(f"    {C.DIM}브라우저를 종료하고 설정을 적용한 뒤, 마지막 열린 탭 그대로 다시 켤게냥!{C.RESET}")
                ans = input(f" 👉 {C.LIGHT_GREEN}진행할까냥? (y/n) : {C.RESET}").strip().lower()
                if ans not in ('y', 'yes', '예', 'ㅇ'):
                    print(f" ❌ {C.RED}작업이 취소되었습니다냥!{C.RESET}")
                    return False
            else:
                print(f"\r\n 🚀 {C.YELLOW}{binfo['name']} 가속 토글을 위해 브라우저를 종료하고 다시 켤게냥!{C.RESET}")
                time.sleep(1)
                
            # 프로세스 정상 종료 시도 (Graceful Close - 탭 복구 경고 방지)
            import subprocess
            try:
                subprocess.run(f'taskkill /IM {proc_name}', shell=True, capture_output=True)
            except Exception:
                pass
                
            closed = False
            for _ in range(15):
                time.sleep(0.2)
                still_running = False
                for proc in psutil.process_iter(['name']):
                    if proc.info['name'] and proc.info['name'].lower() == proc_name.lower():
                        still_running = True
                        break
                if not still_running:
                    closed = True
                    break
            
            # 정상 종료 실패 시 강제 종료(Fallback)
            if not closed:
                killed = False
                for proc in psutil.process_iter(['name']):
                    if proc.info['name'] and proc.info['name'].lower() == proc_name.lower():
                        try:
                            proc.kill()
                            killed = True
                        except Exception:
                            pass
                if killed:
                    print(f" ⚠️ {binfo['name']}이 정상 종료되지 않아 강제로 종료했어냥!{C.RESET}")
                    time.sleep(1.5)
            else:
                print(f" ✅ {binfo['name']}을 정상적으로 종료했어냥! (탭 복구 경고 방지) 👍{C.RESET}")
                time.sleep(1.0)
            
        # 설정 변경
        try:
            with open(path, 'r', encoding='utf-8') as f:
                data = json.load(f)
            
            data['hardware_acceleration_mode_enabled'] = target_val
            if 'hardware_acceleration_mode' in data:
                if isinstance(data['hardware_acceleration_mode'], dict):
                    data['hardware_acceleration_mode']['enabled'] = target_val
                else:
                    data['hardware_acceleration_mode'] = {'enabled': target_val}
            else:
                data['hardware_acceleration_mode'] = {'enabled': target_val}
                
            with open(path, 'w', encoding='utf-8') as f:
                json.dump(data, f, indent=2, ensure_ascii=False)
            print(f" ✅ {C.GREEN}{binfo['name']}의 하드웨어 가속을 [{target_val_str}]으로 변경했어냥!{C.RESET}")
        except Exception as e:
            err(f"설정 변경 중 오류 발생: {e}")
            if interactive: pause()
            return False
            
        if is_running:
            # 브라우저 다시 켜기 (마지막 세션 복구 옵션)
            exe_path = _get_browser_exe_path(bkey)
            if exe_path and os.path.exists(exe_path):
                try:
                    # [V160.42] 관리자 권한 상속 방지를 위해 비승격 실행 적용냥! 🛡️
                    _open_unelevated(exe_path, "--restore-last-session")
                    ok(f"{binfo['name']}을 이전 탭들과 함께 다시 열었어냥! 🚀")
                except Exception as e:
                    err(f"브라우저 재실행 실패: {e}")
            else:
                err(f"브라우저 실행 파일 경로를 찾을 수 없어냥! 직접 실행해줘.")
        else:
            ok(f"{binfo['name']}의 하드웨어 가속을 [{target_val_str}]으로 변경했어냥! (꺼져 있어 설정만 변경) ✨")
            
        if interactive:
            pause()
        else:
            time.sleep(3.0)
        return True

    # 1. 즉시 실행 타겟이 인자로 주어진 경우
    if target_browser in browsers:
        do_toggle(target_browser)
        return

    # 2. 대화형 메뉴 루프
    while True:
        clear_console(push_history=False)
        
        info_pairs = []
        info_dict = {}
        for bkey, binfo in browsers.items():
            path = binfo['path']
            exists = os.path.exists(path)
            state_str = f"{C.GRAY}미설치 (또는 프로필 없음){C.RESET}"
            is_enabled = True
            
            if exists:
                try:
                    with open(path, 'r', encoding='utf-8') as f:
                        data = json.load(f)
                        is_enabled1 = data.get('hardware_acceleration_mode_enabled', True)
                        is_enabled2 = True
                        if 'hardware_acceleration_mode' in data and isinstance(data['hardware_acceleration_mode'], dict):
                            is_enabled2 = data['hardware_acceleration_mode'].get('enabled', True)
                        is_enabled = is_enabled1 and is_enabled2
                    state_str = f"{C.GREEN}🟢 활성화 (ON){C.RESET}" if is_enabled else f"{C.DIM}⚫ 비활성화 (OFF){C.RESET}"
                except Exception:
                    state_str = f"{C.RED}❌ 설정 읽기 오류{C.RESET}"
            
            info_pairs.append((binfo['name'], state_str))
            info_dict[bkey] = {'exists': exists, 'is_enabled': is_enabled}
            
        info_pairs.append(("설명", "크롬, 웨일, 엣지 브라우저의 하드웨어 가속 설정을 ON/OFF로 토글합니다."))
        
        warn_msg = f"{C.GOLD}⚠️ 켜져 있는 브라우저를 토글하면 종료 후 이전 탭들과 함께 자동 재실행돼!{C.RESET}"
        
        _print_mode_dashboard(
            "브라우저 하드웨어 가속 설정 토글",
            info_pairs,
            [warn_msg],
            clear=False
        )
                  
        options = []
        for bkey, binfo in browsers.items():
            tinfo = info_dict[bkey]
            icon = "🌐"
            if bkey == 'chrome': icon = "🌐"
            elif bkey == 'whale': icon = "🐳"
            elif bkey == 'edge': icon = "🟩"
            
            state_icon = "🟢" if tinfo['is_enabled'] else "⚫"
            if not tinfo['exists']:
                options.append(f" {icon} {binfo['name']} 하드웨어 가속 토글 (설치되지 않음)")
            else:
                options.append(f" {icon} {binfo['name']} 하드웨어 가속 토글 {state_icon}")
                
        options.append(" ❌ 이전 메뉴로 돌아가기")
        
        sel = menu("🌐 브라우저 선택", options)
        if sel < 0 or sel >= 3:
            break
            
        bkeys = ['chrome', 'whale', 'edge']
        target_key = bkeys[sel]
        
        do_toggle(target_key)


