# [TAG: #@_async_update_public_ip]

def _async_update_public_ip__REMOVE_TARGET(local_ip):
    global _G_CACHED_PUBLIC_IP, _G_PUBLIC_IP_LOADING
    if _G_PUBLIC_IP_LOADING:
        return
    _G_PUBLIC_IP_LOADING = True
    
    def worker():
        global _G_CACHED_PUBLIC_IP, _G_PUBLIC_IP_LOADING
        try:
            pub = _get_public_ip_via_adapter(local_ip) if local_ip else "조회 실패"
            with _G_CACHED_PUBLIC_IP_LOCK:
                _G_CACHED_PUBLIC_IP = pub
        except Exception:
            pass
        finally:
            _G_PUBLIC_IP_LOADING = False
            
    t = threading.Thread(target=worker, daemon=True)
    t.start()

