# [TAG: #@_tweak_open_gateway_web]

def _tweak_open_gateway_web(settings):
    try:
        return _tweak_open_gateway_web_body(settings)
    except UserAbortException:
        return

def _tweak_open_gateway_web_body(settings):
    import webbrowser
    import time
    
    # 동적 게이트웨이 감지
    gw_ip = _get_default_gateway()
    if not gw_ip:
        print(f"\r\n❌ {ctext('기본 게이트웨이가 감지되지 않았습니다냥! 😢', C.RED)}")
        time.sleep(1.5)
        return
        
    if not _is_private_ip(gw_ip):
        print(f"\r\n⚠️ {ctext(f'주의: 감지된 게이트웨이 [{gw_ip}]는 내부(사설) IP가 아닙니다냥!', C.YELLOW)}")
        print(f"공유기 설정 페이지는 보통 사설 대역(192.168.x.x 등)에서만 운영됩니다.")
        ans = menu("🌐 그래도 브라우저로 접속을 시도해볼까냥?", [
            f" 🚀 예, 열어주세요 (http://{gw_ip})",
            " ❌ 아니요, 돌아갑니다냥"
        ])
        if ans != 0:
            return
            
    url = f"http://{gw_ip}"
    print(f"\r\n 🌐 {ctext(f'기본 게이트웨이 [{gw_ip}] 웹 페이지를 브라우저로 엽니다냥! 🚀', C.GREEN)}")
    webbrowser.open(url)
    time.sleep(1.5)

# [TAG: #@_tweak_win_notifications]
def _tweak_win_notifications():
    """[V22.0] 윈도우 수신 알림 확인 및 삭제 관리 기능 🔔"""
    if '_timer_mgr' in globals():
        globals()['_timer_mgr'].hide_status = True
    try:
        _tweak_win_notifications_impl()
    finally:
        if '_timer_mgr' in globals():
            globals()['_timer_mgr'].hide_status = False

# [TAG: #@_tweak_win_notifications_impl]

def _tweak_win_notifications_impl():
    try:
        import winsdk
    except ImportError:
        print(f"\r\n🔍 {ctext('윈도우 알림 리스너 기능을 사용하려면 winsdk 패키지가 필요해냥!', C.YELLOW)}")
        ok = _auto_install("winsdk", desc="윈도우 SDK 통신 라이브러리")
        if not ok:
            print(f"❌ {ctext('winsdk 설치에 실패해서 기능을 실행할 수 없어냥. 😿', C.RED)}")
            time.sleep(2)
            return
        try:
            import winsdk
        except ImportError:
            print(f"❌ {ctext('설치 후 winsdk 모듈 로딩에 실패했어냥. 😿', C.RED)}")
            time.sleep(2)
            return

    from winsdk.windows.ui.notifications.management import UserNotificationListener
    from winsdk.windows.ui.notifications import NotificationKinds
    import datetime

    def run_async_safe(coro):
        import asyncio
        from concurrent.futures import ThreadPoolExecutor, as_completed
        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            loop = None
        if loop and loop.is_running():
            with ThreadPoolExecutor() as executor:
                return executor.submit(asyncio.run, coro).result()
        else:
            return asyncio.run(coro)

    async def get_listener_and_access():
        listener = UserNotificationListener.current
        access_status = await listener.request_access_async()
        return listener, access_status

    print(f"\r\n🔄 {ctext('윈도우 알림 접근 권한을 확인 중이야냥... 🔐', C.SKY)}")
    try:
        listener, access_status = run_async_safe(get_listener_and_access())
    except Exception as e:
        print(f"❌ {ctext(f'알림 리스너 초기화 에러: {e}', C.RED)}")
        print(f"👉 {ctext('이 기능은 Windows 10 버전 1607 이상 및 Windows 11에서만 지원돼냥!', C.DIM)}")
        time.sleep(3)
        return

    # access_status: 1 (Allowed)
    if int(access_status) != 1:
        print(f"\r\n❌ {ctext('윈도우 알림 접근 권한이 거부되었어냥! 🔒', C.RED)}")
        print(f"💡 {ctext('설정하는 법:', C.GOLD)}")
        print("  1. 윈도우 [설정] -> [개인 정보 및 보안] -> [알림]으로 이동해냥.")
        print("  2. '앱에서 내 알림에 접근하도록 허용' 옵션을 켜줘냥!")
        print("  3. 만약 파이썬 앱이 패키징되지 않았다면 윈도우가 승인을 차단할 수 있어냥. ⚠️")
        time.sleep(5)
        return

    while True:
        async def fetch_notifs():
            return await listener.get_notifications_async(NotificationKinds.TOAST)

        try:
            notifications = run_async_safe(fetch_notifs())
        except Exception as e:
            print(f"❌ {ctext(f'알림 목록을 가져오는 중 오류 발생: {e}', C.RED)}")
