                    _ext_str = str(_ext_item.get('label', _ext_item) if isinstance(_ext_item, dict) else _ext_item)
                    if "일괄 제외 등록" in _ext_str:
                        ext_str = ",".join([f"'{m}'" for m in media_exts])
