# [TAG: #@_get_next_recurring_app_alarm_datetime]
def _get_next_recurring_app_alarm_datetime(settings_or_alarms):
    """안드로이드 알람 스타일 고정 앱 알람(요일별/매월) 중 가장 가까운 다음 알람 일시를 반환합니다."""
    import datetime as _dt_mod
    alarms = []
    if hasattr(settings_or_alarms, 'data'):
        alarms = settings_or_alarms.data.get('recurring_app_alarms', [])
    elif isinstance(settings_or_alarms, list):
        alarms = settings_or_alarms
    elif isinstance(settings_or_alarms, dict):
        alarms = settings_or_alarms.get('recurring_app_alarms', [])

    active_alarms = [a for a in alarms if a.get('enabled', True)]
    if not active_alarms:
        return None, None

    now = _dt_mod.datetime.now()
    earliest_dt = None
    earliest_alarm = None

    for alarm in active_alarms:
        time_str = alarm.get('time', '09:00')
        try:
            parts = time_str.split(':')
            h, m = int(parts[0]), int(parts[1])
        except Exception:
            continue

        rep_type = alarm.get('repeat_type', 'monthly' if alarm.get('month_days') else 'weekly')
        if rep_type == 'monthly' or alarm.get('month_days'):
            month_days = alarm.get('month_days', [])
            if not month_days:
                continue
            for day_offset in range(95):
                target_date = now.date() + _dt_mod.timedelta(days=day_offset)
                act_days = _get_actual_days_in_month(target_date.year, target_date.month, month_days)
                if target_date.day in act_days:
                    candidate_dt = _dt_mod.datetime.combine(target_date, _dt_mod.time(hour=h, minute=m))
                    if candidate_dt > now + _dt_mod.timedelta(seconds=10):
                        if earliest_dt is None or candidate_dt < earliest_dt:
                            earliest_dt = candidate_dt
                            earliest_alarm = alarm
                        break
        else:
            days = alarm.get('days', [0, 1, 2, 3, 4])
            if not days:
                continue
            for day_offset in range(8):
                target_date = now.date() + _dt_mod.timedelta(days=day_offset)
                if target_date.weekday() in days:
                    candidate_dt = _dt_mod.datetime.combine(target_date, _dt_mod.time(hour=h, minute=m))
                    if candidate_dt > now + _dt_mod.timedelta(seconds=10):
                        if earliest_dt is None or candidate_dt < earliest_dt:
                            earliest_dt = candidate_dt
                            earliest_alarm = alarm
                        break

    if earliest_dt and earliest_alarm:
        rep_type = earliest_alarm.get('repeat_type', 'monthly' if earliest_alarm.get('month_days') else 'weekly')
        if rep_type == 'monthly' or earliest_alarm.get('month_days'):
            sched_str = _format_month_days_text(earliest_alarm.get('month_days', []))
        else:
            sched_str = _format_days_text(earliest_alarm.get('days', []))
        label = earliest_alarm.get('label', '고정 알람')
        info = f"{label} [{sched_str}] ({earliest_dt.strftime('%m/%d %H:%M')})"
        return earliest_dt, info

    return None, None


# [TAG: #@_manage_recurring_app_alarms]
def _manage_recurring_app_alarms(settings):
    """요일별/매월 고정 앱 알람 설정 TUI (앱 표준 대시보드 팁 상단 표기 & Space 선택/일괄 작업)"""
    import datetime, time

    while True:
        alarms = settings.data.get('recurring_app_alarms', [])
        sort_by_time = settings.data.get('sort_app_alarms_by_time', False)
        
        options = []
        action_map = []
        alarm_index_by_opt = {}

        weekly_alarms = []
        monthly_alarms = []
        for orig_idx, alarm in enumerate(alarms):
            rep_type = alarm.get("repeat_type", "monthly" if alarm.get("month_days") else "weekly")
            if rep_type == "monthly" or alarm.get("month_days"):
                monthly_alarms.append((orig_idx, alarm))
            else:
                weekly_alarms.append((orig_idx, alarm))

        if sort_by_time:
            weekly_alarms.sort(key=lambda x: x[1].get("time", "00:00"))
            monthly_alarms.sort(key=lambda x: x[1].get("time", "00:00"))

        indexed_alarms = weekly_alarms + monthly_alarms

        if not alarms:
            options.append(구분선("등록된 고정 알람 목록", icon="📌"))
            action_map.append(None)
            options.append("    (등록된 고정 알람이 없어. 아래 ➕ 버튼으로 추가해줘! 👍)")
            action_map.append(None)
        else:
            # 1. 요일별(매주) 알람 목록 그룹
            if weekly_alarms:
                options.append(구분선(f"요일별(매주) 고정 알람 ({len(weekly_alarms)}개)", icon="📅"))
                action_map.append(None)
                for orig_idx, alarm in weekly_alarms:
                    status_icon = "🟢 [ON] " if alarm.get("enabled", True) else "🔴 [OFF]"
                    schedule_text = _format_days_text(alarm.get("days", []))
                    label = alarm.get("label", "고정 알람")
                    time_str = alarm.get("time", "09:00")
                    lbl = f" {status_icon} {time_str} | {schedule_text} | {label}"
                    opt_idx = len(options)
                    options.append(lbl)
                    action_map.append(f"alarm_{orig_idx}")
                    alarm_index_by_opt[opt_idx] = orig_idx

            # 2. 매월(일자별) 알람 목록 그룹
            if monthly_alarms:
                options.append(구분선(f"매월(일자별) 고정 알람 ({len(monthly_alarms)}개)", icon="🗓️"))
                action_map.append(None)
                for orig_idx, alarm in monthly_alarms:
                    status_icon = "🟢 [ON] " if alarm.get("enabled", True) else "🔴 [OFF]"
                    schedule_text = _format_month_days_text(alarm.get("month_days", []))
                    label = alarm.get("label", "고정 알람")
                    time_str = alarm.get("time", "09:00")
                    lbl = f" {status_icon} {time_str} | {schedule_text} | {label}"
                    opt_idx = len(options)
                    options.append(lbl)
                    action_map.append(f"alarm_{orig_idx}")
                    alarm_index_by_opt[opt_idx] = orig_idx

        options.append(구분선("알람 설정 관리 작업 (Space: 내역 선택, Enter: 실행)", icon="⚙️"))
        action_map.append(None)

        options.append(" ➕ 신규 고정 알람 추가")
        action_map.append("add")

        options.append(" 🔄 선택 알람 켜기/끄기 (토글 ON/OFF)")
        action_map.append("toggle")

        options.append(" ✏️ 선택 알람 정보 수정")
        action_map.append("edit")

        options.append(" 🗑️ 선택 알람 항목 삭제")
        action_map.append("delete")

        sort_status_label = "🟢 ON" if sort_by_time else "⚫ OFF"
        options.append(f" ⏱️ 시간 순서별 정렬 설정 (현재: {sort_status_label})")
        action_map.append("toggle_sort")

        options.append(구분선())
        action_map.append(None)

        options.append(" ❌ 이전 메뉴로 돌아가기")
        action_map.append("back")

        # 상단 앱 표준 대시보드 바 팁(tips)으로 안내문 표시
        next_dt, next_info = _get_next_recurring_app_alarm_datetime(settings)
        if next_info:
            tip_msg = f"💡 다음 예정 고정 알람: {next_info} | 앱 가동 시 해당 시각에 알람이 울려! 👍"
        else:
            tip_msg = "💡 우리 앱이 가동 중일 때 지정한 요일/일자 및 시각에 고정 알람(소리, 팝업, 텔레그램)이 울립니다! 👍"
        _print_mode_dashboard("요일별/매월 고정 알람 설정", tips=[tip_msg], icon="⏰", clear=True)

        res, action, selected_indices, *_ = _interactive_menu(
            "⏰ 요일별/매월 고정 알람 설정 (Space: 다중선택, Del: 즉시삭제, E: 즉시수정, Enter: 실행)",
            options,
            timeout=0,
            allow_multi=True
        )

        if res is None or (isinstance(res, int) and res < 0):
            break

        checked_alarm_indices = []
        if selected_indices:
            for s_idx in selected_indices:
                if s_idx in alarm_index_by_opt:
                    checked_alarm_indices.append(alarm_index_by_opt[s_idx])
        checked_alarm_indices = sorted(list(set(checked_alarm_indices)))

        if isinstance(res, list):
            sel_idx = res[-1] if res else -1
        else:
            sel_idx = res

        # [Del 키 즉시 삭제 핫키 지원 🗑️✨]
        if action == "DELETE":
            if checked_alarm_indices:
                del_labels = []
                for del_i in sorted(checked_alarm_indices, reverse=True):
                    if 0 <= del_i < len(alarms):
                        del_item = alarms.pop(del_i)
                        del_labels.append(del_item.get("label", "알람"))
                settings.data['recurring_app_alarms'] = alarms
                settings.save()
                del_str = ", ".join(del_labels)
                print(f"\r\n 🗑️ {ctext(f'선택한 알람 항목 [{del_str}] 이(가) Del 키로 삭제되었어! 👍', C.GREEN)}")
                time.sleep(1.2)
                continue
            elif sel_idx in alarm_index_by_opt:
                t_idx = alarm_index_by_opt[sel_idx]
                if 0 <= t_idx < len(alarms):
                    deleted = alarms.pop(t_idx)
                    settings.data['recurring_app_alarms'] = alarms
                    settings.save()
                    lbl = deleted.get('label', '알람')
                    print(f"\r\n 🗑️ {ctext(f'알람 항목 [{lbl}] 이(가) Del 키로 즉시 삭제되었어! 👍', C.GREEN)}")
                    time.sleep(1.2)
                    continue
            else:
                print(f"\r\n ⚠️ {ctext('삭제할 알람 항목 위에 커서를 두고 Del 키를 눌러줘!', C.YELLOW)}")
                time.sleep(1.2)
                continue

        # [E 키 즉시 수정 핫키 지원 ✏️✨]
        if action == "EDIT":
            if sel_idx in alarm_index_by_opt:
                # 커서 위치의 알람 항목을 바로 수정 모드로 점프!
                _e_target_idx = alarm_index_by_opt[sel_idx]
                # action_map 에서 "edit" 항목의 인덱스를 찾아 sel_idx를 교체
                _edit_opt_idx = action_map.index("edit") if "edit" in action_map else -1
                if _edit_opt_idx >= 0:
                    sel_idx = _edit_opt_idx
                    # checked_alarm_indices 에 없어도 t_idx로 바로 편집하도록 세팅
                    checked_alarm_indices = [_e_target_idx]
                    action = None
                else:
                    print(f"\r\n ⚠️ {ctext('edit 액션을 찾을 수 없어!', C.YELLOW)}")
                    time.sleep(1.2)
                    continue
            else:
                print(f"\r\n ⚠️ {ctext('수정할 알람 항목 위에 커서를 두고 E 키를 눌러줘!', C.YELLOW)}")
                time.sleep(1.2)
                continue

        if sel_idx < 0 or sel_idx >= len(action_map):
            break

        act = action_map[sel_idx]
        if act is None or act == "back":
            break

        if act.startswith("alarm_"):
            t_idx = int(act.split("_")[1])
            alarms[t_idx]["enabled"] = not alarms[t_idx].get("enabled", True)
            settings.data['recurring_app_alarms'] = alarms
            settings.save()
            st = "🟢 [ON] 켜짐" if alarms[t_idx]["enabled"] else "🔴 [OFF] 꺼짐"
            print(f"\r\n ✅ {ctext(f'알람 항목 {t_idx+1}번 상태가 [{st}] (으)로 변경되었어! 👍', C.GREEN)}")
            time.sleep(1.2)
            continue

        if act == "toggle_sort":
            new_sort = not sort_by_time
            settings.data['sort_app_alarms_by_time'] = new_sort
            settings.save()
            st_text = "🟢 [ON] 시간 순서별 정렬" if new_sort else "⚪ [OFF] 등록한 순서대로 (정렬 해제)"
            print(f"\r\n ⏱️ {ctext(f'고정 알람 목록 정렬 모드가 [{st_text}] (으)로 변경되었어! 👍', C.GREEN)}")
            time.sleep(1.2)
            continue

        if act == "add":
            print(f"\r\n ➕ {C.GREEN}{C.BOLD}신규 고정 알람 추가{C.RESET}")
            t_inp = prompt_input(" ⏰ 알람 시각을 입력해줘 (예: 09:00 또는 0900): ").strip()
            formatted_time = _parse_time_input(t_inp)
            if not formatted_time:
                print(f"\r\n ⚠️ {ctext('올바른 시각 형식(예: 09:00 또는 0900)을 입력해줘!', C.YELLOW)}")
                time.sleep(1.5)
                continue

            print("\r\n 🔁 반복 주기를 선택해줘:")
            print("   1. 요일별 반복 (매일, 평일, 주말, 특정 요일)")
            print("   2. 매월 특정 일자 반복 (예: 매월 15일, 13/17일, 말일, 말일-1일 등)")
            rep_choice = prompt_input(" 👉 주기 유형 선택 (1: 요일별, 2: 매월 특정일 / 기본값: 1): ").strip()

            selected_days = []
            selected_month_days = []
            if rep_choice == "2":
                repeat_type = "monthly"
                print("\r\n 📅 매월 반복할 일자를 선택하거나 직접 입력해줘:")
                print("   1. 매월 특정 일자 직접 입력 (예: 15 또는 13, 17 또는 1, 15, 25)")
                print("   2. 매월 말일 (매월 마지막 날 - 28/29/30/31일 자동)")
                print("   3. 매월 말일 1일 전 (말일-1일)")
                print("   4. 매월 말일 2일 전 (말일-2일)")
                print("   5. 매월 말일 3일 전 (말일-3일)")
                print("   6. 직접 입력 (예: 13, 17 또는 말일 또는 말일-1 / L-1, -1 등)")

                m_choice = prompt_input(" 👉 일자 옵션 선택 (1~6 또는 직접입력): ").strip()
                if m_choice == "1":
                    custom_m = prompt_input(" 👉 매월 반복 일자 입력 (예: 15 또는 13, 17): ").strip()
                    selected_month_days = _parse_user_month_days_input(custom_m)
                elif m_choice == "2":
                    selected_month_days = [0]
                elif m_choice == "3":
                    selected_month_days = [-1]
                elif m_choice == "4":
                    selected_month_days = [-2]
                elif m_choice == "5":
                    selected_month_days = [-3]
                elif m_choice == "6":
                    custom_m = prompt_input(" 👉 일자 입력 (예: 13, 17 또는 말일 또는 말일-1): ").strip()
                    selected_month_days = _parse_user_month_days_input(custom_m)
                else:
                    selected_month_days = _parse_user_month_days_input(m_choice)

                if not selected_month_days:
                    selected_month_days = [15]
            else:
                repeat_type = "weekly"
                print("\r\n 📅 반복 요일을 선택해줘:")
                print("   1. 매일 (월~일)")
                print("   2. 평일 (월~금)")
                print("   3. 주말 (토~일)")
                print("   4. 월, 수, 금 (또는 1,3,5 입력)")
                print("   5. 화, 목, 토 (또는 2,4,6 입력)")
                print("   6. 월, 수 (또는 1,3 입력)")
                print("   7. 화, 목 (또는 2,4 입력)")
                print("   8. 직접 요일 선택 (예: 1,3,5 -> 월,수,금 / 1:월 ~ 7:일)")

                d_choice = prompt_input(" 👉 요일 옵션 선택 (1~8 또는 1,3,5 직접입력): ").strip()
                if d_choice == "1": selected_days = [0, 1, 2, 3, 4, 5, 6]
                elif d_choice == "2": selected_days = [0, 1, 2, 3, 4]
                elif d_choice == "3": selected_days = [5, 6]
                elif d_choice == "4": selected_days = [0, 2, 4]
                elif d_choice == "5": selected_days = [1, 3, 5]
                elif d_choice == "6": selected_days = [0, 2]
                elif d_choice == "7": selected_days = [1, 3]
                elif d_choice == "8":
                    custom_d = prompt_input(" 👉 요일 입력 (1:월,2:화,3:수,4:목,5:금,6:토,7:일 / 예: 1,3,5 -> 월,수,금): ").strip()
                    selected_days = _parse_user_days_input(custom_d)
                else:
                    selected_days = _parse_user_days_input(d_choice)

            label_inp = prompt_input(" 🏷️ 알람 항목 이름/라벨 입력 (예: 카드결제대금 체크, 엔터 시 기본값): ").strip()
            if not label_inp:
                label_inp = "고정 알람"

            new_alarm = {
                "id": f"alarm_{int(time.time())}",
                "enabled": True,
                "time": formatted_time,
                "repeat_type": repeat_type,
                "days": selected_days,
                "month_days": selected_month_days,
                "label": label_inp
            }
            alarms.append(new_alarm)
            settings.data['recurring_app_alarms'] = alarms
            settings.save()
            print(f"\r\n ✅ {ctext(f'신규 고정 알람이 성공적으로 추가되었어! ({formatted_time}) 👍', C.GREEN)}")
            time.sleep(1.5)

        elif act == "toggle":
            if not alarms:
                print(f"\r\n ⚠️ {ctext('등록된 고정 알람이 없어!', C.YELLOW)}")
