# region [06. 모듈 및 라이브러리 자동 설치] 📦
import tkinter as tk

import warnings
warnings.filterwarnings("ignore", category=FutureWarning)

# [TAG: #@ensure_libraries]
def ensure_libraries(required_libs: dict):
    """
    라이브러리가 있는지 확인하고, 없으면 자동으로 설치합니다.
    required_libs: {'수입용_이름': '설치용_이름'} 형식의 딕셔너리
    """

    for import_name, install_name in required_libs.items():
        try:
            importlib.import_module(import_name)
        except ImportError:
            print(f"\r\n🔍 '{install_name}' 라이브러리가 없네? {_get_display_name(USER_NAME)}를 위해 바로 설치할게! 잠시만... 🛠️")
            try:
                subprocess.check_call([sys.executable, "-m", "pip", "install", install_name])
                print(f"✅ {install_name} 설치 완료!")
            except Exception as e:
                print(f"❌ {install_name} 설치 중 에러 발생: {e}")
                print(f"👉 직접 'pip install {install_name}'을 시도해봐!")

# 프로그램 시작 시 필수 라이브러리 체크 (Lazy Loading을 위해 제거됨. load_heavy_modules에서 수행)

# [TAG: #@_auto_install]
def _auto_install(package_name, import_name=None, desc="", is_optional=False, extra_args=None, force_upgrade=False):
    """패키지가 없으면 자동으로 pip install 합니다. force_upgrade=True 시 최신 버전으로 업데이트합니다."""
    import importlib
    import importlib.util
    import_name = import_name or package_name

    # [V80.7] 강제 업데이트(force_upgrade) 모드일 때는 체크 건너뛰고 설치 진행! 🚀
    if not force_upgrade and importlib.util.find_spec(import_name):
        return True

    action_str = "업데이트" if force_upgrade else "설치"
    _log_to_file(f"📦 [Auto Install] '{package_name}' ({desc}) {action_str} 시작...")
    msg = f"\r\n📦 '{package_name}' 패키지를 {action_str}합니다{' (' + desc + ')' if desc else ''}..."
    print(msg)
    try:
        cmd = [sys.executable, "-m", "pip", "install", "--prefer-binary"]
        if force_upgrade:
            cmd.append("--upgrade")
        if extra_args:
            cmd.extend(extra_args)
        cmd.append(package_name)

        result = subprocess.run(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            # [V141.38] CREATE_NO_WINDOW: pip 실행 시 까만 콘솔 창 안 뜨게 🙋
            creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0x08000000)
        )
        if result.returncode != 0:
            raise subprocess.CalledProcessError(result.returncode, cmd, result.stderr)
        _log_to_file(f"✅ [Auto Install] '{package_name}' {action_str} 성공.")
        print(f"✅ '{package_name}' {action_str}가 완료되었습니다.\r\n")
    except Exception as e:
        _log_to_file(f"❌ [Auto Install] '{package_name}' {action_str} 실패: {e}")
        print(f"❌ '{package_name}' 자동 {action_str} 실패. 터미널에서 'pip install -U {package_name}'을 직접 실행하세요.\r\n에러: {e}")
        if is_optional:
            return False
        time.sleep(5)
        sys.exit(1)
    return True

# [TAG: #@_generate_server_key]
def _generate_server_key(settings=None):
    """서버 비밀번호 생성: settings에 커스텀 비번이 있으면 그걸 쓰고, 없으면 6자리 랜덤 숫자."""
    import secrets
    import string
    if settings:
        use_custom = settings.data.get('use_custom_password', False)
        custom_pw = settings.data.get('server_password', '').strip()
        if use_custom and custom_pw:
            return custom_pw
    return ''.join(secrets.choice(string.digits) for _ in range(6))


# ══════════════════════════════════════════════════════════════════════
# [V193.0] 🔐 URL 접근 토큰 — 평문 비밀번호를 URL 에 노출하지 않는 방법
# ══════════════════════════════════════════════════════════════════════
# [배경 / 문제점] 🚨
#   예전엔 `?k=601796` 처럼 '평문 비밀번호' 를 URL 에 그대로 실었다.
#   → 주소창·브라우저 기록·스크린샷·텔레그램·복사한 메모에 평문이 그대로 남고,
#     '서버비번=6자리' 라 키공간이 10^6 뿐이라 '무차별 대입' 100만 번이면 끝난다.
#   (비밀번호가 평문이라는 문제보다 '키가 6자리' 쪽이 훨씬 위험했다)
#
# [왜 '암호화'가 아니라 '서명(HMAC)' 인가]  ← 이 부분이 핵심 🧠
#   서버는 URL 에서 비밀번호를 '복구' 할 필요가 없다. '맞는지만' 보면 된다.
#   '검증만' 필요하면 '서명'이 정답이다:
#     · 암호화(Fernet) : 키를 URL 에서 그대로 복구 가능 → 토큰을 보면 비밀번호가 새어나옴
#     · 서명(HMAC)     : 토큰에서 비밀번호를 역산 불가 → '링크를 누가 봐도 키는 못 얻는다'
#   그래서 '비번을 암호화해서 넣자' 는 요청을 '더 안전한 서명' 으로 바꾸어 구현했다. ✨
#
# [토큰 형식]
#   ?t=<b64url(payload)>.<b64url(HMAC-SHA256 서명)>
#     payload = "v1|<scope>|<만료epoch>|<발급epoch>"
#   · scope : 'full' (기존 ?k= 와 동일 권한) / 'ro' (읽기 전용, 쓰기 API 차단)
#   · ttl   : 초. 0 = 만료없음(북마크 유지) / 3600 = 1시간짜리 임시 링크
#
# [하위 호환] 🛡️
#   예전 `?k=평문` 방식도 계속 동작한다 (저장된 북마크가 깨지지 않게).
#   대신 '틀린 인증' 에만 실패 카운터를 쌓아 잠근다 (아래 _auth_fail_guard).

# [TAG: #@_url_token_secret]
def _url_token_secret(settings=None):
    """URL 토큰 서명용 '고엔트로피' 시크릿 확보 🔑 없으면 1회 자동 생성해 암호화 저장.
    ⚠️ 의도적으로 '6자리 server_password' 를 서명키로 쓰지 않는다.
       키공간 10^6 인 키로 서명하면 토큰도 100만 번이면 '오프라인으로' 복제된다.
       'URL 에 키가 없다' 는 사실만 믿히지 말고 실제 강도를 갖게 하려는 장치다."""
    if settings is None:
        return ''
    try:
        import secrets as _sec
        sec = str(settings.data.get('url_token_secret', '') or '').strip()
        if not sec:
            # ⚠️ '아직 로드되지 않은 빈 매니저' 면 새 시크릿을 만들지 않는다.
            #    save() 가 _settings_loaded 가 False 라서 저장을 건너뛰는데,
            #    여기서 시크릿만 새로 뽑으면 '다음 호출엔 또 다른 키' 가 되어
            #    발급된 토큰이 '조용히 전부 검증 실패'한다. (기동 초반 예외 경로)
            if not settings.data and getattr(settings, '_settings_loaded', None) is False:
                _log_to_file("⚠️ [URLToken] 설정이 아직 로드되지 않아 시크릿 생성 보류")
                return ''
            sec = _sec.token_urlsafe(32)   # 256bit
            # ⚠️ 'settings.data' 에는 '평문' 으로 넣는다. SettingsManager.save() 가
            #    저장 복사본에만 encrypt_setting() 을 적용해 파일을 암호화한다.
            #    (여기서 직접 encrypt_setting() 을 걸면 이중 암호회가 되고,
            #     메모리에 암호문이 남아 '다음 호출의 서명키' 가 뒤틀린다 → 전부 검증 실패)
            settings.data['url_token_secret'] = sec
            try:
                settings.save()
                _log_to_file("🔐 [URLToken] 서명 시크릿 자동 생성했어! (256bit)")
            except Exception as e:
                _log_to_file(f"⚠️ [URLToken] 시크릿 저장 실패: {e}")
        return sec
    except Exception as e:
        _log_to_file(f"⚠️ [URLToken] 시크릿 확보 실패: {e}")
        return ''


# [TAG: #@_token_current_k]
def _token_current_k(settings=None, server_key=None) -> str:
    """토큰 서명에 쓸 '현재 비밀번호 k' 를 한 곳에서 결정한다 (발급/검증 반드시 동일 값이어야 함) 🔑
    · 우선순위: 명시 인자 → 전역 _flask_server_key → 설정의 수동 비밀번호
    · ⚠️ 발급 시점과 검증 시점이 다른 값을 쓰면 '조용히 전부 검증 실패' 한다.
       그래서 '어디서 부르든 같은 값'을 반환하도록 이 함수 하나로 통일한다."""
    if server_key is not None:
        k = server_key
    else:
        k = globals().get('_flask_server_key') or ''
        if not k and settings is not None:
            try:
                if settings.data.get('use_custom_password', False):
                    k = settings.data.get('server_password', '')
            except Exception:
                k = ''
    return str(k or '').strip()


# [TAG: #@_token_signing_key]
def _token_signing_key(settings=None, server_key=None) -> str:
    """URL 토큰 '서명키' = HMAC-SHA256( key=url_token_secret , msg='k=' + 현재비밀번호 ) 🔐

    [왜 이렇게 만드나] 🧠 (V236.2 설계)
      ❌ 'k(6자리) 를 서명키로 쓰면' → 키공간 10^6 이라 토큰 하나만 들고 있어도
         오프라인 전수 탐색으로 'full 권한 위조 토큰'을 만들어낼 수 있다. (위 주석이 경고한 그대로)
      ✅ 'k 를 서명 *재료*로 섞는다' → 위조하려면 256bit url_token_secret 이 추가로 필요하다.
         그런데 동시에 'k 가 바뀌면 서명키도 자동으로 바뀌어 기존 t= 토큰이 전부 무효화'된다. ✨
    → '비밀번호 변경 = 전체 링크 폐기' 를 'k 를 키로 써서'(취약) 아닌 '안전한' 방법으로 달성한다.
    [부수 효과] 🔁 랜덤 모드(수동 비번 미지정)에서는 서버 재시작마다 k 가 새로 뽑히므로
       외부 링크도 그때마다 함께 만료된다. (비누 지시: 'k 가 바뀌면 t 도 무효화가 맞다')"""
    base = _url_token_secret(settings)
    if not base:
        return ''
    k = _token_current_k(settings, server_key)
    try:
        import hmac as _hmac, hashlib as _hashlib
        return _hmac.new(base.encode('utf-8'), ('k=' + k).encode('utf-8'), _hashlib.sha256).hexdigest()
    except Exception as e:
        _log_to_file(f"⚠️ [URLToken] 서명키 파생 실패: {e}")
        return ''


_token_settings_cache = None   # 전역 settings 가 없을 때 '한 번만' 읽어 재사용하는 설정 객체

# [TAG: #@_settings_for_token]
def _settings_for_token():
    """토큰 발급/검증에 쓸 설정 객체 (전역 settings → settings_ref 순으로 확보)
    ⚠️ 전역 설정이 아직 없을 때 '매번 새로' SettingsManager 를 만들면 안 된다.
       __init__ 가 .data 를 자동 로드하지 않으므로 매번 '빈 상태'로 시작해
       시크릿을 새로 만들어 버린다 → 발급/검증용 키가 달라져 '조용히 전부 실패'한다.
       그래서 '한 번만' 읽어와 재사용한다. 🛡️"""
    st = globals().get('settings') or globals().get('settings_ref')
    if st is not None:
        return st
    global _token_settings_cache
    if _token_settings_cache is None:
        try:
            m = SettingsManager(SETTINGS_FILE)
            try:
                m.load()          # ← 평문(복호화됨)으로 채워야 서명키가 일치한다
            except Exception as e:
                _log_to_file(f"⚠️ [URLToken] 설정 로드 실패: {e}")
            _token_settings_cache = m
        except Exception as e:
            _log_to_file(f"⚠️ [URLToken] 설정 매니저 생성 실패: {e}")
            return None
    return _token_settings_cache


# [TAG: #@make_url_token]
# 🐱[V193.5] URL 토큰 대폭 단축 (기존 v1 토큰은 100% 계속 유효 — 하위호환)
#   예전(v1): 페이로드 'v1|full|0|1790728678' ASCII(20B) → 27자 + 서명 43자 = 71자
#   새  (v2): 고정폭 바이너리(ver1B + scope1B + exp4B = 6B) → 8자 + 서명 22자
#            + 사람이 읽는 만료시각 표시 필드(서명 대상 아님)
#            → 만료없음 33자 / TTL 있음 42자   (?t= 포함 URL 74자 → 36자)
#   · 'now(발급시각)' 필드는 verify 가 '한 번도 읽지 않아서' 14자를 낭비하고 있었다 → 제거
#   · 구분자 '|' 텍스트 → 고정폭 바이너리 포맷으로 교체
#   · 서명은 SHA256(32B) 대신 128bit 절단값 사용 (위조 2^128, LAN 베어러 토큰으로 충분)
_URL_TOKEN_MAC_LEN = 16   # 서명 16바이트(128bit) 절단
_URL_TOKEN_VER = 2


def make_url_token(settings=None, scope='full', ttl=0):
    """URL 에 넣을 접근 토큰 발급 🔐 (평문 비밀번호 대신 이 토큰을 쓴다)
    · scope: 'full' = 기존 ?k= 와 동일 권한 / 'ro' = 읽기 전용(쓰기 API 403)
    · ttl  : 초. 0 이면 만료 없음(북마크 유지). 3600 이면 '1시간 뒤 자동 폐기' 링크.
    · v2(2026-09-30) : 고정폭 바이너리 + 128bit 절단 서명 → 71자에서 33자(만료없음)로 단축"""
    try:
        import hmac as _hmac, hashlib as _hashlib, base64 as _b64, time as _t, struct as _st
        st = settings if settings is not None else _settings_for_token()
        # 🛡️ [V236.2] 서명키 = url_token_secret 와 '현재 k' 를 섞어 파생 (k 변경 → 자동 무효화)
        secret = _token_signing_key(st)
        if not secret:
            return ''

        def _b64u(b):
            return _b64.urlsafe_b64encode(b).decode().rstrip('=')

        scope = 'ro' if str(scope).lower() == 'ro' else 'full'
        try:
            ttl = max(0, int(ttl))
        except Exception:
            ttl = 0
        now = int(_t.time())
        # ⚠️ ttl 이 0 (만료없음) 이면 exp 를 '0' 으로 둔다. now+0 을 넣으면
        #    발급 즉시 만료되는_token이 되어 버린다 (토큰이 통째로 죽는 사고).
        exp = (now + ttl) if ttl else 0
        # 만료는 2106년까지므로 uint32 에 안전하게 들어간다
        if exp > 0xFFFFFFFF:
            exp = 0xFFFFFFFF
        scope_b = 0x00 if scope == 'ro' else 0x01
        payload = _st.pack('>BBI', _URL_TOKEN_VER, scope_b, exp)
        netloc = str(exp)   # 사람이 읽는 만료시각(정수 문자열 — 0 이어도 '0' 이 된다)
        digest = _hmac.new(secret.encode('utf-8'), payload, _hashlib.sha256).digest()[:_URL_TOKEN_MAC_LEN]
        return '%s.%s.%s' % (_b64u(payload), netloc, _b64u(digest))
    except Exception as e:
        _log_to_file(f"⚠️ [URLToken] 토큰 발급 실패: {e}")
        return ''


# [TAG: #@_url_auth_query]
def _url_auth_query(scope='full', ttl=0):
    """URL 에 붙일 인증 쿼리스트링을 만들어준다 → '?t=<서명토큰>' 🔐
    · 이걸 쓰면 '?k=<평문비밀번호>' 가 주소창·기록·텔레그램에 남지 않는다.
    · scope : 'full' = 전체 권한 / 'ro' = 읽기 전용(쓰기 API 403)
    · ttl   : 초. 0 = 만료없음. 3600 = '1시간 뒤 자동 폐기' 임시 링크.
    · 토큰 발급 실패 시 '빈 문자열' 을 돌려줘서 기존 ?k= 경로로 자연 폴백한다. 🛡️"""
    try:
        tok = make_url_token(_settings_for_token(), scope=scope, ttl=ttl)
        return f"?t={tok}" if tok else ""
    except Exception as e:
        _log_to_file(f"⚠️ [URLToken] 인증 쿼리스트링 생성 실패: {e}")
        return ""


# [TAG: #@verify_url_token]
def verify_url_token(settings, token, need_scope='ro', server_key=None):
    """URL 토큰 검증 → (ok, reason, scope) 🛡️
    · 서명 불일치 / 만료 / 스코프 부족 → 전부 False (구체적 사유는 로그에만)
    · 비교는 hmac.compare_digest (상수시간) — timing_side_channel 차단
    · server_key : 검증을 수행하는 '서버가 실제로 쓰고 있는 k' 를 넘겨야 한다.
      (발급 시점의 k 와 다르면 서명키가 달라져 '서명 불일치' 로 조용히 거절된다)"""
    try:
        import hmac as _hmac, hashlib as _hashlib, base64 as _b64, time as _t
        token = str(token or '').strip()
        if not token or '.' not in token:
            return False, '토큰 형식 오류', ''
        st = settings if settings is not None else _settings_for_token()
        # 🛡️ [V236.2] 발급과 '똑같은' 서명키로 검증해야 한다 (k 가 다르면 서명 불일치로 거부됨)
        secret = _token_signing_key(st, server_key=_token_current_k(st, server_key))
        if not secret:
            return False, '서명 시크릿 없음', ''
        def _unb64(s):
            s = s + '=' * (-len(s) % 4)
            return _b64.urlsafe_b64decode(s.encode('ascii'))

        def _sign(pb):
            return _hmac.new(secret.encode('utf-8'), pb, _hashlib.sha256).digest()

        scope, exp, given, expect = '', 0, b'', b''
        segments = token.split('.')

        # ── v2 (2026-09-30, 짧은 토큰): <payload6B>.<exp정수>.<mac16B> ──
        if len(segments) == 3:
            try:
                payload = _unb64(segments[0])
                if len(payload) == 6 and payload[0] == _URL_TOKEN_VER:
                    scope = 'ro' if payload[1] == 0x00 else 'full'
                    exp = int.from_bytes(payload[2:6], 'big')
                    # 사람이 읽는 만료시각은 '서명 대상 아님' → 무시하고 바이너리를 신뢰한다
                    given = _unb64(segments[2])
                    expect = _sign(payload)[:_URL_TOKEN_MAC_LEN]
            except Exception:
                scope = ''
        # ── v1 (구버전, 71자): <payload>.<mac32B> ── 기존 링크/북마크 호환용
        elif len(segments) == 2:
            try:
                text = _unb64(segments[0]).decode('utf-8')
                parts = text.split('|')
                if len(parts) == 4 and parts[0] == 'v1':
                    scope = parts[1]
                    exp = int(parts[2])
                    given = _unb64(segments[1])
                    expect = _sign(text.encode('utf-8'))
            except Exception:
                scope = ''
        else:
            return False, '토큰 형식 오류', ''

        if not scope:
            return False, '토큰 버전 오류', ''
        if exp and _t.time() > exp:
            return False, '만료된 링크', scope
        if not given or not _hmac.compare_digest(expect, given):
            return False, '서명 불일치', ''
        if need_scope == 'full' and scope != 'full':
            return False, '읽기 전용 토큰입니다', scope
        return True, '', scope
    except Exception:
        return False, '검증 실패', ''


# ══════════════════════════════════════════════════════════════════════
# [V193.0] 🔒 서버 인증 '무차별 대입' 차단기
# ══════════════════════════════════════════════════════════════════════
# 예전엔 check_security 에 실패 카운터가 아예 없었다. 6자리(10^6) + 무제한 시도 = 전량 장악.
# 아래는 '틀린 인증을 제시한' 경우에만 실패를 쌓는다. 🛡️
#  · '아무것도 안 제시한' 401 (만료된 쿠키, 일반 브라우징)은 정상 동작이므로 세지 않는다.
#    그것까지 세면 '동영상 재생까지 5분 잠겨버리는' 사고가 난다. 🎬❌
_server_auth_fail = {}   # ip -> {'n': 실패횟수, 'until': 잠금만료 epoch}
SERVER_AUTH_MAX_FAILS = 30        # 30회 틀리면 잠금
SERVER_AUTH_LOCK_SECONDS = 300    # 5분간 차단


# [TAG: #@_auth_fail_guard]
def _auth_fail_guard(ip, presented=False):
    """'틀린 인증' 에만 실패를 쌓아 잠근다. 🔒 → 현재 잠금중이면 True"""
    if not ip:
        return False
    try:
        import time as _t
        now = _t.time()
        rec = _server_auth_fail.get(ip) or {'n': 0, 'until': 0.0}
        if rec['until'] > now:
            return True
        if rec['until']:          # 이전 잠금이 풀렸으면 카운터 초기화
            rec = {'n': 0, 'until': 0.0}
        if not presented:         # 자격증명을 안 제시한 401 은 정상 → 세지 않는다
            return False
        rec['n'] += 1
        if rec['n'] >= SERVER_AUTH_MAX_FAILS:
            rec['until'] = now + SERVER_AUTH_LOCK_SECONDS
            _log_to_file(f"🔒 [Security] 인증 실패 {rec['n']}회 → {SERVER_AUTH_LOCK_SECONDS}초 잠금 (IP: {ip})")
        _server_auth_fail[ip] = rec
        return rec['until'] > now
    except Exception:
        return False


# [TAG: #@_auth_fail_reset]
def _auth_fail_reset(ip):
    """인증 성공 시 해당 IP 의 실패 카운터를 싹 지운다 ✅"""
    if not ip:
        return
    try:
        _server_auth_fail.pop(ip, None)
    except Exception:
        pass


