# ------------------------------------------------------------------------------
# [V78.x] Stealth AI Engine (Gemini CLI Persistent Session) 🤖🛰️
# ------------------------------------------------------------------------------
import threading

class StealthChatEngine:
    """Gemini CLI(Node.js)를 백그라운드에 상주시켜 초고속 대화를 가능하게 하는 엔진 🚀"""
    # [TAG: #@__init___8]
    def __init__(self, model=None):
        # [V78.x] 모델 매핑
        model_map = {"gpt": "gemini-2.5-flash-lite", "claude": "gemini-3.5-flash", "gemini": "gemini-2.5-flash-lite"}
        self.model = model_map.get(model.lower() if model else "", "gemini-2.5-flash-lite")

        self.history = []
        self._process = None
        self._output_queue = queue.Queue()
        self._stop_event = threading.Event()
        self._is_ready = threading.Event()
        self._lock = threading.Lock()


        # [관리] Node.js 및 index.js 절대 경로 (직결 방식)
        self._node_path = "node"
        self._index_js = os.path.join(os.environ.get('APPDATA', ''), 'npm', 'node_modules', '@google', 'gemini-cli', 'dist', 'index.js')

        # 엔진 백그라운드 기동
        self._start_session()

    # [TAG: #@_start_session]
    def _start_session(self):
        """백그라운드에서 Node.js를 통해 Gemini CLI를 상주 세션으로 엔진 직결 실행합니다."""
        if self._process and self._process.poll() is None: return

        _log_to_file("⏳ [Stealth] 백그라운드 지속 세션 초기화 중 (Direct Node)...")
        try:
            # shell=True를 통해 CMD 환경 래퍼 없이 노드 프로세스를 직접 관리
            args = [self._node_path, self._index_js, "-y", "-o", "text"]
            if self.model: args += ["-m", self.model]

            # [V78.x] 핵심: stderr까지 stdout으로 합쳐서 모든 메시지 캡처
            self._process = subprocess.Popen(
                args,
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                encoding='utf-8',
                bufsize=0,
                shell=True, # 윈도우 환경 대응
                creationflags=subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
            )

            # 실시간 출력 모니터링 스레드 시작
            self._reader_thread = threading.Thread(target=self._read_output, daemon=True)
            self._reader_thread.start()

            # 준비 상태 안내 (콘솔에서 15초 넉넉하게 기다림)
            self._is_ready.wait(timeout=15.0)
        except Exception as e:
            _log_to_file(f"❌ [Stealth] 엔진 기동 실패: {e}")
            self._process = None

    # [TAG: #@_read_output]
    def _read_output(self):
        """출력 파이프에서 한 글자씩 읽어 큐에 쌓고 프롬프트를 감지합니다."""
        ansi_escape = re.compile(r'\x1B(?:[@-Z\\-_]|\[[0-?]*[ -/]*[@-~])')
        buffer = ""
        while self._process and not self._stop_event.is_set():
            try:
                char = self._process.stdout.read(1)
                if not char: break

                clean_char = ansi_escape.sub('', char)
                self._output_queue.put(clean_char)

                # 프롬프트 감지 로직 (준비 완료 또는 답변 끝)
                # [수정] 대소문자 및 부분 일치로 더 유연하게 탐색 🎯
                buffer += clean_char
                if len(buffer) > 200: buffer = buffer[-200:]

                if "> Type" in buffer or "message" in buffer.lower():
                    self._is_ready.set()
            except: break
        self._is_ready.clear()

    # [TAG: #@ask]
    def ask(self, prompt, stream=True):
        """stdin을 통해 질문을 던지고 stdout 프롬프트가 뜰 때까지 응답을 수집합니다."""
        with self._lock:
            if not self._process or self._process.poll() is not None:
                self._start_session()

            # 초동 기동 최대 15초 대기
            if not self._is_ready.wait(timeout=15.0):
                yield "⚠️ 엔진 응답 대기 시간 초과. (노드 엔진이 응답하지 않아)"
                return

            # 이전 큐 찌꺼기 청소
            while not self._output_queue.empty():
                try: self._output_queue.get_nowait()
                except: break

            # 질문 전송 (+ 엔터 두 번)
            try:
                self._process.stdin.write(prompt + "\r\n\r\n")
                self._process.stdin.flush()
            except Exception as e:
                yield f"❌ 명령 전송 실패: {e}"
                return

            full_response = ""
            current_line = ""
            end_detected = False

            # [수정] 프롬프트 마커를 만날 때까지 대기 및 출력 (최대 30초 응답 대기)
            while not end_detected and not self._stop_event.is_set():
                try:
                    char = self._output_queue.get(timeout=30.0)
                    full_response += char
                    current_line += char

                    if char == '\r\n':
                        if current_line.strip(): yield current_line
                        current_line = ""

                    # [V78.x] 유연한 답변 종료 감지
                    if "> Type" in full_response[-50:] or "message" in full_response[-50:].lower():
                        end_detected = True
                        break
                except queue.Empty: break

            # 후처리 및 히스토리 저장
            clean_ans = full_response
            if "> Type" in clean_ans: clean_ans = clean_ans.split("> Type")[0]
            if clean_ans.strip(): self.history.append({"role": "assistant", "content": clean_ans.strip()})

    # [TAG: #@close]
    def close(self):
        """엔진 프로세스를 종료합니다."""
        self._stop_event.set()
        if self._process:
            try:
                self._process.stdin.write("exit\r\n")
                self._process.stdin.flush()
                self._process.terminate()
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

