# [TAG: #@restart_program]
def restart_program(restart_with_server=None):
    """[V11.0] 프로그램을 재시작합니다. 중복 실행 방지(Mutex)를 우회하기 위해 --skip-check를 수반합니다.
    restart_with_server=True면 미디어 서버도 함께 재가동, None이면 현재 상태 유지."""
    global _flask_server_running, _telegram_polling_active, _is_restarting

    # [V51.0] 재시작 상태 플래그 활성화 (와치독 중복 신호 방지) 🔄
    _is_restarting = True

    # [재시작 시 정리] 종료 시 최근 파일/번역 완료 초기화 옵션이 켜져있다면 즉시 실행 🧹✨
    try:
        if 'settings' in globals() and globals()['settings']:
            _perform_normal_exit(globals()['settings'])
    except Exception as _re_e:
        _log_to_file(f"⚠️ [Restart Exit Clean Error] {_re_e}")

    # [V18.2.0] 워치독 바톤터치 유예 플래그 설정 (15초 자동 만료 안전장치) 🛡️
    try:
        bridge = _load_bridge()
        bridge['handoff_active'] = True
        bridge['restarting_until'] = time.time() + 15.0
        _save_bridge(bridge)
    except Exception as e:
        _log_to_file(f"⚠️ [Handover] 브릿지 활성화 중 오류: {e}")

    # 서버 재시작 여부 자동 감지
    if restart_with_server is None:
        restart_with_server = _flask_server_running

    # [디자인] 재시작 메시지 박스
    P, S, G, Y, R, B = C.PURPLE, C.SKY, C.GREEN, C.YELLOW, C.RESET, C.BOLD
    print(f"\r\n {Y}🔄 [ 프로그램 재시작 ] {R}{P}───────────────────────────────────────────{R}")
    print(f"  ✨ {S}수정된 코드를 즉시 반영하여 다시 시작합니다.{R}")
    if restart_with_server:
        print(f"  🌐 {G}미디어 서버도 함께 재가동합니다!{R}")
    print(f"  🚀 {G}{B}새 프로세스를 띄우고 현재 앱을 종료합니다...{R}")
    print(f" {P}─────────────────────────────────────────────────────────────────{R}")

    _log_to_file(f"Log: [Restart] 프로그램 재시작 시퀀스 개시 (Server 재실행 여부: {restart_with_server})")

    _telegram_polling_active = False

    # [V51.0] 재시작 전 자원 정리 (트레이 아이콘 잔상 방지) 🧹✨
    _tray_cleanup()

    # 서버 종료 시도 (재시작 흐름 차단 방지용 별도 스레드)
    # [TAG: #@_shutdown_prep]
    def _shutdown_prep():
        try:
            if _flask_server_running:
                print(f" 🛑 {C.DIM}기존 서버 종료 시도 중...{C.RESET}")
                if restart_with_server:
                    _stop_network_server(keep_state=True)
                else:
                    _stop_network_server()
                print(f" ✅ {C.DIM}기존 서버 정리 완료{C.RESET}")
        except Exception as e:
            _log_to_file(f"Error: [Restart] 서버 종료 중 오류: {e}")

    threading.Thread(target=_shutdown_prep, daemon=True).start()

    _flask_server_running = False
    time.sleep(1.0) # 메시지 확인 및 서버 정리 대기

    # 새 프로세스 실행 (os.execv 사용)
    try:
        # [V8.9/V13.3] --skip-check 인자를 붙여 뮤텍스 충돌 없이 재시작 🔄
        args = sys.argv[:]
        if '--skip-check' not in args:
            args.append('--skip-check')

        # [V13.3] 와치독 플래그 정리 (혹시 모르니)
        root_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in globals() else os.getcwd()
        flag_path = os.path.join(root_dir, ".restart_requested")
        if os.path.exists(flag_path):
            try: os.remove(flag_path)
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

        # [V13.3] 환경 변수를 통한 경고 억제 강제 적용
        os.environ['PYTHONWARNINGS'] = 'ignore'

        _log_to_file(f"Log: [Restart] os.execv 실행 (Args: {args})")

        # [V14.9.4] 재시작 직전 트레이 아이콘 등 자원 명시적 정리 😊
        if 'cleanup' in locals() or 'cleanup' in globals():
            try: cleanup()
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

        # [V13.3] python 실행 시 -W ignore 옵션을 추가하여 서브프로세스 경고 완벽 차단
        new_args = [sys.executable, '-W', 'ignore'] + args
        os.execv(sys.executable, new_args)
    except Exception as e:
        _log_to_file(f"❌ [Restart] 재시작 실패: {e}")
        print(f"❌ 재시작 실패: {e}")
        os._exit(1)

# [TAG: #@ensure_library]
def ensure_library(module_name, pip_name=None):
    """라이브러리가 설치되어 있는지 확인하고 없으면 안내합니다."""
    import importlib
    import importlib.util
    if importlib.util.find_spec(module_name) is not None:
        return True

    p_name = pip_name or module_name
    print(f"\r\n ⚠️ {C.YELLOW}필수 라이브러리 [{module_name}]가 설치되어 있지 않아.{C.RESET}")
    print(f"    {C.DIM}설치하려면 다음 명령어를 실행해줘:{C.RESET}")
    print(f"    {C.BOLD}pip install {p_name}{C.RESET}")
    time.sleep(2)
    return False

_update_available_cached = False # [신규] 메인 메뉴 표시용 캐시

# [TAG: #@check_and_update_program]
def check_and_update_program(silent=False, pre_fetched_content=None):
    """서버에서 최신 버전을 체크하고 업데이트를 수행합니다.
    silent=True일 경우 변경 사항이 있을 때만 알리고 평소엔 조용히 처리합니다.
    pre_fetched_content가 제공되면 다시 다운로드하지 않고 해당 내용을 사용합니다."""
    global _update_available_cached

    # 0. 필수 라이브러리 체크
    if not ensure_library("requests") or not ensure_library("difflib"):
        return False

    import requests
    import difflib

    url = "http://srt.byus.net/korea.srt.py"
    if not silent:
        print(f"\r\n 🔍 {C.CYAN}프로그램 업데이트를 확인하고 있어... (서버 연결 중){C.RESET}")

    try:
        # 1. 서버 파일 다운로드 (V8.2.0: 크기 비교 제거, 내용 해시로 정확히 비교)
        if not silent:
            print(f" 📥 {C.CYAN}서버에서 최신 파일을 가져오는 중...{C.RESET}")
        try:
            res_get = requests.get(url, timeout=15)
            if res_get.status_code != 200:
                if not silent: print(f" ❌ {C.RED}서버 연결 실패! (HTTP {res_get.status_code}){C.RESET}")
                return False
            remote_content_raw = res_get.content
        except Exception as req_e:
            if not silent: print(f" ❌ {C.RED}서버 연결 실패: {req_e}{C.RESET}")
            return False

        local_file = os.path.abspath(__file__)
        with open(local_file, "rb") as f:
            local_content_raw = f.read()

        # [핵심] CRLF/LF 차이를 무시하기 위해 줄바꿈 정규화 후 해시 비교
        # [TAG: #@_norm_hash]
        def _norm_hash(data: bytes) -> str:
            return hashlib.md5(data.replace(b'\r\n', b'\r\n')).hexdigest()

        remote_hash = _norm_hash(remote_content_raw)
        local_hash  = _norm_hash(local_content_raw)

        remote_size = len(remote_content_raw)
        local_size  = os.path.getsize(local_file)

        # 업데이트 가능 여부 판단 (해시가 다를 때만 True)
        is_update_available = (remote_hash != local_hash)
        _update_available_cached = is_update_available # 전역 캐시 업데이트

        # 체크 시간 기록 (settings.json 활용)
        if settings:
            settings.data["last_update_check"] = int(time.time())
            settings.save()

        if not is_update_available:
            if not silent:
                print(f" ✅ {C.GREEN}현재 최신 버전을 사용 중이야! (서버와 내용 동일){C.RESET}")
                time.sleep(1)
            return False

        # 2. 업데이트 진행 (silent 모드면 발견 사실만 알리고 함수 종료)
        if silent:
            return False

        print(f"\r\n 🌟 {C.BOLD}{C.SKY}새로운 버전이 발견되었어! ✨{C.RESET}")
        print(f"    - 현재 크기: {local_size:,} bytes")
        print(f"    - 서버 크기: {remote_size:,} bytes")
        # [V8.2.1] 서버 파일 수정 시간 표시
        last_modified_raw = res_get.headers.get('Last-Modified', '')
        if last_modified_raw:
            try:
                from email.utils import parsedate_to_datetime
                server_dt = parsedate_to_datetime(last_modified_raw)
                # KST 변환 (UTC+9)
                import datetime as _dt
                server_dt_kst = server_dt.astimezone(_dt.timezone(_dt.timedelta(hours=9)))
                print(f"    - 서버 업로드: {C.SKY}{server_dt_kst.strftime('%Y-%m-%d %H:%M:%S')} (KST){C.RESET}")
            except Exception:
                print(f"    - 서버 업로드: {last_modified_raw}")
        print(f"\r\n 👉 {C.YELLOW}업데이트를 진행하고 프로그램을 재시작할까? (Y/n){C.RESET}")


        if os.name == 'nt':
            import msvcrt
            while msvcrt.kbhit(): msvcrt.getch()

        ans = prompt_input(" >> ").strip().lower()
        if ans and ans != 'y': return False # 엔터(빈값)면 진행

        # 3. 다운로드 완료 (이미 다운로드됨 — 재다운로드 불필요)
        new_content = remote_content_raw


        print(f" 🛡️ {C.CYAN}다운로드된 파일 무결성(유사도) 검사 중...{C.RESET}")
        try:
            with open(local_file, "rb") as f:
                old_content = f.read()
            old_text = old_content.decode('utf-8', errors='ignore')
            new_text = new_content.decode('utf-8', errors='ignore')

            similarity = difflib.SequenceMatcher(None, old_text, new_text).quick_ratio()
            print(f"    - 코드 유사도: {similarity*100:.1f}%")

            if similarity < 0.5:
                print(f"\r\n 🛑 {C.RED}경고: 유사도가 너무 낮아(50% 미만) 업데이트를 중단해!{C.RESET}")
                time.sleep(3)
                return False
        except: return False

        # 4. 백업 및 적용
        print(f" 🛡️  {C.CYAN}현재 파일을 백업하고 교체 중...{R}")
        # [V8.1.5] 자동 업데이트 백업 (백업 폴더로 강제 이동)
        backup_path = backup_file(local_file, suffix="update")

        # 5. 파일 교체
        with open(local_file, "wb") as f:
            f.write(new_content)

        print(f"\r\n ✅ {C.GREEN}{C.BOLD}업데이트가 성공적으로 완료되었어!{C.RESET}")
        print(f"    - {C.SKY}백업 생성:{C.RESET} {os.path.basename(backup_path)}")
        print(f"    - 상위 메뉴에서 {C.YELLOW}'복구'{C.RESET}를 통해 언제든 되돌릴 수 있어.")
        print("    - 적용을 위해 프로그램을 재시작해야 해.")
        time.sleep(2)
        return True

    except Exception as e:
        if not silent: print(f" ❌ {C.RED}업데이트 중 오류 발생: {e}{C.RESET}")
        return False


# [TAG: #@update_settings_menu]
def update_settings_menu(settings):
    """프로그램 업데이트 관련 설정 및 즉시 확인 메뉴입니다. (V7.1)"""
    # [수정] 메뉴 진입 시엔 조용히 업데이트 여부만 체크 (V7.6)
    check_and_update_program(silent=True)
    cached_remote_content = None # [V7.9.5] AI 분석용으로 다운로드한 코드 캐시
    # [삭제됨] 전역 컬러 변수(R, G, Y 등) 사용으로 개별 선언 불필요 (V25.0) 👋

    while True:
        is_auto_enabled = settings.data.get('auto_update_enabled', True)
        last_check = settings.data.get('last_update_check', 0)
        datetime.fromtimestamp(last_check).strftime('%Y-%m-%d %H:%M') if last_check > 0 else "기록 없음"

        _auto_state = f"{G}ON (24시간 주기 자동 체크){R}" if is_auto_enabled else f"{C_DIM}⚫ OFF (수동 체크 필요){R}"
        _upd_status = f"{Y}{B}[!] 새로운 업데이트가 발견되었어!{R}" if _update_available_cached else f"{G}최신 버전을 사용 중이야.{R}"

        _print_standard_menu_header("update", settings,
                                    auto_state=_auto_state,
                                    upd_status=_upd_status)

        u_options_map = [
            {"label": f" 🔄 지금 즉시 업데이트 진행하기 (!){' '+Y+B+'[신규 버전 있음]'+R if _update_available_cached else ''}", "key": "check_now"},
            {"label": " 🤖 업데이트 변화점 AI한테 물어보기 (요약)", "key": "ai_summary"},
            {"label": " ⏪ 이전 버전(백업)으로 복구하기", "key": "restore"},
            {"label": " 💾 현재 사용버전 수동 백업하기 (backups 폴더)", "key": "manual_backup"},
            {"label": f" ⏱️ 자동 업데이트 체크 설정 (현재: {'🟢 ON' if is_auto_enabled else '⚫ OFF'})", "key": "toggle_auto"},
            {"label": " 📂 파이썬 실행 폴더 창 열기 (최대화)", "key": "open_folder"},
            {"label": " ❌ 메인 메뉴로 돌아가기", "key": "back"}
        ]
        u_options = [item["label"] for item in u_options_map]
        u_sel, _, *_ = _interactive_menu("프로그램 업데이트 관리", u_options, timeout=0)

        if u_sel < 0 or u_sel >= len(u_options_map): continue
        u_key = u_options_map[u_sel]["key"]

        if u_key == "check_now":
            # 캐시된 내용이 있으면 전달하여 중복 다운로드 방지 (V7.9.5)
            updated = check_and_update_program(silent=False, pre_fetched_content=cached_remote_content)
            if updated:
                return True # 재시작 신호
        elif u_key == "ai_summary":
            # [V7.9] 업데이트 변화점 요약
            load_heavy_modules() # [V13.3] requests 등 필수 라이브러리 바인딩 보장
            if not ensure_library("requests"): continue

            print(f"\r\n 🔍 {C.CYAN}서버에서 최신 코드를 가져와서 분석 중이야...{R}")
            try:
                # 1. 원격 파일 가져오기
                url = "http://srt.byus.net/korea.srt.py"
                res_get = requests.get(url, timeout=15)
                if res_get.status_code != 200:
                    print(f" ❌ {R}서버에서 파일을 가져올 수 없어.{R}")
                    time.sleep(2)
                    continue

                # [V8.1.1] 인코딩 손상 방지를 위해 바이너리로 캐싱
                cached_remote_content = res_get.content
                remote_code = cached_remote_content.decode('utf-8', errors='ignore')

                # 2. 현재 파일 읽기
                with open(os.path.abspath(__file__), "r", encoding="utf-8", errors="ignore") as f:
                    local_code = f.read()

                # 3. AI 에이전트 생성 (업데이트 요약은 항상 가벼운 Lite 모델 사용)
                global API_KEYS
                lite_model = 'gemini-2.5-flash-lite'
                agent = AIAgent(API_KEYS, lite_model)

                # [V7.9.1] 코드 전체 대신 Diff만 추출해서 AI에게 보내기
                # [TAG: #@get_code_diff]
                def get_code_diff(old, new):
                    old_lines = old.splitlines(keepends=True)
                    new_lines = new.splitlines(keepends=True)
                    diff_gen = difflib.unified_diff(old_lines, new_lines, fromfile='local', tofile='remote', n=3)
                    diff_list = list(diff_gen)
                    diff_text = "".join(diff_list[:500]) # 너무 길면 500줄까지만
                    return diff_text if diff_text.strip() else "(변경 사항 없음)"

                diff_content = get_code_diff(local_code, remote_code)

                prompt = "너는 파이썬 엔지니어이자 요약 전문가야. 코드 변경점(Diff)을 보고 '사용자가 체감할 핵심 기능 변화'만 아주 간략하게 3줄로 알려줘.\r\n"
                prompt += "미사여구나 기술적 디테일은 빼고, 어떤 기능이 좋아졌는지만 핵심 위주로 짧게 요약해줘.\r\n"
                prompt += "⚠️ [주의] 절대 JSON 형식을 쓰지 말고, 오직 번호가 매겨진 텍스트 3줄(1., 2., 3.)로만 답변해줘.\r\n"
                prompt += "반드시 친절한 한글로 작성해줘.\r\n\r\n"
                prompt += f"--- [코드 변경점 (Diff)] ---\r\n{diff_content}\r\n"

                summary = agent.ask_simple(prompt, status_fn=lambda x: print(f"    {C.DIM}{x}{R}", end='\r'))

                # AI 응답 후처리 (V7.9.8): 한글이 포함된 라인만 추출하여 깔끔하게 정리
                if summary:
                    summary = summary.strip().strip("`").strip()
                    lines = summary.splitlines()
                    # 한글이 포함된 라인만 골라내기 (JSON 기호, 영문 키 등을 자연스럽게 제거)
                    kr_lines = [l.strip() for l in lines if re.search(r'[가-힣]', l)]
                    if kr_lines:
                        # 이미 번호가 붙어있을 수 있으므로 정리만 해서 합침
                        summary = "\r\n".join(kr_lines)
                    else:
                        # 한글 라인이 전혀 없으면 원본이라도 최대한 정돈해서 표시
                        summary = summary.replace("{", "").replace("}", "").replace("[", "").replace("]", "").strip()

                print(f"\r\n\r\n 🤖 {C.BOLD}{C.SKY}[AI 분석 결과 - 업데이트 변화점 요약]{R}")
                print(f" {'='*60}")
                if summary:
                    print(f" {summary.strip()}")
                else:
                    print(f" {R}AI 분석 응답을 받지 못했어. 다시 시도해봐!{R}")
                print(f" {'='*60}")
                prompt_input(f"\r\n 👉 {Y}엔터를 누르면 메뉴로 돌아가.{R}")
            except Exception as e:
                print(f" ❌ {R}AI 분석 중 오류 발생: {e}{R}")
                time.sleep(2)
        elif u_key == "open_folder":
            # [신규] 실행 폴더 열기 (최대화) (V7.5)
            try:
                folder_path = os.path.dirname(os.path.abspath(__file__))
                if os.name == 'nt':
                    # Windows에서 PowerShell을 사용하여 최대화된 창으로 열기
                    cmd = f'powershell -Command "$wshell = New-Object -ComObject WScript.Shell; $wshell.Run(\'explorer.exe \\"{folder_path}\\"\', 3)"'
                    subprocess.Popen(cmd, shell=True)
                else:
                    open_path_resilient(folder_path)
                print(f"\r\n ✅ {G}실행 폴더를 최대화면으로 열었어!{R}")
                time.sleep(1.5)
            except Exception as e:
                print(f" ❌ {R}폴더 열기 중 오류 발생: {e}{R}")
                time.sleep(2)
        elif u_key == "manual_backup":
            # [V8.1.5] 수동 백업 (백업 폴더로 강제 이동)
            try:
                local_file = os.path.abspath(__file__)
                manual_backup_path = backup_file(local_file, suffix="manual")
                if manual_backup_path:
                    print(f"\r\n ✅ {G}수동 백업이 완료되었어!{R}")
                    print(f"    - {C.SKY}파일명:{R} {os.path.basename(manual_backup_path)}")
                    print(f"    - {C.DIM}위치:{R} backups/ 폴더")
                else:
                    print(f" ❌ {R}백업 생성 실패{R}")
                time.sleep(2)
            except Exception as e:
                print(f" ❌ {R}백업 중 오류 발생: {e}{R}")
                time.sleep(2)
        elif u_key == "restore":
            # [신규] 백업 파일로부터 복구 로직 (V7.2 & V7.9.6 통합 & V8.0.0 최적화)
            local_file_abs = os.path.abspath(__file__)
            # [V155.5] backups 폴더 내 다양한 패턴의 백업 파일 통합 검색 🔍🛡️
            root_dir = os.path.dirname(local_file_abs)
            backup_dir = os.path.join(root_dir, "backups")
            
            backups = []
            for ext_pattern in ["*korea.srt.py*.backup", "*korea.srt.py*.bak", "*korea.srt.py*.aibackup", "korea.srt.py*"]:
                backups.extend(glob.glob(os.path.join(backup_dir, ext_pattern)))
            backups = list(set(backups)) # 중복 파일 경로 제거냥!

            all_backups_list = []
            for b_path in backups:
                # [V155.5] 백업 성격에 따른 라벨링 세분화 🏷️
                if ".update.backup" in b_path:
                    label = "🤖 [업데이트]"
                elif ".aibackup" in b_path:
                    label = "🧠 [AI백업]"
                elif "manual" in b_path:
                    label = "💾 [수동백업]"
                else:
                    label = "📦 [자동백업]"
                all_backups_list.append({"path": b_path, "label": label, "mtime": os.getmtime(b_path)})

            # 최신순 정렬 (가장 최근 백업본이 맨 위로 오도록 보장)
            all_backups_list.sort(key=lambda x: x["mtime"], reverse=True)

            if not all_backups_list:
                print(f"\r\n ℹ️ {Y}아직 생성된 백업 파일이 없어.{R}")
                time.sleep(1.5)
                continue

            b_options = []
            for item in all_backups_list:
                dt_str = datetime.fromtimestamp(item["mtime"]).strftime('%m/%d %H:%M')
                fname = os.path.basename(item["path"])
                b_options.append(f" {item['label']} {fname} ({dt_str})")

            b_options.append(" ❌ 취소")

            b_sel, _, *_ = _interactive_menu("복구할 시점 선택", b_options, timeout=0)
            if b_sel < 0 or b_sel >= len(all_backups_list): continue

            target_backup = all_backups_list[b_sel]["path"]
            print(f"\r\n 🛡️  {C.CYAN}선택한 백업으로 복구를 시작할게...{R}")
            try:
                # 현재 파일을 백업본으로 교체
                shutil.copy2(target_backup, local_file_abs)
                print(f" ✅ {G}복구가 완료되었어! 프로그램을 재시작할게.{R}")
                time.sleep(2)
                return True # 재시작 신호
            except Exception as e:
                print(f" ❌ {R}복구 중 오류 발생: {e}{R}")
                time.sleep(2)
        elif u_key == "toggle_auto":
            new_val = not is_auto_enabled
            settings.data['auto_update_enabled'] = new_val
            settings.save()
            print(f"\r\n ✅ {ctext(f'자동 업데이트 체크가 {'활성화' if new_val else '비활성화'} 되었어!', G if new_val else Y)}")
            time.sleep(1.5)
        elif u_key == "back":
            break
    return False

