# region [08. 텔레그램 봇 연동 시스템] 🤖
# ─────────────────────────────────────────────────────────────
# [신규] 텔레그램 봇 연동 헬퍼 클래스
# ─────────────────────────────────────────────────────────────
# [TAG: #@_sync_remote_menu]
def _sync_remote_menu(token, chat_id, title, items, selected_idx=0, cols=1):
    """[V60.0] TUI 메뉴 상태를 텔레그램 인라인 버튼 리스트로 동기화합니다. 📱📡"""
    global _remote_menu_msg_id, _remote_cmd, _remote_menu_active
    if not token or not chat_id: return
    if not _remote_menu_active: return # [V60.0] 활성화 상태가 아니면 무시 (리스타트 시 자동 팝업 방지)

    _remote_cmd = None # 신호 소모

    # 1. 메시지 본문 요약
    curr_item = items[selected_idx] if 0 <= selected_idx < len(items) else "선택 없음"
    # [V61.1] ANSI 코드 및 레이아웃 마커(__SPAN__, __DIVIDER__) 제거 (텔레그램 전송용) 🧼
    # [V93.0] 객체형 아이템 대응 (원천 비노출 구현 🧼✨)
    curr_item_clean = re.sub(r'\033\[[0-9;]*m', '', _get_ui_text(curr_item)).strip()

    reply = f"📱 <b>원격 리모컨: {title}</b>\r\n"
    reply += "━━━━━━━━━━━━━━━━━━━━\r\n"
    reply += f"👉 <b>{curr_item_clean}</b>\r\n\r\n"
    reply += "<i>(하단 버튼으로 메뉴를 직접 조작해줘! 😊)</i>"

    # 2. 인라인 키보드 구성 (메뉴 항목 버튼 + 방향키)
    kb = []

    # [V60.0] 메뉴 항목들을 버튼으로 생성 (한 줄에 1개씩, 구분선 제외, cols 지원)
    btn_list = []
    for i, item in enumerate(items):
        # [V91.6] ANSI 코드 및 레이아웃 마커(__SPAN__, __DIVIDER__) 제거 🧼
        # [V93.0] 헬퍼를 통해 객체형 아이템의 순수 텍스트 획득 (원천 비노출 ✨)
        item_text = re.sub(r'\033\[[0-9;]*m', '', _get_ui_text(item))

        # [V60.0] 구분선 서식(예: "---------------------,..")은 버튼에서 제외 (사용자님 요청 🚫)
        # [V93.0] Key 방식(Dict) 구분선 판별 우선 적용 ✨
        if _is_divider(item): continue
        if cols == 1 and set(item_text.strip().replace(",", "").replace(".", "")) <= {"-", " ", "_"}: # 대시나 언더바로 선언된 구분선 체크
            if item_text.strip():
                continue

        is_empty_padding = not item_text.strip()

        if is_empty_padding:
            btn_text = " "
            callback = "remote:noop"
        else:
            # [V60.0] 21자(한글 기준) 내외로 추가 확장 (사용자님 요청 📏)
            short_text = _smart_truncate(item_text.strip(), limit=46)
            prefix = "✅ " if i == selected_idx else ""
            btn_text = f"{prefix}{short_text}"
            callback = f"remote:idx:{i}"

        btn_list.append({"text": btn_text, "callback_data": callback, "idx": i})

    # [V60.0] cols 인자에 맞춰 가상 탐색기(TUI)와 동일한 배열(열 기준)로 인라인 키보드 구성
    if cols > 1:
        num_options = len(items)
        rows_count = int(math.ceil(num_options / cols))
        for r in range(rows_count):
            row_btns = []
            for c in range(cols):
                idx = r + (c * rows_count)
                if idx < num_options:
                    # btn_list에서 실제 인덱스에 해당하는 항목 찾기
                    match = next((b for b in btn_list if b["idx"] == idx), None)
                    if match:
                        row_btns.append({"text": match["text"], "callback_data": match["callback_data"]})
            if row_btns:
                kb.append(row_btns)
    else:
        for b in btn_list:
            kb.append([{"text": b["text"], "callback_data": b["callback_data"]}])

    # 내비게이션 및 제어 행
    nav_row = [
        {"text": "⬅️", "callback_data": "remote:left"},
        {"text": "⬆️", "callback_data": "remote:up"},
        {"text": "⬇️", "callback_data": "remote:down"},
        {"text": "➡️", "callback_data": "remote:right"}
    ]
    kb.append(nav_row)

    confirm_row = [
        {"text": "🆗 선택(Enter)", "callback_data": "remote:enter"},
        {"text": "⌨️ 입력", "callback_data": "remote:input"},
        {"text": "❌ 닫기", "callback_data": "remote:close"}
    ]
    kb.append(confirm_row)

    # 3. 메시지 전송 또는 수정 (새 메시지로 갱신 혹은 기존 메시지 덮어쓰기)
    try:
        reply_markup = {"inline_keyboard": kb}
        success = False

        if _remote_menu_msg_id > 0:
            # [V61.1] 기존 메뉴판을 edit_message_text로 덮어쓰기 (채팅 내역 누적/더러워짐 방지 🧹)
            success = TelegramBot.edit_message_text(token, chat_id, _remote_menu_msg_id, reply, kb)

        if not success:
            # 기존 메시지가 지워졌거나 처음 띄우는 경우에만 새 메시지 전송
            resp = TelegramBot.send_message(token, chat_id, reply, reply_markup)
            if isinstance(resp, dict) and "result" in resp and "message_id" in resp["result"]:
                _remote_menu_msg_id = resp["result"]["message_id"]
    except Exception as e:
        _log_to_file(f"⚠️ [Remote Sync Error] {e}")

# endregion

# [TAG: #@_cleanup_remote_py_menu]
def _cleanup_remote_py_menu(token, chat_id):
    """[V78.5] 다른 메뉴 이동 시 기존 '원격 py' 메뉴와 모든 입력 대기 상태를 강제 초기화합니다. 🧹📱"""
    global _remote_menu_active, _remote_menu_msg_id, _remote_input_future, _user_states
    try:
        # 1. 일반 입력 대기 상태(절전 시간 입력 등) 초기화
        _user_states[str(chat_id)] = None

        # 2. 원격 prompt_input() 대기 상태 강제 종료
        if _remote_input_future and not _remote_input_future.done():
            try:
                _remote_input_future.set_result("취소")
                _log_to_file("⌨️ [Cleanup] Remote input waiting cancelled.")
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

        # 3. 원격 py 인라인 메뉴 삭제
        if _remote_menu_active or _remote_menu_msg_id > 0:
            _remote_menu_active = False
            if _remote_menu_msg_id > 0:
                # [V78.4] 기존 메시지를 삭제하여 화면을 깔끔하게 정리 (실패 시 무시)
                TelegramBot.delete_message(token, chat_id, _remote_menu_msg_id)
                _remote_menu_msg_id = 0
    except Exception as e:
        _log_to_file(f"⚠️ [Cleanup Error] {e}")

# region [09. PC 원격 제어 및 멀티미디어] 📸🎵
# ─────────────────────────────────────────────────────────────
# [신규] 공용 유틸리티 함수 - 코드 중복 제거 및 유연한 처리
# ─────────────────────────────────────────────────────────────
# [V19.0] 웹 기반 오디오 스트리밍 엔진 (무설치 + 백그라운드 지원)
class PCAudioWebStreamer:
    """PC 시스템 오디오를 캡처하여 스트리밍하는 클래스"""
    # [TAG: #@__init___9]
    def __init__(self):
        self.p = None
        self.stream = None
        self.is_running = False
        self.listeners = []
        self._lock = threading.Lock()
        self.sample_rate = 44100
        self.channels = 2
        self.chunk_size = 1024

    # [TAG: #@find_wasapi_loopback]
    def find_wasapi_loopback(self):
        try:
            import pyaudio
            p = pyaudio.PyAudio()
            default_out = p.get_default_output_device_info()

            # WASAPI 호스트 API 인덱스 찾기
            wasapi_idx = -1
            for i in range(p.get_host_api_count()):
                if "WASAPI" in p.get_host_api_info_by_index(i)["name"]:
                    wasapi_idx = i
                    break

            if wasapi_idx == -1:
                return None

            # 루프백 장치 찾기
            for i in range(p.get_device_count()):
                dev = p.get_device_info_by_index(i)
                if dev["hostApi"] == wasapi_idx and dev["maxInputChannels"] > 0:
                    # 장치 이름에 'Loopback'이 포함되거나 기본 출력 이름과 유사한 경우
                    if "Loopback" in dev["name"] or default_out["name"] in dev["name"]:
                        return dev

            # 못 찾으면 '스테레오 믹스' 검색
            for i in range(p.get_device_count()):
                dev = p.get_device_info_by_index(i)
                if "스테레오 믹스" in dev["name"] or "Stereo Mix" in dev["name"]:
                    return dev

            return None
        except: return None
        finally:
            try: p.terminate()
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

    # [TAG: #@start_4]
    def start(self):
        with self._lock:
            if self.is_running: return True

            try:
                import pyaudio
                self.p = pyaudio.PyAudio()
                dev = self.find_wasapi_loopback()
                if not dev:
                    _log_to_file("❌ [AudioStream] 루프백 장치를 찾을 수 없음")
                    return False

                self.sample_rate = safe_int(dev.get("defaultSampleRate", 44100), default=44100)
                self.channels = dev["maxInputChannels"]

                self.stream = self.p.open(
                    format=pyaudio.paInt16,
                    channels=self.channels,
                    rate=self.sample_rate,
                    input=True,
                    frames_per_buffer=self.chunk_size,
                    input_device_index=dev["index"]
                )
                self.is_running = True
                _log_to_file(f"🎧 [AudioStream] 스트리밍 시작: {dev['name']} ({self.sample_rate}Hz)")
                return True
            except Exception as e:
                _log_to_file(f"❌ [AudioStream] 시작 실패: {e}")
                self.stop()
                return False

    # [TAG: #@stop_3]
    def stop(self):
        with self._lock:
            self.is_running = False
            if self.stream:
                try: self.stream.stop_stream(); self.stream.close()
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")
                self.stream = None
            if self.p:
                try: self.p.terminate()
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")
                self.p = None
            _log_to_file("🎧 [AudioStream] 스트리밍 중단")

    # [TAG: #@generator]
    def generator(self):
        """Web 응답을 위한 데이터 제너레이터 (WAV 헤더 포함)"""
        if not self.start():
            return

        # WAV 헤더 생성 (Infinite Length 효과를 위해 큰 값 사용 또는 생략 가능하지만 브라우저 호환성을 위해 필요)
        # 여기서는 Raw PCM 대신 간단한 WAV 헤더를 붙여서 호환성 확보

        # [TAG: #@get_header]
        def get_header():
            with io.BytesIO() as container:
                with wave.open(container, "wb") as wav:
                    wav.setnchannels(self.channels)
                    wav.setsampwidth(2) # 16-bit
                    wav.setframerate(self.sample_rate)
                    wav.setnframes(999999999) # 사실상 무한
                return container.getvalue()[:44] # 헤더 부분만 추출

        yield get_header()

        try:
            while self.is_running:
                data = self.stream.read(self.chunk_size, exception_on_overflow=False)
                yield data
        except Exception as e:
            try: _log_to_file(f"⚠️ [Silent Error Handled] {e}")
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")
        finally:
            # 마지막 청취자가 나가도 즉시 끄지 않고 일정 시간 유지할 수 있으나
            # 여기서는 단순하게 구현
            pass

_pc_audio_streamer = PCAudioWebStreamer()

# [TAG: #@_get_image_match_percentage]
def _get_image_match_percentage(path1, path2):
    """[V78.3] 두 이미지의 픽셀 일치율(%)을 계산합니다. (Pillow 기반) 🕵️‍♂️✨"""
    try:
        from PIL import Image, ImageChops, ImageStat
        img1 = Image.open(path1).convert('RGB')
        img2 = Image.open(path2).convert('RGB')

        # 고속 비교를 위해 해상도 축소 (640x360 정도로 충분함)
        img1 = img1.resize((640, 360), Image.NEAREST)
        img2 = img2.resize((640, 360), Image.NEAREST)

        # 두 이미지의 차이점 추출
        diff = ImageChops.difference(img1, img2)
        stat = ImageStat.Stat(diff)

        # 평균 픽셀 차이 (0~255)가 작을수록 일치함
        diff_avg = sum(stat.mean) / 3.0

        # 0(완전 동일) ~ 100(완전 다름) 사이의 점수를 일치율(%)로 변환
        # (차이가 1.0 미만이면 거의 동일한 것으로 간주하여 100% 부여)
        match_rate = max(0.0, 100.0 - (diff_avg / 255.0 * 100.0))
        return match_rate
    except Exception as e:
        _log_to_file(f"⚠️ [Image Compare Error] {e}")
        return 0.0

# [TAG: #@_pc_screenshot_loop_worker]
def _pc_screenshot_loop_worker(token, chat_id):
    """[V78.3] 화면 캡쳐 루프 배경 워커 (감도 99% 정밀 감지) 🕵️‍♂️📸"""
    import tempfile

    # [V8.19] 워커 진입 로그 강제 전송
    _log_to_file(f"🟢 [Screenshot Worker] Thread Entered. (ChatID: {chat_id})")

    global _pc_screenshot_loop_1m_active, _pc_screenshot_loop_change_active, _screenshot_loop_lock, pyautogui

    ref_path = os.path.join(tempfile.gettempdir(), "_last_scr_ref.png")

    while True:
        # [V8.21] 모든 루프의 체크 간격을 60초로 통일 (사용자 요청)
        time.sleep(60)

        with _screenshot_loop_lock:
            active_1m = _pc_screenshot_loop_1m_active
            active_change = _pc_screenshot_loop_change_active

        if not active_1m and not active_change:
            _log_to_file("🛑 [Screenshot Loop] All loops inactive. Worker exiting.")
            if os.path.exists(ref_path):
                try: os.remove(ref_path)
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")
            break

        try:
            _log_to_file(f"📸 [Screenshot Loop] Start Capture... (1m:{active_1m}, Change:{active_change})")
            tmp_dir = tempfile.gettempdir()
            curr_path = os.path.join(tmp_dir, f"loop_scr_{int(time.time())}.png")

            global pyautogui
            if pyautogui is None:
                _log_to_file("⏳ [Screenshot Loop] Loading heavy modules...")
                load_heavy_modules()

            if pyautogui is None:
                _log_to_file("❌ [Screenshot Loop] pyautogui is still None after loading!")
                continue

            pyautogui.screenshot(curr_path)
            _log_to_file(f"💾 [Screenshot Loop] Screenshot saved: {curr_path}")

            should_send = False
            match_rate = 0.0

            if active_1m:
                should_send = True
            elif active_change:
                if not os.path.exists(ref_path):
                    should_send = True
                    match_rate = 0.0
                else:
                    match_rate = _get_image_match_percentage(ref_path, curr_path)
                    if match_rate < 99.0:
                        should_send = True

            if should_send:
                shutil.copy2(curr_path, ref_path)

                now_str = time.strftime('%H:%M:%S')
                mode_str = "🔄 1분 루프" if active_1m else f"🕵️ 변화 감지 ({match_rate:.1f}% 일치)"
                caption = f"📸 <b>{mode_str} 캡쳐본이야!</b>\r\n(보낸시간: {now_str}) 👍"

                btn_1m_txt = "🟢 1분 루프" if active_1m else "🔴 1분 루프"
                btn_chg_txt = "🟢 변화 감지" if active_change else "🔴 변화 감지"

                # [V8.21] 3버튼 1열 배치 UI (1분, 변화, 즉시)
                buttons = [[
                    {"text": btn_1m_txt, "callback_data": "pc_screenshot_loop_1m"},
                    {"text": btn_chg_txt, "callback_data": "pc_screenshot_loop_change"},
                    {"text": "즉시 📸", "callback_data": "pc_screenshot"}
                ]]

                ok = TelegramBot.send_photo(token, chat_id, curr_path, caption, reply_markup={"inline_keyboard": buttons})
                _log_to_file(f"📤 [Screenshot Loop] Send Status: {ok} (Mode: {mode_str})")
            else:
                _log_to_file(f"⏭️ [Screenshot Loop] Skipping (Match: {match_rate:.1f}%)")

            if os.path.exists(curr_path): os.remove(curr_path)
        except Exception as e:
            _log_to_file(f"⚠️ [Screenshot Loop Error] {e}")
            _log_to_file(traceback.format_exc())
        finally:
            if 'curr_path' in locals() and os.path.exists(curr_path):
                try: os.remove(curr_path)
                except: pass

# [TAG: #@_pc_remote_app_scan]
# [규칙] 원격지원 앱은 "그 순간" PC 에 설치된 것만 스캔해서 메뉴를 동적 생성한다.
# ⚠️ 판별 근거는 반드시 "레지스트리 Uninstall + 실제 exe 존재" 교차검증이다.
#    폴더 흔적만 남은 앱(설치 안 된 AnyDesk·RustDesk·VNC 등)을 오인하면 안 된다.
# ⚠️ StarDesk 는 HKCU, TeamViewer 는 HKLM 에 등록되어 있어 3핌브를 모두 봐야 한다.
_PC_REMOTE_APP_TARGETS = [
    # (표시이름, exe프로세스명, exe 상대경로 후보들)
    ("StarDesk",  "StarDesk",  [r"StarDesk\StarDesk.exe", r"StarDesk\bin\StarDesk.exe"]),
    ("TeamViewer", "TeamViewer", [r"TeamViewer\TeamViewer.exe", r"TeamViewer\TeamViewer_Desktop.exe"]),
    ("AnyDesk",   "AnyDesk",   [r"AnyDesk\AnyDesk.exe"]),
    ("RustDesk",  "RustDesk",  [r"RustDesk\RustDesk.exe"]),
    ("ToDesk",    "ToDesk",    [r"ToDesk\ToDesk.exe"]),
    ("Sunlogin",  "SunloginClient", [r"Oray\SunloginClient\SunloginClient.exe"]),
    ("Parsec",    "parsec",    [r"Parsec\parsecd.exe"]),
    ("HopToDesk", "HopToDesk", [r"HopToDesk\HopToDesk.exe"]),
]

def _pc_remote_app_scan() -> list:
    """설치된 원격지원 앱을 스캔합니다. (레지스트리 3핌브 + exe 교차검증)

    Returns: [{'name','exe','running','svc_name'}] — 미설치 앱은 포함되지 않음.
    """
    try:
        import winreg
    except ImportError:
        return []

    # 1) 레지스트리 Uninstall 3핌브에서 설치된 앱 이름 수집
    installed_names = set()
    reg_paths = [
        (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"),
        (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall"),
        (winreg.HKEY_CURRENT_USER,  r"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall"),
    ]
    for root, sub in reg_paths:
        try:
            with winreg.OpenKey(root, sub) as k:
                idx = 0
                while True:
                    try:
                        dn = winreg.EnumKey(k, idx); idx += 1
                    except OSError:
                        break
                    try:
                        with winreg.OpenKey(k, dn) as sk:
                            nm = winreg.QueryValueEx(sk, "DisplayName")[0]
                            if nm: installed_names.add(str(nm).strip())
                    except OSError:
                        continue
        except OSError:
            continue

    # 2) 후보 경로 모으기 (Program Files / Program Files(x86) / LOCALAPPDATA)
    bases = []
    for env in ("ProgramFiles", "ProgramFiles(x86)", "LOCALAPPDATA"):
        p = os.environ.get(env)
        if p and os.path.isdir(p): bases.append(p)

    # 3) 레지스트리 등록 확인 + exe 실존 확인 → 교차검증 통과분만 반환
    found = []
    for name, proc_name, rels in _PC_REMOTE_APP_TARGETS:
        in_reg = any(name.lower() in n.lower() for n in installed_names)
        exe_path = None
        for base in bases:
            for rel in rels:
                cand = os.path.join(base, rel)
                if os.path.isfile(cand):
                    exe_path = cand; break
            if exe_path: break

        if not (in_reg and exe_path):
            continue  # 흔적만 남은 앱은 제외 🚫

        running = False
        try:
            import psutil  # type: ignore
            running = any(p.info['name'] == f"{proc_name}.exe" for p in psutil.process_iter(['name']))
        except Exception:
            # psutil 미사용 시 tasklist 폴백 (표시 전용이라 부정확해도 무해)
            try:
                out = subprocess.run(
                    ['tasklist', '/FI', f'IMAGENAME eq {proc_name}.exe', '/NH'],
                    capture_output=True, text=True, timeout=5, creationflags=subprocess.CREATE_NO_WINDOW
                ).stdout or ''
                running = proc_name.lower() in out.lower()
            except Exception:
                running = False

        found.append({'name': name, 'exe': exe_path, 'running': running, 'proc': proc_name})
    return found

# [TAG: #@_pc_remote_app_menu]
def _pc_remote_app_menu(token: str, chat_id: str, msg_id: int = None):
    """[원격지원] 버튼을 누른 '그 순간' 설치된 앱을 스캔해 인라인키보드를 동적 생성합니다."""
    apps = _pc_remote_app_scan()

    if not apps:
        reply = "🖥️ <b>원격지원 앱</b>\r\n\r\n❌ 설치된 원격지원 앱을 못 찾겠어!\r\n\r\n<i>(AnyDesk · RustDesk · ToDesk 등 설치 후 다시 눌러줘)</i>"
        if msg_id:
            TelegramBot.edit_message_text(token, chat_id, msg_id, reply, None)
        else:
            TelegramBot.send_message(token, chat_id, reply)
        return

    buttons = []
    for idx, app in enumerate(apps):
        # StarDesk·TeamViewer 는 트레이 UI 만 토글 (트레이 우클릭→종기와 동일 동작)
        state = "🟢 실행중" if app['running'] else "🔴 꺼짐"
        act = "pc_rem:0" if app['running'] else "pc_rem:1"  # 0=종료 1=실행
        buttons.append([{"text": f"{'✅' if app['running'] else '📴'} {app['name']}  {state}", "callback_data": f"{act}:{idx}"}])

    buttons.append([{"text": "🔄 새로고침", "callback_data": "pc_rem:2"}, {"text": "❌ 닫기", "callback_data": "pc_rem:9"}])

    reply = "🖥️ <b>원격지원 앱</b>\r\n\r\n원격지원 앱을 선택해줘! 😊\r\n\r\n💡 <b>Tip:</b> <b>끄기</b>는 트레이 아이콘 우클릭 → 종료와 동일해!"
    if msg_id:
        TelegramBot.edit_message_text(token, chat_id, msg_id, reply, buttons)
    else:
        TelegramBot.send_message(token, chat_id, reply, {"inline_keyboard": buttons})

# [TAG: #@_pc_remote_app_toggle]
def _pc_remote_app_toggle(token: str, chat_id: str, mode: str, idx: int):
    """[원격지원] 선택한 원격지원 앱 UI 를 켜거나 끕니다. (mode: '1'=실행 '0'=종료)"""
    apps = _pc_remote_app_scan()
    if idx < 0 or idx >= len(apps):
        TelegramBot.send_message(token, chat_id, "⚠️ 목록이 바뀌었어. 다시 열어줘!")
        return
    app = apps[idx]

    try:
        if mode == '1':
            # [_open_unelevated] 과 동일한 경로 사용 → UWP/인자 처리 로직 재사용 🛡️
            if app['running']:
                TelegramBot.send_message(token, chat_id, f"✅ <b>{app['name']}</b> 이미 실행중이야!")
            else:
                subprocess.Popen(f'explorer.exe "{app["exe"]}"', shell=True)
                _log_to_file(f"🖥️ [Remote App] Launched: {app['name']} ({app['exe']})")
                TelegramBot.send_message(token, chat_id, f"🚀 <b>{app['name']}</b> 실행했어!")
        else:
            # 트레이 우클릭→종기와 동일 = UI 프로세스만 종료
            r = subprocess.run(['taskkill', '/IM', f"{app['proc']}.exe", '/F'],
                               capture_output=True, text=True, timeout=10,
                               creationflags=subprocess.CREATE_NO_WINDOW)
            if r.returncode == 0:
                _log_to_file(f"🖥️ [Remote App] Killed: {app['name']} ({app['proc']}.exe)")
                TelegramBot.send_message(token, chat_id, f"🔒 <b>{app['name']}</b> 껐어! (트레이에서도 사라졌을 거야)")
            else:
                TelegramBot.send_message(token, chat_id, f"⚠️ <b>{app['name']}</b> 종료 실패: <code>{(r.stderr or '').strip()[:80]}</code>")
    except Exception as e:
        _log_to_file(f"⚠️ [Remote App Toggle Error] {e}")
        TelegramBot.send_message(token, chat_id, f"❌ 원격앱 제어 오류: {e}")

# [TAG: #@_pc_control_screenshot]
def _pc_control_screenshot(token: str, chat_id: str):
    """[V78.3] 현재 PC 화면을 캡쳐하여 텔레그램으로 전송합니다. (루프 버튼 포함)"""
    _log_to_file("📸 [Screenshot] Start: Initializing...")
    load_heavy_modules()
    try:
        global _pc_screenshot_loop_1m_active, _pc_screenshot_loop_change_active
        import pyautogui
        import tempfile

        # 임시 파일 경로 생성
        tmp_dir = tempfile.gettempdir()
        screenshot_path = os.path.join(tmp_dir, f"pc_screen_{int(time.time())}.png")
        ref_path = os.path.join(tmp_dir, "_last_scr_ref.png") # 기준 이미지

        # 화면 캡쳐
        pyautogui.screenshot(screenshot_path)

        # 기준 이미지 강제 갱신 (수동 캡쳐 시점이 새로운 기준점이 됨)
        shutil.copy2(screenshot_path, ref_path)

        # 텔레그램 전송
        caption = f"📸 <b>현재 PC 화면 캡쳐본이야!</b>\r\n(시간: {time.strftime('%Y-%m-%d %H:%M:%S')}) 👍"

        btn_1m_txt = "🟢 1분 루프" if _pc_screenshot_loop_1m_active else "🔴 1분 루프"
        btn_chg_txt = "🟢 변화 감지" if _pc_screenshot_loop_change_active else "🔴 변화 감지"

        # [V8.21] 3버튼 1열 배치 UI
        buttons = [[
            {"text": btn_1m_txt, "callback_data": "pc_screenshot_loop_1m"},
            {"text": btn_chg_txt, "callback_data": "pc_screenshot_loop_change"},
            {"text": "즉시 📸", "callback_data": "pc_screenshot"}
        ]]

        success = TelegramBot.send_photo(token, chat_id, screenshot_path, caption, reply_markup={"inline_keyboard": buttons})

        if os.path.exists(screenshot_path): os.remove(screenshot_path)
        return success
    except Exception as e:
        _log_to_file(f"⚠️ [Screenshot Error] {e}")
        TelegramBot.send_message(token, chat_id, f"❌ <b>캡쳐 중 오류 발생:</b> {e}")
        return False

# [TAG: #@_pc_control_key]
def _pc_control_key(key: str, times: int = 1):
    """
    [공통] PC 키 제어 로직 (WinAPI 전용) - V16.0.1
    ⚠️ 주의: 이 함수는 워치독 템플릿 코드(_update_watchdog_script 내의 _pc_control_key)와 미러링 관계임.
    수정 시 템플릿 내부 소스도 반드시 동일하게 동기화할 것! 👍
    """
    try:
        vk_map = {
            'playpause': 0xB3, 'prevtrack': 0xB1, 'nexttrack': 0xB0, 'mediastop': 0xB2,
            'left': 0x25, 'up': 0x26, 'right': 0x27, 'down': 0x28,
            'volumemute': 0xAD, 'volumedown': 0xAE, 'volumeup': 0xAF,
            'space': 0x20, 'enter': 0x0D, 'backspace': 0x08, 'esc': 0x1B, 'tab': 0x09
        }
        vk = vk_map.get(key.lower())
        if vk:
            # [롤백] WM_APPCOMMAND 제거하고 keybd_event만 사용 (AIMP 중복 입력 방지)
            is_extended = (vk >= 0xAD and vk <= 0xB3) or (vk >= 0x21 and vk <= 0x28)
            scan = ctypes.windll.user32.MapVirtualKeyW(vk, 0)
            flag_down = 0x0001 if is_extended else 0 # 1=EXTENDED
            flag_up = 0x0003 if is_extended else 0x0002 # 3=EXTENDED|KEYUP

            for _ in range(times):
                ctypes.windll.user32.keybd_event(vk, scan, flag_down, 0)
                time.sleep(0.01)
                ctypes.windll.user32.keybd_event(vk, scan, flag_up, 0)
            return True
        elif key.lower() == 'alt_f4':
            # [신규] 활성 창 종료 명시적 처리
            ctypes.windll.user32.keybd_event(0x12, 0, 0, 0) # Alt Down
            ctypes.windll.user32.keybd_event(0x73, 0, 0, 0) # F4 Down
            time.sleep(0.05)
            ctypes.windll.user32.keybd_event(0x73, 0, 0x0002, 0) # F4 Up
            ctypes.windll.user32.keybd_event(0x12, 0, 0x0002, 0) # Alt Up
            return True
        elif key.lower() == 'show_desktop':
            # [신규] 바탕화면 보기 (Win+D) 명시적 처리
            ctypes.windll.user32.keybd_event(0x5B, 0, 0, 0) # Left Win Down
            ctypes.windll.user32.keybd_event(0x44, 0, 0, 0) # D Down
            time.sleep(0.05)
            ctypes.windll.user32.keybd_event(0x44, 0, 0x0002, 0) # D Up
            ctypes.windll.user32.keybd_event(0x5B, 0, 0x0002, 0) # Left Win Up
            return True
        else:
            load_heavy_modules()
            import pyautogui
            for _ in range(times): pyautogui.press(key)
            return True
    except: return False

# [TAG: #@_pc_media_stop]
def _pc_media_stop():
    """[V17.5.7] 현재 실행 중인 주요 미디어 플레이어들을 강제 종료합니다."""
    targets = ["AIMP.exe", "PotPlayer64.exe", "PotPlayer.exe", "vlc.exe", "GOM.exe", "KMPlayer.exe", "KMP64.exe"]
    try:
        for target in targets:
            subprocess.run(['taskkill', '/F', '/IM', target], capture_output=True, creationflags=0x08000000)
        return True
    except:
        return False

# [V14.2] 미디어 플레이어 캐시 경로 정의
_MEDIA_CACHE_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "media_players.json")

# [TAG: #@_load_media_cache]
def _load_media_cache():
    """[V16.0.1] settings.json(settings_ref)에서 미디어 플레이어 캐시를 불러옵니다."""
    try:
        # [V16.0.1] settings_ref 혹은 settings 전역 변수 사용
        global settings, settings_ref
        target_settings = settings_ref if settings_ref else settings

        if target_settings:
            media_data = target_settings.data.get("media_players")
            if media_data: return media_data

        # [V14.8] 캐시가 없을 경우 기본값 생성 로직
        os.environ.get('USERNAME', 'User')
        default_cache = {
            "music": [
                {"name": "Spotify", "path": os.path.expandvars(r"%APPDATA%\Spotify\Spotify.exe")},
                {"name": "YouTube Music", "path": os.path.expandvars(r"%LOCALAPPDATA%\YouTube Music\YouTube Music.exe")},
                {"name": "Melon", "path": os.path.expandvars(r"%LOCALAPPDATA%\Melon\Melon.exe")}
            ],
            "video": [
                {"name": "팟플레이어", "path": os.path.join(os.environ.get('PROGRAMFILES', r"C:\Program Files"), r"DAUM\PotPlayer\PotPlayer64.exe")},
                {"name": "팟플레이어(x86)", "path": os.path.join(os.environ.get('PROGRAMFILES(X86)', r"C:\Program Files (x86)"), r"DAUM\PotPlayer\PotPlayer.exe")},
                {"name": "VLC", "path": os.path.join(os.environ.get('PROGRAMFILES', r"C:\Program Files"), r"VideoLAN\VLC\vlc.exe")}
            ]
        }
        # 실제 존재하는 것 위주로 필터링
        valid_cache = {"music": [], "video": []}
        for m_type in ["music", "video"]:
            for item in default_cache[m_type]:
                if os.path.exists(item['path']): valid_cache[m_type].append(item)

        if valid_cache["music"] or valid_cache["video"]:
            _save_media_cache(valid_cache)
            return valid_cache
    except Exception as e:
        _log_to_file(f"⚠️ [Cache Load Error] {e}")
    return None

# [TAG: #@_save_media_cache]
def _save_media_cache(players):
    """[V16.0.1] 미디어 플레이어 검색 결과를 settings.json(settings_ref)에 저장합니다."""
    try:
        global settings, settings_ref
        target_settings = settings_ref if settings_ref else settings

        if target_settings:
            target_settings.data["media_players"] = players
            target_settings.save()
            _log_to_file("✅ [Cache Save] Media players saved to settings.json")
        else:
            # Fallback (settings_ref가 없는 특수 상황 대비)
            pass
    except Exception as e:
        _log_to_file(f"⚠️ [Cache Save Error] {e}")

# [TAG: #@_pc_detect_media_players]
def _pc_detect_media_players(media_type="music", force_refresh=False, found_list=None):
    """PC 파일 시스템에서 주요 미디어 앱 경로를 직접 확인하여 감지합니다. (단순화 버전) [V14.9]"""
    if found_list is None: found_list = []

    # 0. 캐시 확인 (강제 새로고침이 아닌 경우)
    if not force_refresh:
        cached = _load_media_cache()
        if cached and media_type in cached:
            for i, p in enumerate(cached[media_type]):
                # [V15.5.3] 캐시에 index가 없는 경우를 대비해 확실히 부여
                if "index" not in p: p["index"] = i
                if p not in found_list: found_list.append(p)
            return found_list

    # 미디어 타입별 고정 경로 타겟 (유명 앱 5~6가지 위주)
    if media_type == "music":
        targets = [
            ("Spotify", [os.path.expandvars(r"%APPDATA%\Spotify\Spotify.exe"),
                         os.path.expandvars(r"%LOCALAPPDATA%\Microsoft\WindowsApps\Spotify.exe")]),
            ("YouTube Music", [os.path.expandvars(r"%LOCALAPPDATA%\YouTube Music\YouTube Music.exe")]),
            ("AIMP", [os.path.join(os.environ.get('PROGRAMFILES', r"C:\Program Files"), r"AIMP\AIMP.exe"),
                         os.path.join(os.environ.get('PROGRAMFILES(X86)', r"C:\Program Files (x86)"), r"AIMP\AIMP.exe")]),
            ("Melon", [os.path.expandvars(r"%LOCALAPPDATA%\Melon\Melon.exe"),
                       os.path.join(os.environ.get('PROGRAMFILES(X86)', r"C:\Program Files (x86)"), r"Melon\Melon.exe")]),
            ("Bugs", [os.path.expandvars(r"%LOCALAPPDATA%\Bugs\Bugs.exe")]),
            ("Genie", [os.path.join(os.environ.get('PROGRAMFILES(X86)', r"C:\Program Files (x86)"), r"genie\genie.exe")])
        ]
    else: # video
        targets = [
            ("팟플레이어", [os.path.join(os.environ.get('PROGRAMFILES', r"C:\Program Files"), r"DAUM\PotPlayer\PotPlayer64.exe"),
                         os.path.join(os.environ.get('PROGRAMFILES(X86)', r"C:\Program Files (x86)"), r"DAUM\PotPlayer\PotPlayer.exe")]),
            ("VLC", [os.path.join(os.environ.get('PROGRAMFILES', r"C:\Program Files"), r"VideoLAN\VLC\vlc.exe"),
                    os.path.join(os.environ.get('PROGRAMFILES(X86)', r"C:\Program Files (x86)"), r"VideoLAN\VLC\vlc.exe")]),
            ("AIMP (Media)", [os.path.join(os.environ.get('PROGRAMFILES', r"C:\Program Files"), r"AIMP\AIMP.exe"),
                             os.path.join(os.environ.get('PROGRAMFILES(X86)', r"C:\Program Files (x86)"), r"AIMP\AIMP.exe")]),
            ("곰플레이어", [os.path.join(os.environ.get('PROGRAMFILES(X86)', r"C:\Program Files (x86)"), r"GOM\GOMPLAYER\GOM.exe")]),
            ("KMPlayer", [os.path.join(os.environ.get('PROGRAMFILES(X86)', r"C:\Program Files (x86)"), r"KMPlayer\KMPlayer.exe"),
                         os.path.expandvars(r"%LOCALAPPDATA%\KMP64\KMPlayer64.exe")]),
            ("네이버 웨일", [os.path.expandvars(r"%LOCALAPPDATA%\Naver\Naver Whale\Application\whale.exe")])
        ]

    found_names = {p['name'].lower() for p in found_list}
    _log_to_file(f"🔍 [Media Detect] Simple Search Start ({media_type})")

    for name, paths in targets:
        if name.lower() in found_names: continue
        for p in paths:
            try:
                if os.path.exists(p):
                    # [V14.9.4] 텔레그램 콜백 제한 방지를 위해 index 부여
                    next_idx = len(found_list)
                    found_list.append({"name": name, "path": p, "index": next_idx})
                    found_names.add(name.lower())
                    break # 하나라도 찾으면 다음 앱으로
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

    _log_to_file(f"🔍 [Media Detect] Result: {len(found_list)} apps found.")
    return found_list

# [TAG: #@_pc_get_visible_windows]
def _pc_get_visible_windows():
    """현재 실행 중인 모든 가시적 윈도우 목록을 가져옵니다. (Alt-Tab 스타일 필터링 및 데스크톱 스캔 적용)"""
    windows = []
    seen = set()

    try:
        import win32gui
        import win32process
    except ImportError:
        return windows

    try:
        import win32service
        import win32con
    except ImportError:
        win32service = None
        win32con = None

    GWL_EXSTYLE = -20
    WS_EX_TOOLWINDOW = 0x00000080
    WS_EX_APPWINDOW = 0x00040000
    DWMWA_CLOAKED = 14

    mapping = {
        "chrome.exe": "🌐", "msedge.exe": "🌐", "whale.exe": "🌐", "firefox.exe": "🦊", "brave.exe": "🦁",
        "notepad.exe": "📝", "notepad++.exe": "📝", "code.exe": "💻",
        "explorer.exe": "📂", "kakaotalk.exe": "💬", "telegram.exe": "✈️",
        "potplayer64.exe": "🎬", "vlc.exe": "🎬", "mpc-hc64.exe": "🎬", "gom.exe": "🎬",
        "music.exe": "🎵", "spotify.exe": "🎵", "aimp.exe": "🎵", "melon.exe": "🎵",
        "excel.exe": "📊", "winword.exe": "📄", "powerpnt.exe": "📽️",
        "taskmgr.exe": "⚙️", "settings.exe": "⚙️", "cmd.exe": "📟", "powershell.exe": "📟",
        "windowsterminal.exe": "💻", "discord.exe": "🎮", "steam.exe": "🎮", "antigravity.exe": "🚀"
    }

    def get_proc_and_emoji(hwnd):
        exe_name = ""
        try:
            _, pid = win32process.GetWindowThreadProcessId(hwnd)
            import psutil
            p = psutil.Process(pid)
            exe_name = p.name().lower()
        except Exception:
            try:
                pid = ctypes.c_ulong()
                ctypes.windll.user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
                h_proc = ctypes.windll.kernel32.OpenProcess(0x1000, False, pid)
                if h_proc:
                    try:
                        buff = ctypes.create_unicode_buffer(512)
                        size = ctypes.c_ulong(512)
                        if ctypes.windll.kernel32.QueryFullProcessImageNameW(h_proc, 0, buff, ctypes.byref(size)):
                            exe_name = os.path.basename(buff.value).lower()
                    finally:
                        ctypes.windll.kernel32.CloseHandle(h_proc)
            except Exception:
                pass
        emoji = mapping.get(exe_name, "🖼️")
        return exe_name, emoji

    def is_real_window(hwnd):
        if not win32gui.IsWindow(hwnd) or not win32gui.IsWindowVisible(hwnd):
            return False

        length = win32gui.GetWindowTextLength(hwnd)
        if length == 0:
            return False

        ex_style = win32gui.GetWindowLong(hwnd, GWL_EXSTYLE)
        if (ex_style & WS_EX_TOOLWINDOW) and not (ex_style & WS_EX_APPWINDOW):
            return False

        owner = ctypes.windll.user32.GetWindow(hwnd, 4) # GW_OWNER
        if owner:
            return False

        cloaked = ctypes.c_int(0)
        try:
            ctypes.windll.dwmapi.DwmGetWindowAttribute(hwnd, DWMWA_CLOAKED, ctypes.byref(cloaked), ctypes.sizeof(cloaked))
            if cloaked.value != 0:
                return False
        except Exception:
            pass

        try:
            rect = win32gui.GetWindowRect(hwnd)
            w = rect[2] - rect[0]
            h = rect[3] - rect[1]
            if w < 50 or h < 50:
                return False
        except Exception:
            pass

        return True

    def filter_and_add(hwnd):
        if hwnd in seen:
            return True
        seen.add(hwnd)

        if is_real_window(hwnd):
            title = win32gui.GetWindowText(hwnd).strip()
            blacklist = ["Program Manager", "Settings", "Microsoft Store", "Microsoft Text Input Application", "트레이", "장치관리자", "입력기"]
            if not any(k.lower() == title.lower() for k in blacklist):
                proc_name, icon_emoji = get_proc_and_emoji(hwnd)
                display_title = title[:46] + "..." if len(title) > 46 else title
                windows.append({
                    "hwnd": hwnd,
                    "title": display_title,
                    "full_title": title,
                    "icon": icon_emoji,
                    "proc": proc_name
                })
        return True

    desktops = []
    if win32service and win32con:
        try:
            desktops.append(win32service.OpenInputDesktop(0, False, win32con.DESKTOP_ENUMERATE))
        except Exception:
            pass
        try:
            desktops.append(win32service.OpenDesktop('Default', 0, False, win32con.DESKTOP_ENUMERATE))
        except Exception:
            pass

    for d in desktops:
        try:
            win32gui.EnumDesktopWindows(d, lambda h, extra: filter_and_add(h), None)
        except Exception:
            pass

    try:
        win32gui.EnumWindows(lambda h, extra: filter_and_add(h), None)
    except Exception:
        pass

    return windows

# [V13.8] 작업표시줄 고정 앱 목록 가져오기
# [TAG: #@_pc_get_pinned_apps]
def _pc_get_pinned_apps():
    apps = []
    try:
        path = os.path.join(os.environ['APPDATA'], r"Microsoft\Internet Explorer\Quick Launch\User Pinned\TaskBar")
        if os.path.exists(path):
            files = [f for f in os.listdir(path) if f.lower().endswith(".lnk") and not f.lower().startswith("tombstone")]
            # [스마트 정렬]
            # 1. 파일명 시작이 숫자인 경우(예: 01_웨일) 해당 숫자를 우선순위로 정렬
            # 2. 숫자가 없는 경우 파일명 이름순으로 정렬
            # [TAG: #@sort_key]
            def sort_key(filename):
                match = re.match(r'^(\d+)', filename)
                if match:
                    return (0, int(match.group(1)), filename.lower())
                return (1, 0, filename.lower())

            files.sort(key=sort_key)

            for i, f in enumerate(files[:10], 1): # 최대 10개까지
                name = os.path.splitext(f)[0]
                # ' (2)' 같은 중복 이름 제거 및 다듬기
                name = re.sub(r" \(\d+\)$", "", name).strip()
                apps.append({"index": i, "name": name, "path": os.path.join(path, f)})
    except Exception as e:
        _log_to_file(f"❌ [PinnedApps Error] {e}")
    return apps

# [TAG: #@_pc_activate_window]
def _pc_activate_window(hwnd):
    """특정 HWND를 가진 윈도우를 맨 앞으로 가져와 활성화합니다. (강력한 포커스 뺏기 비기 적용)"""
    try:
        if not ctypes.windll.user32.IsWindow(hwnd): return False

        # 0. 윈도우 포커스 제한(Lock)을 풀기 위한 Alt 키 트릭 🪄
        # 윈도우는 포그라운드 프로세스가 아닐 때 포커스를 뺏는 것을 막음.
        # 이를 우회하기 위해 가상으로 Alt 키를 한 번 눌러줌.
        VK_MENU = 0x12 # Alt
        KEYEVENTF_KEYUP = 0x0002
        ctypes.windll.user32.keybd_event(VK_MENU, 0, 0, 0)
        ctypes.windll.user32.keybd_event(VK_MENU, 0, KEYEVENTF_KEYUP, 0)

        # 1. 최소화되어 있다면 복구, 아니라면 그냥 보이기 보강
        if ctypes.windll.user32.IsIconic(hwnd):
            ctypes.windll.user32.ShowWindow(hwnd, 9) # SW_RESTORE
        else:
            ctypes.windll.user32.ShowWindow(hwnd, 5) # SW_SHOW

        # 2. 강력한 포커지 부여 (AttachThreadInput)
        try:
            foreground_thread = ctypes.windll.user32.GetWindowThreadProcessId(ctypes.windll.user32.GetForegroundWindow(), 0)
            target_thread = ctypes.windll.user32.GetWindowThreadProcessId(hwnd, 0)

            if foreground_thread != target_thread:
                ctypes.windll.user32.AttachThreadInput(foreground_thread, target_thread, True)
                ctypes.windll.user32.SetForegroundWindow(hwnd)
                ctypes.windll.user32.SetFocus(hwnd)
                ctypes.windll.user32.BringWindowToTop(hwnd)
                ctypes.windll.user32.AttachThreadInput(foreground_thread, target_thread, False)
            else:
                ctypes.windll.user32.SetForegroundWindow(hwnd)
                ctypes.windll.user32.BringWindowToTop(hwnd)
        except:
            # 실패 시 최후의 수단
            ctypes.windll.user32.SetForegroundWindow(hwnd)

        _log_to_file(f"🪟 [WinSwitch] HWND:{hwnd} 전환 시도 완료")
        return True
    except Exception as e:
        _log_to_file(f"❌ [WinSwitch Error] {e}")
        return False

# ── [V126.0] ☁️ Google Drive (rclone) Integration Helpers ──────────────────────────

# [TAG: #@_cleanup_orphaned_rclone_files]
def _cleanup_orphaned_rclone_files():
    """[V141.0] temp 폴더 내의 고아 rclone 임시 파일들을 정리합니다냥! (PID 체크 및 24시간 경과 기준) 🧹✨"""
    try:

        temp_dir = 'temp'
        if not os.path.exists(temp_dir): return

        # 패턴: rclone_ff_{pid}_{time}_{idx}.txt 또는 rclone_files_from_{pid}.txt
        # rclone_ff_([0-9]+)_.*\.txt  (첫번째 그룹이 PID)
        patterns = [
            re.compile(r'rclone_ff_(\d+)_.*\.txt'),
            re.compile(r'rclone_files_from_(\d+)\.txt'),
            re.compile(r'rclone_ff_(\d+)\.txt') # 구 버전 호환성
        ]

        # [V141.0] rclone_files_from.txt 처럼 PID가 없는 고정 파일도 정리 대상에 포함 (24시간 이상 된 경우)
        static_files = ['rclone_files_from.txt', 'rclone_files_from_all.txt', 'rclone_files_from_18224.txt']

        _log_to_file(" [Cleanup] Starting orphaned rclone temp file scan...")
        count = 0

        for filename in os.listdir(temp_dir):
            fpath = os.path.join(temp_dir, filename)
            pid_to_check = None

            # 1. 고정 파일 또는 특정 레거시 파일 체크 (수정된 지 24시간 넘었으면 삭제)
            if filename in static_files or filename.startswith('rclone_files_from_'):
                if time.time() - os.path.getmtime(fpath) > 86400:
                    try:
                        safe_remove_file(fpath, use_trash=False)
                        count += 1
                    except Exception as e:
                        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                        if "6" not in str(e):
                            _log_to_file(f"⚠️ [Silent Exception] {e}")
                continue

            # 2. PID 포함 파일 체크
            for p in patterns:
                m = p.match(filename)
                if m:
                    pid_to_check = int(m.group(1))
                    break

            if pid_to_check:
                # PID가 현재 본인이 아니면서, 시스템에 살아있는 프로세스가 아닐 경우 삭제
                if pid_to_check != os.getpid():
                    if not _is_pid_alive(pid_to_check):
                        try:
                            safe_remove_file(fpath, use_trash=False)
                            count += 1
                        except Exception as e:
                            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                            if "6" not in str(e):
                                _log_to_file(f"⚠️ [Silent Exception] {e}")

        if count > 0:
            _log_to_file(f" [Cleanup] Processed {count} orphaned rclone temp files (Safety-Checked). ✨")
    except Exception as e:
        _log_to_file(f" [Cleanup] Failed to clean orphaned rclone files: {e}")

# [TAG: #@_cleanup_raw_txt_files]
def _cleanup_raw_txt_files(silent=False):
    """[V17.3.38] temp/*.raw.txt 파일 중 24시간이 지난 파일들을 정리합니다냥! 🧹✨"""
    try:
        temp_dir = 'temp'
        if not os.path.exists(temp_dir): return
        
        now = time.time()
        count = 0
        for f in os.listdir(temp_dir):
            if f.endswith('.raw.txt'):
                fpath = os.path.join(temp_dir, f)
                try:
                    if now - os.path.getmtime(fpath) > 86400: # 24시간 (86400초)
                        os.remove(fpath)
                        count += 1
                except: pass
        
        if not silent and count > 0:
            print(f" 🧹 {C.SKY}24시간 지난 임시 말뭉치({count}개)를 청소했어냥!{C.RESET}")
        
        if count > 0:
            _log_to_file(f"🧼 [Cleanup] {count} raw.txt files removed (over 24h).")
            
    except Exception as e:
        _log_to_file(f"⚠️ [_cleanup_raw_txt_files] {e}")


# [TAG: #@_ensure_rclone]
def _ensure_rclone():
    """temp/rclone.exe 존재 확인 및 없으면 최신 버전 자동 다운로드 (V126.0) 🚀
    [V193.4] 🛡️ 경로를 절대경로(SRT_TEMP_DIR)로 고정한다.
      예전엔 os.path.join('temp', ...) 라 CWD 상대였는데, 앱이 C:\\srt 가 아닌
      디렉터리에서 실행되면 76MB exe 를 못 찾아 **매번 다운로드를 시도**했다. 🐾
    """
    _tdir = SRT_TEMP_DIR if 'SRT_TEMP_DIR' in globals() else os.path.join(BASE_DIR, 'temp')
    rclone_path = os.path.join(_tdir, 'rclone.exe')
    if os.path.exists(rclone_path): return rclone_path

    if not os.path.exists(_tdir): os.makedirs(_tdir, exist_ok=True)
    print(f"\r\n ☁️ {C.SKY}rclone이 없어 최신 버전을 다운로드합니다 (최초 1회)...{C.RESET}")

    try:
        import urllib.request
        import zipfile
        # rclone 공식 GitHub에서 windows-amd64 zip 다운로드
        url = "https://downloads.rclone.org/rclone-current-windows-amd64.zip"
        with urllib.request.urlopen(url) as response:
            with zipfile.ZipFile(io.BytesIO(response.read())) as z:
                # zip 내부의 rclone.exe 찾기 (폴더 안에 있음)
                exe_name = next((f for f in z.namelist() if f.endswith('rclone.exe')), None)
                if exe_name:
                    with open(rclone_path, 'wb') as f:
                        f.write(z.read(exe_name))
                    print(f" ✅ {C.GREEN}rclone.exe 설치 완료!{C.RESET}")
                    return rclone_path
    except Exception as e:
        print(f" ❌ {C.RED}rclone 다운로드 실패: {e}{C.RESET}")
    return None

# [TAG: #@_is_gdrive_path]
def _is_gdrive_path(path):
    """gdrive 가상 경로인지 확인 ☁️"""
    return isinstance(path, str) and path.startswith("gdrive://")

# [TAG: #@_is_gdrive_dir]
def _is_gdrive_dir(p):
    """구글 드라이브 가상 경로가 폴더인지 확인 (슬래시/루트/확장자 역추적 기준) 📏"""
    if not _is_gdrive_path(p): return False

    # 1. 명시적으로 슬래시로 끝나면 무조건 폴더냥! 🛰️
    if p.endswith("/"): return True

    # 2. 계정 루트 경로 (gdrive://account) 판정
    parts = p.replace("gdrive://", "").strip("/").split("/")
    if len(parts) == 1: return True

    # 3. [V131.8] 최종 병기: 확장자 역추적 판정 🕵️‍♂️🛡️
    # 영상, 음악, 자막 파일이 아니라면 탐색기에서는 폴더(이동 가능 항목)로 취급한다냥!
    _media_exts = (
        '.mp4', '.mkv', '.avi', '.mov', '.wmv', '.flv', '.m4v', '.webm', '.ts', '.m2ts', '.m3u8', '.dpl', # Video
        '.mp3', '.flac', '.wav', '.m4a', '.aac', '.ogg', '.wma', '.pls', '.m3u',                        # Audio
        '.srt', '.smi', '.vtt', '.ass', '.txt', '.log'                                                  # Subtitles/Support
    )
    _ext = os.path.splitext(p)[1].lower()
    if not _ext or _ext not in _media_exts:
        return True # 확장자가 없거나 미디어 파일이 아니면 폴더로 간주냥!

    return False

# [V141.32] AI냥 요청: TUI 다중 선택 파일 탐색기 열기 — 폴더가 여러 개면 먼저 확인! 📂💎✨
# [V142.55] 탐색기 창을 실행하고 0.6초 뒤에 강제로 포커스를 잡아 맨 위로 소환냥! 🎩✨
def _run_explorer_with_focus(args, shell=False):

    try:
        subprocess.Popen(args, shell=shell)

        # [TAG: #@_focus_task]

        def _focus_task():
            # 탐색기 창이 뜰 때까지 찰나의 순간 대기 (0.6초면 충분냥! 🕒)
            time.sleep(0.6)
            # CabinetWClass: 윈도우 탐색기의 클래스 이름냥! 🎯
            hwnd = ctypes.windll.user32.FindWindowW("CabinetWClass", None)
            if hwnd:
                # SW_SHOW(5) + 포커스 강제 지정! 🚀
                ctypes.windll.user32.ShowWindow(hwnd, 5)
                ctypes.windll.user32.SetForegroundWindow(hwnd)

        # 메인 루프 방해 안 되게 백그라운드(데몬) 스레드로 돌릴게냥! 🧵
        threading.Thread(target=_focus_task, daemon=True).start()
    except Exception as e:
        _log_to_file(f"⚠️ [_run_explorer_with_focus] Failed: {e}")

# [TAG: #@_open_folder_select_items_win32]
def _open_folder_select_items_win32(folder, item_paths):
    """Win32 SHOpenFolderAndSelectItems로 폴더 하나의 항목들을 선택해서 탐색기 열기.
    모든 exit 경로에서 PIDL 리소스가 반드시 해제됨냥! 🧹"""

    shell32 = ctypes.windll.shell32
    ole32 = ctypes.windll.ole32

    # [V141.38] COM 초기화 및 API 타입 정의 (안정성 끝판왕냥!)
    shell32.ILCreateFromPathW.argtypes = [ctypes.c_wchar_p]
    shell32.ILCreateFromPathW.restype = ctypes.c_void_p
    shell32.ILFindLastID.argtypes = [ctypes.c_void_p]
    shell32.ILFindLastID.restype = ctypes.c_void_p
    shell32.ILFree.argtypes = [ctypes.c_void_p]
    shell32.SHOpenFolderAndSelectItems.argtypes = [ctypes.c_void_p, ctypes.c_uint, ctypes.c_void_p, ctypes.c_ulong]
    shell32.SHOpenFolderAndSelectItems.restype = ctypes.c_long

    ole32.CoInitializeEx.argtypes = [ctypes.c_void_p, ctypes.c_ulong]
    ole32.CoInitializeEx.restype = ctypes.c_long

    # 0x2 = COINIT_APARTMENTTHREADED, 0x0 = COINIT_MULTITHREADED
    # 이미 초기화된 경우(0x80010106)도 대비냥!
    hr_init = ole32.CoInitializeEx(None, 2)
    need_uninit = (hr_init >= 0) # S_OK(0) 또는 S_FALSE(1) 일 때만 해제냥

    pidl_items_abs = []
    pidl_items_rel = []
    pidl_folder = None
    success = False
    try:
        folder_norm = os.path.normpath(folder)
        pidl_folder = shell32.ILCreateFromPathW(folder_norm)
        if not pidl_folder:
            _log_to_file(f" [Win32] Failed to create PIDL for folder: {folder}")
            # 폴백: 일반 폴더 열기 시도냥
            _run_explorer_with_focus(['explorer', folder_norm])
            return True # 창은 열었으므로 성공 간주냥!

        for p in item_paths:
            p_norm = os.path.normpath(p)
            p_abs = shell32.ILCreateFromPathW(p_norm)
            if p_abs:
                pidl_items_abs.append(p_abs)
                p_rel = shell32.ILFindLastID(p_abs)
                if p_rel:
                    pidl_items_rel.append(p_rel)

        if pidl_items_rel:
            _log_to_file(f" [Win32] Selecting {len(pidl_items_rel)} items in {folder}")
            PidlArray = ctypes.c_void_p * len(pidl_items_rel)
            pidl_array = PidlArray(*pidl_items_rel)
            hr = shell32.SHOpenFolderAndSelectItems(pidl_folder, len(pidl_items_rel), pidl_array, 0)
            if hr == 0:
                success = True
            else:
                _log_to_file(f" [Win32] SHOpenFolderAndSelectItems Error: {hex(hr & 0xFFFFFFFF)}")
                _run_explorer_with_focus(['explorer', folder_norm])
                success = True
        else:
            _log_to_file(" [Win32] No valid child PIDLs, just opening folder")
            _run_explorer_with_focus(['explorer', folder_norm])
            success = True
    except Exception as e:
        _log_to_file(f" [Win32] Internal Exception: {e}")
        _run_explorer_with_focus(['explorer', folder])
        success = True
    finally:
        # [V141.41] 모든 exit 경로에서 PIDL 리소스 완벽 해제! 🧹✨
        for p_item in pidl_items_abs:
            shell32.ILFree(p_item)
        if pidl_folder:
            shell32.ILFree(pidl_folder)
        if need_uninit:
            ole32.CoUninitialize()
    return success


# [TAG: #@open_explorer_select_multiple]
def open_explorer_select_multiple(paths, current_dir=None):
    """여러 파일/폴더를 탐색기에서 선택된 상태로 열어줘냥! 🚀
    반환값: 실제로 탐색기 창을 열었으면 True, 아니면 False (취소 등)
    """
    from collections import defaultdict

    if not paths:
        return False

    # [신규] 구글 드라이브 경로가 포함되어 있거나 current_dir이 구드 경로인 경우 브라우저 웹 열기로 스마트 전달! 🌐☁️✨
    if (current_dir and _is_gdrive_path(current_dir)) or (paths and any(_is_gdrive_path(p) for p in paths)):
        _tgt = paths[0] if (paths and len(paths) == 1 and _is_gdrive_path(paths[0])) else None
        return _open_gdrive_web(current_dir, target=_tgt)

    # 1. 절대경로 변환 + 실존하는 로컬 경로만 필터링 (구글 드라이브 경로는 탐색기 선택이 안 되므로 제외 🛡️)
    abs_paths = []
    for p in paths:
        if not p: continue
        
        # [V148.3] AI냥 요청: 지능형 경로 보정 도입! 🧠✨
        # 1) 입력된 경로 그대로 확인
        # 2) 만약 상대 경로라면 current_dir과 합쳐서 확인
        full_p = p
        if not os.path.isabs(p) and current_dir:
            full_p = os.path.join(current_dir, p)
            
        if os.path.exists(full_p) and not _is_gdrive_path(p):
            abs_paths.append(os.path.abspath(full_p))
        elif os.path.exists(p) and not _is_gdrive_path(p):
            abs_paths.append(os.path.abspath(p))

    if not abs_paths:
        # [V148.3] 하나도 못 찾았다면, 파일 대신 폴더라도 열 수 있는지 최후의 보루 시도! 📂🛡️
        if current_dir and os.path.exists(current_dir) and not _is_gdrive_path(current_dir):
             print(f"\r\n ⚠️  {C.YELLOW}파일을 찾지 못해 현재 폴더를 대신 열어줄게냥!{C.RESET}")
             _run_explorer_with_focus(['explorer', os.path.abspath(current_dir)])
             time.sleep(1.2)
             return True
             
        print(f"\r\n ⚠️  {C.YELLOW}탐색기에서 열 수 있는 로컬 파일이 없습니다냥.{C.RESET}")
        time.sleep(1.2)
        return False

    # 2. 폴더별로 그룹화
    folder_groups = defaultdict(list)
    for p in abs_paths:
        parent = os.path.dirname(p)
        folder_groups[parent].append(p)

    folders = list(folder_groups.keys())
    num_folders = len(folders)

    executed = False

    # 4. 모두 같은 폴더면 바로 처리
    if num_folders == 1:
        fld = folders[0]
        if len(abs_paths) == 1:
            try:
                _run_explorer_with_focus(f'explorer /select,"{abs_paths[0]}"', shell=True)
                executed = True
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

        if not executed:
            try:
                executed = _open_folder_select_items_win32(fld, folder_groups[fld])
            except Exception as e:
                _log_to_file(f" [open_explorer_select_multiple] Error: {e}")
                _run_explorer_with_focus(['explorer', fld])
                executed = True
        return executed

    # 5. 폴더가 여러 개 — 사용자에게 먼저 확인냥! 📢
    print(f"\r\n 📂 {C.BOLD}{C.SKY}선택된 파일이 {num_folders}개 폴더에 걸쳐 있어냥!{C.RESET}")
    for i, fld in enumerate(folders, 1):
        items = folder_groups[fld]
        names = ", ".join(os.path.basename(x) for x in items[:2])
        if len(items) > 2: names += f" 외 {len(items)-2}개"
        print(f"   {i}. 📁 {C.DIM}{fld}{C.RESET} ({names})")

    ans = prompt_input(f"\r\n 👉 {C.YELLOW}탐색기 창 {num_folders}개를 각각 열까냥? (Y/n): {C.RESET}")

    if ans is None or ans.strip().lower() in ('', 'y', 'yes', 'ㅛ'):
        for fld in folders:
            try:
                _open_folder_select_items_win32(fld, folder_groups[fld])
                executed = True
                time.sleep(0.3)
            except Exception as e:
                _log_to_file(f" [open_explorer_select_multiple] Folder '{fld}' Error: {e}")
        return executed

    return False


# [TAG: #@_open_gdrive_web]
def _open_gdrive_web(current_dir, target=None):
    """구글 드라이브 현재 폴더 또는 선택 항목을 웹 브라우저로 엽니다냥! 🌐☁️"""
    import webbrowser
    path_to_open = target if (target and _is_gdrive_path(target)) else current_dir
    if not path_to_open or not _is_gdrive_path(path_to_open):
        return False

    acct, rpath = _gdrive_parse_path(path_to_open)
    target_url = "https://drive.google.com/drive/my-drive"
    rpath_clean = (rpath or "").strip("/").strip("\\")

    if rpath_clean:
        folder_id = None
        file_id = None
        parent_rpath = os.path.dirname(rpath_clean).replace("\\", "/").strip("/")
        curr_name = os.path.basename(rpath_clean)

        # 1차: 메모리/디스크 캐시에서 부모 폴더 목록 조회
        cache_key = (acct, parent_rpath)
        if '_GDRIVE_CACHE' in globals() and cache_key in _GDRIVE_CACHE:
            p_dirs, p_files = _GDRIVE_CACHE[cache_key]
            for d in p_dirs:
                if d.get('Name') == curr_name or d.get('Path') == rpath_clean or d.get('Path') == curr_name:
                    folder_id = d.get('ID')
                    break
            if not folder_id and p_files:
                for f in p_files:
                    if f.get('Name') == curr_name or f.get('Path') == rpath_clean or f.get('Path') == curr_name:
                        file_id = f.get('ID')
                        break

        # 2차: 캐시에 없으면 _gdrive_manager로 부모 폴더 목록 조회
        if not folder_id and not file_id:
            try:
                _g_mgr = globals().get('_gdrive_manager')
                if _g_mgr:
                    p_dirs, p_files = _g_mgr('list', account=acct, rpath=parent_rpath)
                    for d in p_dirs:
                        if d.get('Name') == curr_name or d.get('Path') == rpath_clean or d.get('Path') == curr_name:
                            folder_id = d.get('ID')
                            break
                    if not folder_id and p_files:
                        for f in p_files:
                            if f.get('Name') == curr_name or f.get('Path') == rpath_clean or f.get('Path') == curr_name:
                                file_id = f.get('ID')
                                break
            except Exception as _e:
                _log_to_file(f" [GD:Web] Failed to fetch ID: {_e}")

        if folder_id:
            target_url = f"https://drive.google.com/drive/folders/{folder_id}"
        elif file_id:
            target_url = f"https://drive.google.com/file/d/{file_id}/view"

    try:
        webbrowser.open(target_url)
        _disp_target = f"{acct}:/{rpath_clean}" if rpath_clean else f"{acct}:/ (루트)"
        globals()['_last_bg_notification'] = f"🌐 구글 드라이브 웹을 열었어냥! ({_disp_target})"
        globals()['_last_bg_notification_time'] = time.time()
        print(f"\r\n 🌐 {C.GREEN}구글 드라이브 웹 페이지를 브라우저로 열었어냥!{C.RESET}")
        print(f"    ㄴ 대상: {C.SKY}{_disp_target}{C.RESET}")
        print(f"    ㄴ 주소: {C.DIM}{target_url}{C.RESET}")
        time.sleep(1.0)
        return True
    except Exception as e:
        print(f"\r\n ⚠️ {C.RED}웹 브라우저 열기 실패:{C.RESET} {e}")
        time.sleep(1.5)
        return False

# [V131.5] AI냥 요청: 번호로 선택하는 순차적 구글 드라이브 폴더 선택 시스템 🚀🧭🔢
# [TAG: #@_update_recent_gdrive_dest]
def _update_recent_gdrive_dest(settings_obj, new_dest):
    """[V21.3] 최근 사용한 구글 드라이브 목적지 리스트를 업데이트합니다냥! (최대 5개) 🚀✨"""
    if not new_dest: return
    try:
        # 1. 기존 리스트 가져오기
        recent_list = settings_obj.data.get('recent_gdrive_dests', [])
        if not isinstance(recent_list, list):
            if isinstance(recent_list, str): recent_list = [recent_list]
            else: recent_list = []
            
        # 2. 중복 제거 (이미 있으면 해당 항목을 앞으로)
        if new_dest in recent_list:
            recent_list.remove(new_dest)
        
        recent_list.insert(0, new_dest)
        
        # 3. 최대 5개 유지 및 저장
        settings_obj.data['recent_gdrive_dests'] = recent_list[:5]
        settings_obj.data['last_gdrive_copy_dest'] = new_dest # 레거시 지원용
        settings_obj.save()
    except Exception as e:
        _log_to_file(f" ❌ [_update_recent_gdrive_dest] Error: {e}")


# [V131.5] AI냥 요청: 번호로 선택하는 순차적 구글 드라이브 폴더 선택 시스템 🚀🧭🔢
# [V131.5] AI냥 요청: 번호로 선택하는 순차적 구글 드라이브 폴더 선택 시스템 🚀🧭🔢
# [V131.5] AI냥 요청: 번호로 선택하는 순차적 구글 드라이브 폴더 선택 시스템 🚀🧭🔢
# [TAG: #@_gdrive_select_dest_interactive_menu]
def _gdrive_select_dest_interactive_menu(settings_obj):
    """메뉴 방식으로 구글 드라이브 업로드 목적지를 선택합니다냥! (숫자 키 1:1 완벽 매칭)"""
    accts = _gdrive_accounts(settings_obj)
    if not accts:
        print(f"\r\n ⚠️ {C.YELLOW}등록된 구글 드라이브 계정이 없습니다냥! 설정에서 먼저 추가해줘냥!{C.RESET}")
        time.sleep(2); return None

    recent_dests = settings_obj.data.get('recent_gdrive_dests', [])
    if not recent_dests and settings_obj.data.get('last_gdrive_copy_dest'):
        recent_dests = [settings_obj.data['last_gdrive_copy_dest']]
    elif isinstance(recent_dests, str):
        recent_dests = [recent_dests]

    _gdrive_bg_mode = settings_obj.data.get('gdrive_upload_bg_mode', False) if settings_obj else False
    _gdrive_focus_idx = 0

    def _save_gdrive_config():
        if settings_obj:
            settings_obj.data['gdrive_upload_bg_mode'] = _gdrive_bg_mode
            try: settings_obj.save()
            except: pass

    while True:
        _acct_opts = []
        _recent_valid = []
        
        # 1. 최근 위치 목록 추가 (번호 1 ~ recent_count)
        for idx, rd in enumerate(recent_dests[:5]):
            shortcut_hint = "(u)" if idx == 0 else ""
            _acct_opts.append(f"{C.GOLD}⚡ [최근 {idx+1}] {rd} {shortcut_hint}{C.RESET}")
            _recent_valid.append(rd)
        
        recent_count = len(_recent_valid)

        # 2. 구글 계정 목록 추가
        acct_start_idx = len(_acct_opts)
        _acct_opts += [f"☁️ {a['name']} ({a.get('email', 'N/A')})" for a in accts]

        # 3. [실행 방식] 토글바 배치 (숫자 키 1:1 매칭)
        toggle_bg_idx = len(_acct_opts)
        bg_disp = f"{C.YELLOW}⚡ 백그라운드 (비동기){C.R}" if _gdrive_bg_mode else f"{C.GREEN}🚀 포그라운드 (즉시){C.R}"
        _acct_opts.append(f"⚙️ {C.BOLD}[실행 방식]{C.R} {bg_disp}")

        # 4. ❌ 취소 버튼
        cancel_idx = len(_acct_opts)
        _acct_opts.append(f"{C.RED}❌ 취소 (탐색기로){C.RESET}")

        _a_res = _interactive_menu("☁️ 업로드할 구글 계정 선택 (숫자로 입력냥!)", _acct_opts, default_idx=_gdrive_focus_idx)
        _a_idx, _a_act = _a_res[0:2] if isinstance(_a_res, tuple) else (_a_res, None)

        if _a_idx >= 0:
            _gdrive_focus_idx = _a_idx

        # [u] 키 단축키 처리 (가장 최근 목적지)
        if _a_act == "U_KEY" and recent_count > 0:
            rd = _recent_valid[0]
            _la, _lp = rd.split(":", 1)
            return f"gdrive://{_la}/{_lp}/"

        # 취소 처리
        if _a_idx is None or _a_idx == cancel_idx or _a_act == "ESC":
            return None

        # 실행 방식 토글 처리 (숫자 키 1:1 정확 작동!)
        if _a_idx == toggle_bg_idx:
            _gdrive_bg_mode = not _gdrive_bg_mode
            _gdrive_focus_idx = toggle_bg_idx
            _save_gdrive_config()
            clear_console(); continue

        # 최근 위치 직접 선택
        if 0 <= _a_idx < recent_count:
            rd = _recent_valid[_a_idx]
            _la, _lp = rd.split(":", 1)
            return f"gdrive://{_la}/{_lp}/"

        # 일반 계정 선택
        if acct_start_idx <= _a_idx < acct_start_idx + len(accts):
            _acc_idx = _a_idx - acct_start_idx
            _target_account = accts[_acc_idx]['name']
        else:
            return None

        _current_rpath = ""

        # 폴더 탐색 루프
        while True:
            try:
                _g_dirs, _ = _gdrive_list(_target_account, _current_rpath)
                _pure_dirs = [d for d in _g_dirs if d.get('Name') and ".." not in d['Name']]

                _m_title = f"📂 경로: {_target_account}:/{_current_rpath}"
                _m_opts = [f"🏁 {G}[ 이 폴더로 업로드 결정 ]{R}"]

                _fld_names = []
                for _d in _pure_dirs:
                    _nm = _d.get('Name') or _d.get('Path', '').rstrip('/').split('/')[-1]
                    _fld_names.append(_nm)
                    _m_opts.append(f"📁 {_nm}")

                _m_opts += [" ", f"{Y}🔙 상위 폴더로{R}", f"{R}❌ 선택 취소{R}"]

                _f_res = _interactive_menu(_m_title, _m_opts, allow_further=True)
                _f_sel = _f_res[0] if isinstance(_f_res, tuple) else _f_res

                if _f_sel is None: return None

                if _f_sel == 0: # 결정!
                    return f"gdrive://{_target_account}/{_current_rpath.strip('/')}/"

                elif 1 <= _f_sel <= len(_fld_names):
                    _clicked = _fld_names[_f_sel - 1]
                    _current_rpath = f"{_current_rpath.strip('/')}/{_clicked}".strip('/')
                elif _f_sel == len(_fld_names) + 1: # 구분선
                    continue
                elif _f_sel == len(_fld_names) + 2: # 상위 폴더
                    if _current_rpath:
                        _parts = _current_rpath.strip('/').split('/')
                        _current_rpath = '/'.join(_parts[:-1])
                    else:
                        break # 계정 선택으로
                elif _f_sel == len(_m_opts) - 1: # 취소
                    return None
            except Exception as e:
                print(f" ⚠️ {C.RED}구글 드라이브 탐색 오류:{C.RESET} {e}")
                time.sleep(1.5); break

# [TAG: #@_is_gdrive_file]
def _is_gdrive_file(p):
    """구글 드라이브 가상 경로가 파일인지 확인 📜"""
    return _is_gdrive_path(p) and not p.endswith("/")

# [TAG: #@_gdrive_parse_path]
def _gdrive_parse_path(path):
    """gdrive://account_name/remotepath -> (account, remote_path) 분리 및 정규화 🧴☁️"""
    if not _is_gdrive_path(path): return None, None
    # [GD:Circuit] 📂 가상 경로 해석 시작냥!
    _log_to_file(f" [GD:Circuit] 📂 Parsing virtual path: {path}")

    # [V128.5] AI냥 요청: 공백 및 슬래시 처리 강화 (튕김 방지)
    parts = path.replace("gdrive://", "").split("/", 1)
    account = parts[0].strip()
    rpath = parts[1].strip("/") if len(parts) > 1 else ""

    # [GD:Circuit] ⚡ 해석 완료: {account} 계정의 '{rpath}' 경로로 회로 구성!
    _log_to_file(f" [GD:Circuit] ⚡ Split result: Account={account}, RPath={rpath}")
    return account, rpath


