_telegram_file_registry = {}       # {short_id: file_path} 매핑
_telegram_file_registry_counter = 0
_telegram_polling_thread_ref = None
_telegram_polling_active = False

# [TAG: #@_register_file_for_telegram]
def _register_file_for_telegram(file_path: str) -> str:
    """파일 경로를 짧은 ID로 등록하고 반환합니다 (callback_data 64바이트 제한 대응)."""
    global _telegram_file_registry_counter
    _telegram_file_registry_counter += 1
    short_id = f"w{_telegram_file_registry_counter}"
    _telegram_file_registry[short_id] = file_path
    return short_id

# [TAG: #@_path_to_url_path]
def _path_to_url_path(local_path):
    """로컬 파일 경로를 URL 경로(F/path...)로 변환합니다."""
    import urllib.parse
    path = local_path.replace('\\', '/')
    if ':' in path:
        drive, rest = path.split(':', 1)
        if not rest.startswith('/'):
            rest = '/' + rest
        path = f"{drive}{rest}"
    if path.startswith('/'):
        path = path[1:]
    return urllib.parse.quote(path)


# [TAG: #@_auth_query_for_host]
def _auth_query_for_host(host, key, scope='full', ttl=0) -> str:
    """'사용자에게 배포/안내할 주소' 에 붙일 인증 쿼리스트링을 만든다 🌐🔐 (V236.2)

    · 내부망(사설/루프백/Tailscale) → ``?k=<비밀번호>``  (기존 동작 그대로 — LAN 안이라 6자리 노출 허용)
    · 외부망(공인 IP / 터널·DDNS 도메인) → ``?t=<서명토큰>``  (평문 비번이 URL·기록·로그에 안 남는다)
    · 외부망인데 토큰 발급이 실패하면 ``?k=`` 로 폴백한다 (링크가 아예 죽는 것보다 낫다) 🛡️
    """
    if not key:
        return ''
    try:
        import urllib.parse as _up
        h = str(host or '').strip()
        if '://' in h:
            h = (_up.urlparse(h).hostname or '')
        h = h.split(':')[0].strip()
        if not h or _is_internal_client_ip(h):
            return f"?k={_up.quote(str(key))}"
    except Exception:
        return f"?k={key}"
    tq = _url_auth_query(scope, ttl)
    if tq:
        return tq
    # 🟡 [V236.3] 외부망인데 토큰 발급이 실패했다 → ?k= 로 폴백하면 '외부망에서 401' 인 죽은 링크가 된다.
    #    조용히 죽지 않게 반드시 로그를 남겨 원인을 추적 가능하게 한다.
    _log_to_file(f"⚠️ [URLToken] 외부망 주소({host})용 토큰 발급 실패 → ?k= 로 폴백합니다. 이 링크는 외부에서 401 이 됩니다!")
    return f"?k={key}"


# [TAG: #@_page_server_key]
def _page_server_key(key, client_ip=None) -> str:
    """웹 페이지(HTML) JS 에 주입할 '서버키 문자열' 을 만든다 🔐 (V236.3)

    🎯 왜 이게 필요한가
      · 예전엔 내부/외부 구분 없이 **평문 비밀번호** 를 페이지 소스에 그대로 박아넣었다.
        → 외부망 사용자가 `?t=` 링크(평문 비번 없음)로 들어와도, 렌더된 HTML/JS 안에
          평문 비밀번호가 있어 '외부망에 평문 비번 노출' 이라는 목표가、形만 맞고实质은 실패한다. ☠️
      · 그래서 외부 클라이언트에는 평문 대신 **서명 토큰** 을 주입한다.
        → 페이지 내부의 모든 fetch/video URL 이 '토큰(= ?k= 칸에 서명토큰)' 으로 나가며,
          평문 비밀번호는 서버 밖으로 단 1바이트도 나가지 않는다. 🛡️

    · 내부망 → 평문 비밀번호 (기존 동작 완전 유지, LAN 이라 노출 위험 낮음)
    · 외부망 → 서명 토큰 (없으면 빈 문자열 = 아무것도 주입하지 않음)"""
    if not key:
        return ''
    try:
        if _is_internal_http_request(client_ip=client_ip):
            return str(key)
        tok = make_url_token(_settings_for_token(), scope='full', ttl=0)
        return tok or ''
    except Exception as e:
        _log_to_file(f"⚠️ [URLToken] 페이지 키 결정 실패(외부망→빈값): {e}")
        return ''


# [TAG: #@_build_watch_url]
def _build_watch_url(file_path: str) -> str:
    """파일 경로로부터 미디어 서버 스트리밍 URL을 생성합니다."""
    global _flask_server_display_url, _flask_server_port, _flask_server_running, _flask_server_key

    # 서버가 실행 중이면 설정된 외부 주소/포트를 사용, 아니면 로컬 IP 사용
    ip = _flask_server_display_url if (_flask_server_running and _flask_server_display_url) else _get_local_ip()
    port = _flask_server_port if _flask_server_running else 5000

    # 🌐 [V236.2] 내부망은 ?k= , 외부망(터널/공인IP)은 ?t= 서명토큰으로 배포한다
    key_param = _auth_query_for_host(ip, _flask_server_key)
    # --- 기존 [N] 번호 기반 파싱 로직 (Fallback) ---
    def parse_translations(text):
        clean_text = re.sub(r'\[\d+/\d+\]', '', text)
        clean_text = re.sub(r'\d*\(?bot-[a-f0-9\-]+\)?\w*', '', clean_text).strip()
        return clean_text
    url_path = _path_to_url_path(file_path)

    # [V5.5] ?watch= 대신 /video/ 경로 기반으로 변경 (일관성 유지)
    return f"http://{ip}:{port}/video/{url_path}{key_param}"

# [TAG: #@_build_webdav_folder_url]
def _build_webdav_folder_url(folder_name="temp", include_auth=True):
    """WebDAV 특정 폴더로 바로 열 수 있는 URL을 생성합니다 (ID/PW 인증 선택적 포함)."""
    global _flask_server_display_url, _flask_server_key, _flask_server_id, _flask_server_running
    ip = _flask_server_display_url if (_flask_server_running and _flask_server_display_url) else _get_local_ip()
    port = WEBDAV_PORT

    # [V6.1] 텔레그램 버튼 등에서는 인증 정보 포함 시 URL 오류(Bad Request)가 날 수 있음
    if include_auth and _flask_server_id and _flask_server_key:
        auth = f"{quote(_flask_server_id)}:{quote(_flask_server_key)}@"
    else:
        auth = ""

    return f"http://{auth}{ip}:{port}/{quote(folder_name)}/"

# [TAG: #@_auto_start_media_server_for_telegram]
def _auto_start_media_server_for_telegram(settings, file_path: str = None):
    """텔레그램 Watch 버튼용 미디어 서버 자동 시작.
    [V89.10] file_path가 지정된 경우 temp 폴더 플레이리스트만 서비스합니다 (전체 목록 제외).
    """
    global _flask_server_running
    try:
        # [V89.10] 파일이 지정된 경우 → playlists/에 임시 m3u8 생성 (서버가 돌고 있더라도 갱신 필요)
        if file_path and os.path.exists(file_path):
            script_dir = os.path.dirname(os.path.abspath(__file__))
            playlists_dir = os.path.join(script_dir, "playlists")
            os.makedirs(playlists_dir, exist_ok=True)
            # playlists/ 폴더에 streaming_only.m3u8 생성
            m3u_path = os.path.join(playlists_dir, "streaming_only.m3u8")
            with open(m3u_path, "w", encoding="utf-8") as _mf:
                _mf.write("#EXTM3U\r\n")
                _mf.write(os.path.abspath(file_path) + "\r\n")
            print(f"  📡 [V89.11] 스트리밍 전용 플레이리스트 갱신 완료: {os.path.basename(file_path)}")

        # 이미 서버가 실행 중이면 추가 기동 없이 즉시 리턴 (새로 생성된 m3u8은 다음 목록 갱신 시 자동 노출됨)
        if _flask_server_running:
            return True

        if file_path and os.path.exists(file_path):
            # streaming_only 플레이리스트만 서비스 (서버가 꺼져있을 때 새로 시작)
            media_server_start(playlist_name="streaming_only")
        else:
            # 파일이 없거나 지정 안 된 경우 기존 방식(전체)
            media_server_start(playlist_name="__ALL__")

        time.sleep(1.0)
        return True
    except Exception as e:
        print(f"  ❌ 서버 자동 시작 중 오류 발생: {e}")
        return False

# [TAG: #@_build_server_ready_info]
def _build_server_ready_info(playlist_name=None):
    """서버 준비 알림을 위한 메시지와 버튼 리스트를 생성합니다 (v16.1.3)."""
    global _flask_server_display_url, _flask_server_port, _flask_server_key, _flask_server_serving_label

    ip = _flask_server_display_url if _flask_server_display_url else _get_local_ip()
    port = _flask_server_port
    key = _flask_server_key if _flask_server_key else ""

    # 레이블 처리 (전체 리스트 대응)
    if playlist_name == "__ALL__":
        label = "전체 리스트"
    elif playlist_name:
        label = playlist_name
    else:
        label = _flask_server_serving_label if _flask_server_serving_label else "메인 서버"

    # 1. 메시지 구성
    from urllib.parse import quote
    # 🌐 [V236.2] 내부망 ?k= / 외부망 ?t= 서명토큰
    k_suffix = _auth_query_for_host(ip, key)
    access_url = f"http://{ip}:{port}/media{k_suffix}"

    msg = f"{html.escape(_get_display_name(USER_NAME))}, 서버가 준비되었어! 👍\r\n"
    msg += f"📋 <b>플레이리스트:</b> <code>{html.escape(label)}</code>\r\n"
    msg += f"🔗 <b>웹 스트리밍:</b> {html.escape(access_url)}\r\n"

    if key:
        msg += f"📂 <b>WebDAV:</b> <code>http://webdav:{html.escape(key)}@{ip}:{WEBDAV_PORT}/</code>\r\n"
        msg += f"📁 <b>FTP:</b> <code>ftp://ftp:{html.escape(key)}@{ip}:{FTP_PORT}/</code>\r\n"
        msg += f"👤 <b>ID:</b> <code>webdav or ftp</code> / 🔑 <b>PW:</b> <code>{html.escape(key)}</code>\r\n"
    else:
        msg += f"📂 <b>WebDAV:</b> <code>http://{ip}:{WEBDAV_PORT}/</code> (익명)\r\n"
        msg += f"📁 <b>FTP:</b> <code>ftp://{ip}:{FTP_PORT}/</code> (익명)\r\n"

    # 2. 버튼 구성 및 nPlayer 주소 (m3u8 직접 주소 섹션 포함)
    p_name = playlist_name if playlist_name else (_flask_server_serving_label if _flask_server_serving_label else "__ALL__")
    m3u_filename = quote(p_name) + ('' if p_name.lower().endswith('.m3u8') else '.m3u8')
    # 🌐 [V236.2] 외부망이면 '?t=' 토큰 방식 → userinfo 에 평문 비번을 또 넣지 않는다 (이중 노출 방지)
    _pw_userinfo = f"webdav:{key}@" if (key and k_suffix.startswith('?k=')) else ""
    m3u_url_with_auth = f"http://{_pw_userinfo}{ip}:{port}/download/{m3u_filename}{k_suffix}" if key else f"http://{ip}:{port}/download/{m3u_filename}"

    msg += "\r\n📱 <b>nPlayer/MX m3u 주소:</b>\r\n"
    msg += f"<code>{html.escape(m3u_url_with_auth)}</code>\r\n"
    msg += "→ nPlayer 앱 실행 후 네트워크 스트림에 위 주소 붙여넣기!\r\n"

    import base64
    b64_list = base64.b64encode(p_name.encode('utf-8')).decode('utf-8')

    # 팟플레이어 리다이렉터 (이미 list= 가 붙어 있으므로 인증 파라미터는 '&' 로 이어붙인다)
    _auth_amp = ('&' + k_suffix[1:]) if k_suffix else ''
    pot_url = f"http://{ip}:{port}/open/potplaylist?list={b64_list}{_auth_amp}"

    # nPlayer/MX 리다이렉터
    m3u_url_clean = f"http://{ip}:{port}/download/{quote(p_name)}{('' if p_name.lower().endswith('.m3u8') else '.m3u8')}{k_suffix}"
    nplayer_direct_wrapped = f"http://{ip}:{port}/open/nplayer?url={quote(m3u_url_clean)}"

    # [V6.7] 재생기 선택 (Android Intent)
    any_video_redirect = f"http://{ip}:{port}/open/video?url={quote(m3u_url_clean)}&title={quote(p_name)}"

    # WebDAV 폴더 URL (인증 정보 제외 - BUTTON_URL_INVALID 방지)
    webdav_url = f"http://{ip}:{WEBDAV_PORT}/"

    # 버튼 레이아웃 (사용자 요청: 2줄 구성)
    url_buttons = [
        [
            {"text": "🌐 웹스트리밍", "url": access_url},
            {"text": "📂 webdav", "url": webdav_url}
        ],
        [
            {"text": "🖥️ 팟플레이어", "url": pot_url},
            {"text": "📱 nPlayer", "url": nplayer_direct_wrapped},
            {"text": "🎬 재생기선택", "url": any_video_redirect}
        ],
        [
            {"text": "🔴 미디어 서버 끄기", "callback_data": "srv_stop"},
            {"text": "❌ 닫기", "callback_data": "pl_close"}
        ]
    ]
    return msg, url_buttons


# [TAG: #@_pc_media_menu_logic]
def _pc_media_menu_logic(token, msg_chat_id):
    """[V17.5.8] 미디어 서버 통합 제어 메뉴를 전송합니다."""
    global _flask_server_running, _flask_server_display_url, _flask_server_port, _last_played_video_name, _flask_server_key, settings_ref, USER_NAME, standard_kb
    try:
        _media_active = bool(globals().get("_G_MEDIA_SERVING_ACTIVE", False) and _flask_server_running)
        _dash_active = bool(globals().get("_G_DASHBOARD_ACTIVE", False) and _flask_server_running)
        if _flask_server_running and not _media_active and not _dash_active:
            _media_active = True

        status_emoji = "🟢 실행 중" if _media_active else "🔴 중지됨"
        dash_status_emoji = "🟢 실행 중" if _dash_active else "🔴 중지됨"

        port = _flask_server_port if _flask_server_running else settings_ref.data.get('server_port', 5000)
        ip_display = (_flask_server_display_url if _flask_server_display_url else _get_local_ip()) if _flask_server_running else _get_local_ip()

        s_mode = settings_ref.data.get('telegram_default_server_mode', 1)
        mode_map = {1: "🔓 공개 (내부망)", 2: "🔐 보안 (내부망+키)", 3: "🌐 Ngrok (외부망+키)", 4: "📡 UPnP (외부망+키)", 5: "🔗 수동 (외부망+키)", 6: "🧪 수동 (외부망)"}
        mode_str = mode_map.get(s_mode, "알 수 없음")

        # [V18.8] last_server_state가 None일 경우 대비 (AttributeError 방지) 🛡️
        last_state = settings_ref.data.get('last_server_state') or {}
        if not isinstance(last_state, dict): last_state = {}
        
        sel_pl = last_state.get('selected_playlists')
        
        # [V18.8] 특수문자 HTML 파싱 에러 방지를 위해 escape 처리 필수냥! 🛡️✨
        if sel_pl and isinstance(sel_pl, list):
            pl_str = html.escape(", ".join(str(x) for x in sel_pl))
        else:
            pl_str = html.escape(str(sel_pl)) if sel_pl else "전체 리스트"
            
        playing_str = html.escape(str(_last_played_video_name)) if _last_played_video_name else "없음"

        # [V163.0] 미디어 서버 URL에 /media 경로 명시 (구주소 누락 수정 🎬✨)
        url_str = f"http://{ip_display}:{port}/media"
        if s_mode in [2, 3, 4, 5] and _flask_server_key: url_str += _auth_query_for_host(ip_display, _flask_server_key)

        dash_url_str = f"http://{ip_display}:{port}/dashboard"
        if s_mode in [2, 3, 4, 5] and _flask_server_key: dash_url_str += _auth_query_for_host(ip_display, _flask_server_key)

        esc_ip = html.escape(str(ip_display))
        reply = (
            f"🌐 <b>미디어 서버 실시간 정보</b>\r\n\r\n"
            f"• 🎬 미디어 스트리밍: <b>{status_emoji}</b>\r\n"
            f"• 🎛️ 웹 대시보드: <b>{dash_status_emoji}</b>\r\n"
            f"• 📂 선택된 리스트: <b>{pl_str}</b>\r\n"
            f"• 🎬 현재 재생 중: <b>{playing_str}</b>\r\n"
            f"• 접속 모드: <b>{mode_str}</b>\r\n"
            f"• 주소: <code>{esc_ip}</code>\r\n"
            f"• 📱 웹 미디어: <a href=\"{html.escape(url_str)}\">{html.escape(url_str)}</a>"
        )
        if _dash_active:
            reply += f"\r\n• 🌐 웹 대시보드: <a href=\"{html.escape(dash_url_str)}\">{html.escape(dash_url_str)}</a>"
        reply += "\r\n\r\n원하는 기능을 선택해줘! 😊"

        media_btn_text = "🛑 미디어 서버 종료" if _media_active else "▶️ 미디어 서버 시작"
        media_btn_cb = "srv_stop_action" if _media_active else "srv_start_menu"

        dash_btn_text = "🛑 웹 대시보드 종료" if _dash_active else "🎛️ 웹 대시보드 시작"

        _any_active = _media_active or _dash_active
        both_btn_text = "⚡ 둘 다 끄기 (일괄 종료)" if _any_active else "⚡ 둘 다 켜기 (동시 가동)"

        buttons = [
            [{"text": both_btn_text, "callback_data": "srv_both_toggle_action"}],
            [{"text": media_btn_text, "callback_data": media_btn_cb}, {"text": dash_btn_text, "callback_data": "dash_toggle_action"}],
            [{"text": "📡 접속 모드 변경", "callback_data": "srv_mode_menu"}, {"text": "🔄 플레이리스트 갱신", "callback_data": "pl_refresh_action"}]
        ]
        TelegramBot.send_message(token, msg_chat_id, reply, {"inline_keyboard": buttons})
    except Exception as e:
        import traceback
        _log_to_file(f"❌ [Media Menu Error] {e}\r\n{traceback.format_exc()}")
        TelegramBot.send_message(token, msg_chat_id, "⚠️ 미디어 서버 정보를 불러오는 중 오류가 발생했어.", reply_markup=standard_kb)

