                        remote_content = res.content
                        local_file = os.path.abspath(__file__)
                        with open(local_file, "rb") as f:
                            local_content = f.read()

                        # [TAG: #@_h_3]
                        def _h(data): return hashlib.md5(data.replace(b'\r\n', b'\r\n')).hexdigest()

