# [TAG: #@_ensure_ffmpeg]

def verify_ffmpeg_diagnostics_silent():
    """FFmpeg와 FFprobe가 실제로 실행 가능한지 조용히 확인합니다. 🤫"""
    ff = _get_ffmpeg_bin()
    fp = _get_ffprobe_bin()
    flags = 0x08000000 if os.name == 'nt' else 0
    try:
        if subprocess.run([ff, "-version"], capture_output=True, creationflags=flags, timeout=3).returncode != 0: return False, False
        if subprocess.run([fp, "-version"], capture_output=True, creationflags=flags, timeout=3).returncode != 0: return False, False
        return True, True
    except: return False, False

# [TAG: #@_ensure_ffmpeg]
def _ensure_ffmpeg():
    """FFmpeg와 FFprobe가 없으면 조용히(하지만 진행사항은 알리며) 다운로드합니다."""
    script_dir = os.path.dirname(os.path.abspath(sys.argv[0]))
    temp_dir = os.path.join(script_dir, "temp")
    if not os.path.exists(temp_dir): os.makedirs(temp_dir, exist_ok=True)

    ffmpeg_exe = os.path.join(temp_dir, "ffmpeg.exe")
    ffprobe_exe = os.path.join(temp_dir, "ffprobe.exe")

    # [V152.5] 단순히 파일 존재만 확인하는 게 아니라 실제로 실행되는지 전수 조사합니다냥! 🕵️‍♂️🛡️
    _f_ok, _p_ok = verify_ffmpeg_diagnostics_silent()
    if _f_ok and _p_ok:
        return

    # 만약 로컬(temp)에 파일은 있는데 실행이 안 되는 거라면 지우고 새로 받아요! 🐣🗑️
    try:
        if os.path.exists(ffmpeg_exe): os.remove(ffmpeg_exe)
        if os.path.exists(ffprobe_exe): os.remove(ffprobe_exe)
    except: pass


    print("\r\n⚙️  시스템에 FFmpeg 엔진이 발견되지 않았습니다. 최초 1회 자동 다운로드를 시작합니다... (약 100MB)")

    # gyan.dev essentials zip (가장 가볍고 표준적임)
    url = "https://www.gyan.dev/ffmpeg/builds/ffmpeg-release-essentials.zip"

    try:
        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()

        # 메모리에 바로 받아서 압축 풀기 (속도 및 깔끔함)
        with io.BytesIO() as buf:
            total_size = safe_int(response.headers.get('content-length', 0), default=0)
            downloaded = 0

            for chunk in response.iter_content(chunk_size=8192):
                buf.write(chunk)
                downloaded += len(chunk)
                if total_size > 0:
                    done = int(50 * downloaded / total_size)
                    sys.stdout.write(f"\r   📥 다운로드 중: [{'=' * done}{' ' * (50 - done)}] {downloaded/1024/1024:.1f}MB / {total_size/1024/1024:.1f}MB")
                    sys.stdout.flush()

            print("\r\n   📦 압축 해제 및 설치 중...")
            with zipfile.ZipFile(buf) as z:
                # zip 파일 내에서 bin/ffmpeg.exe와 bin/ffprobe.exe 찾기
                for member in z.namelist():
                    if member.endswith("bin/ffmpeg.exe"):
                        with z.open(member) as source, open(ffmpeg_exe, "wb") as target:
                            shutil.copyfileobj(source, target)
                    elif member.endswith("bin/ffprobe.exe"):
                        with z.open(member) as source, open(ffprobe_exe, "wb") as target:
                            shutil.copyfileobj(source, target)

        print("✅ FFmpeg 엔진 설치 완료! 이제 작업을 시작합니다.\r\n")

    except Exception as e:
        print(f"\r\n❌ FFmpeg 자동 다운로드 실패: {e}")
        print("   수동으로 ffmpeg.exe, ffprobe.exe를 스크립트 폴더에 넣어주세요.")
        time.sleep(5)

# (이전에 여기에 있던 FFmpeg 직접 확인 로직 _ensure_ffmpeg() 호출부는 지연 로딩 함수 안으로 이동함)

