    """상태창 가로 길이를 75칸으로 맞춘 프리미엄 버전 (2줄 실선 스타일)"""
    clear_console()

    W, P, R = C.WHITE, C.PURPLE, C.RESET
    width = 75

    line_outer = f" {W}{'═' * (width + 2)}{R}"
    line_inner = f" {W}{'─' * (width + 2)}{R}"

    global _G_SUBTITLE_BG_STATUS, _G_SUBTITLE_BG_QUEUE
    bg_suffix = ""
    if '_G_SUBTITLE_BG_STATUS' in globals() and _G_SUBTITLE_BG_STATUS.get('active'):
        cur = _G_SUBTITLE_BG_STATUS.get('current', 1)
        tot = _G_SUBTITLE_BG_STATUS.get('total', 1)
        stat = _G_SUBTITLE_BG_STATUS.get('status_text', '번역중')
        
        q_info = ""
        if '_G_SUBTITLE_BG_QUEUE' in globals() and '_G_SUBTITLE_BG_QUEUE_LOCK' in globals():
            with _G_SUBTITLE_BG_QUEUE_LOCK:
                q_len = len(_G_SUBTITLE_BG_QUEUE)
                if q_len > 0:
                    q_info = f" (+대기 {q_len}개)"
        bg_suffix = f" {C.YELLOW}(⚙️ 백그라운드 작업: {cur}/{tot} {stat}{q_info}){R}"

    print(line_outer)
    title_text = "💜 친구를 돕는 무언가"
    print(f" {_center_ansi(C.BOLD + P + title_text + R + bg_suffix, width + 4)}")
    print(line_inner)

    prefix = f"[{current_idx}/{total_files}] " if total_files > 0 else ""
    print(f"    {C.SKY}📍 현재 단계:{R} {prefix}{C.BOLD}{current_step}{R}")

    # [V122.0] 모드/모델 판별 로직 정밀화 (인덱스-키 불일치 완전 해결) 🌊🛡️
    current_key = settings_data.get("trans_mode_key") or settings_data.get("mode") or settings_data.get("trans_mode")
    m_idx = settings_data.get('trans_mode_idx', 0)

    # 1. 모드 이름 결정 (키 우선 -> 인덱스 차선)
