# Grouping Constants (Refactored to Dynamic Prefix-based logic - V17.5.1)
# [TAG: #@IS_GEMINI_DIRECT_MODE]
def IS_GEMINI_DIRECT_MODE(m):  return str(m).startswith("gemini_direct")

# [TAG: #@IS_WHISPER_MODE]
def IS_WHISPER_MODE(m):        return str(m).startswith("whisper")

# [TAG: #@IS_COLAB_MODE]
def IS_COLAB_MODE(m):          return str(m).startswith("colab")

# [TAG: #@IS_VAD_MODE]
def IS_VAD_MODE(m):            return str(m).startswith("local_vad")
# [TAG: #@IS_COLAB_TRANSLATE_MODE]
def IS_COLAB_TRANSLATE_MODE(m): return m in [MODE_COLAB_WHISPER_GEMMA_FREE, MODE_COLAB_WHISPER_GEMMA4_E4B, MODE_COLAB_GEMMA4_E4B]

# [TAG: #@IS_LOCAL_WHISPER_MODE]
def IS_LOCAL_WHISPER_MODE(m):   return IS_WHISPER_MODE(m) and not IS_COLAB_MODE(m)

# [TAG: #@IS_WHISPER_GEMINI_MODE]
def IS_WHISPER_GEMINI_MODE(m):  return IS_WHISPER_MODE(m) and "gemini" in str(m)

# [TAG: #@IS_GEMINI_CLI_MODE]
def IS_GEMINI_CLI_MODE(m):       return m in [MODE_WHISPER_GEMINI_CLI, MODE_COLAB_WHISPER_GEMINI_CLI, MODE_GEMINI_CLI_AUDIO_ONESTEP, MODE_EXTRACT_INTERNAL_SUBTITLES, MODE_AGY_AUDIO_ONESTEP, MODE_AGY_ADAPTIVE_PIPELINE]

# [TAG: #@IS_WHISPER_HYBRID_MODE]
def IS_WHISPER_HYBRID_MODE(m): return IS_WHISPER_MODE(m) or IS_COLAB_MODE(m)


# [TAG: #@IS_COLAB_COHERE_TRANSCRIBE_MODE]
def IS_COLAB_COHERE_TRANSCRIBE_MODE(m): return m == MODE_COLAB_COHERE_TRANSCRIBE

# For backward compatibility (Only kept if absolutely necessary, but recommended to use IS_* functions)
# GEMINI_DIRECT_MODES, WHISPER_MODES etc. are now replaced by IS_* functions for better maintainability.


class AIAgent:
    @staticmethod
    # [TAG: #@is_meaningful_transcript]
    def is_meaningful_transcript(srt_content: str) -> bool:
        """[V122.6] 전사 결과가 유효한 대사인지 검증 (타임라인 제외 및 할루시네이션 블랙리스트 체크) 🕵️‍♂️✨"""
        if not srt_content or not srt_content.strip(): return False
        # 1. 할루시네이션(환각) 블랙리스트 🛡️
        blacklist = [
            "시청해주셔서 감사합니다", "시청해 주셔서 감사합니다", "영상을 시청해 주셔서 감사합니다",
            "구독과 좋아요", "좋아요와 구독", "구독과 좋아요 부탁드립니다",
            "Please like and subscribe", "Thanks for watching", "Thank you for watching",
            "Subtitles by", "Amara.org", "subtitle by", "끝까지 시청해주셔서", "채널 구독", "알림 설정",
            "유료광고를 포함하고 있습니다", "유료 광고를 포함하고 있습니다", "이 영상은 유료광고를", "이 영상은 유료 광고를",
            "자막은 설정에서 선택하실 수 있습니다", "자막은 설정에서", "자막 설정에서 자막을",
            "MBC 뉴스", "SBS 뉴스", "KBS 뉴스", "YTN 뉴스", "JTBC 뉴스", "뉴스데스크", "뉴스8",
            "전해주시기 바랍니다", "지금까지 보도국에서", "전해드렸습니다",
            "백엔드 API", "데이터베이스 연결", "데이터베이스를 쿼리", "페이지를 새로고침",
            "simple-chat", "flex column", "flex-grow", "overflow-y", "npm run dev",
            "개발 서버를 시작", "텍스트 인터페이스", "아름다운 UI", "고마워요, 비누", "오늘도 화이팅"
        ]
        # 2. SRT 본문에서 타임라인과 인덱스를 제외한 순수 텍스트만 추출
        pure_texts = []
        for l in srt_content.strip().split('\r\n'):
            l = l.strip()
            if not l or l.isdigit() or '-->' in l: continue
            pure_texts.append(l)
        full_text = " ".join(pure_texts).strip()
        if not full_text: return False
        # 3. 유의미한 문자(한글, 영어, 숫자 + CJK 한자/가나) 존재 확인 🕵️‍♂️✨
        if not re.search(r'[가-힣a-zA-Z0-9\u4e00-\u9fff\u3040-\u30ff]', full_text): return False
        # 4. 블랙리스트 체크 (단독으로 환각 문장만 있는 경우 또는 특정 키워드 포함 시 차단)
        clean_full = re.sub(r'[.,!?\s]', '', full_text)
        for bad in blacklist:
            clean_bad = re.sub(r'[.,!?\s]', '', bad)
            # [V152.32] 초정밀 필터: 특정 악성 문구(자막은 설정...)는 포함만 되어도 바로 컷! ✂️🛡️
            if clean_bad in clean_full:
                if "자막" in bad or "뉴스" in bad: # 치명적인 환각 문구들
                    return False
                if len(clean_full) < len(clean_bad) * 1.5: # 일반적인 환각 문구들
                    return False
        return True

    @staticmethod
    def fix_ai_hallucination(text: str) -> str:
        """[V16.6.4] AI(Gemini)의 할루시네이션(서술형 문구, 반복, 거절 메시지)을 정밀 타격하여 제거합니다냥! 🛡️🎯"""
        if not text: return ""

        # 1. 마크다운 코드 블록 제거 ✨
        text = re.sub(r'```(?:srt|json|text|html|python)?\s*', '', text, flags=re.IGNORECASE)
        text = text.replace('```', '').strip()

        # 2. 전형적인 AI 서술/인사말 문구 제거 (Certainly!, Here is... 등) 🧹
        lines = text.splitlines()
        if not lines: return text

        prefixes = [
            r"^certainly.*", r"^here is the.*", r"^sure, here.*", r"^okay, here.*",
            r"^the translated.*", r"^as requested.*", r"^i have translated.*",
            r"^i understand.*", r"^based on your.*", r"^below is the.*", r"^i can help.*"
        ]
        
        start_idx = 0
        for i in range(min(5, len(lines))):
            line = lines[i].strip().lower()
            if not line: continue
            if any(re.match(p, line, re.I) for p in prefixes):
                start_idx = i + 1
            else:
                # 내용이 시작되면 중단
                if re.match(r'^\[?\d+\]?$', line) or '-->' in line or '[' in line:
                    break
        
        end_idx = len(lines)
        suffixes = [
            r"^i hope this helps.*", r"^let me know if.*", r"^if you have any other.*",
            r"^this is the complete.*", r"^note:.*",
            r"^자막이 아주 자연스럽게.*", r"^혹시 추가로 작업이.*", r"^오늘도 화이팅.*",
            r"^다른 청크도.*", r"^도움이 필요하면.*", r"^언제든 말해줘.*"
        ]
        for i in range(len(lines)-1, max(start_idx, len(lines)-4), -1):
            line = lines[i].strip().lower()
            if not line: continue
            if any(re.match(p, line, re.I) for p in suffixes):
                end_idx = i
            else:
                break
                
        lines = lines[start_idx:end_idx]
        text = "\r\n".join(lines).strip()

        # 3. 안전 필터 거부 문구 감지 🛑
        refusal_patterns = [
            "i can't help with that", "i am a large language model", "i cannot fulfill this request",
            "i cannot translate this content", "i'm sorry, but i cannot", "an error occurred"
        ]
        low_text = text.lower()
        if len(text) < 400:
            if any(p in low_text for p in refusal_patterns):
                return ""

        return text

    @staticmethod
    def calculate_repetition_rate(lines: List[str]) -> float:
        """[V16.6.9] 번역 결과 내의 유의미한 문장 중복률을 계산합니다 (정적 무시 로직 추가) ⚖️✨"""
        if not lines or len(lines) < 3: return 0.0 # [V16.6.9] 최소 3개 이상일 때만 체크냥!
        
        # 유의미한 대사만 추출 (타임스탬프 및 무의미한 점 제거)
        pure_lines = []
        ignore_patterns = ["...", "…", ".", "---", "===END===", "없음", "silence", "silent"]
        
        for l in lines:
            # [N] [S] Text 형태에서 Text만 추출
            clean = re.sub(r'\[\d+\.?\d*s?\]', '', l)
            clean = re.sub(r'\[\d+\]', '', clean).strip()
            
            # [V16.6.9] 무의미한 문구는 중복 체크에서 아예 제외! 🧼
            if not clean or any(p in clean.lower() for p in ignore_patterns):
                continue
            
            if len(clean) > 1: # 한 글자짜리도 제외 (앗, 오, 예 등)
                pure_lines.append(clean)
        
        if not pure_lines or len(pure_lines) < 2: return 0.0
        
        # 중복 비율 계산
        unique_lines = set(pure_lines)
        rate = 1.0 - (len(unique_lines) / len(pure_lines))
        
        # [V16.6.9] 너무 짧은 리스트에서 우연히 겹치는 건 봐줌!
        if len(pure_lines) < 5 and rate < 0.8: return 0.0
        
        return rate


    # [TAG: #@execute_gemini_cli_direct]
    def execute_gemini_cli_direct(self, input_data, prompt, status_fn=None, chunk_idx=0, num_chunks=1, show_output=False, is_text_only=False, custom_prefix=None, model: Optional[str] = None):
        """[V155.0] 타임아웃 발생 시 30초 대기 후 1회 재시도하는 래퍼 함수냥! ⏱️🔄"""
        global _G_SUBTITLE_QUOTA_EXCEEDED
        if _G_SUBTITLE_QUOTA_EXCEEDED:
            self.log_fn(f"\r\n🚫 {C.YELLOW}[Gemini CLI] ⚠️ 이미 API 할당량(Quota) 초과 상태가 감지되어 다음 번역 큐 작업을 건너뜁니다냥! 👋{C.RESET}")
            return None
        with _gemini_cli_timeout_lock:
            start_timeout_count = _gemini_cli_timeout_consecutive_count

        res = self._execute_gemini_cli_direct_internal(
            input_data, prompt, status_fn, chunk_idx, num_chunks, show_output, is_text_only, custom_prefix, model
        )

        if res is None and not _gemini_cli_stop_requested:
            with _gemini_cli_timeout_lock:
                end_timeout_count = _gemini_cli_timeout_consecutive_count
            
            if end_timeout_count > start_timeout_count:
                self.log_fn(f"\r\n⏱️ {C.YELLOW}[Gemini CLI] API 타임아웃 발생으로 인해 30초 대기 후 동일 모델({model or self.model_name})로 1회 재시도합니다냥... (대기 시작){C.RESET}")
                for _ in range(30):
                    if _gemini_cli_stop_requested:
                        break
                    time.sleep(1)
                
                if not _gemini_cli_stop_requested:
                    self.log_fn(f"🔄 {C.GOLD}[Gemini CLI] 30초 대기 완료. 재시도를 시작합니다냥!{C.RESET}")
                    res = self._execute_gemini_cli_direct_internal(
                        input_data, prompt, status_fn, chunk_idx, num_chunks, show_output, is_text_only, custom_prefix, model
                    )
        return res

    # [TAG: #@_execute_gemini_cli_direct_internal]

    def _execute_gemini_cli_direct_internal(self, input_data, prompt, status_fn=None, chunk_idx=0, num_chunks=1, show_output=False, is_text_only=False, custom_prefix=None, model: Optional[str] = None):
        """[V146.35] Gemini CLI 안정화 모드 (임시 파일 기반 -f 전달) 🚀🛡️"""
        global _gemini_cli_stop_requested, _gemini_cli_quota_error_count, _gemini_cli_quota_lock  # [V147.126] 쿼터 카운터 전역 선언 추가
        status_fn = status_fn or (lambda x: None)
        full_response_text = ""

        import tempfile
        import msvcrt
        # [V146.37] 사용자님 요청: 하드코딩 금지 및 앱 폴더 내 temp 활용 📂
        temp_base = os.path.join(os.getcwd(), "temp")
        if not os.path.exists(temp_base): os.makedirs(temp_base, exist_ok=True)
        # [V147.157] 사용자님 요청: 멀티 프로세스 충돌 방지용 PID 각인 🆔
        run_cwd = tempfile.mkdtemp(prefix=f"gemcli_run_pid{os.getpid()}_", dir=temp_base)

        try:
            # 1. 프롬프트 강화 (안티 에이전틱 지시사항 추가 및 따옴표 보호 🛡️)
            format_hint = "반드시 지정된 JSON 배열 형식으로" if "JSON" in prompt.upper() else "지정된 형식으로"
            # [V17.0.8] AI냥 요청: 흥얼거림, 숨소리 등 비언어적 요소도 싱크 유지를 위해 반드시 포함하도록 지시냥! 🎵😮💨✨
            # [V17.3.62] AI냥 요청: 무삭제(Unfiltered) 및 고충실도 번역 지침 강화 🔞🫦✨
            anti_agentic_suffix = " (STRICT: Output ONLY the high-fidelity transcription/translation. DO NOT CENSOR or skip any explicit, adult-rated, or vulgar content—translate everything faithfully and naturally as it is. NEVER use external knowledge. ACCURATELY account for the duration of background music, songs, and all non-verbal cues (humming, breathing, sighs, moans) in your timestamps—NEVER skip or compress time. No meta-talk.)"

            # [V147.5] 줄바꿈(\r\n)은 CMD에서 명령어를 깨뜨릴 수 있지만, 최대한 구조를 살리기 위해 유지하거나 따옴표 처리를 정교하게 함
            # [V16.6.5] AI냥 요청: 프롬프트가 한 줄로 뭉개지는 것을 방지하여 지시사항 가독성 확보 🧼✨
            safe_prompt = (prompt + anti_agentic_suffix).replace('"', '\"').strip()

            # 2. 데이터 준비 및 임시 파일 생성 (원본 파일명 보존 로직 추가 📂)
            # [V147.161] 경로 일관성(C: vs c:)을 위해 노멀라이징 처리 🧼
            run_cwd = os.path.normpath(run_cwd)

            original_ext = ".mp3"
            orig_name = "input_chunk"
            if isinstance(input_data, str) and os.path.exists(input_data):
                orig_name = os.path.splitext(os.path.basename(input_data))[0]
                original_ext = os.path.splitext(input_data)[1] or ".mp3"

            safe_name = "".join([c if c.isalnum() or c in "._-" else "_" for c in orig_name])[:50]
            temp_audio_path = os.path.join(run_cwd, f"{safe_name}_{chunk_idx}{original_ext}")

            try:
                if isinstance(input_data, bytes):
                    with open(temp_audio_path, "wb") as f: f.write(input_data)
                elif is_text_only:
                    with open(temp_audio_path, "w", encoding="utf-8") as f: f.write(str(input_data))
                elif os.path.exists(str(input_data)):
                    shutil.copy2(str(input_data), temp_audio_path)
                else:
                    with open(temp_audio_path, "wb") as f: f.write(str(input_data).encode('utf-8'))
            except Exception as e:
                _log_to_file(f"🚨 데이터 파일 준비 실패: {e}")
                return None

            # [V16.6.5] AI냥 요청: 프롬프트 줄바꿈 및 구조 보존을 위해 파일(@) 방식으로 전달 📂✨
            prompt_txt_path = os.path.join(run_cwd, f"prompt_{chunk_idx}.txt")
            with open(prompt_txt_path, "w", encoding="utf-8") as f:
                f.write(prompt + anti_agentic_suffix)

            # 3. 커맨드 구성 및 실행 환경 설정
            gemini_exe = 'gemini.cmd' if os.name == 'nt' else 'gemini'
            # [V16.4.2] Gemini CLI 전역 기본 모델(GEMINI_CLI_DEFAULT_MODEL)로 -m 플래그 일괄 고정 🚀
            target_model = model or getattr(self, 'model_name', None) or GEMINI_CLI_DEFAULT_MODEL
            if not target_model or str(target_model).lower() in ["auto", "default", "none", "whisper_gemini_cli", ""]:
                target_model = GEMINI_CLI_DEFAULT_MODEL

            clean_model = str(target_model).replace("models/", "") if str(target_model).startswith("models/") else str(target_model)
            model_flag = f"-m {clean_model}"

            # [V16.6.5] 프롬프트 파일(@)과 오디오 파일(@)을 함께 전달 🛰️
            cmd_parts = [f'"{gemini_exe}"', '-y', f'-p "@{prompt_txt_path} @{temp_audio_path}"', '--skip-trust', model_flag, '-o text']
            cmd_str = " ".join(cmd_parts)

            _env = os.environ.copy()
            # [V147.3] API 할당량 오류 방지: 모든 관련 환경 변수를 확실히 제거하여 브라우저 로그인 세션만 사용하게 함 🧼
            for api_key_var in ["GOOGLE_API_KEY", "GEMINI_API_KEY", "PALM_API_KEY"]:
                if api_key_var in _env:
                    del _env[api_key_var]

            # [V147.1] 표준 환경 변수 주입 (다른 곳과 동일하게 설정) 🛰️
            _env["NODE_OPTIONS"] = "--no-deprecation"
            _env["GEMINI_CLI_TRUST_WORKSPACE"] = "true"
            # [V147.162] 워크스페이스 경로를 명시적으로 지정하여 'Path not in workspace' 에러 방지냥! 📂✨
            _env["GEMINI_CLI_WORKSPACE"] = run_cwd
            _env["TERM"] = "dumb"
            _env["NO_COLOR"] = "1"
            _env["CI"] = "true"          # [V17.3.4] 비상! Node v25 안정성 강화: 비대화형 모드 강제 🛡️
            _env["FORCE_COLOR"] = "0"    # [V17.3.4] 컬러 출력 비활성화로 node-pty 간섭 최소화 🧼

            if chunk_idx > 0:
                time.sleep(3.5)

            # 4. 프로세스 실행 (Windows 창 숨김 플래그는 shell=True가 처리하므로 그대로 유지)
            process = subprocess.Popen(
                cmd_str,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                stdin=subprocess.DEVNULL, # [V17.3.4] 입력 스트림 차단으로 대화형 시도 원천 봉쇄 🛑
                text=False,
                cwd=run_cwd,
                shell=True,
                env=_env,
                # [V17.3.4] 창 숨김 및 백그라운드 실행 최적화 🛡️
                creationflags=0x08000000 if os.name == 'nt' else 0
            )

            # 5. 실시간 출력 및 로그 수집 루프
            # [HASHTAG: #GeminiDirect]
            colors = [C.PURPLE, C.SKY, C.GREEN, C.YELLOW, C.MAGENTA]
            color = colors[chunk_idx % len(colors)]
            # [V147.150] 사용자님 요청: 의미 없는 999999 대신 시간 정보([현재시간/전체시간]) 표시냥! 🕰️✨
            batch_label = f"Batch {chunk_idx:02d}/{num_chunks:02d}"
            if custom_prefix:
                prefix = f"{color}[{batch_label} | {custom_prefix}]{C.RESET}"
            else:
                prefix = f"{color}[{batch_label}]{C.RESET}"

            full_res = [""] # [V17.3.42] 모니터링 스레드와 공유하기 위해 리스트로 감쌈 🎁

            if process.stdout:
                last_output_time = [time.time()]
                
                # [V17.3.42] AI냥 요청: 출력이 있으면 60초 더 대기하는 지능형 타임아웃 🧠⏱️
                def monitor_api_timeout():
                    global _gemini_cli_timeout_consecutive_count, _gemini_cli_stop_requested
                    while process.poll() is None:
                        # 기본 240초, 뭐라도 출력 중이었으면 60초 보너스!
                        bonus = 60 if full_res[0].strip() else 0
                        limit = 120 + bonus
                        
                        if time.time() - last_output_time[0] > limit:
                            msg = f" (보너스 {bonus}초 포함)" if bonus else ""
                            print(f"\r\n⚠️ {C.YELLOW}[Gemini CLI] [{batch_label}] {limit}초간 응답이 없어{msg} 현재 시도를 중단하고 '재시도'를 시작합니다냥!{C.RESET}")
                            _log_to_file(f"⚠️ TimeoutMonitor: [{batch_label}] Process hung for {limit}s (bonus={bonus}), killing for retry...")
                            
                            with _gemini_cli_timeout_lock:
                                _gemini_cli_timeout_consecutive_count += 1
                                current_timeout_count = _gemini_cli_timeout_consecutive_count
                            
                            if current_timeout_count >= 2:
                                print(f"\r\n🛑 {C.BOLD}{C.RED}[연속 타임아웃 초과] 타임아웃이 연속 {current_timeout_count}회 발생하여 전체 작업을 중단합니다냥! {C.RESET}😿")
                                _log_to_file(f"🛑 TimeoutCircuitBreaker: Consecutive timeout count reached {current_timeout_count}. Aborting all work.")
                                _gemini_cli_stop_requested = True

                            try:
                                if os.name == 'nt':
                                    subprocess.run(['taskkill', '/F', '/T', '/PID', str(process.pid)], capture_output=True)
                                else:
                                    process.kill()
                            except: pass
                            break
                        time.sleep(2)
                
                timeout_thread = threading.Thread(target=monitor_api_timeout, daemon=True, name="ApiTimeoutMonitor")
                timeout_thread.start()

                for line_bytes in iter(process.stdout.readline, b""):
                    last_output_time[0] = time.time()
                    if _gemini_cli_stop_requested:
                        try: process.terminate()
                        except Exception as e:
                            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                            if "6" not in str(e):
                                _log_to_file(f"⚠️ [Silent Exception] {e}")
                        break

                    # [V16.4.3] AI냥 요청: 지능형 이중 디코딩 (utf-8 -> cp949) 🛡️✨
                    try:
                        line = line_bytes.decode('utf-8')
                    except UnicodeDecodeError:
                        try:
                            line = line_bytes.decode('cp949')
                        except:
                            line = line_bytes.decode('utf-8', errors='replace')
                    if "Loaded cached credentials" in line: continue

                    full_res[0] += line
                    clean_line = line.strip()

                    # [V147.126] AI냥 요청: 쿼터 부족 에러 감시 및 3회 시 중단 🛑🐾 (스레드 안전 버전)
                    if "exhausted your capacity" in clean_line.lower() or "quota exceeded" in clean_line.lower():
                        global _G_SUBTITLE_QUOTA_EXCEEDED
                        _G_SUBTITLE_QUOTA_EXCEEDED = True  # [V155.4] 즉각 쿼터 초과 전역 플래그 활성화 🛑
                        with _gemini_cli_quota_lock:
                            _gemini_cli_quota_error_count += 1
                            current_count = _gemini_cli_quota_error_count
                        self.log_fn(f"\r\n⚠️ {C.YELLOW}[쿼터 경고] API 할당량(Quota) 부족 감지! ({current_count}/3){C.RESET}")

                        if current_count >= 3:
                            self.log_fn(f"\r\n🛑 {C.BOLD}{C.RED}[쿼터 초과] 동일한 에러가 3번 발생하여 작업을 중단합니다. {C.RESET}😿")
                            self.log_fn(f"   💡 {C.DIM}리셋 시간이 너무 길어서(2시간 이상) 오늘은 여기까지 해야 할 것 같아냥!{C.RESET}")
                            _gemini_cli_stop_requested = True
                            try: process.terminate()
                            except Exception as e:
                                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                                if "6" not in str(e):
                                    _log_to_file(f"⚠️ [Silent Exception] {e}")
                            break

                    # [V147.110] AI냥 요청: 불필요한 로그(Warning, YOLO 등) 더 확실하게 제거냥! 🧼
                    if show_output:
                        # ANSI 색상 코드 제거 후 텍스트만 추출해서 체크
                        clean_text = re.sub(r'\033\[[0-9;]*m', '', clean_line)
                        # [V147.113] 에러 스택트레이스나 JSON 에러 덩어리들 필터링 강화 🧼
                        skip_keywords = ["Warning:", "YOLO mode", "terminal detected", "color support", "[STARTUP]", "Loaded cached", "Check out", "Error:", "GaxiosError", "at async", "config:", "method:", "headers:"]
                        if not any(k.lower() in clean_text.lower() for k in skip_keywords):
                            status_fn(f"{prefix} {clean_line}")
                            print(f"{prefix} {clean_line}")

                    # 사용자 중단 체크 (ESC, 's')
                    if msvcrt.kbhit():
                        key = msvcrt.getch()
                        if key in [b'\x1b', b's', b'S']:
                            print(f"\r\n🛑 {C.BOLD}{C.RED}[사용자 중단] 배치를 중지합니다...{C.RESET}")
                            _gemini_cli_stop_requested = True
                            try: process.terminate()
                            except Exception as e:
                                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                                if "6" not in str(e):
                                    _log_to_file(f"⚠️ [Silent Exception] {e}")

            process.stdout.close()
            return_code = process.wait(timeout=600)
            
            # [V147.165] 워닝/안내 메시지 3줄(Windows 10, TERM=dumb, 256-color) 및 YOLO 등이 F2 로그에 섞이는 현상 개선 🧼
            clean_lines = []
            skip_keywords_for_res = ["Warning: Windows 10 detected", "Warning: Basic terminal detected", "Warning: 256-color support", "YOLO mode is enabled", "[STARTUP] Phase 'cleanup_ops'", "[STARTUP] Cannot measure phase"]
            for l in full_res[0].split('\r\n'):
                l_clean = re.sub(r'\033\[[0-9;]*m', '', l).strip()
                if not any(k.lower() in l_clean.lower() for k in skip_keywords_for_res):
                    clean_lines.append(l)
            full_response_text = '\r\n'.join(clean_lines).strip()

            # 6. 결과 반환 (V146.40: 종료 코드가 0이 아니더라도 텍스트가 있으면 일단 수용! 🛡️✨)
            _log_to_file(f"📡 [Gemini CLI Raw Response] Code: {return_code} | Length: {len(full_response_text)}\r\n{full_response_text[:3000]}") # 전수 로깅 🚀
            if (return_code in [0, 1]) or (return_code is None and full_response_text.strip()) or (full_response_text.strip() and len(full_response_text) > 10):
                class DummyRes: pass
                d = DummyRes()
                d.text = full_response_text.strip()
                if len(d.text) < 5:
                    _log_to_file(f"⚠️ [Gemini CLI] [{batch_label}] 응답 텍스트 길이가 너무 짧아(5자 미만) 무효화합니다냥! (Length: {len(d.text)}) | 내용: '{d.text}'")
                    return None
                
                with _gemini_cli_timeout_lock:
                    global _gemini_cli_timeout_consecutive_count
                    _gemini_cli_timeout_consecutive_count = 0
                return d
            else:
                # [V16.4.3] AI냥 요청: 프로세스 사망 원인 정밀 분석 로깅 🕵️‍♂️🔦
                reason = "알 수 없는 에러"
                if return_code == 3221225786:
                    reason = "윈도우 프로세스 강제 종료 (Ctrl+C/터미널 호환성/메모리 부족)"
                _log_to_file(f"❌ Gemini CLI Error ({return_code} - {reason}): 빈 응답이거나 조건 미충족. Raw Response: {full_response_text[:2000]}")
                return None

        except Exception as e:
            _log_to_file(f"❌ Gemini CLI Exception: {e}")
            if 'process' in locals() and process.poll() is None:
                try:
                    process.terminate()
                    try:
                        process.wait(timeout=3)
                    except subprocess.TimeoutExpired:
                        process.kill() # [v17.3.36] 안 꺼지면 확실하게 강제 종료냥! 🧨🛡️
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")
            return None
        finally:
            if 'process' in locals() and process.poll() is None:
                try:
                    process.terminate()
                    try:
                        process.wait(timeout=3)
                    except subprocess.TimeoutExpired:
                        process.kill() # [v17.3.36] 끝까지 안 죽으면 킬냥! 🧨🛡️
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")

            # [V16.4.6] AI냥 요청: 임시 작업 폴더 및 내부 파일 전수 삭제 (청결 유지) 🧹✨
            try:
                if 'run_cwd' in locals() and os.path.exists(run_cwd):
                    shutil.rmtree(run_cwd, ignore_errors=True)
            except Exception as e:
                _log_to_file(f"⚠️ [Cleanup Error] {e}")

    # def execute_cohere_transcribe_colab(self, chunk_file, colab_pool, chunk_idx=0, num_chunks=1, status_fn=None):
    #     """[V80.0] Cohere Transcribe API를 코랩 서버를 통해 호출하여 원문 추출 (번역 X) 🐚 (제거 예정)"""
    #     ... (기존 로직 주석 처리 생략)
        # [TAG: #@parse_translations] [#@dedup_engine]
    def parse_translations(self, text, expected_count):
        """[V16.6.9] 하이브리드 추출기 (자연스러운 중복 허용 모드) (내용 기반 중복 제거 및 번호 리셋 감지 탑재) 🕵️‍♂️🛡️"""
        results = []

        # [V16.4.7] AI냥 요청: Gemini가 명령을 어기고 SRT 형식으로 답할 경우를 대비한 구출 로직 🆘✨
        is_srt_format = "-->" in text and re.search(r'\d{2}:\d{2}:\d{2}', text)

        if is_srt_format:
            # SRT에서 시간과 대사 추출 (번호/시간 제거 후 [SS.S]로 변환)
            lines = text.strip().split('\r\n')
            srt_contents = []
            current_dialogue = []
            current_timestamp = ""
            

            def normalize_text(s):
                # 특수문자, 공백 제거 후 비교하여 순수 내용만 대조
                return re.sub(r'[^가-힣a-zA-Z0-9]', '', s).strip()

            for line in lines:
                line = line.strip()
                if not line:
                    if current_dialogue:
                        content = " ".join(current_dialogue)
                        
                        # [V16.6.8] 이미 나온 내용이거나, 번호가 리셋된 후의 중복이면 무시!
                        if True:
                            if current_timestamp:
                                srt_contents.append(f"[{current_timestamp}] {content}")
                            else:
                                srt_contents.append(content)
                            
                        current_dialogue = []
                        current_timestamp = ""
                    continue

                if "-->" in line:
                    ts_match = re.search(r'(\d{2}):(\d{2}):(\d{2})[.,](\d{3})', line)
                    if ts_match:
                        h, m, s, ms = map(int, ts_match.groups())
                        total_sec = h * 3600 + m * 60 + s + ms / 1000.0
                        current_timestamp = f"{total_sec:.1f}s"
                    continue

                if re.match(r'^\d+$', line):
                    # [V16.6.8] 만약 번호가 1번으로 다시 돌아오면 중복 답변 시작으로 보고 중단!
                    if line == "1" and len(srt_contents) > (expected_count // 2):
                        break
                    continue
                current_dialogue.append(line)

            if current_dialogue:
                content = " ".join(current_dialogue)
                
                if True:
                    if current_timestamp: content = f"[{current_timestamp}] {content}"
                    srt_contents.append(content)

            # 최대한 expected_count에 맞춰서 결과 생성
            for i in range(expected_count):
                results.append(srt_contents[i] if i < len(srt_contents) else "...")
            return results

        # --- 기존 [N] 번호 기반 파싱 로직 (Fallback) ---
        clean_text = re.sub(r'\[\d+/\d+\]', '', text)
        

        def normalize_text(s):
            return re.sub(r'[^가-힣a-zA-Z0-9]', '', s).strip()

        for i in range(1, expected_count + 1):
            pattern_n = rf"(?:\[(\d+\.?\d*)s?\]\s*)?\[0*{i}\]\s*(.*?)(?=\s*(?:\[\d+\.?\d*s?\]\s*)?\[(?!\d+/\d+)\d+\]|\s*===END===|\s*$)"
            matches = re.findall(pattern_n, clean_text, re.DOTALL | re.IGNORECASE)

            if matches:
                cleaned_chunks = []
                for pre_ts, content in matches:
                    chunk = content.strip()
                    if not chunk: continue
                    
                    # [V16.6.8] 내용 중복 체크
                    
                    if False: continue
                    
                    if pre_ts:
                        chunk = f"[{pre_ts}s] {chunk}"
                    cleaned_chunks.append(chunk)
                    

                full_content = "\r\n".join(cleaned_chunks)
                # 생각 블록 및 <think>...</think> 태그 완벽 소탕 🧼✨
                full_content = re.sub(r'<think>.*?</think>', '', full_content, flags=re.DOTALL | re.IGNORECASE)
                full_content = re.sub(r'^(Thinking|Reasoning|Processing|Analysis|Thought):.*?\r\n', '', full_content, flags=re.MULTILINE | re.IGNORECASE)
                full_content = full_content.replace("```", "").replace("**", "").strip()
                full_content = re.sub(rf'\[0*{i}\]\s*', '', full_content)
                # AI 자막 안내 멘트(사담)가 붙은 경우 잘라내기 👮‍♂️
                ad_ment_patterns = r'(?:아래에?\s*(?:최종\s*)?완성된|자막\s*결과물|완성된\s*자막|번역\s*결과|here\s*is\s*the\s*translation|translated\s*subtitles).*$'
                full_content = re.sub(ad_ment_patterns, '', full_content, flags=re.IGNORECASE | re.MULTILINE).strip()

                # [V16.6.7] AI냥 요청: 동일 문장이 따옴표 유무 등으로 중복되는 경우 제거 🧼✨ (지능형 서브스트링/접두사 중복 제거 보강)
                dedup_lines = []
                _line_seen = []
                for l in full_content.split('\r\n'):
                    l_strip = l.strip()
                    if not l_strip: continue
                    lnorm = normalize_text(l_strip)
                    
                    is_dup = False
                    for idx, ext in enumerate(_line_seen):
                        ext_norm = normalize_text(ext)
                        if not ext_norm or not lnorm: continue
                        if len(lnorm) <= len(ext_norm):
                            if lnorm in ext_norm:
                                is_dup = True
                                break
                        else:
                            if ext_norm in lnorm:
                                dedup_lines[idx] = l_strip
                                _line_seen[idx] = l_strip
                                is_dup = True
                                break
                        # 접두사 60% 이상 매치 시 중복 처리 (오타 대응)
                        common_prefix = ""
                        for char_a, char_b in zip(lnorm, ext_norm):
                            if char_a == char_b: common_prefix += char_a
                            else: break
                        if len(common_prefix) >= 4:
                            short_len = min(len(lnorm), len(ext_norm))
                            if (len(common_prefix) / short_len >= 0.6) or (len(common_prefix) >= 6):
                                if len(lnorm) > len(ext_norm):
                                    dedup_lines[idx] = l_strip
                                    _line_seen[idx] = l_strip
                                is_dup = True
                                break
                    if not is_dup:
                        dedup_lines.append(l_strip)
                        _line_seen.append(l_strip)
                
                results.append("\r\n".join(dedup_lines) if dedup_lines else "...")
            else:
                # [V17.3.60] AI냥 요청: 누락된 조각 발생 시 로그 기록냥! 🚨🕵️‍♂️
                if hasattr(self, 'log_fn'):
                    self.log_fn(f"🚨 {C.RED}[Gemini CLI] 조각 [{i}]번 실종 사건 발생! AI가 이 부분을 건너뛰었어냥!{C.RESET}")
                results.append("...")
        return results # [TAG: #@execute_gemma4_onestep_colab]
    def execute_gemma4_onestep_colab(self, audio_data: bytes, count: int, colab_pool, status_fn=None):
        """[V90.0] Gemma 4 e4b 모델을 사용하여 음원을 직접 듣고 자막(번호 기반)을 생성합니다. 🎧✨"""
        status = status_fn or (lambda x: None)
        # [V102.0] IP 기반 화장실 한줄서기 시스템을 통한 1-Step 번역 요청 🚽🌀
        retries = 10
        _current_colab = ""
        if isinstance(colab_pool, str):
            _current_colab = colab_pool
        elif hasattr(colab_pool, 'get_url'):
            _current_colab = colab_pool.get_url()

        if not _current_colab: return None

        while retries > 0:
            try:
                headers = {'Bypass-Tunnel-Reminder': 'true', 'ngrok-skip-browser-warning': 'true'}
                import contextlib
                _svr_lock = colab_pool.get_lock(_current_colab) if colab_pool else contextlib.nullcontext()

                with _svr_lock:
                    status(f"🎧 Gemma 4 e4b가 음원 듣는 중... ({count}개 말뭉치)")

                    # [V95.0] 수정: Instruction-First 프롬프트 (지시사항 먼저, 오디오 나중)
                    audio_markers = " ".join(["<|audio|>" for _ in range(count)])
                    p_msg = (
                        "You are a Korean subtitle transcription AI. "
                        f"Listen to the {count} audio segment(s) carefully and output ONLY the transcript. "
                        "Do NOT repeat these instructions. Format each line exactly as: [N] text."
                        f"\r\n\r\n{audio_markers}"
                    )

                    # [V95.0] 수정: Temperature 0.1 (결정론적 추론, 릝음원비/에코 방지)
                    c_temp, c_top_p, c_rep_pen = 0.1, 1.0, 1.3

                    self.log_fn(f"📡 [PC->Colab] Gemma 4 e4b 원스탭 요청 ({count} batches, Mode: {'Normal' if retries > 3 else 'Safety'}, Temp: {c_temp}, Rep: {c_rep_pen})")

                    stop_tokens = ["<end_of_turn>", "<eos>", "<|endoftext|>", "USER:", "ASSISTANT:"]

                    # [V93.2] 파일 기반 전송: 메모리 버퍼 대신 고정 파일을 통해 안정적으로 전달 🎧💾
                    debug_path = os.path.join("temp", "debug_gemma4_batch.mp3")
                    try:
                        with open(debug_path, "wb") as debug_f:
                            debug_f.write(audio_data)
                    except Exception as e:
                        self.log_fn(f"⚠️ 오디오 파일 저장 실패: {e}")

                    # 파일 핸들을 요청에 직접 넘김
                    with open(debug_path, "rb") as audio_file:
                        response = requests.post(
                            _current_colab + "/transcribe_gemma4",
                            files={'file': ('audio.mp3', audio_file, 'audio/mpeg')},
                            data={
                                'count': count,
                                'prompt': p_msg,
                                'temperature': c_temp,
                                'top_p': c_top_p,
                                'repeat_penalty': c_rep_pen,
                                'stop': json.dumps(stop_tokens)
                            },
                            headers=headers,
                            timeout=600
                        )

                    if response.ok:
                        raw_data = response.json()
                        raw_text = raw_data.get('text', '')

                        # [V94.2] PC측 정화: Vicuna 찌꺼기 및 프롬프트 에코 철저하게 차단 🧼🗑️
                        garbage_pats = [
                            r"A chat between.*?\r\n",
                            r"The assistant gives.*?\r\n",
                            r"Write exactly what you hear in Korean.*?",
                            r"Do not add any conversational text.*?",
                            r"USER:.*", r"ASSISTANT:.*"
                        ]
                        for gp in garbage_pats:
                            raw_text = re.sub(gp, "", raw_text, flags=re.IGNORECASE | re.DOTALL).strip()

                        # 환각/루프 감지 강화 (단순 에코 체크)
                        is_parrot = False
                        if "exactly what you hear" in raw_text or "conversational text" in raw_text:
                            is_parrot = True

                        # 문자열 내에서 특정 구두점이 비정상적으로 많이 나오면 루프로 간주
                        is_loop = raw_text.count("...") > 10 or raw_text.count("당신은") > 5

                        if (len(raw_text) > (count * 1500) and count <= 5) or is_parrot or is_loop:
                            reason = "길이 초과" if not is_parrot and not is_loop else ("에코" if is_parrot else "반복 루프")
                            self.log_fn(f"⚠️ [Gemma 4] {reason} 환각 감지 ({len(raw_text)} chars). 재시도합니다.")
                            retries -= 1
                            time.sleep(2)
                            continue

                        self.log_fn(f"📥 [Colab->PC] Gemma 4 e4b 응답 수신 ({len(raw_text)} bytes)")

                        # [V91.5] 번호 기반 파싱 수행 🛠️
                        parsed_list = self.parse_translations(raw_text, count)

                        # 실패 검증: 점(...) 투성이라면 번역실패로 간주
                        is_all_dots = all(p == "..." or not p.strip() for p in parsed_list)
                        is_echo = any("exactly what you hear" in p or "numbered subtitles" in p for p in parsed_list)

                        if is_all_dots or is_echo:
                            self.log_fn(f"⚠️ [Gemma 4] 응답 유효성 실패 (빈 내용 또는 에코). 재시도... (남은 횟수: {retries-1})")
                            retries -= 1
                            time.sleep(2)
                            continue

                        return parsed_list
                    else:
                        self.log_fn(f"❌ [Colab->PC] Gemma 4 오류 ({response.status_code}): {response.text[:200]}")
                        response.raise_for_status()
            except Exception:
                retries -= 1
                status(f"⚠️ Gemma 4 재시도 중 ({retries}회 남음)...")
                time.sleep(5)
                if retries <= 0: return None
        return None

    # [TAG: #@execute_gemini_cli_onestep]
    # [HASHTAG: #GeminiOneStep]
    def execute_gemini_cli_onestep(self, audio_data: bytes, count: int, status_fn=None, batch_idx=0, total_batches=1, ranges=None, total_duration=0, whisper_text_map=None, baselines=None):
        """[V146.1] Gemini CLI를 사용하여 음원을 직접 듣고 자막(번호 기반)을 생성합니다. 🎧💎"""

        # 1. 임시 오디오 파일 저장 (현재 앱 폴더 내 temp 사용 📂)
        temp_dir = os.path.join(os.getcwd(), "temp")
        if not os.path.exists(temp_dir):
            os.makedirs(temp_dir, exist_ok=True)

        # [V16.7.5] 사용자님 요청: 포맷 변경 없이 MP3 유지냥! 대신 PID 각인으로 충돌 방지 🎧🆔
        temp_audio_path = os.path.join(temp_dir, f"gemini_cli_batch_pid{os.getpid()}_{batch_idx}.mp3")
        try:
            with open(temp_audio_path, "wb") as f:
                f.write(audio_data)

            # 2. 프롬프트 구성 (사용자님 성공 공식 전격 이식! ⚡)
            # [V147.103] 사용자님 아이디어 2탄: 1말뭉치 1줄 강제! 여러 줄은 \r\n 사용! 🤯✨
            time_hints = ""
            whisper_hints = ""
            if ranges and len(ranges) == count:
                hints = []
                drafts = []
                # [V17.3.7] AI냥 요청: time_hints를 상대 시간(오디오 파일 기준)으로 변경 ⏱️
                batch_start_ms = ranges[0][0]
                for i, (start_ms, end_ms) in enumerate(ranges):
                    duration_sec = (end_ms - start_ms) / 1000.0
                    # [V22.5] baselines(물리적 오디오 실측 오프셋) 정보가 존재하면 오차 없이 일치시킴 ⏱️✨
                    if baselines and len(baselines) == len(ranges):
                        rel_start_sec = (baselines[i] - batch_start_ms) / 1000.0
                    else:
                        rel_start_sec = (start_ms - batch_start_ms) / 1000.0
                    # [V17.3.18] 프롬프트 언어 통일: 영어로 변경하여 AI 혼선 방지냥! ⏱️🌐
                    time_desc = "starts near 0.0s" if rel_start_sec == 0 else f"starts at {rel_start_sec:.1f}s"
                    hints.append(f"#{i+1} ({time_desc}, approx {duration_sec:.1f}s long)")

                    if whisper_text_map:
                        draft_text = whisper_text_map.get((start_ms, end_ms), "")
                        if draft_text:
                            drafts.append(f"[{i+1}] ({time_desc}, approx {duration_sec:.1f}s): {draft_text}")

                time_hints = f" Estimated relative start times for the {count} segments are: {', '.join(hints)}."
                if drafts:
                    whisper_hints = "\r\n\r\nWhisper Tiny Rough Reference Draft (Use this as a reference guide to listen to the audio and do the precise translation, timing alignment, and spelling):\r\n" + "\r\n".join(drafts) + "\r\n"

            # [V17.3.62] AI냥 요청: '음미(Contextual Review)' 및 '무삭제(Unfiltered)' 지침 도입 🔞🫦✨
            # [TAG: #@High_Fidelity_Sync]
            p_msg = (
                f"[CRITICAL: DO NOT RUN WHISPER OR ANY LOCAL STT/TRANSCRIPTION TOOLS. Do NOT write Python scripts, run command-line tools, or attempt local transcription. Simply listen to the attached audio/video file directly using your multimodal vision/audio capability and output Korean subtitle translations immediately. NO CODE, NO WHISPER EXECUTION, NO TOOL CALLS.]\r\n\r\n"
                f"Task: Transcribe and translate {count} audio segments into natural Korean subtitles (Netflix/drama quality).\r\n"
                f"Context: Continuous video/audio timeline. Silence gaps preserved.{time_hints}{whisper_hints}\r\n\r\n"
                "━━━ NO TOOL CALLS & NO LOCAL WHISPER — CRITICAL RULE ━━━\r\n"
                "- You are strictly prohibited from using any tools (e.g., run_command, write_to_file, view_file, search_web, etc.).\r\n"
                "- NEVER attempt to run local Whisper models (e.g., whisper small/tiny/medium/large or faster-whisper) or Python scripts.\r\n"
                "- Do NOT try to test, analyze, or run STT scripts. The Whisper text draft provided below was already generated locally beforehand as a rough timestamp reference — DO NOT RUN WHISPER AGAIN.\r\n"
                "- Your ONLY task is to listen to the attached file directly via multimodal API and return the translated subtitles in the exact format requested.\r\n"
                "- Any attempt to use a tool or run local transcription will result in system failure. Just listen and translate immediately.\r\n\r\n"
                "━━━ WHISPER DRAFT & TIMING SYNC (CRITICAL) ━━━\r\n"
                "- The Whisper text draft is a rough reference. Do NOT copy it blindly for content, and do NOT try to re-transcribe locally with whisper-small. Rely strictly on your own direct listening.\r\n"
                "- However, you MUST heavily rely on the Whisper TIMING HINTS to prevent audio sync drift.\r\n"
                "- Do NOT invent subtitles during silence gaps. Confine your timestamps to match the audio boundaries provided by Whisper.\r\n\r\n"
                "━━━ SEGMENT COMPLETENESS — IRON RULE ━━━\r\n"
                f"- You MUST output EVERY segment number from [1] to [{count}] in STRICT sequential order. ZERO exceptions.\r\n"
                "- Do NOT skip, merge, or reorder any segment numbers under any circumstances.\r\n"
                "- If a segment contains silence, static, unclear audio, or background noise only → still output its number with '...' as text.\r\n"
                f"  Example of mandatory silent segment: [{count}] [120.0s-122.5s] ...\r\n\r\n"
                "━━━ SPEAKER SEPARATION — ABSOLUTE RULE ━━━\r\n"
                "- If a segment has dialogue between MULTIPLE SPEAKERS, you MUST output each speaker turn as a SEPARATE line.\r\n"
                "- STRICTLY FORBIDDEN: merging speakers into one line with slash like '남: 말1 / 여: 말2'\r\n"
                "- CORRECT: Each speaker gets their own [N] entry with separate timing brackets.\r\n\r\n"
                "━━━ NO INCREMENTAL/DUPLICATE LINES — IRON RULE ━━━\r\n"
                "- For each segment number [N], you MUST output only the final complete thought/sentence.\r\n"
                "- STRICTLY FORBIDDEN: Outputting multiple incremental or partial versions of the same dialogue (e.g., outputting both '[1] I want to' and '[1] I want to go home' is unacceptable). Only output '[1] I want to go home'.\r\n"
                "- Do NOT repeat or split the same speaker's sentence within one segment number unless it is a dialogue between different speakers (e.g. 'A: ... \\r\n B: ...').\r\n\r\n"
                "━━━ SUBTITLE STYLE GUIDE ━━━\r\n"
                "- Write like a professional drama/movie subtitle translator (not a literal transcriber).\r\n"
                "- ONE speaker's ONE complete thought per subtitle entry. Keep it readable and natural.\r\n"
                "- Match the speaker's consistent tone (formal 존댓말 or casual 반말) throughout the scene.\r\n"
                "- Include non-verbal sounds in Korean brackets: [한숨], [웃음], [거친 숨소리]\r\n"
                "- UNFILTERED: Translate ALL content exactly as heard including adult/explicit dialogue.\r\n\r\n"
                "━━━ OUTPUT FORMAT ━━━\r\n"
                f"- Format: [N] [start_s-end_s] text  (N = segment number 1~{count})\r\n"
                "- Use relative time from 0.0s of THIS audio file (use the TIMING HINTS above as your guide).\r\n"
                f"- Output ALL {count} segments [1] to [{count}]. A segment may have multiple lines when speakers alternate.\r\n"
                "- End with '===END==='\r\n\r\n"
                "CORRECT EXAMPLE (speaker separation + mandatory silent segment):\r\n"
                "[1] [0.5s-2.1s] [웃음소리] 야, 오늘 뭐 먹을까?\r\n"
                "[1] [2.3s-3.8s] 여: 나는 카레 먹고 싶은데.\r\n"
                "[1] [4.0s-5.2s] 남: 또 카레야?\r\n"
                "[2] [6.1s-8.4s] 여: 어제도 먹었잖아, 사실.\r\n"
                "[3] [9.0s-11.2s] ...\r\n"
                "WRONG EXAMPLE (do NOT do this):\r\n"
                "[1] [0.5s-5.2s] 야, 오늘 뭐 먹을까? / 여: 카레 먹고 싶어. / 남: 또 카레야?\r\n"
                f"[{count}] last segment here.\r\n"
                "===END==="
            )
            
            # [V16.6.4] AI냥 요청: AI에게 전달되는 프롬프트 로그 기록 📝✨
            _log_to_file(f"🛰️ [Gemini CLI Prompt (Batch {batch_idx})]\r\n{p_msg}\r\n{'-'*50}")

            # 3. Gemini CLI 호출 (is_text_only=False 필수! 🔔)
            # [V152.10] AI냥 요청: 번호 누락 시 자동 재시도 로직 도입! 🔄🛡️
            abs_audio_path = os.path.abspath(temp_audio_path)
            if not os.path.exists(abs_audio_path):
                self.log_fn(f"❌ [Gemini CLI] 오디오 파일이 존재하지 않음: {abs_audio_path}")
                return None

            # [V26.0] 사용자님 요청: MP3 오디오를 사전에 MP4 가상 동영상 파일로 변환하여 멀티모달 번역 정확도 향상 🎥🎧✨
            temp_video_path = temp_audio_path.replace(".mp3", ".mp4")
            abs_video_path = os.path.abspath(temp_video_path)
            
            ffmpeg_bin = shutil.which("ffmpeg") or "ffmpeg"
            convert_cmd = [
                ffmpeg_bin, "-y",
                "-f", "lavfi", "-i", "color=c=black:s=320x240:r=1",
                "-i", abs_audio_path,
                "-c:v", "libx264", "-tune", "stillimage",
                "-c:a", "aac", "-b:a", "192k",
                "-pix_fmt", "yuv420p", "-shortest",
                abs_video_path
            ]
            self.log_fn(f" 🎬 [Gemini CLI] 오디오를 가상 비디오(MP4)로 변환 중... (ffmpeg)")
            try:
                success, stdout, stderr = run_ffmpeg_task(convert_cmd, desc="Gemini CLI 멀티모달 가상 비디오 생성")
                if not success or not os.path.exists(abs_video_path) or os.path.getsize(abs_video_path) == 0:
                    self.log_fn(f" ⚠️ [Gemini CLI] 비디오 변환 실패. 원본 MP3 오디오 파일로 계속 진행합니다.")
                    abs_video_path = abs_audio_path
            except Exception as fe:
                self.log_fn(f" ⚠️ [Gemini CLI] 비디오 변환 중 오류 발생: {fe}. 원본 MP3 오디오 파일로 계속 진행합니다.")
                abs_video_path = abs_audio_path

            max_retries = 2 # [V17.3.19] AI냥 요청: 먹통 대비 재시도 횟수를 2회로 상향! 🛡️🔄

            # [임무 3] [TAG: #@fmt_time] fmt_time 함수를 루프 바깥으로 이동 (루프 내 반복 정의 방지) 🔧✨
            def fmt_time(s):
                m, s = divmod(int(s), 60)
                h, m = divmod(m, 60)
                return f"{h:02d}:{m:02d}:{s:02d}" if h > 0 else f"{m:02d}:{s:02d}"

            # [임무 1] p_msg는 불변 원본으로 보존. 재시도 피드백은 별도 변수로 관리 🛡️
            p_msg_base = p_msg
            retry_feedback = ""  # 누락 발견 시 덧붙일 피드백 문자열 (재시도마다 갱신)

            for attempt in range(max_retries + 1):
                try:
                    # [V147.150] 사용자님 요청: 시간 표시([현재시간 / 전체시간]) 커스텀 프리픽스 생성 🕰️✨
                    custom_p = None
                    if ranges and total_duration > 0:
                        start_sec = ranges[0][0] / 1000.0
                        custom_p = f"{fmt_time(start_sec)} / {fmt_time(total_duration)}"

                    # [V152.10] 재시도 시 로그에 표시 🔄
                    retry_suffix = f" (재시도 {attempt}/{max_retries})" if attempt > 0 else ""
                    # [V16.6.4] AI냥 요청: 1-based 인덱스 출력으로 통일 🔢✨
                    self.log_fn(f"🚀 {C.GOLD}[Gemini CLI] 번역 요청 중... (배치: {batch_idx}, 말뭉치 {count}개){retry_suffix} - 파일: {abs_video_path}{C.RESET}")

                    # [임무 1] 실제 AI에게 전달할 프롬프트: 원본 + 재시도 피드백 조합 (원본 p_msg_base는 오염 없음) 🧼
                    # [V16.5.0] 음원 직접 번역(One-Step)은 여전히 gemini-3-flash-preview가 가장 강력하므로 강제 고정 🎤⚡
                    current_prompt = p_msg_base + retry_feedback
                    raw_response = self.execute_gemini_cli_direct(abs_video_path, current_prompt, is_text_only=False, status_fn=status_fn, show_output=True, chunk_idx=batch_idx, num_chunks=total_batches, custom_prefix=custom_p, model=getattr(self, "model_name", None))

                    if not raw_response:
                        if attempt < max_retries: continue
                        return None

                    # DummyRes 객체가 반환되는 경우 text 속성 추출
                    if hasattr(raw_response, 'text'):
                        raw_text = raw_response.text
                    else:
                        raw_text = str(raw_response)

                    # [V152.10] 지능형 검증: 모든 번호표 [1] ~ [count]가 원문에 존재하는지 체크 🕵️‍♂️✨
                    missing_indices = []
                    for idx in range(1, count + 1):
                        if not re.search(rf'\[0*{idx}\]', raw_text):
                            missing_indices.append(idx)

                    if missing_indices and attempt < max_retries:
                        self.log_fn(f"⚠️ {C.YELLOW}[Gemini CLI] [Batch {batch_idx}] 번호 누락 발견 {missing_indices}. (AI 피드백 후 재시도합니다...){C.RESET}")
                        # [임무 1] [V17.3.61] 재시도 피드백은 retry_feedback에만 누적. p_msg_base는 절대 오염 금지! 🛡️🗣️
                        retry_feedback = f"\r\n\r\nIMPORTANT: In your previous attempt, you missed these segment numbers: {missing_indices}. This time, you MUST include ALL numbers from [1] to [{count}] without exception."
                        time.sleep(12)
                        continue

                    if missing_indices:
                        # [임무 2] 실제 시도 횟수(attempt+1)로 로그 정확도 수정 🟡
                        self.log_fn(f"🚨 {C.RED}[Gemini CLI] [Batch {batch_idx}] 총 {attempt+1}번 시도했으나 {missing_indices}번은 끝내 침묵했어냥... 후처리를 진행합니다. 🩹{C.RESET}")

                    # [V47.6] AI냥 요청: 환각 문구(자막은 설정에서...) 전수 조사 🕵️‍♂️🚩
                    hallucination_found = False
                    parsed_list_temp = self.parse_translations(raw_text, count)
                    
                    for idx, res_line in enumerate(parsed_list_temp):
                        if not self.is_meaningful_transcript(res_line):
                            self.log_fn(f"🚩 {C.RED}[Gemini CLI] [Batch {batch_idx}] 환각 블랙리스트 감지: {res_line[:30]}... (재시도){C.RESET}")
                            hallucination_found = True
                            break
                    
                    # [V16.6.4] AI냥 요청: 70% 이상 중복/할루시 감지 (Similarity Guard) ⚖️🛡️
                    if not hallucination_found:
                        rep_rate = self.calculate_repetition_rate(parsed_list_temp)
                        if rep_rate >= 0.85:
                            self.log_fn(f"🚩 {C.RED}[Gemini CLI] [Batch {batch_idx}] 중복률 {rep_rate*100:.1f}% 감지! (할루시네이션 의심되어 재시도합니다냥!){C.RESET}")
                            hallucination_found = True

                    if hallucination_found and attempt < max_retries:
                        self.log_fn(f"🔄 {C.YELLOW}[Gemini CLI] [Batch {batch_idx}] 품질 저하로 인해 재번역을 시도합니다냥! ({attempt+1}/{max_retries}){C.RESET}")
                        time.sleep(1.5)
                        continue

                    # 4. 결과 파싱 ([N] text 형식 추출) - 기존 고도화된 parse_translations 활용 🛠️
                    parsed_list = self.parse_translations(raw_text, count)

                    # [V146.6] 최종 정화: 번호표 [N]가 텍스트에 잔류하는 경우 제거
                    # [V16.6.6] AI냥 요청: 뭉치 중간에 박힌 번호표들도 철저히 소탕! 🧼✨ (지능형 서브스트링 중복 제거 보강)
                    cleaned_list = []
                    for i, item in enumerate(parsed_list):
                        idx = i + 1
                        # 줄바꿈된 내용들 각각에 대해 번호표 제거 및 중복 체크
                        sub_lines = []
                        seen_norm = []
                        def normalize_for_dedup(s):
                            return re.sub(r'[^가-힣a-zA-Z0-9]', '', s).strip()

                        for line in item.split('\r\n'):
                            clean_l = re.sub(rf'\[0*{idx}\]\s*', '', line).strip()
                            if clean_l:
                                norm = normalize_for_dedup(clean_l)
                                is_dup = False
                                for s_idx, ext in enumerate(seen_norm):
                                    ext_norm = normalize_for_dedup(ext)
                                    if not ext_norm or not norm: continue
                                    if len(norm) <= len(ext_norm):
                                        if norm in ext_norm:
                                            is_dup = True
                                            break
                                    else:
                                        if ext_norm in norm:
                                            sub_lines[s_idx] = clean_l
                                            seen_norm[s_idx] = clean_l
                                            is_dup = True
                                            break
                                    # 접두사 60% 이상 매치 시 중복 처리 (오타 대응)
                                    common_prefix = ""
                                    for char_a, char_b in zip(norm, ext_norm):
                                        if char_a == char_b: common_prefix += char_a
                                        else: break
                                    if len(common_prefix) >= 4:
                                        short_len = min(len(norm), len(ext_norm))
                                        if (len(common_prefix) / short_len >= 0.6) or (len(common_prefix) >= 6):
                                            if len(norm) > len(ext_norm):
                                                sub_lines[s_idx] = clean_l
                                                seen_norm[s_idx] = clean_l
                                            is_dup = True
                                            break
                                if not is_dup:
                                    sub_lines.append(clean_l)
                                    seen_norm.append(clean_l)
                        
                        clean_item = "\r\n".join(sub_lines).strip()

                        clean_item = clean_agent_chatter_and_emojis(clean_item)

                        cleaned_list.append(clean_item if clean_item else "...")

                    # [V17.3.61] AI냥 요청: 최종 누락분 체크 및 후처리 로그 강화 🩹🚨
                    missing_final = [i+1 for i, item in enumerate(cleaned_list) if item == "..."]
                    if missing_final:
                        self.log_fn(f"🩹 {C.CYAN}[Gemini CLI] [Batch {batch_idx}] 최종 누락 발생: {missing_final}번은 데이터가 없어 '...'으로 채웠어냥!{C.RESET}")

                    return cleaned_list
                except Exception as e:
                    if attempt < max_retries: continue
                    self.log_fn(f"❌ [Gemini CLI] 작업 중 예외 발생: {e}")
                    return None
        except Exception as e:
            self.log_fn(f"❌ [Gemini CLI] 오디오 준비 중 예외 발생: {e}")
            return None
        finally:
            # [V147.155] 사용자님 요청: 임시 오디오 파일 즉시 삭제 (증거 인멸! 🧼🪒✨)
            try:
                if 'temp_audio_path' in locals() and os.path.exists(temp_audio_path):
                    # [V16.4.6] AI냥 요청: 파일 점유(WinError 32) 방지를 위해 미세 지연 후 삭제 ⏳🧼
                    time.sleep(0.3)
                    os.remove(temp_audio_path)
            except Exception as e:
                try:
                    # 삭제 실패 시 한 번 더 기회! (고스트 프로세스 대응) 👻🧹
                    time.sleep(0.5)
                    if os.path.exists(temp_audio_path): os.remove(temp_audio_path)
                except:
                    _log_to_file(f"⚠️ [Cleanup Failed] {temp_audio_path}: {e}")

            # [V26.0] 임시 변환된 가상 비디오 파일도 삭제 🧼🎬
            try:
                if 'temp_video_path' in locals() and os.path.exists(temp_video_path):
                    time.sleep(0.3)
                    os.remove(temp_video_path)
            except Exception as e:
                try:
                    time.sleep(0.5)
                    if os.path.exists(temp_video_path): os.remove(temp_video_path)
                except: pass

            # [V26.0] 임시 변환된 가상 비디오 파일도 삭제 🧼🎬
            try:
                if 'temp_video_path' in locals() and os.path.exists(temp_video_path):
                    time.sleep(0.3)
                    os.remove(temp_video_path)
            except Exception as e:
                try:
                    time.sleep(0.5)
                    if os.path.exists(temp_video_path): os.remove(temp_video_path)
                except: pass


    # [TAG: #@set_detected_language]
    def set_detected_language(self, lang_code: str):
        """[V80.0] 하이브리드 언어 감지 결과를 에이전트에 기록합니다. 🔍"""
        self.detected_language = lang_code
        self.log_fn(f" 🔍 [AIAgent] 감지된 언어를 설정함: {lang_code.upper()} ✨")

    # [TAG: #@execute_agy_cli_onestep]
    def execute_agy_cli_onestep(self, audio_data: bytes, count: int, status_fn=None, batch_idx=0, total_batches=1, ranges=None, total_duration=0, whisper_text_map=None, baselines=None):
        """[테스트 6 방식 이식 V2] agy CLI를 사용하여 음원을 직접 듣고 자막(번호 기반)을 생성합니다. 🎧💎
        변경 이력:
        - [BugFix] f-string 미적용 버그 수정: Output ALL {count} 줄 f"" 누락 수정 🐛→✅
        - [신규] Gemini 방식 max_retries=2 재시도 루프 추가 🔄🛡️
        - [신규] 누락 번호 감지 → 피드백 포함 재시도 (테스트 6 검증 방식) 🕵️‍♂️
        """
        import os
        import re
        import time
        import tempfile
        import shutil
        import uuid

        # 1. 임시 오디오 파일 저장 (현재 앱 폴더 내 temp 사용 📂)
        temp_dir = os.path.join(os.getcwd(), "temp")
        if not os.path.exists(temp_dir):
            os.makedirs(temp_dir, exist_ok=True)

        # PID 각인으로 충돌 방지 🎧🆔
        run_cwd = tempfile.mkdtemp(prefix=f"agy_run_pid{os.getpid()}_", dir=temp_dir)
        temp_audio_path = os.path.join(run_cwd, f"agy_cli_batch_{batch_idx}.mp3")
        prompt_txt_path = os.path.join(run_cwd, f"prompt_{batch_idx}.txt")
        
        try:
            with open(temp_audio_path, "wb") as f:
                f.write(audio_data)

            # 2. 프롬프트 구성 (테스트 6번 성공 공식 완전 이식! ⚡)
            time_hints = ""
            whisper_hints = ""
            if ranges and len(ranges) == count:
                hints = []
                drafts = []
                batch_start_ms = ranges[0][0]
                for i, (start_ms, end_ms) in enumerate(ranges):
                    duration_sec = (end_ms - start_ms) / 1000.0
                    if baselines and len(baselines) == len(ranges):
                        rel_start_sec = (baselines[i] - batch_start_ms) / 1000.0
                    else:
                        rel_start_sec = (start_ms - batch_start_ms) / 1000.0
                    time_desc = "starts near 0.0s" if rel_start_sec == 0 else f"starts at {rel_start_sec:.1f}s"
                    hints.append(f"#{i+1} ({time_desc}, approx {duration_sec:.1f}s long)")

                    if whisper_text_map:
                        draft_text = whisper_text_map.get((start_ms, end_ms), "")
                        if draft_text:
                            drafts.append(f"[{i+1}] ({time_desc}, approx {duration_sec:.1f}s): {draft_text}")

                time_hints = f" Estimated relative start times for the {count} segments are: {', '.join(hints)}."
                if drafts:
                    whisper_hints = "\r\n\r\nWhisper Tiny Rough Reference Draft (Use this as a reference guide to listen to the audio and do the precise translation, timing alignment, and spelling):\r\n" + "\r\n".join(drafts) + "\r\n"

            # [BugFix] p_msg_base로 분리 보존 (재시도 시 오염 방지) 🛡️
            # [BugFix] f-string 미적용 버그 수정: "- Output ALL {count} segments..." 줄 f"" 추가 🐛→✅
            p_msg_base = (
                f"[ROLE MANDATE: PROFESSIONAL ENGLISH/JAPANESE TO KOREAN SUBTITLE TRANSLATOR]\r\n"
                f"- [핵심 페르소나] 당신은 코딩 에이전트나 프로그래머가 절대 아닙니다! 영상과 음성을 듣고 한국어 자막을 만드는 '전문 영어/일본어 미디어 번역가'입니다.\r\n"
                f"- YOU ARE STRICTLY A PROFESSIONAL NATIVE KOREAN MEDIA SUBTITLE TRANSLATOR (SPECIALIZING IN ENGLISH AND JAPANESE TO KOREAN).\r\n"
                f"- ABSOLUTE RULE: You are NOT a coding agent or software developer. Do NOT output coding tutorials, web dev jargon (DTO, 회원가입, auth, create-user, component), plans, or scripts.\r\n"
                f"- ABSOLUTELY NO TOOL CALLS: Do NOT run python scripts (transcribe.py), do NOT check whisper installation, and do NOT use local tools.\r\n"
                f"- Listen to the attached MP4/MP3 media file DIRECTLY using your native multimodal audio/vision capability.\r\n"
                f"- Output Korean subtitle translations immediately in the exact requested bracket format [1]..[{count}].\r\n"
                f"- NO conversational greetings, NO agent status logs, NO filler text.\r\n\r\n"
                f"Task: Transcribe and translate {count} audio segments into natural Korean subtitles (Netflix/drama quality).\r\n"
                f"Context: Continuous video/audio timeline. Silence gaps preserved.{time_hints}{whisper_hints}\r\n\r\n"
                "━━━ SUBTITLE TRANSLATION ONLY — NO AGENT WORKFLOW ━━━\r\n"

                "- You are STRICTLY a subtitle translation engine. Do NOT act as a coding assistant, do NOT create files or python scripts, do NOT mention paths (like C:\\Users\\...), and do NOT output conversational filler.\r\n"

                "- STRICT EMOJI BAN: NEVER output any emojis (e.g. 👍, 😊, 🚀, 😉, 🥺) under any circumstances.\r\n"

                "- CONSISTENT TONE: Maintain a natural, polite Korean subtitle tone (~해요 / ~습니다) consistently across ALL segments.\r\n\r\n"

                "━━━ NO THINKING OR META-TEXT — ABSOLUTE IRON RULE ━━━\r\n"
                "- Do NOT output any thinking, reasoning, chain-of-thought, or intermediate steps. Do NOT output <think> tags or their contents.\r\n"
                "- Do NOT add any introductions, translator's notes, explanations, or concluding greetings (e.g., 'Here is the translation', '자막 결과물을 공유할게').\r\n"
                "- Start directly with the first bracketed segment and end strictly with '===END===', outputting absolutely nothing else.\r\n\r\n"
                "━━━ NO TOOL CALLS — CRITICAL RULE ━━━\r\n"
                "- You are strictly prohibited from using any tools (e.g., run_command, write_to_file, view_file, search_web, etc.).\r\n"
                "- Do NOT try to test, analyze, or run scripts. Your ONLY task is to return the translated subtitles in the exact format requested.\r\n"
                "- Any attempt to use a tool will result in a system failure. Just listen to the audio/video and translate immediately.\r\n\r\n"
                "━━━ WHISPER DRAFT & TIMING SYNC (CRITICAL) ━━━\r\n"
                "- The Whisper text draft is rough. Do NOT copy it for content. Rely strictly on your own ear.\r\n"
                "- However, you MUST heavily rely on the Whisper TIMING HINTS to prevent audio sync drift.\r\n"
                "- Do NOT invent subtitles during silence gaps. Confine your timestamps to match the audio boundaries provided by Whisper.\r\n\r\n"
                "━━━ SEGMENT COMPLETENESS — IRON RULE ━━━\r\n"
                f"- You MUST output EVERY segment number from [1] to [{count}] in STRICT sequential order. ZERO exceptions.\r\n"
                "- Do NOT skip, merge, or reorder any segment numbers under any circumstances.\r\n"
                "- If a segment contains silence, static, unclear audio, or background noise only → still output its number with '...' as text.\r\n"
                f"  Example of mandatory silent segment: [{count}] [120.0s-122.5s] ...\r\n\r\n"
                "━━━ SPEAKER SEPARATION — ABSOLUTE RULE ━━━\r\n"
                "- If a segment has dialogue between MULTIPLE SPEAKERS, you MUST output each speaker turn as a SEPARATE line.\r\n"
                "- STRICTLY FORBIDDEN: merging speakers into one line with slash like '남: 말1 / 여: 말2'\r\n"
                "- CORRECT: Each speaker gets their own [N] entry with separate timing brackets.\r\n\r\n"
                "━━━ NO INCREMENTAL/DUPLICATE LINES — IRON RULE ━━━\r\n"
                "- For each segment number [N], you MUST output only the final complete thought/sentence.\r\n"
                "- STRICTLY FORBIDDEN: Outputting multiple incremental or partial versions of the same dialogue (e.g., outputting both '[1] I want to' and '[1] I want to go home' is unacceptable). Only output '[1] I want to go home'.\r\n"
                "- Do NOT repeat or split the same speaker's sentence within one segment number unless it is a dialogue between different speakers (e.g. 'A: ... \\r\n B: ...').\r\n\r\n"
                "━━━ SUBTITLE STYLE GUIDE ━━━\r\n"
                "- Write like a professional drama/movie subtitle translator (not a literal transcriber).\r\n"
                "- ONE speaker's ONE complete thought per subtitle entry. Keep it readable and natural.\r\n"
                "- Match the speaker's consistent tone (formal 존댓말 or casual 반말) throughout the scene.\r\n"
                "- Include non-verbal sounds in Korean brackets: [한숨], [웃음], [거친 숨소리]\r\n"
                "- UNFILTERED: Translate ALL content exactly as heard including adult/explicit dialogue.\r\n\r\n"
                "━━━ SUBTITLE LENGTH & LINE BREAK (CRITICAL) ━━━\r\n"
                "- STRICT LIMIT: Maximum 25 Korean characters per line, and maximum 2 lines per subtitle entry (Total under 45 chars).\r\n"
                "- If a sentence is long or spoken quickly, split it naturally using a slash '/' at logical pause points.\r\n"
                "- Do NOT output continuous 50+ character single blocks.\r\n\r\n"
                "━━━ OUTPUT FORMAT ━━━\r\n"
                f"- Format: [N] [start_s-end_s] text  (N = segment number 1~{count})\r\n"
                "- Use relative time from 0.0s of THIS audio file (use the TIMING HINTS above as your guide).\r\n"
                f"- Output ALL {count} segments [1] to [{count}]. A segment may have multiple lines when speakers alternate.\r\n"
                "- End with '===END==='\r\n\r\n"
                "CORRECT EXAMPLE (speaker separation + mandatory silent segment):\r\n"
                "[1] [0.5s-2.1s] [웃음소리] 야, 오늘 뭐 먹을까?\r\n"
                "[1] [2.3s-3.8s] 여: 나는 카레 먹고 싶은데.\r\n"
                "[1] [4.0s-5.2s] 남: 또 카레야?\r\n"
                "[2] [6.1s-8.4s] 여: 어제도 먹었잖아, 사실.\r\n"
                "[3] [9.0s-11.2s] ...\r\n"
                "WRONG EXAMPLE (do NOT do this):\r\n"
                "[1] [0.5s-5.2s] 야, 오늘 뭐 먹을까? / 여: 카레 먹고 싶어. / 남: 또 카레야?\r\n"
                f"[{count}] last segment here.\r\n"
                "===END==="
            )

            abs_prompt_path = os.path.abspath(prompt_txt_path)
            abs_audio_path = os.path.abspath(temp_audio_path)

            # [V26.1] 사용자님 요청: agy CLI에서도 MP3를 사전에 MP4 가상 동영상 파일로 변환하여 멀티모달 번역 정확도 향상 🎥🎧✨
            temp_video_path = temp_audio_path.replace(".mp3", ".mp4")
            abs_video_path = os.path.abspath(temp_video_path)
            
            ffmpeg_bin = shutil.which("ffmpeg") or "ffmpeg"
            convert_cmd = [
                ffmpeg_bin, "-y",
                "-f", "lavfi", "-i", "color=c=black:s=320x240:r=1",
                "-i", abs_audio_path,
                "-c:v", "libx264", "-tune", "stillimage",
                "-c:a", "aac", "-b:a", "192k",
                "-pix_fmt", "yuv420p", "-shortest",
                abs_video_path
            ]
            self.log_fn(f" 🎬 [agy CLI] 오디오를 가상 비디오(MP4)로 변환 중... (ffmpeg)")
            try:
                success, stdout, stderr = run_ffmpeg_task(convert_cmd, desc="agy CLI 멀티모달 가상 비디오 생성")
                if not success or not os.path.exists(abs_video_path) or os.path.getsize(abs_video_path) == 0:
                    self.log_fn(f" ⚠️ [agy CLI] 비디오 변환 실패. 원본 MP3 오디오 파일로 계속 진행합니다.")
                    abs_video_path = abs_audio_path
            except Exception as fe:
                self.log_fn(f" ⚠️ [agy CLI] 비디오 변환 중 오류 발생: {fe}. 원본 MP3 오디오 파일로 계속 진행합니다.")
                abs_video_path = abs_audio_path

            # 3. [테스트 6 방식 이식] Gemini와 동일한 재시도 루프 구조 적용 🔄🛡️
            max_retries = 2
            retry_feedback = ""  # 누락 발견 시 덧붙일 피드백 (재시도마다 갱신)

            for attempt in range(max_retries + 1):
                # 재시도 시 피드백 포함한 프롬프트를 파일에 다시 기록
                current_prompt = p_msg_base + retry_feedback
                with open(prompt_txt_path, "w", encoding="utf-8") as f:
                    f.write(current_prompt)

                # @파일경로 방식으로 프롬프트 + 가상 비디오 전달 (테스트 6 성공 방식)
                prompt_arg = f"@{abs_prompt_path} @{abs_video_path}"

                # 재시도마다 새 UUID → DB 락 충돌 원천 차단 🛡️
                conv_id = str(uuid.uuid4())

                retry_suffix = f" (재시도 {attempt}/{max_retries})" if attempt > 0 else ""
                self.log_fn(f"🚀 [agy CLI] 멀티모달 번역 요청 중... (배치: {batch_idx}/{total_batches}, 말뭉치 {count}개){retry_suffix} - 파일: {abs_video_path}")

                # [V200.9 FIX] test_agy_tester.py 성공 공식 1:1 완벽 동기화: conversation_id=None, add_dir=None 으로 일회성 초고속 실행! 🚀⚡

                raw_text = call_agy_cli_sqlite(prompt_arg, conversation_id=conv_id, add_dir=run_cwd, timeout=600, run_cwd=run_cwd)

                if raw_text and raw_text.startswith("⚠️"):
                    # ⚠️ 일시적 에러(DB/CLI 세션) 재시도 허용 🛡️✨
                    self.log_fn(f"⚠️ [agy CLI] 일시적 에러 응답 수신 (시도 {attempt+1}/{max_retries+1}): {raw_text[:120]}")
                    if attempt < max_retries:
                        # [API 절약 스마트 차단] 오디오 음량이 무음/극소 노이즈(-35dB 이하)라면 불필요한 API 재시도 차단! 🛑
                        target_audio = abs_video_path if (abs_video_path and os.path.exists(abs_video_path)) else abs_audio_path
                        mean_v, max_v = _check_fast_volume(target_audio)
                        if mean_v < -35.0 and max_v < -20.0:
                            self.log_fn(f"🛑 [API 절약] 오디오 음량 분석 결과 무음/극소 노이즈 구간(평균 {mean_v:.1f}dB, 최대 {max_v:.1f}dB)으로 판정되어 불필요한 API 재시도를 중단하고 스킵합니다냥! 🔇")
                            return None
                        time.sleep(12)
                        continue
                    return None

                if not raw_text:
                    # 빈 응답은 일시적 문제일 수 있으므로 재시도 허용
                    self.log_fn(f"❌ [agy CLI] 빈 응답 수신 (시도 {attempt+1}/{max_retries+1}), 재시도 대기 중...")
                    if attempt < max_retries:
                        # [API 절약 스마트 차단] 오디오 음량이 무음/극소 노이즈(-35dB 이하)라면 불필요한 API 재시도 차단! 🛑
                        target_audio = abs_video_path if (abs_video_path and os.path.exists(abs_video_path)) else abs_audio_path
                        mean_v, max_v = _check_fast_volume(target_audio)
                        if mean_v < -35.0 and max_v < -20.0:
                            self.log_fn(f"🛑 [API 절약] 무음/극소 노이즈 구간(평균 {mean_v:.1f}dB)으로 판정되어 빈 응답 재시도를 중단하고 스킵합니다냥! 🔇")
                            return None
                        time.sleep(13)
                        continue
                    return None
                missing_indices = []
                for idx in range(1, count + 1):
                    if not re.search(rf'\[0*{idx}\]', raw_text):
                        missing_indices.append(idx)

                if missing_indices and attempt < max_retries:
                    self.log_fn(f"⚠️ [agy CLI] [Batch {batch_idx}] 번호 누락 발견 {missing_indices}. (AI 피드백 후 재시도합니다...)")
                    # [BugFix Gemini 방식] retry_feedback에만 누적, p_msg_base 오염 없음 🛡️
                    retry_feedback = f"\r\n\r\nIMPORTANT: In your previous attempt, you missed these segment numbers: {missing_indices}. This time, you MUST include ALL numbers from [1] to [{count}] without exception."
                    time.sleep(12)
                    continue

                if missing_indices:
                    self.log_fn(f"🚨 [agy CLI] [Batch {batch_idx}] 총 {attempt+1}번 시도했으나 {missing_indices}번은 끝내 침묵했어냥... 후처리를 진행합니다. 🩹")

                # 4. 결과 파싱 및 가공 (지능형 서브스트링 중복 제거 보강)
                parsed_list = self.parse_translations(raw_text, count)
                cleaned_list = []
                for i, item in enumerate(parsed_list):
                    idx = i + 1
                    sub_lines = []
                    seen_norm = []
                    def normalize_for_dedup(s):
                        return re.sub(r'[^가-힣a-zA-Z0-9]', '', s).strip()

                    for line in item.split('\r\n'):
                        clean_l = re.sub(rf'\[0*{idx}\]\s*', '', line).strip()
                        if clean_l:
                            norm = normalize_for_dedup(clean_l)
                            is_dup = False
                            for s_idx, ext in enumerate(seen_norm):
                                ext_norm = normalize_for_dedup(ext)
                                if not ext_norm or not norm: continue
                                if len(norm) <= len(ext_norm):
                                    if norm in ext_norm:
                                        is_dup = True
                                        break
                                else:
                                    if ext_norm in norm:
                                        sub_lines[s_idx] = clean_l
                                        seen_norm[s_idx] = clean_l
                                        is_dup = True
                                        break
                                    # 접두사 60% 이상 매치 시 중복 처리 (오타 대응)
                                    common_prefix = ""
                                    for char_a, char_b in zip(norm, ext_norm):
                                        if char_a == char_b: common_prefix += char_a
                                        else: break
                                    if len(common_prefix) >= 4:
                                        short_len = min(len(norm), len(ext_norm))
                                        if (len(common_prefix) / short_len >= 0.6) or (len(common_prefix) >= 6):
                                            if len(norm) > len(ext_norm):
                                                sub_lines[s_idx] = clean_l
                                                seen_norm[s_idx] = clean_l
                                            is_dup = True
                                            break
                            if not is_dup:
                                sub_lines.append(clean_l)
                                seen_norm.append(clean_l)
                    
                    clean_item = "\r\n".join(sub_lines).strip()

                    clean_item = clean_agent_chatter_and_emojis(clean_item)

                    cleaned_list.append(clean_item if clean_item else "...")

                missing_final = [i+1 for i, item in enumerate(cleaned_list) if item == "..."]
                if missing_final:
                    self.log_fn(f"🩹 [agy CLI] [Batch {batch_idx}] 최종 누락 발생: {missing_final}번은 데이터가 없어 '...'으로 채웠어냥!")

                return cleaned_list

            # 재시도 루프 소진 시 None 반환
            return None
            
        except Exception as e:
            self.log_fn(f"❌ [agy CLI] 예외 발생: {e}")
            return None
        finally:
            # 임시 파일 및 디렉토리 정리
            try:
                if os.path.exists(run_cwd):
                    shutil.rmtree(run_cwd)
            except Exception as e:
                _log_to_file(f"⚠️ [agy Cleanup Failed] {run_cwd}: {e}")

    # [TAG: #@__init___10]
    def __init__(self, api_keys: List[str], model_name: str, log_fn: Optional[Callable[[str], None]] = None):
        load_heavy_modules()
        # [V146.0] 인스턴스 전용 키 변수를 전역 변수와 동기화하여 통합 관리합니다. 🤝
        # [V16.5.6] model_name 속성 통합 (AttributeError 방지) 및 하위 호환성 유지 🤝✨
        self.model_name = model_name
        self.current_model_name = model_name
        self.log_fn = log_fn or print
        self.keep_brackets = False

        # 전역 키 설정 적용 (ZeroDivisionError 방지 가드 추가) 🛡️
        if API_KEYS and len(API_KEYS) > 0:
            # [V147.232] 전역 인덱스가 키 목록 범위를 벗어날 경우 대비하여 나머지 연산(%) 적용 🛡️✨
            genai.configure(api_key=API_KEYS[API_KEY_IDX % len(API_KEYS)])
        else:
            self.log_fn("⚠️ [AIAgent] 사용 가능한 API 키가 없습니다. 로컬 모드 또는 CLI 모드만 작동 가능할 수 있습니다.")

        self.safety_settings = [
            {"category": "HARM_CATEGORY_HARASSMENT", "threshold": "BLOCK_NONE"},
            {"category": "HARM_CATEGORY_HATE_SPEECH", "threshold": "BLOCK_NONE"},
            {"category": "HARM_CATEGORY_SEXUALLY_EXPLICIT", "threshold": "BLOCK_NONE"},
            {"category": "HARM_CATEGORY_DANGEROUS_CONTENT", "threshold": "BLOCK_NONE"},
        ]
        self.system_instruction = "You are a Master Korean Video Translator. ALWAYS translate natural, human-like Korean. ALWAYS output valid JSON."

    # [TAG: #@rotate_key]
    def rotate_key(self) -> bool:
        """[V146.0] API 키 로테이션을 전역 통합 로직으로 위임합니다. 🤝"""
        return rotate_api_key_global(API_KEY_IDX)

    # [TAG: #@get_model]
    def get_model(self, model_name_override: Optional[str] = None, temp: float = 0.2, max_tokens: int = 8192, use_json: bool = True):
        """설정된 파라미터로 GenerativeModel 인스턴스를 생성하여 반환합니다."""
        model_name = model_name_override or self.current_model_name

        # [V7.9] 타입 힌트 오류를 피하기 위해 GenerationConfig 인자를 직접 구성
        if use_json:
            config = genai.types.GenerationConfig(
                temperature=temp,
                max_output_tokens=max_tokens,
                response_mime_type="application/json"
            )
        else:
            config = genai.types.GenerationConfig(
                temperature=temp,
                max_output_tokens=max_tokens
            )
        # [V24.2] Gemini 세분화 모델 ID 매핑
        gemini_map = {
            "gemini_flash_lite": "gemini-3.1-flash-lite",
            "gemini_flash": "gemini-3.5-flash",
            "gemini_pro": "gemini-3.1-pro-preview",
            "gemini_25_flash": "gemini-3.5-flash",
            "gemini": "gemini-2.5-flash-lite" # 하위 호환
        }
        model_name = gemini_map.get(model_name, model_name)

        return genai.GenerativeModel(
            model_name=model_name,
            system_instruction=self.system_instruction,
            safety_settings=self.safety_settings,
            generation_config=config
        )

    # [TAG: #@execute_gemini_chat]
    def execute_gemini_chat(self, user_text: str, model_name: Optional[str] = None, status_fn: Optional[Callable[[str], None]] = None) -> str:
        """[V24.3] Gemini API를 이용한 지능형 챗봇 응답 및 명령어 매핑 (복합 명령 대응)"""
        try:
            # 시스템 프롬프트 구성 (로컬 Gemma와 동일한 가이드 공유)
            chat_instruction = f"""You are a helpful AI assistant for 'Binu PC Control System'.
The user's name is '{USER_NAME}'. Talk in a friendly, polite Korean (해요체).
Use emojis often! 👍✨

### PROGRAM INFO
This program is for SRT subtitle translation and PC control via Telegram.
Available commands for user: /start, /app_on, /server, /mypc

### PC CONTROL CAPABILITIES
You can execute PC commands by including [EXEC:command_id] or [EXEC:command_id:parameter] in your response.
Available command IDs:
- app_on: 프로그램 실행/켜기
- app_off: 프로그램 종료/끄기
- app_restart: 프로그램 재시작
- pc_menu: PC 제어 메뉴/리모컨 호출
- pc_media_stop: 모든 미디어 앱 종료
- pc_vol_up / pc_vol_down / pc_mute: 볼륨 제어 (UP/DOWN/MUTE)
- pc_pause: 재생/일시정지
- pc_prev / pc_next: 이전/다음 곡
- pc_mon_off / pc_mon_on: 모니터 끄기/켜기
- pc_screenshot: 화면 캡쳐
- pc_sleep:N : N분 뒤에 깨어나도록 예약하며 즉시 절전 모드 진입 (예: [EXEC:pc_sleep:90])

### IMPORTANT RULES
1. If the user asks for sleep/standby with a duration (e.g. "90분 뒤에 켜줘", "1시간 뒤 절전"), use [EXEC:pc_sleep:minutes].
2. If it's just "절전해줘", use [EXEC:pc_sleep:0].
3. Only use commands if the user clearly requests them.
4. If you're unsure, just chat normally without [EXEC]."""

            full_prompt = f"{chat_instruction}\r\n\r\nUser Question: {user_text}"
            # 통합 ask_ai 호출 (챗봇은 일반 텍xt 응답 선호)
            res_text = ask_ai(full_prompt, model=model_name or self.current_model_name, temp=0.7) # 챗봇은 약간의 창의성(0.7) 부여

            if res_text:
                return res_text.strip()
            return "🤖 미안해, 대답을 생성하지 못했어. 😢"
        except Exception as e:
            self.log_fn(f"⚠️ [Gemini Chat] 오류: {e}")
            return f"⚠️ [Gemini Chat] API 오류가 발생했어: {e}"

    # [V81.0] Ollama 설치 상태 체크 및 모델 자동 수혈 헬퍼 🔍🐙
    # [TAG: #@_check_ollama_runtime]
    def _check_ollama_runtime(self) -> bool:
        """시스템에 Ollama가 설치되어 있는지 확인합니다."""

        # 1. PATH에서 확인
        try:
            subprocess.run(["ollama", "--version"], capture_output=True, check=True)
            return True
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

        # 2. 윈도우 표준 설치 경로 확인
        appdata = os.environ.get("LOCALAPPDATA", "")
        paths = [
            os.path.join(appdata, "Ollama", "ollama.exe"),
            r"C:\Program Files\Ollama\ollama.exe",
            r"C:\Program Files (x86)\Ollama\ollama.exe"
        ]
        for p in paths:
            if os.path.exists(p): return True

        return False

    # [TAG: #@_ensure_ollama_running]
    def _ensure_ollama_running(self) -> bool:
        """[V82.9] 글로벌 통합 함수를 호출합니다. 🛠️🔄"""
        return _ensure_ollama_server()

    # [TAG: #@_is_local_model_present]
    def _is_local_model_present(self, model_name: str) -> bool:
        """[V82.9] 모델이 로컬에 있는지 하이브리드(API + 파일시스템)로 체크합니다. 📁🔍"""
        import requests
        # 1. API 체크
        try:
            resp = requests.get("http://localhost:11434/api/tags", timeout=3)
            if resp.ok:
                local_names = [m.get('name') for m in resp.json().get('models', [])]
                if model_name in local_names or f"{model_name}:latest" in local_names:
                    return True
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

        # 2. 파일 시스템 직접 체크 (Registry Fallback)
        try:
            base = model_name.split(':')[0]
            tag = model_name.split(':')[1] if ':' in model_name else "latest"
            manifest_path = os.path.expanduser(f"~/.ollama/models/manifests/registry.ollama.ai/library/{base}/{tag}")
            if os.path.exists(manifest_path): return True
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")
        return False

    # [TAG: #@_ensure_ollama_model]
    def _ensure_ollama_model(self, model_name: str) -> str:
        """[V82.9] 지능형 모델 매핑 및 기동 보증 🛰️✨"""
        if not self._ensure_ollama_running():
            return model_name

        # [V82.9] 실제 태그가 붙은 모델명 찾기 (gemma4 -> gemma4:local 등)
        target_tag = _find_ollama_model_tag(model_name)

        # 모델이 존재하면 즉시 반환
        if self._is_local_model_present(target_tag):
            return target_tag

        # 2. 모델이 없음 -> 설치 유도 (콘솔 전용)
        # [V81.7] UI 자물쇠 획득: 다른 메시지 요청이 동시에 들어와도 하나씩 처리하도록 보강 🔐✨
        with G_CONSOLE_UI_LOCK:
            # 자물쇠를 얻은 직후, 다른 스레드가 이미 설치했을 수도 있으므로 재확인 🕵️‍♂️
            if self._is_local_model_present(model_name):
                return model_name

            # [V81.7] 입력을 받기 전 버퍼 찌꺼기 청소 (msvcrt 활용) 🧹✨
            try:
                import msvcrt
                while msvcrt.kbhit(): msvcrt.getch()
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

            _clear_console_buffer(5)
            print(f" {C.BOLD}{C.PURPLE}================================================================={C.RESET}")
            print(f" ⚠️  {C.YELLOW}사용자님! '{model_name}' 모드용 모델({target_tag})이 로컬에 없어냥! {C.RESET}😿")
            print(f" ✨ {C.SKY}최신 젬마4(Gemma 4)로 바로 수혈해줄까냥?{C.RESET} (gemma4:e2b 추천!)")
            print(f" {C.BOLD}{C.PURPLE}================================================================={C.RESET}\r\n")

            opts = [
                " 🐙 gemma4:e2b (초경량/고성능) ✨",
                " 🐙 gemma4:e4b (밸런스형) 🚀",
                " 🐙 gemma4:26b (대용량/똑똑함) 🧠",
                " 🐙 gemma4:31b (최강 성능) 🏆",
                " ✍️  모델 이름 직접 입력하기 (gemma4:local 등) ⌨️",
                " ❌ 취소할래냥! (대화 종료)"
            ]
            tags = ["gemma4:e2b", "gemma4:e4b", "gemma4:26b", "gemma4:31b", "__MANUAL__", None]

            for i, opt in enumerate(opts, 1):
                print(f"  {i}. {opt}")

            try:
                sel = prompt_input(f"\r\n {C.GREEN}사이즈 번호를 입력해줘냥 (취소: c):{C.RESET} ").strip().lower()
                if sel == 'c':
                    print(f" 👋 {C.DIM}알았어냥! 설치를 취소할게냥. {C.RESET}")
                    return model_name

                if not sel.isdigit() or not (1 <= int(sel) <= 6):
                    print(f" ❌ {C.RED}번호를 잘못 입력했어냥! 1번부터 6번 사이로 골라줘냥! {C.RESET}")
                    time.sleep(1.5)
                    return model_name

                choice_idx = int(sel) - 1
                target_tag = tags[choice_idx]

                if target_tag is None:
                    print(f" 👋 {C.DIM}알았어냥! 설치를 취소할게냥. {C.RESET}")
                    return model_name

                if target_tag == "__MANUAL__":
                    manual_tag = prompt_input(f"\r\n {C.SKY}✍️ 사용할 모델 태그를 입력해줘냥 (예: gemma4:local):{C.RESET} ").strip()
                    if not manual_tag: return model_name
                    return manual_tag

                # 설치 시작 전 최종 확인 (혹시 모를 중복 방지)
                if self._is_local_model_present(target_tag):
                    print(f"\r\n ✅ {C.GREEN}'{target_tag}'는 이미 수혈되어 있어냥! 대화하러 가자냥! {C.RESET}😻")
                    prompt_input(f" {C.DIM}(엔터를 누르면 계속해냥...) {C.RESET}")
                    return target_tag

                # 3. 모델 설치 (ollama pull) 📥
                print(f"\r\n 🚀 {C.SKY}Ollama 수혈 시작! '{target_tag}' 설치 중이다냥... 잠시만 기다려줘냥! {C.RESET}✨")
                print(f" {C.DIM}(설치 완료 후 자동으로 대화가 이어져냥!) {C.RESET}")

                subprocess.run(f"ollama pull {target_tag}", shell=True)

                # [V81.7] 설치 완료 후 버퍼 정리 및 사용자 확인 유도 🐾✨
                print(f"\r\n ✅ {C.GREEN}'{target_tag}' 수혈 완료! 이제 준비가 다 되었어냥! {C.RESET}😻")

                try:
                    while msvcrt.kbhit(): msvcrt.getch()
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")

                prompt_input(f" {C.BOLD}{C.SKY}📣 계속하려면 엔터를 눌러주세요냥!{C.RESET} ")

                return target_tag

            except KeyboardInterrupt:
                print("\r\n ❌ 중단되었어냥!")
                return model_name


    # [TAG: #@stream_chat]
    def stream_chat(self, prompt: str, model_name: Optional[str] = None) -> Generator[str, None, None]:
        """[V43.0] 여러 LLM(Gemini, 로컬 Gemma, Colab)을 통합하여 스트리밍 응답을 생성합니다. ✨"""
        model_name = model_name or self.current_model_name

        # 1. 로컬 Gemma 모델 스트리밍 (Gemma-3, Gemma-4 지원 ✨)
        if model_name in ["gemma-local", "gemma-3-4b-it", "gemma3_4b", "gemma4_2b", "gemma-4-2b-it"]:
            try:
                g_size = "2b_it" if "2b" in model_name else "4b_it"
                for chunk in self.execute_local_gemma_chat_stream(prompt, gemma_size=g_size):
                    yield chunk
            except Exception as e:
                yield f"⚠️ [Local Gemma Stream Error] {e}"

        # 2. Gemini API 스트리밍 (통합 ask_ai 활용 ✨)
        elif any(x in model_name for x in ["gemini", "flash", "pro"]):
            try:
                response = ask_ai(prompt, model=model_name, stream=True)
                if response:
                    for chunk in response:
                        if hasattr(chunk, 'text') and chunk.text:
                            yield chunk.text
            except Exception as e:
                yield f"⚠️ [Gemini Stream Error] {e}"

        # 3. Ollama 스트리밍 연동 (V80.8) 🐙
        elif "ollama" in model_name:
            try:
                for chunk in self.execute_local_ollama_chat_stream(prompt, model_name=model_name.replace("local_ollama_", ""), custom_prompt=prompt):
                    yield chunk
            except Exception as e:
                yield f"⚠️ [Ollama Stream Error] {e}"

        # 4. Colab 또는 기타 (단발성 응답을 스트리밍으로 전환) 🌐
        else:
            try:
                # Colab 주소가 프롬프트에 포함되어 있지 않으므로, 호출자가 URL을 관리하거나
                # AIAgent가 설정에서 가져와야 함. 여기서는 단순 ask_simple로 대체하거나
                # 필요시 전용 콜백을 사용하도록 구현.
                res = self.ask_simple(prompt)
                # 글자 단위로 쪼개서 스트리밍 효과 부여
                chunk_size = 8
                for i in range(0, len(res), chunk_size):
                    yield res[i:i+chunk_size]
                    time.sleep(0.05)
            except Exception as e:
                yield f"⚠️ [Stream Fallback Error] {e}"

    # [TAG: #@_get_local_llm]
    def _get_local_llm(self, gemma_size: str):
        """[V44.0] 글로벌 캐시에서 로컬 LLM 인스턴스를 가져오거나 새로 로드하여 반환합니다. 🧠"""
        global GLOBAL_LLM_STORAGE
        import llama_cpp
        model_path = self._ensure_local_gemma(gemma_size)

        if gemma_size not in GLOBAL_LLM_STORAGE:
            n_gpu = 0
            try:
                import torch
                if torch.cuda.is_available(): n_gpu = -1
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

            with LoadingSpinner(f"💎 로컬 Gemma-{gemma_size} 모델 로딩 중..."):
                # [V80.8] AttributeError: 'LlamaModel' object has no attribute 'sampler' 완벽 방지 🛡️
                # 초기화 실패 시 가비지 컬렉터의 2차 에러를 막기 위해 원본 예외를 세밀하게 가로챕니다.
                try:
                    with contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()):
                        llm_temp = llama_cpp.Llama(
                            model_path=model_path,
                            n_ctx=4096,
                            n_gpu_layers=n_gpu,
                            verbose=False
                        )
                        GLOBAL_LLM_STORAGE[gemma_size] = llm_temp
                except (Exception, TypeError, AttributeError) as e:
                    # [V80.8] 범인 포착! 진짜 에러를 로그에 남기고 사용자에게 알림 🕵️‍♂️
                    err_trace = traceback.format_exc()
                    _log_to_file(f"❌ [Llama Loader Error] {e}\r\n{err_trace}")

                    err_msg = str(e).lower()
                    # Gemma 4 등 최신 아키텍처 지원 여부 판단 🚀
                    if "version" in err_msg or "unsupported" in err_msg or "unknown" in err_msg or "sampler" in err_msg:
                        raise RuntimeError("로컬 엔진이 젬마4를 아직 이해하지 못해냥! 🙀\r\n\r\n💡 **해결 방법:**\r\nAI냥 설정 메뉴(1번) -> **`⚙️ 로컬 엔진 업데이트(9번)`**를 눌러서 엔진을 수혈해주면 해결된다냥! 🛠️✨")
                    else:
                        raise RuntimeError(f"로컬 모델 로딩에 실패했어냥! 😿 ({e})\r\n사양 부족이거나 파일 손상일 수 있어냥!")
        return GLOBAL_LLM_STORAGE[gemma_size]

    # [TAG: #@execute_local_gemma_chat_stream]
    def execute_local_gemma_chat_stream(self, prompt: str, gemma_size: str = "4b_it") -> Generator[str, None, None]:
        """[V44.0] 로컬 Gemma 모델을 사용하여 스트리밍 응답을 생성합니다 (글로벌 싱글톤 활용) ✨"""
        try:
            try:
                llm = self._get_local_llm(gemma_size)
            except (TypeError, AttributeError) as te:
                # [V80.7] 로딩 단계 실패(sampler 에러 등) 가로채기 🕵️‍♂️
                _log_to_file(f"❌ [Llama Stream Internals Error] Clean-up failed: {te}")
                yield f"⚠️ 로컬 엔진이 이 모델({gemma_size})을 아직 이해하지 못해냥! 🙀 엔진 업데이트(pip install -U llama-cpp-python)가 필요할 것 같아냥!"
                return

            # stop_tokens 에 주인님: 추가하여 루프 방지 🛡️
            stop_tokens = ["user", "주인님:", "<|im_end|>", "<end_of_turn>", "<|eot_id|>", "<eos>"]

            with LLM_SEMAPHORE:
                stream = llm(
                    prompt,
                    max_tokens=2048,
                    stop=stop_tokens,
                    temperature=0.7,
                    stream=True
                )
                for chunk in stream:
                    token = chunk["choices"][0]["text"]
                    if token:
                        yield token
        except Exception as e:
            err_trace = traceback.format_exc()
            _log_to_file(f"❌ [Local Gemma Stream Error] Full Trace:\r\n{err_trace}")
            yield f"⚠️ [Local Gemma Stream] 오류: {e}"


    # [TAG: #@execute_local_ollama_chat]
    def execute_local_ollama_chat(self, user_text: str, model_name: str = "gemma4:e2b", custom_prompt: str = None) -> str:
        """[V81.9] 로컬 Ollama API를 이용한 단발성 채팅 (인내심/재시도 로직 강화) 🐙💉"""
        import requests
        import time as _time

        # [V81.1] 대화 시작 전 모델 존재 여부 체크 및 자동 수혈 💉✨
        model_name = self._ensure_ollama_model(model_name)

        url = "http://localhost:11434/api/generate" if custom_prompt else "http://localhost:11434/api/chat"
        payload = {
            "model": model_name,
            "stream": False,
            "options": {"temperature": 0.7}
        }
        if custom_prompt: payload["prompt"] = custom_prompt
        else: payload["messages"] = [{"role": "user", "content": user_text}]

        max_retries = 3
        retry_delay = 5

        for attempt in range(max_retries + 1):
            try:
                with LLM_SEMAPHORE:
                    # [V81.9] 타임아웃을 180초로 연장 (노트북이 힘들어할 때를 대비 🐢✨)
                    resp = requests.post(url, json=payload, timeout=180)

                if resp.ok:
                    res_json = resp.json()
                    return res_json.get("response", "") if custom_prompt else res_json.get("message", {}).get("content", "")

                if resp.status_code == 404:
                    return f"⚠️ [Ollama] '{model_name}' 모델을 찾을 수 없어냥! 😿 콘솔에서 재설치가 필요해냥! ✨"

            except Exception as e:
                err_msg = str(e).lower()
                # 연결 거부(10061)나 타임아웃 시 재시도
                if attempt < max_retries and ("connection" in err_msg or "10061" in err_msg or "timeout" in err_msg):
                    self.log_fn(f"⚠️ [Ollama] 연결 지연 중... {attempt+1}차 재시도할게냥! (조금만 더 힘내줘냥! 💪)")
                    _time.sleep(retry_delay)
                    continue

                if "connection" in err_msg or "10061" in err_msg:
                    return "😿 **노트북이 Ollama를 감당하지 못하고 있어냥!**\r\n\r\n1️⃣ **리소스 확인:** 다른 프로그램(크롬 등)을 조금 닫아주면 도움이 될 거야냥!\r\n2️⃣ **Ollama 재시작:** 트레이 아이콘에서 Ollama를 껐다 켜주면 다시 좋아질 수 있어냥!\r\n3️⃣ **다시 시도:** 젬마4가 무거워서 로딩에 시간이 걸리는 거니 잠시 후 다시 말을 걸어줘냥! ✨"
                return f"⚠️ [Ollama Exception] {e}"

        return "🤖 미상 오류로 대답을 못 했어냥. 😿"

    # [TAG: #@execute_local_ollama_chat_stream]
    def execute_local_ollama_chat_stream(self, user_text: str, model_name: str = "gemma4:e2b", custom_prompt: str = None) -> Generator[str, None, None]:
        """[V81.9] 로컬 Ollama API를 이용한 실시간 스트리밍 채팅 (인내심/재시도 강화) ✨"""
        import requests
        import time as _time

        model_name = self._ensure_ollama_model(model_name)
        url = "http://localhost:11434/api/generate" if custom_prompt else "http://localhost:11434/api/chat"
        payload = {
            "model": model_name,
            "stream": True,
            "options": {"temperature": 0.7}
        }
        if custom_prompt: payload["prompt"] = custom_prompt
        else: payload["messages"] = [{"role": "user", "content": user_text}]

        max_retries = 3
        for attempt in range(max_retries + 1):
            try:
                with LLM_SEMAPHORE:
                    # [V81.9] 스트리밍 타임아웃 연장 (180초)
                    resp = requests.post(url, json=payload, stream=True, timeout=180)

                if resp.ok:
                    for line in resp.iter_lines():
                        if line:
                            chunk = json.loads(line.decode('utf-8'))
                            token = chunk.get("response", "") if custom_prompt else chunk.get("message", {}).get("content", "")
                            if token: yield token
                            if chunk.get("done"): break
                    return # 성공 시 종료
                else:
                    if resp.status_code == 404:
                        yield f"⚠️ [Ollama] '{model_name}' 모델을 찾을 수 없어냥! 😿"
                        return
            except Exception as e:
                err_msg = str(e).lower()
                if attempt < max_retries and ("connection" in err_msg or "10061" in err_msg or "timeout" in err_msg):
                    yield f"⏳ [Ollama] 노트북이 힘들어해서 다시 문을 두드리고 있어냥... ({attempt+1}/{max_retries}) ✨"
                    _time.sleep(5)
                    continue
                yield f"⚠️ [Ollama Stream Exception] {e}"
                return

    # [TAG: #@execute_colab_chat]
    def execute_colab_chat(self, url: str, prompt: str) -> str:
        """[V80.8] 코랩 서버와 통신하여 채팅 응답을 가져옵니다. 🌐"""
        try:
            import requests
            headers = {"Bypass-Tunnel-Reminder": "true"}
            with LLM_SEMAPHORE:
                # [V90.2] 대화가 길어질 경우(Pre-filling)를 대비하여 타임아웃을 180초(3분)로 대폭 연장 ⏱️✨
                resp = requests.post(f"{url.rstrip('/')}/chat", json={"prompt": prompt}, headers=headers, timeout=180)

            if resp.ok:
                res_data = resp.json()
                if resp.status_code == 202 and res_data.get("status") == "loading":
                    return f"냥...! {res_data.get('message', '지금 열심히 공부(로딩)하고 있다냥! 잠시만 기다려줘냥! ✨')}"
                return res_data.get("response", "").strip()
            return f"⚠️ [Colab Error] HTTP {resp.status_code}"
        except Exception as e:
            return f"⚠️ [Colab Exception] {e}"

    # [TAG: #@execute_agy_cli_chat]
    def execute_agy_cli_chat(self, prompt: str, system_prompt: str = None) -> str:
        """[V205.0] agy CLI(Antigravity CLI)를 호출하여 AI냥 챗봇 대화 응답을 생성하고 깨끗하게 파싱합니다. 🤖🐱✨"""
        try:
            import tempfile, uuid, os, shutil, re
            temp_base = os.path.join(os.getcwd(), "temp")
            if not os.path.exists(temp_base):
                os.makedirs(temp_base, exist_ok=True)
            run_cwd = tempfile.mkdtemp(prefix=f"agy_cat_pid{os.getpid()}_", dir=temp_base)
            prompt_file = os.path.join(run_cwd, "chat_prompt.txt")

            # 챗봇 전용 페르소나 감지 및 자동 추출/폴백 🛡️🐱
            resolved_persona = system_prompt
            if not resolved_persona:
                m_sys = re.search(r'<\|im_start\|>system\r?\n(.*?)(?:<\|im_end\|>|$)', prompt, flags=re.DOTALL)
                if m_sys:
                    resolved_persona = m_sys.group(1).strip()
            if not resolved_persona:
                try:
                    if hasattr(self, "settings") and self.settings and hasattr(self.settings, "data"):
                        resolved_persona = self.settings.data.get("cat_persona", "")
                except Exception:
                    pass
            if not resolved_persona:
                try:
                    from core.settings import settings as _g_settings
                    resolved_persona = _g_settings.data.get("cat_persona", "")
                except Exception:
                    pass
            if not resolved_persona:
                resolved_persona = "너는 다정하고 귀여운 츤데레 고양이 'AI냥'이야. 말투 끝에 '~냥'을 붙이고, 주인님을 무척 아끼며 도도하면서도 천진난만하게 대답해줘냥! 절대 코딩 비서나 개발 파트너라고 하지 말고 100% 고양이 챗봇으로 몰입해줘냥! ✨🐱💎"

            # 챗봇 전용 가드레일: agy가 코딩 도구를 쓰지 않고 페르소나 대화에만 100% 집중하도록 강제 🛡️
            guardrail_prompt = (
                "[CRITICAL SYSTEM MANDATE: 100% CHATBOT ROLEPLAY IMMERSION — NO CODING, NO TOOLS]\r\n"
                "- You are strictly in conversational chatbot roleplay mode.\r\n"
                "- ABSOLUTE PROHIBITION: NEVER introduce yourself as a coding assistant, developer partner, programming AI, or Antigravity/Google tool. You are NOT a coding agent!\r\n"
                "- You must 100% faithfully adopt and immerse into the assigned persona below:\r\n"
                "--------------------------------------------------\r\n"
                f"{resolved_persona}\r\n"
                "--------------------------------------------------\r\n"
                "- Speak naturally in Korean as your assigned persona. Use rich emojis! ✨💖\r\n"
                "- ABSOLUTE RULE: DO NOT CALL ANY TOOLS (e.g. run_command, view_file, write_to_file, replace_file_content, search_web, manage_task).\r\n"
                "- Any tool call will immediately crash the conversation. Just output your spoken reply text directly.\r\n"
                "- NO META/THINKING PROCESS: Do not output thinking process, analysis tags, or planning headers.\r\n"
                "- Reply immediately with only the direct spoken response.\r\n\r\n"
                f"{prompt}"
            )

            with open(prompt_file, "w", encoding="utf-8") as pf:
                pf.write(guardrail_prompt)

            abs_prompt_path = os.path.abspath(prompt_file)
            prompt_arg = f"@{abs_prompt_path}"
            conv_id = str(uuid.uuid4())

            try:
                # 6, 7번 메뉴의 핵심 엔진인 call_agy_cli_sqlite 호출! (채팅 모드이므로 콘솔 스트리밍은 quiet=True) 🚀
                raw_text = call_agy_cli_sqlite(
                    prompt_arg,
                    conversation_id=conv_id,
                    add_dir=run_cwd,
                    timeout=120,
                    run_cwd=run_cwd,
                    quiet=True
                )

                if raw_text and not raw_text.startswith("⚠️"):
                    # 생각 블록 및 아티팩트 정제 🧼
                    clean_text = raw_text.replace('\r\n', '\n').replace('\r', '\n')
                    paragraphs = clean_text.split("\n\n")
                    cleaned_p = []
                    for p in paragraphs:
                        p_strip = p.strip()
                        if p_strip.startswith("**"):
                            hm = re.match(r'^\*\*([A-Za-z\s\'\-\:\(\)]+)\*\*', p_strip)
                            if hm:
                                h_low = hm.group(1).lower()
                                if any(ti in h_low for ti in ["analyz", "summariz", "consider", "think", "thought", "plan", "process", "checking", "evaluat", "prepar", "understand"]):
                                    continue
                        cleaned_p.append(p)
                    result_text = "\n\n".join(cleaned_p).strip()

                    # XML 스타일 태그 (<thought>...</thought> 등) 제거
                    result_text = re.sub(r'<(thinking|thought)>.*?</\1>', '', result_text, flags=re.IGNORECASE | re.DOTALL).strip()
                    # ANSI escape 코드 정리
                    result_text = re.sub(r'\x1b\[[0-9;]*[mGKHF]|\x1b\].*?\x07|\x1b\[\?[0-9;]*[hl]', '', result_text).strip()

                    # 마크다운 코드블럭 (```text ... ``` 등)으로 감싸져 있을 경우 unwrap 📦✨
                    m_code = re.match(r'^```(?:[a-zA-Z0-9_\-]+)?\s*\n(.*?)\n```$', result_text, flags=re.DOTALL)
                    if m_code:
                        result_text = m_code.group(1).strip()

                    return result_text if result_text else raw_text.strip()

                if raw_text:
                    return raw_text
                return "냥...? (agy로부터 대답을 듣지 못했다냥)"
            finally:
                shutil.rmtree(run_cwd, ignore_errors=True)
        except Exception as e:
            return f"⚠️ [agy CLI Chat Error] {e}"

    # [TAG: #@execute_gemini_cli_chat]
    def execute_gemini_cli_chat(self, prompt: str) -> str:
        """[V80.8] 제미나이 CLI 랩핑을 통해 응답을 가져옵니다. 🤖"""
        try:
            import tempfile
            # [V147.157] 사용자님 요청: PID 기반 독립 폴더 생성 🛡️
            temp_base = os.path.join(os.getcwd(), "temp")
            if not os.path.exists(temp_base): os.makedirs(temp_base, exist_ok=True)
            run_cwd = tempfile.mkdtemp(prefix=f"gemcli_cat_pid{os.getpid()}_", dir=temp_base)
            try:
                cmd_str = f'gemini.cmd -o text -y -m {GEMINI_CLI_DEFAULT_MODEL} -p ""' if os.name == 'nt' else f'gemini -o text -y -m {GEMINI_CLI_DEFAULT_MODEL} -p ""'
                env = os.environ.copy()
                res = subprocess.run(cmd_str, input=prompt, text=True, capture_output=True, encoding='utf-8', timeout=600, cwd=run_cwd, shell=True, env=env)
                if res.returncode == 0:
                    stdout = res.stdout.strip()
                    lines = stdout.splitlines()
                    if lines and "Loaded cached credentials" in lines[0]:
                        stdout = "\r\n".join(lines[1:]).strip()
                    return stdout
                return f"⚠️ [Gemini CLI Error] Code: {res.returncode}"
            finally:
                shutil.rmtree(run_cwd, ignore_errors=True)
        except Exception as e:
            return f"⚠️ [Gemini CLI Exception] {e}"

    # [TAG: #@ask_simple]
    def ask_simple(self, prompt: str, status_fn: Optional[Callable[[str], None]] = None) -> str:
        """[V145.0] 간단한 질문을 통합 ask_ai로 위임합니다. 🤝"""
        if callable(status_fn): status_fn(f"🧠 3. AI 분석 중 ({_get_ai_key_label()})...")
