    # [TAG: #@generate_content]
    def generate_content(self, contents: list, generation_id: str = "Request", model_name_override: Optional[str] = None, temp: float = 0.2, max_tokens: int = 8192, status_fn: Optional[Callable[[str], None]] = None):
        """[V144.0] AIAgent의 생성을 통합 ask_ai로 위임합니다. 🤝"""
        if status_fn: status_fn(f"🧠 3. AI 번역 중 ({generation_id} / {_get_ai_key_label()})...")

        # 모델 정보 확보
        target_model = model_name_override or self.current_model_name

