class PendingQueue:
    """PID 기반 대기열 관리. 각 인스턴스는 pending_files_{PID}.txt를 사용하여
    여러 스크립트가 동시에 실행되어도 서로의 대기열을 침범하지 않습니다."""

    QUEUE_PREFIX = "pending_files"  # pending_files_12345.txt 형식

    # [TAG: #@__init___15]
    def __init__(self, filepath=None):
        if filepath is None:
            filepath = f"{self.QUEUE_PREFIX}_{os.getpid()}.txt"
        self.filepath = filepath

    # [TAG: #@load]
    def load(self) -> List[str]:
        if not os.path.exists(self.filepath):
            return []
        try:
            with open(self.filepath, "r", encoding="utf-8") as f:
                return [line.strip() for line in f.read().split('\r\n') if line.strip()]
        except Exception:
            return []

    # [TAG: #@save]
    def save(self, paths: List[str]):
        try:
            with open(self.filepath, "w", encoding="utf-8") as f:
                f.write("\r\n".join(paths) + "\r\n")
        except Exception as e:
            try: _log_to_file(f"⚠️ [Silent Error Handled] {e}")
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

    # [TAG: #@remove]
    def remove(self, path: str):
        paths = self.load()
        if path in paths:
            paths.remove(path)
            if paths:
                self.save(paths)
            else:
                self.clear()

    # [TAG: #@clear_2]
    def clear(self):
        if os.path.exists(self.filepath):
            try:
                safe_remove_file(self.filepath)
            except Exception as e:
                try: _log_to_file(f"⚠️ [Silent Error Handled] {e}")
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")

    # ==================================================================
    # 정적 유틸리티: 고아 큐 탐지 / PID 생존 확인 / 전체 큐 스캔
    # ==================================================================
    @staticmethod
    # [TAG: #@_is_pid_alive]
    def _is_pid_alive(pid: int) -> bool:
        """주어진 PID의 프로세스가 아직 실행 중인지 확인합니다. (Windows 최적화)"""
        if pid <= 0:
            return False
        try:
            if os.name == 'nt':
                # [V16.4.1] tasklist 대신 Win32 API를 사용하여 성능 및 정확도 극대화 🚀✨
                from ctypes import wintypes
                PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
                STILL_ACTIVE = 259

                h_process = ctypes.windll.kernel32.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
                if h_process:
                    exit_code = wintypes.DWORD()
                    ctypes.windll.kernel32.GetExitCodeProcess(h_process, ctypes.byref(exit_code))
                    ctypes.windll.kernel32.CloseHandle(h_process)
                    return exit_code.value == STILL_ACTIVE
                return False
            else:
                os.kill(pid, 0)  # Signal 0: 프로세스 존재만 확인
                return True
        except (OSError, Exception):
            return False

    @staticmethod
    # [TAG: #@_extract_pid]
    def _extract_pid(filename: str) -> int:
        """pending_files_12345.txt 에서 PID(12345)를 추출합니다. 추출 불가 시 -1 반환."""
        basename = os.path.basename(filename)
        match = re.match(r"pending_files_(\d+)\.txt$", basename)
        if match:
            return safe_int(match.group(1))
        return -1

    @staticmethod
    # [TAG: #@find_all_queue_files]
    def find_all_queue_files() -> List[str]:
        """현재 디렉토리의 모든 pending_files*.txt 파일을 찾습니다."""
        # pending_files.txt (레거시) + pending_files_*.txt (PID 기반) 모두 매칭
        candidates = glob.glob(f"{PendingQueue.QUEUE_PREFIX}*.txt")
        return [f for f in candidates if os.path.exists(f) and os.path.getsize(f) > 0]

    @staticmethod
    # [TAG: #@find_orphaned_queues]
    def find_orphaned_queues() -> List[str]:
        """소유 프로세스가 죽어서 미아가 된 대기열 파일들을 찾습니다.
        - PID 기반 파일: 해당 PID가 살아있으면 활성(무시), 죽었으면 고아
        - 레거시(pending_files.txt): PID 없으므로 항상 고아로 간주
        """
        my_pid = os.getpid()
        orphaned = []
        for f in PendingQueue.find_all_queue_files():
            pid = PendingQueue._extract_pid(f)
            if pid == my_pid:
                continue  # 자기 자신의 큐는 제외
            if pid == -1:
                # 레거시 pending_files.txt → PID 정보 없음 → 고아로 간주
                orphaned.append(f)
            elif not PendingQueue._is_pid_alive(pid):
                # PID가 죽은 큐 → 고아
                orphaned.append(f)
            # else: PID가 살아있음 → 다른 인스턴스가 사용 중 → 건드리지 않음
        return orphaned

    @staticmethod
    # [TAG: #@find_active_queues]
    def find_active_queues() -> List[str]:
        """다른 인스턴스가 현재 사용 중인(PID가 살아있는) 대기열 파일들을 찾습니다."""
        my_pid = os.getpid()
        active = []
        for f in PendingQueue.find_all_queue_files():
            pid = PendingQueue._extract_pid(f)
            if pid != -1 and pid != my_pid and PendingQueue._is_pid_alive(pid):
                active.append(f)
        return active

