# CaffeineManager: 윈도우 절전/화면꺼짐 차단 관리자
# ==============================================================================
class CaffeineManager:
    """윈도우 절전/화면꺼짐을 차단하는 카페인 모드 관리자"""
    ES_CONTINUOUS        = 0x80000000
    ES_SYSTEM_REQUIRED   = 0x00000001
    ES_DISPLAY_REQUIRED  = 0x00000002

    # [TAG: #@__init___16]
    def __init__(self):
        self.is_active = False
        self._was_auto = False  # 자동으로 켜졌는지 추적

    # [TAG: #@enable]
    def enable(self, auto=False):
        """절전/화면꺼짐 차단 시작"""
        try:
            ctypes.windll.kernel32.SetThreadExecutionState(
                self.ES_CONTINUOUS | self.ES_SYSTEM_REQUIRED | self.ES_DISPLAY_REQUIRED
            )
            self.is_active = True
            self._was_auto = auto
        except Exception as e:
            try: _log_to_file(f"⚠️ [Silent Error Handled] {e}")
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

    # [TAG: #@disable]
    def disable(self):
        """절전/화면꺼짐 차단 해제 (원래 상태로)"""
        try:
            ctypes.windll.kernel32.SetThreadExecutionState(self.ES_CONTINUOUS)
        except Exception as e:
            try: _log_to_file(f"⚠️ [Silent Error Handled] {e}")
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")
        self.is_active = False
        self._was_auto = False

    # [TAG: #@auto_restore]
    def auto_restore(self, was_manual_before):
        """작업 완료 시: 수동으로 켜뒀으면 유지, 자동이었으면 끄기"""
        if self._was_auto and not was_manual_before:
            self.disable()

# [V5.0] 전역 사용자 이름 변수
USER_NAME = "주인님"

# [V54.0] 페르소나별 기억(히스토리) 분리 및 암호화 관리 🧠🔐
# [V16.4.4] 중복 임포트 정리 완료 ✨
import os
import threading

# [TAG: #@_is_personality_persona]
def _is_personality_persona(persona_id):
    # 뉴스/정보 전달 봇이 아닌, 순수 성격(대화형) 페르소나인지 확인
    exclude_list = ["newsbot", "realtimebot", "boss", "writer"]
    return persona_id not in exclude_list and persona_id

# [TAG: #@_get_history_filepath]
def _get_history_filepath(persona_id=None):
    temp_dir = ensure_dir(os.path.join(BASE_DIR, "temp"))
    return os.path.join(temp_dir, "persona_histories.enc")

# [TAG: #@clear_all_persona_histories]
def clear_all_persona_histories():
    """모든 페르소나 대화 기록 파일 및 임시 enc 파일 완전 초기화 🧼"""
    f_path = _get_history_filepath()
    if f_path and os.path.exists(f_path):
        try:
            os.remove(f_path)
        except Exception as e:
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")
    try:
        temp_dir = ensure_dir(os.path.join(BASE_DIR, "temp"))
        for old_f in glob.glob(os.path.join(temp_dir, "persona_*.enc")):
            try: os.remove(old_f)
            except Exception: pass
    except Exception:
        pass

# [TAG: #@_encrypt_history]
def _encrypt_history(data_dict):
    json_str = json.dumps(data_dict, ensure_ascii=False)
    # 매우 간단한 암호화: base64 인코딩 후 역순 배치
    b64 = base64.b64encode(json_str.encode('utf-8')).decode('utf-8')
    return b64[::-1]

# [TAG: #@_decrypt_history]
def _decrypt_history(enc_str):
    try:
        b64 = enc_str[::-1]
        json_str = base64.b64decode(b64).decode('utf-8')
        return json.loads(json_str)
    except Exception:
        return {}

# [TAG: #@_load_all_persona_histories]
def _load_all_persona_histories():
    filepath = _get_history_filepath()
    all_hists = {}

    # 통합 파일 로드
    if os.path.exists(filepath):
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                enc_str = f.read().strip()
            if enc_str:
                all_hists = _decrypt_history(enc_str)
        except Exception:
            pass

    # [마이그레이션] 기존 개별 파일들을 찾아 병합 후 삭제 🚀
    temp_dir = ensure_dir(os.path.join(BASE_DIR, "temp"))
    migrated = False
    old_files = glob.glob(os.path.join(temp_dir, "persona_*.enc"))
    for old_f in old_files:
        if os.path.basename(old_f) == "persona_histories.enc": continue

        # 파일명에서 persona_id 추출 (예: persona_cat.enc -> cat)
        b_name = os.path.basename(old_f)
        p_id = b_name.replace("persona_", "").replace(".enc", "")

        try:
            with open(old_f, 'r', encoding='utf-8') as f:
                o_enc = f.read().strip()
            if o_enc:
                # 구버전은 리스트 반환이 기본이므로 예외처리
                b64 = o_enc[::-1]
                j_str = base64.b64decode(b64).decode('utf-8')
                old_list = json.loads(j_str)
                if isinstance(old_list, list):
                    all_hists[p_id] = old_list
                    migrated = True
            os.remove(old_f)
        except Exception:
            pass

    if migrated:
        _save_persona_history_raw(filepath, all_hists)

    return all_hists

# [TAG: #@load_persona_history]
def load_persona_history(persona_id):
    if not _is_personality_persona(persona_id):
        return []

    all_hists = _load_all_persona_histories()
    history = all_hists.get(persona_id, [])

    if not history:
        return []

    now = datetime.now()
    filtered = []

    # 3개월(90일) 지난 대화 제거
    for item in history:
        time_str = item.get('time')
        if time_str:
            try:
                item_time = datetime.strptime(time_str, "%Y-%m-%d %H:%M:%S")
                if (now - item_time).days <= 90:
                    filtered.append(item)
            except Exception:
                pass
        else:
            filtered.append(item)

    # 만료된 대화가 삭제되었으면 덮어쓰기
    if len(filtered) != len(history):
        all_hists[persona_id] = filtered
        _save_persona_history_raw(_get_history_filepath(), all_hists)

    return filtered

# [TAG: #@_save_persona_history_raw]
def _save_persona_history_raw(filepath, data_dict):
    try:
        enc_str = _encrypt_history(data_dict)
        with open(filepath, 'w', encoding='utf-8') as f:
            f.write(enc_str)
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")

# [TAG: #@append_persona_history]
def append_persona_history(persona_id, role, content):
    if not _is_personality_persona(persona_id):
        return

    all_hists = _load_all_persona_histories()
    hist = all_hists.get(persona_id, [])

    now_str = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    hist.append({"role": role, "content": content, "time": now_str})

    all_hists[persona_id] = hist
    _save_persona_history_raw(_get_history_filepath(), all_hists)

# [TAG: #@generate_and_send_summary]
def generate_and_send_summary(settings_ref, chat_id, token, persona_id, recent_hist):
    if not recent_hist: return

    # [TAG: #@_task_2]
    def _task():
        try:
            agent = CatAgent(settings_ref)
            u_name = settings_ref.data.get('user_name', '주인님')

            # [V68.0] 요약 범위 확장 (10->50개) 및 상세 요약(200단어) 요청 🧠📈
            hist_str = ""
            for m in recent_hist[-50:]:
                t = m.get('time', '')
                # [V73.1] 과거 내역에서 기존 명찰 제거 (중복 방지) 🧼
                content = re.sub(r'^\[[^\]]+\]\s*', '', str(m['content'])).strip()
                hist_str += f"[{t}] {m['role']}: {content}\r\n"

            prompt = (
                f"[과거 대화 내역(최대 50개)]\r\n{hist_str}\r\n\r\n"
                f"[지시사항]\r\n방금 {u_name}님이 너를 다시 불렀어! 위의 과거 대화들을 바탕으로, 우리가 이전에 무슨 대화를 나눴었는지 약 200단어 내외로 아주 상세하고 풍부하게 요약해줘. "
                f"그리고 '우리 이런 얘기 했었지~ 기억나?' 하는 뉘앙스로 친근하게 인사하는 선톡을 작성해봐! 캐릭터(페르소나)에 완벽하게 빙의해서 마치 일기장이나 소설처럼 생생하게 들려줘야 해! ✨💎"
            )

            # 기록 없이 응답만 받기 위해 내부적으로 get_response 호출
            reply = agent.get_response(prompt, skip_history=True)
            if reply:
                p_disp = PERSONA_DICT.get(persona_id, "AI냥").split('(')[0].strip()
                tts_enabled = settings_ref.data.get('cat_tts_enabled', False)
                parsed_data = parse_panel_reply(reply) if _detect_panel_type(reply) else None
                send_ai_persona_reply(p_disp, reply, chat_id=str(chat_id), tts=tts_enabled, parsed=parsed_data, persona_id=persona_id)

                # 요약 선톡도 히스토리에 추가 (명찰 제외 알맹이만 저장) 🧼
                clean_record = parsed_data.get("story", reply) if parsed_data else reply
                clean_record = re.sub(r'\[/?(?:PANEL|패널|상태\s*패널)\].*?(?:\[/(?:PANEL|패널|상태\s*패널)\]|$)', '', clean_record, flags=re.DOTALL | re.IGNORECASE).strip()
                clean_record = re.sub(r'\[/?(?:FUTURE|미래패널|미래\s*패널)\].*?(?:\[/(?:FUTURE|미래패널|미래\s*패널)\]|$)', '', clean_record, flags=re.DOTALL | re.IGNORECASE).strip()
                append_persona_history(persona_id, "assistant", clean_record)

                # [V61.5] 기억 용량 50개 유지 (시간 정보 포함) 🧠
                ram_hist = settings_ref.data.get("cat_history", [])
                now_str = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                ram_hist.append({"role": "assistant", "content": clean_record, "time": now_str})
                settings_ref.data["cat_history"] = ram_hist[-50:]
                settings_ref.save()

        except Exception as e:
            _log_to_file(f"generate_summary error: {e}")

    threading.Timer(2.0, _task).start()

