    # [TAG: #@_get_default_user_name]
    def _get_default_user_name(self) -> str:
        """[V125.1] 시스템 사용자 이름을 동적으로 감지합니다. 👤✨"""
        try:
            return os.getlogin()
        except:
            return os.environ.get('USERNAME', 'Owner')

    # [TAG: #@_get_windows_download_path]
    def _get_windows_download_path(self) -> str:
        """[V125.1] 윈도우 표준 다운로드 폴더 경로를 동적으로 감지합니다. 📥✨"""
        try:
            # USERPROFILE 환경변수를 통한 다운로드 폴더 전략
            u_profile = os.environ.get('USERPROFILE')
            if u_profile:
                d_path = os.path.join(u_profile, "Downloads")
                if os.path.exists(d_path): return d_path
            return os.path.join(os.path.expanduser("~"), "Downloads")
        except:
            return os.getcwd()

    def get_valid_path(self, key: str, default_path: str = None) -> str:
        """[V125.3] 저장된 경로가 유효한지 확인하고, 없으면 기본 경로를 임시로 반환냥! 📂✨"""
        val = self.data.get(key)
        if val and os.path.exists(val):
            return val
        if key == 'download_path':
            return self._get_windows_download_path()
        return default_path if default_path else os.getcwd()

    def get(self, key: str, default=None):
        """[DeoVR/Global] 딕셔너리 호환 get 인터페이스 🛡️"""
        return self.data.get(key, default)

    def set(self, key: str, value, save_now: bool = False):
        """[DeoVR/Global] 딕셔너리 호환 set 인터페이스 및 자동 더티 마킹 🛡️"""
        self.data[key] = value
        if hasattr(self, 'dirty_keys'):
            self.dirty_keys.add(key)
        if save_now:
            self.save()

    def __getitem__(self, key: str):
        return self.data[key]

    def __setitem__(self, key: str, value):
        self.data[key] = value
        if hasattr(self, 'dirty_keys'):
            self.dirty_keys.add(key)

    def __contains__(self, key: str):
        return key in self.data

