for _ko, _ja, _en, _sid in _TOP_POPULAR_ACTRESSES:
    if _ko and _ja:
        _ACTRESS_QUICK_MAP[_ko] = (_ja, _en)
        _ACTRESS_QUICK_MAP[_ko.replace(" ", "")] = (_ja, _en)
