def generate_pkce_pair():
    """gallery-dl 공식 호환 PKCE code_verifier (64자리 HEX) 및 code_challenge(S256) 생성"""
    import random
    import binascii
    code_verifier = random.getrandbits(32 * 8).to_bytes(32, "big").hex()
    digest = hashlib.sha256(code_verifier.encode('ascii')).digest()
    code_challenge = binascii.b2a_base64(digest)[:-2].replace(b"+", b"-").replace(b"/", b"_").decode('ascii')
    return code_verifier, code_challenge

def get_pixiv_login_url(code_challenge: str) -> str:
    """브라우저로 열 로그인 URL 생성"""
    params = {
        "client": "pixiv-android",
        "code_challenge_method": "S256",
        "code_challenge": code_challenge,
    }
    return f"{PIXIV_LOGIN_URL}?{urllib.parse.urlencode(params)}"


def _get_clipboard_text() -> str:
    """Windows API를 사용한 초고속 클립보드 텍스트 조회 (무의존성)"""
    if os.name != 'nt':
        return ""
    try:
        import ctypes
        user32 = ctypes.windll.user32
        kernel32 = ctypes.windll.kernel32
        if not user32.OpenClipboard(0):
            return ""
        try:
            if user32.IsClipboardFormatAvailable(13):  # CF_UNICODETEXT
                h = user32.GetClipboardData(13)
                if h:
                    p = kernel32.GlobalLock(h)
                    if p:
                        text = ctypes.c_wchar_p(p).value or ""
                        kernel32.GlobalUnlock(h)
                        return text
        finally:
            user32.CloseClipboard()
    except Exception:
        pass
    return ""


