def _extract_pixiv_code(text: str) -> str:
    """텍스트/URL/콘솔로그/HTML소스에서 Pixiv 인증 code 파라미터 정밀 추출"""
    if not text:
        return ""
    text = str(text).strip()
    import re
    # 1. ?code=... or &code=... or %26code=... or \u0026code=...
    # (pixiv://account/login?code=... 및 콘솔 에러 로그 완벽 커버)
    m = re.search(r'(?:[?&]|%26|&amp;|\\u0026)code=([a-zA-Z0-9_\-\.]+)', text)
    if m:
        val = m.group(1)
        val = val.split('&')[0].split('%')[0].split('"')[0].split("'")[0].split('\\')[0]
        if len(val) >= 15:
            return val
    # 2. code=... 단독 형태
    m = re.search(r'(?:^|[\s"\'=])code=([a-zA-Z0-9_\-\.]+)', text)
    if m:
        val = m.group(1)
        val = val.split('&')[0].split('%')[0].split('"')[0].split("'")[0].split('\\')[0]
        if len(val) >= 15:
            return val
    # 3. 알파벳/숫자/하이픈/언더바 25~100자 단독 문자열 (비누가 코드만 딱 복사했을 때)
    if re.match(r'^[a-zA-Z0-9_\-\.]{25,100}$', text):
        return text
    return ""


