def ui_pixiv_folder_config(settings_ref):
    """저장 폴더 및 구조 설정 (손가락 메뉴 👈)"""
    c = C_PAL
    focus_idx = 1
    while True:
        cur_p = get_default_pixiv_dir(settings_ref.data)
        cur_style = settings_ref.data.get("pixiv_folder_style", "date_author")
        style_info = get_folder_style_info(cur_style)

        title = (
            f"{c.BOLD}{c.SKY}📂 [Pixiv] 다운로드 저장 위치 및 폴더 구조 설정{c.RESET}\r\n"
            f"  현재 저장 위치: {c.GREEN}{cur_p}{c.RESET}\r\n"
            f"  현재 폴더 구조: {c.YELLOW}{style_info['name']}{c.RESET}\r\n"
            f"  구조 미리보기: {c.GRAY}{style_info['desc']}{c.RESET}\r\n"
            f"  {c.YELLOW}💡 [꿀팁] '날짜/작가/사진' 구조(1번)를 쓰시면 수많은 사진이 깔끔하게 날짜별로 정돈됩니다! 👍{c.RESET}"
        )

        menu_items = [
            _pixiv_ui_divider("폴더 분류 구조 선택", icon="📅", width=58),
            {"label": f"📅 👤  [구조 1] 오늘날짜 / 팔로워(작가) / 사진 {'  (✅ 현재선택)' if cur_style == 'date_author' else ''}", "key": "style_date_author"},
            {"label": f"📅 🖼️  [구조 2] 오늘날짜 / 사진 (날짜 폴더 바로 아래) {'  (✅ 현재선택)' if cur_style == 'date_flat' else ''}", "key": "style_date_flat"},
            {"label": f"👤 🖼️  [구조 3] 팔로워(작가) / 사진 (날짜 없이 작가별) {'  (✅ 현재선택)' if cur_style == 'author_only' else ''}", "key": "style_author_only"},
            {"label": f"🖼️     [구조 4] 폴더 없이 기본 경로에 바로 저장 {'  (✅ 현재선택)' if cur_style == 'flat' else ''}", "key": "style_flat"},
            _pixiv_ui_divider("저장 경로 드라이브 변경", icon="🗂️", width=58),
            {"label": f"🗂️     [경로 변경] 폴더 찾아보기 창 열기 (탐색기 GUI 다이얼로그)", "key": "gui_dialog"},
            {"label": f"📌     [경로 변경] 기본 드라이브로 설정 (G:\\pixiv)", "key": "preset_g"},
            {"label": f"📌     [경로 변경] 앱 내부 폴더로 설정 (C:\\srt\\pixiv)", "key": "preset_srt"},
            {"label": f"⌨️     [경로 변경] 새 경로 직접 타이핑 입력", "key": "manual_input"},
            _pixiv_ui_divider(width=58),
            {"label": f"🚪   돌아가기", "key": "back"}
        ]

        sel_idx = _show_menu(title, menu_items, default_idx=focus_idx)
        if sel_idx < 0 or sel_idx >= len(menu_items):
            break

        item = menu_items[sel_idx]
        key = item.get("key", "")
        if key == "sep" or item.get("type") == "divider":
            continue

        focus_idx = sel_idx

        if key == "back":
            break

        elif key.startswith("style_"):
            new_style = key.replace("style_", "")
            settings_ref.data["pixiv_folder_style"] = new_style
            settings_ref.save()
            new_info = get_folder_style_info(new_style)
            print(f"\r\n  {c.GREEN}✅ 저장 구조가 '{new_info['name']}'(으)로 변경되었습니다! 👍{c.RESET}")
            print(f"  {c.GRAY}미리보기: {new_info['desc']}{c.RESET}")
            time.sleep(1.3)

        elif key == "gui_dialog":
            chosen = None
            try:
                import tkinter as tk
                from tkinter import filedialog
                root = tk.Tk()
                root.withdraw()
                root.attributes("-topmost", True)
                chosen = filedialog.askdirectory(initialdir=cur_p, title="Pixiv 저장 폴더 선택")
                root.destroy()
            except Exception:
                pass
            if chosen and os.path.isdir(chosen):
                settings_ref.data["pixiv_download_path"] = chosen
                settings_ref.save()
                print(f"\r\n  {c.GREEN}✅ 저장 폴더가 '{chosen}'(으)로 변경되었습니다!{c.RESET}")
                time.sleep(1.2)

        elif key == "preset_g":
            g_path = r"G:\pixiv"
            os.makedirs(g_path, exist_ok=True)
            settings_ref.data["pixiv_download_path"] = g_path
            settings_ref.save()
            print(f"\r\n  {c.GREEN}✅ 저장 폴더가 '{g_path}'(으)로 변경되었습니다!{c.RESET}")
            time.sleep(1.2)

        elif key == "preset_srt":
            srt_path = r"C:\srt\pixiv"
            os.makedirs(srt_path, exist_ok=True)
            settings_ref.data["pixiv_download_path"] = srt_path
            settings_ref.save()
            print(f"\r\n  {c.GREEN}✅ 저장 폴더가 '{srt_path}'(으)로 변경되었습니다!{c.RESET}")
            time.sleep(1.2)

        elif key == "manual_input":
            manual = input(f"\r\n  새 폴더 경로를 입력하세요: ").strip()
            if manual:
                os.makedirs(manual, exist_ok=True)
                settings_ref.data["pixiv_download_path"] = manual
                settings_ref.save()
                print(f"  {c.GREEN}✅ 저장 폴더가 '{manual}'(으)로 변경되었습니다!{c.RESET}")
                time.sleep(1.2)


def ui_pixiv_folder_open(settings_ref):
    """탐색기로 폴더 열기"""
    c = C_PAL
    dl_dir = get_default_pixiv_dir(settings_ref.data)
    os.makedirs(dl_dir, exist_ok=True)
    try:
        os.startfile(dl_dir)
    except Exception as e:
        print(f"  {c.RED}폴더 열기 실패: {e}{c.RESET}")
        time.sleep(1.2)


def ui_pixiv_archive_manage(settings_ref):
    """아카이브 장부 관리 (손가락 메뉴 👈)"""
    c = C_PAL
    focus_idx = 1
    while True:
        dl_dir = get_default_pixiv_dir(settings_ref.data)
        archive_path = get_pixiv_archive_path(dl_dir)
        cnt = count_archived_items(archive_path)

        title = (
            f"{c.BOLD}{c.SKY}📜 [Pixiv] 수집 기록 장부 (Archive DB) 관리{c.RESET}\r\n"
            f"  장부 파일: {c.GRAY}{archive_path}{c.RESET}\r\n"
            f"  기록된 작품 수: {c.BOLD}{c.YELLOW}{cnt}개{c.RESET} (중복 다운로드 자동 방지)\r\n"
            f"  {c.YELLOW}💡 [꿀팁] 이미 수집된 작품은 아카이브 장부를 통해 자동으로 건너뛰어 초고속으로 완료됩니다! 👍{c.RESET}"
        )

        menu_items = [
            _pixiv_ui_divider("장부 파일 및 초기화", icon="📜", width=58),
            {"label": f"📁   장부 저장 폴더 열기 (윈도우 탐색기)", "key": "open_folder"},
            {"label": f"🧨   기록 장부 소각 (초기화 - 모든 작품 처음부터 다시 다운로드)", "key": "clear_archive"},
            _pixiv_ui_divider(width=58),
            {"label": f"🚪   돌아가기", "key": "back"}
        ]

        sel_idx = _show_menu(title, menu_items, default_idx=focus_idx)
        if sel_idx < 0 or sel_idx >= len(menu_items):
            break

        item = menu_items[sel_idx]
        key = item.get("key", "")
        if key == "sep" or item.get("type") == "divider":
            continue

        focus_idx = sel_idx

        if key == "back":
            break
        elif key == "open_folder":
            ui_pixiv_folder_open(settings_ref)
        elif key == "clear_archive":
            confirm = input(f"\r\n  {c.RED}⚠️ 정말로 기록 장부를 초기화할까요? (y/N): {c.RESET}").strip().lower()
            if confirm == 'y':
                clear_pixiv_archive(archive_path)
                print(f"  {c.GREEN}✅ 장부가 소각되었습니다. (수집 카운트: 0){c.RESET}")
                time.sleep(1.5)


def _handle_pixiv_interactive_menu(settings_ref):
    """Pixiv 설정 및 관리 손가락 대화형 메뉴 (소메뉴 통합 및 구분선 분리) 🎨👉"""
    set_interactive_menu_func(_interactive_menu)
    set_telegram_notification_func(send_telegram_notification)
    # 미등록/오류 작가 목록 자동 복구 및 정비 🛠️✨
    try:
        sanitize_and_repair_custom_artists(settings_ref)
    except Exception:
        pass
    focus_idx = 1
    while True:
        token = settings_ref.data.get('pixiv_refresh_token', '')
        user = settings_ref.data.get('pixiv_account_name', '')
        auth_badge = f"{C.GREEN}🟢 {user or '로그인됨'}{C.RESET}" if token else f"{C.RED}⚫ 미로그인{C.RESET}"
        dl_dir = get_default_pixiv_dir(settings_ref.data)
        archive_path = get_pixiv_archive_path(dl_dir)
        archive_cnt = count_archived_items(archive_path)
        auto_watch = settings_ref.data.get('pixiv_auto_watch', False)
        tg_noti = settings_ref.data.get('pixiv_tg_noti', True)
        dl_done_noti = settings_ref.data.get('pixiv_dl_done_noti', settings_ref.data.get('pixiv_tg_noti', True))
