# [TAG: #@_select_colab_connection_mode]
def _select_colab_connection_mode(settings_obj):
    """
    코랩 연동이 필요한 시점(자막/AI냥)에 호출되어 연결 방식(loca / Direct IP)을 선택받습니다.
    환경설정에 저장된 값을 기본값으로 하여 손가락 위치가 잡힙니다.
    """
    # [V77.4] 저장된 값 가져오기 (없으면 0: loca 가 기본)
    cur_mode = settings_obj.data.get('colab_connection_mode', 0)

    # 팝업 없이 바로 손가락 메뉴(인터랙티브) 실행 ✨
    opts = [
        f" 🔗 Localtunnel (loca) - {C.DIM}프록시 경유 (서버 연결형){R}",
        f" 🚀 Direct IP (직통) - {C.GREEN}공인 IP 직접 연결 (UPnP 개방 필수){R}",
        f" ♻️ 방금 전(기존) 방식 그대로 이어서 쓰기 (현재: {'loca' if cur_mode==0 else 'Direct'})",
        " ❌ 작업 완전 취소 (돌아가기)"
    ]

    sel, _, *_ = _interactive_menu("🌐 코랩 연결 방식을 알려줘냥!", opts, default_idx=cur_mode, timeout=0)

    if sel < 0 or sel == 3:
        return -1

    if sel >= 0 and sel < 2:
        settings_obj.data['colab_connection_mode'] = sel
        settings_obj.save()
        mode_name = "Localtunnel (loca)" if sel == 0 else "Direct IP (직통)"
        print(f" 💾 연결 방식이 [{mode_name}] (으)로 업데이트 되었습니다.")
    return sel


# region [16. 멀티미디어 엔진 및 트랜스코드] 🎞️
# ★ 타임아웃이 적용된 함수를 별도 스레드에서 실행하는 헬퍼
# [TAG: #@_run_with_timeout]
def _run_with_timeout(func, timeout_sec, desc="작업"):
    """func를 별도 스레드에서 실행하고, timeout_sec 이내에 완료되지 않으면 TimeoutError를 발생시킵니다."""
    result_container = [None]
    error_container = [None]

    # [TAG: #@wrapper_2]
    def wrapper():
        try:
            result_container[0] = func()
        except Exception as e:
            error_container[0] = e

    t = threading.Thread(target=wrapper, daemon=True)
    t.start()
    t.join(timeout=timeout_sec)

    if t.is_alive():
        raise TimeoutError(f"⏱️ {desc}이(가) {timeout_sec}초 제한 시간을 초과했습니다.")
    if error_container[0] is not None:
        raise error_container[0]
    return result_container[0]

EXTRACT_AUDIO_TIMEOUT = 600  # 오디오 추출 최대 10분

# [TAG: #@extract_audio_chunk]
def extract_audio_chunk(v_path: str, audio_start: float, audio_end: float, chunk_file: str):
    """FFmpeg 추출 시 강력한 타임아웃과 프로세스 강제 종료 로직을 적용합니다."""
    MAX_RETRY = 3

    # [TAG: #@_do_extract]
    def _do_extract():
        duration = audio_end - audio_start
        script_dir = os.path.dirname(os.path.abspath(sys.argv[0]))

        ffmpeg_bin = _get_ffmpeg_bin()

        for attempt in range(1, MAX_RETRY + 1):
            try:
                # [V16.5.1] AI냥 요청: FFmpeg Permission Denied (-13) 원천 봉쇄! 🛡️✨
                # 1. 기존 파일이 있다면 삭제 시도 (점유 확인)
                if os.path.exists(chunk_file):
                    for i in range(5): # 최대 5번(2.5초) 점유 해제 대기
                        try:
                            with open(chunk_file, "a") as f: pass # 쓰기 권한 테스트
                            os.remove(chunk_file)
                            break
                        except PermissionError:
                            _log_to_file(f"⏳ [점유 대기] {os.path.basename(chunk_file)}가 잠겨 있어냥! ({i+1}/5)")
                            time.sleep(0.5)
                        except Exception as e:
                            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                            if "6" not in str(e):
                                _log_to_file(f"⚠️ [Silent Exception] {e}")

                # [수정] -y 옵션 보강 및 명령어 구성
                command = [
                    ffmpeg_bin, "-y",
                    "-ss", str(audio_start),
                    "-t", str(duration),
                    "-i", v_path,
                    "-vn",
                    "-af", "afftdn=nf=-20, highpass=f=80, lowpass=f=9000",
                    "-c:a", "aac", "-b:a", "64k", "-ac", "1", "-ar", "24000",
                    chunk_file
                ]

                success, stdout, stderr = run_ffmpeg_task(command, timeout=60, desc=f"조각 {audio_start:.0f}s 추출")
                
                if not success:
                    err_str = stderr.decode(errors='ignore')
                    if "Permission denied" in err_str or "error code: -13" in err_str:
                        # [V16.5.1] 권한 에러 시 즉시 재시도하지 않고 잠시 휴식 (백신 등 회피) 🛡️
                        print(f" 🛡️ [조각 {audio_start:.0f}s] 권한 거부 감지! 백신이나 다른 앱이 점유 중인 것 같아냥. 1.5초 후 재시도... ({attempt}/{MAX_RETRY})")
                        time.sleep(1.5)
                        continue
                    
                    if stderr == b"timeout":
                        raise TimeoutError("FFmpeg 추출 시간 초과")
                    raise RuntimeError(f"FFmpeg 에러: {err_str}")

                # [V121.3] 용량 체크 (대폭 강화: 침묵 구간 추출 시 0바이트/깡통 방지)
                if os.path.exists(chunk_file) and os.path.getsize(chunk_file) > 4096: # 최소 4KB 보장냥!
                    return
                else:
                    # 🛠️ [리팩토링] safe_remove_file 사용
                    safe_remove_file(chunk_file)
                    print(f" ⚠️ [조각 {audio_start:.0f}s] 깡통 또는 너무 작은 파일 생성됨 ({os.path.getsize(chunk_file) if os.path.exists(chunk_file) else 0} bytes). {attempt}회 재시도 중...")
            except Exception as e:
                print(f" ⚠️ [조각 {audio_start:.0f}s] 에러 발생: {e}")

            time.sleep(1.5)

        raise RuntimeError(f"{MAX_RETRY}회 시도 후에도 실패했습니다.")

    # _run_with_timeout 헬퍼를 통해 2중으로 보호 (제한 시간 150초)
    _run_with_timeout(_do_extract, 150, "최종 방어형 음원 추출")

SPEECH_CHECK_TIMEOUT = 120

# [TAG: #@check_audio_has_speech]
def check_audio_has_speech(chunk_file: str, silence_threshold_rms: float = 0.01) -> bool:
    """오디오 조각 파일에 실제 음성(소리)이 포함되어 있는지 RMS 에너지 기반으로 검증합니다. (타임아웃 적용)
    
    AI가 빈 자막을 반환했을 때, 진짜 무음인지 아닌지를 판별하여
    불필요한 재시도를 방지합니다.
    
    Args:
        chunk_file: 오디오 조각 파일 경로
        silence_threshold_rms: RMS 에너지 임계값 (이 이하면 무음으로 판단)
    Returns:
        True = 음성이 있음 (재시도 필요), False = 진짜 무음 (재시도 불필요)
    """
    # [TAG: #@_do_check]
    def _do_check():
        load_heavy_modules() # [Safety] Ensure moviepy, numpy, etc. loaded
        import numpy as np
        clip = None
        try:
            # [V135.3] 로직 개선: 오디오 전용 파일은 AudioFileClip으로 불러와서 비디오 프레임 추출 워닝을 사전에 차단합니다냥! 🎧🔒
            if chunk_file.lower().endswith(('.m4a', '.mp3', '.wav', '.aac', '.flac')):
                clip = AudioFileClip(chunk_file)
                audio_obj = clip
            else:
                clip = VideoFileClip(chunk_file)
                audio_obj = clip.audio

            if audio_obj is None:
                return False

            audio_array = audio_obj.to_soundarray(fps=32000)

            if audio_array is None or len(audio_array) == 0:
                return False

            # 모노로 변환
            if len(audio_array.shape) > 1:
                audio_mono = np.mean(audio_array, axis=1)
            else:
                audio_mono = audio_array

            # 전체 RMS 에너지 계산
            np.sqrt(np.mean(audio_mono ** 2))

            # 상위 10% 구간의 RMS (피크 에너지) - 배경 잡음 vs 실제 음성 구별
            window_size = int(32000 * 0.1)  # 100ms 윈도우
            num_windows = max(1, len(audio_mono) // window_size)
            rms_values = []
            for i in range(num_windows):
                window = audio_mono[i * window_size:(i + 1) * window_size]
                if len(window) > 0:
                    rms_values.append(np.sqrt(np.mean(window ** 2)))

            if not rms_values:
                return False

            # (중략 - 기존 로직 유지)
            top_10_percent_idx = max(1, int(len(rms_values) * 0.1))
            peak_rms = np.mean(sorted(rms_values, reverse=True)[:top_10_percent_idx])

            return peak_rms > silence_threshold_rms
        finally:
            if clip:
                try: clip.close()
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")

    try:
        return _run_with_timeout(_do_check, SPEECH_CHECK_TIMEOUT, "음성 검증")
    except (TimeoutError, Exception):
        # 검증 실패/타임아웃 시 안전하게 "음성이 있다"고 가정 (재시도 허용)
        return True

SILENCE_SEARCH_TIMEOUT = 60  # 침묵 탐색 최대 1분

# [TAG: #@find_silence_near]
def find_silence_near(v_path: str, target_time: float, duration: float, search_range: float = 15.0, min_silence_ms: int = 400) -> float:
    """목표 분할점 근처에서 가장 가까운 침묵 구간을 FFmpeg를 사용하여 찾습니다. (타임아웃 적용)
    
    업계 표준 'VAD-aware chunking' 기법의 간소화 버전.
    말하는 도중에 자르지 않고, 문장이 끝나는 조용한 지점에서 치밀하게 분할합니다.
    """
    # [TAG: #@_do_search]
    def _do_search():
        import numpy as np
        import tempfile
        import wave

        search_start = max(0, target_time - search_range)
        # [V121.1] duration이 0이면 상한선을 두지 않음 (수리 모드 등에서 video_dur=0 인 경우 대비) 🛡️
        if duration > 0:
            search_end = min(duration, target_time + search_range)
        else:
            search_end = target_time + search_range

        chunk_dur = search_end - search_start

        # [Safety] 음수 기간 원천 차단 🛑
        if chunk_dur <= 0:
            return target_time

        fps = 32000

        temp_wav = os.path.join(tempfile.gettempdir(), f"silence_check_{uuid.uuid4().hex[:8]}.wav")
        try:
            # FFmpeg로 해당 구간 오디오만 빠르게 WAV로 추출 (1채널, 32kHz)
            cmd = [_get_ffmpeg_bin(), "-y", "-v", "error", "-ss", str(search_start), "-t", str(chunk_dur),
                   "-i", v_path, "-vn", "-ac", "1", "-ar", "32000", "-c:a", "pcm_s16le", "-f", "wav", temp_wav]
            run_ffmpeg_task(cmd, desc="침묵 탐색용 오디오 추출")

            if not os.path.exists(temp_wav):
                return target_time

            with wave.open(temp_wav, 'rb') as wf:
                num_frames = wf.getnframes()
                audio_data = wf.readframes(num_frames)
                audio_array = np.frombuffer(audio_data, dtype=np.int16).astype(np.float32)

            if len(audio_array) == 0:
                return target_time

            audio_mono = audio_array # 이미 모노

            # RMS 에너지를 윈도우 단위로 계산 (50ms 윈도우)
            window_size = int(fps * 0.05)  # 50ms = 800 samples at 16kHz
            num_windows = len(audio_mono) // window_size

            if num_windows == 0:
                return target_time

            rms_values = []
            for i in range(num_windows):
                window = audio_mono[i * window_size:(i + 1) * window_size]
                if len(window) > 0:
                    rms = np.sqrt(np.mean(window ** 2))
                    rms_values.append(rms)

            rms_array = np.array(rms_values)

            # 침묵 임계값: 전체 구간 RMS의 25% 분위수의 120%
            silence_threshold = np.percentile(rms_array, 25) * 1.2
            if silence_threshold < 10.0:  # int16 스케일 기준 너무 낮으면 보정
                silence_threshold = 50.0

            # 연속 침묵 구간 찾기 (400ms = 8 windows)
            min_silence_windows = max(1, int((min_silence_ms / 1000.0) / 0.05))

            # [V121.2] 무음 구간 탐색 결과가 목표 지점에서 너무 멀지 않도록 보정 (최대 15초 유지)
            best_time = target_time
            best_diff = search_range

            silent_count = 0 # [BugFix] 미정의 변수 초기화냥! 🛠️✨
            for i in range(num_windows):
                if rms_array[i] <= silence_threshold:
                    silent_count += 1
                else:
                    if silent_count >= min_silence_windows:
                        # 무음 구간의 중심점을 계산냥! 🎯
                        silence_center_idx = i - silent_count // 2
                        silence_time = search_start + (silence_center_idx * window_size) / fps

                        # 목표 지점에서 가장 가까운 녀석을 골라냥!
                        distance = abs(silence_time - target_time)
                        if distance < best_diff:
                            best_diff = distance
                            best_time = silence_time
                    silent_count = 0

            # [V121.3] 0.5초 미만의 너무 짧은 변경은 무시 (떨림 방지 🛡️)
            if abs(best_time - target_time) < 0.5:
                best_time = target_time

            return float(best_time)
        finally:
            # 🛠️ [리팩토링] safe_remove_file 사용 (V121.2: silence_check 파일은 영구 삭제 ✨)
            safe_remove_file(temp_wav, use_trash=False)

    try:
        return _run_with_timeout(_do_search, SILENCE_SEARCH_TIMEOUT, f"침묵 탐색 ({target_time:.0f}s 근처)")
    except (TimeoutError, Exception):
        return target_time  # 실패/타임아웃 시 원래 위치에서 분할

# [TAG: #@upload_with_retry]
def upload_with_retry(chunk_file: str, status_fn, log_fn):
    """파일 업로드, 검증 진행 및 권한 오류시 자동 키 로테이션을 처리합니다."""
    retries = 3
    rotation_attempts = 0
    UPLOAD_PROCESSING_TIMEOUT = 300  # ★ 업로드 후 PROCESSING 상태 최대 대기 5분
    while retries > 0:
        file_upload_idx = API_KEY_IDX
        try:
            # [V134.5] 새로운 AQ 키 호환성 강화: 환경 변수 강제 주입 및 v1 버전 고정 🛡️🚀
            _k = API_KEYS[file_upload_idx]
            os.environ["GOOGLE_API_KEY"] = _k
            genai.configure(api_key=_k, api_version='v1')

            uploaded_file = genai.upload_file(path=chunk_file)
            _processing_start = time.time()
            while uploaded_file.state.name == "PROCESSING":
                if time.time() - _processing_start > UPLOAD_PROCESSING_TIMEOUT:
                    raise TimeoutError(f"파일 PROCESSING 상태가 {UPLOAD_PROCESSING_TIMEOUT}초를 초과했습니다.")
                status_fn("⏳ 매핑 대기 중...")
                time.sleep(3)
                uploaded_file = genai.get_file(uploaded_file.name)

            if uploaded_file.state.name == "FAILED":
               raise RuntimeError("파일 무결성 검증 실패 (FAILED 상태).")

            status_fn("✔️  업로드 완료")
            return uploaded_file
        except Exception as e:
            err_str = str(e).lower()

            # [V135.0] 안전 퓨즈 (글로벌 업로드): 치명적 오류 시 무한 재시도 및 로테이션 루프 강제 차단 (계정 보호) 🛑
            if "api key not valid" in err_str or "unauthenticated" in err_str:
                status_fn(f"❌ {C.RED}치명적 키 오류 (작업 강제 중단!){C.RESET}")
                log_fn(f"🛑 [인증 오류] 지금 사용 중인 API 키가 완전 잘못되었습니다. 계정 보호(밴 방지)를 위해 파이프라인을 폭파합니다: {err_str}")
                log_fn("   → 해결: [F2] -> [Gemini API 키 관리]에서 최정상 키로 교체해줘냥!")
                raise RuntimeError("FATAL_API_KEY_INVALID: 구글 서버가 키를 완전히 거절했습니다. 작업을 영구 중단합니다.")

            if "suspended" in err_str or "permission denied" in err_str:
                status_fn(f"❌ {C.RED}계정 권한 상실/차단됨!{C.RESET}")
                log_fn("🛑 [치명적 권한 오류] 구글 계정 권한이 정지되었거나 차단되었습니다. 즉시 작업을 중단합니다.")
                raise RuntimeError("FATAL_ACCOUNT_SUSPENDED: 구글 계정이 차단/정지 되었습니다.")

            if "invalid" in err_str or "400" in err_str:
                status_fn(f"❌ {C.RED}잘못된 요청 오류!{C.RESET}")
                log_fn(f"🛑 [요청 오류] 400 Bad Request 또는 서버 거절입니다. 불필요한 스팸 재시도를 중단합니다: {err_str}")
                raise RuntimeError("FATAL_BAD_REQUEST: 지원하지 않는 파일이거나 형식이 완전히 잘못되었습니다.")

            if "403" in err_str or "429" in err_str or "quota" in err_str or "exhausted" in err_str:
                # [V135.0] 한도 초과된 키에 1시간짜리 쿨다운 타이머 세팅 ⏲️
                try: set_api_key_cooldown(API_KEYS[file_upload_idx], minutes=60)
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")

                rotation_attempts += 1
                if rotation_attempts >= max(1, len(API_KEYS)):
                    status_fn(f"❌ {C.RED}모든 키 한도 초과! 시스템 중단.{C.RESET}")
                    log_fn("🛑 [할당량 초과] 등록된 모든 API 키를 다 썼습니다. 밴 방지를 위해 여기서 전원을 강제로 내립니다.")
                    raise RuntimeError("FATAL_QUOTA_EXHAUSTED: 등록된 모든 API 키의 할당량이 완전히 소진되었습니다.")

                rotated = rotate_api_key_global(API_KEY_IDX)
                if rotated:
                    status_fn("🔑 과부하/오류: 통합 API 키 로테이션 완료. 재시도 중...")
                    time.sleep(2)
                else:
                    time.sleep(3)
                continue

            retries -= 1
            log_fn(f"⚠️ 업로드 지연/실패 발생. 재가동 중... (남은 시도: {retries})")
            if retries <= 0:
                raise RuntimeError(f"클라우드 전송 최종 실패: {e}")
            time.sleep(4)
    raise RuntimeError("업로드 시도 횟수 초과")

# [TAG: #@set_api_key_cooldown]
def set_api_key_cooldown(api_key_target: str, minutes: int = 60):
    """[V135.0] 지정된 API 키에 쿨다운(휴식 시간)을 부여하여 당분간(minutes) 로테이션에서 무시되도록 합니다. (스레드 안전 🔐)"""
    with API_KEY_LOCK: # [V147.155] 락 추가로 스레드 안전성 확보 ✨
        try:
            settings_data = {}
            if os.path.exists(SETTINGS_FILE):
                with open(SETTINGS_FILE, "r", encoding="utf-8") as f:
                    settings_data = json.load(f)

            # [규칙] AGENTS.md §암호화 — ⚠️ 구멍 ⑥ (가장 위험) : 여기서 settings.json 을 raw 로 읽고
            #   그대로 (1) 메모리에 주입하고 (2) 파일에 되돌려쓴다. 복호화/재암호화가 없으면:
            #   · 아래 L92745 에서 **암호문이 메모리(self.data)에 주입** → 이후 save() 때 또 암호화 = 이중 암호화
            #     → get_api_keys() 가 한 번 풀어도 여전히 암호문 → Gemini 영구 마비 ☠️
            #   · _set_api_key_cooldown_internal 의 `item["key"] == api_key_target` 매칭이 깨져
            #     legacy 분기로 빠져 api_key_cooldowns 에 **평문 키가 새어 나간다** (2차 평문 유출)
            # 따라서 여기서 반드시 "복호화 → 수정 → 재암호화" 3단으로 처리한다.
            # (암호문이 아니면 복호화 함수가 원문을 반환하므로 평문 상태에서도 동일하게 동작한다)
            # ⚠️ 여기서도 모듈 레벨 함수를 참조하지 않는다(초기 호출 시 NameError 위험) → 자기 완결 중첩 함수
            def _cool_dec(v):
                if not v or not isinstance(v, str): return v
                try:
                    import hashlib as _h2, base64 as _b2
                    from cryptography.fernet import Fernet as _F3
                    _us2 = os.getlogin() if hasattr(os, 'getlogin') else os.environ.get('USERNAME', 'binu_master')
                    return _F3(_b2.urlsafe_b64encode(_h2.sha256(_us2.encode()).digest())).decrypt(v.encode()).decode()
                except Exception:
                    return v
            _ak = settings_data.get("api_keys")
            _plain_ak = None
            if isinstance(_ak, list) and _ak:
                _plain_ak = []
                for _ki in _ak:
                    if isinstance(_ki, dict):
                        _ni = dict(_ki)
                        _kv = _ni.get("key")
                        if isinstance(_kv, str) and _kv:
                            _ni["key"] = _cool_dec(_kv)
                        _plain_ak.append(_ni)
                    else:
                        _plain_ak.append(_ki)
                settings_data["api_keys"] = _plain_ak

            _set_api_key_cooldown_internal(api_key_target, minutes, settings_data)

            # 되돌려쓸 때는 반드시 재암호화 (raw 덮어쓰기 경로이므로 SettingsManager.save() 를 거치지 않는다)
            _ak2 = settings_data.get("api_keys")
            if isinstance(_ak2, list) and _ak2:
                _enc_ak = []
                for _ki in _ak2:
                    if isinstance(_ki, dict):
                        _ni = dict(_ki)
                        _kv = _ni.get("key")
                        # gAAAA 로 시작하면 이미 암호문 → 방어적으로 스킵 (이중 암호화 원천 차단)
                        if isinstance(_kv, str) and _kv and not _kv.startswith("gAAAA"):
                            try:
                                from cryptography.fernet import Fernet as _CoolF
                                import hashlib as _coolh, base64 as _coolb
                                _us = os.getlogin() if hasattr(os, 'getlogin') else os.environ.get('USERNAME', 'binu_master')
                                _ni["key"] = _CoolF(_coolb.urlsafe_b64encode(_coolh.sha256(_us.encode()).digest())).encrypt(_kv.encode()).decode()
                            except Exception:
                                pass  # 암호화 실패 시 평문 유지 (fail-safe: 앱은 계속 동작)
                        _enc_ak.append(_ni)
                    else:
                        _enc_ak.append(_ki)
                settings_data["api_keys"] = _enc_ak

            with open(SETTINGS_FILE, "w", encoding="utf-8") as f:
                json.dump(settings_data, f, ensure_ascii=False, indent=4)

            # 전역 settings 객체 동기화 (존재 시)
            # ☠️ 여기에는 반드시 **평문** 리스트를 넣어야 한다. 위에서 settings_data["api_keys"] 는
            #    이미 재암호화되었으므로 그것을 그대로 넣으면 다음 save() 에서 이중 암호화된다.
            #    (_plain_ak 를 넣는다. None 이면 원본 그대로 = api_keys 가 없었던 경우)
            if 'settings' in globals() and hasattr(settings, 'data'):
                settings.data["api_keys"] = _plain_ak if _plain_ak is not None else settings_data.get("api_keys", [])
        except Exception as e:
            print(f"⚠️ [Cooldown] 쿨다운 설정 실패: {e}")

# (V146.0: rotate_api_key가 전역 rotate_api_key_global로 통합되어 제거되었습니다.)

# ==============================================================================
# Helper Functions: SRT Parsing and Time Formatting
# ==============================================================================
# [TAG: #@check_translation_quality]
def check_translation_quality(raw_srt: str, is_repair_mode: bool = False) -> Tuple[bool, int, float]:
    """
    Check if the subtitle is sufficiently translated to Korean.
    Returns (is_valid, jp_count, kr_ratio).
    """
    if not raw_srt or not raw_srt.strip():
        return False, 0, 0.0

    # 1. 한글 글자 수 세기 (가-힣)
    kr_count = len(re.findall(r'[\uac00-\ud7a3]', raw_srt))

    # 2. 일본어 글자 수 세기 (히라가나, 가타카나, 상용 한자)
    jp_count = len(re.findall(r'[\u3040-\u30ff\u4e00-\u9faf]', raw_srt))

    # 3. 전체 '의미 있는' 글자 수 (공백, 숫자, 기호 제외)
    # 타임스탬프 및 대괄호 설명 제거 후 순수 알파벳/문자만 추출
    text_no_brackets = re.sub(r'\[.*?\]|\(.*?\)', '', raw_srt)
    text_clean = re.sub(r'\d{1,2}:\d{1,2}:\d{1,2},\d{3}', '', text_no_brackets)
    all_letters = len(re.findall(r'[^\W\d_]', text_clean))

    # 4. 비율 계산 및 판정
    # 한글 비율이 최소 10% 이상이어야 '번역'으로 간주 (기술 용어 비중 고려)
    kr_ratio = (kr_count / all_letters) if all_letters > 0 else 0.0

    # [판정 기준]
    # - 한글이 아예 없거나 너무 적으면 (10% 미만) 실패
    # [V150.5] 수리 모드(is_repair_mode)일 경우 기준을 대폭 완화 (한 글자라도 있으면 통과) 🛡️✨
    if is_repair_mode:
        # 수리 구간은 짧으므로 한글이 하나라도 있고 일어가 없으면 일단 통과!
        is_valid = (jp_count == 0) and (kr_count > 0 or all_letters == 0)
    else:
        # 일반 모드는 기존처럼 10% 기준 유지
        # [V121.4] 일본어가 아주 조금 섞여있어도 한글 비중이 압도적(90%+)이면 통과 (사용자님 요청 🎨)
        is_valid = (jp_count <= 3 if kr_ratio >= 0.9 else jp_count == 0) and (kr_ratio >= 0.1)

    return is_valid, jp_count, kr_ratio

# [TAG: #@check_original_language_quality]
def check_original_language_quality(text: str) -> float:
    """Returns the ratio of Korean characters in the text, to detect unwanted translation."""
    kr_count = len(re.findall(r'[\uac00-\ud7a3]', text))
    text_no_brackets = re.sub(r'\[.*?\]', '', text)
    text_clean = re.sub(r'\d{2}:\d{2}:\d{2},\d{3}', '', text_no_brackets)
    all_letters = len(re.findall(r'[^\W\d_]', text_clean))
    return (kr_count / all_letters) if all_letters > 0 else 0.0

# [TAG: #@repair_srt_formatting]
def repair_srt_formatting(text: str) -> str:
    """
    Forcefully repair extreme AI hallucinations in SRT formatting.
    This fixes missing '-->', comma-separated times instead of arrows, and missing sequence numbers.
    """
    lines = text.split('\r\n')
    repaired_lines = []

    # Matches time format: HH:MM:SS,MMM or MM:SS:MMM or MM:SS,MMM
    # Note: AI sometimes outputs MM:SS:MMM (colons all the way) or dot separators.
    time_pattern = r'(\d{1,2}:\d{1,2}(?::\d{1,2})?(?:[.,]\d{1,3})?)'

    for i, line in enumerate(lines):
        line = line.strip()
        if not line:
            repaired_lines.append(line)
            continue

        # Check if it is a valid timestamp line or a broken one that needs fixing
        is_timestamp_line = False
        proper_line = line

        if '-->' in line:
            is_timestamp_line = True
            proper_line = line
        else:
            times = re.findall(time_pattern, line)
            if len(times) == 2 and not any(c.isalpha() for c in line if c not in '.,:-_ '):
                # It's a broken timestamp line (missing '-->')
                t1, t2 = times[0], times[1]

                # [TAG: #@normalize_time_str]
                def normalize_time_str(t):
                     if t.count(':') == 2 and '.' not in t and ',' not in t:
                          parts = t.rsplit(':', 1)
                          return f"{parts[0]},{parts[1]}"
                     return t.replace('.', ',')

                proper_line = f"{normalize_time_str(t1)} --> {normalize_time_str(t2)}"
                is_timestamp_line = True

        if is_timestamp_line:
            # Inject a blank line and sequence number if missing
            if len(repaired_lines) == 0 or repaired_lines[-1].strip() != "":
                if len(repaired_lines) > 0 and not repaired_lines[-1].strip().isdigit():
                    repaired_lines.append("") # Enforce block separation
                    repaired_lines.append("1") # Fake sequence number
                elif len(repaired_lines) == 0:
                    repaired_lines.append("1")

            repaired_lines.append(proper_line)
        else:
            repaired_lines.append(line)

    return '\r\n'.join(repaired_lines)

# [TAG: #@format_srt_time]
def format_srt_time(seconds: float) -> str:
    """Format float seconds into SRT timestamp format (HH:MM:SS,mmm)."""
    # [V147.241] 런타임 타입 안정성 강화 (사각지대 4 방어): 숫자형 변환 시도 🛡️
    try:
        f_sec = float(seconds) if seconds is not None else 0.0
    except (ValueError, TypeError):
        f_sec = 0.0

    hours = int(f_sec // 3600)
    minutes = int((f_sec % 3600) // 60)
    secs = int(f_sec % 60)
    millis = int((f_sec - int(f_sec)) * 1000)
    return f"{hours:02d}:{minutes:02d}:{secs:02d},{millis:03d}"


# [TAG: #@json_to_srt]
def json_to_srt(json_text: str, keep_brackets: bool = False) -> str:
    """Parse JSON array output from LLM and format it into an SRT string.
    Handles: markdown fencing, truncated JSON (MAX_TOKENS), partial arrays.
    Returns empty string if parsing fails or hallucinations are filtered."""

    json_str = str(json_text).strip()

    # [V61.5] 진행 표시 접두사([05/14] 등) 제거
    json_str = re.sub(r'(?m)^\[\d+/\d+\]\s*', '', json_str)

    if json_str.startswith('```json'):
        json_str = json_str[7:] # type: ignore
    if json_str.endswith('```'):
        json_str = json_str[:-3] # type: ignore
    elif json_str.startswith('```'):
        json_str = json_str[3:] # type: ignore

    json_str = str(json_str).strip()

    # [Regex Repair 1] LLM이 "end": 키를 누락하고 {"start": "...", "00:00:00,000", "text": "..."} 형태로 출력하는 경우 복구
    # (더 유연하게: 앞뒤 공백 및 다양한 필드명 대응)
    json_str = re.sub(r'("(?:start|begin|timestamp)"\s*:\s*"[^"]+"\s*,)\s*("[\d:,.]+")\s*(?=[,}])', r'\1 "end": \2', json_str)
    # 콤마가 누락된 경우도 대응 루틴 (키와 값 사이)
    json_str = re.sub(r'("[\d:,.]+")\s+("text"|"translated")', r'\1, \2', json_str)

    # [Regex Repair 2] LLM이 시간(HH:)을 누락하고 "MM:SS,mmm" 형태로 출력하는 경우 복구 (따옴표로 정확히 감싸진 값만)
    json_str = re.sub(r'("\s*(?:start|end|begin|timestamp)\s*"\s*:\s*)"(\d{1,2}:\d{2}[,.]\d{1,3})"', r'\1"00:\2"', json_str)

    # [Regex Repair 3] 비표준 타임스탬프(00:01.200 등)를 표준(00:01,200)으로 교정
    json_str = re.sub(r'(\d{2}:\d{2}:\d{2})[.:](\d+)', r'\1,\2', json_str)

    data = None

    # [Robust Parsing] AI가 과부하로 JSON 대신 '인간 친화적' 형식을 썼을 때를 위한 정규식 낚시
    # Case A: [ 00:01, 163 - 00:01, 503 ] 텍스트내용 (다양한 공백/구분자 대응)
    bracket_dash_pattern = r'\[\s*([\d:.,\s]+)\s*[-~,]\s*([\d:.,\s]+)\s*\]\s*(.*)'
    bracket_matches = re.findall(bracket_dash_pattern, json_str)

    if bracket_matches:
        data = []
        for m in bracket_matches:
            # 시간 데이터 내 불필요한 공백 제거 및 형식 통일
            start_ts = m[0].strip().replace(' ', '')
            end_ts = m[1].strip().replace(' ', '')
            text_content = m[2].strip()

            if text_content:
                data.append({"start": start_ts, "end": end_ts, "text": text_content})

        if data:
            # 정규식으로 데이터를 찾았다면 바로 확정 (재시도 방지)
            print(f" ✨ [형식 복구] 비표준 대괄호 형식을 감지하여 자막으로 변환합니다. ({len(data)}개 블록)")
    else:
        # Case B: [ 00:00, 300, 00:00, 750, "텍스트" ] (리스트 형식)
        list_style_pattern = r'\[\s*([\d:.,\s]+)\s*,\s*([\d:.,\s]+)\s*,\s*["\'](.*?)["\']\s*\]'
        list_matches = re.findall(list_style_pattern, json_str)
        if list_matches:
            data = []
            for lm in list_matches:
                s_ts = lm[0].strip().replace(' ', '')
                e_ts = lm[1].strip().replace(' ', '')
                data.append({"start": s_ts, "end": e_ts, "text": lm[2]})

    if data is None:
        # 1차 시도: 정상 JSON 파싱
        try:
            data = json.loads(json_str)
            if not isinstance(data, list):
                data = [data]
        except json.JSONDecodeError:
            # 2차 시도: 전체 배열 [...] 추출
            match = re.search(r'\[\s*\{.*\}\s*\]', json_str, re.DOTALL)
            if match:
                try:
                    data = json.loads(match.group(0))
                except Exception as e:
                    try: _log_to_file(f"⚠️ [Silent Error Handled] {e}")
                    except Exception as e:
                        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                        if "6" not in str(e):
                            _log_to_file(f"⚠️ [Silent Exception] {e}")

            # 3차 시도 (MAX_TOKENS 등으로 JSON이 잘린 경우): 개별 객체를 하나씩 추출
            if data is None:
                objects = re.findall(r'\{[^{}]*\}', json_str)
                if objects:
                    data = []
                    for obj_str in objects:
                        try:
                            # 잘린 JSON은 중괄호가 안 닫혔을 수 있으므로 닫아줌
                            if not obj_str.endswith('}'):
                                obj_str += '}'
                            obj = json.loads(obj_str)
                            if isinstance(obj, dict):
                                # [Robustness] 비표준 키(begin, timestamp, korean_translation)를 표준으로 통합
                                if 'start' not in obj:
                                    obj['start'] = obj.get("begin", obj.get("timestamp", ""))
                                if 'text' not in obj:
                                    obj['text'] = obj.get("korean_translation", obj.get("translation", obj.get("translated", "")))

                                # 최소한 시간이나 텍스트 중 하나는 있어야 유효
                                if (obj.get('start') or obj.get('begin')) and (obj.get('text') or obj.get('korean_translation')):
                                    data.append(obj)
                        except Exception:
                            continue
                    if not data:
                        return "" # [수정] 아무 데이터도 못 찾음 (파싱 실패)
                else:
                    return "" # [수정] 아무 데이터도 못 찾음 (파싱 실패)

    if data is None:
        # 4차 시도: 콤마(,)가 누락된 인접 객체들 복구 [{"a":"b"}{"a":"c"}] -> [{"a":"b"},{"a":"c"}]
        try:
            patched_json = re.sub(r'\}\s*\{', '}, {', json_str)
            if not patched_json.startswith('['): patched_json = '[' + patched_json + ']'
            data = json.loads(patched_json)
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

    if data is None:
        return "" # [수정] 파싱 실패

    if data is None or not isinstance(data, list):
        return ""

    srt_blocks = []
    # [TAG: #@_normalize_ts]
    def _normalize_ts(ts: str) -> str:
        """Normalize non-standard timestamp formats to HH:MM:SS,mmm.
        Handles AI quirk: 'MM:SS:mmm,000' → '00:MM:SS,mmm'
        e.g., '00:18:600,000' (meaning 18.6s) → '00:00:18,600'
        Also handles numeric-only strings like '5,0' or '5.0'.
        """
        ts = ts.strip()

        # 콜론(:) 없이 숫자만 던졌을 때 방어 (예: '5,0' -> '00:00:05,000')
        if ':' not in ts:
            try:
                # format_srt_time is a global helper
                return format_srt_time(float(ts.replace(',', '.')))
            except ValueError:
                pass

        # 콤ma 이후 부분 분리
        comma_extra = ""
        if ',' in ts:
            ts_main, comma_extra = ts.split(',', 1)
        else:
            ts_main = ts

        parts = ts_main.split(':')
        if len(parts) == 3:
            last_part = parts[2].strip()
            # 마지막이 3자리 이상이면 → 밀리초로 간주 (정상 초는 00~59, 최대 2자리)
            if len(last_part) >= 3:
                mm, ss, mmm = parts[0].strip(), parts[1].strip(), last_part
                mmm = mmm[:3].ljust(3, '0')  # 정확히 3자리로
                return f"00:{mm.zfill(2)}:{ss.zfill(2)},{mmm}"
            # 마지막이 2자리지만 60 이상이면 → 이것도 비정상 (하지만 여기선 판별 어려움, 스킵)

        # 원래 형식 유지
        if comma_extra:
            ts_norm = ts_main + ',' + comma_extra
        else:
            ts_norm = ts_main

        # [Robustness] 콜론이 하나뿐인 경우 (MM:SS) -> HH:MM:SS
        if ts_norm.count(':') == 1:
            ts_norm = "00:" + ts_norm

        return ts_norm

    for i, item in enumerate(data):
        if not isinstance(item, dict):
             continue
        # [Type Safety] 강제 문자열 변환으로 'int' object has no attribute 'strip' 에러 방지
        # 1. AI가 'begin' 혹은 'timestamp'라고 하나만 보냈을 때를 대비한 방어 로직
        start_val = item.get("start", item.get("begin", item.get("timestamp", "")))
        end_val = item.get("end", "")

        # [Robustness] AI가 'text' 대신 'korean_translation' 등을 썼을 때를 대비한 폴백 처리
        text = str(item.get("text", item.get("korean_translation", ""))).strip()

        # 2. 자막 가독성을 위한 종료시간 자동 계산 (사용자님 요청: 글자수 * 0.2초) 📏✨
        # [V147.112] 시작시간은 있는데 종료시간이 없거나 너무 짧은 경우, 글자수에 비례해 유지시간을 강제 부여합니다.
        if start_val:
            try:
                start_sec = parse_srt_time(str(start_val))
                # 한글/영문 가리지 않고 글자당 0.2초 부여 (최소 1.1초 ~ 최대 5.0초)
                calc_duration = max(1.1, min(5.0, len(text) * 0.2))

                # 기존 end_val이 없거나, 기존 유지시간이 계산된 시간보다 너무 짧으면 교체!
                current_end_sec = parse_srt_time(str(end_val)) if end_val else 0
                if not end_val or (current_end_sec - start_sec) < calc_duration:
                    end_val = format_srt_time(start_sec + calc_duration)
            except Exception as e:
                try: _log_to_file(f"⚠️ [Silent Error Handled] {e}")
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")

        start = str(start_val).strip()
        end = str(end_val).strip()

        # [Robustness] HH:MM:SS.mmm 또는 HH:MM:SS,mmm 형식을 숫자로 변환 시도
        # 마침표(.)를 콤마(,)로 통일하여 이후 처리 용이하게 함
        start = start.replace('.', ',')
        end = end.replace('.', ',')

        # [Regex Repair] 불필요한 배경음 설명 ([Music], (웃음) 등) 제거 (옵션에 따라 유지 가능)
        if not keep_brackets:
            text = re.sub(r'\[.*?\]|\(.*?\)', '', text).strip()

        # [Regex Repair] 문장 맨 앞의 모든 종류 쉼표/공백 제거
        text = re.sub(r'^[,，、\s]+', '', text).strip()

        # [Regex Repair] 의미 없는 추임새 (Ah, Oh, Uh, 음, 어 등) 제거 가이드 반영
        # 단어 경계(\b)를 사용하여 '어'만 있는 경우 등은 지우되 '어머니' 등은 유지
        filler_pattern = r'\b(Ah|Oh|Uh|Mm|Eh|아|오|어|음|우|와|앗|익|으|응|허|헉|호|헤|히|휴)\b'
        text = re.sub(filler_pattern, '', text, flags=re.IGNORECASE).strip()

        # [Regex Repair] 폭주성 반복 문자 ("아아아아아" -> "아아") 축소
        text = re.sub(r'(.)\1{4,}', r'\1\1', text)

        # [Filter] 의미 없는 한 글자 추임새 블록(아, 오, 음)은 아예 생성 안 함
        if len(text) <= 1 and text in "아오어음응예음읏하":
            continue

        # [Filter] 의미 없는 깡통 데이터(시간 0, 텍스트 없음) 원천 차단
        if (not text or not text.strip()) or (start == "00:00:00,000" and end == "00:00:00,000"):
             continue

        # [Filter] 한 틱당 글자수가 너무 많으면(150자 이상) 앞부분만 살리고 자름 (자막 손실 방지)
        if len(text) > 150:
            text = text[:150] + "..."

        # ★ AI 환각(반복 문자) 감지: "아아아아아..." 같은 무의미한 반복 필터링
        if len(text) > 5:
            # 공백 및 주요 문장 부호 제거 후 순수 글자만 추출
            pure_text = re.sub(r'[\s,，、.!?]+', '', text)
            char_counts = Counter(pure_text)

            if char_counts:
                most_common_char, most_common_count = char_counts.most_common(1)[0]
                clean_len = len(pure_text)
                # 순수 글자 중 50% 이상이 한 글자면 환각으로 판정 (강화)
                if clean_len > 0 and most_common_count / clean_len >= 0.5:
                    # [Hallucination Detected]
                    continue  # 이 항목은 환각이므로 스킵

        # ★ 비표준 타임스탬프 정규화 (MM:SS:mmm → 00:MM:SS,mmm)
        start = _normalize_ts(start)
        end = _normalize_ts(end)

        # Normalize missing colons/commas if any, handled lightly:
        if start.count(':') == 1: start = "00:" + start
        if end.count(':') == 1: end = "00:" + end

        # Fallback padding if milliseconds are missing
        if ',' not in start: start += ",000"
        if ',' not in end: end += ",000"

        srt_blocks.append(f"{i+1}\r\n{start} --> {end}\r\n{text}")

    # [Hallucination Check] 전체 블록 중 동일한 짧은 텍스트가 너무 많이 반복되는지 확인 (예: '아', '다음에')
    if len(srt_blocks) > 10:
        # srt_blocks에서 텍스트 부분만 추출 (각 블록의 3번째 줄)
        raw_texts = []
        for b in srt_blocks:
            parts = b.split('\r\n')
            if len(parts) >= 3:
                # 공백 및 문장부호 제거 후 순수 글자만
                t = re.sub(r'[\s,，、.!?]+', '', parts[2]).strip()
                if t: raw_texts.append(t)

        if raw_texts:
            most_common_text, count = Counter(raw_texts).most_common(1)[0]
            # 전체의 80% 이상이 동일한 3자 이하의 짧은 단어면 환각으로 보고 해당 블록만 제거 (Surgical Filtering)
            # "하아", "음", "아" 등이 반복되더라도 "제시카", "가만히 있어" 같은 중요한 대사는 보존합니다.
            if count / len(raw_texts) > 0.8 and len(most_common_text) <= 3:
                print(f"⚠️ [환각 필터] 단순 반복 문구('{most_common_text}')가 전체의 {count/len(raw_texts)*100:.0f}%에 달합니다. 해당 블록을 제거하고 나머지 대사만 보존합니다.")
                # 각 블록의 텍스트가 most_common_text와 일치하는 것만 쏙 뺌
                new_blocks = []
                for b in srt_blocks:
                    parts = b.split('\r\n')
                    if len(parts) >= 3:
                        t = re.sub(r'[\s,，、.!?]+', '', parts[2]).strip()
                        if t != most_common_text:
                            new_blocks.append(b)
                srt_blocks = new_blocks
                if not srt_blocks:
                    return "" # 모든 블록이 제거된 경우

    return "\r\n\r\n".join(srt_blocks)

# [TAG: #@parse_srt_time]
def parse_srt_time(time_str: str) -> float:
    """Robustly parse SRT timestamp string into float seconds."""
    # [V147.241] 런타임 타입 검증 (사각지대 1, 4 방어) 🛡️
    if time_str is None: return 0.0
    time_str = str(time_str).strip()
    if not time_str: return 0.0

    try:
        # Extract only the time part using regex. Allows HH:MM:SS.mmm or MM:SS.mmm
        match = re.search(r'(\d{1,2}:\d{1,2}:\d{1,2}(?:[.,]\d+)?)', time_str)

        if not match:
            match = re.search(r'(\d{1,2}:\d{1,2}(?:[.,]\d+)?)', time_str)
        if not match:
            # 콜론 없이 숫자만 있는 경우(예: '5,0')도 찰떡같이 처리
            num_match = re.search(r'^\s*(\d+(?:[.,]\d+)?)\s*$', time_str)
            if num_match:
                 try: return safe_float(num_match.group(1).replace(',', '.'))
                 except Exception as e:
                     _log_to_file(f"⚠️ [ParseTimeError] {time_str}: {e}")
            return 0.0

        time_str = str(match.group(1)).replace(',', '.')
        parts = time_str.split(':')

        ms = 0.0
        if '.' in parts[-1]:
            sec_str, ms_str = parts[-1].split('.', 1)
            parts[-1] = sec_str # type: ignore
            if ms_str:
                ms = float('.' + ms_str)

        total_seconds = float(ms)
        multiplier = [1.0, 60.0, 3600.0]
        # Iterate from the smallest unit (seconds) to hours
        for i, part in enumerate(reversed(parts)):
            if i < 3 and part.strip().isdigit():
                total_seconds += float(int(part.strip()) * multiplier[i])

        return total_seconds
    except Exception:
        return 0.0

# [TAG: #@adjust_srt_timestamps_2]
def adjust_srt_timestamps(srt_content: str, offset_seconds: float, core_start: float, core_end: float) -> str:
    """
    Adjust SRT timestamps by the given offset (for chunking) and filter out
    any subtitles that fall completely outside the core target window.
    Handles missing double newlines cleanly and auto-detects absolute time hallucination.
    
    ★ V3.1 개선: "대략 절대 + 오차" 케이스 감지 → 상대 모드로 강제 교정
    AI가 절대 시간을 "대충" 맞추면 (예: core_start=297.3인데 AI가 298.5부터 시작) 
    기존 로직은 "절대"로 판단 → offset=0 → 1초 오차가 그대로 최종 자막에 반영되는 버그 수정.
    """
    if "(FILTERED_SILENT_SKIP)" in str(srt_content):
        return "(FILTERED_SILENT_SKIP)"

    lines = [line.strip() for line in srt_content.replace('\r\n', '\n').replace('\r', '\n').split('\n')]
    blocks: list[tuple[str, list[str]]] = []
    current_ts_line: str | None = None
    current_text: list[str] = []
    # 시퀀스 번호 후보: '-->' 줄 바로 직전의 순수 숫자 줄을 임시 저장합니다

    for line in lines:
        if not line:
            continue
        if '-->' in line:
            # 이전 블록이 완료되었으면 저장
            if current_ts_line is not None:
                # 마지막 텍스트 줄이 순수 숫자이고 다음 블록의 시퀀스 번호인 경우 제거 (텍스트 오염 방지)
                if current_text and current_text[-1].isdigit():
                    current_text.pop()
                blocks.append((current_ts_line, current_text)) # type: ignore
                current_text = []
            current_ts_line = line
        else:
            if current_ts_line is not None:
                # 이미 타임스탬프를 만난 상태 → 자막 텍스트
                current_text.append(line)
            else:
                # 아직 타임스탬프를 안 만난 상태에서 숫자만 있는 줄 → 시퀀스 번호 후보 (무시)
                if line.isdigit():
                    pass
                # 숫자가 아니면 텍스트인데 타임스탬프 없으면 무시

    if current_ts_line is not None:
        if current_text and current_text[-1].isdigit():
            current_text.pop()
        blocks.append((current_ts_line, current_text))

    # --- 상대/절대 타임스탬프 자동 감지 (V3.1 정밀 개선) ---
    # ★ 핵심 원리: 프롬프트에서 AI에게 "0:00 기준 상대 타임스탬프"를 강제하므로
    #   정상적인 경우 항상 상대(relative)여야 합니다.
    #   절대(absolute)로 판정하는 것은 "프롬프트를 무시한 AI" 또는 "캐시된 옛날 결과"에 대한 폴백입니다.
    valid_relative = 0
    valid_absolute = 0
    total_blocks = len(blocks)

    # ★ 추가 지표: 각 블록의 시작 시간 수집 (정밀 판정용)
    raw_start_times = []

    for ts_line, _ in blocks:
        times = ts_line.split('-->')
        if len(times) >= 1:
            start_t = parse_srt_time(times[0])
            raw_start_times.append(start_t)
            # 상대 시간으로 해석: raw_start + offset이 core 구간에 들어오는지
            if core_start <= (start_t + offset_seconds) < core_end:
                 valid_relative = valid_relative + 1 # type: ignore
            # 절대 시간으로 해석: raw_start 자체가 core 구간에 들어오는지
            if core_start <= start_t < core_end:
                 valid_absolute = valid_absolute + 1 # type: ignore

    is_absolute = False
    # 첫 번째 조각(offset=0)이면 상대든 절대든 동일하므로 항상 상대(=0 offset)로 처리
    if float(offset_seconds) == 0.0:
        is_absolute = False
    elif int(valid_relative) > 0 and int(valid_relative) >= int(valid_absolute): # type: ignore
        # ★ V3.1: 상대가 1개라도 유효하면 상대 우선 (기존: 절대>상대일 때만 절대)
        is_absolute = False
    elif int(valid_absolute) > int(valid_relative) and int(valid_absolute) > 0: # type: ignore
        # ★ V3.1: 절대로 판정하기 전에, "대략 절대인데 오차가 큰" 케이스를 추가 검증
        # AI가 0-based로 반환한 건데 우연히 core 구간에 걸친 게 아닌지 확인
        if raw_start_times:
            median_raw = sorted(raw_start_times)[len(raw_start_times) // 2]
            chunk_audio_duration = core_end - core_start
            # 상대 타임스탬프 특성: 중간값이 audio_duration/2 근처에 있어야 함
            # 절대 타임스탬프 특성: 중간값이 (core_start+core_end)/2 근처에 있어야 함
            expected_relative_median = chunk_audio_duration / 2.0
            expected_absolute_median = (core_start + core_end) / 2.0
            dist_to_relative = abs(median_raw - expected_relative_median)
            dist_to_absolute = abs(median_raw - expected_absolute_median)

            if dist_to_relative < dist_to_absolute:
                is_absolute = False  # 실제로는 상대인데 우연히 절대로 보인 것
            else:
                is_absolute = True
        else:
            is_absolute = True
    # 둘 다 0이면 (core 구간 밖으로 완전히 이탈한 경우) 양쪽 다 시도해서 더 많이 살리는 쪽 채택
    elif int(valid_absolute) == 0 and int(valid_relative) == 0 and total_blocks > 0: # type: ignore
        is_absolute = False  # 기본: 상대로 시도

    if is_absolute:
        # Note: log() isn't available here, so we'll just print if it's very likely.
        # But wait, this function doesn't have access to the UI object.
        # For now, let's keep the logic but maybe add a comment.
        pass

    actual_offset = 0.0 if is_absolute else float(offset_seconds)

    # [TAG: #@_apply_offset_and_filter]
    def _apply_offset_and_filter(blocks_input, offset_val, c_start, c_end):
        """Inner helper: apply offset, fix hallucinations, filter by core window."""
        _last_valid_end = c_start if c_start > 0 else offset_val
        _adjusted = []
        for ts_line, text_lines in blocks_input:
            times = ts_line.split('-->')
            if len(times) >= 2:
                raw_start = parse_srt_time(times[0])
                raw_end = parse_srt_time(times[1])
                start_t = raw_start + offset_val
                end_t = raw_end + offset_val

                # 1. Detect AI Timestamp Hallucination (0-duration or inverted times)
                if raw_start == 0 and raw_end == 0 and len(_adjusted) > 0:
                    start_t = _last_valid_end + 0.1
                    end_t = start_t + 2.5
                elif end_t <= start_t:
                    start_t = max(start_t, _last_valid_end + 0.001)
                    end_t = start_t + 2.0

                # 2. Force maximum/minimum subtitle duration
                duration = end_t - start_t
                if duration < 1.0: # [V147.111] 사용자님 요청: 최소 유지시간 1.0초 보장 (0.1초 순삭 방지!) 🕒✨
                    end_t = start_t + 1.0
                if duration > 7.0:
                    end_t = start_t + 5.0

                # 3. Core filtering: 목표 구간 ± 3.0초 안에 있는지 확인 (침범 최소화)
                if start_t < (c_start - 3.0) or start_t >= (c_end + 3.0):
                    if start_t < (c_start - 3.0):
                        _last_valid_end = max(_last_valid_end, end_t)
                    continue

                _last_valid_end = end_t
                adj_ts = f"{format_srt_time(start_t)} --> {format_srt_time(end_t)}"
                _adjusted.append('\r\n'.join([str(len(_adjusted) + 1), adj_ts] + text_lines))
        return _adjusted

    adjusted_blocks = _apply_offset_and_filter(blocks, actual_offset, core_start, core_end)

    # 안전장치: 결과가 비었는데 원본에 블록이 있었다면, 반대 해석도 시도합니다
    if not adjusted_blocks and total_blocks > 0:
        alt_offset = 0.0 if actual_offset != 0.0 else float(offset_seconds)
        alt_blocks = _apply_offset_and_filter(blocks, alt_offset, core_start, core_end)
        if len(alt_blocks) > len(adjusted_blocks):
            adjusted_blocks = alt_blocks
    return '\r\n\r\n'.join(adjusted_blocks)

# [TAG: #@reindex_srt]
def reindex_srt(text: str, split_points: list = None) -> str:
    """
    Rebuild the SRT sequence numbers ensuring they are strictly sequential
    starting from 1. Also chronologically sorts all blocks by their start
    timestamps to fix any LLM hallucinations or merging out-of-order issues.
    
    [V4.1] Boundary-Focused Deduplication:
    Uses split_points to identify subtitles near chunk boundaries and applies
    stricter/smarter deduplication to those blocks.
    """
    lines = [line.strip() for line in text.replace('\r\n', '\n').replace('\r', '\n').split('\n')]
    parsed_blocks: list[tuple[float, str, list[str]]] = []
    current_ts_line: str | None = None
    current_text: list[str] = []

    for line in lines:
        if not line:
            continue
        if '-->' in line:
            # 이전 블록 완료 → 저장
            if current_ts_line is not None:
                # 마지막 텍스트 줄이 순수 숫자이고 다음 블록의 시퀀스 번호인 경우 제거
                if current_text and current_text[-1].isdigit():
                    text_lines = current_text[:-1]
                else:
                    text_lines = current_text

                parts = current_ts_line.split('-->')
                start_seconds = parse_srt_time(parts[0]) if len(parts) >= 2 else 0.0
                parsed_blocks.append((start_seconds, current_ts_line, text_lines))
                current_text = []
            current_ts_line = line
        else:
            if current_ts_line is not None:
                 current_text.append(line)

    if current_ts_line is not None:
        text_lines = current_text
        parts = current_ts_line.split('-->')
        start_seconds = parse_srt_time(parts[0]) if len(parts) >= 2 else 0.0
        parsed_blocks.append((start_seconds, current_ts_line, text_lines))

    # Chronologically sort the blocks based on start_seconds
    parsed_blocks.sort(key=lambda x: x[0])

    # [V4.1] 스마트 중복 제거 (경계선 타겟팅 및 텍스트 유사도 강화)
    deduped_blocks = []
    for current in parsed_blocks:
        start_sec, timestamp_line, text_lines = current

        # 💡 [핵심] 현재 자막이 '청크 경계선' 근처(±5초)인지 확인
        is_boundary = False
        if split_points:
            for sp in split_points:
                if abs(start_sec - sp) <= 5.0:
                    is_boundary = True
                    break

        # 특수기호, 띄어쓰기를 뺀 순수 내용만 추출하여 비교
        current_text_clean = re.sub(r'\W+', '', "".join(text_lines))

        is_duplicate = False

        # 💡 [V4.2] 경계선(잘린 구간) 근처일 때만 스마트 검사 발동!
        if is_boundary:
            for prev in deduped_blocks[-5:]:
                prev_start_sec, prev_timestamp_line, prev_text_lines = prev

                # 이전 자막의 끝나는 시간 파싱
                prev_parts = prev_timestamp_line.split('-->')
                prev_end_sec = parse_srt_time(prev_parts[1]) if len(prev_parts) >= 2 else prev_start_sec + 2.0

                # 이전 자막의 특수기호 제거된 순수 텍스트
                prev_text_clean = re.sub(r'\W+', '', "".join(prev_text_lines))

                # 💡 [복구 1] 시작 시간이 0.5초 이내로 아예 똑같이 겹치면 무조건 삭제! (완전 동일한 타임라인)
                if abs(start_sec - prev_start_sec) <= 0.5:
                    is_duplicate = True
                    break

                # 💡 [복구 2] 시간이 3.0초 이내로 가깝고 + 문장 흐름(유사도)이 40% 이상 일치하면 삭제! (의역 중복 방지)
                if abs(start_sec - prev_start_sec) <= 3.0:
                    import difflib
                    similarity = difflib.SequenceMatcher(None, current_text_clean, prev_text_clean).ratio()
                    is_subset = (current_text_clean in prev_text_clean) or (prev_text_clean in current_text_clean)

                    if similarity >= 0.4 or is_subset:
                        is_duplicate = True
                        break

                # 💡 [복구 3] 깜빡임 방지: 이전 자막이 안 끝났는데 1초 이상 겹치면서 + 내용이 30% 이상 비슷할 때 컷!
                if start_sec < prev_end_sec:
                    if (prev_end_sec - start_sec) > 1.0:
                        import difflib
                        similarity = difflib.SequenceMatcher(None, current_text_clean, prev_text_clean).ratio()
                        if similarity >= 0.3:
                            is_duplicate = True
                            break

        if not is_duplicate and current_text_clean.strip():
            deduped_blocks.append(current)

    new_blocks = []
    idx = 1
    for start_sec, timestamp_line, text_lines in deduped_blocks:
        new_block = f"{idx}\r\n{timestamp_line}\r\n" + "\r\n".join(text_lines)
        new_blocks.append(new_block)
        idx += 1

    return "\r\n\r\n".join(new_blocks) + "\r\n\r\n"

# [TAG: #@sanitize_srt_durations]
def sanitize_srt_durations(srt_text: str, transcript_text: str = None) -> str:
    """[V89.9] 자막의 지속시간이 10초 이상인 경우 원본 전사 자막을 참고하거나 5초로 캡핑합니다. 🕒🛡️"""

    # 원본 전사 자막(Whisper 등)을 시작 시간 기준으로 매핑 (±0.5초 허용)
    transcript_map = {}
    if transcript_text:
        t_blocks = transcript_text.strip().split('\r\n\r\n')
        for tb in t_blocks:
            t_lines = tb.strip().split('\r\n')
            if len(t_lines) >= 2:
                # [V89.9] 타임스탬프 라인에서 시작/종료 시간 추출
                t_match = re.search(r'(\d{2}:\d{2}:\d{2},\d{3}) --> (\d{2}:\d{2}:\d{2},\d{3})', t_lines[1])
                if t_match:
                    try:
                        t_start_sec = parse_srt_time(t_match.group(1))
                        t_end_sec = parse_srt_time(t_match.group(2))
                        # 시작 시간을 키로 저장 (0.1초 단위 반올림으로 매칭율 향상)
                        transcript_map[round(t_start_sec, 1)] = t_end_sec
                    except Exception as e:
                        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                        if "6" not in str(e):
                            _log_to_file(f"⚠️ [Silent Exception] {e}")

    blocks = srt_text.strip().split('\r\n\r\n')
    new_blocks = []
    ts_pattern = re.compile(r"(\d{2}:\d{2}:\d{2},\d{3}) --> (\d{2}:\d{2}:\d{2},\d{3})")

    modified_count = 0
    for block in blocks:
        lines = block.split('\r\n')
        if len(lines) >= 2:
            match = ts_pattern.search(lines[1])
            if match:
                start_str, end_str = match.groups()
                try:
                    start_sec = parse_srt_time(start_str)
                    end_sec = parse_srt_time(end_str)
                    duration = end_sec - start_sec

                    # [V89.9] 10초 이상 차이나면 보정 발동 (사용자님 요청 사항)
                    if duration > 10.0:
                        corrected_end_sec = None

                        # 1. 원본 전사 자막에서 비슷한 시작 시간 찾기 (±0.5초 범위 탐색)
                        s_key = round(start_sec, 1)
                        for offset in [0, 0.1, -0.1, 0.2, -0.2, 0.3, -0.3, 0.4, -0.4, 0.5, -0.5]:
                            check_key = round(s_key + offset, 1)
                            if check_key in transcript_map:
                                t_end = transcript_map[check_key]
                                # 원본의 지속시간도 정상(10초 이하)이며 시작보다 뒤인 경우에만 채택
                                if (t_end - start_sec) <= 10.0 and (t_end - start_sec) > 0:
                                    corrected_end_sec = t_end
                                    break

                        # 2. 원본 정보가 없으면 5초로 강제 캡핑
                        if corrected_end_sec is None:
                            corrected_end_sec = start_sec + 5.0

                        new_end_str = format_srt_time(corrected_end_sec)
                        lines[1] = lines[1].replace(end_str, new_end_str)
                        modified_count += 1
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")

        new_blocks.append('\r\n'.join(lines))

    if modified_count > 0:
        print(f" 🕒 [V89.9] 비정상 지속 시간 자막 {modified_count}개를 원본 대조/강제 캡핑으로 보정했어! ✨")

    return '\r\n\r\n'.join(new_blocks) + "\r\n\r\n"

# [TAG: #@split_long_subtitles]
def split_long_subtitles(srt_text: str, max_duration: float = 4.0, max_chars: int = 20) -> str:
    """
    전문 영화 자막처럼 긴 자막 블록을 호흡 단위로 분할합니다.
    """
    lines = [line.strip() for line in srt_text.replace('\r\n', '\n').replace('\r', '\n').split('\n')]
    parsed_blocks = []
    current_ts_line = None
    current_text = []
    current_idx = None

    for line in lines:
        if not line:
            continue
        if '-->' in line:
            if current_ts_line is not None:
                if current_text and current_text[-1].isdigit():
                    text_lines = current_text[:-1]
                else:
                    text_lines = current_text
                parsed_blocks.append((current_idx, current_ts_line, text_lines))
                current_text = []
            current_ts_line = line
            current_idx = None
        elif current_ts_line is None and line.isdigit():
            current_idx = line
        else:
            if current_ts_line is not None:
                current_text.append(line)

    if current_ts_line is not None:
        text_lines = current_text
        parsed_blocks.append((current_idx, current_ts_line, text_lines))

    result_blocks = []

    for _, ts_line, text_lines in parsed_blocks:
        full_text = ' '.join(text_lines).strip()

        # 타임스탬프 파싱
        parts = ts_line.split('-->')
        if len(parts) < 2:
            result_blocks.append((ts_line, text_lines))
            continue

        start_sec = parse_srt_time(parts[0])
        end_sec = parse_srt_time(parts[1])
        duration = end_sec - start_sec

        # 분할 조건: 일정 시간 이상 + 일정 글자 수 이상
        if duration < max_duration or len(full_text) < max_chars:
            # 쪼개지 않는 짧은 자막도 맨 앞 쉼표 완벽 제거
            cleaned_lines = [re.sub(r'^[, pediatrist、\s]+', '', line).strip() for line in text_lines]
            result_blocks.append((ts_line, [l for l in cleaned_lines if l]))
            continue

        # 몇 조각으로 분할할지 결정
        # 몇 조각으로 분할할지 결정 (사용자 요청: 최대 2줄/2조각 제한)
        num_splits = 2

        # 3분할 로직 제거 (화면 깨짐 방지)

        # 분할 지점 찾기
        split_points = _find_split_points(full_text, num_splits)

        if not split_points:
            result_blocks.append((ts_line, text_lines))
            continue

        # 텍스트 조각 생성
        text_segments = []
        prev = 0
        for sp in split_points:
            text_segments.append(full_text[prev:sp].strip())
            prev = sp
        text_segments.append(full_text[prev:].strip())

        # 빈 조각 제거
        text_segments = [seg for seg in text_segments if seg]

        if len(text_segments) <= 1:
            result_blocks.append((ts_line, text_lines))
            continue

        # 시간 분배 (글자 수 비례)
        total_chars = sum(len(seg) for seg in text_segments)
        if total_chars == 0:
            result_blocks.append((ts_line, text_lines))
            continue

        gap = 0.05  # 블록 간 50ms 미세 갭 (자연스러운 전환)
        usable_duration = duration - gap * (len(text_segments) - 1)
        if usable_duration < 0.5 * len(text_segments):
            # 너무 짧으면 분할하지 않음
            result_blocks.append((ts_line, text_lines))
            continue

        current_start = start_sec
        for seg_idx, seg in enumerate(text_segments):
            # 맨 앞의 쉼표(,)나 공백(\s)이 하나 이상(+) 있으면 제거(^)
            seg = re.sub(r'^[, pediatrist、\s]+', '', seg).strip()
            if not seg: continue

            char_ratio = len(seg) / total_chars
            seg_duration = max(1.0, usable_duration * char_ratio)  # [V147.111] 최소 유지시간 1.0초 상향! 🕒✨
            seg_end = current_start + seg_duration

            if seg_idx == len(text_segments) - 1:
                seg_end = end_sec  # 마지막 조각은 원본 끝 시간에 맞춤

            new_ts = f"{format_srt_time(current_start)} --> {format_srt_time(min(seg_end, end_sec))}"
            result_blocks.append((new_ts, [seg]))

            current_start = seg_end + gap

    # 시퀀스 번호 재부여
    final_blocks = []
    for idx, (ts_line, text_lines) in enumerate(result_blocks, 1):
        block = f"{idx}\r\n{ts_line}\r\n" + "\r\n".join(text_lines)
        final_blocks.append(block)

    return "\r\n\r\n".join(final_blocks) + "\r\n\r\n"


# [TAG: #@_find_split_points]
def _find_split_points(text: str, num_splits: int) -> list:
    """텍스트에서 자연스러운 분할 지점을 찾습니다."""
    text_len = len(text)
    if text_len < 6:
        return []

    # 이상적인 분할 위치 (균등 분할)
    ideal_positions = [(text_len * (i + 1)) // (num_splits) for i in range(num_splits - 1)]

    split_points = []
    used_positions = set()

    for ideal_pos in ideal_positions:
        best_pos = None
        best_score = float('inf')

        # 검색 범위: 이상적 위치 ±33%
        search_range = max(10, text_len // 3)
        search_start = max(1, ideal_pos - search_range)
        search_end = min(text_len - 1, ideal_pos + search_range)

        for pos in range(search_start, search_end):
            if pos in used_positions:
                continue

            # 이전 분할점과 너무 가까우면 건너뜀
            if split_points and pos - split_points[-1] < 5:
                continue

            # 기본 점수: 이상적 위치와의 거리 (가중치 1.5)
            score = abs(pos - ideal_pos) * 1.5

            # [핵심] 단어 경계(공백) 여부 판단
            is_at_space = (pos < text_len and text[pos] == ' ')
            is_after_space = (pos > 0 and text[pos-1] == ' ')

            if not (is_at_space or is_after_space):
                score += 2000 # 단어 중간 분할에 대한 강력한 페널티 (가독성 최우선)
            else:
                score -= 100  # 단어 경계 보너

            # 한글 조사 및 어미 보너스 (단어 경계일 때만 적용)
            if is_at_space or is_after_space:
                # 3글자 이상 어미 패턴
                if pos >= 3:
                    p3 = text[pos-3:pos]
                    if p3 in ['하면서', '하니까', '정도는', '한테서', '있어서', '없어서', '보다는', '만이라', '있는데', '없는데']:
                        score -= 80
                # 2글자 어미/조사 패턴
                if pos >= 2:
                    p2 = text[pos-2:pos]
                    if p2 in ['해서', '하면', '하고', '인데', '지만', '니까', '어서', '아서', '에서', '부터', '까지', '라고', '으로', '에게', '보다', '처럼', '만큼', '하며', '기엔', '하여']:
                        score -= 60
                # 1글자 주요 조사 패턴
                if pos >= 1:
                    p1 = text[pos-1:pos]
                    if p1 in ['가', '이', '은', '는', '을', '를', '과', '와', '도', '만', '나', '고', '며', '의', '에', '로']:
                        score -= 40

                # [방어] '이/그/저/내/네/제' 등 관형사/대명사 뒤에서 바로 끊기는 것 방지
                if is_after_space:
                    # 앞에 공백이 있거나 문장 시작일 때 (예: " 그 ", "^그 ")
                    if pos == 2 or (pos > 2 and text[pos-2] == ' '):
                        if text[pos-1] in ['이', '그', '저', '내', '제', '네']:
                            score += 500 # 이 단어들은 다음 단어와 붙여서 다음 줄로 보냄

            # 문장 부호 및 쉼표 (최우선순위)
            if pos > 0 and text[pos - 1] in '.!?':
                score -= 300
            elif pos > 0 and text[pos - 1] == ',':
                score -= 200

            if score < best_score:
                best_score = score
                best_pos = pos

        if best_pos is not None:
            split_points.append(best_pos)
            used_positions.add(best_pos)

    split_points.sort()
    return split_points

