# [TAG: #@_show_toast]
def _show_toast(title: str, msg: str):
    """Windows 타스크바 토스트 알림을 띄웁니다. (PowerShell 경유)"""
    if os.name != 'nt': return
    try:
        # [V65.0] 한글 깨짐 방지를 위해 인코딩 명시 및 단순화
        title_esc = title.replace('"', '`"')
        msg_esc = msg.replace('"', '`"')
        ps_cmd = f"Add-Type -AssemblyName System.Windows.Forms; " \
                 f"$notify = New-Object System.Windows.Forms.NotifyIcon; " \
                 f"$notify.Icon = [System.Drawing.SystemIcons]::Information; " \
                 f"$notify.Visible = $true; " \
                 f"$notify.ShowBalloonTip(5000, '{title_esc}', '{msg_esc}', [System.Windows.Forms.ToolTipIcon]::Info); " \
                 f"Start-Sleep -Seconds 5; $notify.Dispose()"
        subprocess.Popen(['powershell', '-WindowStyle', 'Hidden', '-Command', ps_cmd],
                         stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception as e:
        try: _log_to_file(f"⚠️ [Silent Error Handled] {e}")
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

