# [TAG: #@check_gemini_api_type]
def check_gemini_api_type(settings):
    """Gemini API 요금제 정보를 확인하고, 없으면 사용자에게 물어봅니다."""
    if not settings: return "free"

    # [수정] 정보가 이미 있으면 즉시 반환 (문자열/인덱스 혼용 대응) 🚦✨
    val = settings.data.get("gemini_api_type")
    if val == "free" or val == 0: return "free"
    if val == "paid" or val == 1: return "paid"

    # 정보가 없으면 물어본다
    print("\r\n" + "─"*60)
    print(f" 💳 {ctext('Gemini API 요금제 정보가 없어서 확인이 필요해!', C.CYAN, C.BOLD)}")
    print("    (이 설정은 세마포어, 즉 '동시 처리수'를 결정하는 중요한 기준이 돼! 속도와 연관있어 😉)")
    print(f" {C.WHITE}[1] {C.YELLOW}무료 요금제 (Free Mode) {C.RESET}: 동시 처리 {C.BOLD}2개{C.RESET}로 제한 (오류 방지용)")
    print(f" {C.WHITE}[2] {C.GREEN}유료 요금제 (Paid Mode) {C.RESET}: 동시 처리 {C.BOLD}20개{C.RESET} 허용 (강력한 병렬 처리)")
    print("─"*60)

    api_opts = [" [1] 무료 요금제 (Free Mode)", " [2] 유료 요금제 (Paid Mode)"]
    api_sel, _, *_ = _interactive_menu("Gemini API 요금제 정보가 없어서 확인이 필요해!", api_opts, timeout=0)

    # [수정] ESC/취소 시 기본값 'free' 반환 (NoneType 에러 방지) 🛡️
    api_type = "paid" if api_sel == 1 else "free"

    limit_text = "20개 허용" if api_type == "paid" else "2개 제한"
    color = C.GREEN if api_type == "paid" else C.YELLOW
    print(f" ✔️  {color}{api_type.upper()} 요금제(병렬 {limit_text}){C.RESET}로 설정되었어.")

    settings.data["gemini_api_type"] = api_type
    settings.save()
    return api_type

# [TAG: #@restore_console_focus]
def restore_console_focus():
    """Forces the Windows terminal to the foreground (useful after tkinter closes)."""
    if os.name == 'nt':
        try:
            user32 = ctypes.windll.user32
            kernel32 = ctypes.windll.kernel32
            hwnd = kernel32.GetConsoleWindow()
            if hwnd:
                user32.SetForegroundWindow(hwnd)
                user32.ShowWindow(hwnd, 5) # SW_SHOW
            # [V22.35] ANSI 가상 터미널 모드(VT100) 유실 방지 재보장냥! 🛡️✨
            try:
                h_out = kernel32.GetStdHandle(-11)
                mode = ctypes.c_uint32()
                if kernel32.GetConsoleMode(h_out, ctypes.byref(mode)):
                    kernel32.SetConsoleMode(h_out, mode.value | 0x0004 | 0x0008) # ENABLE_VIRTUAL_TERMINAL_PROCESSING
            except: pass
        except Exception as e:
            try: _log_to_file(f"⚠️ [Silent Error Handled] {e}")
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

# [TAG: #@choose_video_files]
def choose_video_files(title: str = "자막을 만들 영상 파일을 선택해줘 (webm 포함)") -> list:
    """비디오 파일(.mp4, .mkv, .webm 등)만 허용하고 나머지는 재선택 유도"""
    print("\r\n" + "="*60)
    print(f" 🎬 {ctext('영상 파일 선택 대기 중...', C.CYAN, C.BOLD)} ")
    print("="*60)

    # 허용할 비디오 확장자 정의 (탐색기 지원 범위와 동기화) ✨
    VIDEO_EXTS = ('.mp4', '.mkv', '.avi', '.mov', '.wmv', '.flv', '.m4v', '.webm', '.ts', '.m2ts', '.m3u8', '.mp3', '.m4a', '.wav', '.flac')

    # 탐색기에서 애초에 비디오 파일만 보이도록 설정 (사용자 편의)
    file_paths = remote_explorer(
        mode='file',
        title=title,
        exts=VIDEO_EXTS,
        show_music_fav=False, # [V61.2] 영상 선택 시 음악 즐겨찾기 제외 🚫🎵
        disable_subtitle_shortcut=True  # [수정] 파일 선택 전용 모드: 's' 자막 단축키 비활성화 🛡️
    )

    restore_console_focus()

    if not file_paths:
        print(f"\r\n 🚫 {ctext('선택된 파일이 없어. 메뉴로 돌아갈게.', C.YELLOW)}")
        time.sleep(1.0)
        return []

    valid_paths = []
    invalid_found = False

    for path in file_paths:
        if path.lower().endswith(VIDEO_EXTS):
            valid_paths.append(path)
        else:
            print(f" ❌ {ctext('오류:', C.RED)} {os.path.basename(path)}는 비디오 파일이 아니야! ❗")
            invalid_found = True

    # 비디오가 아닌 파일이 섞여있거나 하나도 없다면 안내 후 빈 리스트 반환 (메뉴 재진입)
    if invalid_found or not valid_paths:
        print(f"\r\n 👉 {ctext('비디오 파일만 골라서 다시 선택해줄래?', C.CYAN, C.BOLD)}")
        time.sleep(1.5)
        return []

    return valid_paths

# [TAG: #@choose_subtitle_files]
def choose_subtitle_files() -> list:
    """자막 파일(.srt, .smi, .vtt 등)만 허용하고 나머지는 재선택 유도"""
    print("\r\n" + "="*60)
    print(f" 📝 {ctext('자막 파일 선택 대기 중...', C.CYAN, C.BOLD)} ")
    print("="*60)

    SUB_EXTS = ('.srt', '.smi', '.vtt', '.ass', '.ssa')

    file_paths = remote_explorer(
        mode='file',
        title="번역할 자막 파일을 선택해줘 (SRT, SMI 등)",
        exts=SUB_EXTS,
        show_music_fav=False,
        disable_subtitle_shortcut=True,
        view_mode='SUB_PICKER' # [V18.6] 자막 선택 전용 특수 모드 가동냥! 📄✨
    )

    restore_console_focus()

    if not file_paths:
        print(f"\r\n 🚫 {ctext('선택된 파일이 없어. 메뉴로 돌아갈게.', C.YELLOW)}")
        time.sleep(1.0)
        return []

    valid_paths = []
    for path in file_paths:
        if path.lower().endswith(SUB_EXTS):
            valid_paths.append(path)
        else:
            print(f" ❌ {ctext('오류:', C.RED)} {os.path.basename(path)}는 지원하는 자막 형식이 아니야! ❗")

    return valid_paths

# [TAG: #@_print_mode_dashboard]
def _print_mode_dashboard(title: str, info_pairs=None, tips=None, icon: str = "🚀", clear: bool = True, custom_lines=None):
    """
    [프리미엄 UI] 2줄 실선 테두리와 중앙 정렬 제목을 적용한 고품격 대시보드
    """
    if clear:
        clear_console()
    W, P, S, _G, Y, R, B = C.WHITE, C.PURPLE, C.SKY, C.GREEN, C.YELLOW, C.RESET, C.BOLD
    width = 75
    line_outer = 헤더선(width=width + 4)
    line_inner = 헤더선(width=width + 4) # 대시보드 내부 구분용

    print(line_outer)
    title_line = f"{icon} {title}"
    print(f" {_center_ansi(B + P + title_line + R, width + 4)}")

    if info_pairs:
        print(line_inner)
        for label, value in info_pairs:
            label_text = f"{S}📍 {label}{R}"
            val_text = f"{B}{value}{R}"
            content = f"{label_text:<23} : {val_text}"
            print(f"    {content}")

    if custom_lines:
        print(line_inner)
        for line in custom_lines:
            print(f"    {line}")

    if tips:
        print(line_inner)
        print(f"    {Y}⌨️  기억해두면 좋은 꿀팁 & 단축키{R}")
        for tip in tips:
            tip_text = f"ㄴ {tip}"
            print(f"    {C.DIM}{tip_text}{R}")

    print(line_outer + "\r\n")

# [TAG: #@_get_standard_menu_header_str]
def _get_standard_menu_header_str(menu_key: str, settings, **kwargs):
    """[V14.1] 대시보드 헤더 텍스트를 더블 버퍼링 지원용 문자열로 반환냥! 🛡️✨"""
    import io, contextlib
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        _print_standard_menu_header(menu_key, settings, **kwargs)
    return buf.getvalue().rstrip('\n')


