# [TAG: #@_print_youtube_status_banner]
def _print_youtube_status_banner(settings, mode="general", clear: bool = True):
    """[V14.1] 유튜브 다운로드 모드 전용 대시보드 - 일관된 디자인 적용 ✨"""
    title_map = {
        "general": "유튜브 영상/자막 다운로드 모드",
        "fast": "유튜브 초고속 원스톱 모드 (스킵)",
        "onestop": "유튜브 해외소스 자막 자동화 모드"
    }
    title = title_map.get(mode, "유튜브 작업 모드")

    save_path = settings.data.get('saved_video_path', os.getcwd())
    if not os.path.isabs(save_path):
        save_path = os.path.abspath(save_path)

    yt_fmt_map = {
        0: "최고 화질 (No AV1)", 1: "1440p QHD (No AV1)", 2: "1080p FHD (No AV1)", 3: "720p HD (No AV1)",
        4: "오디오 (MP3)", 5: "오디오 (M4A)", 6: "⚡ 원본 복사 (OPUS)", 7: "무손실 (WAV)"
    }
    yt_fmt_str = yt_fmt_map.get(settings.data.get('yt_format_idx', 0), "설정 안 됨")

    info = [
        ("다운로드 화질", f"{C.GREEN}{yt_fmt_str}{C.RESET}"),
        ("저장 위치", f"{C.DIM}{save_path}{C.RESET}")
    ]

    R = C.RESET
    tips = [
        f"{C.GOLD}💡 [꿀팁]{R} 냄비에 물 올리고 불을 올린후, 라면을 털어넣고, 005 엔터 !!",
        f"   {C.DIM}ㄴ 그러면 5분뒤에 잘 익은 라면을 먹을 수 있어!{R}",
        f"{C.GOLD}⏰ [상식]{R} 알람은 매일 그 시간에 울리지만, py가 가동 중이어야 한다는 점 잊지마!",
        f"{C.GOLD}🚀{R} 다수개 작업 시 주소를 계속 입력하고 '일괄 다운로드'를 눌러줘!"
    ]

    _print_mode_dashboard(title, info, tips, icon="🌐⚡", clear=clear)

def _auto_blacklist_unsupported_yt_video(msg):
    """[V176.0] 회원 전용/비공개 등으로 403 에러 발생 시 해당 ID를 히스토리에 기록하여 큐 무한 정체 방지냥! 🛡️✨"""
    try:
        if any(k in msg.lower() for k in ["members", "cfo", "subscriber", "private", "unavailable", "403: forbidden", "403 forbidden", "유료 회원"]):
            import re
            m = re.search(r"\[(?:youtube|generic)\]\s*([a-zA-Z0-9_-]{11})", msg)
            if not m:
                m = re.search(r"(?:v=|\/)([a-zA-Z0-9_-]{11})(?:[\&\?\s]|$)", msg)
            if m:
                blocked_id = m.group(1)
                save_video_history(blocked_id)
                _log_to_file(f" 🔒 [히스토리 차단 등록] {blocked_id} 영상이 회원전용/접근불가로 히스토리에 저장되어 다음 스캔에서 제외됩니다냥! 🚫")
    except Exception:
        pass


# [TAG: #@_inject_youtube_chapters_if_needed]
def _inject_youtube_chapters_if_needed(video_path, info_dict=None, description="", video_url=None):
    """
    [V176.8] 다운로드 완료된 미디어 파일(MP4/MKV/M4A)에 챕터가 누락되었거나 설명란에 타임스탬프가 있는 경우
    FFmpeg 메타데이터(FFMETADATA1)를 생성하여 챕터를 확실하게 주입합니다냥! (자가 조회 및 파일 잠금 안전 재시도 포함) 📖✨
    """
    if not video_path or not os.path.isfile(video_path):
        return False

    ext = os.path.splitext(video_path)[1].lower()
    if ext not in ('.mp4', '.mkv', '.m4a', '.webm', '.mov', '.ts'):
        return False

    # [V178.1 BUG-1 FIX] _t2s 헬퍼를 함수 최상단에 한 번만 정의 (중복 정의 제거)
    def _t2s(ts):
        parts = [int(p) for p in ts.strip().split(':')]
        if len(parts) == 2: return parts[0] * 60 + parts[1]
        elif len(parts) == 3: return parts[0] * 3600 + parts[1] * 60 + parts[2]
        return 0

    try:
        # 1. 챕터 목록 추출 (info_dict의 chapters 또는 description 파싱)
        chapters = []
        if info_dict and isinstance(info_dict.get('chapters'), list) and len(info_dict['chapters']) > 0:
            for c in info_dict['chapters']:
                st = c.get('start_time', 0)
                et = c.get('end_time', 0)
                t = c.get('title', '').strip()
                if et > st and t:
                    chapters.append({'title': t, 'start_time': st, 'end_time': et})

        # 만약 info_dict의 chapters가 비어 있으면 description에서 타임스탬프 파싱
        if not chapters:
            desc = description or (info_dict.get('description', '') if info_dict else '')
            total_dur = (info_dict.get('duration') or 0) if info_dict else 0
            if desc:
                pattern = re.compile(r'(?:^|\n)\s*(?:\[|\()?((?:\d{1,2}:)?\d{1,2}:\d{2})(?:\]|\))?\s*[-–—:]?\s*(.+?)(?=\n|$)', re.MULTILINE)
                matches = pattern.findall(desc)
                if matches and len(matches) >= 2:
                    raw_c = []
                    for t_str, title in matches:
                        sec = _t2s(t_str)
                        clean_t = title.strip().strip('-–—:[]()').strip()
                        if clean_t: raw_c.append((sec, clean_t))
                    raw_c.sort(key=lambda x: x[0])
                    for i, (sec, title) in enumerate(raw_c):
                        start = sec
                        if i + 1 < len(raw_c):
                            end = raw_c[i+1][0]
                        else:
                            end = max(start + 60, total_dur) if total_dur > start else start + 300
                        if end > start:
                            chapters.append({'title': title, 'start_time': start, 'end_time': end})

        # 정보가 없을 때: YouTube ID나 URL, 파일명으로 가볍게 메타데이터 자동 자가 조회 (Self-Lookup) 🔍✨
        if not chapters:
            try:
                bn = os.path.basename(video_path)
                m_vid = re.search(r'([0-9A-Za-z_-]{11})', bn)
                q_target = None
                is_title_search = False  # [V178.1 BUG-4] 제목 검색 여부 플래그
                if video_url:
                    q_target = video_url
                elif m_vid and len(m_vid.group(1)) == 11:
                    q_target = f"https://www.youtube.com/watch?v={m_vid.group(1)}"
                else:
                    clean_bn = re.sub(r'\[.*?\]', '', bn).replace(ext, '').replace('_', ' ').strip()
                    if not clean_bn or len(clean_bn) < 3:
                        clean_bn = bn.replace(ext, '').replace('_', ' ').strip()
                    if len(clean_bn) >= 3:
                        q_target = f"ytsearch1:{clean_bn[:60]}"
                        is_title_search = True  # 제목 검색이므로 duration 안전장치 필요
                
                if q_target:
                    import yt_dlp
                    _s_opts = {
                        'quiet': True,
                        'skip_download': True,
                        'no_warnings': True,
                        'logger': SilentLogger() if 'SilentLogger' in globals() else None
                    }
                    if '_apply_ytdl_stealth_opts' in globals():
                        _s_opts = _apply_ytdl_stealth_opts(_s_opts)
                    if '_get_ytdl_js_runtimes' in globals():
                        _s_opts['js_runtimes'] = _get_ytdl_js_runtimes()
                    with yt_dlp.YoutubeDL(_s_opts) as ydl:
                        auto_info = ydl.extract_info(q_target, download=False)
                        if auto_info:
                            if 'entries' in auto_info and auto_info['entries']:
                                auto_info = auto_info['entries'][0]
                            # [V178.1 BUG-4 FIX] 제목 검색 시 duration 안전장치: 20% 이상 차이나면 다른 영상으로 판단 🛡️
                            if is_title_search and auto_info:
                                local_dur = (info_dict.get('duration') or 0) if info_dict else 0
                                if not local_dur:
                                    try:
                                        import subprocess as _sp
                                        _ffp = _get_ffprobe_bin()
                                        if _ffp:
                                            _r = _sp.run([_ffp, '-v', 'error', '-show_entries', 'format=duration',
                                                          '-of', 'default=noprint_wrappers=1:nokey=1', video_path],
                                                         capture_output=True, text=True, timeout=5)
                                            local_dur = float(_r.stdout.strip()) if _r.stdout.strip() else 0
                                    except Exception:
                                        pass
                                remote_dur = auto_info.get('duration', 0) or 0
                                if local_dur > 0 and remote_dur > 0:
                                    ratio = abs(local_dur - remote_dur) / max(local_dur, remote_dur)
                                    if ratio > 0.20:  # 20% 초과 차이 → 다른 영상, 스킵
                                        _log_to_file(f" ⚠️ [BUG-4 Guard] 제목검색 결과 duration 불일치 (로컬:{local_dur:.0f}s vs 검색:{remote_dur:.0f}s, diff:{ratio:.1%}), 챕터 주입 건너뜀")
                                        auto_info = None  # 무효화
                            if auto_info and auto_info.get('chapters'):
                                for c in auto_info['chapters']:
                                    st = c.get('start_time', 0)
                                    et = c.get('end_time', 0)
                                    t = c.get('title', '').strip()
                                    if et > st and t:
                                        chapters.append({'title': t, 'start_time': st, 'end_time': et})
                            elif auto_info and auto_info.get('description'):
                                a_desc = auto_info['description']
                                a_dur = auto_info.get('duration', 0) or 0
                                pattern = re.compile(r'(?:^|\n)\s*(?:\[|\()?((?:\d{1,2}:)?\d{1,2}:\d{2})(?:\]|\))?\s*[-–—:]?\s*(.+?)(?=\n|$)', re.MULTILINE)
                                matches = pattern.findall(a_desc)
                                if matches and len(matches) >= 2:
                                    raw_c = []
                                    for t_str, title in matches:
                                        sec = _t2s(t_str)
                                        clean_t = title.strip().strip('-–—:[]()').strip()
                                        if clean_t: raw_c.append((sec, clean_t))
                                    raw_c.sort(key=lambda x: x[0])
                                    for i, (sec, title) in enumerate(raw_c):
                                        start = sec
                                        end = raw_c[i+1][0] if i + 1 < len(raw_c) else (max(start + 60, a_dur) if a_dur > start else start + 300)
                                        if end > start:
                                            chapters.append({'title': title, 'start_time': start, 'end_time': end})
            except Exception:
                pass

        if not chapters:
            return False

        # 2. 이미 파일에 챕터가 들어있는지 FFprobe로 확인 (중복 주입 방지)
        ffprobe = _get_ffprobe_bin()
        ffmpeg = _get_ffmpeg_bin()
        flags = 0x08000000 if os.name == 'nt' else 0
        if ffprobe and os.path.exists(ffprobe):
            try:
                chk = subprocess.run([ffprobe, "-v", "error", "-show_chapters", "-of", "json", video_path],
                                     capture_output=True, text=True, encoding="utf-8", errors="replace",
                                     creationflags=flags, timeout=10)
                if chk.returncode == 0 and chk.stdout:
                    probe_data = json.loads(chk.stdout)
                    # [V178.1 IMP-2 FIX] >= 에서 > 로 변경: 기존 챕터 수가 더 많을 때만 스킵 (동수면 재주입)
                    if probe_data.get('chapters') and len(probe_data['chapters']) > len(chapters):
                        _log_to_file(f" ℹ️ [Chapter Guard] '{os.path.basename(video_path)}' already has {len(probe_data['chapters'])} chapters.")
                        return True
            except Exception:
                pass

        # 3. FFMETADATA1 파일 생성
        lines_m = [";FFMETADATA1"]
        for c in chapters:
            start_ms = int(round(c['start_time'] * 1000))
            end_ms = int(round(c['end_time'] * 1000))
            lines_m.append("[CHAPTER]")
            lines_m.append("TIMEBASE=1/1000")
            lines_m.append(f"START={start_ms}")
            lines_m.append(f"END={end_ms}")
            lines_m.append(f"title={c['title']}")
        meta_content = "\n".join(lines_m) + "\n"

        temp_meta_path = video_path + ".ffmeta"
        temp_out_path = video_path + ".ch_tmp" + ext
        with open(temp_meta_path, "w", encoding="utf-8") as f:
            f.write(meta_content)

        # 4. FFmpeg로 무손실 copy 먹싱 (모든 스트림/자막/메타데이터 100% 보존 + 챕터 주입)
        cmd = [
            ffmpeg, "-y", "-loglevel", "error",
            "-i", video_path,
            "-i", temp_meta_path,
            "-map", "0",
            "-map_metadata", "0",
            "-map_chapters", "1",
            "-codec", "copy",
            temp_out_path
        ]
        res = subprocess.run(cmd, capture_output=True, text=True, encoding="utf-8", errors="replace",
                             creationflags=flags, timeout=180)

        # 임시 메타파일 삭제
        try: os.remove(temp_meta_path)
        except: pass

        if res.returncode == 0 and os.path.exists(temp_out_path) and os.path.getsize(temp_out_path) > 1024:
            # 원본 교체 (팟플레이어 재생 중 등 잠금 대비 10회 안전 재시도 & Fallback 복사) 🛡️
            replaced = False
            for attempt in range(10):
                try:
                    os.replace(temp_out_path, video_path)
                    replaced = True
                    break
                except PermissionError:
                    time.sleep(0.5)
            if not replaced:
                try:
                    import shutil
                    shutil.copy2(temp_out_path, video_path)
                    os.remove(temp_out_path)
                    replaced = True
                except Exception as _fe:
                    _log_to_file(f"⚠️ [Chapter Fallback Copy Error] {_fe}")

            if replaced:
                _log_to_file(f" 📖 [Chapter Injected] Successfully embedded {len(chapters)} chapters into '{os.path.basename(video_path)}'!")
                return True
            else:
                return False
        else:
            if os.path.exists(temp_out_path):
                try: os.remove(temp_out_path)
                except: pass
            _log_to_file(f" ⚠️ [Chapter Injection Failed] FFmpeg returned {res.returncode}: {res.stderr}")
            return False
    except Exception as e:
        # [V178.1 BUG-5 FIX] 예외 발생 시에도 임시파일 잔재 제거
        for _tmp in [locals().get('temp_meta_path'), locals().get('temp_out_path')]:
            if _tmp:
                try: os.remove(_tmp)
                except: pass
        _log_to_file(f" ⚠️ [_inject_youtube_chapters_if_needed Error] {e}")
        return False

# [TAG: #@_download_v_internal]
def _download_v_internal(urls, saved_path, format_idx, quiet=False, extra_hooks=None, work_path=None):
    """
    [V8.3] 실제 유튜브 다운로드 핵심 함수 (yt_dlp 사용) ✨🛰️
    - 100MB 기준 자동 4분할 병렬 다운로드 (가속)
    - Golden Camouflage (Chrome-110 impersonation)
    - 공백 제거 및 네이밍 정규화 자동 포함
    """
    import yt_dlp

    # 1. 📂 전용 작업 디렉토리 설정 (기본값 설정)
    if not work_path:
        # [V16.2] PID 대신 URL 해시를 사용하여 중복 방지 및 이어받기 지원 ✨🛰️
        # [V16.3.3] 인스턴스 격리를 위해 PID를 다시 조합하여 독립성 사수! 🛡️🛰️✨
        work_id = hashlib.md5(urls[0].encode()).hexdigest()[:10]
        work_path = os.path.join(saved_path, f"_work_{work_id}_p{os.getpid()}")
        os.makedirs(work_path, exist_ok=True)

    # [V16.2] 🔒 중복 실행 방지 락(Lock) 체크
    lock_file = os.path.join(work_path, ".process.lock")
    if os.path.exists(lock_file):
        try:
            with open(lock_file, "r") as f:
                existing_pid = safe_int(f.read().strip())
            if PendingQueue._is_pid_alive(existing_pid):
                if not quiet:
                    print(f"\r\n ⚠️  {ctext(f'이미 다른 창(PID: {existing_pid})에서 이 영상을 다운로드 중이야냥! 🐾', C.YELLOW)}")
                    print(f" ✨ {ctext('중복 다운로드를 방지하기 위해 이 작업을 건너뛸게냥! 👍', C.SKY)}")
                return []
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

    # 현재 PID 기록
    try:
        with open(lock_file, "w") as f:
            f.write(str(os.getpid()))
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")

    # 2. 🛰️ [Golden Camouflage] 유튜브 탐지 우회 헤더 설정
    agent_header = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0.0.0 Safari/537.36"

    # [V154.93] AI냥 요청: 분할 다운로드 정책 최적화! (전역 8개 분할) 🚀⚡
    concurrent_parts = 8

    # [V21.4] AV1 금지령 해제 및 고화질 사수 작전! 🔓✨ (사용자 요청 반영)
    # 이제 vp9 1080p가 없을 때 av1 1080p를 폴백으로 사용할 수 있도록 허용합니다냥!
    no_av1 = "" 

    def get_fmt(res=None):
        res_limit = f"[height<={res}]" if res else ""
        # [V178.7 FIX] AV1(av01) 원천 차단 + 해상도 최우선 사수 (VP9 없어도 H.264 선택하여 360p 추락 방지!) 🛡️🎬
        f_primary = f"bestvideo{res_limit}[vcodec!^=av01]+bestaudio/best{res_limit}[vcodec!^=av01]"
        f_fallback = f"bestvideo{res_limit}+bestaudio/best{res_limit}"
        return f"{f_primary}/{f_fallback}"

    # [V178.7 FIX] AV1 제외 및 해상도 최우선, 동일 해상도 내 VP9 > H.264 순 정렬 🎯
    if format_idx == 0:
        v_fmt = get_fmt()
        f_sort = ['res', 'codec:vp9:h264', 'br', 'fps']
    elif format_idx == 1:
        v_fmt = get_fmt(1440)
        f_sort = ['res:1440', 'codec:vp9:h264', 'br', 'fps']
    elif format_idx == 2:
        v_fmt = get_fmt(1080)
        f_sort = ['res:1080', 'codec:vp9:h264', 'br', 'fps']
    elif format_idx == 3:
        v_fmt = get_fmt(720)
        f_sort = ['res:720', 'codec:vp9:h264', 'br', 'fps']
    elif format_idx in [4, 5, 6]:
        v_fmt = 'bestaudio/best'
        f_sort = ['br', 'fps']
    else: # 커스텀 또는 목록 보기
        custom = globals().get('_TEMP_CUSTOM_FORMAT', 'best')
        f_sort = ['res', 'codec:vp9:h264', 'br', 'fps']
        if '+' in str(custom):
            v_fmt = custom
        elif str(custom).isdigit():
            v_fmt = f"{custom}+bestaudio"
        else:
            v_fmt = custom if custom != 'best' else f'best{no_av1}'

    ff_path = _get_ffmpeg_bin()
    # [V154.98] 요리사(FFmpeg) 상태 정밀 체크: 엔진이 없으면 화질 합체가 안 되어 파일이 쪼개질 수 있어냥! 🍳🛡️
    ff_ok = False
    try:
        res = subprocess.run([ff_path, "-version"], capture_output=True, text=True, creationflags=0x08000000 if os.name == 'nt' else 0, timeout=5)
        if res.returncode == 0: ff_ok = True
    except: pass

    if not ff_ok and not quiet:
        print(f" ⚠️  {C.RED}[엔진 경고]{C.RESET} FFmpeg 요리사를 찾을 수 없어냥! 영상과 소리가 따로 저장될 수 있어냥! 🙀")
        print(f"    👉 {C.DIM}해결: 'temp' 폴더에 ffmpeg.exe를 넣어주면 합체가 잘 돼냥! 🐾{C.RESET}")

    if not quiet: print(f" 👨‍🍳 {C.SKY}[Subtitle-Check]{C.RESET} 요리사 위치: {C.YELLOW}{ff_path}{R}")

    ydl_opts = {
        'ffmpeg_location': ff_path, 
        'js_runtimes': _get_ytdl_js_runtimes(), # [V175.0] 고화질 n-challenge 해결 🚀⚡
        'remote_components': ['ejs:github'],    # [V175.0] 최신 EJS 챌린지 솔버 활성화 🛡️
        'format': v_fmt,
        'paths': {
            'home': work_path,
            'temp': work_path
        },
        'outtmpl': '[%(uploader).30s] %(title).100s.%(ext)s',
        'trim_file_name': 120, # [V178.8] 윈도우 MAX_PATH(260자) 초과 [Errno 2] 원천 차단! 🛡️📏
        'windowsfilenames': True,
        'file_access_retries': 20, # [V178.8] 파일 락 충돌(WinError 32) 완벽 방어 🛡️
        'user_agent': agent_header,
        'referer': 'https://www.google.com/',
        'language': 'ko', 
        'headers': {
            'Accept-Language': 'ko-KR,ko;q=0.9,en-US;q=0.8,en;q=0.7',
            'Sec-Ch-Ua': '"Chromium";v="128", "Not;A=Brand";v="24", "Google Chrome";v="128"',
            'Sec-Ch-Ua-Platform': '"Windows"',
        },
        'http_chunk_size': 10485760, # [V176.1] 403 Forbidden 방지 10MB 안정 청크 🛡️⚡
        'merge_output_format': 'mp4', # [V143.40] 최종 그릇은 MP4! 📦✨
        'keepsubtitles': False,       # [V148.11] AI냥 요청: 자막 심었으면 원본은 유기적으로 삭제해냥! 🗑️✨
        'postprocessor_args': ['-y', '-loglevel', 'error'], # [V148.11] -y 추가: 묻지 말고 합체하라냥! 🥊📢
        'format_sort': f_sort, 
        'concurrent_fragments': concurrent_parts, 
        'concurrent_fragment_downloads': concurrent_parts, # [V21.3] 레거시 키 호환 ✨
        'retries': 5,
        'fragment_retries': 10,
        'ignoreerrors': True,  # [V21.5] 하나가 실패해도 끝까지 간다냥! 🚀🛡️
        'no_warnings': False, 
        'quiet': quiet,
        # [V148.11] 순차 엔진용 자막 알리미 비서 📡✨
        'logger': type('SeqSubLogger', (SilentLogger,), {
            'debug': lambda self, msg: (
                any(k in msg.lower() for k in ['subtitle', 'cc', 'embed', 'extract', 'convert']) and 
                not quiet and print(f" 🎯 {C.SKY}[Subtitle]{C.RESET} {re.sub(r'\[.*?\]', '', msg).strip()}")
            ),
            'warning': lambda self, msg: SilentLogger().warning(msg),
            'error': lambda self, msg: (
                _log_to_file(f"❌ [yt-dlp Seq Engine Error] {msg}"), # [V21.5] 상세 기록 추가! 🕵️‍♂️
                SilentLogger().error(msg),
                _auto_blacklist_unsupported_yt_video(msg)
            )
        })(),
        'extractor_args': {
            'youtube': {
                'lang': ['ko'],
                'country': ['KR']
            }
        },
        'user_agent': agent_header,
        'listformats': True if format_idx == 8 else False, # [V143.60] 인덱스 조정: 8번이 목록 보기 🔍

        # [V148.7] 자막 심기(Embedding) 성공률 극대화 로직! 🛠️📦
        'writesubtitles': True,             # 업로더 자막(Manual) 다운로드! 📄💎
        'allsubtitles': False,               # [V148.5] 무분별한 전체 다운로드 중단 🛑
        'subtitleslangs': ['ko.*', 'en.*', 'ja.*', 'jp.*'], # 한/영/일 정예 멤버 선발 🇰🇷🇺🇸🇯🇵✨
        'writeautomaticsub': False,          # [V148.10] AI냥 요청: 쓰레기 같은 오토 자막은 이제 안 가져올게냥! 🧼✨
        'embedsubtitles': True,              # 팟플레이어 호환을 위해 영상 안에 쏙! 📦
        'addmetadata': True,                 # [V17.5.5] 영상 메타데이터(업로더, 날짜 등) 주입! 🏷️✨
        'embedchapters': True,               # [V17.5.5] 영상 챕터 정보 주입 (팟플에서 확인 가능) 📖✨
        'postprocessors': [
            # 1. 먼저 가장 호환성 좋은 srt로 변환 (MP4 mov_text 변환의 기반이 됨)
            {'key': 'FFmpegSubtitlesConvertor', 'format': 'srt'},
            # 2. 영상에 자막 심기 (ffmpeg가 알아서 mov_text로 변환해서 MP4에 넣어줌)
            {'key': 'FFmpegEmbedSubtitle', 'already_have_subtitle': False},
            # 3. [V17.5.5] 메타데이터 및 챕터 주입 (FFmpegMetadata - 최종 단계에서 주입하여 챕터 유실 방지!) 🏷️📖
            {'key': 'FFmpegMetadata', 'add_chapters': True, 'add_metadata': True}
        ]
    }
    ydl_opts = _apply_ytdl_stealth_opts(ydl_opts)

    # [V21.5] 형식별 전용 가공 로직 (오디오 모드 격리 및 최적화) 🎧✨
    if format_idx in [4, 5, 6]:
        ydl_opts['merge_output_format'] = None
        ydl_opts['writesubtitles'] = False
        ydl_opts['embedsubtitles'] = False
        
        if format_idx == 4: # MP3 🎵
            ydl_opts['writethumbnail'] = True
            ydl_opts['postprocessors'] = [
                {'key': 'FFmpegExtractAudio', 'preferredcodec': 'mp3', 'preferredquality': '192'},
                {'key': 'FFmpegThumbnailsConvertor', 'format': 'jpg'},
                {'key': 'EmbedThumbnail', 'already_have_thumbnail': False},
                {'key': 'FFmpegMetadata', 'add_chapters': True, 'add_metadata': True}
            ]
        elif format_idx == 5: # M4A 🎧
            ydl_opts['writethumbnail'] = True
            ydl_opts['postprocessors'] = [
                {'key': 'FFmpegExtractAudio', 'preferredcodec': 'm4a', 'preferredquality': '192'},
                {'key': 'FFmpegThumbnailsConvertor', 'format': 'jpg'},
                {'key': 'EmbedThumbnail', 'already_have_thumbnail': False},
                {'key': 'FFmpegMetadata', 'add_chapters': True, 'add_metadata': True}
            ]
        elif format_idx == 6: # Lossless 🛡️
            ydl_opts['postprocessors'] = [
                {'key': 'FFmpegExtractAudio', 'preferredcodec': 'opus', 'preferredquality': '0'}
            ]
            ydl_opts['postprocessor_args'] = ['-c:a', 'copy']

    # 훅 연결
    downloaded_files = []
    downloaded_infos = {}
    success_ids = []  # [V142.40] 진짜 성공한 ID만 추적! 🎯
    # [TAG: #@monitor_hook]
    def monitor_hook(d):
        # [V178.1 BUG-3 FIX] d['status'] → d.get('status') : 키 누락 시 KeyError 방지
        if d.get('status') == 'finished':
            if not quiet: print(f" ✅ {C.GREEN}다운로드 완료! 파일 정리 중이다냥... 🚀{R}")
            info = d.get('info_dict', {})
            final_f = info.get('_filename', d.get('filename'))
            v_id = info.get('id')
            if final_f:
                downloaded_infos[final_f] = info
                if final_f not in downloaded_files:
                    downloaded_files.append(final_f)
            if v_id:
                downloaded_infos[v_id] = info
                if v_id not in success_ids:
                    success_ids.append(v_id)
        elif d.get('status') == 'error':
            if not quiet: print(f" ❌ {C.RED}다운로드 중 엔진 오류가 발생했어냥! 😿{R}")
        
        # [V176.6] 후처리 완료 후 챕터 주입 보강 및 추적
        if d.get('postprocessor') and d.get('status') == 'finished':
            info = d.get('info_dict', {})
            temp_f = d.get('filename') or info.get('_filename')
            if temp_f and os.path.exists(temp_f):
                try:
                    v_target_url = info.get('webpage_url') or info.get('original_url')
                    _inject_youtube_chapters_if_needed(temp_f, info_dict=info, video_url=v_target_url)
                except Exception as _che:
                    _log_to_file(f"⚠️ [Chapter Hook Error] {_che}")

    ydl_opts['progress_hooks'] = [monitor_hook]
    ydl_opts['postprocessor_hooks'] = [monitor_hook] # [V21.5] 변환(MP3 등) 후 최종 경로 추적용! 🕵️‍♂️✨
    if extra_hooks:
        ydl_opts['progress_hooks'].extend(extra_hooks)

    # 5. 🏗️ 실행 및 후처리
    try:
        with yt_dlp.YoutubeDL(ydl_opts) as ydl:
            ydl.download(urls)
    except Exception as e:
        if not quiet: print(f" ❌ {ctext(f'엔진 오류: {e}', C.RED)}")

    # 6. 🧹 챕터 주입 검증 및 파일 이동 ("공백은 밑줄로!") ✨🚀
    final_output_list = []
    # 🍳 [V177.4] .f248.webm 등 미결합 스트림 파일 사전 자동 결합 🎬🔊
    try:
        merged_seq = _repair_and_merge_unmerged_streams(work_path, saved_path)
        final_output_list.extend(merged_seq)
    except Exception as _seq_m_err:
        _log_to_file(f"⚠️ [Sequential Stream Repair Error] {_seq_m_err}")

    if os.path.exists(work_path):
        import re
        # [V178.11] '-N' 접미사(.f234-1.mp4)와 .temp.mp4 결손 잔재까지 라이브러리 이동 차단! 🛡️
        fmt_pat_seq = re.compile(r'(\.f\d+(-\d+)?\.(webm|mp4|mkv|m4a)|\.temp(-\d+)?\.(webm|mp4|mkv|m4a))$', re.IGNORECASE)
        for f in os.listdir(work_path):
            old_p = os.path.join(work_path, f)
            if os.path.isfile(old_p) and not old_p.endswith(('.part', '.ytdl', '.temp', '.tmp', '.lock')):
                # 🚫 미결합 분할 스트림(.f248.webm 등) 단독 이동 차단
                if fmt_pat_seq.search(f):
                    continue
                try:
                    cand_info = downloaded_infos.get(old_p)
                    if not cand_info:
                        for _k, _v in downloaded_infos.items():
                            if isinstance(_k, str) and (_k in old_p or (len(_k) == 11 and _k in f)):
                                cand_info = _v; break
                    cand_url = (cand_info.get('webpage_url') or cand_info.get('original_url')) if cand_info else (urls[0] if (urls and len(urls) == 1) else None)
                    _inject_youtube_chapters_if_needed(old_p, info_dict=cand_info, video_url=cand_url)
                except Exception as _fche:
                    _log_to_file(f"⚠️ [Final Chapter Check Error] {_fche}")
                new_name = f.replace(' ', '_')
                new_p = os.path.join(saved_path, new_name)
                if os.path.exists(new_p):
                    base, ext = os.path.splitext(new_name)
                    new_p = os.path.join(saved_path, f"{base}_{int(time.time())}{ext}")
                try:
                    shutil.move(old_p, new_p)
                    final_output_list.append(new_p)
                except Exception as e:
                    if "6" not in str(e): _log_to_file(f"⚠️ [Final Move Error] {e}")

        # [V21.7] 작업 폴더 삭제는 이제 '안전하게' 휴지통으로! 🗑️✨
        safe_remove_file(work_path, use_trash=True)

    return final_output_list, success_ids

# [TAG: #@_handle_youtube_playlist_search_interactive]

def _handle_youtube_playlist_search_interactive(query: str, settings) -> dict:
    """[V1.0] 유튜브 재생목록 검색 결과를 보여주고 선택한 재생목록을 반환합니다. 🔍📁✨"""
    all_results = []
    current_offset = 0
    current_focus = 0

    def browse_cb(url):
        open_browser(url, message="유튜브 재생목록을 확인하러 간다냥! 📁")

    while True:
        limit_per_page = 50
        if len(all_results) <= current_offset:
            desc = f"🔍 {C.SKY}'{query}'{C.RESET} 유튜브 재생목록 검색 중 (현재 {len(all_results)}개)..."
            with LoadingSpinner(desc):
                new_results = _search_youtube_playlists(query, limit=limit_per_page, offset=current_offset)
            if new_results:
                all_results.extend(new_results)
            elif not all_results:
                print(f"  ❌ {C.RED}검색 결과 재생목록이 없습니다냥...{C.RESET}")
                time.sleep(1.5)
                break
            else:
                print(f"  ✨ {C.GOLD}마지막 페이지입니다냥! 👍{C.RESET}")
                current_offset -= limit_per_page
                time.sleep(1)

        view_items = all_results[current_offset : current_offset + limit_per_page]

        display_options = []
        display_options.append(f"🔍 {C.SKY}다른 키워드로 재생목록 재검색{C.RESET}")

        for r in view_items:
            _title = r.get('title') or '제목 없음'
            _uploader = r.get('uploader') or '알 수 없음'
            _count = r.get('video_count')
            count_label = f"[{C.GOLD}{_count}개{C.RESET}]" if _count is not None else f"[{C.GOLD}??개{C.RESET}]"
            up_label = f"[{C.SKY}{_uploader:<10}{C.RESET}]"
            h_marker = f"{C.LIME}📁{C.RESET}"
            pretty_label = f"{h_marker} {count_label}{up_label} {_title}"
            display_options.append(pretty_label)
            r['display_label'] = pretty_label

        idx_prev, idx_next = -1, -1
        paginations = _get_pagination_opts(curr_page=current_offset // limit_per_page + 1)
        for p in paginations:
            if p.get('key') == 'action_PREV_PAGE':
                idx_prev = len(display_options)
            elif p.get('key') == 'action_NEXT_PAGE':
                idx_next = len(display_options)
            display_options.append(p)

        idx_cancel = len(display_options)
        display_options.append("↩️ 취소")

        title = f"📁 '{query}' 재생목록 검색 결과 ({len(view_items)}개) [{(current_offset//limit_per_page)+1}페이지]"
        
        sel_idx, action, *_ = _interactive_menu(
            title, display_options, timeout=0, prefix="[Playlist Search] ",
            browse_callback=browse_cb, allow_paging=True, allow_further=True,
            default_idx=current_focus
        )

        if sel_idx == -1 or action == "CANCEL": break

        _sel_int = sel_idx[0] if isinstance(sel_idx, list) and len(sel_idx) > 0 else (sel_idx if isinstance(sel_idx, int) else -1)

        if isinstance(sel_idx, list) and sel_idx: current_focus = sel_idx[0]
        elif isinstance(sel_idx, int) and sel_idx >= 0: current_focus = sel_idx

        if _sel_int == idx_cancel: break

        if action in ["BROWSE", "HISTORY"]:
            target_idx = _sel_int
            res_idx = target_idx - 1
            if 0 <= res_idx < len(view_items):
                if action == "BROWSE": browse_cb(view_items[res_idx]['url'])
                else: handle_playlist_history_sync(view_items[res_idx]['url'], settings)
            continue

        if action in ("NEXT_PAGE", "FURTHER") or (idx_next != -1 and _sel_int == idx_next):
            current_offset += limit_per_page
            continue
        if action == "PREV_PAGE" or (idx_prev != -1 and _sel_int == idx_prev):
            current_offset = max(0, current_offset - limit_per_page)
            continue

        if _sel_int == 0:
            new_q = prompt_input("🔍 검색할 새로운 유튜브 재생목록 키워드를 입력해줘", use_history=True, use_volatile_history=True)
            if not new_q: break
            query = new_q
            all_results = []
            current_offset = 0
            continue

        res_idx = _sel_int - 1
        if 0 <= res_idx < len(view_items):
            return view_items[res_idx]

    return None


# [TAG: #@_handle_playlist_action_menu]

def _handle_playlist_action_menu(playlist: dict, settings, saved_path):
    """선택된 재생목록에 대해 작업을 수행합니다. (L키 상세조회 연동 및 자동 감시 등록)"""
    import time
    pl_title = playlist.get('title')
    pl_url = playlist.get('url')
    
    while True:
        menu_items = [
            ("download_detail", f"📥   이 재생목록 상세 조회 및 다운로드 (L키 화면 연동)"),
            ("register_playlist", "🛰️   이 재생목록을 자동 감시(플레이리스트 등록)에 추가"),
            ("back", "↩️   뒤로가기")
        ]
        
        labels = [it[1] for it in menu_items]
        sel, action, *_ = _interactive_menu(f"🎬 재생목록 '{pl_title}'에 대해 어떤 작업을 할까냥?", labels, timeout=0)
        
        if sel < 0 or action == "CANCEL":
            return None, None
            
        choice = menu_items[sel][0]
        if choice == "back":
            return None, None
        
        elif choice == "download_detail":
            res_dict = _handle_youtube_search_interactive(pl_url, settings)
            if res_dict.get("items"):
                return "download", res_dict
            continue
            
        elif choice == "register_playlist":
            new_watch_url = pl_url
            is_playlist = True
            sort_mode = "auto"
            
            ask_items = [
                ("new_only", "🆕   지금부터 올라오는 '신규' 영상만 받기"),
                ("new_plus_test", "🧪   '신규' 영상만 받기 + 최근 영상 '하나' 테스트 다운로드"),
                ("include_all", "🎞️   기존에 올라와 있는 영상도 '모두' 받기")
            ]
            ask_labels = [it[1] for it in ask_items]
            ask_sel, _, *_ = _interactive_menu("🚀 추가한 플레이리스트의 정렬을 분석할게냥!", ask_labels, timeout=0)
            if ask_sel < 0:
                continue
                
            print(f" ⏳ {C.YELLOW}플레이리스트 정보를 분석 중입니다...{C.RESET}")
            try:
                initial_limit = 5000 if ask_sel == 2 else 100
                existing_items, fetched_title = scan_live_playlist(new_watch_url, [], sort_mode=sort_mode, limit=initial_limit)
                
                if fetched_title:
                    pl_title = fetched_title
                    
                current_add_items = []
                
                if ask_sel in [0, 1]:
                    h_path = get_yt_history_path(new_watch_url)
                    record_items = existing_items[:-1] if ask_sel == 1 and existing_items else existing_items
                    
                    if record_items:
                        v_ids = [it['id'] for it in record_items if it.get('id')]
                        save_video_history_bulk(v_ids, file_path=h_path)
                        
                    if ask_sel == 1 and existing_items:
                        test_item = existing_items[-1]
                        if test_item not in current_add_items:
                            current_add_items.append(test_item)
                        print(f" ✅ {C.GREEN}준비 완료! 최근 영상 1개는 테스트로 바로 받고, 나머지는 신규 대기할게냥! 🐾🧪{C.RESET}")
                    else:
                        print(f" ✅ {C.GREEN}준비 완료! 앞으로 올라오는 신규 영상만 감시할게냥! 🐾{C.RESET}")
                else:
                    for item in existing_items:
                        if item not in current_add_items:
                            current_add_items.append(item)
                    print(f" ✅ {C.CYAN}알겠어! 기존 영상들을 포함해 전체를 체크해서 다운로드할게! 🚀{C.RESET}")
                    
                if 'watch_playlist_configs' not in settings.data:
                    settings.data['watch_playlist_configs'] = {}
                settings.data['watch_playlist_configs'][new_watch_url] = {
                    'title': pl_title,
                    'sort': sort_mode,
                    'range': 'new' if ask_sel in [0, 1] else 'all',
                    'added_at': time.strftime("%Y-%m-%d %H:%M:%S")
                }
                
                current_urls = settings.data.get("watch_playlist_url", [])
                if isinstance(current_urls, str):
                    current_urls = [current_urls] if current_urls and current_urls != '미지정' else []
                    
                if new_watch_url not in current_urls:
                    current_urls.append(new_watch_url)
                    settings.data["watch_playlist_url"] = current_urls
                    settings.save()
                    print(f" ✅ {C.GREEN}플레이리스트 등록 완료!{C.RESET}")
                else:
                    print(f" ⚠️ {C.YELLOW}이미 등록된 주소야.{C.RESET}")
                
                time.sleep(1)
                
                if current_add_items:
                    v_urls = [it.get('url') if (it.get('url') and str(it.get('url')).startswith('http')) else f"https://www.youtube.com/watch?v={it.get('id')}" for it in current_add_items if it.get('url') or it.get('id')]
                    v_titles = [it.get('title', '알 수 없는 영상') for it in current_add_items]
                    _print_mode_dashboard("즉시 다운로드 시작", [("파일수", f"{len(v_urls)}개")], tips=["🚀 등록한 영상을 메뉴 이탈 없이 바로 다운로드만 깔끔하게 진행할게냥!"])
                    
                    # 10번 메뉴의 잘 만든 다운로드 로직 함수 호출! 🚀✨
                    download_youtube_interactive(
                        is_resume=True, 
                        show_banner=False, 
                        initial_urls=v_urls, 
                        initial_titles=v_titles,
                        playlist_url=new_watch_url,
                        force_bg=False
                    )
                        
                    print(f"\r\n ✅ {C.GREEN}즉시 다운로드 공정 완료!{C.RESET}")
                    time.sleep(1)
                    
                return "register", None
            except Exception as e:
                print(f" ⚠️ {C.YELLOW}등록 중 오류가 발생했어: {e}{C.RESET}")
                _log_to_file(f"⚠️ [Register playlist from search error] {e}")
                time.sleep(2)
                continue


# [TAG: #@_handle_youtube_search_interactive]
def _handle_youtube_search_interactive(query: str, settings, vr_mode: str = None) -> dict:
    """[V2.1] 유튜브 검색 결과를 토렌트 스타일 UI로 보여주고 선택하게 합니다. (결과 리스트와 메타정보 반환) 🔍🎬✨"""
    # [V155.3] VR 전용 검색 모드 자동 진입 처리 🥽✨
    q_low = (query or '').strip().lower()
    if vr_mode is None and (q_low == 'vr' or q_low.startswith('vr ') or q_low.startswith('vr_')):
        # [V155.4 Fix] 비누의 요청: 메뉴 리스트가 '먼저' 나오고 선택 후 검색어 입력창이 뜨도록 순서 변경! 🥽✨
        vr_items = [
            "👓 180° VR 전용 필터 검색 (입체감 최강 180° SBS)",
            "🌐 360° VR 전용 필터 검색 (360° 파노라마 3D)",
            "🚀 180° + 360° VR 통합 필터 검색 (둘 다)",
            "🔥 유튜브 실시간 인기 3D VR 영상 TOP 목록"
        ]
        sel_vr, _, *_ = _interactive_menu("🥽 어떤 VR 검색 필터를 사용할까냥?", vr_items, timeout=0)
        if sel_vr < 0: return {'items': [], 'pl_title': None}
        elif sel_vr == 0: vr_mode = '180'
        elif sel_vr == 1: vr_mode = '360'
        elif sel_vr == 2: vr_mode = 'both'
        elif sel_vr == 3: vr_mode = 'popular'

        q_target = query[2:].strip('_ ').strip() if (q_low.startswith('vr ') or q_low.startswith('vr_')) else ""
        if vr_mode == 'popular':
            query = "https://www.youtube.com/results?search_query=VR+180+3D&sp=CAMSAhAB"
        else:
            if not q_target:
                vr_mode_label = "180° VR" if vr_mode == '180' else ("360° VR" if vr_mode == '360' else "180°+360° VR")
                q_target = prompt_input(f" 🥽 [{vr_mode_label}] 어떤 영상을 찾고 싶어냥? (예: 키스오브라이프 / 아이브 / 롤러코스터 등): ").strip()
                if not q_target:
                    print(f" ⚠️ {C.YELLOW}검색어를 입력하지 않아서 이전 메뉴로 돌아갈게냥!{C.RESET}")
                    time.sleep(1)
                    return {'items': [], 'pl_title': None}
            query = q_target

    all_results = []
    current_offset = 0
    current_focus = 0 # [V17.3.34] AI냥 요청: 하부 메뉴에서도 손가락 위치(커서) 기억하기냥! ☝️📍
    is_expanded = False # [V143.70] 전체 펼치기 모드 여부 📜
    captured_pl_title = None # [V154.12] 플레이리스트/채널 제목 캡처용 🛰️

    # [V143.72] 장부 데이터(히스토리) 미리 로드하여 중복 체크 준비냥! 💎🛰️
    history_set = set(load_video_history())

    # [V123.0] 공통 브라우저 함수 활용 (b 키 대응 🛰️)
    # [TAG: #@browse_cb]
    def browse_cb(url):
        open_browser(url, message="유튜브 영상을 확인하러 간다냥! 🎬")

    is_url_query = any(x in query.lower() for x in ['youtube.com', 'youtu.be', 'http://', 'https://'])
    
    while True:
        limit_per_page = 200 if is_expanded else 50 # [V21.6] 루프 내 배치로 실시간 반영냥! 🚀
        # [V143.70] 현재 오프셋에 해당하는 결과가 없으면 새로 가져오기 📡
        if len(all_results) <= current_offset:
            new_results = []
            if is_url_query:
                # [URL 모드] 플레이리스트나 채널 주소인 경우 직접 추출
                desc = f"📡 {C.SKY}'{query[:40]}...'{C.RESET} 목록 분석 중 (현재 {len(all_results)}개)..."
                with LoadingSpinner(desc):
                    import yt_dlp
                    try:
                        ydl_opts = {
                            'extract_flat': True, 'quiet': True, 'no_warnings': True, 'logger': SilentLogger(),
                            'playlist_items': f"{current_offset + 1}-{current_offset + limit_per_page}",
                            'language': 'ko',
                            'extractor_args': {'youtube': {'lang': ['ko']}}, # [V17.5.3] AI냥 요청: 한국어 제목 강제 🇰🇷✨
                            'headers': { 'Accept-Language': 'ko-KR,ko;q=0.9,en-US;q=0.8,en;q=0.7' }
                        }
                        with yt_dlp.YoutubeDL(ydl_opts) as ydl:
                            info = ydl.extract_info(query, download=False)
                            if info:
                                if 'entries' in info and info['entries'] is not None:
                                    if not captured_pl_title: captured_pl_title = info.get('title') # [V154.12] 초기 분석 시 제목 캡처냥! 🎣🛰️
                                    for entry in info['entries']:
                                        if entry:
                                            v_id = entry.get('id')
                                            v_url = f"https://www.youtube.com/watch?v={v_id}" if v_id else (entry.get('url') or entry.get('webpage_url'))

                                            entry_up = entry.get('uploader') or entry.get('channel')
                                            playlist_up = info.get('uploader') or info.get('channel')
                                            final_up = entry_up or playlist_up or '알 수 없음'

                                            new_results.append({
                                                'id': v_id, 'title': entry.get('title', '제목 없음'),
                                                'url': v_url, 'uploader': final_up,
                                                'duration': entry.get('duration')
                                            })
                                else:
                                    # [V155.2 Fix] 단일 유튜브 동영상 URL 입력 시 파싱 누락 완벽 대응! 🎯✨
                                    v_id = info.get('id')
                                    v_url = f"https://www.youtube.com/watch?v={v_id}" if v_id else (info.get('webpage_url') or query)
                                    final_up = info.get('uploader') or info.get('channel') or '알 수 없음'
                                    v_title = info.get('title')
                                    v_dur = info.get('duration')
                                    if not v_title or v_title == '제목 없음' or not v_dur:
                                        try:
                                            with yt_dlp.YoutubeDL({'quiet': True, 'no_warnings': True, 'logger': SilentLogger(), 'noplaylist': True, 'language': 'ko'}) as ydl_single:
                                                info_s = ydl_single.extract_info(v_url, download=False)
                                                if info_s:
                                                    v_title = info_s.get('title') or v_title
                                                    final_up = info_s.get('uploader') or info_s.get('channel') or final_up
                                                    v_dur = info_s.get('duration') or v_dur
                                        except Exception:
                                            pass
                                    new_results.append({
                                        'id': v_id, 'title': v_title or '제목 없음',
                                        'url': v_url, 'uploader': final_up,
                                        'duration': v_dur
                                    })
                    except Exception as e:
                        _log_to_file(f"📡 [URL Entry Extraction Error] {e}")
            else:
                # [검색 모드] 일반 키워드 검색
                desc = f"🔍 {C.SKY}'{query}'{C.RESET} 유튜브 검색 중 (현재 {len(all_results)}개)..."
                with LoadingSpinner(desc):
                    actual_query = query
                    if vr_mode:
                        if vr_mode == '180': actual_query = f"{query} VR 180 3D"
                        elif vr_mode == '360': actual_query = f"{query} VR 360 3D"
                        elif vr_mode == 'both': actual_query = f"{query} VR 180 360 3D"
                        elif vr_mode == 'popular': actual_query = "VR 180 3D 8K"

                    raw_results = _search_youtube_advanced(actual_query, limit=limit_per_page, offset=current_offset)
                    new_results = []
                    for r in raw_results:
                        t_u = r.get('title', '').upper()
                        is_vr_item = r.get('is_vr') or any(k in t_u for k in ['VR', '180', '360', 'SBS', '3D VR', 'VR캠'])
                        if vr_mode and not is_vr_item:
                            continue # VR 모드 시 일반 2D 영상 걸러내기 🧼
                        
                        # [V155.3] 180° / 360° 사전 라벨 배지 주입! 👓🌐🏷️
                        is_360 = '360' in t_u or r.get('projection_type') in ['equirectangular', 'cubemap']
                        if vr_mode == '180' and is_360:
                            continue # 180° VR 전용 모드 시 360° VR 영상 완벽 차단! 🧼✨
                        if vr_mode == '360' and not is_360:
                            continue # 360° VR 전용 모드 시 180° VR 영상 완벽 차단! 🧼✨
                        badge = "🌐 [360° VR]" if is_360 else "👓 [180° VR]" if is_vr_item else ""
                        if badge:
                            r['display_label'] = f"{badge} {r.get('title')}"
                        new_results.append(r)

            if new_results:
                all_results.extend(new_results)
            elif not all_results:
                print(f"  ❌ {C.RED}가져올 수 있는 영상이 없습니다냥...{C.RESET}")
                time.sleep(1.5); break
            else:
                # 더 이상 결과가 없는 경우 마지막 페이지로 고정
                if current_offset >= limit_per_page:
                    print(f"  ✨ {C.GOLD}마지막 페이지입니다냥! 👍{C.RESET}")
                    current_offset -= limit_per_page
                    time.sleep(1)

        # [V143.70] 화면에 표시할 항목 결정 (페이징 vs 전체 펼치기) 🔘
        view_items = all_results if is_expanded else all_results[current_offset : current_offset + limit_per_page]

        display_options = []
        display_options.append(f"🔍 {C.SKY}다른 키워드로 유튜브 재검색{C.RESET}")
        display_options.append(f"🌐 {C.SKY}결과 페이지 웹에서 보기{C.RESET}")

        for r in view_items:
            dur_val = r.get('duration')
            if dur_val:
                h = int(dur_val) // 3600
                m = (int(dur_val) % 3600) // 60
                s = int(dur_val) % 60
                dur_str = f"{h:02d}:{m:02d}:{s:02d}" if h > 0 else f"{m:02d}:{s:02d}"
            else:
                dur_str = "--:--"
            _uploader = r.get('uploader') or '알 수 없음'
            _raw_title = r.get('title') or '제목 없음'
            t_u = _raw_title.upper()
            is_vr_item = r.get('is_vr') or any(k in t_u for k in ['VR', '180', '360', 'SBS', '3D VR', 'VR캠'])
            is_360 = '360' in t_u or r.get('projection_type') in ['equirectangular', 'cubemap']
            vr_badge = f"{C.GREEN}🌐 [360° VR]{C.RESET} " if is_360 else (f"{C.SKY}👓 [180° VR]{C.RESET} " if is_vr_item else "")
            _title = f"{vr_badge}{_raw_title}"

            # [V143.72] 장부(History) 체크 로직: 제목 색상은 사용자 요청으로 화사하게 원복(WHITE)하고 💾 표시만 남김냥! 🛡️✨
            # [V154.91] AI냥 요청: 폰트가 중간에 바뀌어 보이는 현상 해결 (색상 시퀀스 일관성 유지) 🛰️✨
            is_in_history = r.get('id') in history_set
            h_marker = f"{C.LIME}💾{C.RESET}" if is_in_history else f"{C.SKY}🎬{C.RESET}"

            dur_label = f"[{C.GOLD}{dur_str:>5}{C.RESET}]"
            up_label = f"[{C.SKY}{_uploader:<10}{C.RESET}]" # [V152.23] 하드코딩 슬라이싱 제거냥! 🧼✨
            title_label = f" {_title}"
            pretty_label = f"{h_marker} {dur_label}{up_label}{title_label}" # [V143.76] 대기목록에서도 쓸 예쁜 라벨 저장! ✨
            display_options.append(pretty_label)
            r['display_label'] = pretty_label # 아이템 객체에 라벨 박제냥! 📌

        # [V141.2] AI냥 통합 요청: 공통 페이지네이션 로직 사용! 🌐🔄✨
        idx_prev, idx_next = -1, -1
        if not is_expanded:
            paginations = _get_pagination_opts(curr_page=current_offset // limit_per_page + 1)
            for p in paginations:
                if p.get('key') == 'action_PREV_PAGE':
                    idx_prev = len(display_options)
                elif p.get('key') == 'action_NEXT_PAGE':
                    idx_next = len(display_options)
                display_options.append(p)


        idx_toggle_expand = len(display_options)
        if is_expanded:
            display_options.append(f"📄 {C.CYAN}페이지 단위로 보기 (접기){C.RESET}")
        else:
            display_options.append(f"📜 {C.CYAN}전체 펼치기 (100개+ 무제한 한꺼번에 보기){C.RESET}")

        idx_all, idx_new = -1, -1
        # [V22.0] AI냥 요청: URL 분석뿐만 아니라 일반 키워드 검색 결과에서도 전체 추가 및 미다운로드 추가가 상시 가능하도록 가드 해제! 🚀✨
        idx_all = len(display_options)
        display_options.append(f"➕ {C.SKY}이 목록 전체 추가 (All){C.RESET}")
        idx_new = len(display_options)
        display_options.append(f"✨ {C.GOLD}미다운로드(장부에 없는) 항목만 자동 추가{C.RESET}")

        idx_batch = len(display_options)
        display_options.append(f"📦 {C.GREEN}선택 항목 일괄 추가 (Space로 멀티 선택){C.RESET}")
        idx_cancel = len(display_options)
        display_options.append("↩️ 취소")

        hint = f" {C.GRAY}(b:브라우징, u:업로더, h:히스토리, space:멀티){C.RESET}"
        count_info = f" ({len(view_items)}개)"
        p_info = " [전체]" if is_expanded else f" [{current_offset//limit_per_page + 1}페이지]"
        title = ("📡 URL 분석 결과" if is_url_query else f"📺 '{query}' 검색 결과") + f"{count_info}{p_info}{hint}"

        # [V21.6] AI냥 요청: "한번에 쫙" 보기 위해 펼치기 모드에서는 2열(cols=2) 레이아웃 적용냥! 📐✨
        # [V21.9] 터미널 너비가 너무 좁으면(110자 미만) 억지로 2열로 만들지 않고 1열로 유지하여 가독성 사수냥! 🛡️📏
        _tw, _ = shutil.get_terminal_size()
        _c_mode = 2 if (is_expanded and _tw >= 110) else 1
        
        sel_idx, action, selected_set, *_ = _interactive_menu(
            title, display_options, timeout=0, prefix="[Search] ", allow_multi=True,
            browse_callback=browse_cb, allow_paging=True, allow_further=True,
            default_idx=current_focus, cols=_c_mode
        )

        if sel_idx == -1 or action == "CANCEL": break

        # [V154.12] sel_idx 정규화 (리스트/단일 int 대응)
        _sel_int = sel_idx[0] if isinstance(sel_idx, list) and len(sel_idx) > 0 else (sel_idx if isinstance(sel_idx, int) else -1)

        if isinstance(sel_idx, list) and sel_idx: current_focus = sel_idx[0]
        elif isinstance(sel_idx, int) and sel_idx >= 0: current_focus = sel_idx

        if _sel_int == idx_cancel: break

        # 브라우징/히스토리/업로더필터/페이징 처리
        if action == "FILTER_UPLOADER":
            target_idx = _sel_int
            res_idx = target_idx - 2
            if 0 <= res_idx < len(view_items):
                target_item = view_items[res_idx]
                target_uploader = target_item.get('uploader')
                if target_uploader and target_uploader != '알 수 없음':
                    up_clean = target_uploader.strip()
                    up_lower = up_clean.lower()
                    filtered = [r for r in all_results if r.get('uploader') and up_lower in r.get('uploader').strip().lower()]
                    if filtered:
                        all_results = filtered
                        current_offset = 0
                        print(f"\n  🎯 {C.SKY}'{up_clean}'{C.RESET}{C.GOLD} 업로더 항목 ({len(filtered)}개)으로 필터링했어냥! 🐾{C.RESET}")
                        time.sleep(1)
                    else:
                        print(f"\n  🔍 {C.SKY}'{up_clean}'{C.RESET}{C.GOLD} 업로더 키워드로 유튜브 재검색을 진행할게냥! 🐾{C.RESET}")
                        time.sleep(1)
                        query = up_clean
                        all_results = []
                        current_offset = 0
                        is_url_query = False
                else:
                    print(f"\n  ⚠️ {C.YELLOW}선택한 항목의 업로더 정보를 찾을 수 없어냥! 🐾{C.RESET}")
                    time.sleep(1)
            continue

        if action in ["BROWSE", "HISTORY"]:
            target_idx = _sel_int
            res_idx = target_idx - 2
            if 0 <= res_idx < len(view_items):
                if action == "BROWSE": browse_cb(view_items[res_idx]['url'])
                else: handle_playlist_history_sync(view_items[res_idx]['url'], settings)
            continue

        if action in ("NEXT_PAGE", "FURTHER") or (idx_next != -1 and _sel_int == idx_next):
            current_offset += limit_per_page; continue
        if action == "PREV_PAGE" or (idx_prev != -1 and _sel_int == idx_prev):
            current_offset = max(0, current_offset - limit_per_page); continue

        # 기능 버튼 처리
        if _sel_int == 0:
            new_q = prompt_input("🔍 검색할 새로운 유튜브 키워드를 입력해줘", use_history=True, use_volatile_history=True)
            if not new_q: break
            query = new_q; all_results = []; current_offset = 0; is_url_query = False; continue

        if _sel_int == 1:
            # 결과 페이지 웹에서 보기
            import urllib.parse
            if is_url_query:
                search_url = query
            else:
                encoded_query = urllib.parse.quote(query)
                search_url = f"https://www.youtube.com/results?search_query={encoded_query}"
            
            browse_cb(search_url)
            continue

        if _sel_int == idx_toggle_expand:
            if not is_expanded:
                if is_url_query:
                    desc = f"📜 {C.SKY}전체 목록(최대 1000개)을 한꺼번에 가져오는 중이야냥...🐾{C.RESET}"
                    with LoadingSpinner(desc):
                        import yt_dlp
                        try:
                            ydl_opts = {
                                'extract_flat': True, 'quiet': True, 'no_warnings': True, 'logger': SilentLogger(),
                                'playlist_items': "1-1000",
                                'language': 'ko',
                                'extractor_args': {'youtube': {'lang': ['ko']}},
                                'headers': { 'Accept-Language': 'ko-KR,ko;q=0.9,en-US;q=0.8,en;q=0.7' }
                            }
                            with yt_dlp.YoutubeDL(ydl_opts) as ydl:
                                info = ydl.extract_info(query, download=False)
                                if info and 'entries' in info:
                                    captured_pl_title = info.get('title')
                                    all_results = []
                                    for entry in info['entries']:
                                        if entry:
                                            v_id = entry.get('id')
                                            v_url = f"https://www.youtube.com/watch?v={v_id}" if v_id else (entry.get('url') or entry.get('webpage_url'))
                                            all_results.append({
                                                'id': v_id, 'title': entry.get('title', '제목 없음'),
                                                'url': v_url, 'uploader': entry.get('uploader', info.get('uploader', '알 수 없음')),
                                                'duration': entry.get('duration')
                                            })
                        except Exception as e:
                            _log_to_file(f"📜 [Full Expand Fetch Error] {e}")
                else:
                    desc = f"🔍 {C.SKY}'{query}'{C.RESET} 관련 영상을 듬뿍(최대 500개) 가져오는 중이야냥...🐾"
                    with LoadingSpinner(desc):
                        new_results = _search_youtube_advanced(query, limit=500, offset=0)
                        if new_results: all_results = new_results
            is_expanded = not is_expanded
            if is_expanded: current_offset = 0
            continue

        if _sel_int == idx_all:
            return {"items": all_results, "pl_title": captured_pl_title}
        
        if _sel_int == idx_new:
            with LoadingSpinner(f" 🔍 {C.SKY}히스토리 데이터와 대조 중이야냥... 🐾{C.RESET}"):
                history_set = set(load_video_history())
                new_items = [r for r in all_results if r.get('id') not in history_set]
            if not new_items:
                print(f" ✨ {C.GOLD}모든 영상이 이미 히스토리에 있어냥! 👍{C.RESET}")
                time.sleep(1.2); continue
            return {"items": new_items, "pl_title": captured_pl_title}

        if _sel_int == idx_batch:
            if not selected_set:
                print(f" ⚠️ {C.YELLOW}먼저 Space 키로 다운로드할 항목들을 골라줘냥! 🐾{C.RESET}")
                time.sleep(1.2); continue
            valid_items = [view_items[i-2] for i in selected_set if 2 <= i <= len(view_items) + 1]
            return {"items": valid_items, "pl_title": captured_pl_title}

        # 개별 아이템 선택
        res_idx = _sel_int - 2
        if 0 <= res_idx < len(view_items):
            # Space로 선택된 다중 항목이 있다면 그걸 우선
            if selected_set and len(selected_set) > 0:
                valid_items = [view_items[i-2] for i in selected_set if 2 <= i <= len(view_items) + 1]
                return {"items": valid_items, "pl_title": captured_pl_title}
            # 아니면 현재 Enter 친 항목 하나만 반환
            return {"items": [view_items[res_idx]], "pl_title": captured_pl_title}

    return {"items": [], "pl_title": None}

    return {"items": [], "pl_title": None}
# [TAG: #@_get_chrome_youtube_history]

def _get_chrome_youtube_history(limit=50):
    """[V200.0] 로컬 크롬 브라우저의 History DB(SQLite)를 읽어와 최근 유튜브 시청 기록을 초고속으로 추출합니다냥! 🕵️‍♂️✨"""
    import os, shutil, sqlite3, tempfile
    import urllib.parse
    
    entries = []
    local_app_data = os.environ.get('LOCALAPPDATA', '')
    if not local_app_data: return entries
    
    history_db = os.path.join(local_app_data, r'Google\Chrome\User Data\Default\History')
    if not os.path.exists(history_db): return entries
        
    temp_dir = tempfile.gettempdir()
    temp_db = os.path.join(temp_dir, 'chrome_history_temp.db')
    
    try:
        shutil.copy2(history_db, temp_db)
        conn = sqlite3.connect(temp_db)
        cursor = conn.cursor()
        
        cursor.execute('''
            SELECT url, title, last_visit_time 
            FROM urls 
            WHERE url LIKE '%youtube.com/watch%' 
            ORDER BY last_visit_time DESC 
            LIMIT ?
        ''', (limit,))
        
        for url, title, _ in cursor.fetchall():
            parsed_url = urllib.parse.urlparse(url)
            qs = urllib.parse.parse_qs(parsed_url.query)
            video_id = qs.get('v', [None])[0]
            
            if video_id and not any(e['id'] == video_id for e in entries):
                entries.append({
                    'id': video_id,
                    'title': title,
                    'url': url,
                    'uploader': 'Chrome History',
                    'duration': 0
                })
        
        conn.close()
    except Exception as e:
        print(f"  ⚠️ {C.YELLOW}크롬 시청 기록을 불러오는데 실패했어냥: {e}{C.RESET}")
    finally:
        if os.path.exists(temp_db):
            try: os.remove(temp_db)
            except: pass
            
    return entries

# [TAG: #@_execute_youtube_download_process]
def _execute_youtube_download_process(
    urls: list, 
    video_titles: list, 
    saved_path: str, 
    choice_idx: int, 
    settings, 
    is_bg_mode: bool = False, 
    dynamic_fragments: int = 4, 
    is_resume_subtitles: bool = False, 
    chat_id: str = ""
) -> Tuple[list, bool]:
    """
    [V176.0] 유튜브 다운로드 실행 엔진 (포어그라운드 / 완전 비노출 백그라운드 공통)
    - is_bg_mode == True : 완전 비노출(Silent) 다운로드, 콘솔 렌더링 X, 완료 후 메뉴 X, G_BG_DOWNLOAD_STATUS 등록
    - is_bg_mode == False : 실시간 진행바(현황판) 콘솔 렌더링, 완료 후 FINAL 작업완료 메뉴 노출
    """
    import re, copy, yt_dlp

    if not urls:
        return [], False

    # [V178.11] 착수 전 여유 공간 사전 검사 — Errno 28 로 3회 futile 재시도 후 포기했던 사고 원천 차단! 💾🛡️
    try:
        _probe_dir = os.path.normpath(saved_path)
        while _probe_dir and not os.path.isdir(_probe_dir):
            _nxt = os.path.dirname(_probe_dir)
            if _nxt == _probe_dir: break
            _probe_dir = _nxt
        if _probe_dir and os.path.isdir(_probe_dir):
            _free_b = shutil.disk_usage(_probe_dir).free
            if _free_b < 2 * 1024 ** 3:
                _log_to_file(f"🛑 [Disk-Guard] '{_probe_dir}' 여유 공간 {_free_b / 1024**3:.2f}GB < 2.00GB "
                             f"→ 유튜브 다운로드를 시작하지 않고 즉시 중단한다! (Errno 28 futile 재시도 원천 차단) 🚀")
                if not is_bg_mode:
                    print(f"\r\n 🛑 {C.RED}[용량 부족]{C.RESET} 저장장치 여유 공간이 {_free_b / 1024**3:.2f}GB야. "
                          f"2GB 이상 확보한 뒤 다시 시도해줘! 🚀{R}")
                return [], False
    except Exception:
        pass

    work_id = hashlib.md5(urls[0].encode()).hexdigest()[:10]
    curr_pid = os.getpid()

    while True:
        saved_path = os.path.normpath(saved_path)
        work_path = os.path.join(saved_path, f"_work_{work_id}_p{curr_pid}")
        lock_file = os.path.join(work_path, ".process.lock")

        if os.path.exists(lock_file):
            try:
                with open(lock_file, "r") as f:
                    existing_pid = safe_int(f.read().strip())
                if PendingQueue._is_pid_alive(existing_pid):
                    if not is_bg_mode:
                        print(f"\r\n ⚠️  {C.YELLOW}앗! 이미 다른 창(PID: {existing_pid})에서 이 작업을 하고 있어냥!{R}")
                        print(f" ✨ {C.SKY}중복 다운로드 방지를 위해 현재 창의 작업은 멈출게냥! 👍{R}")
                        time.sleep(3)
                    else:
                        _log_to_file(f"⚠️ [Bg-Download Skip] 이미 다른 프로세스(PID: {existing_pid})에서 작업 중")
                    return [], False
            except Exception as e:
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

        try:
            if not os.path.exists(work_path):
                os.makedirs(work_path, exist_ok=True)
            with open(lock_file, "w") as f:
                f.write(str(os.getpid()))
            break
        except Exception as e:
            if is_bg_mode:
                _log_to_file(f"❌ [Bg Work Path Error] {e}")
                time.sleep(2)
                try:
                    if not os.path.exists(work_path): os.makedirs(work_path, exist_ok=True)
                    break
                except Exception:
                    return [], False

            is_device_not_ready = "[WinError 21]" in str(e) or "device not ready" in str(e).lower()
            if is_device_not_ready:
                print(f"\r\n ⚠️  {C.RED}앗! 장치가 준비되지 않았어멍! (G: 드라이브 등 연결 확인){R}")
                print(f" ⏳ {C.YELLOW}1초 후에 자고 있는 드라이브를 한 번 더 깨워 볼게냥...{R}")
                time.sleep(1.0)
                try:
                    if not os.path.exists(work_path):
                        os.makedirs(work_path, exist_ok=True)
                    print(f" ✅ {C.GREEN}축하해멍! 자동 재시도로 드라이브를 깨웠어!{R}")
                    break
                except Exception as ex:
                    if "6" not in str(ex):
                        _log_to_file(f"⚠️ [Silent Exception] {ex}")

            print(f"\r\n ❌ {C.RED}작업 폴더 생성 실패: {e}{R}")
            r_opts_map = [
                {"label": f"🔄 {C.BOLD}재시도 (드라이브 연결 완료){R}", "key": "retry"},
                {"label": f"🏠 {C.SKY}내 컴퓨터 본체(기본 폴더)에 저장할래!{R}", "key": "default"},
                {"label": "📂 다른 폴더 직접 선택하기 (바탕화면 등)", "key": "other"},
                {"label": "❌ 취소 (다음에 할래냥!)", "key": "cancel"}
            ]
            r_opts = [item["label"] for item in r_opts_map]
            r_sel, _, *_ = _interactive_menu("🆘 드라이브가 먹통이야멍! 어떻게 할까냥?", r_opts, timeout=0)
            if r_sel < 0: return [], False
            r_key = r_opts_map[r_sel]["key"]
            if r_key == "retry":
                time.sleep(0.5); continue
            elif r_key == "default":
                saved_path = os.path.join(os.path.expanduser("~"), "Downloads")
                time.sleep(1); continue
            elif r_key == "other":
                root = tk.Tk(); root.withdraw()
                new_p = remote_explorer(mode='dir', title="드라이브 대신 저장할 곳을 골라줘!")
                restore_console_focus()
                # [버그수정] remote_explorer(dir)는 리스트(선택결정 버튼) 반환 가능 → 단일 경로로 안전 추출 🛡️
                new_p = _get_single_path(new_p)
                if new_p:
                    saved_path = new_p
                    time.sleep(1); continue
                else: continue
            else:
                return [], False

    # G_BG_DOWNLOAD_STATUS 등록
    if 'G_BG_DOWNLOAD_STATUS' not in globals():
        globals()['G_BG_DOWNLOAD_STATUS'] = {}
    for idx_u, (u_url, u_title) in enumerate(zip(urls, video_titles)):
        globals()['G_BG_DOWNLOAD_STATUS'][u_url] = {
            'title': u_title or u_url,
            'index': idx_u + 1,
            'total': len(urls),
            'pct': '0.0%',
            'speed': '0B/s',
            'eta': '--:--',
            'status': 'waiting',
            'type': 'youtube'
        }

    all_downloaded_files = []
    _yt_lock = threading.Lock()

    class SafeFilenameCollector:
        def __init__(self):
            self.finished_raw_paths = []
            self.finished_infos = {}
            self._lock = threading.Lock()
        def hook(self, d):
            if d.get('status') == 'finished':
                info = d.get('info_dict') or {}
                f = info.get('_filename')
                v_id = info.get('id')
                with self._lock:
                    if f:
                        if f not in self.finished_raw_paths:
                            self.finished_raw_paths.append(f)
                        self.finished_infos[f] = info
                    if v_id:
                        self.finished_infos[v_id] = info
        def post_hook(self, d):
            if d.get('status') == 'finished':
                info = d.get('info_dict') or {}
                f = info.get('_filename')
                v_id = info.get('id')
                with self._lock:
                    if f:
                        if f not in self.finished_raw_paths:
                            self.finished_raw_paths.append(f)
                        self.finished_infos[f] = info
                    if v_id:
                        self.finished_infos[v_id] = info

    collector = SafeFilenameCollector()

    ff_path = _get_ffmpeg_bin()
    ydl_opts = {
        'ffmpeg_location': ff_path,
        'js_runtimes': _get_ytdl_js_runtimes(),
        'remote_components': ['ejs:github'],
        'ignoreerrors': False,
        'socket_timeout': 30,
        'retries': 15,
        'fragment_retries': 15,
        'file_access_retries': 20, # [V178.8] 파일 락 충돌(WinError 32) 방어용 재시도 상향! 🛡️⚡
        'skip_unavailable_fragments': True,
        'continuedl': True,
        'paths': {
            'home': work_path,
            'temp': work_path
        },
        'language': 'ko',
        'user_agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0.0.0 Safari/537.36',
        'headers': {
            'Accept-Language': 'ko-KR,ko;q=0.9,en-US;q=0.8,en;q=0.7',
            'Sec-Ch-Ua': '"Chromium";v="128", "Not;A=Brand";v="24", "Google Chrome";v="128"',
            'Sec-Ch-Ua-Platform': '"Windows"',
        },
        'concurrent_fragments': dynamic_fragments,
        'concurrent_fragment_downloads': dynamic_fragments,
        'http_chunk_size': 10 * 1024 * 1024,
        'buffersize': 1024 * 1024,
        'extractor_args': {
            'youtube': {
                'lang': ['ko'],
                'country': ['KR']
            }
        },
        'referer': 'https://www.youtube.com/',
        'nopart': False,
        'overwrites': True,
        'restrictfilenames': False,
        'windowsfilenames': True,
        'trim_file_name': 120, # [V178.8] 윈도우 MAX_PATH(260자) [Errno 2] 원천 차단! 🛡️📏
        'noplaylist': True,
        'progress_hooks': [collector.hook],
        'postprocessor_hooks': [collector.post_hook],
        'quiet': True,
        'noprogress': True,
        'no_color': True,
        'logger': SilentLogger(),
        'no_warnings': True,
        'updatetime': False,
        'postprocessor_args': ['-y', '-loglevel', 'error'],
        'merge_output_format': 'mp4',
        'keepsubtitles': False,
        'writesubtitles': True,
        'allsubtitles': False,
        'subtitleslangs': ['ko.*', 'en.*', 'ja.*', 'jp.*'],
        'writeautomaticsub': False,
        'embedsubtitles': True,
        'addmetadata': True,
        'embedchapters': True,
        'postprocessors': [
            {'key': 'FFmpegSubtitlesConvertor', 'format': 'srt'},
            {'key': 'FFmpegEmbedSubtitle', 'already_have_subtitle': False},
            {'key': 'FFmpegMetadata', 'add_chapters': True, 'add_metadata': True}
        ]
    }
    ydl_opts = _apply_ytdl_stealth_opts(ydl_opts)

    def get_v_fmt(res=None):
        r = f"[height<={res}]" if res else ""
        # [V178.7 FIX] AV1(av01) 원천 차단 + 해상도 최우선 사수 (VP9 없어도 H.264 선택하여 360p 추락 방지!) 🛡️🎬
        v_primary = f"bestvideo{r}[vcodec!^=av01]+bestaudio/best{r}[vcodec!^=av01]"
        v_fallback = f"bestvideo{r}+bestaudio/best{r}"
        return f"{v_primary}/{v_fallback}"

    if choice_idx in (7, 8) and globals().get('_TEMP_CUSTOM_FORMAT'):
        custom_fmt = globals().get('_TEMP_CUSTOM_FORMAT', 'best')
        if custom_fmt.isdigit():
            ydl_opts['format'] = f"{custom_fmt}+bestaudio"
        else:
            ydl_opts['format'] = custom_fmt
        ydl_opts['format_sort'] = ['res', 'codec:vp9:h264', 'br', 'fps']
    elif choice_idx == 0:
        ydl_opts['format'] = get_v_fmt()
        ydl_opts['format_sort'] = ['res', 'codec:vp9:h264', 'br', 'fps']
    elif choice_idx == 1:
        ydl_opts['format'] = get_v_fmt(1440)
        ydl_opts['format_sort'] = ['res:1440', 'codec:vp9:h264', 'br', 'fps']
    elif choice_idx == 2:
        ydl_opts['format'] = get_v_fmt(1080)
        ydl_opts['format_sort'] = ['res:1080', 'codec:vp9:h264', 'br', 'fps']
    elif choice_idx == 3:
        ydl_opts['format'] = get_v_fmt(720)
        ydl_opts['format_sort'] = ['res:720', 'codec:vp9:h264', 'br', 'fps']
    else:
        ydl_opts['format'] = 'bestaudio/best'
        ydl_opts['format_sort'] = ['br', 'fps']
        ydl_opts['merge_output_format'] = None
        ydl_opts['writesubtitles'] = False
        ydl_opts['embedsubtitles'] = False
        if choice_idx == 6:
            # [V163.3] ⚡ 음원 원본 복사 (OPUS / No Encoding - 스트림 복사)
            ydl_opts['postprocessors'] = [
                {'key': 'FFmpegExtractAudio', 'preferredcodec': 'best', 'nopostoverwrites': False},
                {'key': 'FFmpegMetadata', 'add_chapters': True, 'add_metadata': True}
            ]
            ydl_opts['postprocessor_args'] = ['-c:a', 'copy', '-y', '-loglevel', 'error']
        elif choice_idx == 7:
            # [V163.3] 🛡️ 무손실 오디오 (WAV)
            ydl_opts['postprocessors'] = [
                {'key': 'FFmpegExtractAudio', 'preferredcodec': 'wav'},
                {'key': 'FFmpegMetadata', 'add_chapters': True, 'add_metadata': True}
            ]
            ydl_opts['postprocessor_args'] = ['-y', '-loglevel', 'error']
        else:
            target_ext = ['mp3', 'm4a'][max(0, min(1, choice_idx-4))]
            ydl_opts['postprocessors'] = [
                {'key': 'FFmpegExtractAudio', 'preferredcodec': target_ext, 'preferredquality': '192'},
                {'key': 'FFmpegMetadata', 'add_chapters': True, 'add_metadata': True}
            ]
            ydl_opts['postprocessor_args'] = ['-y', '-loglevel', 'error']

    if not is_bg_mode:
        print_youtube_header(saved_path, len(urls), "STEP 3: 다운로드 중", settings_data=settings.data if hasattr(settings, 'data') else None)
        print(f"\r\n🚀 {ctext(f'{len(urls)}개 영상의 멀티 다운로드를 시작합니다! (동적 분할: {dynamic_fragments} fragments/스레드)', C.YELLOW, C.BOLD)}")
        with _yt_lock:
            print(f"\r\n {C.GOLD}{C.BOLD}[ 📋 전체 다운로드 작업 목록 ]{R}")
            print(f" {C.DIM}{'━' * 110}{R}")
            _disp_limit = 12
            for i, (u, t) in enumerate(zip(urls, video_titles)):
                _title_disp = t[:100] + ".." if len(t) > 102 else t
                if i < _disp_limit:
                    print(f" {C.GOLD}⚡{R} {C.YELLOW}{_title_disp}{R}")
                elif i == _disp_limit:
                    print(f" {C.DIM}   ... 외 {len(urls) - _disp_limit}개의 작업이 줄 서있어냥! 🐾{R}")
                    break
            print(f" {C.DIM}{'━' * 110}{R}\r\n")
            for _ in range(6): print("")

    completed_count = 0
    completed_lock = threading.Lock()
    _progress_slots = [None] * 4
    _slot_lock = threading.Lock()
    _available_slots = list(range(4))
    _available_slots_lock = threading.Lock()
    _last_dashboard_render_time = [0.0]

    def _render_dashboard_slots(force=False):
        if is_bg_mode:
            return
        now = time.time()
        if not force and (now - _last_dashboard_render_time[0] < 0.5):
            return
        _last_dashboard_render_time[0] = now
        with _yt_lock:
            sys.stdout.write("\033[6A")
            with completed_lock:
                curr_done = completed_count
            total_jobs = len(urls)
            sys.stdout.write(f"\r\033[K {C.SKY}{C.BOLD}[ 🚀 실시간 진행 현황판 (4 Threads | {curr_done}/{total_jobs}) ]{R}\r\n")
            sys.stdout.write(f"\r\033[K {C.DIM}{'─' * 110}{R}\r\n")
            for i in range(4):
                slot = _progress_slots[i]
                if slot:
                    _, status = slot
                    sys.stdout.write(f"\r\033[K {status}\r\n")
                else:
                    sys.stdout.write(f"\r\033[K {C.DIM} 💤 AI냥이 다음 작업을 기다리고 있어냥...{R}\r\n")
            sys.stdout.flush()

    if not is_bg_mode:
        _render_dashboard_slots(force=True)

    try:
        current_history = set(load_video_history())

        def _single_download_task(args):
            idx, v_url, v_title, history_set = args
            my_slot = None
            with _available_slots_lock:
                if _available_slots: my_slot = _available_slots.pop(0)
            if my_slot is None: return False

            # 이제 슬롯을 획득하여 실제 다운로드가 시작되므로 downloading으로 상태 전환! 📥✨
            if 'G_BG_DOWNLOAD_STATUS' in globals() and v_url in globals()['G_BG_DOWNLOAD_STATUS']:
                globals()['G_BG_DOWNLOAD_STATUS'][v_url]['status'] = 'downloading'

            try:
                _clean_t = re.sub(r'\x1b[^m]*m', '', v_title)
                _pure_t = re.sub(r'^\[\s*[\d\-:]+\s*\]\s*', '', _clean_t)
                _pure_t = re.sub(r'^\[.*?\]\s*', '', _pure_t).strip()
                safe_title = "".join([c for c in _pure_t if c not in r'\/:*?"<>|']).strip()
                if not safe_title: safe_title = "유튜브_영상"
                cur_ydl_opts = _apply_ytdl_stealth_opts(dict(ydl_opts))

                is_vr_keyword = bool(re.search(r'(?:\bVR\b|\b180[°도]|\b360[°도]|\bSBS\b|3D\s*VR|VR\s*캠|VR\s*180|VR\s*360)', v_title or '', re.IGNORECASE))
                vr_tag = ''
                if is_vr_keyword:
                    _vt_upper = (v_title or '').upper()
                    if any(k in _vt_upper for k in ['SIMULATED', 'DEPTH MAP', 'DEPTHMAP']):
                        vr_tag = '_full_sbs'
                    else:
                        vr_tag = '_360_mono' if ('360' in _vt_upper or '360°' in _vt_upper or '360도' in _vt_upper) else '_180_SBS'
                    cur_ydl_opts['format'] = 'bestvideo+bestaudio/best'
                    _ext_args = dict(ydl_opts.get('extractor_args', {}))
                    cur_ydl_opts['extractor_args'] = _ext_args
                    if vr_tag not in v_title:
                        cur_ydl_opts['outtmpl'] = f"[%(uploader).30s] %(title).100s{vr_tag}.%(ext)s"
                    else:
                        cur_ydl_opts['outtmpl'] = "[%(uploader).30s] %(title).100s.%(ext)s"
                else:
                    cur_ydl_opts['outtmpl'] = "[%(uploader).30s] %(title).100s.%(ext)s"
                cur_ydl_opts['trim_file_name'] = 120 # [V178.8] 윈도우 MAX_PATH(260자) [Errno 2] 완벽 차단! 🛡️📏
                cur_ydl_opts['windowsfilenames'] = True

                v_id = None
                v_id_match = re.search(r'(?:v=|\/)([0-9A-Za-z_-]{11}).*', v_url)
                if v_id_match: v_id = v_id_match.group(1)

                is_intact = False
                safe_title_lower = safe_title.lower()
                for f in os.listdir(saved_path):
                    if f.endswith(('.part', '.ytdl', '.temp', '.tmp')): continue
                    f_stem, f_ext = os.path.splitext(f)
                    if f_ext.lower() in ['.mp4', '.mkv', '.webm', '.ts', '.mp3', '.m4a']:
                        if (v_id and v_id in f) or (f_stem.lower() == safe_title_lower) or (f_stem.lower() == safe_title_lower.replace(' ', '_')):
                            _f_path = os.path.join(saved_path, f)
                            if os.path.isfile(_f_path) and os.path.getsize(_f_path) > 1024 * 1024:
                                is_intact = True; break

                if is_intact:
                    if 'G_BG_DOWNLOAD_STATUS' in globals() and v_url in globals()['G_BG_DOWNLOAD_STATUS']:
                        globals()['G_BG_DOWNLOAD_STATUS'][v_url].update({'pct': '100%', 'status': 'finished'})
                    if not is_bg_mode:
                        with _slot_lock:
                            _progress_slots[my_slot] = (v_title, f"⏭️  {C.GREEN}{v_title[:60]}...{R} {C.DIM}이미 존재함 (스킵!){R} 🐾")
                            _render_dashboard_slots()
                    return True

                for _check_dir in [saved_path, work_path]:
                    if os.path.exists(_check_dir):
                        for _cf in os.listdir(_check_dir):
                            if _cf.endswith('.part'):
                                if (v_id and v_id in _cf) or (safe_title_lower in _cf.lower()):
                                    try: safe_remove_file(os.path.join(_check_dir, _cf))
                                    except Exception: pass

                def _single_progress_hook(d):
                    try:
                        pct = re.sub(r'\x1b[^m]*m', '', d.get('_percent_str', '?').strip())
                        speed = d.get('_speed_str', '').strip()
                        eta = d.get('_eta_str', '').strip()
                        st = d.get('status', 'downloading')
                        if 'G_BG_DOWNLOAD_STATUS' in globals() and v_url in globals()['G_BG_DOWNLOAD_STATUS']:
                            globals()['G_BG_DOWNLOAD_STATUS'][v_url].update({
                                'pct': pct,
                                'speed': speed,
                                'eta': eta,
                                'status': st
                            })
                        if not is_bg_mode:
                            if st == 'downloading':
                                with _slot_lock:
                                    _progress_slots[my_slot] = (v_title, f"📥 {C.SKY}{v_title[:60]}...{R} {C.BOLD}{pct:>7}{R} {C.DIM}({speed}, ETA: {eta}){R}")
                                    _render_dashboard_slots(force=False)
                            elif st == 'finished':
                                with _slot_lock:
                                    _progress_slots[my_slot] = (v_title, f"🔄 {C.SKY}{v_title[:60]}...{R} {C.BOLD}포스트 프로세싱(합체/변환) 중...{R} 🎬")
                                    _render_dashboard_slots(force=True)
                    except Exception: pass

                class SubLogger(SilentLogger):
                    def debug(self, msg):
                        try:
                            if not is_bg_mode:
                                msg_l = str(msg).lower()
                                if any(k in msg_l for k in ['subtitle', 'cc', 'embed', 'extract', 'convert']):
                                    with _slot_lock:
                                        clean_msg = re.sub(r'\[.*?\]', '', str(msg)).strip()
                                        _progress_slots[my_slot] = (v_title, f"🎯 {C.SKY}{v_title[:60]}...{R} {C.DIM}{clean_msg[:40]}...{R} 🏹")
                                        _render_dashboard_slots(force=False)
                        except Exception: pass
                    def warning(self, msg):
                        try: super().warning(msg)
                        except Exception: pass
                    def error(self, msg):
                        try:
                            _log_to_file(f"❌ [yt-dlp Engine Error] {msg}")
                            super().error(msg)
                        except Exception: pass

                cur_ydl_opts['logger'] = SubLogger()
                cur_ydl_opts['progress_hooks'] = cur_ydl_opts.get('progress_hooks', []) + [_single_progress_hook]

                for attempt in range(1, 4):
                    try:
                        if attempt > 1 and not is_bg_mode:
                            with _slot_lock:
                                _progress_slots[my_slot] = (v_title, f"🔄 {C.YELLOW}{v_title[:60]}...{R} {C.BOLD}재시도 중 ({attempt}/3)...{R} ⚡")
                                _render_dashboard_slots(force=True)

                        with yt_dlp.YoutubeDL(cur_ydl_opts) as ydl:
                            ret_code = ydl.download([v_url])
                            if ret_code != 0:
                                raise RuntimeError(f"yt-dlp download returned error code: {ret_code}")

                        found_completed = False
                        cand_info = collector.finished_infos.get(v_id) if v_id else None
                        target_wf_path = None
                        if cand_info and cand_info.get('_filename') and os.path.exists(cand_info.get('_filename')):
                            target_wf_path = cand_info.get('_filename')
                        else:
                            for wf in os.listdir(work_path):
                                if wf.endswith(('.part', '.ytdl', '.temp', '.tmp', '.lock')): continue
                                if (v_id and v_id in wf) or (safe_title_lower and (safe_title_lower in wf.lower() or safe_title_lower.replace(' ', '_') in wf.lower())):
                                    _c_path = os.path.join(work_path, wf)
                                    if os.path.isfile(_c_path) and os.path.getsize(_c_path) > 1024 * 1024:
                                        target_wf_path = _c_path
                                        break

                        if target_wf_path and os.path.isfile(target_wf_path):
                            try:
                                _inject_youtube_chapters_if_needed(target_wf_path, info_dict=cand_info, video_url=v_url)
                            except Exception as _che:
                                _log_to_file(f"⚠️ [Single Task Chapter Inject Error] {_che}")
                            found_completed = True
                        else:
                            for wf in os.listdir(work_path):
                                if wf.endswith(('.part', '.ytdl', '.temp', '.tmp', '.lock')): continue
                                wf_path = os.path.join(work_path, wf)
                                if os.path.isfile(wf_path) and os.path.getsize(wf_path) > 1024 * 1024:
                                    try:
                                        _inject_youtube_chapters_if_needed(wf_path, info_dict=cand_info, video_url=v_url)
                                    except Exception: pass
                                    target_wf_path = wf_path
                                    found_completed = True; break

                        # [V178.9] 개별 영상 완료 즉시 본 폴더로 이동 & 히스토리 등록 (1개 대용량 작업 지연 시 볼모 방지!) 🚀🛡️
                        if target_wf_path and os.path.isfile(target_wf_path):
                            try:
                                _f_name = os.path.basename(target_wf_path)
                                _target_fname = _f_name.replace(' ', '_')
                                _final_target = os.path.normpath(os.path.join(saved_path, _target_fname))
                                if os.path.exists(_final_target):
                                    safe_remove_file(_final_target)
                                shutil.move(target_wf_path, _final_target)
                                _abs_moved = os.path.abspath(_final_target)
                                with _yt_lock:
                                    if _abs_moved not in all_downloaded_files:
                                        all_downloaded_files.append(_abs_moved)
                                # 관련 부속 파일(자막 등)도 동반 이동
                                _b_stem = os.path.splitext(_f_name)[0]
                                for _exf in os.listdir(work_path):
                                    if _exf.startswith(_b_stem) and not _exf.endswith(('.part', '.ytdl', '.lock', '.tmp')):
                                        try:
                                            _src_ex = os.path.join(work_path, _exf)
                                            _dst_ex = os.path.join(saved_path, _exf.replace(' ', '_'))
                                            if os.path.exists(_dst_ex): safe_remove_file(_dst_ex)
                                            shutil.move(_src_ex, _dst_ex)
                                        except Exception: pass
                                if v_id:
                                    save_video_history(v_id)
                                _log_to_file(f"⚡ [Immediate Evacuation] '{_target_fname}' 본 폴더 즉시 이동 및 히스토리 등록 완료!")
                            except Exception as _mve:
                                _log_to_file(f"⚠️ [Single Task Immediate Move Error] {_mve}")

                        if not found_completed:
                            for sf in os.listdir(saved_path):
                                if sf.endswith(('.part', '.ytdl', '.temp', '.tmp', '.lock')): continue
                                sf_path = os.path.join(saved_path, sf)
                                if os.path.isfile(sf_path) and os.path.getsize(sf_path) > 1024 * 1024:
                                    if (v_id and v_id in sf) or (safe_title_lower in sf.lower()):
                                        found_completed = True
                                        if v_id: save_video_history(v_id)
                                        break

                        if not found_completed:
                            raise RuntimeError("Completed media file not found in work directory")

                        if 'G_BG_DOWNLOAD_STATUS' in globals() and v_url in globals()['G_BG_DOWNLOAD_STATUS']:
                            globals()['G_BG_DOWNLOAD_STATUS'][v_url].update({'pct': '100%', 'status': 'finished'})

                        if not is_bg_mode:
                            with _slot_lock:
                                _progress_slots[my_slot] = (v_title, f"✅ {C.GREEN}{v_title[:60]}...{R} {C.BOLD}다운로드 완료!{R} ✨")
                                _render_dashboard_slots(force=True)
                        return True

                    except Exception as e:
                        _log_to_file(f"⚠️ [Download Attempt {attempt}/3 Failed] {v_title}: {e}")
                        # [V178.11] 용량 부족(Errno 28)은 재시도해도 100% 실패 → 즉시 중단하고 장부 오염 방지! 🛑
                        _e_s = str(e)
                        if 'No space left on device' in _e_s or '[Errno 28]' in _e_s or 'ENOSPC' in _e_s:
                            _log_to_file(f"🛑 [ENOSPC-ABORT] '{v_title}' 디스크 용량 부족(Errno 28) → futile 재시도 중단! "
                                         f"(잔재 .temp/.fXXX 결손파일은 다음 스캔에서 자동 폐기·재다운로드됨) 🛡️")
                            if 'G_BG_DOWNLOAD_STATUS' in globals() and v_url in globals()['G_BG_DOWNLOAD_STATUS']:
                                globals()['G_BG_DOWNLOAD_STATUS'][v_url]['status'] = 'failed'
                            return False
                        if attempt < 3:
                            time.sleep(3 * attempt)
                            continue
                        else:
                            e_str = str(e)
                            if any(kw in e_str for kw in ["confirm your age", "Inappropriate for some users", "Sign in to confirm your age"]):
                                if not is_bg_mode:
                                    with _slot_lock:
                                        _progress_slots[my_slot] = (v_title, f"🔞 {C.RED}{v_title[:60]}...{R} {C.BOLD}연령 제한 스킵{R} 🐾")
                                        _render_dashboard_slots(force=True)
                                if v_id: save_video_history(v_id)
                                return True
                            if 'G_BG_DOWNLOAD_STATUS' in globals() and v_url in globals()['G_BG_DOWNLOAD_STATUS']:
                                globals()['G_BG_DOWNLOAD_STATUS'][v_url]['status'] = 'failed'
                            if not is_bg_mode:
                                with _slot_lock:
                                    _progress_slots[my_slot] = (v_title, f"❌ {C.RED}{v_title[:60]}...{R} {C.BOLD}다운로드 실패{R} 😿")
                                    _render_dashboard_slots(force=True)
                            return False
            finally:
                with _available_slots_lock:
                    _available_slots.append(my_slot)
                with completed_lock:
                    nonlocal completed_count
                    completed_count += 1
                if not is_bg_mode:
                    with _slot_lock:
                        _render_dashboard_slots(force=True)

        try:
            globals()['_is_youtube_downloading'] = True
            with ThreadPoolExecutor(max_workers=4) as executor:
                task_args = [(i, u, t, current_history) for i, (u, t) in enumerate(zip(urls, video_titles))]
                results = list(executor.map(_single_download_task, task_args))
        finally:
            globals()['_is_youtube_downloading'] = False

        if not is_bg_mode:
            print(f"\r\n 💤 {ctext('시스템이 파일을 정리할 시간을 줍니다 (2초 대기)...', C.DIM)}")
        time.sleep(2.0)

        # 🍳 [V177.4] .f248.webm 등 미결합 스트림 파일 사전 자동 결합 및 자가 치유 🎬🔊
        try:
            merged_repaired = _repair_and_merge_unmerged_streams(work_path, saved_path)
            for m_file in merged_repaired:
                abs_m = os.path.abspath(m_file)
                if abs_m not in all_downloaded_files:
                    all_downloaded_files.append(abs_m)
        except Exception as _m_err:
            _log_to_file(f"⚠️ [Post-Download Stream Repair Error] {_m_err}")

        # work_path -> saved_path 이동
        if os.path.exists(work_path):
            # [V178.11] '-N' 접미사(.f234-1.mp4)와 .temp.mp4 결손 잔재까지 라이브러리 이동 차단! 🛡️
            fmt_pat = re.compile(r'(\.f\d+(-\d+)?\.(webm|mp4|mkv|m4a)|\.temp(-\d+)?\.(webm|mp4|mkv|m4a))$', re.IGNORECASE)
            for f_name in os.listdir(work_path):
                if f_name.endswith((".lock", ".part", ".ytdl", ".temp", ".tmp", ".aria2")): continue
                # 🚫 미결합 분할 스트림(.f248.webm 등) 단독 이동 차단
                if fmt_pat.search(f_name):
                    continue
                raw_f = os.path.join(work_path, f_name)
                if not os.path.isfile(raw_f) or os.path.getsize(raw_f) < 1024: continue
                target_filename = f_name.replace(' ', '_')
                target_path = os.path.normpath(os.path.join(saved_path, target_filename))
                try:
                    cand_info = collector.finished_infos.get(raw_f)
                    cand_url = None
                    if not cand_info:
                        for _k, _v in collector.finished_infos.items():
                            if isinstance(_k, str) and (_k in f_name or (len(_k) == 11 and _k in f_name)):
                                cand_info = _v; break
                    if cand_info:
                        cand_url = cand_info.get('webpage_url') or cand_info.get('original_url')
                    _inject_youtube_chapters_if_needed(raw_f, info_dict=cand_info, video_url=cand_url)
                except Exception as _che:
                    _log_to_file(f"⚠️ [WorkPath Chapter Check Error] {_che}")
                try:
                    if os.path.exists(target_path): safe_remove_file(target_path)
                    shutil.move(raw_f, target_path)
                    abs_target = os.path.abspath(target_path)
                    if abs_target not in all_downloaded_files:
                        all_downloaded_files.append(abs_target)
                except Exception as e:
                    _log_to_file(f"⚠️ [File Move Error] {e}")

        # 히스토리 기록 (기본 장부 및 스텔스/채널 장부 동시 반영)
        if urls and 'results' in locals():
            for (u, t), is_success in zip(zip(urls, video_titles), results):
                if is_success:
                    v_id_match = re.search(r'(?:v=|\/)([0-9A-Za-z_-]{11}).*', u)
                    if v_id_match:
                        _vid = v_id_match.group(1)
                        save_video_history(_vid)
                        _log_to_file(f"💾 [CORE-HISTORY] 다운로드 완료 장부 저장: {_vid} ({t[:30]})")

        safe_remove_file(work_path, use_trash=True)
        _cleanup_orphan_lock_files(saved_path)

        # 미완료 항목 2차 재시도
        missing_items = []
        for i, (u, t) in enumerate(zip(urls, video_titles)):
            if 'results' in locals() and i < len(results) and results[i]:
                continue
            v_id = None
            v_id_match = re.search(r'(?:v=|\/)([0-9A-Za-z_-]{11}).*', u)
            if v_id_match: v_id = v_id_match.group(1)
            _clean_t = re.sub(r'\x1b[^m]*m', '', t)
            _pure_t = re.sub(r'^\[\s*[\d\-:]+\s*\]\s*', '', _clean_t)
            _pure_t = re.sub(r'^\[.*?\]\s*', '', _pure_t).strip()
            safe_t = "".join([c for c in _pure_t if c not in r'\/:*?"<>|']).strip().lower()
            is_exist = False
            for f in os.listdir(saved_path):
                if f.endswith(('.part', '.ytdl', '.temp', '.tmp')): continue
                f_lower = f.lower()
                # [V178.11] 미결합 분할 스트림·결손 잔재는 '완료 파일' 후보에서 영구 제외! 🛡️
                if re.search(r'(\.f\d+(-\d+)?\.(webm|mp4|mkv|m4a)|\.temp(-\d+)?\.(webm|mp4|mkv|m4a))$', f, re.IGNORECASE):
                    continue
                if (v_id and v_id in f) or (safe_t and (safe_t in f_lower or safe_t.replace(' ', '_') in f_lower)):
                    fp = os.path.join(saved_path, f)
                    # [V178.11] '크기>1MB' 만 믿으면 .temp.mp4(moov 없음)·잘린 .fXXX.mp4 같은 쓰레기가
                    #            '이미 있으니까 성공'으로 오인돼 재다운로드를 영구 차단한다 → ffprobe 무결성 검증 필수! 🧪🛡️
                    if os.path.isfile(fp) and os.path.getsize(fp) > 1024 * 1024:
                        if not _is_valid_media_file(fp):
                            _log_to_file(f"🗑️ [Stale-Residue] 결손/미결합 잔재로 판정 → 성공으로 치지 않고 재다운로드 대상으로 보냅니다: {f}")
                            continue
                        is_exist = True
                        abs_fp = os.path.abspath(fp)
                        if abs_fp not in all_downloaded_files:
                            all_downloaded_files.append(abs_fp)
                        break
            if not is_exist:
                missing_items.append((i, u, t))

        if missing_items:
            retry_workers = min(2, len(missing_items))
            retry_fragments = 6 if len(missing_items) <= 2 else 4
            ydl_opts['concurrent_fragments'] = retry_fragments
            ydl_opts['concurrent_fragment_downloads'] = retry_fragments
            _log_to_file(f"⚠️ [유튜브 다운로드] {len(missing_items)}개 미완료 영상 감지 -> 2차 자동 재시도 실행")
            if not is_bg_mode:
                print(f"\r\n 🔄 {ctext(f'미완료된 {len(missing_items)}개 영상을 안정 모드로 자동 재시도합니다... 🐾', C.YELLOW, C.BOLD)}")
            time.sleep(2.0)
            if not os.path.exists(work_path):
                try: os.makedirs(work_path, exist_ok=True)
                except Exception: pass
            try:
                globals()['_is_youtube_downloading'] = True
                with ThreadPoolExecutor(max_workers=retry_workers) as executor:
                    task_args = [(i, u, t, current_history) for (i, u, t) in missing_items]
                    retry_results = list(executor.map(_single_download_task, task_args))
            except Exception as _retry_err:
                _log_to_file(f"⚠️ [유튜브 재시도 예외] {_retry_err}")
            finally:
                globals()['_is_youtube_downloading'] = False

            time.sleep(2.0)
            if os.path.exists(work_path):
                for f_name in os.listdir(work_path):
                    if f_name.endswith((".lock", ".part", ".ytdl", ".temp", ".tmp", ".aria2")): continue
                    raw_f = os.path.join(work_path, f_name)
                    if not os.path.isfile(raw_f) or os.path.getsize(raw_f) < 1024: continue
                    # [V178.11] 미결합 분할 스트림(.f248.webm)·결손 잔재(.temp.mp4)를 라이브러리로 옮기지 않는다! 🛡️
                    if re.search(r'(\.f\d+(-\d+)?\.(webm|mp4|mkv|m4a)|\.temp(-\d+)?\.(webm|mp4|mkv|m4a))$', f_name, re.IGNORECASE):
                        continue
                    target_filename = f_name.replace(' ', '_')
                    target_path = os.path.normpath(os.path.join(saved_path, target_filename))
                    try:
                        cand_info = collector.finished_infos.get(raw_f)
                        cand_url = None
                        if not cand_info:
                            for _k, _v in collector.finished_infos.items():
                                if isinstance(_k, str) and (_k in f_name or (len(_k) == 11 and _k in f_name)):
                                    cand_info = _v; break
                        if cand_info:
                            cand_url = cand_info.get('webpage_url') or cand_info.get('original_url')
                        _inject_youtube_chapters_if_needed(raw_f, info_dict=cand_info, video_url=cand_url)
                    except Exception as _che:
                        _log_to_file(f"⚠️ [Retry Chapter Check Error] {_che}")
                    try:
                        if os.path.exists(target_path): safe_remove_file(target_path)
                        shutil.move(raw_f, target_path)
                        abs_target = os.path.abspath(target_path)
                        if abs_target not in all_downloaded_files:
                            all_downloaded_files.append(abs_target)
                    except Exception as e:
                        _log_to_file(f"⚠️ [Retry File Move Error] {e}")

            for u, t in zip(urls, video_titles):
                _clean_t = re.sub(r'\x1b[^m]*m', '', t)
                _pure_t = re.sub(r'^\[\s*[\d\-:]+\s*\]\s*', '', _clean_t)
                _pure_t = re.sub(r'^\[.*?\]\s*', '', _pure_t).strip()
                safe_t = "".join([c for c in _pure_t if c not in r'\/:*?"<>|']).strip().lower()
                if safe_t:
                    for f in os.listdir(saved_path):
                        if f.endswith(('.part', '.ytdl', '.temp', '.tmp')): continue
                        if safe_t in f.lower() and any(f.lower().endswith(ext) for ext in ['.mp4', '.mkv', '.webm', '.ts', '.mp3', '.m4a']):
                            abs_f = os.path.abspath(os.path.join(saved_path, f))
                            if abs_f not in all_downloaded_files:
                                all_downloaded_files.append(abs_f)

        # G_BG_DOWNLOAD_STATUS 완료 상태 갱신 (완료 후 재생 및 현황 확인을 위해 보존! 🎬✨)
        if 'G_BG_DOWNLOAD_STATUS' in globals():
            for idx_u, u in enumerate(urls):
                if u in globals()['G_BG_DOWNLOAD_STATUS']:
                    fp = all_downloaded_files[idx_u] if (all_downloaded_files and idx_u < len(all_downloaded_files)) else (all_downloaded_files[0] if all_downloaded_files else "")
                    fn_title = os.path.splitext(os.path.basename(fp))[0] if fp else ""
                    curr_title = globals()['G_BG_DOWNLOAD_STATUS'][u].get('title', '')
                    if not curr_title or curr_title.startswith('http'):
                        final_t = fn_title or curr_title or u
                    else:
                        final_t = curr_title or fn_title or u
                    globals()['G_BG_DOWNLOAD_STATUS'][u].update({
                        'title': final_t,
                        'pct': '100%',
                        'status': 'finished',
                        'speed': '완료',
                        'eta': '00:00',
                        'file_path': fp,
                        'filename': os.path.basename(fp) if fp else ""
                    })

        try:
            _schedule_ytdl_cache_cleanup(settings)
        except Exception: pass

        if all_downloaded_files:
            _append_to_temp_playlist(all_downloaded_files)
            # [신규] 유튜브 다운로드 지정 폴더가 포함된 플레이리스트 자동 1회 갱신 🔄✨
            _should_pl_refresh = True
            if settings and hasattr(settings, 'data') and isinstance(settings.data, dict):
                _should_pl_refresh = settings.data.get('auto_playlist_refresh', True)
            elif isinstance(settings, dict):
                _should_pl_refresh = settings.get('auto_playlist_refresh', True)
            if _should_pl_refresh:
                try:
                    _auto_refresh_playlists_for_path(saved_path, settings, silent=is_bg_mode)
                except Exception as _pl_err:
                    _log_to_file(f"⚠️ [Auto Playlist Refresh Error] {_pl_err}")
            tg_mode = 'full'
            if settings and hasattr(settings, 'data'):
                tg_mode = settings.data.get('s_m_tg_msg_mode', 'full')

            if tg_mode != 'off':
                msg = "📥 <b>유튜브 영상 다운로드 완료!</b>\r\n\r\n"
                msg += f"📦 <b>다운로드 개수:</b> {len(all_downloaded_files)}개\r\n"
                if tg_mode == 'full':
                    msg += f"📂 <b>최근 파일:</b> {os.path.basename(all_downloaded_files[-1])}"
                watch_buttons = []
                registered_sids = {}
                for _fp in all_downloaded_files[-8:]:
                    registered_sids[_fp] = _register_file_for_telegram(_fp)
                if len(all_downloaded_files) >= 2:
                    all_sids = [registered_sids[_fp] for _fp in all_downloaded_files[-8:] if _fp in registered_sids]
                    _sids_str = ",".join(all_sids)
                    watch_buttons.append([{"text": "💻 PC 전체 재생 (팟플) 🚀", "callback_data": f"play_local:{_sids_str}"}])
                for dl_file in all_downloaded_files[-5:]:
                    if dl_file not in registered_sids:
                        registered_sids[dl_file] = _register_file_for_telegram(dl_file)
                    short_id = registered_sids[dl_file]
                    _fn_s = os.path.basename(dl_file)[:24]
                    watch_buttons.append([
                        {"text": f"💻 PC : {_fn_s}", "callback_data": f"play_local:{short_id}"},
                        {"text": "📱 모바일", "callback_data": f"watch:{short_id}"}
                    ])
                webdav_url = _build_webdav_folder_url("temp", include_auth=True)
                watch_buttons.append([{"text": "📂 다운로드 폴더 열기 (WebDAV)", "url": webdav_url}])
                if tg_mode != 'off':
                    send_telegram_notification(msg, buttons=watch_buttons, chat_id=chat_id)
            globals()['_global_force_explorer_refresh'] = True
        else:
            if not is_bg_mode or chat_id:
                send_telegram_notification("📥 <b>유튜브 다운로드 결과가 없어멍...!</b> ❌\r\n(네트워크 오류나 중복 가능성 확인 부탁해냥!)", chat_id=chat_id)

        # [Auto Cart] 다운로드 완료된 파일 장바구니 자동 담기 연동 🛒✨
        try:
            if all_downloaded_files:
                pending_cart_urls = globals().get('_G_PENDING_AUTO_CART_URLS', set())
                cfg_dict = settings.data.get('watch_playlist_configs', {}) if (settings and hasattr(settings, 'data')) else {}
                auto_cart_channels = {u for u, c in cfg_dict.items() if isinstance(c, dict) and c.get('auto_cart')}

                matched_cart = False
                for u in urls:
                    if u in pending_cart_urls:
                        matched_cart = True
                        pending_cart_urls.discard(u)
                    elif not is_bg_mode and any(ch in u or u in ch for ch in auto_cart_channels):
                        matched_cart = True

                if matched_cart:
                    for df in all_downloaded_files:
                        if os.path.exists(df):
                            _add_to_shopping_cart(df, settings, reason="유튜브 다운로드 완료 (자동 담기 연동)")
        except Exception as _cart_ex:
            _log_to_file(f"⚠️ [Download Auto Cart Error] {_cart_ex}")

        # [V176.0] 백그라운드 모드인 경우 완료 메뉴를 완전히 건너뛰고 조용히 리턴! 🤫✨
        if is_bg_mode:
            _log_to_file(f"✅ [Bg-Youtube-Download] 총 {len(all_downloaded_files)}개 다운로드 완료 (조용히 종료냥! 🐾)")
            return all_downloaded_files, False

        # 포어그라운드 모드에서 완료 후 대화형 메뉴 처리
        if all_downloaded_files:
            if is_resume_subtitles:
                print(f"\r\n 🚀 {ctext('다운로드 완료! 번개처럼 자막 작업을 시작할게!', C.GREEN, C.BOLD)}")
                return all_downloaded_files, True

            while True:
                print_youtube_header(saved_path, len(all_downloaded_files), "FINAL: 작업 완료", settings_data=settings.data if hasattr(settings, 'data') else None)
                print(f" ✨ {ctext(f'{len(all_downloaded_files)}개의 파일을 다운받았어! 👍', C.GREEN, C.BOLD)}")
                print(f"{ctext('─' * 65, C.DIM)}\r\n")

                last_file = all_downloaded_files[-1] if all_downloaded_files else ""
                last_filename = os.path.basename(last_file)
                display_name = last_filename[:35] if len(last_filename) > 38 else last_filename

                if len(all_downloaded_files) > 1:
                    play_menu_text = f" ▶️ 방금 다운로드한 {len(all_downloaded_files)}개 파일 연속 재생 (플레이리스트)"
                else:
                    play_menu_text = f" ▶️ 마지막 다운로드 파일 재생 ({display_name})"

                show_trans_menu = False
                target_v_path = ""
                eng_stream_idx = -1
                if len(all_downloaded_files) == 1:
                    target_v_path = all_downloaded_files[0]
                    if os.path.exists(target_v_path):
                        _streams = get_internal_subtitle_streams(target_v_path, _get_ffprobe_bin())
                        for _s in _streams:
                            _tags = _s.get('tags', {})
                            _l = str(_tags.get('language', '')).lower()
                            _t = str(_tags.get('title', '')).lower()
                            if _l == 'eng' or 'english' in _t:
                                show_trans_menu = True
                                eng_stream_idx = _s.get('index')
                                break

                post_menu_map = [
                    {"label": play_menu_text, "key": "play"},
                    {"label": " 📁 다운로드 폴더 열기 (내용 확인)", "key": "open_folder"},
                    {"label": " 📂 TUI 탐색기로 열기 (내용 확인)", "key": "open_tui"},
                ]

                if show_trans_menu:
                    post_menu_map.append({"label": " 🌏 영어 내장 자막 발견! 한글로 번역할까냥?", "key": "trans_internal_sub"})

                post_menu_map.extend([
                    {"label": " 🎬 바로 자막 만들기 공정 시작하기", "key": "process_sub"},
                    {"label": " ⚡ 하던 대로 자막 만들기 (설정 스킵)", "key": "resume_sub"},
                    {"label": " 🗑️ 다 봤니? 영상과 자막 삭제 (휴지통)", "key": "delete_all"},
                    {"label": " 🏠 메인 메뉴로 돌아가기 (처음으로)", "key": "go_main"},
                    {"label": " 🚪 프로그램 종료", "key": "exit_app"}
                ])
                post_menu = [item["label"] for item in post_menu_map]

                p_idx, _, *_ = _interactive_menu("🏁 작업을 마쳤어! 이제 뭐 할까?", post_menu, timeout=0)
                if p_idx < 0:
                    print(f"\r\n 🏠 {ctext('메인 메뉴로 돌아갈게...', C.CYAN)}")
                    time.sleep(1)
                    return [], False
                if p_idx >= len(post_menu_map):
                    continue

                p_key = post_menu_map[p_idx]["key"]

                if p_key == "play":
                    target_to_play = ""
                    if all_downloaded_files:
                        if len(all_downloaded_files) > 1:
                            temp_dir = os.path.join(os.getcwd(), "temp")
                            os.makedirs(temp_dir, exist_ok=True)
                            m3u_path = os.path.join(temp_dir, "_temp_playlist.m3u8")
                            try:
                                with open(m3u_path, "w", encoding="utf-8", errors="ignore") as f:
                                    for fp in all_downloaded_files:
                                        if os.path.exists(fp):
                                            f.write(fp + "\r\n")
                                target_to_play = m3u_path
                            except:
                                target_to_play = last_file
                        else:
                            target_to_play = last_file

                    if target_to_play and os.path.exists(target_to_play):
                        print(f"\r\n 🎬 {ctext('영상을 재생합니다! 확인하는 동안 메뉴는 대기할게 친구야.', C.SKY)}")
                        open_path_resilient(target_to_play)
                    else:
                        print(f"\r\n ❌ {ctext('파일을 찾을 수 없어.', C.RED)}")
                    time.sleep(1)
                    continue

                elif p_key == "open_folder":
                    print(f"\r\n 📂 {ctext('다운로드 폴더를 열었어! 꽉 찬 화면으로 확인해봐 친구야.', C.CYAN)}")
                    open_path_resilient(saved_path)
                    time.sleep(1)
                    continue

                elif p_key == "open_tui":
                    remote_explorer(mode='file', title="TUI 탐색기 (다운로드)", initialdir=saved_path, settings_param=settings)
                    continue

                elif p_key == "process_sub":
                    return all_downloaded_files, False

                elif p_key == "resume_sub":
                    if not os.path.exists(SETTINGS_FILE) or "model_idx" not in getattr(settings, 'data', {}):
                        print(f"\r\n ⚠️ {C.RED}{C.BOLD}먼저 메인 메뉴에서 자막 설정을 한 번 완료해줘!{C.RESET}")
                        time.sleep(2)
                        continue
                    return all_downloaded_files, True

                elif p_key == "trans_internal_sub":
                    print(f"\r\n 🧠 {C.SKY}내장 자막을 추출해서 한글로 번역할게냥! 잠시만 기다려줘냥...{C.RESET}")
                    v_base = os.path.splitext(target_v_path)[0]
                    tmp_org = v_base + ".org.srt"
                    if extract_subtitle_stream(target_v_path, eng_stream_idx, tmp_org, _get_ffmpeg_bin()):
                        lang = _detect_subtitle_language(tmp_org)
                        source_path = f"{v_base}.{lang}.srt"
                        if not os.path.exists(source_path):
                            os.rename(tmp_org, source_path)
                            print(f" 📦 내장 자막을 {os.path.basename(source_path)}로 백업했어냥!")
                        else:
                            if os.path.exists(tmp_org): os.remove(tmp_org)
                            print(f" 📦 기존 백업({os.path.basename(source_path)})을 사용하여 번역할게냥!")

                        m_idx = settings.data.get("model_idx", 0) if hasattr(settings, 'data') else 0
                        models = ["auto", "gemini-3.1-pro-preview", "gemini-3-flash-preview", "gemini-3.1-flash-lite-preview", "gemini-2.5-pro", "gemini-3.5-flash", "gemini-2.5-flash-lite"]
                        m_name = models[m_idx] if m_idx < len(models) else "auto"
                        sel_chunk = _select_translation_chunk_interactive([source_path], settings)
                        if sel_chunk is None:
                            print(f"\r\n ⚠️ {C.YELLOW}취소되었다냥!{C.RESET}"); time.sleep(1); continue

                        out_path = v_base + ".srt"
                        if translate_srt_with_agy_cli(source_path, out_path=out_path, model=m_name, chunk_size=sel_chunk):
                            print(f"\r\n ✅ {C.GREEN}번역 완료! 자막 파일이 생성되었어냥: {os.path.basename(out_path)}{C.RESET}")
                        else:
                            print(f"\r\n ❌ {C.RED}자막 번역에 실패했어냥..{C.RESET}")
                    else:
                        print(f"\r\n ❌ {C.RED}내장 자막을 추출하지 못했어냥.. (FFmpeg 확인 필요){C.RESET}")
                    time.sleep(2)
                    continue

                elif p_key == "delete_all":
                    print(f"\r\n 🗑️ {C.BOLD}{C.ORANGE}삭제 대상 파일을 확인해줘!{C.RESET}")
                    print(f" {C.DIM}---------------------------------------------------------{C.RESET}")
                    target_files = set()
                    for f in all_downloaded_files:
                        if os.path.exists(f):
                            target_files.add(os.path.abspath(f))
                        sp = os.path.splitext(f)[0] + ".srt"
                        if os.path.exists(sp):
                            target_files.add(os.path.abspath(sp))

                    if not target_files:
                        print(f" 🔍 {C.YELLOW}삭제할 파일을 찾을 수 없어!{C.RESET}")
                        prompt_input(f" 👉 {C.GOLD}Enter를 누르면 메뉴로 돌아갑니다...{C.RESET} ")
                        continue

                    for f in sorted(list(target_files)):
                        print(f"   📄 {os.path.basename(f)}")
                    print(f" {C.DIM}---------------------------------------------------------{C.RESET}")
                    print(f" 💡 {C.BOLD}{C.GREEN}[Enter]{C.RESET}: 휴지통으로 이동  /  {C.BOLD}{C.RED}[c]{C.RESET}: 취소 후 메뉴로")

                    confirm_options = ["✅ 삭제 진행", "❌ 취소 (메뉴로 돌아가기)"]
                    confirm_idx, _, *_ = _interactive_menu("정말 이 파일들을 휴지통으로 보낼까?", confirm_options, cols=1)
                    if confirm_idx < 0: break
                    if confirm_idx != 0:
                        print(f" ↩️ {C.YELLOW}취소했어!{C.RESET}"); time.sleep(1)
                        continue

                    print(f"\r\n 🚮 {ctext('파일들을 휴지통으로 안전하게 보낼게!', C.ORANGE)}")
                    del_count = 0
                    error_occurred = False
                    for f_path in sorted(list(target_files)):
                        try:
                            safe_remove_file(f_path)
                            del_count += 1
                        except Exception as e:
                            print(f"   ⚠️ {C.RED}삭제 중 오류 발생:{C.RESET} {os.path.basename(f_path)}")
                            print(f"      ㄴ 이유: {e}")
                            error_occurred = True

                    if error_occurred:
                        print(f"\r\n ❌ {C.BOLD}{C.RED}일부 파일을 삭제하지 못했어!{C.RESET}")
                        prompt_input(f" 👉 {C.GOLD}Enter를 눌러 확인...{C.RESET} ")
                    else:
                        print(f" ✨ {ctext(f'총 {del_count}개의 파일을 휴지통으로 보냈어!', C.GREEN)}")
                        time.sleep(1.5)
                    return [], False

                elif p_key == "go_main":
                    print(f"\r\n 🏠 {ctext('메인 메뉴로 돌아갈게...', C.CYAN)}")
                    time.sleep(1)
                    return [], False

                elif p_key == "exit_app":
                    play_success_sound()
                    _exit_app_safely(settings)
        else:
            print(f"\r\n⚠️ {ctext('다운로드된 파일을 찾지 못했어. 경로를 확인해줘!', C.RED)}")
            return [], False

    except Exception as e:
        _log_to_file(f"❌ [Youtube Download Process Error] {e}")
        if not is_bg_mode:
            error_msg = f"😱 <b>친구야, 다운로드 중에 문제가 생겼어!</b>\r\n\r\n❌ <b>에러 내용:</b> {e}"
            print(f"\r\n\r\n{C.RED}{'=' * 65}")
            print(f" 😱 {C.BOLD}친구야, 다운로드 중에 문제가 생겼어!{C.RESET}")
            print(f" ❌ {ctext('에러 내용:', C.YELLOW)} {e}")
            print(f"{C.RED}{'=' * 65}{C.RESET}")
            if chat_id:
                send_telegram_notification(error_msg, category='subtitle', chat_id=chat_id)
            prompt_input(f"\r\n 👉 {ctext('Enter를 누르면 메인 메뉴로 돌아갈게...', C.SKY)} ")
        if 'work_path' in locals():
            safe_remove_file(work_path, use_trash=True)
        return [], False


