                    # 검색어이거나, 혹은 채널/플레이리스트 주소인 경우 인터랙티브 모드 진입냥!
                    if u_input and ((not is_url and not u_input.isdigit()) or (is_url and is_list_or_channel and ('youtube.com' in u_input or 'youtu.be' in u_input))):
                        res_dict = _handle_youtube_search_interactive(u_input, settings)
