# [V142.29] 입력 감지 몽키 패치: OS 유휴 시간 대신 '우리 프로그램' 내의 실제 입력만 추적냥! 🐾🛡️
# [TAG: #@_patch_input_trackers]
def _patch_input_trackers():
    import msvcrt
    global _G_LAST_INPUT_TIME

    # [TAG: #@_update_time]
    def _update_time():
        global _G_LAST_INPUT_TIME
        _G_LAST_INPUT_TIME = __import__("time").time()
        if globals().get("_G_SLEEP_MODE", False):
            globals()["_G_SLEEP_MODE"] = False; globals()["_global_menu_redraw_flag"] = True

    # [V176.0] kbhit 패치: 가상 키 버퍼에 키가 있으면 즉시 True 반환! 🔍✨
    orig_kbhit = getattr(msvcrt, '_orig_kbhit', msvcrt.kbhit)
    msvcrt._orig_kbhit = orig_kbhit
    def patched_kbhit():
        if globals().get('_has_virtual_key', lambda: False)():
            return True
        return orig_kbhit()
    msvcrt.kbhit = patched_kbhit

    # [TAG: #@patched_getch]
    orig_getch = getattr(msvcrt, '_orig_getch', msvcrt.getch)
    msvcrt._orig_getch = orig_getch
    def patched_getch():
        _update_time()
        vk = globals().get('_pop_virtual_key', lambda: None)()
        if vk is not None:
            if isinstance(vk, bytes):
                return vk
            return vk.encode('utf-8', errors='ignore')
        return orig_getch()
    msvcrt.getch = patched_getch

    orig_getwch = getattr(msvcrt, '_orig_getwch', msvcrt.getwch)
    msvcrt._orig_getwch = orig_getwch
    # [TAG: #@patched_getwch]
    def patched_getwch():
        _update_time()
        vk = globals().get('_pop_virtual_key', lambda: None)()
        if vk is not None:
            if isinstance(vk, bytes):
                return vk.decode('utf-8', errors='ignore')
            return str(vk)
        return orig_getwch()
    msvcrt.getwch = patched_getwch

_patch_input_trackers()
_G_IS_TRANSLATING = False      # [V136.0] 현재 AI 번역/자막 작업 중인지 여부 🧠🌎
