_last_bg_notification = ""  # [V90.5] 백그라운드 작업 알림 (메뉴 하단 고정용) ⚓✨
_last_bg_notification_time = 0.0 # [신규] 알림 발생 시점 기록 (자동 삭제 타이머용) 🕰️


# [TAG: #@bg_print]
def bg_print(*args, **kwargs):
    """[V90.5] 백그라운드 스레드에서 안전하게 알림을 보내고 하단에 표시되도록 유도함냥! 🐾✨
    순서: ① 알림 변수 업데이트 → ② redraw 플래그 ON → ③ 메뉴가 응답하도록 대기"""
    global _last_bg_notification, _last_bg_notification_time, _global_menu_redraw_flag

    # [V90.5] 직접 출력은 메뉴 판을 깨뜨리므로 자제하고 전역 변수에 위임 (줄바꿈 제거 루틴 포함 🧼)

    msg = " ".join(map(str, args)).strip().replace('\r\n', ' ')
    _last_bg_notification = msg
    _last_bg_notification_time = time.time() # [신규] 알림 발생 시점 업데이트 🕰️
    _global_menu_redraw_flag = True

# [NEW] 원격 사용자 입력 퓨처 (대화형 대기용) 💬
# [TAG: #@get_translation_mode]
def get_translation_mode(default_val, auto_skip: bool = False, manual_only: bool = False, v_paths: list = None, prefix: str = ""):
    """[V3.0] 자막 방식 선택 메뉴. 코랩 서버 상태 실시간 표시 지원 🟢/⚫"""
    # [신규] 코랩 서버 상태 확인 (필요 시)
    colab_status_str = ""
    try:
        _s = settings_ref
    except NameError:
        _s = settings
    saved_urls = _s.data.get("colab_urls", [])
    if saved_urls:
        primary_url = saved_urls[0]
        is_alive = _check_url_health(primary_url, timeout=2) # 메뉴 진입 시엔 빠르게 체크
        icon = f"{C.GREEN}🟢{C.RESET}" if is_alive else f"{C.RED}⚫{C.RESET}"
        colab_status_str = f"   (📡 {icon} {C.BOLD}Colab 상태{C.RESET}: {primary_url[:40]}...)"

    title = f"🚀 🎬 자막은 어떤 방식으로 만들어볼까? {colab_status_str}"
    # 맵핑 정의 (키와 표시 텍스트)
    mode_map = [
        (MODE_GEMINI_DIRECT_1STEP, f"{_fmt_num(1)}🚀 [Gemini API] Gemini 원스텝 │ 음성 ➡️ 한글 직행 (초고속)"),
        (MODE_GEMINI_DIRECT_2STEP, f"{_fmt_num(2)}🧠 [Gemini API] Gemini 투스텝 │ 원어 추출 ➡️ 한글 번역 (정밀)"),
        (MODE_WHISPER_GEMINI_PURE, f"{_fmt_num(3)}💻 [Gemini API] 로컬 Whisper (일반) + Gemini │ 내 PC 추출 ➡️ 한글 번역"),
        (MODE_WHISPER_GEMINI_BILINGUAL, f"{_fmt_num(4)}🎵 [Gemini API] 로컬 Whisper (합본) + Gemini │ 내 PC 추출 ➡️ 영+한 합본"),
        (MODE_COLAB_WHISPER_GEMINI, f"{_fmt_num(5)}☁️ [Gemini API] 코랩 Whisper + Gemini │ 코랩 추출 ➡️ 한글 번역"),
        (None, 구분선()),
        (MODE_AGY_ADAPTIVE_PIPELINE, f"{_fmt_num(6)}⚡ [초고속 마스터] agy 스마트 가변 멀티모달 원스텝 (무음 자동스킵 + 3채널 병렬) 🚀✨"),
        (MODE_AGY_AUDIO_ONESTEP, f"{_fmt_num(7)}🤖 [CLI 독립] agy CLI 멀티모달 원스탭 자막 만들기 (MP3 실시간) (agy 멀티모달) ✨"),
        (None, 구분선()),
        (MODE_COLAB_WHISPER_GEMMA_FREE, f"{_fmt_num(8)}🆓 [완전 무료] 코랩 Whisper + 코랩 Gemma3 │ 100% 무료 추출/번역"),
        (MODE_COLAB_WHISPER_GEMMA4_E4B, f"{_fmt_num(9)}🆓 [완전 무료] 코랩 Whisper 전사 + 코랩 Gemma4 e4b 번역 │ 100% 무료 추출/번역"),
        (MODE_COLAB_GEMMA4_E4B, f"{_fmt_num(10)}🐚 [코랩 무료] 코랩 Gemma 4 e4b 원스탭 자막 만들기 (MP3 실시간)"),
        (MODE_WHISPER_GEMMA_4B_LOCAL, f"{_fmt_num(11)}🈚 [로컬 무료] 로컬 Whisper + 로컬 Gemma 4b (오프라인)"),
        (MODE_WHISPER_GEMMA_STREAM_LOCAL, f"{_fmt_num(12)}🌊 [로컬 스트림] 로컬 Whisper + 로컬 Gemma (실시간/통짜)"),
        (MODE_EXTRACT_INTERNAL_SUBTITLES, f"{_fmt_num(13)}🎬 내장 자막 있는지 확인후 추출 (Internal Extraction)")
    ]


    # default_val이 인덱스(int)인 경우 키(str)로 변환 (하위 호환성)
    if isinstance(default_val, (int, float)):
        idx = safe_int(default_val, default=0)
        if 0 <= idx < len(mode_map):
            default_val = mode_map[idx][0]
        else:
            default_val = MODE_GEMINI_DIRECT_1STEP

    # 현재 옵션 리스트 생성
    options = [m[1] for m in mode_map]

    # [신규] 자막 요약 모드 추가 조건 체크
    found_sub_path = None
    if v_paths and len(v_paths) == 1:
        v_path = v_paths[0]
        base_name = os.path.splitext(v_path)[0]
        srt_path = base_name + ".srt"
        smi_path = base_name + ".smi"
        found_sub_path = srt_path if os.path.exists(srt_path) else (smi_path if os.path.exists(smi_path) else None)

        if found_sub_path:
            has_korean = False
            try:
                # [V17.0] read_subtitle_content 호출 시 예외 처리 강화
                with open(found_sub_path, 'r', encoding='utf-8', errors='ignore') as f:
                    content = f.read(5000) # 일부만 읽어서 체크
                if content: has_korean = bool(re.search('[가-힣]', content))
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

            # 요약 옵션들 추가 (인스턴스별 동격 키 할당)
            summary_options = [
                (MODE_SUBTITLE_SUMMARY, f"{_fmt_num(len(options)+1)}📝 {ctext('너 자막 있네? 자막과 제목으로 이 동영상 줄거리 알려줄게. (약 3~5줄)', C.GOLD)}"),
                (MODE_SUBTITLE_REMAKE_3MIN, f"{_fmt_num(len(options)+2)}⏱️ {ctext('너 자막 있네? 자막이 맘에 안들어? 지정 시점부터 지정 분량만큼 다시 만들어준다.', C.SKY)}"),
                (MODE_SUBTITLE_HIGHLIGHT, f"{_fmt_num(len(options)+3)}🎬 {ctext('너 자막 있네? 자막 맛집 4곳 뽑아서 하이라이트 만들어줄께.', C.SKY)}"),
                (MODE_SUBTITLE_EDIT_NOTEPAD, f"{_fmt_num(len(options)+4)}🗒️ {ctext('너 자막 있네? 메모장으로 자막 직접 수정 (수동 편집)', C.GREEN)}"),
                (MODE_SUBTITLE_REINDEX, f"{_fmt_num(len(options)+5)}🔢 {ctext('너 자막 있네? 수정된 자막 순번 다시 지정 (번호 정렬)', C.YELLOW)}"),
                (MODE_SUBTITLE_REFINE, f"{_fmt_num(len(options)+6)}✨ {ctext('너 자막 있네? AI가 전체 맥락을 파악해서 자막을 더 자연스럽게 깎아줄게! (퇴고)', C.MAGENTA)}"),
                (MODE_SUBTITLE_RESYNC_LYRICS, f"{_fmt_num(len(options)+7)}🎵 {ctext('너 자막 있네? 커버/뮤비 싱크가 안 맞아? Whisper 고속 전사로 기존 가사 1:1 싱크 교정! (칼싱크)', C.CYAN)}")
            ]
            if not has_korean:
                summary_options.insert(2, (MODE_SUBTITLE_TRANSLATION, f"{_fmt_num(len(options)+3)}🌎 {ctext('자막이 있네? 근데 한글이 없어! 한글 자막으로 번역해줄게.', C.SKY)}"))

            # 요약 옵션들 추가 전 구분선 삽입
            mode_map.append((None, 구분선()))

            for k, o in summary_options:
                mode_map.append((k, o))

    # [새로운 기능] 대상 영상 확인용 재생 버튼 맨 아래 추가! 🚀
    mode_map.append((None, 구분선()))
    valid_count = len([x for x in mode_map if x[0] is not None])
    mode_map.append(("MODE_PLAY_VIDEO", f"{_fmt_num(valid_count + 1)}▶️ 해당 파일 재생하기 (확인용)"))

    options = [m[1] for m in mode_map]

    options.append(" ❌ 이전 메뉴로 돌아가기")

    # default_val을 인덱스로 변환
    default_idx = 0
    for i, (k, _) in enumerate(mode_map):
        if k == default_val:
            default_idx = i
            break

    # [UX 개선] 자막 방식 선택 전에 어떤 영상인지 노출
    if v_paths:
        _print_video_file_info(v_paths, context_title="선택한 영상 정보")

    # [V146.5] 사용자 요청: 현재 불안정한 모델(11, 13번) 및 구분선 선택 제한 🛡️🚧
    skip_indices = [i for i, (k, _) in enumerate(mode_map) if k in [MODE_LOCAL_VAD_CHECK] or k is None]

    # [V91.5] 표준선 marker가 포함되어 있으므로 skip_indices 자동 계산 로직 적용
    idx, triggered, *_ = _interactive_menu(title, options, default_idx, auto_skip, timeout=0, skip_idx=skip_indices)

    if idx < 0: return "-1", "-1", False, None # [V77.5 Globalizer] Unpack 에러 방지용 튜플 반환 🛡️

    if idx == len(options) - 1: # 취소
        return "-1", "-1", False, None

    selected_key = mode_map[idx][0]

    # [V77.3] 코랩 기반 모드가 선택된 경우, 연결 방식을 미리 확인 🌐
    if selected_key in [MODE_COLAB_WHISPER_GEMINI, MODE_COLAB_WHISPER_GEMINI_CLI, MODE_COLAB_WHISPER_GEMMA_FREE, MODE_COLAB_WHISPER_GEMMA4_E4B]:
        _select_colab_connection_mode(settings_ref if 'settings_ref' in globals() else settings)

    return selected_key, selected_key, (manual_only or triggered), found_sub_path

