# [TAG: #@truncate_context]
def truncate_context(prompt, limit=8192):
    '''[V90.8] 대화 문맥이 너무 길어지면 오래된 순으로 정리하여 VRAM 부족을 방지합니다.'''
    if len(prompt) < limit: return prompt
    
    print(f" [Context] 문맥이 너무 길어 정리합니다... (현재 길이: {len(prompt)})")
    # Gemma/ChatML 구분자들
    sep_user = "<start_of_turn>user" if "<start_of_turn>" in prompt else "<|im_start|>user"
    sep_model = "<start_of_turn>model" if "<start_of_turn>" in prompt else "<|im_start|>assistant"
    
    # 1. 시스템 프롬프트(첫 번째 메시지) 보존 시도
    parts = prompt.split(sep_user)
    if len(parts) <= 2: return prompt[-limit:] # 너무 짧으면 그냥 뒤에서부터 자름
    
    system_part = parts[0]
    history_parts = parts[1:]
    
    # 2. 최신 메시지부터 역순으로 채워서 한도 내로 유지
    kept_history = []
    current_len = len(system_part)
    for p in reversed(history_parts):
        if current_len + len(p) + len(sep_user) < limit:
            kept_history.insert(0, p)
            current_len += len(p) + len(sep_user)
        else: break
        
    new_prompt = system_part + sep_user + sep_user.join(kept_history)
    print(f" [Context] 정리 완료 (새 길이: {len(new_prompt)})")
    return new_prompt

# [TAG: #@_async_cleanup]
def _async_cleanup():
    '''[V90.8] 응답 전송 후 조용히 메모리를 청소하는 백그라운드 작업'''
    time.sleep(0.5) # 응답이 완전히 나갈 때까지 잠시 대기
    try:
        if torch and hasattr(torch, 'cuda') and torch.cuda.is_available(): torch.cuda.empty_cache()
        gc.collect()
    except Exception as e:
        colab_log(f"⚠️ [Silent Exception] {e}")

