# --- [V78.2] 무적의 파이썬: 리버스 브릿지 터널링 (Client Side - 정밀 진단) 🛡️ ---
# [TAG: #@start_reverse_bridge_client]
def start_reverse_bridge_client(target_ip, target_port=G_BRIDGE_PORT, local_port=G_FLASK_PORT):
    import socket, threading, time, os, subprocess
    # [V80.6] 초인종(노크) 기능 분리 🔔
    # [TAG: #@send_knock]
    def send_knock():
        print(f" 🔔 저기요~ 초인종 누릅니다냥! (주소: {target_ip}:{target_port})")
        import requests
        try:
            # Direct 모드에서는 주소가 로컬 5000번이므로 고정값 전달
            payload = {'url': f'http://127.0.0.1:{local_port}'}
            resp = requests.post(f"http://{target_ip}:{target_port}/cat/update_url", json=payload, timeout=5)
            if resp.status_code == 200:
                print(" ✅ 초인종 소리가 안방까지 들린 것 같아냥! 🐈✨")
                return True
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")
        return False

    # 1. 사전 진단 및 첫 번째 노크
    connected = False
    try:
        test_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        test_sock.settimeout(5.0)
        test_sock.connect((target_ip, target_port))
        test_sock.close()
        print(f"✅ [진단 완료] 우리집 PC와 통신이 가능합니다! (Port {target_port} OPEN) ✨")
        
        # 첫 번째 초인종 누르기
        send_knock()
        connected = True
    except Exception as e:
        print(f"❌ [진단 실패] 우리집 PC에 접속할 수 없다냥! (사유: {e})")
        
        # 2단계: ICMP Ping 테스트 (네트워크 경로 확인)
        print(f"🔍 [추가 진단] 인터넷 자체가 통하는지 핑(Ping)을 날려볼게냥...")
        try:
            # os.system을 사용하여 좀 더 가볍게 체크 (방출된 출력은 무시)
            ret = os.system(f"ping -c 1 -W 2 {target_ip} > /dev/null 2>&1")
            if ret == 0:
                print(f"✅ [Ping OK] 우리집 집주소는 잘 찾아왔는데, 문(5002)만 잠겨있다냥! 🏠🔒")
                print(f"💡 팁: 공유기 설정에서 {G_BRIDGE_PORT}번 포트포워딩(UPnP)이 제대로 됐는지 확인해줘냥! 🐾")
            else:
                print(f"❌ [Ping FAIL] 우리집 집주소 자체가 응답이 없다냥! 🚫🏠")
                print(f"💡 팁: 인터넷 연결이나 공인 IP({target_ip})가 정확한지 확인해줘냥! ✨")
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")
    # [V103.3] 🔑 진짜 원인 수정! 초인종 성공 시 TCP 터널 워커도 즉시 시작!
    # 기존: 초인종(노크)만 누르고 bridge_worker는 한 번도 안 시작됨 → 코랩 로그에 흔적 없음
    # 수정: connected=True 이면 백그라운드로 _start_reverse_bridge_server 자동 실행
    if connected:
        print(f"🚀 [Bridge] 초인종 성공! TCP 데이터 터널도 개통한다냥! (PC: {target_ip}:{target_port})")
        threading.Thread(
            target=_start_colab_side_bridge, # [TAG: #@logic_audit] Bug#1 fix: 동명 함수 충돌 해결, 코랩 클라이언트용 함수 정확히 지정 🛡️
            kwargs=dict(local_port=local_port, target_ip=target_ip, target_port=target_port),
            daemon=True
        ).start()

_active_bridge_sessions = 0 # 전역 활성 세션 카운터
_g_bridge_worker_func = None # 하트비트에서 호출하기 위한 워커 함수 참조

# [TAG: #@_start_colab_side_bridge] (#@logic_audit Bug#1 fix: 코랩 클라이언트 전용 브릿지. PC→코랩 단방향 단일 연결용 🛡️)
def _start_colab_side_bridge(local_port=5000, target_ip='127.0.0.1', target_port=5002, local_front_port=5000):
    # [TAG: #@single_threaded_bridge]
    def single_threaded_bridge():
        import time, socket, select
        
        # 1. 로컬 AI 서버(5000번) 구동 대기
        _flask_ready = False
        while not _flask_ready:
            try:
                with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                    s.settimeout(1.0)
                    if s.connect_ex(('127.0.0.1', local_port)) == 0:
                        _flask_ready = True
                        print(f"✅ [Bridge] AI 서버 감지 완료! 리버스 브릿지를 준비한다냥! ✨")
                        break
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")
            time.sleep(1)
            
        print(f"🚀 [Bridge] 스레드 제로(0)! 지연 접속(Lazy) 모드가 가동되었습니다냥! 🐱💎")
        
        while True:
            bs = None
            ts = None
            try:
                # 코랩 멈춤(Freezing) 방지를 위한 확실한 세팅
                bs = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                bs.setsockopt(socket.SOL_SOCKET, socket.SO_KEEPALIVE, 1)
                # [V110.16] 리눅스 커널 수준의 강력한 TCP Keep-Alive 설정 (60초 유휴 시 작동) 🛡️✨
                if hasattr(socket, 'TCP_KEEPIDLE'):
                    try:
                        bs.setsockopt(socket.IPPROTO_TCP, socket.TCP_KEEPIDLE, 60)
                        bs.setsockopt(socket.IPPROTO_TCP, socket.TCP_KEEPINTVL, 10)
                        bs.setsockopt(socket.IPPROTO_TCP, socket.TCP_KEEPCNT, 6)
                    except: pass
                bs.settimeout(300.0) # [V110.16] 유휴 좀비 방지 타임아웃 상향 (300초=5분) 🛡️
                
                print(f" ⏳ [{get_kst_now()}] [Bridge] PC({target_ip}:{target_port})에 연결을 대기 중이다냥...")
                bs.connect((target_ip, target_port))
                
                # [V107.0] 🚨 PC가 데이터를 진짜로 보낼 때까지 대기 (타임아웃 적용) 🚨
                first_data = bs.recv(8192)
                if not first_data:
                    continue
                
                print(f" ✅ [{get_kst_now()}] [Bridge] PC 단일 연결 성공! 내부 AI 서버와 연결을 시작해냥! ✨")
                ts = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                ts.settimeout(10.0)
                ts.connect(('127.0.0.1', local_port))
                ts.settimeout(120.0) # 로컬 AI 서버도 타임아웃 적용
                
                # [V107.5] 세션 활성화 마킹
                global _active_bridge_sessions
                _active_bridge_sessions = 1
                
                # 처음 받은 데이터를 쏴줍니다.
                ts.sendall(first_data)
                
                # 완전히 단일 쓰레드로 데이터 파이프 릴레이
                sockets = [bs, ts]
                broken = False
                while not broken:
                    # [V110.15] 타임아웃 1.0초로 설정하여 주기적으로 루프를 돌며 루프 자체의 생존 확인
                    r, _, _ = select.select(sockets, [], [], 1.0)
                    if not r:
                        continue
                    
                    if bs in r:
                        data = bs.recv(8192)
                        if not data: broken = True
                        else: ts.sendall(data)
                        
                    if ts in r:
                        data = ts.recv(8192)
                        if not data: broken = True
                        else: bs.sendall(data)
            except socket.timeout:
                pass # 타임아웃 시 조용히 연결 종료하고 재연결 시도
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")
            finally:
                # [V107.5] 세션 비활성화 마킹 (다시 10초 주기로 전환) 💓🚀
                _active_bridge_sessions = 0
                if bs: 
                    try: bs.close() 
                    except Exception as e:
                        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                        if "6" not in str(e):
                            _log_to_file(f"⚠️ [Silent Exception] {e}")
                if ts: 
                    try: ts.close() 
                    except Exception as e:
                        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                        if "6" not in str(e):
                            _log_to_file(f"⚠️ [Silent Exception] {e}")
                # 서버 부하를 막기 위해 연결이 끊어지면 잠깐 쉬었다가 다시 시도
                time.sleep(0.5)

    # 전체를 통틀어 딱 1개의 백그라운드 스레드만 띄움! 무한 증식 원천 봉쇄 🛡️
    threading.Thread(target=single_threaded_bridge, daemon=True).start()


# [V80.6] 모든 함수 정의 완료 후 서비스 즉시 가동! (핸드셰이크 우선! ⚡)
