    # [TAG: #@run_receiver]
    def run_receiver():
        log = logging.getLogger('werkzeug')
        log.setLevel(logging.ERROR)
        from werkzeug.serving import make_server
        try:
            srv = make_server('0.0.0.0', port, receiver_app, threaded=True)
            srv.serve_forever()
        except Exception as e:
            print(f"❌ [Colab 수신기] 실행 오류: {e}")

    # [V65.7] 공인 IP/UPnP 실패 시를 대비한 로컬 터널 자동 가동 스레드
    # [TAG: #@run_receiver_tunnel]
    def run_receiver_tunnel():
        global _colab_receiver_tunnel_url
        # [중요] 이미 터널이 있거나 UPnP가 성공했다면 추가 실행하지 않음 (선택사항이지만 안정성 위해 실행)
        print(f" 📡 {C.CYAN}[수신기 터널]{C.RESET} 외부 연동을 위한 터널 생성을 시작합니다...")
        try:
            npx_cmd = "npx.cmd" if os.name == 'nt' else "npx"
            # npx --yes localtunnel --port 5001
            # [V65.8] 수신기는 별도 도메인 없이 랜덤하게 생성
            proc = subprocess.Popen([npx_cmd, "--yes", "localtunnel", "--port", str(port)],
                                     stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, bufsize=1)

            for _ in range(30): # 약 30초간 시도
                line = proc.stdout.readline()
                if not line: break
                if "your url is:" in line:
                    _url = line.split("your url is:")[1].strip()
                    _colab_receiver_tunnel_url = _url
                    print(f" ✨ {C.GREEN}[수신기 터널] 외부 주소 생성 성공:{C.RESET} {C.BOLD}{_url}{C.RESET}")
                    break
                time.sleep(1)
        except Exception as e:
            print(f" ⚠️ [수신기 터널] 가동 실패: {e}")

    threading.Thread(target=run_receiver, daemon=True).start()

    # [V77.2] 연결 방식 설정에 따른 터널 구동 여부 결정 🌐✨
    conn_mode = settings_ref.data.get('colab_connection_mode', 0) # 0: Localtunnel, 1: Direct IP

    if conn_mode == 0:
        # [V65.8] 수신기용 로컬터널 가동 (항상 시도하여 안정성 극대화)
        threading.Thread(target=run_receiver_tunnel, daemon=True).start()
    else:
        print(f" 🚀 {C.GREEN}[Direct IP 모드]{C.RESET} 터널을 생성하지 않고 공인 IP로 직통 연결을 준비합니다. (UPnP 필수!)")


    _colab_receiver_running = True
    return _colab_receiver_url
