# [TAG: #@_copy_colab_code_to_clipboard]
def _copy_colab_code_to_clipboard(trans_mode: str = "", colab_llm: str = None, colab_ollama: str = "None", colab_whisper: str = "large-v3", endpoint: str = "/cat/update_url"):
    """코랩 실행 코드를 클립보드에 복사하고 파일로도 저장하는 헬퍼."""
    try:
        # [진단로그] 전역 변수 상태 확인 (사용자님 피드백 반영: '밥'이 있는지 먼저 확인! 🐈)
        global COLAB_CODE_UNIVERSAL
        if 'COLAB_CODE_UNIVERSAL' not in globals() or not COLAB_CODE_UNIVERSAL:
             print(f" ⚠️ {C.RED}[데이터 오류]{C.RESET} 'COLAB_CODE_UNIVERSAL' 변수를 찾을 수 없습니다.")
             return ""

        # 1. 수동 설정값 확인 (우선)
        try:
            main_url = settings_ref.data.get("main_web_url", "")
        except NameError:
            try:
                main_url = settings.data.get("main_web_url", "")
            except NameError:
                main_url = ""

        # 2. 전용 수신기(5001)에서 수신 주소 받아오기 (미디어 서버 의존 해결)
        is_using_public_ip = False
        conn_mode = settings_ref.data.get('colab_connection_mode', 0)

        # [V125.0] Direct IP 모드(1)인 경우 공인 IP 감지 강화 🚀✨
        if conn_mode == 1:
            ext_ip = _get_external_ip() # 새로 강화된 감지기 호출
            if ext_ip and "127.0.0.1" not in ext_ip:
                main_url = f"http://{ext_ip}:{G_SIGNAL_PORT}"
                is_using_public_ip = True
            else:
                # 감지 실패 시 기존 수신기 가동 주소라도 확보 시도
                if not main_url:
                    main_url = _start_colab_receiver_if_needed()

                # 그래도 로컬이면 경고
                if "127.0.0.1" in main_url or "192.168" in main_url or "10.0" in main_url:
                    print(f" ⚠️ {C.RED}[연결 긴급]{C.RESET} 공인 IP 감지에 실패하여 로컬 주소({main_url})를 사용합니다. 코랩 연동이 되지 않을 수 있어냥!")
        else:
            # 터널 사용 모드(0) 등 일반 감지 로직
            if not main_url or "127.0.0.1" in main_url or "192.168" in main_url or "10.0" in main_url:
                if not main_url:
                    main_url = _start_colab_receiver_if_needed()

                if conn_mode == 0 and 'loca.lt' not in main_url:
                    _wait_count = 0
                    while _wait_count < 5:
                        if '_colab_receiver_tunnel_url' in globals() and _colab_receiver_tunnel_url:
                            main_url = _colab_receiver_tunnel_url
                            break
                        time.sleep(1)
                        _wait_count += 1

            if main_url and "127.0.0.1" not in main_url and "192.168" not in main_url and "10.0" not in main_url:
                is_using_public_ip = True


        # [V40.4] 3단계 상황별 모델 자동 매칭
        if colab_llm is None:
            if trans_mode == MODE_COLAB_WHISPER_GEMMA_FREE:
                colab_llm = "Gemma-3-12B-Korean (고성능)"
            elif trans_mode == MODE_COLAB_WHISPER_GEMMA4_E4B:
                colab_llm = "Gemma-4-E4B-Uncensored"
            else:
                colab_llm = "None (Whisper API 연동)"

        # [V80.0] Cohere 2B 로컬 모드 여부 확인 🐚 (제거 예정)
        # is_cohere_2b = "True" if trans_mode == MODE_COLAB_COHERE_2B else "False"
        # if trans_mode == MODE_COLAB_COHERE_2B:
        #     colab_whisper = "None"
        #     colab_llm = "None (Whisper API 연동)"

        # [NEW] Gemma 4 e4b 모드 대응 (코렙 사이드에서 처리) ✨
        if trans_mode == MODE_COLAB_GEMMA4_E4B:
             colab_whisper = "None"
             colab_llm = "None (Gemma 4 e4b 원스탭)"

        # [V111.0] 가벼운 모드(위스퍼 전용/Gemini CLI) 판단 🚀✨
        # 구글 드라이브 마운트나 HF 로그인을 생략하여 '실행' 즉시 루틴에 진입하도록 함. (사용자 요청 🧼✨)
        use_drive = "True"
        use_hf = "True"

        # 위스퍼만 사용하거나 제미나이 CLI 연동인 경우 드라이브/HF 팝업 생략 (가벼운 작업 전용)
        if trans_mode in [MODE_COLAB_WHISPER_GEMINI, MODE_COLAB_WHISPER_GEMINI_CLI]:
            use_drive = "False"
            use_hf = "False"

        is_direct = "True" if conn_mode == 1 else "False"
        hf_token = settings_ref.data.get("hf_token", "")

        # [V122.5] 파라미터 블록 생성 (가벼운 모드에서는 토큰 선언 자체를 제거하여 팝업 원천 차단 🧼✨)
        if use_hf == "True":
            hf_token_block = f'HF_TOKEN = "{hf_token}" # @param {{type:"string"}}'
            use_hf_block = f"USE_HF = {use_hf} # @param {{type:\"boolean\"}}"
        else:
            hf_token_block = "" # 선언 자체를 하지 않음 (코랩 보안 비밀 연동 로직 회피)
            use_hf_block = f"USE_HF = {use_hf}"

        if use_drive == "True":
            use_drive_block = f"USE_DRIVE = {use_drive} # @param {{type:\"boolean\"}}"
        else:
            use_drive_block = f"USE_DRIVE = {use_drive}"

        # 템플릿 치환 (Ollama 및 신규 가이드 플래그 포함)
        code_to_copy = COLAB_CODE_UNIVERSAL \
            .replace("{colab_llm_placeholder}", colab_llm) \
            .replace("{colab_whisper_placeholder}", colab_whisper) \
            .replace("{colab_ollama_placeholder}", colab_ollama) \
            .replace("{report_url_placeholder}", main_url) \
            .replace("{report_endpoint_placeholder}", endpoint) \
            .replace("{is_direct_ip_mode}", is_direct) \
            .replace("{flask_port_placeholder}", str(G_FLASK_PORT)) \
            .replace("{signal_port_placeholder}", str(G_SIGNAL_PORT)) \
            .replace("{bridge_port_placeholder}", str(G_BRIDGE_PORT)) \
            .replace("{hf_token_param_block}", hf_token_block) \
            .replace("{use_drive_param_block}", use_drive_block) \
            .replace("{use_hf_param_block}", use_hf_block)


        # [V65.7] 어떤 주소가 복사되었는지 사용자에게 명시적으로 알림
        _url_type = "✨ 터널" if "loca.lt" in main_url or "lhr.life" in main_url else "🏠 로컬/공인 IP"
        print(f" 📋 [클립보드] 코랩 실행 코드를 준비했어! (보고 주소: {main_url} [{_url_type}])")

        # [TAG: #@_set_clipboard_windows]
        def _set_clipboard_windows(text):
            """ctypes를 이용한 윈도우 네이티브 클립보드 복사 윈도우 전용 🛡️"""

            # Constants
            CF_UNICODETEXT = 13
            GMEM_MOVEABLE = 0x0002

            user32 = ctypes.windll.user32
            kernel32 = ctypes.windll.kernel32

            # 텍스트 데이터 준비
            text_utf16 = text.encode('utf-16le') + b'\x00\x00'

            # 클립보드 열기
            if not user32.OpenClipboard(None):
                return False

            try:
                user32.EmptyClipboard()
                h_global = kernel32.GlobalAlloc(GMEM_MOVEABLE, len(text_utf16))
                if not h_global:
                    return False

                lp_global = kernel32.GlobalLock(h_global)
                ctypes.memmove(lp_global, text_utf16, len(text_utf16))
                kernel32.GlobalUnlock(h_global)

                if not user32.SetClipboardData(CF_UNICODETEXT, h_global):
                    return False
                return True
            finally:
                user32.CloseClipboard()

        # [TAG: #@_verify_clipboard]
        def _verify_clipboard(expected):
            """클립보드 내용이 예상값과 일치하는지 확인 ✨"""
            try:
                # tkinter를 이용해 짧게 확인
                v_root = tk.Tk()
                v_root.withdraw()
                current_text = v_root.clipboard_get()
                v_root.destroy()
                # 공백 제거 후 일부 내용(앞부분 100자) 비교
                return expected[:100].strip() in current_text.strip()
            except:
                return False

        # [V65.8] 클립보드 원시기(Primal stage) 정화: 복사 전 항상 초기화 🧼
        try:
            ctypes.windll.user32.OpenClipboard(None)
            ctypes.windll.user32.EmptyClipboard()
            ctypes.windll.user32.CloseClipboard()
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

        # [V65.8-6] 코랩(리눅스) 환경에 최적화: 줄바꿈 정규화 (\r\n -> \r\n) 🧼
        # 메모장은 상관없지만 코랩(브라우저)은 \r를 깨진 문자()로 볼 수 있어!
        code_to_copy = code_to_copy.replace('\r\n', '\r\n').replace('\r', '\r\n')

        # [V65.8-6] 유령 문자(BOM, Zero-width 등) 정밀 타격 제거 🧹
        code_to_copy = re.sub(r'[\ufeff\u200b\u200c\u200d\u2060]', '', code_to_copy)

        # [V65.8] 시작/끝 부분의 유령 문자(BOM, 공백 등) 전면 제거 🧹
        code_to_copy = code_to_copy.strip('\ufeff\ufe0f\u200b \t\r\n\r')

        # 1차 시도: 윈도우 네이티브 API (가장 강력)
        success = False
        import tkinter as tk
        try:
            success = _set_clipboard_windows(code_to_copy)
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

        # 2차 시도: Windows clip.exe (백업)
        if not success:
            try:
                # [V65.8-6] BOM 없는 UTF-16LE 인코딩을 사용하여 코랩에서의 깨짐 방지 ✨
                subprocess.run(['clip'], input=code_to_copy.encode('utf-16le'), check=True, creationflags=0x08000000)
                success = True
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

        # 3차 시도: 기존 tkinter 방식 (호환성)
        if not success:
            try:
                root = tk.Tk()
                root.withdraw()
                root.clipboard_clear()
                root.clipboard_append(code_to_copy)
                root.update()
                root.destroy()
                success = True
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

        # [점검] 복사 결과 최종 확인! ✨
        is_verified = _verify_clipboard(code_to_copy)

        if is_verified:
            print(f" ✅ {C.GREEN}클립보드 복사 및 검증 완료!{C.RESET}")
        else:
            print(f"\r\n 🚨 {C.RED}{C.BOLD}[경고] 클립보드 복사 확인 실패!{C.RESET}")
            print(f"    {C.YELLOW}일부 보안 프로그램이나 시스템 설정으로 인해 자동 복사가 차단되었을 수 있습니다.{C.RESET}")
            print(f"    👉 대신 생성된 {C.CYAN}colab_server_code.py{C.RESET} 파일을 직접 열어 복사해 주세요!")

        # 파일로도 저장 (클립보드 실패 대비용 밥그릇)
        try:
            _colab_file = os.path.join(os.path.dirname(os.path.abspath(sys.argv[0])), "colab_server_code.py")
            with open(_colab_file, "w", encoding="utf-8") as _cf:
                _cf.write(code_to_copy)
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

        print("\r\n ✅ 코랩 실행 코드가 클립보드에 복사되었습니다! (Ctrl+V 준비 완료)")
        print("    📄 파일로도 저장됨: colab_server_code.py")
        print(f"    📡 [연동 정보] 코랩이 보고할 로컬 주소: {main_url}{endpoint}")
        if is_using_public_ip:
            print(f"    ⚠️ {C.YELLOW}잠깐! 공인 IP로 설정되었습니다.{C.RESET}")
            print(f"       공유기에서 {C.CYAN}5001번 포트를 수동으로 포트포워딩{C.RESET} 해주셔야 할 수 있습니다!")

        print(" ⚡ [클립보드 자동화] 파일을 찾아서 올릴 필요 없이, 코드를 복사해 드립니다.")
    except Exception as e:
        print(f" ❌ 실행 코드 복사 중 오류 발생: {e}")
        pass

    print(f"\r\n {C.CYAN}📋 [AI냥] 코랩용 소스코드가 클립보드에 복사되었습니다!{C.RESET}")
    print(f" 💡 {C.BOLD}구글 코랩(Google Colab){C.RESET} 페이지의 빈 셀에 {C.YELLOW}Ctrl+V{C.RESET}로 붙여넣고 실행해줘냥! 🐾")

    # [V80.3] 자동화 워치독 가동 여부 확인 (봉인됨) ✨
    auth_idx = ""

    conn_mode = settings_ref.data.get('colab_connection_mode', 0)
    if conn_mode == 1: # Direct Bridge
        ext_ip = _get_external_ip()
        print(f"\r\n {C.GREEN}🚀 [Direct Bridge 모드 활성화됨]{C.RESET}")
        print(f" 🏠 우리집 외부 IP: {C.BOLD}{ext_ip if ext_ip else '감지 실패'}{C.RESET}")
        print(f" 🔔 코랩이 실행되면 자동으로 이 PC({ext_ip if ext_ip else '127.0.0.1'})를 찾아올 거야냥!")
        print(f"    (대상 주소: {C.CYAN}http://{ext_ip if ext_ip else '127.0.0.1'}:5002{C.RESET})")
        print(f" ⚠️  만약 {C.RED}접속 실패(Connection Refused){C.RESET}가 뜬다면:")
        print(f"    1. 공유기에서 {C.BOLD}{G_BRIDGE_PORT}번 포트포워딩{C.RESET}이 되어있는지 확인해줘냥!")
        print(f"    2. 방화벽에서 {C.BOLD}korea.srt.py(Python){C.RESET}의 통신을 허용했는지 확인해줘냥!")
        if not ext_ip or "127.0.0.1" in str(ext_ip):
             print(f"    💡 {C.YELLOW}[팁] 공인 IP 감지에 실패했어. 수동으로 공유기 설정을 확인해달라냥! 🐾{C.RESET}")

    print("-" * 60)
    print(" 1️⃣ 잠시 후 구글 코랩(Colab) 새 창이 자동으로 열립니다.")
    print("    ⚠️ [중요] 코랩 창이 열리면 반드시 'T4 GPU' 등 하드웨어 가속기로 설정해주세요!")
    print(" 2️⃣ 빈 화면(셀)에 [Ctrl + V] 하여 코드를 붙여넣습니다.")
    print(" 3️⃣ [▶ 실행] 버튼을 누르면 서버가 가동됩니다.")

    return auth_idx if auth_idx else ""

# [TAG: #@_validate_and_add_url]
def _validate_and_add_url(url: str, url_list: list, trans_mode: int) -> bool:
    """URL 유효성을 검증하고 리스트에 추가. 성공 시 True 반환."""
    url = url.rstrip('/')
    if url in url_list:
        print("⚠️ 이미 등록된 주소입니다.")
        return False

    print(" 📡 입력하신 서버 주소가 유효한지 확인합니다...")
    try:
        import requests
        headers = {"Bypass-Tunnel-Reminder": "true"}

        # [V80.1] 핸드쉐이크 도입: 단순 접속이 아니라 실제 사용자 SRT 서버인지 확인 🤝
        try:
            print(f" 🤝 [핸드쉐이크] 코랩 서버({url}) 신원 확인 중... 🔍")
            r_ping = requests.get(f"{url}/ping", timeout=5, headers=headers)
            if r_ping.status_code == 200 and r_ping.json().get('app') == 'binu_srt':
                print(" ✅ [검증 성공] 사용자 SRT 서버로 확인되었습니다! ✨")
            else:
                print(f" ⚠️ {C.YELLOW}[검증 실패] 서버는 열려있으나 사용자 SRT 서버가 아닙니다. (다른 서비스 점유 중?){C.RESET}")
        except Exception as e:
            print(f" ⚠️ [핸드쉐이크 실패] {str(e)}")

        # 모드에 따른 엔드포인트 구분 (실제 작동 여부 체크)
        endpoint = "/translate" if IS_COLAB_TRANSLATE_MODE(trans_mode) else "/transcribe"
        test_kwargs = {"json": {"text": "hi"}, "headers": headers} if IS_COLAB_TRANSLATE_MODE(trans_mode) else {"headers": headers}

        try:
            res = requests.post(url + endpoint, timeout=30, **test_kwargs)
            if res.status_code in [200, 400]:
                print(" ✅ [연결 성공] 서버가 정상 작동 중입니다! (등록 완료)")
                play_success_sound() # 딩동뎅!
                url_list.append(url)
                return True
        except Exception as e:
            print(f" ⚠️ {C.YELLOW}[연결 에러] {str(e)}{C.RESET}")

        print(" ❌ [오류] 서버가 응답하지 않거나 이상합니다.")
        print(" ※ 팁: LocalTunnel 경고 화면이 떴다면 URL로 직접 접속해 'Continue' 버튼을 한 번 눌러주세요.")

        # [V65.7] AI냥 피드백: y/n 대신 방향키 선택형으로! 🐾
        add_sel, _, *_ = _interactive_menu("서버 응답이 없거나 이상해. 그래도 추가할까?", ["✅ 주소 강제 추가", "❌ 취소"], cols=2)
        if add_sel < 0: return None # [V77.5 Globalizer]
        if add_sel == 0:
            url_list.append(url)
            print("    ⚠️ 강제 등록되었습니다.")
            return True

    except Exception as e:
        print(f" ❌ [연결 실패] 입력하신 주소로 연결할 수 없습니다 ({e}).")
        add_sel, _, *_ = _interactive_menu("연결에 실패했어. 그래도 추가할까?", ["✅ 주소 강제 추가", "❌ 취소"], cols=2)
        if add_sel < 0: return None # [V77.5 Globalizer]
        if add_sel == 0:
            url_list.append(url)
            print("    ⚠️ 강제 등록되었습니다.")
            return True
    return False

# [TAG: #@_wait_for_colab_sync]
def _wait_for_colab_sync(check_callback, timeout: int = 600, cat_tone: bool = False, recopy_callback=None) -> tuple[bool, bool]:
    """[V46.6] 코랩 서버 터널링 주소 수신을 대기하는 공통 루프."""
    msg_wait = "기다려줘냥!" if cat_tone else "기다려주세요!"
    msg_cancel = "대기를 취소했어냥!" if cat_tone else "대기를 취소했습니다!"
    msg_success = "성공! 자동 연결되었어냥!" if cat_tone else "성공! 자동 연결되었습니다!"

    print(f"\r\n ⏳ {C.YELLOW}[현재 자동으로 터널링 주소 수신을 기다리는 중입니다...]{C.RESET}")
    print(f"    {C.RED}⚠️ (중요) 코랩 창이 열리면 상단 메뉴의 [런타임] ➔ [런타임 유형 변경]에서 반드시 'T4 GPU'로 설정해주세요!{C.RESET}")
    print(f"    설정 후 빈 셀에 붙여넣기 + '▶ 실행'을 누르고 터널링 주소가 생성될 때까지 {msg_wait}")
    print(f"    {C.DIM}(수동 입력: [Enter] / 대기 취소: [c] / 코드 재복사: [v]){C.RESET}\r\n")

    elapsed = 0
    setup_done = False
    manual_fallback = False
    last_success_time = None # [V65.7] 마지막 수신 시간 추적

    try: _s = settings_ref
    except NameError: _s = settings

    import msvcrt as _msvcrt
    import time as _time
    while elapsed < timeout:
        _s.load()

        is_success, should_break = check_callback(_s)
        if is_success:
            setup_done = True
            last_success_time = _time.time() # 수신할 때마다 타이머 리셋

        if should_break:
            break

        # [V65.7] 주소가 하나라도 왔다면, 10초 대기 후 자동 시작 로직 가동 🚀
        if setup_done and last_success_time:
            idle_elapsed = _time.time() - last_success_time
            if idle_elapsed > 10:
                print(f"\r\n 🚀 {C.GREEN}[자동 진행]{C.RESET} 10초간 추가 코랩 응답이 없어 현재 연결된 서버로 작업을 시작합니다! ✨")
                break
            sys.stdout.write(f"\r    ⏳ 추가 코랩 서버 대기 중... ({10 - int(idle_elapsed)}초 후 자동 시작) [Enter:즉시 / c:취소] ")
        else:
            # [V65.8] 수신기 주소 상태 표시 강화
            global _colab_receiver_tunnel_url, _colab_receiver_url
            _current_recv = _colab_receiver_tunnel_url if _colab_receiver_tunnel_url else _colab_receiver_url
            sys.stdout.write(f"\r    📡  {C.CYAN}계속 감시 중...{C.RESET} (수신주소: {C.YELLOW}{_current_recv}{C.RESET} {C.DIM}[외부접속용]{R}) [Enter:수동 / c:취소 / v:코드재복사] ")

        sys.stdout.flush()

        if _msvcrt.kbhit():
            c = _msvcrt.getch()
            if c in (b'\r', b'\r\n'):
                manual_fallback = True
                break
            elif c.lower() == b'c':
                print(f"\r\n ❌ {C.RED}{msg_cancel}{C.RESET}")
                break
            elif c.lower() == b'v':
                if recopy_callback:
                    recopy_callback()
                    print(f"\r\n 📋 {C.GREEN}코랩 실행 코드를 클립보드에 다시 복사했습니다! (Ctrl+V 준비 완료)🐾{C.RESET}")
                continue
        time.sleep(0.5)
        elapsed += 0.5

    if setup_done:
        # [V80.7] AI냥 전용 성공 메시지 커스텀 (Task 3) 🐾
        if cat_tone:
            print(f"\r\n 🎊 {C.BOLD}{C.GREEN}성공!{C.RESET} {C.SKY}자동 연결 및 기재가 완료되었어냥!{C.RESET}")
            print("    (잠시 후 메인 메뉴로 돌아갑니다... 🐾)")
        else:
            print(f"\r\n 🎉 {C.GREEN}{msg_success}{C.RESET}")

        import winsound as _winsound
        try:
            # [사용자 요청] 성공 알림음을 '갸냘픈 도-미-솔'로 변경 (High Octave) 🎵✨
            _winsound.Beep(1046, 100) # 도 (C6)
            _winsound.Beep(1318, 100) # 미 (E6)
            _winsound.Beep(1568, 200) # 솔 (G6)
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")
        time.sleep(1.5) # [V80.7] 사용자 요청: 1.5초 대기 후 자동 복귀 🚀

    return setup_done, manual_fallback

# [TAG: #@_input_colab_urls_loop]
def _input_colab_urls_loop(existing_valid_urls: list, trans_mode: int, already_triggered: bool = False) -> list:
    """[V3.0] 빈 줄이 입력될 때까지 코랩 URL을 반복 입력받는 루프. 🟢/⚫ 상태 표시 지원"""
    new_urls = list(existing_valid_urls)

    active_queues = PendingQueue.find_active_queues()
    num_active_instances = len(active_queues)
    total_instances = num_active_instances + 1

    manual_fallback_triggered = False
    auth_idx = ""
    while True:
        if len(new_urls) == 0 and not manual_fallback_triggered:
            options = [
                f"{C.GREEN}🚀 코랩 서버 자동 연결 (주소 자동 수신 시작) {C.BOLD}⭐추천{C.RESET}",
                "✍️ 코랩 주소 복사 후 그대로 붙여넣기 (수동 등록)",
                "🌐 브라우저 다시 열기 (소스 코드 복사)",
                "🪟 브릿지 통신 디버그 로그 새 창 열기",
                "❌ 취소 (메인 메뉴로 이동)"
            ]

            sel, _, *_ = _interactive_menu("코랩(Colab) 서버 연결 방식을 선택해주세요.", options, cols=1, clear_previous_remote=False)
            if sel < 0: break # [V77.5 Globalizer]

            if sel == 4: # 취소
                return None
            elif sel == 4: # 로그 새창 띄우기
                import tempfile
                log_path = os.path.join(tempfile.gettempdir(), "bridge_debug.log")

                # [V105.2] 요청사항 반영: temp 폴더에 저장 & 선택 시 기존 로그 초기화(w 모드) 🧹
                try: open(log_path, "w", encoding="utf-8").close()
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")

                # [V105.1] 관제 센터 전용 PowerShell 스크립트: 우측 절반 자동 스냅 & UTF8 인코딩 🪟✨🧭
                ps_cmd = (
                    'Add-Type -AssemblyName System.Windows.Forms; '
                    '$sig = \'[DllImport("user32.dll")] public static extern bool MoveWindow(IntPtr hWnd, int X, int Y, int nWidth, int nHeight, bool bRepaint);\'; '
                    '$type = Add-Type -MemberDefinition $sig -Name "Win32" -Namespace "WinAPI" -PassThru; '
                    '$scr = [System.Windows.Forms.Screen]::PrimaryScreen.WorkingArea; '
                    '$hw = (Get-Process -Id $PID).MainWindowHandle; '
                    '[WinAPI.Win32]::MoveWindow($hw, ($scr.Width/2), 0, ($scr.Width/2), $scr.Height, $true); '
                    '[Console]::OutputEncoding = [System.Text.Encoding]::UTF8; '
                    '$Host.UI.RawUI.WindowTitle = "AI 통신 관제 센터 (Bridge Console)"; '
                    f'Get-Content -Wait -Tail 30 -Encoding UTF8 "{log_path}"'
                )
                subprocess.Popen(
                    ['powershell.exe', '-NoProfile', '-Command', ps_cmd],
                    creationflags=subprocess.CREATE_NEW_CONSOLE
                )
                continue
            elif sel == 3: # 브라우저 다시 열기
                auth_idx = _copy_colab_code_to_clipboard(trans_mode=trans_mode, endpoint="/sub/update_url")
                url_to_open = "https://colab.research.google.com/#create=true"
                delayed_open_browser(url_to_open, "메인 번역 코랩 서버 창을 다시 엽니다", delay=0, initial_auth_idx=auth_idx)
                continue
            elif sel == 2: # 수동 등록
                print("\r\n\r\n ✍️ 코랩 주소를 수동으로 기재합니다.")
                manual_fallback_triggered = True
                # continue 하지 않으므로 아래의 수동 입력 prompt_input() 으로 진입함
            elif sel == 0: # 자동 연결
                # [V104.0] 사용자가 자동 연결 시작 시점에 안내양 감시기 기동 🚏🚌✨
                # [TAG: #@bus_conductor_neon_sign]
                def bus_conductor_neon_sign():
                    _write_bridge_log(" 🚏 [버스 안내양] 업무 시작! 코랩 초인종 수색 대행 서비스를 시작합니다냥! 🚌", console=True)
                    while not _colab_receiver_bridge_active:
                        # [V107.8] 메인 터미널 도배 방지 -> 로그 파일로만 '수색 중' 메시지 전송 📝
                        _write_bridge_log(" 🚏 [버스 안내양] 코랩 서버의 초인종을 애타게 기다리고 있어냥... (감시중) 🚌")
                        time.sleep(5)
                # [V107.8] 자동 창 띄우기: 0번 선택 시 로그 전용 창(PowerShell)을 자동으로 오픈! 🪟✨
                try:
                    import tempfile
                    lp = os.path.join(tempfile.gettempdir(), "bridge_debug.log")
                    # 기존 로그 비우기 (새 출발)
                    try: open(lp, "w", encoding="utf-8").close()
                    except Exception as e:
                        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                        if "6" not in str(e):
                            _log_to_file(f"⚠️ [Silent Exception] {e}")
                    # [V109.0] 관제 센터 전용 PowerShell 스크립트: 우측 절반 자동 스냅 & UTF8 인코딩 🪟✨🧭
                    ps_setup = (
                        'Add-Type -AssemblyName System.Windows.Forms; '
                        '$sig = \'[DllImport("user32.dll")] public static extern bool MoveWindow(IntPtr hWnd, int X, int Y, int nWidth, int nHeight, bool bRepaint);\'; '
                        '$type = Add-Type -MemberDefinition $sig -Name "Win32" -Namespace "WinAPI" -PassThru; '
                        '$scr = [System.Windows.Forms.Screen]::PrimaryScreen.WorkingArea; '
                        '$hw = (Get-Process -Id $PID).MainWindowHandle; '
                        '[WinAPI.Win32]::MoveWindow($hw, ($scr.Width/2), 0, ($scr.Width/2), $scr.Height, $true); '
                        '[Console]::OutputEncoding = [System.Text.Encoding]::UTF8; '
                        '$Host.UI.RawUI.WindowTitle = "AI 통신 관제 센터 (Bridge Console)"; '
                        f'Get-Content -Wait -Tail 30 -Encoding UTF8 "{lp}"'
                    )
                    subprocess.Popen(['powershell.exe', '-NoProfile', '-Command', ps_setup], creationflags=subprocess.CREATE_NEW_CONSOLE)
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")

                threading.Thread(target=bus_conductor_neon_sign, daemon=True).start()

                # [V107.0] 🚨 즉시 통과 조건 강화: 단순히 URL 문자열이 있는 게 아니라, 진짜 브릿지 세션이 살아있어야 함!
                bridge_url = "http://127.0.0.1:5000"
                if "127.0.0.1:5000" in _colab_receiver_url and _colab_receiver_bridge_active:
                    print(f"\r\n ⚡ {C.SKY}[Direct Bridge]{C.RESET} 활성화된 브릿지 연결을 확인했어냥! 즉시 작업을 시작합니다. 👍")
                    if bridge_url not in new_urls:
                        new_urls.append(bridge_url)
                    return new_urls

                if not already_triggered:
                    auth_idx = _copy_colab_code_to_clipboard(trans_mode=trans_mode, endpoint="/sub/update_url")
                    url_to_open = "https://colab.research.google.com/#create=true"
                    delayed_open_browser(url_to_open, "메인 번역 코랩 서버 창을 엽니다", initial_auth_idx=auth_idx)
                else:
                    print(f"\r\n 📋 {C.GREEN}이미 코랩 실행 코드가 준비되어 있어! (수신 대기 중...){C.RESET}")

                try: _s = settings_ref
                except NameError: _s = settings

                _s.load()
                len(_s.data.get('colab_urls', []))

                # [TAG: #@_recopy]
                def _recopy():
                    _copy_colab_code_to_clipboard(trans_mode=trans_mode, endpoint="/sub/update_url")

                # [V65.6] 이미 검증을 거친 주소들을 기억해서 무한 루프 방지 🛡️
                processed_found_urls = set(new_urls)

                # [TAG: #@_trans_check]
                def _trans_check(s_obj):
                    current_urls = s_obj.data.get('colab_urls', [])
                    # [V65.6] 중복되지 않았고, 아직 검증하지 않은 새로운 주소만 추출
                    new_found = [u for u in current_urls if u not in processed_found_urls]
                    if new_found:
                        detected_url = new_found[0]
                        processed_found_urls.add(detected_url)
                        print(f"\r\n ✨ {C.GREEN}[자동 감지]{C.RESET} 새로운 주소를 수신했습니다: {detected_url}")
                        print(" ⏳ [연결 확인 중] ... ", end="", flush=True)
                        # [V78.5] 127.0.0.1 = Direct Bridge (TCP 소켓 터널) → HTTP 헬스체크 불필요, 브릿지 플래그로 대체
                        if "127.0.0.1" in detected_url and _colab_receiver_bridge_active:
                            print(f" {C.GREEN}🟢 연결 성공! (Direct Bridge 🌉){C.RESET}")
                            new_urls.append(detected_url)
                            return True, False
                        if _check_url_health(detected_url):
                            print(f" {C.GREEN}🟢 연결 성공!{C.RESET}")
                            new_urls.append(detected_url)
                            return True, False
                        else:
                            print(f" {C.RED}⚫ 연결 실패! (서버 설정을 다시 확인해주세요){C.RESET}")
                            try:
                                s_obj.data['colab_urls'] = [u for u in current_urls if u != detected_url]
                                s_obj.save()
                            except Exception as e:
                                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                                if "6" not in str(e):
                                    _log_to_file(f"⚠️ [Silent Exception] {e}")
                            return False, False
                    # [V109.4] 🚨 브릿지 자동 감지 강화 (도배 및 무한 루프 방지 패치) 📡✨
                    bridge_url = "http://127.0.0.1:5000"
                    is_ptr_match = ("/bridge_ip/" in str(_colab_receiver_url))

                    # 이미 처리된 주소라면 중복 체크를 하지 않고 조용히 넘어감 (무한 루프 방지 핵심)
                    if bridge_url not in processed_found_urls:
                        if (is_ptr_match or (bridge_url in str(_colab_receiver_url))) and _colab_receiver_bridge_active:
                            # 1. 먼저 브릿지 세션 큐 상태 확인
                            is_bridge_ready = (_colab_sessions and not _colab_sessions.empty())

                            # 2. [핵심] 실제 헬스체크 수행 (찔러보기 로그 출력) 🎯
                            sys.stdout.write(f"\r    📡 {C.SKY}[Direct Bridge]{C.RESET} 기존 연결(127.0.0.1:5000) 찔러보는 중... ")
                            sys.stdout.flush()

                            if is_bridge_ready:
                                processed_found_urls.add(bridge_url)
                                print(f"{C.GREEN}✅ 응답 확인!{C.RESET}")
                                print(f" ✨ {C.SKY}[Direct Bridge]{C.RESET} 코랩이 이미 살아있어 즉시 작업을 시작한다냥! 👍")
                                new_urls.append(bridge_url)
                                return True, False
                            else:
                                # 실패하면 로그를 남기고 대기 계속
                                sys.stdout.write(f"{C.RED}❌ 응답 없음{C.RESET}  ")
                                sys.stdout.flush()

                    return False, False

                setup_done, manual_fallback = _wait_for_colab_sync(_trans_check, timeout=600, cat_tone=False, recopy_callback=_recopy)

                if setup_done or len(new_urls) > 0:
                    # [V65.6] 이미 하나라도 성공적으로 연결되었다면, Enter를 눌렀을 때 수동 입력으로 가지 않고 즉시 시작! ⭐
                    if manual_fallback:
                        print(f"\r\n 🚀 {C.GREEN}등록된 {len(new_urls)}개의 서버로 바로 작업을 시작합니다!{C.RESET}")
                        return new_urls

                    if len(new_urls) >= total_instances:
                        print(f"\r\n ✅ 현재 {len(new_urls)}개의 코랩 서버가 등록되었습니다.")
                        print(f"    (더 등록하려면 다른 코랩에서 코드를 실행하고, 시작하려면 {C.BOLD}[Enter]{C.RESET}를 누르세요!)")
                        continue
                    else:
                        print(f"\r\n 💡 {len(new_urls)}/{total_instances}개 서버 등록됨. 서버가 더 필요하면 추가 실행 후 [Enter]를 누르세요.")
                        continue
                elif manual_fallback:
                    print("\r\n\r\n ✍️ 코랩 주소를 수동으로 기재합니다.")
                    manual_fallback_triggered = True
                    # 다음 루프 혹은 하단으로 넘어가서 수동 prompt를 띄움
                else:
                    return None # [V63.7] 취소(c) 시 즉시 메인 메뉴로 복귀


        # 여기서부터는 url을 수동으로 입력받는 공통 로직
        if len(new_urls) == 0 and not manual_fallback_triggered:
            continue # 자동수신이 아닌 취소/다른조작 등의 이유로 떨어진 경우 재차 메뉴 노출

        # [V63.6] 서버 한 개만 필요한 경우 수동 입력 후 즉시 마무리 (사용자 요청 반영 ⭐)
        if len(new_urls) >= total_instances:
             # 사실 이미 루프를 돌고 있다면 이전에 성공한 것.
             # 메뉴를 띄우지 않고 바로 확정 메뉴로 넘어가거나 끝냄
             break

        # [V61.5] 수동 입력 시에도 메뉴를 띄워 '입력 완료'나 '취소'를 명확히 고르게 함 (사용자님 피드백 반영 ⭐)
        manual_options = [
            f"✍️ {C.CYAN}주소 #{len(new_urls)+1} 직접 입력하기{C.RESET}",
            "✅ 입력 완료 (서버 목록 확정)",
            "❌ 취소 (메인 메뉴로 이동)"
        ]

        m_sel, _, *_ = _interactive_menu(f"코랩 서버 등록 중 (현재 {len(new_urls)}개)", manual_options, cols=1, clear_previous_remote=False)
        if m_sel < 0: return None # [V77.5 Globalizer]

        if m_sel == 2: # 취소
            return None
        elif m_sel == 1: # 완료
            if new_urls: break
            else:
                print("⚠️ 최소 1개의 주소를 입력해야 합니다!")
                time.sleep(1.5)
                continue

        # 0번: 직접 입력하기
        prompt = f" 👉 {C.SKY}코랩 주소 #{len(new_urls)+1} 입력 (https://...){C.RESET}: "
        url_raw = prompt_input(prompt)
        url = url_raw.strip() if url_raw else ""

        if not url:
            continue

        if not url.startswith(("https://", "http://")):
            print(f" ⚠️ {C.RED}올바른 주소가 아닙니다.{C.RESET} 'https://' 로 시작하는 전체 주소를 입력해주세요.")
            time.sleep(1.5)
            continue

        # 즉시 헬스체크 수행
        if _check_url_health(url):
            print(f" {C.GREEN}🟢 연결 성공!{C.RESET} 서버가 응답합니다. (등록 완료)")
            play_success_sound()
            if url not in new_urls:
                new_urls.append(url)
            print(f"   현재 등록된 서버: {len(new_urls)}개")
            time.sleep(1)

            # [V63.6] 서버 한 개만 필요한 경우 즉시 확정 (사용자 요청 반영 ⭐)
            if len(new_urls) >= total_instances:
                print(f" ✨ {total_instances}개 서버가 모두 등록되었습니다. 설정을 확정합니다.")
                time.sleep(1)
                break
        else:
            print(f" {C.RED}⚫ 연결 실패!{C.RESET} (주소를 다시 확인하거나 코랩 [▶ 실행] 상태를 점검해주세요)")
            add_anyway_res = prompt_input("    그래도 추가할까요? (y/N): ")
            add_anyway = add_anyway_res.strip().lower() if add_anyway_res else 'n'
            if add_anyway == 'y':
                new_urls.append(url)
                print("    ⚠️ 강제 등록되었습니다.")
                time.sleep(1)
                if len(new_urls) >= total_instances: break

    return new_urls

# [TAG: #@_check_url_health]
def _check_url_health(url: str, timeout: int = 30, silent: bool = False) -> bool:
    """[V3.0] 코랩 서버의 /ping 엔드포인트를 확인하여 헬스체크를 수행합니다. 🔗"""
    import requests
    if not url: return False
    url = url.rstrip('/')
    headers = {"Bypass-Tunnel-Reminder": "true"}
    try:
        # /ping 엔드포인트가 있으면 우선 체크, 없으면 /transcribe(400) 체크 폴백
        try:
            res = requests.get(url + '/ping', headers=headers, timeout=timeout)
            if res.ok: return True
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

        res = requests.post(url + '/transcribe', headers=headers, timeout=timeout)
        return res.status_code in [200, 400]
    except:
        return False

# [TAG: #@_print_pool_summary]
def _print_pool_summary(pool: ColabPool, urls: list):
    """등록된 코랩 서버 요약을 출력하는 헬퍼."""
    print(f"\r\n✔️ [완료] 코랩 서버 {len(urls)}개 등록됨:")
    for i, u in enumerate(urls):
        marker = "★" if u == pool.primary_url else " "
        print(f"   {marker} 서버{i+1}: {u}")
    if len(urls) > 1:
        print(f"\r\n 💡 이 인스턴스(PID {os.getpid()})의 기본 서버: {pool.primary_url}")
        print("    (다른 인스턴스를 실행하면 PID에 따라 다른 서버가 배정됩니다)")
    print()

# [TAG: #@get_colab_urls]
def get_colab_urls(existing_urls: list = None, trans_mode: int = 4) -> ColabPool:
    """[V3.0] 코랩 서버 URL을 입력받아 ColabPool을 반환합니다. 🟢/⚫ 아이콘 표시 지원"""
    global _COLAB_WHISPER_SEMAPHORE
    _s = settings_ref if 'settings_ref' in globals() else (settings if 'settings' in globals() else None)
    clear_console()
    _print_standard_menu_header("colab_setup", _s)

    pool = ColabPool()
    existing_urls = existing_urls or []

    # [V125.5] AI냥 요청: 초인종 수색 대행 서비스 (10초간 귀 기울이기) 👂✨
    # 앱을 갓 켰을 때, 코랩이 이미 살아있다면 하트비트가 올 때까지 잠시 기다려줍니다.
    if not _colab_receiver_bridge_active:
        _write_bridge_log(" 🚏 [버스 안내양] 잠시만요! 기존 코랩 서버가 초인종을 누르는지 10초간 확인해볼게요냥... 🚌", console=True)
        for _ in range(10):
            if _colab_receiver_bridge_active: break
            time.sleep(1)

    # [V125.0] AI냥 요청: 신규 서버 열기 강제를 위한 메뉴 시스템 도입 🚀✨
    if existing_urls or _colab_receiver_bridge_active:
        is_auto_mode = (trans_mode == 5)
        
        # 초인종이 이미 울리고 있는 경우 문구 강화
        prompt = "사용자 님! 코랩 서버를 어떻게 설정할까요?"
        if _colab_receiver_bridge_active:
            prompt = f" ✨ {C.GREEN}[감지 성공]{C.RESET} 기존 코랩 서버가 초인종을 울리고 있어요! 그대로 쓸까요?"

        options = [
            f"🔗 기존 코랩 서버 재사용 시도 (저장된 {len(existing_urls)}개)" if not _colab_receiver_bridge_active else "🔗 살아있는 기존 서버 그대로 사용하기 ✨",
            "🚀 신규 코랩 서버 열기 (브라우저 창 띄우기 - 12345)"
        ]
        
        # [V126.0] 지능형 선택 및 타임아웃 로직 🧠✨
        if is_auto_mode and (_colab_receiver_bridge_active or existing_urls):
            sel = 0
            print(f" 🤖 {C.CYAN}[Auto Mode]{C.RESET} 기존 서버가 살아있어 자동으로 연결합니다냥! 🚀")
            time.sleep(1)
        else:
            # 수동 모드면 60초 타임아웃 (안 누르면 0번 '재사용' 선택)
            sel, action, *_ = _interactive_menu(prompt, options, cols=1, timeout=60)
            if sel < 0: return None # 취소
            if action == "timeout":
                print(f"\r\n ⏰ {C.YELLOW}[Timeout]{C.RESET} 응답이 없어 기존 서버를 그대로 사용합니다냥! 🐾")
                sel = 0

        if sel == 1:
            print(f"\r\n 🧹 {C.YELLOW}[Clean-up]{C.RESET} 기존 서버 목록을 초기화하고 새로 시작합니다냥! 🐾")
            existing_urls = []
            if _s:
                _s.data["colab_urls"] = []
                _s.save()

    # 기존 URL 헬스체크
    alive_urls = []
    if existing_urls:
        print(f" * 이전에 사용한 서버 {len(existing_urls)}개를 확인합니다...")
        for i, url in enumerate(existing_urls):
            url = url.rstrip('/')
            print(f"   ⏳ 서버{i+1}: {url} ... ", end="", flush=True)

            # [V125.1] 로컬 IP(Bridge Mode)라도 무조건 신뢰하지 않고 실제로 통신이 되는지 확인 🛡️
            # (수동으로 브릿지는 켜져있는데 코랩 런타임이 해제된 경우 '해골' 처리를 위해)
            if _check_url_health(url, timeout=5): # 로컬은 5초면 충분냥!
                print(f" {C.GREEN}🟢 정상{C.RESET}")
                alive_urls.append(url)
            else:
                print(f" {C.RED}⚫ 불가 (해골상태 💀){C.RESET}")

        if alive_urls:
            pool.set_urls(alive_urls)

            # [V99.0] 다중 코랩 병렬 처리 활성화 (세마포어 확장) 🚀🚀
            current_count = len(alive_urls)
            if current_count > 1:
                # [주의] release()를 호출하여 허용량을 동적으로 늘림
                for _ in range(current_count - 1):
                    _COLAB_WHISPER_SEMAPHORE.release()
                print(f" 🚀 {C.CYAN}[병렬 처리 활성화]{C.RESET} {current_count}개의 코랩 서버가 감지되었습니다. (동시 작업 가능)")

            if len(alive_urls) == len(existing_urls):
                print(f"\r\n ✔️ 모든 서버 정상! (PID {os.getpid()} - {pool.primary_url})")
            else:
                print(f"\r\n ⚠️ {len(existing_urls)}개 중 {len(alive_urls)}개만 살아있습니다.")
        else:
            print("\r\n ❌ 기존 서버가 모두 응답하지 않습니다. 새로 설정해야 합니다.")

    # ★ 다른 py 인스턴스 활성 여부 확인 → 서버 수 부족 시 추가 서버 입력 유도
    active_queues = PendingQueue.find_active_queues()
    num_active_instances = len(active_queues)
    total_instances = num_active_instances + 1

    if alive_urls and len(alive_urls) >= total_instances:
        if num_active_instances > 0:
            print(f"\r\n 📊 [분산 현황] 다른 인스턴스 {num_active_instances}개 활성 중")
            print(f"    유효 서버 {len(alive_urls)}개 ≥ 총 인스턴스 {total_instances}개 → 분산 가능!\r\n")
        return pool

    if alive_urls and num_active_instances > 0 and len(alive_urls) < total_instances:
        print(f"\r\n ⚠️ [분산 권장] 다른 인스턴스 {num_active_instances}개가 활성 중입니다.")
        print(f"    현재 유효 서버: {len(alive_urls)}개 / 필요 서버: {total_instances}개 이상")
        add_more = prompt_input("\r\n    코랩 서버를 추가로 등록하시겠습니까? (Y/n): ").strip().lower()
        if add_more != 'n':
            auth_idx = _copy_colab_code_to_clipboard(trans_mode, endpoint="/sub/update_url")
            delayed_open_browser("https://colab.research.google.com/#create=true", "추가 코랩 서버 오픈", initial_auth_idx=auth_idx)
            new_urls = _input_colab_urls_loop(alive_urls, trans_mode, already_triggered=True)
            pool.set_urls(new_urls)
            _print_pool_summary(pool, new_urls)
            return pool
        else:
            print(f" ℹ️ 기존 서버 {len(alive_urls)}개로 진행합니다.\r\n")
            return pool

    if alive_urls and num_active_instances == 0:
        return pool

    # ✨ 새로 설정해야 하는 경우
    auth_idx = _copy_colab_code_to_clipboard(trans_mode, endpoint="/sub/update_url")
    delayed_open_browser("https://colab.research.google.com/#create=true", "구글 코랩 새 창 오픈", initial_auth_idx=auth_idx)
    new_urls = _input_colab_urls_loop(alive_urls, trans_mode, already_triggered=True)
    if new_urls is None: return None
    pool.set_urls(new_urls)
    _print_pool_summary(pool, new_urls)
    return pool

# [TAG: #@init_colab_pool]
def init_colab_pool(trans_mode: int, settings: 'SettingsManager') -> 'ColabPool':
    """코랩 풀 초기화를 일관되게 처리하는 통합 함수. (V108.9 통합본 🏗️✨)"""
    global G_COLAB_POOL, G_FLASK_PORT, G_SIGNAL_PORT, G_BRIDGE_PORT

    if not IS_COLAB_MODE(trans_mode):
        return None

    # [V96.6] 자막 작업 시작 시점에 다이내믹 포트 클러스터 확정 🔌⚡
    G_FLASK_PORT, G_SIGNAL_PORT, G_BRIDGE_PORT = _find_port_cluster(5000)
    _log_to_file(f"📡 [Port Shift] 작업 시작 시점 포트 확정: {G_FLASK_PORT}, {G_SIGNAL_PORT}, {G_BRIDGE_PORT}")

    # [V125.7] 🔌 작업 시작 시점에 수신기/브릿지 서버를 선제적으로 깨워줍니다냥!
    if IS_COLAB_MODE(trans_mode):
        _start_colab_receiver_if_needed()

    saved_urls = settings.data.get("colab_urls", [])
    colab_pool = get_colab_urls(saved_urls, trans_mode)

    if colab_pool is None:
        return None

    # [V108.9] 🔗 전역 배정기(G_COLAB_POOL)와 완벽 동기화! 🛡️✨
    G_COLAB_POOL = colab_pool
    print(f" ✅ {C.GREEN}[풀 동기화]{C.RESET} 전역 배정기(G_COLAB_POOL)가 최신 일꾼들로 업데이트되었습니다냥! 🚽💎")

    settings.data["colab_urls"] = colab_pool.to_list()
    settings.save()
    return colab_pool

# [V102.8] 새치기 방지용 진입 락 (번호표 시스템) 🎟️🛡️
G_COLAB_CONNECT_LOCK = threading.Lock()

# [TAG: #@check_colab_server]
def check_colab_server(colab_pool_or_url: Any, trans_mode: str, settings=None) -> Any:
    """코랩 서버 연결 상태를 점검합니다.
    성공 시 해당 객체(또는 URL)를 반환합니다.
    실패 시 사용자에게 재시도/URL 재입력 기회를 제공합니다.
    """
    import requests as _req
    _headers = {
        'Bypass-Tunnel-Reminder': 'true',
        'User-Agent': 'python-requests/2.31.0',
        'ngrok-skip-browser-warning': 'true'
    }

    _max_retries = 9999 # [V80.4] 무한에 가까운 재시도 (사용자 요청 반영 ♾️)
    _retry_count = 0

    _endpoint = "/translate" if IS_COLAB_TRANSLATE_MODE(trans_mode) else "/transcribe"
    _test_kwargs = {"json": {"text": "hi"}} if IS_COLAB_TRANSLATE_MODE(trans_mode) else {}

    # 로컬 변수로 관리
    colab_obj = colab_pool_or_url

    # [V102.8] 번호표 뽑기: 앞사람이 들어갈 때까지 대기냥! 🎟️
    with G_COLAB_CONNECT_LOCK:
        # [V125.7] 🔌 온디맨드 서버 가동: 체크 진입 시점에 브릿지 서버가 꺼져 있다면 깨워줍니다냥!
        _conn_mode = settings.data.get('colab_connection_mode', 0) if settings else 0
        if _conn_mode == 1: # Direct Bridge (IP) 모드일 때
             _start_colab_receiver_if_needed()

        while True:
            # 현재 테스트할 URL 추출
            target_url = colab_obj
            if hasattr(colab_obj, 'get_url'):
                target_url = colab_obj.get_url()
            elif not isinstance(colab_obj, str) and colab_obj is not None:
                target_url = str(colab_obj)

            if not target_url:
                print("\r\n ⚠️ 등록된 코랩 서버가 없습니다. 새로 설정합니다...")
                new_url = prompt_input("\r\n👉 코랩 접속 주소 (https://...): ").strip()
                if not new_url:
                    return colab_obj # 취소 시 원본 반환 (None 등)

                if hasattr(colab_obj, 'add_url'):
                    colab_obj.add_url(new_url)
                    target_url = colab_obj.get_url()
                else:
                    colab_obj = new_url
                    target_url = new_url

                if settings:
                    settings.data["colab_url"] = target_url # 호환성을 위해 단일 URL 저장
                    settings.save()

            print(f"\r\n ⏳ [사전 점검] 코랩 서버({target_url}) 연결 상태를 확인합니다...")
            _check_ok = False
            _check_err_msg = ""

            # [V78.5] 다이렉트 브릿지(127.0.0.1) 상황에서는 가벼운 핸드쉐이크(/ping) 사용 및 불필요 헤더 제거 🛡️
            _is_direct = "127.0.0.1" in target_url or "localhost" in target_url
            _current_headers = _headers.copy()
            if _is_direct:
                _current_headers.pop('Bypass-Tunnel-Reminder', None)
                _current_headers.pop('ngrok-skip-browser-warning', None)
                _current_headers['Connection'] = 'close' # 브릿지 세션 꼬임 방지

                # [V102.2] 브릿지 하드웨어 워밍업: 비동기 핸드쉐이크 덕분에 대기 시간을 대폭 단축(2s -> 0.5s)! ⏱️🚀
                if _retry_count == 0:
                    print(f" ⏳ {C.DIM}[Direct Bridge] 연결 즉시 확인 중...{C.RESET}")
                    time.sleep(0.5)

            try:
                if _is_direct:
                    # 다이렉트 모드: 가벼운 GET /ping 사용
                    _res = _req.get(target_url.rstrip('/') + "/ping", headers=_current_headers, timeout=15)
                else:
                    # 기존 모드: POST /translate or /transcribe (Tunnel bypass 포함)
                    _res = _req.post(
                        target_url.rstrip('/') + _endpoint,
                        headers=_current_headers,
                        timeout=30,
                        **_test_kwargs
                    )

                # [V78.8] 400 에러(Translation model not loaded)는 서버 가동은 확인된 것이므로 성공으로 간주 🛡️
                if _res.ok or _res.status_code == 400:
                    _check_ok = True
                else:
                    _check_err_msg = f" ❌ [실패] 코랩 서버가 비정상 응답({_res.status_code})을 반환했습니다."
            except Exception as _err:
                # [V79.6] Direct Bridge(127.0.0.1:5000) 통신 중 발생하는 '강제 종료(10054)' 또는 '연결 거부(10061)' 에러 처리
                _err_str = str(_err)
                if _is_direct and ("10054" in _err_str or "10061" in _err_str or "Connection aborted" in _err_str):
                    if "10061" in _err_str:
                        # [V121.5] 연결 거부는 브릿지 자체가 꺼진 것! 자동으로 깨워줍니다냥! 🔌⚡
                        print(f"\r 🔌 {C.YELLOW}[Direct Bridge]{C.RESET} 로컬 서버가 꺼져 있어냥! 자동으로 다시 깨울게냥! ✨   ", end="", flush=True)
                        try:
                            _start_colab_receiver_if_needed()
                            time.sleep(1.0) # 기동 시간 확보
                        except Exception as e:
                            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                            if "6" not in str(e):
                                _log_to_file(f"⚠️ [Silent Exception] {e}")
                        _check_err_msg = " ⚠️ [Retry] 브릿지 서버를 재가동했습니다. 잠시 후 다시 시도합니다."
                    else:
                        # 10054는 서버(브릿지)는 떠있지만 코랩 세션이 없을 때 발생함
                        reg_count = 0
                        if isinstance(colab_obj, ColabPool): reg_count = colab_obj.active_count
                        elif G_COLAB_POOL: reg_count = G_COLAB_POOL.active_count

                        if reg_count > 0:
                            print(f"\r\n ✨ {C.GREEN}[Direct Bridge] 입구를 확인했다냥!{C.RESET} 바로 입장할게냥!")
                            return colab_obj

                        status_msg = f"대기열에 {reg_count}대 등록됨" if reg_count > 0 else "도착하지 않았어냥"
                        print(f"\r ⏳ {C.SKY}[Direct Bridge]{C.RESET} 아직 코랩이 {status_msg}! 조금만 더 기다려줄래? (대기 중...)   ", end="", flush=True)
                        _check_err_msg = f" ⚠️ [Wait] 코랩이 아직 브릿지에 연결되지 않았습니다. ({reg_count}대 대기 중)"
                else:
                    _check_err_msg = f" ❌ [연결 실패] 코랩 서버에 연결할 수 없습니다: {_err}"

            if _check_ok:
                print(" ✔️ [테스트 통과] 코랩 서버가 정상 응답합니다!\r\n")
                return colab_obj

            # 실패 시 재시도 로직
            if _retry_count < _max_retries:
                _retry_count += 1
                print(f"\r\n{_check_err_msg}")
                # [V102.5] 초인종 반응성 극대화: 재시도 대기 시간을 10초 -> 1초로 단축냥! ⚡
                print(" 🔄 즉시 재접속을 시도합니다... [Enter: 건너뛰고 수동 설정으로]")

                # [수정] Enter 입력 시 즉시 재시도 건너뛰기 로직
                _user_cancelled = False
                if os.name == 'nt':
                    import msvcrt
                    while msvcrt.kbhit(): msvcrt.getch()
                    for _countdown in range(1, 0, -1):
                        sys.stdout.write("\r    ⏰ 재접속 대기 중... (Enter: 건너뛰고 수동 메뉴로) ")
                        sys.stdout.flush()
                        for _ in range(10):
                            time.sleep(0.1)
                            if msvcrt.kbhit():
                                if msvcrt.getch() in (b'\r', b'\r\n'):
                                    _user_cancelled = True; break
                        if _user_cancelled: break
                else:
                    import select
                    for _countdown in range(1, 0, -1):
                        sys.stdout.write("\r    ⏰ 재접속 대기 중... (Enter: 건너뛰고 수동 메뉴로) ")
                        sys.stdout.flush()
                        _rlist, _, _ = select.select([sys.stdin], [], [], 1.0)
                        if _rlist:
                            sys.stdin.readline()
                            _user_cancelled = True; break

                if _user_cancelled:
                    print("\r\n    ⏎ 사용자가 재시도를 취소하고 수동 메뉴로 이동합니다.")
                    _retry_count = _max_retries
                else:
                    print("\r    🔄 재접속 시도 중...                             ")
                    continue

            # 자동 재시도 소진 or 사용자 취소 → 수동 선택지 제공
            if _retry_count >= _max_retries and _check_err_msg:
                print(f"\r\n{_check_err_msg}")

            # 실패 시 사용자 선택
            current_urls_str = ""
            if hasattr(colab_obj, 'urls'):
                current_urls_str = ", ".join(colab_obj.urls)
            elif isinstance(colab_obj, str):
                current_urls_str = colab_obj

            print(f"\r\n 📋 현재 등록된 코랩 서버: {current_urls_str}")
            options = [
                "1️⃣ 코랩을 다시 켜고 새 주소 입력 (브라우저 자동 열림)",
                "2️⃣ 새 코랩 주소 직접 입력",
                "3️⃣ 점검 무시하고 강제 진행",
                "❌ 취소 (메인 메뉴로 이동)"
            ]
            choice, _, *_ = _interactive_menu("옵션을 선택해주세요", options, cols=1)
            if choice < 0: break

            new_url = ""
            if choice == 3:
                print("\r\n 🚫 연결 점검을 중단하고 메인 메뉴로 돌아갑니다.")
                return None
            elif choice == 2:
                print(" ⚠️ 점검을 건너뛰고 강제 진행합니다. 서버가 꺼져있으면 오류가 발생할 수 있습니다.\r\n")
                return colab_obj
            elif choice == 1:
                new_url = prompt_input("\r\n👉 새 코랩 접속 주소 (https://...): ").strip()
                if new_url.startswith("http"):
                    if hasattr(colab_obj, 'add_url'): colab_obj.add_url(new_url)
                    else: colab_obj = new_url
                    print(f" 📡 새 주소 추가됨. 다시 점검합니다: {new_url}")
                else:
                    print(" ⚠️ 올바른 주소가 아닙니다. 기존 주소로 재시도합니다.")
            else: # choice == 0: 코랩 브라우저 열기
                _copy_colab_code_to_clipboard(trans_mode)
                delayed_open_browser(
                    "https://colab.research.google.com/#create=true",
                    "구글 코랩(Colab) 새 창을 엽니다"
                )
                new_url = prompt_input("\r\n👉 새로 발급된 코랩 접속 주소 (https://...): ").strip()
                if new_url.startswith("http"):
                    if hasattr(colab_obj, 'add_url'): colab_obj.add_url(new_url)
                    else: colab_obj = new_url
                    print(f" 📡 새 주소 추가됨. 점검합니다: {new_url}")
                else:
                    print(" ⚠️ 올바른 주소가 아닙니다. 기존 주소로 재시도합니다.")
    return colab_obj

# [TAG: #@get_model_selection]
def get_model_selection(default_idx: int = 0, auto_skip: bool = False, manual_only: bool = False, prefix: str = "", trans_mode: str = "") -> Tuple[int, str, bool, str]:
    """Interactively get model selection and translation tone."""
    if IS_GEMINI_CLI_MODE(trans_mode):
        # [V18.9] AI냥 요청: CLI 모드에서도 'auto'를 기본으로 하여 유연하게 대처냥! 🤖
        return 0, "auto", False, ""

    title = "🤖 어떤 AI 모델을 써서 번역해볼까?"
    options = [
        " 0️⃣  CLI 기본값 사용 (Auto 🤖)",
        " 1️⃣  Gemini 3.1 Pro (최강 성능 🧠)",
        " 2️⃣  Gemini 3 Flash (속도+품질 ⚡)",
        " 3️⃣  Gemini 3.1 Flash Lite (최적화 🛰️)",
        " 4️⃣  Gemini 2.5 Pro (안정적)",
        " 5️⃣  Gemini 3.5 Flash (추천 ⭐)",
        " 6️⃣  Gemini 2.5 Flash Lite (초경량)",
        " ❌ 이전 메뉴로 돌아가기"
    ]
    timeout = 0
    if not auto_skip:
        print("\r\n  ┌───────────────────────────────────────────────────────────┐")
        print(f"  │  💡 {ctext('AI가 음성을 직접 듣고 자막을 생성합니다.', C.CYAN)}          ")
        print(f"  │  🎯 {ctext('모델 성능이 좋을수록 번역 품질이 올라가요!', C.YELLOW)}      ")
        print("  │  ⚡ 속도가 중요하면 Lite, 품질이 중요하면 상위 모델 추천  ")
        print("  └───────────────────────────────────────────────────────────┘")
    idx, triggered, *_ = _interactive_menu(title, options, default_idx, auto_skip, timeout=timeout)
    if idx < 0: return -1, "", False, "" # [V77.5 Globalizer] 언팩 에러 방지용 튜플 반환 🛡️

    manual_now = manual_only or triggered

    # 매핑: 메뉴 인덱스 -> 실제 모델명
    mapping = {
        0: "auto",
        1: "gemini-3.1-pro-preview",
        2: "gemini-3-flash-preview",
        3: "gemini-3.1-flash-lite-preview",
        4: "gemini-2.5-pro",
        5: "gemini-3.5-flash",
        6: "gemini-2.5-flash-lite"
    }
    cancel_idx = 7

    if idx == cancel_idx: # 취소 선택
        return -1, None, False, ""

    selected_model = mapping.get(idx, "gemini-2.5-flash-lite")

    # [V8.7] 고성능 모델 전용: 영상 장르별 맞춤형 번역톤 설정
    extra_tone_prompt = ""
    B, G, Y, W, R = C.BOLD, C.GREEN, C.YELLOW, C.WHITE, C.RESET

    if not auto_skip and "lite" not in selected_model.lower():
        tone_options = []
        for k, v in TRANSLATION_TONES.items():
            line = f"{_fmt_num(k)} {v['label']}"
            if "desc" in v:
                # [V20.2] 메뉴 옆에 한국어 설명 추가
                line += f" - {v['desc']}"
            tone_options.append(line)
        tone_options.append(" ❌ 취소 (이전 메뉴로)")

        tone_idx, _, *_ = _interactive_menu("🎭 영상의 분위기에 맞춰 번역톤을 설정할까?", tone_options, default_idx=0, timeout=0)
        if tone_idx < 0: return "-1", "-1", False, None # [V77.5 Globalizer]

        if tone_idx == len(TRANSLATION_TONES): # 취소 선택
            return -1, None, False, ""

        tone_key = tone_idx + 1
        tone_data = TRANSLATION_TONES.get(tone_key, TRANSLATION_TONES[1])

        if tone_data["prompt"] == "CUSTOM":
            custom_tone = prompt_input(f"\r\n {G}👉 원하는 말투를 짧게 설명해줘: {R}").strip()
            extra_tone_prompt = f"Tone: {custom_tone}" if custom_tone else ""
        else:
            extra_tone_prompt = tone_data["prompt"]

    if not auto_skip:
        # [사용자님 요청] 모델 선택 즉시 프롬프트 확인 상자 출력
        reset = "\033[0m"
        print(f"\r\n{Y}╔" + "═" * 70 + "╗")
        print(f"║ 🤖 {B}[AI Configuration]{R} Model: {Y}{selected_model}{R}")
        print("╟" + "─" * 70 + "╢")
        print(f"║ 📌 {G}System Role{R}")
        print("║    - Master Korean Video Translator (Natural & Human-like)")
        print(f"║    - ALWAYS output {W}valid JSON{R}")
        print("║")
        print(f"║ 📝 {G}Prompt Instructions{R}")
        print(f"║    1. {W}COMPLETE COVERAGE:{R} No omissions.")
        print(f"║    2. {W}STYLE:{R} Natural spoken Korean context. {f'({B}{extra_tone_prompt}{R})' if extra_tone_prompt else ''}")
        print(f"║    3. {W}SYNC:{R} Precise start/end timestamp matching.")
        print(f"║    4. {W}FORMAT:{R} Maintain JSON array structure strictly.")
        print("╚" + "═" * 70 + f"╝{reset}\r\n")

    return idx, selected_model, manual_now, extra_tone_prompt

# [TAG: #@get_gemma_model_selection]
def get_gemma_model_selection(default_key: str = "4b_it", auto_skip: bool = False, manual_now: bool = False, prefix: str = "") -> Tuple[int, str, bool]:
    """[V23.1] 로컬 Gemma 모델 체급 선택 메뉴 (고유 키 기반 리팩토링 - 밀림 방지)"""
    title = "🧠 Gemma [원어->한글번역] 모델 체급은 어느 정도가 좋을까?"
    options = [
        " 1️⃣  TranslateGemma 4B  (번역특화 / 보급형 GPU)",
        " 2️⃣  TranslateGemma 12B (번역특화 / 고정밀 / 추천 ⭐)",
        " 3️⃣  Gemma-3 4B         (최신 / 강력추천 / Power)",
        " 4️⃣  Gemma-3 12B        (최신 / 고품질 / RTX 3060)",
        " ❌ 이전 메뉴로 돌아가기"
    ]
    size_map = {
        0: "4b_trans", 1: "12b_trans",
        2: "4b_it", 3: "12b_it"
    }

    # 키(Key) -> 인덱스(Index) 역방향 매핑 (기본값 설정용)
    idx_map = {v: k for k, v in size_map.items()}
    default_idx = idx_map.get(default_key, 0)

    if auto_skip and default_idx < len(options) - 1:
        return default_idx, size_map[default_idx], manual_now

    choice, triggered, *_ = _interactive_menu(title, options, default_idx=default_idx, timeout=0, prefix=prefix)
    if choice < 0: return None # [V77.5 Globalizer]

    if choice == len(options) - 1:  # 취소 선택
        return -1, default_key, False

    manual_now = manual_now or triggered
    selected_key = size_map.get(choice, default_key)
    return choice, selected_key, manual_now

