# [TAG: #@get_cleanup_mode]
def get_cleanup_mode(default_idx: int = 0, auto_skip: bool = False, manual_only: bool = False, prefix: str = "") -> Tuple[int, int, bool]:
    """Interactively get temp file cleanup preference."""
    title = "🧹 임시 파일들은 어떻게 정리해줄까?"

    options_map = [
        {"label": " 1️⃣  휴지통 (Trash) - 추천. 디스크 공간 절약", "key": "trash", "val": 0},
        {"label": " 2️⃣  완전 삭제 (Permanent Delete) - 복구 불가, 즉시 최적화 🔥", "key": "perm_del", "val": 1},
        {"label": " 3️⃣  파일 유지 (Keep Files) - 디버깅 및 소스 보존", "key": "keep", "val": 2},
        {"label": " ❌ 이전 메뉴로 돌아가기", "key": "cancel", "val": -1}
    ]
    options = [item["label"] for item in options_map]

    timeout = 0
    sel_idx, triggered, *_ = _interactive_menu(title, options, default_idx, auto_skip, timeout=timeout)
    if sel_idx < 0 or sel_idx >= len(options_map):
        return -1, -1, False

    sel_key = options_map[sel_idx]["key"]

    if sel_key == "cancel": # 취소 선택
        return -1, -1, False

    manual_now = manual_only or triggered
    cleanup_val = options_map[sel_idx]["val"]

    # 설정에 쓸 목적으로 기존 인덱스와 동일하게 반환
    idx = sel_idx

    labels = ["휴지통 (Trash)", "완전 삭제 (Permanent Delete)", "파일 유지 (Keep Files)"]
    if not auto_skip and 0 <= cleanup_val < len(labels):
        pass # placeholder or remove if redundant
    return idx, cleanup_val, manual_now

# [TAG: #@get_skip_existing_mode]
def get_skip_existing_mode(default_idx, auto_skip, manual_only=False, file_count=0, prefix: str = ""):
    """이미 자막이 있는 경우 건너뛸지 설정합니다. 파일이 하나면 자동으로 '새로 만들기'로 진행합니다."""
    if file_count == 1:
        # 파일이 하나면 묻지 않고 '무시하고 새로 만들기'(1) 리턴
        return 1, manual_only

    title = "🆕 이미 자막(.srt)이 있는 경우 어떻게 할까?"

    options_map = [
        {"label": " 1️⃣  기존 자막 있으면 건너뛰기 (추천 ⭐)", "key": "skip", "val": 0},
        {"label": " 2️⃣  무시하고 새로 만들기", "key": "overwrite", "val": 1},
        {"label": " ❌ 이전 메뉴로 돌아가기", "key": "cancel", "val": -1}
    ]
    options = [item["label"] for item in options_map]

    sel_idx, triggered, *_ = _interactive_menu(title, options, default_idx, auto_skip, timeout=0)
    if sel_idx < 0 or sel_idx >= len(options_map):
        return -1, False

    sel_key = options_map[sel_idx]["key"]

    if sel_key == "cancel": # 취소 선택
        return -1, False

    manual_now = manual_only or triggered
    idx = options_map[sel_idx]["val"]

    if not auto_skip:
        pass
    return idx, manual_now

