# [TAG: #@get_watcher_whisper_model]
def get_watcher_whisper_model(settings):
    """백그라운드 감시 환경에 최적화된 Whisper 모델을 감지하고 로드합니다."""
    priority = ["large-v3", "medium", "small", "base"]
    try:
        hf_home = os.environ.get("HF_HOME") or os.environ.get("HUGGINGFACE_HUB_CACHE") or os.environ.get("TRANSFORMERS_CACHE")
        if hf_home:
            hf_hub_path = hf_home if "hub" in hf_home.lower() else os.path.join(hf_home, "hub")
        else:
            hf_hub_path = os.path.expanduser("~/.cache/huggingface/hub")

        if os.path.exists(hf_hub_path):
            found_models = []
            items = os.listdir(hf_hub_path)
            for item in items:
                for p_model in priority:
                    if p_model in item.lower() and "whisper" in item.lower():
                        found_models.append(p_model)
            for p_model in priority:
                if p_model in found_models: return p_model
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")
    return settings.data.get('whisper_model_idx_watcher', "base")

# [TAG: #@detect_audio_language]
def detect_audio_language(v_path, local_whisper, silent=False):
    """Whisper 모델을 사용하여 영상의 주 언어를 정밀 스캔합니다. (전역 표준화 버전)
    [V110.12] 3중 샘플링 투표 시스템(Tri-Point Voting) 도입 🕵️‍♂️🔍
    - [V110.13] 파일명 기반 일본어 휴리스틱(Heuristic) 선행 감지 추가 🎌🏎️
    """
    # [V16.3.2] 감지 실패 시 'unknown' 대신 None을 반환하여 위스퍼 엔진 오류 방지 🛡️✨
    if not local_whisper: return None, 0.0

    # [V110.13] 파일명 기반 일본어 휴리스틱 (사용자님 요청: FC2 등 자동 감지) 🎌
    v_name = os.path.basename(v_path).lower()

    # 1. 주요 일본 영상 접두사 및 레이블 🎨
    ja_marks = [
        'fc2', 'carib', 'heyzo', 'pondo', 'mgs', 'tokyo-hot', 'paco', 'muramura',
        '10musume', 'kin8tian', 'caribbeancom', 'heydouga', 'mywife', 'natural-high',
        'silk', 'star', 'prestige', 'ideapocket', 'moodyz', 's1', 'sod', 'ipx', 'ssni',
        'snis', 'ebod', 'mide', 'pred', 'jufe', 'jul', 'abp', 'adn', 'atid', 'dava'
    ]

    is_ja_heuristic = False
    match_reason = ""

    if any(v_name.startswith(p) for p in ja_marks):
        is_ja_heuristic = True
        match_reason = "전용 접두사 매칭"
    elif re.search(r'[a-z]{2,5}-\d{2,5}', v_name): # JAV 규격 (ABC-123 형식)
        is_ja_heuristic = True
        match_reason = "JAV 표준 규격(Code-Num) 매칭"
    elif re.search(r'[\u3040-\u30ff]', v_name): # 일본어 문자(히라가나/가타카나) 포함
        is_ja_heuristic = True
        match_reason = "일본어 문자(히라가나/가타카나) 포함"

    if is_ja_heuristic:
        if not silent:
            bg_print(f" 🎯 {C.SKY}[휴리스틱 감지]{C.RESET} {match_reason} -> {C.YELLOW}ja{C.RESET} 확정 🎌")
        return "ja", 1.0

    # [V110.12] 스캔 포인트 지능형 배치 (인트로 무음/음악 구간 회피)
    scan_points = [10, 70, 130] # 약간의 오프셋을 두어 인트로 바로 다음부터 스캔 🎯
    results = []

    # 영상의 전체 길이 확인 (짧은 영상 대응용)
    total_duration = 300 # 기본 5분 가정
    try:
        import cv2
        _cap = cv2.VideoCapture(v_path)
        if _cap.isOpened():
            _frames = _cap.get(cv2.CAP_PROP_FRAME_COUNT)
            _fps = _cap.get(cv2.CAP_PROP_FPS)
            if _fps > 0: total_duration = _frames / _fps
        _cap.release()
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")

    if not silent:
        bg_print(f" 🎯 {C.SKY}[정밀 스캔 시작]{C.RESET} '{os.path.basename(v_path)}' 언어 분석 중...")

    for i, offset in enumerate(scan_points):
        # 영상이 스캔 포인트보다 짧으면 0초로 강제 이동하거나 종료
        if offset >= total_duration:
            if i == 0: offset = 0
            else: break # 더 이상 스캔할 지점이 없음

        try:
            # [V110.12] clip_start를 사용하여 해당 시점부터 30초간 분석
            _segs, _info = local_whisper.transcribe(
                v_path, clip_start=offset, clip_duration=30,
                beam_size=10, vad_filter=True, initial_prompt="Detecting video language context."
            )
            for _s in _segs: break # Generator 소모 및 결과 확정

            results.append({'lang': _info.language, 'prob': _info.language_probability, 'offset': offset})
            if not silent:
                bg_print(f"   ∟ {i+1}차 스캔({offset}s): {C.YELLOW}{_info.language}{C.RESET} (신뢰도: {_info.language_probability:.2f})")

            # [최적화] 1·2차 결과 일치 시 즉시 종료 (Early Exit) 🏎️✨
            if len(results) >= 2 and results[-1]['lang'] == results[-2]['lang']:
                if not silent:
                    bg_print(f"   💡 {C.GREEN}1·2차 결과 일치! 정밀 스캔 조기 종료(Skip 3rd).{C.RESET}")
                break
        except Exception as e:
            if not silent: bg_print(f"   ⚠️ {i+1}차 스캔 중 오류: {e}")

    if not results: return None, 0.0

    # 투표 알고리즘 (Majority Vote) 🗳️
    counts = {}
    for r in results: counts[r['lang']] = counts.get(r['lang'], 0) + 1

    winner_lang = max(counts, key=counts.get)
    if counts[winner_lang] >= 2:
        max_prob = max([r['prob'] for r in results if r['lang'] == winner_lang])
        return winner_lang, max_prob
    else:
        # 다수결이 안 되면 전체 지점 중 신뢰도가 가장 높은 녀석 선택
        best_res = max(results, key=lambda x: x['prob'])
        return best_res['lang'], best_res['prob']

# [TAG: #@run_auto_translate_pipeline]
def run_auto_translate_pipeline(v_path, settings, colab_pool=None, trans_mode=None):
    """감지된 비디오에 대해 사전에 정의된 메인 번역 파이프라인을 가동합니다."""
    global _G_IS_TRANSLATING
    _G_IS_TRANSLATING = True
    try:
        # [V98.7] AI냥 요청: 외부 주입 trans_mode가 있으면 우선 사용, 없으면 설정 복구 🚀✨
        if trans_mode is None:
            # 1. 번역 모드 및 모델 설정 복구
            selected_trans_idx = safe_int(settings.data.get("trans_mode_idx", 0), default=0)
            # [V21.0] 정수 맵 대신 상수를 직접 사용하도록 통일 (스킵 현상 방지)
            trans_mode_map = {
                0: MODE_GEMINI_DIRECT_1STEP,
                1: MODE_GEMINI_DIRECT_2STEP,
                2: MODE_WHISPER_GEMINI_PURE,
                3: MODE_WHISPER_GEMINI_BILINGUAL,
                4: MODE_COLAB_WHISPER_GEMINI,
                5: MODE_COLAB_WHISPER_GEMMA_FREE,
                6: MODE_WHISPER_GEMMA_4B_LOCAL,
                7: MODE_LOCAL_VAD_CHECK
            }
            trans_mode = trans_mode_map.get(selected_trans_idx, MODE_GEMINI_DIRECT_1STEP)

        # [V2.0] 번역 톤 설정 복구
        extra_tone_prompt = settings.data.get("extra_tone_prompt", "")

        model = None
        # [추가] 코랩 모드일 때 대시보드용 모델 명칭 보정
        if IS_COLAB_TRANSLATE_MODE(trans_mode):
            if settings:
                settings.data["model_name"] = "Gemma-3-12B-Korean"

        if trans_mode not in ["colab_whisper_gemma_free", "colab_whisper_gemini", MODE_COLAB_GEMMA4_E4B] and not IS_COLAB_TRANSLATE_MODE(trans_mode):
            global API_KEYS, API_KEY_IDX
            API_KEYS = get_api_keys()
            if not API_KEYS:
                raise ValueError("등록된 API 키가 없습니다.")

            raw_key_idx = settings.data.get("api_key_idx", 0)
            API_KEY_IDX = int(raw_key_idx) % max(1, len(API_KEYS))
            genai.configure(api_key=API_KEYS[API_KEY_IDX])

            selected_model_idx = safe_int(settings.data.get("model_idx", 0), default=0)
            model_mapping = {0: "gemini-3-flash-preview", 1: "gemini-3.5-flash", 2: "gemini-2.5-flash-lite"}
            selected_model_name = model_mapping.get(selected_model_idx, "gemini-3-flash-preview")

            model = genai.GenerativeModel(
                model_name=selected_model_name,
                system_instruction="You are a Master Korean Video Translator. ALWAYS translate natural, human-like Korean. ALWAYS output valid JSON."
            )

        # 2. 파이프라인 파라미터 구성
        chunk_dur_map = [60, 120, 180, 300, 600, 999999]
        c_idx = safe_int(settings.data.get("chunk_duration_idx", 3), default=0)
        chunk_duration_sec = chunk_dur_map[c_idx] if c_idx < len(chunk_dur_map) else 300

        whisper_sizes = ["base", "small", "medium", "large-v3"]
        w_idx = safe_int(settings.data.get("whisper_idx", 0), default=0)
        whisper_size_val = whisper_sizes[w_idx] if w_idx < len(whisper_sizes) else "base"
        if trans_mode in [MODE_GEMINI_CLI_AUDIO_ONESTEP, MODE_COLAB_GEMMA4_E4B, MODE_AGY_AUDIO_ONESTEP, MODE_AGY_ADAPTIVE_PIPELINE]:
            whisper_size_val = "tiny"

        cleanup_temp = safe_int(settings.data.get("cleanup_idx", 0), default=0)

        # 3. 코랩 모드 체크
        if IS_COLAB_MODE(trans_mode):
            colab_pool = init_colab_pool(trans_mode, settings)
            if colab_pool is None:
                print(f"\r\n ⚠️ {C.YELLOW}코랩 연결이 취소되었습니다. 파이프라인을 중단합니다.{C.RESET}")
                return False
            colab_pool = check_colab_server(colab_pool, trans_mode, settings)

        # ★ 메인 파이프라인 가동!
        return process_video_file(
            v_path,
            translation_mode=trans_mode,
            model=model,
            trans_mode=trans_mode,
            cleanup_mode=cleanup_temp,
            chunk_duration_sec=chunk_duration_sec,
            whisper_size=whisper_size_val,
            colab_pool=colab_pool,
            settings=settings,
            extra_tone_prompt=extra_tone_prompt,
            show_cli_output=False
        )
    except Exception as ex:
        with open("watcher_error.log", "a", encoding="utf-8") as f:
            f.write(f"\r\n[{time.ctime()}] Pipeline Error: {ex}\r\n")
        return False
    finally:
        _G_IS_TRANSLATING = False


# [TAG: #@_add_to_shopping_cart]
def _add_to_shopping_cart(file_path: str, s_obj=None, reason: str = "") -> bool:
    """[신규] 다운로드 완료된 파일 등을 장바구니(shopping_cart)에 안전하게 자동 등록하고,
    설정된 자동 자막/스파크 번역 등의 파이프라인을 즉각 가동합니다! 🛒⚡✨"""
    if not file_path or not os.path.exists(file_path):
        return False
    try:
        if s_obj is None:
            s_obj = globals().get('settings') or globals().get('settings_ref')
            if not s_obj:
                try:
                    s_obj = SettingsManager(SETTINGS_FILE)
                    s_obj.load()
                except Exception:
                    s_obj = None
        if not s_obj:
            return False

        s_obj.load()
        cart = s_obj.data.setdefault('shopping_cart', {})
        t_abs = os.path.abspath(file_path)
        t_norm = os.path.normcase(t_abs)

        already_exists = False
        if isinstance(cart, dict):
            found_key = next((k for k in cart.keys() if os.path.normcase(os.path.abspath(k)) == t_norm), None)
            if found_key:
                already_exists = True
            else:
                cart[t_abs] = time.time()
        elif isinstance(cart, list):
            found_item = next((p for p in cart if os.path.normcase(os.path.abspath(p)) == t_norm), None)
            if found_item:
                already_exists = True
            else:
                cart.append(t_abs)

        if not already_exists:
            try:
                _hq_dir = os.path.join(BASE_DIR, "scripts")
                if _hq_dir not in sys.path: sys.path.insert(0, _hq_dir)
                import harvest_queue
                harvest_queue.add_to_harvest_queue(t_abs)
            except Exception:
                pass

            s_obj.save()
            try:
                if '_invalidate_view_caches' in globals():
                    globals()['_invalidate_view_caches']()
            except Exception:
                pass

            _name = os.path.basename(file_path)
            _log_to_file(f"🛒 [Auto Cart] '{_name}' 장바구니 자동 등록 완료! (사유: {reason})")

            # 사운드 알림 및 토스트 알림
            try:
                _play_cart_sound(is_added=True)
            except Exception:
                pass

            _msg = f"🛒 [장바구니 담김] {_name[:30]}"
            globals()['_last_bg_notification'] = _msg
            globals()['_last_bg_notification_time'] = time.time()
            globals()['_global_menu_redraw_flag'] = True

            try:
                _show_windows_toast(_msg)
            except Exception:
                pass

            # 장바구니 자동 연동 트리거 (자막 자동 생성, 구글드라이브 자동 추출, 스파크 번역)
            if s_obj.data.get('cart_auto_subtitle', False):
                _check_and_trigger_cart_auto_subtitle(s_obj)
            if s_obj.data.get('cart_auto_gdrive_extract', False):
                _check_and_trigger_cart_auto_gdrive_extract(s_obj)
            if s_obj.data.get('cart_auto_spark_translate', False):
                _check_and_trigger_cart_spark_translate(s_obj)

            return True
        return False
    except Exception as e:
        _log_to_file(f"⚠️ [_add_to_shopping_cart] Error: {e}")
        return False

# [V6.5] Flask 백그라운드 자막 생성을 위한 도우미 함수
# [TAG: #@_check_and_trigger_cart_auto_subtitle]
def _check_and_trigger_cart_auto_subtitle(s_obj=None):
    """[V183.0] 장바구니(카트) 자동 자막 생성 옵션이 켜져있을 때, 카트의 자막 없는 영상들을 백그라운드 큐로 투입합니다! 🛒⚡✨"""
    try:
        if s_obj is None:
            s_obj = globals().get('settings') or globals().get('settings_ref')
            if not s_obj:
                try:
                    s_obj = SettingsManager(SETTINGS_FILE)
                    s_obj.load()
                except Exception:
                    s_obj = None
        if not s_obj or not s_obj.data.get('cart_auto_subtitle', False):
            return

        s_obj.load()
        cart = s_obj.data.get('shopping_cart', {})
        cart_keys = list(cart.keys()) if isinstance(cart, dict) else list(cart)
        if not cart_keys:
            return

        sub_ext_list = ('.srt', '.smi', '.vtt', '.ass', '.ssa', '.ko.srt', '.en.srt', '.jp.srt', '.ko.vtt')
        target_v_exts = globals().get('v_exts') or ('.mp4', '.mkv', '.avi', '.wmv', '.mov', '.flv', '.webm', '.ts', '.tp', '.m2ts')

        # [비누님 요청] 장바구니에 담긴 파일은 기존 자막 유무와 무관하게(맘에 안 들어 재요청하는 경우 포함) 모두 처리 대상! 🛒✨
        pending_files = []
        for cp in cart_keys:
            _cp_path = cp.get("path") if isinstance(cp, dict) else cp
            if not _cp_path or not os.path.exists(_cp_path):
                continue
            if not _cp_path.lower().endswith(target_v_exts):
                continue
            pending_files.append(_cp_path)

        if pending_files:
            _log_to_file(f"🛒⚡ [Cart Auto Subtitle] Found {len(pending_files)} pending files in cart. Triggering engine...")
            start_subtitle_engine(pending_files, s_obj, is_resume=True, notify_label="카트(자동)", pk='CART')
    except Exception as e:
        _log_to_file(f"⚠️ [_check_and_trigger_cart_auto_subtitle] Error: {e}")

# [TAG: #@_check_and_trigger_cart_auto_gdrive_extract]
def _check_and_trigger_cart_auto_gdrive_extract(s_obj=None):
    """[신규] 장바구니(카트) 자동 구글드라이브 추출 옵션이 켜져있을 때,
    카트의 동영상들을 MP3(64kbps)로 순차 추출 후 설정된 구글드라이브 폴더에 백그라운드로 안전하게 자동 업로드합니다! 🛒☁️✨
    TUI 화면 출력을 100% 차단(DEVNULL/PIPE)하여 화면 깨짐을 방지하고,
    완료된 파일은 settings.data['gdrive_extracted_files'][v_path] = 1 로 영구 기록하여 중복을 방지합니다! 🐈
    """
    try:
        if s_obj is None:
            s_obj = globals().get('settings') or globals().get('settings_ref')
            if not s_obj:
                try:
                    s_obj = SettingsManager(SETTINGS_FILE)
                    s_obj.load()
                except Exception:
                    s_obj = None

        if not s_obj or not s_obj.data.get('cart_auto_gdrive_extract', False):
            return

        s_obj.load()

        # 구글드라이브 대상 폴더 확인
        _gdrive_dest = s_obj.data.get('audio_extract_gdrive_folder', '')
        if not _gdrive_dest:
            _gdrive_recent = s_obj.data.get('audio_extract_gdrive_folders', [])
            _gdrive_dest = _gdrive_recent[0] if _gdrive_recent else ''
        if not _gdrive_dest:
            _log_to_file("⚠️ [Cart Auto GDrive] 구글드라이브 폴더가 설정되지 않아 자동 추출을 건너뜁니다.")
            return

        # 장바구니 파일 목록
        cart = s_obj.data.get('shopping_cart', {})
        cart_keys = list(cart.keys()) if isinstance(cart, dict) else list(cart)
        if not cart_keys:
            return

        # 이미 추출/업로드 완료된 장부 로드 (영구 보관)
        extracted_map = s_obj.data.setdefault('gdrive_extracted_files', {})

        target_v_exts = globals().get('v_exts') or ('.mp4', '.mkv', '.avi', '.wmv', '.mov', '.flv', '.webm', '.ts', '.tp', '.m2ts')
        pending_files = []
        for cp in cart_keys:
            _cp_path = cp.get("path") if isinstance(cp, dict) else cp
            if not _cp_path or not os.path.exists(_cp_path):
                continue
            if not _cp_path.lower().endswith(target_v_exts):
                continue
            _norm_cp = os.path.normpath(os.path.abspath(_cp_path))
            # 이미 처리 완료된 파일(값 1)인지 체크
            if extracted_map.get(_norm_cp) == 1 or extracted_map.get(_cp_path) == 1:
                continue
            pending_files.append(_norm_cp)

        if not pending_files:
            return

        _log_to_file(f"🛒☁️ [Cart Auto GDrive] Found {len(pending_files)} new video(s) to process. Queueing...")

        # 이미 실행 중인지 확인 (중복 백그라운드 스레드 방지)
        _running_flag = globals().get('_cart_auto_gdrive_running', False)
        if _running_flag:
            _log_to_file("⚠️ [Cart Auto GDrive] 이미 백그라운드 작업이 실행 중입니다.")
            return

        def _bg_extract_and_upload():
            global _GDRIVE_CACHE, _GDRIVE_CACHE_TIME
            globals()['_cart_auto_gdrive_running'] = True
            try:
                ffmpeg_bin = _get_ffmpeg_bin()
                if not ffmpeg_bin:
                    _log_to_file("❌ [Cart Auto GDrive] FFmpeg을 찾을 수 없어 중단합니다.")
                    return

                rclone_exe = _ensure_rclone()
                if not rclone_exe:
                    _log_to_file("❌ [Cart Auto GDrive] Rclone을 찾을 수 없어 중단합니다.")
                    return

                # 임시 추출 폴더 준비 (절대 경로)
                _app_dir = os.path.dirname(os.path.abspath(__file__))
                _temp_extract_dir = os.path.join(_app_dir, 'temp', 'cart_gdrive_extract')
                os.makedirs(_temp_extract_dir, exist_ok=True)

                conf_path = os.path.join(_app_dir, 'temp', 'rclone.conf')
                if not os.path.exists(conf_path):
                    conf_path = os.path.join('temp', 'rclone.conf')

                actual_dest = _gdrive_dest
                _dest_account = None
                _dest_rpath = ""
                if _is_gdrive_path(_gdrive_dest):
                    _dest_account, _dest_rpath = _gdrive_parse_path(_gdrive_dest)
                    actual_dest = f"{_dest_account}:{_dest_rpath}"

                # 상단 TUI 알림 (시작)
                globals()['_last_bg_notification'] = f"☁️ [카트 구드] {len(pending_files)}개 음원 추출 및 업로드 시작..."
                globals()['_last_bg_notification_time'] = time.time()

                processed_count = 0
                for idx, v_path in enumerate(pending_files, 1):
                    try:
                        _fname = os.path.basename(v_path)
                        _name, _ = os.path.splitext(_fname)
                        _out_name = f"{_name}.mp3"
                        _out_path = os.path.join(_temp_extract_dir, _out_name)

                        # 임시 추출 폴더 내 다른 잔여 파일 정리 (현재 대상만 안전하게 격리 복사되도록)
                        try:
                            for _leftover in os.listdir(_temp_extract_dir):
                                _lf_p = os.path.join(_temp_extract_dir, _leftover)
                                if os.path.isfile(_lf_p) and _leftover != _out_name:
                                    try: os.remove(_lf_p)
                                    except Exception: pass
                        except Exception:
                            pass

                        # TUI 상단 1줄 알림 갱신
                        globals()['_last_bg_notification'] = f"🎵 [카트 추출 {idx}/{len(pending_files)}] {_fname[:25]}..."
                        globals()['_last_bg_notification_time'] = time.time()

                        # 1단계: FFmpeg 64kbps MP3 추출 (TUI 출력 완전 차단)
                        # 기존 불완전 파일 있으면 삭제
                        if os.path.exists(_out_path) and os.path.getsize(_out_path) <= 1024:
                            try:
                                os.remove(_out_path)
                            except Exception:
                                pass

                        need_extract = True
                        if os.path.exists(_out_path) and os.path.getsize(_out_path) > 1024:
                            _log_to_file(f"♻️ [Cart Auto GDrive] 이미 온전하게 추출됨, 재사용: {_out_name}")
                            need_extract = False

                        if need_extract:
                            _log_to_file(f"🎵 [Cart Auto GDrive] ({idx}/{len(pending_files)}) MP3 추출 시작: {_fname}")
                            _cmd = [
                                ffmpeg_bin, "-nostdin", "-y", "-i", v_path,
                                "-vn", "-c:a", "libmp3lame", "-b:a", "64k",
                                "-ac", "1", "-ar", "22050", _out_path
                            ]
                            _flags = 0x08000000 if os.name == 'nt' else 0
                            _proc = subprocess.run(
                                _cmd,
                                stdout=subprocess.DEVNULL,
                                stderr=subprocess.PIPE,
                                stdin=subprocess.DEVNULL,
                                creationflags=_flags,
                                timeout=600
                            )
                            if _proc.returncode != 0 or not os.path.exists(_out_path) or os.path.getsize(_out_path) <= 1024:
                                _err = _proc.stderr.decode('utf-8', errors='ignore') if _proc.stderr else 'Unknown'
                                _log_to_file(f"❌ [Cart Auto GDrive] FFmpeg 추출 실패 ({_fname}): returncode={_proc.returncode}, err={_err[:150]}")
                                continue
                            _log_to_file(f"✅ [Cart Auto GDrive] FFmpeg 추출 성공: {_out_name} ({os.path.getsize(_out_path)} bytes)")

                        # 2단계: 구글드라이브 업로드 (격리 폴더 rclone copy로 유니코드/특수문자 100% 안전 전송!)
                        globals()['_last_bg_notification'] = f"☁️ [카트 구드 {idx}/{len(pending_files)}] 업로드 중: {_out_name[:25]}..."
                        globals()['_last_bg_notification_time'] = time.time()

                        _clean_extract_dir = _temp_extract_dir.replace('\\', '/')
                        _rc_cmd = [
                            rclone_exe, 'copy', _clean_extract_dir, actual_dest,
                            '--config', conf_path,
                            '-v',
                            '--timeout', '5m',
                            '--contimeout', '1m',
                            '--retries', '3',
                            '--retries-sleep', '5s',
                            '--drive-pacer-min-sleep', '100ms'
                        ]
                        _log_to_file(f"☁️ [Cart Auto GDrive] ({idx}/{len(pending_files)}) Rclone copy 시작: {_out_name} -> {actual_dest}")
                        _rc_res = subprocess.run(
                            _rc_cmd,
                            capture_output=True,
                            text=True,
                            encoding='utf-8',
                            errors='replace',
                            creationflags=0x08000000 if os.name == 'nt' else 0,
                            timeout=600
                        )

                        _err_out = _rc_res.stderr.strip() if _rc_res.stderr else ""
                        _is_success = (_rc_res.returncode == 0) and ("ERROR :" not in _err_out) and ("Failed to copy" not in _err_out)
                        if _is_success:
                            _log_to_file(f"🎉 [Cart Auto GDrive] 업로드 성공: {_out_name}")
                            processed_count += 1

                            # 3단계: 장부에 완료 영구 기록 (1 저장)
                            try:
                                s_obj.load()
                                _extracted = s_obj.data.setdefault('gdrive_extracted_files', {})
                                _extracted[v_path] = 1
                                _extracted[os.path.normpath(os.path.abspath(v_path))] = 1
                                s_obj.save()
                            except Exception as _save_e:
                                _log_to_file(f"⚠️ [Cart Auto GDrive] 장부 저장 실패: {_save_e}")

                            # 4단계: 업로드 완료된 임시 MP3 파일 즉시 영구 폐기 🗑️
                            try:
                                if os.path.exists(_out_path):
                                    try:
                                        os.remove(_out_path)
                                        _log_to_file(f"🗑️ [Cart Auto GDrive] 업로드 완료 후 임시 MP3 즉시 폐기 성공: {_out_name}")
                                    except Exception as _rm_e:
                                        _log_to_file(f"⚠️ [Cart Auto GDrive] os.remove 실패, safe_remove_file 폴백: {_rm_e}")
                                        safe_remove_file(_out_path, use_trash=False)
                            except Exception as _tr_err:
                                _log_to_file(f"⚠️ [Cart Auto GDrive] 임시 파일 정리 오류: {_tr_err}")

                            # 5단계: 구글드라이브 탐색기 인메모리 & 디스크 캐시 즉시 무효화 🔄✨
                            try:
                                if _dest_account:
                                    _rp_clean = _dest_rpath.rstrip('/')
                                    _GDRIVE_CACHE.pop((_dest_account, _rp_clean), None)
                                    _GDRIVE_CACHE_TIME.pop((_dest_account, _rp_clean), None)
                                    _GDRIVE_CACHE.pop((_dest_account, _rp_clean + '/'), None)
                                    _GDRIVE_CACHE_TIME.pop((_dest_account, _rp_clean + '/'), None)
                                    if not _rp_clean:
                                        _GDRIVE_CACHE.pop((_dest_account, ''), None)
                                        _GDRIVE_CACHE_TIME.pop((_dest_account, ''), None)
                                _save_gdrive_cache()
                                _log_to_file(f"🔄 [Cart Auto GDrive] GDrive 캐시 즉시 갱신 완료: dest={actual_dest}")
                            except Exception as _cache_e:
                                _log_to_file(f"⚠️ [Cart Auto GDrive] GDrive 캐시 무효화 실패: {_cache_e}")
                        else:
                            _log_to_file(f"❌ [Cart Auto GDrive] Rclone 업로드 실패 ({_out_name}): rc={_rc_res.returncode}, err={_err_out[:200]}")
                            globals()['_last_bg_notification'] = f"❌ [구드 업로드 실패] {_out_name[:20]}..."
                            globals()['_last_bg_notification_time'] = time.time()

                    except Exception as _item_e:
                        _log_to_file(f"❌ [Cart Auto GDrive] 개별 파일 처리 오류 ({os.path.basename(v_path)}): {_item_e}")

                # 최종 알림
                if processed_count > 0:
                    globals()['_last_bg_notification'] = f"🎉 [카트 구드] {processed_count}개 파일 업로드 완료!"
                    globals()['_last_bg_notification_time'] = time.time()
                    _log_to_file(f"🎉 [Cart Auto GDrive] 모든 작업 완료: 총 {processed_count}/{len(pending_files)}개 성공.")
                else:
                    globals()['_last_bg_notification'] = "⚠️ [카트 구드] 업로드 완료된 파일이 없습니다."
                    globals()['_last_bg_notification_time'] = time.time()

            except Exception as _bg_e:
                _log_to_file(f"❌ [Cart Auto GDrive] 백그라운드 스레드 치명적 오류: {_bg_e}")
            finally:
                globals()['_cart_auto_gdrive_running'] = False

        _t = threading.Thread(target=_bg_extract_and_upload, daemon=True, name="CartAutoGDrive")
        _t.start()
        _log_to_file(f"🚀 [Cart Auto GDrive] 백그라운드 스레드 시작 (신규 대기={len(pending_files)}, dest={_gdrive_dest})")

    except Exception as e:
        _log_to_file(f"⚠️ [_check_and_trigger_cart_auto_gdrive_extract] Error: {e}")

# [TAG: #@_run_gdrive_harvest_precheck]
def _run_gdrive_harvest_precheck(s_obj=None, timeout=120):
    """[V193.8 신규] 🌾 스파크 전송 '직전' 에 구드(구글드라이브)에 이미 완성된 자막이
    있는지 먼저 확인하고, 있으면 즉시 로컬로 수신(추수)한다! 📥✨

    🎯 [비누님 요청 2026-10-01]
       "장바구니에 들어가면 카트에 담긴 게 있으면 무조건 스파크 자막 만들기가 시작되는데,
        사실 구드에 이미 만들어진 자막이 있을 수도 있거든? 이전에 타임오버로 실패하는
        경우도 있고, 그걸 우선 체크하고, 자막 만들기가 진행되게."
       → 즉 '구드 수신을 ALWAYS 먼저, 스파크 번역은 그 다음' 순서로 뒤집는다.

    📌 판정 근거(= '자막 만들기 시도한 로그'):
       추수 대기열(temp/spark_harvest_queue.json) + 장바구니 중에서
       '아직 로컬에 자막이 없는' 항목만 후보로 본다.
       (harvest_queue.get_pending_harvest_items() 가 이미 이 선별을 해준다)

    🛡️ 안전장치:
       · 중복 실행 방지 플래그 (_cart_spark_harvest_running)
       · timeout 초과 시 자식을 kill 하고 '없음'으로 간주 → 스파크 전송을 막지 않는다
       · 수신 대상이 아예 없으면 rclone 네트워크 호출 자체를 생략한다
       · 어떤 예외든 삼키고 0건으로 돌려보내 스파크 전송을 절대 막지 않는다

    반환: (harvested_count:int, output:str)
    """
    try:
        # 보조 인스턴스(두 번째 앱 창)에서는 중복 구드 조회 방지
        if '--secondary' in sys.argv or globals().get('IS_SECONDARY_INSTANCE', False):
            return 0, ""

        _base_app_dir = os.path.dirname(os.path.abspath(__file__))
        _fetch_script = os.path.join(_base_app_dir, "scripts", "fetch_spark_subtitles.py")
        if not os.path.exists(_fetch_script):
            _log_to_file("⚠️ [Pre-Harvest] 수신 스크립트(fetch_spark_subtitles.py)가 없어 선행 수신을 건너뜁니다.")
            return 0, ""

        # 이미 다른 선행 수신(또는 수동 수신)이 돌고 있으면 중복 실행하지 않는다 🛡️
        if globals().get('_cart_spark_harvest_running', False):
            _log_to_file("⏭️ [Pre-Harvest] 선행 수신이 이미 진행 중이므로 중복 실행을 건너뜁니다.")
            return 0, ""

        # ---- ① 수신 후보 선별 (추수 대기열 + 장바구니 중 '자막 없는' 것만) ----
        _hq_dir = os.path.join(_base_app_dir, "scripts")
        if _hq_dir not in sys.path:
            sys.path.insert(0, _hq_dir)
        _pending_map = {}
        try:
            import harvest_queue as _hq
            _pending_map = _hq.get_pending_harvest_items() or {}
        except Exception as _hqe:
            _log_to_file(f"⚠️ [Pre-Harvest] 추수 대기열 조회 실패(무시하고 진행): {_hqe}")
            _pending_map = {}

        if not _pending_map:
            _log_to_file("☁️ [Pre-Harvest] 미추수 대기 항목이 없어 구드 조회를 생략합니다.")
            return 0, ""

        globals()['_cart_spark_harvest_running'] = True
        try:
            globals()['_last_bg_notification'] = f"🌾 구드에 이미 만들어진 자막이 있는지 확인 중... (후보 {len(_pending_map)}건)"
            globals()['_last_bg_notification_time'] = time.time()

            _cf = getattr(subprocess, "CREATE_NO_WINDOW", 0) if sys.platform == "win32" else 0
            _p = subprocess.Popen(
                [sys.executable, "-u", _fetch_script],
                stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                text=True, encoding='utf-8', errors='replace',
                creationflags=_cf,
            )
            try:
                _out, _ = _p.communicate(timeout=timeout)
            except subprocess.TimeoutExpired:
                # 구드가 느려도 스파크 전송을 '영구 차단'하지 않는다 ⏳
                try:
                    _p.kill()
                except Exception:
                    pass
                _log_to_file(f"⏳ [Pre-Harvest] 구드 조회 {timeout}초 초과 — 스파크 전송 단계로 진행합니다.")
                return 0, ""
            except Exception as _ce:
                _log_to_file(f"⚠️ [Pre-Harvest] 구드 조회 통신 오류: {_ce}")
                return 0, ""

            _out = _out or ""
            _saved = _out.count("자막 저장 완료") + _out.count("자막 생성 완료") + _out.count("✅ [완료]")
            _m_cnt = re.search(r'총\s*(\d+)개\s*자막이', _out)
            if _m_cnt:
                try:
                    _sc = int(_m_cnt.group(1))
                    if _sc > _saved:
                        _saved = _sc
                except Exception:
                    pass

            if _saved > 0:
                # 수신으로 settings.json 의 장바구니가 바뀌므로 최신본을 다시 읽는다 🔄
                try:
                    if s_obj:
                        s_obj.load()
                except Exception:
                    pass
                try:
                    if '_invalidate_view_caches' in globals():
                        globals()['_invalidate_view_caches']()
                except Exception:
                    pass
                _log_to_file(f"🌾 [Pre-Harvest] 구드에서 이미 만들어진 자막 {_saved}개를 먼저 받았어냥! (스파크 재전송 대상에서 자동 제외)")
            else:
                _log_to_file("☁️ [Pre-Harvest] 구드에 아직 새 자막이 없음 → 스파크 번역 전송을 진행합니다.")

            return _saved, _out
        finally:
            globals()['_cart_spark_harvest_running'] = False

    except Exception as e:
        _log_to_file(f"⚠️ [_run_gdrive_harvest_precheck] Error: {e}")
        return 0, ""

# [TAG: #@_cart_spark_has_fresh_subtitle]
def _cart_spark_has_fresh_subtitle(video_path, added_time=0):
    """[P0-1/P0-2 신규 2026-10-08] 해당 영상의 자막이 '이미 완성' 상태인지 판정한다. 🛡️

    🎯 [규칙] AGENTS.md §버그 진단 — 카트에 '이미 자막이 끝난 항목'이 남아있는데
       스파크 번역 요청이 또 들어가는 사고(자막 1/5개 번역 진행 알림의 주원인)를 원천 차단.

    판정 규칙(탐색기 카트 렌더링 / harvest_queue 와 '완전히 동일한' 기준):
       · 동일 stem 의 자막 확장자(`.ko.srt` `.srt` `.smi` `.vtt` `.ass` `.ssa`) 중 하나라도 있고
       · 그 자막의 mtime/ctime 이 '카트에 담긴 시각(added_time)'보다 뒤이면 → 새 자막 완성 ✅
       · 담긴 시각 정보가 없으면(레거시 0/None) 자막이 있으면 완성으로 간주(harvest_queue 와 동일)

    ⚠️ 보수 원칙: added_time 보다 '이전'의 자막은 미완성으로 보고 전송 허용한다
       (사용자가 "맘에 안 들어 다시 담아" 재번역 요청하는 legit 경로를 막지 않기 위함).
    """
    try:
        if not video_path:
            return False
        _base = os.path.splitext(video_path)[0]
        for _sx in ('.ko.srt', '.srt', '.smi', '.vtt', '.ass', '.ssa'):
            _sp = _base + _sx
            if not os.path.exists(_sp):
                continue
            try:
                if os.path.getsize(_sp) <= 0:
                    continue  # 빈 파일은 미완성으로 간주
            except Exception:
                continue
            if not isinstance(added_time, (int, float)) or added_time <= 0:
                return True  # 담긴 시각 정보 없음 → 자막 있으면 완성으로 간주
            try:
                _st = os.stat(_sp)
                if max(_st.st_mtime, _st.st_ctime) > added_time:
                    return True
            except Exception:
                continue
    except Exception:
        return False
    return False

# [TAG: #@_check_and_trigger_cart_spark_translate]
def _check_and_trigger_cart_spark_translate(s_obj=None, force=False):
    """[신규] 장바구니 스파크 번역 옵션이 켜져있거나 수동 강제 요청(force=True) 시,
    카트의 동영상/음원들을 64kbps MP3로 추출 후 Gemini Spark에 자동 업로드하고 /srt 스킬을 호출합니다! 🛒⚡✨
    백그라운드 스레드에서 안전하게 비동기 가동되며, TUI 화면 깨짐을 방지합니다. 🐈
    """
    try:
        if s_obj is None:
            s_obj = globals().get('settings') or globals().get('settings_ref')
            if not s_obj:
                try:
                    s_obj = SettingsManager(SETTINGS_FILE)
                    s_obj.load()
                except Exception:
                    s_obj = None

        # 미추수 자막이 남아있다면 워처 자동 복구(Keep-Alive) 동반 검사 🌾✨
        try:
            _check_and_resume_spark_harvest(s_obj)
        except Exception:
            pass

        if not force and (not s_obj or not s_obj.data.get('cart_auto_spark_translate', False)):
            return False, "장바구니 스파크 자동 번역 옵션이 꺼져있어냥!"

        # 중복 실행 방어
        if globals().get('_cart_spark_translate_running', False):
            return False, "이미 스파크 번역 작업이 백그라운드에서 실행 중이야냥! ⏳"

        # 쿨다운 (최소 10초) 방어 - force=True일 때는 즉시 전송 허용!
        _now = time.time()
        _last_time = globals().get('_last_cart_spark_time', 0)
        if not force and (_now - _last_time < 10):
            return False, "방금 전송 요청을 처리했어냥. 잠시 후 다시 시도해줘냥!"

        # 스파크 전송 스크립트 존재 확인
        _base_app_dir = os.path.dirname(os.path.abspath(__file__))
        _spark_script = os.path.join(_base_app_dir, "scripts", "send_cart_to_spark.py")
        if not os.path.exists(_spark_script):
            _log_to_file(f"⚠️ [_check_and_trigger_cart_spark_translate] 스크립트를 찾을 수 없음: {_spark_script}")
            return False, "스파크 전송 스크립트(send_cart_to_spark.py)를 찾을 수 없어냥!"

        if s_obj:
            s_obj.load()
            cart = s_obj.data.get('shopping_cart', {})
        else:
            cart = {}
        cart_keys = list(cart.keys()) if isinstance(cart, dict) else list(cart)
        if not cart_keys:
            return False, "장바구니가 비어있어냥! 먼저 파일을 담아줘냥 🛒"

        target_v_exts = globals().get('v_exts') or ('.mp4', '.mkv', '.avi', '.wmv', '.mov', '.flv', '.webm', '.ts', '.tp', '.m2ts', '.mp3', '.wav', '.m4a', '.aac', '.flac', '.ogg')

        # 이미 스파크로 전송한 이력 확인 (send_cart_to_spark.py와 동일한 normcase+abspath 정규화 방식 사용 🔑)
        _hist_file = os.path.join(_base_app_dir, "temp", "spark_sent_history.json")
        _sent_hist = {}
        if not force and os.path.exists(_hist_file):
            try:
                with open(_hist_file, 'r', encoding='utf-8', errors='ignore') as f:
                    _sent_hist = json.load(f)
            except Exception:
                _sent_hist = {}

        pending_files = []
        for cp in cart_keys:
            _cp_path = cp.get("path") if isinstance(cp, dict) else cp
            if not _cp_path or not os.path.exists(_cp_path):
                continue
            if not _cp_path.lower().endswith(target_v_exts):
                continue

            # 수동 강제 전송(force=True)이 아닐 때만 전송 이력 체크
            if not force:
                # 카트에 담긴 시각(added_time) 조회 🕒
                _cp_added_time = cart.get(_cp_path) if isinstance(cart, dict) else 0
                if not _cp_added_time and isinstance(cart, dict):
                    _norm_p = os.path.normcase(os.path.abspath(_cp_path))
                    for _k, _v in cart.items():
                        if os.path.normcase(os.path.abspath(_k)) == _norm_p:
                            _cp_added_time = _v
                            break

                # [P0-1 FIX] 이미 '새 자막'이 완성된 항목은 스파크 재전송 금지 🚫
                #    (예전엔 파일존재·확장자·sent_history 3종만 봐서 '완성/취소된 자막'이
                #     카트에 남아있으면 매 진입마다 재요청이 반복됐다 🦴)
                if _cart_spark_has_fresh_subtitle(_cp_path, _cp_added_time):
                    _log_to_file(f"⏭️ [Cart Spark] 이미 완성된 자막 보유 → 재전송 제외: {os.path.basename(_cp_path)}")
                    continue

                # 이미 스파크로 전송한 이력이 있는 경우:
                # 단, 사용자가 그 이후에 카트에 다시 담았다면(added_time > sent_time) 재번역 요청이므로 스마트하게 전송 허용! 🚀
                _norm_cp = os.path.normcase(os.path.abspath(_cp_path))
                if _norm_cp in _sent_hist:
                    _sent_ts = _sent_hist.get(_norm_cp, 0)
                    if isinstance(_sent_ts, (int, float)) and _cp_added_time and _cp_added_time > _sent_ts:
                        pass # 카트에 새로 다시 담은 파일이므로 재전송 대상 허용! ✨
                    else:
                        continue # 기존 전송 이력이 더 최신이면 건너뜀

            pending_files.append(_cp_path)

        if not pending_files:
            return False, "장바구니에 새로 전송할 동영상/음원 파일이 없어냥!"

        globals()['_last_cart_spark_time'] = _now
        # [BUG FIX] running 플래그는 스레드 시작 직전에만 설정 → Popen 이전 예외 시 영구 잠김 방지 🛡️
        globals()['_cart_spark_translate_running'] = True

        def _bg_spark_runner():
            try:
                # 🌾 [V193.8] 구드 선행 수신(Pre-Harvest) — 반드시 '스파크 전송보다 먼저' 수행한다!
                #    카트에 담긴 게 있다고 무조건 새 번역을 올리면 안 되고,
                #    이전 실행(타임아웃 등)으로 구드에 이미 완성돼 있는 자막을 먼저 받아와야 한다.
                _pre_harvested = 0
                try:
                    _pre_harvested, _pre_out = _run_gdrive_harvest_precheck(s_obj=s_obj)
                except Exception as _phe:
                    _pre_harvested = 0
                    _log_to_file(f"⚠️ [Cart Spark Translate] 선행 수신 예외(무시하고 진행): {_phe}")

                if _pre_harvested > 0:
                    # 수신으로 장바구니가 정리되었으므로 '실제 전송 대상'을 다시 계산한다 🔄
                    # ⚠️ 안전장치: 재계산을 못 하면 '없음'이 아니라 '알 수 없음'으로 취급한다.
                    #    잘못된 조기 종료로 스파크 전송을 놓치면 안 되므로 None(불확실)으로 둔다. 🛡️
                    _remaining = None
                    try:
                        if s_obj:
                            s_obj.load()
                        _cart2 = s_obj.data.get('shopping_cart', {}) if s_obj else {}
                        if isinstance(_cart2, dict):
                            _remaining = []
                            for _cp2 in _cart2.keys():
                                _p2 = _cp2.get("path") if isinstance(_cp2, dict) else _cp2
                                if not _p2 or not os.path.exists(_p2):
                                    continue
                                if not _p2.lower().endswith(target_v_exts):
                                    continue
                                # [P0-2 FIX] 재계산 경로에서도 '완성 자막' 항목을 제외한다.
                                #    선행 수신(Pre-Harvest)이 방금 내려받은 자막까지 재전송하는 것을 막는다.
                                _added2 = _cart2.get(_cp2, 0)
                                if _cart_spark_has_fresh_subtitle(_p2, _added2):
                                    continue
                                _remaining.append(_p2)
                    except Exception as _rce:
                        _log_to_file(f"⚠️ [Pre-Harvest] 전송 대상 재계산 실패(일단 전송 진행): {_rce}")
                        _remaining = None

                    if _remaining is not None:
                        globals()['_last_bg_notification'] = f"🌾 구드 자막 {_pre_harvested}개 선수신! 남은 {len(_remaining)}개만 번역"
                        globals()['_last_bg_notification_time'] = time.time()

                        if not _remaining:
                            _log_to_file("🎉 [Cart Spark Translate] 구드 선행 수신으로 전량 해결 → 스파크 전송을 건너뜁니다!")
                            try:
                                telegram_send(f"🌾 구드에 이미 만들어진 자막 {_pre_harvested}개를 먼저 받았어냥!\n남은 작업이 없어 스파크 전송은 생략했어 ✨")
                            except Exception:
                                pass
                            return  # ← 스파크 업로드 자체를 실행하지 않고 종료
                        _log_to_file(f"✅ [Pre-Harvest] {_pre_harvested}개 사전 수신 → 스파크 번역은 나머지 {len(_remaining)}개만 진행")

                # [비누님 요청] 스파크 작업 시작 시 텔레그램 알림 전송 📱✨ (예: "자막 6/13개 번역 진행 (spark)")
                try:
                    _total_cart_vids = [cp for cp in cart_keys if (cp.get("path") if isinstance(cp, dict) else cp).lower().endswith(target_v_exts)]
                    _total_cart = len(_total_cart_vids) if _total_cart_vids else len(cart_keys)
                    if force:
                        _tg_msg = f"자막 {len(pending_files)}개 낱개(1개씩) 순차 번역 진행 (spark 수동)"
                    else:
                        _cur_batch = min(len(pending_files), 6)
                        _tg_msg = f"자막 {_cur_batch}/{_total_cart}개 번역 진행 (spark)"
                    send_telegram_notification(_tg_msg, category='subtitle')
                    _log_to_file(f"📱 [Cart Spark Translate] 텔레그램 알림 전송 완료: {_tg_msg}")
                except Exception as _tg_e:
                    _log_to_file(f"⚠️ [Cart Spark Translate] 텔레그램 알림 전송 실패: {_tg_e}")

                _log_to_file(f"✨ [Cart Spark Translate] 백그라운드 스레드 가동 (대상={len(pending_files)}개, force={force})")
                _cmd = [sys.executable, "-u", _spark_script]
                if force:
                    _cmd.append("--force-all")
                    _cmd.extend(["--batch-size", "1"])  # 💡 수동 요청은 각각 낱개로 1개씩 업로드 후 /srt 호출! 🎯✨
                # TUI 화면 보호를 위해 stdout/stderr는 PIPE로 캡처하여 화면 간섭 방지
                _proc = subprocess.Popen(
                    _cmd,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.STDOUT,
                    text=True,
                    encoding='utf-8',
                    errors='replace'
                )
                if _proc.stdout:
                    for raw_line in iter(_proc.stdout.readline, ''):
                        if not raw_line:
                            break
                        line_s = raw_line.strip()
                        if not line_s:
                            continue
                        if "📢 [PROGRESS]" in line_s:
                            noti = line_s.split("📢 [PROGRESS]", 1)[1].strip()
                            globals()['_last_bg_notification'] = noti
                            globals()['_last_bg_notification_time'] = time.time()
                            try:
                                if '_invalidate_view_caches' in globals():
                                    globals()['_invalidate_view_caches']()
                            except Exception:
                                pass
                _proc.wait()
                _log_to_file(f"✅ [Cart Spark Translate] 완료 (returncode={_proc.returncode})")
                globals()['_last_bg_notification'] = f"🎉 스파크 번역 요청 완료! (총 {len(pending_files)}개)"
                globals()['_last_bg_notification_time'] = time.time()
                try:
                    if '_invalidate_view_caches' in globals():
                        globals()['_invalidate_view_caches']()
                except Exception:
                    pass
            except Exception as _bg_e:
                _log_to_file(f"❌ [Cart Spark Translate] 백그라운드 스레드 오류: {_bg_e}")
            finally:
                globals()['_cart_spark_translate_running'] = False

        _t = threading.Thread(target=_bg_spark_runner, daemon=True, name="CartSparkTranslate")
        _t.start()
        _log_to_file(f"🚀 [Cart Spark Translate] 백그라운드 작업 시작 (대기 파일={len(pending_files)}, force={force})")
        if force:
            return True, f"장바구니 파일 {len(pending_files)}개 낱개(1개씩) 스파크 번역 시작냥! 🚀✨"
        else:
            return True, f"장바구니 파일 {len(pending_files)}개 스파크 번역 시작냥! 🚀✨"

    except Exception as e:
        _log_to_file(f"⚠️ [_check_and_trigger_cart_spark_translate] Error: {e}")
        return False, f"오류 발생: {e}"

# [TAG: #@_check_and_resume_spark_harvest]
def _check_and_resume_spark_harvest(s_obj=None):
    """[신규] 앱 부팅 또는 주기적 점검 시, 스파크 추수 대기열(spark_harvest_queue.json)이나
    장바구니에 아직 자막이 완성되지 않은 미추수 항목이 있다면 워처를 자동으로 부활/실행합니다! 🌾📦✨
    """
    try:
        # 보조 인스턴스에서는 중복 실행 방지
        if '--secondary' in sys.argv or globals().get('IS_SECONDARY_INSTANCE', False):
            return False, "보조 인스턴스 스킵"

        _base_dir = os.path.dirname(os.path.abspath(__file__))
        _hq_dir = os.path.join(_base_dir, "scripts")
        if _hq_dir not in sys.path:
            sys.path.insert(0, _hq_dir)

        try:
            import harvest_queue
            pending = harvest_queue.get_pending_harvest_items()
            if pending:
                if not harvest_queue.is_watcher_running():
                    # 🐛[V193.8 수정] 예전엔 user_requested 인자를 안 줬는데,
                    #   launch_watcher_if_needed() 는 기본값 False 이면 '무조건 거부'하도록
                    #   방어되어 있어서 워처가 단 한 번도 뜨지 않았는데도
                    #   로그에는 '워처를 가동했어냥!' 이라고 거짓말을 출력했다.
                    #   → 이제 실제로 '기동됐을 때만' 성공으로 보고한다 (조용한 실패 금지) 🦴
                    _ok, _msg = harvest_queue.launch_watcher_if_needed(interval=90)
                    if _ok:
                        _log_to_file(f"🌾 [Spark Harvest] 미추수 자막({len(pending)}개) 자동 회수를 위해 워처를 가동했어냥! 🚀")
                        return True, f"미추수 자막 {len(pending)}개 워처 가동"
                    _log_to_file(f"🌾 [Spark Harvest] 미추수 자막 {len(pending)}개 감지 — 워처는 자동 기동하지 않아 ({_msg}). "
                                 f"장바구니 진입/전송 시 선행 수신(Pre-Harvest)이 대신 처리해 줘! 📥")
                    return False, _msg
                else:
                    return True, f"미추수 자막 {len(pending)}개 워처 감시 중"
        except Exception as _he:
            _log_to_file(f"⚠️ [_check_and_resume_spark_harvest] harvest_queue 연동 오류: {_he}")
    except Exception as e:
        _log_to_file(f"⚠️ [_check_and_resume_spark_harvest] 에러: {e}")
    return False, "대기 항목 없음 또는 이미 실행 중"

# [TAG: #@_bg_process_subtitle]
def _bg_process_subtitle(v_path):
    """Flask 웹 요청을 받아 백그라운드 스레드에서 자막 생성을 수행합니다.
    ★ [V92.3] start_subtitle_engine 에 위임 - 중복 로직 완전 제거!
    """
    global settings
    _active_jobs = globals().setdefault('_flask_active_jobs', set())
    if not os.path.exists(v_path):
        print(f" ⚠️ {C.YELLOW}[Web Subtitle Request]{C.RESET} 파일을 찾을 수 없어: {v_path}")
        return

    print(f"\r\n 🌐 {C.BOLD}{C.SKY}[Web Subtitle Request]{C.RESET} 웹에서 자막 생성을 요청받았어! ✨")
    print(f" 🎬 대상: {C.CYAN}{os.path.basename(v_path)}{C.RESET}")

    # settings 안전 로드 🛡️
    s_obj = globals().get('settings') or globals().get('settings_ref')
    if not s_obj:
        try:
            s_obj = SettingsManager(SETTINGS_FILE)
            s_obj.load()
        except Exception:
            s_obj = None

    v_path_norm = os.path.normpath(v_path).lower()
    _active_jobs.add(v_path_norm)
    try:
        # ★ 저장된 설정으로 즉시 실행 (is_resume=True) + 텔레그램에 '웹(자동)' 출처 표시
        start_subtitle_engine([v_path], s_obj, is_resume=True, notify_label='웹(자동)')
    except Exception as e:
        print(f"\r\n ❌ {C.RED}[Web Subtitle Request]{C.RESET} 자막 생성 중 오류 발생: {e}")
    finally:
        _active_jobs.discard(v_path_norm)


# ==============================================================================
# ★ [신규] 자막 제작 공통 엔진 함수군 (Subtitle Engine Core) 🚀
# - start_subtitle_engine(v_paths, settings, is_resume=False): 메인 컨트롤러
# - _build_subtitle_config(v_paths, settings, is_resume): 설정 수집 (질문 or 저장값)
# - _init_ai_model_for_subtitle(config, settings): AI 모델 초기화
# - _execute_subtitle_jobs(v_paths, config, model, settings): 파일별 자막 실행
# ==============================================================================

# [TAG: #@_build_subtitle_config]
def _build_subtitle_config(v_paths, settings, is_resume=False):
    """
    [부품 1] 자막 제작에 필요한 설정값을 수집한다.
    - is_resume=True : 저장된 설정값을 바로 로드 (질문 없음)
    - is_resume=False: 사용자에게 모드/모델/위스퍼/청크 등을 물어봄
    반환값: config dict 또는 None (취소 시)
    """
    config = {
        'trans_mode': MODE_GEMINI_DIRECT_1STEP,
        'selected_model_idx': 0,
        'selected_model_name': 'gemini-2.5-flash-lite',
        'selected_whisper_idx': 0,
        'whisper_size': 'base',
        'selected_cleanup_idx': 0,
        'cleanup_temp': 0,
        'selected_skip_idx': 1,
        'selected_skip_name': '기존자막 건너뛰기(자동)',
        'selected_chunk_idx': 3,
        'chunk_duration_sec': 300,
        'extra_tone_prompt': '',
        'gemma_size': settings.data.get('gemma_size', '4b_it'),
        'colab_pool': None,
        'show_cli_output': False,
        'sub_path': None,
        'repair_start_min': 0.0,
        'repair_duration_min': 3.0,
        'is_resume': is_resume, # [V16.4.9] 이어하기 여부 박제! 🏷️✨
    }

    if is_resume:
        # ── 저장된 설정 로드 (질문 스킵) ──────────────────────────────────
        _log_to_file(" [Config] Loading saved settings (is_resume=True)")
        trans_mode = settings.data.get('trans_mode_key', MODE_GEMINI_DIRECT_1STEP)
        if 'trans_mode_key' not in settings.data and 'trans_mode_idx' in settings.data:
            old_idx = settings.data.get('trans_mode_idx', 0)
            _tm_map = {
                0: MODE_GEMINI_DIRECT_1STEP, 1: MODE_GEMINI_DIRECT_2STEP,
                2: MODE_WHISPER_GEMINI_PURE, 3: MODE_WHISPER_GEMINI_BILINGUAL,
                4: MODE_COLAB_WHISPER_GEMINI, 5: MODE_COLAB_WHISPER_GEMINI_CLI,
                6: MODE_WHISPER_GEMINI_CLI, 7: MODE_COLAB_WHISPER_GEMMA_FREE,
                8: MODE_WHISPER_GEMMA_4B_LOCAL, 9: MODE_LOCAL_VAD_CHECK,
                10: MODE_WHISPER_GEMMA_STREAM_LOCAL, 11: MODE_COLAB_GEMMA4_E4B, 12: MODE_COLAB_WHISPER_GEMMA4_E4B,
                13: MODE_GEMINI_CLI_AUDIO_ONESTEP
            }
            trans_mode = _tm_map.get(old_idx, MODE_GEMINI_DIRECT_1STEP)
        config['trans_mode'] = trans_mode
        _log_to_file(f" [Config] Selected trans_mode: {trans_mode}")

        selected_model_idx = settings.data.get('model_idx', 0)
        model_mapping = {
            0: 'gemini-3.5-flash',
            1: 'gemini-3.5-flash',
            2: 'gemini-2.5-flash-lite',
            3: 'gemini-2.5-flash-lite',
            4: 'gemini-3.5-flash' # 스냅샷 'Gemini 3 Flash Preview' 대응 ✨
        }
        if trans_mode == MODE_LOCAL_VAD_CHECK:
            config['selected_model_name'] = 'gemini-2.5-flash-lite'
        elif IS_GEMINI_CLI_MODE(trans_mode):
            config['selected_model_name'] = model_mapping.get(selected_model_idx, 'gemini-3-flash')
        elif IS_COLAB_TRANSLATE_MODE(trans_mode):
            config['selected_model_name'] = 'gemini-2.5-flash-lite'
        else:
            config['selected_model_name'] = model_mapping.get(selected_model_idx, 'gemini-2.5-flash-lite')
        config['selected_model_idx'] = selected_model_idx
        _log_to_file(f" [Config] Selected model: {config['selected_model_name']} (idx={selected_model_idx})")

        # [V122.1] 리스트 길이를 확장하고 인덱스 범위를 체크하도록 개선 (IndexError 방지) 🛡️
        chunk_idx = safe_int(settings.data.get('chunk_duration_idx', 5), default=0)
        _dur_list = [30, 45, 60, 120, 180, 300, 600, 1200, 1800, 3600, 999999]
        config['selected_chunk_idx'] = chunk_idx
        config['chunk_duration_sec'] = _dur_list[chunk_idx] if chunk_idx < len(_dur_list) else 300
        _log_to_file(f" [Config] Chunk duration: {config['chunk_duration_sec']}s (idx={chunk_idx})")

        w_idx = safe_int(settings.data.get('whisper_idx', 0), default=0)
        config['selected_whisper_idx'] = w_idx
        _w_list = ['base', 'small', 'medium', 'large-v3']
        config['whisper_size'] = _w_list[w_idx] if w_idx < len(_w_list) else 'base'
        if trans_mode in [MODE_GEMINI_CLI_AUDIO_ONESTEP, MODE_COLAB_GEMMA4_E4B, MODE_AGY_AUDIO_ONESTEP, MODE_AGY_ADAPTIVE_PIPELINE]:
            config['whisper_size'] = 'tiny'
        _log_to_file(f" [Config] Whisper size: {config['whisper_size']} (idx={w_idx if config['whisper_size'] != 'tiny' else 'VAD'})")

        c_idx = settings.data.get('cleanup_idx', 0)
        config['selected_cleanup_idx'] = c_idx
        config['cleanup_temp'] = c_idx
        _log_to_file(f" [Config] Cleanup mode: {c_idx}")

        config['selected_skip_idx'] = settings.data.get('skip_existing_idx', 0)
        _log_to_file(" [Config] Initializing colab pool (if needed)")
        config['colab_pool'] = init_colab_pool(trans_mode, settings)
        config['gemma_size'] = settings.data.get('gemma_size', '4b_it')
        _log_to_file(" [Config] Final config built for is_resume")

        # [V93.2] Fix: 자동 모드(is_resume)일 때 즉시 설정을 반환하지 않아 튕기는 문제 해결 🎯
        return config

    else:
        # ── 사용자 질문 모드 ───────────────────────────────────────────────
        q_total = 5 if len(v_paths) > 1 else 4
        q_idx = [1]
        # [TAG: #@get_p]
        def get_p():
            p = f'[ {q_idx[0]}/{q_total} ] '
            q_idx[0] += 1
            return p

        while True:
            q_idx[0] = 1
            selected_trans_key, trans_mode, manual_now, sub_path = get_translation_mode(
                settings.data.get('trans_mode_key', MODE_GEMINI_DIRECT_1STEP),
                False, False, v_paths=v_paths, prefix=get_p()
            )
            if selected_trans_key == '-1':
                return None  # 취소

            # 바로 재생 처리
            if trans_mode == 'MODE_PLAY_VIDEO':
                for _vp in v_paths:
                    open_path_resilient(_vp)
                time.sleep(1)
                continue

            _print_job_flow_intro(trans_mode)

            # 총 질문 수 보정
            if trans_mode in [MODE_WHISPER_GEMINI_PURE, MODE_WHISPER_GEMINI_BILINGUAL,
                               MODE_LOCAL_VAD_CHECK, MODE_WHISPER_GEMMA_4B_LOCAL,
                               MODE_WHISPER_GEMINI_CLI, MODE_COLAB_WHISPER_GEMINI_CLI]:
                q_total = 6 if len(v_paths) > 1 else 5
            elif IS_COLAB_TRANSLATE_MODE(trans_mode):
                q_total = 4 if len(v_paths) > 1 else 3
            else:
                q_total = 5 if len(v_paths) > 1 else 4

            config['sub_path'] = sub_path
            config['trans_mode'] = trans_mode

            # 빠른 종료 모드들
            if trans_mode == MODE_SUBTITLE_SUMMARY:
                # [V205.0] agy CLI 기반 초고속 요약 모드
                try:
                    for _vp in v_paths:
                        summarize_video_with_srt(_vp, None, sub_path=sub_path)
                    print(f'\r\n ✅ {C.GREEN}요약 완료!{C.RESET}')
                    time.sleep(2)
                except Exception as e:
                    print(f' ❌ 요약 중 오류: {e}')
                    time.sleep(2)
                return None  # 엔진 루프 생략

            if trans_mode == MODE_SUBTITLE_EDIT_NOTEPAD:
                # [V147.172] AI냥 요청: 메모장 직접 수정 모드 📝
                for _vp in v_paths:
                    target_sub = sub_path if (sub_path and os.path.exists(sub_path)) else os.path.splitext(_vp)[0] + '.srt'
                    if os.path.exists(target_sub):
                        print(f" 📝 {C.SKY}{os.path.basename(target_sub)}{C.RESET} 파일을 메모장으로 엽니다...")
                        # [Safety] 윈도우 메모장 실행 (작업이 끝날 때까지 대기하지 않음)
                        subprocess.Popen(["notepad.exe", target_sub])
                    else:
                        print(f" ❌ {C.RED}자막 파일을 찾을 수 없습니다:{C.RESET} {target_sub}")
                time.sleep(1)
                return None

            if trans_mode == MODE_SUBTITLE_REINDEX:
                # [V147.172] AI냥 요청: 자막 순번 재지정 모드 🔢
                for _vp in v_paths:
                    target_sub = sub_path if (sub_path and os.path.exists(sub_path)) else os.path.splitext(_vp)[0] + '.srt'
                    if os.path.exists(target_sub):
                        print(f" 🔢 {C.YELLOW}{os.path.basename(target_sub)}{C.RESET} 순번 재지정 중...")
                        try:
                            with open(target_sub, 'r', encoding='utf-8', errors='ignore') as f:
                                old_text = f.read()
                            new_text = reindex_srt(old_text)
                            with open(target_sub, 'w', encoding='utf-8') as f:
                                f.write(new_text)
                            print(f" ✅ {C.GREEN}번호 정렬 완료!{C.RESET}")
                        except Exception as e:
                            print(f" ❌ {C.RED}재지정 중 오류 발생:{C.RESET} {e}")
                    else:
                        print(f" ❌ {C.RED}자막 파일을 찾을 수 없습니다:{C.RESET} {target_sub}")
                time.sleep(1.5)
                return None

            if trans_mode == MODE_SUBTITLE_REFINE:
                # [V205.0] agy CLI 기반 자막 맥락 윤색 (퇴고) 모드 ✨
                try:
                    for _vp in v_paths:
                        target_sub = sub_path if (sub_path and os.path.exists(sub_path)) else os.path.splitext(_vp)[0] + '.srt'
                        if os.path.exists(target_sub):
                            refine_subtitle_with_gemini(_vp, None, sub_path=target_sub)
                        else:
                            print(f" ❌ {C.RED}자막 파일을 찾을 수 없습니다:{C.RESET} {target_sub}")
                    print(f'\r\n ✅ {C.GREEN}자막 퇴고(다듬기) 완료!{C.RESET}')
                except Exception as e:
                    print(f' ❌ 다듬기 중 오류: {e}')
                time.sleep(2)
                return None

            if trans_mode == MODE_SUBTITLE_RESYNC_LYRICS:
                # [V206.0] 비누님 요청: 너 자막 있네? 커버 뮤비/음원 Whisper 1:1 초정밀 가사 자동 싱크 🎵⚡ (함수형 내재화)
                try:
                    for _vp in v_paths:
                        target_sub = sub_path if (sub_path and os.path.exists(sub_path)) else os.path.splitext(_vp)[0] + '.srt'
                        if not os.path.exists(target_sub):
                            print(f" ❌ {C.RED}자막 파일을 찾을 수 없습니다:{C.RESET} {target_sub}")
                            continue

                        print(f"\r\n 🎵 {C.CYAN}Whisper 기반 가사 1:1 초정밀 싱크 교정 시작!{C.RESET}")
                        print(f" 🎬 대상 영상: {C.BOLD}{os.path.basename(_vp)}{C.RESET}")
                        print(f" 📄 원본 자막: {C.YELLOW}{os.path.basename(target_sub)}{C.RESET}")
                        print(f" 💡 {C.DIM}기존 텍스트(원문/번역)는 100% 보존하고 시간(타임스탬프)만 칼같이 맞춥니다.{C.RESET}\n")

                        result_path = None
                        try:
                            result_path = _resync_run(_vp, target_sub, model_name="base")
                        except Exception as e:
                            print(f"\r\n ❌ {C.RED}싱크 교정 실패:{C.RESET} {e}")

                        if result_path:
                            print(f"\r\n 🎉 {C.GREEN}{C.BOLD}가사 싱크 교정(Re-sync) 성공! 칼싱크 자막 적용 완료!{C.RESET} ✨")
                            print(f" 🔒 {C.DIM}수정 전 원본은 _backup_original_srt 폴더에 안전하게 보관되었습니다.{C.RESET}")
                            try:
                                ans = input(f"\n ▶ {C.YELLOW}지금 바로 플레이어로 싱크를 확인해볼까? (Y/n) > {C.RESET}").strip().lower()
                                if ans != 'n':
                                    open_path_resilient(_vp)
                            except Exception:
                                pass
                except Exception as e:
                    print(f" ❌ {C.RED}싱크 교정 중 오류 발생:{C.RESET} {e}")
                time.sleep(1.5)
                return None

            if trans_mode == MODE_SUBTITLE_HIGHLIGHT:
                config.update({
                    'selected_model_idx': settings.data.get('model_idx', 4),
                    'selected_model_name': {
                        0: 'gemini-3.5-flash',
                        1: 'gemini-3.5-flash',
                        2: 'gemini-2.5-flash-lite',
                        3: 'gemini-2.5-flash-lite',
                        4: 'gemini-3.5-flash' # 스냅샷 'Gemini 3 Flash Preview' 대응 ✨
                    }.get(settings.data.get('model_idx', 4), 'gemini-3.5-flash'),
                    'selected_whisper_idx': 0, 'whisper_size': 'base',
                    'selected_cleanup_idx': 0, 'cleanup_temp': 0,
                    'selected_skip_idx': 1, 'selected_chunk_idx': 6,
                    'chunk_duration_sec': 600, 'colab_pool': None,
                })
                break

            if trans_mode == MODE_SUBTITLE_REMAKE_3MIN:
                m_cancelled = False
                while True:
                    ans = prompt_input(f' 👉 {C.SKY}몇 분부터 시작할까? (취소: c): {C.RESET}').strip().lower()
                    if ans == 'c': m_cancelled = True; break
                    try: config['repair_start_min'] = safe_float(ans); break
                    except: print(f' ❌ {C.RED}숫자만 입력해줘!{C.RESET}')

                if not m_cancelled:
                    # [V110.5] 재작업 길이(duration) 선택 메뉴 추가 ✨⏱️
                    dur_menu = [f" ⏱️ {i}분간 작업" for i in range(1, 11)]
                    dur_sel, _, *_ = _interactive_menu("⏱️ 작업할 분량을 선택해줘냥!", dur_menu, default_idx=2) # 기본 3분
                    if dur_sel < 0: m_cancelled = True
                    else: config['repair_duration_min'] = float(dur_sel + 1)

                if m_cancelled: return None
                config.update({
                    'selected_model_idx': 0,
                    'selected_model_name': 'agy-cli',
                    'selected_whisper_idx': 0,
                    'whisper_size': 'base',
                    'selected_cleanup_idx': settings.data.get('cleanup_idx', 0),
                    'cleanup_temp': settings.data.get('cleanup_idx', 0),
                    'selected_skip_idx': 1,
                    'selected_chunk_idx': 3,
                    'chunk_duration_sec': 300,
                    'colab_pool': None,
                })
                break

            if trans_mode == MODE_EXTRACT_INTERNAL_SUBTITLES:
                # [V152.28] 내장 자막 추출 모드: 추가 질문 없이 바로 시작냥! 🎬✨
                config.update({
                    'selected_model_idx': 0, 'selected_model_name': 'none',
                    'selected_whisper_idx': 0, 'whisper_size': 'base',
                    'selected_cleanup_idx': 0, 'cleanup_temp': 0,
                    'selected_skip_idx': 1, 'selected_chunk_idx': 6,
                    'chunk_duration_sec': 600, 'colab_pool': None,
                })
                break

            if trans_mode == MODE_AGY_ADAPTIVE_PIPELINE:
                # [V200.1] 8번 agy 스마트 가변 멀티모달 원스텝 모드: 불필요한 질문(모델/청크분할/임시파일) 전면 스킵하고 즉시 번역 직행! ⚡🚀
                config.update({
                    'selected_model_idx': 0, 'selected_model_name': 'agy-multimodal-adaptive',
                    'selected_whisper_idx': 0, 'whisper_size': 'none',
                    'selected_cleanup_idx': 0, 'cleanup_temp': 0,
                    'selected_skip_idx': 1, 'selected_chunk_idx': 10, # Full (자체 스마트 가변 분할)
                    'chunk_duration_sec': 999999, 'colab_pool': None,
                })
                break

            # ── Gemma / Stream / 일반 모드 질문 ──────────────────────────
            selected_model_idx = 0
            selected_model_name = 'gemini-2.5-flash-lite'

            if trans_mode in [MODE_GEMINI_DIRECT_1STEP, MODE_WHISPER_GEMINI_CLI,
                               MODE_COLAB_WHISPER_GEMINI_CLI, MODE_GEMINI_DIRECT_2STEP,
                               MODE_WHISPER_GEMINI_PURE, MODE_COLAB_WHISPER_GEMINI,
                               MODE_WHISPER_GEMINI_BILINGUAL, MODE_SUBTITLE_TRANSLATION]:
                selected_model_idx, ai_model, manual_now, extra_tone = get_model_selection(
                    settings.data.get('model_idx', 1), False, False, prefix=get_p(), trans_mode=trans_mode
                )
                if selected_model_idx == -1: return None
                selected_model_name = ai_model
                settings.data['model_name'] = selected_model_name
                settings.save()
                config['extra_tone_prompt'] = extra_tone

            if trans_mode == MODE_WHISPER_GEMMA_4B_LOCAL:
                sel_w, ws, _ = get_whisper_model_selection(settings.data.get('whisper_size_idx', 3), False, False, prefix=get_p())
                if sel_w == -1: return None
                settings.data['whisper_size_idx'] = sel_w
                saved_gk = settings.data.get('gemma_size', '4b_it')
                sel_g, gs, _ = get_gemma_model_selection(saved_gk, False, False, prefix=get_p())
                if sel_g == -1: return None
                settings.data['gemma_size_idx'] = sel_g
                settings.data['gemma_size'] = gs
                config.update({'selected_whisper_idx': sel_w, 'whisper_size': ws, 'gemma_size': gs})

            if trans_mode == MODE_WHISPER_GEMMA_STREAM_LOCAL:
                sel_w, ws, _ = get_whisper_model_selection(settings.data.get('whisper_size_idx', 3), False, False, prefix=get_p())
                if sel_w == -1: return None
                settings.data['whisper_size_idx'] = sel_w
                saved_gk = settings.data.get('gemma_size', '4b_it')
                sel_g, gs, _ = get_gemma_model_selection(saved_gk, False, False, prefix=get_p())
                if sel_g == -1: return None
                settings.data['gemma_size'] = gs
                config.update({
                    'selected_whisper_idx': sel_w, 'whisper_size': ws, 'gemma_size': gs,
                    'selected_cleanup_idx': 0, 'cleanup_temp': 0,
                    'selected_skip_idx': 1, 'selected_chunk_idx': 7, 'chunk_duration_sec': 999999,
                    'colab_pool': None,
                })
                config['selected_model_idx'] = selected_model_idx
                config['selected_model_name'] = selected_model_name
                break

            # [V19.5] AI냥 요청: 17번 번역 모드(MODE_SUBTITLE_TRANSLATION)는 모델 선택 후 즉시 진행 (패스트트랙) 🚀✨
            jump_to_process = (trans_mode in [MODE_WHISPER_GEMMA_STREAM_LOCAL, MODE_SUBTITLE_TRANSLATION])
            if jump_to_process:
                # 번역 모드 전용 추천 기본값 세팅 (질문 스킵용)
                if trans_mode == MODE_SUBTITLE_TRANSLATION:
                    config.update({
                        'selected_cleanup_idx': 0, 'cleanup_temp': 0,
                        'selected_skip_idx': 1, 'selected_chunk_idx': 5, # 번역은 5분(300초) 단위가 안정적냥!
                        'chunk_duration_sec': 300,
                        'colab_pool': None,
                    })
                
                config['selected_model_idx'] = selected_model_idx
                config['selected_model_name'] = selected_model_name
                break

            if not jump_to_process:
                if trans_mode in [MODE_WHISPER_GEMINI_PURE, MODE_WHISPER_GEMINI_BILINGUAL,
                                   MODE_LOCAL_VAD_CHECK, MODE_WHISPER_GEMINI_CLI,
                                   MODE_COLAB_WHISPER_GEMINI_CLI, MODE_COLAB_WHISPER_GEMMA_FREE, MODE_COLAB_WHISPER_GEMMA4_E4B]:
                    if 'colab' in trans_mode.lower():
                        config['selected_whisper_idx'] = 3; config['whisper_size'] = 'large-v3'
                    else:
                        sel_w, ws, _ = get_whisper_model_selection(settings.data.get('whisper_idx', 0), False, False, prefix=get_p(), timeout=0)
                        if sel_w == -1: return None
                        settings.data['whisper_idx'] = sel_w
                        config['selected_whisper_idx'] = sel_w; config['whisper_size'] = ws
                else:
                    w_idx = safe_int(settings.data.get('whisper_idx', 0), default=0)
                    config['selected_whisper_idx'] = w_idx
                    _w_list = ['base', 'small', 'medium', 'large-v3']
                    config['whisper_size'] = _w_list[w_idx] if w_idx < len(_w_list) else 'base'

                sel_c, ct, _ = get_cleanup_mode(settings.data.get('cleanup_idx', 0), False, False, prefix=get_p())
                if sel_c == -1: return None
                config['selected_cleanup_idx'] = sel_c; config['cleanup_temp'] = ct

                if len(v_paths) > 1:
                    sel_s, _ = get_skip_existing_mode(settings.data.get('skip_existing_idx', 0), False, file_count=len(v_paths), prefix=get_p())
                    if sel_s == -1: return None
                    config['selected_skip_idx'] = sel_s
                else:
                    config['selected_skip_idx'] = 1

                sel_ch, ch_sec, _ = get_chunk_duration_mode(settings.data.get('chunk_duration_idx', 3), False, False, v_paths=v_paths, prefix=get_p(), trans_mode=trans_mode)
                if sel_ch == -1: return None
                config['selected_chunk_idx'] = sel_ch; config['chunk_duration_sec'] = ch_sec

            config['colab_pool'] = init_colab_pool(trans_mode, settings)
            if IS_COLAB_MODE(trans_mode) and config['colab_pool'] is None:
                return None

            config['selected_model_idx'] = selected_model_idx
            config['selected_model_name'] = selected_model_name
            if IS_GEMINI_CLI_MODE(trans_mode):
                config['show_cli_output'] = True

            # 설정 저장
            m_labels = {0: 'Gemini 3 Flash', 1: 'Gemini 3.5 Flash', 2: 'Gemini Flash Lite'}
            settings.data.update({
                'trans_mode_key': trans_mode,
                'model_idx': selected_model_idx,
                'model_name': m_labels.get(selected_model_idx, 'Lite'),
                'chunk_duration_idx': config['selected_chunk_idx'],
                'whisper_idx': config['selected_whisper_idx'],
                'cleanup_idx': config['selected_cleanup_idx'],
                'skip_existing_idx': config['selected_skip_idx'],
                'extra_tone_prompt': config['extra_tone_prompt'],
                'gemma_size': config['gemma_size'],
            })
            settings.save()
            break

    # [V22.2b] Gemini CLI 멀티모달 원스탭 및 Gemma4 코랩 모드에서는 음성구간감지(VAD)용으로 Tiny 모델이 고정 기동되므로 최종 보정냥! 🕵️‍♂️✨
    if config and config.get('trans_mode') in [MODE_GEMINI_CLI_AUDIO_ONESTEP, MODE_COLAB_GEMMA4_E4B, MODE_AGY_AUDIO_ONESTEP, MODE_AGY_ADAPTIVE_PIPELINE]:
        config['whisper_size'] = 'tiny'
    return config


# [TAG: #@_init_ai_model_for_subtitle]
def _init_ai_model_for_subtitle(config, settings):
    """
    [부품 2] config에 맞는 AI 모델 인스턴스를 초기화해서 반환한다.
    실패 시 None 반환.
    """
    global _flask_shared_model
    trans_mode = config['trans_mode']
    try:
        if trans_mode == MODE_LOCAL_VAD_CHECK or IS_GEMINI_CLI_MODE(trans_mode):
            model = None
        elif not IS_COLAB_TRANSLATE_MODE(trans_mode):
            API_KEYS = get_api_keys()
            if not API_KEYS:
                # [V147.231] AI냥 요청: API 키가 없을 때의 'list index out of range' 에러 방지 및 안내 강화 🛡️✨
                raise ValueError("등록된 Gemini API 키가 하나도 없습니다냥! 🗝️\r\n'환경 설정(S)' 메뉴에서 Gemini API 키를 최소 하나 이상 등록해달라냥! ✨")

            API_KEY_IDX = settings.data.get('api_key_idx', 0) % len(API_KEYS)
            import google.generativeai as _genai
            _genai.configure(api_key=API_KEYS[API_KEY_IDX])
            model = _genai.GenerativeModel(
                model_name=config.get('selected_model_name', 'gemini-3.5-flash'),
                system_instruction='You are a Master Korean Video Translator. ALWAYS translate natural, human-like Korean. ALWAYS output valid JSON.'
            )
        else:
            model = None
        _flask_shared_model = model
        return model
    except Exception as e:
        print(f'❌ AI 모델 초기화 오류: {e}')
        time.sleep(2)
        return None

def check_subtitle_bg_cancel():
    global _G_SUBTITLE_BG_CANCEL_REQUESTED
    if '_G_SUBTITLE_BG_CANCEL_REQUESTED' in globals() and _G_SUBTITLE_BG_CANCEL_REQUESTED:
        _log_to_file("⚠️ [BgQueueWorker] Cancel requested by user. Aborting current execution.")
        raise UserAbortException("백그라운드 자막 작업 취소 요청됨냥!")


# [TAG: #@_execute_subtitle_jobs]
def _execute_subtitle_jobs(v_paths, config, model, settings, pk=None, thread_id=None):
    """
    [부품 3] 파일 목록을 순서대로 처리하며 자막을 생성한다.
    성공/실패 파일 목록을 담은 dict를 반환한다.
    """
    # [V147.241] 사각지대 2 방어: config.get()을 사용하여 안전하게 추출냥! 🛡️
    trans_mode    = config.get('trans_mode', MODE_GEMINI_DIRECT_1STEP)
    cleanup_temp  = config.get('cleanup_temp', 0)
    chunk_sec     = config.get('chunk_duration_sec', 300)
    whisper_size  = config.get('whisper_size', 'base')
    colab_pool    = config.get('colab_pool')
    extra_tone    = config.get('extra_tone_prompt', '')
    gemma_size    = config.get('gemma_size', '4b')
    show_cli      = config.get('show_cli_output', False)
    is_res        = config.get('is_resume', False) # [V16.4.9] 신호 포착! 🛰️
    sub_path      = config.get('sub_path')
    repair_min    = config.get('repair_start_min', 0.0)


    # [V147.176] 함수 내에서 참조할 비디오 확장자 정의 (Ruff F821 해결 ✨)
    v_exts = ('.mp4', '.mkv', '.avi', '.mov', '.wmv', '.flv', '.m4v', '.webm', '.ts', '.m2ts', '.mpg', '.mpeg', '.tp')

    total_files = len(v_paths)
    success_files = []
    success_full_paths = []
    fail_files = []

    # 작업 시작 전 active_subtitle_tasks 등록
    current_active = settings.data.get('active_subtitle_tasks', [])
    for p in v_paths:
        if p not in current_active:
            current_active.append(p)
    settings.data['active_subtitle_tasks'] = current_active
    settings.save()

    # [V147.174] AI냥 요청: 카트 작업 중 새 파일이 들어오면 멈추지 않고 계속 달리기! 🚀🛒🔄
    # 기존 for 루프를 동적 확장이 가능한 리스트 기반 제어로 변경냥!
    work_list = list(v_paths)
    queued_set = set(work_list)
    file_idx = 0

    # [TAG: #@_execute_subtitle_jobs_loop] 🏷️✨
    while file_idx < len(work_list):
        # [V21.12] 백그라운드 작업 취소 요청 감지냥! 🛑✨
        global _G_SUBTITLE_BG_CANCEL_REQUESTED
        if '_G_SUBTITLE_BG_CANCEL_REQUESTED' in globals() and _G_SUBTITLE_BG_CANCEL_REQUESTED:
            print(f"\r\n 🛑 {C.BOLD}{C.RED}[백그라운드 작업 취소됨]{C.RESET} 사용자가 작업을 강제 중단했습니다냥! ✋")
            _log_to_file("⚠️ [BgQueueWorker] Cancel requested by user. Terminating loop.")
            for p in work_list[file_idx:]:
                if p not in fail_files:
                    fail_files.append(p)
            break

        v_path = work_list[file_idx]
        total_files = len(work_list) # 실시간 총 개수 갱신
        
        # [V21.12] 백그라운드 UI 피드백을 위해 상태 전역 변수 실시간 갱신냥! 📡✨
        global _G_SUBTITLE_BG_STATUS, _G_SUBTITLE_BG_JOBS
        _G_SUBTITLE_BG_STATUS['active'] = True
        _G_SUBTITLE_BG_STATUS['current'] = file_idx + 1
        _G_SUBTITLE_BG_STATUS['total'] = total_files
        _G_SUBTITLE_BG_STATUS['status_text'] = '번역중'
        _G_SUBTITLE_BG_STATUS['current_path'] = os.path.normpath(v_path).lower()
        if thread_id is not None:
            _G_SUBTITLE_BG_JOBS[thread_id] = {
                'active': True,
                'current': file_idx + 1,
                'total': total_files,
                'status_text': '번역중',
                'current_path': os.path.normpath(v_path).lower()
            }

        print_ui_header(settings.data, f'작업 중 ({file_idx+1}/{total_files})', total_files=total_files, current_idx=file_idx+1)
        print(f'{ctext("="*65, C.CYAN)}')
        print(f' 🎬 {ctext(f"[작업 {file_idx+1}/{total_files}]", C.YELLOW, C.BOLD)} {ctext(os.path.basename(v_path), C.CYAN, C.BOLD)}')
        print(f'{ctext("="*65, C.CYAN)}')

        # [버그 수정] 작업 전 자막 파일의 존재 및 수정 시간을 기록하여, 새로 생성되거나 갱신된 파일만 장바구니에서 삭제되도록 방어 🛡️
        _target_srt_path = os.path.splitext(v_path)[0] + ".srt"
        try:
            _initial_srt_mtime = os.path.getmtime(_target_srt_path) if os.path.exists(_target_srt_path) else 0
        except:
            _initial_srt_mtime = 0

        try:
            if trans_mode == MODE_LOCAL_VAD_CHECK:
                missing = check_missing_subtitles(v_path)
                if missing: review_missing_segments(v_path, missing)
                success = True
            elif trans_mode == MODE_SUBTITLE_TRANSLATION:
                success = translate_existing_subtitles(v_path, model, sub_path=sub_path)
            elif trans_mode == MODE_SUBTITLE_REMAKE_3MIN:
                # [V189.0] 백그라운드/웹 스튜디오 수리 모드 auto_confirm 옵션 지원 ⏱️✨
                is_auto_conf = config.get('auto_confirm', True)
                repair_s = config.get('repair_start_min', 0.0)
                repair_d = config.get('repair_duration_min', 3.0)
                success = fill_subtitle_gap_manual(v_path, model, repair_s, sub_path=sub_path, settings=settings, duration_min=repair_d, auto_confirm=is_auto_conf)
            elif trans_mode == MODE_EXTRACT_INTERNAL_SUBTITLES:
                # [V152.28] 내장 자막 추출 플로우 연결냥! 🎬✨
                success = extract_internal_subtitles_flow([v_path], settings)
            elif trans_mode == MODE_SUBTITLE_SUMMARY:
                # [V187.0] AI 자막 기반 줄거리 요약 백그라운드 분기 📝✨
                try:
                    summarize_video_with_srt(v_path, model, sub_path=sub_path)
                    success = True
                except Exception as ex_sum:
                    _log_to_file(f"⚠️ [Summary Error] {ex_sum}")
                    success = False
            elif trans_mode == MODE_SUBTITLE_REFINE:
                # [V187.0] AI 자막 맥락 윤색 / 퇴고 백그라운드 분기 ✨
                try:
                    target_sub = sub_path if (sub_path and os.path.exists(sub_path)) else os.path.splitext(v_path)[0] + '.srt'
                    refine_subtitle_with_gemini(v_path, model, sub_path=target_sub)
                    success = True
                except Exception as ex_ref:
                    _log_to_file(f"⚠️ [Refine Error] {ex_ref}")
                    success = False
            elif trans_mode == MODE_SUBTITLE_HIGHLIGHT:
                cur_srt = sub_path if (sub_path and os.path.exists(sub_path)) else os.path.splitext(v_path)[0] + '.srt'
                hl_menu_map = [
                    {'label': ' 🎬 표준: 15초 4컷 (총 1분)', 'key': 'std_15_4'},
                    {'label': ' ⚡ 숏폼: 10초 6컷 (총 1분)', 'key': 'short_10_6'},
                    {'label': ' 📈 확장: 15초 8컷 (총 2분)', 'key': 'ext_15_8'},
                    {'label': ' 🎥 풍성: 10초 12컷 (총 2분)', 'key': 'rich_10_12'},
                    {'label': ' 🎯 맞춤: 15초 n컷 (개수 직접 입력)', 'key': 'custom_15_n'},
                    {'label': ' 🔥 집중: 10초 n컷 (개수 직접 입력)', 'key': 'focus_10_n'},
                    {'label': ' ❌ 취소', 'key': 'cancel'},
                ]
                hl_sel, _, *_ = _interactive_menu('하이라이트 스타일을 골라줘!', [x['label'] for x in hl_menu_map], timeout=0, prefix='[ 1/1 ] 🎬 ')
                if hl_sel < 0 or hl_sel == 6:
                    success = False
                else:
                    num_clips = [4, 6, 8, 12][hl_sel] if hl_sel < 4 else 4
                    duration = [15, 10, 15, 10][hl_sel] if hl_sel < 4 else (15 if hl_sel == 4 else 10)
                    if hl_sel in [4, 5]:
                        while True:
                            ni = prompt_input(f' 👉 {C.SKY}몇 컷으로 만들까? (예: 8): {C.RESET}').strip()
                            if ni.isdigit(): num_clips = int(ni); break
                            print(f'  ⚠️ {C.YELLOW}숫자만 입력해줘~{C.RESET}')
                    highlights = get_ai_highlights(cur_srt, model, num_clips=num_clips, duration_sec=duration)
                    if highlights:
                        h_path = make_highlight_video(v_path, cur_srt, highlights, duration_sec=duration)
                        if h_path and os.path.exists(h_path):
                            success = True
                        else:
                            success = False
                    else:
                        success = False
            else:
                # [V17.3.8] AI냥 요청: '즉시 실행(a)' 이더라도 사용자가 '무시하고 새로 만들기(1)'를 설정해두었다면 덮어쓰도록 수정냥! 🛡️✨
                is_translation_resume = is_res and (config.get('selected_skip_idx', 0) != 1)

                success = process_video_file(
                    v_path, translation_mode=trans_mode, model=(model or config.get('selected_model_name')),
                    trans_mode=trans_mode, cleanup_mode=cleanup_temp,
                    chunk_duration_sec=chunk_sec, whisper_size=whisper_size,
                    colab_pool=colab_pool, settings=settings,
                    curr_file_idx=file_idx + 1, total_file_count=total_files,
                    extra_tone_prompt=extra_tone, gemma_size=gemma_size,
                    show_cli_output=show_cli, is_resume=is_translation_resume
                )
        except AIResponseFloodAbortException as flood_err:
            print(f"\r\n 🛑 {C.BOLD}{C.RED}[AI 응답 도배로 중단]{C.RESET} '{os.path.basename(v_path)}'에서 응답 지연 도배가 감지되어 남은 작업을 모두 실패 처리하고 중단합니다냥!")
            _log_to_file(f"⚠️ [BgQueueWorker] AIResponseFloodAbortException caught. Terminating execute jobs loop due to flood.")
            settings.load()
            current_active = settings.data.get('active_subtitle_tasks', [])
            for p in work_list[file_idx:]:
                p_base = os.path.basename(p)
                if p_base not in fail_files:
                    fail_files.append(p_base)
                v_norm = os.path.normcase(os.path.abspath(p))
                if current_active:
                    current_active = [x for x in current_active if os.path.normcase(os.path.abspath(x)) != v_norm]
            settings.data['active_subtitle_tasks'] = current_active
            settings.save()
            break
        except UserAbortException as uae:
            print(f"\r\n 🛑 {C.BOLD}{C.RED}[백그라운드 작업 중단]{C.RESET} 취소 요청에 의해 작업을 즉시 중단합니다냥!")
            _log_to_file("⚠️ [BgQueueWorker] UserAbortException caught. Terminating execute jobs loop.")
            for p in work_list[file_idx:]:
                if p not in fail_files:
                    fail_files.append(p)
            raise
        except Exception as e:
            import traceback
            _log_to_file(f"❌ [Subtitle Job Error] {e}\r\n{traceback.format_exc()}") # [V17.3.36] 에러 상세 로깅 보강 🔦
            print(f' ❌ 작업 중 오류: {e}')
            success = False

        # 완료 처리
        # [2026-04-12] 카트 및 활성 작업 정밀 정리 로직 훅 🧼✨🛒
        # 자막 파일이 새로 생성되었거나 작업 성공으로 내용이 갱신된 경우에만 지웁니다 (번역 실패 시 남아있는 구버전 파일 때문 방어)
        _srt_exists_now = os.path.exists(_target_srt_path)
        is_new_or_updated = _srt_exists_now and (_initial_srt_mtime == 0 or os.path.getmtime(_target_srt_path) > _initial_srt_mtime)

        if success or is_new_or_updated:
            if success:
                print(f" ✅ '{os.path.basename(v_path)}' 작업 완료!")
                # [V147.170] AI냥 요청: 작업이 '끝나는' 시점에 하이라이팅 기록! 🥇✨
                # [V147.175] 유튜브 플레이리스트 시작 시에도 강조 지연 적용 🏆🕰️
                _save_last_played_ctx(v_path, settings_obj=settings, pk=pk, is_starting=True)
            elif is_new_or_updated:
                print(f" ✨ '{os.path.basename(v_path)}' 새로운/갱신된 자막이 발견되어 카트에서 정리할게냥!")

            success_files.append(os.path.basename(v_path))
            success_full_paths.append(v_path)

            # [V147.181] AI냥 요청: 파일 하나가 끝날 때마다 즉시 번역 완료 목록(History)에 등록냥! 🎖️✨🚀
            add_to_translated_history(v_path, settings)

            # 1. 활성 작업 리스트 정리 (경로 정규화 매칭 ✨)
            v_norm = os.path.normcase(os.path.abspath(v_path))

            # [V121.5] 제거 전 최신 설정 불러오기 (백그라운드 창 등 다른 프로세스 병합 대비 🔄)
            settings.load()

            current_active = settings.data.get('active_subtitle_tasks', [])
            if current_active:
                settings.data['active_subtitle_tasks'] = [p for p in current_active if os.path.normcase(os.path.abspath(p)) != v_norm]

            # 2. 카트 리스트 정리 (경로 정규화 매칭 ✨)
            _cart = settings.data.get('shopping_cart', [])
            if _cart:
                # [V121.5] 딕셔너리/리스트 양쪽 대응 및 정규화 매칭 🧼
                if isinstance(_cart, dict):
                    keys_to_del = [k for k in _cart.keys() if os.path.normcase(os.path.abspath(k)) == v_norm]
                    for k in keys_to_del:
                        del _cart[k]
                        _log_to_file(f" [Cart] Removed from dict-cart: {k}")
                else:
                    # [V147.167] 딕셔너리(DNA 포함) 항목도 안전하게 경로 비교하여 제거 🛡️✨
                    def _get_p(item): return item.get("path") if isinstance(item, dict) else item
                    orig_len = len(_cart)
                    _cart = [p for p in _cart if os.path.normcase(os.path.abspath(_get_p(p))) != v_norm]
                    if len(_cart) < orig_len:
                        _log_to_file(f" [Cart] Removed from list-cart: {v_path}")

                settings.data['shopping_cart'] = _cart

            settings.save()
        else:
            print(f" ⏭️ '{os.path.basename(v_path)}' 문제 발생(자막 미생성). 다음 파일로 넘어갑니다.")
            fail_files.append(os.path.basename(v_path))

        # [V147.174] 💡 카트 모드 전용: 작업 도중 카트에 새로 들어온 파일이 있나 체크해서 큐에 수혈냥!
        if pk == 'CART':
            settings.load()
            current_cart = settings.data.get('shopping_cart', {})
            cart_keys = list(current_cart.keys()) if isinstance(current_cart, dict) else list(current_cart)

            added_count = 0
            for cp in cart_keys:
                # 경로 추출 보조 (딕셔너리 형태 대응)
                _cp_path = cp.get("path") if isinstance(cp, dict) else cp
                if _cp_path and _cp_path not in queued_set and os.path.exists(_cp_path) and _cp_path.lower().endswith(v_exts):
                    work_list.append(_cp_path)
                    queued_set.add(_cp_path)
                    added_count += 1

                    # 새 작업도 active_subtitle_tasks에 미리 등록 🛡️
                    curr_active = settings.data.get('active_subtitle_tasks', [])
                    if _cp_path not in curr_active:
                        curr_active.append(_cp_path)
                        settings.data['active_subtitle_tasks'] = curr_active

            if added_count > 0:
                settings.save()
                print(f" 🛒 {C.GREEN}카트에 새 파일 {added_count}개가 추가되어 작업 목록에 넣었어냥!{C.RESET} (총 {len(work_list)}개)")

        # [V17.3.40] 비누님 요청: 번역 완료 후 30초 유휴 대기 제거! (다음 파일 초반 오디오 추출/위스퍼 작업으로 자연스럽게 대기됨) 🚀⚡

        file_idx += 1

    return {
        'success_files': success_files,
        'success_full_paths': success_full_paths,
        'fail_files': fail_files,
    }


# [TAG: #@get_internal_subtitle_streams]
def get_internal_subtitle_streams(video_path, ffprobe_bin):
    """ffprobe를 사용하여 영상 내부의 자막 스트림 목록을 가져옵니다. (AI냥 요청 🛠️✨)"""
    try:
        cmd = [
            ffprobe_bin,
            "-v", "error",
            "-select_streams", "s",
            "-show_entries", "stream=index,codec_name:stream_tags=language,title",
            "-of", "json",
            video_path
        ]
        flags = 0x08000000 if os.name == 'nt' else 0
        result = subprocess.run(cmd, capture_output=True, text=True, creationflags=flags, timeout=5)
        if result.returncode != 0:
            return []

        data = json.loads(result.stdout)
        return data.get("streams", [])
    except Exception as e:
        _log_to_file(f" [Subtitle:Probe] Error: {e}")
        return []

# [TAG: #@extract_subtitle_stream]
def extract_subtitle_stream(video_path, stream_index, output_path, ffmpeg_bin):
    """ffmpeg를 사용하여 특정 인덱스의 자막 스트림을 SRT로 추출합니다. (AI냥 요청 🛠️✨)"""
    try:
        # -y: overwrite, -i: input, -map 0:s:N: select subtitle stream, -c:s srt: convert to srt
        cmd = [
            ffmpeg_bin,
            "-y",
            "-i", video_path,
            "-map", f"0:{stream_index}",
            "-c:s", "srt",
            output_path
        ]
        flags = 0x08000000 if os.name == 'nt' else 0
        result = subprocess.run(cmd, capture_output=True, text=True, creationflags=flags, timeout=30)
        return result.returncode == 0
    except Exception as e:
        _log_to_file(f" [Subtitle:Extract] Error: {e}")
        return False

# [TAG: #@extract_internal_subtitles_flow]
def extract_internal_subtitles_flow(v_paths, settings):
    """영상 내부 자막 추출 통합 플로우 (AI냥 요청 🛠️✨)"""
    if not v_paths: return

    fp = _get_ffprobe_bin()
    ff = _get_ffmpeg_bin()

    success_count = 0
    total_files = len(v_paths)

    if total_files > 1:
        print(f"\r\n 🎬 {C.BOLD}{C.SKY}[내장 자막 추출 시작]{C.RESET} 총 {total_files}개 영상 확인 중...")

    for idx, v_path in enumerate(v_paths, 1):
        if not os.path.isfile(v_path): continue

        bn = os.path.basename(v_path)
        print(f"\r\n [{idx}/{total_files}] 🔍 {C.YELLOW}{bn}{C.RESET} 분석 중...")

        streams = get_internal_subtitle_streams(v_path, fp)

        if not streams:
            print(f" ❌ {C.RED}내장된 자막 스트림을 찾지 못했어냥!{C.RESET}")
            continue

        # 텍스트 기반 자막만 필터링 (srt, ass, mov_text 등)
        text_streams = [s for s in streams if s.get('codec_name') in ('subrip', 'mov_text', 'ass', 'text', 'webvtt')]

        if not text_streams:
            print(" ⚠️  이미지 기반 자막(PGS/VOBSUB)만 발견되었어냥. SRT로 바로 뽑는 건 지금은 힘들어냥! 😿")
            continue

        selected_stream = None
        if len(text_streams) == 1:
            selected_stream = text_streams[0]
        else:
            # 여러 개면 메뉴 띄우기냥! 📋
            print(f" 💡 {C.SKY}여러 개의 자막이 발견되었어냥! 어떤 걸 뽑을까냥?{C.RESET}")
            menu_opts = []
            for s in text_streams:
                lang = s.get('tags', {}).get('language', 'und')
                title = s.get('tags', {}).get('title', 'No Title')
                menu_opts.append(f"Stream #{s['index']} ({lang}) - {title}")
            menu_opts.append("❌ 취소")

            sel = _interactive_menu(f"[{bn}] 자막 선택", menu_opts, clear_on_exit=False)
            if sel is None or (isinstance(sel, int) and sel == len(menu_opts) - 1) or sel == -1:
                print(" ⏭️ 이 파일은 건너뛸게냥!")
                continue
            selected_stream = text_streams[sel]

        if selected_stream:
            # 출력 파일명 결정 (임시 추출용)
            temp_srt = os.path.splitext(v_path)[0] + ".internal.srt"
            final_srt = os.path.splitext(v_path)[0] + ".srt"

            print(f" 🚀 자막 추출 중... (Stream #{selected_stream['index']})")
            if extract_subtitle_stream(v_path, selected_stream['index'], temp_srt, ff):
                print(f" ✅ {C.GREEN}추출 성공!{C.RESET} -> 이제 재미니 CLI로 번역을 시작할게냥! 🤖")

                # [V152.28] 재미니 CLI 번역 엔진 가동! 🚀✨
                try:
                    agent = AIAgent([], "gemini-3-flash-preview", log_fn=print)
                    prompt = (
                        "너는 전문 자막 번역가야. 내가 주는 SRT 자막 내용을 한국어로 자연스럽게 번역해줘.\r\n"
                        "중요: 타임스탬프와 인덱스 형식은 절대 건드리지 말고, 대사만 번역해냥! 말투는 AI냥이 좋아하는 친근한 말투로 부탁해냥! 👍"
                    )

                    # [V146.35] 안정적인 직접 호출 모드 사용
                    translated_text = agent.execute_gemini_cli_direct(temp_srt, prompt, is_text_only=False, show_output=True)

                    if translated_text:
                        with open(final_srt, "w", encoding="utf-8") as f:
                            f.write(translated_text.strip())
                        print(f" ✨ {C.BOLD}{C.GREEN}번역 완료!{C.RESET} -> {os.path.basename(final_srt)} 탄생냥! 👍✨")
                        success_count += 1

                        # 임시 파일 정리 (증거 인멸! 🧼)
                        # [V16.3.3] 리소스 정리: 성공 시에만 확실히 삭제냥!
                        if os.path.exists(temp_srt): os.remove(temp_srt)
                    else:
                        # [V16.3.3] 번역 실패 시에는 분석을 위해 파일을 남겨둠 (사용자 안내 강화)
                        print(f" ❌ {C.RED}재미니 CLI 번역에 실패했어냥! 😿{C.RESET} (추출된 원본은 {os.path.basename(temp_srt)}에 남아있어냥)")
                except Exception as ex:
                    # [V16.3.3] 예외 발생 시 상세 로그와 함께 임시 파일 정리
                    print(f" ❌ 번역 중 오류 발생: {ex}")
                    _log_to_file(f"🚨 [extract_internal_subtitles_flow] Error: {traceback.format_exc()}")
                    if os.path.exists(temp_srt):
                        try: os.remove(temp_srt)
                        except: pass
            else:
                print(f" ❌ {C.RED}추출에 실패했어냥! 😿{C.RESET}")

    if success_count > 0:
        print(f"\r\n ✨ {C.BOLD}{C.GREEN}작업 완료!{C.RESET} 총 {success_count}개의 자막을 성공적으로 처리했어냥! 👍✨")
        time.sleep(1)

    return success_count > 0


# [TAG: #@get_bg_dashboard_header_text]
def _get_bg_dashboard_header_text(settings=None):
    """[V21.13] 번쩍임(깜빡임) 0% 더블 버퍼링 지원용 대시보드 헤더 문자열 생성기 🛡️✨"""
    global _G_SUBTITLE_BG_STATUS, _G_SUBTITLE_BG_QUEUE, _G_SUBTITLE_BG_CANCEL_REQUESTED, _G_SUBTITLE_BG_JOBS
    if '_G_SUBTITLE_BG_JOBS' not in globals():
        globals()['_G_SUBTITLE_BG_JOBS'] = {}

    lines = []
    lines.append("="*65)
    lines.append(f"  {C.BOLD}{C.MAGENTA}🔋 [백그라운드 통합 작업 관리 대시보드] 🔋{C.RESET}")
    lines.append("="*65)

    # 1. 자막 작업 파트
    lines.append(f" {C.BOLD}{C.SKY}[ 📝 자막 생성 / 번역 작업 상태 ]{C.RESET}")
    
    active_jobs = list(_G_SUBTITLE_BG_JOBS.values())
    if not active_jobs and _G_SUBTITLE_BG_STATUS.get('active', False):
        active_jobs.append(_G_SUBTITLE_BG_STATUS)
    
    if active_jobs:
        lines.append(f"  🚀 {C.GREEN}{C.BOLD}[진행 중]{C.RESET} 현재 {C.YELLOW}{len(active_jobs)}{C.RESET}개의 백그라운드 자막 작업 활성냥!")
        lines.append("  ┌─────────────────────────────────────────────────────┐")
        for j_idx, job in enumerate(active_jobs):
            curr = job.get('current', 0)
            tot = job.get('total', 0)
            st_text = job.get('status_text', '대기중')
            curr_path = job.get('current_path')
            fn = os.path.basename(curr_path) if curr_path else '알 수 없는 파일'
            if len(fn) > 25:
                fn = fn[:22] + "..."
            lines.append(f"  │  {j_idx+1:2d}. {C.YELLOW}{fn:<25}{C.RESET} [ {C.SKY}{curr}/{tot}{C.RESET} | {st_text} ]")
        lines.append("  └─────────────────────────────────────────────────────┘")
    else:
        lines.append(f"  💤 {C.DIM}[대기 상태]{C.RESET} 현재 실행 중인 백그라운드 자막 작업이 없어냥.")

    with _G_SUBTITLE_BG_QUEUE_LOCK:
        q_len = len(_G_SUBTITLE_BG_QUEUE)
        q_copy = list(_G_SUBTITLE_BG_QUEUE)

    lines.append(f"  ⏳ {C.BOLD}자막 대기 큐:{C.RESET} {C.SKY}{q_len}{C.RESET}개")
    if q_len > 0:
        lines.append("  ┌─────────────────────────────────────────────────────┐")
        for idx, item in enumerate(q_copy):
            v_paths = item[0]
            first_fn = os.path.basename(v_paths[0])
            if len(first_fn) > 30:
                first_fn = first_fn[:27] + "..."
            add_msg = f"외 {len(v_paths)-1}개" if len(v_paths) > 1 else ""
            lines.append(f"  │  {idx+1:2d}. {first_fn} {add_msg}")
        lines.append("  └─────────────────────────────────────────────────────┘")

    lines.append("-" * 65)

    # 2. 스텔스 백그라운드 다운로드 파트 (Miss19 & 유튜브) 📥✨
    lines.append(f" {C.BOLD}{C.GOLD}[ 📥 스텔스 백그라운드 다운로드 작업 상태 ]{C.RESET}")
    
    stealth_tasks = globals().get('_G_STEALTH_BG_TASKS', [])
    bg_dl_status = globals().get('G_BG_DOWNLOAD_STATUS', {})
    
    seen_active_ids = set()
    active_bg_items = []
    for url, info in bg_dl_status.items():
        if isinstance(info, dict) and info.get('status') == 'downloading':
            obj_id = id(info)
            if obj_id not in seen_active_ids:
                seen_active_ids.add(obj_id)
                active_bg_items.append((url, info))

    seen_finished_ids = set()
    finished_bg_items = []
    for url, info in bg_dl_status.items():
        if isinstance(info, dict) and info.get('status') == 'finished':
            obj_id = id(info)
            if obj_id not in seen_finished_ids:
                seen_finished_ids.add(obj_id)
                finished_bg_items.append((url, info))
    
    if stealth_tasks:
        lines.append(f"  🚀 {C.GREEN}{C.BOLD}[진행 중]{C.RESET} 현재 {C.YELLOW}{len(stealth_tasks)}{C.RESET}개의 백그라운드 다운로드 작업 진행 중이다냥!")
        lines.append("  ┌─────────────────────────────────────────────────────┐")
        for idx, task in enumerate(stealth_tasks):
            title = task.get('title', '알 수 없는 영상')
            if len(title) > 25:
                title = title[:22] + "..."
            
            v_url = task.get('v_url')
            pct = "0.0%"
            speed = "--"
            eta = "--:--"
            index = task.get('index', idx + 1)
            total = task.get('total', len(stealth_tasks))
            if v_url and v_url in bg_dl_status:
                pct = bg_dl_status[v_url].get('pct', '0.0%')
                speed = bg_dl_status[v_url].get('speed', '0B/s')
                eta = bg_dl_status[v_url].get('eta', '--:--')
                index = bg_dl_status[v_url].get('index', index)
                total = bg_dl_status[v_url].get('total', total)
            
            lines.append(f"  │  {idx+1:2d}. [{index}/{total}] {C.YELLOW}{title:<25}{C.RESET} [ {C.SKY}{pct:>6}{C.RESET} | {speed} | 남음: {eta} ]")
        lines.append("  └─────────────────────────────────────────────────────┘")
    elif active_bg_items:
        lines.append(f"  🚀 {C.GREEN}{C.BOLD}[진행 중]{C.RESET} 현재 {C.YELLOW}{len(active_bg_items)}{C.RESET}개의 다운로드 작업 진행 중이다냥!")
        lines.append("  ┌─────────────────────────────────────────────────────┐")
        for idx, (url, info) in enumerate(active_bg_items):
            title = info.get('title', '알 수 없는 영상')
            if len(title) > 25:
                title = title[:22] + "..."
            pct = info.get('pct', '0.0%')
            speed = info.get('speed', '0B/s')
            eta = info.get('eta', '--:--')
            index = info.get('index', idx + 1)
            total = info.get('total', len(active_bg_items))
            lines.append(f"  │  {idx+1:2d}. [{index}/{total}] {C.YELLOW}{title:<25}{C.RESET} [ {C.SKY}{pct:>6}{C.RESET} | {speed} | 남음: {eta} ]")
        lines.append("  └─────────────────────────────────────────────────────┘")
    else:
        lines.append(f"  💤 {C.DIM}[대기 상태]{C.RESET} 현재 다운로드 중인 작업이 없다냥.")
        
    if finished_bg_items:
        lines.append(f"  ✅ {C.GREEN}{C.BOLD}[완료]{C.RESET} 최근 {C.YELLOW}{len(finished_bg_items)}{C.RESET}개의 다운로드가 정상 완료되었어냥! 🎉")
        lines.append("  ┌─────────────────────────────────────────────────────┐")
        for idx, (url, info) in enumerate(finished_bg_items[-5:]):
            raw_title = info.get('title') or ''
            if not raw_title or raw_title.startswith('http'):
                raw_title = info.get('filename') or os.path.basename(info.get('file_path', '')) or raw_title or '완료된 영상'
            title = os.path.splitext(raw_title)[0]
            if len(title) > 28:
                title = title[:25] + "..."
            lines.append(f"  │  {idx+1:2d}. 🎬 {C.GREEN}{title:<28}{C.RESET} [ {C.GREEN}100% 완료{C.RESET} | 📁 저장완료! ]")
        lines.append("  └─────────────────────────────────────────────────────┘")
        
    # [V176.7] 영구 저장된 다운로드 대기 큐 표시 ⏳📥✨
    try:
        dl_persist_q = _load_download_queue_persist()
    except Exception:
        dl_persist_q = []
    
    dl_q_len = len(dl_persist_q)
    lines.append(f"  ⏳ {C.BOLD}다운로드 대기 큐:{C.RESET} {C.SKY}{dl_q_len}{C.RESET}개")
    if dl_q_len > 0:
        lines.append("  ┌─────────────────────────────────────────────────────┐")
        for idx, item in enumerate(dl_persist_q[:5]):
            title = item.get('title', '알 수 없는 영상') if isinstance(item, dict) else str(item)
            if len(title) > 30:
                title = title[:27] + "..."
            lines.append(f"  │  {idx+1:2d}. {title}")
        if dl_q_len > 5:
            lines.append(f"  │  ... 외 {dl_q_len - 5}개 대기 중")
        lines.append("  └─────────────────────────────────────────────────────┘")
    
    lines.append("-" * 65)

    # 3. Pixiv 백그라운드 다운로드 파트 🎨⚡ (직접/작가 즉시 다운로드 + 대기 큐)
    lines.append(f" {C.BOLD}{C.GOLD}[ 🎨 Pixiv 백그라운드 다운로드 작업 상태 ]{C.RESET}")

    if is_pixiv_bg_downloading():
        pixiv_now = _PIXIV_BG_DOWNLOAD_STATUS or "⏳ 작업 실행 준비 중..."
        with _PIXIV_BG_JOB_LOCK:
            pixiv_q = list(_PIXIV_BG_JOB_QUEUE)
        lines.append(f"  🚀 {C.GREEN}{C.BOLD}[진행 중]{C.RESET} {C.YELLOW}{pixiv_now}{C.RESET}")
        if pixiv_q:
            lines.append("  ┌─────────────────────────────────────────────────────┐")
            for qi, qj in enumerate(pixiv_q[:5]):
                qs = str(qj.get('status', '대기 중'))
                if len(qs) > 30:
                    qs = qs[:27] + "..."
                lines.append(f"  │  {qi+1:2d}. ⏳ {qs}")
            if len(pixiv_q) > 5:
                lines.append(f"  │  ... 외 {len(pixiv_q)-5}개 대기 중")
            lines.append("  └─────────────────────────────────────────────────────┘")
        # 📊 [규칙] 실행 중에는 진행률 수치를 별도 줄로도 보여준다 (아래 상태문만으로는 줄이 길 때 잘릴 수 있음)
        try:
            with _PIXIV_BG_PROGRESS_LOCK:
                _pp = dict(_PIXIV_BG_PROGRESS)
                _pp["running"] = list(_PIXIV_BG_PROGRESS.get("running") or [])
            if int(_pp.get("total") or 0) > 0:
                lines.append(f"  📊 진행률 {C.SKY}{_pp.get('done', 0)}/{_pp['total']}명{C.RESET} 완료 · "
                             f"신규 파일 {C.YELLOW}{_pp.get('new_cnt', 0)}개{C.RESET}"
                             + (f" · 작업중 {C.CYAN}{', '.join(_pp['running'][:4])}{C.RESET}" if _pp['running'] else ""))
        except Exception:
            pass
        # 🔍 [규칙] print_output=False 라 화면에 안 나오는 gallery-dl 오류/경고를 여기서 1줄로 노출
        _live_err = globals().get('_PIXIV_BG_LIVE_ERR', '')
        if _live_err:
            lines.append(f"  ⚠️ {C.RED}최근 오류/경고{C.RESET} {C.DIM}{_live_err}{C.RESET}")
    else:
        lines.append(f"  💤 {C.DIM}[대기 상태]{C.RESET} 현재 실행/대기 중인 Pixiv 백그라운드 다운로드가 없다냥.")

    # [Pixiv NEW] 영속 대기열 (앱 재시작 이어받기) — 작품 URL 1개 = 1칸, 완료되면 자동 제거 🗑️
    if _PIXIV_QUEUE_PENDING:
        lines.append(f"  📦 {C.CYAN}[영속 대기열]{C.RESET} 미완료 작품 {C.YELLOW}{_PIXIV_QUEUE_PENDING}개{C.RESET} "
                     f"{C.DIM}(temp/pixiv_queue.json · 앱 재시작 시 자동 이어받기){C.RESET}")

    # ⏸ 일시정지 안내 (2026-10-04) — 취소(🛑)와 달리 보존 상태임을 명시
    if is_pixiv_bg_paused():
        try:
            _pst = _load_pixiv_pause_state() or {}
        except Exception:
            _pst = {}
        _rem = _pst.get("remaining_artists") or []
        lines.append(f"  ⏸ {C.YELLOW}{C.BOLD}[일시정지됨]{C.RESET} 미완료 작가 {C.YELLOW}{len(_rem)}명{C.RESET}"
                     f" · 대기 큐 {C.YELLOW}{_pst.get('queue_left', 0)}개{C.RESET} 보존"
                     f" {C.DIM}(temp/pixiv_pause_state.json · 앱 껐다 켜도 재개 가능){C.RESET}")

    _plr = _PIXIV_BG_LAST_RESULT
    if _plr and not is_pixiv_bg_downloading():
        if _plr.get('cancelled'):
            lines.append(f"  ⛔ {C.RED}{C.BOLD}[중단됨]{C.RESET} ✋ 취소로 중단 — 취소 시점까지 {C.YELLOW}{_plr.get('new_cnt', 0)}{C.RESET}개 수집됨 ({_plr.get('time', '')})")
        else:
            _plr_err = str(_plr.get('err') or '').strip()
            if len(_plr_err) > 220:   # 장시간 실행 시 오류가 길어질 수 있어 표시만 축약 🛡️
                _plr_err = _plr_err[:217].replace("\n", " ") + "..."
            lines.append(f"  🏁 {C.GREEN}{C.BOLD}[최근 완료]{C.RESET} 새 파일 {C.YELLOW}{_plr.get('new_cnt', 0)}{C.RESET}개 수집 ({_plr.get('time', '')})"
                         + (f" ⚠️ {_plr_err}" if _plr_err else ""))

    lines.append("="*65)
    return "\n".join(lines)


# [TAG: #@manage_subtitle_bg_queue_interactive]
def manage_subtitle_bg_queue_interactive(settings):
    """
    [V21.13] 백그라운드 자막 작업 및 스텔스 다운로드 상태를 모니터링하고 취소/조작하는 대화형 메뉴냥! ⚙️🔋✨ (번쩍임 0% 패치)
    """
    global _G_SUBTITLE_BG_STATUS, _G_SUBTITLE_BG_QUEUE, _G_SUBTITLE_BG_CANCEL_REQUESTED, _G_SUBTITLE_BG_JOBS
    global _G_SHOW_BACKGROUND_LOGS, _G_BACKGROUND_LOG_BUFFER, _G_BACKGROUND_LOG_LOCK
    global _G_SHOW_DOWNLOAD_LOGS, _G_DOWNLOAD_LOG_BUFFER, _G_DOWNLOAD_LOG_LOCK
    if '_G_SUBTITLE_BG_JOBS' not in globals():
        globals()['_G_SUBTITLE_BG_JOBS'] = {}

    _first_draw = True
    while True:
        if _first_draw:
            clear_console(push_history=True)
            _first_draw = False

        active_jobs = list(_G_SUBTITLE_BG_JOBS.values())
        if not active_jobs and _G_SUBTITLE_BG_STATUS.get('active', False):
            active_jobs.append(_G_SUBTITLE_BG_STATUS)
        is_bg_active = len(active_jobs) > 0

        with _G_SUBTITLE_BG_QUEUE_LOCK:
            q_len = len(_G_SUBTITLE_BG_QUEUE)

        stealth_tasks = globals().get('_G_STEALTH_BG_TASKS', [])
        bg_dl_status = globals().get('G_BG_DOWNLOAD_STATUS', {})
        active_dl_count = len(stealth_tasks)

        menu_opts = [
            "🔄   진행 상황 새로고침",
            구분선("실시간 로그 모니터링", icon="📺", width=65),
        ]
        
        menu_opts.append("📺   실시간 자막 로그 모니터링 🔍")
        menu_opts.append("📥   실시간 다운로드 로그 모니터링 (yt-dlp) 🔍")

        menu_opts.append(구분선("작업 실행 모드 설정", icon="⚙️", width=65))

        sub_bg_mode = True
        if hasattr(settings, 'data') and isinstance(settings.data, dict):
            sub_bg_mode = settings.data.get("subtitle_bg_mode", True)
        elif isinstance(settings, dict):
            sub_bg_mode = settings.get("subtitle_bg_mode", True)

        if sub_bg_mode:
            menu_opts.append(f"📝   자막 모드: {C.GREEN}{C.BOLD}백그라운드 큐 🟢{C.RESET} (토글)")
        else:
            menu_opts.append(f"📝   자막 모드: {C.RED}{C.BOLD}포어그라운드 실시간 🔴{C.RESET} (토글)")

        dl_bg_mode = True
        if hasattr(settings, 'data') and isinstance(settings.data, dict):
            dl_bg_mode = settings.data.get("download_bg_mode", settings.data.get("s_m_b_d", True))
        elif isinstance(settings, dict):
            dl_bg_mode = settings.get("download_bg_mode", settings.get("s_m_b_d", True))

        if dl_bg_mode:
            menu_opts.append(f"📥   다운로드 모드: {C.GREEN}{C.BOLD}백그라운드 스텔스 🟢{C.RESET} (토글)")
        else:
            menu_opts.append(f"📥   다운로드 모드: {C.RED}{C.BOLD}포어그라운드 실시간 🔴{C.RESET} (토글)")

        pl_refresh_mode = True
        if hasattr(settings, 'data') and isinstance(settings.data, dict):
            pl_refresh_mode = settings.data.get("auto_playlist_refresh", True)
        elif isinstance(settings, dict):
            pl_refresh_mode = settings.get("auto_playlist_refresh", True)

        if pl_refresh_mode:
            menu_opts.append(f"🔄   플레이리스트 자동 새로고침: {C.GREEN}{C.BOLD}ON 🟢{C.RESET} (토글)")
        else:
            menu_opts.append(f"🔄   플레이리스트 자동 새로고침: {C.RED}{C.BOLD}OFF ⚫{C.RESET} (토글)")

        menu_opts.append(구분선("작업 제어 및 전체 취소", icon="🛑", width=65))

        if is_bg_active or q_len > 0:
            menu_opts.append("🛑   자막 작업 취소 (진행 작업 및 대기열 비우기)")
        else:
            menu_opts.append("❌   자막 작업 취소 (대기열 없음)")

        seen_active_ids = set()
        active_bg_items = []
        for url, info in bg_dl_status.items():
            if isinstance(info, dict) and info.get('status') == 'downloading':
                obj_id = id(info)
                if obj_id not in seen_active_ids:
                    seen_active_ids.add(obj_id)
                    active_bg_items.append((url, info))

        seen_finished_ids = set()
        finished_bg_items = []
        for url, info in bg_dl_status.items():
            if isinstance(info, dict) and info.get('status') == 'finished':
                obj_id = id(info)
                if obj_id not in seen_finished_ids:
                    seen_finished_ids.add(obj_id)
                    finished_bg_items.append((url, info))
        persist_dl_items = _load_download_queue_persist()
        if active_dl_count > 0 or active_bg_items or persist_dl_items:
            menu_opts.append("🛑   다운로드 취소 (진행 작업 및 대기열 비우기)")
        elif finished_bg_items:
            menu_opts.append("🧹   완료 목록 비우기 (다운로드 기록 정리)")
        else:
            menu_opts.append("❌   다운로드 취소 (진행 중인 작업 없음)")

        # ⏸ 일시정지 / ▶ 재개 (2026-10-04) — 취소와 달리 큐·대기열을 보존한다
        if is_pixiv_bg_paused():
            menu_opts.append("▶   Pixiv 백그라운드 다운로드 재개 (일시정지 해제, 남은 것만 이어받기)")
        elif is_pixiv_bg_downloading():
            menu_opts.append("⏸   Pixiv 백그라운드 다운로드 일시정지 (대기열 그대로 보존)")

        if is_pixiv_bg_downloading():
            menu_opts.append("🎨   Pixiv 백그라운드 다운로드 취소 (진행 중 ⚡)")
        else:
            menu_opts.append("🎨   Pixiv 백그라운드 다운로드 취소 (진행 없음)")

        menu_opts.append(구분선("시스템 & 네트워크 진단", icon="📊", width=65))

        menu_opts.append("🌐   실시간 웹/미디어 접속자 확인 및 IP 차단 관리 🛡️")
        menu_opts.append("📊   네트워크 실시간 사용량 체크")
        menu_opts.append("🖥️   작업관리자 열기")

        menu_opts.append(구분선(width=65))
        menu_opts.append("↩️   이전 화면으로 돌아가기")

        def _dash_header_cb(selected_idx=0):
            return _get_bg_dashboard_header_text(settings)

        raw_idx, key_pressed, *_ = _interactive_menu(
            "💡 원하시는 작업을 선택해줘냥!", 
            menu_opts, 
            timeout=None, 
            truncate=False, 
            is_bg_dashboard=True, 
            refresh_timeout=1.5,
            dynamic_header_callback=_dash_header_cb
        )
        
        if key_pressed == "EXIT_PROGRAM":
            _exit_app_safely(settings)
            break

        if raw_idx is None or key_pressed == "REFRESH":
            continue

        if raw_idx < 0 or key_pressed in ("TOGGLE_BG_MANAGE", "BG_MANAGE"):
            break
        
        _sel_item = menu_opts[raw_idx] if (raw_idx is not None and 0 <= raw_idx < len(menu_opts)) else ""
        _opt_str = str(_sel_item.get('label', _sel_item) if isinstance(_sel_item, dict) else _sel_item)

        if "플레이리스트" in _opt_str:
            # [신규] 다운로드 완료 시 플레이리스트 자동 새로고침 토글 🔄✨
            curr_pl = True
            if hasattr(settings, 'data') and isinstance(settings.data, dict):
                curr_pl = settings.data.get("auto_playlist_refresh", True)
            elif isinstance(settings, dict):
                curr_pl = settings.get("auto_playlist_refresh", True)
            new_pl = not curr_pl

            if hasattr(settings, 'data') and isinstance(settings.data, dict):
                settings.data["auto_playlist_refresh"] = new_pl
            elif isinstance(settings, dict):
                settings["auto_playlist_refresh"] = new_pl

            if hasattr(settings, 'save'):
                settings.save()

            st_text = f"{C.GREEN}{C.BOLD}ON 🟢{C.RESET}" if new_pl else f"{C.RED}{C.BOLD}OFF ⚫{C.RESET}"
            print(f"\r\n 🔄 {C.GREEN}{C.BOLD}[플레이리스트 자동 새로고침 변경]{C.RESET} 다운로드 완료 시 플레이리스트 자동 새로고침이 {st_text}(으)로 전환되었어냥!")
            time.sleep(1.2)
            continue
        elif "새로고침" in _opt_str:
            continue
        elif "자막 로그" in _opt_str:
            show_background_subtitle_log_monitor()
            continue
        elif "다운로드 로그" in _opt_str:
            # [V175.0 NEW] 다운로드 (yt-dlp) 실시간 로그 토글 📥✨
            _G_SHOW_DOWNLOAD_LOGS = not _G_SHOW_DOWNLOAD_LOGS
            if _G_SHOW_DOWNLOAD_LOGS:
                clear_console()
                print("="*65)
                print(f" 📥 {C.GREEN}{C.BOLD}[실시간 백그라운드 다운로드 (yt-dlp) 로그 모니터링 모드]{C.RESET}")
                print(f" 💡 {C.CYAN}아무 키나 누르면 대시보드로 돌아가고 로그가 다시 백그라운드로 전환됩니다냥!{C.RESET}")
                print("="*65)
                # 이전 버퍼 출력 (없으면 debug.log 최근 내용 가져오기)
                with _G_DOWNLOAD_LOG_LOCK:
                    stream = getattr(sys.stdout, 'original_stream', sys.stdout)
                    if _G_DOWNLOAD_LOG_BUFFER:
                        stream.write("".join(_G_DOWNLOAD_LOG_BUFFER))
                        stream.flush()
                        _G_DOWNLOAD_LOG_BUFFER.clear()
                    else:
                        try:
                            if os.path.exists(LOG_PATH):
                                with open(LOG_PATH, 'r', encoding='utf-8-sig', errors='ignore') as lf:
                                    lines = lf.readlines()[-300:]
                                _dl_kw = ("download", "ytdl", "stealth", "m3u8", "cdn", "resume dl", "ph 페이지", "pornhub", "missav", "hentaihaven", "yt_dlp")
                                recent_dl = [ln for ln in lines if any(k in ln.lower() for k in _dl_kw)]
                                if recent_dl:
                                    stream.write("".join(recent_dl[-50:]))
                                    stream.flush()
                        except: pass
                
                # 키보드 입력이 있을 때까지 대기
                try:
                    while True:
                        if msvcrt.kbhit():
                            msvcrt.getch() # 버퍼 소거
                            break
                        time.sleep(0.1)
                except KeyboardInterrupt:
                    pass
                
                _G_SHOW_DOWNLOAD_LOGS = False
                clear_console()
                print(f"\r\n 📥 {C.RED}다운로드 로그 모니터링 모드를 종료하고 백그라운드로 전환합니다냥!{C.RESET}")
                time.sleep(1)
            continue
        elif "자막 모드" in _opt_str:
            # [V174.0 NEW] 자막 작업 모드 토글 📝✨
            curr_s = True
            if hasattr(settings, 'data') and isinstance(settings.data, dict):
                curr_s = settings.data.get("subtitle_bg_mode", True)
            elif isinstance(settings, dict):
                curr_s = settings.get("subtitle_bg_mode", True)
            new_s = not curr_s

            if hasattr(settings, 'data') and isinstance(settings.data, dict):
                settings.data["subtitle_bg_mode"] = new_s
                settings.data["use_bg_thread_subtitle"] = new_s
            elif isinstance(settings, dict):
                settings["subtitle_bg_mode"] = new_s
                settings["use_bg_thread_subtitle"] = new_s

            if hasattr(settings, 'save'):
                settings.save()

            st_text = f"{C.GREEN}{C.BOLD}백그라운드 큐 🟢{C.RESET}" if new_s else f"{C.RED}{C.BOLD}포어그라운드 실시간 🔴{C.RESET}"
            print(f"\r\n 📝 {C.GREEN}{C.BOLD}[자막 모드 변경]{C.RESET} 자막 작업 모드가 {st_text}(으)로 전환되었어냥!")
            time.sleep(1.2)
            continue
        elif "다운로드 모드" in _opt_str:
            # [V174.0 NEW] 다운로드 모드 토글 📥✨
            curr_d = True
            if hasattr(settings, 'data') and isinstance(settings.data, dict):
                curr_d = settings.data.get("download_bg_mode", settings.data.get("s_m_b_d", True))
            elif isinstance(settings, dict):
                curr_d = settings.get("download_bg_mode", settings.get("s_m_b_d", True))
            new_d = not curr_d

            if hasattr(settings, 'data') and isinstance(settings.data, dict):
                settings.data["download_bg_mode"] = new_d
                settings.data["s_m_b_d"] = new_d
            elif isinstance(settings, dict):
                settings["download_bg_mode"] = new_d
                settings["s_m_b_d"] = new_d

            if hasattr(settings, 'save'):
                settings.save()

            st_text = f"{C.GREEN}{C.BOLD}백그라운드 스텔스 🟢{C.RESET}" if new_d else f"{C.RED}{C.BOLD}포어그라운드 실시간 🔴{C.RESET}"
            print(f"\r\n 📥 {C.GREEN}{C.BOLD}[다운로드 모드 변경]{C.RESET} 다운로드 실행 모드가 {st_text}(으)로 전환되었어냥!")
