# [TAG: #@_get_local_playlist_file_map]
def _get_local_playlist_file_map():
    """[V111.0] 모든 플레이리스트 파일을 스캔하여 {ID/파일명: 전체경로} 매핑 맵 생성 🕵️‍♂️✨"""
    playlist_dir = _get_playlists_dir()
    file_map = {} # { "key": "path" }

    if not os.path.exists(playlist_dir):
        return file_map

    # 품번 패턴 (예: FC2-PPV-1234567, MGS-1234 등)
    id_pattern = re.compile(r'([a-zA-Z0-9]{2,10}-[a-zA-Z0-9]{2,10}-\d+|[a-zA-Z0-9]{2,10}-\d+)')

    for f in os.listdir(playlist_dir):
        if f.endswith(".m3u8"):
            p_path = os.path.join(playlist_dir, f)
            try:
                with open(p_path, "r", encoding="utf-8") as file:
                    lines = file.readlines()
                    for line in lines:
                        line = line.strip()
                        if line and not line.startswith("#") and os.path.exists(line):
                            # 실제 존재하는 파일 경로인 경우
                            basename = os.path.basename(line)
                            # 1. 파일명 전체(확장자 제외) 등록
                            name_wo_ext = os.path.splitext(basename)[0]
                            file_map[name_wo_ext.lower()] = line

                            # 2. 품번 패턴 추출 및 등록
                            ids = id_pattern.findall(basename)
                            for item_id in ids:
                                file_map[item_id.lower()] = line
                        elif line and not line.startswith("#") and line.startswith(('http://', 'https://')):
                            # 스트리밍 주소는 일단 스킵 (또는 필요시 추가 가능)
                            pass
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")
    return file_map

# [TAG: #@_build_sm_download_file_map]
def _build_sm_download_file_map(save_dir: str) -> dict:
    """[v3.4] 다운로드 폴더의 실제 .mp4/.mkv 파일을 직접 스캔하여
    ID/제목 양방향 매칭이 가능한 파일맵 생성 🗂️🔍

    v3.4 개선:
    - en dash(–, U+2013) / em dash(—, U+2014) 정규화 추가
    - 이모지 문자 제거 추가
    - prefix 키도 40자로 확장

    Returns:
        { normalized_key: full_path }  (키: 소문자 정규화, 특수문자 제거)
    """
    file_map = {}
    if not save_dir or not os.path.exists(save_dir):
        return file_map

    # [v3.4 / V193.0] en/em dash, 전각 파이프(｜), 구드 특수 홑따옴표(‛) 및 스마트 따옴표 포함 정규화 패턴
    _CLEAN = re.compile(r'[\s\u2013\u2014\-_\.\[\]()【】「」『』:：|｜,，!！?？#＃&＆\'\"‛‘’“”′″‚„‹›·•]+')
    # [v3.4] 이모지/특수 유니코드 구역 제거
    _EMOJI = re.compile(
        r'[\U00010000-\U0010ffff]'   # 보충 다국어 평면 (이모지 대부분)
        r'|[\u2600-\u27ff]'          # 기타 기호 (♠♣ 등)
        r'|[\ufe00-\ufe0f]'          # 변형 선택자
        r'|[\u200b-\u200f]'          # 제로폭 공백 등
    )

    # [TAG: #@_normalize]
    def _normalize(s: str) -> str:
        """이모지 제거 → 특수문자 공백화 → 소문자 정규화"""
        s = _EMOJI.sub(' ', s)
        return _CLEAN.sub(' ', s).strip().lower()

    for fname in os.listdir(save_dir):
        if not fname.lower().endswith(('.mp4', '.mkv', '.avi', '.mov', '.wmv')):
            continue
        full_path = os.path.join(save_dir, fname)
        stem = os.path.splitext(fname)[0]

        # 1. 파일명 전체(소문자) 등록
        file_map[stem.lower()] = full_path

        # 2. 정규화된 키 등록
        norm = _normalize(stem)
        if norm:
            file_map[norm] = full_path

        # 3. 앞 40자 prefix 등록 (제목 앞부분 매칭)
        if len(norm) > 10:
            file_map[norm[:40]] = full_path

    return file_map


# [TAG: #@_sm_is_local_match]
def _sm_is_local_match(r_id: str, r_title: str, file_map: dict) -> tuple:
    """[v3.4] 영상 ID와 제목을 file_map에 대해 양방향 매칭 🔍

    v3.4 개선:
    - en/em dash, 이모지 정규화 추가
    - prefix 비교 → Jaccard 단어 교집합 비율(65% 이상) 방식으로 개선
      → "Sex Vlog – Sex Diaries" vs "Sex Vlog - London | Sex Diaries" 같은 케이스 대응

    Returns:
        (is_match: bool, matched_path: str | None)
    """
    # [v3.4 / V193.0] en/em dash, 전각 파이프(｜), 구드 특수 홑따옴표(‛) 및 스마트 따옴표 포함 정규화 패턴
    _CLEAN = re.compile(r'[\s\u2013\u2014\-_\.\[\]()【】「」『』:：|｜,，!！?？#＃&＆\'\"‛‘’“”′″‚„‹›·•]+')
    _EMOJI = re.compile(
        r'[\U00010000-\U0010ffff]'
        r'|[\u2600-\u27ff]'
        r'|[\ufe00-\ufe0f]'
        r'|[\u200b-\u200f]'
    )

    # [TAG: #@_norm]
    def _norm(s: str) -> str:
        s = _EMOJI.sub(' ', s)
        return _CLEAN.sub(' ', s).strip().lower()

    r_id_l  = r_id.lower()
    r_tit_n = _norm(r_title)

    # 1. ID 직접 포함 매칭 (의미 있는 ID만, 예: viewkey, 품번 등)
    if r_id_l and len(r_id_l) >= 4 and r_id_l not in ('link', 'unknown', 'none'):
        for key, path in file_map.items():
            if r_id_l in key:
                return True, path

    # 2. Jaccard 단어 교집합 비율 매칭 (en dash 등 특수문자 차이에도 robust)
    if r_tit_n and len(r_tit_n) >= 5:
        # 의미 있는 단어만 추출 (2자 이상, 숫자 제외 단어도 포함)
        tit_words = set(w for w in r_tit_n.split() if len(w) >= 2)
        if len(tit_words) >= 3:
            best_ratio = 0.0
            best_path  = None
            for key, path in file_map.items():
                key_words = set(w for w in key.split() if len(w) >= 2)
                if not key_words:
                    continue
                inter = len(tit_words & key_words)
                
                # 방어 로직: 로컬 파일명의 단어가 1~2개로 너무 적을 때(예: sub.mp4)
                # 부분 일치(Overlap) 허용 시 엄청난 False Positive가 발생합니다.
                # 따라서 단어가 적을 때는 max()를 써서 엄격한 Jaccard 유사도로 판정합니다.
                if len(key_words) < 3:
                    denominator = max(len(tit_words), len(key_words))
                else:
                    denominator = min(len(tit_words), len(key_words))
                    
                ratio = inter / denominator
                if ratio > best_ratio:
                    best_ratio = ratio
                    best_path  = path
            if best_ratio >= 0.65:  # 65% 이상 단어 일치 시 매칭
                return True, best_path

    return False, None

from functools import lru_cache

_history_lock = threading.Lock()
_bridge_lock = threading.Lock()
@lru_cache(maxsize=256)
# [TAG: #@_get_media_metadata_fancy]
def _get_media_metadata_fancy(file_path):
    """[V111.0] ffprobe를 활용하여 영상 메타데이터(용량, 시간)를 펜시하게 포맷팅 🎬✨"""
    if not file_path or not os.path.exists(file_path):
        return None

    try:
        # 1. 파일 크기
        size_bytes = os.path.getsize(file_path)
        size_gb = size_bytes / (1024**3)
        size_mb = size_bytes / (1024**2)
        size_str = f"{size_gb:.1f}GB" if size_gb >= 1 else f"{int(size_mb)}MB"

        # 2. 재생 시간 (ffprobe 사용)
        duration_str = "Unknown"
        # ffprobe.exe가 스크립트 경로에 있는지 확인
        ffprobe_exe = _get_ffprobe_bin()

        cmd = [
            ffprobe_exe, "-v", "error", "-show_entries", "format=duration",
            "-of", "default=noprint_wrappers=1:nokey=1", file_path
        ]

        # [V111.0] Windows에서 검은 창 방지 (creationflags)
        c_flags = 0
        if os.name == 'nt':
            c_flags = 0x08000000 # CREATE_NO_WINDOW

        result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, creationflags=c_flags)
        if result.returncode == 0 and result.stdout.strip():
            duration_sec = safe_float(result.stdout.strip())
            mins = int(duration_sec // 60)
            duration_str = f"{mins}min"

        # 3. 펜시한 포맷팅 (사용자 요청: 파일명 용량 재생시간)
        basename = os.path.basename(file_path)
        # 너무 길면 자름
        display_name = basename[:55] + "..." if len(basename) > 58 else basename

        banner = (
            f"  {C.BOLD}{C.PURPLE}🏠 [Local Match]{R} "
            f"{C.WHITE}{display_name}{R} │ "
            f"{C.GOLD}{size_str}{R} │ "
            f"{C.SKY}{duration_str}{R}"
        )
        return banner
    except:
        return None


# [TAG: #@_cleanup_orphaned_subtitles]
def _cleanup_orphaned_subtitles(settings):
    """[V64.0] 플레이리스트 폴더 내 동영상 없는 나홀로 자막(.srt)을 휴지통으로 이동합니다. 🧹"""
    try:
        from send2trash import send2trash
        groups = settings.data.get("playlist_groups", {})
        music_groups = settings.data.get("playlist_music_groups", {})

        all_folders = []
        for folders in groups.values(): all_folders.extend(folders)
        for folders in music_groups.values(): all_folders.extend(folders)

        # 중복 제거 및 유효한 경로만 필터링
        target_folders = sorted(list(set([os.path.abspath(f) for f in all_folders if os.path.isdir(f)])))

        if not target_folders:
            print(f"\r\n ⚠️ {C.RED}체크할 플레이리스트 폴더가 등록되어 있지 않아!{C.RESET}")
            time.sleep(1.5)
            return

        video_extensions = ('.mp4', '.mkv', '.avi', '.mov', '.wmv', '.flv', '.webm', '.ts', '.m2ts', '.m4v')

        print(f"\r\n 🔍 {C.SKY}나홀로 자막(동영상 없는 .srt)을 찾고 있어...{C.RESET}")
        found_orphans = []

        for folder in target_folders:
            try:
                # 해당 폴더의 모든 파일 목록
                all_files = os.listdir(folder)
                srt_files = [f for f in all_files if f.lower().endswith('.srt')]
                video_files = [f for f in all_files if f.lower().endswith(video_extensions)]

                # 동영상 파일 이름(확장자 제외) 집합 생성
                video_basenames = {os.path.splitext(v)[0] for v in video_files}

                for srt in srt_files:
                    basename = os.path.splitext(srt)[0]
                    if basename not in video_basenames:
                        found_orphans.append(os.path.join(folder, srt))
            except Exception as fe:
                _log_to_file(f"[_cleanup_orphaned_subtitles Folder Error] {folder}: {fe}")

        if not found_orphans:
            print(f"\r\n ✨ {C.GREEN}깨끗해! 동영상 없는 나홀로 자막이 하나도 없어!{C.RESET}")
            time.sleep(1.5)
            return

        print(f"\r\n 🗑️ {C.YELLOW}총 {len(found_orphans)}개의 나홀로 자막을 발견했어!{C.RESET}")
        # 너무 많으면 리스트 생략
        display_limit = 20
        for i, path in enumerate(found_orphans[:display_limit]):
            print(f"   - {C.DIM}{os.path.basename(path)}{C.RESET}")
        if len(found_orphans) > display_limit:
            print(f"   ... 외 {len(found_orphans) - display_limit}개 생략")

        ans = prompt_input(f"\r\n 👉 {C.SKY}이 파일들을 모두 휴지통으로 보낼까? (Y/n): {C.RESET}").strip().lower()
        if ans in ('y', ''):
            success_count = 0
            for path in found_orphans:
                try:
                    send2trash(path)
                    success_count += 1
                except Exception as e:
                    print(f" ❌ {os.path.basename(path)} 이동 실패: {e}")
            print(f"\r\n ✅ {C.GREEN}성공적으로 {success_count}개의 파일을 휴지통으로 비웠어냥!{C.RESET}")
        else:
            print(f"\r\n ❌ {C.YELLOW}정리 작업을 취소했어.{C.RESET}")

    except Exception as e:
        print(f"\r\n ❌ 오류 발생: {e}")
        _log_to_file(f"[_cleanup_orphaned_subtitles Exception] {e}")

    time.sleep(2)


# [TAG: #@duplicate_finder_interactive]
def duplicate_finder_interactive(settings):
    """중복 파일 찾기 대화형 메뉴"""
    # [수정] monitored, R 변수 초기화 추가 (NameError 방지)
    monitored = settings.data.get("monitored_folders", [])
    R = C.RESET
    
    try:
        while True:
            _print_standard_menu_header("duplicate_finder", settings)

            options_map = [
                {"label": " ➕ 검사할 폴더 추가하기", "key": "add"},
                {"label": " ➖ 검사할 폴더 삭제하기 (리스트에서 선택)", "key": "delete"},
                {"label": "  " + "─" * 48, "key": "sep"},
                {"label": " 🚀 [1형] 해시값 기반 검색 (완전 일치 / 고속)", "key": "search_0"},
                {"label": " 🚀 [2형] 크기 동일 시 음파 유사도 분석 (정밀)", "key": "search_1"},
                {"label": " 🚀 [3형] 파일명 유사도 기반 검색 (유사 단어)", "key": "search_2"},
                {"label": "  " + "─" * 48, "key": "sep2"},
                {"label": " 🔥 [전체] 1형+2형+3형 한 번에 검사 (통합 결과)", "key": "search_all"},  # [v18.5] AI냥 요청: 3가지 비교 한 번에! ✨
                {"label": " 🧹 나홀로 자막(SRT) 찾아 정리하기 (동영상 없는 자막)", "key": "cleanup_orphaned_subs"},
                {"label": " 🗑️ 휴지통 및 임시 찌꺼기 비우기 (영구 삭제)", "key": "empty_trash"},
                {"label": " ❌ 이전 메뉴로 돌아가기", "key": "back"}
            ]

            options = [item["label"] for item in options_map]
            choice, _, *_ = _interactive_menu("🚀 무엇을 할까?", options, timeout=0)

            if choice < 0: # [수정] ESC 키 입력 시 메인 메뉴로 복구 ✨
                break

            if choice >= len(options_map): continue
            choice_key = options_map[choice]["key"]

            if choice_key == "add": # 폴더 추가
                import tkinter as tk
                root = tk.Tk(); root.withdraw(); root.attributes('-topmost', True)
                new_f = remote_explorer(mode='dir', title="중복 파일 검사 폴더 선택")
                root.destroy()
                if new_f:
                    # [V] 리스트와 단일 문자열 모두 유연하게 처리
                    paths = new_f if isinstance(new_f, list) else [new_f]
                    added_count = 0
                    for p in paths:
                        if not p: continue
                        try:
                            norm_p = os.path.normpath(p)
                            if norm_p not in monitored:
                                monitored.append(norm_p)
                                added_count += 1
                        except Exception as e:
                            print(f"\r\n ⚠️ {C.YELLOW}유효하지 않은 경로 무시됨 ({p}): {e}{R}")

                    if added_count > 0:
                        settings.data["monitored_folders"] = monitored
                        settings.save()
                        print(f"\r\n ✅ {C.GREEN}{added_count}개의 폴더가 추가되었어!{R}")
                        time.sleep(1)
                continue

            elif choice_key == "delete": # 폴더 삭제
                if not monitored:
                    print(f"\r\n ⚠️ {C.RED}삭제할 폴더가 없어!{R}")
                    time.sleep(1); continue

                del_options_map = [{"label": f" 🗑️ {f}", "key": idx} for idx, f in enumerate(monitored)]
                del_options_map.append({"label": " ❌ 취소", "key": "cancel"})
                del_options = [item["label"] for item in del_options_map]

                del_idx, _, *_ = _interactive_menu("🗑️ 어떤 폴더를 삭제할까?", del_options, timeout=0)
                if del_idx < 0: break # [V77.5 Globalizer]
                if 0 <= del_idx < len(del_options_map):
                    del_key = del_options_map[del_idx]["key"]
                    if del_key != "cancel":
                        removed = monitored.pop(del_key)
                        settings.data["monitored_folders"] = monitored
                        settings.save()
                        print(f"\r\n ✅ {C.GREEN}'{removed}' 폴더를 검사 리스트에서 뺐어!{R}")
                        time.sleep(1)
                continue

            elif choice_key.startswith("search_"): # 검색 실행
                if not monitored:
                    print(f"\r\n ⚠️ {C.RED}폴더를 먼저 하나 이상 추가해줘!{R}")
                    time.sleep(2); continue

                # [v18.5] 전체 검사 or 단일 검사 분기
                if choice_key == "search_all":
                    _run_duplicate_search(monitored, -1, settings)  # -1 = 통합 전체 모드
                else:
                    search_mode = safe_int(choice_key.split("_")[1])
                    _run_duplicate_search(monitored, search_mode, settings)
                continue

            elif choice_key == "cleanup_orphaned_subs": # 나홀로 자막 정리
                _cleanup_orphaned_subtitles(settings)
                continue

            elif choice_key == "empty_trash": # [V195.0] 휴지통 및 임시 찌꺼기 비우기 🗑️🧹
                _empty_recycle_bin(verbose=True, async_mode=False)
                prompt_input(f"\r\n 🔘 {C.SKY}엔터를 누르면 메뉴로 돌아갑니다...{R}")
                continue

            elif choice_key == "back": # 뒤로 가기
                break
    except UserAbortException:
        # [V21.11] AI냥 요청: 중복 검사 중 취소 시 메인 메뉴로 안전하게 복구냥! 🛡️✨
        print(f"\r\n {C.YELLOW}⚠️ 작업을 중단하고 메인 메뉴로 돌아왔어냥!{C.RESET}")
        time.sleep(1.2)

# [TAG: #@_run_duplicate_search]
def _run_duplicate_search(folders: List[str], search_mode: int, settings):
    """실제 중복 검색 로직 실행"""
    video_extensions = ['.mp4', '.mkv', '.avi', '.mov', '.wmv', '.flv', '.webm', '.mpg', '.mpeg', '.m4v']
    R = C.RESET

    print(f"\r\n 🔍 {C.SKY}영상 파일 목록을 수집 중입니다...{R}")
    # [V36.1] 중복 폴더 및 파일 수집 최적화 🚀
    # 1. 대상 폴더 목록 정규화 및 상호 중복(부모-자식 관계) 제거
    abs_folders = sorted(list(set(os.path.normpath(os.path.abspath(f)) for f in folders if os.path.exists(f))))
    unique_scan_folders = []
    for i, f in enumerate(abs_folders):
        is_sub = False
        for j, other in enumerate(abs_folders):
            if i != j and (f == other or f.startswith(other + os.sep)):
                is_sub = True; break
        if not is_sub: unique_scan_folders.append(f)

    # 2. 파일 수집 (set을 사용하여 물리적으로 동일한 파일 중복 방지)
    all_files_set = set()
    for f in unique_scan_folders:
        for root, dirs, files in os.walk(f):
            for name in files:
                ext = os.path.splitext(name)[1].lower()
                if ext in video_extensions:
                    full_p = os.path.normpath(os.path.abspath(os.path.join(root, name)))
                    try:
                        if os.path.getsize(full_p) > 20 * 1024 * 1024:
                            all_files_set.add(full_p)
                    except:
                        pass

    all_files = list(all_files_set)

    if not all_files:
        print(f" ⚠️ {C.YELLOW}수집된 파일이 없어!{R}")
        time.sleep(2); return

    print(f" ✅ {C.GREEN}{len(all_files)}개의 파일을 찾았어. 분석을 시작할게!{R}")

    groups = []

    if search_mode == 0: # Hash
        size_map = defaultdict(list)
        for f in all_files:
            try: size_map[os.path.getsize(f)].append(f)
            except: continue

        for size, paths in size_map.items():
            if len(paths) < 2: continue
            h_map = defaultdict(list)
            for p in paths:
                h = _get_fast_hash(p)
                if h: h_map[h].append(p)
            for h_paths in h_map.values():
                if len(h_paths) > 1: groups.append(h_paths)

    elif search_mode == 1: # Size + Audio
        size_map = defaultdict(list)
        for f in all_files:
            try:
                size_map[os.path.getsize(f)].append(f)
            except: continue

        print(f" 🎙️ {C.BOLD}크기가 동일한 {sum(1 for v in size_map.values() if len(v) > 1)}개 그룹의 영상 시그니처를 분석합니다...{R}")
        for size, paths in size_map.items():
            if len(paths) < 2: continue
            sig_map = {} # path -> signature
            for p in paths:
                sig = _get_audio_signature(p)
                if sig: sig_map[p] = sig

            # 유사한 시그니처 묶기
            processed = set()
            for p1, s1 in sig_map.items():
                if p1 in processed: continue
                current_group = [p1]
                processed.add(p1)
                for p2, s2 in sig_map.items():
                    if p2 in processed: continue
                    # 평균과 분산이 매우 근접하면 동일 파일로 간주
                    if abs(s1[0] - s2[0]) < 1.0 and abs(s1[1] - s2[1]) / (s1[1] + 1e-6) < 0.01:
                        current_group.append(p2)
                        processed.add(p2)
                if len(current_group) > 1: groups.append(current_group)

    elif search_mode == 2: # Filename similarity
        # 간단한 이름 기반 (공백 제거, 소문자화 후 비교)
        name_map = defaultdict(list)
        for f in all_files:
            name = os.path.basename(f).lower().replace(" ", "")
            name_map[name].append(f)
        for n_paths in name_map.values():
            if len(n_paths) > 1: groups.append(n_paths)

    elif search_mode == -1:  # [v18.5] 통합 전체 모드: 1형+2형+3형 동시 실행 🔥
        print(f" {C.BOLD}{C.SKY}🔥 [전체 검사] 1형 해시 → 2형 음파 → 3형 파일명 순서로 검사할게냥!{R}")
        seen_frozensets = set()  # 중복 그룹 중복 방지용

        # [TAG: #@_dedup_add]

        def _dedup_add(g_list):
            """동일한 파일 집합 그룹이 이미 추가됐으면 스킵"""
            fs = frozenset(g_list)
            if fs not in seen_frozensets:
                seen_frozensets.add(fs)
                groups.append(g_list)

        # ── 1형: 해시 ──────────────────────────────────────────────────────
        print(f"  🔷 {C.SKY}[1형]{R} 해시값 기반 검색 중...")
        size_map_h = defaultdict(list)
        for f in all_files:
            try: size_map_h[os.path.getsize(f)].append(f)
            except: continue
        for size, paths in size_map_h.items():
            if len(paths) < 2: continue
            h_map = defaultdict(list)
            for p in paths:
                h = _get_fast_hash(p)
                if h: h_map[h].append(p)
            for h_paths in h_map.values():
                if len(h_paths) > 1: _dedup_add(h_paths)

        # ── 2형: 크기+음파 ─────────────────────────────────────────────────
        print(f"  🔶 {C.YELLOW}[2형]{R} 크기·음파 유사도 분석 중...")
        size_map_a = defaultdict(list)
        for f in all_files:
            try: size_map_a[os.path.getsize(f)].append(f)
            except: continue
        for size, paths in size_map_a.items():
            if len(paths) < 2: continue
            sig_map = {}
            for p in paths:
                sig = _get_audio_signature(p)
                if sig: sig_map[p] = sig
            processed = set()
            for p1, s1 in sig_map.items():
                if p1 in processed: continue
                cg = [p1]; processed.add(p1)
                for p2, s2 in sig_map.items():
                    if p2 in processed: continue
                    if abs(s1[0] - s2[0]) < 1.0 and abs(s1[1] - s2[1]) / (s1[1] + 1e-6) < 0.01:
                        cg.append(p2); processed.add(p2)
                if len(cg) > 1: _dedup_add(cg)

        # ── 3형: 파일명 ────────────────────────────────────────────────────
        print(f"  🟣 {C.PURPLE}[3형]{R} 파일명 유사도 검색 중...")
        name_map_a = defaultdict(list)
        for f in all_files:
            name = os.path.basename(f).lower().replace(" ", "")
            name_map_a[name].append(f)
        for n_paths in name_map_a.values():
            if len(n_paths) > 1: _dedup_add(n_paths)

        print(f"  ✅ {C.GREEN}통합 검색 완료! 총 {len(groups)}개 중복 그룹 발견{R}")
        time.sleep(0.8)

    if not groups:
        print(f"\r\n ✨ {C.BOLD}{C.GREEN}중복된 파일이 보이지 않아! 깨끗해!{R}")
        time.sleep(2); return

    _manage_duplicate_groups(groups)

# [TAG: #@_manage_duplicate_groups]
def _manage_duplicate_groups(groups: List[List[str]]):
    """찾은 중복 그룹들을 페이지 단위로 예쁘게 리스트화해서 노출"""
    R, P, G, S, _Y = C.RESET, C.PURPLE, C.GREEN, C.SKY, C.YELLOW

    # 1. 리스트 평탄화 (그룹 구분 정보 유지)
    flattened_list = []
    for g_idx, group in enumerate(groups, 1):
        for p in group:
            if os.path.exists(p):
                try:
                    mtime = os.path.getmtime(p)
                except:
                    mtime = 0.0
                flattened_list.append({
                    "path": p,
                    "group_id": g_idx,
                    "size": os.path.getsize(p) / (1024*1024),
                    "mtime": mtime
                })

    if not flattened_list:
        print(f"\r\n ✨ {G}모든 중복 파일이 정리되었어!{R}")
        time.sleep(2); return

    # 2. 그룹별로 자동 하이라이트(삭제 대상) 미리 계산냥!
    # 각 그룹에서 용량이 가장 크고(1순위), 수정시간이 가장 오래된(2순위) 파일 1개를 보존(마스터)로 지정하고
    # 나머지를 자동 삭제 대상(auto_delete_paths)에 수집냥!
    auto_delete_paths = set()
    from collections import defaultdict
    group_items = defaultdict(list)
    for item in flattened_list:
        group_items[item["group_id"]].append(item)

    for g_id, items in group_items.items():
        if len(items) < 2:
            continue
        # 정렬: 삭제 우선순위가 높은 순 (크기가 작을수록 1순위, 동일 크기면 최근 날짜가 2순위냥!)
        sorted_items = sorted(items, key=lambda x: (x["size"], -x["mtime"]))
        # 마지막 1개(가장 크고 오래된 보존 대상)를 제외한 나머지를 삭제 대상으로 등록
        for item in sorted_items[:-1]:
            auto_delete_paths.add(item["path"])

    # [추가] 메뉴를 통해 언제든 복원할 수 있게 기본 자동 선택 대상 사본을 저장냥!
    default_auto_delete_paths = set(auto_delete_paths)

    # [V205.1] 동일 중복 그룹 내 살아남는 보존 파일 경로 탐색 헬퍼 🛡️✨ (경로 정규화 보강)
    def _find_survivor(target_item, exclude_paths=None):
        if not target_item:
            return None
        norm_excludes = {os.path.normcase(os.path.abspath(p)) for p in (exclude_paths or set()) if p}
        target_path = target_item.get("path", "")
        if not target_path:
            return None
        target_norm = os.path.normcase(os.path.abspath(target_path))
        gid = target_item.get("group_id")

        candidates = []
        for it in flattened_list:
            if it.get("group_id") != gid:
                continue
            it_p = it.get("path", "")
            if not it_p or not os.path.exists(it_p):
                continue
            it_norm = os.path.normcase(os.path.abspath(it_p))
            if it_norm == target_norm or it_norm in norm_excludes:
                continue
            candidates.append(it)

        if not candidates:
            return None
        # 보존 우선순위: 크기가 가장 크고(1순위), 수정시간이 오래된(2순위) 순서
        candidates.sort(key=lambda x: (-x.get("size", 0), x.get("mtime", 0)))
        return candidates[0]["path"]

    # [V205.1] 중복 파일 1개 안전 삭제 통합 헬퍼 (자막 이전 + 고아 자막 및 작업 잔해 정리) 🛡️🧹
    def _delete_single_duplicate(item_dict, survivor_path=None):
        if not item_dict or "path" not in item_dict:
            return False
        full_target = os.path.abspath(item_dict["path"])
        if not os.path.exists(full_target):
            return False

        # 1. 생존 파일이 지정되어 있으면 자막을 먼저 안전 이전!
        migrated_subs = set()
        survivor_subs = set()
        if survivor_path and os.path.exists(survivor_path):
            surv_abs = os.path.abspath(survivor_path)
            try:
                migrated = _safely_migrate_subtitles(full_target, surv_abs, is_move=True)
                migrated_subs = {os.path.normcase(os.path.abspath(m)) for m in migrated}
            except Exception:
                pass
            try:
                survivor_subs = {os.path.normcase(os.path.abspath(s)) for s in _find_associated_subtitles(surv_abs)}
                survivor_subs.add(os.path.normcase(surv_abs))
            except Exception:
                pass

        # 2. 영상 본체 삭제 (휴지통)
        safe_remove_file(full_target)

        # 3. 고아 자막 정리: 이전되지 않고 남아있는 삭제 대상의 연관 자막 휴지통 이동 🧼
        try:
            rem_subs = _find_associated_subtitles(full_target)
            for sub in rem_subs:
                sub_abs = os.path.abspath(sub)
                sub_norm = os.path.normcase(sub_abs)
                # 생존자 자막이나 생존 영상 본체는 절대 삭제 금지!
                if sub_norm in survivor_subs or sub_norm in migrated_subs:
                    continue
                safe_remove_file(sub_abs, use_trash=True)
        except Exception:
            pass

        # 4. 작업 파편 및 잔해물 정리
        try:
            stem_path = os.path.splitext(full_target)[0]
            _cleanup_video_work_remnants(stem_path, cleanup_mode=0)
        except Exception:
            pass

        return True

    while True:
        # [V22.4] AI냥 요청: 페이지를 나누지 않고 전체 목록을 한 번에 보여주기 위해 page_size 제한 제거 🚀✨
        total_files = len(flattened_list)
        if total_files == 0:
            print(f"\r\n ✨ {G}모든 중복 파일이 정리되었어!{R}")
            time.sleep(2)
            return

        page_size = total_files
        total_pages = 1
        current_page = 0
        page_items = flattened_list

        clear_console()
        print(f" {P}╔{'═' * 70}╗{R}")
        print(f" {P}║{R}  🔍 {C.BOLD}중복 검색 결과 (총 {len(groups)}개 그룹 / {total_files}개 파일){R} {' ' * (22 if len(groups) < 10 else 21)} {P}║{R}")
        print(f" {P}╠{'═' * 70}╣{R}")
        print(f" {P}║{R}  📄 전체 중복 파일 목록 {' ' * 46}{P}║{R}")
        print(f" {P}╚{'═' * 70}╝{R}\r\n")

        display_options = []
        option_to_file = {}
        nav_indices = {}
        last_group_id = -1
        initial_select_indices = set()  # 초기 하이라이트 선택 인덱스 수집용

        for item in page_items:
            # 그룹이 바뀌면 한 줄 띄우기 (시각적 구분)
            if last_group_id != -1 and item["group_id"] != last_group_id:
                display_options.append(f"{P}--- 그룹 {item['group_id']} ------------------------------------------{R}")

            full_p = os.path.abspath(item["path"])
            # [V22.99] 스페이스 멀티 선택이 가능하도록 🎬(영화 아이콘) 프리픽스 탑재냥! 🎬✨
            prefix = f"🎬 {P}[G{item['group_id']}]{R} "
            option_text = f"{prefix}{full_p} ({item['size']:.1f}MB)"
            
            curr_idx = len(display_options)
            display_options.append(option_text)
            option_to_file[curr_idx] = item

            # 자동 삭제 대상 경로이면 초기 체크 활성화
            if item["path"] in auto_delete_paths:
                initial_select_indices.add(curr_idx)
            
            last_group_id = item["group_id"]

        # 네비게이션 옵션 추가
        if total_pages > 1:
            if current_page < total_pages - 1:
                curr_idx = len(display_options)
                display_options.append(f" ⏭️  다음 페이지 ({current_page+2}/{total_pages})")
                nav_indices[curr_idx] = "next"
            if current_page > 0:
                curr_idx = len(display_options)
                display_options.append(f" ⏮️  이전 페이지 ({current_page}/{total_pages})")
                nav_indices[curr_idx] = "prev"

        deselect_all_idx = len(display_options)
        display_options.append(" 🔓 전체 선택 해제 (ESC)")

        auto_select_idx = len(display_options)
        display_options.append(" 🎯 중복 자동 선택 (최근/작은 파일)")

        exit_idx = len(display_options)
        display_options.append(" ❌ 검색 중단 (메뉴로)")

        prompt = "💡 Space: 선택 | ESC: 전체선택해제 | Enter/D: 일괄삭제 (Y/n) ✨"
        choice, action, selected_indices, *_ = _interactive_menu(
            prompt, display_options, timeout=0, truncate=False, allow_multi=True,
            initial_indices=initial_select_indices
        )
        if (isinstance(choice, int) and choice < 0) or action == "CANCEL": break

        # 사용자가 수동으로 체크 변경한 내용을 auto_delete_paths에 실시간 동기화 (페이지 이동 대비)
        for idx, item in option_to_file.items():
            if idx in selected_indices:
                auto_delete_paths.add(item["path"])
            else:
                auto_delete_paths.discard(item["path"])

        # 1. 다중 선택 처리 (Space 선택이 있는 경우)
        if isinstance(choice, list):
            # 전체 flattened_list 중에서 auto_delete_paths에 포함되어 있고 실제 존재하는 모든 파일을 삭제 대상으로 지정
            target_files = [item for item in flattened_list if item["path"] in auto_delete_paths and os.path.exists(item["path"])]
            if not target_files:
                continue
            
            # 사용자 요청: Y/n 기본값 변경 (대문자 Y, 소문자 n)
            print(f"\r\n 🗑️  선택한 {len(target_files)}개 파일을 모두 삭제할까냥? (Y/n): ", end="", flush=True)
            ans = get_single_key_physical()
            print(ans)  # 입력받은 키 화면에 에코 출력
            
            # 사용자 요청: 엔터(\r, \r\n) 혹은 y를 누르면 삭제 진행
            if ans in ('y', '\r', '\r\n'):
                success_count = 0
                all_target_paths = {item["path"] for item in target_files}
                for f_item in target_files:
                    full_target = os.path.abspath(f_item['path'])
                    # [V205.1] 동일 중복 그룹 내 살아남는 보존 파일로 딸린 자막 자동 안착 + 고아 자막/잔해 정리! 🛡️🎬
                    survivor_p = _find_survivor(f_item, exclude_paths=all_target_paths)
                    try:
                        if _delete_single_duplicate(f_item, survivor_p):
                            success_count += 1
                            flattened_list = [it for it in flattened_list if it["path"] != f_item["path"]]
                            auto_delete_paths.discard(f_item["path"])
                    except Exception as e:
                        print(f" ❌ {os.path.basename(full_target)} 삭제 실패: {e}")
                print(f"\r\n ✅ {C.GREEN}성공적으로 {success_count}개 중복 파일을 삭제 완료했다냥!{R}")
                
                time.sleep(1.5)
            continue

        # 2. 네비게이션 또는 검색 중단 단일 액션 처리
        if choice in nav_indices:
            direction = nav_indices[choice]
            if direction == "next":
                current_page += 1
            elif direction == "prev":
                current_page -= 1
            continue
        elif choice == deselect_all_idx:
            auto_delete_paths.clear()
            continue
        elif choice == auto_select_idx:
            auto_delete_paths = set(default_auto_delete_paths)
            continue
        elif choice == exit_idx:
            return
        elif choice not in option_to_file:
            continue # 구분선 클릭 등

        # 3. 단일 파일 선택 처리 (일반 엔터)
        selected_file_item = option_to_file[choice]
        
        # 단일 파일 삭제 단축키(D/Delete)를 직접 누른 경우
        if action == "DELETE":
            full_target = os.path.abspath(selected_file_item['path'])
            print(f"\r\n 🗑️  '{os.path.basename(full_target)}' 파일을 삭제할까냥? (Y/n): ", end="", flush=True)
            ans = get_single_key_physical()
            print(ans)  # 입력받은 키 화면에 에코 출력
            if ans in ('y', '\r', '\r\n'):
                # [V205.1] 동일 중복 그룹 내 살아남는 보존 파일로 딸린 자막 자동 안착 + 고아 자막/잔해 정리! 🛡️🎬
                survivor_p = _find_survivor(selected_file_item, exclude_paths={selected_file_item['path']})
                try:
                    if _delete_single_duplicate(selected_file_item, survivor_p):
                        print(f" ✅ {G}삭제 완료!{R}")
                        flattened_list = [it for it in flattened_list if it["path"] != selected_file_item["path"]]
                        auto_delete_paths.discard(selected_file_item["path"])
                        time.sleep(1)
                    else:
                        print(f" ❌ {C.RED}삭제 실패: 파일이 존재하지 않거나 처리할 수 없어!{R}")
                        time.sleep(2)
                except Exception as e:
                    print(f" ❌ {C.RED}삭제 실패: {e}{R}")
                    time.sleep(2)
            continue

        # 일반 엔터 입력 시 액션 서브메뉴 띄우기
        action_options = [
            " ▶️  파일 재생하기",
            " 🗑️  파일 삭제하기 (휴지통)",
            " 🔙  취소 (리스트로 돌아가기)"
        ]

        act_choice, _, *_ = _interactive_menu(f"🎬 선택된 파일: {os.path.abspath(selected_file_item['path'])}", action_options, timeout=0)
        if act_choice < 0: break

        if act_choice == 0: # 재생
            print(f" 🎬 {S}파일을 재생합니다...{R}")
            try: open_path_resilient(os.path.abspath(selected_file_item['path']))
            except:
                print(f" ❌ {C.RED}플레이어를 열 수 없어!{R}")
                time.sleep(1)
        elif act_choice == 1: # 삭제
            full_target = os.path.abspath(selected_file_item['path'])
            # [V205.1] 동일 중복 그룹 내 살아남는 보존 파일로 딸린 자막 자동 안착 + 고아 자막/잔해 정리! 🛡️🎬
            survivor_p = _find_survivor(selected_file_item, exclude_paths={selected_file_item['path']})
            try:
                if _delete_single_duplicate(selected_file_item, survivor_p):
                    print(f" ✅ {G}삭제 완료!{R}")
                    flattened_list = [it for it in flattened_list if it["path"] != selected_file_item["path"]]
                    auto_delete_paths.discard(selected_file_item["path"])
                    time.sleep(1)
                else:
                    print(f" ❌ {C.RED}삭제 실패: 파일이 존재하지 않거나 처리할 수 없어!{R}")
                    time.sleep(2)
            except Exception as e:
                print(f" ❌ {C.RED}삭제 실패: {e}{R}")
                time.sleep(2)

# [TAG: #@_safe_rename]
def _safe_rename(old_path, new_path):
    """
    파일 이름 변환을 시도하고, PermissionError 발생 시 안전하게 스킵합니다.
    (이전 버전의 강제 프로세스 종료 로직은 문제가 있어 제거됨)
    """
    try:
        os.rename(old_path, new_path)
        _update_shopping_cart_path(old_path, new_path)
        _update_hits_path(old_path, new_path)
        return True
    except PermissionError:
        print(f"   ⚠️ 파일이 사용 중이라 건너뜁니다: {os.path.basename(old_path)}")
        return False
    except Exception as e:
        print(f"   ❌ 이름 변경 실패 ({os.path.basename(old_path)}): {e}")
        return False

# [TAG: #@_probe_file_lock]
def _probe_file_lock(path):
    """[V22.43] 다른 프로세스(토렌트 시드/플레이어)가 파일을 잠갔는지 **파일을 건드리지 않고** 판별한다. 🔍🛡️

    왜 새로 만드나:
        기존 `is_file_locked()` 는 `os.rename(path, path+'.lock_test_check')` 로 **실제 이름을 바꿨다가**
        되돌리는 방식이다. 두 번째 rename 이 실패하면 파일명이 '__xxx.lock_test_check' 로 영구 남는다. ☠️
        (실측 위험: 파일이 잠겨 있으면 1차 rename 자체가 실패해 论리 외의 부산물 가능)

    여기서는 `CreateFileW(DELETE 권한 + 공유허용)` 핸들만 '열어봤다가 즉시 닫는다':
        - 열림 성공 → 남이 붙들고 있지 않음 (잠금 없음)
        - ERROR_SHARING_VIOLATION(32) / ERROR_ACCESS_DENIED(5) → 잠김
    파일 내용도 이름도 전혀 변경하지 않으므로 판별 실패해도 원본이 100% 안전하다. 🛡️
    """
    if not path or not os.path.exists(path) or os.path.isdir(path):
        return False
    if os.name != 'nt':
        return False   # 다른 OS 는 rename 실패가 예외로 그대로 올라오므로 여기선 판별 불필요

    # 읽기전용(FILE_ATTRIBUTE_READONLY)은 delete 만 막고 rename 은 통하므로 '잠금'으로 오판하지 않는다
    try:
        if getattr(os.stat(path), 'st_file_attributes', 0) & 0x1:
            return False
    except Exception:
        pass

    try:
        import ctypes
        k32 = ctypes.WinDLL("kernel32", use_last_error=True)
        DELETE = 0x00010000
        SHARE_ALL = 0x1 | 0x2 | 0x4      # 읽기/쓰기/삭제 전부 공유 요청
        OPEN_EXISTING = 3
        FILE_ATTRIBUTE_NORMAL = 0x80
        INVALID_HANDLE_VALUE = ctypes.c_void_p(-1).value
        # [V22.43] ⚠️ argtypes/restype 미지정 시 HANDLE 이 32비트 로 잘려
        #    잠긴 파일을 '안 잠김'으로 오판하고 조용히 통과시킨다(실측 T8 실패 사례).
        #    반드시 시그니처를 선언한다. 🛡️
        k32.CreateFileW.argtypes = [ctypes.c_wchar_p, ctypes.c_uint32, ctypes.c_uint32,
                                    ctypes.c_void_p, ctypes.c_uint32, ctypes.c_uint32,
                                    ctypes.c_void_p]
        k32.CreateFileW.restype = ctypes.c_void_p
        k32.CloseHandle.argtypes = [ctypes.c_void_p]
        k32.CloseHandle.restype = ctypes.c_int
        h = k32.CreateFileW(path, DELETE, SHARE_ALL, None, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, None)
        if h and h != INVALID_HANDLE_VALUE and h != 0:
            k32.CloseHandle(h)
            return False
        return ctypes.get_last_error() in (5, 32)   # ACCESS_DENIED / SHARING_VIOLATION
    except Exception:
        return False   # 판별 불가 → '안 잠김'으로 두고, 실제 rename 이 최종裁决한다


# [TAG: #@_move_no_copy]
def _move_no_copy(src, dst):
    """[V22.43] **복사 폴백 없는** 순수 이동만 시도한다. rename 실패하면 곧바로 예외. 🚚🛡️

    ⚠️ [핵심 버그FIX] `shutil.move()` 는 내부적으로
            try: os.rename(src, dst)
            except OSError:  shutil.copy2(src, dst); os.unlink(src)     ← 이 폴백이 사고의 원인
        토렌트가 잠깐 시드 중이라 rename 이 막히면 → 7GB 영상이 통째로 복사되고
        → 원본은 잠금 때문에 unlink 실패 → **원본+사본 2벌로 하드를 2배로 먹는다.**
        (실측: G:\\atmp\\DLDSS-537.mp4 와 G:\\atmp\\DLDSS-537__5d458614.mp4 가 크기·mtime까지 동일)

    규칙: os.rename 만 시도한다. 실패하면 예외를 올려 호출부가 '보류' 처리하게 만든다. 🚫
    """
    if os.name == 'nt':
        s_drv = os.path.splitdrive(os.path.abspath(src))[0].upper()
        d_drv = os.path.splitdrive(os.path.abspath(dst))[0].upper()
        if s_drv and d_drv and s_drv != d_drv:
            raise OSError(18, f"EXDEV: 다른 드라이브 ({s_drv} -> {d_drv}) — 복사 금지 정책으로 보류")
    os.rename(src, dst)
    return True


# [TAG: #@_sweep_orphan_tmp_files]
def _sweep_orphan_tmp_files(folder_path, video_extensions, sub_extensions):
    """[V22.43] 예전 shutil.move '카피 폴백' 이 남긴 '__<uuid8>' 고아 임시파일을 청소한다. 🧹🛡️

    판정 (전부 만족할 때만 휴지통 이동):
        1) 이름이 '{원본명}__{8자리hex}{확장자}' 패턴
        2) 확장자가 영상/자막 확장자
        3) 루트에 **원래 이름** 파일이 이미 존재하고 크기가 동일  → 확실한 중복 사본
        4) 지금 잠겨 있지 않음 (시드 중이면 건드리지 않는다)
    하나라도 안 맞으면 **절대 지우지 않고 보고만** 한다 (오판 방어). ☠️
    """
    import send2trash
    removed = 0
    R = C.RESET
    try:
        items = os.listdir(folder_path)
    except Exception:
        return 0

    for item in items:
        m = re.match(r'^(?P<base>.+)__(?P<uid>[0-9a-f]{8})(?P<ext>\.[A-Za-z0-9]{1,6})$', item)
        if not m:
            continue
        base, ext = m.group('base'), m.group('ext').lower()
        if ext not in video_extensions and ext not in sub_extensions:
            continue

        orphan_p = os.path.join(folder_path, item)
        origin_p = os.path.join(folder_path, f"{base}{ext}")
        if not os.path.isfile(origin_p):
            continue                       # 원본이 없으면 '유일한 사본'일 수 있다 → 손대지 않음
        try:
            if os.path.getsize(orphan_p) != os.path.getsize(origin_p):
                continue
        except Exception:
            continue
        if _probe_file_lock(orphan_p):
            print(f"   ⏸️ {C.YELLOW}[보류] 고아 임시파일 사용 중(시드 중이라 대기):{R} {item}")
            continue

        try:
            send2trash.send2trash(os.path.abspath(orphan_p))
            if os.path.exists(orphan_p):
                # send2trash 가 조용히 실패한 경우 (점유 중 OLE 0x80270027 등) → 삭제된 것으로 세지 않는다
                print(f"   ⏸️ {C.YELLOW}[보류] 고아 임시파일 정리 보류 (점유 중으로 판단):{R} {item}")
                continue
            removed += 1
            print(f"   🧹 {C.YELLOW}중복 고아 임시파일 휴지통:{R} {item} → 원본 '{base}{ext}' 이미 존재")
        except Exception as e:
            print(f"   ⚠️ 고아 임시파일 정리 실패 ({item}): {e}")
    return removed

# [TAG: #@_build_tmp_extract_name]
def _build_tmp_extract_name(orig_fname, ext, batch_uuid, max_base=100):
    """
    [V22.41] 임시 추출 파일명 생성기 🏷️🛡️ (이름 유실 원천 차단)

    왜 이 함수가 있냐:
        예전에는 f"_tmp_extract_{uuid4().hex[:8]}{ext}" 로 **원본명을 버렸다.**
        그 결과 Step C(최종 리네임)가 중간에 실패하면(잠금/중단/예외)
        정체를 알 수 없는 고아 파일이 이름도 모르게 영구 잔존했다.
        → UUID만으로는 정체 복구가 불가능해서, 지금 구조로는 파일 손상 관점에서 가장 위험했다.

    규칙:
        1. 형식 = "{원본 base}__{배치 UUID}{확장자}"
           → 원본명이 이름에 남으므로, Step C 실패 시에도 **그 자체로 정체 복구 가능**
           → UUID가 붙으므로, 모든 토렌트가 같은 파일명("18+무료동영상(996gg.cc)-...")
             을 쓰더라도 충돌하지 않는다 (기존 uuid-only 와 동일한 유일성 보장)
        2. 배치 UUID는 **하위폴더당 1개만** 발급한다.
           → 같은 배치의 .mp4 와 .srt 가 동일 UUID를 공유 = 중단돼도 이름만으로 페어링 가능
        3. MAX_PATH(260) 보호: 원본 base 는 max_base 자로 절삭한다.
           (실측: G:\\atmp 최장 파일명 59자, 여유 252자 → 여유 있으나 이중화 대비)
        4. Windows 정규화/예약 문자(\\/*:?\"<>| , 제어문자) 제거.
           후행 공백·점은 Windows가 강제로 제거해버리므로 미리 잘라낸다.
    """
    base = os.path.splitext(os.path.basename(orig_fname))[0]
    base = re.sub(r'[\\/:*?"<>|\x00-\x1f]', '_', base)
    base = base.rstrip(' .')  # 후행 공백/점은 Windows가 탈락시켜 복원 불가가 된다
    if len(base) > max_base:
        base = base[:max_base].rstrip(' .')
    if not base:
        base = "unknown"
    return f"{base}__{batch_uuid}{ext}"

# [TAG: #@_cleanup_folder_logic]
def _cleanup_folder_logic(folder_path):
    """
    [V22.40] 스마트 토렌트 폴더 정리 로직 🧹✨:
    1. 1단계 하위 폴더에서 영상 파일 및 자막 파일 추출
    2. 폴더명-파일명 충돌 방지: 임시 파일 이동 -> 원본 폴더 휴지통 이동 -> 최종 스마트 이름 안착
    3. 남은 찌꺼기 파일(nfo, jpg, url, 빈 폴더 등) 휴지통 이동
    """
    import send2trash
    import uuid
    import shutil
    R, G, _Y, _S = C.RESET, C.GREEN, C.YELLOW, C.SKY

    if not os.path.exists(folder_path):
        print(f" ⚠️ {C.RED}폴더가 존재하지 않아:{R} {folder_path}")
        return

    print(f"\r\n 🧹 {C.CYAN}'{os.path.basename(folder_path)}' 폴더 정리를 시작할게! (1단계 하위폴더 대상){R}")

    video_extensions = ('.mp4', '.mkv', '.avi', '.mov', '.wmv', '.flv', '.webm', '.ts', '.m2ts', '.m4v')
    sub_extensions = ('.srt', '.vtt', '.ass')
    temp_extensions = ('.part', '.ytdl', '.aria2', '.part-Frag', '.temp.mp4')
    temp_ext_lower = tuple(t.lower() for t in temp_extensions)

    def _is_active_temp(file_name, file_full_path):
        fn_lower = file_name.lower()
        if fn_lower.endswith(temp_ext_lower) or '.processing.' in fn_lower or fn_lower.endswith('.lock'):
            return True
        if fn_lower.endswith('.!qb'):
            try:
                if os.path.getsize(file_full_path) > 100 * 1024 * 1024:
                    return True
            except: pass
        return False

    moved_count = 0
    removed_count = 0

    # [V22.43] 🧹 먼저 과거 'shutil.move 카피 폴백' 이 남긴 고아 '__<uuid>' 중복본을 청소한다.
    # (원본 이름의 파일이 이미 있고 크기가 같을 때만 → 확실한 사본이라 판단)
    try:
        removed_count += _sweep_orphan_tmp_files(folder_path, video_extensions, sub_extensions)
    except Exception as e:
        _log_to_file(f"⚠️ [SweepOrphanTmp] {e}")

    # 1. 1단계 하위 폴더들 검사 및 추출
    try:
        sub_items = [d for d in os.listdir(folder_path) if os.path.isdir(os.path.join(folder_path, d))]
    except Exception as e:
        print(f" ❌ {C.RED}폴더 목록을 읽을 수 없어:{R} {e}")
        return

    for folder_nm in sub_items:
        if folder_nm.startswith("_work_"): continue
        sub_path = os.path.join(folder_path, folder_nm)

        # 미완료/다운로드 중인 임시 파일 확인
        try:
            items_in_sub = os.listdir(sub_path)
        except Exception:
            continue

        has_incomplete = False
        for root_s, _, files_s in os.walk(sub_path):
            if any(_is_active_temp(f, os.path.join(root_s, f)) for f in files_s):
                has_incomplete = True
                break
        if has_incomplete:
            continue

        # 하위 폴더 내의 영상 및 자막 파일 수집
        targets = []
        for root_s, _, files_s in os.walk(sub_path):
            for f in files_s:
                if f.startswith("_work_"): continue
                f_full = os.path.join(root_s, f)
                f_lower = f.lower()
                
                is_vid = f_lower.endswith(video_extensions)
                is_sub = f_lower.endswith(sub_extensions)
                
                if is_vid:
                    try:
                        sz_mb = os.path.getsize(f_full) / (1024 * 1024)
                    except:
                        sz_mb = 0
                    if sz_mb >= 50 or len(files_s) <= 5:
                        targets.append((f_full, f, True, sz_mb))
                elif is_sub:
                    targets.append((f_full, f, False, 0))

        if not targets:
            continue

        # [V22.43] 🛡️ 시드 중 잠금 사전 감지 → '보류' 처리 (강제 이동/복사 금지)
        # shutil.move 는 rename 실패 시 자동으로 copy2 폴백해서 원본+사본 2벌(디스크 2배)이 된다.
        # 따라서 잠겨 있는 파일이 하나라도 있으면 이 하위 폴더 전체를 이번 회차 '보류'한다.
        locked_files = [t[0] for t in targets if _probe_file_lock(t[0])]
        if locked_files:
            print(f"   ⏸️ {C.YELLOW}[보류] '{folder_nm}' — 파일 {len(locked_files)}개가 사용 중(시드/재생)이라 이번엔 건너뜁니다:{R}")
            for lf in locked_files[:3]:
                print(f"        🔒 {os.path.basename(lf)}")
            if len(locked_files) > 3:
                print(f"        … 외 {len(locked_files)-3}개")
            print(f"      {C.SKY}💡 시드가 끝난 뒤 다시 정리하면 정상 처리됩니다.{R}")
            continue

        # 충돌 방지 3단계 이동:
        # Step A: 임시 안전 파일명으로 루트(folder_path)로 이동
        # [규칙] 임시 이름 = "{원본명}__{배치UUID}{확장자}"
        #   - 원본명이 이름에 남는다 → Step C 실패해도 이름 자체로 정체 복구 가능 (이름 유실 원천 차단)
        #   - 배치UUID는 "하위폴더당 1개" 발급 → 같은 배치의 영상/자막이 같은 UUID = 자동 페어링
        #   - UUID가 붙으므로 원본명이 같아도(전 토렌트가 동일 파일명) 충돌 없음
        batch_uuid = uuid.uuid4().hex[:8]  # [규칙] 파일마다가 아니라 '하위폴더당' 1개만 발급!
        temp_moved_list = [] # (temp_path, orig_filename, is_video, size_mb)
        for f_full, orig_fname, is_vid, sz_mb in targets:
            ext = os.path.splitext(orig_fname)[1].lower()
            temp_name = _build_tmp_extract_name(orig_fname, ext, batch_uuid)
            temp_dest = os.path.join(folder_path, temp_name)
            try:
                # [V22.43] 🚫 shutil.move 금지 — os.rename 만 (복사 폴백 차단 → 디스크 2배 방지)
                _move_no_copy(f_full, temp_dest)
                temp_moved_list.append((temp_dest, orig_fname, is_vid, sz_mb))
            except Exception as e:
                print(f"   ⚠️ {C.YELLOW}임시 이동 실패 ({orig_fname}):{R} {e}")

        if not temp_moved_list:
            continue

        # [V22.43] 🛡️ 전부 이동 못 했으면 이 하위 폴더는 '보류' (부분 이동 상태로 원본 폴더를 버리지 않는다)
        if len(temp_moved_list) != len(targets):
            print(f"   ⏸️ {C.YELLOW}[보류] '{folder_nm}' — 일부 파일 이동 실패로 이번 정리를 보류합니다 (원본 폴더 그대로){R}")
            for tp, ofn, _, _ in temp_moved_list:
                try:
                    _move_no_copy(tp, os.path.join(sub_path, ofn))
                except Exception:
                    pass
            continue

        # Step B: 원본 하위 폴더를 휴지통으로 이동 (폴더명 충돌 제거!)
        try:
            send2trash.send2trash(os.path.abspath(sub_path))
            removed_count += 1
        except Exception as e:
            try: shutil.rmtree(sub_path, ignore_errors=True)
            except: pass

        # Step C: 스마트 이름 계산 및 최종 리네임
        video_temps = [t for t in temp_moved_list if t[2]]
        sub_temps = [t for t in temp_moved_list if not t[2]]

        smart_base_from_folder = _smart_clean_filename(folder_nm, is_folder=True)

        for temp_path, orig_fname, is_vid, sz_mb in video_temps:
            f_smart = _smart_clean_filename(orig_fname, is_folder=False)
            f_smart_base = os.path.splitext(f_smart)[0]
            
            v_ext = os.path.splitext(orig_fname)[1].lower()
            if len(f_smart_base) <= 3 or f_smart_base.lower() in ('video', 'movie', 'sample', 'preview', 'main', 'final'):
                final_name = f"{smart_base_from_folder}{v_ext}"
            else:
                final_name = f_smart

            final_dest = os.path.join(folder_path, final_name)
            if os.path.exists(final_dest):
                base_fn, ext_fn = os.path.splitext(final_name)
                c = 1
                while os.path.exists(final_dest):
                    final_dest = os.path.join(folder_path, f"{base_fn}_{c}{ext_fn}")
                    c += 1
                final_name = os.path.basename(final_dest)

            try:
                os.rename(temp_path, final_dest)
                print(f"   🚚 {G}추출+스마트정돈 완료:{R} {final_name} ({sz_mb:.1f}MB)")
                moved_count += 1
            except Exception as e:
                print(f"   ❌ {C.RED}최종 리네임 실패 ({final_name}):{R} {e}")
                # [규칙] 임시 파일명에 원본명이 남아 있으므로, 정체가 불명인 파일이 절대 생기지 않는다.
                print(f"      🛡️ {C.SKY}원본명 보존됨 — 이 파일만 직접 이름변경하면 됩니다:{R} {os.path.basename(temp_path)}")

        # 자막 파일 최종 리네임
        for temp_path, orig_fname, is_vid, _ in sub_temps:
            s_ext = os.path.splitext(orig_fname)[1].lower()
            if len(video_temps) == 1:
                v_smart_name = _smart_clean_filename(video_temps[0][1], is_folder=False)
                v_base = os.path.splitext(v_smart_name)[0]
                if len(v_base) <= 3 or v_base.lower() in ('video', 'movie', 'sample', 'preview', 'main', 'final'):
                    v_base = smart_base_from_folder
                final_s_name = f"{v_base}{s_ext}"
            else:
                final_s_name = _smart_clean_filename(orig_fname, is_folder=False)

            final_s_dest = os.path.join(folder_path, final_s_name)
            if os.path.exists(final_s_dest):
                base_fn, ext_fn = os.path.splitext(final_s_name)
                c = 1
                while os.path.exists(final_s_dest):
                    final_s_dest = os.path.join(folder_path, f"{base_fn}_{c}{ext_fn}")
                    c += 1
                final_s_name = os.path.basename(final_s_dest)

            try:
                os.rename(temp_path, final_s_dest)
                print(f"   📝 {G}자막 추출+동기화 완료:{R} {final_s_name}")
                moved_count += 1
            except Exception as e:
                print(f"   ❌ {C.RED}자막 리네임 실패 ({final_s_name}):{R} {e}")
                print(f"      🛡️ {C.SKY}원본명 보존됨 — 이 파일만 직접 이름변경하면 됩니다:{R} {os.path.basename(temp_path)}")

    # 2-A. 루트에 있는 20MB 이하 광고성 소형 동영상 휴지통 처리 🗑️📢
    # (예: "18+游戏大全-七龍珠H版.mp4", 토렌트 광고 영상 등)
    AD_VIDEO_MAX_MB = 20
    for item in list(os.listdir(folder_path)):
        if item.startswith("_work_"): continue
        item_path = os.path.join(folder_path, item)
        if not os.path.isfile(item_path): continue
        ext = os.path.splitext(item)[1].lower()
        if ext not in video_extensions: continue
        try:
            sz_mb = os.path.getsize(item_path) / (1024 * 1024)
        except:
            continue
        if sz_mb < AD_VIDEO_MAX_MB:
            try:
                send2trash.send2trash(os.path.abspath(item_path))
                removed_count += 1
                print(f"   🗑️ {C.YELLOW}광고 동영상 삭제:{R} {item} ({sz_mb:.1f}MB)")
            except Exception as e:
                print(f"   ⚠️ 광고 동영상 삭제 실패 ({item}): {e}")

    # 2-B. 루트(folder_path)에 남아있는 불필요 찌꺼기 파일 정리 (.nfo, .url, .torrent 등)
    garbage_exts = ('.nfo', '.url', '.torrent', '.website', '.lnk')
    for item in os.listdir(folder_path):
        if item.startswith("_work_"): continue
        item_path = os.path.join(folder_path, item)
        if os.path.isfile(item_path):
            ext = os.path.splitext(item)[1].lower()
            if ext in garbage_exts:
                try:
                    send2trash.send2trash(os.path.abspath(item_path))
                    removed_count += 1
                except: pass

    print(f"\r\n ✨ {G}폴더 정리 끝!{R} {moved_count}개 추출/정돈, {removed_count}개 찌꺼기 휴지통행! 🎉\r\n\r\n")
def process_video_file(v_path: str, translation_mode: Union[int, str], model: Any, trans_mode: Union[int, str], cleanup_mode: int = 0,
                       chunk_duration_sec: int = 300, whisper_size: str = "base",
                       colab_pool: Any = None, settings=None,
                       curr_file_idx: int = 1, total_file_count: int = 1,
                       is_repair_mode: bool = False, extra_tone_prompt: str = "", gemma_size: str = "4b",
                       show_cli_output: bool = False, is_resume: bool = False):
    global _G_SUBTITLE_QUOTA_EXCEEDED, _gemini_cli_quota_error_count
    _G_SUBTITLE_QUOTA_EXCEEDED = False
    _gemini_cli_quota_error_count = 0  # [V155.4] 새 비디오 파일 처리 시 쿼터 에러 횟수 초기화 🧼
    
    res = _process_video_file_internal(
        v_path, translation_mode, model, trans_mode, cleanup_mode,
        chunk_duration_sec, whisper_size, colab_pool, settings,
        curr_file_idx, total_file_count, is_repair_mode, extra_tone_prompt,
        gemma_size, show_cli_output, is_resume
    )
    
    if res is True:
        srt_path = os.path.splitext(v_path)[0] + ".srt"
        if os.path.exists(srt_path):
            try:
                with open(srt_path, "r", encoding="utf-8", errors="ignore") as f:
                    content = f.read()
                
                delay_count = content.count("[AI 응답 지연")
                total_blocks = content.count(" --> ")
                
                is_flooded = False
                if delay_count >= 5:
                    is_flooded = True
                elif total_blocks > 0 and delay_count >= 3 and (delay_count / total_blocks) >= 0.3:
                    is_flooded = True
                    
                if is_flooded:
                    print(f"\r\n🚨 {C.RED}{C.BOLD}[작업 중단]{C.RESET} 자막 결과에 '[AI 응답 지연/실패]' 메세지가 가득해냥! ({delay_count}/{total_blocks}개)")
                    try:
                        os.remove(srt_path)
                        print(f"   🗑️ 해당 자막 파일('{os.path.basename(srt_path)}')을 삭제했어냥! 🧹")
                    except Exception as e:
                        _log_to_file(f"⚠️ [FloodedSRTRemoveError] {e}")
                    
                    print(f"   🛑 {C.YELLOW}더 이상 자막을 생성하지 않고 전체 작업을 중단할게냥!{C.RESET}\r\n")
                    raise AIResponseFloodAbortException("AI 응답 지연 도배 감지")
            except AIResponseFloodAbortException:
                raise
            except Exception as e:
                _log_to_file(f"⚠️ [AI Delay Flood Wrapper Check Fail] {e}")
                
    return res

# [TAG: #@_safe_copy_subtitle]

def _safe_copy_subtitle(src, dst, max_retries=5, retry_delay=0.3):
    """[V3.9.1] 로컬 temp에 저장된 최종 자막을 대상 폴더(예: G 드라이브)로 안전 복사 🚚🛡️
    윈도우 파일 점유(WinError 32) 발생 시 0.3초 대기 후 최대 5회 재시도하여 안정성을 극대화합니다냥! 🐈✨"""
    import shutil, time
    for attempt in range(1, max_retries + 1):
        try:
            shutil.copy2(src, dst)
            return True
        except OSError as e:
            if e.errno == 28: # No space left on device
                print(f"\r\n ⚠️ {C.RED}{C.BOLD}[용량 부족 경고]{C.RESET} 대상 저장 장치(G 드라이브 등)의 용량이 꽉 차서 자막 파일을 대상 폴더로 복사하지 못했어냥!")
                print(f"    📢 {C.YELLOW}하지만 걱정 마냥! 번역 완료된 최종 자막 파일은 로컬 temp 폴더에 안전하게 살아있어냥!{C.RESET}")
                print(f"    📂 {C.GREEN}자막 보존 경로: {src}{C.RESET}\r\n")
                return False
            if attempt < max_retries:
                time.sleep(retry_delay)
                continue
            print(f"\r\n ⚠️ {C.RED}자막 파일 복사 실패 (기타 시스템 에러, {attempt}회 시도): {e}{C.RESET}\r\n")
            return False
        except Exception as e:
            if attempt < max_retries:
                time.sleep(retry_delay)
                continue
            print(f"\r\n ⚠️ {C.RED}자막 파일 복사 중 일반 예외 발생 ({attempt}회 시도): {e}{C.RESET}\r\n")
            return False
    return False

