import concurrent.futures
from concurrent.futures import ThreadPoolExecutor, as_completed

_agy_pipe_print_lock = threading.Lock()
_agy_pipe_file_write_lock = threading.Lock()

def _agy_pipe_safe_print(*args, log_fn=None, **kwargs):
    with _agy_pipe_print_lock:
        if log_fn:
            msg = " ".join(str(a) for a in args)
            log_fn(msg)
        else:
            print(*args, flush=True, **kwargs)
            sys.stdout.flush()

def _agy_pipe_send_file_to_trash(file_path, log_fn=None):
    if not os.path.exists(file_path):
        return
    try:
        if 'safe_remove_file' in globals():
            safe_remove_file(file_path, use_trash=True)
            _agy_pipe_safe_print(f"🗑️ [휴지통 이동 완료] {file_path}", log_fn=log_fn)
            return
    except Exception:
        pass
    try:
        import send2trash
        send2trash.send2trash(file_path)
        _agy_pipe_safe_print(f"🗑️ [휴지통 이동 완료] {file_path}", log_fn=log_fn)
    except Exception:
        try:
            cmd = [
                "powershell", "-NoProfile", "-Command",
                f"Add-Type -AssemblyName Microsoft.VisualBasic; [Microsoft.VisualBasic.FileIO.FileSystem]::DeleteFile('{os.path.abspath(file_path)}', 'OnlyErrorDialogs', 'SendToRecycleBin')"
            ]
            subprocess.run(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE, text=True, encoding="utf-8", errors="replace", creationflags=0x08000000 if os.name == 'nt' else 0, check=True)
            _agy_pipe_safe_print(f"🗑️ [휴지통 이동 완료 (PowerShell)] {file_path}", log_fn=log_fn)
        except Exception as e:
            _agy_pipe_safe_print(f"⚠️ 휴지통 이동 실패 ({e}), 파일 유지: {file_path}", log_fn=log_fn)

def _agy_pipe_get_audio_duration(file_path):
    fp_bin = _get_ffprobe_bin() if '_get_ffprobe_bin' in globals() else "ffprobe"
    cmd = [
        fp_bin, "-v", "error",
        "-show_entries", "format=duration",
        "-of", "default=noprint_wrappers=1:nokey=1",
        file_path
    ]
    res = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, encoding="utf-8", errors="replace", creationflags=0x08000000 if os.name == 'nt' else 0, check=True)
    return float(res.stdout.strip())

def _agy_pipe_extract_audio_from_video(video_path, output_mp3_path=None, log_fn=None, start_sec=None, duration_sec=None):
    if not os.path.exists(video_path):
        _agy_pipe_safe_print(f"❌ 비디오 파일을 찾을 수 없습니다: {video_path}", log_fn=log_fn)
        return None
        
    if not output_mp3_path:
        base_name = os.path.splitext(video_path)[0]
        output_mp3_path = base_name + ".mp3"
        
    out_dir = os.path.dirname(os.path.abspath(output_mp3_path))
    if out_dir:
        os.makedirs(out_dir, exist_ok=True)
        
    _seg_info = f" (구간: {start_sec:.1f}s ~ {start_sec+duration_sec:.1f}s)" if start_sec is not None and duration_sec is not None else ""
    _agy_pipe_safe_print(f"🎬 [1단계: 오디오 추출] 비디오에서 메인 오디오 트랙 추출 중...{_seg_info}", log_fn=log_fn)
    _agy_pipe_safe_print(f"  - 원본 영상: {video_path}", log_fn=log_fn)
    _agy_pipe_safe_print(f"  - 출력 오디오: {output_mp3_path}", log_fn=log_fn)
    
    ff_bin = _get_ffmpeg_bin() if '_get_ffmpeg_bin' in globals() else "ffmpeg"
    cmd = [ff_bin, "-y"]
    if start_sec is not None:
        cmd.extend(["-ss", str(start_sec)])
    if duration_sec is not None:
        cmd.extend(["-t", str(duration_sec)])
    cmd.extend([
        "-i", video_path,
        "-map", "0:a:0?",
        "-vn",
        "-c:a", "libmp3lame",
        "-q:a", "2",
        output_mp3_path
    ])
    
    try:
        subprocess.run(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE, text=True, encoding="utf-8", errors="replace", creationflags=0x08000000 if os.name == 'nt' else 0, check=True)
        size_mb = os.path.getsize(output_mp3_path) / (1024 * 1024)
        _agy_pipe_safe_print(f"✅ 오디오 추출 완료! ({size_mb:.2f} MB)", log_fn=log_fn)
        return output_mp3_path
    except subprocess.CalledProcessError as e:
        _agy_pipe_safe_print(f"❌ 오디오 추출 실패: {e.stderr}", log_fn=log_fn)
        return None

# [V230.0] 파일명 기반 강제 청크 분기(_agy_pipe_detect_media_profile)는 Whisper 실시간 발화량 감지 엔진으로 완전 통합 대체되어 정리되었습니다. 🧹✨

def _agy_pipe_find_adaptive_speech_chunks(audio_path, target_interval=90.0, min_chunk_dur=25.0, max_chunk_dur=120.0, min_speech_gap=3.5, noise_thresh="-30dB", log_fn=None):
    """
    [V230.0] Faster-Whisper Tiny 기반 초고속 발화 감지 + 발화량/대사수 기반 가변 청크 분할기 🎙️⚡
    - Whisper를 강제 번역용이 아닌 '발화량 및 무음 감지 센서'로만 사용하여 화자 입모양 100% 일치 실현!
    - 무음/BGM 구간(3.5초 이상)은 통째로 자동 스킵하여 시간 및 토큰 절약
    - 말이 쏟아지는 구간은 대사 수(14~18개)에 맞춰 30~50초 단위로 지능형 분할하여 AI 조기 중단 완벽 방어!
    """
    total_dur = _agy_pipe_get_audio_duration(audio_path)
    _agy_pipe_safe_print(f"\n🔍 [2단계: 초고속 Whisper Tiny 발화 밀도 및 무음 구간 정밀 스캔] 총 길이 {total_dur/60:.2f}분 ({total_dur:.3f}초)", log_fn=log_fn)
    
    # 1. 인메모리 Faster-Whisper Tiny 모델 확보
    model = _agy_pipe_get_whisper_tiny_model(log_fn=log_fn)
    raw_segments = []
    
    if model is not None:
        try:
            t0_scan = time.time()
            with _AGY_PIPE_WHISPER_LOCK:
                segments, info = model.transcribe(
                    audio_path,
                    beam_size=1,
                    best_of=1,
                    temperature=0.0,
                    condition_on_previous_text=False,
                    vad_filter=True,
                    vad_parameters=dict(threshold=0.5, min_silence_duration_ms=400, speech_pad_ms=150),
                    no_speech_threshold=0.6
                )
                with LoadingSpinner("🎙️ Whisper Tiny 초고속 발화 밀도 1회 전수 분석 중..."):
                    raw_segments = list(segments)
            t_scan_el = time.time() - t0_scan
            _agy_pipe_safe_print(f"  ✅ [Whisper Tiny 스캔 완료 ({t_scan_el:.2f}초)] 총 {len(raw_segments)}개 발화 세그먼트 감지 완료! ⚡", log_fn=log_fn)
        except Exception as scan_err:
            _agy_pipe_safe_print(f"  ⚠️ [Whisper 스캔 오류 발생: {scan_err}] FFmpeg 무음 탐색 모드로 대체합니다.", log_fn=log_fn)
            raw_segments = []

    # 2. Whisper 스캔 결과가 있는 경우: 발화량 및 무음 스킵 기반 스마트 청킹
    if raw_segments:
        # 유효 세그먼트 정제 (start, end, duration, text)
        speech_events = []
        for s in raw_segments:
            st = float(s.start)
            ed = float(s.end)
            dur = ed - st
            txt = str(s.text).strip() if getattr(s, "text", None) else ""
            if dur >= 0.1:
                speech_events.append((st, ed, dur, txt))
                
        if not speech_events:
            _agy_pipe_safe_print("⚠️ 유효 발화가 감지되지 않아 빈 청크로 처리합니다.", log_fn=log_fn)
            return []

        # 청크 분할 알고리즘
        # 목표: 대사 약 14~18개 또는 누적 발화 30~45초 도달 시 + 다음 대사 사이 쉼표에서 커팅
        # 무음 스킵: 이전 발화 끝과 다음 발화 시작 사이 gap >= min_speech_gap 이면 무음 구간 완전 제외!
        TARGET_UTTERANCES = 16
        TARGET_SPEECH_DUR = 35.0
        
        chunks = []
        c_events = []
        c_start = None
        
        for i, (st, ed, dur, txt) in enumerate(speech_events):
            if c_start is None:
                # 새 청크 시작: 발화 시작 0.6초 전 버퍼 (0초 이하 방지)
                c_start = max(0.0, st - 0.6)
                c_events = [(st, ed, dur, txt)]
                continue
                
            prev_st, prev_ed, prev_dur, _ = c_events[-1]
            gap = st - prev_ed
            c_total_dur = ed - c_start
            c_speech_dur = sum(e[2] for e in c_events) + dur  # [Fix] 현재 발화 포함하여 정확한 누적 발화 시간 계산
            c_count = len(c_events) + 1  # [Fix] 현재 발화 포함하여 정확한 대사 수 계산
            
            should_cut = False
            cut_includes_current = False  # [Fix] 현재 발화를 이전 청크에 포함할지 여부
            
            # 조건 A: 긴 무음 구간 발생 (gap >= min_speech_gap, e.g. 3.5초 이상 침묵/BGM)
            if gap >= min_speech_gap:
                should_cut = True
                
            # 조건 B: 발화량 목표 도달 (대사 16개 이상 또는 실발화 35초 이상) + 쉼표(gap >= 0.8초) 발생 + 최소 길이 만족
            elif (c_count >= TARGET_UTTERANCES or c_speech_dur >= TARGET_SPEECH_DUR) and gap >= 0.8 and c_total_dur >= min_chunk_dur:
                should_cut = True
                
            # 조건 C: 최대 청크 길이 초과 임박 (c_total_dur >= max_chunk_dur)
            # [Fix] 쉼표가 없더라도 max를 초과하면 현재 발화까지 포함시킨 후 컷!
            elif c_total_dur >= max_chunk_dur:
                should_cut = True
                cut_includes_current = True
                
            if should_cut:
                if cut_includes_current:
                    # [Fix] 현재 발화를 이전 청크에 포함 (대사 중간 잘림 방지)
                    c_end = min(total_dur, ed + 0.6)
                    if c_end > c_start + 0.5:
                        chunks.append((c_start, c_end))
                    c_start = None  # 다음 발화에서 새 청크 시작
                    c_events = []
                else:
                    # 현재 청크 확정 (이전 발화 끝 + 0.6초 버퍼)
                    c_end = min(total_dur, prev_ed + 0.6)
                    if c_end > c_start + 0.5:
                        chunks.append((c_start, c_end))
                    # 다음 청크 시작 준비 (무음은 자동 스킵됨!)
                    c_start = max(0.0, st - 0.6)
                    c_events = [(st, ed, dur, txt)]
            else:
                c_events.append((st, ed, dur, txt))
                
        # 마지막 잔여 청크 마무리
        if c_events and c_start is not None:
            last_ed = c_events[-1][1]
            c_end = min(total_dur, last_ed + 0.6)
            if c_end > c_start + 0.5:
                chunks.append((c_start, c_end))
                
    else:
        # Fallback: FFmpeg silencedetect 기반 분할
        _agy_pipe_safe_print("  ℹ️ FFmpeg silencedetect를 이용한 대체 분할을 진행합니다...", log_fn=log_fn)
        ff_bin = _get_ffmpeg_bin() if '_get_ffmpeg_bin' in globals() else "ffmpeg"
        cmd = [
            ff_bin, "-i", audio_path,
            "-af", f"silencedetect=noise={noise_thresh}:d=0.3",
            "-f", "null", "-"
        ]
        res = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, errors="replace")
        
        silence_ranges = []
        current_start = None
        for line in res.stderr.splitlines():
            if "silence_start:" in line:
                m = re.search(r"silence_start:\s*([0-9\.]+)", line)
                if m: current_start = float(m.group(1))
            elif "silence_end:" in line and current_start is not None:
                m = re.search(r"silence_end:\s*([0-9\.]+)", line)
                if m:
                    silence_ranges.append((current_start, float(m.group(1))))
                    current_start = None
                    
        if current_start is not None and current_start < total_dur:
            silence_ranges.append((current_start, total_dur))
            
        raw_speech_ranges = []
        cur_pos = 0.0
        for s_start, s_end in silence_ranges:
            if s_start > cur_pos + 0.2:
                raw_speech_ranges.append((cur_pos, s_start))
            cur_pos = max(cur_pos, s_end)
        if cur_pos < total_dur - 0.2:
            raw_speech_ranges.append((cur_pos, total_dur))
            
        if not raw_speech_ranges:
            return [(0.0, total_dur)]
            
        chunks = []
        for sp_start, sp_end in raw_speech_ranges:
            sp_dur = sp_end - sp_start
            if sp_dur <= max_chunk_dur:
                pad_start = max(0.0, sp_start - 0.8)
                pad_end = min(total_dur, sp_end + 0.8)
                chunks.append((pad_start, pad_end))
            else:
                c_cur = sp_start
                while c_cur < sp_end:
                    cut_point = min(sp_end, c_cur + target_interval)
                    chunks.append((max(0.0, c_cur - 0.8), min(total_dur, cut_point + 0.8)))
                    c_cur = cut_point

    # 3. 겹침 정리 및 인접 청크 스무딩 (안전 가드)
    safe_chunks = []
    for cs, ce in chunks:
        if not safe_chunks:
            safe_chunks.append((cs, ce))
        else:
            prev_cs, prev_ce = safe_chunks[-1]
            if cs <= prev_ce + 0.8:
                # 겹치거나 너무 가까우면 합치되, max_chunk_dur 이내일 때만 합침
                if ce - prev_cs <= max_chunk_dur:
                    safe_chunks[-1] = (prev_cs, max(prev_ce, ce))
                else:
                    safe_chunks.append((max(prev_ce, cs), ce))
            else:
                safe_chunks.append((cs, ce))
                
    total_active_sec = sum(ce - cs for cs, ce in safe_chunks)
    skipped_sec = max(0.0, total_dur - total_active_sec)
    
    _agy_pipe_safe_print(f"\n✨ [발화량 & 무음 스킵 지능형 가변 청크 확정] 총 {len(safe_chunks)}개 청크:", log_fn=log_fn)
    _agy_pipe_safe_print(f"  ⚡ 실제 AI 번역 처리 시간: {total_active_sec/60:.2f}분 ({total_active_sec:.1f}초) (전체 {total_dur/60:.2f}분 중)", log_fn=log_fn)
    if skipped_sec > 3.0:
        _agy_pipe_safe_print(f"  🛑 자동 스킵된 무음/BGM 구간: {skipped_sec/60:.2f}분 ({skipped_sec:.1f}초) ({(skipped_sec/total_dur)*100:.1f}% 토큰 & 시간 절약! 💸)", log_fn=log_fn)
    else:
        _agy_pipe_safe_print(f"  🛑 자동 스킵된 무음 구간: 0.0분 (0.0% 절약)", log_fn=log_fn)
        
    for i, (cs, ce) in enumerate(safe_chunks):
        dur = ce - cs
        tag = "스팟 대화 컷" if dur <= 25 else ("표준 밀도 대화 컷" if dur <= 60 else "여유 대화 컷")
        _agy_pipe_safe_print(f"  #{i+1:02d} 🎬 [{tag}] {timedelta(seconds=int(cs))} ~ {timedelta(seconds=int(ce))} (길이: {dur:.1f}초)", log_fn=log_fn)
        
    return safe_chunks

def _agy_pipe_create_virtual_video_clip(audio_path, start_sec, duration_sec, output_mp4_path):
    """
    [V234.0] agy CLI 전용 초경량 가상 비디오(MP4) 생성기 🎥⚡
    - agy CLI는 MP4 첨부만 지원하므로, 64x64 극소 해상도 + r=1 + threads=1 로 CPU 부하를 1% 미만으로 극소화
    - 부동소수점 오차 없는 소수점 3자리 정규화 타임스탬프 적용
    - 실패 시 stderr 핵심 에러 문장을 파싱하여 상세 안내 보장!
    """
    ff_bin = _get_ffmpeg_bin() if '_get_ffmpeg_bin' in globals() else "ffmpeg"
    ss_str = f"{float(start_sec):.3f}"
    dur_str = f"{float(duration_sec):.3f}"
    cmd = [
        ff_bin, "-y",
        "-ss", ss_str,
        "-t", dur_str,
        "-i", audio_path,
        "-f", "lavfi",
        "-t", dur_str,
        "-i", "color=c=black:s=64x64:r=1",
        "-c:v", "libx264",
        "-preset", "ultrafast",
        "-tune", "stillimage",
        "-crf", "38",
        "-pix_fmt", "yuv420p",
        "-c:a", "aac",
        "-b:a", "128k",
        "-ar", "44100",
        "-threads", "1",
        "-shortest",
        output_mp4_path
    ]
    proc = subprocess.run(
        cmd,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.PIPE,
        text=True,
        encoding="utf-8",
        errors="replace",
        creationflags=0x08000000 if os.name == 'nt' else 0
    )
    if proc.returncode != 0:
        err_lines = [l.strip() for l in (proc.stderr or "").splitlines() if l.strip()]
        err_tail = " | ".join(err_lines[-3:]) if err_lines else f"exit status {proc.returncode}"
        raise RuntimeError(f"FFmpeg 가상 비디오 생성 실패 ({err_tail})")
    return output_mp4_path

_agy_pipe_extract_audio_clip = _agy_pipe_create_virtual_video_clip

def _agy_pipe_parse_time_to_seconds(t_str):
    t_str = t_str.strip().replace(",", ".")
    parts = t_str.split(":")
    if len(parts) == 3:
        h, m, s = parts
        return float(h) * 3600 + float(m) * 60 + float(s)
    elif len(parts) == 2:
        m, s = parts
        return float(m) * 60 + float(s)
    return float(parts[0])

def _agy_pipe_format_seconds_to_srt_time(sec):
    if sec < 0: sec = 0.0
    total_ms = int(round(sec * 1000))
    ms = total_ms % 1000
    total_s = total_ms // 1000
    s = total_s % 60
    total_m = total_s // 60
    m = total_m % 60
    h = total_m // 60
    return f"{h:02d}:{m:02d}:{s:02d},{ms:03d}"

def _agy_pipe_parse_and_offset_srt_blocks(srt_text, offset_sec=0.0):
    entries = []
    time_pat = re.compile(
        r'(\d{1,2}:\d{2}:\d{2}[,\.]\d{1,3}|\d{1,2}:\d{2}[,\.]\d{1,3})\s*-->\s*(\d{1,2}:\d{2}:\d{2}[,\.]\d{1,3}|\d{1,2}:\d{2}[,\.]\d{1,3})'
    )
    lines = srt_text.splitlines()
    i = 0
    while i < len(lines):
        line = lines[i].strip()
        m = time_pat.search(line)
        if m:
            start_str, end_str = m.group(1), m.group(2)
            st = _agy_pipe_parse_time_to_seconds(start_str)
            ed = _agy_pipe_parse_time_to_seconds(end_str)
            
            text_lines = []
            i += 1
            while i < len(lines):
                cur = lines[i].strip()
                # 🚨 시스템 종료 마커(===END=== 등) 감지 시 무시
                if re.match(r'^=+\s*END\s*=+$', cur, re.IGNORECASE) or re.match(r'^=+$', cur):
                    i += 1
                    continue
                if not cur:
                    if i + 1 < len(lines) and (time_pat.search(lines[i+1]) or lines[i+1].strip().isdigit()):
                        break
                    else:
                        i += 1
                        continue
                if time_pat.search(cur) or (cur.isdigit() and i + 1 < len(lines) and time_pat.search(lines[i+1])):
                    break
                text_lines.append(cur)
                i += 1
                
            text = "\n".join(text_lines).strip()
            if text:
                entries.append((st + offset_sec, ed + offset_sec, text))
            continue
        i += 1
    return entries

