# [TAG: #@get_audio_codec]
def get_audio_codec(v_path):
    """ffprobe를 사용하여 오디오 코덱을 확인합니다."""
    script_dir = os.path.dirname(os.path.abspath(sys.argv[0]))
    ffprobe_bin = _get_ffprobe_bin()

    cmd = [ffprobe_bin, "-v", "error", "-select_streams", "a:0", "-show_entries", "stream=codec_name", "-of", "default=noprint_wrappers=1:nokey=1", v_path]
    try:
        c_flags = 0x08000000 if os.name == 'nt' else 0
        res = subprocess.run(cmd, capture_output=True, text=True, encoding="utf-8", errors="replace", creationflags=c_flags, check=True)
        return res.stdout.strip()
    except:
        return "aac" # 기본값

# [TAG: #@get_ext_by_codec]
def get_ext_by_codec(codec):
    """코덱에 맞는 확장자를 반환합니다."""
    mapping = {
        "aac": "m4a",
        "mp3": "mp3",
        "opus": "opus",
        "vorbis": "ogg",
        "flac": "flac",
        "alac": "m4a",
        "ac3": "ac3"
    }
    return mapping.get(codec, "mka") # 그 외엔 범용 mka

# [TAG: #@cut_video_interactive]
def cut_video_interactive(settings, prefix_getter: Callable = None):
    """영상 자르기 독립 기능 (3가지 모드 지원)"""
    processed_files = []
    # 1. 파일 선택
    v_paths = choose_video_files(title="작업할 영상/음성 파일을 선택해줘 (자르기/음성추출/VAD)")
    if not v_paths: return

    # 1-1. 선택한 영상 파일 정보 표시
    _print_video_file_info(v_paths, "✂️ 선택한 영상 정보")

    # 2. 저장 폴더 설정 메뉴 (1번에 현재 영상 폴더 기본값 제공)
    video_folder = ""
    if v_paths and len(v_paths) > 0:
        first_vp = v_paths[0]
        if os.path.exists(first_vp):
            video_folder = os.path.dirname(os.path.abspath(first_vp))
        else:
            video_folder = os.path.dirname(first_vp)

    working_path = settings.get_valid_path("cut_video_path") or settings.get_valid_path("download_path")
    if not working_path or not os.path.exists(working_path):
        working_path = os.getcwd() # 기본값으로 현재 디렉토리 설정

    script_dir = os.path.dirname(os.path.abspath(sys.argv[0]))

    folder_opts = []
    if video_folder and os.path.exists(video_folder):
        folder_opts.append({"type": "current", "path": video_folder, "label": f" 📁 현재 영상 폴더 ({video_folder}) (기본값)"})
    if working_path and os.path.exists(working_path) and os.path.normpath(working_path) != os.path.normpath(video_folder or ""):
        folder_opts.append({"type": "recent", "path": working_path, "label": f" 📂 최근 사용 폴더 ({working_path})"})
    elif not folder_opts:
        folder_opts.append({"type": "recent", "path": working_path, "label": f" 📂 최근 사용 폴더 ({working_path})"})

    folder_opts.append({"type": "browse", "path": "", "label": " 🔍 새 폴더 선택하기 (한번만 사용)..."})
    if os.path.normpath(script_dir) != os.path.normpath(video_folder or ""):
        folder_opts.append({"type": "program", "path": script_dir, "label": f" 🏠 프로그램 폴더 ({script_dir})"})
    folder_opts.append({"type": "cancel", "path": "", "label": " ❌ 이전 메뉴로 돌아가기"})

    path_options = [opt["label"] for opt in folder_opts]
    q_prefix = prefix_getter() if prefix_getter else ""
    path_choice, _, *_ = _interactive_menu("📂 어디에 저장할까?", path_options, timeout=0, prefix=q_prefix)
    if path_choice < 0 or path_choice >= len(folder_opts): return -1, "", False # [V77.5 Globalizer]

    sel_opt = folder_opts[path_choice]
    if sel_opt["type"] == "cancel":
        return
    elif sel_opt["type"] in ("current", "recent", "program"):
        cut_path = sel_opt["path"]
    elif sel_opt["type"] == "browse":
        import tkinter as tk
        root = tk.Tk(); root.withdraw()
        print(f"\r\n📂 {ctext('이번에만 사용할 저장 폴더를 선택해줘!', C.CYAN)}")
        _res = remote_explorer(mode='dir', title="저장 폴더 선택", initialdir=video_folder if video_folder else (working_path if working_path else script_dir))
        cut_path = _get_single_path(_res)
        root.destroy()
        if not cut_path: return
    else:
        cut_path = script_dir

    # 3. 자르기/추출 옵션 선택
    cut_options = [
        " 🕒 처음부터 몇 분까지 자르기 (0 ~ N분)",
        " 🕒 몇 분에서 몇 분까지 자르기 (N ~ M분)",
        " 🕒 뒤에서 몇 분 자르기 (끝에서 N분)",
        " 🎵 음성만 추출하기 (형식 선택 가능)",
        " ❌ 이전 메뉴로 돌아가기"
    ]
    q_prefix = prefix_getter() if prefix_getter else ""
    mode_idx, _, *_ = _interactive_menu("✂️ 무엇을 할까?", cut_options, timeout=0, prefix=q_prefix)
    if mode_idx < 0: return -1, "", False, "" # [V77.5 Globalizer]
    if mode_idx == 4: # 취소 선택
        return

    # 음성 추출 특수 로직
    if mode_idx == 3:
        audio_formats = [
            " 🎵 [MP3] 최고 음질 (320kbps)",
            " 🎵 [MP3] 표준 음질 (192kbps)",
            " 📝 [MP3] 전사용 최적 (64kbps, ~28MB/시간)",
            " 🎧 [M4A] 고음질 (AAC 192kbps)",
            " 📝 [M4A] 전사용 최적 (AAC 64kbps, ~28MB/시간)",
            " 🔊 [AC3] 고음질 서라운드",
            " ⚡ [무손실] 원본 코덱 그대로 추출 (Copy)",
            " ❌ 이전 메뉴로 돌아가기"
        ]
        q_prefix = prefix_getter() if prefix_getter else ""
        fmt_idx, _, *_ = _interactive_menu("🎧 어떤 형식으로 추출할까?", audio_formats, timeout=0, prefix=q_prefix)
        if fmt_idx < 0: return -1, "", False # [V77.5 Globalizer]
        if fmt_idx == len(audio_formats) - 1: # 취소 선택
            return
        audio_settings = [
            ("libmp3lame", "320k", "mp3"),
            ("libmp3lame", "192k", "mp3"),
            ("libmp3lame", "64k", "mp3"),
            ("aac", "192k", "m4a"),
            ("aac", "64k", "m4a"),
            ("ac3", "640k", "ac3"),
            ("copy", "0", "auto") # 무손실용
        ]
        codec, bitrate, ext_type = audio_settings[fmt_idx]

    start_min, end_min, last_min = 0, 0, 0
    if mode_idx == 0:
        q_p = prefix_getter() if prefix_getter else ""
        while True:
            val = prompt_input(f"\r\n 👉 {C.SKY}{q_p}처음부터 몇 분까지 자를까? (예: 5):{C.RESET} ").strip()
            if not val:
                print(f" {C.YELLOW}⚠️ 분량이 입력되지 않았어. 다시 입력해줘!{C.RESET}")
                continue
            try:
                end_min = safe_int(val)
                break
            except:
                print(f" {C.RED}❌ 숫자만 입력할 수 있어!{C.RESET}")
    elif mode_idx == 1:
        q_p = prefix_getter() if prefix_getter else ""
        while True:
            val1 = prompt_input(f" 👉 {C.SKY}{q_p}시작 분 (N):{C.RESET} ")
            val2 = prompt_input(f" 👉 {C.SKY}{q_p}종료 분 (M):{C.RESET} ")
            if not val1 or not val2:
                print(f" {C.YELLOW}⚠️ 시작분과 종료분을 모두 입력해야 해!{C.RESET}")
                continue
            try:
                start_min = safe_int(val1)
                end_min = safe_int(val2)
                if start_min >= end_min:
                    print(f" {C.RED}❌ 종료 분이 시작 분보다 커야 해!{C.RESET}")
                    continue
                break
            except:
                print(f" {C.RED}❌ 숫자만 입력할 수 있어!{C.RESET}")
    elif mode_idx == 2:
        q_p = prefix_getter() if prefix_getter else ""
        while True:
            val = prompt_input(f"\r\n 👉 {C.SKY}{q_p}뒤에서 몇 분을 자를까? (예: 3):{C.RESET} ").strip()
            if not val:
                print(f" {C.YELLOW}⚠️ 분량이 입력되지 않았어. 다시 입력해줘!{C.RESET}")
                continue
            try:
                last_min = safe_int(val)
                break
            except:
                print(f" {C.RED}❌ 숫자만 입력할 수 있어!{C.RESET}")

    print(f"\r\n{ctext('=' * 60, C.MAGENTA)}")
    msg = "음성 추출" if mode_idx == 3 else "영상 자르기"
    print(f" 🚀 {ctext(f'총 {len(v_paths)}개 파일 {msg} 시작!', C.YELLOW, C.BOLD)}")
    print(f"{ctext('=' * 60, C.MAGENTA)}")

    script_dir = os.path.dirname(os.path.abspath(sys.argv[0]))
    ffmpeg_bin = _get_ffmpeg_bin()

    success_count = 0
    start_time = time.time()

    # [V65.0] 필터링 상태 변수 (사용자 요청 🔍)
    for i, v_path in enumerate(v_paths):
        fname = os.path.basename(v_path)
        name, ext = os.path.splitext(fname)

        # 파일명 생성 규칙
        if mode_idx == 0:
            out_name = f"{name}_{end_min}min_cut{ext}"
        elif mode_idx == 1:
            out_name = f"{name}_{start_min}-{end_min}min_cut{ext}"
        elif mode_idx == 2:
            out_name = f"{name}_last{last_min}min_cut{ext}"
        else: # mode_idx == 3 (음성 추출)
            out_name = f"{name}.{ext_type}"

        out_path = os.path.join(cut_path, out_name)

        print(f" 🔹 [{i+1}/{len(v_paths)}] {ctext('작업 중:', C.CYAN)} {fname}")

        if mode_idx == 3:
            # 음성 추출 명령어
            if codec == "copy":
                real_codec = get_audio_codec(v_path)
                real_ext = get_ext_by_codec(real_codec)
                out_name = f"{name}.{real_ext}"
                out_path = os.path.join(cut_path, out_name)
                cmd = [ffmpeg_bin, "-y", "-i", v_path, "-vn", "-c:a", "copy", out_path]
            else:
                out_path = os.path.join(cut_path, out_name)
                cmd = [ffmpeg_bin, "-y", "-i", v_path, "-vn", "-c:a", codec, "-b:a", bitrate, out_path]
        else:
            # 시간 계산 (자르기용)
            actual_start = 0
            actual_duration = None

            if mode_idx == 0:
                actual_duration = end_min * 60
            elif mode_idx == 1:
                actual_start = start_min * 60
                actual_duration = (end_min - start_min) * 60
            else:
                # [V5.8] 렉 방지를 위해 영상 시간 체크 봉인 🐢🛑
                # total_dur = get_video_duration(v_path)
                total_dur = 0
                if total_dur > 0:
                    actual_start = max(0, total_dur - (last_min * 60))
                else:
                    print(f"   ❌ {ctext('파일 길이 확인 실패:', C.RED)} {fname}")
                    continue

            # FFmpeg 명령어 (스트림 카피 시도 - 빠름)
            cmd = [ffmpeg_bin, "-y", "-ss", str(actual_start)]
            if actual_duration:
                cmd.extend(["-t", str(actual_duration)])
            cmd.extend(["-i", v_path, "-c", "copy", out_path])

        try:
            # [V147.168] run_ffmpeg_task 적용으로 -nostdin 자동 삽입 및 안전성 강화 🛡️✨
            success, _, _ = run_ffmpeg_task(cmd, desc="영상 자르기/추출")
            if not success:
                raise Exception("FFmpeg 래퍼에서 실패 반환")
            print(f"   ✅ {ctext('성공!', C.GREEN)} ➜ {out_name}")
            success_count += 1
            processed_files.append(out_path)
        except Exception as e:
            print(f"   ❌ {ctext('실패:', C.RED)} {fname} (이유: {e})")

    elapsed = time.time() - start_time
    print(f"\r\n{ctext('=' * 60, C.GREEN)}")
    print(f" 🎉 {ctext(f'{msg} 작업 완료!', C.WHITE, C.BOLD)}")
    print(f" ✅ 성공: {success_count}개 / 실패: {len(v_paths) - success_count}개")
    print(f" ⏱️ 소요 시간: {elapsed:.1f}초")
    print(f" 📂 저장 위치: {cut_path}")
    print(f"{ctext('=' * 60, C.GREEN)}\r\n")

    # 세션 종료 공통 메뉴 호출
    if processed_files:
        go_to_main, new_v_paths = show_post_process_menu(processed_files, settings)
        if not go_to_main and new_v_paths:
            # [자막 만들기] 선택 시 v_paths를 업데이트하고 main의 자막 흐름으로 진입 유도
            return {"action": "add_subtitles", "files": new_v_paths}

    time.sleep(1)
    return None

# [TAG: #@_get_fast_hash]
def _get_fast_hash(file_path):
    """파일의 크기와 앞/중간/뒤 일부를 기반으로 빠른 해시 생성"""
    try:
        size = os.path.getsize(file_path)
        hasher = hashlib.md5()
        with open(file_path, 'rb') as f:
            if size < 1024 * 1024:
                hasher.update(f.read())
            else:
                hasher.update(f.read(8192))
                f.seek(size // 2)
                hasher.update(f.read(8192))
                f.seek(size - 8192)
                hasher.update(f.read(8192))
        return hasher.hexdigest()
    except: return None

# [TAG: #@_get_audio_signature]
def _get_audio_signature(file_path, duration=300):
    """영상에서 오디오를 추출(첫 duration초)하여 통계적 특징(평균/분산) 추출"""
    # [V147.168] 임시 파일을 중앙 temp 디렉토리로 이동 🏠✨
    temp_audio = get_srt_temp_path(file_path, "_sig.wav")
    try:
        script_dir = os.path.dirname(os.path.abspath(sys.argv[0]))
        ffmpeg_bin = _get_ffmpeg_bin()

        # 첫 5분만 추출하여 분석 (속도 중시)
        cmd = [ffmpeg_bin, "-y", "-i", file_path, "-t", str(duration), "-vn", "-ac", "1", "-ar", "8000", "-f", "wav", temp_audio]
        # [V147.168] run_ffmpeg_task 적용으로 -nostdin 자동 삽입 및 안전성 강화 🛡️✨
        run_ffmpeg_task(cmd, desc="시그니처 오디오 추출")

        if not os.path.exists(temp_audio): return None

        # 오디오 데이터 읽기
        import wave
        with wave.open(temp_audio, 'rb') as w:
            n_frames = w.getnframes()
            data = w.readframes(n_frames)
            import numpy as np
            samples = np.frombuffer(data, dtype=np.int16).astype(np.float32)
            if len(samples) == 0: return None
            # 평균과 분산을 시그니처로 사용 (간단하지만 크기 동일 시 효과적)
            return (np.mean(samples), np.var(samples))
    except: return None
    finally:
        # 🛠️ [리팩토링] safe_remove_file 사용
        safe_remove_file(temp_audio)

