# [TAG: #@_loop_delete_interactive]
def _loop_delete_interactive(title, items_getter, delete_callback, exit_label="❌ 취소",
                             allow_multi=False, multi_delete_callback=None):
    """
    [v98.7] 삭제 루프 통합 핸들러 🗑️🔄✨
    항목 삭제 후에도 상위 메뉴로 나가지 않고 해당 목록에 계속 머무를 수 있게 있습니다.
    [v260.10] allow_multi=True 면 Space 로 여러 개 골라 한 번에 삭제 지원 ✨🔍
             (multi_delete_callback 이 있으면 목록을 통째로 넘기고, 없으면 항목별 삭제)
    """
    R = C.RESET
    while True:
        items = items_getter()
        if not items:
            print(f"\r\n ⚠️ {C.RED}삭제할 항목이 하나도 없어!{R}")
            time.sleep(1)
            break

        # UI 레이아웃 구성
        del_opts = [{"label": f" 🗑️ {item}", "key": item} for item in items]
        del_opts.append({"label": f" {exit_label}", "key": "cancel"})

        opt_labels = [i["label"] for i in del_opts]
        _m_title = title + ("   (Space 여러 개 선택 → Enter 확정)" if allow_multi else "")
        sel, *_ = _interactive_menu(_m_title, opt_labels, timeout=0, allow_multi=allow_multi)

        if sel is None:
            break

        cancel_idx = len(del_opts) - 1
        if isinstance(sel, (list, set, tuple)):
            # [규칙] 데이터 항목에서 Enter/숫자 입력 시에는 다중 선택 인덱스 리스트가 돌아온다
            if any(isinstance(_i, int) and _i == cancel_idx for _i in sel):
                break  # 취소 버튼 커서에서 Enter/숫자 입력 → 빠져나간다 🛑
            sel_keys = []
            for _i in sel:
                if isinstance(_i, int) and 0 <= _i < cancel_idx:
                    sel_keys.append(del_opts[_i]["key"])
            if not sel_keys:
                continue
        else:
            if not isinstance(sel, int) or sel < 0 or sel == cancel_idx:  # ESC or 취소
                break
            sel_keys = [del_opts[sel]["key"]]

        # 🛡️ 여러 개를 한 번에 지울 때는 실수 방지 확인 한 번 🛡️
        if len(sel_keys) > 1:
            print(f"\r\n 🗑️ {C.YELLOW}선택한 {len(sel_keys)}건을 목록에서 뺄게!{R}")
            for _k in sel_keys:
                print(f"    - {_smart_truncate(str(_k), 66)}")
            _ans = str(prompt_input(f" 👉 {C.BOLD}정말 삭제할까? (y/N):{R} ")).strip().lower()
            if _ans not in ("y", "yes", "ㅇ", "예"):
                print(f"    {C.DIM}취소했어!{R}")
                time.sleep(0.8)
                continue

        if len(sel_keys) > 1 and callable(multi_delete_callback):
            # 일괄 삭제 콜백 (한 번에 저장) ⚡
            if multi_delete_callback(sel_keys):
                print(f"\r\n ✅ {C.GREEN}{len(sel_keys)}개 항목 삭제 완료!{R}")
                time.sleep(0.6)
            else:
                print(f"\r\n ❌ {C.RED}삭제 처리 중 문제가 발생했어.{R}")
                time.sleep(1)
            continue

        for target_key in sel_keys:
            # 삭제 콜백 실행 (성공 시 True 반환)
            if delete_callback(target_key):
                print(f"\r\n ✅ {C.GREEN}'{_smart_truncate(str(target_key), 66)}' 삭제 완료!{R}")
                time.sleep(0.5) # 쾌속 삭제를 위해 대기 시간 단축 ✨
            else:
                print(f"\r\n ❌ {C.RED}삭제 처리 중 문제가 발생했어.{R}")
                time.sleep(1)

# [TAG: #@playlist_group_interactive]
# [TAG: #@_virtual_folder_interactive_manager]
def create_virtual_folder_interactive(settings):
    """🔮 가상 병합 폴더(Union Folder) 생성 대화형 메뉴"""
    R = C.RESET
    s = settings
    vf_map = s.data.setdefault('virtual_folders', {})
    
    seen_paths = set()
    candidate_list = []
    
    # 1) 즐겨찾기 폴더들 수집
    for grp_paths in list(s.data.get('playlist_groups', {}).values()) + list(s.data.get('playlist_music_groups', {}).values()):
        if isinstance(grp_paths, list):
            for p in grp_paths:
                if isinstance(p, str) and os.path.isdir(p):
                    norm_p = os.path.normpath(p)
                    if os.path.normcase(norm_p) not in seen_paths:
                        seen_paths.add(os.path.normcase(norm_p))
                        candidate_list.append(norm_p)

    for p in s.data.get('custom_favorites', []):
        if isinstance(p, str) and os.path.isdir(p):
            norm_p = os.path.normpath(p)
            if os.path.normcase(norm_p) not in seen_paths:
                seen_paths.add(os.path.normcase(norm_p))
                candidate_list.append(norm_p)

    # 2) 다이렉트 숏컷 폴더들 수집
    for p in s.data.get('direct_shortcuts', []):
        if isinstance(p, str) and not _is_virtual_path(p) and os.path.isdir(p):
            norm_p = os.path.normpath(p)
            if os.path.normcase(norm_p) not in seen_paths:
                seen_paths.add(os.path.normcase(norm_p))
                candidate_list.append(norm_p)
                
    # 3) WebDAV 폴더들 수집
    for f in s.data.get('file_webdav_folders', []):
        if not f.get('is_virtual') and f.get('path'):
            p = os.path.normpath(f.get('path'))
            if os.path.isdir(p) and os.path.normcase(p) not in seen_paths:
                seen_paths.add(os.path.normcase(norm_p))
                candidate_list.append(p)

    # 4) 드라이브 목록 수집
    import string
    for d in string.ascii_uppercase:
        drv = f"{d}:\\"
        if os.path.exists(drv) and os.path.normcase(drv) not in seen_paths:
            seen_paths.add(os.path.normcase(drv))
            candidate_list.append(drv)

    menu_opts = []
    for p in candidate_list:
        base_nm = os.path.basename(p.rstrip('\\/')) or p
        menu_opts.append(f"📁 {base_nm}  →  {p}")

    print(f"\r\n {C.PURPLE}╔{'═'*65}{R}")
    print(f" {C.PURPLE}║{R}  🔮 {C.BOLD}{C.GOLD}가상 병합 폴더 생성 (Union Virtual Folder){R}")
    print(f" {C.PURPLE}╟{'─'*65}{R}")
    print(f" {C.PURPLE}║{R}  💡 여러 드라이브/물리 폴더를 하나의 가상 폴더로 합쳐서 탐색/재생합니다.")
    print(f" {C.PURPLE}║{R}  💡 {C.GREEN}Space키{R}로 묶을 물리 폴더들을 2개 이상 선택 후 {C.GREEN}Enter{R}를 눌러줘냥!")
    print(f" {C.PURPLE}╚{'═'*65}{R}\r\n")

    try:
        sel_res, _, *_ = _interactive_menu(
            "🔮 가상 폴더로 묶을 물리 폴더 선택 (Space: 다중선택, Enter: 완료)",
            menu_opts,
            allow_multi=True,
            allow_empty=True
        )
    except UserAbortException:
        return

    if sel_res is None or (isinstance(sel_res, int) and sel_res < 0):
        return

    if isinstance(sel_res, int):
        selected_idxs = [sel_res]
    else:
        selected_idxs = list(sel_res)

    selected_paths = [candidate_list[i] for i in selected_idxs if 0 <= i < len(candidate_list)]

    if len(selected_paths) < 1:
        print(f" ⚠️ {C.YELLOW}폴더가 선택되지 않았어냥!{R}")
        time.sleep(1)
        return

    print(f"\r\n 🏷️  {C.CYAN}가상 병합 폴더의 이름을 입력해줘 (예: movies, aaa, all_series):{R}")
    name_input = input("   가상 이름> ").strip().replace("/", "_").replace("\\", "_")
    if not name_input:
        name_input = "merged_" + os.path.basename(selected_paths[0].rstrip('\\/'))

    if name_input in vf_map:
        print(f" ⚠️ {C.RED}'{name_input}' 이름은 이미 사용 중이야냥!{R}")
        time.sleep(1.5)
        return

    vf_map[name_input] = selected_paths
    s.data['virtual_folders'] = vf_map
    s.save()
    print(f"\r\n ✅ {C.GREEN}🔮 {name_input} (물리 폴더 {len(selected_paths)}개 병합) 생성 완료!{R}")
    time.sleep(1.2)


def manage_virtual_folders_interactive(settings):
    """⚙️ 가상 병합 폴더 관리 (목록/추가/삭제/수정)"""
    R = C.RESET
    s = settings
    while True:
        vf_map = s.data.get('virtual_folders', {})
        if not vf_map:
            print(f"\r\n ⚠️ {C.YELLOW}등록된 가상 병합 폴더가 없어냥! 새로 생성해줘냥.{R}")
            time.sleep(1.2)
            create_virtual_folder_interactive(s)
            break

        menu_opts = []
        v_keys = list(sorted(vf_map.keys()))
        for k in v_keys:
            paths = vf_map[k]
            _valid_c = sum(1 for p in paths if os.path.exists(p))
            _summary_p = ", ".join([os.path.basename(p.rstrip('\\/')) or p for p in paths[:2]])
            if len(paths) > 2: _summary_p += f" 외 {len(paths)-2}개"
            menu_opts.append(f"🔮 {k}  →  [{len(paths)}개 물리 폴더 병합] ({_summary_p})")
        menu_opts.append("➕ 새 가상 병합 폴더 생성하기")
        menu_opts.append("❌ 나가기")

        choice, _, *_ = _interactive_menu("⚙️ 관리할 가상 병합 폴더 선택", menu_opts)
        if choice < 0 or choice == len(menu_opts) - 1:
            break
        if choice == len(menu_opts) - 2:
            create_virtual_folder_interactive(s)
            continue

        selected_k = v_keys[choice]

        # ━━━ 선택된 가상 폴더 상세 관리 루프 ━━━
        while True:
            vf_map = s.data.get('virtual_folders', {})
            if selected_k not in vf_map:
                break
            current_paths = vf_map[selected_k]

            # [상태창] 선택된 가상 병합 폴더 정보 박스 출력 🔮📦✨
            valid_c = sum(1 for p in current_paths if os.path.exists(p))
            stat_c = f"{C.GREEN}{valid_c}개 정상{R}" if valid_c == len(current_paths) else f"{C.YELLOW}{valid_c}/{len(current_paths)}개 정상{R}"
            box_w = 68
            print(f"\r\n {C.PURPLE}╔{'═' * box_w}{R}")
            print(f" {C.PURPLE}║{R}  🔮 {C.BOLD}{C.GOLD}가상 병합 폴더: {selected_k}{R}  {C.DIM}(virtual://{selected_k}){R}")
            print(f" {C.PURPLE}╟{'─' * box_w}{R}")
            print(f" {C.PURPLE}║{R}  📁 묶인 물리 폴더: {C.SKY}총 {len(current_paths)}개{R} ({stat_c})")
            print(f" {C.PURPLE}╟{'─' * box_w}{R}")
            for p in current_paths:
                _exists = os.path.exists(p)
                _st_icon = f"{C.GREEN}✅{R}" if _exists else f"{C.RED}❌{R}"
                _st_text = "" if _exists else f" {C.RED}(경로 없음){R}"
                print(f" {C.PURPLE}║{R}   {_st_icon} {C.CYAN}{p}{R}{_st_text}")
            print(f" {C.PURPLE}╚{'═' * box_w}{R}\r\n")

            sub_opts = [
                f"📂 🔮 {selected_k} 가상 폴더 즉시 열기",
                f"➕ 물리 폴더 추가하기",
                f"➖ 물리 폴더 제거하기",
                f"🏷️ 가상 폴더 이름 변경하기",
                f"🗑️ 가상 폴더 삭제하기",
                f"❌ 돌아가기"
            ]

            sub_choice, _, *_ = _interactive_menu(f"🔮 {selected_k} 가상 폴더 설정", sub_opts)
            if sub_choice < 0 or sub_choice == len(sub_opts) - 1:
                break
            elif sub_choice == 0:
                # 가상 폴더 즉시 열기
                return f"virtual://{selected_k}"
            elif sub_choice == 1:
                # 물리 폴더 추가
                add_p = remote_explorer(mode='dir', title=f"🔮 {selected_k}에 추가할 물리 폴더 선택")
                if add_p and isinstance(add_p, list) and len(add_p) > 0:
                    p_to_add = add_p[0]
                    if p_to_add not in current_paths:
                        current_paths.append(p_to_add)
                        vf_map[selected_k] = current_paths
                        s.data['virtual_folders'] = vf_map
                        s.save()
                        print(f" ✅ {C.GREEN}{p_to_add} 추가 완료!{R}"); time.sleep(1)
            elif sub_choice == 2:
                # 물리 폴더 제거
                if len(current_paths) <= 1:
                    print(f" ⚠️ {C.YELLOW}폴더가 1개뿐이라 제거할 수 없어냥!{R}"); time.sleep(1.2)
                    continue
                del_opts = [f"📁 {p}" for p in current_paths] + ["❌ 취소"]
                del_c, _, *_ = _interactive_menu("제거할 물리 폴더 선택", del_opts)
                if 0 <= del_c < len(current_paths):
                    removed = current_paths.pop(del_c)
                    vf_map[selected_k] = current_paths
                    s.data['virtual_folders'] = vf_map
                    s.save()
                    print(f" ✅ {C.GREEN}{removed} 제거 완료!{R}"); time.sleep(1)
            elif sub_choice == 3:
                # 이름 변경
                new_nm = input(f" 새 가상 폴더 이름 ({selected_k} -> ): ").strip().replace("/", "_").replace("\\", "_")
                if new_nm and new_nm != selected_k:
                    if new_nm in vf_map:
                        print(f" ⚠️ {C.RED}'{new_nm}' 이름은 이미 존재해냥!{R}"); time.sleep(1.2)
                    else:
                        vf_map[new_nm] = vf_map.pop(selected_k)
                        # direct_shortcuts 갱신
                        ds = s.data.get('direct_shortcuts', [])
                        old_vpath = f"virtual://{selected_k}"
                        new_vpath = f"virtual://{new_nm}"
                        if old_vpath in ds:
                            ds[ds.index(old_vpath)] = new_vpath
                            s.data['direct_shortcuts'] = ds
                        s.data['virtual_folders'] = vf_map
                        s.save()
                        selected_k = new_nm
                        print(f" ✅ {C.GREEN}이름이 '{new_nm}'(으)로 변경되었어냥!{R}"); time.sleep(1)
            elif sub_choice == 4:
                # 가상 폴더 삭제
                confirm = input(f" 🗑️ 정말 '🔮 {selected_k}' 가상 폴더를 삭제할까냥? (물리 파일은 삭제되지 않음) (y/N): ").strip().lower()
                if confirm in ('y', 'yes'):
                    del vf_map[selected_k]
                    old_vpath = f"virtual://{selected_k}"
                    ds = s.data.get('direct_shortcuts', [])
                    if old_vpath in ds:
                        ds.remove(old_vpath)
                        s.data['direct_shortcuts'] = ds
                    s.data['virtual_folders'] = vf_map
                    s.save()
                    print(f" ✅ {C.GREEN}🔮 {selected_k} 삭제 완료!{R}"); time.sleep(1)
                    break

# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
# 🖼️ [Fotoo Engine] 이미지 그룹 및 전자액자/스크린세이버 헬퍼 함수
# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
IMAGE_EXTENSIONS = ('.jpg', '.jpeg', '.png', '.webp', '.gif', '.bmp', '.heic', '.avif', '.svg')
# [규칙] 브라우저가 <video> 로 바로 재생 가능한 확장자만 담는다.
#        (.mov/.mkv/.avi 는 Chrome 이 못 틀어 넣으므로 의도적으로 제외)
#        → Pixiv 우고이라 MP4 변환분을 슬라이드 사이사이에 자연스럽게 편입시킨다 🎬
VIDEO_EXTENSIONS_FOTOO = ('.mp4', '.webm', '.m4v')
# 📂 [Fotoo 스캔 대상] 이미지 + 영상 통합. 슬라이드에 둘 다 함께 올라간다.
FOTOO_MEDIA_EXTENSIONS = IMAGE_EXTENSIONS + VIDEO_EXTENSIONS_FOTOO
_image_count_cache = {} # {folder_path: (mtime, count)}
_gphoto_album_cache = {} # {clean_url: (timestamp, [photo_dict, ...])}

def _is_gphoto_url(path: str) -> bool:
    """구글 포토 공유 앨범 링크인지 판별 📸✨"""
    if not isinstance(path, str): return False
    p = path.strip().lower()
    return (
        p.startswith("https://photos.app.goo.gl/") or
        p.startswith("http://photos.app.goo.gl/") or
        p.startswith("photos.app.goo.gl/") or
        p.startswith("https://photos.google.com/share/") or
        p.startswith("http://photos.google.com/share/") or
        p.startswith("photos.google.com/share/") or
        p.startswith("https://photos.google.com/album/") or
        p.startswith("photos.google.com/album/") or
        p.startswith("gphotos://")
    )

def _clean_gphoto_url(path: str) -> str:
    """gphotos:// 접두사 제거 및 URL 정규화 🔗"""
    if not isinstance(path, str): return ""
    p = path.strip()
    if p.startswith("gphotos://"):
        p = p[10:].strip()
    # 프로토콜 누락 시 https:// 자동 보정
    if not p.startswith("http://") and not p.startswith("https://"):
        if p.startswith("photos.app.goo.gl") or p.startswith("photos.google.com"):
            p = "https://" + p
    return p.rstrip('/')

def _parse_gphoto_url_tokens(text: str):
    """붙여넣은 텍스트에서 구글 포토 공유 앨범 URL을 '여러 개' 추출 (줄바꿈/공백/쉼표 구분) 🔗✨
    [규칙] 카드 1장 = 이미지 그룹 1장 → 앨범을 몇 개 등록해도 /media 에는 카드 1장만 노출되고,
           슬라이드/셔플 시 그룹에 속한 모든 앨범 사진이 하나로 섞여 재생된다.
    - 공백으로 붙여넣어도, 한 줄에 하나씩 붙여넣어도, 문장에 섞여 있어도 URL 만 정확히 뽑는다.
    - 중복은 최초 등장 순서대로 제거한다 (입력 순서 보존).
    """
    if not isinstance(text, str):
        return []
    # [실측] 공유 링크 실형태가 두 가지라 따로 처리해야 한다:
    #        ① https://photos.app.goo.gl/<id>          → 짧은 호스트 뒤에 id 가 바로 온다 (경로 계층 없음!)
    #        ② https://photos.google.com/share/<id>   → 'share' 또는 'album' 경로 계층이 있다
    #        괄호/문장부호로 끝나는 URL 오인식 방지를 위해 id 는 영숫자/_/- 만 허용한다.
    _pat = (r'(?:https?://)?photos\.app\.goo\.gl/[A-Za-z0-9_\-]+'
            r'|(?:https?://)?photos\.google\.com/(?:share|album)/[A-Za-z0-9_\-]+')
    found, seen = [], set()
    for _m in re.finditer(_pat, text):
        clean_u = _clean_gphoto_url(_m.group(0))
        if not _is_gphoto_url(clean_u):
            continue
        if clean_u in seen:
            continue
        seen.add(clean_u)
        found.append(clean_u)
    return found

def _get_gphoto_db_path():
    """temp/gphoto_cache.db 경로 반환 및 디렉터리 보장 📁"""
    db_dir = os.path.join(BASE_DIR, "temp")
    os.makedirs(db_dir, exist_ok=True)
    return os.path.join(db_dir, "gphoto_cache.db")

def _init_gphoto_db():
    """temp/gphoto_cache.db SQLite 단일 캐시 DB 초기화 🗄️✨"""
    import sqlite3
    db_path = _get_gphoto_db_path()
    try:
        with sqlite3.connect(db_path, timeout=5.0) as conn:
            conn.execute("""
                CREATE TABLE IF NOT EXISTS gphoto_albums (
                    album_url TEXT PRIMARY KEY,
                    album_id TEXT,
                    album_title TEXT,
                    photos_json TEXT,
                    photo_count INTEGER,
                    updated_at REAL
                )
            """)
            conn.commit()
    except Exception as e:
        try: _log_to_file(f"⚠️ [_init_gphoto_db Error] {e}")
        except: pass

def _load_gphoto_from_db(clean_url, with_meta: bool = False):
    """temp/gphoto_cache.db에서 캐시된 사진 목록 로드 ⚡ (with_meta=True 시 (photos, updated_at, count, title) 반환)"""
    import sqlite3
    import json
    import re
    db_path = _get_gphoto_db_path()
    if not os.path.exists(db_path):
        return (None, 0.0, 0, "") if with_meta else None
    try:
        with sqlite3.connect(db_path, timeout=5.0) as conn:
            cursor = conn.cursor()
            cursor.execute(
                "SELECT album_title, photos_json, photo_count, updated_at FROM gphoto_albums WHERE album_url = ?",
                (clean_url,)
            )
            row = cursor.fetchone()
            if not row and '/share/' in clean_url:
                m = re.search(r'/share/([^/?#]+)', clean_url)
                if m:
                    cursor.execute(
                        "SELECT album_title, photos_json, photo_count, updated_at FROM gphoto_albums WHERE album_id = ?",
                        (m.group(1),)
                    )
                    row = cursor.fetchone()
            if row and row[1]:
                photos = json.loads(row[1])
                if with_meta:
                    return photos, float(row[3] or 0.0), int(row[2] or len(photos)), (row[0] or "")
                return photos
    except Exception as e:
        try: _log_to_file(f"⚠️ [_load_gphoto_from_db Error] {e}")
        except: pass
    return (None, 0.0, 0, "") if with_meta else None

def _touch_gphoto_db_updated_at(clean_url):
    """사진 변동이 없을 때 DB의 updated_at만 현재 시각으로 갱신하여 24시간 Freeze 연장 ❄️"""
    import sqlite3
    import time
    clean_u = _clean_gphoto_url(clean_url)
    db_path = _get_gphoto_db_path()
    if not os.path.exists(db_path):
        return
    try:
        with sqlite3.connect(db_path, timeout=5.0) as conn:
            cursor = conn.cursor()
            cursor.execute("UPDATE gphoto_albums SET updated_at = ? WHERE album_url = ?", (time.time(), clean_u))
            conn.commit()
    except Exception as e:
        try: _log_to_file(f"⚠️ [_touch_gphoto_db_updated_at Error] {e}")
        except: pass


def _get_gphoto_cached_info(clean_url):
    """DB에서 가볍게 앨범 제목과 사진 개수를 0.001초 만에 조회 ⚡"""
    clean_u = _clean_gphoto_url(clean_url)
    if clean_u in _gphoto_album_cache:
        cached_photos = _gphoto_album_cache[clean_u][1]
        title = cached_photos[0].get('name', '').rsplit(' ', 1)[0] if cached_photos else ""
        return title, len(cached_photos)
    import sqlite3
    import re
    db_path = _get_gphoto_db_path()
    if not os.path.exists(db_path):
        return "", 0
    try:
        with sqlite3.connect(db_path, timeout=5.0) as conn:
            cursor = conn.cursor()
            cursor.execute("SELECT album_title, photo_count FROM gphoto_albums WHERE album_url = ?", (clean_u,))
            row = cursor.fetchone()
            if not row and '/share/' in clean_u:
                m = re.search(r'/share/([^/?#]+)', clean_u)
                if m:
                    cursor.execute("SELECT album_title, photo_count FROM gphoto_albums WHERE album_id = ?", (m.group(1),))
                    row = cursor.fetchone()
            if row:
                return row[0] or "구글 포토", row[1] or 0
    except Exception:
        pass
    return "", 0

def _get_gphoto_cached_count(clean_url):
    """DB에서 사진 개수만 초고속 조회 ⚡"""
    _, cnt = _get_gphoto_cached_info(clean_url)
    return cnt


def _get_gphoto_album_recency(clean_url, photos=None):
    """[신규 2026-10-03] 구글 포토 공유 앨범의 '최신 사진 시각' 추출 — 카드 정렬용 ⌛✨
    - 반환값은 '구글 공유 앨범 카드(이미지 소스 하나)'의 진짜 시간값.
      예전엔 모든 앨범 카드에 mtime=9999999999.0 을 고정下发해서
      시간역순/시간순 정렬이 아예 동작하지 않았다 (stable sort → 등록순 유지) 🐛
    - 1순위: 캐시된 사진들의 timestamp 최대값 (= 앨범 최신 사진 촬영시각)
    - 2순위: DB updated_at (마지막 수집 시각)
    - 3순위: 0.0 (알 수 없음 → 정렬 시 최하단)
    🛡️ [FIX 2026-10-03] 다른 gphoto 헬퍼와 동일하게 반드시 _clean_gphoto_url() 정규화를 거친다.
       정규화 없이 조회하면 'photos.app.goo.gl/xxx'(프로토콜 없음) 처럼 DB 키와 어긋난 URL 은
       조회 실패 → 0.0 → 최신순 맨 밑으로 가라앉는 버그가 생겼다.
    """
    clean_u = _clean_gphoto_url(clean_url)
    if not clean_u:
        return 0.0
    try:
        if photos is None:
            photos = _load_gphoto_from_db(clean_u) or []
        best = 0.0
        for p in (photos or []):
            if not isinstance(p, dict):
                continue
            try:
                ts = float(p.get('timestamp') or 0)
            except Exception:
                ts = 0.0
            if ts > best:
                best = ts
        if best > 0.0:
            return best
    except Exception as e:
        try: _log_to_file(f"⚠️ [_get_gphoto_album_recency scan error] {e}")
        except Exception: pass
    try:
        _ph, updated_at, _c, _t = _load_gphoto_from_db(clean_u, with_meta=True)
        return float(updated_at or 0.0)
    except Exception:
        return 0.0

def _save_gphoto_to_db(clean_url, album_id, album_title, photos):
    """temp/gphoto_cache.db에 사진 목록 저장 💾"""
    import sqlite3
    import json
    import time
    _init_gphoto_db()
    db_path = _get_gphoto_db_path()
    try:
        with sqlite3.connect(db_path, timeout=5.0) as conn:
            cursor = conn.cursor()
            cursor.execute("""
                INSERT OR REPLACE INTO gphoto_albums 
                (album_url, album_id, album_title, photos_json, photo_count, updated_at)
                VALUES (?, ?, ?, ?, ?, ?)
            """, (
                clean_url,
                album_id or "",
                album_title or "",
                json.dumps(photos, ensure_ascii=False),
                len(photos),
                time.time()
            ))
            conn.commit()
    except Exception as e:
        try: _log_to_file(f"⚠️ [_save_gphoto_to_db Error] {e}")
        except: pass

def _delete_gphoto_from_db(clean_url):
    """temp/gphoto_cache.db에서 앨범 데이터 삭제 🗑️"""
    import sqlite3
    clean_u = _clean_gphoto_url(clean_url)
    db_path = _get_gphoto_db_path()
    if not os.path.exists(db_path):
        return
    try:
        with sqlite3.connect(db_path, timeout=5.0) as conn:
            cursor = conn.cursor()
            cursor.execute("DELETE FROM gphoto_albums WHERE album_url = ?", (clean_u,))
            conn.commit()
    except Exception as e:
        try: _log_to_file(f"⚠️ [_delete_gphoto_from_db Error] {e}")
        except: pass

def _extract_gphoto_media_info(item):
    """구글 포토 아이템에서 비디오 여부 및 재생시간(초) 추출 🎬✨"""
    is_video = False
    duration = 0
    if isinstance(item, list):
        for el in item:
            if isinstance(el, dict):
                # 1) 비디오 duration 추출 ('139842850')
                if '139842850' in el:
                    v = el['139842850']
                    if isinstance(v, list) and len(v) > 0 and isinstance(v[0], list) and len(v[0]) > 0:
                        try:
                            duration = int(float(str(v[0][0])))
                            is_video = True
                        except Exception:
                            pass
                # 2) 비디오/모션 포토 메타데이터 ('83148624', '76647426')
                if '83148624' in el or '76647426' in el:
                    is_video = True
                    if duration <= 0:
                        duration = 4  # 기본 모션 포토 재생시간 4초
                break
    return is_video, duration

def _extract_gphoto_item_meta(item):
    """구글 포토 item에서 촬영 날짜, 타임스탬프, 위치/설명 추출 🍊✨"""
    import datetime
    date_str = ""
    timestamp = 0.0
    location_str = ""

    def _find_ts(obj):
        nonlocal timestamp, date_str
        if timestamp > 0:
            return
        if isinstance(obj, (int, float)):
            # 13자리 밀리초 타임스탬프 (2000년 ~ 2035년: 946684800000 ~ 2051222400000)
            if 946684800000 <= obj <= 2051222400000:
                ts = obj / 1000.0
                try:
                    dt = datetime.datetime.fromtimestamp(ts)
                    date_str = f"{dt.year}년 {dt.month}월 {dt.day}일"
                    timestamp = ts
                except Exception:
                    pass
            # 10자리 초 타임스탬프 (946684800 ~ 2051222400)
            elif 946684800 <= obj <= 2051222400:
                try:
                    dt = datetime.datetime.fromtimestamp(obj)
                    date_str = f"{dt.year}년 {dt.month}월 {dt.day}일"
                    timestamp = float(obj)
                except Exception:
                    pass
        elif isinstance(obj, list):
            for sub in obj:
                _find_ts(sub)
                if timestamp > 0:
                    break

    def _find_loc(obj):
        nonlocal location_str
        if location_str: return
        if isinstance(obj, str):
            s = obj.strip()
            if s and len(s) < 80 and not s.startswith('http') and not s.startswith('AF1Qip'):
                if any(k in s for k in ['시 ', '군 ', '구 ', '동 ', '읍 ', '면 ', '리 ', '길 ', '로 ', '제주', '서울', '부산', '인천', '대구', '대전', '광주', '울산', '세종', '경기', '강원', '충북', '충남', '전북', '전남', '경북', '경남', '대만', '타이베이', '가오슝', '도쿄', '오사카', '교토', '후쿠오카', '삿포로', '오키나와', '해수욕장', '공원', '산', '해변', '타워', '빌리지', '호텔', '리조트', '박물관', '미술관', '사찰', '성당', '시장', '항구', '포구', '카페']):
                    location_str = s
        elif isinstance(obj, list):
            for sub in obj:
                _find_loc(sub)
                if location_str: break

    try:
        if len(item) > 2 and isinstance(item[2], (int, float)) and item[2] > 0:
            ts = item[2] / 1000.0 if item[2] > 10000000000 else float(item[2])
            dt = datetime.datetime.fromtimestamp(ts)
            date_str = f"{dt.year}년 {dt.month}월 {dt.day}일"
            timestamp = ts
        else:
            _find_ts(item)
        _find_loc(item)
    except Exception:
        pass

    return date_str, timestamp, location_str

GPHOTO_FREEZE_SECONDS = 86400  # 24시간 동안은 캐시 DB를 그대로 사용하여 네트워크 낭비 0! ❄️

# ============================================================================
# [TAG: #@midjourney_explore_source] 🎨 미드저니(Midjourney) Explore → 이미지 그룹 가상 앨범 소스
# ----------------------------------------------------------------------------
# [규칙] 사진 dict 를 '구글 포토와 완전히 동일 규격'으로 생산한다.
#        → /media 카드 · 썸네일 · 카운트 · 6~9번 이동/복사/병합 · 13~16번 간격/효과/순서/BGM ·
#          11·12번 웹게시/비밀번호 가 코드 추가 0줄로 그대로 재사용된다. 🛡️
# [규칙] 가상 앨범 키는 photos.app.goo.gl/ 로 시작 → _is_gphoto_url() 이 원래부터 True
#        → 기존 전 소스 분기(카드/카운트/배치갱신/폴더보기 제외)에 자동 편입된다.
#        키 규약:  .../merge_mj_f_<feed>_<hash12>  → ❄️ 고정  (그 시점 스냅샷, 네트워크 0회)
#                 .../merge_mj_a_<feed>_<hash12>  → 🔄 자동  (24h Freeze 지나면 자동 재수집)
# [규칙] 네트워크 실패 시 절대 빈 목록을 돌려주지 않는다 → 마지막 성공 DB 캐시 유지 (V193.4와 동일)
# ----------------------------------------------------------------------------
# [실측] 2026-10-02 · 인증 불필요 공개 API. 필수 헤더 x-csrf-protection: 1 (없으면 401),
#        Cloudflare 는 requests/urllib 을 403 으로 막으므로 curl_cffi TLS 지문(impersonate) 필수.
#        1페이지 50장 · page 0~3 = 200장 풀(page 4+ 빈 배열) · CDN 200/200 200 OK · 핫링크 24/24 성공.
# ============================================================================
MJ_EXPLORE_API = "https://www.midjourney.com/api/explore"
MJ_CDN_ORIGIN = "https://cdn.midjourney.com"
MJ_EXPLORE_PAGES_MAX = 4
MJ_FEED_LABEL = {
    "top": "일간 인기",
    "week": "주간 인기",
    "month": "월간 인기",
    "staff_picks": "스태프 픽",
    "community": "커뮤니티",
}
_MJ_TLS_FINGERPRINTS = ("chrome124", "safari", "chrome120", "chrome110", "chrome")

def _is_midjourney_album_key(path) -> bool:
    """미드저니 가상 앨범 키 판별 (merge_mj_f_ / merge_mj_a_) 🎨"""
    if not isinstance(path, str):
        return False
    return "photos.app.goo.gl/merge_mj_" in path.strip().lower()

def _midjourney_album_spec(clean_url):
    """가상 앨범 키 → (mode, feed, hash) 파싱. mode 'f'=고정 / 'a'=자동"""
    import re as _re
    p = (clean_url or "").lower()
    m = _re.search(r"merge_mj_([fa])_([a-z_]+?)_([0-9a-f]{12})", p)
    if m:
        return m.group(1), m.group(2), m.group(3)
    return ("a" if "merge_mj_a_" in p else "f"), "top", ""

def _midjourney_album_id(clean_url) -> str:
    """DB album_id 컬럼용 대표 키"""
    _, _, h = _midjourney_album_spec(clean_url)
    return f"mj_{h}" if h else "mj"

def _build_midjourney_album_key(mode, feed, seed) -> str:
    """모드/피드/시드로 안정적인 가상 앨범 키 생성 (같은 시드는 같은 키 → 중복 등록 방지)"""
    import hashlib
    h = hashlib.md5(f"mj|{mode}|{feed}|{seed}".encode("utf-8")).hexdigest()[:12]
    return f"https://photos.app.goo.gl/merge_mj_{mode}_{feed}_{h}"

def _fetch_midjourney_explore_items(feed="top", max_pages=MJ_EXPLORE_PAGES_MAX, timeout=30):
    """Midjourney Explore 공개 API 에서 작품 원본 목록 수집 (로그인 불필요) 🎨⚡
    [반환] API 원본 dict 리스트 (id / enqueue_time / width / height / prompt / display_name ...)
    [실패] 빈 리스트 반환 (호출측에서 stale 캐시 유지 판단)"""
    import json as _json

    _req = None
    try:
        from curl_cffi import requests as _req
    except Exception:
        # [규칙] curl_cffi 는 런타임 지연 임포트. 없으면 자동 설치 시도 후 포기(graceful)
        try:
            _auto_install("curl_cffi", "curl_cffi", "스텔스 AI 통신 엔진 (Browser Impersonation)")
            from curl_cffi import requests as _req
        except Exception:
            _req = None
            try: _log_to_file("⚠️ [midjourney] curl_cffi 없음 → 수집 불가")
            except: pass

    if _req is None:
        return []

    headers = {
        "x-csrf-protection": "1",
        "Accept": "*/*",
        "Referer": "https://www.midjourney.com/explore?tab=top",
    }

    items, seen_ids = [], set()
    pages = max(1, min(int(max_pages or 1), MJ_EXPLORE_PAGES_MAX))
    for page in range(pages):
        url = f"{MJ_EXPLORE_API}?page={page}&feed={feed}&_ql=explore"
        payload, last_err, rate_limited = None, "미시도", False
        # 🐾 [BUGFIX] 429 는 TLS 지문과 무관한 '요청 속도 제한'이라 impersonate 를 바꿔도 소용없다.
        #    → 429 는 즉시中断하고 Retry-After 만큼 기다린 뒤 같은 지문으로 재시도한다.
        for attempt in range(1, 4):
            for imp in _MJ_TLS_FINGERPRINTS:
                try:
                    r = _req.get(url, headers=headers, impersonate=imp, timeout=timeout)
                    if r.status_code == 200:
                        payload = _json.loads(r.text)
                        rate_limited = False
                        break
                    last_err = f"HTTP {r.status_code}"
                    if r.status_code == 429:
                        rate_limited = True
                        _retry_after = 0.0
                        try:
                            _retry_after = float(r.headers.get("Retry-After") or 0)
                        except Exception:
                            _retry_after = 0.0
                        break
                except Exception as e:
                    last_err = f"{type(e).__name__}: {e}"
            if payload is not None or not rate_limited:
                break
            if attempt < 3:
                _mj_wait_rate_limit(_retry_after, attempt)
        if payload is None:
            try: _log_to_file(f"⚠️ [midjourney] explore page{page} 수집 실패 ({last_err})")
            except: pass
            break
        if not isinstance(payload, list) or not payload:
            break
        # 🐾 페이지 사이 최소 간격 (MJ rate limit 예방)
        if page < pages - 1:
            import time as _t2
            import random as _r2
            _t2.sleep(_r2.uniform(0.8, 1.6))
        added = 0
        for it in payload:
            if not isinstance(it, dict):
                continue
            jid = it.get("id")
            if not jid or jid in seen_ids:
                continue
            seen_ids.add(jid)
            items.append(it)
            added += 1
        if added == 0:
            break
    return items

def _build_midjourney_photo_dicts(items, album_title, album_key):
    """MJ API 아이템 → 구글 포토와 동일 규격의 photo dict 리스트로 변환 🎨
    [핵심] CDN URL 패턴: {origin}/{job_id}/0_{grid_idx}_{size}_N.webp
           grid_idx = items[] 중 server_filtered==False 칸의 인덱스(0~3)
           size     = 2048(본화) / 384(썸네일)  · base_url 은 '바로 열 수 있는 완전 URL'로 둔다
           (구글포토 전용 '=w1920-h1080' 꼬이는 googleusercontent 판별을 자연스럽게 우회)"""
    import datetime as _dt

    photos, seen_urls = [], set()
    for it in items or []:
        if not isinstance(it, dict):
            continue
        jid = it.get("id")
        if not jid:
            continue
        grid = it.get("items") or []
        gi = 0
        for k, cell in enumerate(grid):
            if isinstance(cell, dict) and not cell.get("server_filtered"):
                gi = k
                break
        else:
            if not grid:
                continue
        full_url = f"{MJ_CDN_ORIGIN}/{jid}/0_{gi}_2048_N.webp"
        thumb_url = f"{MJ_CDN_ORIGIN}/{jid}/0_{gi}_384_N.webp"
        if full_url in seen_urls:
            continue
        seen_urls.add(full_url)

        ts, date_str = 0.0, ""
        et = it.get("enqueue_time")
        if isinstance(et, (int, float)) and et > 0:
            try:
                ts = float(et) / 1000.0
                d = _dt.datetime.fromtimestamp(ts)
                date_str = f"{d.year}년 {d.month}월 {d.day}일"
            except Exception:
                ts, date_str = 0.0, ""

        prompt = ""
        try:
            _dp = (it.get("prompt") or {}).get("decodedPrompt") or []
            if _dp and isinstance(_dp[0], dict):
                prompt = str(_dp[0].get("content") or "")[:400]
        except Exception:
            prompt = ""

        idx = len(photos) + 1
        photos.append({
            'idx': idx - 1,
            'name': f"{album_title} {idx:03d}",
            'filename': f"mj_{idx:03d}.webp",
            'path': full_url,
            'base_url': full_url,
            'url': full_url,
            'thumb': thumb_url,
            'width': it.get('width') or 1024,
            'height': it.get('height') or 1024,
            'is_remote': True,
            'album_url': album_key,
            'origin_url': album_key,
            'is_video': False,
            'duration': 0,
            'date': date_str,
            'timestamp': ts,
            'location': '',   # [규칙] "…에서" 어미가 붙으므로 비워둔다 (배지 문구 오남 방지)
            'mj_id': jid,
            'mj_author': it.get('display_name') or '',
            'mj_prompt': prompt,
        })
    return photos

def _fetch_midjourney_album_photos(clean_url, force_refresh=False):
    """미드저니 가상 앨범 사진 목록 반환 (고정/자동 모드 분기) 🎨❄️🔄
    ❄️ 고정(f): 네트워크 0회 — DB 스냅샷 그대로 반환. force=True 면 '현재 시점의 신규 URL 만 append'(중복 제거)
    🔄 자동(a): 24h Freeze 지나면 자동 재수집(덮어쓰기). force=True 면 즉시 재수집(덮어쓰기)
    [규칙] 실패해도 기존 DB 스냅샷을 절대 버리지 않는다 (빈 목록은 상위 카운트를 0장으로 덮어씀)"""
    import time as _time

    clean_u = _clean_gphoto_url(clean_url)
    mode, feed, _h = _midjourney_album_spec(clean_u)
    now = _time.time()

    db_photos, updated_at, _db_count, db_title = _load_gphoto_from_db(clean_u, with_meta=True)
    db_photos = db_photos or []

    # ❄️ 고정: 강제 갱신이 아니면 DB 스냅샷 즉시 반환 (네트워크 0회)
    if mode == "f" and not force_refresh:
        if db_photos:
            _gphoto_album_cache[clean_u] = (now, db_photos)
        return db_photos

    # 🔄 자동: 24시간 Freeze 안이면 DB 반환
    if mode == "a" and not force_refresh and db_photos and (now - updated_at) < GPHOTO_FREEZE_SECONDS:
        _gphoto_album_cache[clean_u] = (now, db_photos)
        return db_photos

    default_title = f"Midjourney {MJ_FEED_LABEL.get(feed, feed)}"
    album_title = db_title or default_title

    # 🐾 [BUGFIX #2] 재수집 경로도 429 백오프를 반드시 거친다.
    #    예전엔 '앨범 생성' 경로에만 있어서, 자동 모드 24h 갱신이 몰리면 429 를 그대로 삼켰다.
    # 🐛 [BUGFIX #4] 네트워크 라이브러리 예외까지 삼켜야 '직접 호출 경로'(mj_append/mj_refresh)가 죽지 않는다.
    #    예전엔 예외가 그대로 올라와 TUI 서브메뉴가 통째로 종료됐다.
    items = []
    for _attempt in range(1, 4):
        try:
            items = _fetch_midjourney_explore_items(feed=feed)
        except Exception as _e:
            try: _log_to_file(f"⚠️ [midjourney] 재수집 예외: {type(_e).__name__}: {_e}")
            except Exception: pass
            items = []
        if items:
            break
        if _attempt < 3:
            try: _log_to_file(f"🐾 [midjourney] 재수집 429 → {_attempt}회차 유예 후 재시도")
            except Exception: pass
            try:
                _mj_wait_rate_limit(0, _attempt)
            except Exception:
                pass

    try:
        new_photos = _build_midjourney_photo_dicts(items, album_title, clean_u)
    except Exception as _e:
        try: _log_to_file(f"⚠️ [midjourney] photo dict 변환 실패: {type(_e).__name__}: {_e}")
        except Exception: pass
        new_photos = []

    if not new_photos:
        # 🐛 [BUGFIX #3] 절대 빈 목록을 반환하지 않는다. 상위 _count_images_in_folders 가
        #    '0장' 으로 덮어써 버리면 MJ 카드가 통째로 증발한다. (V193.4 와 동일 규칙)
        if db_photos:
            _gphoto_album_cache[clean_u] = (now, db_photos)
            try: _log_to_file(f"⚠️ [midjourney] {clean_u[-28:]} 재수집 실패 → 기존 {len(db_photos)}장 유지")
            except Exception: pass
            return db_photos
        return []

    # ➕ 고정 모드 + 강제 갱신: 기존 스냅샷을 유지한 채 '신규 URL 만' 덧붙인다 (기존 사진 절대 삭제 안 함)
    if mode == "f" and db_photos:
        seen_keys = set()
        for p in db_photos:
            k = p.get('base_url') or p.get('url') or p.get('path')
            if k:
                seen_keys.add(k)
        merged = list(db_photos)
        added = 0
        for p in new_photos:
            k = p.get('base_url') or p.get('url')
            if k and k in seen_keys:
                continue
            if k:
                seen_keys.add(k)
            merged.append(p)
            added += 1
        for i, p in enumerate(merged):
            p['idx'] = i
        _save_gphoto_to_db(clean_u, _midjourney_album_id(clean_u), album_title, merged)
        _gphoto_album_cache[clean_u] = (now, merged)
        try: _log_to_file(f"🎨 [midjourney] 고정앨범 '{album_title}' 신규 {added}장 추가 (누계 {len(merged)}장)")
        except: pass
        return merged

    _save_gphoto_to_db(clean_u, _midjourney_album_id(clean_u), album_title, new_photos)
    _gphoto_album_cache[clean_u] = (now, new_photos)
    try: _log_to_file(f"🎨 [midjourney] '{album_title}' {len(new_photos)}장 저장 (모드={'고정' if mode=='f' else '자동'})")
    except: pass
    return new_photos

def _mj_wait_rate_limit(retry_after=0.0, attempt=0):
    """429(Rate Limit) 회피 대기 — Retry-After 헤더 우선, 없으면 지수 백오프+지터 🐾
    [규칙] MJ 는 짧은 시간에 연속 요청하면 429 를 돌려준다.
           앨범을 '고정+자동' 처럼 연달아 만들 때도 걸리므로 여기서 반드시 속도를 낮춘다."""
    import time as _time
    import random as _rnd
    if retry_after and retry_after > 0:
        wait = min(float(retry_after), 90.0)
    else:
        wait = min(4.0 * (2 ** max(0, attempt - 1)), 45.0) + _rnd.uniform(0.5, 2.0)
    try:
        _log_to_file(f"🐾 [midjourney] rate limit 대기 {wait:.1f}s (attempt={attempt})")
    except Exception:
        pass
    _time.sleep(wait)

def _create_midjourney_image_album(settings, img_groups, group_name, mode, feed="top"):
    """미드저니 가상 앨범을 만들어 현재 이미지 그룹에 등록 (고정/자동 모드 선택) 🎨
    [반환] (성공여부, 메시지)
    [BUGFIX] rate limit(429) 우회를 위해 _mj_wait_rate_limit 을 재시도 루프에 건다. 🐾"""
    import time as _time

    now = _time.time()
    key = _build_midjourney_album_key(mode, feed, f"{now:.0f}")
    print(f"\r\n 🎨 {C.BOLD}{C.SKY}Midjourney Explore 작품 수집 중...{C.RESET}")
    print(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
    print(f"  📡 피드: {C.GOLD}{MJ_FEED_LABEL.get(feed, feed)}{C.RESET}  |  모드: {C.MAGENTA}{'❄️ 고정(그 시점 스냅샷)' if mode == 'f' else '🔄 자동(24시간마다 최신)'}{C.RESET}")
    print(f"  💡 최대 {MJ_EXPLORE_PAGES_MAX * 50}장까지 자동 수집합니다. 잠시만 기다려 주세요...")

    # 🐾 [BUGFIX] '같은 피드를 고정+자동 으로 연달아 만들기' 는 429 를 확실히 유발한다.
    #    → 재시도 루프로 유예 후 재시도하고, 그래도 실패하면 사유를 구분해 안내한다.
    items = []
    for _attempt in range(1, 4):
        items = _fetch_midjourney_explore_items(feed=feed)
        if items:
            break
        if _attempt < 3:
            print(f"    {C.YELLOW}🐾 전송량 제한(429) 감지 → 잠시 대기 후 재시도합니다...{C.RESET}")
            _mj_wait_rate_limit(0, _attempt)
    if not items:
        print(f"\r\n ❌ {C.RED}수집에 실패했어냥! (전송량 제한 또는 Midjourney 차단){C.RESET}")
        print(f"    {C.DIM}잠시(1~2분) 뒤 다시 시도해 주세요. 이미 만든 앨범은 그대로 쓸 수 있어!{C.RESET}")
        return False, "수집 실패 (429 전송량 제한)"

    title = f"Midjourney {MJ_FEED_LABEL.get(feed, feed)}"
    photos = _build_midjourney_photo_dicts(items, title, key)
    if not photos:
        print(f"\r\n ❌ {C.RED}변환된 이미지가 0장이야냥.{C.RESET}")
        return False, "이미지 0장"

    _save_gphoto_to_db(key, _midjourney_album_id(key), title, photos)
    _gphoto_album_cache[key] = (_time.time(), photos)

    folders = list(img_groups.get(group_name, []))
    folders.append(key)
    img_groups[group_name] = folders
    settings.data["playlist_image_groups"] = img_groups
    settings.save()

    mode_txt = "❄️ 고정 (그 시점 사진 고정 · '현재 사진 추가'로 누적 가능)" if mode == "f" else "🔄 자동 (24시간마다 자동 재수집)"
    print(f"\r\n ✅ {C.GREEN}미드저니 앨범이 추가되었어냥!{C.RESET}")
    print(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
    print(f"  📚 제목: {C.SKY}{title}{C.RESET}")
    print(f"  📷 사진: {C.CYAN}{len(photos):,}장{C.RESET}")
    print(f"  ⚙️ 모드: {C.MAGENTA}{mode_txt}{C.RESET}")
    print(f"  🔑 키  : {C.DIM}{key}{C.RESET}")
    return True, f"{len(photos)}장"


# ============================================================================
# [TAG: #@midjourney_local_download] 📥 Midjourney Explore → 로컬 webp 다운로드 (Pixiv 수집기 방식)
# ----------------------------------------------------------------------------
# [규칙] 비뉴는 "URL 앨범(고정/자동)" 과 "로컬 다운로드 폴더" 를 완전히 분리한다.
#        URL 앨범  → temp/gphoto_cache.db + CDN 핫링크 (위 블록)
#        로컬 앨범 → <MJ 폴더>/<피드>/ 아래 webp 파일 (Pixiv 다운로드 폴더와 동일 개념)
# [규칙] 이미 받은 파일은 '파일명 = job_id' 규칙으로 물리적으로 스킵한다 → 장부 DB 불필요, 재수집 0开销
# [규칙] 저장은 '원본 webp' 그대로 (변환 없음). MJ CDN webp 는 전 브라우저/플레이어가 지원한다.
# [규칙] 자동 주기 수집은 MJ rate limit(429) 을 존중해 최소 30분 간격으로만 돈다.
# ----------------------------------------------------------------------------
MJ_DL_DEFAULT_DIRNAME = "Midjourney"
MJ_DL_MIN_INTERVAL_MIN = 30          # 429 예방: 자동 주기 최소 간격(분)
MJ_DL_MAX_WORKERS = 8
_MJ_DL_WATCHDOG_RUNNING = False
_MJ_DL_WATCHDOG_STOP_EVENT = threading.Event()
_MJ_DL_WATCHDOG_THREAD = None
_MJ_DL_LAST_CHECK = ""
_MJ_DL_LAST_COUNT = 0

def get_midjourney_download_dir(settings_data: dict) -> str:
    """Midjourney 다운로드 폴더 경로
    [규칙] 사용자가 직접 지정한 midjourney_download_path 를 최우선으로 쓴다.
           미지정이면 예전처럼 'Pixiv 폴더 아래 Midjourney' 기본값을 쓴다. (하위호환)"""
    custom = ""
    if isinstance(settings_data, dict):
        custom = str(settings_data.get("midjourney_download_path") or "").strip().strip('"')
    # 🐛 [BUGFIX #6] 예전엔 os.path.isdir(custom) 을 먼저 걸어서, '아직 없는 새 폴더'를
    #    지정하면 조용히 기본값으로 떨어졌다. (사용자가 지정했는데 다른 곳에 쌓이는 사고)
    #    → 있으면 쓰고, 없으면 만들며, 실패할 때만 기본값으로 폴백한다.
    if custom:
        try:
            abs_custom = os.path.abspath(os.path.expanduser(custom))
            os.makedirs(abs_custom, exist_ok=True)
            if os.path.isdir(abs_custom):
                return os.path.normpath(abs_custom)
        except Exception as e:
            try: _log_to_file(f"⚠️ [midjourney] 지정 폴더 사용 불가({e}) → 기본값으로 폴백")
            except Exception: pass
    base = get_default_pixiv_dir(settings_data)
    p = os.path.join(base, MJ_DL_DEFAULT_DIRNAME)
    os.makedirs(p, exist_ok=True)
    return os.path.normpath(p)

def get_midjourney_download_dir_display(settings_data: dict) -> str:
    """TUI 표시용 — 사용자 지정 폴더면 '지정됨' 배지, 기본값이면 '(기본)' 표기"""
    custom = ""
    if isinstance(settings_data, dict):
        custom = str(settings_data.get("midjourney_download_path") or "").strip().strip('"')
    return "📂 지정됨" if custom else "📂 기본"

def _mj_dl_fingerprint(feed, job_id, grid_idx):
    """중복 판정용 파일명 (job_id 만으로 충분 — 같은 job 은 같은 image 라는 MJ 규칙)"""
    return f"{job_id}_{grid_idx}.webp"

def _mj_items_from_db_snapshot(feed="top"):
    """🐛 [BUGFIX #5] 이미 만들어둔 '미드저니 URL 앨범' DB 캐시에서 CDN URL 목록을 복구한다.
    [규칙] API(429) 와 CDN 은 서로 다른 호스트다. CDN 은 rate limit 에 걸리지 않으므로
           '목록만 못 받았을 때' 과거에 확보한 URL 로 그대로 다운로드가 가능하다. 🛡️
    [반환] [{id, items:[{server_filtered}]}] 형태 (원본 API 와 동일 구조)"""
    try:
        import sqlite3 as _sq
        import json as _js
        db_path = _get_gphoto_db_path()
        if not os.path.exists(db_path):
            return []
        with _sq.connect(db_path, timeout=5.0) as conn:
            rows = list(conn.execute(
                "SELECT album_url, photos_json FROM gphoto_albums "
                "WHERE album_url LIKE ?", (f"%merge_mj_%_{feed}_%",)))
        out = []
        for _url, pj in rows:
            if not pj:
                continue
            for p in (_js.loads(pj) or []):
                u = p.get('base_url') or p.get('url') or ''
                if 'cdn.midjourney.com' not in u:
                    continue
                # {job_id}/0_{grid}_{size}_N.webp → id/grid 복원
                parts = u.split('/')
                if len(parts) < 2:
                    continue
                jid = parts[-2]
                seg = parts[-1]
                gi = 0
                try:
                    gi = int(seg.split('_')[1])
                except Exception:
                    pass
                out.append({"id": jid,
                            "items": [{"server_filtered": (k != gi)} for k in range(4)]})
        # job_id 중복 제거
        seen, uniq = set(), []
        for it in out:
            if it["id"] in seen:
                continue
            seen.add(it["id"])
            uniq.append(it)
        return uniq
    except Exception:
        return []

def _mj_dl_scan_existing(feed_dir):
    """이미 받은 job_id 집합 복원 (장부 없이 폴더 스캔만으로) — 재수집 시 즉시 스킵"""
    seen = set()
    try:
        for fn in os.listdir(feed_dir):
            if fn.lower().endswith('.webp'):
                seen.add(fn.split('_')[0])
    except Exception:
        pass
    return seen

def _mj_dl_download_one(url, dest_path, headers, timeout=60):
    """단일 webp 다운로드 (임시파일 → 원자적 rename) 🛡️
    [규칙] curl_cffi 를 여기서 lazy import 한다. MJ CDN 은 Cloudflare 이라
           일반 requests/urllib 은 403 으로 막힌다 → TLS 지문(impersonate) 필수."""
    try:
        os.makedirs(os.path.dirname(dest_path), exist_ok=True)
        if os.path.exists(dest_path) and os.path.getsize(dest_path) > 1024:
            return 'skip', 0
        tmp = dest_path + ".part"
        from curl_cffi import requests as _creq
        r = _creq.get(url, headers=headers, impersonate="chrome124", timeout=timeout)
        if r.status_code != 200:
            return 'fail', 0
        data = r.content
        if not data or len(data) < 1024:
            return 'fail', 0
        with open(tmp, "wb") as f:
            f.write(data)
        os.replace(tmp, dest_path)
        return 'ok', len(data)
    except Exception:
        try:
            if os.path.exists(dest_path + ".part"):
                os.remove(dest_path + ".part")
        except Exception:
            pass
        return 'fail', 0

def download_midjourney_feed(feed="top", target_root=None, stop_event=None, progress_cb=None,
                             max_pages=MJ_EXPLORE_PAGES_MAX, quiet=False, settings_data=None):
    """[핵심] MJ Explore 피드를 로컬 webp 로 다운로드 (이미 있는 파일은 스킵) 📥
    [반환] (신규다운로드수, 실패수, 총용량bytes, 폴더경로)
    [BUGFIX #5] 예전엔 목록 수집이 429 면 '조용히 0장 반환' → 사용자는 "다운로드 실패" 를
        이유 없이 마주했다. 이제 (1) DB 스냅샷 URL 로 대체 시도하고 (2) 그래도 실패하면
        구체적 사유를 반환한다. 아무 말 없이 0장 을 돌려주지 않는다. 🛡️"""
    import concurrent.futures as _cf

    if target_root is None:
        # [규칙] stats/폴더열기와 경로가 어긋나면 안 되므로 '단일 진실 공급원'을 쓴다
        target_root = get_midjourney_download_dir(settings_data or {})
    feed_dir = os.path.join(target_root, feed)
    os.makedirs(feed_dir, exist_ok=True)

    items = _fetch_midjourney_explore_items(feed=feed, max_pages=max_pages)
    err_reason = ""
    if not items:
        # 🐛 [BUGFIX #5] 429 로 API 가 막혔어도 '이미 만들어둔 URL 앨범(DB 스냅샷)' 의 CDN 주소로
        #    다운로드할 수 있다. CDN 은 rate limit 대상이 아니고, photo dict 에 url 이 이미 있다.
        items = _mj_items_from_db_snapshot(feed)
        if items:
            err_reason = "API 429(전송량 제한) → 기존 URL 앨범 캐시로 대체 수집"
            try: _log_to_file(f"📥 [midjourney] '{feed}' API 429 → DB 스냅샷 {len(items)}건으로 대체 수집")
            except Exception: pass
        else:
            err_reason = "API 429(전송량 제한) · 로컬 URL 앨범 캐시도 없음"
            if not quiet:
                print(f"\r\n ❌ {C.RED}Midjourney 목록 수집 실패!{C.RESET}")
                print(f"    {C.YELLOW}사유: {err_reason}{C.RESET}")
                print(f"    {C.DIM}💡 해결법: ① 1~2분 뒤 다시 시도  ② /media 이미지 그룹 3번에서"
                      f"'미드저니 Explore 앨범(URL)' 을 한 번 만들어두면{C.RESET}")
                print(f"    {C.DIM}   그 다음부터는 캐시로 다운로드가 가능해. (CDN 은 차단 안 됨){C.RESET}")
            try: _log_to_file(f"⚠️ [midjourney] '{feed}' 목록 수집 실패: {err_reason}")
            except Exception: pass
            return 0, 0, 0, feed_dir

    existing = _mj_dl_scan_existing(feed_dir)
    headers = {"Accept": "image/avif,image/webp,image/*,*/*;q=0.8",
               "Referer": "https://www.midjourney.com/"}
    jobs = []
    for it in items:
        jid = it.get("id")
        if not jid or jid in existing:
            continue
        grid = it.get("items") or []
        gi = 0
        for k, cell in enumerate(grid):
            if isinstance(cell, dict) and not cell.get("server_filtered"):
                gi = k
                break
        fname = _mj_dl_fingerprint(feed, jid, gi)
        if os.path.exists(os.path.join(feed_dir, fname)):
            continue
        jobs.append((f"{MJ_CDN_ORIGIN}/{jid}/0_{gi}_2048_N.webp", os.path.join(feed_dir, fname)))

    if not jobs:
        if not quiet:
            tag = f" {C.YELLOW}({err_reason}){C.RESET}" if err_reason else ""
            print(f"\r\n ✅ {C.GREEN}'{feed}' 피드는 이미 모두 받아놨어! (신규 0장){tag}")
        return 0, 0, 0, feed_dir

    ok_n, fail_n, total_bytes = 0, 0, 0
    total = len(jobs)
    done = 0
    cancelled = False
    with _cf.ThreadPoolExecutor(max_workers=MJ_DL_MAX_WORKERS, thread_name_prefix="MjDl") as ex:
        futs = [ex.submit(_mj_dl_download_one, u, p, headers) for u, p in jobs]
        for fu in _cf.as_completed(futs):
            # 🛑 취소 요청 감지 — 이미 시작된 건 마저 받고, 나머지는 더 받지 않는다
            if stop_event is not None and stop_event.is_set():
                cancelled = True
                for f2 in futs:
                    f2.cancel()
                break
            try:
                st, sz = fu.result()
            except Exception:
                st, sz = 'fail', 0
            done += 1
            if st == 'ok':
                ok_n += 1
                total_bytes += sz
            elif st == 'fail':
                fail_n += 1
            if progress_cb:
                try:
                    progress_cb(done, total, ok_n, fail_n)
                except Exception:
                    pass
            elif not quiet and (done % 20 == 0 or done == total):
                pct = int(done * 100 / total)
                print(f"\r ⬇️ {feed}: {pct}% ({done}/{total}) 성공 {ok_n} / 실패 {fail_n}", end="", flush=True)
    if not quiet:
        print()

    try: _log_to_file(f"📥 [midjourney] '{feed}' 다운로드 완료: 신규 {ok_n}장 / 실패 {fail_n}장"
                      f"{' [취소됨]' if cancelled else ''} → {feed_dir}")
    except Exception:
        pass
    return ok_n, fail_n, total_bytes, feed_dir

def get_midjourney_download_stats(target_root=None):
    """(폴더별 파일수, 총용량) — TUI 상태 표시용
    [규칙] root 미지정 시 get_midjourney_download_dir() 를 그대로 써야 다운로드 경로와 어긋나지 않는다."""
    import glob as _glob
    root = target_root or get_midjourney_download_dir({})
    per_feed, total, total_bytes = {}, 0, 0
    try:
        for d in _glob.glob(os.path.join(root, "*")):
            if not os.path.isdir(d):
                continue
            fs = [f for f in os.listdir(d) if f.lower().endswith(".webp")]
            if not fs:
                continue
            sz = sum(os.path.getsize(os.path.join(d, f)) for f in fs)
            per_feed[os.path.basename(d)] = len(fs)
            total += len(fs)
            total_bytes += sz
    except Exception:
        pass
    return per_feed, total, total_bytes

def start_midjourney_watchdog(settings_ref, send_tg_func=None):
    """[규칙] MJ rate limit 보호 — 최소 30분 간격으로만 수집한다"""
    global _MJ_DL_WATCHDOG_RUNNING, _MJ_DL_WATCHDOG_THREAD, _MJ_DL_WATCHDOG_STOP_EVENT
    if _MJ_DL_WATCHDOG_RUNNING and _MJ_DL_WATCHDOG_THREAD and _MJ_DL_WATCHDOG_THREAD.is_alive():
        return False
    _MJ_DL_WATCHDOG_STOP_EVENT.clear()
    _MJ_DL_WATCHDOG_RUNNING = True

    def _worker():
        global _MJ_DL_WATCHDOG_RUNNING, _MJ_DL_LAST_CHECK, _MJ_DL_LAST_COUNT
        while not _MJ_DL_WATCHDOG_STOP_EVENT.is_set():
            data = getattr(settings_ref, 'data', {}) or {}
            enabled = bool(data.get("midjourney_auto_dl", False))
            feeds = data.get("midjourney_dl_feeds") or ["top"]
            interval = max(MJ_DL_MIN_INTERVAL_MIN, int(data.get("midjourney_dl_interval_min", 180) or 180))
            if not enabled:
                if _MJ_DL_WATCHDOG_STOP_EVENT.wait(timeout=15):
                    break
                continue
            _MJ_DL_LAST_CHECK = datetime.now().strftime("%H:%M:%S")
            root = get_midjourney_download_dir(data)
            added_total = 0
            for fd in feeds:
                if _MJ_DL_WATCHDOG_STOP_EVENT.is_set():
                    break
                try:
                    a, _f, _b, _d = download_midjourney_feed(feed=fd, target_root=root, quiet=True)
                    added_total += a
                except Exception as e:
                    try: _log_to_file(f"⚠️ [midjourney watchdog] '{fd}' 실패: {e}")
                    except Exception: pass
                # [규칙] 429 예방 — 피드 사이에 최소 45초 간격
                if _MJ_DL_WATCHDOG_STOP_EVENT.wait(timeout=45):
                    break
            _MJ_DL_LAST_COUNT = added_total
            if added_total > 0 and callable(send_tg_func):
                try:
                    send_tg_func(
                        f"🎨 <b>[Midjourney] 새 작품 {added_total}장</b> 다운로드 완료했어! 📥✨\r\n"
                        f"📂 폴더: <code>{root}</code>", category="info")
                except Exception:
                    pass
            for _ in range(max(1, interval) * 6):
                if _MJ_DL_WATCHDOG_STOP_EVENT.wait(timeout=10):
                    break
        _MJ_DL_WATCHDOG_RUNNING = False

    _MJ_DL_WATCHDOG_THREAD = threading.Thread(target=_worker, name="MidjourneyWatchdog", daemon=True)
    _MJ_DL_WATCHDOG_THREAD.start()
    return True

def stop_midjourney_watchdog():
    global _MJ_DL_WATCHDOG_RUNNING
    _MJ_DL_WATCHDOG_STOP_EVENT.set()
    _MJ_DL_WATCHDOG_RUNNING = False

def is_midjourney_watchdog_active() -> bool:
    return _MJ_DL_WATCHDOG_RUNNING and _MJ_DL_WATCHDOG_THREAD is not None and _MJ_DL_WATCHDOG_THREAD.is_alive()

def get_midjourney_watchdog_status_str() -> str:
    global _MJ_DL_LAST_CHECK, _MJ_DL_LAST_COUNT
    if not is_midjourney_watchdog_active():
        return "⚫ OFF"
    if _MJ_DL_LAST_CHECK:
        return f"🟢 ON (최근: {_MJ_DL_LAST_CHECK} · +{_MJ_DL_LAST_COUNT}장)"
    return "🟢 ON"


# ============================================================================
# [TAG: #@midjourney_bg_download] ⏳ Midjourney 백그라운드 다운로드 (Pixiv 큐 엔진과 동일 구조)
# ----------------------------------------------------------------------------
# [규칙] '지금 즉시 다운로드' 는 TUI 를 블로킹하지 않는다 → 큐에 넣고 즉시 메뉴로 돌아온다. 🚀
#        Pixiv 의 _PIXIV_BG_JOB_QUEUE / _pixiv_bg_enqueue_job 과 1:1 로 같은 형태를 쓴다.
# [규칙] 취소는 "이미 받아둔 파일은 남기고 미다운로드만 중단" 으로 동작한다 (부분 파일 .part 자동 정리)
# [규칙] 완료 시 텔레그램 알림은 '다운로드 폴더를 바꿔도' 계속 동작해야 하므로
#        폴더 경로를 스레드 진입 시점에 스냅샷해서 쓴다 (실행 중 설정 변경과 race 방지)
# ----------------------------------------------------------------------------
_MJ_DL_BG_RUNNING = False
_MJ_DL_BG_STATUS = ""
_MJ_DL_BG_STOP_EVENT = threading.Event()
_MJ_DL_BG_CANCEL_REQUESTED = threading.Event()
_MJ_DL_BG_JOB_QUEUE = deque()
_MJ_DL_BG_JOB_LOCK = threading.Lock()
_MJ_DL_BG_QUEUE_THREAD = None
_MJ_DL_BG_LAST_RESULT = None
_MJ_DL_BG_DONE = threading.Event()      # 테스트/대기용 완료 신호

def is_midjourney_bg_downloading() -> bool:
    """실행 중 + 대기 큐 포함 (Pixiv 와 동일 판정)"""
    if _MJ_DL_BG_RUNNING:
        return True
    with _MJ_DL_BG_JOB_LOCK:
        return bool(_MJ_DL_BG_JOB_QUEUE)

def get_midjourney_bg_download_status_str() -> str:
    global _MJ_DL_BG_STATUS
    if not is_midjourney_bg_downloading():
        return ""
    qn = 0
    with _MJ_DL_BG_JOB_LOCK:
        qn = len(_MJ_DL_BG_JOB_QUEUE)
    base = _MJ_DL_BG_STATUS or "⏳ 백그라운드 다운로드 중..."
    return f"{base} (대기 {qn})" if qn else base

def get_midjourney_bg_last_result():
    return _MJ_DL_BG_LAST_RESULT

def stop_midjourney_bg_downloads():
    """백그라운드 다운로드 중지 + 대기 큐 비우기 (정리된 대기 작업 수 반환)"""
    global _MJ_DL_BG_STATUS
    with _MJ_DL_BG_JOB_LOCK:
        stopped = len(_MJ_DL_BG_JOB_QUEUE)
        _MJ_DL_BG_JOB_QUEUE.clear()
    _MJ_DL_BG_CANCEL_REQUESTED.set()
    _MJ_DL_BG_STOP_EVENT.set()
    _MJ_DL_BG_STATUS = "🛑 취소 요청됨... 다운로드 중지 중..."
    return stopped

def _mj_dl_bg_queue_worker():
    """큐 작업을 순차 실행하는 워커 스레드 (Pixiv _pixiv_bg_queue_worker 와 동일 형태)"""
    global _MJ_DL_BG_RUNNING, _MJ_DL_BG_STATUS, _MJ_DL_BG_QUEUE_THREAD
    try:
        while True:
            with _MJ_DL_BG_JOB_LOCK:
                if not _MJ_DL_BG_JOB_QUEUE:
                    _MJ_DL_BG_QUEUE_THREAD = None
                    return
                job = _MJ_DL_BG_JOB_QUEUE.popleft()
            try:
                _MJ_DL_BG_STOP_EVENT.clear()
                _MJ_DL_BG_RUNNING = True
                _MJ_DL_BG_STATUS = job["status"]
                if _MJ_DL_BG_CANCEL_REQUESTED.is_set():
                    _MJ_DL_BG_STATUS = "⏹ 취소됨"
                    continue
                job["fn"]()
            except Exception as e:
                global _MJ_DL_BG_LAST_RESULT
                _MJ_DL_BG_LAST_RESULT = {"new_cnt": 0, "fail": 0, "err": str(e),
                                         "time": datetime.now().strftime("%H:%M:%S")}
            finally:
                _MJ_DL_BG_RUNNING = False
                _MJ_DL_BG_STATUS = ""
    finally:
        _MJ_DL_BG_QUEUE_THREAD = None
        _MJ_DL_BG_DONE.set()

def _mj_dl_bg_enqueue_job(status_msg, job_fn):
    """백그라운드 작업을 큐에 추가 (이미 진행 중이어도 줄서서 순차 실행)"""
    global _MJ_DL_BG_QUEUE_THREAD
    need_start = False
    with _MJ_DL_BG_JOB_LOCK:
        was_empty = not _MJ_DL_BG_JOB_QUEUE
        _MJ_DL_BG_JOB_QUEUE.append({"status": status_msg, "fn": job_fn})
        if was_empty:
            _MJ_DL_BG_CANCEL_REQUESTED.clear()
        if not _MJ_DL_BG_QUEUE_THREAD or not _MJ_DL_BG_QUEUE_THREAD.is_alive():
            _MJ_DL_BG_QUEUE_THREAD = threading.Thread(target=_mj_dl_bg_queue_worker,
                                                      name="MjDlBgQueueThread", daemon=True)
            need_start = True
    if need_start:
        _MJ_DL_BG_QUEUE_THREAD.start()

def start_midjourney_bg_download(settings_ref, send_tg_func=None, feeds=None):
    """[핵심] MJ 인기작 다운로드를 '백그라운드 큐'로 즉시 시작 (TUI 블로킹 없음) 🚀
    [반환] (성공여부, 안내문구)"""
    global _MJ_DL_BG_LAST_RESULT
    data = getattr(settings_ref, 'data', {}) or {}
    tg_func = _get_telegram_func(send_tg_func)
    targets = list(feeds or data.get("midjourney_dl_feeds") or ["top"])
    if not targets:
        return False, "수집할 피드가 없습니다. 먼저 '수집할 피드 선택' 을 해주세요!"

    # [규칙] 실행 중 설정이 바뀌어도 폴더/피드는 스냅샷으로 고정 (race 방지)
    root_snapshot = get_midjourney_download_dir(data)
    tg_on = bool(data.get("midjourney_dl_tg_noti", True))
    was_running = is_midjourney_bg_downloading()
    _MJ_DL_BG_DONE.clear()

    label = ", ".join(MJ_FEED_LABEL.get(f, f) for f in targets)

    def _bg_worker():
        global _MJ_DL_BG_STATUS, _MJ_DL_BG_LAST_RESULT
        total_new = total_fail = 0
        errs = []
        try:
            for i, fd in enumerate(targets, 1):
                if _MJ_DL_BG_STOP_EVENT.is_set():
                    break
                _MJ_DL_BG_STATUS = f"⏳ {MJ_FEED_LABEL.get(fd, fd)} 수집·다운로드 중... ({i}/{len(targets)})"

                def _cb(done, total, ok, fail, _fd=fd):
                    pct = int(done * 100 / total) if total else 100
                    _MJ_DL_BG_STATUS = f"⏳ {_fd} {pct}% ({done}/{total}) 성공 {ok} · 실패 {fail}"

                a, f_cnt, _b, _d = download_midjourney_feed(
                    feed=fd, target_root=root_snapshot,
                    stop_event=_MJ_DL_BG_STOP_EVENT,
                    progress_cb=_cb, quiet=True)
                total_new += a
                total_fail += f_cnt
                if a == 0 and f_cnt == 0:
                    errs.append(f"{MJ_FEED_LABEL.get(fd, fd)}: 수집 실패(429/차단)")
                # [규칙] 429 예방 — 피드 사이 최소 45초
                if i < len(targets):
                    for _ in range(45):
                        if _MJ_DL_BG_STOP_EVENT.wait(timeout=1):
                            break

            cancelled = _MJ_DL_BG_STOP_EVENT.is_set()
            _MJ_DL_BG_LAST_RESULT = {
                "new_cnt": total_new, "fail": total_fail,
                "err": "; ".join(errs) if errs else "",
                "time": datetime.now().strftime("%H:%M:%S"),
                "cancelled": cancelled, "feeds": targets, "dir": root_snapshot,
            }
            if tg_on and callable(tg_func):
                try:
                    if cancelled:
                        msg = (f"⛔ <b>[Midjourney] 백그라운드 다운로드 중단!</b>\r\n"
                               f"취소 시점까지 받은 파일: <b>{total_new}장</b>\r\n"
                               f"📂 <code>{root_snapshot}</code>")
                    else:
                        msg = (f"🎨 <b>[Midjourney] 백그라운드 다운로드 완료!</b>\r\n"
                               f"대상: <b>{label}</b>\r\n"
                               f"새로 받은 작품: <b>{total_new}장</b>"
                               + (f" (실패 {total_fail}장)" if total_fail else "") + " 🚀✨\r\n"
                               f"📂 <code>{root_snapshot}</code>")
                    if errs:
                        msg += "\r\n⚠️ <i>" + "; ".join(errs)[:200] + "</i>"
                    tg_func(msg, category="info")
                except Exception:
                    pass
        except Exception as e:
            _MJ_DL_BG_LAST_RESULT = {"new_cnt": total_new, "fail": total_fail,
                                     "err": str(e), "time": datetime.now().strftime("%H:%M:%S")}

    _mj_dl_bg_enqueue_job(f"⏳ {label} 백그라운드 다운로드 대기 중...", _bg_worker)
    return True, ("다른 작업이 진행 중이라 뒤에 줄섰어!" if was_running else "백그라운드로 시작했어!")

def _mj_register_local_folder_as_image_group(settings_ref, folder_path, group_name=None):
    """[규칙] 다운로드된 로컬 폴더를 '이미지 그룹 소스'로 등록한다.
        → /media 전자액자가 MJ 를 로컬 파일로 재생하므로 네트워크 0회, 로딩 즉시, 삭제도 자유롭다. 🛡️
    [반환] (성공여부, 그룹명)"""
    img_groups = settings_ref.data.setdefault("playlist_image_groups", {})
    if not group_name:
        base = os.path.basename(folder_path.rstrip("\\/")) or "미드저니"
        group_name = base
    # 이름 충돌 시 접미사
    if group_name in img_groups:
        i = 2
        while f"{group_name} ({i})" in img_groups:
            i += 1
        group_name = f"{group_name} ({i})"
    cur = list(img_groups.get(group_name, []))
    if folder_path not in cur:
        cur.append(folder_path)
    img_groups[group_name] = cur
    settings_ref.data["playlist_image_groups"] = img_groups
    settings_ref.save()
    return True, group_name

def ui_midjourney_download_menu(settings_ref, send_tg_func=None):
    """[TAG: #@midjourney_local_download] 🎨 Midjourney 로컬 다운로드 대화형 메뉴
    [규칙] URL 가상 앨범(고정/자동) 과 완전 분리. 여기는 '로컬 파일'만 다룬다."""
    FEEDS = ["top", "week", "month", "staff_picks"]
    while True:
        clear_console()
        root = get_midjourney_download_dir(settings_ref.data)
        per_feed, total, total_bytes = get_midjourney_download_stats()
        size_txt = (f"{total_bytes / (1024 ** 3):.2f}GB" if total_bytes >= 1024 ** 3
                    else f"{total_bytes / (1024 ** 2):.1f}MB")
        enabled = bool(settings_ref.data.get("midjourney_auto_dl", False))
        interval = int(settings_ref.data.get("midjourney_dl_interval_min", 180) or 180)
        cur_feeds = settings_ref.data.get("midjourney_dl_feeds") or ["top"]

        print(f"\r\n 🎨 {C.BOLD}{C.SKY}Midjourney 인기작 로컬 다운로드{C.RESET}")
        print(" " + "─" * 58)
        print(f"  📂 저장 폴더: {C.SKY}{root}{C.RESET} {get_midjourney_download_dir_display(settings_ref.data)}")
        print(f"  📊 누적: {C.GREEN}{total:,}장{C.RESET} · {C.GOLD}{size_txt}{C.RESET}")
        if per_feed:
            parts = [f"{MJ_FEED_LABEL.get(k, k)} {v:,}장" for k, v in sorted(per_feed.items())]
            print(f"  🗂️ 피드별: {C.CYAN}{' / '.join(parts)}{C.RESET}")
        print(f"  ⏱️ 자동 수집: {C.GREEN + '🟢 ON' + C.RESET if enabled else C.DIM + '⚫ OFF' + C.RESET} · {interval}분 주기 (최소 {MJ_DL_MIN_INTERVAL_MIN}분)")
        print(f"  📡 워커: {get_midjourney_watchdog_status_str()}")
        print(" " + "─" * 58)
        print(f"  {C.DIM}💡 이미 받은 파일은 자동으로 건너뛰어. 중복 다운로드 없음!{C.RESET}")

        bg_st = get_midjourney_bg_download_status_str()
        bg_badge = f" {C.YELLOW}⏳[진행중]{C.RESET}" if bg_st else ""
        with _MJ_DL_BG_JOB_LOCK:
            _qn = len(_MJ_DL_BG_JOB_QUEUE)
        # [규칙] 취소 메뉴 번호를 하드코딩하지 말고 목록에서 직접 찾는다 (삽입 시 자동 반영)
        _stop_label = " 🛑 백그라운드 다운로드 취소"
        _stop_no = 9  # 아래 목록의 bg_stop 위치(1-based)
        cancel_hint = f" {C.YELLOW}({_stop_no}번으로 취소 가능){C.RESET}" if (bg_st or _qn) else ""
        mj_menu = [
            {"label": f" 📥 지금 즉시 다운로드 (선택한 피드, 신규분만){bg_badge}", "key": "dl_now"},
            {"label": f" 📊 백그라운드 다운로드 상태 확인{cancel_hint}", "key": "bg_status"},
            {"label": f" 🎯 수집할 피드 선택 [현재: {', '.join(MJ_FEED_LABEL.get(f, f) for f in cur_feeds)}]", "key": "pick_feeds"},
            {"label": f" 📂 다운로드 폴더 지정 [현재: {get_midjourney_download_dir_display(settings_ref.data)}]", "key": "set_dir"},
            {"label": f" ⏱️ 자동 주기 수집 {'켜기' if not enabled else '끄기'}", "key": "toggle_auto"},
            {"label": f" 🕒 자동 주기 간격 설정 [현재: {interval}분]", "key": "set_interval"},
            {"label": " 📂 다운로드 폴더 열기", "key": "open_dir"},
            {"label": " 🖼️ 누적 폴더를 이미지 그룹(앨범)으로 등록 → /media", "key": "as_album"},
            {"label": f"{_stop_label}{cancel_hint}", "key": "bg_stop"},
            {"label": " ❌ 이전 메뉴로 돌아가기", "key": "back"},
        ]
        _stop_no = next((i + 1 for i, o in enumerate(mj_menu) if o["key"] == "bg_stop"), 0)
        sel, *_ = _interactive_menu("🎨 Midjourney 로컬 다운로드", [o["label"] for o in mj_menu], timeout=0)
        if sel < 0 or sel >= len(mj_menu):
            break
        key = mj_menu[sel]["key"]
        if key == "back":
            break

        elif key == "dl_now":
            # [규칙] TUI 를 블로킹하지 않는다 → 백그라운드 큐로 던지고 즉시 메뉴로 복귀 (Pixiv 와 동일)
            feeds = settings_ref.data.get("midjourney_dl_feeds") or ["top"]
            ok, msg = start_midjourney_bg_download(settings_ref, send_tg_func, feeds=feeds)
            if ok:
                label = ", ".join(MJ_FEED_LABEL.get(f, f) for f in feeds)
                print(f"\r\n 🚀 {C.GREEN}백그라운드 다운로드 시작!{C.RESET} ({label})")
                print(f"    {C.DIM}{msg}{C.RESET}")
                print(f"    {C.DIM}📂 {root}{C.RESET}")
                print(f"    {C.DIM}💡 메뉴를 계속 써도 돼. 완료 시 텔레그램으로 알려줄게!{C.RESET}")
            else:
                print(f"\r\n ❌ {C.RED}{msg}{C.RESET}")
            time.sleep(2.2)

        elif key == "bg_status":
            res = get_midjourney_bg_last_result()
            st = get_midjourney_bg_download_status_str()
            if st:
                print(f"\r\n ⏳ {C.YELLOW}진행 중...{C.RESET} {st}")
            else:
                print(f"\r\n 😴 {C.DIM}백그라운드 다운로드 작업 없음{C.RESET}")
            if res:
                print(f"    📥 최근 결과: 신규 {C.GREEN}{res.get('new_cnt', 0)}장{C.RESET}"
                      f" · 실패 {C.YELLOW}{res.get('fail', 0)}장{C.RESET}"
                      f" · {C.DIM}{res.get('time', '')}{C.RESET}")
                if res.get('cancelled'):
                    print(f"    {C.YELLOW}⛔ 취소됨{C.RESET}")
                if res.get('err'):
                    print(f"    ⚠️ {C.YELLOW}{res['err']}{C.RESET}")
            qn = 0
            with _MJ_DL_BG_JOB_LOCK:
                qn = len(_MJ_DL_BG_JOB_QUEUE)
            print(f"    📋 대기 큐: {qn}건")
            time.sleep(2.5)

        elif key == "bg_stop":
            n = stop_midjourney_bg_downloads()
            print(f"\r\n 🛑 {C.YELLOW}취소 요청! 대기 {n}건 정리 · 이미 받은 파일은 유지돼.{C.RESET}")
            time.sleep(2.2)

        elif key == "set_dir":
            print(f"\r\n 📂 {C.BOLD}{C.SKY}다운로드 폴더 지정{C.RESET}")
            print(" " + "─" * 58)
            print(f"  현재: {C.SKY}{root}{C.RESET}")
            print(f"  {C.DIM}· 빈칸(Enter) → 기본값으로 되돌리기{C.RESET}")
            print(f"  {C.DIM}· 주소 직접 입력 → 글자를 붙여넣어도 돼{C.RESET}")
            print(f"  {C.DIM}· 예) D:\\midjourney  또는  G:\\AI\\Midjourney{C.RESET}")
            print(" " + "─" * 58)
            raw = prompt_input(f"\r\n 👉 새 폴더 경로 [기본값 되돌리려면 Enter]: ").strip().strip('"')
            if not raw:
                settings_ref.data.pop("midjourney_download_path", None)
                settings_ref.save()
                print(f"\r\n ✅ {C.GREEN}기본값으로 되돌렸어: {get_midjourney_download_dir(settings_ref.data)}{C.RESET}")
                time.sleep(2.2)
                continue
            try:
                abs_p = os.path.abspath(os.path.expanduser(raw))
                os.makedirs(abs_p, exist_ok=True)
                if not os.path.isdir(abs_p):
                    raise OSError("폴더가 아니야")
                # 이미 쓰던 폴더였는지 확인 (중복 다운로드 방지 안내)
                prev_root = get_midjourney_download_dir(settings_ref.data)
                if os.path.normpath(prev_root) != os.path.normpath(abs_p):
                    _pf, _pt, _ = get_midjourney_download_stats(target_root=prev_root)
                    if _pt > 0:
                        print(f"\r\n {C.YELLOW}⚠️ 기존 폴더에 {_pt}장이 있어. 이대로 옮기면 '중복 판정'이 깨질 수 있어!{C.RESET}")
                        print(f"    {C.DIM}기존 폴더: {prev_root}{C.RESET}")
                        ans = prompt_input(f"\r\n  그래도 지정할까? (y/N): ").strip().lower()
                        if ans not in ('y', 'yes'):
                            print(f"\r\n ↩️ {C.DIM}취소했어.{C.RESET}")
                            time.sleep(1.5)
                            continue
                settings_ref.data["midjourney_download_path"] = abs_p
                settings_ref.save()
                print(f"\r\n ✅ {C.GREEN}다운로드 폴더 지정 완료!{C.RESET}")
                print(f"    {C.SKY}{abs_p}{C.RESET}")
            except Exception as e:
                print(f"\r\n ❌ {C.RED}폴더를 만들지 못했어: {e}{C.RESET}")
            time.sleep(2.2)

        elif key == "pick_feeds":
            fopts = [f" {'✅ ' if f in cur_feeds else '   '}{MJ_FEED_LABEL.get(f, f)}" for f in FEEDS]
            fsel, *_ = _interactive_menu("수집할 피드 선택 (멀티 선택 · Enter 확정)", fopts, allow_multi=True, timeout=0)
            if not isinstance(fsel, list):
                continue
            picked = [FEEDS[i] for i in fsel if 0 <= i < len(FEEDS)]
            if not picked:
                print(f"\r\n ⚠️ {C.YELLOW}피드를 1개 이상 선택해줘!{C.RESET}")
                time.sleep(1.5)
                continue
            settings_ref.data["midjourney_dl_feeds"] = picked
            settings_ref.save()
            print(f"\r\n ✅ {C.GREEN}수집 피드 설정: {', '.join(MJ_FEED_LABEL.get(f, f) for f in picked)}{C.RESET}")
            time.sleep(1.5)

        elif key == "toggle_auto":
            settings_ref.data["midjourney_auto_dl"] = not enabled
            settings_ref.save()
            if not enabled:
                start_midjourney_watchdog(settings_ref, send_tg_func)
                print(f"\r\n 🟢 {C.GREEN}자동 주기 수집을 켰어! ({interval}분 주기){C.RESET}")
            else:
                stop_midjourney_watchdog()
                print(f"\r\n ⚫ {C.YELLOW}자동 주기 수집을 껐어!{C.RESET}")
            time.sleep(1.6)

        elif key == "set_interval":
            raw = prompt_input(f"\r\n ⏱️ 수집 주기(분, 최소 {MJ_DL_MIN_INTERVAL_MIN}) [현재 {interval}]: ").strip()
            if raw:
                try:
                    v = max(MJ_DL_MIN_INTERVAL_MIN, int(float(raw)))
                    settings_ref.data["midjourney_dl_interval_min"] = v
                    settings_ref.save()
                    print(f"\r\n ✅ {C.GREEN}주기 {v}분으로 설정했어!{C.RESET}")
                except Exception:
                    print(f"\r\n ❌ {C.RED}숫자가 아니야!{C.RESET}")
            time.sleep(1.5)

        elif key == "open_dir":
            try:
                if os.name == 'nt':
                    os.startfile(root)
                else:
                    import subprocess
                    subprocess.Popen(["xdg-open", root])
            except Exception as e:
                print(f"\r\n ❌ {C.RED}폴더를 열지 못했어: {e}{C.RESET}")
            time.sleep(1.0)

        elif key == "as_album":
            if not per_feed:
                print(f"\r\n ⚠️ {C.YELLOW}아직 다운로드된 사진이 없어!{C.RESET}")
                time.sleep(1.6)
                continue
            sub = [f" {MJ_FEED_LABEL.get(k, k)} · {v:,}장" for k, v in sorted(per_feed.items())]
            ssel, *_ = _interactive_menu("어느 폴더를 앨범(로컬)으로 등록할까?", sub, timeout=0)
            keys = sorted(per_feed.keys())
            if ssel < 0 or ssel >= len(keys):
                continue
            chosen = keys[ssel]
            fpath = os.path.join(root, chosen)
            ok, gname = _mj_register_local_folder_as_image_group(settings_ref, fpath)
            if ok:
                print(f"\r\n ✅ {C.GREEN}'{gname}' 이미지 그룹으로 등록했어!{C.RESET}")
                print(f"    {C.DIM}/media 에서 '{gname}' 카드가 보인다. 클릭하면 바로 슬라이드쇼!{C.RESET}")
                print(f"    {C.DIM}📂 {fpath}{C.RESET}")
            time.sleep(2.5)

def _fetch_gphoto_album_photos(album_url: str, force_refresh: bool = False):
    """구글 포토 공유 앨범 URL에서 전체 이미지 목록 파싱 및 temp/gphoto_cache.db 영구 캐싱 📸⚡ (24시간 Freeze 및 경량 메타 변경 감지 지원)"""
    import urllib.request
    import urllib.parse
    import re
    import time
    import json
    
    clean_url = _clean_gphoto_url(album_url)
    if not clean_url:
        return []
    
    now = time.time()
    # 1. 인메모리 캐시 확인 (1시간 유효, 강제 갱신 아닐 때)
    if not force_refresh and clean_url in _gphoto_album_cache:
        cached_time, cached_photos = _gphoto_album_cache[clean_url]
        if now - cached_time < 3600 and cached_photos:
            return cached_photos

    # 2. SQLite DB 캐시 및 24시간 Freeze 확인 ❄️
    db_photos, updated_at, db_count, db_title = (None, 0.0, 0, "")
    # 🎨 [MJ] 미드저니 가상 앨범은 '고정/자동' 모드별로 동작이 갈리므로 아래 merge_ 일반 처리보다 앞에서 분기한다.
    #    (자동 모드만 24h Freeze 를 보고 재수집하고, 고정 모드는 DB 스냅샷만 쓴다 → /media 배치갱신이 자동 감지)
    if _is_midjourney_album_key(clean_url):
        try:
            return _fetch_midjourney_album_photos(clean_url, force_refresh)
        except Exception as _mj_err:
            try: _log_to_file(f"⚠️ [midjourney] {clean_url[-32:]} 처리 실패: {_mj_err}")
            except: pass
            # 🐛 [BUGFIX] 예외 시 '빈 목록'을 주면 상위 카운트가 0장으로 덮여 카드가 죽는다 → 마지막 캐시 유지
            return _load_gphoto_from_db(clean_url) or []
    if '/merge_' in clean_url:
        # 짬뽕 가상 통합 앨범은 외부 구글 네트워크가 없으므로 DB 캐시를 즉시 반환 📦✨
        db_photos = _load_gphoto_from_db(clean_url)
        if db_photos:
            _gphoto_album_cache[clean_url] = (now, db_photos)
            return db_photos
    elif not force_refresh:
        db_photos, updated_at, db_count, db_title = _load_gphoto_from_db(clean_url, with_meta=True)
        if db_photos:
            # 마지막 갱신/확인 후 24시간(86400초) 이내라면 네트워크 요청 0회! 0.001초 컷 Freeze 반환 🚀
            if (now - updated_at) < GPHOTO_FREEZE_SECONDS:
                _gphoto_album_cache[clean_url] = (now, db_photos)
                return db_photos

    req = urllib.request.Request(
        clean_url,
        headers={
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36',
            'Accept-Language': 'ko-KR,ko;q=0.9,en-US;q=0.8,en;q=0.7'
        }
    )
    
    photos = []
    seen = set()
    try:
        with urllib.request.urlopen(req, timeout=20) as response:
            final_url = response.geturl()
            html = response.read().decode('utf-8', errors='ignore')
    except Exception as _net_err:
        # [V193.4] 🛡️ 네트워크가 안 되면 '빈 목록'을 돌려주지 않는다.
        #   빈 목록을 주면 상위(카운트/이미지 그룹/플리 갱신)이 그 앨범을 '0장'으로 덮어써 버린다.
        #   → 마지막으로 성공한 DB 캐시를 그대로 반환한다. (24h Freeze 만료 직후가 가장 위험) 🐾
        _stale = None
        try:
            _stale = _load_gphoto_from_db(clean_url, with_meta=True)[0]
        except Exception:
            pass
        if _stale:
            _gphoto_album_cache[clean_url] = (now, _stale)
            _log_to_file(f"⚠️ [gphoto] '{clean_url[:48]}' 네트워크 실패({type(_net_err).__name__}) → 기존 캐시 {len(_stale)}장 유지")
            return _stale
        _log_to_file(f"⚠️ [gphoto] '{clean_url[:48]}' 네트워크 실패({type(_net_err).__name__}) → 캐시도 없어 빈 목록")
        return []

    try:
        # 앨범 ID 및 공유 키 파싱
        album_id = ""
        share_key = ""
        m_url = re.search(r'/share/([^/?#]+)', final_url)
        if m_url:
            album_id = m_url.group(1)
        m_key = re.search(r'[?&]key=([^&#]+)', final_url)
        if m_key:
            share_key = m_key.group(1)

        # batchexecute 필수 세션 정보 파싱
        bl_m = re.search(r'\"cfb2h\":\"([^\"]+)\"', html)
        bl = bl_m.group(1) if bl_m else "boq_photosuiserver_20260909.07_p0"
        fdr_m = re.search(r'\"FdrFJe\":\"([^\"]+)\"', html)
        fsid = fdr_m.group(1) if fdr_m else ""
            
        # 앨범 제목 추출 (og:title 또는 <title>)
        album_title = ""
        title_m = re.search(r'<meta\s+property=[\"\']og:title[\"\']\s+content=[\"\']([^\"\']+)[\"\']', html, re.IGNORECASE)
        if not title_m:
            title_m = re.search(r'<title>([^<]+)</title>', html, re.IGNORECASE)
        if title_m:
            album_title = title_m.group(1).replace('- Google 포토', '').replace('- Google Photos', '').strip()
        if not album_title:
            album_title = db_title or "구글 포토"

        next_token = None

        # 1차 파싱: HTML 내 ds:1 데이터 블록에서 300장 및 continuation token 추출
        m_ds1 = re.search(r"AF_initDataCallback\(\{[^\}]*key:\s*'ds:1'[^\}]*data:\s*(\[.*?\])\s*,\s*sideChannel:", html, re.DOTALL)
        if not m_ds1:
            m_ds1 = re.search(r"AF_initDataCallback\(\{[^\}]*key:\s*'ds:1'[^\}]*data:\s*(\[.*\])\s*\}", html, re.DOTALL)

        raw_items = []
        if m_ds1:
            try:
                init_data = json.loads(m_ds1.group(1))
                raw_items = init_data[1] if len(init_data) > 1 and isinstance(init_data[1], list) else []
                next_token = init_data[2] if len(init_data) > 2 and isinstance(init_data[2], str) else None
            except Exception as e:
                try: _log_to_file(f"⚠️ [_fetch_gphoto_album_photos ds:1 parse error] {e}")
                except: pass

        # 🔍 [스마트 Freeze 검사] 강제 갱신이 아니고 기존 DB 캐시가 있는 경우: 최신 사진 변동 확인! (크롤링 방지) 🛡️
        if not force_refresh and db_photos and raw_items:
            first_raw_url = None
            if isinstance(raw_items[0], list) and len(raw_items[0]) > 1 and isinstance(raw_items[0][1], list) and raw_items[0][1]:
                first_raw_url = raw_items[0][1][0] if isinstance(raw_items[0][1][0], str) else None
            cached_first_url = db_photos[0].get('base_url') or db_photos[0].get('path')
            
            is_unchanged = False
            if first_raw_url and cached_first_url:
                # 첫 번째 사진 URL 일치 여부 확인 (도메인/옵션 차이 대비 고유 미디어 키 비교 지원)
                first_key = first_raw_url.split('.googleusercontent.com')[-1].split('=')[0] if '.googleusercontent.com' in first_raw_url else first_raw_url
                cached_key = cached_first_url.split('.googleusercontent.com')[-1].split('=')[0] if '.googleusercontent.com' in cached_first_url else cached_first_url
                if (first_raw_url == cached_first_url) or (first_key and cached_key and first_key == cached_key) or (first_raw_url in cached_first_url) or (cached_first_url in first_raw_url):
                    if not next_token:
                        is_unchanged = (len(raw_items) == len(db_photos))
                    else:
                        is_unchanged = True

            if is_unchanged:
                # 사진 증가/변동 없음! 24시간 Freeze 연장 후 기존 캐시 즉시 반환 ❄️
                _touch_gphoto_db_updated_at(clean_url)
                _gphoto_album_cache[clean_url] = (now, db_photos)
                return db_photos

        # 🚀 사진 변동 감지 또는 강제 갱신: 첫 페이지 300장 파싱 진행!
        if raw_items:
            for item in raw_items:
                if isinstance(item, list) and len(item) > 1 and isinstance(item[1], list):
                    info = item[1]
                    base_url = info[0] if len(info) > 0 else None
                    w = info[1] if len(info) > 1 and isinstance(info[1], int) else 1920
                    h = info[2] if len(info) > 2 and isinstance(info[2], int) else 1080
                    if base_url and isinstance(base_url, str) and base_url.startswith('http') and base_url not in seen:
                        seen.add(base_url)
                        idx = len(photos) + 1
                        is_vid, dur = _extract_gphoto_media_info(item)
                        d_str, ts_val, loc_val = _extract_gphoto_item_meta(item)
                        photos.append({
                            'idx': idx - 1,
                            'name': f"{album_title} {idx:03d}",
                            'filename': f"gphoto_{idx:03d}.jpg",
                            'path': base_url,
                            'base_url': base_url,
                            'url': f"{base_url}=w1920-h1080",
                            'thumb': f"{base_url}=w400-h400-c",
                            'width': w,
                            'height': h,
                            'is_remote': True,
                            'album_url': clean_url,
                            'origin_url': clean_url,
                            'is_video': is_vid,
                            'duration': dur,
                            'date': d_str,
                            'timestamp': ts_val,
                            'location': loc_val
                        })


        # 2차: ds:1 추출 실패 시 기존 정규식 패턴 폴백
        if not photos:
            pattern_dim = re.compile(r'\[\"(https://lh[0-9]\.googleusercontent\.com/(?:pw/)?[a-zA-Z0-9\-_]+)\",(\d+),(\d+)\]')
            for match in pattern_dim.finditer(html):
                base_url = match.group(1)
                w = int(match.group(2))
                h = int(match.group(3))
                if w >= 300 and h >= 300 and base_url not in seen:
                    seen.add(base_url)
                    idx = len(photos) + 1
                    photos.append({
                        'idx': idx - 1,
                        'name': f"{album_title} {idx:03d}",
                        'filename': f"gphoto_{idx:03d}.jpg",
                        'path': base_url,
                        'base_url': base_url,
                        'url': f"{base_url}=w1920-h1080",
                        'thumb': f"{base_url}=w400-h400-c",
                        'width': w,
                        'height': h,
                        'is_remote': True,
                        'album_url': clean_url,
                        'origin_url': clean_url,
                        'date': '',
                        'timestamp': 0.0,
                        'location': ''
                    })

        # 3단계: Continuation Token이 있으면 batchexecute RPC(snAcKc)로 다음 페이지들 연속 수집 🔄
        # [V193.4] 🛡️ 페이지 상한: Google 가 잘못된 토큰을 주면 next_token 이 끝없이 돌아올 수 있다.
        #   실측 1페이지 = 300장이고 DB 총 7만장 규모라 정상 앨범은 수십 회면 끝난다.
        #   50회(≈15,000장) 를 넘으면 정상 앨범이 절대 못 미치는 수치이므로 상한으로 끊는다. 🚀
        GPHOTO_MAX_PAGES = 50
        page = 1
        if next_token and album_id:
            print(f"\r  📸 구글 포토 [{album_title}] 전체 사진 수집 중... ({len(photos)}장)", end="", flush=True)

        while next_token and album_id:
            page += 1
            if page > GPHOTO_MAX_PAGES:
                _log_to_file(f"⚠️ [gphoto] '{album_title}' 페이지 {GPHOTO_MAX_PAGES}회 상한 도달 — 다음 토큰 무시하고 수집 종료")
                break
            params = {
                'rpcids': 'snAcKc',
                'source-path': f'/share/{album_id}',
                'bl': bl,
                'f.sid': fsid,
                'hl': 'ko',
                '_reqid': str(100000 + page),
                'rt': 'c'
            }
            batch_url = "https://photos.google.com/_/PhotosUi/data/batchexecute?" + urllib.parse.urlencode(params)
            req_payload = [album_id, next_token, None, share_key]
            envelope = [[["snAcKc", json.dumps(req_payload), None, "generic"]]]
            post_body = urllib.parse.urlencode({"f.req": json.dumps(envelope)}).encode('utf-8')

            headers = {
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36',
                'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8',
                'Referer': final_url
            }

            try:
                batch_req = urllib.request.Request(batch_url, data=post_body, headers=headers, method='POST')
                with urllib.request.urlopen(batch_req, timeout=20) as resp:
                    res_text = resp.read().decode('utf-8', errors='ignore')

                batch_items = []
                new_token = None
                for line in res_text.split('\n'):
                    line = line.strip()
                    if not line or line.isdigit() or line.startswith(")]}'"):
                        continue
                    try:
                        arr = json.loads(line)
                        if isinstance(arr, list):
                            for chunk in arr:
                                if len(chunk) > 2 and chunk[1] == 'snAcKc':
                                    inner = json.loads(chunk[2])
                                    if len(inner) > 1 and isinstance(inner[1], list):
                                        batch_items = inner[1]
                                    if len(inner) > 2 and isinstance(inner[2], str):
                                        new_token = inner[2]
                    except Exception:
                        pass

                if not batch_items:
                    break

                for item in batch_items:
                    if isinstance(item, list) and len(item) > 1 and isinstance(item[1], list):
                        info = item[1]
                        base_url = info[0] if len(info) > 0 else None
                        w = info[1] if len(info) > 1 and isinstance(info[1], int) else 1920
                        h = info[2] if len(info) > 2 and isinstance(info[2], int) else 1080
                        if base_url and isinstance(base_url, str) and base_url.startswith('http') and base_url not in seen:
                            seen.add(base_url)
                            idx = len(photos) + 1
                            is_vid, dur = _extract_gphoto_media_info(item)
                            d_str, ts_val, loc_val = _extract_gphoto_item_meta(item)
                            photos.append({
                                'idx': idx - 1,
                                'name': f"{album_title} {idx:03d}",
                                'filename': f"gphoto_{idx:03d}.jpg",
                                'path': base_url,
                                'base_url': base_url,
                                'url': f"{base_url}=w1920-h1080",
                                'thumb': f"{base_url}=w400-h400-c",
                                'width': w,
                                'height': h,
                                'is_remote': True,
                                'album_url': clean_url,
                                'origin_url': clean_url,
                                'is_video': is_vid,
                                'duration': dur,
                                'date': d_str,
                                'timestamp': ts_val,
                                'location': loc_val
                            })

                print(f"\r  📸 구글 포토 [{album_title}] 전체 사진 수집 중... ({len(photos)}장)", end="", flush=True)
                next_token = new_token
                time.sleep(0.1)  # 서버 부하 방지용 짧은 딜레이

            except Exception as e:
                try: _log_to_file(f"⚠️ [_fetch_gphoto_album_photos pagination error at page {page}] {e}")
                except: pass
                break

        if photos:
            if page > 1:
                print(f"\r  ✅ 구글 포토 [{album_title}] 총 {len(photos)}장 수집 완료! 💾 (temp/gphoto_cache.db 저장)")
            _save_gphoto_to_db(clean_url, album_id, album_title, photos)
            _gphoto_album_cache[clean_url] = (now, photos)
            
    except Exception as e:
        try: _log_to_file(f"⚠️ [_fetch_gphoto_album_photos Error] {e}")
        except: pass

    return photos

def _get_image_files_in_folders(folders, recursive=True, max_files=None):
    """지정된 폴더 목록에서 지원하는 이미지 + 동영상 파일 경로 반환 (고속 스캔 & 중복 제거) 🖼️🎬

    [변경] Pixiv 우고이라 MP4 도 슬라이드에 함께 편입시킨다.
           영상은 is_video=True 로 표시되어 플레이어의 <video> 요소로 재생된다.
           (재생시간은 서버에서 ffprobe 로 뽑지 않고 브라우저가 직접 읽는다 — 247개 영상 스캔 지연 방지)
    [성능 최적화] max_files 지정 시 해당 개수 도달 시 즉시 탐색 중단 (10000개 이내 초고속 로딩) ⚡🚀
    """
    image_files = []
    seen = set()
    for fld in folders:
        if not fld:
            continue
        # 구글 포토 URL은 별도 처리 대상이므로 건너뜀
        if _is_gphoto_url(fld):
            continue
        if not os.path.exists(fld):
            continue
        if max_files and len(image_files) >= max_files:
            break
        try:
            if recursive:
                # ⚠️ [BUGFIX] os.walk 는 오류를 기본적으로 조용히 삼킨다.
                #    부분 스캔 상태로 그대로 쓰면 "재생할 파일이 없습니다" 로 이어지므로
                #    오류를 감지해 사용자에게 알 수 있게 로그로 남긴다.
                _walk_err = []
                for root, _, files in os.walk(fld, onerror=lambda e: _walk_err.append(e)):
                    for fn in files:
                        ext = os.path.splitext(fn)[1].lower()
                        if ext in FOTOO_MEDIA_EXTENSIONS:
                            full_path = os.path.normpath(os.path.join(root, fn))
                            if full_path not in seen:
                                seen.add(full_path)
                                image_files.append(full_path)
                                if max_files and len(image_files) >= max_files:
                                    break
                    if max_files and len(image_files) >= max_files:
                        break
                if _walk_err:
                    try:
                        _log_to_file(f"⚠️ [_get_image_files_in_folders 부분 스캔] {fld} 오류 {len(_walk_err)}건 (일부 파일만 수집됨)")
                    except Exception:
                        pass
            else:
                for fn in os.listdir(fld):
                    ext = os.path.splitext(fn)[1].lower()
                    if ext in FOTOO_MEDIA_EXTENSIONS:
                        full_path = os.path.normpath(os.path.join(fld, fn))
                        if os.path.isfile(full_path) and full_path not in seen:
                            seen.add(full_path)
                            image_files.append(full_path)
                            if max_files and len(image_files) >= max_files:
                                break
        except Exception as e:
            try: _log_to_file(f"⚠️ [_get_image_files_in_folders Error] {e}")
            except: pass
    return image_files

def _flush_console_input_buffer():
    """프롬프트 입력 후 콘솔 입력 버퍼에 남은 잔여 입력을 비운다 🧹✨
    [규칙] prompt_input() 은 input() 기반이라 '여러 줄 붙여넣기' 하면 2줄째 이후가
           콘솔 버퍼에 그대로 남는다. 그 잔여 문자가 다음 _interactive_menu() 의 키입력으로
           먹히면 숫자 키가 즉시 실행되어 [🗑️ 그룹 삭제] 같은 위험 메뉴가 임의로 눌릴 수 있다. 🛑
           → 여러 줄 입력은 반드시 클립보드 경로(멀티라인 정상 처리)로 안내한다.
    """
    try:
        if os.name != 'nt':
            return
        import ctypes as _ct
        _ct.windll.kernel32.FlushConsoleInputBuffer(_ct.windll.kernel32.GetStdHandle(-10))
    except Exception:
        pass

def _batch_add_gphoto_albums(group_name, settings, folders, img_groups):
    """구글 포토 공유 앨범 URL 등록 공통 플로우 (초간결 UX & 자동 재활용) 🔗✨
    동작:
        1) 클립보드에 링크가 있으면 1번 안내 후 사용 여부 확인
        2) 직접 입력 시 줄바꿈/공백/쉼표 구분 다중 URL 자동 파싱
        3) 주소가 2개 이상이면 즉시 질문:
           - 🗂️ 각각 앨범 올리기 (앨범별로 새 카드 각각 생성)
           - 📦 하나의 소스로 합쳐서 올리기 (현재 카드 1장에 모두 묶기)
        4) 이미 등록/캐시된 앨범은 캐시 즉시 재활용 (네트워크 낭비 방지 ♻️)
        5) 저장 완료 후 명확한 안내
    """
    R = C.RESET
    print(f"\r\n 🔗 {C.SKY}구글 포토 앨범 공유 링크를 입력해줘!{R}")
    print(f"    {C.DIM}(예: https://photos.app.goo.gl/xxxx 또는 https://photos.google.com/share/...){R}")
    print(f"    {C.GOLD}✨ 여러 개는 한 번에 붙여넣어도 돼! (줄바꿈 / 공백 / 쉼표 모두 지원){R}")

    # 1) 클립보드 자동 감지
    try:
        clip_txt = _get_gphotos_clipboard_text() or ""
    except Exception:
        clip_txt = ""
    clip_urls = _parse_gphoto_url_tokens(clip_txt) if clip_txt else []

    raw_text = ""
    if clip_urls:
        print(f"\r\n 📋 {C.GREEN}클립보드에서 구글 포토 앨범 {len(clip_urls)}개를 감지했어!{R}")
        for _cu in clip_urls[:5]:
            print(f"    · {C.DIM}{_cu}{R}")
        if len(clip_urls) > 5:
            print(f"    · {C.DIM}… 외 {len(clip_urls) - 5}개 더{R}")
        clip_opts = [
            f" ✅ 클립보드의 {len(clip_urls)}개 앨범 사용하기",
            " ✍️ 직접 새로 입력하기",
            " ❌ 취소"
        ]
        c_sel, _, *_ = _interactive_menu("클립보드의 앨범들을 사용할까냥?", clip_opts)
        if c_sel == 0:
            raw_text = "\n".join(clip_urls)
        elif c_sel == 2 or c_sel < 0:
            return (0, 0)

    if not raw_text:
        raw_text = prompt_input(
            f"\r\n 👉 {C.BOLD}공유 URL (여러 개면 복사한 여러 줄 그대로 붙여넣기):{R} "
        ).strip()
        _flush_console_input_buffer()

    if not raw_text:
        print(f" ⚠️ {C.YELLOW}입력이 취소되었어냥.{R}")
        time.sleep(1)
        return (0, 0)

    # 2) URL 파싱
    input_urls = _parse_gphoto_url_tokens(raw_text)
    if not input_urls:
        print(f"\r\n ⚠️ {C.RED}올바른 구글 포토 공유 앨범 URL 형식이 아니야냥!{R}")
        print(f"    {C.YELLOW}구글 포토에서 [공유] -> [링크 만들기]로 생성된 링크를 넣어줘.{R}")
        time.sleep(2)
        return (0, 0)

    num_urls = len(input_urls)
    is_individual = False

    # 3) 주소가 2개 이상이면 즉시 물어보기! (잡다한 질의 전면 생략) 👈✨
    if num_urls >= 2:
        mode_opts = [
            f" 📦 하나의 앨범으로 묶기 (이 앨범들의 사진들을 짬뽕해 1개 단일 앨범으로 등록 ✨)",
            f" 🗂️ 각각 앨범 올리기 (앨범별로 각각 새 카드 {num_urls}장 만들기)",
            " ❌ 취소"
        ]
        m_sel, _, *_ = _interactive_menu(
            f"❓ 구글 포토 앨범 {num_urls}개를 어떻게 올릴까냥?", mode_opts
        )
        if isinstance(m_sel, list):
            m_sel = m_sel[0] if m_sel else -1
        if m_sel < 0 or m_sel == 2:
            print(f"\r\n ⚠️ {C.YELLOW}등록이 취소되었어냥.{R}")
            time.sleep(1)
            return (0, 0)
        is_individual = (m_sel == 1)

    # 4) 앨범별 사진 확인 및 캐시 수집 (이미 등록/캐시된 앨범은 즉시 재활용) ♻️⚡
    print(f"\r\n 🔍 {C.SKY}구글 포토 앨범 {num_urls}개의 사진 정보를 확인하고 있어냥...{R}")
    total_photos = 0
    failed_count = 0
    album_info_list = []  # [(clean_u, title, count)]

    for _i, raw_u in enumerate(input_urls, 1):
        clean_u = _clean_gphoto_url(raw_u)
        _t, _c = _get_gphoto_cached_info(clean_u)
        if _c and _c > 0:
            # 캐시가 이미 존재함 -> 0초 만에 즉시 재활용! ♻️
            total_photos += _c
            print(f" [{_i}/{num_urls}] ♻️  {C.BOLD}{_t or clean_u}{R} · 이미 캐시된 앨범 ({_c:,}장 즉시 재사용)")
            album_info_list.append((clean_u, _t, _c))
            try: sys.stdout.flush()
            except Exception: pass
            continue

        # 캐시가 없으면 수집 진행
        print(f" [{_i}/{num_urls}] 📸 {C.BOLD}{clean_u}{R}")
        try:
            scanned = _fetch_gphoto_album_photos(clean_u, force_refresh=True)
        except Exception as fe:
            try: _log_to_file(f"⚠️ [batch gphoto fetch error] {clean_u}: {fe}")
            except Exception: pass
            scanned = []

        if scanned:
            _t, _c = _get_gphoto_cached_info(clean_u)
            _cnt = len(scanned)
            total_photos += _cnt
            album_info_list.append((clean_u, _t, _cnt))
            print(f"      ✅ {C.GREEN}{_t or '제목 미상'}{R} · {_cnt:,}장 캐시 저장 완료! 💾")
        else:
            failed_count += 1
            album_info_list.append((clean_u, "", 0))
            print(f"      ⚠️ {C.YELLOW}사진 즉시 확인 실패 — 링크는 등록할게냥! (재생 시 재시도){R}")
        try: sys.stdout.flush()
        except Exception: pass

    # 5) 등록 및 저장 처리
    img_groups_curr = settings.data.get("playlist_image_groups", {})

    if is_individual:
        # A. 각각 앨범 올리기: 앨범별로 새 카드(그룹) 생성 🗂️
        created_cards = []
        for clean_u, _title, _cnt in album_info_list:
            cname = (_title or "").strip()
            if not cname or cname.lower() in ("구글 포토", "google photos"):
                cname = f"구글포토_{clean_u.rsplit('/', 1)[-1][:8]}"

            # 중복 그룹명 방지 고유화
            final_name = cname
            dup_idx = 2
            while final_name in img_groups_curr and clean_u not in img_groups_curr[final_name]:
                final_name = f"{cname} ({dup_idx})"
                dup_idx += 1

            if final_name not in img_groups_curr:
                img_groups_curr[final_name] = [clean_u]
            else:
                if clean_u not in img_groups_curr[final_name]:
                    img_groups_curr[final_name].append(clean_u)
            created_cards.append((final_name, _cnt))

        settings.data["playlist_image_groups"] = img_groups_curr
        settings.save()

        print(f"\r\n 🎉 {C.GREEN}구글 포토 앨범 {len(album_info_list)}개를 각각 새 카드로 등록 완료했어! 🗂️✨{R}")
        for cname, _cnt in created_cards[:8]:
            _cnt_txt = f" ({_cnt:,}장)" if _cnt else ""
            print(f"    🖼️ 새 카드: {C.SKY}'{cname}'{R}{_cnt_txt}")
        if len(created_cards) > 8:
            print(f"    … 외 {len(created_cards) - 8}개 더")
        print(f"    ✨ /media 에서 각 앨범이 개별 카드로 슬라이드쇼 재생돼냥!")
        return (len(album_info_list), 0)

    else:
        # B. 하나의 앨범으로 묶기 (짬뽕 단일 앨범 만들기) 📦✨
        # 그룹을 새로 만드는 게 아니라, 현재 '{group_name}' 이미지 그룹 안에서
        # 여러 개로 쪼개진 구글 앨범들의 사진들을 1개의 단일 통합 앨범으로 DB에 병합하여 1개 소스로 등록!
        candidate_titles = [t for _, t, _ in album_info_list if t and t.lower() not in ("구글 포토", "google photos")]
        default_unified_name = ""
        if candidate_titles:
            base_cand = re.sub(r'[\s\-_]*(?:\(?part\s*\d+\)?|\(?파트\s*\d+\)?|\d+|[①-⑳]+)$', '', candidate_titles[0], flags=re.IGNORECASE).strip()
            default_unified_name = base_cand or candidate_titles[0]
        if not default_unified_name:
            default_unified_name = "구글포토_통합앨범"

        # 사용자에게 단일 앨범 제목 확인
        print(f"\r\n 📝 {C.SKY}이 {len(album_info_list)}개 앨범을 하나로 묶을 '통합 앨범 제목'을 입력해줘!{R}")
        print(f"    {C.DIM}(그대로 엔터 치면 '{default_unified_name}'(으)로 묶여냥){R}")
        user_name_inp = prompt_input(f" 👉 {C.BOLD}통합 앨범 제목 [{default_unified_name}]:{R} ").strip()
        _flush_console_input_buffer()
        final_album_title = user_name_inp or default_unified_name

        # 모든 앨범의 사진들을 순서대로 합치기 (사진 URL 기준 중복 제거)
        merged_photos = []
        seen_photo_urls = set()
        for clean_u, _, _ in album_info_list:
            pts = _load_gphoto_from_db(clean_u)
            if not pts:
                try: pts = _fetch_gphoto_album_photos(clean_u)
                except Exception: pts = []
            for p in (pts or []):
                p_key = p.get('base_url') or p.get('url') or p.get('path')
                if p_key and p_key in seen_photo_urls:
                    continue
                if p_key:
                    seen_photo_urls.add(p_key)
                merged_photos.append(p)

        # 짬뽕 통합 앨범용 고유 대표 키 생성 (기존 개별 앨범과 별도로 공존할 수 있도록 고유 URL 키 발급)
        # 예: https://photos.app.goo.gl/merge_<hash>
        import hashlib
        u_hash = hashlib.md5("".join(sorted(u for u, _, _ in album_info_list)).encode('utf-8')).hexdigest()[:12]
        primary_url = f"https://photos.app.goo.gl/merge_{u_hash}"

        # 통합된 사진들로 DB의 gphoto_albums 에 신규 저장! (기존 개별 앨범 데이터 절대 훼손 안 됨)
        _save_gphoto_to_db(primary_url, f"merge_{u_hash}", final_album_title, merged_photos)
        _gphoto_album_cache[primary_url] = (time.time(), merged_photos)

        # 현재 이미지 그룹(group_name)의 folders 에 새 짬뽕 앨범 추가! (기존 앨범 삭제 절대 없음 🛡️)
        curr_folders = img_groups_curr.get(group_name, folders)
        if primary_url not in curr_folders:
            curr_folders.append(primary_url)

        img_groups_curr[group_name] = curr_folders
        settings.data["playlist_image_groups"] = img_groups_curr
        settings.save()

        print(f"\r\n 🎉 {C.GREEN}구글 포토 앨범 {len(album_info_list)}개를 '{final_album_title}' 1개 앨범으로 짬뽕 통합 완료! 📦✨{R}")
        print(f"    📚 총 합산 사진 수: {C.CYAN}{len(merged_photos):,}장{R}")
        print(f"    🛡️ 기존 등록된 앨범들은 그대로 보존되고, 새 짬뽕 앨범이 1개 추가되었어냥! 👍")
        return (1, 0)

def _count_images_in_folders(folders):
    """폴더 및 구글 포토/드라이브 목록의 총 이미지 파일 개수 계산 (캐시 적용으로 초고속) ⚡"""
    total = 0
    for fld in folders:
        if not fld:
            continue
        # 1. 구글 포토 공유 앨범
        if _is_gphoto_url(fld):
            _cnt = _get_gphoto_cached_count(fld)
            if _cnt is not None and _cnt > 0:
                total += _cnt
            else:
                try:
                    pts = _fetch_gphoto_album_photos(fld)
                    total += len(pts) if pts else 1
                except Exception:
                    total += 1
            continue

        # 2. 구글 드라이브 가상 폴더
        if isinstance(fld, str) and fld.startswith("gdrive://"):
            try:
                _u = fld[9:]
                acct, rpath = _u.split('/', 1) if '/' in _u else (_u, "")
                _, g_files = _gdrive_manager('list', account=acct, rpath=rpath)
                total += sum(1 for gf in g_files if any(gf.get('Name', '').lower().endswith(ext) for ext in IMAGE_EXTENSIONS))
            except Exception:
                pass
            continue

        # 3. 로컬 폴더
        if not os.path.exists(fld):
            continue
        try:
            mtime = os.path.getmtime(fld)
            cached = _image_count_cache.get(fld)
            if cached and cached[0] == mtime:
                total += cached[1]
                continue

            # ⚠️ [BUGFIX] os.walk 는 오류를 기본적으로 '조용히 삼킨다'(onerror=None).
            #    그 상태로 부분 스캔된 count(예: 1)를 그대로 캐시에 박아버리면,
            #    폴더 mtime 가 안 바뀌는 한 이후 모든 화면에서 그 잘못된 개수가 영구 고정된다.
            #    (실증: pix.auto 가 23,498장 이어야 하는데 '1장' 으로 표시됨)
            #    → 오류 발생 여부를 감지하고, 깨끗하게 끝난 경우에만 캐시에 기록한다.
            walk_failed = []
            count = 0
            for root, _, files in os.walk(fld, onerror=lambda e: walk_failed.append(e)):
                for fn in files:
                    ext = os.path.splitext(fn)[1].lower()
                    if ext in FOTOO_MEDIA_EXTENSIONS:
                        count += 1

            if walk_failed or count <= 0:
                # 스캔이 온전하지 않으면 캐시에 넣지 않는다 → 다음 요청에서 재시도
                total += count
            else:
                _image_count_cache[fld] = (mtime, count)
                total += count
        except Exception:
            pass
    return total

# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
# 🎨 [Pixiv 원본 역추적 엔진] 다운로드된 사진 → 원작 게시물(artworks) URL 복원
# ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
# 📁 폴더구조 : G:\pixiv\{작가폴더명}\{illust_id}_p{page}.{ext}
# 📄 파일구조 : "[작가명] {illust_id}_p{page}.{ext}"   ← gallery-dl 기본 파일명 템플릿
#    (pixiv_manager.py가 쓰는 기본값: "[{user[name]|user[account]}] {id}_p{num}.{extension}")
# 💡 두 구조(폴더명 + 파일명)를 역산하면 원본 게시물 URL을 100% 복원할 수 있다!
#    → 슬라이드쇼 감상 중 "이 사진 원본 보기" 한 번으로 피시브 작품 페이지로 바로 점프! 🚀
# ────────────────────────────────────────────────────────────────────
# ⚠️ Pixiv 일련번호(illust_id)는 최근 연도 기준 9~10자리이며, 6~11자리 구간으로 안전 매칭한다.
#    (12자리까지 허용하면 "20240101120000_p1.jpg" 같은 날짜파일명을 오탐할 수 있어 제외)
_PIXIV_ILLUST_RE = re.compile(r'(?<!\d)(\d{6,11})_p(\d+)(?!\d)')
# 📂 파일명 앞단 "[작가명] " 접두사에서 작가명을 뽑아내는 패턴 (gallery-dl artist 태그)
_PIXIV_ARTIST_PREFIX_RE = re.compile(r'^\s*[\[\(【]([^\]\)】]{1,60})[\]\)】]')

def _pixiv_normalize_artist_key(name):
    """작가명 정규화 키 생성 (대소문자/공백/특수문자 무시하고 비교) 🔤"""
    if not name:
        return ""
    s = str(name).strip().lower()
    # 특수문자 제거 후 비교 (예: "makfaL AI" ↔ "makfal_ai")
    s = re.sub(r'[\s_\-\.]+', '', s)
    return s

def _build_pixiv_artist_map(settings_obj=None):
    """등록된 Pixiv 작가 목록 → {정규화명: {...}} 매핑 생성 (작가 프로필 페이지 역링크용) 🗂️
    📌 메뉴 17(🎯 수동 등록 작가)의 '작가 폴더명' ↔ settings.pixiv_custom_artists 'name'을 매칭한다."""
    amap = {}
    try:
        data = getattr(settings_obj, 'data', None) if settings_obj is not None else None
        if data is None:
            try:
                so = SettingsManager(SETTINGS_FILE); so.load(); data = so.data
            except Exception:
                data = {}
        artists = (data or {}).get("pixiv_custom_artists", []) or []
        for a in artists:
            if not isinstance(a, dict):
                continue
            aid = str(a.get("id") or "").strip()
            if not aid:
                continue
            info = {'id': aid, 'name': a.get('name') or '', 'account': a.get('account') or ''}
            for k in (info['name'], info['account']):
                nk = _pixiv_normalize_artist_key(k)
                if nk:
                    amap.setdefault(nk, info)
    except Exception as e:
        try: _log_to_file(f"⚠️ [_build_pixiv_artist_map Error] {e}")
        except: pass
    return amap

def _pixiv_origin_from_path(file_path, artist_map=None, root_path=None):
    """다운로드된 사진 1장 → 원작 Pixiv 게시물 정보 역산 🔍🎨
    :param file_path: 로컬 경로 또는 gdrive:// 가상 경로
    :param artist_map: _build_pixiv_artist_map() 결과 (작가 폴더명 → 작가 ID)
    :param root_path: 등록된 사진 소스 루트 (이 폴더명은 작가명이 아니므로 제외)
    :return: dict 또는 None (역추적 실패 시 None)
        {'illust_id','page','artist','artist_id','artwork_url','user_url'}"""
    if not file_path or not isinstance(file_path, str):
        return None
    try:
        # gdrive://acct/rpath/xxx.png → 경로만 떼서 동일한 규칙 적용 ☁️
        _p = file_path[9:] if file_path.startswith("gdrive://") else file_path
        _p = _p.replace('/', os.sep).replace('\\', os.sep) if os.sep != '/' else _p.replace('\\', '/')
        bn = os.path.basename(_p)
        stem = os.path.splitext(bn)[0]
        if not stem:
            return None

        m = _PIXIV_ILLUST_RE.search(stem)
        if not m:
            return None
        illust_id = m.group(1)
        page = int(m.group(2))

        # 1) 파일명 접두사 "[작가명] " 우선 사용
        artist = ''
        pm = _PIXIV_ARTIST_PREFIX_RE.match(stem)
        if pm:
            artist = pm.group(1).strip()
        # 2) 없으면 부모 폴더명 사용 (G:\pixiv\{작가폴더명}\xxx_p0.png 형태)
        if not artist:
            _dir = os.path.dirname(_p)
            parent = os.path.basename(_dir).strip() if _dir else ''
            # 🛡️ 등록 소스 루트 그 자체(G:\pixiv 등)는 작가명이 아니므로 제외
            _root_base = ''
            if root_path:
                _r = root_path[9:] if str(root_path).startswith("gdrive://") else str(root_path)
                _r = _r.replace('\\', os.sep) if os.sep != '/' else _r
                _root_base = os.path.basename(str(_r).rstrip('/\\') or '').strip().lower()
            # 드라이브 루트(G:\)나 빈 경로도 작가명으로 쓰지 않는다 🚫
            if parent and not re.fullmatch(r'[A-Za-z]:', parent) and _dir.strip(os.sep) \
               and parent.lower() != _root_base:
                artist = parent

        artist_id = ''
        user_url = ''
        if artist_map:
            info = artist_map.get(_pixiv_normalize_artist_key(artist))
            if info:
                artist_id = info.get('id', '')
                if not artist:
                    artist = info.get('name', '') or info.get('account', '')
                if artist_id:
                    user_url = f"https://www.pixiv.net/users/{artist_id}"

        return {
            'illust_id': illust_id,
            'page': page,
            'artist': artist,
            'artist_id': artist_id,
            'artwork_url': f"https://www.pixiv.net/artworks/{illust_id}",
            'user_url': user_url
        }
    except Exception as e:
        try: _log_to_file(f"⚠️ [_pixiv_origin_from_path Error] {e}")
        except: pass
        return None

def _attach_pixiv_origin(photo_entry, file_path, artist_map=None, root_path=None):
    """사진 메타 dict에 Pixiv 원본 역추적 정보를 부착 (실패 시 dict 그대로 반환) 🔗"""
    if not isinstance(photo_entry, dict):
        return photo_entry
    info = _pixiv_origin_from_path(file_path, artist_map, root_path)
    if not info:
        return photo_entry
    photo_entry['origin_url'] = info['artwork_url']
    photo_entry['origin_id'] = info['illust_id']
    photo_entry['origin_page'] = info['page']
    if info['artist']:
        photo_entry['origin_artist'] = info['artist']
    if info['user_url']:
        photo_entry['origin_user_url'] = info['user_url']
    return photo_entry

# [TAG: #@_conn_engine]
# ==============================================================================
# 🖥️ [접속·액션 카드 엔진] /media 카드 → 앱 내부 액션 즉시 실행 / 웹 SSH 터미널 연결 🎛️✨
#   - 카드 데이터는 settings.json 의 "playlist_conn_groups" 에 저장된다.
#   - 'action' 카드 : mode="run"   → 무질문(headless) 내부 액션 즉시 실행
#                     mode="focus" → 앱 TUI를 해당 메뉴로 점프시켜 눈으로 확인 진행
#   - 'ssh'/'web'/'rdp'/'vnc' 카드 : 외부 접속 → 웹 터미널 / 새 창 / 외부 실행
# ==============================================================================

# 🗂️ 접속 카드 유형별 메타 (라벨/기본 아이콘)
_CONN_TYPE_META = {
    "action": {"label": "⚡ 앱 내부 액션", "icon": "⚡", "color": "#f59e0b"},
    "ssh":    {"label": "🖥️ SSH 원격 셸",  "icon": "🖥️", "color": "#0ea5e9"},
    "rdp":    {"label": "🖥️ 원격 데스크톱", "icon": "🖥️", "color": "#2563eb"},
    "vnc":    {"label": "🖻 VNC 원격 화면", "icon": "🖻", "color": "#7c3aed"},
    "web":    {"label": "🌐 웹 주소",       "icon": "🌐", "color": "#0284c7"},
    "ftp":    {"label": "📁 FTP 폴더",     "icon": "📁", "color": "#16a34a"},
    # [2026-10-10 신규] 📱 핸드폰 미러링 — 카드 클릭 → **이 PC 화면에** scrcpy 창이 뜬다.
    #   (SSH 카드가 웹 터미널을 여는 것과 같은 발상, 단 대상이 '폰 화면'이다)
    #   [사용자 지시] "콘솔에서 실행할때와 동일하게 … 로컬pc 에서 할꺼니까"
    #   → 웹으로 영상을 스트리밍하지 않고, 서버 PC 에 scrcpy 창을 직접 띄운다.
    "phone":  {"label": "📱 핸드폰 미러링",  "icon": "📱", "color": "#10b981"},
}

