_CONN_RUNNABLE_NEEDS_TARGET = ("fotoo_slideshow", "video_shuffle_play", "music_shuffle_play")

# 🖥️ 웹 SSH 세션 레지스트리 (세션마다 독립 상태 객체 — 이전 스레드 잔여 출력 누수 방지 🛡️)
