_CONN_SSH_EOF = object()

# 📱 phone 카드 중복 실행 방지 (2026-10-10 · 99 감사 P2)
#   [문제] 카드 클릭 시 스레드로 곧바로 scrcpy 를 띄우는데 **중복 방지 장치가 없었다.**
#          연속 클릭하면 창이 계속 쌓이고 adb connect 를 반복 호출한다.
#          scrcpy 는 한 기기에 여러 개가 동시에 붙으면 기기 경합이 생긴다.
#   [해법] 카드별 '마지막 실행 시각'을 기억하고 쿨다운 동안 재실행을 막는다.
#          (완전 차단이 아니라 쿨다운 — 실수는 막되 정당한 재실행은 허용)
_CONN_PHONE_BUSY = {}          # {카드키: 마지막 실행 시각}
_CONN_PHONE_COOLDOWN = 15      # 초
_CONN_PHONE_BUSY_MAX = 64      # 무한 증가 방지 상한


def _conn_type_default_icon(c_type) -> str:
    """접속 카드 유형별 기본 아이콘 반환 🎨"""
    key = str(c_type or "").strip().lower()
    meta = _CONN_TYPE_META.get(key)
    return meta["icon"] if meta else "🔗"


def _conn_normalize_group_name(name) -> str:
    """'그룹.conns' / 'conn_group://그룹' 형태를 순수 그룹명으로 정규화 🏷️"""
    clean = str(name or "").strip()
    if clean.endswith(".conns"):
        clean = clean[: -len(".conns")]
    if clean.startswith("conn_group://"):
        clean = clean[len("conn_group://"):]
    return clean.strip()


def _conn_load_groups():
    """접속·액션 카드 그룹 전체를 안전하게 로드 (실패 시 빈 dict) 🗂️"""
    try:
        s = SettingsManager(SETTINGS_FILE)
        s.load()
        g = s.data.get("playlist_conn_groups", {})
        return g if isinstance(g, dict) else {}
    except Exception as e:
        try: _log_to_file(f"⚠️ [Conn Engine] 그룹 로드 실패: {e}")
        except Exception: pass
        return {}


def _conn_group_items(g_val):
    """그룹 값(dict{items}|list)에서 아이템 리스트를 안전하게 추출 📦"""
    if isinstance(g_val, dict):
        items = g_val.get("items", [])
    elif isinstance(g_val, (list, tuple)):
        items = list(g_val)
    else:
        items = []
    return [it for it in items if isinstance(it, dict) and str(it.get("type") or "").strip()]


def _conn_save_items(settings, group_name, new_items):
    """편집 결과를 그룹에 저장한다 🛡️

    ⚠️ `_conn_group_items()` 는 type 이 비어 있는 항목을 걸러내므로, 걸러진 채로
       저장하면 사용자가 모르게 카드가 영구 삭제된다(데이터 손실).
       → 검증된 항목은 '동일 객체' 기준으로 제자리 교체/추가하고,
         비정상 항목은 원래 자리에 그대로 보존한다.
    """
    def _valid(it):
        return isinstance(it, dict) and str(it.get("type") or "").strip()

    g2 = settings.data.get("playlist_conn_groups", {})
    if not isinstance(g2, dict):
        g2 = {}
    gval = g2.get(group_name)
    if isinstance(gval, dict):
        raw = list(gval.get("items", []) or [])
    elif isinstance(gval, (list, tuple)):
        raw = list(gval)
    else:
        raw = []

    new_list = list(new_items or [])
    old_valid = [i for i, it in enumerate(raw) if _valid(it)]
    matched = 0
    for i in old_valid:
        if matched < len(new_list) and new_list[matched] is raw[i]:
            matched += 1

    if matched == len(old_valid) and len(new_list) >= len(old_valid):
        for k, i in enumerate(old_valid):
            raw[i] = new_list[k]
        raw.extend(new_list[len(old_valid):])
    else:
        invalid = [it for it in raw if not _valid(it)]
        raw = new_list + invalid

    if isinstance(gval, dict):
        gval["items"] = raw
    else:
        g2[group_name] = {"items": raw}
    settings.data["playlist_conn_groups"] = g2
    settings.save()
    return len(raw) - len(new_list)


def _conn_get_item(group_name, index):
    """(그룹명, 인덱스)로 카드 아이템을 찾아 반환. 실패 시 (None, 정규화된그룹명) 🛡️"""
    gname = _conn_normalize_group_name(group_name)
    groups = _conn_load_groups()
    if gname not in groups:
        return None, gname
    items = _conn_group_items(groups.get(gname))
    try:
        idx = int(index)
    except Exception:
        return None, gname
    if idx < 0 or idx >= len(items):
        return None, gname
    return items[idx], gname


# [TAG: #@_conn_action_catalog]
def _conn_action_catalog():
    """웹 카드에서 즉시 실행 가능한 내부 액션 카탈로그 (라벨 → action_id) 📚"""
    catalog = {}
    try:
        reg = globals().get("SPECIAL_HOTKEY_ACTIONS") or {}
        for aid, info in reg.items():
            if aid == "disabled":
                continue
            if aid in _CONN_RUNNABLE_NEEDS_TARGET:
                continue  # 플리 지정이 필요한 액션은 웹 카드 단독 실행 불가 🚫
            nm = (info or {}).get("name") or aid
            catalog[aid] = re.sub(r"\s+", " ", str(nm)).strip()
    except Exception:
        pass
    for aid, nm in _CONN_RUNNABLE_EXTRA.items():
        catalog[aid] = nm
    return catalog


def _conn_is_runnable(action_id) -> bool:
    """화이트리스트에 등록된 즉시 실행 액션인지 판별 🛡️"""
    aid = str(action_id or "").strip()
    if not aid:
        return False
    if aid in _CONN_RUNNABLE_EXTRA:
        return True
    reg = globals().get("SPECIAL_HOTKEY_ACTIONS") or {}
    return aid in reg and aid != "disabled" and aid not in _CONN_RUNNABLE_NEEDS_TARGET


def _conn_notify_telegram(text):
    """카드 실행 사실을 텔레그램으로 알림 (실패해도 무시) 📲"""
    try:
        fn = globals().get("send_telegram_message") or globals().get("_telegram_send")
        if callable(fn):
            fn(text)
    except Exception:
        pass


# [TAG: #@_conn_execute_phone_card]
def _conn_execute_phone_card(group_name, index, item):
    """📱 핸드폰 미러링 카드 실행 — 이 PC 에 scrcpy 창을 띄운다. 반환: (성공, 메시지) 🪞

    [사용자 지시 2026-10-10]
      "/media 에서 ssh 콘솔 접속할 수 있는것처럼, 카드로 지정한 핸드폰의 미러링"
      "특정 카드를 선택하면 핸드폰 화면이 뜨고 조작이 가능하도록"
      + "미러링 화면은 콘솔에서 실행할때와 동일하게 … 어차피 원격에서 하는건 아니고
        로컬pc 에서 할꺼니까"
      → 즉 웹으로 픽셀을 보내지 않고 **서버 PC 화면에 scrcpy 창을 직접 띄운다.**

    [설계]
      · 카드의 target = 기기 IP (또는 'all' = 지정된 폰 전체)
      · 연결/미러링 실행은 phone_common 엔진이 담당한다(SSOT — 냥폰/ADB마법사와 동일).
        여기선 '어떤 폰·어떤 모드'만 카드에서 읽어 넘긴다.
      · 반환은 **즉시**(스레드) 하고 실제 연결은 백그라운드에서 한다.
        adb 연결은 수 초 걸릴 수 있어 웹 요청이 먼저 끝나야 화면이 멈추지 않는다.
    [카드 필드]
        target           : 기기 IP 또는 'all'
        mirror_profile   : 'multi'(다중 최적화, 기본) | 'single'(고화질+오디오)
        turn_off_screen  : True 면 폰 본체 화면 끄고(절전 모드)
    """
    label = str(item.get("label") or "핸드폰 미러링").strip()
    target = str(item.get("target") or "").strip()
    profile = str(item.get("mirror_profile") or "multi").strip().lower()
    if profile not in ("multi", "single"):
        profile = "multi"
    turn_off = bool(item.get("turn_off_screen"))

    if not _PHONE_COMMON_OK:
        return False, "폰 엔진이 없어 (공개 배포본) 미러링을 열 수 없어! 📱"

    # ── 'all' 이면 지정된 폰 전체를 동시에 연다 ──
    is_all = (not target or target.lower() == "all")
    if not is_all and not _adb_ip_strings():
        return False, "등록된 기기가 없어! 먼저 '무선 ADB 최초 등록'을 해줘. 🔍"

    # 🛡️ [99 감사 P2] 중복 실행 방지 — 연속 클릭으로 창이 쌓이는 것을 막는다.
    card_key = f"{group_name}::{index}::{target or 'all'}"
    now = time.time()
    last = _CONN_PHONE_BUSY.get(card_key, 0)
    if now - last < _CONN_PHONE_COOLDOWN:
        left = int(_CONN_PHONE_COOLDOWN - (now - last)) + 1
        return False, f"아까 실행했어! {left}초 후에 다시 눌러줘 (창 중복 방지) 🛡️"
    if len(_CONN_PHONE_BUSY) > _CONN_PHONE_BUSY_MAX:
        # 오래된 것부터 정리 (사전은 삽입 순서 보장)
        for _k in list(_CONN_PHONE_BUSY)[:len(_CONN_PHONE_BUSY) // 2]:
            _CONN_PHONE_BUSY.pop(_k, None)
    _CONN_PHONE_BUSY[card_key] = now

    def _worker():
        """[99 감사 P1] 반환값을 **버리지 않는다** — 실패를 사용자에게 알린다.

        [왜] 웹 토스트는 이미 '열었어' 로 나가 버린 뒤다. 그래서 실패가 조용하면
           사용자는 '눌렀는데 왜 안 뜨지?' 만 남고 원인을 알 수 없다(먹통 증상).
           → 성공/실패 모두 텔레그램으로 남기고 로그에 사유를 적는다.
        """
        try:
            if is_all:
                res = _phone_mirror_all(turn_off_screen=turn_off, profile=profile)
                failed = res.get("failed") or []
                succ = res.get("success", 0)
                total = res.get("total", 0)
                if failed:
                    _who = ", ".join(f.get("name") or f.get("ip") for f in failed)
                    _why = failed[0].get("reason") or ""
                    _log_to_file(f"📱 [Conn Card] '{label}' 미러링 부분 실패: "
                                 f"{len(failed)}/{total} — {_who} ({_why})")
                    _conn_notify_telegram(
                        f"📱 [웹 카드] '{label}' — {succ}/{total}대 성공, "
                        f"{len(failed)}대 실패: {_who}\n   💡 {_why}")
                else:
                    _log_to_file(f"📱 [Conn Card] '{label}' 미러링 {succ}/{total}대 완료")
                    _conn_notify_telegram(f"✅ [웹 카드] '{label}' 미러링 {succ}대 완료! 📱")
            else:
                # 카드 target 의 IP 에 해당하는 등록 dict 를 찾아 1대만 연다
                dev = next((d for d in _adb_load_ips() if d.get("ip") == target), None)
                if not dev:
                    # 등록에 없지만 mDNS 로 잡힐 수 있으므로 IP 로 직접 시도한다
                    dev = {"ip": target, "port": 5555}
                r = _phone_mirror_one(dev.get("ip"), dev.get("port", 5555),
                                      alias=dev.get("alias") or "",
                                      profile=profile, turn_off_screen=turn_off)
                if r.get("ok"):
                    _log_to_file(f"📱 [Conn Card] '{label}' 미러링 창 실행: {r.get('target')}")
                    _conn_notify_telegram(f"✅ [웹 카드] '{label}' 미러링 창을 열었어! 📱")
                else:
                    _why = r.get("reason") or "연결 실패"
                    _log_to_file(f"❌ [Conn Card] '{label}' 미러링 실패: {_why}")
                    _conn_notify_telegram(f"❌ [웹 카드] '{label}' 미러링 실패!\n   💡 {_why}")
        except Exception as e:
            _log_to_file(f"❌ [Conn Card] phone 미러링 예외: {e}")
            _conn_notify_telegram(f"❌ [웹 카드] '{label}' 미러링 중 오류: {e}")

    try:
        threading.Thread(target=_worker, name="ConnCardPhone", daemon=True).start()
    except Exception as e:
        return False, f"미러링 실행 스레드 시작 실패: {e}"

    _log_to_file(f"📱 [Conn Card] phone 미러링 요청: group='{group_name}' "
                 f"idx={index} target={target or 'all'} profile={profile}")
    # [99 감사 P2] '켜졌어' 사전 알림은 보내지 않는다 → 완료/실패 알림으로 대체
    #   (클릭마다 '켜짐'이 오면 스팸이고, 정작 실패는 안 보이는 모순이 생긴다)
    who = "지정된 폰 전체" if is_all else target
    return True, (f"'{label}' 미러링을 시작했어! 이 PC 창을 확인해봐 📱 ({who})\n"
                  f"   완료·실패 결과는 텔레그램으로 알려줄게.")


# [TAG: #@_conn_execute_action]
def _conn_execute_action(group_name, index, minutes=None):
    """접속 카드의 내부 액션을 실행한다. 반환: (성공여부, 메시지) 🎯

    mode="run"   → 화이트리스트 검증 후 백그라운드 스레드에서 무질문 실행
    mode="focus" → 앱 TUI 메뉴로 점프 신호 주입 (사용자가 눈으로 확인하며 진행) 🧭
    """
    item, gname = _conn_get_item(group_name, index)
    if not item:
        return False, "접속 카드를 찾을 수 없어! 목록을 새로고침해줘. 🔍"

    c_type = str(item.get("type") or "").strip().lower()

    # 📱 [2026-10-10 신규] 핸드폰 미러링 카드 → 이 PC 에 scrcpy 창을 띄운다.
    #   [사용자 지시] "콘솔에서 실행할때와 동일하게 … 로컬pc 에서 할꺼니까"
    #   → 웹 영상 스트리밍이 아니라 **서버 PC 화면에 실제 창**을 연다(same as console).
    if c_type == "phone":
        return _conn_execute_phone_card(gname, index, item)

    if c_type != "action":
        return False, "이 카드는 실행형 액션 카드가 아니야!"

    target = str(item.get("target") or "").strip()
    label = str(item.get("label") or target or "내부 액션").strip()
    mode = str(item.get("mode") or "").strip().lower()
    if mode not in ("run", "focus"):
        mode = "focus"

    # 🧭 [focus] 앱 TUI 메뉴로 점프 — 웹에서 직접 실행하지 않고 사용자가 눈으로 확인 🛡️
    if mode == "focus":
        if not _SUBMENU_DEEPLINK_HANDLERS.get(target):
            return False, f"'{target}' 은(는) 등록된 앱 메뉴가 아니야! 🔍"
        globals()["_remote_cmd"] = f"conn_dl:{target}"
        msg = f"앱 메뉴를 앞으로 가져와 '{label}' 화면을 열었어! 🧭 확인 후 진행해줘."
        _log_to_file(f"🖥️ [Conn Card] focus 신호 전송: group='{gname}' idx={index} target={target}")
        _conn_notify_telegram(f"🖥️ [웹 카드] '{label}' 메뉴를 앱에서 열었습니다.")
        return True, msg

    # ⚡ [run] 무질문 즉시 실행 — 반드시 화이트리스트에 있어야 한다 🛡️
    if not _conn_is_runnable(target):
        return False, f"'{target}' 은(는) 웹에서 즉시 실행할 수 없는 액션이야! 🔒"

    # 🌙 [절전 및 예약 기상 특수 처리] (동기적으로 스케줄/타이머 등록 후 10초 카운트다운 시작)
    if target in ("pc_sleep_wake", "system_sleep"):
        try:
            s = globals().get("settings") or globals().get("settings_ref")
            if s is None:
                s = SettingsManager(SETTINGS_FILE)
                s.load()
            token = (s.data.get('telegram_bot_token') or '') if s else ''
            chat_id = (s.data.get('telegram_chat_id') or '') if s else ''
            wake_mins = safe_int(minutes, default=0) if minutes is not None else 0

            # 10초 딜레이와 함께 절전/기상 예약 루틴 가동
            _pc_sleep_wake(token=token, chat_id=chat_id, minutes=wake_mins, settings=s, delay_seconds=10)

            if wake_mins > 0:
                wake_time = datetime.now() + timedelta(minutes=wake_mins)
                wake_str = wake_time.strftime("%H시 %M분")
                msg = f"10초 뒤 절전 모드에 진입하고, {wake_mins}분 뒤({wake_str})에 자동으로 깨어날 거야! 👍"
            else:
                msg = "10초 뒤에 PC가 절전 모드에 들어갈 거야! 💤"

            _log_to_file(f"💤 [Conn Card] 절전/기상 요청: group='{gname}' idx={index} minutes={wake_mins}")
            _conn_notify_telegram(f"💤 [웹 카드] '{label}' {msg}")
            return True, msg
        except Exception as e:
            _log_to_file(f"❌ [Conn Card] 절전 실행 실패: {e}")
            return False, f"절전 모드 실행 실패: {e}"

    def _worker():
        try:
            if target == "router_ip_refresh":
                s = globals().get("settings") or globals().get("settings_ref")
                if s is None:
                    s = SettingsManager(SETTINGS_FILE)
                    s.load()
                _router_quick_ip_refresh(s, quiet=True)
            elif target == "pc_mon_off":
                ctypes.windll.user32.SendMessageW(0xFFFF, 0x0112, 0xF170, 2)
            elif target == "pc_mon_on":
                ctypes.windll.user32.mouse_event(1, 1, 1, 0, 0)
                ctypes.windll.user32.mouse_event(1, -1, -1, 0, 0)
                ctypes.windll.user32.SendMessageW(0xFFFF, 0x0112, 0xF170, -1)
            elif target == "pc_vol_up":
                _pc_control_key('volumeup', times=1)
            elif target == "pc_vol_down":
                _pc_control_key('volumedown', times=1)
            elif target == "pc_mute":
                _pc_control_key('volumemute', times=1)
            elif target == "pc_play_pause":
                _pc_control_key('playpause', times=1)
            elif target == "pc_prev_track":
                _pc_control_key('prevtrack', times=1)
            elif target == "pc_next_track":
                _pc_control_key('nexttrack', times=1)
            elif target == "pc_media_stop":
                players = ["AIMP.exe", "PotPlayer64.exe", "PotPlayer.exe", "vlc.exe", "GOM.exe", "KMPlayer.exe", "KMP64.exe"]
                for p in players:
                    subprocess.run(f"taskkill /F /IM {p}", shell=True, capture_output=True)
            elif target == "pc_show_desktop":
                _pc_control_key('show_desktop', times=1)
            elif target == "pc_exit":
                _pc_control_key('alt_f4', times=1)
            elif target == "pc_reboot":
                subprocess.run('shutdown /r /t 10 /c "PC를 10초 뒤 재부팅합니다."', shell=True, capture_output=True)
            elif target == "pc_screenshot":
                s = globals().get("settings") or globals().get("settings_ref")
                token = (s.data.get('telegram_bot_token') or '') if s else ''
                chat_id = (s.data.get('telegram_chat_id') or '') if s else ''
                _pc_control_screenshot(token, chat_id)
            else:
                _execute_special_hardware_action(target)
            _log_to_file(f"⚡ [Conn Card] run 실행 완료: group='{gname}' idx={index} target={target}")
            # 📲 성공 감사 기록 — 토스트/확인창이 약속한 "텔레그램 기록"을 실제로 남긴다
            _conn_notify_telegram(f"✅ [웹 카드] '{label}' 실행이 완료되었어! (그룹: {gname})")
        except Exception as e:
            _log_to_file(f"❌ [Conn Card] run 실행 실패: {target} → {e}")
            _conn_notify_telegram(f"❌ [웹 카드] '{label}' 실행 중 오류가 발생했어!")

    try:
        threading.Thread(target=_worker, name="ConnCardAction", daemon=True).start()
    except Exception as e:
        return False, f"액션 실행 스레드 시작 실패: {e}"

    msg = f"'{label}' 실행을 시작했어! 완료되면 텔레그램으로 알려줄게. ⚡"
    _log_to_file(f"⚡ [Conn Card] run 실행 요청: group='{gname}' idx={index} target={target}")
    return True, msg


# [TAG: #@_conn_ssh_find_bin]
def _conn_ssh_find_bin():
    """Windows OpenSSH 클라이언트(ssh.exe) 경로 탐색 (PATH → 시스템 경로 순) 🐾"""
    try:
        cand = (_sshc_bin_paths() or {}).get("ssh")
        if cand and os.path.exists(cand):
            return cand
    except Exception:
        pass
    for p in (
        os.path.expandvars(r"%WINDIR%\System32\OpenSSH\ssh.exe"),
        os.path.expandvars(r"%ProgramFiles%\OpenSSH\ssh.exe"),
        r"C:\Windows\System32\OpenSSH\ssh.exe",
    ):
        if p and os.path.exists(p):
            return p
    return None


# [TAG: #@_conn_ssh_reader]
def _conn_ssh_reader(sess):
    """원격 PTY 출력 → 세션 버퍼로 밀어 넣는 전용 리더 스레드 📥
    ⚠️ Windows 파이프는 select()가 불가하므로 os.read() 로 직접 읽는다.
    ⚠️ 멀티바이트(EUC-KR) 잘림 방지를 위해 점진적 디코더를 쓴다."""
    proc = sess.get("proc")
    if proc is None or proc.stdout is None:
        return
    try:
        fd = proc.stdout.fileno()
    except Exception:
        return
    codec = sess.get("codec") or "utf-8"
    # 🛡️ codecs 는 korea.srt.py 전역에 없는 모듈이므로 반드시 함수 내부 lazy import 한다
    #    (누락 시 아래 fallback 까지 NameError 로 터져 리더 스레드가 즉사한다)
    import codecs as _codecs
    try:
        dec = _codecs.getincrementaldecoder(codec)(errors="replace")
    except Exception:
        dec = _codecs.getincrementaldecoder("utf-8")(errors="replace")

    try:
        while True:
            try:
                data = os.read(fd, 4096)
            except Exception:
                break
            if not data:
                break
            try:
                text = dec.decode(data)
            except Exception:
                continue
            if text:
                with sess["lock"]:
                    sess["chunks"].append(text)
            # ⚠️ 여기서는 last_active 를 갱신하지 않는다.
            #    갱신하면 원격에 출력이 있는 세션(tail -f 등)은 브라우저를 닫아도
            #    유휴 GC 가 영영 발동하지 않아 SSH 프로세스가 무한 누수된다.
            #    생존 판정은 '사용자 입력'과 '스트림 연결'만으로 한다. (아래 _conn_ssh_touch)
    finally:
        try:
            tail = dec.decode(b"", True)
            if tail:
                with sess["lock"]:
                    sess["chunks"].append(tail)
        except Exception:
            pass
        with sess["lock"]:
            sess["closed"] = True
            sess["chunks"].append(_CONN_SSH_EOF)  # 종료 마커 (마지막)


# [TAG: #@_conn_ssh_start]
def _conn_ssh_start(settings, alias, rows=30, cols=100, group=""):
    """웹 SSH 터미널 세션 시작. 반환: (sid, err) — 실패 시 sid=None 🖥️
    ⚠️ 레거시 서버 호환을 위해 원격에서 `stty rows/cols` 로 PTY 크기를 강제한다."""
    alias = str(alias or "").strip()
    if not alias:
        return None, "접속 대상(alias)이 비어 있어!"

    prof = None
    if settings is not None:
        prof = _sshc_get_profile(settings, alias)
    if not prof:
        try:
            s = SettingsManager(SETTINGS_FILE)
            s.load()
            prof = _sshc_get_profile(s, alias)
        except Exception:
            prof = None
    if not prof:
        return None, f"'{alias}' 등록된 SSH 프로필이 없어! 설정에서 먼저 추가해줘. ⚠️"

    ssh_bin = _conn_ssh_find_bin()
    if not ssh_bin:
        return None, "Windows OpenSSH 클라이언트(ssh.exe)를 찾지 못했어! ⚠️"

    try:
        rows = max(10, min(500, int(rows or 30)))
        cols = max(20, min(400, int(cols or 100)))
    except Exception:
        rows, cols = 30, 100

    shell_cmd = str(prof.get("shell_cmd") or "bash --login").strip()
    # ⚠️ 서버 bash는 '-l' 을 거부하므로 반드시 'bash --login' 형태를 쓴다
    remote_cmd = f"stty rows {rows} cols {cols}; exec {shell_cmd}"

    try:
        proc = subprocess.Popen(
            [ssh_bin, "-tt", "-o", "BatchMode=yes", alias, remote_cmd],
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            bufsize=0,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        )
    except Exception as e:
        return None, f"SSH 세션 실행 실패: {e}"

    # 🛡️ codecs 전역 임포트가 없으므로 lazy import 한다.
    #    ⚠️ 이전엔 NameError 가 조용히 잡혀 EUC-KR 서버인데도 utf-8 로 떨어져 한글이 깨졌다.
    import codecs as _codecs
    try:
        codec = _sshc_charmap_codec(alias) or "utf-8"
        _codecs.lookup(codec)
    except Exception:
        codec = "utf-8"

    with _CONN_SSH_LOCK:
        _CONN_SSH_SEQ[0] += 1
        sid = f"wssh_{int(time.time())}_{_CONN_SSH_SEQ[0]}"
        sess = {
            "sid": sid,
            "alias": alias,
            "group": _conn_normalize_group_name(group),  # 🔒 요청 시 그룹 접근권 재검증에 사용
            "codec": codec,
            "proc": proc,
            "chunks": [],       # 세션 전용 버퍼 (공용 리스트 재사용 금지 🛡️)
            "lock": threading.Lock(),
            "closed": False,
            "rows": rows,
            "cols": cols,
            "created": time.time(),
            "last_active": time.time(),
        }
        _CONN_SSH_SESSIONS[sid] = sess
        # 🧹 동시 세션 수 제한 (초과분은 오래된 것부터 정리)
        # 🛡️ [치명 수정] _conn_ssh_stop 은 _CONN_SSH_LOCK 을 다시 잡으므로(비재진적 Lock)
        #    절대 이 with 블록 안에서 호출하면 안 된다 → 대상만 수집하고 밖에서 정리한다.
        evict = []
        if len(_CONN_SSH_SESSIONS) > _CONN_SSH_MAX_SESSIONS:
            oldest = sorted(_CONN_SSH_SESSIONS.values(), key=lambda s: s.get("created", 0))
            for old in oldest[: len(_CONN_SSH_SESSIONS) - _CONN_SSH_MAX_SESSIONS]:
                evict.append(old.get("sid"))

    for _ev_sid in evict:          # 🔓 락 밖에서 정리 (데드락 방지)
        try:
            _conn_ssh_stop(_ev_sid)
        except Exception:
            pass

    threading.Thread(target=_conn_ssh_reader, args=(sess,), name=f"ConnSshReader_{sid}", daemon=True).start()
    _log_to_file(f"🖥️ [Conn SSH] 세션 시작: sid={sid} alias={alias} codec={codec} {rows}x{cols}")
    return sid, ""


# [TAG: #@_conn_ssh_stop]
def _conn_ssh_stop(sid):
    """SSH 세션 종료 (프로세스 종료 + 레지스트리 제거) 🛑"""
    with _CONN_SSH_LOCK:
        sess = _CONN_SSH_SESSIONS.pop(str(sid or ""), None)
    if not sess:
        return False
    try:
        proc = sess.get("proc")
        if proc is not None and proc.poll() is None:
            try:
                proc.terminate()
            except Exception:
                pass
            try:
                proc.wait(timeout=2)
            except Exception:
                try: proc.kill()
                except Exception: pass
    except Exception:
        pass
    with sess.get("lock", threading.Lock()):
        sess["closed"] = True
    _log_to_file(f"🛑 [Conn SSH] 세션 종료: sid={sess.get('sid')} alias={sess.get('alias')}")
    return True


def _conn_ssh_session(sid):
    """sid로 세션 객체 조회 (없으면 None) 🔍"""
    with _CONN_SSH_LOCK:
        return _CONN_SSH_SESSIONS.get(str(sid or ""))


def _conn_ssh_touch(sid):
    """세션이 살아있음(브라우저 접속 중)을 표기 🕒
    ⚠️ SSE 스트림이 붙을 때마다 호출해야 조용한 세션도 유휴 GC 에 걸리지 않는다."""
    sess = _conn_ssh_session(sid)
    if sess:
        sess["last_active"] = time.time()
        return True
    return False


def _conn_ssh_gc():
    """유휴/종료된 SSH 세션 주기적 정리 🧹"""
    now = time.time()
    dead = []
    with _CONN_SSH_LOCK:
        for sid, s in list(_CONN_SSH_SESSIONS.items()):
            if s.get("closed") or (now - float(s.get("last_active") or 0)) > _CONN_SSH_IDLE_TTL:
                dead.append(sid)
    for sid in dead:
        _conn_ssh_stop(sid)


# [TAG: #@_conn_ssh_write]
def _conn_ssh_write(sid, text):
    """브라우저 → 원격 셸 입력 전송 (UTF-8 → 서버 charmap 역변환) ⌨️
    ⚠️ 서버 출력과 같은 EUC-KR 로 바꿔 보내야 원격 셸이 정상 처리한다."""
    sess = _conn_ssh_session(sid)
    if not sess:
        return False, "세션이 없거나 이미 종료되었어!"
    try:
        data = (text or "").encode(sess.get("codec") or "utf-8", errors="replace")
        if not data:
            return True, ""
        stdin_f = sess["proc"].stdin
        os.write(stdin_f.fileno(), data)
        sess["last_active"] = time.time()
        return True, ""
    except Exception as e:
        return False, str(e)


# [TAG: #@_conn_ssh_read]
def _conn_ssh_read(sid, timeout=0.4):
    """원격 셸 → 브라우저 출력 수집. 반환: (ok, 텍스트, 종료여부) 📤"""
    sess = _conn_ssh_session(sid)
    if not sess:
        return False, "", True
    out = []
    done = False
    deadline = time.time() + max(0.0, float(timeout or 0.4))
    slock = sess["lock"]
    while True:
        item = _CONN_SSH_EOF
        with slock:
            if sess["chunks"]:
                item = sess["chunks"].pop(0)
            closed = bool(sess.get("closed"))
        if item is _CONN_SSH_EOF:
            if closed:
                done = True
                break
            if time.time() >= deadline:
                break
            time.sleep(0.02)
            continue
        out.append(item)
    return True, "".join(out), done


def _is_playlist_published_state(name, fname="", pub_map=None):
    """플레이리스트의 웹 게시 상태(True/False)를 정규화하여 판별하는 통일 헬퍼 🌐✨"""
    if pub_map is None:
        return True
    if not isinstance(pub_map, dict) or not pub_map:
        return True

    clean_name = str(name or '').strip()
    if clean_name.endswith('.urls') or clean_name.startswith('url_group://'):
        clean_name = clean_name.replace('.urls', '').replace('url_group://', '')
    elif clean_name.endswith('.images') or clean_name.startswith('image_group://'):
        clean_name = clean_name.replace('.images', '').replace('image_group://', '')
    elif clean_name.endswith('.conns') or clean_name.startswith('conn_group://'):
        clean_name = clean_name[:-len('.conns')] if clean_name.endswith('.conns') else clean_name[len('conn_group://'):]
    elif clean_name.endswith('.memos') or clean_name.startswith('memo_group://'):
        clean_name = clean_name[:-len('.memos')] if clean_name.endswith('.memos') else clean_name[len('memo_group://'):]
    elif clean_name.lower().endswith(('.m3u8', '.dpl', '.m3u', '.pls')):
        clean_name = os.path.splitext(os.path.basename(clean_name))[0]
    else:
        clean_name = os.path.splitext(os.path.basename(clean_name))[0]

    raw_name = str(fname or '').strip()

    # 1. clean_name 정확 매칭 우선 (예: 'google.photo')
    if clean_name in pub_map:
        return bool(pub_map[clean_name])

    # 2. raw_name 정확 매칭 (예: 'google.photo.images')
    if raw_name and raw_name in pub_map:
        return bool(pub_map[raw_name])

    # 3. 대소문자 무시 clean_name 매칭
    c_low = clean_name.lower()
    for k, v in pub_map.items():
        if str(k).lower() == c_low:
            return bool(v)

    # 4. 대소문자 무시 raw_name / noext 매칭
    if raw_name:
        r_low = raw_name.lower()
        r_noext = os.path.splitext(os.path.basename(raw_name))[0].lower()
        for k, v in pub_map.items():
            if str(k).lower() in (r_low, r_noext):
                return bool(v)

    return True

# 🌐 [신규] 즐겨찾기 URL 스크린샷 썸네일 캐시 폴더
URL_SCREENSHOTS_DIR = os.path.join(BASE_DIR, "temp", "url_screenshots")

def _get_url_screenshot_cache_path(url):
    """URL의 고유 MD5 해시 기반 로컬 스크린샷 캐시 파일 경로 반환 📸"""
    import hashlib
    clean_u = (url or "").strip().strip("'\"")
    h = hashlib.md5(clean_u.encode('utf-8')).hexdigest()
    return os.path.join(URL_SCREENSHOTS_DIR, f"{h}.png")

def _get_clipboard_url_native():
    """윈도우 네이티브 클립보드에서 유효한 URL 자동 추출 📋🔗"""
    try:
        import ctypes, ctypes.wintypes as wt
        u32 = ctypes.windll.user32
        k32 = ctypes.windll.kernel32
        if u32.OpenClipboard(None):
            h_mem = u32.GetClipboardData(13) # CF_UNICODETEXT
            if h_mem:
                k32.GlobalLock.restype = wt.LPCWSTR
                text_ptr = k32.GlobalLock(h_mem)
                if text_ptr:
                    cand = str(text_ptr).strip().strip("'\"")
                    if cand.startswith(('http://', 'https://', 'www.')):
                        k32.GlobalUnlock(h_mem)
                        u32.CloseClipboard()
                        return cand
                k32.GlobalUnlock(h_mem)
            u32.CloseClipboard()
    except Exception:
        pass
    return None

def _fetch_url_metadata(url, timeout=4.0):
    """웹페이지 접속 후 <title> 태그 및 도메인 자동 추출 (초고속 메타데이터 수집, SSL/인코딩 방어) 🌐✨"""
    import urllib.request
    import urllib.parse
    import re
    import html
    import ssl
    clean_u = (url or "").strip().strip("'\"")
    if not clean_u.startswith(('http://', 'https://')):
        clean_u = 'https://' + clean_u
    
    parsed = urllib.parse.urlparse(clean_u)
    domain = parsed.netloc or parsed.path.split('/')[0]
    title = domain
    try:
        ctx = ssl._create_unverified_context()
        req = urllib.request.Request(
            clean_u, 
            headers={'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'}
        )
        with urllib.request.urlopen(req, timeout=timeout, context=ctx) as response:
            raw_data = response.read(65536)
            charset = 'utf-8'
            content_type = response.headers.get('content-type', '').lower()
            if 'charset=' in content_type:
                charset = content_type.split('charset=')[-1].split(';')[0].strip()
            elif b'charset=euc-kr' in raw_data.lower() or b'charset="euc-kr"' in raw_data.lower():
                charset = 'euc-kr'
            elif b'charset=cp949' in raw_data.lower() or b'charset="cp949"' in raw_data.lower():
                charset = 'cp949'
            
            try:
                html_text = raw_data.decode(charset, errors='replace')
            except Exception:
                html_text = raw_data.decode('utf-8', errors='ignore')

            m = re.search(r'<title[^>]*>(.*?)</title>', html_text, re.IGNORECASE | re.DOTALL)
            if m:
                t = html.unescape(m.group(1).strip())
                t = re.sub(r'\s+', ' ', t)
                if t:
                    title = t
    except Exception:
        pass
    return {'url': clean_u, 'title': title, 'domain': domain}

def _capture_url_screenshot(url, out_path=None, force=False):
    """Windows Edge 또는 Chrome 헤드리스 모드로 실제 웹페이지 고화질 스크린샷 캡처 (실패 시 mshots 무료 썸네일 폴백) 📸✨"""
    import hashlib
    import subprocess
    import tempfile
    import urllib.request
    import urllib.parse
    import ssl
    
    clean_u = (url or "").strip().strip("'\"")
    if not clean_u.startswith(('http://', 'https://')):
        clean_u = 'https://' + clean_u
        
    if not out_path:
        out_path = _get_url_screenshot_cache_path(clean_u)
        
    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    
    if not force and os.path.exists(out_path) and os.path.getsize(out_path) > 1000:
        return out_path
        
    browser_candidates = [
        r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe",
        r"C:\Program Files\Microsoft\Edge\Application\msedge.exe",
        r"C:\Program Files\Google\Chrome\Application\chrome.exe",
        r"C:\Program Files (x86)\Google\Chrome\Application\chrome.exe"
    ]
    browser_bin = None
    for b in browser_candidates:
        if os.path.exists(b):
            browser_bin = b
            break
            
    captured = False
    if browser_bin:
        temp_user_data = os.path.join(tempfile.gettempdir(), f"binu_shot_{hashlib.md5(clean_u.encode()).hexdigest()[:8]}")
        cmd = [
            browser_bin,
            "--headless=new",
            "--disable-gpu",
            "--hide-scrollbars",
            "--window-size=1280,720",
            f"--user-data-dir={temp_user_data}",
            f"--screenshot={out_path}",
            clean_u
        ]
        try:
            subprocess.run(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=12, creationflags=0x08000000)
            if os.path.exists(out_path) and os.path.getsize(out_path) > 1000:
                captured = True
        except Exception:
            pass
        finally:
            try:
                if os.path.exists(temp_user_data):
                    import shutil
                    shutil.rmtree(temp_user_data, ignore_errors=True)
            except Exception:
                pass
                
    # 만약 브라우저 캡처 실패 시: WordPress mshots 무료 썸네일 API로 즉시 폴백 🛡️
    if not captured or not os.path.exists(out_path) or os.path.getsize(out_path) < 1000:
        try:
            mshot_url = f"https://s0.wp.com/mshots/v1/{urllib.parse.quote(clean_u)}?w=800"
            req = urllib.request.Request(mshot_url, headers={'User-Agent': 'Mozilla/5.0'})
            ctx = ssl._create_unverified_context()
            with urllib.request.urlopen(req, timeout=8, context=ctx) as resp, open(out_path, 'wb') as f:
                f.write(resp.read())
            if os.path.exists(out_path) and os.path.getsize(out_path) > 500:
                captured = True
        except Exception:
            pass
            
    return out_path if captured else None

def _async_capture_url_screenshot(url, force=False):
    """비동기 백그라운드 스레드로 스크린샷 캡처 실행 (웹 대시보드 지연 방지) ⚡"""
    import threading
    t = threading.Thread(target=_capture_url_screenshot, args=(url, None, force), daemon=True)
    t.start()

def playlist_url_group_interactive(group_name, settings):
    """특정 즐겨찾기 URL 그룹 관리 대화형 메뉴 🌐✨"""
    R = C.RESET
    while True:
        clear_console()
        url_groups = settings.data.get("playlist_url_groups", {})
        items = url_groups.get(group_name, [])

        # 🌐 [신규] 미디어서버(웹) 게시 상태 및 접근 비밀번호 정보 로드 ✨
