        is_published = _is_playlist_published_state(group_name, f"{group_name}.urls", publish_map)
        publish_label = "게시 중 ⚪" if is_published else "비게시 ⚫"

        pins_map = settings.data.get("playlist_pins", {})
        current_pin = str(pins_map.get(group_name, "")).strip()
        pin_label = f"설정됨 🔒 ({len(current_pin)}자리)" if current_pin else "비번 없음 🔓"

        _print_standard_menu_header("playlist", settings)
        print(f"  🌐 {C.BOLD}즐겨찾기 URL 그룹:{R} {C.GREEN}{group_name}{R} (등록 사이트 {len(items)}개)")
        print(f"  🌐 {C.BOLD}웹 게시 상태:{R} {C.SKY}{publish_label}{R}  |  🔑 {C.BOLD}접근 비밀번호:{R} {C.GOLD}{pin_label}{R}")
        if items:
            print("  " + 헤더선(width=58))
            print(f"  🔗 {C.BOLD}등록된 웹사이트 목록:{R}")
            for idx, it in enumerate(items, 1):
                u = it.get('url', '') if isinstance(it, dict) else it
                t = (it.get('title', '') if isinstance(it, dict) else '') or u
                shot_path = _get_url_screenshot_cache_path(u)
                has_shot = os.path.exists(shot_path) and os.path.getsize(shot_path) > 1000
                shot_tag = f"{C.GREEN}📸 캡처됨{R}" if has_shot else f"{C.YELLOW}⏳ 미캡처{R}"
                print(f"    {idx}. 🌐 {C.SKY}[{t}]{R} {u} ({shot_tag})")
        print(" " + 헤더선(width=60))

        options_map = [
            {"label": " ➕ 새로운 웹사이트 URL 추가하기 (클립보드 감지/일괄 지원)", "key": "add"},
            {"label": " ➖ 등록된 웹사이트 URL 삭제하기", "key": "delete"},
            {"label": " ✏️ 등록된 사이트 이름(별칭) 또는 URL 수정", "key": "edit_site"},
            {"label": " 📌 사이트 순서 변경 (위/아래 재배치)", "key": "reorder_sites"},
            {"label": " 📸 등록된 모든 웹사이트 스크린샷 새로고침 (일괄 재촬영)", "key": "refresh_shots"},
            {"label": " 🌐 등록된 웹사이트 기본 브라우저에서 열기", "key": "open_browser"},
            {"label": f" 🌐 미디어서버(웹) 게시 설정 [현재: {publish_label}]", "key": "publish_toggle"},
            {"label": f" 🔑 미디어서버(웹) 접근 비번 설정 [현재: {pin_label}]", "key": "pin_setup"},
            {"label": " 📝 URL 그룹 이름 변경", "key": "rename_group"},
            {"label": " ❌ 이전 메뉴로 돌아가기", "key": "back"}
        ]

        options = [item["label"] for item in options_map]
        choice, action, *_ = _interactive_menu(f"🚀 '{group_name}' URL 그룹에서 무엇을 할까?", options, timeout=0)

        if choice < 0 or choice >= len(options_map):
            break

        choice_key = options_map[choice]["key"]
        if action == "HISTORY":
            choice_key = "publish_toggle"

        if choice_key == "back":
            break

        elif choice_key == "add":
            clip_u = _get_clipboard_url_native()
            print(f"\r\n 🔗 {C.SKY}추가할 웹사이트 주소(URL)를 입력해줘!{R}")
            if clip_u:
                print(f"    📋 {C.GREEN}클립보드에서 감지된 주소:{R} {C.BOLD}{clip_u}{R}")
                prompt_label = f" 👉 {C.BOLD}URL (Enter시 클립보드 주소 사용):{R} "
            else:
                print(f"    {C.DIM}(예: https://www.naver.com 또는 youtube.com, 여러 줄 붙여넣기 일괄 추가 지원){R}")
                prompt_label = f" 👉 {C.BOLD}URL:{R} "

            raw_inp = prompt_input(prompt_label).strip()
            chosen_inp = raw_inp if raw_inp else (clip_u or "")

            if not chosen_inp:
                print(f" ⚠️ {C.YELLOW}입력이 취소되었어냥.{R}")
                time.sleep(1)
                continue

            raw_tokens = [tok.strip().strip("'\"") for tok in chosen_inp.split() if tok.strip()]
            valid_urls = []
            for tok in raw_tokens:
                if tok.startswith(('http://', 'https://')):
                    valid_urls.append(tok)
                elif '.' in tok and not tok.startswith(('file:', 'ftp:')):
                    valid_urls.append('https://' + tok)

            if not valid_urls:
                print(f" ⚠️ {C.RED}올바른 웹사이트 주소(URL)를 찾지 못했어냥!{R}")
                time.sleep(1.5)
                continue

            exist_urls = [(it.get('url', '') if isinstance(it, dict) else it) for it in items]
            import datetime
            now_str = datetime.datetime.now().strftime('%Y-%m-%d %H:%M')

            if len(valid_urls) == 1:
                new_u = valid_urls[0]
                if new_u in exist_urls:
                    print(f"\r\n ⚠️ {C.YELLOW}이미 등록되어 있는 URL이야!{R}")
                    time.sleep(1.5)
                    continue

                print(f" 🔍 {C.SKY}웹페이지 제목을 읽어오는 중...{R}")
                meta = _fetch_url_metadata(new_u)
                auto_title = meta.get('title') or meta.get('domain') or new_u
                print(f" 👉 감지된 제목: {C.GREEN}{auto_title}{R}")
                user_title = prompt_input(f" 👉 {C.BOLD}이름 수정 (Enter시 그대로 사용):{R} ").strip()
                final_title = user_title if user_title else auto_title

                new_item = {'url': new_u, 'title': final_title, 'added_at': now_str}
                items.append(new_item)
                url_groups[group_name] = items
                settings.data["playlist_url_groups"] = url_groups
                settings.save()

                print(f"\r\n 📸 {C.SKY}웹페이지 스크린샷 캡처 중...{R}")
                _async_capture_url_screenshot(new_u)
                print(f" ✅ {C.GREEN}'{final_title}' 사이트가 추가되었어!{R}")
                time.sleep(1.2)
            else:
                added_count = 0
                print(f"\r\n 📦 {C.SKY}총 {len(valid_urls)}개의 URL을 일괄 등록합니다...{R}")
                for u in valid_urls:
                    if u not in exist_urls:
                        meta = _fetch_url_metadata(u)
                        auto_title = meta.get('title') or meta.get('domain') or u
                        items.append({'url': u, 'title': auto_title, 'added_at': now_str})
                        exist_urls.append(u)
                        _async_capture_url_screenshot(u)
                        added_count += 1
                        print(f"  ➕ 추가됨: {auto_title} ({u})")
                url_groups[group_name] = items
                settings.data["playlist_url_groups"] = url_groups
                settings.save()
                print(f"\r\n ✅ {C.GREEN}총 {added_count}개 사이트가 성공적으로 등록되었어!{R}")
                time.sleep(1.5)
            continue

        elif choice_key == "delete":
            if not items:
                print(f"\r\n ⚠️ {C.YELLOW}삭제할 사이트가 없어냥!{R}")
                time.sleep(1.5)
                continue

            def _get_items():
                return [(it.get('title', '') if isinstance(it, dict) else it) + f" ({it.get('url', '') if isinstance(it, dict) else it})" for it in items]

            def _del_item(idx_str):
                try:
                    target_idx = None
                    for i, it in enumerate(items):
                        disp = (it.get('title', '') if isinstance(it, dict) else it) + f" ({it.get('url', '') if isinstance(it, dict) else it})"
                        if disp == idx_str:
                            target_idx = i
                            break
                    if target_idx is not None:
                        del_target = items[target_idx]
                        u_del = del_target.get('url', '') if isinstance(del_target, dict) else del_target
                        if u_del:
                            shot_p = _get_url_screenshot_cache_path(u_del)
                            if os.path.exists(shot_p):
                                try: os.remove(shot_p)
                                except Exception: pass
                        del items[target_idx]
                        url_groups[group_name] = items
                        settings.data["playlist_url_groups"] = url_groups
                        settings.save()
                        return True
                except Exception:
                    pass
                return False

            _loop_delete_interactive(f"🗑️ '{group_name}'에서 삭제할 사이트를 선택해줘", _get_items, _del_item, allow_multi=True)
            continue

        elif choice_key == "edit_site":
            if not items:
                print(f"\r\n ⚠️ {C.YELLOW}수정할 사이트가 없어냥!{R}")
