                final_u = new_url_inp if new_url_inp else cur_u
                if not final_u.startswith(('http://', 'https://')):
                    final_u = 'https://' + final_u

                url_changed = (final_u != cur_u)
                if isinstance(cur_item, dict):
                    cur_item['title'] = final_t
                    cur_item['url'] = final_u
                else:
                    items[e_choice] = {'url': final_u, 'title': final_t}

                url_groups[group_name] = items
                settings.data["playlist_url_groups"] = url_groups
                settings.save()

                if url_changed:
                    print(f" 📸 {C.SKY}URL이 변경되어 스크린샷을 새로 캡처합니다...{R}")
