                if s_idx < len(items) - 1:
                    mov_opts.append("⬇️ 한 칸 아래로 내리기")
                    mov_opts.append("⏬ 맨 아래로 내리기")
                mov_opts.append("❌ 취소")

                m_choice, m_label, *_ = _interactive_menu("어디로 이동할까?", mov_opts, timeout=0)
                if "한 칸 위로" in m_label:
                    items[s_idx - 1], items[s_idx] = items[s_idx], items[s_idx - 1]
                elif "맨 위로" in m_label:
                    item_to_move = items.pop(s_idx)
                    items.insert(0, item_to_move)
                elif "한 칸 아래로" in m_label:
                    items[s_idx + 1], items[s_idx] = items[s_idx], items[s_idx + 1]
                elif "맨 아래로" in m_label:
                    item_to_move = items.pop(s_idx)
                    items.append(item_to_move)

                url_groups[group_name] = items
                settings.data["playlist_url_groups"] = url_groups
                settings.save()
                print(f"\r\n ✅ {C.GREEN}순서가 변경되었어!{R}")
