            other_groups = [g for g in img_groups_curr.keys() if g != group_name]
            target_opts = []
            for g in other_groups:
                g_cnt = len(img_groups_curr.get(g, []))
                target_opts.append(f"🖼️ '{g}' 그룹으로 복사 (현재 소스 {g_cnt}개 등록됨)")
            target_opts.append("➕ 새 이미지 그룹 만들어서 바로 복사하기")
