                         settings.data.pop('telegram_notify_manual_bulk', None)
                         settings.data.pop('telegram_manual_bulk_threshold', None)
                         settings.data.pop('telegram_notify_security', None)
                         settings.data.pop('telegram_notify_foreign_blocked', None)
                         settings.data.pop('telegram_notify_error', None)
