# [TAG: #@_sync_potplayer_exit_position_to_db]
def _sync_potplayer_exit_position_to_db(last_played_path=None):
    """[V179.0] 팟플레이어 종료 시점에 DPL 1/2 파일 및 레지스트리에서 최종 시청 파일과 위치(초)를 정밀 추출하여 썸.db에 영구 동기화 🎬💾✨"""
    try:
        appdata_dir = os.environ.get('APPDATA', '')
        dpl_candidates = [
            os.path.join(os.path.dirname(os.path.abspath(__file__)), "temp", "Binu_Auto_Playlist_1.dpl"),
            os.path.join(os.path.dirname(os.path.abspath(__file__)), "temp", "Binu_Auto_Playlist_2.dpl"),
            os.path.join(os.path.dirname(os.path.abspath(__file__)), "temp", "Binu_Auto_Playlist.dpl"),
            os.path.join(appdata_dir, r"PotPlayer64\Playlist\PotPlayer64.dpl"),
            os.path.join(appdata_dir, r"PotPlayerMini64\Playlist\PotPlayerMini64.dpl"),
            os.path.join(appdata_dir, r"PotPlayer\Playlist\PotPlayer.dpl")
        ]
        
        dpl_records = []
        for dpl_p in dpl_candidates:
            if not os.path.exists(dpl_p): continue
            try:
                mtime = os.path.getmtime(dpl_p)
                pname = None
                ptime_ms = 0
                with open(dpl_p, 'r', encoding='utf-8', errors='ignore') as f:
                    for line in f:
                        line = line.strip()
                        if line.startswith('playname='):
                            pname = line.split('=', 1)[1].strip()
                        elif line.startswith('playtime='):
                            try: ptime_ms = int(line.split('=', 1)[1].strip())
                            except: pass
                if pname and os.path.exists(pname) and ptime_ms > 3000:
                    dpl_records.append((mtime, pname, ptime_ms / 1000.0))
            except Exception as de:
                _log_to_file(f"⚠️ [DPL Pos Read Error {dpl_p}] {de}")
                
        reg_records = []
        try:
            import winreg
            for base_key in [r"Software\DAUM\PotPlayer64\Positions", r"Software\DAUM\PotPlayerMini64\Positions", r"Software\DAUM\PotPlayer\Positions"]:
                try:
                    k = winreg.OpenKey(winreg.HKEY_CURRENT_USER, base_key)
                    idx = 0
                    while True:
                        try:
                            v_name, v_val, _ = winreg.EnumValue(k, idx)
                            if isinstance(v_val, str) and '=' in v_val:
                                parts = v_val.split('=', 1)
                                ms_str, fpath = parts[0].strip(), parts[1].strip()
                                if ms_str.isdigit() and fpath and os.path.exists(fpath):
                                    pos_s = int(ms_str) / 1000.0
                                    if pos_s > 3.0:
                                        reg_records.append((fpath, pos_s))
                            idx += 1
                        except OSError:
                            break
                    winreg.CloseKey(k)
                except Exception:
                    pass
        except Exception as re:
            _log_to_file(f"⚠️ [Reg Pos Read Error] {re}")
            
        for fpath, pos_s in reg_records:
            _save_playback_pos_db(fpath, pos_s)
            
        for mtime, pname, pos_s in dpl_records:
            _save_playback_pos_db(pname, pos_s)
            _log_to_file(f"🎬 [PotPlayer Exit Sync] DPL 추출 성공: {os.path.basename(pname)} -> {pos_s:.1f}초 썸.db 저장 💾✨")
            
        if last_played_path and os.path.exists(last_played_path):
            match_pos = None
            for fp, ps in reg_records:
                if os.path.abspath(fp).lower() == os.path.abspath(last_played_path).lower():
                    match_pos = ps
                    break
            if match_pos is None:
                for _, dp, ps in dpl_records:
                    if os.path.abspath(dp).lower() == os.path.abspath(last_played_path).lower():
                        match_pos = ps
                        break
            if match_pos and match_pos > 3.0:
                _save_playback_pos_db(last_played_path, match_pos)
                _log_to_file(f"🎯 [PotPlayer Exit Sync] 최종 파일 매칭 완료: {os.path.basename(last_played_path)} -> {match_pos:.1f}초 💾✨")
                
    except Exception as e:
        _log_to_file(f"⚠️ [_sync_potplayer_exit_position_to_db Error] {e}")

_g_last_web_stream_record = {}  # {path_lower: timestamp} (30초 쿨다운 디바운스용) ⏱️
_g_last_video_stream_log = {}   # {path_lower: timestamp} (5초 쿨다운 콘솔 로그 디바운스용) ⏱️
_G_MEDIA_REQUEST_LOG_VISIBLE = True  # [신규] 미디어 서버 [Request] 로그 콘솔 출력 토글 (True: 보임, False: 숨김/파일만) 📋

# [TAG: #@_record_single_playback]
def _record_single_playback(abs_path):
    """[V177.1] 웹 미디어서버 스트리밍 또는 단일 파일 재생 시 카운트 +1 누적 (30초 쿨다운 디바운스) 🌐🎬"""
    if not abs_path: return
    import time
    now = time.time()
    norm_p = os.path.abspath(abs_path)
    norm_key = norm_p.lower()
    
    # 30초 내 동일 파일 중복 스트리밍 요청 디바운스
    last_t = _g_last_web_stream_record.get(norm_key, 0)
    if now - last_t < 30.0:
        return
    _g_last_web_stream_record[norm_key] = now
    
    _record_batch_playbacks([norm_p])

# [V191.0] 썸네일 인메모리(RAM) 초고속 LRU 캐시 및 동시성 락 (최대 200개, 디스크 I/O 90% 제거 ⚡🧠)
from collections import OrderedDict
_g_thumb_mem_cache = OrderedDict()
_g_thumb_cache_lock = threading.Lock()
_MAX_THUMB_MEM_CACHE = 1000

# [TAG: #@_get_thumb_from_mem]
def _get_thumb_from_mem(key):
    """[V191.0] 메모리(RAM)에서 썸네일 바이너리 0.00001초 즉각 조회 🚀"""
    if not key: return None
    with _g_thumb_cache_lock:
        if key in _g_thumb_mem_cache:
            _g_thumb_mem_cache.move_to_end(key)
            return _g_thumb_mem_cache[key]
    return None

# [TAG: #@_put_thumb_to_mem]
def _put_thumb_to_mem(key, mime_type, data):
    """[V191.0] 메모리(RAM)에 썸네일 바이너리 LRU 저장 (최대 1000개 제한) 🧠💾"""
    if not key or data is None: return
    with _g_thumb_cache_lock:
        _g_thumb_mem_cache[key] = (mime_type, data)
        _g_thumb_mem_cache.move_to_end(key)
        while len(_g_thumb_mem_cache) > _MAX_THUMB_MEM_CACHE:
            _g_thumb_mem_cache.popitem(last=False)

# [TAG: #@_get_thumb_cache_key]
def _get_thumb_cache_key(abs_path):
    """[V191.1] 경로 대소문자/구분자 정규화 및 mtime 반올림 기반 일관된 썸네일 해시 키 생성 🎯🔑"""
    if not abs_path:
        return "", 0.0, ""
    import hashlib
    try:
        norm_p = os.path.normcase(os.path.normpath(os.path.abspath(abs_path)))
    except Exception:
        norm_p = str(abs_path).strip().lower()
    try:
        mtime = round(os.path.getmtime(norm_p), 1)
    except Exception:
        mtime = 0.0
    key = hashlib.sha1(f"{norm_p}_{mtime}".encode('utf-8')).hexdigest()
    return norm_p, mtime, key

# [V183.0] 썸네일 추출 FFmpeg 동시 실행 제한 세마포어 (최대 2개 프로세스로 시스템 프리징 원천 방지 🚥🛡️)
_THUMBNAIL_SEMAPHORE = threading.BoundedSemaphore(2)

# # [TAG: #@_extract_youtube_id]
def _extract_youtube_id(text):
    """[V191.5] URL, 태그 또는 파일명에서 11자리 YouTube 비디오 ID 추출 📺🔍"""
    if not text: return None
    import re
    s = str(text)
    m = re.search(r'(?:watch\?v=|youtu\.be/|shorts/|embed/)([a-zA-Z0-9_-]{11})', s)
    if m: return m.group(1)
    m = re.search(r'\[([a-zA-Z0-9_-]{11})\](?:\.[a-zA-Z0-9]+)?$', s)
    if m: return m.group(1)
    return None

# [TAG: #@_fetch_youtube_thumbnail]
def _fetch_youtube_thumbnail(yt_id):
    """[V191.5] YouTube 공식 CDN에서 고화질 썸네일(maxres/hq) 직접 초고속 다운로드 📺⚡"""
    if not yt_id: return None
    import urllib.request
    headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)'}
    for quality in ['maxresdefault', 'hqdefault', 'mqdefault']:
        url = f"https://i.ytimg.com/vi/{yt_id}/{quality}.jpg"
        try:
            req = urllib.request.Request(url, headers=headers)
            with urllib.request.urlopen(req, timeout=3.0) as resp:
                if resp.status == 200:
                    data = resp.read()
                    if data and len(data) > 1500:
                        _log_to_file(f"📺 [YouTube Cover Found] ID: {yt_id} ({len(data)} bytes)")
                        return data
        except Exception:
            continue
    return None

# [TAG: #@_clean_music_title_for_search]
def _clean_music_title_for_search(raw_name):
    """[V191.5] 음원 파일명에서 채널명/트랙번호/영상수식어/확장자를 완전 정제하여 순수 음악 키워드 추출 🎵🧹"""
    import re
    if not raw_name:
        return ""
    s = str(raw_name).strip()
    # 1. 오디오/비디오 확장자 제거
    s = re.sub(r'\.(mp3|flac|wav|m4a|aac|ogg|wma|opus|alac|mp4|mkv|webm)$', '', s, flags=re.IGNORECASE)
    # 2. 선두 대괄호/중괄호 태그 제거 (예: [워너뮤직코리아], [LMFAVEVO], [STARSHIP], [Reservoir_Recordings_])
    s = re.sub(r'^[\[\{].*?[\]\}]\s*', '', s)
    # 3. 선두 트랙 번호 제거 (예: '01 - ', '01. ', '1-02 ', '[01] ')
    s = re.sub(r'^(?:\[\d+\]|\d{1,3}[\s\.\-_]+)', '', s).strip()
    # 4. 대괄호/소괄호 안의 비디오/음원 수식어 제거
    bracket_junk = r'\[\s*(?:official|music\s*video|audio|mv|video|lyrics?|hd|4k|m\/v|full|remix|live|special\s*clip|visualizer|color\s*coded|hq|flac).*?\]'
    paren_junk = r'\(\s*(?:official|music\s*video|audio|mv|video|lyrics?|hd|4k|m\/v|full|live|special\s*clip|visualizer|color\s*coded|hq|flac|feat|ft).*?\)'
    s = re.sub(bracket_junk, '', s, flags=re.IGNORECASE)
    s = re.sub(paren_junk, '', s, flags=re.IGNORECASE)
    # 5. 비음악 단독 수식어 제거 (Norah Jones Don\'t Know Why HD FLAC QUALITY 등 대응)
    junk_words = [
        r'\bHD\b', r'\b4K\b', r'\bFLAC\b', r'\bQUALITY\b', r'\bOfficial\b', r'\bMusic Video\b',
        r'\b가사\b', r'\b번역\b', r'\b뮤직비디오\b', r'\bMV\b', r'\bAOL Sessions\b', r'\bHQ\b',
        r'\bAudio\b', r'\bLyrics\b'
    ]
    for j in junk_words:
        s = re.sub(j, '', s, flags=re.IGNORECASE)
    # 6. 밑줄 및 특수기호/연속 공백 정리
    s = s.replace('_', ' ')
    s = re.sub(r'["\']', '', s)
    s = re.sub(r'\s+', ' ', s).strip()
    return s

# [TAG: #@_fetch_online_music_cover]
def _fetch_online_music_cover(raw_name, abs_path=None):
    """[V191.5] YouTube 링크/태그 감지, 동일 비디오 연동 및 Deezer/iTunes 고화질 커버 100% 족집게 추출 🍏📺🎶✨"""
    import urllib.request, urllib.parse, json, re, os, subprocess
    if not raw_name and not abs_path:
        return None, None

    # 📺 0단계: YouTube 링크/ID 기반 공식 고화질 썸네일 초고속 추출 (0.05초 100% 성공 🎯)
    if abs_path and os.path.exists(abs_path):
        try:
            ffprobe_bin = _get_ffprobe_bin() if '_get_ffprobe_bin' in globals() else 'ffprobe'
            cmd = [ffprobe_bin, '-v', 'quiet', '-print_format', 'json', '-show_format', abs_path]
            startupinfo = None
            if os.name == 'nt':
                startupinfo = subprocess.STARTUPINFO()
                startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
                startupinfo.wShowWindow = 0
            res = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, startupinfo=startupinfo, timeout=1.5)
            if res.returncode == 0 and res.stdout:
                info = json.loads(res.stdout.decode('utf-8', errors='ignore'))
                tags = info.get('format', {}).get('tags', {})
                for field in ['comment', 'description', 'purl', 'synopsis']:
                    yt_id = _extract_youtube_id(tags.get(field, ''))
                    if yt_id:
                        yt_img = _fetch_youtube_thumbnail(yt_id)
                        if yt_img:
                            return 'image/jpeg', yt_img
        except Exception:
            pass

    # 파일명에서도 YouTube ID 검사
    yt_id_name = _extract_youtube_id(raw_name or (os.path.basename(abs_path) if abs_path else ''))
    if yt_id_name:
        yt_img = _fetch_youtube_thumbnail(yt_id_name)
        if yt_img:
            return 'image/jpeg', yt_img

    # 🎬 1단계: 동일 이름의 동영상 파일(.mp4, .mkv, .webm)이 존재하면 해당 키프레임 캡처 연동!
    if abs_path:
        try:
            base_no_ext = os.path.splitext(os.path.basename(abs_path))[0]
            cur_dir = os.path.dirname(abs_path)
            cand_dirs = [cur_dir]
            for opt_dir in [r"F:\music.video", r"D:\music.video", r"E:\music.video"]:
                if os.path.exists(opt_dir): cand_dirs.append(opt_dir)
            ff_bin = _get_ffmpeg_bin() if '_get_ffmpeg_bin' in globals() else 'ffmpeg'
            sinfo = None
            if os.name == 'nt':
                sinfo = subprocess.STARTUPINFO()
                sinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
                sinfo.wShowWindow = 0
            for cdir in cand_dirs:
                found_vid = False
                for ext in ['.mp4', '.mkv', '.webm', '.avi']:
                    vid_path = os.path.join(cdir, base_no_ext + ext)
                    if os.path.exists(vid_path) and os.path.isfile(vid_path):
                        cmd_vid = [ff_bin, '-nostats', '-loglevel', 'error', '-threads', '1', '-y', '-ss', '00:00:25', '-i', vid_path, '-an', '-sn', '-dn', '-vframes', '1', '-vf', "scale='min(480,iw)':-2", '-q:v', '3', '-pix_fmt', 'yuvj420p', '-f', 'image2', 'pipe:1']
                        r_vid = subprocess.run(cmd_vid, stdout=subprocess.PIPE, stderr=subprocess.PIPE, startupinfo=sinfo, timeout=3.0)
                        if r_vid.returncode == 0 and len(r_vid.stdout) > 1000:
                            _log_to_file(f"🎬 [Video Keyframe Linked] {base_no_ext} -> {os.path.basename(vid_path)}")
                            return 'image/jpeg', r_vid.stdout
                        found_vid = True
                        break
                if found_vid: break
        except Exception:
            pass

    # 🎵 2단계: 스마트 검색어 정제 및 쿼리 구성
    queries = []
    cleaned_title = _clean_music_title_for_search(raw_name or (os.path.basename(abs_path) if abs_path else ''))
    if cleaned_title and len(cleaned_title) >= 2:
        queries.append(cleaned_title)
        if ' - ' in cleaned_title:
            parts = cleaned_title.split(' - ', 1)
            artist_part = parts[0].strip()
            song_part = parts[1].strip()
            q_clean = f"{artist_part} {song_part}"
            if q_clean not in queries:
                queries.append(q_clean)

    # 3단계: ffprobe 메타 태그 힌트 추가 (단, 채널명 의심 문자열 제외)
    if abs_path and os.path.exists(abs_path):
        try:
            ffprobe_bin = _get_ffprobe_bin() if '_get_ffprobe_bin' in globals() else 'ffprobe'
            cmd = [ffprobe_bin, '-v', 'quiet', '-print_format', 'json', '-show_format', abs_path]
            startupinfo = None
            if os.name == 'nt':
                startupinfo = subprocess.STARTUPINFO()
                startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
                startupinfo.wShowWindow = 0
            res = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, startupinfo=startupinfo, timeout=1.5)
            if res.returncode == 0 and res.stdout:
                info = json.loads(res.stdout.decode('utf-8', errors='ignore'))
                tags = info.get('format', {}).get('tags', {})
                tag_map = {k.lower(): str(v).strip() for k, v in tags.items() if v}
                artist = tag_map.get('artist') or tag_map.get('album_artist') or ''
                title = tag_map.get('title') or ''
                # 채널명 의심 필터링
                channel_hints = ['tv', 'vevo', 'media', 'official', 'records', 'entertainment', 'korea', '채널', 'channel', 'club', 'topic']
                is_channel = any(h in artist.lower() for h in channel_hints) if artist else False
                if not is_channel and artist and title and artist.lower() not in title.lower():
                    q_tag = f"{artist} {title}"
                    if q_tag not in queries:
                        queries.append(q_tag)
                elif title:
                    clean_t = _clean_music_title_for_search(title)
                    if clean_t and clean_t not in queries:
                        queries.append(clean_t)
        except Exception:
            pass

    if not queries:
        return None, None

    headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)'}

    for q in queries:
        # 1차: Deezer Search API (무료, 안정적) 🎶
        try:
            deezer_url = f"https://api.deezer.com/search?q={urllib.parse.quote(q)}&limit=1"
            req_dz = urllib.request.Request(deezer_url, headers=headers)
            with urllib.request.urlopen(req_dz, timeout=3.0) as resp_dz:
                if resp_dz.status == 200:
                    payload = json.loads(resp_dz.read().decode('utf-8', errors='ignore'))
                    dz_results = payload.get('data', [])
                    if dz_results:
                        album_obj = dz_results[0].get('album') or {}
                        art_url_dz = album_obj.get('cover_big') or album_obj.get('cover_medium')
                        if art_url_dz:
                            img_req_dz = urllib.request.Request(art_url_dz, headers=headers)
                            with urllib.request.urlopen(img_req_dz, timeout=3.5) as img_resp_dz:
                                if img_resp_dz.status == 200:
                                    img_data_dz = img_resp_dz.read()
                                    if img_data_dz and len(img_data_dz) > 500:
                                        _log_to_file(f"🎶 [Deezer Cover Found] '{q}' -> {dz_results[0].get('title')} ({len(img_data_dz)} bytes)")
                                        return 'image/jpeg', img_data_dz
        except Exception:
            pass

        # 2차: Apple iTunes Search API (폴백) 🍏
        try:
            itunes_url = f"https://itunes.apple.com/search?term={urllib.parse.quote(q)}&entity=song&limit=1"
            req = urllib.request.Request(itunes_url, headers=headers)
            with urllib.request.urlopen(req, timeout=3.0) as resp:
                if resp.status == 200:
                    payload = json.loads(resp.read().decode('utf-8', errors='ignore'))
                    results = payload.get('results', [])
                    if results:
                        art_url = results[0].get('artworkUrl100', '')
                        if art_url:
                            for candidate_url in [art_url.replace('100x100bb', '600x600bb'), art_url]:
                                try:
                                    img_req = urllib.request.Request(candidate_url, headers=headers)
                                    with urllib.request.urlopen(img_req, timeout=3.5) as img_resp:
                                        if img_resp.status == 200:
                                            img_data = img_resp.read()
                                            if img_data and len(img_data) > 500:
                                                _log_to_file(f"🍏 [iTunes Cover Found] '{q}' -> {results[0].get('artistName')} - {results[0].get('trackName')} ({len(img_data)} bytes)")
                                                return 'image/jpeg', img_data
                                except Exception:
                                    continue
        except Exception:
            pass

    return None, None

# [TAG: #@_has_embedded_album_art]
_g_active_art_embeds = set()
_g_art_embed_lock = threading.Lock()

def _has_embedded_album_art(audio_path):
    """오디오 파일 내부에 이미 앨범 아트(attached_pic)가 포함되어 있는지 초고속(0.0001초) 검사 🔍🎵"""
    if not audio_path or not os.path.exists(audio_path):
        return False
    # 0단계: MP3 파일 초고속 바이너리 APIC 프레임 검사 (ffprobe 프로세스 생성 불필요, 0.0001초 반환 ⚡)
    ext = os.path.splitext(audio_path)[1].lower()
    if ext == '.mp3':
        try:
            with open(audio_path, 'rb') as f:
                header = f.read(131072)
            if b'APIC' in header:
                return True
        except Exception:
            pass

    # 1단계: ffprobe 기반 attached_pic 정밀 검사
    try:
        ffprobe_bin = _get_ffprobe_bin() if '_get_ffprobe_bin' in globals() else 'ffprobe'
        cmd = [
            ffprobe_bin, '-v', 'error',
            '-select_streams', 'v',
            '-show_entries', 'stream=codec_name,disposition:stream_disposition=attached_pic',
            '-of', 'json',
            audio_path
        ]
        sinfo = None
        if os.name == 'nt':
            sinfo = subprocess.STARTUPINFO()
            sinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
            sinfo.wShowWindow = 0
        res = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, startupinfo=sinfo, timeout=1.5)
        if res.returncode == 0 and res.stdout:
            data = json.loads(res.stdout.decode('utf-8', errors='ignore'))
            for stream in data.get('streams', []):
                disp = stream.get('disposition', {})
                if disp.get('attached_pic') == 1 or stream.get('codec_name') in ['mjpeg', 'png', 'jpeg']:
                    return True
    except Exception:
        pass
    return False

# [TAG: #@_embed_album_art_to_audio]
def _embed_album_art_to_audio(audio_path, image_data=None, image_path=None, source_video=None, overwrite=False):
    """[V191.6] MP3/오디오 파일에 앨범 아트를 무손실(-c:a copy)로 초고속(0.05초) 임베드 🎵🖼️✨
    1. image_data (바이트 스트림) 우선 사용
    2. image_path (로컬 이미지 경로) 사용
    3. source_video (동영상 파일)의 25초 키프레임 캡처 사용
    4. 모두 없으면 _fetch_online_music_cover(유튜브/Deezer/iTunes)로 고화질 커버 자동 검색/획득
    5. ffmpeg으로 원본 오디오를 재인코딩하지 않고 무손실 결합 후 원자적 교체
    """
    import tempfile, shutil
    if not audio_path or not os.path.exists(audio_path):
        return False

    # 이미 앨범 커버가 있고 overwrite가 아니면 스킵
    if not overwrite and _has_embedded_album_art(audio_path):
        return True

    # [Race Condition 방어] 동일 파일 동시 임베드 방지 가드 🛡️✨
    with _g_art_embed_lock:
        if audio_path in _g_active_art_embeds:
            return False
        _g_active_art_embeds.add(audio_path)

    ff_bin = _get_ffmpeg_bin() if '_get_ffmpeg_bin' in globals() else 'ffmpeg'
    sinfo = None
    if os.name == 'nt':
        sinfo = subprocess.STARTUPINFO()
        sinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
        sinfo.wShowWindow = 0

    temp_img_file = None
    temp_out = None
    try:
        # A. 이미지 데이터 준비
        img_bytes = None
        if image_data:
            img_bytes = image_data
        elif image_path and os.path.exists(image_path):
            try:
                with open(image_path, 'rb') as f:
                    img_bytes = f.read()
            except Exception:
                pass
        elif source_video and os.path.exists(source_video):
            # 동영상 25초 키프레임 캡처 시도
            try:
                cmd_v = [
                    ff_bin, '-nostats', '-loglevel', 'error', '-threads', '1', '-y',
                    '-ss', '00:00:25', '-i', source_video,
                    '-an', '-sn', '-dn', '-vframes', '1',
                    "-vf", "scale='min(600,iw)':-2",
                    '-q:v', '2', '-pix_fmt', 'yuvj420p', '-f', 'image2', 'pipe:1'
                ]
                r_v = subprocess.run(cmd_v, stdout=subprocess.PIPE, stderr=subprocess.PIPE, startupinfo=sinfo, timeout=4.0)
                if r_v.returncode == 0 and len(r_v.stdout) > 1000:
                    img_bytes = r_v.stdout
            except Exception:
                pass

        # B. 여전히 이미지가 없으면 온라인 커버 자동 검색 (유튜브 ID / 뮤비 키프레임 / Deezer / iTunes)
        if not img_bytes:
            raw_title = os.path.splitext(os.path.basename(audio_path))[0]
            _, img_bytes = _fetch_online_music_cover(raw_title, abs_path=audio_path)

        if not img_bytes or len(img_bytes) < 500:
            return False

        # C. 임시 이미지 파일 생성
        temp_dir = os.path.dirname(audio_path)
        with tempfile.NamedTemporaryFile(suffix='.jpg', dir=temp_dir, delete=False) as tf:
            temp_img_file = tf.name
            tf.write(img_bytes)

        # D. ffmpeg 무손실(-c:a copy) 결합
        ext = os.path.splitext(audio_path)[1].lower()
        temp_out = os.path.join(temp_dir, f"_temp_art_{os.getpid()}_{int(time.time()*1000)}{ext}")

        if ext == '.mp3':
            cmd_embed = [
                ff_bin, '-nostats', '-loglevel', 'error', '-y',
                '-i', audio_path,
                '-i', temp_img_file,
                '-map', '0:a',
                '-map', '1:0',
                '-c:a', 'copy',
                '-c:v', 'copy',
                '-id3v2_version', '3',
                '-metadata:s:v', 'title=Album cover',
                '-metadata:s:v', 'comment=Cover (front)',
                '-disposition:v:0', 'attached_pic',
                temp_out
            ]
        elif ext in ['.m4a', '.mp4']:
            cmd_embed = [
                ff_bin, '-nostats', '-loglevel', 'error', '-y',
                '-i', audio_path,
                '-i', temp_img_file,
                '-map', '0:a',
                '-map', '1:0',
                '-c:a', 'copy',
                '-c:v', 'copy',
                '-disposition:v:0', 'attached_pic',
                temp_out
            ]
        elif ext == '.flac':
            cmd_embed = [
                ff_bin, '-nostats', '-loglevel', 'error', '-y',
                '-i', audio_path,
                '-i', temp_img_file,
                '-map', '0:a',
                '-map', '1:0',
                '-c:a', 'copy',
                '-c:v', 'copy',
                '-disposition:v:0', 'attached_pic',
                temp_out
            ]
        else:
            cmd_embed = [
                ff_bin, '-nostats', '-loglevel', 'error', '-y',
                '-i', audio_path,
                '-i', temp_img_file,
                '-map', '0:a',
                '-map', '1:0',
                '-c:a', 'copy',
                '-c:v', 'copy',
                temp_out
            ]

        orig_stat = None
        try:
            orig_stat = os.stat(audio_path)
        except Exception:
            pass

        res_embed = subprocess.run(cmd_embed, stdout=subprocess.PIPE, stderr=subprocess.PIPE, startupinfo=sinfo, timeout=8.0)
        if res_embed.returncode == 0 and os.path.exists(temp_out) and os.path.getsize(temp_out) > len(img_bytes):
            # [Windows File Lock 방어] 최대 5회 안전 재시도 (0.1초 간격) 🛡️✨
            replaced = False
            for attempt in range(5):
                try:
                    shutil.move(temp_out, audio_path)
                    replaced = True
                    break
                except Exception:
                    time.sleep(0.1)

            if not replaced:
                _log_to_file(f"⚠️ [Embed Art Error] Failed to replace locked file: {audio_path}")
                return False

            if orig_stat:
                try:
                    os.utime(audio_path, (orig_stat.st_atime, orig_stat.st_mtime))
                except Exception:
                    pass
            _log_to_file(f"🎨 [Album Art Embedded] Successfully embedded art into: {os.path.basename(audio_path)} ({len(img_bytes)} bytes)")

            # DB 캐시 및 메모리 캐시 갱신
            try:
                target_path, mtime, key = _get_thumb_cache_key(audio_path)
                if key:
                    _put_thumb_to_mem(key, 'image/jpeg', img_bytes)
                    db_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "temp")
                    db_path = os.path.join(db_dir, "thumbnails.db")
                    conn = sqlite3.connect(db_path, timeout=3.0)
                    conn.execute("INSERT OR REPLACE INTO thumbnails (key, abs_path, mtime, mime_type, data) VALUES (?, ?, ?, ?, ?)",
                                 (key, target_path, mtime, 'image/jpeg', img_bytes))
                    conn.commit()
                    conn.close()
            except Exception:
                pass
            return True
        else:
            err_msg = res_embed.stderr.decode('utf-8', errors='ignore').strip() if res_embed.stderr else 'unknown'
            _log_to_file(f"⚠️ [Embed Art Failed] {os.path.basename(audio_path)}: ffmpeg rc={res_embed.returncode}, err={err_msg[:200]}")
            return False
    except Exception as e:
        _log_to_file(f"⚠️ [Embed Art Error] {audio_path}: {e}")
        return False
    finally:
        with _g_art_embed_lock:
            _g_active_art_embeds.discard(audio_path)
        if temp_img_file and os.path.exists(temp_img_file):
            try: os.remove(temp_img_file)
            except Exception: pass
        if temp_out and os.path.exists(temp_out):
            try: os.remove(temp_out)
            except Exception: pass

# [TAG: #@_get_or_create_thumbnail]
def _get_or_create_thumbnail(abs_path):
    """[V191.4] 동영상 및 오디오 파일 썸네일 3단계 초고속 룩업 & RAM LRU 캐시 기반 초안정 추출 ⚡🎬🎵"""
    import sqlite3, subprocess, hashlib
    audio_exts = ('.mp3', '.flac', '.wav', '.m4a', '.aac', '.ogg', '.wma', '.opus', '.alac')
    is_music_file = bool(abs_path and any(str(abs_path).lower().endswith(ext) for ext in audio_exts))

    if not abs_path:
        return 'image/svg+xml', _get_fallback_svg_thumbnail(is_music_file)

    if str(abs_path).startswith("gdrive://") or "://" in str(abs_path):
        return 'image/svg+xml', _get_fallback_svg_thumbnail(is_music_file)

    # 🚫 정확한 원본 경로에 파일이 없으면 없는 파일로 처리
    if not os.path.exists(abs_path) or not os.path.isfile(abs_path):
        return 'image/svg+xml', _get_fallback_svg_thumbnail(is_music_file)

    target_path, mtime, key = _get_thumb_cache_key(abs_path)
    if not key:
        return 'image/svg+xml', _get_fallback_svg_thumbnail(is_music_file)

    # 0. [V191.0] 메모리(RAM) LRU 캐시 최우선 확인 (디스크 I/O 0회, 0.00001초 반환 ⚡)
    mem_cached = _get_thumb_from_mem(key)
    if mem_cached:
        if mem_cached[0] == 'image/svg+xml;fallback' or not mem_cached[1]:
            return 'image/svg+xml', _get_fallback_svg_thumbnail(is_music_file)
        else:
            return mem_cached[0] or 'image/jpeg', mem_cached[1]

    db_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "temp")
    os.makedirs(db_dir, exist_ok=True)
    db_path = os.path.join(db_dir, "thumbnails.db")

    # 1. DB 캐시 조회 (1차: 신규 키 -> 2차: 구버전 키 -> 3차: abs_path 인덱스 0.0001초 초고속 바이패스 🛡️✨)
    conn = None
    try:
        conn = sqlite3.connect(db_path, timeout=5.0)
        conn.execute("PRAGMA cache_size = -32000;")
        cur = conn.cursor()
        cur.execute("SELECT mime_type, data FROM thumbnails WHERE key = ?", (key,))
        row = cur.fetchone()

        # [V191.2] 미스 시 구버전 키 및 abs_path 폴백 즉각 조회 (기존 3500개 썸네일 100% 무손실 구제)
        if not row:
            old_key = hashlib.sha1(f"{abs_path}_{mtime}".encode('utf-8')).hexdigest()
            cur.execute("SELECT mime_type, data FROM thumbnails WHERE key = ?", (old_key,))
            row = cur.fetchone()
            if not row:
                cur.execute("SELECT mime_type, data FROM thumbnails WHERE abs_path = ? COLLATE NOCASE LIMIT 1", (target_path,))
                row = cur.fetchone()
            # 구버전 키나 abs_path로 발견 시 신규 키로 즉시 DB 동기화
            if row and row[1]:
                try:
                    cur.execute("INSERT OR REPLACE INTO thumbnails (key, abs_path, mtime, mime_type, data) VALUES (?, ?, ?, ?, ?)",
                                (key, target_path, mtime, row[0], row[1]))
                    conn.commit()
                except Exception:
                    pass

        if row:
            # Negative cache (이전에 생성 실패했던 파일인 경우 바로 SVG 반환)
            if row[0] == 'image/svg+xml;fallback' or not row[1]:
                _put_thumb_to_mem(key, 'image/svg+xml;fallback', b'')
                return 'image/svg+xml', _get_fallback_svg_thumbnail(is_music_file)
            else:
                mime = row[0] or 'image/jpeg'
                _put_thumb_to_mem(key, mime, row[1])
                return mime, row[1]
    except Exception as e:
        _log_to_file(f"⚠️ [Thumbnail DB Read Error] {e}")
    finally:
        if conn:
            try: conn.close()
            except Exception: pass

    # 2. 동일 폴더 포스터/커버 이미지 우선 탐색 (세마포어 진입 전 디스크 직접 읽음)
    folder = os.path.dirname(target_path)
    base_no_ext = os.path.splitext(target_path)[0]
    candidate_images = [
        base_no_ext + '.jpg', base_no_ext + '.jpeg', base_no_ext + '.png', base_no_ext + '.webp',
        os.path.join(folder, 'poster.jpg'), os.path.join(folder, 'cover.jpg'), os.path.join(folder, 'folder.jpg'),
        os.path.join(folder, 'thumb.jpg'), os.path.join(folder, 'thumbnail.jpg'),
        os.path.join(folder, 'album.jpg'), os.path.join(folder, 'front.jpg'),
        os.path.join(folder, 'Cover.jpg'), os.path.join(folder, 'Folder.jpg'), os.path.join(folder, 'Poster.jpg')
    ]
    for c_img in candidate_images:
        if os.path.exists(c_img) and os.path.isfile(c_img):
            try:
                with open(c_img, 'rb') as f:
                    local_thumb_data = f.read()
                if local_thumb_data:
                    local_mime = 'image/jpeg'
                    c_lower = c_img.lower()
                    if c_lower.endswith('.png'): local_mime = 'image/png'
                    elif c_lower.endswith('.webp'): local_mime = 'image/webp'
                    # 로컬 커버 이미지를 찾았으면 DB 및 RAM에 캐싱하고 즉시 반환
                    _put_thumb_to_mem(key, local_mime, local_thumb_data)
                    conn = None
                    try:
                        conn = sqlite3.connect(db_path, timeout=5.0)
                        conn.execute("PRAGMA cache_size = -32000;")
                        conn.execute("INSERT OR REPLACE INTO thumbnails (key, abs_path, mtime, mime_type, data) VALUES (?, ?, ?, ?, ?)",
                                     (key, target_path, mtime, local_mime, local_thumb_data))
                        conn.commit()
                    except Exception:
                        pass
                    finally:
                        if conn:
                            try: conn.close()
                            except Exception: pass
                    return local_mime, local_thumb_data
            except Exception:
                pass

    # 3. 오디오 내장 커버 or 비디오 FFmpeg 키프레임 추출 (로컬 CPU 작업: 세마포어로 동시 실행 최대 2개 엄격 제한 🚥🛡️)
    thumb_data = None
    mime_type = 'image/jpeg'

    with _THUMBNAIL_SEMAPHORE:
        # 3-1. Double-Checked Locking (세마포어 대기 중 다른 스레드가 먼저 완료했는지 재확인)
        mem_cached = _get_thumb_from_mem(key)
        if mem_cached:
            if mem_cached[0] == 'image/svg+xml;fallback' or not mem_cached[1]:
                return 'image/svg+xml', _get_fallback_svg_thumbnail(is_music_file)
            else:
                return mem_cached[0] or 'image/jpeg', mem_cached[1]

        conn = None
        try:
            conn = sqlite3.connect(db_path, timeout=5.0)
            conn.execute("PRAGMA cache_size = -32000;")
            cur = conn.cursor()
            cur.execute("SELECT mime_type, data FROM thumbnails WHERE key = ?", (key,))
            row = cur.fetchone()
            if not row:
                old_key = hashlib.sha1(f"{abs_path}_{mtime}".encode('utf-8')).hexdigest()
                cur.execute("SELECT mime_type, data FROM thumbnails WHERE key = ?", (old_key,))
                row = cur.fetchone()
                if not row:
                    cur.execute("SELECT mime_type, data FROM thumbnails WHERE abs_path = ? COLLATE NOCASE LIMIT 1", (target_path,))
                    row = cur.fetchone()
                if row and row[1]:
                    try:
                        cur.execute("INSERT OR REPLACE INTO thumbnails (key, abs_path, mtime, mime_type, data) VALUES (?, ?, ?, ?, ?)",
                                    (key, target_path, mtime, row[0], row[1]))
                        conn.commit()
                    except Exception:
                        pass

            if row:
                if row[0] == 'image/svg+xml;fallback' or not row[1]:
                    _put_thumb_to_mem(key, 'image/svg+xml;fallback', b'')
                    return 'image/svg+xml', _get_fallback_svg_thumbnail(is_music_file)
                else:
                    mime = row[0] or 'image/jpeg'
                    _put_thumb_to_mem(key, mime, row[1])
                    return mime, row[1]
        except Exception:
            pass
        finally:
            if conn:
                try: conn.close()
                except Exception: pass

        try:
            ff = _get_ffmpeg_bin()
            startupinfo = None
            if os.name == 'nt':
                startupinfo = subprocess.STARTUPINFO()
                startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
                startupinfo.wShowWindow = 0  # SW_HIDE

            if is_music_file:
                # 🎵 1차: 오디오 파일 내장 앨범 아트(APIC / covr / attached_pic) 고속 추출 시도 (0.01초)
                cmd_audio = [
                    ff, '-nostats', '-loglevel', 'error', '-threads', '1',
                    '-y', '-i', target_path,
                    '-an', '-vf', "scale='min(480,iw)':-2", '-q:v', '3',
                    '-pix_fmt', 'yuvj420p',
                    '-f', 'image2', 'pipe:1'
                ]
                proc = subprocess.run(cmd_audio, stdout=subprocess.PIPE, stderr=subprocess.PIPE, startupinfo=startupinfo, timeout=5)
                if proc.returncode == 0 and proc.stdout:
                    thumb_data = proc.stdout
                    mime_type = 'image/jpeg'
            else:
                # 🎬 비디오 파일 초고속 키프레임 추출 (8K HEVC / VR 부하 원천 제거, 25초 우선 캡처 🚀)
                scale_filter = "scale='min(480,iw)':-2:flags=fast_bilinear"
                attempts = [
                    # 1차: 25초 지점 Fast keyframe seek (VR/고화질 본편 최적 🎯)
                    [ff, '-nostats', '-loglevel', 'error', '-hwaccel', 'auto', '-skip_frame', 'nokey', '-threads', '1', '-y', '-ss', '00:00:25', '-i', target_path, '-an', '-sn', '-dn', '-vframes', '1', '-vf', scale_filter, '-q:v', '3', '-pix_fmt', 'yuvj420p', '-f', 'image2', 'pipe:1'],
                    # 2차: 5초 지점 Fast keyframe seek
                    [ff, '-nostats', '-loglevel', 'error', '-hwaccel', 'auto', '-skip_frame', 'nokey', '-threads', '1', '-y', '-ss', '00:00:05', '-i', target_path, '-an', '-sn', '-dn', '-vframes', '1', '-vf', scale_filter, '-q:v', '3', '-pix_fmt', 'yuvj420p', '-f', 'image2', 'pipe:1'],
                    # 3차: 1초 지점 Fast keyframe seek (초단기 짤방/인트로)
                    [ff, '-nostats', '-loglevel', 'error', '-hwaccel', 'auto', '-skip_frame', 'nokey', '-threads', '1', '-y', '-ss', '00:00:01', '-i', target_path, '-an', '-sn', '-dn', '-vframes', '1', '-vf', scale_filter, '-q:v', '3', '-pix_fmt', 'yuvj420p', '-f', 'image2', 'pipe:1'],
                    # 4차: 첫 키프레임 직접 캡처
                    [ff, '-nostats', '-loglevel', 'error', '-hwaccel', 'auto', '-skip_frame', 'nokey', '-threads', '1', '-y', '-i', target_path, '-an', '-sn', '-dn', '-vframes', '1', '-vf', scale_filter, '-q:v', '3', '-pix_fmt', 'yuvj420p', '-f', 'image2', 'pipe:1'],
                ]
                for cmd in attempts:
                    try:
                        proc = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, startupinfo=startupinfo, timeout=4)
                        if proc.returncode == 0 and proc.stdout:
                            thumb_data = proc.stdout
                            mime_type = 'image/jpeg'
                            break
                    except Exception:
                        continue
        except Exception as e:
            _log_to_file(f"⚠️ [FFmpeg Thumbnail Error] {target_path}: {e}")

        # 로컬 추출 성공 시 (비디오 썸네일 또는 오디오 내장 태그 커버) 즉시 DB/RAM 캐시 저장 후 반환
        if thumb_data:
            conn = None
            try:
                conn = sqlite3.connect(db_path, timeout=5.0)
                conn.execute("PRAGMA cache_size = -32000;")
                conn.execute("INSERT OR REPLACE INTO thumbnails (key, abs_path, mtime, mime_type, data) VALUES (?, ?, ?, ?, ?)",
                             (key, target_path, mtime, mime_type, thumb_data))
                conn.commit()
                _put_thumb_to_mem(key, mime_type, thumb_data)
            except Exception as e:
                _log_to_file(f"⚠️ [Thumbnail DB Write Error] {e}")
            finally:
                if conn:
                    try: conn.close()
                    except Exception: pass
            return mime_type, thumb_data

        # 비디오 파일인데 로컬 추출 실패한 경우: 세마포어 내에서 바로 Negative Cache 저장 후 종료
        if not is_music_file:
            conn = None
            try:
                conn = sqlite3.connect(db_path, timeout=5.0)
                conn.execute("PRAGMA cache_size = -32000;")
                conn.execute("INSERT OR REPLACE INTO thumbnails (key, abs_path, mtime, mime_type, data) VALUES (?, ?, ?, ?, ?)",
                             (key, target_path, mtime, 'image/svg+xml;fallback', b''))
                conn.commit()
                _put_thumb_to_mem(key, 'image/svg+xml;fallback', b'')
            except Exception as e:
                _log_to_file(f"⚠️ [Thumbnail DB Write Error] {e}")
            finally:
                if conn:
                    try: conn.close()
                    except Exception: pass
            return 'image/svg+xml', _get_fallback_svg_thumbnail(is_music_file)

    # 4. [V191.4] 오디오 파일 전용 외부 글로벌 음원 DB(Apple iTunes / Deezer) 자동 검색 🍏🎶✨
    # 🚥 중요: 세마포어 블록을 빠져나와 실행되므로, 네트워크 HTTP 요청이 동시 2개 CPU 세마포어를 점유하지 않아 병렬로 초고속 처리됨!
    if is_music_file:
        fname = os.path.basename(target_path)
        online_mime, online_data = _fetch_online_music_cover(fname, target_path)
        if online_data:
            thumb_data = online_data
            mime_type = online_mime or 'image/jpeg'

        # 음원 결과 DB 및 RAM에 저장 (성공 시 고화질 커버, 실패 시 Negative Cache 마킹)
        conn = None
        try:
            conn = sqlite3.connect(db_path, timeout=5.0)
            conn.execute("PRAGMA cache_size = -32000;")
            if thumb_data:
                conn.execute("INSERT OR REPLACE INTO thumbnails (key, abs_path, mtime, mime_type, data) VALUES (?, ?, ?, ?, ?)",
                             (key, target_path, mtime, mime_type, thumb_data))
                conn.commit()
                _put_thumb_to_mem(key, mime_type, thumb_data)
                # [V191.6] 오디오 파일 자체에도 앨범 아트를 비동기로 자동 임베드 (음악 플레이어/탐색기 커버 표시) 🎨🎧✨
                try:
                    threading.Thread(target=_embed_album_art_to_audio, args=(target_path,), kwargs={'image_data': thumb_data, 'overwrite': False}, daemon=True).start()
                except Exception:
                    pass
                return mime_type, thumb_data
            else:
                # 🛡️ 실패한 파일도 Negative Cache 저장하여 매 요청마다 불필요한 온라인 재검색 완전 방지!
                conn.execute("INSERT OR REPLACE INTO thumbnails (key, abs_path, mtime, mime_type, data) VALUES (?, ?, ?, ?, ?)",
                             (key, target_path, mtime, 'image/svg+xml;fallback', b''))
                conn.commit()
                _put_thumb_to_mem(key, 'image/svg+xml;fallback', b'')
        except Exception as e:
            _log_to_file(f"⚠️ [Thumbnail DB Write Error] {e}")
        finally:
            if conn:
                try: conn.close()
                except Exception: pass

    # 5. 실패 시 기본 SVG 플레이스홀더 반환 (오디오는 Spotify 감성 SVG 🎵)
    return 'image/svg+xml', _get_fallback_svg_thumbnail(is_music_file)

# [TAG: #@_save_thumbnail_data_db]
def _save_thumbnail_data_db(abs_path, image_bytes, mime_type='image/jpeg'):
    """[V191.1] 시청 종료 시점의 캡처 썸네일 데이터를 temp/thumbnails.db 에 영구 업데이트 🖼️💾✨"""
    if not abs_path or not image_bytes: return False
    conn = None
    try:
        import sqlite3
        norm_p, mtime, key = _get_thumb_cache_key(abs_path)
        if not key: return False
        
        base_dir = globals().get('BASE_DIR') or (os.path.dirname(os.path.abspath(__file__)) if '__file__' in globals() else os.getcwd())
        db_dir = os.path.join(base_dir, "temp")
        os.makedirs(db_dir, exist_ok=True)
        db_path = os.path.join(db_dir, "thumbnails.db")

        conn = sqlite3.connect(db_path, timeout=5.0)
        conn.execute("PRAGMA cache_size = -32000;")
        conn.execute("INSERT OR REPLACE INTO thumbnails (key, abs_path, mtime, mime_type, data) VALUES (?, ?, ?, ?, ?)",
                     (key, norm_p, mtime, mime_type, image_bytes))
        conn.commit()
        # [V191.0] RAM LRU 캐시에도 동시 갱신
        _put_thumb_to_mem(key, mime_type, image_bytes)
        _log_to_file(f"📸 [Thumbnail DB Update] 시청 시점 썸네일 저장 완료: {os.path.basename(norm_p)} ({len(image_bytes)} bytes)")
        return True
    except Exception as e:
        _log_to_file(f"⚠️ [Save Thumbnail Data DB Error] {e}")
        return False
    finally:
        if conn:
            try: conn.close()
            except Exception: pass

# [TAG: #@_run_thumbnail_db_gc]
def _run_thumbnail_db_gc(force=False, verbose=False):
    """[V191.1] temp/thumbnails.db 스마트 가비지 컬렉션 및 용량 다이어트 (외장하드 분리 보호 & VACUUM) 🧼🗄️✨"""
    import os, time, json, sqlite3
    base_dir = globals().get('BASE_DIR') or (os.path.dirname(os.path.abspath(__file__)) if '__file__' in globals() else os.getcwd())
    db_dir = os.path.join(base_dir, "temp")
    db_path = os.path.join(db_dir, "thumbnails.db")
    state_file = os.path.join(db_dir, "thumbnail_gc_state.json")

    if not os.path.exists(db_path):
        return {"status": "no_db", "cleaned_count": 0, "size_before": 0, "size_after": 0}

    now = time.time()
    try:
        size_before = os.path.getsize(db_path)
    except Exception:
        size_before = 0

    # 쿨타임(7일) 체크 (force=True가 아닐 때)
    if not force and os.path.exists(state_file):
        try:
            with open(state_file, 'r', encoding='utf-8') as f:
                state = json.load(f)
            last_cleaned = state.get("last_cleaned_at", 0)
            # 7일(604800초) 미만이고 DB 크기가 100MB 미만이면 안전하게 스킵
            if (now - last_cleaned < 604800) and (size_before < 100 * 1024 * 1024):
                if verbose:
                    _log_to_file(f"🧹 [Thumbnail GC] 쿨타임 미경과 (최근 정리: {int((now-last_cleaned)//3600)}시간 전, 크기: {size_before//(1024*1024)}MB) - 스킵!")
                return {"status": "skipped", "reason": "cooldown", "size_before": size_before}
        except Exception:
            pass

    cleaned_count = 0
    vacuum_done = False
    conn = None
    try:
        conn = sqlite3.connect(db_path, timeout=15.0)
        conn.execute("PRAGMA journal_mode=WAL;")
        conn.execute("PRAGMA cache_size = -32000;")
        cur = conn.cursor()

        # 1. 실제 파일이 삭제된 고아(Orphan) 썸네일 검사 (외장드라이브 오탐지 방지 🛡️)
        cur.execute("SELECT key, abs_path FROM thumbnails")
        rows = cur.fetchall()
        orphan_keys = []
        for r_key, r_path in rows:
            if not r_path or r_path.startswith("gdrive://") or "://" in r_path:
                continue
            # 🛡️ 외장 드라이브/USB/네트워크 마운트 해제 감지 보호
            drive, _ = os.path.splitdrive(r_path)
            if drive:
                drive_root = drive + '\\' if not drive.endswith('\\') else drive
                if not os.path.exists(drive_root):
                    # 드라이브 자체가 연결 해제된 상태라면 영상 삭제로 보지 않고 보존!
                    continue
            if not os.path.exists(r_path):
                orphan_keys.append((r_key,))

        if orphan_keys:
            cur.executemany("DELETE FROM thumbnails WHERE key = ?", orphan_keys)
            cleaned_count = len(orphan_keys)
            conn.commit()
            # [V191.1] RAM 캐시에서도 삭제된 고아 키 동기화 제거
            with _g_thumb_cache_lock:
                for (k,) in orphan_keys:
                    _g_thumb_mem_cache.pop(k, None)
            _log_to_file(f"🧹 [Thumbnail GC] 실제 삭제된 영상의 고아 썸네일 {cleaned_count}개 청소 완료! 🧼")

        # 2. 크기가 100MB 이상이거나 30개 이상 정리되었을 때 WAL 체크포인트 & VACUUM 수행
        if cleaned_count >= 30 or size_before >= 100 * 1024 * 1024 or force:
            _log_to_file(f"🗄️ [Thumbnail GC] DB 최적화 VACUUM 시작 (정리 전: {size_before // 1024} KB)...")
            try:
                conn.execute("PRAGMA wal_checkpoint(TRUNCATE);")
            except Exception:
                pass
            conn.execute("VACUUM;")
            vacuum_done = True

        conn.close()
        conn = None

        # 3. 정리 후 크기 측정 및 상태 저장
        size_after = os.path.getsize(db_path) if os.path.exists(db_path) else 0
        diff_mb = (size_before - size_after) / (1024 * 1024)
        _log_to_file(f"✨ [Thumbnail GC] 완료: {cleaned_count}개 삭제, 용량: {size_before//(1024*1024)}MB -> {size_after//(1024*1024)}MB (절감: {diff_mb:.1f}MB, VACUUM: {vacuum_done}) 👍")

        try:
            with open(state_file, 'w', encoding='utf-8') as f:
                json.dump({
                    "last_cleaned_at": now,
                    "last_cleaned_date": time.strftime("%Y-%m-%d %H:%M:%S"),
                    "cleaned_count": cleaned_count,
                    "size_before_bytes": size_before,
                    "size_after_bytes": size_after,
                    "vacuum_done": vacuum_done
                }, f, ensure_ascii=False, indent=2)
        except Exception:
            pass

        return {
            "status": "success",
            "cleaned_count": cleaned_count,
            "size_before": size_before,
            "size_after": size_after,
            "diff_mb": diff_mb,
            "vacuum_done": vacuum_done
        }
    except Exception as e:
        _log_to_file(f"⚠️ [Thumbnail GC Error] {e}")
        return {"status": "error", "error": str(e)}
    finally:
        if conn:
            try: conn.close()
            except Exception: pass

# [TAG: #@_schedule_thumbnail_db_gc]
def _schedule_thumbnail_db_gc():
    """[V191.0] 백그라운드 데몬 스레드로 비동기 썸디비 가비지 컬렉터 구동 🚀"""
    import threading
    threading.Thread(target=_run_thumbnail_db_gc, kwargs={'force': False, 'verbose': False}, daemon=True).start()

# [TAG: #@_probe_video_vr_by_stream]
def _probe_video_vr_by_stream(filepath: str) -> str:
    """[V191.4] ffprobe를 이용해 비디오 해상도 및 화면비를 초고속 분석하여 VR 포맷 추적 (4K/8K 2:1 와이드 -> vr180_sbs) 🥽🎥"""
    try:
        if not filepath or not os.path.isfile(filepath):
            return '2d'
        ffprobe_bin = _get_ffprobe_bin() if '_get_ffprobe_bin' in globals() else 'ffprobe'
        cmd = [
            ffprobe_bin,
            "-v", "error",
            "-select_streams", "v:0",
            "-show_entries", "stream=width,height,side_data_list",
            "-of", "json",
            filepath
        ]
        import subprocess, json
        res = subprocess.run(cmd, capture_output=True, text=True, timeout=5, creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))
        if res.returncode == 0 and res.stdout:
            data = json.loads(res.stdout)
            streams = data.get('streams', [])
            if streams:
                st = streams[0]
                w = int(st.get('width', 0) or 0)
                h = int(st.get('height', 0) or 0)
                if w > 0 and h > 0:
                    ratio = w / h
                    # 1) stereoscopic side_data 메타데이터가 명시된 경우
                    side_data = st.get('side_data_list', [])
                    for sd in side_data:
                        side_type = str(sd.get('side_data_type', '')).lower()
                        if 'stereo' in side_type:
                            st_mode = str(sd.get('type', '')).lower()
                            if 'side' in st_mode or 'left_right' in st_mode:
                                return 'vr180_sbs'
                    # 2) 4K/8K 해상도이면서 정확히 2:1 와이드 (1.95 ~ 2.05)인 경우 (DeoVR/VR180 SBS 마스터 표준)
                    if w >= 3840 and (1.95 <= ratio <= 2.05):
                        return 'vr180_sbs'
                    # 3) 비주류 OU 계열은 자동 감지 완전 스킵 (2D 영상 안전 보호) 🛡️✨
    except Exception:
        pass
    return '2d'

# [TAG: #@detect_video_vr_mode]
def detect_video_vr_mode(filepath: str, vr_meta_map: dict = None, allow_probe: bool = False) -> str:
    """[V191.4] 파일명 및 DB 캐시 기반 3D/VR 초고속 판별 (대량 목록 조회 시 ffprobe 차단으로 0.0001초 반환) 🥽🎬✨"""
    if not filepath:
        return '2d'
    try:
        # 1. 일괄 맵 또는 DB에서 사용자 수동 지정 VR 포맷 최우선 확인! 🥇
        if vr_meta_map is not None:
            norm_k = os.path.normpath(str(filepath)).lower()
            saved_db_fmt = vr_meta_map.get(norm_k)
        else:
            saved_db_fmt = _get_saved_vr_format_from_db(filepath)
        if saved_db_fmt:
            return saved_db_fmt

        import re
        p_raw = str(filepath)
        # 🛡️ [비누 요청 100% 반영] 전체 폴더 경로로 인한 2D 영상 오탐 원천 방지: 순수 파일명 우선 추출!
        f_raw = os.path.basename(p_raw)
        if not f_raw:
            f_raw = p_raw
        f_name = f_raw.lower()

        # 🥽 [비누 핵심 힌트 반영] 대문자 VR 키워드 정밀 분석 (\bVR\b, 8KVR, 4KVR, VR캠, 3D VR 등)
        has_capital_vr = bool(re.search(r'(?:\bVR\b|\b[48]KVR\b|\bVR캠\b|3D\s*VR|VR\s*3D)', f_raw))

        # 2. 180 VR 감지 (vr180, 180vr, 3d 180, 180°, 180도 등) -> 180은 100% vr180_sbs로 일원화 (비주류 OU 스킵)
        has_180 = bool(re.search(r'(?:vr\s*180|180\s*vr|3d\s*180|180\s*3d|180[°도]|vr180|180vr|3d180|180x180|180[ _.-]?deg|180[ _.-]?(?:sbs|lr|3dh)|(?:\b|_|-)180(?:\b|_|-)(?:sbs|lr|vr|3dh))', f_name))
        
        # 🛡️ 단순 에피소드 360화, 360p 해상도 오탐 방지: VR360 전용 패턴만 엄격 매칭!
        has_360 = bool(re.search(r'(?:vr\s*360|360\s*vr|3d\s*360|360\s*3d|360[°도]|vr360|3d360|360vr|360[ _.-]?deg|360[ _.-]?(?:sbs|lr|3d)|(?:\b|_|-)360(?:\b|_|-)(?:sbs|lr|vr|3d)|pano|equirect)', f_name))

        # 🥽 [비누 요청 100% 반영] 비주류 3D OU(Over-Under) 계열은 자동 감지 완전 스킵!
        # 명시적 OU 키워드가 들어있는 경우 SBS로 잘못 왜곡 재생되지 않도록 기본 2D로 안전하게 보호 🛡️✨
        is_ou = bool(re.search(r'(?:_ou_|_tb_|_ou\b|_tb\b|\[ou\]|\[tb\]|\(ou\)|\(tb\)|\.ou\.|\.tb\.|top[-_.]?bottom|over[-_.]?under|half[-_.]?ou|half[-_.]?tb|(?:\b|_)h[-_.]ou(?:\b|_)|3d[-_.]?ou|3d[-_.]?tb)', f_name))
        if is_ou:
            return '2d'

        is_sbs = bool(re.search(r'(?:_sbs_|_lr_|_sbs\b|_lr\b|\[sbs\]|\[lr\]|\(sbs\)|\.sbs\.|side[-_.]?by[-_.]?side|half[-_.]?sbs|(?:\b|_)h[-_.]sbs(?:\b|_)|3d[-_.]?sbs|3dh)', f_name))

        if has_180:
            return 'vr180_sbs'

        if has_360:
            # 🌐 [비누 요청 100% 반영] 360 VR 영상은 기본 360 모노(2D 파노라마)로 재생!
            return 'vr360_mono'

        # 대문자 VR 키워드가 확인된 경우 (DeoVR 및 VR 콘텐츠 대부분 SBS 180VR)
        if has_capital_vr:
            if has_360:
                return 'vr360_mono'
            return 'vr180_sbs'

        # 3D 입체 영화 감지 (SBS 및 3D 영화 태그) -> 100% cinema_3d_sbs 로 일원화 (3D OU는 실생활 전무하여 스킵)
        if is_sbs or re.search(r'(?:[\._\-\[\(]3d[\._\-\]\)]|\b3d-movie\b|\b3d-bluray\b)', f_name):
            return 'cinema_3d_sbs'

        # 🥽 xxxvr숫자 / vrxxx숫자 품번 패턴 (예: ajvr00228, crvr00406, devr00039, dsvr01828, vrkm01722 등)
        if re.search(r'(?:^|[^a-z0-9])(?:[a-z0-9]{1,8}vr(?:sp)?|vr[a-z0-9]{1,8})[-_]?[0-9]{2,6}(?:[^a-z0-9]|$)', f_name):
            return 'vr180_sbs'

        # 🥽 특수 VR 전문 제작사 및 브랜드 레이블 (단순 3글자 약어 단독 매칭 방지: 품번 숫자 결합 필수)
        if re.search(r'(?:^|[^a-z0-9])(?:aqugl|svace|fsvss|vrbangers|wankzvr|stripzvr|sexlikereal)(?:[-_]?[0-9]{2,6}|[^a-z0-9]|$)|(?:^|[^a-z0-9])(?:bvr|vrb)[-_]?[0-9]{2,6}(?:[^a-z0-9]|$)', f_name):
            return 'vr180_sbs'

        # 🔍 [영상 추적 방식] allow_probe=True인 경우에만 실제 영상 스트림 해상도 검사 (대량 목록 조회 시 무거운 ffprobe 동기 호출 완전 차단) 🎥✨
        if allow_probe and os.path.isfile(p_raw) and p_raw.lower().endswith(('.mp4', '.mkv', '.mov', '.webm', '.ts')):
            detected_mode = _probe_video_vr_by_stream(p_raw)
            if detected_mode:
                try:
                    _save_vr_format_data_db(p_raw, detected_mode)
                except Exception:
                    pass
                return detected_mode
    except Exception:
        pass
    return '2d'

# [TAG: #@_save_vr_format_data_db]
def _save_vr_format_data_db(abs_path, vr_format):
    """[V185.0] 사용자가 수동 변경한 VR 포맷 정보를 temp/thumbnails.db의 video_vr_meta 테이블에 영구 저장 🥽💾✨"""
    if not abs_path or not vr_format: return False
    try:
        import sqlite3, time
        norm_p = os.path.abspath(abs_path)
        base_dir = globals().get('BASE_DIR') or (os.path.dirname(os.path.abspath(__file__)) if '__file__' in globals() else os.getcwd())
        db_dir = os.path.join(base_dir, "temp")
        os.makedirs(db_dir, exist_ok=True)
        db_path = os.path.join(db_dir, "thumbnails.db")

        with sqlite3.connect(db_path, timeout=5.0) as conn:
            conn.execute("""
                CREATE TABLE IF NOT EXISTS video_vr_meta (
                    abs_path TEXT PRIMARY KEY,
                    vr_format TEXT NOT NULL,
                    updated_at REAL NOT NULL
                )
            """)
            conn.execute("""
                INSERT OR REPLACE INTO video_vr_meta (abs_path, vr_format, updated_at)
                VALUES (?, ?, ?)
            """, (norm_p, str(vr_format).strip(), time.time()))
            conn.commit()
        _log_to_file(f"🥽 [VR Meta DB Update] VR 포맷 저장 완료: {os.path.basename(norm_p)} -> {vr_format}")
        return True
    except Exception as e:
        _log_to_file(f"⚠️ [Save VR Format DB Error] {e}")
        return False

_G_VR_FORMATS_CACHE = {"ts": 0.0, "data": {}}

# [TAG: #@_get_all_vr_formats_db]
def _get_all_vr_formats_db():
    """[V191.2] temp/thumbnails.db에서 모든 VR 포맷 메타데이터를 1회 일괄 딕셔너리로 초고속 반환 (N+1 병목 완전 제거) 🥽⚡ (3초 메모리 캐싱)"""
    global _G_VR_FORMATS_CACHE
    import time
    now = time.time()
    if now - _G_VR_FORMATS_CACHE.get("ts", 0.0) < 3.0:
        return _G_VR_FORMATS_CACHE.get("data", {})
    result = {}
    try:
        import sqlite3
        base_dir = globals().get('BASE_DIR') or (os.path.dirname(os.path.abspath(__file__)) if '__file__' in globals() else os.getcwd())
        db_path = os.path.join(base_dir, "temp", "thumbnails.db")
        if not os.path.exists(db_path): return result

        conn = None
        try:
            conn = sqlite3.connect(db_path, timeout=3.0)
            conn.execute("PRAGMA cache_size = -32000;")
            cur = conn.cursor()
            cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='video_vr_meta'")
            if cur.fetchone():
                cur.execute("SELECT abs_path, vr_format FROM video_vr_meta")
                for r_path, r_vf in cur.fetchall():
                    if r_path and r_vf:
                        result[os.path.normpath(r_path).lower()] = str(r_vf).strip()
            _G_VR_FORMATS_CACHE = {"ts": now, "data": result}
        finally:
            if conn:
                try: conn.close()
                except Exception: pass
    except Exception:
        pass
    return result

# [TAG: #@_get_saved_vr_format_from_db]
def _get_saved_vr_format_from_db(abs_path):
    """[V185.0] temp/thumbnails.db에서 저장된 비디오의 VR 포맷 조회 🥽🔍"""
    if not abs_path: return None
    try:
        import sqlite3
        norm_p = os.path.abspath(abs_path)
        base_dir = globals().get('BASE_DIR') or (os.path.dirname(os.path.abspath(__file__)) if '__file__' in globals() else os.getcwd())
        db_path = os.path.join(base_dir, "temp", "thumbnails.db")
        if not os.path.exists(db_path): return None

        conn = None
        try:
            conn = sqlite3.connect(db_path, timeout=3.0)
            cursor = conn.cursor()
            cursor.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='video_vr_meta'")
            if not cursor.fetchone(): return None
            cursor.execute("SELECT vr_format FROM video_vr_meta WHERE abs_path = ? COLLATE NOCASE LIMIT 1", (norm_p,))
            row = cursor.fetchone()
            if row and row[0]:
                return str(row[0]).strip()
        finally:
            if conn:
                try: conn.close()
                except Exception: pass
    except Exception:
        pass
    return None

# [TAG: #@_capture_thumbnail_at_pos_ffmpeg]
def _capture_thumbnail_at_pos_ffmpeg(abs_path, pos):
    """[V184.0] FFmpeg로 시청 시점(초) 프레임을 백그라운드 캡처하여 썸디비에 비동기 저장 🎬⚡"""
    def _worker():
        try:
            if not abs_path or not os.path.exists(abs_path): return
            ff = _get_ffmpeg_bin()
            startupinfo = None
            if os.name == 'nt':
                startupinfo = subprocess.STARTUPINFO()
                startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
                startupinfo.wShowWindow = 0
            
            pos_sec = max(1.0, float(pos or 0))
            scale_filter = "scale='min(480,iw)':-2:flags=fast_bilinear"
            cmd = [
                ff, '-nostats', '-loglevel', 'error', '-hwaccel', 'auto',
                '-threads', '1', '-y', '-ss', str(pos_sec), '-i', abs_path,
                '-an', '-sn', '-dn', '-vframes', '1', '-vf', scale_filter,
                '-q:v', '3', '-pix_fmt', 'yuvj420p', '-f', 'image2', 'pipe:1'
            ]
            proc = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, startupinfo=startupinfo, timeout=6)
            if proc.returncode == 0 and proc.stdout:
                _save_thumbnail_data_db(abs_path, proc.stdout, 'image/jpeg')
        except Exception as e:
            _log_to_file(f"⚠️ [Async FFmpeg Pos Thumbnail Error] {abs_path} @ {pos}s: {e}")

    threading.Thread(target=_worker, daemon=True).start()


# [TAG: #@_get_local_ip]

def _get_local_ip():
    """공유기 내부 IP 주소를 자동으로 알아냅니다."""
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        s.connect(('8.8.8.8', 80))
        ip = s.getsockname()[0]
    except Exception:
        ip = '127.0.0.1'
    finally:
        s.close()
    return ip

