      { id: 'slide', name: '슬라이드', icon: '↔️', desc: '쇼츠/틱톡 스타일 스와이프' },
      { id: 'vortex', name: '볼텍스 줌', icon: '🌀', desc: '역동적 회전 & 줌인' },
