    # [TAG: #@api_conn_ssh_input]
    def api_conn_ssh_input():
        """브라우저 키 입력 → 원격 셸 전달 ⌨️ (UTF-8 → 서버 charmap 역변환)"""
        from flask import jsonify, request
        try:
            data = request.get_json(force=True, silent=True) or request.form or {}
            sid = str(data.get('sid', '') or '')
            sess = _conn_ssh_session(sid)
            if not sess:
                return jsonify({"success": False, "error": "세션이 없거나 만료되었어!"}), 404
            blocked, code = _conn_access_guard(sess.get('group', ''))
            if blocked is not None:
                return blocked, code
            ok, err = _conn_ssh_write(sid, data.get('data', ''))
            return jsonify({"success": bool(ok), "error": err}), (200 if ok else 400)
        except Exception as e:
            return jsonify({"success": False, "error": str(e)}), 500

