    @app.route('/api/tui/action', methods=['POST'])
    # [TAG: #@api_tui_action]
    def api_tui_action():
        """Web TUI 메뉴 클릭 또는 가상 제어 키 전송 🚀📥"""
        from flask import jsonify, request
        try:
            data = request.get_json(force=True, silent=True) or request.form or {}
            special = str(data.get('special') or '').strip().upper()
            raw_key = data.get('key')
            idx = data.get('idx')
            hotkey = data.get('hotkey')

            action = str(data.get('action') or '').strip().lower()
            if action in ('prompt_input', 'input'):
                text = str(data.get('text') or '')
                is_cancel = bool(data.get('cancel', False))
                wpf = globals().get('_web_prompt_future')
                if wpf is not None and not wpf.done():
                    wpf.set_result('' if is_cancel else text)
                    return jsonify({"success": True, "len": len(text), "via": "web_prompt_future"})
                rif = globals().get('_remote_input_future')
                if rif is not None and not rif.done():
                    rif.set_result('' if is_cancel else text)
                    return jsonify({"success": True, "len": len(text), "via": "remote_input_future"})
                if is_cancel:
                    _push_virtual_key('\x1b')
                else:
                    for ch in text:
                        _push_virtual_key(ch)
                    _push_virtual_key('\r')
                return jsonify({"success": True, "len": len(text), "via": "virtual_keys"})

            if special:
                special_map = {
                    'UP': ('\xe0', 'H'),
                    'DOWN': ('\xe0', 'P'),
                    'LEFT': ('\xe0', 'K'),
                    'RIGHT': ('\xe0', 'M'),
                    'ENTER': ('\r',),
                    'ESC': ('\x1b',),
                    'BACKSPACE': ('\x08',),
                    'TAB': ('\t',),
                    'SPACE': (' ',),
                    'HOME': ('\xe0', 'G'),
                    'END': ('\xe0', 'O'),
                    'PAGEUP': ('\xe0', 'I'),
                    'PAGEDOWN': ('\xe0', 'Q'),
                    'DELETE': ('\xe0', 'S'),
                    'INSERT': ('\xe0', 'R'),
                    'SHIFT_UP': ('\xe0', '\x98'),
                    'SHIFT_DOWN': ('\xe0', '\xa0'),
                    'CTRL_UP': ('\xe0', '\x8d'),
                    'CTRL_DOWN': ('\xe0', '\x91'),
                    'F1': ('\x00', ';'),
                    'F2': ('\x00', '<'),
                    'F3': ('\x00', '='),
                    'F4': ('\x00', '>'),
                    'F5': ('\x00', '?'),
                }
                if special in special_map:
                    for k in special_map[special]:
                        _push_virtual_key(k)
                    return jsonify({"success": True, "pushed": special})

            if idx is not None:
                idx_val = int(idx)
                globals()['_remote_cmd'] = f"select:{idx_val}"
                return jsonify({"success": True, "selected_idx": idx_val})

            if hotkey:
                for ch in str(hotkey):
                    _push_virtual_key(ch)
                return jsonify({"success": True, "pushed_hotkey": hotkey})

            if raw_key:
                for ch in str(raw_key):
                    _push_virtual_key(ch)
                return jsonify({"success": True, "pushed_key": raw_key})

            return jsonify({"success": False, "error": "No action payload"}), 400
        except Exception as e:
            return jsonify({"success": False, "error": str(e)}), 500

    @app.route('/api/tui/input', methods=['POST'])
    # [TAG: #@api_tui_input]
    def api_tui_input():
        """Web TUI 프롬프트 텍스트 입력 전송 📝📥"""
        from flask import jsonify, request
        try:
            data = request.get_json(force=True, silent=True) or request.form or {}
            text = str(data.get('text') or '')
            is_cancel = bool(data.get('cancel', False))

            # 1. 🌐 _web_prompt_future가 활성화되어 있다면 즉시 결과 전달!
            wpf = globals().get('_web_prompt_future')
            if wpf is not None and not wpf.done():
                wpf.set_result('' if is_cancel else text)
                return jsonify({"success": True, "len": len(text), "via": "web_prompt_future"})

            # 2. 텔레그램/원격 퓨처가 있다면 전달
            rif = globals().get('_remote_input_future')
            if rif is not None and not rif.done():
                rif.set_result('' if is_cancel else text)
                return jsonify({"success": True, "len": len(text), "via": "remote_input_future"})

            # 3. Fallback: 가상 키 버퍼로 주입
            if is_cancel:
                _push_virtual_key('\x1b')  # ESC
            else:
                for ch in text:
                    _push_virtual_key(ch)
                _push_virtual_key('\r')
            return jsonify({"success": True, "len": len(text), "via": "virtual_keys"})
        except Exception as e:
            return jsonify({"success": False, "error": str(e)}), 500

