    @app.route('/api/console/stream')
    # [TAG: #@api_console_stream]
    def api_console_stream():
        """콘솔 stdout/stderr 출력을 웹 SSE 로 실시간 스트리밍 📡📺"""
        from flask import Response, stream_with_context, jsonify
        import json, time, queue
        _init_console_mirror()
        mirror = globals().get('_G_CONSOLE_MIRROR')
        if mirror is None:
            return jsonify({"success": False, "error": "Console mirror not initialized"}), 500

        client_q = mirror.add_client()

        @stream_with_context
        def _gen():
            yield "retry: 800\n\n"
            deadline = time.time() + 25.0
            try:
                while time.time() < deadline:
                    try:
                        chunk = client_q.get(timeout=0.4)
                        if chunk:
                            yield "data: " + json.dumps({"t": chunk}, ensure_ascii=False) + "\n\n"
                    except queue.Empty:
                        pass
            finally:
                mirror.remove_client(client_q)

        return Response(
            _gen(), mimetype='text/event-stream',
            headers={'Cache-Control': 'no-cache, no-store, must-revalidate',
                     'X-Accel-Buffering': 'no', 'Connection': 'keep-alive'}
        )

