    @app.route('/api/playlist_pin/status', methods=['GET', 'POST'])
    def playlist_pin_status():
        """[신규] 특정 플레이리스트의 PIN 설정 여부 조회 API 🔍"""
        from flask import jsonify, request
        try:
            raw_name = request.args.get('playlist') or request.form.get('playlist') or ''
            if not raw_name and request.is_json:
                raw_name = (request.get_json(silent=True) or {}).get('playlist', '')
            raw_name = str(raw_name).strip()
            if not raw_name:
                return jsonify({"success": False, "error": "playlist 파라미터가 필요합니다."}), 400

            clean_name = raw_name
            if clean_name.endswith('.urls') or clean_name.startswith('url_group://'):
                clean_name = clean_name.replace('.urls', '').replace('url_group://', '')
            elif clean_name.endswith('.images') or clean_name.startswith('image_group://'):
                clean_name = clean_name.replace('.images', '').replace('image_group://', '')
            elif clean_name.endswith('.conns') or clean_name.startswith('conn_group://'):
                clean_name = clean_name[:-len('.conns')] if clean_name.endswith('.conns') else clean_name[len('conn_group://'):]
            elif clean_name.endswith('.memos') or clean_name.startswith('memo_group://'):
                clean_name = clean_name[:-len('.memos')] if clean_name.endswith('.memos') else clean_name[len('memo_group://'):]
            elif clean_name.lower().endswith(('.m3u8', '.dpl', '.m3u', '.pls')):
                clean_name = os.path.splitext(os.path.basename(clean_name))[0]
            else:
                clean_name = os.path.splitext(os.path.basename(clean_name))[0]

            settings_obj = SettingsManager(SETTINGS_FILE)
            settings_obj.load()

            # 비게시 여부 확인
            pub_map = settings_obj.data.get("playlist_web_publish", {})
            is_unpub = False
            if pub_map.get(clean_name) is False or pub_map.get(raw_name) is False:
                is_unpub = True
            else:
                c_low = clean_name.lower()
                r_low = raw_name.lower()
                r_noext = os.path.splitext(os.path.basename(raw_name))[0].lower()
                for k, v in pub_map.items():
                    if str(k).lower() in (c_low, r_low, r_noext) and v is False:
                        is_unpub = True
                        break

            pins_map = settings_obj.data.get("playlist_pins", {})
            saved_pin = str(pins_map.get(clean_name, "")).strip()
            if not saved_pin:
                saved_pin = str(pins_map.get(raw_name, "")).strip()
            if not saved_pin and pins_map:
                lower_pins = {str(k).lower(): str(v).strip() for k, v in pins_map.items()}
                saved_pin = lower_pins.get(clean_name.lower(), "") or lower_pins.get(raw_name.lower(), "")

            # 이미지 플레이리스트 여부 및 재생 후 바로 삭제(delete_after_view) 설정 조회 🖼️
            # ⚠️ 동영상(.m3u8, .m3u, .dpl) 및 URL 플레이리스트는 재생 후 삭제가 모달에 노출되지 않도록 엄격 분기
            is_video_or_url = raw_name.lower().endswith(('.m3u8', '.m3u', '.dpl', '.urls')) or raw_name.startswith('url_group://')
            if is_video_or_url:
                is_image = False
            else:
                img_groups = settings_obj.data.get("playlist_image_groups", {})
                is_image = raw_name.endswith('.images') or raw_name.startswith('image_group://') or (raw_name in img_groups) or (clean_name in img_groups and not clean_name.lower().endswith(('.m3u8', '.m3u', '.dpl', '.urls')))
            
            img_cfg = settings_obj.data.get("playlist_image_settings", {}).get(clean_name, {})
            if not img_cfg:
                img_cfg = settings_obj.data.get("playlist_image_settings", {}).get(raw_name, {})
            delete_after_view = bool(img_cfg.get('delete_after_view', False)) if is_image else False

            return jsonify({
                "success": True,
                "has_pin": bool(saved_pin),
                "is_published": not is_unpub,
                "is_image": is_image,
                "delete_after_view": delete_after_view,
                "playlist": clean_name
            })
        except Exception as e:
            return jsonify({"success": False, "error": str(e)}), 500

    @app.route('/api/playlist/toggle_publish', methods=['POST'])
    @app.route('/api/playlist_pin/toggle_publish', methods=['POST'])
    def playlist_toggle_publish():
        """[신규] 플레이리스트 미디어서버(웹) 게시/비게시(⚪/⚫) 토글 API 🌐✨"""
        import urllib.parse
        from flask import jsonify, request
        try:
            data = request.get_json(force=True, silent=True) or request.form or {}
            raw_name = str(data.get('playlist', '') or data.get('group_name', '')).strip()
            new_pub = data.get('is_published')
            input_pin = str(data.get('pin', '')).strip()

            if not raw_name:
                return jsonify({"success": False, "error": "playlist 이름이 필요합니다."}), 400

            clean_name = raw_name
            if clean_name.endswith('.urls') or clean_name.startswith('url_group://'):
                clean_name = clean_name.replace('.urls', '').replace('url_group://', '')
            elif clean_name.endswith('.images') or clean_name.startswith('image_group://'):
                clean_name = clean_name.replace('.images', '').replace('image_group://', '')
            elif clean_name.endswith('.conns') or clean_name.startswith('conn_group://'):
                clean_name = clean_name[:-len('.conns')] if clean_name.endswith('.conns') else clean_name[len('conn_group://'):]
            elif clean_name.endswith('.memos') or clean_name.startswith('memo_group://'):
                clean_name = clean_name[:-len('.memos')] if clean_name.endswith('.memos') else clean_name[len('memo_group://'):]
            elif clean_name.lower().endswith(('.m3u8', '.dpl', '.m3u', '.pls')):
                clean_name = os.path.splitext(os.path.basename(clean_name))[0]
            else:
                clean_name = os.path.splitext(os.path.basename(clean_name))[0]

            settings_obj = SettingsManager(SETTINGS_FILE)
            settings_obj.load()

            pub_map = settings_obj.data.get("playlist_web_publish", {})
            cur_pub = pub_map.get(clean_name, True)
            if cur_pub is True and (pub_map.get(raw_name) is False):
                cur_pub = False

            # 새 상태가 지정되지 않았으면 단순 토글
            target_pub = not cur_pub if new_pub is None else bool(new_pub)

            # 비게시 -> 게시 전환 시 비밀번호 검증 🔒
            pins_map = settings_obj.data.get("playlist_pins", {})
            saved_pin = str(pins_map.get(clean_name, "")).strip()
            if not saved_pin:
                saved_pin = str(pins_map.get(raw_name, "")).strip()

            if target_pub and saved_pin:
                if not _verify_playlist_pin_suffix(input_pin, saved_pin):
                    return jsonify({"success": False, "error": "비밀번호가 일치하지 않아냥! 게시 상태로 변경할 수 없어. ❌"}), 401

            pub_map[clean_name] = target_pub
            if raw_name != clean_name:
                pub_map[raw_name] = target_pub
            settings_obj.data["playlist_web_publish"] = pub_map
            settings_obj.save()

            msg = f"'{clean_name}' 플레이리스트가 미디어서버(웹)에 게시되었어냥! 🌐✨" if target_pub else f"'{clean_name}' 플레이리스트가 비게시(숨김) 처리되었어냥! 🔒"
            return jsonify({
                "success": True,
                "is_published": target_pub,
                "playlist": clean_name,
                "message": msg
            })
        except Exception as e:
            return jsonify({"success": False, "error": str(e)}), 500

    @app.route('/api/playlist_pin/set', methods=['POST'])
    def playlist_pin_set():
        """[신규] 플레이리스트의 PIN 설정 / 변경 / 해제 및 미디어 옵션 API 🔑"""
        from flask import jsonify, request
        try:
            data = request.get_json(force=True, silent=True) or request.form or {}
            raw_name = str(data.get('playlist', '')).strip()
            old_pin = str(data.get('old_pin', '')).strip()
            new_pin = str(data.get('new_pin', '')).strip()
            pin_action = str(data.get('pin_action', 'auto')).strip()

            if not raw_name:
                return jsonify({"success": False, "error": "playlist 이름이 필요합니다."}), 400

            clean_name = raw_name
            if clean_name.endswith('.urls') or clean_name.startswith('url_group://'):
                clean_name = clean_name.replace('.urls', '').replace('url_group://', '')
            elif clean_name.endswith('.images') or clean_name.startswith('image_group://'):
                clean_name = clean_name.replace('.images', '').replace('image_group://', '')
            elif clean_name.endswith('.conns') or clean_name.startswith('conn_group://'):
                clean_name = clean_name[:-len('.conns')] if clean_name.endswith('.conns') else clean_name[len('conn_group://'):]
            elif clean_name.endswith('.memos') or clean_name.startswith('memo_group://'):
                clean_name = clean_name[:-len('.memos')] if clean_name.endswith('.memos') else clean_name[len('memo_group://'):]
            elif clean_name.lower().endswith(('.m3u8', '.dpl', '.m3u', '.pls')):
                clean_name = os.path.splitext(os.path.basename(clean_name))[0]
            else:
                clean_name = os.path.splitext(os.path.basename(clean_name))[0]

            settings_obj = SettingsManager(SETTINGS_FILE)
            settings_obj.load()

            # 🌐 미디어서버 노출 여부 동시 반영
            if 'is_published' in data:
                is_pub = bool(data['is_published'])
                pub_map = settings_obj.data.setdefault("playlist_web_publish", {})
                pub_map[clean_name] = is_pub
                if raw_name != clean_name:
                    pub_map[raw_name] = is_pub

            # 🖼️ 이미지 플레이리스트 전용: 재생 후 바로 삭제(delete_after_view) 옵션 저장
            is_video_or_url = raw_name.lower().endswith(('.m3u8', '.m3u', '.dpl', '.urls')) or raw_name.startswith('url_group://')
            if not is_video_or_url and 'delete_after_view' in data:
                is_del_after = bool(data['delete_after_view'])
                all_img_settings = settings_obj.data.setdefault("playlist_image_settings", {})
                all_img_settings.setdefault(clean_name, {})['delete_after_view'] = is_del_after
                if raw_name != clean_name:
                    all_img_settings.setdefault(raw_name, {})['delete_after_view'] = is_del_after

            p_map = settings_obj.data.get("playlist_pins", {})
            saved_pin = str(p_map.get(clean_name, "")).strip()
            if not saved_pin:
                saved_pin = str(p_map.get(raw_name, "")).strip()

            # 1. 완전 해제 요청인 경우
            if pin_action == 'remove':
                if saved_pin and not _verify_playlist_pin_suffix(old_pin, saved_pin):
                    return jsonify({"success": False, "error": "현재 비밀번호가 일치하지 않아냥! ❌"}), 401
                if clean_name in p_map:
                    del p_map[clean_name]
                if raw_name in p_map:
                    del p_map[raw_name]
                if f"{clean_name}.memos" in p_map:
                    del p_map[f"{clean_name}.memos"]
                if f"{clean_name}.conns" in p_map:
                    del p_map[f"{clean_name}.conns"]
                if f"{clean_name}.urls" in p_map:
                    del p_map[f"{clean_name}.urls"]
                if f"{clean_name}.images" in p_map:
                    del p_map[f"{clean_name}.images"]
                settings_obj.data["playlist_pins"] = p_map
                settings_obj.save()
                return jsonify({
                    "success": True,
                    "has_pin": False,
                    "is_published": settings_obj.data.get("playlist_web_publish", {}).get(clean_name, True),
                    "delete_after_view": settings_obj.data.get("playlist_image_settings", {}).get(clean_name, {}).get('delete_after_view', False),
                    "message": f"'{clean_name}' 플레이리스트 비밀번호가 해제되었어냥! 🔓"
                })

            # 2. 새 비번 입력이 없는 경우 (기존 유지 & 옵션만 저장)
            if not new_pin:
                settings_obj.save()
                return jsonify({
                    "success": True,
                    "has_pin": bool(saved_pin),
                    "is_published": settings_obj.data.get("playlist_web_publish", {}).get(clean_name, True),
                    "delete_after_view": settings_obj.data.get("playlist_image_settings", {}).get(clean_name, {}).get('delete_after_view', False),
                    "message": f"'{clean_name}' 설정이 성공적으로 저장되었어냥! ⚙️✨"
                })

            # 3. 새 비번을 새로 설정하거나 변경하는 경우
            if saved_pin and not _verify_playlist_pin_suffix(old_pin, saved_pin):
                return jsonify({"success": False, "error": "현재 비밀번호가 일치하지 않아냥! ❌"}), 401

            if not (new_pin.isdigit() and 1 <= len(new_pin) <= 6):
                return jsonify({"success": False, "error": "비밀번호는 0~9 숫자 1~6자리여야 해냥! ⚠️"}), 400

            p_map[clean_name] = new_pin
            if raw_name != clean_name:
                p_map[raw_name] = new_pin
            settings_obj.data["playlist_pins"] = p_map
            settings_obj.save()
            return jsonify({
                "success": True,
                "has_pin": True,
                "is_published": settings_obj.data.get("playlist_web_publish", {}).get(clean_name, True),
                "delete_after_view": settings_obj.data.get("playlist_image_settings", {}).get(clean_name, {}).get('delete_after_view', False),
                "message": f"'{clean_name}' 비밀번호 및 설정이 성공적으로 저장되었어냥! 🔒✨"
            })
        except Exception as e:
            return jsonify({"success": False, "error": str(e)}), 500

    @app.route('/api/playlist_pin/relock', methods=['POST'])
    def playlist_pin_relock():
        """[신규] 플레이리스트 세션 인증 토큰을 즉시 삭제하여 다시 잠금 상태로 복원 🔒✨"""
        import urllib.parse
        from flask import jsonify, request, session
        try:
            data = request.get_json(force=True, silent=True) or request.form or {}
            raw_name = urllib.parse.unquote(str(data.get('playlist', '') or '')).strip()
            clean_name = raw_name
            if clean_name.endswith('.urls') or clean_name.startswith('url_group://'):
                clean_name = clean_name.replace('.urls', '').replace('url_group://', '')
            elif clean_name.endswith('.images') or clean_name.startswith('image_group://'):
                clean_name = clean_name.replace('.images', '').replace('image_group://', '')
            elif clean_name.lower().endswith(('.m3u8', '.dpl', '.m3u', '.pls')):
                clean_name = os.path.splitext(os.path.basename(clean_name))[0]
            else:
                clean_name = os.path.splitext(os.path.basename(raw_name))[0]

            try:
                session.pop('pin_auth_master', None)
                session.pop(f"pin_auth_{clean_name}", None)
                session.pop(f"pin_auth_{raw_name}", None)
                # 🔒 [비누 요청: 한번 풀면 나머지도 같이 풀림] 다시 잠그기 시 전체 플레이리스트 인증 세션도 함께 일괄 초기화
                keys_to_clear = [k for k in list(session.keys()) if str(k).startswith('pin_auth_')]
                for k in keys_to_clear:
                    session.pop(k, None)
            except Exception:
                pass
            return jsonify({"success": True, "message": f"'{clean_name}' 및 모든 플레이리스트가 다시 잠겼어냥! 🔒", "playlist": clean_name, "all_relocked": True})
        except Exception as e:
            return jsonify({"success": False, "error": str(e)}), 500

    @app.route('/save_playlist_order', methods=['POST'])
    # [TAG: #@save_playlist_order]
    def save_playlist_order():
        """[V181.2] 사용자가 드래그 앤 드롭으로 재배치한 플레이리스트 순서를 settings.json에 영구 저장 💾✨"""
        from flask import jsonify, request
        try:
            data = request.get_json(force=True, silent=True) or {}
            order = data.get('order', [])
            if isinstance(order, list) and order:
                settings_obj = SettingsManager(SETTINGS_FILE)
                settings_obj.load()
                settings_obj.data['custom_playlist_order'] = order
                settings_obj.save()
                return jsonify({'success': True, 'saved_count': len(order)})
        except Exception as e:
            try: _log_to_file(f"⚠️ [save_playlist_order Error] {e}")
            except: pass
            return jsonify({'success': False, 'error': str(e)}), 500
        return jsonify({'success': False}), 400

