    @app.route('/api/youtube/channel_videos', methods=['GET'])
    def api_youtube_channel_videos():
        channel_url = request.args.get('url', '').strip()
        if not channel_url:
            return jsonify({'status': 'error', 'message': '채널 URL이 필요합니다.'}), 400
        try:
            h_data = load_video_history()
            items, pl_title = scan_live_playlist(channel_url, history=h_data, sort_mode='top', limit=15)
            if not items:
                items, pl_title = scan_live_playlist(channel_url, history=[], sort_mode='top', limit=10)
            result = []
            for it in items:
                v_id = it.get('id', '')
                if not v_id: continue
                result.append({
                    'id': v_id,
                    'title': it.get('title', '제목 없음'),
                    'url': f"https://www.youtube.com/watch?v={v_id}",
                    'uploader': it.get('uploader', pl_title or '유튜브'),
                    'thumbnail': f"https://i.ytimg.com/vi/{v_id}/mqdefault.jpg",
                    'is_new': v_id not in h_data
                })
            return jsonify({'status': 'success', 'channel_title': pl_title, 'videos': result})
        except Exception as e:
            return jsonify({'status': 'error', 'message': str(e)}), 500

    @app.route('/api/ott/launch', methods=['POST'])
    def api_ott_launch():
        r"""[V195.0] 네이버 웨일 브라우저 no-gpu & C:\User Data Netflix 전용 프로필로 OTT 실행 🍿🐳✨"""
        try:
            import subprocess
            import shutil
            data = request.get_json(force=True, silent=True) or {}
            key = data.get('key', 'netflix')
            urls_map = {
                'netflix': ['https://www.netflix.com'],
                'tving': ['https://www.tving.com/movie'],
                'coupang': ['https://www.coupangplay.com/movies'],
                'wavve': ['https://www.wavve.com'],
                'disney': ['https://www.disneyplus.com/ko-kr/home']
            }
            target_urls = urls_map.get(key, ['https://www.netflix.com'])
            whale_candidates = [
                r"C:\Program Files (x86)\Naver\Naver Whale\Application\whale.exe",
                r"C:\Program Files\Naver\Naver Whale\Application\whale.exe",
                os.path.expandvars(r"%LocalAppData%\Naver\Naver Whale\Application\whale.exe"),
                shutil.which("whale"),
                shutil.which("naver-whale")
            ]
            whale_path = next((p for p in whale_candidates if p and os.path.isfile(p)), None)
            if not whale_path:
                return jsonify({'status': 'error', 'message': '네이버 웨일(whale.exe) 브라우저를 찾을 수 없습니다.'}), 404
            import sys
            user_data_dir = r"C:\User Data Netflix"
            try:
                os.makedirs(user_data_dir, exist_ok=True)
            except Exception:
                pass
            cmd = [whale_path, '--disable-gpu', f'--user-data-dir={user_data_dir}', '--new-window'] + target_urls
            creationflags = 0
            if sys.platform == 'win32':
                creationflags = getattr(subprocess, 'DETACHED_PROCESS', 0) | getattr(subprocess, 'CREATE_NEW_PROCESS_GROUP', 0)
            subprocess.Popen(
                cmd,
                stdin=subprocess.DEVNULL,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                close_fds=(sys.platform != 'win32'),
                creationflags=creationflags
            )
            return jsonify({'status': 'success', 'message': 'Whale 브라우저가 새 창으로 실행되었습니다.', 'urls': target_urls})
        except Exception as e:
            return jsonify({'status': 'error', 'message': str(e)}), 500

    @app.route('/api/youtube/search', methods=['POST'])
    def api_youtube_search():
        data = request.get_json(force=True, silent=True) or {}
        query = data.get('query', '').strip()
        if not query:
            return jsonify({'status': 'error', 'message': '검색어를 입력해주세요.'}), 400
        try:
            import yt_dlp
            search_opts = _apply_ytdl_stealth_opts({
                'extract_flat': True,
                'quiet': True,
                'no_warnings': True,
                'logger': SilentLogger()
            })
            with yt_dlp.YoutubeDL(search_opts) as ydl:
                info = ydl.extract_info(f"ytsearch10:{query}", download=False)
                entries = info.get('entries', []) if info else []
                results = []
                for entry in entries:
                    if entry and entry.get('id'):
                        results.append({
                            'id': entry['id'],
                            'title': entry.get('title', '제목 없음'),
                            'url': entry.get('url') or f"https://www.youtube.com/watch?v={entry['id']}",
                            'uploader': entry.get('uploader', '알 수 없음'),
                            'duration': entry.get('duration_string', ''),
                            'thumbnail': f"https://i.ytimg.com/vi/{entry['id']}/mqdefault.jpg"
                        })
                return jsonify({'status': 'success', 'videos': results})
        except Exception as e:
            return jsonify({'status': 'error', 'message': str(e)}), 500

