    @app.route('/api/youtube/download', methods=['POST'])
    def api_youtube_download():
        data = request.get_json(force=True, silent=True) or {}
        urls_in = data.get('urls', [])
        choice_idx = int(data.get('format_idx', 0))
        raw_make_subs = data.get('make_subtitles', False)
        if isinstance(raw_make_subs, str):
            make_subtitles = raw_make_subs.strip().lower() in ('true', '1', 'yes', 'y')
        else:
            make_subtitles = bool(raw_make_subs)
        # [V206.1] 🛒 웹 체크박스 "다운로드 완료 후 장바구니에 바로 넣기" (스파크 자막 자동화, 기본 OFF) ⚡✨
        raw_cart_add = data.get('cart_add', False)
        if isinstance(raw_cart_add, str):
            cart_add = raw_cart_add.strip().lower() in ('true', '1', 'yes', 'y')
        else:
            cart_add = bool(raw_cart_add)
        # (체크박스를 안 건드렸으면 마지막 저장 설정값을 그대로 사용 · 미저장 시 OFF)
        if 'cart_add' not in data:
            try:
                _cfg_st = SettingsManager(settings_ref.filepath if ('settings_ref' in globals() and settings_ref) else SETTINGS_FILE)
                _cfg_st.load()
                cart_add = bool(_cfg_st.data.get('s_m_yt_auto_cart_add', False))
            except Exception:
                cart_add = False
        
        _log_to_file(f"📥 [Web-Youtube-Download] URLs: {urls_in}, Format: {choice_idx}, MakeSubtitles: {make_subtitles}, CartAdd: {cart_add}")
        
        if isinstance(urls_in, str):
            urls_in = [u.strip() for u in urls_in.replace('\r\n', '\n').split('\n') if u.strip()]
        urls = [u for u in urls_in if u and ('youtube.com' in u or 'youtu.be' in u)]
        
        if not urls:
            return jsonify({'status': 'error', 'message': '유효한 유튜브 URL이 없습니다.'}), 400
            
        _s_p = settings_ref.filepath if ('settings_ref' in globals() and settings_ref) else SETTINGS_FILE
        _st = SettingsManager(_s_p)
        _st.load()
        saved_path = _st.get_valid_path("download_path")
        
        def _bg_worker():
            try:
                titles = ["" for _ in urls]
                downloaded_files, _ = _execute_youtube_download_process(
                    urls=urls,
                    video_titles=titles,
                    saved_path=saved_path,
                    choice_idx=choice_idx,
                    settings=_st,
                    is_bg_mode=True
                )
                # 다운로드 완료 즉시 모든 URL 상태를 100% 완료 상태 및 파일 경로 바인딩 (재생 지원 🎬✨)
                if 'G_BG_DOWNLOAD_STATUS' in globals():
                    for idx, u in enumerate(urls):
                        fp = downloaded_files[idx] if (downloaded_files and idx < len(downloaded_files)) else (downloaded_files[0] if downloaded_files else "")
                        if u not in globals()['G_BG_DOWNLOAD_STATUS']:
                            globals()['G_BG_DOWNLOAD_STATUS'][u] = {'title': os.path.basename(fp) if fp else u}
                        globals()['G_BG_DOWNLOAD_STATUS'][u].update({
                            'pct': '100%',
                            'status': 'finished',
                            'speed': '완료',
                            'eta': '00:00',
                            'file_path': fp,
                            'filename': os.path.basename(fp) if fp else ""
                        })
                if make_subtitles and downloaded_files:
                    try:
                        start_subtitle_engine(downloaded_files, _st, is_resume=True)
                    except Exception as sub_e:
                        _log_to_file(f"⚠️ [Web-Download-Subtitles-Error] {sub_e}")
                # [V206.1] 🛒 다운로드 완료 즉시 장바구니 담기 → cart_auto_spark_translate/auto_subtitle 자동 연동 ⚡✨
                if cart_add and downloaded_files:
                    _cart_ok = 0
                    for df in downloaded_files:
                        try:
                            if not df or not os.path.exists(df):
                                continue
                            if _add_to_shopping_cart(df, _st, reason="웹 다운로드 완료 (장바구니 즉시 담기)"):
                                _cart_ok += 1
                        except Exception as _one_e:
                            _log_to_file(f"⚠️ [Web-Download-CartAdd-Error] {_one_e}")
                    if _cart_ok:
                        _spark_on = bool(_st.data.get('cart_auto_spark_translate', False))
                        _sub_on = bool(_st.data.get('cart_auto_subtitle', False))
                        _tail = "🧠 스파크 자동 번역까지 이어서 가동!" if _spark_on else ("🎙️ 자막 자동 생성까지 이어서 가동!" if _sub_on else "장바구니 연동 옵션은 꺼져 있어 담기만 완료했어냥!")
                        _log_to_file(f"🛒⚡ [Web-AutoCart] {_cart_ok}개 파일 장바구니 자동 담기 완료! ({_tail})")
                        # 웹 '다운로드 현황' 탭에 🛒 배지를 띄우기 위한 상태 마킹 🏷️
                        try:
                            _added_norm = set()
                            for _af in downloaded_files:
                                if _af and os.path.exists(_af):
                                    _added_norm.add(os.path.normcase(os.path.abspath(_af)))
                            for _u, _t in globals().get('G_BG_DOWNLOAD_STATUS', {}).items():
                                if not isinstance(_t, dict):
                                    continue
                                _fp2 = _t.get('file_path')
                                if _fp2 and os.path.normcase(os.path.abspath(_fp2)) in _added_norm:
                                    _t['cart_added'] = True
                        except Exception as _badge_e:
                            _log_to_file(f"⚠️ [Web-AutoCart-Badge] {_badge_e}")
            except Exception as ex:
                _log_to_file(f"❌ [Web-Download-Error] {ex}")
            finally:
                try:
                    _schedule_ytdl_cache_cleanup(_st)
                except Exception: pass
                
        threading.Thread(target=_bg_worker, daemon=True).start()
        return jsonify({
            'status': 'success',
            'message': f"{len(urls)}개 영상 다운로드를 백그라운드에서 시작했어냥! 🚀",
            'count': len(urls)
        })

