    @app.route('/api/recycle_bin_status', methods=['GET'])
    def api_recycle_bin_status():
        """[V195.0] 윈도우 휴지통 파일 개수 및 총 용량 실시간 조회 API 🗑️📊"""
        try:
            import ctypes
            from ctypes import wintypes
            class _SHQUERYRBINFO(ctypes.Structure):
                _fields_ = [
                    ('cbSize', wintypes.DWORD),
                    ('i64Size', ctypes.c_int64),
                    ('i64NumItems', ctypes.c_int64)
                ]
            rbinfo = _SHQUERYRBINFO()
            rbinfo.cbSize = ctypes.sizeof(_SHQUERYRBINFO)
            res = ctypes.windll.shell32.SHQueryRecycleBinW(None, ctypes.byref(rbinfo))
            if res == 0:
                count = int(rbinfo.i64NumItems)
                size_bytes = int(rbinfo.i64Size)
            else:
                count = 0
                size_bytes = 0

            if size_bytes >= 1024 * 1024 * 1024:
                size_str = f"{size_bytes / (1024 * 1024 * 1024):.1f} GB"
            elif size_bytes >= 1024 * 1024:
                size_str = f"{size_bytes / (1024 * 1024):.1f} MB"
            elif size_bytes >= 1024:
                size_str = f"{size_bytes / 1024:.1f} KB"
            else:
                size_str = f"{size_bytes} B"

            return jsonify({
                'status': 'success',
                'count': count,
                'size_bytes': size_bytes,
                'size_formatted': size_str,
                'is_empty': (count == 0)
            })
        except Exception as e:
            return jsonify({
                'status': 'error',
                'message': str(e),
                'count': 0,
                'size_bytes': 0,
                'size_formatted': '0 B',
                'is_empty': True
            }), 200

