    @app.route('/api/playback/recent', methods=['GET', 'POST'])
    def api_playback_recent():
        """[V182.6] 넷플릭스 스타일 최근 시청 이어보기 조회 및 저장 API 🍿✨
           - GET  : videos(플리당 최대 10개 보관분) + limit(실제 표시 개수 1~10) 반환
           - POST : video 저장 / active_playlists 저장 / limit(표시 개수) 저장 모두 지원
        """
        from flask import jsonify, request
        if request.method == 'POST':
            try:
                data = request.get_json(silent=True) or request.form or {}
                video = data.get('video')
                playlist_name = data.get('playlist_name', '').strip()
                active_playlists = data.get('active_playlists')

                saved_limit = None
                if data.get('limit') is not None:
                    saved_limit = _set_recent_continue_limit(data.get('limit'))

                if active_playlists is not None and isinstance(active_playlists, list):
                    try:
                        settings_obj = SettingsManager(SETTINGS_FILE)
                        settings_obj.load()
                        settings_obj.data['resume_tracking_playlists'] = active_playlists
                        settings_obj.save()
                    except Exception:
                        pass

                if video and isinstance(video, dict):
                    _save_recent_continue_db(video, playlist_name)
                    return jsonify({'success': True, 'limit': saved_limit if saved_limit is not None else _get_recent_continue_limit()})
                elif active_playlists is not None or saved_limit is not None:
                    return jsonify({'success': True, 'active_playlists': active_playlists,
                                    'limit': saved_limit if saved_limit is not None else _get_recent_continue_limit()})
            except Exception as e:
                return jsonify({'success': False, 'error': str(e)}), 400
            return jsonify({'success': False, 'error': 'invalid data'}), 400
        else:
            try:
                settings_obj = SettingsManager(SETTINGS_FILE)
                settings_obj.load()
                active_playlists = settings_obj.data.get('resume_tracking_playlists', None)
                videos = _get_recent_continue_db(active_playlists)
                return jsonify({'success': True, 'videos': videos, 'active_playlists': active_playlists,
                                'limit': _get_recent_continue_limit()})
            except Exception as e:
                return jsonify({'success': False, 'error': str(e)}), 500

