_webdav_server_thread = None
_webdav_server_running = False

# --- [신규] 독립 WebDAV 파일서버 전역 변수 (미디어서버와 별도) ---
_file_dav_server_thread = None
_file_dav_server_running = False
_file_dav_cheroot_server = None  # cheroot 서버 인스턴스 (종료 제어용)

# --- [신규] UPnP 포트 포워딩 관리 전역 변수 ---
_upnp_instance = None
_upnp_mapped_ports = []
_upnp_mode = None
_upnp_failed_completely = False
_miniupnpc_install_checked = False

# [TAG: #@_get_external_ip]
def _get_external_ip():
    """공인 IP 주소를 가져옵니다. (다중 API 및 재시도 로직 강화 ✨)"""
    import urllib.request
    providers = [
        'https://api.ipify.org',
        'https://icanhazip.com',
        'http://checkip.amazonaws.com',
        'https://ifconfig.me/ip',
        'https://ident.me'
    ]

    for url in providers:
        for attempt in range(2):
            try:
                with urllib.request.urlopen(url, timeout=5) as r:
                    ip = r.read().decode('utf8').strip()
                    if ip and "." in ip:
                        return ip
            except:
                continue
    return None

# [TAG: #@_setup_upnp_port_forwarding]
def _setup_upnp_port_forwarding(port: int) -> bool:
    """UPnP 포트 포워딩을 설정합니다. (라이브러리 -> SOAP 폴백)"""
    global _upnp_instance, _upnp_mapped_ports, _upnp_mode, _upnp_failed_completely

    print(f" 📡 [UPnP] {port}번 포트 개방 시도 중... (공유기 노크 중 🔔)")
    # 1. 시도: miniupnpc 라이브러리 (최우선)
    try:
        import miniupnpc
        if _upnp_instance is None:
            u = miniupnpc.UPnP()
            u.discoverdelay = 200
            if u.discover() > 0:
                print(f"  🔍 {C.SKY}UPnP 장치를 발견했습니다!{C.RESET}")
                u.selectigd()
                _upnp_instance = u
                _upnp_mode = "library"
            else:
                raise Exception("IGD not found")

        local_ip = _upnp_instance.lanaddr
        _upnp_instance.addportmapping(port, 'TCP', local_ip, port, f'Gemini Server {port}', '')
        if port not in _upnp_mapped_ports:
            _upnp_mapped_ports.append(port)
        print(f"  ✅ {C.GREEN}UPnP 라이브러리 방식으로 포트 {port} 개방 성공!{C.RESET}")
        return True
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")

    # [V4.5] 라이브러리 실패 시 SOAP 폴백 호출
    success = _setup_upnp_soap_fallback(port)
    if success and port not in _upnp_mapped_ports:
        _upnp_mapped_ports.append(port)
    return success

# [TAG: #@_generate_virtual_m3u_content]
def _generate_virtual_m3u_content(source_path, use_web_url, environ, server_key=None):
    """실시간 가상 M3U 내용 생성 (WebDAV/FTP 공유)"""
    base_url = ""
    if use_web_url:
        host = environ.get("HTTP_HOST", "localhost")
        if not host and "SERVER_NAME" in environ:
            host = environ["SERVER_NAME"]
            if environ.get("SERVER_PORT"):
                host += ":" + str(environ["SERVER_PORT"])

        proto = environ.get("wsgi.url_scheme", "http")
        # 현재 파일이 위치한 가상 폴더 경로
        vpath = environ.get("PATH_INFO", "/")
        vdir = os.path.dirname(vpath).replace("\\", "/")
        base_url = f"{proto}://{host}{vdir}/"

    lines = ['#EXTM3U']
    try:
        with open(source_path, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith('#'):
                    fname = os.path.basename(line)
                    if use_web_url:
                        url = base_url + quote(fname)
                        if server_key:
                            url += f"?k={server_key}"
                        lines.append(url)
                    else:
                        lines.append(fname)
        return ('\r\n'.join(lines) + '\r\n').encode('utf-8')
    except:
        return b'#EXTM3U\r\n'


# [TAG: #@_setup_upnp_soap_fallback]
def _setup_upnp_soap_fallback(port: int) -> bool:
    """라이브러리가 없을 때 사용하는 순수 파이썬 SOAP 방식 (AddPortMapping)"""
    global _upnp_failed_completely
    try:
        # [V4.5] 이미 실패가 확정된 상태면 로그 출력 없이 즉시 리턴
        if _upnp_failed_completely: return False

        local_ip = _get_local_ip()
        print(f"  🔍 {C.SKY}SOAP 폴백 엔진 가동 중...{C.RESET} (내부 IP: {local_ip})")

        success = _upnp_soap_request('AddPortMapping', port, local_ip)
        if success:
            print(f"  ✅ {C.GREEN}SOAP 방식으로 포트 {port} 개방 성공!{C.RESET}")
            return True
        else:
            print(f"  ❌ {C.RED}SOAP 방식도 실패했습니다.{C.RESET} (공유기 설정을 수동으로 확인해주세요)")
            _upnp_failed_completely = True # 한 번 전면 실패하면 이 세션에선 더 출력 안 함
            return False
    except Exception:
        _upnp_failed_completely = True
        return False

# [TAG: #@_upnp_soap_request]
def _upnp_soap_request(action: str, port: int, local_ip: Optional[str] = None) -> bool:
    """공유기에 SOAP 요청을 보냅니다 (Add/Delete PortMapping) - WANIP/WANPPP 모두 지원"""
    import urllib.request
    import urllib.error
    from urllib.parse import urljoin

    # [TAG: #@get_soap_payload]
    def get_soap_payload(service_type: str, action: str, port: int, local_ip: Optional[str]) -> str:
        if action == 'AddPortMapping':
            return f"""<u:AddPortMapping xmlns:u="{service_type}">
<NewRemoteHost></NewRemoteHost>
<NewExternalPort>{port}</NewExternalPort>
<NewProtocol>TCP</NewProtocol>
<NewInternalPort>{port}</NewInternalPort>
<NewInternalClient>{local_ip}</NewInternalClient>
<NewEnabled>1</NewEnabled>
<NewPortMappingDescription>Gemini Subtitle Fallback</NewPortMappingDescription>
<NewLeaseDuration>0</NewLeaseDuration>
</u:AddPortMapping>"""
        else:
            return f"""<u:DeletePortMapping xmlns:u="{service_type}">
<NewRemoteHost></NewRemoteHost>
<NewExternalPort>{port}</NewExternalPort>
<NewProtocol>TCP</NewProtocol>
</u:DeletePortMapping>"""

    try:
        # 1. SSDP Discovery (InternetGatewayDevice 검색)
        ssdp_msg = (
            'M-SEARCH * HTTP/1.1\r\n'
            'HOST: 239.255.255.250:1900\r\n'
            'MAN: "ssdp:discover"\r\n'
            'MX: 2\r\n'
            'ST: urn:schemas-upnp-org:device:InternetGatewayDevice:1\r\n\r\n'
        ).encode()

        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.settimeout(2.5)
        s.sendto(ssdp_msg, ('239.255.255.250', 1900))

        locations = set()
        try:
            for _ in range(5): # 여러 응답 수집
                data, addr = s.recvfrom(2048)
                match = re.search(r'LOCATION: (http://.+)\r', data.decode(), re.I)
                if match: locations.add(match.group(1).strip())
        except socket.timeout: pass
        finally: s.close()

        if not locations: return False

        # 2. 각 Location URL에서 제어 서비스 찾기
        for loc_url in locations:
            print(f"  👉 {C.SKY}Location 발견:{C.RESET} {loc_url}")
            try:
                with urllib.request.urlopen(loc_url, timeout=3) as f:
                    xml = f.read().decode()

                # WANIPConnection 또는 WANPPPConnection 서비스 검색
                services = re.findall(r'<service>(.*?)</service>', xml, re.S)
                print(f"  📦 {len(services)}개의 서비스 발견됨")
                for svc_xml in services:
                    st_match = re.search(r'<serviceType>(urn:schemas-upnp-org:service:WAN[IP]{2}Connection:\d+)</serviceType>', svc_xml)
                    ctrl_match = re.search(r'<controlURL>(.+?)</controlURL>', svc_xml)

                    if st_match and ctrl_match:
                        service_type = st_match.group(1)
                        control_url = urljoin(loc_url, ctrl_match.group(1))
                        print(f"  🎯 {C.SKY}제어 대상 발견:{C.RESET} {service_type}")
                        print(f"  🔗 {C.SKY}Control URL:{C.RESET} {control_url}")

                        # 3. SOAP 요청 전송
                        payload = get_soap_payload(service_type, action, port, local_ip)
                        envelope = f"""<?xml version="1.0"?>
<s:Envelope xmlns:s="http://schemas.xmlsoap.org/soap/envelope/" s:encodingStyle="http://schemas.xmlsoap.org/soap/encoding/">
<s:Body>{payload}</s:Body>
</s:Envelope>"""

                        headers = {
                            'Content-Type': 'text/xml; charset="utf-8"',
                            'SOAPACTION': f'"{service_type}#{action}"'
                        }

                        try:
                            req = urllib.request.Request(control_url, data=envelope.encode(), headers=headers)
                            with urllib.request.urlopen(req, timeout=3) as r:
                                if r.status == 200:
                                    return True
                        except urllib.error.HTTPError as he:
                            print(f"  ❌ {C.RED}HTTP 에러({he.code}):{C.RESET} {he.reason}")
                            body = he.read().decode()
                            if 'Conflict' in body or '718' in body: print("  ⚠️ 이미 포트가 열려있거나 충돌이 발생했어.")
                        except Exception as e:
                            print(f"  ❌ {C.RED}전송 에러:{C.RESET} {e}")
            except Exception as e:
                print(f"  ❌ {C.RED}XML 분석 에러:{C.RESET} {e}")
                continue
        return False
    except Exception as e:
        print(f"  ❌ {C.RED}SOAP 시스템 에러:{C.RESET} {e}")
        return False

# [TAG: #@_start_network_server]
def _start_network_server(playlist_dir: str, port: int = None, selected_playlists: Optional[List[str]] = None, use_security: bool = False, use_tunnel: bool = False, use_upnp: bool = False, use_manual: bool = False, is_dashboard_only: bool = False, is_bg_launch: bool = False) -> Tuple[str, int, str, Optional[str]]:
    global G_FLASK_PORT, WEBDAV_PORT, FTP_PORT, settings, _sent_server_address, _is_starting_server, _flask_server_key, _flask_server_id, _flask_server_display_url, _flask_server_port, _flask_server_running, _flask_server_thread, _flask_shutdown_event, _flask_shared_model, _flask_server_serving_label
    if settings:
        G_FLASK_PORT = int(settings.data.get('web_server_port', G_FLASK_PORT))
        WEBDAV_PORT = int(settings.data.get('st_webdav_port', settings.data.get('webdav_port', WEBDAV_PORT)))
        FTP_PORT = int(settings.data.get('ftp_port', FTP_PORT))
        globals()['G_FLASK_PORT'] = G_FLASK_PORT
        globals()['WEBDAV_PORT'] = WEBDAV_PORT
        globals()['FTP_PORT'] = FTP_PORT
    if port is None or port == 5000:
        port = G_FLASK_PORT
    _is_starting_server = True # 시작 중 플래그 ON 🎬
    _sent_server_address = False
    # [V6.3.2] 팟플레이어/nPlayer FTP 폴더 인식 이슈 방지를 위해 playlists 폴더 강제 생성 및 파일 충돌 제거
    if os.path.exists(playlist_dir):
        if not os.path.isdir(playlist_dir):
            try:
                os.remove(playlist_dir)
                os.makedirs(playlist_dir, exist_ok=True)
                print(f"  🚧 {C.ORANGE}경고:{C.RESET} 플레이리스트 경로가 파일로 존재하여 삭제 후 폴더로 재생성했어! 📁")
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")
    else:
        try: os.makedirs(playlist_dir, exist_ok=True)
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

    # [V181.1] 미디어 서버 가동 시 실제 폴더 스캔 후 플레이리스트 전면 1회 자동 갱신 🔄🍿✨
    # [V193.1] 부팅 속도 최적화(핵심): 예전엔 여기서 _rebuild_all_media_playlists() 를
    #   메인 스레드로 동기 수행했다. 18개 그룹을 직렬 os.walk 하므로 실측 4~58초,
    #   그런데 이 함수는 5000포트를 여는 것보다 '먼저' 불렸다(아래 run_server 정리 참조).
    #   → 브라우저가 커넥션 거부를 보며 멍때리는 8~58초가 그대로 사용자 체감 대기였음. 😱
    #
    #   이제는 '포트를 먼저 열고 → 그 다음에 백그라운드에서 갱신'한다.
    #     · playlists/*.m3u8 는 이전 실행본이 이미 디스크에 있으므로 즉시 Previous 데이터로 서비스되고,
    #     · 갱신이 끝나면 자동으로 새본으로 넘어간다 (캐시 무효화까지 수행).
    #     · 플리 갱신이 선행되어야 레지스트리를 재구축할 수 있으므로 둘은 반드시 같은 스레드에서 순차 실행.
    def _bg_rescan_playlists_and_registry():
        # [V193.2] 🛡️ 이 스레드의 print 를 TUI 로 새지 않게 한다.
        #   _generate_playlist() 의 else 분기(silent=True 일 때)는 진행 메시지를
        #   `\r` 로 출력하는데(silent=True 가 오히려 이 분기를 탄다), 이제 이 작업은
        #   이미 인터랙티브해진 메뉴 위에서 돌아간다 → 화면이 18줄 뒤덮인다.
        #   ThreadMutedStream 의 '백그라운드 로그 버퍼'로 돌려서 보존한다.
        try:
            _G_THREAD_LOCAL.mute_stdout = True
        except Exception:
            pass
        try:
            if settings is None:
                settings_obj = SettingsManager(SETTINGS_FILE)
                settings_obj.load()
            else:
                settings_obj = settings
            _rebuild_all_media_playlists(settings_obj, silent=True)
            if '_m3u8_count_cache' in globals() and isinstance(globals()['_m3u8_count_cache'], dict):
                globals()['_m3u8_count_cache'].clear()
            # [V181.1] 레지스트리 갱신 (재생성된 m3u8 기준이라 순차 실행이 필수)
            # [V193.2] silent 는 원래대로 is_bg_launch 를 쓴다.
            #   True 로 하드코딩해서 포그라운드 기동 시 '📂 가상 레지스트리 갱신 완료' 토스트가
            #   사라지는 기능 손실이 있었다. (토스트 소비처: 14486/14808/21083/16294)
            _rebuild_virtual_registry(playlist_dir, selected_playlists=selected_playlists,
                                      force=True, silent=is_bg_launch)
            _log_to_file("🍿 [MediaServer] 백그라운드 플레이리스트/레지스트리 갱신 완료 (서버는 이미 응답 중)")
        except Exception as e:
            try: _log_to_file(f"⚠️ [MediaServer Startup Playlist Sync Error] {e}")
            except: pass

    # [V193.1] 서버 리스닝 성공 직후(= 아래 _flask_server_thread.start() 다음)에 실제 실행한다.
    #   (지금은 여기서 '함수 정의'만 해두고 스레드 시작은 서버 가동 뒤로 미룬다) 🐾
    _pending_bg_rescan = _bg_rescan_playlists_and_registry

    if not is_bg_launch and not is_dashboard_only:
        print(f" 🍿 {C.SKY}미디어 서버 가동: 플레이리스트 동기화 및 갱신 중...{C.RESET} 🔄")

    # [추가] 서버 시작 전 웹 필수 모듈 확인 및 AI 엔진은 백그라운드 비동기 예열 🚀
    _auto_install("flask", "flask", "로컬 네트워크 스트리밍 서버")
    load_heavy_modules(silent=True, is_async=True)

    R = C.RESET

    # ━━━ 0. 기존 프로세스 정리 (포트 충돌 방지) ━━━
    _stop_network_server()  # 내부 상태 정리
    import time as _time
    _time.sleep(0.3)

    # [V17.3] 서브 인스턴스 보호 로직 강화 🛡️✨
    # 보조 앱(Secondary)이라면 메인 앱의 프로세스를 죽이지 않도록 점유 체크 및 종료 스킵!
    if IS_SECONDARY_INSTANCE:
        # 포트 사용 중인지 가볍게 체크
        _port_busy = False
        for chk_port in [port, WEBDAV_PORT]:
            if _is_port_in_use(chk_port):
                _port_busy = True
                break
        
        if _port_busy:
            print(f"  📡 {C.SKY}[보조 앱]{C.RESET} 메인 앱(또는 다른 프로세스)이 이미 포트 {port}를 사용 중이야! ✨")
            print(f"     {C.DIM}메인 앱의 번역 작업을 방해하지 않기 위해 서버 시작을 건너뛸게냥! 🛡️🚫{C.RESET}")
            
            # [V17.3.1] 안전한 반환값 구성 (전역 변수가 비어있을 경우 대비)
            _ret_url = _flask_server_display_url or _get_local_ip()
            _ret_port = _flask_server_port or port
            _ret_id = _flask_server_id or "nplayer"
            _ret_key = _flask_server_key # None일 수 있음
            return _ret_url, _ret_port, _ret_id, _ret_key
    else:
        # 포트를 점유 중인 외부 프로세스 강제 종료 (이전 세션 잔여물 - 메인 인스턴스 전용)
        # [V193.1] 부팅 속도 최적화: 예전엔 포트가 비어 있어도 매번 PowerShell 을 2~4회 콜드 스타트했다
        #   (Get-NetTCPConnection → 비었음 → 그대로 종료). 실측 1~2초 낭비.
        #   → 소켓 bind 로 먼저 빠르게 확인하고, 진짜 점유됐을 때만 PowerShell 을 띄운다. 🚀
        import subprocess as _sub
        for kill_port in [port, WEBDAV_PORT]:
            try:
                # [V193.1] 1단계: 저비용 소켓 프로브 (PowerShell 없이)
                if not _is_port_in_use(kill_port):
                    continue
                # [V16.1] 점유 중일 때만 PowerShell을 사용하여 포트를 점유 중인 프로세스 탐색 및 강제 종료 (정밀 타격)
                cmd = f'powershell -Command "Get-NetTCPConnection -LocalPort {kill_port} -ErrorAction SilentlyContinue | Select-Object -ExpandProperty OwningProcess"'
                res = _sub.run(cmd, capture_output=True, text=True, shell=True)
                pids = set(res.stdout.strip().split())

                my_pid = str(os.getpid())
                for pid in pids:
                    if pid != my_pid and int(pid) > 0:
                        # 프로세스 이름 확인 (안전 확인용)
                        p_name_cmd = f'powershell -Command "Get-Process -Id {pid} -ErrorAction SilentlyContinue | Select-Object -ExpandProperty ProcessName"'
                        p_name_res = _sub.run(p_name_cmd, capture_output=True, text=True, shell=True)
                        p_name = p_name_res.stdout.strip()

                        print(f"  🔪 포트 {kill_port} 점유 발견: {p_name}(PID {pid}) 종료 시도...", end="", flush=True)
                        _sub.run(f'taskkill /F /PID {pid}', capture_output=True, shell=True)
                        print(f" {C.GREEN}완료!{R}")
                        _time.sleep(0.3)
            except Exception as kill_err:
                print(f"  ⚠️ 프로세스 정리 중 오류: {kill_err}")

    # [V4.6] 자동 플레이리스트 갱신 로직 제거 (사용자 요청: 수동으로만 갱신)
    # 이전에는 여기서 _generate_playlist를 호출했으나, 이제는 수동 버튼으로만 작동함.

    # 2. Flask 서버 시작
    if _flask_server_running:
        # Flask 웹서버가 이미 구동 중(대시보드 등)일 때 미디어 서버를 가동하는 경우:
        if not is_dashboard_only:
            globals()["_G_MEDIA_SERVING_ACTIVE"] = True
            # [V193.1] 부팅 속도 최적화: 이 분기는 포트가 이미 떠 있는 상태라 '대기'는 없지만,
            #   예전엔 여기서도 4~58초짜리 os.walk 를 TUI 스레드에서 동기 수행해 메뉴가 얼었다.
            #   → 동일한 백그라운드 워커로 처리한다. 🚀
            try:
                threading.Thread(target=_pending_bg_rescan, name="MediaPlaylistRescan",
                                 daemon=True).start()
            except Exception as e:
                try: _log_to_file(f"⚠️ [MediaServer Active Playlist Sync Error] {e}")
                except: pass
            # WebDAV 및 FTP 서버 시작
            _start_webdav_server(playlist_dir, selected_playlists=selected_playlists, server_id=_flask_server_id, server_key=_flask_server_key, is_bg=is_bg_launch)
            ftp_masq = (_flask_server_display_url or _get_local_ip()) if (use_upnp or use_manual or use_tunnel) else None
            _start_ftp_server(playlist_dir, selected_playlists=selected_playlists, server_id=_flask_server_id, server_key=_flask_server_key, masquerade_address=ftp_masq, is_bg=is_bg_launch)
            _flask_server_serving_label = "전체" if selected_playlists is None else ", ".join([os.path.splitext(p)[0] for p in selected_playlists])

            # 미디어 서버 실행 상태 영구 저장 💾✨
            if settings:
                settings.data['last_server_state'] = {
                    'playlist_dir': playlist_dir,
                    'port': port,
                    'selected_playlists': selected_playlists,
                    'use_security': use_security,
                    'use_tunnel': use_tunnel,
                    'use_upnp': use_upnp,
                    'use_manual': use_manual
                }
                settings.data['server_last_running_state'] = True
                settings.save()
            _log_to_file(f"🎬 [MediaServer] Activated on running Flask server (Label: {_flask_server_serving_label})")
        else:
            globals()["_G_DASHBOARD_ACTIVE"] = True
            if settings:
                settings.data['dashboard_last_running_state'] = True
                settings.save()

        return _flask_server_display_url or _get_local_ip(), _flask_server_port, _flask_server_id, _flask_server_key


    _flask_server_key = None
    _flask_server_id = "nplayer"
    # [원복] 보안/외부망 모드인 경우에만 보안 키 생성 (내부망 공개 모드는 익명 접근 유지)
    if use_security or use_tunnel or use_upnp or use_manual:
        _flask_server_key = _generate_server_key(settings)
        _flask_server_id = "webdav"

    # ━━━ 3. Ngrok 터널링 (외부망 모드) ━━━
    tunnel_url = None
    display_url = _get_local_ip()
    tunnel_url = None

    if use_tunnel:
        try:
            print(f"\r\n 🌐 {C.CYAN}Ngrok 외부 터널을 생성하는 중이야...{R}")
            try:
                from pyngrok import ngrok, conf
            except ImportError:
                _auto_install("pyngrok", "pyngrok", "Ngrok 터널링")
                from pyngrok import ngrok

            # 설정된 토큰이 있으면 적용
            token = settings.data.get('ngrok_auth_token', '') if settings else ''
            if token:
                ngrok.set_auth_token(token)

            # 기존 터널 있으면 종료
            ngrok.kill()

            # 새 터널 생성
            public_url = ngrok.connect(port).public_url
            tunnel_url = public_url
            print(f" ✅ \033[32m외부 주소 생성 완료:\033[0m \033[1m{tunnel_url}\033[0m")
            display_url = tunnel_url
        except Exception as tun_err:
            print(f" ❌ \033[31m터널 생성 실패:\033[0m {tun_err}")
            print(" 💡 \033[2mNgrok 토큰 설정이 필요할 수 있어. (설정 메뉴 확인)\033[0m")
            use_tunnel = False # 실패 시 내부망으로 전환 시도

    if use_upnp:
        global _miniupnpc_install_checked, _upnp_failed_completely
        if _upnp_failed_completely:
            print(f" ❌ {C.RED}UPnP 설정 실패 (이전 시도 실패). 공유기 설정을 확인해줘.{R}")
            use_upnp = False
        else:
            try:
                print(f"\r\n 📡 {C.CYAN}UPnP 외부 포트 포워딩을 시도하는 중이야...{R}")

                # [V4.5] miniupnpc 설치 확인 - 세션 진입 시 딱 1회만 수행
                if not _miniupnpc_install_checked:
                    if not _auto_install("miniupnpc", "miniupnpc", "공유기 UPnP 포트 포워딩", is_optional=True):
                        print(f" 💡 {C.BOLD}{C.SKY}Tip:{R} 'miniupnpc' 설치가 실패했다면 아래 문서를 참고해 C++ 빌드 도구를 설치해야 할 수도 있어!")
                        print("    👉 https://visualstudio.microsoft.com/visual-cpp-build-tools/")
                        print("    [체크항목] ✔ Desktop development with C++ (또는 MSVC v143, Windows 10/11 SDK)")
                        print("    설치 후 터미널을 다시 실행해줘! (현재는 SOAP 폴백으로 진행할게)\r\n")
                    _miniupnpc_install_checked = True

                ext_ip = _get_external_ip()
                # [V4.6.3] 모든 서비스 포트 및 FTP Passive 데이터 포트 전송
                ports_to_forward = [port, WEBDAV_PORT, FTP_PORT] + list(range(3000, 3006))

                success_count = 0
                for p in ports_to_forward:
                    if _setup_upnp_port_forwarding(p):
                        success_count += 1

                if ext_ip and success_count > 0:
                    display_url = ext_ip
                    print(f" ✅ {C.GREEN}UPnP 포트 포워딩 완료! 외부 주소: {C.BOLD}{display_url}{R} (총 {success_count}개 포트 개방)")
                elif not ext_ip:
                    print(f" ❌ {C.RED}UPnP 실패: 외부 IP를 가져올 수 없어.{R}")
                else:
                    print(f" ❌ {C.RED}UPnP 설정 실패. 공유기가 지원하지 않거나 꺼져있을 수 있어.{R}")
                    _upnp_failed_completely = True # 한 번 실패하면 이 플래그 세팅
                    use_upnp = False
            except Exception as upnp_err:
                print(f" ❌ {C.RED}UPnP 오류: {upnp_err}{R}")
                _upnp_failed_completely = True
                use_upnp = False

    if use_manual:
        try:
            print(f"\r\n 🔗 {C.CYAN}수동 포트포워딩 모드로 공인 IP를 확인 중이야...{R}")
            ext_ip = _get_external_ip()
            if ext_ip:
                display_url = ext_ip
                print(f" ✅ {C.GREEN}공인 IP 확인 완료! 외부 주소: {C.BOLD}{display_url}:{port}{R} (WebDAV: {WEBDAV_PORT})")
            else:
                print(f" ❌ {C.RED}공인 IP를 가져오지 못했어. 인터넷 연결을 확인해줘.{R}")
                use_manual = False
        except Exception as man_err:
            print(f" ❌ {C.RED}수동 모드 오류: {man_err}{R}")
            use_manual = False

    # ━━━ 4. 모든 설정 완료 후 WebDAV/FTP 서버 최종 시작 (미디어 스트리밍 서버 종속 🎬) ━━━
    if not is_dashboard_only:
        _start_webdav_server(playlist_dir, selected_playlists=selected_playlists, server_id=_flask_server_id, server_key=_flask_server_key, is_bg=is_bg_launch)
        # [V4.6.5] 외부 접속 모드(UPnP, Manual, Tunnel)인 경우 마스커레이드 주소 전달 (Passive Mode 데이터 연결 대응)
        ftp_masq = display_url if (use_upnp or use_manual or use_tunnel) else None
        _start_ftp_server(playlist_dir, selected_playlists=selected_playlists, server_id=_flask_server_id, server_key=_flask_server_key, masquerade_address=ftp_masq, is_bg=is_bg_launch)

    app = _create_flask_app(playlist_dir, selected_playlists=selected_playlists, server_key=_flask_server_key)

    _flask_shutdown_event = threading.Event()

    global _flask_srv
    # [TAG: #@run_server]
    def run_server():
        global _flask_server_running, _flask_srv
        try:
            import logging
            # Werkzeug 콘솔 로깅 완전 비활성화 🤫
            _wlog = logging.getLogger('werkzeug')
            _wlog.setLevel(logging.ERROR)
            _wlog.disabled = True

            from werkzeug.serving import make_server, WSGIRequestHandler

            # Werkzeug 액세스 로그 및 400 Bad Request/SSL 프로브 에러 로그를 콘솔 대신 debug.log로만 리다이렉트 🛡️
            def _silent_wsgi_log_msg(self, format, *args):
                try:
                    msg = format % args
                    _log_to_file(f"[Werkzeug] {self.address_string()} - - {msg}")
                except Exception:
                    pass

            def _silent_wsgi_log_err(self, format, *args):
                try:
                    msg = format % args
                    _log_to_file(f"[Werkzeug Error] {self.address_string()} - - {msg}")
                except Exception:
                    pass

            WSGIRequestHandler.log_message = _silent_wsgi_log_msg
            WSGIRequestHandler.log_error = _silent_wsgi_log_err

            _flask_srv = make_server('0.0.0.0', port, app, threaded=True, request_handler=WSGIRequestHandler)
            _flask_srv.serve_forever()
        except Exception as e:
            _log_to_file(f"❌ Flask 서버 오류: {e}")
        finally:
            _flask_server_running = False

    _flask_server_running = True # [V4.4] 쓰레드 시작 전 미리 플래그 설정 (동기화 이슈 방지)
    if is_dashboard_only:
        globals()["_G_DASHBOARD_ACTIVE"] = True
    else:
        globals()["_G_MEDIA_SERVING_ACTIVE"] = True
    # [V236.0] 🌐 새 서버 인스턴스 발급 → 열려있는 웹페이지가 스스로 새로고침한다 🔔
    #   앱 재시작 후 미디어 서버가 다시 올라오는 순간이 '탭 자동 복구' 트리거다.
    _bump_server_epoch(f"네트워크 서버 기동 (dashboard_only={is_dashboard_only})")
    _flask_server_thread = threading.Thread(target=run_server, daemon=True)
    _flask_server_thread.start()

    # [V193.1] 🚀 포트가 열린 다음에야 무거운 플레이리스트/레지스트리 재구축을 백그라운드로 시작한다.
    #   → 사용자는 4~58초를 더 이상 기다리지 않고 곧바로 /media 에 접속한다.
    #   (서버가 이미 떠 있으므로 그동안 TUI 메뉴/핫키/다른 서버 기능도 방해받지 않는다)
    try:
        threading.Thread(target=_pending_bg_rescan, name="MediaPlaylistRescan", daemon=True).start()
    except Exception as e:
        try: _log_to_file(f"⚠️ [MediaServer BG Rescan Start Error] {e}")
        except: pass

    # ━━━ 5. Flask 웹 서버 독립 안내 세션 출력 및 텔레그램 알림 ━━━
    if _flask_server_running:
        _sub_path = "/dashboard" if is_dashboard_only else "/media"
        f_url = f"http://{display_url}:{port}{_sub_path}"
        # 🔐 [V193.0] 텔레그램/로그로 퍼지는 URL 은 '서명 토큰' 사용 (평문 키 유출 방지)
        if _flask_server_key: f_url += _url_auth_query('full') or f"?k={_flask_server_key}"

        if not is_bg_launch:
            print("\r\n" + "="*50)
            print(f" 🚀 {C.BOLD}{C.MAGENTA}친구의 Flask 웹 서버 가동 중!{R}")
            print(f" 🔗 {C.BOLD}{C.SKY}접속 URL:{R} {f_url}")
            if _flask_server_key:
                print(f" 🔑 {C.BOLD}보안 키(KEY):{R} {_flask_server_key}")
            print("="*50 + "\r\n")
        else:
            _log_to_file(f"🚀 [Background Server Running] URL: {f_url} | Key: {_flask_server_key}")
        
        # 텔레그램으로 대시보드 주소 발송! 📱✨
        threading.Thread(target=_send_dashboard_server_startup_telegram, args=(display_url, port, _flask_server_key), daemon=True).start()

    _flask_server_display_url = display_url
    _flask_server_port = port
    _flask_server_serving_label = "전체" if selected_playlists is None else ", ".join([os.path.splitext(p)[0] for p in selected_playlists]) # [V60.1] 확장자 보존 📋

    # [신규] 서버 상태 저장 (미디어 서버 가동 시에만 저장!)
    if settings and not is_dashboard_only:
        settings.data['last_server_state'] = {
            'playlist_dir': playlist_dir,
            'port': port,
            'selected_playlists': selected_playlists,
            'use_security': use_security,
            'use_tunnel': use_tunnel,
            'use_upnp': use_upnp,
            'use_manual': use_manual
        }
        settings.data['server_last_running_state'] = True # [V8.1] 자동 재시작 플래그 동기화 ✨
        settings.save()

    _log_to_file(f"🎬 [MediaServer] Started (Label: {_flask_server_serving_label})")
    # [V60.1] 시작 중(_is_starting_server) 플래그를 여기서 풀면 안 됨!
    # (알림 쓰레드가 끝나기 전에 메인 루프가 간섭하여 이중 알림이 가는 문제 발생 🎬🚫)
    # _is_starting_server = False # 시작 완료 🎬🏁
    # _is_starting_server = False  # 시작 완료 플래그 OFF 🎬🏁
    return display_url, port, _flask_server_id, _flask_server_key

# [TAG: #@_wait_for_port]
def _wait_for_port(port, timeout=15):
    """[V15.5.3] 지정된 포트가 실제로 리스닝 상태가 될 때까지 기다립니다. (가장 정확한 서버 준비 확인법)"""
    start_time = time.time()

    # [V65.0] 필터링 상태 변수 (사용자 요청 🔍)
    while time.time() - start_time < timeout:
        try:
            # 로콜 호스트에 소켓 연결 시도
            with socket.create_connection(("127.0.0.1", port), timeout=1):
                return True
        except (ConnectionRefusedError, socket.timeout, OSError):
            time.sleep(0.5)
    return False

# ━━━ [신규] 서버 제어 공통 API ({USER_NAME}의 요청) ━━━
# [TAG: #@media_server_stop]
def media_server_stop(keep_state=False):
    """현재 가동 중인 미디어 서버를 완전히 중지합니다."""
    print(f" 🛑 [System] 미디어 서버 종료 요청 수신 (keep_state={keep_state})")
    # [V163.1] 서버 완전 종료 시 서빙 플래그도 리셋 (keep_state=True는 모드 변경 재시작용이므로 보존)
    if not keep_state:
        globals()["_G_MEDIA_SERVING_ACTIVE"] = False
        globals()["_G_DASHBOARD_ACTIVE"] = False
    _stop_network_server(keep_state=keep_state)
    return True

# [TAG: #@media_server_start]
def media_server_start(playlist_name="__ALL__", mode_idx=None, chat_id=None):
    """미디어 서버를 지정된 설정으로 시작합니다 (비동기 스레드 실행)."""
    global settings, _is_starting_server
    token = settings.data.get('telegram_token', '')
    if not token: return False
    target_chat_id = chat_id or settings.data.get('telegram_chat_id', '')
    if not target_chat_id: return False

    # [수정] 시작 시퀀스 중복 방지 플래그 조기 설정 (V60.1 보완) 🎬🚀
    _is_starting_server = True

    # [TAG: #@_internal_start]
    def _internal_start():
        global _is_starting_server
        try:
            # [TAG: #@now]
            def now():
                return datetime.now().strftime("%H:%M:%S")
            print(f"\r\n 🛡️ [{now()}] [System] 서버 시작 시퀀스 개시 (Playlist: {playlist_name})", flush=True)

            # [V16.1.0] 서버 시작 전 가상 레지스트리 및 플레이리스트 배경 갱신 (사용자님 요청)
            try:
                print("  🔄 플레이리스트 및 가상 경로 갱신 중...", flush=True)
                p_dir = os.path.join(os.getcwd(), "playlists")
                t_playlists = None if playlist_name == "__ALL__" else [playlist_name]
                _rebuild_all_media_playlists(settings, silent=True)
                if '_m3u8_count_cache' in globals() and isinstance(globals()['_m3u8_count_cache'], dict):
                    globals()['_m3u8_count_cache'].clear()
                _rebuild_virtual_registry(p_dir, selected_playlists=t_playlists, force=True)
                print("  ✨ 갱신 완료!", flush=True)
            except Exception as re_e:
                print(f"  ⚠️ 배경 갱신 중 경미한 오류 (무시됨): {re_e}")

            # [V15.5.0] 텔레그램 알림 진단 로그 추가
            notify_server = settings.data.get("telegram_notify_server", False)
            print(f"  🔍 [Debug] Notify_Server: {notify_server}, Token: {'Set' if token else 'None'}, ChatID: {target_chat_id}, Settings: {settings is not None}")

            # 1. 모드 설정 결정
            s_mode = mode_idx if mode_idx is not None else settings.data.get('telegram_default_server_mode', 1)
            use_sec = (s_mode in [2, 3, 4, 5])
            use_tun = (s_mode == 3)
            use_upnp = (s_mode == 4)
            use_manual = (s_mode in [5, 6])

            # 2. 서버 실행
            target_playlists = None if playlist_name == "__ALL__" else [playlist_name]
            globals()["_G_MEDIA_SERVING_ACTIVE"] = True
            d_url, d_port, d_id, d_key = _start_network_server(
                playlist_dir=os.path.join(os.getcwd(), "playlists"),
                selected_playlists=target_playlists,
                use_security=use_sec,
                use_tunnel=use_tun,
                use_upnp=use_upnp,
                use_manual=use_manual,
                is_dashboard_only=False
            )

            # 3. 구동 완료 대기 (소켓 포트 체크 방식 도입)
            # [V15.5.3] 단순 시간 대기 대신 실제 포트 오픈을 확인하여 안정성 극대화 (사용자님 제안)
            print(f"  ⏳ 서버 포트({d_port}) 응답 대기 중...", flush=True)
            ready = _wait_for_port(d_port, timeout=15)

            if ready:
                _flask_server_running = True
                print("  ✅ 서버 포트 응답 확인 완료! (Ready)", flush=True)
            else:
                print(f"  ⚠️ 서버 포드 응답 타임아웃 (포트: {d_port})", flush=True)

            # 4. 결과 통보 (텔레그램)
            if (d_url is not None) or _flask_server_running:
                if token and target_chat_id:
                    global _sent_server_address
                    if not _sent_server_address:
                        reply_msg, url_buttons = _build_server_ready_info(playlist_name)
                        # [V15.5.2] 전송 성공 여부를 확인하여 플래그 및 로그 관리
                        ok = send_telegram_notification(reply_msg, buttons=url_buttons, category='server', chat_id=str(target_chat_id))
                        if ok:
                            _sent_server_address = True
                            print(f" 🛡️ [{now()}] [System] 서버 시작 알림 전송 성공! (Target ID: {target_chat_id})", flush=True)
                        else:
                            print(f" ❌ [{now()}] [System] 텔레그램 알림 전송 실패! (ChatID: {target_chat_id}, Log: debug.log)", flush=True)
            else:
                print(f" ❌ [{now()}] [System] 서버 구동 확인 실패", flush=True)
                if token and target_chat_id:
                    status_msg = f"❌ <b>서버 시작 실패</b>\r\n\r\n플레이리스트 <code>{safe_html(playlist_name)}</code> 시작 중 응답이 없어. 로그를 확인해줘! 😊"
                    TelegramBot.send_message(token, target_chat_id, status_msg)

        except Exception as e:
            print(f" ❌ [System] 서버 시작 쓰레드 오류: {e}")
            if token and target_chat_id:
                try: TelegramBot.send_message(token, target_chat_id, f"❌ 서버 기동 중 치명적 오류: {e}")
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")
        finally:
            # [수정] 성공/실패 여부와 관계없이 시작 중 플래그 해제 🎬🏁
            _is_starting_server = False

    # 백그라운드 스레드 가동
    threading.Thread(target=_internal_start, daemon=True).start()
    return True

# [TAG: #@_stop_network_server]
def _stop_network_server(keep_state=False):
    """모든 네트워크 서버(Flask, WebDAV)를 중지합니다.
    keep_state=True면 last_server_state를 유지해 재시작 후 자동 복구할 수 있습니다."""
    global _flask_srv, _flask_server_running
    global _flask_server_display_url, _flask_server_port
    if _flask_srv:
        try: _flask_srv.shutdown()
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")

    global _ftp_srv, _ftp_server_running
    if _ftp_srv:
        try: _ftp_srv.close_all()
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")
    _ftp_server_running = False

    _flask_server_display_url = None
    _flask_server_port = G_FLASK_PORT

    # [신규] UPnP 포트 포워딩 해제 (독립 WebDAV 서버가 점유 중인 포트는 해제 제외!)
    # 미디어 서버 종료가 WebDAV UPnP 매핑을 덩달아 날리는 충돌을 완벽히 방지하는 격리 처리!
    global _upnp_instance, _upnp_mapped_ports, _upnp_mode
    if _upnp_mapped_ports:
        print(f"  🔓 {C.BOLD}UPnP 포트 포워딩 해제 시도 중...{C.RESET}")
        
        # 독립 WebDAV가 현재 구동 중이라면 해당 포트는 보호 목록에 등록하여 해제 방지!
        # (같은 모듈 내 전역 변수 _file_dav_server_running, _file_dav_upnp_port 직접 접근)
        protected_ports = set()
        if _file_dav_server_running:
            _file_dav_port = int(settings.data.get('file_webdav_port', 8765)) if settings else 8765
            protected_ports.add(_file_dav_port)
        
        for p in list(_upnp_mapped_ports):
            if p in protected_ports:
                print(f"    - 포트 {p} 보호됨 (독립 WebDAV 서버 운영 중 - 해제 건너뜀 🛡️)")
                continue
            try:
                if _upnp_mode == "library" and _upnp_instance:
                    _upnp_instance.deleteportmapping(p, 'TCP')
                elif _upnp_mode == "soap":
                    _upnp_soap_request('DeletePortMapping', p)
                print(f"    - 포트 {p} 해제됨")
                _upnp_mapped_ports.remove(p)
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

    # [V4.6.4] 서버 종료 후 포트 자원 정리를 위해 짧은 대기
    time.sleep(0.5)
    
    # WebDAV가 실행 중이면 UPnP 인스턴스를 살려두고, 아니면 완전 정리!
    if not _file_dav_server_running:
        _upnp_instance = None
        _upnp_mapped_ports = []
        _upnp_mode = None

    _flask_server_running = False

    # [신규] 서버 상태 초기화 (정지됨) - keep_state=True면 재시작 후 자동 복구를 위해 유지
    if settings and not keep_state:
        global _sent_server_address
        _sent_server_address = False # 서버 중지 시 알림 플래그 초기화
        settings.data['last_server_state'] = None # [V17.3.3] pop 대신 None 할당으로 병합 시 부활 방지 🛡️✨
        settings.data['server_last_running_state'] = False # [V8.1] 자동 재시작 플래그 동기화 ✨
        settings.save()


# [TAG: #@_auto_start_server_if_needed]
def _auto_start_server_if_needed(settings, is_async: bool = True):
    """프로그램 시작 시 이전 서버 상태를 복구하고 켜진 상태를 항시 유지합니다. (초고속 백그라운드 비동기 🚀✨)"""
    if not settings: return

    state = settings.data.get('last_server_state')
    if not state:
        state = {
            'playlist_dir': os.path.join(os.getcwd(), "playlists"),
            'port': 5000,
            'selected_playlists': None,
            'use_security': False,
            'use_tunnel': False,
            'use_upnp': False,
            'use_manual': False
        }

    def _bg_auto_start_worker():
        try:
            _start_network_server(
                playlist_dir=state.get('playlist_dir', os.path.join(os.getcwd(), "playlists")),
                port=state.get('port', 5000),
                selected_playlists=state.get('selected_playlists'),
                use_security=state.get('use_security', False),
                use_tunnel=state.get('use_tunnel', False),
                use_upnp=state.get('use_upnp', False),
                use_manual=state.get('use_manual', False),
                is_bg_launch=True
            )
            settings.data['server_last_running_state'] = True
            settings.data['last_server_state'] = state
            settings.save()
            _log_to_file("✅ [Background Auto-Start] Web Dashboard & Media Server running successfully.")
        except Exception as e:
            _log_to_file(f"❌ [Background Auto-Start Error] {e}")

    _log_to_file("🚀 [Auto-Start] Launching Web Dashboard & Media Server in background...")
    if is_async:
        threading.Thread(target=_bg_auto_start_worker, daemon=True, name="BinuAutoStartServerThread").start()
    else:
        _bg_auto_start_worker()

