        _dash_active = globals().get("_G_DASHBOARD_ACTIVE", False) and _is_srv_on
        _media_active = globals().get("_G_MEDIA_SERVING_ACTIVE", False) and _is_srv_on

        dash_state = "🟢 실행 중" if _dash_active else "⚫ 정지됨"
        media_state = "🟢 실행 중" if _media_active else "⚫ 정지됨"

        _block_foreign = settings.data.get('block_foreign_ip', True) if settings else True
        _foreign_tg_mute = not settings.data.get('telegram_notify_foreign_blocked', False) if settings else True
        _mute_str = " / 텔레그램 🔕" if _foreign_tg_mute else " / 텔레그램 🔔"
        _foreign_tag = f"{C.GREEN}🟢 국내 전용 (해외 차단{_mute_str}){R}" if _block_foreign else f"{C.RED}🔴 전세계 허용{R}"

        # [영구 설정 동기화] 미디어 요청 로그 가시성: settings에서 글로벌 변수로 반영 📋
        if settings and 'media_request_log_visible' in settings.data:
            globals()['_G_MEDIA_REQUEST_LOG_VISIBLE'] = settings.data['media_request_log_visible']

