        print(f"{P}║{R}  🎛️ {B}웹 서비스 개별 제어 센터{R}")
        print(f"{P}╟{'─' * 65}{R}")
        print(f"{P}║{R}  1️⃣  웹 대시보드 서비스: {dash_state}")
        print(f"{P}║{R}  2️⃣  미디어 스트리밍 서버: {media_state}")
        print(f"{P}║{R}  🛡️  해외 IP 보안 모드: {_foreign_tag}")
        print(f"{P}╚{'═' * 65}{R}\n")

        _pw_mode_str = f"{C.GREEN}수동 [{settings.data.get('server_password','') if settings else ''}]{R}" if (settings and settings.data.get('use_custom_password') and settings.data.get('server_password')) else f"{C.DIM}6자리 랜덤{R}"
        _active_key_str = f" {C.SKY}(가동 키: {C.GOLD}{_flask_server_key}{C.SKY}){R}" if _flask_server_key else ""

        # 🔐 [V193.0] 표시 URL 은 '서명 토큰' 을 쓴다 (화면 캡처/스크롤 유출 대비)
        _waq = _url_auth_query('full') or (f"?k={_flask_server_key}" if _flask_server_key else "")

        _dash_url = f"http://localhost:{G_FLASK_PORT}/dashboard" + _waq

        _media_url = f"http://localhost:{G_FLASK_PORT}/media" + _waq

