# [TAG: #@_s_m_show_pre_search_duplicate_warning]
def _s_m_show_pre_search_duplicate_warning(query, silent=False):
    """[V112.2] 사용자 요청: 검색 시작 전 로컬(플레이리스트)에 중복 파일이 있는지 커다란 박스로 안내 🕵️‍♂️📦✨"""
    if not query or len(query) < 3: return None

    try:
        file_map = _get_local_playlist_file_map()
        q_lower = query.lower()

        # 매칭되는 파일 찾기 (ID 패턴 또는 단순 포함 여부)
        found_path = None
        for key, path in file_map.items():
            if q_lower in key:
                found_path = path
                break

        if found_path:
            # 팬시 메타데이터 추출
            size_bytes = os.path.getsize(found_path)
            size_gb = size_bytes / (1024**3)
            size_mb = size_bytes / (1024**2)
            size_str = f"{size_gb:.1f}GB" if size_gb >= 1 else f"{int(size_mb)}MB"

            # 재생 시간
            duration_str = "Unknown"
            try:
                ffprobe_exe = _get_ffprobe_bin()

                cmd = [ffprobe_exe, "-v", "error", "-show_entries", "format=duration", "-of", "default=noprint_wrappers=1:nokey=1", found_path]
                c_flags = 0x08000000 if os.name == 'nt' else 0
                result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, encoding="utf-8", errors="replace", creationflags=c_flags, timeout=2)
                if result.returncode == 0 and result.stdout.strip():
                    duration_sec = safe_float(result.stdout.strip())
                    duration_str = f"{int(duration_sec // 60)}min"
            except Exception as e:
                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                if "6" not in str(e):
                    _log_to_file(f"⚠️ [Silent Exception] {e}")

            # [사용자 요청] 시원하고 펜시한 경고 박스 출력 🎨📦
            print(f"\r\n  {C.BOLD}{C.YELLOW}┏━━━━━━━━━━━━━━━━ [이미 파일 있음] 내 PC에 이 영상이 있어냥! 🐾 ━━━━━━━━━━━━━━━━┓{C.RESET}")
            print(f"  {C.YELLOW}┃{C.RESET}  📂 {C.BOLD}파일명:{C.RESET} {os.path.basename(found_path)[:60]}")
            print(f"  {C.YELLOW}┃{C.RESET}  📏 {C.BOLD}용량:{C.RESET} {C.GOLD}{size_str}{C.RESET} │ 🕒 {C.BOLD}재생시간:{C.RESET} {C.SKY}{duration_str}{C.RESET}")
            print(f"  {C.YELLOW}┃{C.RESET}  📍 {C.BOLD}경로:{C.RESET} {C.DIM}{os.path.dirname(found_path)}{C.RESET}")
            print(f"  {C.YELLOW}┗━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━┛{C.RESET}")

            if not silent:
                print(f"\r\n  🔍 {C.DIM}이미 가지고 있는 영상이지만, 다른 버전을 위해 검색을 계속 진행할게냥... (2초 후 시작){C.RESET}")
                time.sleep(2)
            return found_path
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")
    return None

# [TAG: #@_rename_files_in_folder]
# [TAG: #@_find_series_stem]
def _find_series_stem(base_name):
    """파일명 base에서 시리즈 공통 stem을 추론합니다."""
    import re
    stem = re.sub(r'([_\-\.\s]?(?:part|cd|p|ep)?\d+)?([_\-\.\s]?\d+k)?$', '', base_name, flags=re.IGNORECASE).strip()
    if len(stem) < 3:
        m = re.match(r'^(.*?)(?:[_\-\.\s]\d+)+$', base_name)
        if m and len(m.group(1)) >= 3:
            stem = m.group(1)
        else:
            stem = base_name
    return stem

# [TAG: #@_find_series_files]
def _find_series_files(parent_dir, target_filename):
    """target_filename과 동일한 시리즈 패밀리에 속하는 파일 목록을 반환합니다."""
    if not parent_dir or not os.path.exists(parent_dir):
        return [target_filename]
    
    base, ext = os.path.splitext(target_filename)
    stem = _find_series_stem(base)
    if not stem or len(stem) < 3:
        return [target_filename]
    
    try:
        all_files = [f for f in os.listdir(parent_dir) if os.path.isfile(os.path.join(parent_dir, f))]
        series = [f for f in all_files if f.startswith(stem)]
        if len(series) >= 2:
            return series
    except Exception as e:
        pass
    return [target_filename]

# [TAG: #@_calc_series_new_name]
def _calc_series_new_name(s_filename, old_filename, new_filename):
    """old_filename -> new_filename 변경 규칙을 동일 시리즈의 s_filename에도 적용합니다."""
    if s_filename == old_filename:
        return new_filename
    
    import re
    old_base, old_ext = os.path.splitext(old_filename)
    new_base, new_ext = os.path.splitext(new_filename)
    s_base, s_ext = os.path.splitext(s_filename)
    
    old_stem = _find_series_stem(old_base)
    new_stem = _find_series_stem(new_base)
    
    # 1. stem 기반 치환
    if old_stem and new_stem and old_stem != new_stem and s_base.startswith(old_stem):
        new_s_base = new_stem + s_base[len(old_stem):]
        ext_to_use = new_ext if s_ext.lower() == old_ext.lower() else s_ext
        return new_s_base + ext_to_use
    
    # 2. h_숫자 및 알파벳 전 불필요 숫자 접두사 패턴 기반 치환
    new_s_base = re.sub(r'^(?:[hH]_\d+_?|\d+)(?=[a-zA-Z])', '', s_base)
    if new_s_base != s_base:
        ext_to_use = new_ext if s_ext.lower() == old_ext.lower() else s_ext
        return new_s_base + ext_to_use
            
    # 3. 단순 접두사 차이 기반 치환
    import difflib
    sm = difflib.SequenceMatcher(None, old_base, new_base)
    match = sm.find_longest_match(0, len(old_base), 0, len(new_base))
    if match.size > 0:
        old_prefix = old_base[:match.a]
        new_prefix = new_base[:match.b]
        if old_prefix and s_base.startswith(old_prefix):
            new_s_base = new_prefix + s_base[len(old_prefix):]
            ext_to_use = new_ext if s_ext.lower() == old_ext.lower() else s_ext
            return new_s_base + ext_to_use

    return s_filename

# [TAG: #@_smart_clean_filename]
def _smart_clean_filename__REMOVE_TARGET(filename, is_folder=False):
    """
    [V22.40] 스마트 파일명 정돈 엔진 🏷️✨
    - 대괄호/화질/코덱/사이트 태그 자동 제거
    - 접두사 (h_1711@, 13cldg 등) 제거
    - JAV 품번 표준화 (CLDG-014, HEYZO-3917, GANA-3425, LUXU-1895, MREC-009, NOSKN-103)
    - 특수 품번 (1pondo, Tokyo-Hot, Caribbean, 10musume, FC2 등) 지원
    - 충돌로 붙은 불필요 접미사 (_1, _new 등) 정리
    """
    if not filename:
        return filename

    import re
    video_exts = {'.mp4', '.mkv', '.avi', '.mov', '.wmv', '.flv', '.webm', '.ts', '.m2ts', '.m4v', '.srt', '.vtt', '.ass'}
    
    name_part = filename
    ext_part = ""
    
    # 중복 확장자나 실수로 붙은 확장자 처리 (예: test.mp4.mp4 -> base: test, ext: .mp4)
    while True:
        base, cur_ext = os.path.splitext(name_part)
        if cur_ext.lower() in video_exts:
            if not is_folder and not ext_part:
                ext_part = cur_ext
            name_part = base
        else:
            if not is_folder and not ext_part:
                ext_part = cur_ext
                name_part = base
            break

    orig_clean = name_part.strip()
    
    # 1. '@' 가 있으면 '@' 뒤쪽만 취함 (예: javdb.com@CLDG-014 -> CLDG-014)
    if '@' in orig_clean:
        orig_clean = orig_clean.split('@')[-1].strip()

    # 2. 사이트 도메인 제거 (예: www.javdb.com, 141jav.com, missav.com 등)
    orig_clean = re.sub(r'(?:https?:\/\/)?(?:www\.)?[a-zA-Z0-9-]+\.(?:com|net|org|xyz|tv|me|cc|io|vip|top|club|site|app)[_\-\s]*', '', orig_clean, flags=re.IGNORECASE).strip()

    # 3. 특수 브랜드 보호 (1pondo, 10musume, Caribbeancom, Tokyo-Hot, HEYZO, FC2)
    # (A) 1pondo / 10musume / pacopacomama
    m_1p = re.search(r'(?:^|[^a-zA-Z0-9])(1pondo|10musume|pacopacomama)[-_ ]?(\d{6})[-_ ]?(\d{2,4})(?=[^a-zA-Z0-9]|$)', orig_clean, re.IGNORECASE)
    if m_1p:
        brand = m_1p.group(1).lower()
        res_name = f"{brand}_{m_1p.group(2)}_{m_1p.group(3)}"
        return res_name if is_folder else res_name + (ext_part if ext_part else ".mp4")

    # (B) Tokyo-Hot (예: tokyo-hot-n1234, [Tokyo-Hot] cz001 등)
    m_th = re.search(r'(?:tokyo[-_ ]?hot)[-_ ]?([a-zA-Z]{1,3}\d{3,5}|\d{3,5})', orig_clean, re.IGNORECASE)
    if m_th:
        code_num = m_th.group(1).lower()
        res_name = f"Tokyo-Hot-{code_num}"
        return res_name if is_folder else res_name + (ext_part if ext_part else ".mp4")

    # (C) HEYZO (예: HEYZO-3917, heyzo_3947, HEYZO 3917)
    m_hz = re.search(r'(?:^|[^a-zA-Z0-9])(?:heyzo)[-_ ]?(\d{3,5})(?=[^a-zA-Z0-9]|$)', orig_clean, re.IGNORECASE)
    if m_hz:
        res_name = f"HEYZO-{m_hz.group(1)}"
        return res_name if is_folder else res_name + (ext_part if ext_part else ".mp4")

    # (D) Caribbeancom (예: caribbean-123456-001, caribbeancom 123456-001)
    m_cb = re.search(r'(?:^|[^a-zA-Z0-9])(?:caribbean(?:com)?)[-_ ]?(\d{6})[-_ ]?(\d{2,4})(?=[^a-zA-Z0-9]|$)', orig_clean, re.IGNORECASE)
    if m_cb:
        res_name = f"caribbean_{m_cb.group(1)}_{m_cb.group(2)}"
        return res_name if is_folder else res_name + (ext_part if ext_part else ".mp4")

    # (E) FC2-PPV
    m_fc2 = re.search(r'(?:^|[^a-zA-Z0-9])(?:FC2|FC2[-_ ]?PPV)[-_ ]?(\d{5,8})(?=[^a-zA-Z0-9]|$)', orig_clean, re.IGNORECASE)
    if m_fc2:
        res_name = f"FC2-PPV-{m_fc2.group(1)}"
        return res_name if is_folder else res_name + (ext_part if ext_part else ".mp4")

    # 4. 앞부분의 불필요 임시 접두사 제거 (h_1711, h_1840_, 13cldg -> cldg, 55tmavr -> tmavr)
    orig_clean = re.sub(r'^(?:[hH]_\d+_?|\d{1,3})(?=[a-zA-Z])', '', orig_clean).strip()

    # 5. [V22.50] 원본 구조 보존: 노이즈 태그만 제거, JAV 재포맷 없음 🛡️
    # - Step 5(part_suffix), Step 6(JAV 재포맷) 제거 → 시리즈 번호/구분자 보존
    t = orig_clean
    t = re.sub(r'\[[^\]]*\]|\([^\)]*\)|\{[^\}]*\}', '', t)
    t = re.sub(r'(?i)\b(1080p|720p|480p|360p|2160p|4k|hd|fhd|uhd|x264|x265|h264|h265|hevc|uncensored)\b', '', t)
    t = re.sub(r'[-_./\\:|]+', ' ', t)
    t = ' '.join(t.split()).strip()
    
    if not t:
        t = orig_clean
        
    return t if is_folder else t + (ext_part if ext_part else ".mp4")

# [TAG: #@_rename_files_in_folder]
# [TAG: #@_smart_clean_filename]
def _smart_clean_filename(filename, is_folder=False):
    """
    [V22.50] 스마트 파일명 정돈 엔진 🏷️✨ (원본 구조 보존 강화)
    - 원본 파일명 구조 최대한 유지, 불필요 노이즈만 제거
    - @ 앞 접두사 / 사이트 도메인 제거
    - 대괄호/화질/코덱 태그 제거
    - 특수 품번 (1pondo, Tokyo-Hot, Caribbean, 10musume, FC2, HEYZO) 만 표준화
    - ⚠️ 일반 JAV 재포맷(ABC-001 대문자 강제 등) 제거 → 시리즈 파일 구조 보존
    """
    if not filename:
        return filename

    import re
    video_exts = {'.mp4', '.mkv', '.avi', '.mov', '.wmv', '.flv', '.webm', '.ts', '.m2ts', '.m4v', '.srt', '.vtt', '.ass'}
    
    name_part = filename
    ext_part = ""
    
    # 중복 확장자나 실수로 붙은 확장자 처리 (예: test.mp4.mp4 -> base: test, ext: .mp4)
    while True:
        base, cur_ext = os.path.splitext(name_part)
        if cur_ext.lower() in video_exts:
            if not is_folder and not ext_part:
                ext_part = cur_ext
            name_part = base
        else:
            if not is_folder and not ext_part:
                ext_part = cur_ext
                name_part = base
            break

    orig_clean = name_part.strip()
    
    # 1. '@' 가 있으면 '@' 뒤쪽만 취함 (예: javdb.com@CLDG-014 -> CLDG-014)
    if '@' in orig_clean:
        orig_clean = orig_clean.split('@')[-1].strip()

    # 2. 사이트 도메인 제거 (예: www.javdb.com, 141jav.com, missav.com 등)
    orig_clean = re.sub(r'(?:https?:\/\/)?(?:www\.)?[a-zA-Z0-9-]+\.(?:com|net|org|xyz|tv|me|cc|io|vip|top|club|site|app)[_\-\s]*', '', orig_clean, flags=re.IGNORECASE).strip()

    # 3. 특수 브랜드 보호 (1pondo, 10musume, Caribbeancom, Tokyo-Hot, HEYZO, FC2)
    # (A) 1pondo / 10musume / pacopacomama
    m_1p = re.search(r'(?:^|[^a-zA-Z0-9])(1pondo|10musume|pacopacomama)[-_ ]?(\d{6})[-_ ]?(\d{2,4})(?=[^a-zA-Z0-9]|$)', orig_clean, re.IGNORECASE)
    if m_1p:
        brand = m_1p.group(1).lower()
        res_name = f"{brand}_{m_1p.group(2)}_{m_1p.group(3)}"
        return res_name if is_folder else res_name + (ext_part if ext_part else ".mp4")

    # (B) Tokyo-Hot (예: tokyo-hot-n1234, [Tokyo-Hot] cz001 등)
    m_th = re.search(r'(?:tokyo[-_ ]?hot)[-_ ]?([a-zA-Z]{1,3}\d{3,5}|\d{3,5})', orig_clean, re.IGNORECASE)
    if m_th:
        code_num = m_th.group(1).lower()
        res_name = f"Tokyo-Hot-{code_num}"
        return res_name if is_folder else res_name + (ext_part if ext_part else ".mp4")

    # (C) HEYZO (예: HEYZO-3917, heyzo_3947, HEYZO 3917)
    m_hz = re.search(r'(?:^|[^a-zA-Z0-9])(?:heyzo)[-_ ]?(\d{3,5})(?=[^a-zA-Z0-9]|$)', orig_clean, re.IGNORECASE)
    if m_hz:
        res_name = f"HEYZO-{m_hz.group(1)}"
        return res_name if is_folder else res_name + (ext_part if ext_part else ".mp4")

    # (D) Caribbeancom (예: caribbean-123456-001, caribbeancom 123456-001)
    m_cb = re.search(r'(?:^|[^a-zA-Z0-9])(?:caribbean(?:com)?)[-_ ]?(\d{6})[-_ ]?(\d{2,4})(?=[^a-zA-Z0-9]|$)', orig_clean, re.IGNORECASE)
    if m_cb:
        res_name = f"caribbean_{m_cb.group(1)}_{m_cb.group(2)}"
        return res_name if is_folder else res_name + (ext_part if ext_part else ".mp4")

    # (E) FC2-PPV
    m_fc2 = re.search(r'(?:^|[^a-zA-Z0-9])(?:FC2|FC2[-_ ]?PPV)[-_ ]?(\d{5,8})(?=[^a-zA-Z0-9]|$)', orig_clean, re.IGNORECASE)
    if m_fc2:
        res_name = f"FC2-PPV-{m_fc2.group(1)}"
        return res_name if is_folder else res_name + (ext_part if ext_part else ".mp4")

    # 4. 앞부분의 불필요 임시 접두사 제거 (h_1711, h_1840_, 13cldg -> cldg, 55tmavr -> tmavr)
    orig_clean = re.sub(r'^(?:[hH]_\d+_?|\d{1,3})(?=[a-zA-Z])', '', orig_clean).strip()

    # 5. [V22.50] 원본 구조 보존: 노이즈 태그만 제거, JAV 재포맷/구분자 변환 없음 🛡️
    # 삭제된 Step 5(part_suffix), Step 6(JAV 재포맷) → 시리즈 번호/- _ 구분자 완전 보존
    t = orig_clean
    # 대괄호/소괄호/중괄호 태그 제거 (화질, 코덱, 사이트명 등 노이즈)
    t = re.sub(r'\[[^\]]*\]|\([^\)]*\)|\{[^\}]*\}', '', t)
    # 화질/코덱 단독 키워드 제거 (단어 경계 기준)
    t = re.sub(r'(?i)\b(1080p|720p|480p|360p|2160p|4k|hd|fhd|uhd|x264|x265|h264|h265|hevc|uncensored)\b', '', t)
    # ⚠️ [-_./\:|]+ → 공백 변환 제거: 원본 파일명 구조(시리즈 번호 등) 보존
    # 연속 공백만 정리
    t = ' '.join(t.split()).strip()
    
    if not t:
        t = orig_clean
        
    return t if is_folder else t + (ext_part if ext_part else ".mp4")

# [TAG: #@_rename_files_in_folder]
def _rename_files_in_folder(target_folder):
    """
    [V22.40] 스마트 파일명 정돈 로직 🏷️✨:
    1. 최신 스마트 정돈 엔진(_smart_clean_filename)을 적용하여 표준 품번 및 깔끔한 파일명으로 변환
    2. 동반된 자막 파일(.srt)도 영상과 동일한 이름으로 1:1 자동 정돈
    """
    R, G, _Y, S = C.RESET, C.GREEN, C.YELLOW, C.SKY

    if not os.path.exists(target_folder):
        print(f" ⚠️ {C.RED}폴더가 존재하지 않아!{R}")
        return

    print(f"\r\n 🏷️ {C.CYAN}스마트 파일명 정돈(표준 품번 및 노이즈 제거)을 시작할게!{R}")

    files = [f for f in os.listdir(target_folder) if os.path.isfile(os.path.join(target_folder, f))]
    rename_count = 0

    video_exts = {'.mp4', '.mkv', '.avi', '.mov', '.wmv', '.flv', '.webm', '.ts', '.m2ts', '.m4v'}

    # 1. 영상 파일 먼저 정돈
    video_files = [f for f in files if os.path.splitext(f)[1].lower() in video_exts]
    renamed_video_map = {} # old_base -> new_base

    for filename in video_files:
        old_path = os.path.join(target_folder, filename)
        new_name = _smart_clean_filename(filename, is_folder=False)
        if not new_name or filename == new_name:
            continue

        new_path = os.path.join(target_folder, new_name)
        if old_path == new_path:
            continue

        # 충돌 방지
        if os.path.exists(new_path):
            base, ext = os.path.splitext(new_name)
            counter = 1
            while os.path.exists(new_path):
                new_path = os.path.join(target_folder, f"{base}_{counter}{ext}")
                counter += 1
            new_name = os.path.basename(new_path)

        if _safe_rename(old_path, new_path):
            print(f"   🏷️  {S}{filename}{R} -> {G}{new_name}{R}")
            rename_count += 1
            old_b = os.path.splitext(filename)[0]
            new_b = os.path.splitext(new_name)[0]
            renamed_video_map[old_b] = new_b

    # 2. 자막 파일 정돈 (.srt 등)
    sub_files = [f for f in files if os.path.splitext(f)[1].lower() in ('.srt', '.vtt', '.ass')]
    for s_file in sub_files:
        old_path = os.path.join(target_folder, s_file)
        s_base, s_ext = os.path.splitext(s_file)
        
        if s_base in renamed_video_map:
            new_name = renamed_video_map[s_base] + s_ext
        else:
            new_name = _smart_clean_filename(s_file, is_folder=False)

        if not new_name or s_file == new_name:
            continue

        new_path = os.path.join(target_folder, new_name)
        if old_path == new_path:
            continue

        if os.path.exists(new_path):
            base, ext = os.path.splitext(new_name)
            counter = 1
            while os.path.exists(new_path):
                new_path = os.path.join(target_folder, f"{base}_{counter}{ext}")
                counter += 1
            new_name = os.path.basename(new_path)

        if _safe_rename(old_path, new_path):
            print(f"   📝 {S}{s_file}{R} -> {G}{new_name}{R} (자막 동기화)")
            rename_count += 1

    print(f"\r\n ✨ {G}정돈 완료!{R} 총 {rename_count}개의 파일명이 스마트하게 바뀌었어. 👍")

# [TAG: #@_optimize_torrent_folder_one_click]
def _optimize_torrent_folder_one_click(target_folder, settings=None):
    """
    [V15.2] 토렌트 폴더 최적화(추출 + 파일명 정돈) 원큐 통합 함수 ⚡🕵️‍♂️✨
    [V22.40] 스마트 폴더 추출 + 충돌 방지 + 최신 스마트 리네임 완벽 통합 🚀✨
    """
    if not os.path.exists(target_folder):
        print(f" ⚠️ {C.RED}폴더가 존재하지 않아!{C.RESET}")
        return

    print(f"\r\n 🚀 {C.BOLD}{C.SKY}[원큐 최적화]{C.RESET} '{os.path.basename(target_folder)}'를 완벽하게 정리해줄게냥! ✨")

    # 1. 폴더 정리 (하위 폴더 영상/자막 추출 및 원본 폴더/찌꺼기 휴지통 정리)
    _cleanup_folder_logic(target_folder)

    # 2. 파일명 및 자막 스마트 정돈
    _rename_files_in_folder(target_folder)

    print(f"\r\n ✨ {C.GREEN}{C.BOLD}모든 정리가 끝났어! 폴더가 아주 깨끗해졌네냥! 🐈✨{C.RESET}")

