# [TAG: #@gphotos_slideshow_integration]
def _get_gphotos_clipboard_text():
    try:
        import tkinter as tk
        r = tk.Tk()
        r.withdraw()
        txt = r.clipboard_get().strip()
        r.destroy()
        return txt
    except Exception:
        return ""

def _copy_gphotos_clipboard(text):
    try:
        import tkinter as tk
        r = tk.Tk()
        r.withdraw()
        r.clipboard_clear()
        r.clipboard_append(text)
        r.update()
        r.destroy()
        return True
    except Exception:
        return False

def _calc_geo_distance(lat1, lon1, lat2, lon2):
    if lat1 is None or lon1 is None or lat2 is None or lon2 is None:
        return 999999.0
    import math
    R = 6371.0
    dlat = math.radians(lat2 - lat1)
    dlon = math.radians(lon2 - lon1)
    a = math.sin(dlat / 2.0)**2 + math.cos(math.radians(lat1)) * math.cos(math.radians(lat2)) * math.sin(dlon / 2.0)**2
    c = 2.0 * math.atan2(math.sqrt(a), math.sqrt(1.0 - a))
    return R * c

def _extract_base_and_dong(loc_str):
    if not loc_str: return "", "", ""
    import re
    s = str(loc_str).strip()
    poi = ""
    matches = list(re.finditer(r'\(([^)]+)\)', s))
    if matches:
        last_m = matches[-1]
        poi = last_m.group(1).strip()
        base_addr = (s[:last_m.start()] + s[last_m.end():]).strip()
        base_addr = re.sub(r'\s+', ' ', base_addr).strip()
    else:
        base_addr = s
    tokens = base_addr.split()
    dong_key = ""
    for t in reversed(tokens):
        if any(t.endswith(suffix) for suffix in ['동', '읍', '면', '리', '町', '丁目', '區', '구', 'City', 'District']):
            dong_key = t
            break
    if not dong_key and tokens:
        dong_key = tokens[-1]
    return base_addr, poi, dong_key

def _is_same_dong_area(loc1, loc2, lat1=None, lon1=None, lat2=None, lon2=None):
    if not loc1 or not loc2: return False
    if lat1 is not None and lon1 is not None and lat2 is not None and lon2 is not None:
        dist_km = _calc_geo_distance(lat1, lon1, lat2, lon2)
        if dist_km <= 1.5:
            return True
    base1, _, dong1 = _extract_base_and_dong(loc1)
    base2, _, dong2 = _extract_base_and_dong(loc2)
    if base1 and base2 and base1 == base2: return True
    if dong1 and dong2 and dong1 == dong2:
        tokens1 = set(base1.split())
        tokens2 = set(base2.split())
        common = tokens1.intersection(tokens2)
        if len(common) >= 2 or (len(common) >= 1 and any(c not in ['대한민국', '일본', '대만', '한국', 'South Korea'] for c in common)):
            return True
    return False

def _interpolate_missing_locations(photos_list, max_gap_seconds=600):
    if not photos_list or len(photos_list) < 2:
        return photos_list
    import re, datetime
    items = []
    for orig_idx, p in enumerate(photos_list):
        if not isinstance(p, dict): continue
        ts = p.get('timestamp')
        if not ts:
            d_str = p.get('date', '')
            if d_str:
                m = re.search(r'(\d{4})년\s*(\d{1,2})월\s*(\d{1,2})일', d_str)
                if m:
                    try:
                        dt = datetime.datetime(int(m.group(1)), int(m.group(2)), int(m.group(3)))
                        ts = dt.timestamp()
                    except Exception:
                        ts = 0.0
            if not ts: ts = 0.0
        else:
            try:
                ts = float(ts)
            except Exception:
                ts = 0.0
        items.append({'orig_idx': orig_idx, 'ts': ts, 'ref': p})

    timed_items = [it for it in items if it['ts'] > 0]
    timed_items.sort(key=lambda x: x['ts'])
    interpolated_count = 0

    if len(timed_items) >= 2:
        valid_timed_indices = [i for i, it in enumerate(timed_items) if it['ref'].get('location')]
        for v_idx in range(len(valid_timed_indices) - 1):
            i_prev = valid_timed_indices[v_idx]
            i_next = valid_timed_indices[v_idx + 1]
            if i_next <= i_prev + 1: continue
            it_prev = timed_items[i_prev]
            it_next = timed_items[i_next]
            p_prev = it_prev['ref']
            p_next = it_next['ref']
            gap_sec = it_next['ts'] - it_prev['ts']
            if gap_sec <= 0 or gap_sec > max_gap_seconds: continue

            loc_prev = p_prev.get('location', '')
            loc_next = p_next.get('location', '')
            lat_prev, lon_prev = p_prev.get('lat'), p_prev.get('lon')
            lat_next, lon_next = p_next.get('lat'), p_next.get('lon')

            if _is_same_dong_area(loc_prev, loc_next, lat_prev, lon_prev, lat_next, lon_next):
                base_prev, poi_prev, _ = _extract_base_and_dong(loc_prev)
                base_next, poi_next, _ = _extract_base_and_dong(loc_next)
                if poi_prev and poi_next and poi_prev == poi_next:
                    target_loc = loc_prev
                elif poi_prev and not poi_next:
                    target_loc = loc_prev
                elif poi_next and not poi_prev:
                    target_loc = loc_next
                else:
                    target_loc = base_prev or base_next or loc_prev

                for k in range(i_prev + 1, i_next):
                    it_k = timed_items[k]
                    target_p = it_k['ref']
                    if target_p.get('location'): continue
                    target_p['location'] = target_loc
                    interpolated_count += 1
                    if lat_prev is not None and lat_next is not None and lon_prev is not None and lon_next is not None and gap_sec > 0:
                        ratio = (it_k['ts'] - it_prev['ts']) / gap_sec
                        ratio = max(0.0, min(1.0, ratio))
                        target_p['lat'] = round(lat_prev + ratio * (lat_next - lat_prev), 6)
                        target_p['lon'] = round(lon_prev + ratio * (lon_next - lon_prev), 6)
                    elif lat_prev is not None and lon_prev is not None:
                        target_p['lat'] = lat_prev
                        target_p['lon'] = lon_prev

        for i, it in enumerate(timed_items):
            target_p = it['ref']
            if target_p.get('location'): continue
            ts_cur = it['ts']
            if i > 0:
                p_before = timed_items[i-1]['ref']
                if p_before.get('location') and abs(ts_cur - timed_items[i-1]['ts']) <= 300:
                    target_p['location'] = p_before['location']
                    if p_before.get('lat') is not None:
                        target_p['lat'] = p_before['lat']
                        target_p['lon'] = p_before['lon']
                    interpolated_count += 1
                    continue
            if i < len(timed_items) - 1:
                p_after = timed_items[i+1]['ref']
                if p_after.get('location') and abs(timed_items[i+1]['ts'] - ts_cur) <= 300:
                    target_p['location'] = p_after['location']
                    if p_after.get('lat') is not None:
                        target_p['lat'] = p_after['lat']
                        target_p['lon'] = p_after['lon']
                    interpolated_count += 1
                    continue

    for p in photos_list:
        if isinstance(p, dict):
            p.pop('_sort_ts', None)

    if interpolated_count > 0:
        try:
            print(f"\r ✨ {C.BOLD}{C.GREEN}10분 이내 인접 사진 위치 스마트 보간 완료:{C.RESET} 총 {interpolated_count:,}장에 동/주소 자동 배정! 📸🚀")
        except Exception:
            pass
    return photos_list

def extract_all_gphotos(album_url):
    """구글 포토 공유 앨범 링크로부터 OAuth 인증 없이 대용량 전수 사진 URL 및 메타데이터 추출 (RPC 방식) 📸✨"""
    import urllib.request, urllib.parse, re, json, datetime
    print(f"\r\n 📸 {C.BOLD}{C.SKY}구글 포토 공유 앨범 분석 시작 (OAuth 인증 불필요)...{C.RESET}")
    print(f" 🔗 {C.DIM}{album_url}{C.RESET}")
    
    headers = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36',
        'Accept-Language': 'ko-KR,ko;q=0.9,en-US;q=0.8,en;q=0.7'
    }
    
    req = urllib.request.Request(album_url, headers=headers)
    with urllib.request.urlopen(req, timeout=20) as resp:
        final_url = resp.geturl()
        html = resp.read().decode('utf-8', errors='ignore')

    album_id = ""
    share_key = ""
    m_url = re.search(r'/share/([^/?#]+)', final_url)
    if m_url: album_id = m_url.group(1)
    m_key = re.search(r'[?&]key=([^&#]+)', final_url)
    if m_key: share_key = m_key.group(1)

    bl_m = re.search(r'"cfb2h":"([^"]+)"', html)
    bl = bl_m.group(1) if bl_m else "boq_photosuiserver_20260909.07_p0"
    fdr_m = re.search(r'"FdrFJe":"([^"]+)"', html)
    fsid = fdr_m.group(1) if fdr_m else ""

    album_title = ""
    title_m = re.search(r'<meta\s+property=["\']og:title["\']\s+content=["\']([^"\']+)["\']', html, re.IGNORECASE)
    if not title_m: title_m = re.search(r'<title>([^<]+)</title>', html, re.IGNORECASE)
    if title_m: album_title = title_m.group(1).replace('- Google 포토', '').replace('- Google Photos', '').strip()
    if not album_title: album_title = "구글 포토 앨범"

    _GEO_CACHE = {}

    def _dms_to_deg(dms, ref):
        if not dms or len(dms) < 3: return None
        try:
            deg = float(dms[0]) + float(dms[1])/60.0 + float(dms[2])/3600.0
            if ref in ['S', 'W']: deg = -deg
            return deg
        except Exception:
            return None

