            local_count = len([f for f in os.listdir(out_dir) if f.lower().endswith('.html') and f.lower() != 'index.html']) if os.path.exists(out_dir) else 0
            deployed_count = len(settings.data.get('gphotos_slideshow_links', {})) if (settings and hasattr(settings, 'data') and isinstance(settings.data.get('gphotos_slideshow_links'), dict)) else 0
            lines.append(f" 💾 {ctext('슬라이드쇼 저장소 및 배포 상태', C.SKY)}")
