_ADB_DEVICES_FILE = os.path.join(
    os.path.dirname(os.path.abspath(__file__)) if '__file__' in globals() else os.getcwd(),
    'temp', 'adb_devices.json')

# ══ 공개 배포 안전 규칙 ══════════════════════════════════════════════════
# [규칙] AGENTS.md §공개/비공개 배포 경계 — korea.srt.py 는 공개 저장소(korea-srt)
#        배포본이므로 APK 파일명·경로·앱 이름·패키지명을 **소스에 하드코딩 금지**.
#   → 아래 목록은 settings.json(비공개) 에서 읽고, 없으면 런타임에 자동 스캔한다.
#   → 공개본에서는 "APK 가 없다" 만 표시되며 어떤 내부 정보도 노출되지 않는다.
_ADB_SCAN_EXCLUDE_DIRS = {
    "backup", "backups", "temp", "logs", ".git", "__pycache__", ".agents",
    "build", "dist", ".gradle", ".idea", ".vscode", "models_cache",
    "gosh_test", "test", ".gemini", "node_modules", "playlists",
}


def _adb_scan_apks(app_dir, recursive=True):
    """폴더 내 APK 를 런타임 스캔한다 (하드코딩 없이 목록 확보).

    recursive=True 면 하위 폴더까지 재귀 검색하되, 빌드 산출물/임시 폴더는 제외한다.
    (예: app/build/outputs/... 는 후보에서 빼고, 사용자가 고른 APK 는 등록해 둔다.)
    """
    found = []
    if recursive:
        try:
            for root, dirs, files in os.walk(app_dir):
                # 빌드·임시 폴더는 탐색에서 제외
                dirs[:] = [d for d in dirs if d.lower() not in _ADB_SCAN_EXCLUDE_DIRS]
                for f in files:
                    if f.lower().endswith('.apk'):
                        full = os.path.join(root, f)
                        if os.path.isfile(full):
                            found.append(full)
        except Exception:
            pass
    else:
        try:
            for f in os.listdir(app_dir):
                if f.lower().endswith('.apk'):
                    full = os.path.join(app_dir, f)
                    if os.path.isfile(full):
                        found.append(full)
        except Exception:
            pass
    return sorted(set(found), key=lambda p: p.lower())


def _adb_targets(settings, app_dir):
    """배포 대상 APK 목록을 얻는다.

    우선순위:
      1) settings.json 의 'adb_apk_targets' (사용자가 등록한 값, 비공개 파일)
      2) 없으면 작업 폴더 최상위 APK 자동 스캔 후 settings 에 캐시
    """
    targets = []
    if settings:
        try:
            reg = settings.data.get('adb_apk_targets', [])
            if isinstance(reg, list):
                for item in reg:
                    if isinstance(item, str) and os.path.exists(item):
                        targets.append(item)
                    elif isinstance(item, dict):
                        p = item.get('path', '')
                        if p and os.path.exists(p):
                            targets.append(p)
        except Exception:
            targets = []

    if not targets:
        targets = _adb_scan_apks(app_dir)
        # 자동 스캔 결과는 비공개 settings 에 캐시해 다음부터 재사용한다.
        if targets and settings:
            try:
                settings.data['adb_apk_targets'] = targets
                settings.save()
            except Exception:
                pass
    return targets


def _adb_exe_path():
    """adb 실행 파일 경로 — [규칙] 2026-10-10 통합: phone_common 이 SSOT.
    (phone_common 이 없으면 공개 배포본이므로 기존 탐색 로직으로 물러선다)"""
    if _PHONE_COMMON_OK:
        return _phone_adb_path()
    local = os.environ.get('LOCALAPPDATA', '')
    cands = [
        os.path.join(local, 'Android', 'Sdk', 'platform-tools', 'adb.exe'),
        r'C:\Android\platform-tools\adb.exe',
        'adb.exe',
    ]
    for c in cands:
        if os.path.isabs(c):
            if os.path.exists(c):
                return c
        else:
            p = shutil.which(c)
            if p:
                return p
    return None


def _adb_load_ips():
    """pairing 성공한 기기 목록(list[dict]) — [규칙] 2026-10-10 phone_common 과 동일 구조."""
    if _PHONE_COMMON_OK:
        try:
            return _phone_load_ips()
        except Exception:
            pass
    # 폴백(공개 배포본): 옛 문자열 목록도 dict 로 승격시켜 반환 형식을 통일한다
    out = []
    try:
        with open(_ADB_DEVICES_FILE, 'r', encoding='utf-8') as f:
            data = json.load(f)
        for d in data.get('devices', []):
            if isinstance(d, str) and d:
                out.append({'ip': d, 'alias': d, 'port': 5555})
            elif isinstance(d, dict) and d.get('ip'):
                d.setdefault('alias', d['ip'])
                d.setdefault('port', 5555)
                out.append(d)
    except Exception:
        pass
    return out


# [TAG: #@_adb_ip_strings]
def _adb_ip_strings():
    """등록 기기 IP 만 뽑은 문자열 목록 (표시/비교용)."""
    return [d.get('ip') for d in _adb_load_ips() if isinstance(d, dict) and d.get('ip')]


def _adb_save_ip(ip):
    """pairing 성공한 IP를 저장한다 (중복 방지)."""
    if not ip:
        return False
    if _PHONE_COMMON_OK:
        try:
            return _phone_add_ip(ip)
        except Exception:
            pass
    devs = _adb_load_ips()
    have = {d.get('ip') for d in devs if isinstance(d, dict)}
    if ip in have:
        return True
    devs.append({'ip': ip, 'alias': ip, 'port': 5555})
    try:
        os.makedirs(os.path.dirname(_ADB_DEVICES_FILE), exist_ok=True)
        with open(_ADB_DEVICES_FILE, 'w', encoding='utf-8') as f:
            json.dump({'devices': devs, 'info': _adb_load_info()}, f,
                      ensure_ascii=False, indent=2)
        return True
    except Exception:
        return False


# ══ 기기 정보(모델명·OS·배터리 등) 수집/캐시 ═══════════════════════════
# [규칙] AGENTS.md §공개/비공개 배포 경계 — 기기 정보를 **하드코딩하지 않는다.**
#   전부 기기에서 읽어온 값이라 공개 저장소(korea-srt) 배포본에서도 정보가 노출되지 않는다.

# [TAG: #@_adb_info_load]
def _adb_load_info():
    """adb_devices.json 안의 'info' 캐시를 읽는다 (dict)."""
    try:
        with open(_ADB_DEVICES_FILE, 'r', encoding='utf-8') as f:
            data = json.load(f)
        info = data.get('info', {})
        return info if isinstance(info, dict) else {}
    except Exception:
        return {}


# [TAG: #@_adb_info_save]
def _adb_info_save(info):
    """기��� 정보 캐시를 'info' 키로 저장한다.

    ⚠️ devices(IP 목록) 키는 **반드시 유지**한다 — pairing 등록 목록이 날아가면 안 된다.
    """
    try:
        os.makedirs(os.path.dirname(_ADB_DEVICES_FILE), exist_ok=True)
        with open(_ADB_DEVICES_FILE, 'w', encoding='utf-8') as f:
            json.dump({'devices': _adb_load_ips(), 'info': info or {}},
                      f, ensure_ascii=False, indent=2)
        return True
    except Exception:
        return False


# [TAG: #@_adb_device_info]
def _adb_device_info(adb, dev, timeout=15):
    # [규칙] 2026-10-10 통합 — phone_common 이 있으면 그쪽 수집기를 쓴다(동일한 값/동일한 캐시).
    """기기의 모델명·제조사·OS·ABI·IP·배터리·여유공간을 한 번에 모아 dict 로 돌려준다.

    [설계] adb 를 여러 번 호출하지 않고 **셸 1회 호출**로 끝낸다(실측 253ms).
           연결이 끊긴 기기면 캐시된 값만 돌려준다(빈 dict).
    [규칙] 실패해도 절대 예외를 던지지 않는다 — 메뉴가 죽으면 안 된다.
    [규칙] 공개 배포 안전 — 모든 값은 기기에서 읽어온다(하드코딩 0건).
    """
    if _PHONE_COMMON_OK:
        # 공용 수집기 사용 (phone_device_info 는 adb 경로를 스스로 찾는다)
        try:
            got = _phone_device_info(dev, timeout=timeout)
            if got:
                return got
        except Exception:
            pass

    if not adb or not dev:
        return {}

    # ── 1) 살아있으면 실시간 조회 (셸 1회 호출로 전부 수집) ──
    #    앞 6줄은 순서가 고정되도록 "항상 출력되는" 명령만 쓴다.
    #    빈 값이 나와도 줄 자체는 출력되므로 위치가 밀리지 않는다.
    try:
        ok, out = _adb_run(adb, ['-s', dev, 'shell',
                                 'echo $(getprop ro.product.manufacturer); '
                                 'echo $(getprop ro.product.model); '
                                 'echo $(getprop ro.build.version.release); '
                                 'echo $(getprop ro.build.version.sdk); '
                                 'echo $(getprop ro.product.cpu.abi); '
                                 'echo $(getprop ro.serialno); '
                                 'ip route 2>/dev/null | grep -o "src [0-9.]*" '
                                 '| head -1 | cut -d" " -f2; '
                                 'dumpsys battery 2>/dev/null | grep -m1 "level:" '
                                 '| grep -o "[0-9]*" | head -1; '
                                 'df -h /data 2>/dev/null | tail -1'],
                          timeout=timeout)
        if ok and out:
            lines = [x.strip() for x in out.splitlines()]
            # 최소 6줄(앞 6개 필드)은 항상 확보되어야 파싱이 안전하다
            while len(lines) < 6:
                lines.append('')
            info = {
                'manufacturer': lines[0],
                'model': lines[1],
                'android': lines[2],
                'sdk': lines[3],
                'abi': lines[4],
                'serial': lines[5],
                'ip': lines[6] if len(lines) > 6 else '',
                'battery': lines[7] if len(lines) > 7 else '',
            }
            # 여유공간: df 출력에서 실제 여유 크기 칸을 뽑는다
            # (예: "/dev/block/dm-72 104G 86G 17G 84% /data/user/0" → 여유는 뒤에서 3번째)
            if len(lines) > 8:
                parts = lines[8].split()
                if len(parts) >= 3:
                    info['free'] = parts[-3]
            # ── 2) 캐시에 저장 (다음에 미연결이어도 이름이 보인다) ──
            info['label'] = _adb_device_label(info)
            info['seen'] = time.strftime('%Y-%m-%d %H:%M:%S')
            cache = _adb_load_info()
            cache[dev] = info
            _adb_info_save(cache)
            return info
    except Exception:
        pass

    # ── 3) 실패 시엔 캐시로 대체 ──
    return _adb_load_info().get(dev, {}) or {}


# [TAG: #@_adb_device_short]
def _adb_device_short(info):
    """기종명만(OS 제외) — 폴백 환경에선 라벨에서 OS 를 잘라 낸다."""
    if _PHONE_COMMON_OK and info:
        try:
            return _phone_device_short(info)
        except Exception:
            pass
    lab = _adb_device_label(info)
    return lab.split('·')[0].strip() if lab else ''


# [TAG: #@_adb_device_label]
def _adb_device_label(info):
    """기기 정보를 '삼성 SM-A566S · 안드로이드 16' 형태의 한 줄 라벨로 만든다."""
    if _PHONE_COMMON_OK and info:
        try:
            return _phone_device_label(info)
        except Exception:
            pass
    if not info:
        return ''
    maker = (info.get('manufacturer') or '').strip()
    model = (info.get('model') or '').strip()
    # 제조사와 모델명이 같으면(삼성 등) 중복 표기하지 않는다
    if maker and model and maker.lower() == model.lower():
        model = ''
    name = f"{maker} {model}".strip()
    if not name:
        name = model or maker or '알 수 없음'
    parts = [name]
    if info.get('android'):
        parts.append(f"안드로이드 {info['android']}")
    return ' · '.join(parts)


# [TAG: #@_adb_device_badges]
# [TAG: #@_adb_is_vr]  ★ VR/MR 헤드셋(Quest 등) 판별 — 설치 대상에서 빼기 위한 표식
#   [공개 배포 안전] 기기 목록을 소스에 적지 않는다(키워드 판별만).
def _adb_is_vr(info):
    """VR/MR 헤드셋인가? phone_common 이 있으면 그것을, 없으면 키워드로 판별."""
    if not info or not isinstance(info, dict):
        return False
    try:
        if _PHONE_COMMON_OK:
            from phone_common import phone_is_vr_device as _p_is_vr
            return bool(_p_is_vr(info))
    except Exception:
        pass
    try:
        blob = ' '.join(str(info.get(k) or '')
                        for k in ('manufacturer', 'model', 'device', 'product')).lower()
        # [99 감사 P2 · 2026-10-10] 부분일치 오탐 방지 → 완전한 단어만 VR 로 본다.
        return bool(re.search(r'(?<![a-z0-9])(?:oculus|meta|quest|pico|lynx|horizon|vive)'
                              r'(?![a-z0-9])', blob))
    except Exception:
        return False


def _adb_device_badges(info):
    """메뉴 한 줄에 붙일 짧은 상태 배지들을 만든다 (🔋73% · 🌐192.168.0.5 · 💾여유 17G)."""
    if _PHONE_COMMON_OK and info:
        try:
            return _phone_device_badges(info)
        except Exception:
            pass
    if not info:
        return ''
    out = []
    if _adb_is_vr(info):
        out.append("🎮 VR")
    bat = (info.get('battery') or '').strip()
    if bat.isdigit():
        out.append(f"🔋{bat}%")
    ip = (info.get('ip') or '').strip()
    if ip:
        out.append(f"🌐{ip}")
    free = (info.get('free') or '').strip()
    if free:
        out.append(f"💾여유 {free}")
    return ' · '.join(out)


# ══ 폰 정보 표시 SSOT (마법사 헤더 · 런처 메뉴가 같은 내용을 본다) ══════
# [TAG: #@_adb_device_compact]
def _adb_device_compact(info, fallback=''):
    """메뉴 '한 줄'용 아주 짧은 이름 — device_name > model > 제조사.

    [규칙] 2026-10-10 사용자 지적 — "폰 정보가 부실하다".
      긴 라벨('희태의 Quantum6 (samsung SM-A566S) · 안드로이드 16')은
      메뉴 한 줄에 넣으면 개행되어 읽을 수가 없다 → 짧은 이름만 뽑는다.
    """
    if not info or not isinstance(info, dict):
        return fallback
    for k in ('device_name', 'model'):
        v = (info.get(k) or '').strip()
        if v:
            return v
    return (info.get('manufacturer') or '').strip() or fallback


# [TAG: #@_adb_phone_summary_lines]
def _adb_phone_summary_lines(devs=None, info_map=None, known_ips=None, indent="      "):
    """연결/등록된 폰을 '한 대 한 줄' 요약 문자열로 만든다.

    [규칙] 2026-10-10 사용자 지적 — "폰 정보가 부실하다".
      ADB 마법사 헤더와 런처(메인 21) 메뉴 헤더가 **같은 내용·같은 양식**이어야
      하므로 표시 로직을 한 곳에 모은다(SSOT). 한쪽만 고치면 또 어긋난다.
    [주의] adb 를 새로 부르지 않는다 — 호출자가 devs/info_map 를 미리 수집해 넘긴다.
           (헤더 콜백은 매 렌더마다 호출되므로 여기서 adb 를 치면 메뉴가 먹통된다)
    [입력] devs        : 연결된 시리얼 목록
           info_map   : {시리얼: info} (_adb_dev_info_map 결과)
           known_ips  : 등록만 되어 있고 미연결인 IP 목록
    """
    devs = list(devs or [])
    info_map = info_map or {}
    if known_ips is None:
        known_ips = _adb_ip_strings()
    cache = _adb_load_info() or {}
    lines = []
    for d in devs:
        i = info_map.get(d) or {}
        # [주의] 🎮 VR 표시는 _adb_device_badges() 가 맨 앞에 붙여준다(중복 방지).
        nm = _adb_device_label(i) or d
        bg = _adb_device_badges(i)
        lines.append(f"{indent}· {nm}" + (f" {C.GRAY}[{bg}]{C.RESET}" if bg else ""))
    for ip in known_ips:
        if any(ip in d for d in devs):
            continue
        inf = {}
        for i2 in cache.values():
            if isinstance(i2, dict) and i2.get('ip') == ip:
                inf = i2
                break
        nm = _adb_device_label(inf)
        bg = _adb_device_badges(inf)
        head = f"{nm} " if nm else ""
        if bg:
            head += f"{C.GRAY}[{bg}]{C.RESET} "
        lines.append(f"{indent}· {head}{C.GRAY}{ip} · 미연결(등록됨){C.RESET}")
    if not lines:
        lines.append(f"{indent}{C.GRAY}없음 (자동 재연결 대기){C.RESET}")
    return lines


# [TAG: #@_adb_menu_tag]
def _adb_menu_tag(devs=None, info_map=None, known=None):
    """런처 메뉴 한 줄 끝에 붙이는 '폰 상태 태그' (예: 🟢 연결 3대: A · B · C).

    [규칙] 2026-10-10 — 예전엔 '등록됨 4대' 처럼 **개수만** 보여줘서
      어떤 폰이 붙어 있는지 알 수 없었다(사용자 지적: 폰 정보가 부실하다).
    """
    devs = list(devs or [])
    info_map = info_map or {}
    if known is None:
        known = _adb_load_ips()
    if devs:
        names = []
        for d in devs:
            i = info_map.get(d) or {}
            nm = _adb_device_compact(i) or d
            if _adb_is_vr(i):
                nm = f"🎮 {nm}"
            if nm not in names:
                names.append(nm)
        shown = ' · '.join(names[:3])
        if len(names) > 3:
            shown += f" 외 {len(names) - 3}대"
        return f" {C.GREEN}[🟢 연결 {len(devs)}대: {shown}]{C.RESET}"
    if known:
        return f" {C.YELLOW}[⚪ 등록 {len(known)}대 · 미연결]{C.RESET}"
    return f" {C.YELLOW}[최초 pairing 필요]{C.RESET}"


# [TAG: #@_adb_device_detail_screen]
def _adb_device_detail_screen(info_map):
    """연결된 폰의 상세 정보(기종·OS·시리얼·배터리·저장공간)를 표로 보여준다."""
    print(f"\r\n {C.BOLD}{C.SKY}📱 연결된 폰 상세 정보{C.RESET}")
    print(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
    if not info_map:
        print(f" {C.YELLOW}연결된 기기가 없습니다.{C.RESET}")
    for d, info in info_map.items():
        nm = _adb_device_label(info) or d
        print(f" 📱 {C.GREEN}{ctext(nm, C.GREEN)}{C.RESET}")
        rows = []
        if info.get('android'):
            rows.append(("운영체제", f"안드로이드 {info['android']} (API {info.get('sdk', '-')})"))
        if info.get('device_name'):
            rows.append(("기기 이름", info['device_name']))
        if info.get('carrier'):
            rows.append(("통신사", info['carrier']))
        if info.get('serial'):
            rows.append(("시리얼", info['serial']))
        if info.get('ip'):
            rows.append(("IP 주소", info['ip']))
        if info.get('abi'):
            rows.append(("아키텍처", info['abi']))
        if info.get('battery'):
            rows.append(("배터리", f"{info['battery']}%"))
        if info.get('free'):
            rows.append(("저장공간 여유", info['free']))
        if info.get('patch'):
            rows.append(("보안 패치", info['patch']))
        if not rows:
            print(f"    {C.GRAY}(정보를 수집하지 못했습니다){C.RESET}")
        for k, v in rows:
            print(f"    {C.GRAY}·{C.RESET} {k:<10} : {ctext(v, C.SKY)}")
        print(f"    {C.GRAY}· adb 시리얼 : {d}{C.RESET}")
        print(f"    {C.GRAY}· 설명 확인 시각 : {_adb_info_seen()}{C.RESET}")
        print(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
    try:
        input(f"\n {C.GRAY}Enter 키를 누르면 돌아가요...{C.RESET}")
    except (KeyboardInterrupt, EOFError):
        pass


# [TAG: #@_adb_devinfo_mem_cache]
_ADB_DEVINFO_MEM_CACHE = {}

def _adb_clear_devinfo_cache():
    """기기 정보 메모리 캐시 초기화."""
    global _ADB_DEVINFO_MEM_CACHE
    _ADB_DEVINFO_MEM_CACHE.clear()
    if '_PHONE_COMMON_OK' in globals() and _PHONE_COMMON_OK:
        try:
            if '_phone_clear_info_cache' in globals():
                _phone_clear_info_cache()
        except Exception:
            pass

# [TAG: #@_adb_dev_info_map]
def _adb_dev_info_map(adb, devs, force=False):
    """연결된 기기 전체의 정보를 {'시리얼': info} 형태로 만든다 (메뉴 표시용).

    [성능 최적화 (2026-10-10)]
    - 최초 진입 시 1회 수집 후 메모리 캐시에 보관하여 이후 루프 지연을 완전 해소.
    - 사용자가 '기기 정보 새로고침'을 누르면 force=True로 실시간 갱신.
    """
    global _ADB_DEVINFO_MEM_CACHE
    if not isinstance(_ADB_DEVINFO_MEM_CACHE, dict):
        _ADB_DEVINFO_MEM_CACHE = {}

    if force:
        _adb_clear_devinfo_cache()

    out = {}
    cache = _adb_load_info()
    for d in (devs or []):
        if not force and d in _ADB_DEVINFO_MEM_CACHE and _ADB_DEVINFO_MEM_CACHE[d]:
            out[d] = _ADB_DEVINFO_MEM_CACHE[d]
            continue
        try:
            info = _adb_device_info(adb, d) or cache.get(d, {}) or {}
            out[d] = info
            if info:
                _ADB_DEVINFO_MEM_CACHE[d] = info
        except Exception:
            info = cache.get(d, {}) or {}
            out[d] = info
            if info:
                _ADB_DEVINFO_MEM_CACHE[d] = info
    return out


def _adb_run(adb, args, timeout=30):
    """adb 실행 헬퍼. 실패해도 예외를 던지지 않고 (ok, output) 을 반환한다."""
    try:
        _cflags = subprocess.CREATE_NO_WINDOW if os.name == 'nt' else 0
        r = subprocess.run([adb] + list(args), capture_output=True, text=True,
                           timeout=timeout, encoding='utf-8', errors='replace',
                           creationflags=_cflags)
        out = ((r.stdout or '') + (r.stderr or '')).strip()
        return (r.returncode == 0), out
    except FileNotFoundError:
        return False, 'adb 실행 파일 없음'
    except subprocess.TimeoutExpired:
        return False, 'adb 응답 타임아웃'
    except Exception as e:
        return False, f'{type(e).__name__}: {e}'


# [TAG: #@_adb_dedupe_fallback]
def _adb_dedupe_fallback(devs):
    """phone_common 이 없는 환경(공개 배포본)용 dedupe — 경로 문자열만으로 판단한다."""
    import re as _re
    best, order = {}, []
    for s in devs or []:
        t = s or ''
        if '_adb-tls-connect._tcp' in t:
            key, rank = f'__{t}', 2          # mDNS (1회성)
        elif _re.match(r'^\d{1,3}(\.\d{1,3}){3}:\d+$', t):
            key, rank = t, 1                 # 영구 무선 (tcpip)
        else:
            key, rank = f'__{t}', 3
        if key not in order:
            order.append(key)
        if key not in best or rank < best[key][1]:
            best[key] = (t, rank)
    keep = [best[k][0] for k in order]
    return keep, [d for d in (devs or []) if d not in keep]


def _adb_connected(adb):
    """현재 'device' 상태인 기기 시리얼 목록. (에뮬레이터/host/offline 은 제외)

    [규칙] 사용자 지시(2026-10-10) — **무선 영구 설정이 기존 1회성 무선 연결을 대체**한다.
       폰 1대가 USB + 무선 동시 연결이면 adb 가 2개로 등록하는데(예: 192.168.100.21:5555
       와 adb-R5CWC0GC0AP-xxx._adb-tls-connect._tcp), 그러면 메뉴에 같은 폰이 2줄 뜨고
       설치도 2번 실행된다 → ro.serialno 기준으로 1건만 남긴다.
    """
    ok, out = _adb_run(adb, ['devices'], timeout=20)
    if not ok:
        return []
    devs = []
    for line in out.splitlines()[1:]:
        parts = line.strip().split()
        if len(parts) >= 2 and parts[1] == 'device':
            devs.append(parts[0])
    if len(devs) <= 1:
        return devs
    try:
        if _PHONE_COMMON_OK:
            keep, dropped = _phone_dedupe_devices(devs)
        else:
            keep, dropped = _adb_dedupe_fallback(devs)
        if dropped:
            print(f" {C.GRAY}ℹ️ 중복 연결 정리: {len(dropped)}건 대체됨 (영구 무선이 우선){C.RESET}")
        return keep
    except Exception:
        return devs


def _adb_pair_wizard(adb):
    """무선 디버깅 pairing 1회 등록 마법사.

    [설계] 서드바이트 앱은 adb pairing 을 스스로 수행할 수 없다(Android hidden API 차단).
      → 폰에서 '기기 쌍 사용하여 디버깅 코드 연결' 화면으로 사용자를 안내하고,
        IP:포트 + 6자리 코드를 입력받아 adb pair 을 1회 실행한다.
      → 성공 시 IP 를 저장하므로 이후에는 매번 입력 없이 자동 재연결된다.
    """
    print(f"\r\n {C.BOLD}{C.SKY}📡 무선 ADB 최초 등록 (1회만 하면 됩니다){C.RESET}")
    print(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
    print(f"  1️⃣  폰: {C.YELLOW}설정 → 개발자 옵션{C.RESET} → {C.GREEN}무선 디버깅 ON{C.RESET}")
    print(f"  2️⃣  폰: {C.YELLOW}무선 디버깅{C.RESET} 화면 → {C.GREEN}'기기 쌍 사용하여 디버깅 코드 연결'{C.RESET}")
    print(f"  3️⃣  그 화면에 뜨는 {C.CYAN}IP 주소와 포트{C.RESET} + {C.CYAN}6자리 코드{C.RESET} 를 아래에 입력")
    print(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
    print(f"  ⏳ 코드는 {C.YELLOW}2분{C.RESET} 동안만 유효합니다. (오래 걸리면 3번부터 다시 여세요)")
    print()

    raw = prompt_input(" 👉 IP:포트 입력 (예: 192.168.0.5:41234): ").strip()
    if not raw:
        print(f" ⚠️ {C.YELLOW}입력 취소 — 등록을 건너뜁니다.{C.RESET}")
        return False
    raw = raw.replace(' ', '')
    if ':' not in raw:
        # 포트를 생략한 경우 기본 무선 디버깅 포트로 보정
        raw = f"{raw}:5555"
    code = prompt_input(" 👉 6자리 pairing 코드 입력: ").strip()
    if not code:
        print(f" ⚠️ {C.YELLOW}코드 미입력 — 등록을 건너뜁니다.{C.RESET}")
        return False

    print(f"\r\n 🔗 pairing 중... ({raw} / {code})")
    ok, out = _adb_run(adb, ['pair', raw, code], timeout=30)
    if ok and 'successfully paired' in out.lower():
        ip = raw.split(':')[0]
        _adb_save_ip(ip)
        print(f" ✅ {C.GREEN}pairing 성공!{C.RESET} 이제부터 자동 재연결됩니다. 🎉")
        print(f"    (IP 저장: {_ADB_DEVICES_FILE})")
        return True
    print(f" ❌ {C.RED}pairing 실패{C.RESET}")
    print(f"    {out[:300]}")
    if 'expired' in out.lower() or 'timeout' in out.lower():
        print(f"    💡 코드 만료 — 폰에서 다시 코드를 발급받고 재시도하세요.")
    print(f"    💡 폰과 PC 가 같은 Wi-Fi 인지, 방화벽이 adb 를 막는지 확인하세요.")
    return False


def _adb_autoconnect(adb):
    """자동 재연결.  1) 저장된 IP:5555 전부  2) mDNS 자동 발견

    [99 감사 P0 · 2026-10-10] 예전엔 '1대라도 연결돼 있으면 즉시 return' 해서
       나머지 폰을 연결 시도조차 하지 않았다 → 폰 2대 중 1대만 잡히는 증세.
    """
    # 1) 저장된 IP 는 끝까지 시도 (이미 연결된 기기에도 connect 는 0.1초로 무해)
    for ip in _adb_ip_strings():
        _adb_run(adb, ['connect', f'{ip}:5555'], timeout=15)

    # 2) mDNS 로 같은 네트워크의 무선 디버깅 기기 자동 발견
    ok, out = _adb_run(adb, ['mdns', 'services'], timeout=15)
    if ok:
        targets = []
        for line in out.splitlines():
            if '_adb-tls-connect._tcp' in line:
                hp = line.strip().split()[-1]
                if ':' in hp and hp not in targets:
                    targets.append(hp)
        for t in targets:
            _adb_run(adb, ['connect', t], timeout=15)
        # [99 감사 P1 · 2026-10-10] mDNS 발견 IP 는 **등록 파일에 넣지 않는다.**
        #   (같은 공유기의 남의 기기가 목록에 딸려 오는 문제 → 등록은 pairing/USB 고정만)

    return _adb_connected(adb)


# ══════════════════════════════════════════════════════════════════════
# [TAG: #@_adb_version_engine]  버전 비교 엔진
#   "폰에 지금 몇 버전이 깔려 있고, 내 PC 에는 몇 버전이 있는가" 를 대조한다.
#
#   로컬 APK   : aapt/aapt2 `dump badging` → package / versionCode / versionName
#   기기 설치본: `adb shell dumpsys package <pkg>` → versionCode / versionName
#
#   [규칙] AGENTS.md §공개/비공개 배포 경계 —
#     패키지명·앱 이름·버전 번호를 소스에 하드코딩하지 않는다.
#     전부 APK/기기에서 읽어내는 값이라 공개 저장소 배포본에서도 정보가 노출되지 않는다.
# ══════════════════════════════════════════════════════════════════════

def _adb_aapt_path():
    """Android SDK build-tools 의 aapt(없으면 aapt2) 경로. 못 찾으면 None."""
    local = os.environ.get('LOCALAPPDATA', '')
    sdk_roots = [
        os.path.join(local, 'Android', 'Sdk', 'build-tools'),
        os.path.join(os.environ.get('ANDROID_HOME', ''), 'build-tools'),
        os.path.join(os.environ.get('ANDROID_SDK_ROOT', ''), 'build-tools'),
        r'C:\Android\build-tools',
    ]
    for root in sdk_roots:
        if not root or not os.path.isdir(root):
            continue
        try:
            for ver in sorted(os.listdir(root), reverse=True):
                for exe in ('aapt.exe', 'aapt2.exe'):
                    p = os.path.join(root, ver, exe)
                    if os.path.isfile(p):
                        return p
        except Exception:
            continue
    for name in ('aapt.exe', 'aapt2.exe', 'aapt', 'aapt2'):
        p = shutil.which(name)
        if p:
            return p
    return None


_ADB_PKG_RE = re.compile(
    r"package:\s+name='([^']+)'\s+versionCode='(\d+)'\s+versionName='([^']*)'")


def _adb_local_apk_info(apk_path):
    """로컬 APK 의 {pkg, code, name}. 판독 실패면 None."""
    exe = _adb_aapt_path()
    if not exe or not os.path.isfile(apk_path):
        return None
    try:
        r = subprocess.run([exe, 'dump', 'badging', apk_path],
                           capture_output=True, text=True, timeout=60,
                           encoding='utf-8', errors='replace')
    except Exception:
        return None
    m = _ADB_PKG_RE.search(r.stdout or '')
    if not m:
        return None
    try:
        code = int(m.group(2))
    except Exception:
        code = None
    return {'pkg': m.group(1), 'code': code, 'name': m.group(3)}


def _adb_device_pkg_info(adb, dev, pkg):
    """기기에 설치된 pkg 의 {code, name}. 미설치/실패면 None."""
    if not pkg:
        return None
    ok, out = _adb_run(adb, ['-s', dev, 'shell', 'dumpsys', 'package', pkg], timeout=30)
    if not ok or not out:
        return None
    m = re.search(r'versionCode=(\d+)', out)
    if not m:
        return None
    n = re.search(r'versionName=(\S+)', out)
    try:
        code = int(m.group(1))
    except Exception:
        return None
    return {'code': code, 'name': n.group(1) if n else ''}


def _adb_version_status(local_code, dev_code):
    """(상태키, 라벨) — 'new'/'update'/'same'/'older'/'unknown'."""
    if dev_code is None:
        return 'new', '미설치 → 설치'
    if local_code is None:
        return 'unknown', '버전 판독 불가'
    if local_code > dev_code:
        return 'update', f'업데이트 필요 (설치본 {dev_code})'
    if local_code == dev_code:
        return 'same', f'최신 일치 ({dev_code})'
    return 'older', f'⚠ 로컬이 구버전 (설치본 {dev_code})'


def _adb_fmt_ver(v):
    """버전 표기 (versionName 우선, 없으면 versionCode)."""
    if not v:
        return '판독불가'
    return str(v.get('name') or v.get('code') or '?')


def _adb_compare_versions(apk_paths, adb, devs):
    """APK 목록 × 기기 목록 버전 비교표.

    반환: list of dict
        {'apk','basename','pkg','code','name','per_dev':{dev:info|None},
         'status','label','missing','n_missing'}

    [99 감사 P0 · 2026-10-10] 예전 판정은 **설치된 기기만** 모아서 최솟값을 냈다.
        codes = [v['code'] for v in per_dev.values() if v]   ← 미설치 기기가 소거됨
      그 결과 폰 3대 중 1대가 미설치여도 나머지 2대가 최신이면 `worest=최신` 이 되어
      '모두 최신입니다' 로 조기 종료했다(실측: Redmi 에 냥튜브·냥셸 미설치인데 최신으로 오인).
      → 이제 **미설치 기기가 한 대라도 있으면** 그것을 최우선으로Raising 한다.
         (설치본이 있는 기기 중 최솟값 비교는 그대로 유지)
    """
    rows = []
    for apk in apk_paths:
        info = _adb_local_apk_info(apk) or {}
        per_dev = {}
        for dev in (devs or []):
            per_dev[dev] = _adb_device_pkg_info(adb, dev, info.get('pkg'))
        # [규칙] 미설치 기기는 판정에서 버리지 않는다 — '설치 필요' 로 즉시 올린다.
        missing = [d for d, v in per_dev.items() if not v]
        # 설치된 기기들 중 '가장 구버전' 기준(하나라도 갱신 필요면 갱신으로 본다)
        codes = [v['code'] for v in per_dev.values() if v]
        worst = min(codes) if codes else None
        st, lb = _adb_version_status(info.get('code'), worst)
        if missing:
            # [P0] 일부 기기 미설치 → 업데이트 필요보다 '미설치' 가 우선(더 급한 조치)
            n_miss = len(missing)
            if st == 'new':
                lb = f'미설치 {n_miss}대 (전체 미설치)'
            else:
                st = 'new'
                lb = f'미설치 {n_miss}대 → 설치 필요'
        rows.append({
            'apk': apk,
            'basename': os.path.basename(apk),
            'pkg': info.get('pkg'),
            'code': info.get('code'),
            'name': info.get('name'),
            'per_dev': per_dev,
            'status': st,
            'label': lb,
            'missing': missing,
            'n_missing': len(missing),
        })
    return rows


# ══════════════════════════════════════════════════════════════════════
# [TAG: #@_adb_usb_engine]  USB → tcpip 5555 자동 고정 엔진
#
# [왜 이게 필요한가 — 사용자 정리(2026-10-10)]
#     · 무선 디버깅(토글)은 **폰 재부팅마다 꺼진다** → 매번 폰에서 손으로 켜야 한다.
#     · pairing 은 6자리 코드를 요구하므로 자동화가 불가능하다.
#     · adb tcpip 5555 는 **토글과 무관**하고, USB 1회면 그 뒤로 포트가 고정된다.
#       → USB 를 꽂은 상태로 이 기능을 한 번 실행하면, 그 뒤 USB 를 뽑고
#         리부팅해도 같은 IP:5555 로 바로 붙는다.
#     · 단, 폰을 **안 켜보는 날**에는 이 포트 설정도 초기화된다(그땐 폰에서 토글 필요).
#
#   [공개 배포 안전] 기기 시리얼·IP 는 전부 런타임 판독이라 소스에 값이 남지 않는다.
# ══════════════════════════════════════════════════════════════════════

def _adb_is_wireless_serial(s):
    """무선(mDNS/IP) 시리얼인지 — IP:PORT 또는 _adb-tls-* 형태."""
    s = (s or '').strip()
    return ':' in s or '_adb-tls-connect' in s or '_adb-tls-pairing' in s


def _adb_is_emulator_serial(s):
    """에뮬레이터 시리얼인지 (포맷 고정이라 로컬 전용 — 공개 배포 대상 아님)."""
    s = (s or '').strip().lower()
    return s.startswith('emulator-') or s.endswith('-5554') or s.endswith(':5554')


def _adb_usb_devices(adb):
    """USB 로 꽂혀 있는 **실제 폰** 시리얼 목록 (무선/mDNS/에뮬레이터 제외)."""
    ok, out = _adb_run(adb, ['devices'], timeout=20)
    if not ok:
        return []
    devs = []
    for line in out.splitlines()[1:]:
        parts = line.strip().split()
        if len(parts) >= 2 and parts[1] == 'device':
            s = parts[0]
            if _adb_is_wireless_serial(s) or _adb_is_emulator_serial(s):
                continue
            devs.append(s)
    return devs


def _adb_device_wifi_ip(adb, dev):
    """기기의 Wi-Fi(wlan) IP 를 알아낸다. 못 찾으면 None."""
    tries = [
        ['shell', 'ip', 'route'],
        ['shell', 'ip', '-f', 'inet', 'addr', 'show'],
        ['shell', 'ifconfig', 'wlan0'],
        ['shell', 'getprop', 'dhcp.wlan0.ipaddress'],
    ]
    for args in tries:
        ok, out = _adb_run(adb, ['-s', dev] + args, timeout=20)
        if not ok or not out:
            continue
        # 1) ip route : "192.168.100.0/24 dev wlan0 ... src 192.168.100.55"
        m = re.search(r'dev\s+wlan\d+[^\n]*?src\s+(\d{1,3}(?:\.\d{1,3}){3})', out)
        if m:
            return m.group(1)
        # 2) ip addr / ifconfig : "inet 192.168.100.55/24"
        m = re.search(r'inet\s+(?:addr:)?(\d{1,3}(?:\.\d{1,3}){3})', out)
        if m:
            return m.group(1)
        # 3) getprop 는 IP 문자열 그 자체
        t = out.strip().split()
        if len(t) == 1 and re.fullmatch(r'\d{1,3}(?:\.\d{1,3}){3}', t[0]):
            return t[0]
    return None


def _adb_usb_to_tcpip(port=5555, dev=None, quiet=False):
    """USB 로 꽂힌 폰을 tcpip 모드로 고정하고, 그 IP 를 저장 목록에 넣는다.

    [인자]
        port : 고정할 포트 (기본 5555 — 관습값)
        dev  : USB 시리얼. None 이면 꽂힌 폰이 1대일 때 자동 선택.
    [반환] dict {'ok', 'dev', 'ip', 'port', 'msg'}
    """
    def _say(m):
        if not quiet:
            print(m)

    adb = _adb_exe_path()
    if not adb:
        return {'ok': False, 'msg': 'adb 를 찾지 못했습니다.'}

    usb = _adb_usb_devices(adb)
    if not usb:
        return {'ok': False, 'msg': 'USB 로 꽂힌 폰이 없습니다. 케이블을 연결하세요.'}

    if dev:
        if not any(dev in u for u in usb):
            return {'ok': False, 'msg': f'지정한 기기가 USB 로 연결돼 있지 않습니다: {dev}'}
        target = dev
    elif len(usb) == 1:
        target = usb[0]
    else:
        return {'ok': False, 'msg': f'폰이 {len(usb)}대 연결돼 있습니다. 하나만 꽂거나 지정하세요.',
                'usb': usb}

    _say(f" 🔌 USB 기기: {target}")
    ok, out = _adb_run(adb, ['-s', target, 'tcpip', str(port)], timeout=30)
    if not ok or 'error' in (out or '').lower():
        return {'ok': False, 'msg': f'tcpip 설정 실패: {(out or "")[:200]}'}
    _say(f"    ✅ {C.GREEN}tcpip {port} 로 고정 요청 완료{C.RESET}")

    # adbd 가 재기동하는 동안 잠깐 대기 (실측 1~2초)
    time.sleep(2.5)

    ip = _adb_device_wifi_ip(adb, target)
    if not ip:
        return {'ok': False, 'dev': target, 'port': port,
                'msg': '폰의 Wi-Fi IP 를 못 읽었습니다. (Wi-Fi 가 켜져 있는지 확인하세요)'}

    _adb_save_ip(ip)
    _say(f"    📡 Wi-Fi IP: {ip}")

    ok2, _ = _adb_run(adb, ['connect', f'{ip}:{port}'], timeout=15)
    _say(f"    {'✅' if ok2 else 'ℹ️ '} 무선 연결 시도 {ip}:{port}")
    _say(f"    💾 IP 저장 완료 — 이제 USB 를 뽑아도 이 주소로 붙습니다.")

    return {'ok': True, 'dev': target, 'ip': ip, 'port': port,
            'msg': f'{ip}:{port} 로 고정 완료'}


# [TAG: #@_adb_sel_devs]  진행할 폰 지정(None = 연결된 전체 자동).
_ADB_SEL_DEVS = {'devs': None}

# [TAG: #@_adb_all_devs_sentinel]  "전체 기기" 선택을 나타내는 센티널.
#   None 은 '구분선 자리(선택 불가)' 라 쓰므로 둘을 구분해야 한다.
_ADB_ALL_DEVS = object()


# [TAG: #@_adb_vr_exclude]  ★ VR 헤드셋(Quest 등)은 **등록·표시만**, APK 설치는 제외
#   [규칙] 사용자 지시(2026-10-10) — 헤드셋도 adb 에 붙으므로 등록/상태는 그대로 두되,
#          폰 전용 APK 설치 대상·버전 비교표에서는 자동으로 뺀다.
#   [공개 배포 안전] 기기명·앱 이름·패키지명을 소스에 적지 않는다(키워드 판별만).
#   [주의] phone_common 이 없는 공개 배포본이면 **전부 설치 대상**(= 기존 동작) 유지.
def _adb_split_vr(devs):
    """(APK 설치 대상 기기, VR 헤드셋) 로 나눈다 — 판별 실패 시 전부 설치 대상."""
    devs = list(devs or [])
    if not devs:
        return [], []
    try:
        if not _PHONE_COMMON_OK:
            return devs, []
        from phone_common import phone_split_vr
        normal, vr = phone_split_vr(devs)
        return normal, vr
    except Exception:
        return devs, []


def _adb_ask_yes_no(question):
    """(Y/n) 질문 — '빈 엔터/y' 는 예. 사용자는 손가락 대화형에 익숙하다."""
    try:
        r = prompt_input(f" {question} (Y/n): ").strip().lower()
    except (KeyboardInterrupt, EOFError):
        return False
    return r in ('', 'y', 'yes', 'o', 'ㅇ', '예', '네')


def _adb_filter_by_version(adb, devs, apk_path, say=None, ask=None):
    """설치 대상에서 '이미 최신' 폰을 걸러낸다. → (남은 devs, 건너뛴 정보)

    [규칙] 2026-10-10 사용자 지시 —
      "우선 구버젼 설치된 폰만 필터해서 설치 진행하고,
       모두 최신 버젼이면 강제로 재설치 할래? 물어보도록"

    [판정]
      · 'new'(미설치) / 'update'(설치본이 구버전) → **설치 대상**
      · 'same'(최신 일치)                        → 건너뜀
      · 'older'(설치본이 PC보다 *새er*)          → 건너뜀
        (adb install -r 은 다운그레이드를 막는다 → INSTALL_FAILED_VERSION_DOWNGRADE)
      · 'unknown'(판독 불가)                     → **설치** (안전 쪽)

    [전부 최신일 때] ask() 로 '강제 재설치' 를 묻는다.
      · 예  → 전부 대상으로 돌려준다(기존처럼 강제 설치)
      · 아니오 → (None, info) 반환 → 호출부는 아무것도 하지 않는다

    [반환] (devs|None, info)
      devs 가 **None** 이면 '설치하지 않겠다'는 뜻(사용자가 아니오를 골랐다).
    """
    say = say or (lambda m: None)
    ask = ask or (lambda q: False)
    info = {'total': len(devs), 'skip_same': [], 'skip_older': [],
            'unknown': [], 'forced': False}

    # [안전] 로컬 APK 를 못 읽으면 판정을 못 하므로 **그대로 전부 설치**한다.
    local = _adb_local_apk_info(apk_path)
    if not local or not local.get('pkg') or local.get('code') is None:
        say(f" ℹ️ {C.GRAY}APK 버전 판독 불가 → 기존처럼 전체 기기에 설치합니다.{C.RESET}")
        return devs, info

    ver_txt = f"{local.get('name') or '?'} (code {local['code']})"
    say(f" 📋 로컬 APK : {C.CYAN}{ver_txt}{C.RESET}")

    todo, same_, older_, unknown = [], [], [], []
    devinfo = {}          # [성능] 기기당 dumpsys 는 1~3초 걸린다 → 결과를 저장해 재사용
    for dev in devs:
        dv = _adb_device_pkg_info(adb, dev, local['pkg'])
        devinfo[dev] = dv or {}
        dcode = (dv or {}).get('code')
        st, _label = _adb_version_status(local['code'], dcode)
        if st == 'new':
            todo.append(dev)
        elif st == 'update':
            todo.append(dev)
            say(f"   ⬆️ {dev}: {dcode} → {local['code']} 업데이트")
        elif st == 'same':
            same_.append(dev)
        elif st == 'older':
            older_.append(dev)
        else:                               # unknown = 판독 실패 → 안전하게 설치
            unknown.append(dev)
            todo.append(dev)
    info['skip_same'] = same_
    info['skip_older'] = older_
    info['unknown'] = unknown

    if same_:
        say(f" ⏭️ 이미 최신이라 건너뜀 {len(same_)}대: {', '.join(same_)}")
    if older_:
        say(f" ⏭️ 설치본이 더 최신이라 건너뜀 {len(older_)}대: {', '.join(older_)}"
            f" {C.GRAY}(다운그레이드 불가){C.RESET}")
    if unknown:
        say(f" ❓ 버전 판독 불가(설치 진행) {len(unknown)}대: {', '.join(unknown)}")

    # ── 전부 최신(또는 더 최신) → 강제 재설치를 묻는다 ──
    if not todo:
        # [성능] 위에서 이미 받아둔 정보를 재사용한다(여기서 다시 dumpsys 를 부르면
        #        폰 1대당 1~3초씩 **또** 걸린다).
        _names = ", ".join(f"{d} ({_adb_fmt_ver(devinfo.get(d))})"
                           for d in (same_ + older_))
        say("")
        say(f" 🎉 모든 기기가 최신 버전입니다 — 설치할 곳이 없어요.")
        say(f"    {_names}")
        if ask(f"    그래도 {len(same_) + len(older_)}대에 강제로 재설치할까요?"):
            say(f" 🔁 예 — 전대 강제 재설치합니다.")
            info['forced'] = True
            return list(same_) + list(older_), info
        return None, info
    return todo, info


# [TAG: #@_adb_explain_install_error]
def _adb_explain_install_error(out, say=None):
    """adb 설치 실패 로그에서 **원인별 해결책**을 뽑아 한 줄씩 알려준다. 🩺

    [규칙] 2026-10-10 — 실제 실패 로그를 보고 무엇을 해야 하는지 바로 알 수 있게 한다.
       "❌ 설치 실패" 만으로는 사용자가 답을 몰라 반복해서 실패한다.
    [특히] INSTALL_FAILED_USER_RESTRICTED 는 **기기가 스스로 막은 것**이라
       PC 를 아무리 고쳐도 해결되지 않는다 → 폰 쪽 설정을 안내해야 한다.
    """
    say = say or (lambda m: None)
    out = str(out or '')
    if 'INSTALL_FAILED_USER_RESTRICTED' in out:
        say(f"       🛡️ 폰이 설치를 **막은 것**입니다 (PC 문제가 아님). 해결책:")
        say(f"          ① 폰 화면을 켜고 잠금해제 상태로 두기 (잠그면 MIUI 가 막음)")
        say(f"          ② [개발자 옵션] → '설치 via USB' 또는 'USB 설치 허용' 켜기")
        say(f"          ③ [설정] → '알림' 에서 'APK 설치 허용' 켜기 (샤오미/MIUI 필수)")
        say(f"          ④ Google Play Protect '앱 설치 검사' 일시 해제")
        say(f"          ⑤ USB 디버깅을 껐다 켠 뒤 재시도")
    elif 'INSTALL_FAILED_UPDATE_INCOMPATIBLE' in out or 'signatures do not match' in out.lower():
        say(f"       💡 서명키 불일치 — 이 APK 는 다른 키로 서명됐다(keystore 원본 확인).")
    elif 'INSTALL_FAILED_VERSION_DOWNGRADE' in out:
        say(f"       💡 versionCode 가 낮음 — 버전 업이 필요합니다 (다운그레이드 불가).")
    elif 'INSTALL_FAILED_INSUFFICIENT_STORAGE' in out:
        say(f"       💡 저장 공간 부족 — 폰에서 여유 공간을 확보하세요.")
    elif 'INSTALL_FAILED_TEST_ONLY' in out:
        say(f"       💡 testOnly 플래그가 붙은 APK — 실제 배포 APK로 빌드하세요.")
    elif 'DELETE_FAILED_INTERNAL_ERROR' in out:
        say(f"       💡 기존 앱 삭제 실패 — '설정 → 앱' 에서 직접 지운 뒤 재시도.")
    else:
        say(f"       💡 위 메시지를 그대로 읽어볼 것 (원인은 폰·네트워크에 따라 다름).")


def _adb_install_apk(apk_path, quiet=False, only_devs=None):
    """연결된 기기에 adb install -r 로 APK 를 무음(설치창 0회) 설치한다.

    [규칙] AGENTS.md §스크립트 내재화 — 서명키가 동일하고 versionCode 가 오를 때만 성공한다.
    [인자]
        only_devs : 이 기기(들)에만 설치. None 이면 메뉴에서 고른 폰(_ADB_SEL_DEVS)을 쓰고,
                    그것도 없으면 연결된 전체에 설치한다.
    """
    def _say(msg):
        if not quiet:
            print(msg)

    adb = _adb_exe_path()
    if not adb:
        _say(f" ⚠️ {C.YELLOW}adb 를 찾지 못했습니다. (설치 스킵){C.RESET}")
        return False
    if not os.path.exists(apk_path):
        _say(f" ⚠️ {C.YELLOW}APK 없음{C.RESET}: {apk_path}")
        return False

    devs = _adb_autoconnect(adb)
    if not devs:
        _say(f" ⚠️ {C.YELLOW}연결된 기기 없음 — 스킵{C.RESET}")
        return False

    # [규칙] 사용자가 메뉴에서 고른 폰이 있으면 그 폰에만 설치한다.
    want = only_devs if only_devs is not None else _ADB_SEL_DEVS.get('devs')
    if want:
        picked = [d for d in devs if d in want]
        if not picked:
            _say(f" ⚠️ {C.YELLOW}선택한 폰이 연결되어 있지 않음 — 스킵 ({', '.join(want)}){C.RESET}")
            return False
        devs = picked

    # ★ [규칙] 2026-10-10 — 'APK 설치할 기기 지정' 의 **예외폰**을 먼저 걷어낸다.
    #   [왜 여기?] 모든 설치 경로(단일 설치 / 일괄 / 버전 확인 후 배포)가
    #          **다 이 함수를 지난다** → 여기가 유일한 관문이라 한 번만 막으면 된다.
    #   [주의] 저장된 제외는 IP 기준이다. 시리얼은 'IP:포트'/'USB시리얼' 형태라
    #          그대로 비교하면 안 되고 IP 로 나눠 비교해야 한다.
    if _PHONE_COMMON_OK:
        _apk_ex = _phone_apk_exclude()
        if _apk_ex:
            _kept = [d for d in devs if (str(d).split(':')[0]) not in _apk_ex]
            _dropped = [d for d in devs if (str(d).split(':')[0]) in _apk_ex]
            if _dropped:
                _say(f" 🚫 예외폰 {len(_dropped)}대 제외: {', '.join(_dropped)}")
            if not _kept:
                _say(f" ⚠️ {C.YELLOW}모든 기기가 예외폰으로 지정됨 — 스킵{C.RESET}")
                _say(f"     💡 'APK 설치할 기기 지정' 에서 최소 1대를 체크하세요.")
                return False
            devs = _kept

    # ★ [규칙] VR 헤드셋은 APK 설치 대상에서 제외한다(등록·표시는 유지).
    devs, _vr = _adb_split_vr(devs)
    if not devs:
        _say(f" ⚠️ {C.YELLOW}APK 설치 대상 기기 없음 (VR 기기만 연결됨) — 스킵{C.RESET}")
        return False

    # ══ 🛡️ 버전 선필터 (2026-10-10 사용자 지시) ══
    #   "기존 설치된 버젼 체크 무시하고 강제로 설치가 진행되는데,
    #    우선 구버젼 설치된 폰만 필터해서 설치 진행하고,
    #    모두 최신 버젼이면 강제로 재설치 할래? 물어보도록"
    #   → 구버전/미설치 폰만 'adb install' 을 태우고, 최신 폰은 건너뛴다.
    #   → 건너뛸 폰이 하나라도 있으면 질문 없이 진행한다(묻는다면 시끄러움).
    #   [안전] 로컬 APK 판독이 실패하면 **기존처럼 전부 설치**한다(안전 쪽).
    devs, _skipped = _adb_filter_by_version(
        adb, devs, apk_path, say=lambda m: _say(m),
        ask=lambda q: _adb_ask_yes_no(q))
    if devs is None:                      # 전부 최신 + 강제 재설치 '아니오'
        return True
    if not devs:
        _say(f" ⏭️ 설치할 폰 없음 — 모두 최신 버전입니다.")
        return True

    all_ok = True
    for dev in devs:
        # [규칙] 2026-10-10 사용자 지시 — 시리얼만 찍으면 '어느 폰인지' 알 수 없다.
        #   → 기기 이름(모델·OS)과 배터리/IP 를 **먼저** 한 줄 찍고 adb 줄을 잇는다.
        #   [성능] _phone_info_by_ip 는 캐시만 읽는다(adb 호출 없음) → 느려지지 않는다.
        _ip = str(dev).split(':')[0]
        _inf = (_phone_info_by_ip(_ip) if _PHONE_COMMON_OK else {}) or {}
        _nm = _adb_device_label(_inf) or _ip
        _bg = _adb_device_badges(_inf)
        _ex = f" {C.GRAY}[{_bg}]{C.RESET}" if _bg else ""
        _say(f"    · {_nm}{_ex}")
        _say(f" 📱 adb install -r → {dev}")
        ok, out = _adb_run(adb, ['-s', dev, 'install', '-r', apk_path], timeout=180)
        if ok and 'Success' in out:
            _say(f"    ✅ {C.GREEN}설치 완료!{C.RESET} ({os.path.basename(apk_path)})")
        else:
            all_ok = False
            _say(f"    ❌ {C.RED}설치 실패{C.RESET}: {out[:300]}")
            _adb_explain_install_error(out, say=lambda m: _say(m))
    return all_ok


def _adb_registered_apks(settings):
    """현재 등록된 APK 목록(경로 리스트)을 원본 그대로 반환한다 (캐시 무시)."""
    if not settings:
        return []
    try:
        reg = settings.data.get('adb_apk_targets', [])
    except Exception:
        return []
    if not isinstance(reg, list):
        return []
    out = []
    for item in reg:
        if isinstance(item, str):
            out.append(item)
        elif isinstance(item, dict):
            p = item.get('path', '')
            if p:
                out.append(p)
    return out


def _adb_register_apks(settings, paths, app_dir):
    """APK 목록을 settings.json(비공개) 에 등록한다. 등록값을 반환."""
    if not settings:
        return []
    reg = _adb_registered_apks(settings)
    # 중복 제거(정규화 경로 기준)
    norm = {os.path.normpath(p) for p in reg}
    for p in paths:
        if os.path.normpath(p) not in norm:
            reg.append(p)
            norm.add(os.path.normpath(p))
    settings.data['adb_apk_targets'] = reg
    settings.save()
    return reg


def _adb_unregister_apks(settings, paths):
    """등록된 APK 목록에서 제거한다."""
    if not settings:
        return []
    drop = {os.path.normpath(p) for p in paths}
    reg = [p for p in _adb_registered_apks(settings) if os.path.normpath(p) not in drop]
    settings.data['adb_apk_targets'] = reg
    settings.save()
    return reg


# [TAG: #@_adb_menu_esc]
def _adb_menu_esc(fn, *args, **kwargs):
    """_interactive_menu 호출 래퍼 — ESC 예외를 '정상 취소'로 바꿔 돌려준다. 🛡️

    [문제 · 2026-10-10 사용자 지적]
      "메인 → 서브 → 서브2 상태에서 서브2에서 esc 누르면 **간혹** 메인으로 가더라고"
      원인: _interactive_menu 는 ESC 를 받으면 '취소키워드(뒤로가기/취소…)' 가 있는
      메뉴에서 `raise UserAbortException()` 한다. 이 예외는 **BaseException** 자손이라
      `except Exception` 으론 안 잡히고 **호출 스택을 그대로 관통**한다.
      → 서브2에서 ESC 를 누르면 '바로 위(서브)' 를 건너뛰고 **메인 메뉴로 직행**했다.

    [해법] 여기서 **한 번만** 받아서 정상적인 '취소(-1)' 로 바꿔 반환한다.
      → 호출자는 기존 취소 분기(보통 return)로 평온히 **한 단계 위**로 돌아간다.

    [범위] **21번(ADB 무선배포·미러링) 안의 하위 메뉴에만** 적용한다.
      · 서브1(_adb_deploy_menu)은 ESC → 메인 이 **맞는** 동작이라 손대지 않는다.
      · 다른 메뉴(구글 슬라이드쇼 등)는 범위를 넓히면 회귀 위험이 커서 제외.

    [반환형] _interactive_menu 의 반환과 **같은 모양**을 유지한다(5-튜플).
      그래야 호출부의 `sel, _, *_ = ...` 언패킹이 깨지지 않는다.
    """
    try:
        return fn(*args, **kwargs)
    except UserAbortException:
        return -1, "CANCEL", [], -1, ""


def _adb_apk_register_wizard(settings, app_dir):
    """APK 검색 · 등록 마법사 (폴더를 지정해 APK 를 찾아 등록 목록에 추가).

    [패턴] AGENTS.md §빈 엔터=종료 일괄 입력 — 여러 APK 를 계속 선택/입력할 수 있고,
           빈 엔터로 확정 후 한 번에 등록한다.
    """
    while True:
        print(f"\r\n {C.BOLD}{C.SKY}🔍 APK 검색 · 등록{C.RESET}")
        print(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")

        scan_opts = [
            f"📂 현재 폴더에서 검색  {C.GRAY}[{app_dir}]{C.RESET}",
            f"🖇️ 경로 직접 입력 (붙여넣기 가능)",
            "↩️ 돌아가기",
        ]
        s_sel, _, *_ = _adb_menu_esc(_interactive_menu, "APK 검색 범위를 선택하세요", scan_opts)
        if s_sel < 0 or s_sel >= 2:
            return

        if s_sel == 0:
            scan_dir = app_dir
        else:
            raw = prompt_input(" 👉 검색할 폴더 경로 입력: ").strip().strip('"')
            if not raw:
                print(f" ⚠️ {C.YELLOW}입력 취소{C.RESET}")
                continue
            scan_dir = os.path.abspath(os.path.expanduser(raw))
            if not os.path.isdir(scan_dir):
                print(f" ❌ {C.RED}폴더가 아닙니다: {scan_dir}{C.RESET}")
                time.sleep(2)
                continue

        print(f"\r\n 🔍 검색 중... {scan_dir}")
        found = _adb_scan_apks(scan_dir, recursive=True)
        if not found:
            print(f" ⚠️ {C.YELLOW}APK 를 찾지 못했습니다.{C.RESET}")
            try:
                input(f"\n {C.GRAY}Enter 키를 누르면 돌아가요...{C.RESET}")
            except (KeyboardInterrupt, EOFError):
                pass
            continue

        already = {os.path.normpath(p) for p in _adb_registered_apks(settings)}

        # ── 다중 선택 (스페이스 토글 · a 전체선택 · Enter 확정) ──
        sel_opts = []
        for p in found:
            is_reg = os.path.normpath(p) in already
            badge = f" {C.GREEN}[이미 등록됨]{C.RESET}" if is_reg else ""
            rel = os.path.relpath(p, scan_dir)
            sel_opts.append(f"📄 {rel}{badge}")

        print(f" {C.GRAY}스페이스=토글 / a=전체 / Enter=확정 / 숫자=즉시 선택{C.RESET}")
        sel, _act, _sel_idx, *_ = _adb_menu_esc(_interactive_menu,
            f"업데이트 대상으로 등록할 APK 선택 (총 {len(found)}개 발견)",
            sel_opts, allow_multi=True
        )

        # [규칙] AGENTS.md §다중선택 반환값 —
        #   allow_multi=True 이면 1순위 반환값이 list(선택 인덱스) 또는 int(단일/취소)다.
        #   int(-1) 는 취소다. 반드시 isinstance 로 방어해야 한다.
        if isinstance(sel, list):
            picked = [found[i] for i in sel if 0 <= i < len(found)]
        elif isinstance(sel, int) and sel >= 0 and sel < len(found):
            picked = [found[sel]]
        else:
            picked = []

        if not picked:
            print(f" ⚠️ {C.YELLOW}선택된 APK 가 없습니다.{C.RESET}")
            try:
                input(f"\n {C.GRAY}Enter 키를 누르면 돌아가요...{C.RESET}")
            except (KeyboardInterrupt, EOFError):
                pass
            continue

        print(f"\r\n {C.BOLD}{C.CYAN}선택한 APK {len(picked)}개{C.RESET}")
        for p in picked:
            print(f"   📦 {os.path.basename(p)}")

        reg = _adb_register_apks(settings, picked, app_dir)
        print(f"\r\n ✅ {C.GREEN}등록 완료!{C.RESET} (총 {len(reg)}개)")
        print(f"    이제 '메뉴 → {os.path.basename(picked[0]) if picked else 'APK'}' 로 상시 업데이트할 수 있습니다.")
        try:
            input(f"\n {C.GRAY}Enter 키를 누르면 돌아가요...{C.RESET}")
        except (KeyboardInterrupt, EOFError):
            pass
        return


def _adb_apk_manage_wizard(settings, app_dir):
    """📋 APK 대상 관리 (검색 · 등록 · 해제) 마법사.

    [규칙] 2026-10-10 사용자 지시 — 최상위 메뉴에 따로 있던 'APK 검색·등록' 을
      **여기 안으로 넣었다**(메뉴가 길고 헷갈렸음).
      → 이 화면 한 곳에서 '찾아 등록' 과 '등록 해제' 를 모두 한다.
    [개선] 예전엔 등록된 APK 가 0개면 **즉시 return** 해서 '검색·등록' 화면에
      아예 갈 수 없었다(막다른 길). 이제는 0개여도 '검색·등록' 이 보인다.
    [루프] 등록/해제 후 목록이 바로 바뀌어야 하므로 같은 화면을 다시 그린다.
    """
    while True:
        reg = _adb_registered_apks(settings)
        m_opts = []
        for p in reg:
            exists = "🟢" if os.path.exists(p) else "❌"
            m_opts.append(f"{exists} {os.path.basename(p)} {C.GRAY}[{os.path.dirname(p)}]{C.RESET}")
        m_opts.append("──────────────────────────────────────────────────────────")
        m_opts.append("🔎 APK 검색 · 등록  (폴더를 지정해 APK 를 찾아 등록)")
        m_opts.append("🚪 뒤로가기")

        _n_reg = len(reg)
        header = [
            f" {C.GOLD}📋 APK 대상 관리{C.RESET}",
            " ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
            f"  • 등록된 APK: {C.GREEN}{_n_reg}개{C.RESET}",
            " ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
            f"  💡 {C.GRAY}APK 를 고르면 등록에서 빼고, '검색·등록' 을 고르면 새로 추가해요.{C.RESET}",
        ]
        sel, _, *_ = _adb_menu_esc(_interactive_menu, "APK 대상 관리", m_opts, dynamic_header_callback=lambda _=0: "\n".join(header))
        if not isinstance(sel, int) or sel < 0 or sel >= len(m_opts):
            return                       # ESC / 뒤로가기
        _pick = m_opts[sel]

        if _pick.startswith("🔎"):
            # ── 검색 · 등록 (기존 7번 메뉴 functionality) ──
            _adb_apk_register_wizard(settings, app_dir)
            continue                    # 등록 결과가 반영되도록 목록을 다시 그린다
        if _pick.startswith("🚪"):
            return

        # ── 등록 해제 ──
        idx = sel
        if idx >= len(reg):
            continue
        target = reg[idx]
        ans = prompt_input(f" 🗑️ {os.path.basename(target)} 을(를) 등록에서 뺄까요? [y/N]: ").strip().lower()
        if ans == 'y':
            _adb_unregister_apks(settings, [target])
            print(f"\r\n 🗑️ {C.GREEN}등록 해제 완료{C.RESET}")
        else:
            print(f"\r\n ↩️ 취소")
        try:
            input(f"\n {C.GRAY}Enter 키를 누르면 돌아가요...{C.RESET}")
        except (KeyboardInterrupt, EOFError):
            return


# [TAG: #@_adb_all_devices_sentinel]  "전체 기기(모두 삭제)" 를 나타내는 센티널.
_ADB_ALL_DEVICES = object()


def _adb_reset_wizard():
    """🗑️ 등록 기기 정리 — **하나씩 골라 지우거나**, 전체를 지운다.

    [규칙] 2026-10-10 사용자 지시 — 예전엔 '파일 통째 삭제' 한 방뿐이라
           폰 하나만 빼고 싶어도 전부 지워야 했다(다시 pairing 필요 = 회복 비용 큼).
    [패턴] AGENTS.md §다중선택 — Space 로 여러 개 골라 한 번에 지운다.
    [주의] 개별 삭제는 '나머지 유지'로 저장(기기 정보 캐시 보존),
           전체 삭제만 파일 통째(정보 캐시까지 제거)다.
    """
    devs = _adb_load_ips()               # list[dict]
    if not devs:
        print(f"\r\n ℹ️ {C.GRAY}등록된 기기가 없습니다.{C.RESET}")
        time.sleep(2)
        return

    _cache = _adb_load_info() or {}
    _ip2info = {}
    for _inf in _cache.values():
        if isinstance(_inf, dict) and _inf.get('ip'):
            _ip2info.setdefault(_inf['ip'], _inf)
    _adb = _adb_exe_path()
    _live = _adb_connected(_adb) if _adb else []

    opts, keys = [], []
    for _d in devs:
        _ip = _d.get('ip') if isinstance(_d, dict) else str(_d)
        _info = _ip2info.get(_ip) or {}
        _alias = (_d.get('alias') or '') if isinstance(_d, dict) else ''
        _nm = _adb_device_label(_info) or _alias or _ip
        _bg = _adb_device_badges(_info)
        _st = '연결됨' if any(_ip in _x for _x in _live) else '미연결'
        _ex = ' · '.join([f"{_ip} · {_st}"] + ([_bg] if _bg else []))
        opts.append(f"📱 {_nm} {C.GRAY}[{_ex}]{C.RESET}")
        keys.append(_ip)
    opts.append("──────────────────────────────────────────────────────────")
    keys.append(None)
    opts.append(f"🔥 {C.RED}전체 삭제 ({len(devs)}대){C.RESET} "
                f"{C.GRAY}[등록 이력·기기 정보까지 모두 지움]{C.RESET}")
    keys.append(_ADB_ALL_DEVICES)

    print(f"\r\n {C.BOLD}{C.SKY}🗑️ 등록 기기 정리{C.RESET}")
    print(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
    sel, _, *_ = _adb_menu_esc(_interactive_menu,
        "지울 기기를 고르세요 (Space 다중선택 · 전체 삭제는 맨 아래)",
        opts, allow_multi=True)
    if not isinstance(sel, list) or not sel:
        print(f"\r\n ↩️ {C.YELLOW}취소 — 아무것도 지우지 않았습니다.{C.RESET}")
        time.sleep(1.5)
        return
    picked = [keys[i] for i in sel if 0 <= i < len(keys) and keys[i] is not None]
    if not picked:
        print(f"\r\n ↩️ {C.YELLOW}취소 — 아무것도 지우지 않았습니다.{C.RESET}")
        time.sleep(1.5)
        return

    # ── 전체 삭제 ──
    if _ADB_ALL_DEVICES in picked:
        print(f"\r\n {C.RED}⚠️ 등록된 기기 {len(devs)}대를 모두 지웁니다.{C.RESET}")
        print(f"    {C.GRAY}(지우면 pairing 을 다시 해야 합니다 — USB 고정으로 복구 가능){C.RESET}")
        ans = prompt_input(" 진짜 지울까요? [y/N]: ").strip().lower()
        if ans != 'y':
            print(f"\r\n ↩️ 취소")
            time.sleep(1.5)
            return
        try:
            if os.path.exists(_ADB_DEVICES_FILE):
                os.remove(_ADB_DEVICES_FILE)
            print(f"\r\n 🗑️ {C.GREEN}등록 목록을 전부 초기화했습니다.{C.RESET}")
        except Exception as e:
            print(f"\r\n ❌ {C.RED}초기화 실패:{C.RESET} {e}")
        time.sleep(1.5)
        return

    # ── 개별 삭제 (나머지 기기·정보 캐시는 그대로 보존) ──
    #   [99 감사 P2 · 2026-10-10] 직접 json 덮어쓰기(중간에 끊기면 파일이 깨진다)를
    #   피하려고 phone_common 의 phone_remove_ip(원자적, force) 를 우선 사용한다.
    try:
        if _PHONE_COMMON_OK:
            from phone_common import phone_remove_ip as _p_remove_ip
            _ok = 0
            for ip in picked:
                if _p_remove_ip(ip):
                    _ok += 1
                    print(f"\r\n 🗑️ 삭제 완료: {C.GRAY}{ip}{C.RESET}")
                else:
                    print(f"\r\n ❌ {C.RED}삭제 실패:{C.RESET} {ip}")
            print(f"\r\n ✅ {C.GREEN}{_ok}대 삭제{C.RESET} "
                  f"{C.GRAY}(남은 등록 {len(_adb_load_ips())}대){C.RESET}")
        else:
            _left = [d for d in _adb_load_ips()
                     if (d.get('ip') if isinstance(d, dict) else str(d)) not in set(picked)]
            _tmp = _ADB_DEVICES_FILE + '.tmp'
            with open(_tmp, 'w', encoding='utf-8') as f:
                json.dump({'devices': _left, 'info': _cache}, f, ensure_ascii=False, indent=2)
            os.replace(_tmp, _ADB_DEVICES_FILE)      # 원자적 교체
            for ip in picked:
                print(f"\r\n 🗑️ 삭제 완료: {C.GRAY}{ip}{C.RESET}")
            print(f"\r\n ✅ {C.GREEN}{len(picked)}대 삭제{C.RESET} "
                  f"{C.GRAY}(남은 등록 {len(_left)}대){C.RESET}")
    except Exception as e:
        print(f"\r\n ❌ {C.RED}삭제 실패:{C.RESET} {e}")
    time.sleep(1.5)


def _adb_device_pick_wizard(devs):
    """📱 진행할 폰(기기) 선택 — 특정 폰만 골라 그 폰에만 배포한다.

    [규칙] AGENTS.md §다중선택 반환값 — list(int) / int / -1 모두 방어한다.
    [기능] 기기 시리얼(adb-XXXX...) 대신 **모델명·제조사·OS·배터리** 를 보여준다.
           수집한 정보는 temp/adb_devices.json 의 'info' 에 저장되어 재사용된다.
    [반환] list[str] (선택 시리얼) / None (취소·변경 없음)
    """
    ips = _adb_ip_strings()
    cur = _ADB_SEL_DEVS.get('devs')

    # ★ [규칙] VR 헤드셋은 설치 대상 목록에서 빼고(등록·표시는 유지), 아래에 안내로 남긴다.
    devs = list(devs or [])
    _info0 = _adb_dev_info_map(_adb_exe_path(), devs) if devs else {}
    devs, _vr = _adb_split_vr(devs)
    if cur:
        cur = [d for d in cur if d not in _vr]

    print(f"\r\n {C.BOLD}{C.SKY}📱 진행할 폰 선택{C.RESET}")
    print(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
    if _vr:
        _vnames = ', '.join(_adb_device_label(_info0.get(d) or {}) or d for d in _vr)
        print(f" {C.GRAY}🎮 VR 헤드셋은 등록만 유지하고 APK 설치 대상에서 제외: {_vnames}{C.RESET}")
    if not devs:
        if _vr:
            print(f" {C.YELLOW}🎮 VR 헤드셋만 연결되어 있습니다 — APK 설치 대상 기기가 없습니다.{C.RESET}")
        else:
            print(f" {C.YELLOW}⚠️ 연결된 기기가 없습니다. '무선 ADB 최초 등록' 을 먼저 하세요.{C.RESET}")
        return None

    # ── 기기 정보 수집 (셸 1회 호출씩, 실패해도 메뉴는 그대로 진행) ──
    adb = _adb_exe_path()
    print(f" {C.GRAY}📡 기기 정보 확인 중...{C.RESET}")
    info_map = _adb_dev_info_map(adb, devs)

    opts, keys = [], []
    # ① 전체 기기(제한 없음)
    all_tag = f" {C.GREEN}[현재]{C.RESET}" if not cur else ""
    opts.append(f"📱 전체 기기로 진행 {C.GRAY}(연결된 모든 기기){C.RESET}{all_tag}")
    keys.append(_ADB_ALL_DEVS)
    # ── [규칙] opts 와 keys 는 **인덱스가 1:1로 대응**해야 한다.
    #    구분선을 넣을 때도 keys 에 자리를 비워야 sel 인덱스가 어긋나지 않는다.
    #    (구분선 자리 = None → 선택 불가이므로 아래에서 걸러진다)
    opts.append("──────────────────────────────────────────────────────────")
    keys.append(None)
    # ② 개별 기기 — 모델명 우선, 없으면 시리얼
    for d in devs:
        mark = f" {C.GREEN}[현재 선택됨]{C.RESET}" if cur and d in cur else ""
        _info = info_map.get(d) or {}
        _label = _adb_device_label(_info)
        _badges = _adb_device_badges(_info)
        _ex = f" {C.GRAY}[{_badges}]{C.RESET}" if _badges else ""
        _name = _label if _label else d
        # 세로가 짧은 메뉴이므로 상세(시리얼/ABI)는 한 줄로 덧붙이지 않는다.
        #   필요하면 아래 '📋 선택한 폰 상세 정보' 항목에서 언제든 볼 수 있다.
        opts.append(f"📱 {_name}{_ex}{mark}")
        keys.append(d)
    # ③ 등록은 되어 있으나 지금 연결 안 된 IP → 선택 시 재연결 시도
    #    [규칙] VR 헤드셋 IP 는 여기서도 뺀다(선택하면 APK 설치 대상이 되어버린다).
    _vr_ips = set()
    try:
        for _inf in (_adb_load_info() or {}).values():
            if isinstance(_inf, dict) and _inf.get('ip'):
                try:
                    from phone_common import phone_is_vr_device as _p_is_vr
                    if _p_is_vr(_inf):
                        _vr_ips.add(_inf['ip'])
                except Exception:
                    pass
    except Exception:
        _vr_ips = set()
    offline = [ip for ip in ips
               if ip not in _vr_ips and not any(ip in d for d in devs)]
    if offline:
        opts.append("──────────────────────────────────────────────────────────")
        keys.append(None)
        # 캐시된 정보에서 IP 로 기기를 찾아 이름까지 보여준다
        for ip in offline:
            _cached = ''
            for _dev, _inf in info_map.items():
                if _inf.get('ip') == ip:
                    _cached = _adb_device_label(_inf)
                    break
            _nm = f"{_cached} " if _cached else ""
            opts.append(f"🔗 {_nm}{ip} {C.YELLOW}[미연결 · 선택하면 연결 시도]{C.RESET}")
            keys.append(ip)

    # ④ 연결된 폰의 상세 정보 보기 (시리얼·ABI·SDK·보안패치 등)
    opts.append("──────────────────────────────────────────────────────────")
    keys.append(None)
    i_detail = len(opts)
    opts.append(f"📋 {ctext('연결된 폰 상세 정보 보기 (기종·OS·시리얼·배터리)', C.SKY)}")
    keys.append('__DETAIL__')

    # ⑤ 취소 항목 — [규칙] 2026-10-10 사용자 지적("취소 메뉴가 빠진 곳 더 있나")
    #   · 이 메뉴에는 '전체 기기' 가 있어서 ESC(-1/[]) 와 '전체 기기' 를 헷갈릴 수 있다.
    #   → 눈에 보이는 '취소' 를 놓고, 누르면 **아무것도 바꾸지 않고** 그대로 나간다.
    opts.append("──────────────────────────────────────────────────────────")
    keys.append(None)
    # [주의] '취소' 를 단독으로 고르면 int 인덱스로 돌아오고,
    #   아래의 'ESC/빈 선택' 분기가 그대로 "취소" 로 처리한다(따로 분기 불필요).
    opts.append(f"🚪 {ctext('취소하고 돌아가기 (설정 그대로)', C.SKY)}")
    keys.append('__CANCEL__')

    def _detail_cb(_=0):
        """헤더에 연결된 폰 정보를 표로 보여준다."""
        lines = [f" {C.GOLD}📱 연결된 폰 상세 정보{C.RESET}",
                 " ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"]
        if not info_map:
            lines.append(f"  {C.YELLOW}연결된 기기가 없습니다.{C.RESET}")
        for _d, _i in info_map.items():
            nm = _adb_device_label(_i) or _d
            lines.append(f"  📱 {ctext(nm, C.GREEN)}")
            if _i.get('android'):
                lines.append(f"     {C.GRAY}· OS{C.RESET} 안드로이드 {_i.get('android')} "
                             f"{C.GRAY}(API {_i.get('sdk', '-')}){C.RESET}")
            if _i.get('serial'):
                lines.append(f"     {C.GRAY}· 시리얼{C.RESET} {_i.get('serial')}")
            if _i.get('ip'):
                lines.append(f"     {C.GRAY}· IP{C.RESET} {_i.get('ip')}")
            if _i.get('abi'):
                lines.append(f"     {C.GRAY}· 아키텍처{C.RESET} {_i.get('abi')}")
            if _i.get('battery'):
                lines.append(f"     {C.GRAY}· 배터리{C.RESET} {_i.get('battery')}%")
            if _i.get('free'):
                lines.append(f"     {C.GRAY}· 저장공간 여유{C.RESET} {_i.get('free')}")
            lines.append(f"     {C.GRAY}· adb 시리얼{C.RESET} {_d}")
        lines.append(" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
        return "\n".join(lines)

    sel, _, *_ = _adb_menu_esc(_interactive_menu,
        "진행할 폰을 고르세요 (Space 다중선택 · 해당 폰에만 설치됩니다)",
        opts, allow_multi=True,
        dynamic_header_callback=_detail_cb)
    # [99 감사 P1 · 2026-10-10] 취소와 "전체 기기" 선택을 반드시 구분한다.
    #   allow_multi 메뉴에서 ESC/빈 선택은 [] 로 돌아오는데, 이를 "전체 기기"로
    #   해석하면 **사용자가 취소했는데도 지정 폰이 풀려버린다.**
    if not isinstance(sel, list) or not sel:
        # '상세 정보' 항목이 눌린 경우(단일 인덱스 반환) → 상세 화면 후 복귀
        if sel == i_detail:
            _adb_device_detail_screen(info_map)
            return None
        print(f"\r\n ↩️ {C.YELLOW}취소 — 기존 지정 그대로입니다.{C.RESET}")
        return None
    # [규칙] '__DETAIL__' / '__CANCEL__' 은 메뉴 동작용 마커이지 기기 시리얼이 아니다.
    #   구분선(None)과 함께 걸러내 기기 목록에 섞이지 않게 한다.
    picked_keys = [keys[i] for i in sel
                   if 0 <= i < len(keys)
                   and keys[i] is not None
                   and keys[i] not in ('__DETAIL__', '__CANCEL__')]
    if not picked_keys:
        print(f"\r\n ↩️ {C.YELLOW}취소 — 기존 지정 그대로입니다.{C.RESET}")
        return None
    # "전체 기기" 를 함께 골랐으면 제한 없음으로 해석한다(가장 넓은 선택이 우선).
    if _ADB_ALL_DEVS in picked_keys:
        _ADB_SEL_DEVS['devs'] = None
        print(f"\r\n ☀️  {C.GREEN}전체 기기{C.RESET}로 진행합니다.")
        return None

    picked = list(picked_keys)
    # 미연결 IP 가 섞였으면 연결 시도
    adb = _adb_exe_path()
    if adb:
        for ip in list(picked):
            if any(ip in d for d in devs):
                continue
            tgt = ip if ':' in ip else f'{ip}:5555'
            print(f"\r\n 🔗 연결 시도: {tgt} …")
            _adb_run(adb, ['connect', tgt], timeout=15)
    live = _adb_connected(adb) if adb else []
    live = live or devs
    picked = [p for p in picked if any(p in d for d in live)]
    if not picked:
        print(f"\r\n ❌ {C.RED}선택한 폰에 연결하지 못했습니다.{C.RESET}")
        return None

    _ADB_SEL_DEVS['devs'] = picked
    print(f"\r\n ✅ {C.GREEN}선택 완료{C.RESET} → {', '.join(picked)}")
    # [★ 문구 정정 · 2026-10-11] 예전엔 "이제 아래 모든 배포는 이 폰에만 진행됩니다" 라고
    #   안내했는데, 이 세션 지정(_ADB_SEL_DEVS)은 **APK 설치(_adb_install_apk)와
    #   버전 비교(_adb_version_wizard)만** 참조한다. 화면 미러링은 phone_common 쪽
    #   별도 지정('미러링할 기기 지정')을 쓰므로 "모든 배포" 라고 말하면 거짓말이다.
    #   → 사용자가 범위를 정확히 알 수 있게 명시한다.
    print(f"    {C.GRAY}적용 범위: APK 설치 · 버전 비교 (화면 미러링은 '미러링할 기기 지정' 따로){C.RESET}")
    return picked


def _adb_version_wizard(settings, app_dir, adb, devs):
    """📊 버전 확인 + 원하는 것만 골라 배포.

    [규칙] AGENTS.md §다중선택 — 목록을 보고 스페이스로 고른 뒤 Enter(확정)로
           한 번에 일괄 처리한다(선택 → 즉시 설치를 반복하지 않는다).
    """
    targets = _adb_targets(settings, app_dir)
    if not targets:
        print(f"\r\n ⚠️ {C.YELLOW}등록된 APK 가 없습니다.{C.RESET}")
        time.sleep(2)
        return

    print(f"\r\n {C.BOLD}{C.SKY}📊 버전 확인 {C.GRAY}(설치본 ↔ 내 PC){C.RESET}")
    print(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
    if not adb:
        print(f" ❌ {C.RED}adb 미발견 — 버전 확인 불가{C.RESET}")
        time.sleep(2)
        return
    # [규칙] 폰 2대를 모두 확인해야 하는데 1대만 잡히던 문제(2026-10-10)
    #   예전엔 '아무 기기도 없으면' 만 재연결 → 한 대가 붙어 있으면 나머지는 시도조차 안 한다.
    devs = _adb_autoconnect(adb)
    if not devs:
        print(f" ❌ {C.RED}연결된 기기가 없습니다 — '무선 ADB 최초 등록' / 'USB → 무선 고정' 을 확인하세요.{C.RESET}")
        time.sleep(2)
        return

    # ★ [버그 · 2026-10-10] '진행할 폰' 으로 한정해 둔 폰이 있는데도 **전체 기기**로
    #   비교하던 문제 → _adb_autoconnect() 가 연결된 전부를 돌려주기 때문에, 여기서
    #   반드시 _ADB_SEL_DEVS['devs'] 로 다시 한 번 좁혀야 한다.
    #   (설치 쪽 _adb_install_apk() 는 이미 이 필터를 하므로, 확인만 전체로 보이던 불일치)
    _want = _ADB_SEL_DEVS.get('devs')
    if _want:
        _picked = [d for d in devs if d in _want]
        if not _picked:
            _wn = ', '.join(_want)
            print(f" ❌ {C.RED}선택한 폰이 연결되어 있지 않습니다: {_wn}{C.RESET}")
            print(f"    {C.GRAY}폰을 켜고 '무선 ADB 최초 등록' 또는 'USB → 무선 고정' 으로 붙인 뒤 다시 시도하세요."
                  f"{C.RESET}")
            time.sleep(2)
            return
        if len(_picked) < len(devs):
            print(f" {C.GRAY}🎯 '진행할 폰' 선택에 따라 {len(_picked)}대만 비교합니다 "
                  f"(전체 {len(devs)}대 중).{C.RESET}")
        devs = _picked

    _miss = [ip for ip in _adb_ip_strings() if not any(ip in d for d in devs)]
    if _miss:
        print(f" ⚠️ {C.YELLOW}붙지 않은 등록 기기 {len(_miss)}대: {', '.join(_miss)}"
              f" {C.GRAY}(꺼져 있거나 IP 변경 — 이번 비교에서 빠짐){C.RESET}")

    # ★ [규칙] VR 헤드셋은 APK 설치 대상이 아니므로 버전 비교표에서도 뺀다.
    devs, _vr = _adb_split_vr(devs)
    if not devs:
        print(f" ❌ {C.RED}비교할 대상 기기(폰)가 없습니다 — VR 기기는 APK 설치 대상에서 제외됩니다.{C.RESET}")
        time.sleep(2)
        return

    rows = _adb_compare_versions(targets, adb, devs)
    multi_dev = len(devs) > 1

    icon = {'new': '🆕', 'update': '⬆️', 'same': '✅',
            'older': '⚠️', 'unknown': '❓'}
    color = {'new': C.SKY, 'update': C.GOLD, 'same': C.GREEN,
             'older': C.YELLOW, 'unknown': C.GRAY}

    # [규칙] 대상 기기는 시리얼 대신 기종명으로 보여준다.
    #        기기가 여러 대면 한 줄에 이어쓰면 줄이 뒤로 넘어가 안 읽혀서 **한 줄에 한 대씩** 세로로 출력한다.
    _dinfo = _adb_dev_info_map(adb, devs)
    _dnames = [_adb_device_label(_dinfo.get(d) or {}) or d for d in devs]
    print(f" {C.GRAY}대상 기기 {C.SKY}{len(_dnames)}대{C.RESET}")
    for _i, _nm in enumerate(_dnames, 1):
        print(f"   {C.SKY}{_i}){C.RESET} {_nm}")
    print()
    opts, keys = [], []
    n_update = n_new = n_same = 0
    # [99 감사 P0 · 2026-10-10] 요약은 **APK 건수** 가 아니라 **기기 건수**(APK × 기기)로 센다.
    #   예전엔 APK 1건을 세면 Redmi 1대가 미설치여도 "미설치 0" 이 나오는 거짓말이 있었다.
    c_same = c_update = c_missing = 0
    for r in rows:
        if r['status'] == 'update':
            n_update += 1
        elif r['status'] == 'new':
            n_new += 1
        elif r['status'] == 'same':
            n_same += 1
        c_missing += r.get('n_missing', 0)
        for _d, _v in (r.get('per_dev') or {}).items():
            if not _v:
                continue
            if r.get('code') is not None and _v.get('code') is not None \
                    and r['code'] > _v['code']:
                c_update += 1
            else:
                c_same += 1
        loc = f"v{r['name']}" if r.get('name') else (
            f"v{r['code']}" if r.get('code') is not None else '판독불가')
        devs_txt = []
        for d in devs:
            v = r['per_dev'].get(d)
            devs_txt.append(f"설치됨 {_adb_fmt_ver(v)}" if v else "미설치")
        dev_disp = " / ".join(devs_txt) if multi_dev else (devs_txt[0] if devs_txt else '-')
        st = r['status']
        opts.append(f"{icon.get(st, '·')} {r['basename']} "
                    f"{C.GRAY}[PC {loc} → 폰 {dev_disp}]{C.RESET} "
                    f"{color.get(st, C.RESET)}{r['label']}{C.RESET}")
        keys.append(r['apk'])

    # [99 감사 P0] 기기별 비교표를 **항상** 먼저 출력한다.
    #   예전엔 opts(기기별 '미설치' 포함)가 오직 _interactive_menu 안에서만 렌더링되어,
    #   '모두 최신' 조기 종료 시에는 사용자가 기기별 내역을 아예 볼 수 없었다(dead 표시).
    print(f" {C.BOLD}📱 기기별 버전{C.RESET}")
    for r in rows:
        st = r['status']
        loc = f"v{r['name']}" if r.get('name') else (
            f"v{r['code']}" if r.get('code') is not None else '판독불가')
        print(f"  {icon.get(st, '·')} {r['basename']} {C.GRAY}(PC {loc}){C.RESET}")
        for i, d in enumerate(devs):
            v = r['per_dev'].get(d)
            nm = _dnames[i] if i < len(_dnames) else d
            if v:
                okmark = '✅' if (r.get('code') is not None and v.get('code') == r['code']) else '⬆️'
                print(f"      {okmark} {nm} : {_adb_fmt_ver(v)}")
            else:
                print(f"      {C.SKY}🆕{C.RESET} {C.GRAY}{nm} :{C.RESET} "
                      f"{C.SKY}미설치 → 설치 필요{C.RESET}")
        print()

    print(f" {C.GREEN}기 기준{C.RESET} · 최신 {c_same} · {C.GOLD}업데이트 {c_update}{C.RESET} · "
          f"{C.SKY}미설치 {c_missing}{C.RESET}")
    print(f" {C.GRAY}APK 기준{C.RESET} · 최신 {n_same} · 업데이트 {n_update} · 미설치 {n_new}\n")

    # 기본 체크 = 업데이트 필요한 것 + 미설치 것만 (최신은 굳이 다시 설치 X)
    presel = {i for i, r in enumerate(rows) if r['status'] in ('update', 'new')}
    if not presel:
        print(f" {C.GREEN}✨ 모두 최신입니다. 설치할 것이 없어요.{C.RESET}")
        try:
            input(f"\n {C.GRAY}Enter 키를 누르면 돌아가요...{C.RESET}")
        except (KeyboardInterrupt, EOFError):
            pass
        return

    # [규칙] 2026-10-10 — 이 메뉴에 **취소 항목이 없었다**.
    #   ESC 로는 빠질 수 있지만(→ -1), 눈앞에 '취소'가 없으므로
    #   "여기서 못 나가겠다" 는 인상을 준다(사용자 지적).
    #   → 항목/구분선을 추가하고 keys 를 1:1 로 맞춰 인덱스를 지킨다.
    _n_apk = len(keys)                     # 취소 추가 **전** APK 개수
    opts.append("──────────────────────────────────────────────────────────")
    opts.append("🚪 취소하고 돌아가기")
    keys.append(None)

    sel, _, *_ = _adb_menu_esc(_interactive_menu,
        "배포할 항목을 고르세요 (기본 = 업데이트/미설치 항목만 체크됨)",
        opts, allow_multi=True, initial_indices=presel)

    # [규칙] AGENTS.md §다중선택 반환값 — list / int / -1 모두 방어
    if isinstance(sel, int) and 0 <= sel < len(keys) and keys[sel] is None:
        picked = []                        # '취소' 항목을 고른 경우
    elif isinstance(sel, list):
        # 다중선택에서 '취소'가 함께 체크되어도 설치하면 안 된다 → APK 행만 담는다.
        if any(keys[i] is None for i in sel if 0 <= i < len(keys)):
            picked = []
        else:
            picked = [keys[i] for i in sel if 0 <= i < _n_apk and keys[i]]
    elif isinstance(sel, int) and 0 <= sel < len(keys):
        picked = [keys[sel]]
    else:
        picked = []

    if not picked:
        print(f"\r\n ↩️ {C.YELLOW}선택 없음 — 설치하지 않습니다.{C.RESET}")
        try:
            input(f"\n {C.GRAY}Enter 키를 누르면 돌아가요...{C.RESET}")
        except (KeyboardInterrupt, EOFError):
            pass
        return

    print(f"\r\n {C.BOLD}{C.CYAN}선택한 {len(picked)}개를 설치합니다{C.RESET}")
    for p in picked:
        print(f"   📦 {os.path.basename(p)}")
    results = []
    for p in picked:
        print(f"\n 📦 {os.path.basename(p)}")
        results.append((os.path.basename(p), _adb_install_apk(p)))
    succ = sum(1 for _, o in results if o)
    res_color = C.GREEN if succ == len(results) else C.YELLOW
    print(f"\n ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
    print(f" {res_color}결과: {succ}/{len(results)} 성공{C.RESET}")
    for label, o in results:
        print(f"   {'✅' if o else '❌'} {label}")
    if succ == len(results):
        print(f"\r\n 🎉 {C.GREEN}배포 완료!{C.RESET}")
    try:
        input(f"\n {C.GRAY}Enter 키를 누르면 돌아가요...{C.RESET}")
    except (KeyboardInterrupt, EOFError):
        pass


def _adb_usb_wizard():
    """🔌 USB → tcpip 5555 고정 마법사.

    [사용 흐름] 폰에 USB 를 꽂고 이 메뉴를 한 번 실행하면,
    그 뒤 USB 를 뽑아도 (같은 IP 로) 무선으로 붙는다.
    """
    adb = _adb_exe_path()
    if not adb:
        print(f"\r\n ❌ {C.RED}adb 미발견{C.RESET}")
        time.sleep(2)
        return
    usb = _adb_usb_devices(adb)
    if not usb:
        print(f"\r\n ❌ {C.RED}USB 로 꽂힌 폰이 없습니다.{C.RESET}")
        print(f"    폰 → '개발자 옵션 → USB 디버깅' 켜고 케이블을 꽂으세요.")
        try:
            input(f"\n {C.GRAY}Enter 키를 누르면 돌아가요...{C.RESET}")
        except (KeyboardInterrupt, EOFError):
            pass
        return

    print(f"\r\n {C.BOLD}{C.SKY}🔌 USB → 무선 고정 (tcpip){C.RESET}")
    print(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
    if len(usb) > 1:
        print(f" ⚠️ 폰이 {len(usb)}대 연결돼 있습니다. 하나만 꽂고 다시 시도하세요.")
        for u in usb:
            print(f"    · {u}")
        try:
            input(f"\n {C.GRAY}Enter 키를 누르면 돌아가요...{C.RESET}")
        except (KeyboardInterrupt, EOFError):
            pass
        return

    port = 5555
    print(f" {C.GRAY}폰에 꽂힌 USB 기기: {usb[0]}{C.RESET}")
    raw = prompt_input(f" 포트 입력 {C.GRAY}(기본 {port}, 빈 엔터 = 그대로):{C.RESET}").strip()
    if raw:
        if raw.isdigit() and 1024 < int(raw) < 65536:
            port = int(raw)
        else:
            print(f" ⚠️ {C.YELLOW}잘못된 포트 — 기본값 {port} 을 씁니다.{C.RESET}")

    res = _adb_usb_to_tcpip(port=port, dev=usb[0])
    if res.get('ok'):
        print(f"\r\n 🎉 {C.GREEN}{res['msg']}{C.RESET}")
        print(f"    {C.GRAY}이제 USB 를 뽑아도 됩니다. "
              f"(폰을 한 번도 안 켜본 날엔 다시 꽂아야 합니다){C.RESET}")
    else:
        print(f"\r\n ❌ {C.RED}{res['msg']}{C.RESET}")
        print(f"    💡 {C.GRAY}폰에서 '개발자 옵션 → USB 디버깅' 이 켜져 있는지 확인하세요.{C.RESET}")
    try:
        input(f"\n {C.GRAY}Enter 키를 누르면 돌아가요...{C.RESET}")
    except (KeyboardInterrupt, EOFError):
        pass


# ══ 📺 미러링 마법사 (2026-10-10 · 냥폰 메뉴 흡수 통합) ════════════════════
# [규칙] 사용자 지시 — 냥폰 매니저의 미러링 메뉴가 ADB 배포 마법사와 반씩 중복이었다.
#   → 여기 한 곳에 모으고, '기기 지정(다중선택)·예외폰' 기능을 추가했다.
#   → 실제 실행은 phone_common 엔진(phone_smart_connect / phone_launch_mirror)을 쓴다.
#   [공개 배포 안전] phone_common 이 없는 공개 배포본에서는 메뉴가 자연히 비어 동작한다.


def _adb_mirror_pause(msg=""):
    """미러링 액션 후 'Enter 대기' — 예외는 삼킨다(마법사가 죽으면 안 된다)."""
    try:
        input(f"\n {C.GRAY}{msg or 'Enter 키를 누르면 돌아가요...'}{C.RESET}")
    except (KeyboardInterrupt, EOFError):
        pass


def _adb_mirror_pick_wizard():
    """🎯 미러링할 기기 지정 — Space 다중선택 + 예외폰 지정 + 저장.

    [규칙] 2026-10-10 사용자 지시 —
      "무선 미러링 진행하고자 하는 기기를 선택하고, 저장할 수 있게"
      "폰 멀티선택(space) -> 미러링 가능하게, 예외폰 지정 가능하게"
    [설계] 체크를 **끊은** 폰이 '예외폰(exclude)' 으로 저장된다.
      · 아무도 껐지 않으면 전체가 미러링 대상(= 예전 동작 그대로)
      · 기기 등록 파일과 **분리** 저장 → '등록 기기 삭제'와 절대 간섭하지 않는다.
    """
    if not _PHONE_COMMON_OK:
        print(f"\r\n ❌ {C.RED}미러링 엔진 없음 (공개 배포본){C.RESET}")
        time.sleep(2)
        return
    devs = _adb_load_ips()
    if not devs:
        print(f"\r\n ❌ {C.YELLOW}등록된 기기가 없습니다 — 먼저 '무선 ADB 최초 등록'을 하세요.{C.RESET}")
        _adb_mirror_pause()
        return

    excl = _phone_mirror_targets()
    opts, keys = [], []
    _cache = _adb_load_info() or {}
    _ip2info = {}
    for _inf in _cache.values():
        if isinstance(_inf, dict) and _inf.get('ip'):
            _ip2info.setdefault(_inf['ip'], _inf)

    for d in devs:
        _ip = d.get('ip')
        if not _ip:
            continue
        _inf = _ip2info.get(_ip) or _phone_info_by_ip(_ip) or {}
        _nm = _adb_device_label(_inf) or d.get('alias') or _ip
        _bg = _adb_device_badges(_inf)
        _ex = f" {C.GRAY}[{_bg}]{C.RESET}" if _bg else ""
        # [주의] 🎮 VR 표시는 _adb_device_badges() 가 맨 앞에 이미 붙여준다 → 중복 금지.
        # ★ 지금 미러링 대상인지(초기 체크)를 **눈에 보이게** 표시한다.
        _st = (f" {C.YELLOW}[예외폰]{C.RESET}" if _ip in excl
               else f" {C.GREEN}[미러링 대상]{C.RESET}")
        opts.append(f"📱 {_nm} {C.GRAY}[{_ip}]{C.RESET}{_ex}{_st}")
        keys.append(_ip)
    opts.append("──────────────────────────────────────────────────────────")
    opts.append("🚪 뒤로가기")
    keys.append(None)      # 구분선 자리
    keys.append(None)      # 뒤로가기 자리  → [규칙] opts↔keys 인덱스 1:1

    # [규칙] 현재 '미러링 대상'인 것만 처음부터 체크돼 있게 한다.
    initial = {i for i, ip in enumerate(keys) if ip and ip not in excl}
    _n_target = len(initial)
    _n_excl = len([k for k in keys if k]) - _n_target

    header = [
        f" {C.GOLD}🎯 미러링 대상 기기 지정{C.RESET}",
        " ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
        f"  • {C.GRAY}Space 로 토글 → 체크된 폰만 미러링합니다.{C.RESET}",
        f"  • {C.GRAY}체크를 끈 폰은 '예외폰'으로 저장(미러링 제외).{C.RESET}",
        f"  • 현재: {C.GREEN}미러링 {_n_target}대{C.RESET} / "
        f"{C.YELLOW}예외 {_n_excl}대{C.RESET}",
    ]
    sel, _, *_ = _adb_menu_esc(_interactive_menu, "미러링할 기기를 고르세요", opts,
                                   allow_multi=True, initial_indices=initial,
                                   dynamic_header_callback=lambda _=0: "\n".join(header))
    # [규칙] AGENTS.md §다중선택 반환값 — list / int / -1 을 모두 방어한다.
    if isinstance(sel, int):
        # 구분선·뒤로가기 버튼을 커서 위치에서 바로 누른 경우
        if 0 <= sel < len(opts) and opts[sel].strip().startswith("🚪"):
            return
        return
    if not isinstance(sel, list):
        return
    if not sel:
        print(f"\r\n ↩️ {C.YELLOW}취소 — 기존 설정 그대로입니다.{C.RESET}")
        _adb_mirror_pause()
        return

    picked = {keys[i] for i in sel if 0 <= i < len(keys) and keys[i]}
    new_excl = [ip for ip in keys if ip and ip not in picked]
    if _phone_save_mirror_exclude(new_excl):
        print(f"\r\n ✅ {C.GREEN}저장 완료!{C.RESET}")
        print(f"     • 미러링 대상 : {C.GREEN}{len(picked)}대{C.RESET}")
        print(f"     • 예외폰     : {C.YELLOW}{len(new_excl)}대{C.RESET}"
              + (f"  ({', '.join(new_excl)})" if new_excl else ""))
        if len(picked) == 1:
            only = next(iter(picked))
            _inf = _ip2info.get(only) or {}
            print(f"     • 1대만 지정됨: {_adb_device_label(_inf) or only}")
    else:
        print(f"\r\n ❌ {C.RED}저장 실패{C.RESET}")
    _adb_mirror_pause()


# [TAG: #@_adb_apk_pick_wizard]
def _adb_apk_pick_wizard():
    """📦 APK 설치할 기기 지정 — Space 다중선택 + 예외폰 지정 + **저장**.

    [규칙] 2026-10-10 사용자 지시 — 미러링 기기 지정(🎯)과 **완전히 같은 방식**으로
       "APK 설치할 기기 지정" 을 만들되, 그 결과가 **저장**되어 배포 때 자동 반영되게 한다.

    [기존 vs 신규]
      · 기존 '📱 진행할 폰 선택' = **이번 세션에서만** 유효(앱을 끄면 사라짐)
      · 이 메뉴            = **저장**됨(영구). 모든 설치 경로가 지킨다.
      → 둘 다 있으면 '저장 제외' → '세션 선택' 순으로 적용된다(_adb_install_apk).

    [설계] 미러링과 동일하게 **'제외(exclude)'** 방식으로 저장한다.
      · 아무도 껐지 않으면 전폰 대상(= 기존 동작 그대로, 위험 없음)
      · 기기 등록 파일과 별도 저장 → '등록 기기 삭제'와 절대 간섭하지 않는다.
    """
    if not _PHONE_COMMON_OK:
        print(f"\r\n ❌ {C.RED}폰 엔진 없음 (공개 배포본){C.RESET}")
        time.sleep(2)
        return
    devs = _adb_load_ips()
    if not devs:
        print(f"\r\n ❌ {C.YELLOW}등록된 기기가 없습니다 — 먼저 '무선 ADB 최초 등록' 을 하세요.{C.RESET}")
        _adb_mirror_pause()
        return

    excl = _phone_apk_exclude()
    cache = _adb_load_info() or {}
    ip2info = {}
    for inf in cache.values():
        if isinstance(inf, dict) and inf.get("ip"):
            ip2info.setdefault(inf["ip"], inf)

    opts, keys = [], []
    for d in devs:
        ip = d.get("ip")
        if not ip:
            continue
        inf = ip2info.get(ip) or _phone_info_by_ip(ip) or {}
        nm = _adb_device_label(inf) or d.get("alias") or ip
        bg = _adb_device_badges(inf)
        ex = f" {C.GRAY}[{bg}]{C.RESET}" if bg else ""
        # [주의] 🎮 VR 표시는 _adb_device_badges() 가 맨 앞에 이미 붙여준다 → 중복 금지.
        #   VR 헤드셋은 원래부터 APK 설치 대상이 아니므로(아래 필터) 여기서 알린다.
        vr = ""
        st = (f" {C.YELLOW}[예외폰]{C.RESET}" if ip in excl
              else f" {C.GREEN}[설치 대상]{C.RESET}")
        opts.append(f"📦 {nm} {C.GRAY}[{ip}]{C.RESET}{ex}{vr}{st}")
        keys.append(ip)
    opts.append("──────────────────────────────────────────────────────────")
    opts.append("🚪 뒤로가기")
    keys.append(None)      # 구분선 자리
    keys.append(None)      # 뒤로가기 자리 → [규칙] opts↔keys 인덱스 1:1

    # [규칙] 현재 '설치 대상'인 것만 처음부터 체크돼 있게 한다.
    initial = {i for i, ip in enumerate(keys) if ip and ip not in excl}
    n_t = len(initial)
    n_e = len([k for k in keys if k]) - n_t

    header = [
        f" {C.GOLD}📦 APK 설치할 기기 지정{C.RESET}",
        " ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
        f"  • {C.GRAY}Space 로 토글 → 체크된 폰에만 APK 가 설치됩니다.{C.RESET}",
        f"  • {C.GRAY}체크를 끈 폰은 '예외폰'으로 저장(설치 제외).{C.RESET}",
        f"  • {C.YELLOW}저장되는 값이라{'':s}{C.RESET}{C.YELLOW} 앱을 껐다 켜도 그대로입니다.{C.RESET}",
        f"  • 현재: {C.GREEN}설치 대상 {n_t}대{C.RESET} / "
        f"{C.YELLOW}예외 {n_e}대{C.RESET}",
    ]
    sel, _, *_ = _adb_menu_esc(_interactive_menu, "APK 설치할 기기를 고르세요", opts,
                                   allow_multi=True, initial_indices=initial,
                                   dynamic_header_callback=lambda _=0: "\n".join(header))
    # [규칙] AGENTS.md §다중선택 반환값 — list / int / -1 을 모두 방어한다.
    if isinstance(sel, int):
        return
    if not isinstance(sel, list):
        return
    if not sel:
        print(f"\r\n ↩️ {C.YELLOW}취소 — 기존 설정 그대로입니다.{C.RESET}")
        _adb_mirror_pause()
        return

    picked = {keys[i] for i in sel if 0 <= i < len(keys) and keys[i]}
    new_excl = [ip for ip in keys if ip and ip not in picked]
    if _phone_save_apk_exclude(new_excl):
        print(f"\r\n ✅ {C.GREEN}저장 완료!{C.RESET}")
        print(f"     • 설치 대상 : {C.GREEN}{len(picked)}대{C.RESET}")
        print(f"     • 예외폰     : {C.YELLOW}{len(new_excl)}대{C.RESET}"
              + (f"  ({', '.join(new_excl)})" if new_excl else ""))
        # 세션 선택과 충돌하지 않게 함께 초기화한다.
        #   (두 설정이 겹치면 "설치 대상인데 왜 안 들어가?" 혼란만 생긴다)
        if _ADB_SEL_DEVS.get('devs'):
            _ADB_SEL_DEVS['devs'] = None
            print(f"     • {C.GRAY}세션 한정 '진행할 폰 선택' 도 초기화했어요.{C.RESET}")
    else:
        print(f"\r\n ❌ {C.RED}저장 실패{C.RESET}")
    _adb_mirror_pause()


def _adb_mirror_all(turn_off_screen=False):
    """📺 지정된 폰 전체 동시 미러링.

    [99 감사 P1 · 2026-10-10] 루프를 phone_common.phone_mirror_all 로 내렸다.
      예전엔 이 파일/korea/adb_deployer/nyangphone 에 4벌로 복제돼 있어
      한쪽만 고치면 나머지가 어긋났다 → 이제 **SSOT 는 phone_common 한 곳**.
    """
    if not _PHONE_COMMON_OK:
        print(f"\r\n ❌ {C.RED}미러링 엔진 없음 (공개 배포본){C.RESET}")
        time.sleep(2)
        return
    if not _phone_scrcpy_exe():
        print(f"\r\n ❌ {C.RED}scrcpy 엔진이 없습니다.{C.RESET}")
        print(f"     💡 {C.GRAY}'🐱 냥폰 매니저' 를 1회 실행하면 자동으로 내려받습니다.{C.RESET}")
        _adb_mirror_pause()
        return

    excl = _phone_mirror_targets()
    n_target = len([d.get('ip') for d in _adb_load_ips()
                    if d.get('ip') and d.get('ip') not in excl])
    if not n_target:
        print(f"\r\n ❌ {C.YELLOW}미러링할 기기가 없습니다.{C.RESET}")
        print(f"     💡 {C.GRAY}'🎯 미러링할 기기 지정' 에서 최소 1대를 체크하세요.{C.RESET}")
        _adb_mirror_pause()
        return

    print(f"\r\n {C.BOLD}{C.SKY}📺 무선 미러링 동시 실행 (총 {n_target}대){C.RESET}")
    print(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
    if excl:
        print(f" 🚫 예외폰 {len(excl)}대 제외: {', '.join(sorted(excl))}")
    if turn_off_screen:
        print(f" 🔋 [절전 모드] 폰 본체 화면 끄기 (발열/배터리 절약)")
    print(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")

    def _printer(kind, p):
        """phone_common 이 보낸 이벤트를 이 화면 모양으로 그린다 (표시만 담당).

        [99 감사 P1] 루프 자체는 phone_common.phone_mirror_all(SSOT) 이 담당한다.
        여기선 **표시만** 한다 → 엔진이 4벌로 복제되던 문제를 없앤다.
        """
        if kind == 'head':
            print(f"\r\n 📡 [{p['i']}/{p['n']}] {p['name']} ({p['ip']}:{p['port']}) 연결 시도 중...")
        elif kind == 'step':
            print(f"     {C.GRAY}{p['msg']}{C.RESET}")
        elif kind == 'ok':
            print(f"     ✅ 연결 성공! 미러링 창 실행 ({p['target']})")
        elif kind == 'fail':
            print(f"     ❌ {C.RED}{p['reason']}{C.RESET}")

    res = _phone_mirror_all(turn_off_screen=turn_off_screen, profile='multi',
                            on_progress=_printer)
    failed = res.get('failed') or []
    print(f"\r\n ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
    col = C.GREEN if not failed else C.YELLOW
    print(f" 🏁 {col}완료: {res.get('total', 0)}대 중 {res.get('success', 0)}대 미러링 실행{C.RESET}")
    if failed:
        print(f" 📋 실패 기기 & 원인:")
        for f in failed:
            print(f"    • {f.get('name') or f.get('ip')}: {f.get('reason')}")
        print(f" 💡 {C.GRAY}'🔌 USB → 무선 고정(tcpip 5555)' 을 다시 실행하면 해결됩니다.{C.RESET}")
    _adb_mirror_pause()


def _adb_mirror_single():
    """📱 특정 폰 1대만 고화질(오디오 포함) 미러링."""
    if not _PHONE_COMMON_OK:
        print(f"\r\n ❌ {C.RED}미러링 엔진 없음 (공개 배포본){C.RESET}")
        time.sleep(2)
        return
    devs = _adb_load_ips()
    if not devs:
        print(f"\r\n ❌ {C.YELLOW}등록된 기기가 없습니다.{C.RESET}")
        _adb_mirror_pause()
        return

    opts, keys = [], []
    for d in devs:
        _ip = d.get('ip')
        if not _ip:
            continue
        _inf = _phone_info_by_ip(_ip) or {}
        _nm = _adb_device_label(_inf) or d.get('alias') or _ip
        _bg = _adb_device_badges(_inf)
        _ex = f" {C.GRAY}[{_bg}]{C.RESET}" if _bg else ""
        opts.append(f"📱 {_nm} {C.GRAY}[{_ip}:{d.get('port', 5555)}]{C.RESET}{_ex}")
        keys.append(d)
    opts.append("──────────────────────────────────────────────────────────")
    opts.append("🚪 취소")
    keys.append(None)
    keys.append(None)      # [규칙] opts↔keys 1:1 — 구분선 자리에도 슬롯을 둔다

    sel, _, *_ = _adb_menu_esc(_interactive_menu, "고화질 미러링할 폰 선택", opts)
    # [규칙] list 로 오면(다중선택 잔재) 첫 항목을 쓴다 — int 아니면 안전하게 나간다.
    if isinstance(sel, list):
        sel = sel[0] if sel else -1
    if not isinstance(sel, int) or not (0 <= sel < len(keys)) or not keys[sel]:
        return

    d = keys[sel]
    ip, port = d.get('ip'), d.get('port', 5555)
    print(f"\r\n 📡 연결 시도 중... ({ip}:{port})")

    def _step(m):
        print(f"     {C.GRAY}{m}{C.RESET}")

    r = _phone_mirror_one(ip, port, alias=d.get('alias') or '', on_step=_step)
    if r.get('ok'):
        print(f"     ✅ 연결 성공! 고화질 미러링 창을 엽니다 ({r['target']})")
        print(f"     📺 오디오 포함 고화질 모드 (비트레이트 8M)")
    else:
        print(f"     ❌ {C.RED}{r.get('reason')}{C.RESET}")
    _adb_mirror_pause()


# [TAG: #@_adb_app_launcher_wizard]
def _adb_app_launcher_wizard(settings, adb, devs, mode='all'):
    """🚀 안드로이드 원격 앱 실행 & 등록 관리 런처 마법사 (2026-10-10 신규).

    [기능]
    - 등록된 앱 번호로 원격 즉시 호출 (실행 / 강제 종료 / 재시작 / 상세 정보)
    - 새 앱 등록: 폰에 설치된 앱(3rd-party) 자동 검색 선택 등록 + 직접 패키지명 입력
    - 등록된 앱 삭제 및 관리
    - settings.json ('adb_quick_apps') 로컬 영구 저장 (소스 코드 하드코딩 완전 배제)
    """
    if not devs or not adb:
        return

    _devinfo_local = _adb_dev_info_map(adb, devs) if '_adb_dev_info_map' in globals() else {}

    def _dev_lbl(d):
        if '_adb_device_label' in globals():
            lbl = _adb_device_label(_devinfo_local.get(d) or {})
            if lbl:
                return lbl
        return d

    cflags = subprocess.CREATE_NO_WINDOW if os.name == 'nt' else 0

    while True:
        # settings.json 에서 불러오기 (하드코딩 프리셋 없음 - 사용자가 직접 등록)
        quick_apps = settings.data.get('adb_quick_apps')
        if not isinstance(quick_apps, list):
            quick_apps = []
            settings.data['adb_quick_apps'] = quick_apps

        opts = []
        act = {}

        # ── 📱 [1] 등록된 앱 목록 ──
        if quick_apps:
            for idx, item in enumerate(quick_apps):
                app_name = item.get('name', '이름 없음')
                pkg = item.get('pkg', '')
                i_idx = len(opts)
                opts.append(f"📱 [{idx+1}] {C.BOLD}{C.CYAN}{app_name}{C.RESET} {C.GRAY}({pkg}){C.RESET}")
                act[i_idx] = ("app_action", idx, item)
        else:
            opts.append(f"  {C.GRAY}(등록된 앱이 없습니다 — 아래 '새 앱 등록'으로 추가하세요){C.RESET}")
            act[len(opts) - 1] = ("none", None, None)

        opts.append("──────────────────────────────────────────────────────────")

        # ── ⚙️ [2] 앱 등록 및 관리 ──
        i_add_scan = len(opts)
        opts.append(f"🔍 {ctext('폰에 설치된 앱 검색해서 추가 (3rd-party 자동 스캔)', C.SKY)}")
        act[i_add_scan] = ("add_scan", None, None)

        i_add_manual = len(opts)
        opts.append("✍️  새 앱 직접 등록 (패키지명 & 앱 이름 직접 입력)")
        act[i_add_manual] = ("add_manual", None, None)

        if quick_apps:
            i_stop_all = len(opts)
            opts.append("🛑 등록된 앱 일괄 강제 종료 (전체 Force-Stop)")
            act[i_stop_all] = ("stop_all", None, None)

            i_del = len(opts)
            opts.append("🗑️  등록된 앱 삭제 (목록에서 제거)")
            act[i_del] = ("delete_app", None, None)

        opts.append("──────────────────────────────────────────────────────────")
        i_exit = len(opts)
        opts.append("🚪 뒤로가기")
        act[i_exit] = ("exit", None, None)

        def _header_cb(_=0):
            lines = []
            tgt_name = "전체 기기 일괄 제어" if mode == 'all' else "단일 폰 단독 제어"
            dev_labels = [_dev_lbl(d) for d in devs]
            dev_str = ', '.join(dev_labels)
            if len(dev_str) > 55:
                dev_str = dev_str[:54] + "…"

            lines.append(f" 💾 {ctext('안드로이드 원격 앱 실행 & 런처 허브', C.SKY)}")
            lines.append(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
            lines.append(f"  • {ctext('작업 모드', C.GREEN)}: {C.BOLD}{C.GOLD}{tgt_name}{C.RESET} ({len(devs)}대 대상)")
            lines.append(f"  • {ctext('제어 대상', C.SKY)}: {dev_str}")
            lines.append(f"  • {ctext('등록 앱수', C.GOLD)}: {C.GREEN}{len(quick_apps)}개{C.RESET} (로컬 settings.json 안전 보존)")
            lines.append(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
            lines.append(f"  💡 {C.GRAY}등록된 앱을 선택하면 [실행 / 강제 종료 / 재시작]을 원격 수행합니다.{C.RESET}")
            lines.append(f"  💡 {C.GRAY}폰에 깔린 앱을 검색하거나 패키지명을 직접 등록할 수 있어요.{C.RESET}")
            return "\n".join(lines)

        sel, _, *_ = _adb_menu_esc(_interactive_menu,
            "🚀 안드로이드 원격 앱 실행 & 런처 허브",
            opts,
            dynamic_header_callback=_header_cb
        )
        if sel < 0:
            break
        if sel not in act:
            continue     # [★ 방어 · 2026-10-11] 구분선 등 무효 인덱스 → 메뉴 유지
        if act[sel][0] == "exit":
            break

        kind, idx, item = act[sel]
        if kind == "none":
            continue

        # ── 📱 앱 선택 시 조작 메뉴 ──
        if kind == "app_action":
            app_name = item.get('name', '앱')
            pkg = item.get('pkg', '')
            sub_opts = [
                f"▶️  [{app_name}] 원격 즉시 실행 (Launch)",
                f"⏹️  [{app_name}] 원격 강제 종료 (Force-Stop)",
                f"🔄 [{app_name}] 원격 재시작 (종료 후 1초 뒤 재실행)",
                f"ℹ️  [{app_name}] 앱 상세 정보 조회 (dumpsys package)",
                f"🗑️  [{app_name}] 등록 목록에서 삭제",
                "──────────────────────────────────────────────────────────",
                "🚪 취소 (돌아가기)"
            ]
            sub_sel, _, *_ = _adb_menu_esc(_interactive_menu,
                f"📱 [{app_name}] 원격 작업 선택",
                sub_opts
            )
            if sub_sel == 0:  # 실행
                print(f"\r\n 🚀 {C.BOLD}{C.SKY}[{app_name}] 원격 실행 중...{C.RESET}")
                cmd_launch = f"monkey -p {pkg} -c android.intent.category.LAUNCHER 1"
                for d in devs:
                    lbl = _dev_lbl(d)
                    try:
                        r = subprocess.run([adb, '-s', d, 'shell', cmd_launch],
                                           capture_output=True, text=True, timeout=10,
                                           encoding='utf-8', errors='replace', creationflags=cflags)
                        if "Events injected: 1" in (r.stdout or '') or r.returncode == 0:
                            print(f"   ✅ [{lbl}] '{app_name}' 실행 신호 전송 완료")
                        else:
                            subprocess.run([adb, '-s', d, 'shell', 'monkey', '-p', pkg, '1'],
                                           capture_output=True, timeout=5, creationflags=cflags)
                            print(f"   ✅ [{lbl}] '{app_name}' 실행 요청 완료")
                    except Exception as e:
                        print(f"   ❌ [{lbl}] 실행 실패: {e}")
                time.sleep(1.2)

            elif sub_sel == 1:  # 강제 종료
                print(f"\r\n 🛑 {C.BOLD}{C.YELLOW}[{app_name}] 강제 종료 중...{C.RESET}")
                for d in devs:
                    lbl = _dev_lbl(d)
                    try:
                        subprocess.run([adb, '-s', d, 'shell', 'am', 'force-stop', pkg],
                                       capture_output=True, timeout=8, creationflags=cflags)
                        print(f"   ✅ [{lbl}] '{app_name}' 종료 완료")
                    except Exception as e:
                        print(f"   ❌ [{lbl}] 종료 실패: {e}")
                time.sleep(1.2)

            elif sub_sel == 2:  # 재시작
                print(f"\r\n 🔄 {C.BOLD}{C.SKY}[{app_name}] 재시작(종료 후 재실행) 중...{C.RESET}")
                for d in devs:
                    lbl = _dev_lbl(d)
                    try:
                        subprocess.run([adb, '-s', d, 'shell', 'am', 'force-stop', pkg],
                                       capture_output=True, timeout=8, creationflags=cflags)
                        time.sleep(0.8)
                        cmd_launch = f"monkey -p {pkg} -c android.intent.category.LAUNCHER 1"
                        subprocess.run([adb, '-s', d, 'shell', cmd_launch],
                                       capture_output=True, timeout=10, creationflags=cflags)
                        print(f"   ✅ [{lbl}] '{app_name}' 재시작 완료")
                    except Exception as e:
                        print(f"   ❌ [{lbl}] 재시작 실패: {e}")
                time.sleep(1.2)

            elif sub_sel == 3:  # 상세 정보
                print(f"\r\n ℹ️  {C.BOLD}{C.SKY}[{app_name}] 패키지 정보 조회 ({pkg}){C.RESET}")
                for d in devs:
                    lbl = _dev_lbl(d)
                    print(f"\n   📱 기기: {C.GOLD}{lbl}{C.RESET}")
                    try:
                        r = subprocess.run([adb, '-s', d, 'shell', f'dumpsys package {pkg}'],
                                           capture_output=True, text=True, timeout=10,
                                           encoding='utf-8', errors='replace', creationflags=cflags)
                        lines = (r.stdout or '').splitlines()
                        found = False
                        for line in lines:
                            l = line.strip()
                            if any(k in l for k in ['versionName', 'versionCode', 'firstInstallTime', 'lastUpdateTime', 'enabled=']):
                                print(f"      {C.GRAY}·{C.RESET} {l}")
                                found = True
                        if not found:
                            print(f"      {C.GRAY}(패키지가 설치되어 있지 않거나 정보를 읽을 수 없습니다){C.RESET}")
                    except Exception as e:
                        print(f"      오류: {e}")
                input(f"\n {C.GRAY}Enter 키를 누르면 돌아가요...{C.RESET}")

            elif sub_sel == 4:  # 삭제
                if 0 <= idx < len(quick_apps):
                    quick_apps.pop(idx)
                    settings.data['adb_quick_apps'] = quick_apps
                    try:
                        settings.save()
                    except Exception:
                        pass
                    print(f"\r\n ✅ [{app_name}] 등록 목록에서 삭제되었습니다.")
                    time.sleep(1.0)
            continue

        # ── 🔍 [add_scan] 폰에 설치된 앱 검색 & 등록 ──
        if kind == "add_scan":
            scan_dev = devs[0]
            print(f"\r\n 🔍 {C.SKY}[{_dev_lbl(scan_dev)}] 설치된 앱(3rd-party) 목록을 스캔하는 중...{C.RESET}")
            try:
                r = subprocess.run([adb, '-s', scan_dev, 'shell', 'pm', 'list', 'packages', '-3'],
                                   capture_output=True, text=True, timeout=12,
                                   encoding='utf-8', errors='replace', creationflags=cflags)
                pkgs = []
                for line in (r.stdout or '').splitlines():
                    p = line.strip()
                    if p.startswith('package:'):
                        pkgs.append(p[len('package:'):].strip())
                pkgs = sorted(list(set(pkgs)))
            except Exception as e:
                print(f" ❌ 스캔 오류: {e}")
                time.sleep(1.5)
                continue

            if not pkgs:
                print(f" ℹ️  설치된 3rd-party 앱이 없어서 전체 시스템/사용자 앱을 조회합니다...")
                try:
                    r = subprocess.run([adb, '-s', scan_dev, 'shell', 'pm', 'list', 'packages'],
                                       capture_output=True, text=True, timeout=12,
                                       encoding='utf-8', errors='replace', creationflags=cflags)
                    for line in (r.stdout or '').splitlines():
                        p = line.strip()
                        if p.startswith('package:'):
                            pkgs.append(p[len('package:'):].strip())
                    pkgs = sorted(list(set(pkgs)))
                except Exception:
                    pass

            if not pkgs:
                print(f" ❌ 앱 목록을 가져오지 못했습니다.")
                time.sleep(1.5)
                continue

            reg_pkgs = {x.get('pkg') for x in quick_apps}

            scan_opts = []
            scan_act = {}
            for p in pkgs:
                is_reg = p in reg_pkgs
                tag = f" {C.GRAY}[이미 등록됨]{C.RESET}" if is_reg else ""
                i_p = len(scan_opts)
                scan_opts.append(f"📦 {p}{tag}")
                scan_act[i_p] = p

            scan_opts.append("──────────────────────────────────────────────────────────")
            i_c = len(scan_opts)
            scan_opts.append("🚪 취소 (돌아가기)")
            scan_act[i_c] = None

            p_sel, _, *_ = _adb_menu_esc(_interactive_menu,
                f"🔍 등록할 앱 선택 (총 {len(pkgs)}개 검색됨)",
                scan_opts
            )
            if p_sel < 0 or p_sel not in scan_act or not scan_act[p_sel]:
                continue

            chosen_pkg = scan_act[p_sel]
            print(f"\r\n 📦 선택한 패키지: {C.BOLD}{C.CYAN}{chosen_pkg}{C.RESET}")
            def_name = chosen_pkg.split('.')[-1].capitalize()
            try:
                custom_name = input(f" ✍️  앱 표시 이름을 입력하세요 [기본: {def_name}] > ").strip()
                if not custom_name:
                    custom_name = def_name

                quick_apps.append({"name": custom_name, "pkg": chosen_pkg})
                settings.data['adb_quick_apps'] = quick_apps
                try:
                    settings.save()
                except Exception:
                    pass
                print(f"\r\n ✅ {C.GREEN}'{custom_name}' ({chosen_pkg}) 등록 완료!{C.RESET}")
                time.sleep(1.2)
            except (KeyboardInterrupt, EOFError):
                pass
            continue

        # ── ✍️ [add_manual] 새 앱 직접 입력 등록 ──
        if kind == "add_manual":
            try:
                print(f"\r\n ✍️  {C.BOLD}{C.SKY}새 앱 직접 등록{C.RESET}")
                app_name = input(f"   • 앱 표시 이름 (예: 내 앱) > ").strip()
                if not app_name:
                    continue
                pkg_name = input(f"   • 안드로이드 패키지명 (예: com.example.app) > ").strip()
                if not pkg_name:
                    continue

                quick_apps.append({"name": app_name, "pkg": pkg_name})
                settings.data['adb_quick_apps'] = quick_apps
                try:
                    settings.save()
                except Exception:
                    pass
                print(f"\r\n ✅ {C.GREEN}'{app_name}' ({pkg_name}) 등록 완료!{C.RESET}")
                time.sleep(1.2)
            except (KeyboardInterrupt, EOFError):
                pass
            continue

        # ── 🛑 [stop_all] 등록된 앱 일괄 강제 종료 ──
        if kind == "stop_all":
            pkgs = [x.get('pkg') for x in quick_apps if x.get('pkg')]
            if not pkgs:
                print(f"\r\n ℹ️  종료할 등록 앱이 없습니다.")
                time.sleep(1.2)
                continue
            print(f"\r\n 🛑 {C.BOLD}{C.YELLOW}등록된 {len(pkgs)}개 앱 일괄 강제 종료 중...{C.RESET}")
            for d in devs:
                lbl = _dev_lbl(d)
                for pkg in pkgs:
                    subprocess.run([adb, '-s', d, 'shell', 'am', 'force-stop', pkg],
                                   capture_output=True, timeout=5, creationflags=cflags)
                print(f"   ✅ [{lbl}] 등록 앱 일괄 종료 완료")
            time.sleep(1.2)
            continue

        # ── 🗑️ [delete_app] 등록된 앱 삭제 ──
        if kind == "delete_app":
            if not quick_apps:
                print(f"\r\n ℹ️  삭제할 등록 앱이 없습니다.")
                time.sleep(1.2)
                continue
            del_opts = []
            del_act = {}
            for idx, item in enumerate(quick_apps):
                i_idx = len(del_opts)
                del_opts.append(f"🗑️  [{idx+1}] {item.get('name')} ({item.get('pkg')})")
                del_act[i_idx] = idx
            del_opts.append("──────────────────────────────────────────────────────────")
            i_c = len(del_opts)
            del_opts.append("🚪 취소 (돌아가기)")
            del_act[i_c] = -1

            d_sel, _, *_ = _adb_menu_esc(_interactive_menu,
                "🗑️ 삭제할 앱 선택",
                del_opts
            )
            if d_sel >= 0 and d_sel in del_act and del_act[d_sel] >= 0:
                removed = quick_apps.pop(del_act[d_sel])
                settings.data['adb_quick_apps'] = quick_apps
                try:
                    settings.save()
                except Exception:
                    pass
                print(f"\r\n ✅ '{removed.get('name')}' 등록 해제 완료.")
                time.sleep(1.2)
            continue


# [TAG: #@_adb_control_center_wizard]
def _adb_control_center_wizard(settings, adb, devs, mode='all'):
    """📱 ⚡ ADB 스마트 원격 제어 & 리눅스 셸 센터 (2026-10-10 신규)."""
    if not devs or not adb:
        return

    app_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in globals() else os.getcwd()
    _devinfo_local = _adb_dev_info_map(adb, devs) if '_adb_dev_info_map' in globals() else {}

    def _dev_lbl(d):
        if '_adb_device_label' in globals():
            lbl = _adb_device_label(_devinfo_local.get(d) or {})
            if lbl: return lbl
        return d

    def _run_shell(cmd_args, desc=""):
        print(f"\r\n 🚀 {desc} 실행 중...")
        cflags = subprocess.CREATE_NO_WINDOW if os.name == 'nt' else 0
        for d in devs:
            lbl = _dev_lbl(d)
            cmd = [adb, '-s', d, 'shell'] + list(cmd_args)
            try:
                r = subprocess.run(cmd, capture_output=True, text=True, timeout=15,
                                   encoding='utf-8', errors='replace', creationflags=cflags)
                out = (r.stdout or '').strip()
                err = (r.stderr or '').strip()
                ok = (r.returncode == 0)
                mark = '✅' if ok else '❌'
                res_txt = f" : {out}" if (out and len(out) < 60) else ""
                print(f"   {mark} [{lbl}]{res_txt}")
                if err and not ok:
                    print(f"      ⚠️ {err[:80]}")
            except Exception as e:
                print(f"   ❌ [{lbl}] 오류: {e}")

    while True:
        opts = []
        act = {}

        # ── 🐚 [1] 리눅스 셸 & 원격 텍스트 ──
        i_sh = len(opts)
        opts.append("🐚 실시간 대화형 리눅스 셸(Shell) 터미널 접속 [독립 창 실행 🪟]")
        act[i_sh] = "shell_interactive"

        i_cmd = len(opts)
        opts.append("⌨️  ADB 단일 셸 명령어 직접 실행 (명령 입력 ➔ 결과 콘솔 출력)")
        act[i_cmd] = "cmd_exec"

        i_txt = len(opts)
        opts.append("✍️  폰에 텍스트/URL 원격 타이핑 (PC 키보드에서 폰으로 전송)")
        act[i_txt] = "text_type"

        i_pst = len(opts)
        opts.append("📋 PC 클립보드 텍스트 폰에 즉시 붙여넣기 (Paste)")
        act[i_pst] = "paste"

        opts.append("──────────────────────────────────────────────────────────")

        # ── 📸 [2] 화면 캡처 & 디스플레이 설정 ──
        i_cap = len(opts)
        opts.append("📸 폰 화면 스크린샷 캡처 (PC screenshots 폴더로 자동 저장 & 열기)")
        act[i_cap] = "screencap"

        i_rec = len(opts)
        opts.append("🎥 폰 화면 15초 동영상 녹화 (PC recordings 폴더로 자동 저장)")
        act[i_rec] = "screenrecord"

        i_on = len(opts)
        opts.append("🔋 화면 켜짐 유지 (Stay-Awake 상시 유지) ON")
        act[i_on] = "stay_on"

        i_off = len(opts)
        opts.append("💤 화면 켜짐 유지 해제 (기본 절전 모드로 복구) OFF")
        act[i_off] = "stay_off"

        i_rot = len(opts)
        opts.append("🔄 화면 자동 회전 토글 (가로/세로 자동 회전 ON/OFF)")
        act[i_rot] = "rotation"

        i_bri = len(opts)
        opts.append("💡 화면 밝기 조절 (최소 / 중간 / 최대 선택)")
        act[i_bri] = "brightness"

        i_noti = len(opts)
        opts.append("🔔 상단 알림창 & 빠른 설정창 원격 내리기")
        act[i_noti] = "notification"

        opts.append("──────────────────────────────────────────────────────────")

        # ── 🔘 [3] 원격 하드웨어 키 & 내비게이션 ──
        i_home = len(opts)
        opts.append("🏠 홈(Home) 버튼 누르기")
        act[i_home] = "key_home"

        i_back = len(opts)
        opts.append("◀️ 뒤로가기(Back) 버튼 누르기")
        act[i_back] = "key_back"

        i_apps = len(opts)
        opts.append("📱 최근 실행 앱 목록 호출")
        act[i_apps] = "key_apps"

        i_pwr = len(opts)
        opts.append("⚡ 전원 버튼 누르기 (화면 끄기/켜기 토글)")
        act[i_pwr] = "key_power"

        i_unlock = len(opts)
        opts.append("🔓 화면 잠금 해제 (화면 켜고 위로 스와이프)")
        act[i_unlock] = "unlock"

        opts.append("──────────────────────────────────────────────────────────")

        # ── 🔊 [4] 사운드 & 네트워크 제어 ──
        i_mute = len(opts)
        opts.append("🔇 미디어 볼륨 음소거 (0단계 Mute)")
        act[i_mute] = "vol_mute"

        i_vmax = len(opts)
        opts.append("🔊 미디어 볼륨 최대로 (15단계 Max)")
        act[i_vmax] = "vol_max"

        i_wifi = len(opts)
        opts.append("📡 Wi-Fi 켜기 / 끄기 토글")
        act[i_wifi] = "wifi"

        i_air = len(opts)
        opts.append("✈️ 비행기 모드 토글")
        act[i_air] = "airplane"

        opts.append("──────────────────────────────────────────────────────────")

        # ── 📦 [5] 앱 관리 & 전원 시스템 ──
        i_app_hub = len(opts)
        opts.append("🚀 등록된 앱 원격 실행 & 관리 런처 (번호로 실행 / 종료 / 새 앱 등록)")
        act[i_app_hub] = "app_launcher"

        i_stop = len(opts)
        opts.append("🛑 등록된 앱 일괄 강제 종료 (force-stop)")
        act[i_stop] = "stop_apps"

        i_bat = len(opts)
        opts.append("📊 배터리 상태 & 하드웨어 상세 정보 조회")
        act[i_bat] = "battery_info"

        i_reb = len(opts)
        opts.append("🔄 기기 원격 재부팅 (Reboot)")
        act[i_reb] = "reboot"

        opts.append("──────────────────────────────────────────────────────────")
        i_exit = len(opts)
        opts.append("🚪 뒤로가기")
        act[i_exit] = "exit"

        def _header_cb(_=0):
            lines = []
            tgt_name = "전체 기기 일괄 제어" if mode == 'all' else "단일 폰 단독 제어"
            dev_labels = [_dev_lbl(d) for d in devs]
            dev_str = ', '.join(dev_labels)
            if len(dev_str) > 55:
                dev_str = dev_str[:54] + "…"

            lines.append(f" 💾 {ctext('안드로이드 ADB 스마트 원격 제어 & 리눅스 셸 센터', C.SKY)}")
            lines.append(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
            lines.append(f"  • {ctext('작업 모드', C.GREEN)}: {C.BOLD}{C.GOLD}{tgt_name}{C.RESET} ({len(devs)}대 대상)")
            lines.append(f"  • {ctext('제어 대상', C.SKY)}: {dev_str}")
            lines.append(f"  • {ctext('리눅스 셸', C.GREEN)}: 개발자 모드 콘솔 터미널 지원 🪟")
            lines.append(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
            lines.append(f"  💡 {C.GRAY}[리눅스 셸] 독립 CMD 창을 열어 폰의 리눅스 셸에 실시간 접속합니다.{C.RESET}")
            lines.append(f"  💡 {C.GRAY}[스크린샷] 캡처하면 PC screenshots 폴더에 저장되고 탐색기가 자동 열려요!{C.RESET}")
            lines.append(f"  💡 {C.GRAY}[타이핑] PC 키보드로 긴 문장이나 주소를 쳐서 폰에 1초 만에 전송할 수 있어요.{C.RESET}")
            return "\n".join(lines)

        sel, _, *_ = _adb_menu_esc(_interactive_menu,
            "📱 ⚡ ADB 스마트 원격 제어 & 리눅스 셸 센터",
            opts,
            dynamic_header_callback=_header_cb
        )
        if sel < 0:
            break
        if sel not in act:
            continue     # [★ 방어 · 2026-10-11] 구분선 등 무효 인덱스 → 메뉴 유지
        if act[sel] == "exit":
            break

        action = act[sel]

        # [0] 🐚 실시간 대화형 리눅스 셸 터미널 접속 (새 창 실행)
        if action == "shell_interactive":
            print(f"\r\n 🐚 {C.BOLD}{C.SKY}리눅스 셸(Shell) 터미널을 독립 창으로 엽니다...{C.RESET}")
            for d in devs:
                lbl = _dev_lbl(d)
                title_str = f"Android Shell - {lbl}"
                try:
                    subprocess.Popen(f'start "{title_str}" cmd /k "{adb}" -s {d} shell', shell=True)
                    print(f"   ✅ [{lbl}] 셸 콘솔 창 실행 완료 🪟")
                except Exception as e:
                    print(f"   ❌ [{lbl}] 셸 실행 오류: {e}")
            time.sleep(1)
            continue

        # [1] ⌨️ ADB 단일 셸 명령어 직접 실행
        if action == "cmd_exec":
            try:
                cmd_in = input(f"\r\n ⌨️  {C.GOLD}실행할 ADB shell 명령어 입력 (취소: 빈 엔터){{C.RESET}} > ").strip()
                if cmd_in:
                    _run_shell(cmd_in.split(), desc=f"명령어 '{cmd_in}'")
                    input(f"\n {C.GRAY}Enter 키를 누르면 돌아가요...{C.RESET}")
            except (KeyboardInterrupt, EOFError):
                pass
            continue

        # [2] ✍️ 폰에 텍스트/URL 원격 타이핑
        if action == "text_type":
            try:
                txt_in = input(f"\r\n ✍️  {C.GOLD}폰에 전송할 텍스트/URL 입력 (취소: 빈 엔터){{C.RESET}} > ").strip()
                if txt_in:
                    esc_txt = txt_in.replace(' ', '%s').replace('&', '\\&').replace('"', '\\"').replace("'", "\\'")
                    _run_shell(['input', 'text', esc_txt], desc="텍스트 원격 타이핑")
                    input(f"\n {C.GRAY}Enter 키를 누르면 돌아가요...{C.RESET}")
            except (KeyboardInterrupt, EOFError):
                pass
            continue

        # [3] 📋 PC 클립보드 붙여넣기
        if action == "paste":
            _run_shell(['input', 'keyevent', '279'], desc="클립보드 붙여넣기 (KEYCODE_PASTE)")
            time.sleep(1)
            continue

        # [4] 📸 스크린샷 캡처
        if action == "screencap":
            out_dir = os.path.join(app_dir, "screenshots")
            os.makedirs(out_dir, exist_ok=True)
            ts = time.strftime('%Y%m%d_%H%M%S')
            cflags = subprocess.CREATE_NO_WINDOW if os.name == 'nt' else 0
            print(f"\r\n 📸 {C.BOLD}{C.SKY}화면 스크린샷 캡처 중...{C.RESET}")
            saved_paths = []
            for d in devs:
                lbl = _dev_lbl(d).replace(' ', '_').replace('(', '').replace(')', '')
                fn = f"screenshot_{lbl}_{ts}.png"
                local_path = os.path.join(out_dir, fn)
                try:
                    subprocess.run([adb, '-s', d, 'shell', 'screencap', '-p', '/sdcard/scrcap_tmp.png'],
                                   capture_output=True, timeout=15, creationflags=cflags)
                    r_pull = subprocess.run([adb, '-s', d, 'pull', '/sdcard/scrcap_tmp.png', local_path],
                                            capture_output=True, timeout=15, creationflags=cflags)
                    subprocess.run([adb, '-s', d, 'shell', 'rm', '/sdcard/scrcap_tmp.png'],
                                   capture_output=True, timeout=10, creationflags=cflags)
                    if r_pull.returncode == 0 and os.path.exists(local_path):
                        print(f"   ✅ [{_dev_lbl(d)}] 저장됨: {fn}")
                        saved_paths.append(local_path)
                    else:
                        print(f"   ❌ [{_dev_lbl(d)}] 캡처 실패")
                except Exception as e:
                    print(f"   ❌ [{_dev_lbl(d)}] 오류: {e}")
            if saved_paths and os.name == 'nt':
                try: os.startfile(out_dir)
                except Exception: pass
            input(f"\n {C.GRAY}Enter 키를 누르면 돌아가요...{C.RESET}")
            continue

        # [5] 🎥 폰 화면 15초 동영상 녹화
        if action == "screenrecord":
            rec_dir = os.path.join(app_dir, "recordings")
            os.makedirs(rec_dir, exist_ok=True)
            ts = time.strftime('%Y%m%d_%H%M%S')
            cflags = subprocess.CREATE_NO_WINDOW if os.name == 'nt' else 0
            print(f"\r\n 🎥 {C.BOLD}{C.SKY}폰 화면 15초 녹화 시작... (잠시만 기다려주세요){{C.RESET}}")
            for d in devs:
                lbl = _dev_lbl(d).replace(' ', '_').replace('(', '').replace(')', '')
                fn = f"record_{lbl}_{ts}.mp4"
                local_path = os.path.join(rec_dir, fn)
                try:
                    print(f"   ⏳ [{_dev_lbl(d)}] 녹화 중 (15초)...")
                    subprocess.run([adb, '-s', d, 'shell', 'screenrecord', '--time-limit', '15', '/sdcard/rec_tmp.mp4'],
                                   capture_output=True, timeout=25, creationflags=cflags)
                    r_pull = subprocess.run([adb, '-s', d, 'pull', '/sdcard/rec_tmp.mp4', local_path],
                                            capture_output=True, timeout=20, creationflags=cflags)
                    subprocess.run([adb, '-s', d, 'shell', 'rm', '/sdcard/rec_tmp.mp4'],
                                   capture_output=True, timeout=10, creationflags=cflags)
                    if r_pull.returncode == 0 and os.path.exists(local_path):
                        print(f"   ✅ [{_dev_lbl(d)}] 저장 완료: {fn}")
                    else:
                        print(f"   ❌ [{_dev_lbl(d)}] 녹화 저장 실패")
                except Exception as e:
                    print(f"   ❌ [{_dev_lbl(d)}] 오류: {e}")
            if os.name == 'nt':
                try: os.startfile(rec_dir)
                except Exception: pass
            input(f"\n {C.GRAY}Enter 키를 누르면 돌아가요...{C.RESET}")
            continue

        # [6] 🔋 화면 켜짐 유지 ON
        if action == "stay_on":
            _run_shell(['svc', 'power', 'stayon', 'true'], desc="화면 항상 켜짐 유지 ON (Stay-Awake)")
            time.sleep(1)
            continue

        # [7] 💤 화면 켜짐 유지 OFF
        if action == "stay_off":
            _run_shell(['svc', 'power', 'stayon', 'false'], desc="화면 켜짐 유지 OFF (기본 절전 복구)")
            time.sleep(1)
            continue

        # [8] 🔄 화면 자동 회전 토글
        if action == "rotation":
            _run_shell(['settings', 'put', 'system', 'accelerometer_rotation', '1'], desc="화면 자동 회전 ON")
            time.sleep(1)
            continue

        # [9] 💡 화면 밝기 조절
        if action == "brightness":
            sub_b = ["1. 최소 밝기 (어둡게)", "2. 중간 밝기 (표준)", "3. 최대 밝기 (선명하게)", "4. 뒤로"]
            b_sel, _, *_ = _adb_menu_esc(_interactive_menu, "원하는 화면 밝기를 선택하세요", sub_b)
            val_map = {0: '20', 1: '128', 2: '255'}
            if b_sel in val_map:
                _run_shell(['settings', 'put', 'system', 'screen_brightness', val_map[b_sel]],
                           desc=f"화면 밝기 조절 ({val_map[b_sel]})")
                time.sleep(1)
            continue

        # [10] 🔔 상단 알림창 내리기
        if action == "notification":
            _run_shell(['cmd', 'statusbar', 'expand-notifications'], desc="상단 알림창 내리기")
            time.sleep(1)
            continue

        # [11] 🏠 홈 버튼
        if action == "key_home":
            _run_shell(['input', 'keyevent', '3'], desc="홈(Home) 버튼")
            time.sleep(0.5)
            continue

        # [12] ◀️ 뒤로가기 버튼
        if action == "key_back":
            _run_shell(['input', 'keyevent', '4'], desc="뒤로가기(Back) 버튼")
            time.sleep(0.5)
            continue

        # [13] 📱 최근 앱 목록
        if action == "key_apps":
            _run_shell(['input', 'keyevent', '187'], desc="최근 실행 앱 목록")
            time.sleep(0.5)
            continue

        # [14] ⚡ 전원 버튼
        if action == "key_power":
            _run_shell(['input', 'keyevent', '26'], desc="전원 버튼 누름")
            time.sleep(0.5)
            continue

        # [15] 🔓 잠금화면 해제
        if action == "unlock":
            print(f"\r\n 🔓 {C.BOLD}{C.SKY}화면 잠금 해제 시도 중...{C.RESET}")
            cflags = subprocess.CREATE_NO_WINDOW if os.name == 'nt' else 0
            for d in devs:
                try:
                    subprocess.run([adb, '-s', d, 'shell', 'input', 'keyevent', '224'],
                                   capture_output=True, timeout=10, creationflags=cflags)
                    time.sleep(0.3)
                    subprocess.run([adb, '-s', d, 'shell', 'input', 'swipe', '500', '1600', '500', '400', '300'],
                                   capture_output=True, timeout=10, creationflags=cflags)
                    print(f"   ✅ [{_dev_lbl(d)}] 스와이프 전송 완료")
                except Exception as e:
                    print(f"   ❌ [{_dev_lbl(d)}] 오류: {e}")
            time.sleep(1)
            continue

        # [16] 🔇 미디어 볼륨 음소거
        if action == "vol_mute":
            _run_shell(['media', 'volume', '--set', '0'], desc="미디어 볼륨 0 (음소거)")
            time.sleep(1)
            continue

        # [17] 🔊 미디어 볼륨 최대
        if action == "vol_max":
            _run_shell(['media', 'volume', '--set', '15'], desc="미디어 볼륨 15 (최대)")
            time.sleep(1)
            continue

        # [18] 📡 Wi-Fi 켜기
        if action == "wifi":
            _run_shell(['svc', 'wifi', 'enable'], desc="Wi-Fi 켜기")
            time.sleep(1)
            continue

        # [19] ✈️ 비행기 모드 토글
        if action == "airplane":
            _run_shell(['cmd', 'connectivity', 'airplane-mode', 'toggle'], desc="비행기 모드 토글")
            time.sleep(1)
            continue

        # [20] 🚀 등록된 앱 원격 실행 & 관리 런처
        if action == "app_launcher":
            _adb_app_launcher_wizard(settings, adb, devs, mode=mode)
            continue

        # [20-1] 🛑 등록된 앱 일괄 강제 종료
        if action == "stop_apps":
            quick_apps = settings.data.get('adb_quick_apps') or []
            pkgs = [x.get('pkg') for x in quick_apps if x.get('pkg')]
            if not pkgs:
                print(f"\r\n ℹ️  {C.YELLOW}등록된 앱이 없습니다.{C.RESET} 앱 런처에서 먼저 앱을 등록해주세요.")
                time.sleep(1.5)
                continue
            print(f"\r\n 🛑 {C.BOLD}{C.YELLOW}등록된 {len(pkgs)}개 앱 일괄 강제 종료 중...{C.RESET}")
            cflags = subprocess.CREATE_NO_WINDOW if os.name == 'nt' else 0
            for d in devs:
                for p in pkgs:
                    subprocess.run([adb, '-s', d, 'shell', 'am', 'force-stop', p],
                                   capture_output=True, timeout=10, creationflags=cflags)
                print(f"   ✅ [{_dev_lbl(d)}] 등록 앱 프로세스 정리 완료")
            time.sleep(1.2)
            continue

        # [21] 📊 배터리 상태 & 하드웨어 정보
        if action == "battery_info":
            print(f"\r\n 📊 {C.BOLD}{C.SKY}기기 배터리 및 하드웨어 정보 조회{C.RESET}")
            cflags = subprocess.CREATE_NO_WINDOW if os.name == 'nt' else 0
            for d in devs:
                lbl = _dev_lbl(d)
                print(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
                print(f" 📱 {C.BOLD}{lbl}{C.RESET} ({d})")
                try:
                    r_bat = subprocess.run([adb, '-s', d, 'shell', 'dumpsys', 'battery'],
                                           capture_output=True, text=True, timeout=10,
                                           encoding='utf-8', errors='replace', creationflags=cflags)
                    if r_bat.returncode == 0:
                        for l in (r_bat.stdout or '').splitlines():
                            if any(k in l.lower() for k in ('level', 'scale', 'voltage', 'temperature', 'status', 'health')):
                                print(f"    {C.GRAY}·{C.RESET} {l.strip()}")
                except Exception as e:
                    print(f"    오류: {e}")
            print(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
            input(f"\n {C.GRAY}Enter 키를 누르면 돌아가요...{C.RESET}")
            continue

        # [22] 🔄 기기 원격 재부팅
        if action == "reboot":
            try:
                ans = input(f"\r\n ⚠️  {C.RED}정말 대상 기기를 재부팅하시겠습니까? (y/n){C.RESET} > ").strip().lower()
                if ans == 'y':
                    cflags = subprocess.CREATE_NO_WINDOW if os.name == 'nt' else 0
                    for d in devs:
                        subprocess.run([adb, '-s', d, 'reboot'],
                                       capture_output=True, timeout=10, creationflags=cflags)
                        print(f"   ✅ [{_dev_lbl(d)}] 재부팅 신호 전송 완료")
                    time.sleep(1.5)
            except (KeyboardInterrupt, EOFError):
                pass
            continue

def _adb_deploy_menu(settings):
    """📱 안드로이드 무선 ADB 배포 + 화면 미러링 마법사.

    [2026-10-10 통합] 냥폰 매니저의 미러링 메뉴를 이 메뉴에 **흡수**했다.
      (기존: ADB 배포 마법사 / 냥폰 매니저 두 곳이 반씩 중복 → 한 곳으로 통합)
    [규칙] 공개 배포 안전 — APK 목록을 하드코딩하지 않는다(런타임 스캔/settings).
    """
    app_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in globals() else os.getcwd()

    while True:
        adb = _adb_exe_path()
        devs = _adb_connected(adb) if adb else []
        known_ips = _adb_ip_strings()

        # ── [99 감사 P1] 기기 시리얼 → 사람이 읽는 이름 ──
        #   adb-XXXX._adb-tls-connect._tcp 같은 시리얼을 그대로 보여주면
        #   어떤 폰인지 알 수 없다(사용자 지적). 기종명을 붙여 함께 표기한다.
        _devinfo = _adb_dev_info_map(adb, devs)
        _devname = {}
        for _d in devs:
            _label = _adb_device_label(_devinfo.get(_d) or {})
            _devname[_d] = _label or _d

        # [규칙] 2026-10-10 사용자 지시 — '📡 상태 보기' 메뉴를 **제거**했다.
        #   헤더(상단 상태창)에 adb 상태·연결/등록 기기·진행 대상·설치/미러링 대상이
        #   이미 다 보인다 → 같은 내용을 또 열어보는 것이噪声이었다.
        #   [보존] 그 화면에만 있던 'APK 파일이 실제로 있는지(🟢/❌)' 표시는
        #        아래 APK 메뉴 항목에 흡수했다(아래 opts.append 참고).
        opts = []
        act = {}

        # ── 진행할 폰 타겟 정보 계산 ──
        sel_devs = _ADB_SEL_DEVS.get('devs')
        # ★ [규칙] VR 헤드셋은 '진행 대상(설치)' 표기에서 제외한다(목록에는 🎮 로 남김).
        _vr_set = {d for d in devs if _adb_is_vr(_devinfo.get(d) or {})}
        if sel_devs:
            sel_devs = [d for d in sel_devs if d not in _vr_set] or None
        tgt_txt = (', '.join(_devname.get(d, d) for d in sel_devs)
                   if sel_devs else "전체 기기")

        # ══ 📱 [1] 배포 대상 폰 설정 (어느 폰에 설치할까?) ══
        # [규칙] 사용자 지시(옵션 A) — 폰 지정 메뉴를 최상단 1섹션으로 배치.
        #   1) 영구 저장되는 기본 배포 대상 기기 지정 (Space 다중선택 · 예외폰 설정)
        #   2) 이번 작업만 특정 폰 1대 지정 (단일 폰 배포)
        _apk_ex = _phone_apk_exclude() if _PHONE_COMMON_OK else set()
        _apk_reg_ips = [d.get("ip") for d in _adb_load_ips() if d.get("ip")]
        _apk_n = len([i for i in _apk_reg_ips if i not in _apk_ex])
        _apk_tag = (f" {C.GRAY}[대상 {_apk_n}대 · 예외 {len(_apk_ex)}대]{C.RESET}"
                    if _PHONE_COMMON_OK else "")
        i_apk_pick = len(opts)
        opts.append(f"🎯 {C.GOLD}배포 대상 폰 지정{C.RESET} "
                    f"{C.GRAY}[Space 다중선택 · 예외폰 설정 · 영구 저장]{C.RESET}{_apk_tag}")
        act[i_apk_pick] = ("apk_pick", None)

        i_pickdev = len(opts)
        opts.append(f"📱 {C.CYAN}이번 작업만 특정 폰 1대 지정{C.RESET} "
                    f"{C.GRAY}[현재: {tgt_txt}]{C.RESET}")
        act[i_pickdev] = ("pick_dev", None)

        opts.append("──────────────────────────────────────────────────────────")

        # ══ 📦 [2] 설치할 APK 관리 & 배포 (무엇을 설치할까?) ══
        targets = _adb_targets(settings, app_dir)
        i_all = len(opts)
        all_label = f"{len(targets)}종 일괄 무음 배포" if targets else "일괄 무음 배포"
        opts.append(f"🚀 {C.BOLD}{C.CYAN}{all_label} (설치창 0회 원클릭!){C.RESET}")
        act[i_all] = ("install_all", None)

        i_ver = len(opts)
        chk_label = "📊 버전 비교 & 스마트 배포" if targets else "📊 버전 확인"
        opts.append(f"{chk_label} {C.GRAY}[내 PC vs 폰 설치본 자동 비교]{C.RESET}")
        act[i_ver] = ("version", None)

        i_mgmt = len(opts)
        opts.append(f"🔍 {ctext('APK 대상 관리 (새 APK 검색 · 등록 · 해제)', C.SKY)}")
        act[i_mgmt] = ("manage_apks", None)

        if targets:
            for apk in targets:
                nm = os.path.basename(apk)
                sub = os.path.relpath(apk, app_dir) if apk.startswith(app_dir) else apk
                _ex_ok = os.path.exists(apk)
                _mark = f"{C.GREEN}🟢{C.RESET}" if _ex_ok else f"{C.RED}❌{C.RESET}"
                _warn = "" if _ex_ok else f" {C.RED}[파일 없음]{C.RESET}"
                opts.append(f"  {_mark} {nm} {C.GRAY}[클릭 시 대상 폰들에 즉시 설치]{C.RESET}{_warn}")
                act[len(opts) - 1] = ("install", (apk, nm))
        else:
            opts.append(f"  {C.GRAY}(등록된 APK 없음 — 위 'APK 대상 관리' 에서 검색·등록 하세요){C.RESET}")

        opts.append("──────────────────────────────────────────────────────────")

        # ══ 📺 [3] 화면 미러링 & 원격 제어 (어느 폰 화면을 띄울까?) ══
        _excl_mirror = _phone_mirror_targets() if _PHONE_COMMON_OK else set()
        _m_cnt = len([d for d in devs if d not in _vr_set])
        _mir_tag = (f" {C.GRAY}[대상 {_m_cnt}대 · 예외 {len(_excl_mirror)}대]{C.RESET}"
                    if _PHONE_COMMON_OK else "")
        _engine = _phone_scrcpy_exe() if _PHONE_COMMON_OK else None

        i_mir_pick = len(opts)
        opts.append(f"🎯 {C.GOLD}미러링할 기기 지정{C.RESET} "
                    f"{C.GRAY}[Space 다중선택 · 예외폰 설정]{C.RESET}{_mir_tag}")
        act[i_mir_pick] = ("mirror_pick", None)

        _mir_st = "" if _engine else f" {C.YELLOW}[scrcpy 엔진 없음]{C.RESET}"
        i_mir_all = len(opts)
        opts.append(f"📺 선택된 폰 전체 동시 미러링 "
                    f"{C.GRAY}[다중 분할 화면 · 원격 조작]{C.RESET}{_mir_st}")
        act[i_mir_all] = ("mirror_all", False)

        i_mir_off = len(opts)
        opts.append(f"🔋 [절전 모드] 폰 화면 끄고 전체 미러링 "
                    f"{C.GRAY}[발열/배터리 절약 강추! 👍]{C.RESET}{_mir_st}")
        act[i_mir_off] = ("mirror_all", True)

        i_mir_one = len(opts)
        opts.append(f"📱 특정 폰 1대만 고화질 미러링 {C.GRAY}[오디오 포함]{C.RESET}{_mir_st}")
        act[i_mir_one] = ("mirror_one", None)

        i_cmd = len(opts)
        # [★ 메뉴 최적화 · 2026-10-11] 예전엔 아래 두 항목이 나란히 있었다 —
        #   'ADB 명령어 전송 & 스마트 제어실 [전체 대상 폰 동시]'
        #   'ADB 명령어 전송 & 스마트 제어실 [특정 폰 1대 선택]'
        #   라벨이 거의 같아서 "뭐가 다른지" 알 수 없었고 메뉴 줄만 2개 더 먹었다.
        #   → **한 항목으로 통합**하고, 안에서 '전체 / 1대'를 고르게 한다.
        _cmd_tag = (f"{len(sel_devs)}대 지정" if sel_devs else "전체 기기")
        opts.append(f"⚡ {C.BOLD}{C.GOLD}ADB 명령어 전송 & 스마트 제어실{C.RESET} "
                    f"{C.GRAY}[화면·소리·앱·전원·셸 · 대상 {_cmd_tag}]{C.RESET}")
        act[i_cmd] = ("cmd", None)

        opts.append("──────────────────────────────────────────────────────────")

        # ══ 📡 [4] 무선 ADB 기기 연결 & 관리 ══
        i_pair = len(opts)
        pair_tag = f" {C.GRAY}[등록됨]{C.RESET}" if known_ips else ""
        opts.append(f"📡 무선 ADB 최초 등록 (Wi-Fi pairing){C.RESET}{pair_tag}")
        act[i_pair] = ("pair", None)

        usb_list = _adb_usb_devices(adb) if adb else []
        usb_hint = (f" {C.GREEN}[USB 연결됨]{C.RESET}" if len(usb_list) == 1
                    else (f" {C.GRAY}[USB {len(usb_list)}대]{C.RESET}" if len(usb_list) > 1 else ""))
        i_usb = len(opts)
        opts.append(f"🔌 USB → 무선 고정 (tcpip 5555){C.RESET}{usb_hint}")
        act[i_usb] = ("usb_tcpip", None)

        i_list = len(opts)
        opts.append("🗑️ 등록 기기 정리 "
                    f"{C.GRAY}[개별 선택 삭제 / 전체 초기화]{C.RESET}")
        act[i_list] = ("reset", None)

        opts.append("──────────────────────────────────────────────────────────")

        # ── 🔄 기기 정보 새로고침 (사용자 요청) ──
        i_refresh = len(opts)
        opts.append(f"🔄 {ctext('기기 정보 새로고침', C.SKY)} "
                    f"{C.GRAY}[배터리 · 스토리지 · 연결 상태 최신화]{C.RESET}")
        act[i_refresh] = ("refresh_info", None)

        opts.append("──────────────────────────────────────────────────────────")
        i_exit = len(opts)
        opts.append("🚪 뒤로가기")
        act[i_exit] = ("exit", None)

        def _header_cb(_=0):
            _excl_m = _phone_mirror_targets() if _PHONE_COMMON_OK else set()
            _reg_ips = [d.get('ip') for d in _adb_load_ips() if d.get('ip')]
            _mir_n = len([i for i in _reg_ips if i not in _excl_m])
            _eng = _phone_scrcpy_exe() if _PHONE_COMMON_OK else None
            _apk_ex_h = _phone_apk_exclude() if _PHONE_COMMON_OK else set()
            _apk_n_h = len([i for i in _reg_ips if i not in _apk_ex_h])

            apk_str = f"{len(targets)}종 등록됨" if targets else "미등록 (관리에서 등록)"
            target_str = f"{_apk_n_h}대 지정됨 (예외 {len(_apk_ex_h)}대 · 영구 저장)"
            if tgt_txt != "전체 기기":
                target_str += f" [이번 세션: {tgt_txt}]"
            mirror_str = f"{_mir_n}대 지정됨 (예외 {len(_excl_m)}대)" + (" · 엔진 ✔" if _eng else " · 엔진 없음")

            lines = [_get_standard_menu_header_str(
                "adb_deploy", settings,
                apk_info=apk_str,
                target_info=target_str,
                mirror_info=mirror_str
            )]
            lines.append(f" 💾 {ctext('실시간 안드로이드 기기 연결 & 배포 상태', C.SKY)}")
            lines.append(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
            lines.append(f"  • {ctext('adb 상태', C.GREEN)}: "
                         f"{'✔ 사용가능' if adb else '✘ 미발견'}")
            _dev_lines = _adb_phone_summary_lines(devs, _devinfo, known_ips)
            lines.append(f"  • {ctext('연결 기기', C.GREEN)}: "
                         f"{C.GRAY}(연결 {len(devs)}대 / 등록 {len(known_ips)}개){C.RESET}")
            lines.extend(_dev_lines)
            lines.append(f"  • {ctext('1축 설치할 APK', C.GOLD)}: "
                         f"{C.GREEN}{len(targets)}종{C.RESET} "
                         f"{C.GRAY}({', '.join(os.path.basename(a) for a in targets) if targets else '등록 없음'}){C.RESET}")
            lines.append(f"  • {ctext('2축 배포 대상폰', C.GOLD)}: "
                         f"{C.GREEN}{_apk_n_h}대{C.RESET} "
                         f"{C.GRAY}(예외 {len(_apk_ex_h)}대 · 저장됨){C.RESET}"
                         + (f" ⚡ {C.SKY}이번 폰: {tgt_txt}{C.RESET}" if tgt_txt != "전체 기기" else ""))
            lines.append(f"  • {ctext('3축 미러링 폰', C.GOLD)}: "
                         f"{C.GREEN}{_mir_n}대{C.RESET} "
                         f"{C.GRAY}(예외 {len(_excl_m)}대){C.RESET}"
                         + (" · 엔진 ✔" if _eng else f" {C.YELLOW}· 엔진 없음{C.RESET}"))
            lines.append(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
            lines.append(f"  💡 {C.GRAY}무선 ADB 페어링은 최초 1회만 등록하면 영구 유지됩니다.{C.RESET}")
            return "\n".join(lines)

        sel, _, *_ = _interactive_menu(
            "📱 안드로이드 ADB 무선배포 · 화면 미러링 · 멀티 제어",
            opts,
            dynamic_header_callback=_header_cb
        )
        # [★ 방어 · 2026-10-11] 예전 한 줄짜리 조건이면 **구분선 번호를 누르는 순간
        #   `sel not in act` 이 참이 되어 `break` → ADB 스튜디오가 통째로 닫혔다.**
        #   이제 `_is_divider` 가 구분선을 미리 걸러내지만(번호 미부여),
        #   혹시라도 act 에 없는 인덱스가 오면 **메뉴를 닫지 말고 다시 그리게** 한다.
        if sel < 0:
            break                      # 취소/ESC → ADB 메뉴 종료(정상)
        if sel not in act:
            continue                   # 구분선 등 무효 인덱스 → 무시하고 재렌더
        if act[sel][0] in ("exit", "none"):
            break

        kind, payload = act[sel]

        # [참고] '📡 상태 보기' 는 2026-10-10 에 제거했다(헤더와 내용이 중복).
        #   act 는 매 루프마다 위 메뉴 정의로 다시 만들어지므로 'status' 키는
        #   도달할 수 없다 → unreachable 분기(죽은 코드)를 남기지 않는다.

        # ── 🔄 기기 정보 새로고침 ──
        if kind == "refresh_info":
            print(f"\r\n 🔄 {C.BOLD}{C.SKY}연결된 기기 정보를 실시간으로 새로고침하는 중...{C.RESET}")
            _devinfo = _adb_dev_info_map(adb, devs, force=True)
            print(f" ✅ {C.GREEN}기기 {len(devs)}대 정보 최신화 완료!{C.RESET}")
            time.sleep(0.8)
            continue

        # ── 진행할 폰(기기) 선택 ──
        if kind == "pick_dev":
            _adb_device_pick_wizard(devs)
            continue

        # ── 버전 확인 + 선택 배포 ──
        if kind == "version":
            _adb_version_wizard(settings, app_dir, adb, devs)
            continue

        # [참고] 'scan' 항목과 분기는 2026-10-10 에 **완전히 제거**했다.
        #   검색·등록은 이제 'manage_apks'(APK 대상 관리) 화면 안으로 들어갔다.
        #   → act 는 매 루프마다 메뉴 정의로 다시 만들어지므로 옛 'scan' 키는
        #     도달할 수 없다. unreachable 분기(죽은 코드)를 남기지 않는다.

        # ── 📦 APK 설치할 기기 지정 (Space 다중선택 · 예외폰 · 저장) ──
        if kind == "apk_pick":
            _adb_apk_pick_wizard()
            continue

        # ── 📺 미러링할 기기 지정 (Space 다중선택 · 예외폰) ──
        if kind == "mirror_pick":
            _adb_mirror_pick_wizard()
            continue

        # ── 📺 선택된 폰 전체 동시 미러링 ──
        if kind == "mirror_all":
            _adb_mirror_all(turn_off_screen=bool(payload))
            continue

        # ── 📱 특정 폰 1대 고화질 미러링 ──
        if kind == "mirror_one":
            _adb_mirror_single()
            continue

        # ── ⚡ ADB 명령어 전송 & 스마트 제어실 (전체/1대 통합 · 2026-10-11) ──
        #  [★ 최적화] '전체 대상 폰 동시' / '특정 폰 1대 선택' 두 항목을 한 항목으로 통합.
        #  [★ 버그수정] 예전 '전체' 경로는 _ADB_SEL_DEVS(이번 작업 폰 지정)를 **무시했다.**
        #    '이번 작업만 특정 폰 1대 지정'을 해놓고 제어실은 전체 폰을 잡는 모순 →
        #    설치(_adb_install_apk)·버전 비교와 **같은 규칙**으로 좁히도록 고쳤다.
        if kind == "cmd":
            if not adb:
                print(f"\r\n ❌ {C.RED}adb 미발견{C.RESET}")
                time.sleep(2)
                continue
            _ex = _phone_apk_exclude() if _PHONE_COMMON_OK else set()
            _cand = [d for d in devs if d not in _vr_set]
            _cand = [d for d in _cand if not any(ip in d for ip in _ex)] or _cand
            # ★ 세션 지정이 있으면 그 폰들로 좁힌다(설치·버전 비교와 동일 규칙).
            if sel_devs:
                _narrow = [d for d in _cand if d in sel_devs]
                if _narrow:
                    _cand = _narrow
            if not _cand:
                print(f"\r\n ⚠️ {C.YELLOW}연결된 대상 기기가 없습니다.{C.RESET}")
                time.sleep(2)
                continue
            # 폰이 1대뿐이면 선택 과정 없이 바로 진입(추가 클릭 방지).
            if len(_cand) == 1:
                _adb_control_center_wizard(settings, adb, _cand, mode='one')
                continue

            _dinfo_local = _adb_dev_info_map(adb, _cand)
            _sub_opts, _sub_act = [], {}
            _sub_opts.append(f"⚡ {C.BOLD}{C.GOLD}전체 {len(_cand)}대 동시 제어{C.RESET} "
                             f"{C.GRAY}[여러 폰에 동시에 전송]{C.RESET}")
            _sub_act[0] = ('all', None)
            _sub_opts.append("──────────────────────────────────────────────────────────")
            for _i, _d in enumerate(_cand):
                _lbl = _adb_device_label(_dinfo_local.get(_d) or {}) or _d
                _sub_opts.append(f"📱 {_lbl} {C.GRAY}한 대만{C.RESET}")
                _sub_act[_i + 1] = ('one', _d)
            _sub_opts.append("──────────────────────────────────────────────────────────")
            _sub_opts.append("🚪 뒤로가기")
            _s_idx, _, *_ = _adb_menu_esc(_interactive_menu, "제어할 폰을 고르세요", _sub_opts)
            if isinstance(_s_idx, int) and _s_idx in _sub_act:
                _mode, _one = _sub_act[_s_idx]
                _adb_control_center_wizard(settings, adb,
                                           _cand if _mode == 'all' else [_one], mode=_mode)
            continue

        # ── 등록 APK 목록 관리(해제) ──
        if kind == "manage_apks":
            _adb_apk_manage_wizard(settings, app_dir)
            continue

        # ── pairing 등록 ──
        if kind == "pair":
            if not adb:
                print(f"\r\n ❌ {C.RED}adb 를 찾지 못했습니다.{C.RESET}")
                time.sleep(2)
                continue
            _adb_pair_wizard(adb)
            try:
                input(f"\n {C.GRAY}Enter 키를 누르면 돌아가요...{C.RESET}")
            except (KeyboardInterrupt, EOFError):
                pass
            continue

        # ── USB → tcpip 고정 ──
        if kind == "usb_tcpip":
            _adb_usb_wizard()
            continue

        # ── 등록 기기 정리(개별 삭제 / 전체 삭제) ──
        if kind == "reset":
            _adb_reset_wizard()
            continue

        # ── 단일 앱 무음 설치 ──
        if kind == "install":
            apk, label = payload
            print(f"\r\n {C.BOLD}{C.SKY}📦 {label} 무선 배포{C.RESET}")
            if not adb:
                print(f" ❌ {C.RED}adb 미발견 — 먼저 adb 를 설치해야 합니다.{C.RESET}")
                time.sleep(2)
                continue
            print(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
            ok = _adb_install_apk(apk)
            if not ok:
                print(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
                print(f" 💡 {C.GRAY}기기가 없으면 '무선 ADB 최초 등록' 을 먼저 해주세요.{C.RESET}")
            try:
                input(f"\n {C.GRAY}Enter 키를 누르면 돌아가요...{C.RESET}")
            except (KeyboardInterrupt, EOFError):
                pass
            continue

        # ── 전체 일괄 설치 ──
        if kind == "install_all":
            if not adb:
                print(f"\r\n ❌ {C.RED}adb 미발견 — 먼저 adb 를 설치해야 합니다.{C.RESET}")
                time.sleep(2)
                continue
            all_targets = _adb_targets(settings, app_dir)
            if not all_targets:
                print(f"\r\n ⚠️ {C.YELLOW}배포 대상 APK 가 없습니다.{C.RESET}")
                time.sleep(2)
                continue
            print(f"\r\n {C.BOLD}{C.SKY}🚀 {len(all_targets)}종 일괄 무선 배포 시작{C.RESET}")
            print(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
            results = []
            for apk in all_targets:
                nm = os.path.basename(apk)
                print(f"\n 📦 {nm}")
                ok = _adb_install_apk(apk)
                results.append((nm, ok))
            print(f"\n ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
            succ = sum(1 for _, o in results if o)
            color = C.GREEN if succ == len(results) else C.YELLOW
            print(f" {color}결과: {succ}/{len(results)} 성공{C.RESET}")
            for label, o in results:
                print(f"   {'✅' if o else '❌'} {label}")
            try:
                input(f"\n {C.GRAY}Enter 키를 누르면 돌아가요...{C.RESET}")
            except (KeyboardInterrupt, EOFError):
                pass
            continue


# [TAG: #@_py_internal_script_names]
# ══ 공개 배포 안전 (SSOT) ══════════════════════════════════════════════
# [규칙] AGENTS.md §공개/비공개 배포 경계 + 99 감사 P1 (2026-10-09)
#   내부 스크립트 파일명은 **여기 한 곳**에만 적는다. (99 감사에서 4곳 분산 확인)
#   · 여러 곳에 흩으면 하나만 고쳤을 때 다른 곳이 남는다.
#   · check_public_release.py 의 INTERNAL_NAMES 와 반드시 함께 갱신한다.
# [99 감사 P3 · 2026-10-10] phone_common.py 추가 —
#   냥폰/ADB배포 공용 엔진이라 공개 저장소에 올라가면 안 되는 비공개 파일이다.
#   (INTERNAL_NAMES 와 1:1 유지)
_INTERNAL_PY_FILES = ("nyangphone.py", "adb_deployer.py", "tui_menu.py", "phone_common.py")


# [TAG: #@_py_launcher_probe]
def _py_launcher_probe(app_dir):
    """내장 py 실행기 후보의 '진짜 존재'를 판별한다 (파일명 AND 내용 지표).

    [규칙] AGENTS.md §공개/비공개 배포 경계 + 사용자 지시(2026-10-09)
      - 파일명만 같으면 통과시키지 않는다. (다른 사람이 만든 동명 파일일 수 있다)
      - 반드시 **내용 지표(시그니처 문자열)** 까지 확인해야 진짜 우리 스크립트다.
      - 파일명은 _INTERNAL_PY_FILES 한 곳에만 적는다(분산 금지).
      - 공개 배포본에는 이 파일들이 없으므로 결과는 전부 False 다.

    반환: {키: True/False}
        'nyangphone'  : 냥폰(스마트폰 무선 미러링)
        'adb'         : 안드로이드 무선 ADB 배포 도우미
    """
    out = {'nyangphone': False, 'adb': False}

    def _has_marker(fn, markers):
        """파일이 존재하고, 내용에 지표 문자열이 하나라도 있으면 True."""
        path = os.path.join(app_dir, fn)
        if not os.path.isfile(path):
            return False
        try:
            with open(path, 'r', encoding='utf-8', errors='replace') as f:
                head = f.read(8192)      # 앞부분만 읽으면 충분(헤더 docstring 영역)
        except Exception:
            return False
        return any(m in head for m in markers)

    # 냥폰 — 스크립트 시그니처 (파일명은 SSOT 상수에서)
    out['nyangphone'] = _has_marker(
        _INTERNAL_PY_FILES[0],
        ("nyangphone", "scrcpy", "무선 미러링")
    )
    # ADB 도우미 — 시그니처 + **실제 등록된 기기 IP 존재** (지표)
    if _has_marker(_INTERNAL_PY_FILES[1],
                   ("adb install -r", "wireless debugging", "pairing")):
        out['adb'] = bool(_adb_load_ips())   # 폰이 한 대라도 등록돼 있어야 노출

    return out


# [TAG: #@_py_launcher_describe]
def _py_launcher_describe(item):
    """등록 항목의 한 줄 설명을 얻는다.

    [규칙] 사용자 지시(2026-10-09) — "이게 머야?" 방지.
      사용자가 직접 실행해본 적 없는 도구일수록 **무엇을 하는지** 알려야 한다.
      1) 등록 시 저장한 'desc' 를 우선 사용
      2) 없으면 파일 첫 docstring 을 자동으로 뽑아 요약으로 쓴다
    """
    d = (item.get("desc") or "").strip()
    if d:
        return d
    # 자동 추출: 첫 docstring 의 첫 의미 있는 줄
    path = item.get("path", "")
    try:
        if path and os.path.isfile(path):
            with open(path, 'r', encoding='utf-8', errors='replace') as f:
                lines = f.read(4096).splitlines()
            for ln in lines:
                s = ln.strip().lstrip('#').strip().strip('"\'').strip()
                if not s:
                    continue
                # 인코딩 선언 / 구분선 / 단독 따옴표(raw-string r) 는 설명이 아니다
                if s.startswith('-*-') or s.startswith('coding'):
                    continue
                if set(s) <= set('=-—─━*#~·• \'"r'):
                    continue
                if len(s) < 4:
                    continue
                return s[:60]
    except Exception:
        pass
    return ""


# [TAG: #@manage_custom_py_launchers_interactive]
def manage_custom_py_launchers_interactive(settings):
    """[V1.0] 등록된 파이썬 스크립트(.py) 별도 창(새 콘솔) 원클릭 실행 및 관리 마법사 🚀✨"""
    app_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in globals() else os.getcwd()

    def _scan_srt_py_candidates():
        """srt 폴더 및 하부폴더 내 파이썬 스크립트 검색 (백업/임시 폴더 제외) 🔍"""
        exclude_dirs = {
            "backup", "backups", "temp", "logs", ".git", "__pycache__", ".agents",
            "build", "dist", ".gradle", ".idea", ".vscode", "models_cache",
            "gosh_test", "test", ".gemini", "node_modules", "playlists"
        }
        candidates = []
        for root, dirs, files in os.walk(app_dir):
            # 백업 및 임시 폴더 필터링
            dirs[:] = [
                d for d in dirs
                if d.lower() not in exclude_dirs
                and not d.startswith(".")
                and "backup" not in d.lower()
                and "temp" not in d.lower()
            ]
            for f in files:
                if not f.lower().endswith('.py'):
                    continue
                # 자기 자신 및 백업 파일 제외
                if f.lower() == "korea.srt.py" or "backup" in f.lower() or "bak" in f.lower():
                    continue
                full_p = os.path.join(root, f)
                # [99 감사 P3] import 전용 헬퍼 모듈(tui_menu.py 등)은 '실행'할 수 없다.
                #   __main__ 블록이 없는 .py 는 등록 후보에서 제외한다(실수로 등록하면 no-op).
                #   판독 실패 시에는 제외하지 않는다(안전한 쪽 = 보여주기).
                try:
                    if os.path.getsize(full_p) < 2 * 1024 * 1024:
                        with open(full_p, 'r', encoding='utf-8', errors='ignore') as pf:
                            if '__main__' not in pf.read():
                                continue
                except Exception:
                    pass
                rel_p = os.path.relpath(full_p, app_dir)
                candidates.append((rel_p, full_p))
        candidates.sort(key=lambda x: (x[0].count(os.sep), x[0].lower()))
        return candidates

    while True:
        if settings:
            settings.load()

        launchers = settings.data.get('custom_py_launchers', [])
        if not isinstance(launchers, list):
            launchers = []
            settings.data['custom_py_launchers'] = launchers

        # ⚠️ [규칙] 자동 등록 금지 — 사용자가 직접 등록한다.
        #   과거 내장 스크립트를 "추천" 형태로 자동 등록했으나,
        #   사용자가 "내가 등록한 게 아니다 → 다른 사람이 보면 이게 머냐" 라고 지적해서 폐기했다.
        #   이제 등록은 전부 '🔍 검색해서 등록' 또는 '✍️ 경로 직접 입력' 으로만 한다.

        # 메뉴 리스트 구성
        menu_opts = []
        action_map = {}  # index -> action/item

        # [규칙] 사용자 지시(2026-10-09) — "첨자는 내부 구조를 몰라야 한다".
        #   첨자 격리는 **자동 등록분(legacy_auto) 한정**이다.
        #   ⚠️ 99 감사(2026-10-09) P0 수정 — 이전엔 이름에 'adb' 가 섞인지만 보고 숨겼더니,
        #      **사용자가 직접 등록한 항목까지 사라지는** 결함이 생겼다.
        #      직접 등록은 사용자의 명시적 의도이므로 절대 숨기지 않는다.
        _probe = _py_launcher_probe(app_dir)

        # [규칙] 2026-10-10 ADB 메뉴 중복 해소 —
        #   'ADB 배포 도우미'(adb_deployer.py)와 '무선 ADB 배포 마법사'(내장 엔진)은
        #   **같은 기능의 2벌**이라 목록이 어색했다. 내장 마법사가 더 완성도 높으므로
        #   등록 항목을 **삭제하지 않고** '내장 마법사로 열기'로 승격한다.
        #   (파일·설정은 그대로 남으므로 되돌리기 쉽고 사용자 선택도 존중한다)
        _ADB_SUPERSEDED = ('adb_deployer.py',)

        def _is_superseded_adb(it):
            """내장 마법사가 이미 있는 ADB 배포 도우미 항목인가?"""
            p = (it.get("path") or "").lower()
            return any(p.endswith(s) for s in _ADB_SUPERSEDED)

        # 첨자에게 숨길 대상 판정 (자동 등록분만)
        def _should_hide(it):
            if it.get("legacy_auto") is not True:
                return False        # → 직접 등록분은 항상 보인다
            p = (it.get("path") or "").lower()
            n = (it.get("name") or "").lower()
            if "adb_deployer" in p or "adb" in n:
                return not _probe['adb']
            if "nyangphone" in p or "냥폰" in n:
                return not _probe['nyangphone']
            return False

        visible = [it for it in launchers if not _should_hide(it)]

        # ── 📱 폰 관리 (미러링 · 무선 ADB) 상단 통합 블록 ──
        #   냥폰/ADB 처럼 "폰"을 다루는 항목은 위(일반 스크립트)보다 위쪽에 둔다.
        # [99 감사 P1 · 2026-10-10] 예전엔 '_adb_known(등록된 폰 있음)' 도 조건이라서,
        #   **폰 목록이 비면 마법사까지 사라졌다** → pairing 진입점이 없어 FIRST-RUN 불가.
        #   → adb 만 있으면 항상 노출한다(첫 pairing 이 곧 이 화면에서 한다).
        _phone_block = [it for it in visible if _is_superseded_adb(it)]
        _adb_known = _adb_load_ips()
        # [규칙] 2026-10-10 사용자 지적 — "냥폰/ADB 메뉴의 폰 정보가 부실하다".
        #   예전 태그는 '등록됨 N대' 라는 **개수만** 보여줘서 어떤 폰인지 알 수 없었다.
        #   → 마법사(_adb_deploy_menu)와 **똑같은 수집기**로 기종·OS·배터리·IP까지
        #     읽어와 태그와 헤더 양쪽에 진짜 정보를 보여준다(SSOT: _adb_dev_info_map).
        #   ⚠️ adb 호출은 **메뉴를 그릴 때 1회만** 한다. 헤더 콜백 안에서 adb 를 부르면
        #      키 입력마다 adb 가 돌아 화면이 멈춘다(먹통) → 아래에서 한 번 계산해 변수로 넘긴다.
        _adb_exe = _adb_exe_path()
        _adb_devs = _adb_connected(_adb_exe) if _adb_exe else []
        _adb_info = _adb_dev_info_map(_adb_exe, _adb_devs) if _adb_devs else {}
        # [규칙] 2026-10-10 통합 — ADB 무선배포/미러링은 **메인 메뉴 21번**으로 승격했다.
        #   여기선 같은 마법사를 또 띄우면 '어디로 가야 하지?' 혼란만 늘어난다(중복).
        #   → '바로가기' 한 줄로 대체한다.
        #   [99 감사 P3] 조건을 _phone_block 하나로 정리했다. 예전엔
        #   `if _phone_block or _probe['adb']:` 안에 또 `if _phone_block:` 를 겹쳐
        #   바깥 조건이 _adb_tag 계산만 하는 죽은 중첩이 돼 있었다.
        #   adb 만 있고 미등록인 경우에도 이 메뉴는 의미가 없다
        #   (진입점은 언제나 메인 메뉴 21번 → phone_hub 가 담당한다).
        if _phone_block:
            _adb_tag = _adb_menu_tag(_adb_devs, _adb_info, _adb_known)
            adb_idx = len(menu_opts)
            menu_opts.append(
                f"📱 {C.BOLD}{C.CYAN}안드로이드 ADB/미러링 마법사 바로가기{C.RESET} "
                f"{C.GRAY}[메인 메뉴 'ADB 무선배포·미러링·멀티제어' 에도 있음]{C.RESET}{_adb_tag}")
            action_map[adb_idx] = ("adb_wizard", None)

        if visible:
            for idx, item in enumerate(visible):
                p_name = item.get("name", "파이썬 스크립트")
                p_path = item.get("path", "")
                # [규칙] ADB 도우미 항목은 위 통합 블록에서 이미 '마법사'로 승격했다.
                #   여기서 다시 같은 항목을 다루면 메뉴가 2벌로 보인다(중복).
                if _is_superseded_adb(item):
                    continue
                exists_mark = "🟢" if os.path.exists(p_path) else "❌ (파일없음)"
                base_fn = os.path.basename(p_path)
                _desc = _py_launcher_describe(item)
                if len(_desc) > 52:
                    _desc = _desc[:51] + "…"
                _desc_txt = f" {C.GRAY}└ {_desc}{C.RESET}" if _desc else ""
                menu_opts.append(f"🚀 {p_name} {C.GRAY}[{exists_mark} {base_fn}]{C.RESET}{_desc_txt}")
                action_map[len(menu_opts) - 1] = ("run", item)
        else:
            menu_opts.append(f"  {C.GRAY}(현재 등록된 파이썬 스크립트가 없습니다){C.RESET}")
            action_map[len(menu_opts) - 1] = ("none", None)

        # (참고) 위에서 continue 로 걸러진 항목이 전부면 목록이 비어 있는 것처럼 보인다.
        #   첨자에게 내부 구조를 숨기기 위해 '없음' 문구로 자연스럽게 대체한다.

        menu_opts.append("──────────────────────────────────────────────────────────")

        add_scan_idx = len(menu_opts)
        menu_opts.append("🔍 srt 폴더 내 파이썬(.py) 앱 검색해서 후보에서 등록 👈")
        action_map[add_scan_idx] = ("add_scan", None)

        add_manual_idx = len(menu_opts)
        menu_opts.append("✍️ 경로 직접 입력하여 파이썬 파일 등록")
        action_map[add_manual_idx] = ("add_manual", None)

        del_idx = len(menu_opts)
        menu_opts.append("🗑️ 등록된 파이썬 스크립트 삭제")
        action_map[del_idx] = ("del", None)

        # [99 감사 P1 · 2026-10-10] ADB 마법사는 위 통합 블록에서 **항상** 노출한다
        #   (adb 만 있으면 됨). 따라서 아래에 2벌로 다시 열지 않는다 = 중복 방지.

        open_folder_idx = len(menu_opts)
        menu_opts.append(f"📂 파이썬 프로그램 폴더 열기 ({C.GRAY}{app_dir}{C.RESET})")
        action_map[open_folder_idx] = ("open_folder", None)

        menu_opts.append("──────────────────────────────────────────────────────────")
        exit_idx = len(menu_opts)
        menu_opts.append("🚪 메인 메뉴로 돌아가기")
        action_map[exit_idx] = ("exit", None)

        def _header_cb(selected_idx=0):
            lines = []
            # [규칙] 99 감사 P1 — 헤더는 "실제 표시되는" 개수를 써야 한다(숨김 항목 포함 시 불일치).
            _shown = len(visible)
            h_str = _get_standard_menu_header_str("custom_py_launcher", settings, py_count=_shown)
            lines.append(h_str)
            lines.append(f" 💾 {ctext('파이썬 스크립트 런처 상태 요약', C.SKY)}")
            lines.append(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
            lines.append(f"  • {ctext('등록된 실행 파일', C.GREEN)}: {_shown}개 스크립트")
            lines.append(f"  • {ctext('실행 방식', C.YELLOW)}: Windows CMD 독립 콘솔 창 (메인 프로그램 무간섭 🪟)")
            lines.append(f"  • {ctext('기본 작업 폴더', C.SKY)}: {app_dir}")
            # [규칙] 사용자 지시(2026-10-09) — "이게 머야?" 방지.
            #   아래에 각 항목이 **무엇을 하는 도구인지** 한 줄씩 밝혀 준다.
            if visible:
                lines.append(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
                lines.append(f" 📖 {ctext('각 항목이 하는 일', C.SKY)}")
                for _it in visible:
                    _n = _it.get("name", "")
                    # [규칙] 2026-10-10 — ADB 도우미는 위에서 '마법사'로 승격되므로
                    #   여기서 또 설명을 거듭하면 사용자가 같은 걸 2번 세게 된다.
                    if _is_superseded_adb(_it):
                        continue
                    _d = _py_launcher_describe(_it)
                    if len(_d) > 58:
                        _d = _d[:57] + "…"
                    lines.append(f"   • {ctext(_n, C.GREEN)}")
                    lines.append(f"     {C.GRAY}└ {_d or '설명 없음'}{C.RESET}")
            lines.append(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
            # [규칙] 2026-10-10 사용자 지적 — "폰 정보가 부실하다".
            #   ADB 항목의 태그만으로는 부족해 **헤더에도 폰을 한 대 한 줄로** 세운다.
            #   (마법사 헤더와 완전히 같은 내용·양식 = _adb_phone_summary_lines SSOT)
            #   ⚠️ adb 를 다시 부르지 않는다 — 위에서 1회 수집한 값을 재사용한다.
            if _adb_known or _adb_devs:
                lines.append(f" 📱 {ctext('내 폰 상태', C.SKY)}")
                lines.append(f"  • {ctext('adb', C.GREEN)}: "
                             f"{'✔ 사용가능' if _adb_exe else '✘ 미발견'}"
                             f" {C.GRAY}(연결 {len(_adb_devs)}대 / 등록 {len(_adb_known)}대){C.RESET}")
                lines.extend(_adb_phone_summary_lines(
                    _adb_devs, _adb_info, _adb_ip_strings()))
                lines.append(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
            lines.append(f"  💡 {C.GRAY}배포·점검 도구는 소스 수정 후 '배포/검사'가 필요할 때만 실행합니다.{C.RESET}")
            return "\n".join(lines)

        sel, _, *_ = _interactive_menu(
            "🚀 등록된 파이썬(py) 스크립트 실행 & 관리 마법사",
            menu_opts,
            dynamic_header_callback=_header_cb
        )

        if sel < 0 or sel not in action_map or action_map[sel][0] in ("exit", "none"):
            break

        act, target_item = action_map[sel]

        # [0] 안드로이드 3종 무선 ADB 배포 마법사 (등록 + 무음 배포)
        if act == "adb_wizard":
            _adb_deploy_menu(settings)
            continue

        # [1] 실행
        if act == "run":
            p_path = target_item.get("path", "")
            p_name = target_item.get("name", "파이썬 스크립트")
            if not os.path.exists(p_path):
                print(f"\r\n ❌ {C.RED}파일을 찾을 수 없습니다:{C.RESET} {p_path}")
                time.sleep(2)
                continue

            print(f"\r\n 🚀 {C.BOLD}{C.SKY}[{p_name}]{C.RESET} 실행 중...")
            try:
                target_cwd = os.path.dirname(p_path) or app_dir
                win_title = f"{p_name}"
                py_exe = sys.executable

                # Windows Terminal(wt.exe)이 설치되어 있으면 깔끔한 새 창으로 실행
                wt_path = shutil.which("wt") if os.name == 'nt' else None
                if wt_path:
                    # wt -w 0 nt: 새 창(또는 현재 터미널 새 탭)으로 열기
                    # cmd.exe /k 로 감싸서 스크립트가 끝나거나 에러가 나도 창이 바로 꺼지지 않고 대기
                    wt_cmd = [
                        wt_path, "--window", "new", "--title", win_title, "-d", target_cwd,
                        "cmd.exe", "/k", f'"{py_exe}" "{p_path}"'
                    ]
                    subprocess.Popen(wt_cmd, cwd=target_cwd)
                else:
                    # wt가 없는 경우 cmd.exe /c start 로 새 창 띄우고 /k 로 유지
                    # start "" cmd.exe /k ""python.exe" "script.py""
                    cmd_line = f'start "{win_title}" cmd.exe /k ""{py_exe}" "{p_path}""'
                    subprocess.Popen(cmd_line, shell=True, cwd=target_cwd)

                print(f" ✨ {C.GREEN}새 콘솔 창으로 성공적으로 실행되었습니다! 👍{C.RESET}")
                time.sleep(1)
            except Exception as e:
                print(f" ❌ {C.RED}실행 오류:{C.RESET} {e}")
                time.sleep(2)
            continue

        # [2] srt 폴더 검색 후보에서 등록
        elif act == "add_scan":
            print(f"\r\n 🔍 {C.BOLD}{C.SKY}srt 폴더 내 파이썬 스크립트 검색 중...{C.RESET}")
            cands = _scan_srt_py_candidates()
            if not cands:
                print(f" ⚠️ {C.YELLOW}등록 가능한 파이썬(.py) 파일을 찾지 못했습니다.{C.RESET}")
                time.sleep(2)
                continue

            registered_paths = {os.path.normpath(it.get("path", "")) for it in launchers}
            scan_opts = []
            for rel_p, full_p in cands:
                is_reg = os.path.normpath(full_p) in registered_paths
                reg_badge = f" {C.GREEN}[이미 등록됨]{C.RESET}" if is_reg else ""
                scan_opts.append(f"📄 {rel_p}{reg_badge}")
            scan_opts.append("──────────────────────────────────────────────────────────")
            scan_opts.append("↩️ 취소하고 돌아가기")

            c_sel, _, *_ = _interactive_menu(
                f"등록할 파이썬 스크립트를 선택하세요 (총 {len(cands)}개 발견)",
                scan_opts
            )
            if 0 <= c_sel < len(cands):
                chosen_rel, chosen_full = cands[c_sel]
                if os.path.normpath(chosen_full) in registered_paths:
                    print(f"\r\n ⚠️ {C.YELLOW}이미 등록되어 있는 파일입니다!{C.RESET}")
                    time.sleep(1.5)
                    continue

                default_name = os.path.splitext(os.path.basename(chosen_full))[0]
                # [규칙] AGENTS.md §공개/비공개 배포 경계 — 공개 배포본에 내부 파일명을
                #   하드코딩하지 않는다. 아래 매핑은 "사용자가 직접 등록할 때"만 쓰는
                #   입력 힌트이며(신규 등록이 아니므로 무해), 자동 추가 로직은 쓰지 않는다.
                #   자동 등록은 2026-10-09 사용자 지적으로 전면 폐기됨.
                if "nyangphone" in chosen_rel.lower():
                    default_name = "🐱 냥폰 매니저 (스마트폰 무선 미러링 & 멀티 제어)"
                elif "adb_deploy" in chosen_rel.lower():
                    default_name = "📱 안드로이드 무선 ADB 배포 도우미 (pairing · 자동 업데이트 · 무음 설치)"
                elif "deploy_apk" in chosen_rel.lower():
                    default_name = "📦 APK 통합 배포 도구 (deploy_apk)"
                elif "deploy_go" in chosen_rel.lower():
                    default_name = "🐧 go.sh / go.env FTP 배포 도구"

                print(f"\r\n 📌 선택된 파일: {C.SKY}{chosen_rel}{C.RESET}")
                inp_name = prompt_input(f" 👉 메뉴에 표시할 별칭 [Enter 치면 '{default_name}']: ").strip()
                if not inp_name:
                    inp_name = default_name

                launchers.append({
                    "name": inp_name,
                    "path": chosen_full,
                    "created_at": time.strftime("%Y-%m-%d %H:%M:%S")
                })
                settings.data['custom_py_launchers'] = launchers
                settings.save()
                print(f"\r\n 🎉 {C.GREEN}성공적으로 등록되었습니다! 👍{C.RESET}")
                time.sleep(1.5)
            continue

        # [3] 경로 직접 입력
        elif act == "add_manual":
            print(f"\r\n ✍️ {C.BOLD}{C.SKY}새 파이썬(.py) 스크립트 경로 직접 입력{C.RESET}")
            print(f" ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━")
            inp_path = prompt_input(" 👉 파이썬 파일 경로: ").strip().strip('"').strip("'")
            if not inp_path:
                continue

            if not os.path.isabs(inp_path):
                inp_path = os.path.abspath(os.path.join(app_dir, inp_path))

            if not os.path.exists(inp_path):
                print(f"\r\n ⚠️ {C.YELLOW}입력한 파일이 존재하지 않습니다:{C.RESET} {inp_path}")
                time.sleep(2)
                continue

            default_name = os.path.splitext(os.path.basename(inp_path))[0]
            inp_name = prompt_input(f" 👉 메뉴에 표시할 이름 [Enter 치면 '{default_name}']: ").strip()
            if not inp_name:
                inp_name = default_name

            launchers.append({
                "name": inp_name,
                "path": inp_path,
                "created_at": time.strftime("%Y-%m-%d %H:%M:%S")
            })
            settings.data['custom_py_launchers'] = launchers
            settings.save()
            print(f"\r\n 🎉 {C.GREEN}성공적으로 등록되었습니다!{C.RESET}")
            time.sleep(1.5)
            continue

        # [4] 삭제
        elif act == "del":
            if not launchers:
                print(f"\r\n ⚠️ {C.YELLOW}삭제할 스크립트가 없습니다.{C.RESET}")
                time.sleep(1.5)
                continue
            # [규칙] 99 감사 P0 — 삭제 대상은 **화면에 숨겨진 항목까지 전부**다.
            #   사용자가 직접 등록했는데 안 보이는 상태로 갇히면 안 되므로,
            #   숨김 항목에는 (현재 숨김) 표시를 붙여 여기서라도 정리할 수 있게 한다.
            del_opts = []
            for it in launchers:
                _tag = f" {C.RED}[현재 숨김]{C.RESET}" if _should_hide(it) else ""
                del_opts.append(f"🗑️ {it.get('name')} "
                                f"({os.path.basename(it.get('path', ''))}){_tag}")
            del_opts.append("↩️ 취소하고 돌아가기")
            d_sel, _, *_ = _interactive_menu("삭제할 파이썬 스크립트를 선택하세요", del_opts)
            if 0 <= d_sel < len(launchers):
                removed = launchers.pop(d_sel)
                settings.data['custom_py_launchers'] = launchers
                settings.save()
                print(f"\r\n 🗑️ {C.YELLOW}[{removed.get('name')}]{C.RESET} 목록에서 삭제되었습니다.")
                time.sleep(1.5)
            continue

        # [5] 폴더 열기
        elif act == "open_folder":
            os.startfile(app_dir)
            continue


