    if IS_SECONDARY_INSTANCE:
        _log_to_file("Running as Secondary Instance (Skipping Mutex)")
    elif not is_child_process and '--test' not in sys.argv:
        # [수정] 이미 Mutex를 획득한 상태(F4 등 루프 재진입)라면 건너뜀 🛡️
        if globals().get('_app_mutex_handle') is None:
            # [V66.0] 와치독과 동기화를 위해 전역 Mutex 이름 통일
            mutex_name = "Global\\BinuSubtitleGenerator_Mutex"

            # [V19.0] 지능형 중복 체크: 강제 종료 대신 사용자에게 선택권 부여 (서브앱 전환) 🛡️💬
            # [V135.5] AI냥 요청: F5 재시작 시 튕김 방지 (고스트 정리 및 재시도 루프) 🧟🧹✨
            mutex = ctypes.windll.kernel32.CreateMutexW(None, False, mutex_name)
            if ctypes.windll.kernel32.GetLastError() == 183: # ERROR_ALREADY_EXISTS
                # 1. 자가 잠금 방지를 위해 일단 핸들을 닫음
                ctypes.windll.kernel32.CloseHandle(mutex)

                # [V135.6] Bug Fix: 일반 실행 시 멀쩡한 기존 앱을 죽이는 문제 해결 🛡️
                # F5 재시작(--skip-check) 시에만 이전 인스턴스를 찾아 고스트 사냥을 수행합니다.
                # 사용자가 아이콘을 단순히 두 번 눌렀을 때는 잡지 않고 바로 서브앱 묻는 창(Y/N)으로 넘어갑니다.
                if '--skip-check' in sys.argv:
                    # 2. 고스트(좀비) 프로세스 자동 사냥 🕵️‍♂️🔥
                    try:
                        import psutil
                        curr_pid = os.getpid()
                        script_fn = os.path.basename(__file__)
                        ghosts_found = False
                        for proc in psutil.process_iter(['pid', 'name', 'cmdline']):
                            try:
                                if proc.pid == curr_pid: continue
                                cmdline = proc.info.get('cmdline') or []
                                cmdline_str = " ".join(map(str, cmdline))
                                if script_fn in cmdline_str:
                                    proc.kill()
                                    ghosts_found = True
                            except Exception as e:
                                # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                                if "6" not in str(e):
                                    _log_to_file(f"⚠️ [Silent Exception] {e}")

                        if ghosts_found:
                            _log_to_file("🧟 죽지 않은 고스트 앱 프로세스를 발견하여 정리했습니다. (F5 재시작 대응)")

                        # 3. 윈도우 커널이 핸들을 정리할 시간을 위한 재시도 루프 (최대 2.5초) ⏳
                        for _retry in range(5):
                            time.sleep(0.5)
                            mutex = ctypes.windll.kernel32.CreateMutexW(None, False, mutex_name)
                            if ctypes.windll.kernel32.GetLastError() != 183:
                                break # 성공!
                            ctypes.windll.kernel32.CloseHandle(mutex)
                    except Exception as _e:
                        _log_to_file(f" [Error] Ghost cleanup failed: {_e}")

                # 4. 재시도 후에도(또는 사냥을 안 해서) 여전히 잡혀있다면 그때만 팝업 진행 💬
                if ctypes.windll.kernel32.GetLastError() == 183:
                    # [V134.3] AI냥 요청: 30초 타임아웃 프롬프트 구현 🕰️🛰️✨
                    print(f"\r\n  {C.BOLD}{C.YELLOW}[중복 실행 감지]{C.RESET}")
                    print("  이미 비서(메인 앱)가 다른 곳에서 일하고 있어냥! 🐾")
                    print(f"  {C.SKY}서브앱(보조 창){C.RESET}으로 실행할까냥? (서버 기능을 제외한 기능만 사용 가능)")
                    print(f"  [Y] 서브앱 실행  /  [N] 종료  {C.DIM}(30초 뒤 자동 종료){C.RESET}")

                    import msvcrt
                    # 입력 버퍼 비우기 (기존의 남은 키 입력 무시 🧼)
                    while msvcrt.kbhit(): msvcrt.getch()

                    start_t = time.time()
                    choice = None
                    while time.time() - start_t < 30:
                        remaining = int(30 - (time.time() - start_t))
                        sys.stdout.write(f"\r  ⏰ 결정까지 {C.RED}{remaining:2d}{C.RESET}초 남았어냥... >> ")
                        sys.stdout.flush()

                        if msvcrt.kbhit():
                            _k = msvcrt.getch()
                            try: _k = _k.decode('utf-8').lower()
                            except: _k = str(_k)

                            if _k in ('y', '\r', '1'): # Y, Enter, 1
                                choice = 'y'
                                break
                            elif _k in ('n', 'q', '0', '\x1b'): # N, Q, 0, ESC
                                choice = 'n'
                                break
