                    if _media_on:
                        status_badges.append(f"{SKY}{C.BOLD}🌐 미디어서버 ON{R}")

                    # [V5.9] 실시간 재생 정보 집계
                    active_now = []
                    now_ts = time.time()
                    with _playing_sessions_lock:
                        for ip, info in list(_playing_sessions.items()):
                            if now_ts - info['time'] < 60:
                                active_now.append(f"{C.CYAN}{info['title']}{R} ({C.DIM}{ip}{R})")
