                            _f_state = "항상 켜기 🟢" if _f_always else "OFF ⚫"
                            _p_state = "항상 켜기 🟢" if _p_always else "OFF ⚫"
                            _pl_ref_state = "켜짐 🟢" if _pl_ref else "OFF ⚫"
                            _w_scope = "하위 폴더 포함 🟩" if recurse else "현재 폴더만 🟨"

                            _print_standard_menu_header("auto_watch", settings, f_state=_f_state, p_state=_p_state, target=f"{watch_folder} ({_w_scope})")

