def _pick_fotoo_slideshow_group(settings_obj, cfg_key=None):
    """🖼️ 특수 전역 핫키 fotoo_slideshow 액션의 타깃 플리(사진 플레이리스트) 선택 서브메뉴 🐾 (슬롯별 저장 지원)"""
    try:
        img_groups = (settings_obj.data or {}).get("playlist_image_groups", {}) or {}
        if not img_groups:
            print(f"\r\n ⚠️ {C.YELLOW}등록된 사진 플리가 하나도 없어냥! 먼저 플리를 등록해줘. 🖼️{C.RESET}")
            time.sleep(1.2)
            return
        group_names = [g for g in img_groups if not _is_playlist_private(settings_obj, g)]
        if not group_names:
            print(f"\r\n ⚠️ {C.YELLOW}선택 가능한 공개 사진 플리가 없어냥! (비공개 플리는 제외 🛡️){C.RESET}")
            time.sleep(1.2)
            return
        slot_key = _special_hotkey_slot_key(cfg_key, 'fotoo_slideshow')
        hidden_cnt = len(img_groups) - len(group_names)
        cur_tg = settings_obj.data.get(slot_key) or ''
        if not cur_tg:
            cur_tg = settings_obj.data.get('special_hotkey_photo_group') or ''
        opts = []
        cur_idx = 0
        for gi, g_name in enumerate(group_names):
            cnt = len(img_groups[g_name]) if isinstance(img_groups[g_name], (list, tuple)) else 0
            mark = f" {C.GREEN}✔️{C.RESET}" if g_name == cur_tg else ""
            opts.append(f" 🖼️  [{g_name}] (사진 {cnt}장){mark}")
            if g_name == cur_tg:
                cur_idx = gi
        opts.append(" ❌  취소")
        pick, _, *_ = _interactive_menu(
            "🖼️ fotoo_slideshow 슬라이드쇼 타깃 플리 선택냥! 🐾\r\n"
            f"{C.GRAY}핫키를 누를 때 브라우저로 재생할 사진 플리를 골라줘.{C.RESET}\r\n"
            f"{C.GRAY}현재 타깃: {cur_tg or '(없음 - 최초 실행 시 첫 플리 사용)'}{C.RESET}"
            + (f"\r\n{C.DIM}비공개 플리 {hidden_cnt}개는 목록에서 제외되었어. 🔒{C.RESET}" if hidden_cnt else ""),
            opts,
            default_idx=cur_idx,
            timeout=0
        )
        if 0 <= pick < len(group_names):
            sel = group_names[pick]
            settings_obj.data[slot_key] = sel
            settings_obj.save(dirty_keys=[slot_key])
            print(f"\r\n ✅ {C.GREEN}fotoo_slideshow 타깃 플리가 '{sel}'(으)로 설정되었습니다!{C.RESET}")
            time.sleep(1)
    except Exception as e:
        _log_to_file(f"Special Hotkey Error picking fotoo_slideshow group: {e}")


def _pick_playlist_target(settings_obj, cfg_key, kind_label, icon, is_music=False, legacy_key=None):
    """🎬/🎵 특수 전역 핫키 액션의 타깃 플리(동영상/음악) 선택 서브메뉴 공용 헬퍼 🐾 (슬롯별 저장 지원)"""
    try:
        pl_names = [p for p in _list_playlist_names(is_music=is_music) if not _is_playlist_private(settings_obj, p)]
        total_cnt = len(_list_playlist_names(is_music=is_music))
        if not pl_names:
            print(f"\r\n ⚠️ {C.YELLOW}선택 가능한 공개 {kind_label} 플리가 하나도 없어냥! (비공개 플리 제외 🛡️){C.RESET}")
            time.sleep(1.2)
            return
        hidden_cnt = total_cnt - len(pl_names)
        cur_tg = settings_obj.data.get(cfg_key) or ''
        if not cur_tg and legacy_key:
            cur_tg = settings_obj.data.get(legacy_key) or ''
        opts = []
        cur_idx = 0
        for pi, p_name in enumerate(pl_names):
            mark = f" {C.GREEN}✔️{C.RESET}" if p_name == cur_tg else ""
            opts.append(f" {icon}  [{p_name}]{mark}")
            if p_name == cur_tg:
                cur_idx = pi
        opts.append(" ❌  취소")
        pick, _, *_ = _interactive_menu(
            f"{icon} 특수 전역 핫키 [{kind_label} 셔플재생] 타깃 플리 선택냥! 🐾\r\n"
            f"{C.GRAY}핫키를 누를 때 연속 재생할 {kind_label} 플리를 골라줘.{C.RESET}\r\n"
            f"{C.GRAY}현재 타깃: {cur_tg or '(없음 - 최초 실행 시 첫 플리 사용)'}{C.RESET}"
            + (f"\r\n{C.DIM}비공개 플리 {hidden_cnt}개는 목록에서 제외되었어. 🔒{C.RESET}" if hidden_cnt else ""),
            opts,
            default_idx=cur_idx,
            timeout=0
        )
        if 0 <= pick < len(pl_names):
            sel = pl_names[pick]
            settings_obj.data[cfg_key] = sel
            settings_obj.save(dirty_keys=[cfg_key])
            print(f"\r\n ✅ {C.GREEN}{kind_label} 셔플재생 타깃 플리가 '{sel}'(으)로 설정되었습니다!{C.RESET}")
            time.sleep(1)
    except Exception as e:
        _log_to_file(f"Special Hotkey Error picking {cfg_key}: {e}")


def _is_special_hotkey_excluded():
    """현재 활성화(Foreground)된 창이 특수 핫키 예외 앱(예: 엑셀 등)인지 확인 🛡️✨"""
    try:
        import ctypes
        from ctypes import wintypes
        if not settings.data.get('special_hotkey_exclude_enabled', True):
            return False, ""
        
        exclude_list = settings.data.get('special_hotkey_exclude_apps', ['excel.exe'])
        if not exclude_list:
            return False, ""
        
        user32 = ctypes.windll.user32
        hwnd = user32.GetForegroundWindow()
        if not hwnd:
            return False, ""
        
        # 1. 프로세스 파일명 확인
        pid = wintypes.DWORD()
        user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
        pname = ""
        if pid.value:
            try:
                import psutil
                pname = psutil.Process(pid.value).name().lower()
            except Exception:
                pass
                
        # 2. 창 제목 확인
        length = user32.GetWindowTextLengthW(hwnd)
        title = ""
        if length > 0:
            buf = ctypes.create_unicode_buffer(length + 1)
            user32.GetWindowTextW(hwnd, buf, length + 1)
            title = buf.value.lower()
            
        for ex in exclude_list:
            ex_clean = ex.strip().lower()
            if not ex_clean:
                continue
            if ex_clean in pname:
                return True, pname
            if not ex_clean.endswith('.exe') and ex_clean in title:
                return True, title[:30]
                
        return False, ""
    except Exception as e:
        return False, ""


def _start_special_hardware_hotkey_thread():
    """[V22.40] Pause / Break (0x13) 및 Scroll Lock (0x91) Win32 RegisterHotKey 전용 백그라운드 스레드 가동 🚀✨"""
    import threading, ctypes, time
    from ctypes import wintypes

    def _special_hotkey_worker():
        user32 = ctypes.windll.user32
        VK_PAUSE = 0x13
        VK_SCROLL = 0x91
        HOTKEY_ID_PAUSE = 0xF102
        HOTKEY_ID_SCROLL = 0xF103
        MOD_NOREPEAT = 0x4000

        # [P0-1] GetAsyncKeyState 시그니처 명시 고정 — 반환형이 SHORT 여야 상위비트가 '누름중'이 된다 🛡️
        try:
            user32.GetAsyncKeyState.argtypes = [ctypes.c_int]
            user32.GetAsyncKeyState.restype = ctypes.c_short
        except Exception:
            pass

        def _is_down(vk):
            """해당 가상키가 '지금 물리적으로 눌려 있는가' (GetAsyncKeyState 상위비트)"""
            try:
                return bool(user32.GetAsyncKeyState(vk) & 0x8000)
            except Exception:
                return False

        # 스레드 전용 메시지 큐 생성
        msg = wintypes.MSG()
        user32.PeekMessageW(ctypes.byref(msg), None, 0, 0, 0)

        # 1. Pause 키 등록
        reg_pause = user32.RegisterHotKey(None, HOTKEY_ID_PAUSE, MOD_NOREPEAT, VK_PAUSE)
        _pause_mode = 'MOD_NOREPEAT'
        if not reg_pause:
            reg_pause = user32.RegisterHotKey(None, HOTKEY_ID_PAUSE, 0, VK_PAUSE)
            _pause_mode = 'NO-NOREPEAT(오토리필트ON)'

        # 2. Scroll Lock 키 등록
        reg_scroll = user32.RegisterHotKey(None, HOTKEY_ID_SCROLL, MOD_NOREPEAT, VK_SCROLL)
        _scroll_mode = 'MOD_NOREPEAT'
        if not reg_scroll:
            reg_scroll = user32.RegisterHotKey(None, HOTKEY_ID_SCROLL, 0, VK_SCROLL)
            _scroll_mode = 'NO-NOREPEAT(오토리필트ON)'

        # [P0-2] '어떤 플래그로 실제로 등록됐는지'를 로그에 남긴다.
        #   기존엔 `ScrollLock: True` 만 찍혀서 MOD_NOREPEAT 적용 여부를 알 수 없었다.
        #   폴백(플래그 0 = 오토리필트 ON)으로 등록돼 있으면 중복 WM_HOTKEY 의 진짜 원인이 된다. 🩺
        _log_to_file(
            f"Hotkey: Special HW Hotkeys registered - Pause: {bool(reg_pause)}[{_pause_mode}], "
            f"ScrollLock: {bool(reg_scroll)}[{_scroll_mode}] 🛡️🚀"
        )

        # [P0-1] ★ 물리 홀드 감시 폴러 ★ (10ms 간격 · Pause/Scroll 2개만 조회)
        #   WM_HOTKEY 는 '키다운'에서만 발생한다. 그래서 **직전에 인정한 탭 이후 '키를 뗐다'는 사실이
        #   한 번도 없는데** 또 WM_HOTKEY 가 도착했다면 = 오토리필트 리핏 / 키 바운스 / 드라이버 중복 주입이다.
        #   이걸 연타로 세면 '1회 눌렀는데 2연타로 동작'하는 오탐이 되므로 카운트에서 제외한다. 🛡️
        #   ⚠️ '현재 눌려 있는가' 만 보면 **정당한 첫 탭까지 오탐**된다(폴러가 키다운을 먼저 볼 수 있음).
        #      그래서 '눌림→뗌음 전환 횟수(릴리즈 카운터)' 로 판정한다.
        #      → 순수 시간 데바운스도, 순수 상태 판정도 아니라 '실제로 뗐는가' 기반이라 의도한 빠른 2연타는 살아남는다
        _phys_down = {VK_PAUSE: False, VK_SCROLL: False}
        _phys_rel_cnt = {VK_PAUSE: 0, VK_SCROLL: 0}  # '눌림→뗌음' 전환 누적 횟수

        def _phys_poll_worker():
            while True:
                for _vk in (VK_PAUSE, VK_SCROLL):
                    _d = _is_down(_vk)
                    if _phys_down[_vk] and not _d:
                        _phys_rel_cnt[_vk] += 1   # 키를 뗐다 = 릴리즈 1회 관측
                    _phys_down[_vk] = _d
                time.sleep(0.01)

        threading.Thread(target=_phys_poll_worker, name="SpecialKeyPhysPoll", daemon=True).start()

        def _is_dup_hotkey(vk, seen_rel):
            """직전 인정 탭 이후 '릴리즈'가 없고 아직 눌려 있으면 = 같은 홀드에서 재주입된 중복 WM_HOTKEY"""
            if seen_rel < 0:
                return False                                    # 아직 받은 적 없는 첫 탭 → 절대 중복 아님
            if _phys_rel_cnt.get(vk, 0) != seen_rel:
                return False                                    # 사이에 뗐다가 다시 눌린 것 = 정상 새 탭
            if not _phys_down.get(vk):
                return False                                    # 이미 뗌어 있음
            return _is_down(vk)                                 # 지금도 눌림 = 홀드 중 중복 주입

        # [V22.4x] Pause/Scroll Lock 1·2·3연타 공용 상태머신 헬퍼 🏓
        # [V22.6x] ⭐ 4·5연타까지 확장 — cfg_keys(슬롯 설정키 목록) 길이만큼 단계가 자동 생성된다.
        # - 설정 안 된 단계는 순차 폴백(2연타 미설정 시 1연타, 5연타 미설정 시 4연타 … 1연타 확정)
        # - '실제로 설정된 최대 연타 수'에 맞춰 판정 창 자동 확장 (3연타 이하 = 기존 0.4초 그대로 /
        #   4연타 = 0.5초 / 5연타 = 0.6초) → 고연타가 가능해도 저연타 지연이 늘지 않는다 ⏱️
        def _make_press_handler(cfg_keys, key_label, vk):
            cfg_keys = tuple(cfg_keys)
            st = {'last_ts': 0.0, 'count': 0, 'timer': None, 'gen': 0, 'last_fire_ts': 0.0,
                  'seen_rel': -1}  # [P0-1] -1 = 아직 인정한 탭 없음 (첫 탭 오탐 방지)
            BASE_WIN = 0.4  # 기본 연타 판정 창 (초)

            def _acts():
                return tuple(settings.data.get(k, 'disabled') for k in cfg_keys)

            def _max_tap():
                """실제로 '설정된' 최대 연타 수 (1 ~ len(cfg_keys))"""
                mx = 0
                for _i, _a in enumerate(_acts()):
                    if _a != 'disabled':
                        mx = _i + 1
                return mx

            def _win():
                return BASE_WIN + 0.1 * max(0, _max_tap() - 3)

            def _cancel_timer():
                if st['timer'] is not None:
                    try:
                        st['timer'].cancel()
                    except Exception:
                        pass
                    st['timer'] = None

            def _resolve(count):
                """연타 수에서 아래로 내려가며 '설정된 액션' 첫 단계 → (액션, 실제단계, 슬롯키)"""
                acts = _acts()
                for n in range(min(count, len(acts)), 0, -1):
                    if acts[n - 1] != 'disabled':
                        return acts[n - 1], n, cfg_keys[n - 1]
                return 'disabled', count, cfg_keys[0]

            def _fire(action_id, tap_n, slot_cfg=None):
                if action_id == 'disabled':
                    return
                _log_to_file(f"Special Hotkey: {key_label} {tap_n}연타 → '{action_id}' 🏓")
                threading.Thread(target=_execute_special_hardware_action, args=(action_id, slot_cfg), daemon=True).start()

            def _flush(count):
                """연타 확정 → 폴백 해석 후 즉시 발화"""
                _cancel_timer()
                st['count'] = 0
                # [P1] 확정 시 타임스탬프까지 초기화 → 다음 탭은 무조건 1연타로 시작
                st['last_ts'] = 0.0
                st['last_fire_ts'] = time.monotonic()
                _fire(*_resolve(count))

            def _arm():
                # [P1] 세대(generation) 토큰 — 취소 직전에 이미 실행 진입한 '이전' 타이머가
                #      새 타이머를 조기 확정하거나 카운트를 0으로 밀어버리는 경합을 원천 차단
                st['gen'] += 1
                _my_gen = st['gen']

                def _on_timeout():
                    if st['timer'] is None or st['gen'] != _my_gen:
                        return
                    st['timer'] = None
                    if st['count'] >= 1:
                        _flush(st['count'])
                    st['count'] = 0
                _cancel_timer()
                _t = threading.Timer(_win() + 0.05, _on_timeout)
                _t.daemon = True
                st['timer'] = _t
                _t.start()

            def on_press():
                # [P1] NTP 등으로 시계가 뒤로 가면 '간격 판정'이 음수가 되어 카운터 리셋이 깨진다
                #      → wall clock(time.time) 대신 단조 시계(monotonic) 사용
                now = time.monotonic()

                # [P0-1] ★ 핵심 수정: 물리 홀드 중 도착한 중복 WM_HOTKEY 무시 ★
                #   직전 인정 탭 이후 '키를 뗐다'는 사실이 없는데 또 WM_HOTKEY 가 왔다면
                #   = 오토리필트/키 바운스/드라이버 중복 주입 → 연타 카운트를 늘리지 않는다.
                if _is_dup_hotkey(vk, st['seen_rel']):
                    _log_to_file(f"Special Hotkey: {key_label} 중복 WM_HOTKEY 무시 (물리 홀드 중 재주입 · 연타 미증가) 🛡️")
                    return
                st['seen_rel'] = _phys_rel_cnt.get(vk, 0)

                max_tap = _max_tap()
                if now - st['last_ts'] > _win():
                    st['count'] = 0
                st['count'] = min(st['count'] + 1, len(cfg_keys))
                st['last_ts'] = now
                n = st['count']

                # 아직 최고 연타에 도달하지 않았다면 → 다음 탭 대기 (타이머 재무장)
                if n < max_tap:
                    _log_to_file(f"Special Hotkey: {key_label} {n}연타 입력 ({max_tap}연타 대기중...) 🏓⏱️")
                    _arm()
                    return

                # 최고 연타 도달 → 더 이상 설정된 단계 없으므로 확정 즉시 발화 (기존 동작 유지)
                if n == 1:
                    # 다중연타 미설정(1연타만 사용) → 기존 0.3초 중복 방지 가드
                    # [P1] 전역 공유 변수 → 핸들러별 상태로 분리 (Pause 와 Scroll 이 서로를 누락시키던 잠재 버그 제거)
                    if now - st['last_fire_ts'] > 0.3:
                        _flush(1)
                    else:
                        _cancel_timer()
                        st['count'] = 0
                    return
                _flush(n)
            on_press.state = st
            return on_press

        pause_handler = _make_press_handler(
            ('special_hotkey_pause', 'special_hotkey_pause2', 'special_hotkey_pause3',
             'special_hotkey_pause4', 'special_hotkey_pause5'), 'Pause', VK_PAUSE)
        scroll_handler = _make_press_handler(
            ('special_hotkey_scroll', 'special_hotkey_scroll2', 'special_hotkey_scroll3',
             'special_hotkey_scroll4', 'special_hotkey_scroll5'), 'Scroll Lock', VK_SCROLL)

        def _re_register(hotkey_id, vk):
            """패스스루 후 핫키 재등록 — 일시적 실패 시 재시도하여 '핫키 영구 사망' 방지 🛡️
            [V22.4x] 기존에는 RegisterHotKey 1회 실패 시 그 키를 앱 재시작 전까지 다시는
            받을 수 없었다. 최대 5회 재시도 + MOD_NOREPEAT 불가 시 평범한 플래그로 폴백."""
            for attempt in range(5):
                try:
                    if user32.RegisterHotKey(None, hotkey_id, MOD_NOREPEAT, vk):
                        return True
                except Exception:
                    pass
                time.sleep(0.08)
            try:
                if user32.RegisterHotKey(None, hotkey_id, 0, vk):
                    return True
            except Exception:
                pass
            _log_to_file(f"Special Hotkey: ⚠️ Hotkey re-register FAILED id={hotkey_id:#x} (5회 재시도 실패) 🛡️")
            return False

        try:
            while user32.GetMessageW(ctypes.byref(msg), None, 0, 0) > 0:
                if msg.message == 0x0312: # WM_HOTKEY
                    now = time.time()

                    if msg.wParam == HOTKEY_ID_PAUSE:
                        is_excluded, matched_app = _is_special_hotkey_excluded()
                        if is_excluded:
                            _log_to_file(f"Special Hotkey: Pause bypassed & passed through to excluded app ({matched_app}) 🛡️✨")
                            user32.UnregisterHotKey(None, HOTKEY_ID_PAUSE)
                            user32.keybd_event(VK_PAUSE, 0x45, 0, 0)
                            user32.keybd_event(VK_PAUSE, 0x45, 2, 0)
                            time.sleep(0.05)
                            reg_pause = _re_register(HOTKEY_ID_PAUSE, VK_PAUSE)
                        else:
                            pause_handler()

                    elif msg.wParam == HOTKEY_ID_SCROLL:
                        is_excluded, matched_app = _is_special_hotkey_excluded()
                        if is_excluded:
                            _log_to_file(f"Special Hotkey: Scroll Lock bypassed & passed through to excluded app ({matched_app}) 🛡️✨")
                            user32.UnregisterHotKey(None, HOTKEY_ID_SCROLL)
                            user32.keybd_event(VK_SCROLL, 0x46, 0, 0)
                            user32.keybd_event(VK_SCROLL, 0x46, 2, 0)
                            time.sleep(0.05)
                            reg_scroll = _re_register(HOTKEY_ID_SCROLL, VK_SCROLL)
                        else:
                            scroll_handler()

                user32.TranslateMessage(ctypes.byref(msg))
                user32.DispatchMessageW(ctypes.byref(msg))
        finally:
            for _h in (pause_handler, scroll_handler):
                try:
                    _st = getattr(_h, 'state', None)
                    if _st and _st.get('timer') is not None:
                        _st['timer'].cancel()
                except Exception:
                    pass
            if reg_pause: user32.UnregisterHotKey(None, HOTKEY_ID_PAUSE)
            if reg_scroll: user32.UnregisterHotKey(None, HOTKEY_ID_SCROLL)

    t = threading.Thread(target=_special_hotkey_worker, name="SpecialHWHotKeyThread", daemon=True)
    t.start()

# [TAG: #@_show_debug_log_tail]
def _show_debug_log_tail():
    """[지침 V2.1] F2 단축키 입력 시 하단 로그 표시를 토글합니다. 
    [V142.4] AI냥 요청: 탐색기나 팟플 중에도 작동하도록 전역 허용으로 변경! 🔓🚀
    [V142.5] 멀티 인스턴스 최적화: 현재 활성 창인 경우에만 작동하도록 제한합니다냥! 🛡️✨
    """
    if not _is_main_win_active(): return

    # 팟플레이어나 탐색기 등 특정 창이 활성일 때 혹은 메인 창이 활성일 때 모두 허용
    is_allowed = True

    # 너무 무분별한 전역 작동을 방지하고 싶다면 특정 클래스만 필터링할 수 있지만,
    # 사용자님 요청에 따라 F1처럼 시원하게 열어줍니다냥! ✨

    import winsound
    try: winsound.Beep(1000, 100) # 작동 확인용 비프음 🎵
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")

    _log_to_file("Hotkey: F2 pressed (Log Toggle - Global)")
    global _flag_show_f2_logs, _global_menu_redraw_flag, _last_log_file_stat
    _flag_show_f2_logs = not _flag_show_f2_logs
    if _flag_show_f2_logs:
        _last_log_file_stat = (0, 0, 0, 0, 0, False) # F2 켤 때 이전 캐시를 밀어버려서 즉시 강제 렌더링되게 만듭니다냥! 🧼✨
    _global_menu_redraw_flag = True # 메뉴 즉시 갱신 유도


# [TAG: #@_toggle_media_server_from_hotkey]
def _toggle_media_server_from_hotkey():
    """[지침 V2.0] F3 단축키 입력 시 현재 창의 메뉴를 중단하고 미디어 서버 제어로 전환합니다."""
    if not _is_main_win_active():
        try:
            hwnd = ctypes.windll.user32.GetForegroundWindow()
            buf = ctypes.create_unicode_buffer(512)
            ctypes.windll.user32.GetWindowTextW(hwnd, buf, 512)
            _log_to_file(f"[F3 무시] 활성 창 아님. Title: {buf.value}")
        except Exception as e:
            # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
            if "6" not in str(e):
                _log_to_file(f"⚠️ [Silent Exception] {e}")
        return
    import winsound
    try:
        # 로그 뷰어 상태에 따라 비프음 차별화 🎵
        winsound.Beep(1500 if _flag_show_f2_logs else 1200, 100)
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")

    if _flag_show_f2_logs:
        _log_to_file("Hotkey: F3 pressed - Toggle Real-time Log Mode")
    else:
        _log_to_file("Hotkey: F3 pressed - Triggering Internal Media Server Flow")

    global _flag_trigger_f3_action
    _flag_trigger_f3_action = True # 메뉴 인터럽트 신호 발생

# [TAG: #@_clear_screen_from_hotkey]
def _clear_screen_from_hotkey():
    """[신규] F4 단축키 입력 시 쌓인 로그를 지우고 깔끔한 메뉴 화면으로 복구합니다."""
    if not _is_main_win_active(): return
    import winsound
    try: winsound.Beep(900, 100)
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")

    if _flag_show_f2_logs:
        _log_to_file("Hotkey: F4 pressed - Requesting Notepad for Log File")
    else:
        _log_to_file("Hotkey: F4 pressed - Clearing Screen and Redrawing Full Menu")
    # [Soft Clear] 버퍼 유지를 위해 공통 지우기 함수 적용 ✨
    _clear_console_buffer(10)
    global _flag_trigger_f4_action
    _flag_trigger_f4_action = True

# [TAG: #@_restart_app_from_hotkey]
def _restart_app_from_hotkey():
    """[V16.0] F5 단축키 입력 시 현재 콘솔 창이 포커스 된 상태일 경우 프로그램을 재시작합니다."""
    if not _is_main_win_active():
        # [V133.7] F5 핫키의 중복 연쇄 재시작 방지 보루 (과다한 로그 도배도 함께 억제)
        return

    # [V160.9] AI냥 요청: 백그라운드 작업 중 F5 방지 및 확인 프롬프트 ✨
    bg_jobs = globals().get('_G_SUBTITLE_BG_JOBS', {})
    dl_jobs = globals().get('_G_DL_BG_JOBS', {})
    is_working = any(j.get('active') for j in bg_jobs.values()) or any(j.get('active') for j in dl_jobs.values())
    
    if is_working:
        globals()['_g_f5_restart_pending'] = True
        return

    import winsound
    try: winsound.Beep(1400, 100)
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")

    # [TAG: #@_LOG_INIT_F5]
    global _flag_show_f2_logs, _last_log_file_stat, _log_scroll_offset
    if _flag_show_f2_logs:
        _log_to_file("Hotkey: F5 pressed - Initializing/Clearing Log File")
        try:
            with open(_DEBUG_LOG_PATH, "w", encoding="utf-8") as f:
                f.write(f"[{datetime.now().strftime('%Y-%m-%d %H:%M:%S')}] 🧹 로그가 초기화되었습니다냥! ✨\r\n")
            _log_scroll_offset = 0
            _last_log_file_stat = (0, 0, 0, 0, 0, False) # 즉시 갱신 유도
            # [V193.7 · 99감사 P2] 이 함수는 '핫키 스레드'에서 돈다.
            #   여기서 직접 _render_full_screen_logs 를 부르면 메인 스레드의
            #   메뉴 렌더링(stdout StringIO 캡처)과 커서 상태가 경합해 화면이 깨진다.
            #   → '다시 그려라'는 신호만 남기고 실제 그리기는 메인 스레드가 한다. 🛡️
            globals()['_global_menu_redraw_flag'] = True
            return
        except Exception as e:
            _log_to_file(f" ❌ 로그 초기화 중 오류 발생: {e}")
            return

    _log_to_file("Hotkey: F5 pressed - Restarting Application")
    threading.Thread(target=restart_program, args=(True,), daemon=True).start()

# [신규] PotPlayer 전역 단축키 (따봉) 관련 기능 🎹👍
# [TAG: #@_is_potplayer_foreground]
def _is_potplayer_foreground():
    """[V142.14] 현재 활성화된 창이 팟플레이어인지 확인하고 핸들(hwnd)을 반환합니다냥! 🕵️‍♂️🔭"""
    if os.name != 'nt': return 0
    try:
        hwnd = ctypes.windll.user32.GetForegroundWindow()
        if not hwnd: return 0
        buf = ctypes.create_unicode_buffer(256)
        ctypes.windll.user32.GetClassNameW(hwnd, buf, 256)
        class_name = buf.value

        # [V142.14] 팟플 계열 클래스명 검사 🛡️
        if any(cn in class_name for cn in ["PotPlayer64", "PotPlayerMini64", "PotPlayer"]):
            return hwnd
        return 0
    except: return 0

# [TAG: #@_is_physical_key_pressed]

def _is_physical_key_pressed(vk_code: int) -> bool:
    """[V142.21] 특정 가상 키(VK)가 물리적으로 눌려 있는지 직접 확인합니다냥! 🕵️‍♂️✨
    VK_SHIFT=0x10, VK_UP=0x26, VK_DOWN=0x28, '8'=0x38
    """
    try:
        # GetAsyncKeyState의 최상위 비트(0x8000)가 1이면 현재 눌려 있는 상태!
        return (ctypes.windll.user32.GetAsyncKeyState(vk_code) & 0x8000) != 0
    except:
        return False

# [TAG: #@_force_release_key]

def _force_release_key(vk_code: int):
    """[V142.21] 운영체제 레벨에서 특정 키의 릴리스(KeyUp) 이벤트를 강제로 발생시킵니다냥! 🛠️🛑
    keyboard.release()가 가끔 안 먹히는 'Stuck' 현상을 원천 봉쇄합니다.
    """
    try:
        # KEYEVENTF_KEYUP = 0x0002
        ctypes.windll.user32.keybd_event(vk_code, 0, 0x0002, 0)
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")

# [TAG: #@_is_physical_shift_pressed]

def _is_physical_shift_pressed():
    """[V142.19] AI냥 요청: keyboard 라이브러리의 Stuck 현상 방지를 위해 '물리적' Shift 상태를 직접 확인합니다냥! 🛡️✨"""
    return _is_physical_key_pressed(0x10) # VK_SHIFT

def _is_physical_ctrl_pressed():
    """[V17.3.40] 물리적 Ctrl(0x11, VK_CONTROL) 상태를 직접 확인합니다냥! 🛡️✨"""
    return _is_physical_key_pressed(0x11) # VK_CONTROL

def _is_physical_alt_pressed():
    """[V17.3.40] 물리적 Alt(0x12, VK_MENU) 상태를 직접 확인합니다냥! 🛡️✨"""
    return _is_physical_key_pressed(0x12) # VK_MENU

def _is_physical_win_pressed():
    """[V17.3.40] 물리적 Win 키(0x5B, 0x5C) 상태를 직접 확인합니다냥! 🛡️✨"""
    return _is_physical_key_pressed(0x5B) or _is_physical_key_pressed(0x5C) # VK_LWIN, VK_RWIN


_osd_lock = threading.Lock()
_last_osd_time = 0

# [TAG: #@_show_potplayer_osd] (#@logic_audit)
def _show_potplayer_osd(msg, target_hwnd=None):
    """[V142.14] 특정 팟플레이어 핸들(target_hwnd)을 정밀 추적하여 중복 실행 없이 OSD 메시지를 전송합니다냥! 🎯🛡️✨"""
    global _last_osd_time
    try:
        import psutil

        # [V142.14] 전역 락 및 쿨타임(0.3초) 적용으로 동시 실행 방지 🔒🛑
        with _osd_lock:
            now = time.time()
            if now - _last_osd_time < 0.3: return
            _last_osd_time = now

            pot_exe = None

            # 1. [V142.14] 전달받은 핸들(hwnd)이 있다면 우선적으로 PID 및 경로 추출 🛰️🎯
            if target_hwnd:
                try:
                    pid = ctypes.c_ulong()
                    ctypes.windll.user32.GetWindowThreadProcessId(target_hwnd, ctypes.byref(pid))
                    if pid.value > 0:
                        proc = psutil.Process(pid.value)
                        p_name = proc.name().lower()
                        if 'potplayer' in p_name:
                            pot_exe = proc.exe()
                            _log_to_file(f" [OSD] Target PID identified via HWND: {pid.value} -> {pot_exe}")
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")

            # 2. 핸들 추적 실패 시, 현재 포그라운드 창 재확인 (차선책) 📂
            if not pot_exe:
                try:
                    hwnd = ctypes.windll.user32.GetForegroundWindow()
                    if hwnd:
                        pid = ctypes.c_ulong()
                        ctypes.windll.user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
                        if pid.value > 0:
                            proc = psutil.Process(pid.value)
                            if 'potplayer' in proc.name().lower():
                                pot_exe = proc.exe()
                                _log_to_file(f" [OSD] Target PID identified via Foreground: {pid.value} -> {pot_exe}")
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")

            # 3. 모든 방법 실패 시, 실행 중인 프로세스 전체 스캔 (최후의 수단) 🔍
            if not pot_exe:
                try:
                    for proc in psutil.process_iter(['name', 'exe']):
                        try:
                            p_info = proc.info
                            p_name = p_info.get('name')
                            p_exe = p_info.get('exe')
                            if p_name and 'potplayer' in p_name.lower():
                                if p_exe and os.path.exists(p_exe):
                                    pot_exe = p_exe
                                    _log_to_file(f" [OSD] Target PID identified via Process Scan: {proc.pid} -> {pot_exe}")
                                    break
                        except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                            continue
                except Exception as e:
                    # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
                    if "6" not in str(e):
                        _log_to_file(f"⚠️ [Silent Exception] {e}")

            # [핵심 수술] 실행 중인 팟플레이어를 찾지 못했다면, 새로 띄우지 않고 조용히 종료합니다냥! 🤫🚫
            if pot_exe:
                # /osd_msg 파라미터는 실행 중인 팟플이 있으면 그쪽에 메시지만 전달함 ✨
                subprocess.Popen([pot_exe, f"/osd_msg={msg}"], creationflags=subprocess.CREATE_NO_WINDOW)
            else:
                _log_to_file(f" [OSD] Skip: No active PotPlayer process found for message: {msg}")
    except Exception as e:
        _log_to_file(f" [OSD] Error: {e}")


# [TAG: #@_show_windows_toast]
def _show_windows_toast(msg, title="Binu Assistant"):
    """[V142.1] winsdk가 있으면 네이티브 알림을, 없으면 PowerShell을 이용해 윈도우 시스템 알림(Toast)을 띄웁니다냥! 🎈"""
    try:
        # 1. winsdk를 사용한 모던 토스트 알림 시도 ✨
        import winsdk.windows.ui.notifications as notifications
        import winsdk.windows.data.xml.dom as dom
        
        # XML 특수문자 이스케이프 처리 🛡️
        def xml_escape(s):
            return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;").replace("'", "&apos;")
        
        esc_title = xml_escape(title)
        esc_msg = xml_escape(msg)
        
        xml_str = f"""<toast>
            <visual>
                <binding template="ToastGeneric">
                    <text>{esc_title}</text>
                    <text>{esc_msg}</text>
                </binding>
            </visual>
        </toast>"""
        
        xml_doc = dom.XmlDocument()
        xml_doc.load_xml(xml_str)
        toast = notifications.ToastNotification(xml_doc)
        
        import sys
        _exe = os.path.basename(sys.executable).lower()
        _app_id = "Microsoft.AutoGenerated.{DB45519C-FE91-C27B-6836-A29B49927795}" if "pythonw" in _exe else "Microsoft.AutoGenerated.{0EA389B3-CB76-DD01-8F5F-58F64537AD4A}"
        notifier = notifications.ToastNotificationManager.create_toast_notifier(_app_id)
        notifier.show(toast)
        return
    except Exception as ex:
        # [V142.22] winsdk 에러 상세 내역 로그에 추가 📝
        _log_to_file(f"⚠️ winsdk 알림 실패 (파워쉘 폴백으로 이동): {ex}")
        pass

    try:
        # 2. [폴백] PowerShell Balloon Tip 스크립트 🚀
        ps_cmd = (
            f"Add-Type -AssemblyName System.Windows.Forms; "
            f"$notify = New-Object System.Windows.Forms.NotifyIcon; "
            f"$notify.Icon = [System.Drawing.SystemIcons]::Information; "
            f"$notify.Visible = $true; "
            f"$notify.ShowBalloonTip(3000, '{title}', '{msg}', 'Info'); "
            f"Start-Sleep -s 3; $notify.Dispose();"
        )
        subprocess.Popen(["powershell", "-NoProfile", "-Command", ps_cmd], creationflags=subprocess.CREATE_NO_WINDOW)
    except Exception as e:
        # [V154.7] AI냥 요청: 6번 에러는 정지 시 흔한 일이므로 침묵냥! 🤫
        if "6" not in str(e):
            _log_to_file(f"⚠️ [Silent Exception] {e}")

_last_hotkey_time = 0
_g_potplayer_hotkeys_active = False # [V17.3.36] NameError 방지 및 상태 관리용 변수 초기화냥! 🛡️✨

# [신규] V17.3.36 따봉/카트 사운드 공용 헬퍼 🎵✨
def _play_hit_sound(is_added=True):
    """도-미-솔(상승) 또는 솔-미-도(하강) 따봉 소리냥! 🎵"""
    try:
        import winsound
        if is_added: # 도(1046)-미(1318)-솔(1568)
            winsound.Beep(1046, 100); winsound.Beep(1318, 100); winsound.Beep(1568, 150)
        else: # 솔-미-도
            winsound.Beep(1568, 100); winsound.Beep(1318, 100); winsound.Beep(1046, 150)
    except: pass

