def _setup_keyboard_numpad_canonical_names():
    """
    [V160.8] keyboard 라이브러리 등록 (일반 단축키 호환용) ⌨️✨
    """
    try:
        import keyboard
        c_names = keyboard._canonical_names.canonical_names
        for i in range(10):
            c_names[f'num{i}'] = f'num {i}'
            c_names[f'numpad{i}'] = f'num {i}'
        
        c_names['num-'] = 'num minus'
        c_names['numpad-'] = 'num minus'
        c_names['num_minus'] = 'num minus'
        c_names['num_sub'] = 'num minus'
        c_names['subtract'] = 'num minus'
        
        c_names['num+'] = 'add'
        c_names['numpad+'] = 'add'
        c_names['num_plus'] = 'add'
        c_names['num_add'] = 'add'
        c_names['plus'] = 'add'
        
        c_names['num*'] = 'num multiply'
        c_names['numpad*'] = 'num multiply'
        c_names['num_mul'] = 'num multiply'
        c_names['multiply'] = 'num multiply'
        
        c_names['num/'] = 'num divide'
        c_names['numpad/'] = 'num divide'
        c_names['num_div'] = 'num divide'
        c_names['divide'] = 'num divide'
        
        c_names['num.'] = 'decimal'
        c_names['numpad.'] = 'decimal'
        c_names['num_dec'] = 'decimal'
        c_names['decimal'] = 'decimal'
    except Exception:
        pass


