def manage_custom_shortcuts(settings):
    # #@wizard_shortcut_v3
    import re
    import os
    import tkinter as tk
    from tkinter import filedialog
    
    # [TAG: #@_askopenfilename_no_resolve]

    def _askopenfilename_no_resolve(title="", filetypes=None, initialdir=None):
        try:
            import win32gui
            import win32con
            
            filter_str = ""
            if filetypes:
                parts = []
                for label, pattern in filetypes:
                    win_pattern = ";".join(pattern.split())
                    parts.append(f"{label}\0{win_pattern}")
                filter_str = "\0".join(parts) + "\0\0"
            else:
                filter_str = "All Files\0*.*\0\0"
                
            flags = win32con.OFN_EXPLORER | win32con.OFN_NODEREFERENCELINKS | win32con.OFN_FILEMUSTEXIST
            init_dir = initialdir or ""
            file_title = title or "Select File"
            
            file_path, _, _ = win32gui.GetOpenFileNameW(
                hwndOwner=0,
                Title=file_title,
                Filter=filter_str,
                Flags=flags,
                InitialDir=init_dir,
                DefExt="*"
            )
            return file_path
        except Exception as e:
            if hasattr(e, 'winerror') and e.winerror == 0:
                return ""
            try:
                return filedialog.askopenfilename(
                    title=title,
                    filetypes=filetypes or [("All Files", "*.*")]
                )
            except Exception as ex:
                return ""

    # [TAG: #@_try_resolve_and_extract_lnk]

    def _try_resolve_and_extract_lnk(path):
        if not path or not path.lower().endswith('.lnk'):
            return None
        try:
            import win32com.client
            import pythoncom
            pythoncom.CoInitialize()
            shell = win32com.client.Dispatch("WScript.Shell")
            shortcut = shell.CreateShortCut(path)
            target = shortcut.TargetPath
            arguments = shortcut.Arguments
            return target, arguments
        except Exception as e:
            _log_to_file(f"⚠️ [_try_resolve_and_extract_lnk] Error: {e}")
        return None

    def get_shortcut_display(k, val):
        disp_k = k if is_repeated_key_shortcut(k) or re.fullmatch(r'\.+', k) or 'num' in k or 'numpad' in k else k.replace('.', '+')
        if isinstance(val, dict):
            t = val.get('type')
            tgt = val.get('target', '')
            if t == 'program':
                is_url = tgt.lower().startswith(('http://', 'https://', 'ftp://', 'mailto:'))
