# [TAG: #@_execute_open_browser_web_page]
def _execute_open_browser_web_page(settings, page_type="dashboard", ip_mode="select"):
    """
    [V188.0] 웹 대시보드(/dashboard) 및 미디어 서버(/media) 웹페이지 브라우저 즉시 열기 🌐🍿✨
    ip_mode: 'local' (내부망 IP), 'external' (공인 IP / DuckDNS), 'select' (선택 메뉴)
    """
    import webbrowser
    port = int(settings.data.get('web_server_port', 5000)) if settings else 5000
    sub_path = "/dashboard" if page_type == "dashboard" else "/media"
    page_name = "웹 대시보드" if page_type == "dashboard" else "미디어 서버 웹페이지"

    # 서버가 안 켜져 있다면 백그라운드 자동 기동 유도
    if not globals().get('_flask_server_running', False):
        try:
            print(f"\r\n 🚀 {C.SKY}서버가 가동되지 않아 백그라운드에서 시작하는 중입니다냥...{C.RESET}")
            _auto_start_server_if_needed(settings, is_async=True)
            time.sleep(1.0)
        except Exception as se:
            _log_to_file(f"⚠️ [OpenBrowserWeb] Auto-start attempt: {se}")

    local_ip = _get_local_ip() or "127.0.0.1"
    duck_domain = settings.data.get('duckdns_domain', '').strip() if settings else ''
    if duck_domain and not duck_domain.endswith(".duckdns.org"):
        duck_domain = f"{duck_domain}.duckdns.org"

    # 보안 키 파라미터 구성
    key_param = ""
    curr_key = globals().get('_flask_server_key')
    if curr_key:
        key_param = f"?k={curr_key}"

    target_url = None

    if ip_mode == "local":
        target_url = f"http://{local_ip}:{port}{sub_path}{key_param}"
    elif ip_mode == "external":
        if duck_domain:
            target_url = f"http://{duck_domain}:{port}{sub_path}{key_param}"
        else:
            try:
                ext_ip = _get_external_ip() or local_ip
            except:
                ext_ip = local_ip
            target_url = f"http://{ext_ip}:{port}{sub_path}{key_param}"
    else:
        # 'select' 모드: 대화형 선택 메뉴
        clear_console()
        ext_ip = settings.data.get('duckdns_last_ip', '') if settings else ''
        if not ext_ip:
            try:
                ext_ip = _get_external_ip() or "미감지"
            except:
                ext_ip = "미감지"

        options = [
            f" 🏠 1. 로컬 IP (내부망)  : http://{local_ip}:{port}{sub_path}{key_param}",
            f" 💻 2. 루프백 (내 PC)   : http://127.0.0.1:{port}{sub_path}{key_param}",
        ]
        url_map = [
            f"http://{local_ip}:{port}{sub_path}{key_param}",
            f"http://127.0.0.1:{port}{sub_path}{key_param}"
        ]

        if duck_domain:
            options.append(f" 🦆 3. DuckDNS 도메인   : http://{duck_domain}:{port}{sub_path}{key_param}")
            url_map.append(f"http://{duck_domain}:{port}{sub_path}{key_param}")

        if ext_ip and ext_ip != "미감지":
            options.append(f" 🌐 4. 외부 공인 IP     : http://{ext_ip}:{port}{sub_path}{key_param}")
            url_map.append(f"http://{ext_ip}:{port}{sub_path}{key_param}")

        options.append(" ❌ 취소")

        title = f"🌐 {page_name} 열기 - 접속할 주소를 골라줘냥! 🚀"
        sel_idx, *_ = _interactive_menu(title, options, timeout=0)
        if sel_idx < 0 or sel_idx >= len(url_map):
            return

        target_url = url_map[sel_idx]

    if target_url:
        print(f"\r\n 🌐 {C.GREEN}{page_name} 브라우저를 엽니다냥!{C.RESET}")
        print(f" 👉 {C.SKY}{target_url}{C.RESET}\r\n")
        try:
            webbrowser.open(target_url)
            _log_to_file(f"✅ [OpenBrowserWeb] Opened {target_url}")
        except Exception as we:
            _log_to_file(f"❌ [OpenBrowserWeb] Failed to open {target_url}: {we}")
            os.system(f'start "" "{target_url}"')
        time.sleep(0.8)


# [TAG: #@_create_desktop_web_shortcuts_interactive]
def _create_desktop_web_shortcuts_interactive(settings):
    """
    [V188.2] 🖥️ 바탕화면에 웹 대시보드 및 미디어 서버 바로가기(.url) 파일 생성 (OneDrive/다국어/아이콘 완벽 지원) 🚀✨
    """
    import os
    # 윈도우 바탕화면 실제 경로 획득 (레지스트리 User Shell Folders 우선 탐색으로 OneDrive 완벽 대응)
    desktop_dir = ""
    try:
        import winreg
        key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders")
        desktop_dir, _ = winreg.QueryValueEx(key, "Desktop")
        desktop_dir = os.path.expandvars(desktop_dir)
        winreg.CloseKey(key)
    except:
        pass

    if not desktop_dir or not os.path.exists(desktop_dir):
        candidates = [
            os.path.join(os.path.expanduser("~"), "OneDrive", "Desktop"),
            os.path.join(os.path.expanduser("~"), "OneDrive", "바탕 화면"),
            os.path.join(os.path.expanduser("~"), "Desktop"),
            os.path.join(os.path.expanduser("~"), "바탕 화면"),
        ]
        for c in candidates:
            if os.path.exists(c):
                desktop_dir = c
                break
        else:
            desktop_dir = os.path.join(os.path.expanduser("~"), "Desktop")

    try:
        os.makedirs(desktop_dir, exist_ok=True)
    except:
        pass

    port = int(settings.data.get('web_server_port', 5000)) if settings else 5000
    local_ip = _get_local_ip() or "127.0.0.1"
    duck_domain = settings.data.get('duckdns_domain', '').strip() if settings else ''
    if duck_domain and not duck_domain.endswith(".duckdns.org"):
        duck_domain = f"{duck_domain}.duckdns.org"

    try:
        ext_ip = settings.data.get('duckdns_last_ip', '') if settings else ''
        if not ext_ip:
            ext_ip = _get_external_ip() or local_ip
    except:
        ext_ip = local_ip

    key_param = ""
    curr_key = globals().get('_flask_server_key')
    if curr_key:
        key_param = f"?k={curr_key}"

    # 후보 리스트
    candidates = [
        ("🎛️ 1. 웹 대시보드 (로컬 IP)", "[BINU] 웹 대시보드 (로컬).url", f"http://{local_ip}:{port}/dashboard{key_param}"),
        ("🎛️ 2. 웹 대시보드 (루프백 내 PC)", "[BINU] 웹 대시보드 (내PC).url", f"http://127.0.0.1:{port}/dashboard{key_param}"),
        ("🎛️ 3. 웹 대시보드 (외부/도메인)", "[BINU] 웹 대시보드 (외부).url", f"http://{duck_domain or ext_ip}:{port}/dashboard{key_param}"),
        ("🍿 4. 미디어 센터 (로컬 IP)", "[BINU] 미디어 센터 (로컬).url", f"http://{local_ip}:{port}/media{key_param}"),
        ("🍿 5. 미디어 센터 (루프백 내 PC)", "[BINU] 미디어 센터 (내PC).url", f"http://127.0.0.1:{port}/media{key_param}"),
        ("🍿 6. 미디어 센터 (외부/도메인)", "[BINU] 미디어 센터 (외부).url", f"http://{duck_domain or ext_ip}:{port}/media{key_param}"),
    ]

    clear_console()
    options = [c[0] for c in candidates]
    options.append("🚀 7. [전체 생성] 위 6개 바로가기 한 방에 모두 만들기!")
    options.append("❌ 취소")

    title = f"🖥️ 바탕화면에 만들 웹 바로가기를 선택해줘냥! (폴더: {desktop_dir})"
    sel, *_ = _interactive_menu(title, options, timeout=0)
    if sel < 0 or sel >= len(options) - 1:
        return

    def _write_url_file(filename, target_url, is_media=False):
        target_path = os.path.join(desktop_dir, filename)
        icon_idx = 115 if is_media else 15
        content = f"[InternetShortcut]\r\nURL={target_url}\r\nIconFile=shell32.dll\r\nIconIndex={icon_idx}\r\n"
        with open(target_path, "w", encoding="utf-8-sig") as f:
            f.write(content)
        return target_path

    created = []
    if sel == len(options) - 2:  # 전체 생성
        for idx_c, (_, fname, t_url) in enumerate(candidates):
            p = _write_url_file(fname, t_url, is_media=(idx_c >= 3))
            created.append(p)
    else:
        _, fname, t_url = candidates[sel]
        p = _write_url_file(fname, t_url, is_media=(sel >= 3))
        created.append(p)

    clear_console()
    print(f"\r\n ✨ {C.GREEN}{C.BOLD}바탕화면에 웹 바로가기 생성이 완료되었어냥! 🎉{C.RESET}")
    print(f" {C.DIM}───────────────────────────────────────────────────────{C.RESET}")
    for p in created:
        print(f"  📄 {C.SKY}{os.path.basename(p)}{C.RESET} ➡️ {C.GRAY}{p}{C.RESET}")
    print(f" {C.DIM}───────────────────────────────────────────────────────{C.RESET}")
    print(f" 💡 {C.YELLOW}이제 바탕화면의 아이콘을 더블클릭하면 웹 브라우저가 바로 뜹니다냥! 👍{C.RESET}\r\n")
    time.sleep(2.0)


# [TAG: #@_execute_potplayer_recent_playlist]

def _execute_potplayer_recent_playlist(settings):
    try:
        import os
        import time
        target_path = os.path.join(os.environ.get('APPDATA', os.path.expanduser('~')), r"PotPlayer64\Playlist\PotPlayer64.dpl")
        appdata = os.environ.get('APPDATA', '')
        candidate_paths = [
            target_path,
            os.path.join(appdata, r"PotPlayer64\Playlist\PotPlayer64.dpl"),
            os.path.join(appdata, r"PotPlayerMini64\Playlist\PotPlayerMini64.dpl"),
            os.path.join(appdata, r"PotPlayer\Playlist\PotPlayer.dpl")
        ]
        
        valid_paths = [p for p in candidate_paths if os.path.exists(p)]
        
        if valid_paths:
            # 시간순(mtime) 정렬해서 가장 최신 파일 획득냥!
            valid_paths.sort(key=os.path.getmtime, reverse=True)
            target_path = valid_paths[0]
            
            success = _open_unelevated(target_path)
            if success:
                status_msg = f"🎬 팟플레이어 최근 재생목록 실행 성공! (파일: {os.path.basename(target_path)})"
            else:
                status_msg = f"❌ 팟플레이어 실행 실패냥..."
        else:
            status_msg = f"⚠️ 최근 재생목록 파일(.dpl)이 존재하지 않아냥!"
            
        globals()['_last_bg_notification'] = status_msg
        globals()['_last_bg_notification_time'] = time.time()
        globals()['_global_menu_redraw_flag'] = True
        _log_to_file(f" ✅ [Shortcut Action] PotPlayer recent playlist: {status_msg}")
    except Exception as e:
        _log_to_file(f" ❌ [Shortcut Action] PotPlayer recent playlist failed: {e}")

# [TAG: #@_execute_caffeine_toggle]

def _execute_caffeine_toggle(settings):
    """순환 토글: OFF(⚫) → 1시간(🟠) → 2시간(🟠) → 항상 ON(🟢) → OFF(⚫)"""
    try:
        caf = globals().get('caffeine')
        if caf:
            now_ts = time.time()
            c_until = settings.data.get('caffeine_until', 0)
            c_dur = settings.data.get('caffeine_duration_hours', 0)
            is_always_on = settings.data.get('caffeine_always_on', False)
            is_active = getattr(caf, 'is_active', False)

            # 기존 카페인 타이머 정리
            _timer_mgr = globals().get('_timer_mgr')
            if _timer_mgr and hasattr(_timer_mgr, 'timers'):
                _timer_mgr.timers = [t for t in _timer_mgr.timers if t.get('type') != 'caffeine_off']

            if not is_active:
                # ① OFF(⚫) → 🟠 1시간 후 자동 해제
                caf.enable(auto=False)
                settings.data['caffeine_always_on'] = False
                settings.data['caffeine_until'] = now_ts + 3600
                settings.data['caffeine_duration_hours'] = 1
                if hasattr(settings, 'dirty_keys'):
                    settings.dirty_keys.update({'caffeine_until', 'caffeine_duration_hours', 'caffeine_always_on'})
                settings.save()
                if _timer_mgr and hasattr(_timer_mgr, 'add_timer'):
                    _timer_mgr.add_timer(60, b_type='caffeine_off')
                status_msg = "🟠 카페인 모드 ON (1시간) — 1시간 뒤 알람 소리 없이 조용히 꺼집니다냥! ☕"
            elif c_until and c_until > now_ts and c_dur == 1:
                # ② 1시간(🟠) → 🟠 2시간 후 자동 해제
                caf.enable(auto=False)
                settings.data['caffeine_always_on'] = False
                settings.data['caffeine_until'] = now_ts + 7200
                settings.data['caffeine_duration_hours'] = 2
                if hasattr(settings, 'dirty_keys'):
                    settings.dirty_keys.update({'caffeine_until', 'caffeine_duration_hours', 'caffeine_always_on'})
                settings.save()
                if _timer_mgr and hasattr(_timer_mgr, 'add_timer'):
                    _timer_mgr.add_timer(120, b_type='caffeine_off')
                status_msg = "🟠 카페인 모드 ON (2시간) — 2시간 뒤 알람 소리 없이 조용히 꺼집니다냥! ☕"
            elif not is_always_on:
                # ③ 2시간(🟠) 또는 기타 타이머/임시 ON → 🟢 ON (항상)
                caf.enable(auto=False)
                settings.data['caffeine_always_on'] = True
                settings.data['caffeine_until'] = 0
                settings.data['caffeine_duration_hours'] = 0
                if hasattr(settings, 'dirty_keys'):
                    settings.dirty_keys.update({'caffeine_until', 'caffeine_duration_hours', 'caffeine_always_on'})
                settings.save()
                status_msg = "🟢 카페인 모드 ON (항상) — 재시작해도 무제한 유지! ☕"
            else:
                # ④ 🟢 ON (항상) → ⚫ OFF
                caf.disable()
                settings.data['caffeine_always_on'] = False
                settings.data['caffeine_until'] = 0
                settings.data['caffeine_duration_hours'] = 0
                if hasattr(settings, 'dirty_keys'):
                    settings.dirty_keys.update({'caffeine_until', 'caffeine_duration_hours', 'caffeine_always_on'})
                settings.save()
                status_msg = "⚫ 카페인 모드 OFF — 절전 방지가 해제되었습니다냥! ☕"

            globals()['_last_bg_notification'] = status_msg
            globals()['_last_bg_notification_time'] = time.time()
            globals()['_global_menu_redraw_flag'] = True
            _log_to_file(f" ✅ [Shortcut Action] Caffeine toggled: {status_msg}")
        else:
            _log_to_file(" ⚠️ [Shortcut Action] CaffeineManager instance not found.")
    except Exception as e:
        _log_to_file(f" ❌ [Shortcut Action] Caffeine toggle failed: {e}")

